window.C40DATA={"DEADLINES":[{"course":"da","kind":"exam","label":"In class exam I, Linear Regression","date":"2026-09-16T13:00"},{"course":"da","kind":"exam","label":"In class exam II, Logistic Regression","date":"2026-09-30T13:00","note":"Sur Blackboard, prevoir R et RStudio"},{"course":"da","kind":"exam","label":"In class exam III, Time Series","date":"2026-10-14T16:30","note":"Date corrigee le 29/09 sur Blackboard, etait le 16/10"},{"course":"da","kind":"exam","label":"Mock final exam, exercise session","date":"2026-10-30T18:15"},{"course":"da","kind":"exam","label":"General exam","date":"2026-12-16T14:00"},{"course":"cr","kind":"coursework","label":"Case study write up, Leases III, Cathay Pacific","date":"2026-10-27T17:00","note":"Groupe 6, date revisee le 4/10 sur Blackboard"},{"course":"cr","kind":"coursework","label":"Case study write up, Impairments II","date":null,"note":"Biosensors International Group, date pas encore annoncee sur Blackboard"},{"course":"cr","kind":"coursework","label":"Case study write up, Revenue Recognition III","date":"2026-11-10T17:00","note":"General Dynamics and Ford, date annoncee le 4/10 sur Blackboard"},{"course":"cr","kind":"coursework","label":"Case study write up, Equity Settled Share Based Payments II","date":"2026-11-15T17:00","note":"eBay Stock Option Plans, date annoncee le 4/10 sur Blackboard"},{"course":"cr","kind":"coursework","label":"Case study write up, Consolidation and Business Combinations","date":"2026-12-01T17:00","note":"Lyradon Velquanta, date annoncee le 4/10 sur Blackboard"},{"course":"cr","kind":"exam","label":"Partial exam I","date":"2026-10-27T09:00"},{"course":"cr","kind":"exam","label":"Partial exam II or general exam","date":"2026-12-11T09:00"},{"course":"fm","kind":"exam","label":"Partial exam I","date":"2026-10-20T09:00"},{"course":"fm","kind":"exam","label":"General exam, reserved slot","date":"2026-12-15T09:00","note":"Verifier sur You@B si une session anterieure existe"},{"course":"cg","kind":"exam","label":"General exam, reserved slot","date":"2026-12-09T11:30","note":"Verifier sur You@B"},{"course":"cg","kind":"assignment","label":"Individual assignment, lectures 1 to 10","date":"2026-10-09T23:59","note":"Deadline annoncee sur Blackboard le 7/10, tentative ouverte, a soumettre avant 23h59 vendredi"},{"course":"cg","kind":"assignment","label":"Group assignment presentation","date":null,"note":"Presentee en fin de cours, groupes de 5, date pas encore annoncee"}],"SESSIONS":{"cr":[[1,"Global financial reporting regulation and accounting principles","2026-09-07T08:30",true,false],[2,"IFRS conceptual framework","2026-09-07T10:15",true,false],[3,"IFRS financial statements, presentation and general principles I","2026-09-07T12:00",true,false],[4,"IFRS financial statements, presentation and general principles II","2026-09-14T08:30",true,false],[5,"Financial instruments I, presentation and classification","2026-09-14T10:15",true,false],[6,"Financial instruments II, recognition and measurement","2026-09-14T12:00",true,false],[7,"Financial instruments III, derecognition and impairment","2026-09-21T08:30",true,false],[8,"Financial instruments IV, case study, Fair Value Accounting at Berkshire Hathaway","2026-09-21T10:15",true,true],[9,"Non current assets I, PP&E","2026-09-21T12:00",true,false],[10,"Non current assets II, PP&E","2026-09-28T08:30",true,false],[11,"Non current assets III, intangibles","2026-09-28T10:15",true,false],[12,"Impairments I","2026-09-28T12:00",true,false],[13,"Impairments II, case study, Biosensors International Group","2026-10-05T08:30",true,true],[14,"Provisions, contingent liabilities and contingent assets","2026-10-05T10:15",true,false],[15,"Review session I","2026-10-05T12:00",false,false],[16,"Leases I","2026-11-02T08:30",true,false],[17,"Leases II","2026-11-02T10:15",true,false],[18,"Leases III, case study, Cathay Pacific","2026-11-02T12:00",true,true],[19,"Deferred taxes and valuation allowances I","2026-11-09T08:30",true,false],[20,"Deferred taxes and valuation allowances II","2026-11-09T10:15",true,false],[21,"Leases and deferred taxes","2026-11-09T12:00",true,false],[22,"Revenue recognition I","2026-11-16T08:30",true,false],[23,"Revenue recognition II","2026-11-16T10:15",true,false],[24,"Revenue recognition III, case study, General Dynamics and Ford","2026-11-16T12:00",true,true],[25,"Equity settled share based payments I","2026-11-23T08:30",true,false],[26,"Equity settled share based payments II, case study, eBay Stock Option Plans","2026-11-23T10:15",true,true],[27,"Employee benefits, pension accounting","2026-11-23T12:00",true,false],[28,"Consolidated financial statements, concept of control I","2026-11-30T08:30",true,false],[29,"Consolidated financial statements, concept of control II","2026-11-30T10:15",true,false],[30,"Business combinations I","2026-11-30T12:00",true,false],[31,"Consolidation and business combinations, case study, Lyradon Velquanta","2026-12-03T12:00",true,true],[32,"Review session II","2026-12-03T14:45",false,false]],"da":[[1,"Introduction to regression models"],[2,"Categorical variables, dummies and F-tests"],[3,"Variable transformations and interactions"],[4,"Multicollinearity, assumption violations, influential points"],[5,"Panel data models, FEM vs REM"],[6,"Logistic regression, binary logit model"],[7,"Logistic regression, significance tests, prediction, model fit"],[8,"Multinomial logit model"],[9,"Time series, general characteristics, transformations and decomposition"],[10,"Probabilistic models for time series, stationarity, white noise and random walk"],[11,"AR, MA, ARMA and ARIMA models, model selection and diagnostic"],[12,"Forecasting, exponential smoothing, Holt-Winters, forecasting with ARIMA"]],"fm":{"partI":[{"n":1,"topic":"Introduction to the course. Financial planning, linking short term and long term financing decisions, cash and treasury management","hasFiche":true},{"n":2,"topic":"Financial planning, the importance of working capital management","hasFiche":true},{"n":3,"topic":"Financial planning, writing your plan, how to build financials and forecasts","hasFiche":true},{"n":"4-5","topic":"Corporate financial risk management, FX transaction exposure measurement and management, alternative hedging strategies, exercises","hasFiche":true},{"n":6,"topic":"Corporate financial risk management, managing interest rate risk, interest rate swaps","hasFiche":true},{"n":7,"topic":"Capital structure and corporate value, H J Heinz case study (cost of capital class note)","hasFiche":true},{"n":8,"topic":"Capital structure and corporate value, the optimal capital structure","hasFiche":false},{"n":9,"topic":"Capital structure and valuation techniques in private equity and LBO","hasFiche":false},{"n":10,"topic":"New challenges of the treasury department, guest speaker","hasFiche":false},{"n":11,"topic":"Closing thoughts, conclusions, summary of the course, Q&A","hasFiche":false}],"partII":[{"n":1,"topic":"Introduction to the second part, credit risk management map, first insight into default risk","hasFiche":false},{"n":2,"topic":"Agencies ratings versus internal ratings, judgement based versus statistical based ratings","hasFiche":false},{"n":3,"topic":"Other concepts, measures and tools of credit risk, VAR versus regulatory capital, portfolio models versus Basel","hasFiche":false},{"n":4,"topic":"Loan pricing and other applications of credit risk measures","hasFiche":false},{"n":5,"topic":"Loan pricing and risk adjusted performance measures, pricing policies and bank strategic decisions (4h)","hasFiche":false},{"n":6,"topic":"Credit selection, cash is king but profit is king's father","hasFiche":false},{"n":7,"topic":"Equity approach versus entity approach (WACC) in finance","hasFiche":false},{"n":8,"topic":"Corporate financial ratio analysis, financial leverage and operating leverage (4h)","hasFiche":false},{"n":9,"topic":"Corporate credit analysis, credit analysts versus AI","hasFiche":false},{"n":10,"topic":"Corporate financing within banking regulations and risks for banks stability","hasFiche":false},{"n":11,"topic":"Conclusions, course review, Q&A, and mock exams","hasFiche":false}]},"cg":[[1,"Presentation of the course. Corporate governance overview, separation of ownership and management",true],[2,"Shareholders versus stakeholders view of the firm, the corporate purpose",true],[3,"Global governance failure, Enron and Theranos",true],["4-7","Corporate governance mechanisms, the board of directors, Unilever incident, beyond compliance and making boards effective",true],["8a","Field project preparation, analyzing a governance report of a listed company, part 1",false],["8b","Field project preparation, analyzing a governance report of a listed company, part 2",false],[9,"Ownership structure, corporate governance and strategy, shareholder activism, ESG investing (Blackboard files this under session 9, not the syllabus slot 7)",true],["10","Designing governance for effective decision-making, private and family controlled firms (Blackboard session 10)",true],["10a","Board crisis simulation, part 1",false],["10b","Board crisis simulation, part 2",false],[11,"The role of governance in managing risks, the internal control and management system",false],[12,"Is corporate governance inevitable, a long term perspective",false],[13,"The Anglo Saxon model",false],[14,"Corporate governance made in Germany",false],[15,"France, the resilience of the past and the market pressure",false],[16,"The Italian case, good theories and bad practices",false],[17,"Japan, corporate governance in transition",false],[18,"Corporate governance Chinese way",false],[19,"Activist investors and corporate governance",false],[20,"Institutional investors and sovereign wealth funds",false],[21,"Leviathans, when the state is the owner",false],[22,"Corporate ownership around the world",false],[23,"Workgroup presentations",false]]},"FICHE_URLS":{"cr":{"1":"fiches/cr-1.pdf","2":"fiches/cr-2.pdf","3":"fiches/cr-3.pdf","4":"fiches/cr-4.pdf","5":"fiches/cr-5.pdf","6":"fiches/cr-6.pdf","7":"fiches/cr-7.pdf","8":"fiches/cr-8.pdf","9":"fiches/cr-9.pdf","10":"fiches/cr-10.pdf","11":"fiches/cr-11.pdf","12":"fiches/cr-12.pdf","13":"fiches/cr-13.pdf","14":"fiches/cr-14.pdf","16":"fiches/cr-16.pdf","17":"fiches/cr-17.pdf","18":"fiches/cr-18.pdf","19":"fiches/cr-19.pdf","20":"fiches/cr-20.pdf","21":"fiches/cr-21.pdf","22":"fiches/cr-22.pdf","23":"fiches/cr-23.pdf","24":"fiches/cr-24.pdf","25":"fiches/cr-25.pdf","26":"fiches/cr-26.pdf","27":"fiches/cr-27.pdf","28":"fiches/cr-28.pdf","29":"fiches/cr-29.pdf","30":"fiches/cr-30.pdf","31":"fiches/cr-31.pdf"},"da":{"1":"fiches/da-1.pdf","2":"fiches/da-2.pdf","3":"fiches/da-3.pdf","4":"fiches/da-4.pdf","5":"fiches/da-5.pdf","6":"fiches/da-6.pdf","7":"fiches/da-7.pdf","8":"fiches/da-8.pdf","9":"fiches/da-9.pdf","10":"fiches/da-10.pdf","11":"fiches/da-11.pdf","12":"fiches/da-12.pdf","exam-prep":"fiches/da-exam-prep.pdf"},"fm":{"1":"fiches/fm-1.pdf","2":"fiches/fm-2.pdf","3":"fiches/fm-3.pdf","6":"fiches/fm-6.pdf","7":"fiches/fm-7.pdf","8":"fiches/fm-8.pdf","9":"fiches/fm-9.pdf?v=20261016-paper-simple","4-5":"fiches/fm45-reader.html?v=20261013-teaching"},"cg":{"1":"fiches/cg-1.pdf","2":"fiches/cg-2.pdf","3":"fiches/cg-3.pdf","9":"fiches/cg-9.pdf","10":"fiches/cg-10.pdf","4-7":"fiches/cg-4-7.pdf"}},"QCM":{"da":[{"id":"da-s1-q1","session":1,"topic":"Why regression models","question":"A study records turnover Y and several company characteristics x. Which statement matches the broad regression framework used in the lecture?","choices":["Model the ranking of company characteristics using their separate correlations with turnover.","Model turnover by assigning every company the same value regardless of its characteristics.","Model each company characteristic as a function of turnover and the remaining characteristics.","Model a summary of turnover as a function of the recorded company characteristics."],"correct_index":3,"explanation":"Regression relates an aspect or summary of Y to explanatory variables. Reversing response and predictors answers a different question. Ranking correlations does not specify the regression function. Assigning a common value ignores the explanatory variables.","set":1},{"id":"da-s1-q2","session":1,"topic":"Theoretical equation","question":"Two properties have the same age and distance from the centre but different observed prices. What does the error term in the lecture's linear model allow?","choices":["Their predictor values are automatically corrected because the error measures distance inaccurately.","Their conditional mean prices differ because the same predictors imply different coefficients.","Their observed prices must coincide because the intercept already captures every omitted influence.","Their observed prices can differ because influences outside the included predictors remain."],"correct_index":3,"explanation":"The deterministic component is the same at identical predictor values, but the random error covers other influences on Y. It does not assign different coefficients to identical units, make the intercept absorb all variation, or automatically correct measurement of predictors.","set":1},{"id":"da-s1-q3","session":1,"topic":"Five assumptions","question":"A fitted model has zero mean errors, but error variance is larger for some sample units than for others. Which lecture assumption is violated by this variance pattern?","choices":["Uncorrelated errors, because a changing variance forces errors to move together.","Homoskedasticity, because error variance must equal the same sigma squared for every unit.","Zero mean errors, because a changing variance forces the error mean to change.","No perfect multicollinearity, because a changing variance creates exact relations among predictors."],"correct_index":1,"explanation":"Homoskedasticity requires constant error variance across units. Mean, covariance across units, and exact linear relations among predictors are different assumptions. The stated variance pattern does not by itself establish those other violations.","set":1},{"id":"da-s1-q4","session":1,"topic":"Five assumptions","question":"In a regression with an intercept, x2 equals exactly twice x1 for every sample unit. Which problem follows from the lecture's no perfect multicollinearity assumption?","choices":["The error variance must be zero, so uncertainty disappears from every prediction.","The two slope estimates are unique, but their standard errors must be identical.","The two slope coefficients must both be zero, so the fitted response is constant.","The separate slope coefficients cannot be uniquely estimated from these predictor values."],"correct_index":3,"explanation":"An exact linear relation among explanatory variables violates the fifth assumption. Different combinations of the two slopes can produce the same fitted values. This prevents unique coefficient estimation, rather than proving zero errors, zero slopes, or equal standard errors.","set":1},{"id":"da-s1-q5","session":1,"topic":"Meaning of 'linear'","question":"A researcher writes E(Y) = beta0 + beta1 x + beta2 x squared. Under the lecture's meaning of linear regression, how should this specification be classified?","choices":["Linear in the parameters, even though the response can vary nonlinearly with x.","Linear in the parameters only when beta2 is fixed at zero before estimation.","Nonlinear in the parameters, because the response includes a squared explanatory variable.","Nonlinear in the parameters whenever the fitted response is not a straight line."],"correct_index":0,"explanation":"Linearity refers to the coefficients beta, which enter additively and to the first power. A transformed predictor such as x squared is allowed. Curvature in x does not make the specification nonlinear in its parameters.","set":1},{"id":"da-s1-q6","session":1,"topic":"Least squares estimation","question":"Two candidate fitted equations give residuals (1, 1, 1) and (0, 0, 2). Which does least squares prefer when these are the only candidates?","choices":["The second equation, because two observations have exactly zero residuals.","The second equation, because its sum of absolute residuals is smaller.","The first equation, because its sum of squared residuals is smaller.","The first equation, because its largest fitted value must be smaller."],"correct_index":2,"explanation":"Least squares compares squared residual sums: the first gives 1 + 1 + 1 = 3, and the second gives 0 + 0 + 4 = 4. Absolute residual sums and the number of exact fits are different objectives. The residuals do not establish the size of the fitted values.","set":1},{"id":"da-s1-q7","session":1,"topic":"Marginal effect","question":"In the lecture's property model, price is measured in thousands of euros per square metre and the age coefficient is minus 0.09. What does one additional year of age imply at a fixed distance from the centre?","choices":["Mean price falls by 90 euros per square metre while distance also changes.","Mean price falls by 90 euros per square metre at that distance.","Every individual property must lose exactly 90 euros per square metre.","Mean price falls by 9 euros per square metre at that distance."],"correct_index":1,"explanation":"The coefficient measures a change in the conditional mean, holding the other predictor fixed. A change of minus 0.09 thousand euros is minus 90 euros. It does not fix every individual outcome or allow distance to vary in the same interpretation.","set":1},{"id":"da-s1-q8","session":1,"topic":"Spurious effect","question":"A positive relation between x and Y disappears after adding z, which is related to both x and Y. Which interpretation matches the lecture's spurious effect mechanism?","choices":["The original relation proves perfect multicollinearity because x and z are related.","The original relation establishes causality because it was observed before z was included.","The original relation may reflect an omitted z influence rather than a direct x effect.","The original relation must reflect normal errors because z improves the model specification."],"correct_index":2,"explanation":"An omitted variable related to both predictor and response can induce an apparent relationship. Adding it can change the estimated effect. Correlation alone is not proof of causality or perfect multicollinearity, and the change does not establish an error distribution.","set":1},{"id":"da-s1-q9","session":1,"topic":"Spurious effect example","question":"In the lecture's coastal property example, the distance coefficient changes from positive to negative after property age is included. Which conclusion follows?","choices":["Changing the distance unit is sufficient to explain the coefficient's reversal of sign.","At a fixed age, greater distance is associated with lower mean price in the expanded model.","At a fixed age, greater distance is associated with higher mean price in the expanded model.","Age and distance must have an exact linear relation that prevents coefficient estimation."],"correct_index":1,"explanation":"The multiple regression coefficient describes distance while holding age fixed, and it is negative. The initial positive relation was induced by omitted age, since newer properties tended to be farther away. The example does not establish perfect collinearity or a change of measurement units.","set":1},{"id":"da-s1-q10","session":1,"topic":"Confidence intervals","question":"The data, coefficient estimate and standard error stay fixed. A 95% coefficient confidence interval is replaced by a 99% interval. What changes?","choices":["The interval remains fixed because the data and standard error are unchanged.","The interval narrows because the standard error falls at a higher confidence level.","The interval widens because the required Student t quantile becomes larger.","The interval widens because the coefficient estimate moves farther from zero."],"correct_index":2,"explanation":"The margin of error is the relevant t quantile times the standard error. Higher confidence increases the quantile while estimate and standard error remain fixed. The larger margin widens the interval without changing its centre.","set":1},{"id":"da-s1-q11","session":1,"topic":"Hypothesis test on a coefficient","question":"A slope estimate is minus 0.09 with standard error 0.02. For the two sided test against zero, the stated critical absolute t value is 2. What is the conclusion?","choices":["Reject, because the absolute slope estimate alone exceeds its standard error.","Do not reject, because a negative slope cannot exceed a positive critical value.","Do not reject, because the absolute t statistic is 0.18 and is below the critical value.","Reject, because the absolute t statistic is 4.5 and exceeds the critical value."],"correct_index":3,"explanation":"Compute t as minus 0.09 divided by 0.02, giving minus 4.5. A two sided decision uses its absolute value, so reject against the stated threshold of 2. The statistic is a ratio, not a product or a comparison of the unstandardised coefficient.","set":1},{"id":"da-s1-q12","session":1,"topic":"Prediction","question":"At the same predictor values and confidence level, compare a prediction for one property with an estimate of the mean for all such properties. Which statement matches the lecture?","choices":["The same point prediction, with a wider interval for the individual property.","Different point predictions, with a wider interval for the individual property.","Different point predictions, with a wider interval for the conditional mean.","The same point prediction, with a wider interval for the conditional mean."],"correct_index":0,"explanation":"The error cannot be predicted beyond zero, so both point predictions use the same fitted mean. The individual prediction also carries uncertainty from its error term and therefore has the wider interval. The two uncertainty levels do not require different point estimates.","set":1},{"id":"da-s1-q13","session":1,"topic":"Extrapolation","question":"A property model was estimated using ages from 0 to 40 years. A prediction is requested for a property aged 100 years. What is the lecture's main warning?","choices":["The fitted relation is being extended beyond the observed predictor range without sample support.","The original sample R squared necessarily falls because the new property is older.","The fitted coefficients necessarily change as soon as the new predictor value is entered.","The fitted relation becomes valid because the same prediction equation can still be evaluated."],"correct_index":0,"explanation":"This is extrapolation. An evaluable equation is not evidence that its relationship remains valid outside the observed range. Entering a new predictor value does not itself refit coefficients or alter the original sample fit statistic.","set":1},{"id":"da-s1-q14","session":1,"topic":"R²","question":"For a sample with positive total deviance, a fitted regression with an intercept has R squared equal to zero. What must be true?","choices":["Every observed response equals its fitted value, leaving no residual deviance.","Every fitted response equals the sample mean, leaving no explained deviance.","Every explanatory variable is perfectly correlated with another explanatory variable.","Every estimated slope has a p value above 0.05, leaving no significant effects."],"correct_index":1,"explanation":"R squared is explained deviance divided by total deviance. With a positive denominator, zero requires the squared deviations of fitted values from the sample mean to sum to zero. Perfect fit instead gives R squared equal to one. Significance and collinearity are different issues.","set":1},{"id":"da-s1-q15","session":1,"topic":"Adjusted R²","question":"A predictor is added to a regression on the same sample. Raw R squared increases slightly but adjusted R squared falls. Which explanation matches the lecture?","choices":["Raw R squared penalises added predictors, so its rise proves the new variable is significant.","Raw and adjusted R squared use identical penalties, so one must have been calculated incorrectly.","Adjusted R squared penalises model size, and the added fit does not offset that penalty.","Adjusted R squared rises with model size, so its fall proves the software used different data."],"correct_index":2,"explanation":"Raw R squared does not decrease when predictors are added. Adjusted R squared balances explanatory power against model size using n and p, so it can fall when the improvement in fit is too small. A change in raw R squared alone is not a significance test.","set":1},{"id":"da-s1-q16","session":1,"topic":"Comparing models","question":"Two models use the same response and sample. The larger contains all predictors in the smaller plus three additional predictors. Which method tests whether those additions matter jointly?","choices":["Use a partial F test for the added predictors in the nested models.","Compare adjusted R squared and interpret the larger value as a significance test.","Run three separate t tests and treat their results as a joint group test.","Compare raw R squared and select the model with the larger value."],"correct_index":0,"explanation":"The lecture identifies the partial F test as the inferential comparison for nested models. Raw R squared mechanically favours a larger model, adjusted R squared is descriptive, and separate coefficient tests do not test the added group jointly.","set":1},{"id":"da-s2-q1","session":2,"topic":"Dummy variable coding","question":"A researcher wants a dummy for the presence of a garage, using the lecture's coding convention. Which pair of values belongs in the two groups?","choices":["Garage present: value 1. Garage absent: value 0.","Garage present: 1. Garage absent: minus 1.","Garage present: its mean price. Garage absent: its mean price.","Garage present: 0. Garage absent: 1."],"correct_index":0,"explanation":"The stated convention assigns 1 to presence and 0 to absence. Reversing 0 and 1 is another possible convention, but not the one specified here. Minus 1 coding is not this dummy coding, and group mean prices are outcomes rather than indicators.","set":1},{"id":"da-s2-q2","session":2,"topic":"Reading a dummy coefficient","question":"In a model with age and a garage dummy, the garage coefficient is 0.8 thousand euros per square metre. What does it estimate?","choices":["Homes with a garage have an age slope 800 euros higher than other homes.","Homes with a garage have total mean price 800 euros at a fixed age.","Homes with a garage have mean price 800 euros higher without controlling age.","Homes with a garage have mean price 800 euros higher at a fixed age."],"correct_index":3,"explanation":"The dummy shifts the fitted intercept by 0.8 thousand euros, keeping the age slope unchanged. It is a conditional mean gap, not an absolute price or an uncontrolled group comparison. A differing age slope would require an interaction term.","set":1},{"id":"da-s2-q3","session":2,"topic":"k-1 dummy rule","question":"Four unordered city zones enter a regression that includes an intercept. Which coding represents their separate effects without imposing numeric spacing or perfect collinearity?","choices":["One numeric variable, with the zones assigned the values 0 to 3.","Three indicators, with the omitted zone as the reference category.","Four indicators, with every zone compared against the common intercept.","Two indicators, with the remaining zones sharing one reference effect."],"correct_index":1,"explanation":"With an intercept, k categories require k minus 1 indicators. Four indicators sum to the intercept column. A single 0 to 3 score imposes spacing and ordering. Two indicators merge two zones rather than representing all four separately.","set":1},{"id":"da-s2-q4","session":2,"topic":"Reference category","question":"Zone A is the reference in a model with age and indicators for B and C. An estimate bB = 0.6 thousand euros means what?","choices":["B has mean price 600 euros above A at the same age.","B has mean price 600 euros at the same age.","B has mean price 600 euros above all other zones combined.","B has mean price 600 euros above C at the same age."],"correct_index":0,"explanation":"Each included zone coefficient is a contrast against the omitted category, A, holding age fixed. The contrast against C would be bB minus bC. The coefficient is not a price level or a comparison against a pooled reference.","set":1},{"id":"da-s2-q5","session":2,"topic":"Reference category trap","question":"With A as reference, bB = 0.6 and bC = minus 0.3. What is the fitted C versus B mean gap, and how is its significance assessed?","choices":["Minus 0.9, with a test of the C versus B contrast.","Minus 0.3, with a test of the C versus B contrast.","Minus 0.9, with the individual test of bC against zero.","Plus 0.3, with the individual test of bB against zero."],"correct_index":0,"explanation":"At fixed age, C minus B is bC minus bB, giving minus 0.9. The separate coefficient tests compare each zone with A, not with each other. Test this contrast directly or recode B as the reference before testing C.","set":1},{"id":"da-s2-q6","session":2,"topic":"Testing a dummy coefficient","question":"A regression has n = 100 observations, an intercept and p = 3 predictors including a garage dummy. Which method tests its single dummy coefficient against zero under the lecture assumptions?","choices":["Use its group size divided by its standard error with 98 residual degrees of freedom.","Use its coefficient divided by its standard error with 98 residual degrees of freedom.","Use its coefficient multiplied by its standard error with 96 residual degrees of freedom.","Use its coefficient divided by its standard error with 96 residual degrees of freedom."],"correct_index":3,"explanation":"The ordinary coefficient t test applies to dummies. Residual degrees of freedom are n minus p minus 1, so 96. Using n minus 2 ignores the other predictors. The statistic standardises the coefficient by division, not multiplication or substitution of group size.","set":1},{"id":"da-s2-q7","session":2,"topic":"Partial F-test purpose","question":"A model contains age and two indicators for a three zone variable. To test whether zone contributes beyond age, what is the partial F null hypothesis?","choices":["Both zone coefficients are equal, with their common value unrestricted.","The age coefficient equals zero, with both zone coefficients unrestricted.","Both zone coefficients equal zero, with the age coefficient unrestricted.","All three slope coefficients equal zero, with the intercept unrestricted."],"correct_index":2,"explanation":"The partial comparison removes the zone indicators but retains age. Its null sets both added coefficients to zero. Testing age or all slopes changes the question. Equality of the two zone coefficients tests B versus C rather than whether zone contributes at all.","set":1},{"id":"da-s2-q8","session":2,"topic":"Partial F-test formula","question":"A reduced model has residual deviance 500 and q = 1 predictor. Its complete model has residual deviance 420, p = 3 predictors and n = 100. What is the partial F numerator?","choices":["80, the residual deviance reduction without dividing by the added predictors.","26.67, the residual deviance reduction divided by all three complete model predictors.","4.375, the complete model residual deviance divided by its residual degrees of freedom.","40, the residual deviance reduction divided by the two added predictors."],"correct_index":3,"explanation":"The numerator is (500 minus 420) divided by (3 minus 1), giving 40. The denominator is 420 divided by 96, giving 4.375. Dividing by all complete model predictors belongs to neither this numerator nor its degrees of freedom.","set":1},{"id":"da-s2-q9","session":2,"topic":"Nested vs non-nested","question":"All models use the same response and observations. Which pair permits the lecture's partial F comparison for added predictors?","choices":["A model with age, compared with a model with distance and two zone indicators.","A model with age and distance, compared with a model with age and a garage indicator.","A model with age, compared with a model with age and two zone indicators.","A model with two zone indicators, compared with a model with age and distance."],"correct_index":2,"explanation":"Only the age model and the age plus zone model are nested: every predictor of the smaller model is retained in the larger one. The other pairs replace at least one predictor, so this partial F procedure cannot compare them. The same response and sample are necessary but not sufficient.","set":1},{"id":"da-s2-q10","session":2,"topic":"Global F-test","question":"A model has an intercept and three slopes. Which reduced model makes its partial F test the global F test?","choices":["A model with no intercept, testing only the intercept against zero.","An intercept only model, testing all three slopes jointly against zero.","A model with all three slopes, testing their individual t statistics separately.","A model with one slope, testing the remaining two slopes jointly against zero."],"correct_index":1,"explanation":"The global test compares the examined model with the null model containing only an intercept, q = 0. Its null sets all slopes to zero. Retaining a slope produces a partial test of a smaller group. An intercept test and individual slope tests are different questions.","set":1},{"id":"da-s2-q11","session":2,"topic":"Total deviance invariance","question":"Several regressions with an intercept use exactly the same response values and observations but different predictors. Which quantity is fixed across them?","choices":["Residual degrees of freedom, since every model uses the same sample size.","Explained deviance, since every model includes an intercept.","Residual deviance, since every model uses the same observed responses.","Total deviance, since it uses observed responses and their sample mean."],"correct_index":3,"explanation":"Total deviance depends only on the observed responses around their mean. Fitted values change with the predictor set, so residual and explained deviance can change. Residual degrees of freedom also depend on the number of predictors, not just n.","set":1},{"id":"da-s2-q12","session":2,"topic":"Not rejecting H0 in the global F-test","question":"A global F test has p value 0.12 and is assessed at level 0.05. What does the test support?","choices":["There is insufficient evidence that the population intercept differs from zero.","There is insufficient evidence that at least one population slope differs from zero.","There is sufficient evidence that every population slope equals zero.","There is sufficient evidence that at least one population slope differs from zero."],"correct_index":1,"explanation":"Since 0.12 exceeds 0.05, the global null is not rejected. That is insufficient evidence against jointly zero slopes, not evidence proving them zero. The global test does not test the intercept.","set":1},{"id":"da-s2-q13","session":2,"topic":"k-1 rule mistake","question":"A regression includes an intercept and exhaustive indicators xA, xB and xC for three mutually exclusive zones. Why can its coefficients not all be uniquely estimated?","choices":["The sum xA + xB + xC equals the response column for every observation.","The indicators share similar frequencies, making their correlations close to one.","The sum xA + xB + xC equals the intercept column for every observation.","The indicators have binary values, preventing the calculation of any regression slope."],"correct_index":2,"explanation":"Each unit belongs to exactly one zone, so the indicators sum to 1, an exact linear dependence with the intercept column. Omitting one indicator removes this dummy trap. The issue is exact dependence, not group frequencies or the use of binary predictors.","set":1},{"id":"da-s3-q1","session":3,"topic":"Linearity vs additivity","question":"Advertising has diminishing marginal association with revenue as its own level increases. Its association also differs between new and established products. Which additions address the two features separately?","choices":["An interaction with product status for the first, and a transformation of advertising for the second.","A transformation of advertising for the first, and an interaction with product status for the second.","A transformed intercept for the first, and a product status dummy for the second.","A product status dummy for the first, and a transformed intercept for the second."],"correct_index":1,"explanation":"Changing an effect with its own predictor level concerns nonlinearity. Changing it with another variable concerns nonadditivity. A transformation addresses the first, while an interaction addresses the second. A dummy alone changes the intercept, not the advertising slope.","set":1},{"id":"da-s3-q2","session":3,"topic":"Transformation rules","question":"A researcher adds x squared to allow curvature. Which specification follows the lecture's usual lower order convention?","choices":["Replace x with log(x) even when the sample contains zero values.","Retain x alongside x squared and assess the added curvature term.","Replace x with x squared and assume that all collinearity is removed.","Retain x squared alone and interpret its coefficient as a constant slope."],"correct_index":1,"explanation":"The lecture usually retains all lower powers when introducing a higher power. The quadratic coefficient does not give a constant marginal slope. Logarithms require positive values, and dropping x does not establish absence of collinearity or an appropriate restriction.","set":1},{"id":"da-s3-q3","session":3,"topic":"Reading a transformed effect","question":"The fitted equation is y = 2 + 6x minus x squared. What is its local marginal association with x at x = 4?","choices":["Minus 1, found by reading the coefficient of the quadratic term.","Plus 6, found by reading the coefficient of the linear term.","Minus 2, found by evaluating the derivative 6 minus 2x.","Plus 5, found by adding the two predictor coefficients."],"correct_index":2,"explanation":"Differentiate the fitted equation to obtain 6 minus 2x, then substitute 4 to get minus 2. The linear and quadratic terms contribute together. Neither individual coefficient nor their unweighted sum is the local marginal effect.","set":1},{"id":"da-s3-q4","session":3,"topic":"Derivative vs finite difference","question":"For y = 2 + 6x minus x squared, x moves from 1 to 2. What is the actual fitted change, rather than an endpoint derivative?","choices":["Plus 2, from the derivative evaluated at the ending value 2.","Plus 4, from the derivative evaluated at the starting value 1.","Plus 6, from the coefficient of the untransformed x term.","Plus 3, subtracting the initial fitted value from the final fitted value."],"correct_index":3,"explanation":"Fitted values are 7 at x = 1 and 10 at x = 2, so the finite change is 3. The derivative is 4 at the start and 2 at the end. Those local rates are not the exact finite change over this interval.","set":1},{"id":"da-s3-q5","session":3,"topic":"Log transformation shortcut","question":"For y = 2.4 + 0.3 log(x), using the natural log, x rises by 1%. What is the fitted response change?","choices":["Exactly 0.3 log(1.01), approximately 0.003 in response units.","Exactly 0.3 log(1.01), approximately 0.3% of the response.","Exactly 0.3 times 1.01, approximately 0.303 in response units.","Exactly 0.3 times 0.01, approximately 0.003 in response percent."],"correct_index":0,"explanation":"The change is 0.3 times log(1.01), approximately 0.002985. The 0.003 shortcut is an approximation in Y units, since Y is not logged. It is neither exactly 0.003 nor a percentage change in Y.","set":1},{"id":"da-s3-q6","session":3,"topic":"Interaction term definition","question":"The fitted model is y = b0 + b1 x1 + b2 x2 + bint x1 x2. Holding x2 fixed, what determines the slope on x1?","choices":["b1 + bint x2, so it can vary with x2.","b1 + bint x1, so it can vary with x1.","b1 + bint, so it is constant across all x2.","b1 + b2 x2, so it can vary with x2."],"correct_index":0,"explanation":"Collecting the x1 terms gives x1 times (b1 + bint x2). The slope depends on the other variable. b2 x2 shifts the fitted level at fixed x2, and adding bint alone is correct only at x2 = 1.","set":1},{"id":"da-s3-q7","session":3,"topic":"Quantitative × dummy interaction","question":"For y = 2 + 3x + 5d + 4xd, d is a 0/1 dummy. What are the fitted intercept and slope when d = 1?","choices":["Intercept 2 and slope 7.","Intercept 7 and slope 7.","Intercept 6 and slope 8.","Intercept 7 and slope 3."],"correct_index":1,"explanation":"Substituting d = 1 gives 2 + 3x + 5 + 4x = 7 + 7x. The main dummy term adds 5 to the intercept and the interaction adds 4 to the slope. Ignoring either gives one of the partial results.","set":1},{"id":"da-s3-q8","session":3,"topic":"Non-significant interaction","question":"The interaction in a quantitative predictor and dummy model has p value 0.20 at level 0.05. The researcher removes only that interaction. What follows for the refitted model?","choices":["The fitted group lines coincide, because both the dummy and interaction are removed.","The fitted group slopes were already proven equal in the population before refitting.","The fitted group lines are parallel, while their intercepts may still differ.","The fitted group lines have distinct slopes, while their intercepts must coincide."],"correct_index":2,"explanation":"Removing the product imposes a common slope, while retaining the dummy allows an intercept gap. A nonsignificant test is not proof of equal population slopes and does not automatically delete the dummy. The original estimated lines need not already be parallel.","set":1},{"id":"da-s3-q9","session":3,"topic":"Interaction with k categories","question":"A model includes x, indicators for B and C relative to A, and products x times B and x times C. What structure can it represent?","choices":["Three category lines, with separate intercept and slope adjustments relative to A.","Three category lines, with separate slopes but one necessarily common intercept.","Three category lines, with separate intercepts but one necessarily common slope.","Two category lines, since the omitted category A has no fitted equation."],"correct_index":0,"explanation":"A uses the baseline intercept and slope. Each other category adds its dummy coefficient to the intercept and its product coefficient to the slope. The model allows differences in both, although estimated adjustments can be zero. A remains a represented category.","set":1},{"id":"da-s3-q10","session":3,"topic":"Testing interactions jointly","question":"A three category model has main effects and two product terms, x times B and x times C. Which test asks specifically whether the x slope varies by category?","choices":["A global F test setting every slope coefficient to zero while retaining only the intercept.","An individual t test setting the baseline x coefficient to zero while retaining both product terms.","A partial F test setting both dummy coefficients to zero while retaining both product terms.","A partial F test setting both product coefficients to zero while retaining all main effects."],"correct_index":3,"explanation":"Equal category slopes correspond to both interaction adjustments being zero. Test their joint contribution against a model retaining x and both dummies. Dummy, global, and baseline x tests address intercept differences, all predictors, or the reference slope instead.","set":1},{"id":"da-s3-q11","session":3,"topic":"Variable appearing in multiple forms","question":"A model contains x, x squared and xz, along with z. To assess the overall relevance of x, what comparison follows the lecture?","choices":["Test x alone, retaining x squared, xz and z in the reduced model.","Test x squared alone, retaining x, xz and z in the reduced model.","Test x and z jointly, retaining x squared and xz in the reduced model.","Test x, x squared and xz jointly, retaining z in the reduced model."],"correct_index":3,"explanation":"All model terms involving x must be tested jointly to assess its overall relevance. The partial F comparison removes x, its power and its interaction, while preserving unrelated z. A single term test addresses only that component, not all contributions of x.","set":1},{"id":"da-s3-q12","session":3,"topic":"Confusing non-linearity and non-additivity","question":"One pattern shows that the effect of a budget increase changes with the initial budget. Another shows that it changes with product launch status. Which distinction is correct?","choices":["Both concern nonadditivity, since both are fixed by a launch status dummy.","The first concerns nonadditivity. The second concerns nonlinearity.","The first concerns a nonlinear effect. The second concerns a nonadditive effect.","Both concern nonlinearity, since both are fixed by a squared budget term."],"correct_index":2,"explanation":"Dependence on the same predictor's own level is nonlinearity. Dependence on another predictor's level is nonadditivity. Transforming budget can address curvature, and interacting budget with status can allow different slopes. A dummy alone does not address both.","set":1},{"id":"da-s4-q1","session":4,"topic":"Multicollinearity definition","question":"A regression has more than two predictors. Pairwise correlations are modest, but one predictor is well explained by a combination of the others. Which assessment follows the lecture?","choices":["Perfect multicollinearity must be present because the predictors share information.","Multicollinearity can still be high because overlap may involve several predictors jointly.","Error variance must be unequal because one predictor is explained by the others.","Multicollinearity must be low because all pairwise correlations are modest."],"correct_index":1,"explanation":"With more than two predictors, joint linear dependence can be strong even when pairwise correlations are not. Assess the level of overlap rather than treating any correlation as perfect dependence. Predictor overlap does not itself diagnose unequal error variances.","set":1},{"id":"da-s4-q2","session":4,"topic":"Effect of high multicollinearity","question":"Holding the coefficient estimate fixed, a larger standard error reflects high multicollinearity. How does this affect its two sided t test?","choices":["The absolute t statistic rises and its p value falls.","The absolute t statistic falls and its p value falls.","The absolute t statistic stays fixed and its p value rises.","The absolute t statistic falls and its p value rises."],"correct_index":3,"explanation":"The statistic is the estimate divided by its standard error. A larger denominator reduces its absolute value and raises the two sided p value, making rejection harder. This concerns precision rather than a mechanical change to the coefficient estimate.","set":1},{"id":"da-s4-q3","session":4,"topic":"Multicollinearity extreme case","question":"Correlated predictors have nonsignificant individual t tests, while the model has a significant global F test. Which explanation matches the lecture?","choices":["The group has identical zero coefficients, so all tests agree on their population values.","The group violates normality, which is established by the disagreement between the tests.","The group carries useful information, but overlapping contributions make separate effects hard to estimate.","The group carries no useful information, so the significant global test must be invalid."],"correct_index":2,"explanation":"The global test concerns joint explanatory contribution, while individual tests condition on other predictors. Overlap can inflate standard errors and obscure individual effects. This pattern neither proves zero slopes nor establishes nonnormal errors or an invalid global test.","set":1},{"id":"da-s4-q4","session":4,"topic":"VIF","question":"To calculate VIF for xj, an auxiliary regression explains xj using all other predictors and has R squared 0.95. What is the VIF?","choices":["1.05, using 1 divided by the auxiliary R squared.","20, using 1 divided by (1 minus 0.95).","0.95, using the auxiliary R squared without transformation.","0.05, using 1 minus the auxiliary R squared."],"correct_index":1,"explanation":"VIF is 1 divided by (1 minus Rj squared), giving 20. The auxiliary response is xj, not the original Y. The other quantities omit or change the variance inflation formula.","set":1},{"id":"da-s4-q5","session":4,"topic":"VIF threshold","question":"A quantitative predictor has VIF 12. A dummy term also needs a collinearity diagnostic. Which assessment matches the lecture's conventions?","choices":["12 is below its conventional threshold of 20. The lecture uses GVIF for dummy terms.","12 proves exact collinearity. The lecture uses residual t statistics for dummy terms.","12 exceeds its conventional threshold of 10. The lecture uses Cook's distance for dummy terms.","12 exceeds its conventional threshold of 10. The lecture uses GVIF for dummy terms."],"correct_index":3,"explanation":"The lecture uses VIF above 10 as a somewhat arbitrary high collinearity threshold, and GVIF for dichotomous variables. A finite VIF of 12 indicates strong, not exact, linear overlap. Cook's distance concerns observation influence, not predictor collinearity.","set":1},{"id":"da-s4-q6","session":4,"topic":"Remedies for multicollinearity","question":"Two predictors provide highly overlapping information. Which proposed response addresses a different problem rather than being a collinearity remedy listed in the lecture?","choices":["Remove one overlapping predictor while considering loss of useful information.","Collect more observations to improve precision despite the overlap.","Log transform the response to address changing residual dispersion.","Use principal components to combine the overlapping predictor information."],"correct_index":2,"explanation":"Transforming Y can help with heteroskedasticity, but it is not one of the stated collinearity remedies. The lecture lists removing predictors, increasing sample size, and factor analysis or PCA. Each has a tradeoff rather than a guaranteed cure.","set":1},{"id":"da-s4-q7","session":4,"topic":"Residual plots","question":"Residuals are centred near zero, but their vertical spread increases as fitted values grow. What concern does this pattern most directly raise?","choices":["An exact linear relation among the explanatory variables.","A curved conditional mean with constant error variance.","A constant residual spread around the fitted conditional mean.","Unequal error variances across different fitted conditional mean values."],"correct_index":3,"explanation":"A widening funnel concerns heteroskedasticity. A curved residual centre would instead suggest a missing nonlinear mean relationship. The plot does not establish perfect collinearity, and the observed changing spread contradicts constant variance.","set":1},{"id":"da-s4-q8","session":4,"topic":"Q-Q plot","question":"A normal Q Q plot compares standardized residual quantiles with theoretical normal quantiles and shows strong systematic departures from a straight line. What does this suggest?","choices":["The error normality assumption deserves further scrutiny.","The predictor collinearity assumption has been confirmed.","The constant error variance assumption has been confirmed.","The model's joint slope significance has been established."],"correct_index":0,"explanation":"This plot is a qualitative normality diagnostic. Systematic departures suggest nonnormality rather than confirming homoskedasticity or no collinearity. Neither error diagnostics nor their shape replace a global F test of slopes.","set":1},{"id":"da-s4-q9","session":4,"topic":"Log-log vs log-lin","question":"In a fitted log response and log predictor model, the coefficient on log(distance) is minus 0.3. Using the lecture's small change interpretation, what is associated with a 1% distance increase?","choices":["An approximately 0.3 unit decrease in the response, holding other predictors fixed.","An approximately 30% decrease in the response, holding other predictors fixed.","An approximately 0.3% decrease in the response, holding other predictors fixed.","An approximately 0.003% decrease in the response, holding other predictors fixed."],"correct_index":2,"explanation":"In a log log model the coefficient is a small percentage change elasticity. A 1% increase in distance is associated with approximately minus 0.3% in Y. It is not a fixed response unit change and requires neither multiplication nor division by 100 again.","set":1},{"id":"da-s4-q10","session":4,"topic":"Outlier vs leverage point","question":"A property has an unusually extreme predictor profile but its observed price lies near its fitted price. Which description is supported?","choices":["It can have high leverage without being a regression outlier.","It cannot be anomalous because its residual is small.","It must be both a regression outlier and an influential observation.","It must be a regression outlier without having high leverage."],"correct_index":0,"explanation":"Leverage concerns unusual predictor values, whereas a regression outlier has a large residual. A small residual does not rule out leverage. Influence must be assessed through changes on removal or influence diagnostics, not assumed from leverage alone.","set":1},{"id":"da-s4-q11","session":4,"topic":"Influential observations","question":"Removing one observation substantially changes the fitted regression coefficients. Which diagnostic pairing matches the lecture?","choices":["dfbeta summarizes overall influence. Cook's distance measures each coefficient's change.","dfbeta measures each coefficient's change. Cook's distance summarizes overall influence.","dfbeta measures each residual's normality. GVIF summarizes overall observation influence.","VIF measures each coefficient's change. Cook's distance summarizes predictor collinearity."],"correct_index":1,"explanation":"An influential observation changes regression results materially when removed. dfbeta is defined per coefficient and observation, while Cook's distance is per observation and combines residual and leverage. VIF and GVIF diagnose collinearity, not case deletion influence.","set":1},{"id":"da-s4-q12","session":4,"topic":"Common mistake","question":"A predictor has a nonsignificant t test and a high collinearity diagnostic. What is the most justified interpretation?","choices":["Its individual effect is imprecisely identified given the other predictors, not proven absent.","Its information is entirely redundant because a high diagnostic establishes exact dependence.","Its population effect is zero because a nonsignificant test establishes the null hypothesis.","Its coefficient must be removed because retaining it invalidates every fitted prediction."],"correct_index":0,"explanation":"Overlap can inflate the standard error and leave insufficient evidence of a separate effect. Nonsignificance is not proof of zero, and high but imperfect collinearity is not exact redundancy. Removal needs context because useful information can be lost.","set":1},{"id":"da-s5-q1","session":5,"topic":"Panel data definition","question":"Which study has the cross sectional and temporal structure defining panel data in the lecture?","choices":["One country's GDP and unemployment are recorded annually for thirty years.","Five different countries are selected each year and their identities are not tracked.","The same five countries' GDP and unemployment are recorded annually for thirty years.","Five countries' GDP and unemployment are recorded once in a single year."],"correct_index":2,"explanation":"Panel data repeatedly observe the same units through time. A single year is cross sectional, one country through time is a time series, and replacing units each year without tracking them does not provide the same longitudinal structure.","set":1},{"id":"da-s5-q2","session":5,"topic":"Balanced panel","question":"A balanced panel follows five countries annually from 1991 through 2020 inclusive. How many recorded values are available for each variable?","choices":["145, from five units observed at twenty nine time points.","30, from counting only the annual time points.","150, from five units observed at thirty time points.","300, from doubling the number for two measured variables."],"correct_index":2,"explanation":"The inclusive interval contains 30 years. A balanced panel gives n times T = 5 times 30 = 150 values per variable. Two variables give two sets of 150, not 300 values for each variable.","set":1},{"id":"da-s5-q3","session":5,"topic":"Why classic regression fails","question":"The same firms are observed repeatedly. Why can ordinary cross sectional regression assumptions fail when these observations are pooled?","choices":["Errors across dates within the same firm can correlate.","Repeated observations automatically create perfect predictor collinearity.","The response cannot be quantitative when firms are observed repeatedly.","The predictor coefficients necessarily vary at every date."],"correct_index":0,"explanation":"Repeated observations can share persistent unit influences, violating the ordinary uncorrelated error assumption. Panel responses can be quantitative, and repeated sampling neither forces changing slopes nor exact predictor dependence.","set":1},{"id":"da-s5-q4","session":5,"topic":"Pooling model","question":"A researcher stacks all unit and time observations and fits ordinary OLS without using unit identities. Which feature identifies the lecture's pooling approach?","choices":["It estimates a separate intercept for each unit to absorb its permanent traits.","It treats each row as a separate observation without modelling the shared unit structure.","It decomposes errors and uses generalized least squares for a shared unit component.","It compares fixed and random effects using the Hausman test before estimation."],"correct_index":1,"explanation":"Pooling ignores the panel structure and applies ordinary regression to the stacked rows. Unit intercepts describe fixed effects. A random shared component with generalized estimation describes random effects, and Hausman is a model comparison test rather than pooling.","set":1},{"id":"da-s5-q5","session":5,"topic":"Fixed Effects Model","question":"In the fixed effects equation Yit = alpha + beta xit + mu_i + epsilon_it, what does mu_i represent?","choices":["A fixed time component, shared by all units, absorbed into each date's intercept.","A fixed unit component, constant across time, absorbed into the unit's intercept.","A random temporary shock, changing across time, absorbed into the unit's slope.","A random predictor coefficient, changing across units, absorbed into each observation's slope."],"correct_index":1,"explanation":"The lecture's individual fixed effect captures unobserved traits of a unit that remain constant through time. alpha plus mu_i is its individual intercept, while the slope is common. Time effects and varying slopes are not the component in this stated model.","set":1},{"id":"da-s5-q6","session":5,"topic":"Random Effects Model","question":"A firm's persistent unobserved management quality affects Y and is correlated with x. Which random effects requirement is at issue?","choices":["The individual error component must have exactly the same value for every unit.","The explanatory variable must be constant within every unit across all dates.","The idiosyncratic component must account for all persistent differences between units.","The individual error component must be uncorrelated with the explanatory variables."],"correct_index":3,"explanation":"REM requires both error components to be uncorrelated with the predictors. Correlation of the persistent unit component with x threatens consistency. Equal effects across firms, forcing persistent variation into epsilon, and time constant x are not its defining requirement.","set":1},{"id":"da-s5-q7","session":5,"topic":"FEM vs REM parameter count","question":"Why does the lecture favour random effects over fixed effects when the random effects assumptions hold?","choices":["It guarantees consistent coefficients even when the unit component is correlated with x.","It removes all idiosyncratic variation and therefore produces exact fitted responses.","It permits every unit to have a separate slope while avoiding any common intercept.","It offers more efficient coefficient estimation without estimating one fixed intercept per unit."],"correct_index":3,"explanation":"Under its assumptions REM is consistent and more efficient, while FEM estimates individual effects and loses degrees of freedom. This preference is conditional on validity. It does not permit correlation with x, remove all noise, or impose unit specific slopes.","set":1},{"id":"da-s5-q8","session":5,"topic":"Individual vs idiosyncratic error","question":"A panel error combines a firm's persistent culture and a temporary market shock. Which allocation matches the lecture?","choices":["Culture belongs to epsilon_it. The temporary shock belongs to mu_i.","Culture belongs to mu_i. The temporary shock belongs to epsilon_it.","Both belong to mu_i because every error is specific to a firm.","Both belong to epsilon_it because neither is directly observed."],"correct_index":1,"explanation":"mu_i captures persistent time constant differences across units. epsilon_it captures temporary fluctuations that vary over units and dates. Being unobserved does not determine which component applies, and unit specificity alone does not imply time constancy.","set":1},{"id":"da-s5-q9","session":5,"topic":"Hausman test decision rule","question":"A Hausman comparison returns p value 0.02 at level 0.05. Under the lecture's decision rule, which model is selected and why?","choices":["Fixed effects, since the null supporting random effects consistency is rejected.","Random effects, since the null supporting random effects consistency is rejected.","Random effects, since the null requiring zero coefficients for all slopes is rejected.","Fixed effects, since the null requiring zero coefficients for all slopes is rejected."],"correct_index":0,"explanation":"0.02 is below 0.05, so reject the Hausman null that REM assumptions hold. The lecture then chooses FEM. This is not the global null of zero slopes, and rejecting it does not favour REM.","set":1},{"id":"da-s5-q10","session":5,"topic":"High individual-error variance","question":"A valid random effects model assigns most unexplained variance to its individual component. What is the appropriate interpretation?","choices":["The high individual share itself proves that the random effects coefficients are inconsistent.","The high individual share itself proves correlation between that component and x.","Persistent differences between individual units dominate the remaining unexplained model variation.","Temporary within unit fluctuations dominate the remaining unexplained variation."],"correct_index":2,"explanation":"A large individual variance indicates substantial persistent differences across units. It does not itself establish correlation with predictors or inconsistency. The stated validity assumptions still matter, while a dominant idiosyncratic component would indicate temporary fluctuations.","set":1},{"id":"da-s5-q11","session":5,"topic":"fixef() prediction","question":"A fitted fixed effects model gives firm A's full unit intercept 20 and a common slope 0.2. For that firm at x = 100, which fitted mean is correct?","choices":["40, using firm A's full intercept plus the common slope times x.","100, using firm A's predictor value as its fitted response.","20, using only the common slope times x and omitting the unit intercept.","24, multiplying firm A's intercept by one plus the common slope."],"correct_index":0,"explanation":"The fitted firm equation is alpha_A + beta x = 20 + 0.2 times 100 = 40. Use the unit's full intercept, obtainable through fixef for the lecture's within model. Do not omit it, substitute x for Y, or multiply it by the slope.","set":1},{"id":"da-s6-q1","session":6,"topic":"Probability vs odds","question":"An event has probability 0.8. What are its odds?","choices":["0.25, comparing nonevent probability with event probability.","0.8, treating event probability itself as the odds.","5, taking the reciprocal of nonevent probability.","4, comparing event probability with nonevent probability."],"correct_index":3,"explanation":"Odds are p divided by (1 minus p), so 0.8 divided by 0.2 = 4. The inverse ratio is the odds of the complementary event. Neither p itself nor the reciprocal of 1 minus p is the event's odds.","set":1},{"id":"da-s6-q2","session":6,"topic":"Probability vs odds","question":"Two events have probabilities 0.4 and 0.8. Which pair gives their respective odds and respects the difference between probability and odds?","choices":["0.6 and 0.2, so odds equal the complementary probabilities.","0.4 and 0.8, so odds must always stay below one.","Approximately 0.667 and 4, so odds need not stay below one.","1.5 and 0.25, so odds decrease when probability increases."],"correct_index":2,"explanation":"Use p/(1 minus p): 0.4/0.6 = 0.667 and 0.8/0.2 = 4. Odds increase with probability and can exceed 1. They are neither probabilities nor their complements.","set":1},{"id":"da-s6-q3","session":6,"topic":"Probability vs odds","question":"An event has odds 3. What probability corresponds to those odds?","choices":["0.75, using odds divided by one plus odds.","0.333, using one divided by the odds.","3, treating the odds as the probability.","0.25, using one divided by one plus odds."],"correct_index":0,"explanation":"Invert the odds formula: p = 3/(1 + 3) = 0.75. The value 0.25 is the complement probability. Probability is not odds or its reciprocal.","set":1},{"id":"da-s6-q4","session":6,"topic":"Log-odds behavior","question":"As an event probability approaches 1 from below, what happens to its log odds?","choices":["They decrease without bound as the event probability approaches one.","They approach one because probabilities cannot exceed one.","They approach zero as the event probability approaches its upper bound.","They increase without bound as the nonevent probability approaches zero."],"correct_index":3,"explanation":"p/(1 minus p) tends to positive infinity, and so does its logarithm. Log odds equal zero at p = 0.5 and tend to negative infinity as p approaches zero, not one.","set":1},{"id":"da-s6-q5","session":6,"topic":"Logistic regression setup","question":"A researcher models whether a debtor defaults, coded 1 for default and 0 otherwise. Why is the lecture's binary logit model suitable for the response type?","choices":["The response measures odds directly and can take values greater than one.","The response is binary and its conditional mean is an event probability.","The response measures log odds directly and can take any real value.","The response is continuous and its conditional mean is a default amount."],"correct_index":1,"explanation":"The observed Y is Bernoulli, not observed odds or log odds. Its expected value is the probability of Y = 1. The model transforms that probability, rather than changing the binary response into a directly observed continuous quantity.","set":1},{"id":"da-s6-q6","session":6,"topic":"Logistic regression setup","question":"For Y taking 1 with probability p and 0 otherwise, what is E(Y)?","choices":["log(p divided by 1 minus p), from using the logit.","p, from weighting the two response values by their probabilities.","p divided by 1 minus p, from using the event odds.","1 minus p, from using the probability of the zero response."],"correct_index":1,"explanation":"E(Y) = 1 times p + 0 times (1 minus p) = p. The odds and logit are transformations of this mean, not the mean itself.","set":1},{"id":"da-s6-q7","session":6,"topic":"Model equation","question":"A logit model's linear predictor is eta = b0 + b1 x1 + b2 x2. Which fitted quantity equals eta?","choices":["Log odds, log(p divided by (1 minus p)).","The probability p without any transformation.","The odds p divided by (1 minus p).","The log of the probability p alone."],"correct_index":0,"explanation":"The linear model applies to log odds. Odds equal exp(eta), and probability equals exp(eta)/(1 + exp(eta)). The untransformed probability and its log are not eta.","set":1},{"id":"da-s6-q8","session":6,"topic":"Estimation","question":"How does the lecture estimate the unknown coefficients of its binary logit model?","choices":["A Hausman comparison, rather than fitting the binary response model.","Ordinary least squares, rather than maximum likelihood for the binary responses.","A partial F comparison, rather than fitting the binary response model.","Maximum likelihood, rather than ordinary least squares for the binary responses."],"correct_index":3,"explanation":"The lecture states maximum likelihood and leaves its calculation to software. F tests compare linear models in the earlier sessions. Hausman compares fixed and random effects panel models, not logit coefficient estimation.","set":1},{"id":"da-s6-q9","session":6,"topic":"Odds ratio, quantitative variable","question":"A quantitative predictor has coefficient b in an additive logit model. With all other predictors fixed, what does exp(b) compare?","choices":["Event odds before a one unit predictor increase divided by event odds after it.","Event probability after a one unit predictor increase divided by probability before it.","Event probability after a one unit predictor increase minus probability before it.","Event odds after a one unit predictor increase divided by event odds before it."],"correct_index":3,"explanation":"A unit predictor increase adds b to log odds, multiplying odds by exp(b). This is an odds ratio in the stated direction, not a probability ratio, its reciprocal, or a probability difference.","set":1},{"id":"da-s6-q10","session":6,"topic":"Odds ratio, quantitative variable","question":"A predictor's fitted coefficient equals zero in an additive logit model. What happens to fitted odds after a one unit increase with other predictors fixed?","choices":["They increase by 1, so probability rises by one percentage point.","They are multiplied by 0, so the event becomes impossible.","They are multiplied by 1, so neither odds nor probability changes.","They stay fixed, but probability necessarily changes with the predictor."],"correct_index":2,"explanation":"exp(0) = 1. Unchanged odds imply unchanged probability because their correspondence is one to one. A zero fitted coefficient does not set the event odds to zero or add one to them.","set":1},{"id":"da-s6-q11","session":6,"topic":"Odds ratio, dichotomous variable","question":"A dummy is coded 1 for female and 0 for male. With age fixed, what is exp(bfemale) in the lecture's awareness model?","choices":["Female awareness probability minus male awareness probability.","Female awareness probability divided by male awareness probability.","Male awareness odds divided by female awareness odds.","Female awareness odds divided by male awareness odds."],"correct_index":3,"explanation":"The dummy comparison moves from 0 to 1, so exp(bfemale) is female odds over male odds at fixed age. The reverse odds ratio is exp(minus bfemale). A ratio or difference of probabilities is not given by exponentiating the coefficient.","set":1},{"id":"da-s6-q12","session":6,"topic":"Worked example (awareness)","question":"In the awareness logit model, the age coefficient is 0.2 and exp(0.2) is 1.2214. For one extra year with sex fixed, which change is correct?","choices":["Awareness odds rise by 22.14%, while the probability change depends on its starting level.","Awareness probability rises by 0.2 percentage points at every starting level.","Awareness odds rise by 1.2214%, while the probability change depends on its starting level.","Awareness probability rises by 22.14%, while the odds change depends on its starting level."],"correct_index":0,"explanation":"The odds factor is 1.2214, equivalent to a 22.14% increase in odds. The event probability also rises, but its change cannot be obtained from this coefficient alone without the baseline probability.","set":2},{"id":"da-s6-q13","session":6,"topic":"Worked example (awareness)","question":"The female dummy coefficient is minus 0.8 and exp(minus 0.8) is 0.4493. At the same age, which comparison is correct?","choices":["Female awareness odds are 55.07% of male odds, a 44.93% reduction.","Female awareness probability is 44.93% of male probability, a 55.07% reduction.","Female awareness odds are 144.93% of male odds, a 44.93% increase.","Female awareness odds are 44.93% of male odds, a 55.07% reduction."],"correct_index":3,"explanation":"The odds factor 0.4493 expresses the retained proportion. Subtract it from 1 for the reduction: 0.5507. This ratio applies to odds, not probability, and a factor below one indicates a reduction.","set":2},{"id":"da-s6-q14","session":6,"topic":"Odds ratio, sign rule","question":"A predictor has a negative coefficient in an additive logit model. For an increase in that predictor with others fixed, which direction follows?","choices":["Neither changes, because the coefficient acts only on log odds.","Both fitted odds and fitted event probability decrease.","Fitted odds decrease but fitted event probability increases.","Fitted odds increase but fitted event probability decreases."],"correct_index":1,"explanation":"A negative coefficient reduces log odds, and hence odds. Probability is an increasing function of odds, so it also decreases. Modelling log odds does not isolate the change from probability.","set":2},{"id":"da-s6-q15","session":6,"topic":"Test on individual coefficient","question":"A logit coefficient is 0.42 with standard error 0.25. The two sided 5% critical absolute z value is 1.96. What is the decision?","choices":["Do not reject, because the absolute z statistic is 1.68.","Reject, because the absolute z statistic is 1.68.","Reject, because the absolute z statistic is 2.38.","Do not reject, because the absolute z statistic is 0.105."],"correct_index":0,"explanation":"The statistic is 0.42 divided by 0.25 = 1.68, below 1.96. Multiplying gives 0.105, while taking a reciprocal of the estimate gives about 2.38, neither of which is the statistic. A nonzero estimate does not alone establish significance.","set":2},{"id":"da-s6-q16","session":6,"topic":"Test on individual coefficient","question":"For testing a single logit coefficient against zero, which statistic and null approximation does the lecture use?","choices":["Estimate divided by standard error, exactly Student t with n minus p minus 1 degrees of freedom.","Estimate squared without standardization, approximately F with p numerator degrees of freedom.","Estimate divided by its estimated standard error, with an approximate standard normal null distribution.","Estimate multiplied by standard error, approximately standard normal."],"correct_index":2,"explanation":"The lecture's individual logit test uses a Wald z ratio and an approximate standard normal null distribution. It is not the exact linear regression t procedure, an unstandardised square, or a product with the standard error.","set":2},{"id":"da-s6-q17","session":6,"topic":"Common exam trap","question":"A one unit change multiplies event odds by 1.22. Initially the probability is 0.5. What is the new probability, approximately?","choices":["0.550, obtained from new odds 1.22 divided by 2.22.","0.610, obtained by multiplying the initial probability by 1.22.","0.450, obtained by using one divided by 2.22.","0.720, obtained by adding 0.22 to the initial probability."],"correct_index":0,"explanation":"Initially odds are 1. They become 1.22, so p = 1.22/(1 + 1.22), approximately 0.550. The 22% increase concerns odds, not a probability multiplier or a 22 percentage point increase. 1/2.22 gives the complementary probability.","set":2},{"id":"da-s7-q1","session":7,"topic":"Why a new test","question":"Two dummies represent a three category predictor in a logit model. Why do two separate coefficient Z tests not replace a joint test of the predictor?","choices":["Each Z test concerns one coefficient, while the joint null sets both to zero together.","Each Z test concerns all slopes, while the joint null concerns only the intercept.","Each Z test concerns probabilities directly, while the joint null concerns their sample average.","Each Z test compares nonnested models, while the joint test compares predicted classes."],"correct_index":0,"explanation":"The individual Wald test is for one coefficient. A group comparison tests a vector of coefficients jointly, using the session's likelihood ratio procedure. It does not concern all slopes unless global, the intercept alone, or the sample classification average.","set":1},{"id":"da-s7-q2","session":7,"topic":"Partial vs global test","question":"How does the global likelihood ratio test of a logit model relate to the partial test?","choices":["It uses an intercept only reduced model, so all added slope coefficients are tested jointly.","It uses a reduced model with one predictor, so the remaining slopes are tested jointly.","It uses a no intercept complete model, so the intercept coefficient is tested alone.","It averages the individual Z statistics, so all predictor tests receive equal weights."],"correct_index":0,"explanation":"The global test is the partial comparison with q = 0 and a reduced model containing only the intercept. It tests all slopes, not the intercept. Averaging Z statistics is not the likelihood ratio procedure.","set":1},{"id":"da-s7-q3","session":7,"topic":"Residual deviance","question":"For the lecture's individual binary response logit model, the maximized log likelihood is minus 80. What is the residual deviance?","choices":["40, using minus half the maximized log likelihood.","Minus 160, using twice the maximized log likelihood.","160, using minus twice the maximized log likelihood.","80, using minus the maximized log likelihood alone."],"correct_index":2,"explanation":"The lecture defines residual deviance as minus 2 log L(M). With log L(M) = minus 80, the result is 160. This is a likelihood based quantity, not a squared residual sum or a log likelihood with another scale.","set":1},{"id":"da-s7-q4","session":7,"topic":"Chi-square test statistic","question":"On the same sample, a reduced logit model has deviance 250 and one predictor. A complete nested model has deviance 238 and three predictors. What are the likelihood ratio statistic and degrees of freedom?","choices":["Minus 12 with 2 degrees of freedom, subtracting reduced deviance from complete deviance.","12 with 3 degrees of freedom, counting all complete model predictors.","12 with 2 degrees of freedom, from the deviance and parameter differences.","6 with 2 degrees of freedom, after dividing the deviance change by added predictors."],"correct_index":2,"explanation":"The statistic is 250 minus 238 = 12, with p minus q = 2 degrees of freedom. Unlike the linear model F statistic, no division by added predictors is used. Counting all slopes would apply to a global comparison with an intercept only model.","set":1},{"id":"da-s7-q5","session":7,"topic":"LRT naming","question":"Why are the session's partial and global chi square procedures also called likelihood ratio tests?","choices":["Their statistics compare classification accuracy ratios at the 0.5 threshold.","Their statistics compare maximized likelihoods through differences in minus twice log likelihood.","Their statistics compare the ratios of individual coefficient standard errors.","Their statistics compare a predictor's VIF against its generalized VIF."],"correct_index":1,"explanation":"The residual deviance difference equals minus twice the log ratio of reduced to complete maximized likelihoods. That is the basis of LRT. Standard errors, classification accuracy and VIF diagnose different aspects and do not define this test.","set":1},{"id":"da-s7-q6","session":7,"topic":"Prediction steps","question":"A fitted logit model gives linear predictor eta for a new observation. Which sequence obtains the event probability?","choices":["Exponentiate eta to get probability, then divide probability by one minus probability.","Exponentiate eta to get odds, then divide odds by one plus odds.","Treat eta as probability, then threshold it before calculating odds.","Take the logarithm of eta to get odds, then divide odds by one plus odds."],"correct_index":1,"explanation":"The linear predictor is log odds. exp(eta) gives odds, and odds/(1 + odds) gives probability. Thresholding is a later classification choice, not the conversion from the fitted equation to probability.","set":1},{"id":"da-s7-q7","session":7,"topic":"Prediction of Y","question":"The predicted event probability is exactly 0.5. Under the lecture's stated default classification rule, which class is predicted?","choices":["1 for every model, because no other classification threshold is permitted.","0, because the default rule includes equality below the cutoff.","Neither, because a probability of 0.5 is undefined for a binary response.","1, because the default rule includes equality at 0.5."],"correct_index":3,"explanation":"The stated rule predicts 1 when p is at least 0.5 and 0 otherwise. A probability of 0.5 is valid. The lecture allows other thresholds, so this answer depends on the specified default rather than a universal requirement.","set":1},{"id":"da-s7-q8","session":7,"topic":"AIC","question":"A logit model has residual deviance 159.84, three predictor coefficients and an intercept. What is its AIC under the lecture formula?","choices":["159.84, using residual deviance without a complexity penalty.","167.84, adding twice the four fitted coefficients.","163.84, adding the four fitted coefficients once.","165.84, adding twice the three predictor coefficients."],"correct_index":1,"explanation":"AIC equals residual deviance + 2(p + 1). With p = 3 and an intercept, the penalty is 8, giving 167.84. Omitting the intercept, dropping the factor 2, or omitting the penalty yields the other results.","set":1},{"id":"da-s7-q9","session":7,"topic":"AIC interpretation","question":"Two compatible logit models fitted to the same response and sample have AIC 168 and 175. What follows according to this criterion?","choices":["Neither can be compared unless the two models have identical predictor sets.","The model with AIC 168 is proven significantly better by a test at 5%.","The model with AIC 175 is preferred because a larger penalty indicates better fit.","The model with AIC 168 is preferred by the fit and complexity tradeoff."],"correct_index":3,"explanation":"Lower AIC is preferred. It is a descriptive comparison balancing likelihood fit against parameter count, not a significance test or proof. The predictor sets can differ, provided models are compared on compatible data and response.","set":1},{"id":"da-s7-q10","session":7,"topic":"AIC vs chi-square test","question":"A logit model with age is nested within a model with age and two vehicle indicators, fitted to the same sample. Which tool formally tests whether the indicators contribute?","choices":["A partial chi square likelihood ratio test of the two added coefficients.","A global Z test formed by averaging the two individual Z values.","An AIC comparison interpreted as a p value for the added coefficients.","A comparison of the models' raw classification accuracy alone."],"correct_index":0,"explanation":"The session's partial LRT tests the added group jointly in nested models. AIC and classification accuracy are descriptive, while an average of Z statistics is not this joint test. The reduced model retains age.","set":1},{"id":"da-s7-q11","session":7,"topic":"Worked example, insurance","question":"In the insurance model, the age coefficient is minus 0.0389 and its odds multiplier is 0.9618. With vehicle category fixed, how do high claim odds change for one extra year?","choices":["They decrease by about 3.82%, retaining 96.18% of their previous value.","The claim probability decreases by exactly 3.82 percentage points.","They increase by about 3.89%, since the absolute coefficient is 0.0389.","They decrease by about 96.18%, retaining 3.82% of their previous value."],"correct_index":0,"explanation":"An odds factor of 0.9618 means a reduction of 1 minus 0.9618 = 0.0382, or 3.82%. It is not the retained percentage as a reduction. The coefficient is negative, and the exact probability change requires the starting probability.","set":1},{"id":"da-s7-q12","session":7,"topic":"Worked example, insurance","question":"The insurance model's global likelihood ratio test has statistic 77.344 on 3 degrees of freedom and p value below 2.2 times 10 to the power minus 16. What is supported at 5%?","choices":["Every fitted binary class is correct, so the model has perfect accuracy.","The intercept differs from zero, so the model's baseline probability is significant.","Every slope differs from zero, so all individual predictors are significant.","At least one slope differs from zero, so the model is globally significant."],"correct_index":3,"explanation":"The global null sets all slopes to zero and the alternative requires at least one nonzero slope. Rejection does not establish individual significance of every coefficient, test the intercept, or imply perfect prediction.","set":1},{"id":"da-s7-q13","session":7,"topic":"Worked example, insurance","question":"The insurance LRT compares age alone with age plus vehicle category. It has statistic 69.202 on 2 degrees of freedom and a very small p value. What contribution is tested?","choices":["All three slopes jointly, comparing the complete model with an intercept only model.","Age alone, controlling for vehicle category retained in both models.","Both vehicle indicators jointly, controlling for age retained in both models.","The intercept alone, comparing models with and without a common intercept."],"correct_index":2,"explanation":"The reduced model retains age and omits the two vehicle indicators. Their additional joint contribution is the tested group. Two degrees of freedom correspond to the two added coefficients, rather than all three slopes.","set":1},{"id":"da-s7-q14","session":7,"topic":"Worked example, insurance","question":"Of 200 cases, 128 predicted negatives and 40 predicted positives match their observed classes. What is the overall proportion classified correctly?","choices":["16%, using the 32 misclassified cases divided by 200.","20%, using only the 40 correct positives divided by 200.","84%, using all 168 correct cases divided by 200.","64%, using only the 128 correct negatives divided by 200."],"correct_index":2,"explanation":"Both correct negative and correct positive classifications count. (128 + 40)/200 = 0.84. The two components individually are 64% and 20%, while 16% is the error rate, not accuracy.","set":1},{"id":"da-s7-q15","session":7,"topic":"Common exam trap","question":"Two logit models on the same binary response and sample use unrelated predictor sets, so neither nests within the other. Which comparison from this session is applicable?","choices":["AIC, as a descriptive fit and complexity comparison rather than the nested partial LRT.","The individual Z test, treating one coefficient from each model as a joint contrast.","The partial LRT, treating the difference in predictor counts as sufficient for nesting.","The global LRT, subtracting their deviances as if either model were an intercept only model."],"correct_index":0,"explanation":"AIC permits a descriptive comparison of compatible nonnested models. Having different parameter counts alone does not make models nested. Individual Z and global intercept only comparisons cannot be repurposed as the stated nested group test.","set":1},{"id":"da-s8-q1","session":8,"topic":"Multinomial setup","question":"A consumer chooses one of three unordered brands. Which response structure calls for the lecture's multinomial rather than binary logit model?","choices":["One continuous response separated by three explanatory variables.","One qualitative outcome taking three distinct unordered response categories.","Three quantitative predictors with one binary response.","One binary response observed at three different dates."],"correct_index":1,"explanation":"The distinction depends on the dependent variable's categories, not the predictor count or observation dates. Multinomial logit represents a qualitative response with more than two categories. Binary logit already allows multiple predictors.","set":1},{"id":"da-s8-q2","session":8,"topic":"Number of equations","question":"A response has four categories with A1 as reference. How many log ratio equations are estimated?","choices":["Three, for A2, A3 and A4 relative to A1.","Four, one for every category relative to A1.","Six, one for every possible pair of categories.","One, assigning category numbers as a quantitative response."],"correct_index":0,"explanation":"The formulation has k minus 1 equations. A1 is the reference, so its probability is recovered through normalization, not a separate equation. All pairwise equations are unnecessary, and treating labels as a quantitative response changes the model.","set":1},{"id":"da-s8-q3","session":8,"topic":"Reference category","question":"In a multinomial model with A1 as reference, what does the equation for category A2 express?","choices":["log(p2/p1), the log probability ratio for A2 relative to A1.","log(p2/p3), the log probability ratio for A2 relative to A3.","log(p2/(1 minus p2)), the log odds for A2 relative to all other categories.","log(p1/p2), the reverse log probability ratio for A1 relative to A2."],"correct_index":0,"explanation":"Each equation compares a nonreference category with the specified reference. For more than two categories, p1 is not generally 1 minus p2. A different denominator or reversed ratio changes the contrast and its coefficients.","set":1},{"id":"da-s8-q4","session":8,"topic":"Coefficients across equations","question":"The age coefficients are 0.03 in log(p2/p1) and 0.01 in log(p3/p1). Is this compatible with the lecture's multinomial specification?","choices":["No, the same predictor must have the same coefficient in every equation.","Yes, each nonreference equation has its own coefficients for the predictors.","Yes, but only if the two probability ratios are treated as independent binary responses.","No, at most one nonreference category may have a nonzero age coefficient."],"correct_index":1,"explanation":"Category equations generally have different coefficient sets because they model different reference contrasts. They jointly define one multinomial response and are normalized together, rather than separate independent binary responses.","set":1},{"id":"da-s8-q5","session":8,"topic":"Interpreting a coefficient, quantitative","question":"The age coefficient in log(p2/p1) is 0.03, with other predictors fixed. What changes for one extra year?","choices":["The probability p2 is multiplied by exp(0.03), about a 3.05% increase.","The ratio p1/p2 is multiplied by exp(0.03), about a 3.05% increase.","The probability p2 increases by exactly 0.03 percentage points.","The ratio p2/p1 is multiplied by exp(0.03), about a 3.05% increase."],"correct_index":3,"explanation":"A unit increase adds 0.03 to the specified log ratio, multiplying p2/p1 by exp(0.03). The probability p2 itself depends on all equations and normalization. Reversing the ratio changes the multiplier to exp(minus 0.03).","set":1},{"id":"da-s8-q6","session":8,"topic":"Interpreting a coefficient, dichotomous","question":"A dummy coefficient is minus 0.6 in log(p2/p1). Comparing dummy 1 with dummy 0, all else fixed, how does p2/p1 change?","choices":["It is about 54.88% lower, since exp(minus 0.6) is about 0.5488.","It is about 45.12% lower, since exp(minus 0.6) is about 0.5488.","It is about 60% lower, since the coefficient equals minus 0.6.","It is about 45.12% higher, since the coefficient magnitude is 0.6."],"correct_index":1,"explanation":"The multiplier 0.5488 retains 54.88% of the original ratio, corresponding to a 45.12% reduction. The coefficient acts on log ratio rather than a direct percentage scale, and its negative sign implies a decrease.","set":1},{"id":"da-s8-q7","session":8,"topic":"Test on individual coefficient","question":"For the coefficient of x in the A3 versus A1 equation, what does rejecting H0: beta_x3 = 0 support?","choices":["x is associated with the A2 versus A1 conditional odds in the population.","x is associated with all category probabilities by the same amount in the population.","x is associated only with the overall probability of choosing A1 in the population.","x is associated with the A3 versus A1 conditional odds in the population."],"correct_index":3,"explanation":"The individual null concerns one predictor in one specified category contrast. Rejecting it supports a nonzero effect on that ratio, not identical changes in all probabilities or a different equation's coefficient.","set":1},{"id":"da-s8-q8","session":8,"topic":"Tests not covered","question":"Which description accurately reflects the lecture's scope of multinomial significance testing?","choices":["All significance tests use the same one degree of freedom regardless of coefficients tested.","All significance tests are excluded because multinomial coefficients cannot be tested.","Individual Z tests are covered, with joint and global chi square tests mentioned only.","Individual Z tests are excluded. Joint and global chi square tests are developed."],"correct_index":2,"explanation":"The lecture develops individual coefficient tests using an approximate standard normal statistic. It notes that group and entire model tests exist but does not cover them here. This is a scope limit, not impossibility of such tests.","set":1},{"id":"da-s8-q9","session":8,"topic":"Prediction method","question":"At fixed predictors, exp(eta2) = r2 and exp(eta3) = r3 give p2/p1 and p3/p1. Which reference probability is correct?","choices":["p1 = 1/(1 + r2) without using r3.","p1 = 1 minus r2 minus r3.","p1 = 1/(r2 + r3).","p1 = 1/(1 + r2 + r3)."],"correct_index":3,"explanation":"Substitute p2 = r2 p1 and p3 = r3 p1 into p1 + p2 + p3 = 1. This gives p1(1 + r2 + r3) = 1. All category equations must share this normalization.","set":1},{"id":"da-s8-q10","session":8,"topic":"Worked example, brands","question":"For a thirty year old woman in the brand example, log(p2/p1) = 2.1 and log(p3/p1) = 1.4. Which next calculation correctly recovers p2?","choices":["exp(1.4)/(1 + exp(2.1) + exp(1.4)).","exp(2.1)/(1 + exp(2.1)).","2.1/(1 + 2.1 + 1.4).","exp(2.1)/(1 + exp(2.1) + exp(1.4))."],"correct_index":3,"explanation":"Exponentiate both log ratios and normalize all three categories. The result is approximately 0.6176. A separate binary conversion ignores A3, using raw log ratios skips exponentiation, and the final expression gives p3 rather than p2.","set":1},{"id":"da-s8-q11","session":8,"topic":"Worked example, students","question":"A fitted program choice model reports equations labelled academic and vocation, with general as the omitted category. How should the academic equation be interpreted?","choices":["As log probability ratio academic over vocation, the other reported equation.","As log odds of academic over both remaining categories pooled together.","As log probability ratio academic over general, the model's reference category.","As log probability ratio general over academic, reversing the reference contrast."],"correct_index":2,"explanation":"The omitted response category is the reference for each reported equation. The academic coefficient set therefore models academic versus general. Always inspect the actual factor reference rather than assuming it from category names or ordering.","set":1},{"id":"da-s8-q12","session":8,"topic":"Worked example, students","question":"A multinomial dummy coefficient is 0.1802 with standard error 0.4000. The two sided 5% critical absolute Z value is 1.96. What conclusion is justified?","choices":["Reject its zero null, since every positive estimate establishes a population effect.","Reject its zero null, since exp(0.1802) is approximately 1.1975.","Do not reject its zero null, since the absolute Z statistic is approximately 0.451.","Do not reject its zero null, since its estimated odds ratio is exactly one."],"correct_index":2,"explanation":"The ratio 0.1802/0.4000 is about 0.4505, below 1.96. A positive estimated coefficient or odds ratio above one is not enough for significance. The estimated odds ratio is about 1.1975, not exactly one. The standard error here is supplied for this test exercise.","set":1},{"id":"da-s8-q13","session":8,"topic":"Common exam trap","question":"The coefficient on x in log(p3/p1) is 0.01. Why is it wrong to call 0.01 the direct effect on overall p3?","choices":["It changes a log category ratio, while p3 also depends on the other equations through normalization.","It changes p3 directly, but the response category labels have no mathematical meaning.","It changes only the intercept, while all predictor effects must be common across equations.","It changes the log ratio p1/p3, while p3 is fixed by definition."],"correct_index":0,"explanation":"The model coefficient acts on log(p3/p1). To recover p3, all exponentiated equations share a denominator. Therefore a ratio effect is not a constant direct probability effect. The coefficient is neither merely an intercept nor the reversed ratio.","set":1},{"id":"da-s8-q14","session":8,"topic":"Common exam trap","question":"Age coefficients are 0.03 for A2 versus A1 and 0.01 for A3 versus A1. What is the age coefficient for log(p3/p2)?","choices":["Minus 0.02, subtracting the A2 contrast from the A3 contrast.","Plus 0.01, using the A3 coefficient without the A2 equation.","Plus 0.03, using the A2 coefficient without the A3 equation.","Plus 0.04, adding the two reference contrast coefficients."],"correct_index":0,"explanation":"log(p3/p2) = log(p3/p1) minus log(p2/p1), so its age coefficient is 0.01 minus 0.03 = minus 0.02. Both original coefficients concern distinct contrasts. Their difference is appropriate when explicitly forming this new contrast.","set":1},{"id":"da-s6-q18","session":6,"topic":"Odds and log-odds","question":"An event probability is 0.2. What is its natural log odds, approximately?","choices":["Plus 1.386, since inverse odds are 4.","Minus 1.609, since probability is 0.2.","Minus 1.386, since odds are 0.25.","Plus 0.25, since odds are 0.25."],"correct_index":2,"explanation":"Odds = 0.2/0.8 = 0.25, so log odds = log(0.25), approximately minus 1.386. log(p), log inverse odds, and odds without taking their log are different quantities.","set":2},{"id":"da-s6-q19","session":6,"topic":"Odds ratio over several units","question":"The age coefficient in the awareness model is 0.2. For a five year increase with sex fixed, what is the fitted odds multiplier?","choices":["Approximately6.107, using5 times exp(0.2).","Approximately1.221, using exp(0.2) for just one year.","Approximately2.718, using exp(1) over five years.","Approximately1.041, using exp(0.2 divided by5)."],"correct_index":2,"explanation":"Five years add 5 times 0.2 = 1 to log odds, multiplying odds by exp(1). Multipliers compound rather than being multiplied by five as numbers. This is a 171.8% increase in odds, not necessarily the same probability increase.","set":2},{"id":"da-s6-q20","session":6,"topic":"Prediction","question":"The awareness model has log odds 1.5 + 0.2 age minus 0.8 female, with female coded 1. What is the fitted probability for a twenty year old woman?","choices":["Approximately 0.996, applying the logistic conversion to 5.5.","Approximately 0.991, applying the logistic conversion to 4.7.","Approximately 0.009, using the complementary probability from 4.7.","Approximately 0.998, applying the logistic conversion to 6.3."],"correct_index":1,"explanation":"Substitute age 20 and female 1: eta = 1.5 + 4 minus 0.8 = 4.7. Probability is exp(4.7)/(1 + exp(4.7)), approximately 0.991. Ignoring the dummy gives 5.5, reversing its sign gives 6.3, and the final distractor is the complement.","set":2},{"id":"da-s6-q21","session":6,"topic":"Z-test","question":"A logit coefficient is minus 0.8 with standard error 0.35. Critical absolute z values are 1.96 at 5% and 2.576 at 1%. Which two sided decision follows?","choices":["Reject at 1% but not at 5%, since the absolute z value is about 2.286.","Reject at 5% but not at 1%, since the absolute z value is about 2.286.","Reject at neither level, since the negative z value cannot exceed a positive threshold.","Reject at both 5% and 1%, since the absolute z value is about 2.286."],"correct_index":1,"explanation":"The absolute ratio 0.8/0.35 is approximately 2.286, between the two thresholds. A two sided test uses magnitude regardless of sign. The stricter 1% threshold makes rejection harder than the 5% threshold.","set":2},{"id":"da-s7-q16","session":7,"topic":"Partial chi-square test","question":"Nested logit models have reduced deviance 250 and complete deviance 238, with two added predictors. The 1% chi square critical value on 2 degrees of freedom is 9.21. What follows?","choices":["Do not reject at 1%, because the statistic 12 is below the critical value.","Reject the added group null at 1%, because the statistic 12 exceeds 9.21.","Reject the intercept null at 1%, because the statistic 12 exceeds 9.21.","Do not reject at 1%, because the statistic 6 is below 9.21."],"correct_index":1,"explanation":"The deviance reduction is 12, without division by the two added predictors. It exceeds 9.21, so the group is significant even at 1%. This partial comparison tests the added slopes, not the intercept.","set":1},{"id":"da-s7-q17","session":7,"topic":"AIC","question":"On the same sample, model A has deviance 200 with three predictors and model B has deviance 205 with one predictor. Both have an intercept. Which AIC comparison is correct?","choices":["B is preferred, with AIC 200 versus A's 205.","A is preferred, with AIC 206 versus B's 207.","A is preferred, with AIC 208 versus B's 209.","B is preferred, with AIC 206 versus A's 203."],"correct_index":2,"explanation":"For A, 200 + 2(3 + 1) = 208. For B, 205 + 2(1 + 1) = 209. A's fit gain slightly exceeds its larger penalty. Omitting the intercept or halving or discarding the penalty gives different, incorrect AIC values.","set":1},{"id":"da-s7-q18","session":7,"topic":"Prediction","question":"A predicted log odds value is minus 0.5. What is the event probability, approximately?","choices":["0.607, by treating exp(minus 0.5) directly as probability.","0.622, after converting exp(plus 0.5) through odds/(1 + odds).","Minus 0.5, by treating the linear predictor directly as probability.","0.378, after converting odds exp(minus 0.5) through odds/(1 + odds)."],"correct_index":3,"explanation":"The odds are approximately 0.60653, so p = 0.60653/1.60653 = 0.37754. Odds are not probability. Reversing the sign gives the complement, while a negative probability is invalid.","set":1},{"id":"da-s7-q19","session":7,"topic":"Global chi-square test","question":"Null deviance is 300 on 249 residual degrees of freedom. Complete model deviance is 280 on 246. The 5% chi square critical value on 3 degrees of freedom is 7.81. Which global test result is correct?","choices":["Statistic 20 on 246 degrees of freedom, so test against the complete model's residual degrees of freedom.","Statistic 20 on 3 degrees of freedom, so reject the joint zero slope null.","Statistic 6.67 on 3 degrees of freedom, so divide the deviance drop by added coefficients.","Statistic minus 20 on 3 degrees of freedom, so the complete model has reduced likelihood."],"correct_index":1,"explanation":"The statistic is 300 minus 280 = 20. Test degrees of freedom are the residual degrees of freedom difference, 249 minus 246 = 3, not 246. 20 exceeds 7.81, supporting global significance.","set":1},{"id":"da-s8-q15","session":8,"topic":"Multinomial prediction","question":"The brand equations are eta2 = 1.2 + 0.03 age minus 0.6 male and eta3 = 1.1 + 0.01 age + 0.4 male. For a forty year old man, which category has the highest fitted probability?","choices":["A2, because its age coefficient alone is larger than A3's age coefficient.","A1, because the reference category has fitted probability one by definition.","A3, whose predictor1.9 exceeds A2 at1.8 and the reference value0.","A2, because eta 2 = 2. 4 after ignoring the male coefficient."],"correct_index":2,"explanation":"At age 40 and male 1, eta2 = 1.8 and eta3 = 1.9. Normalized probabilities share a denominator, so the largest exponential has the largest probability. A3 is approximately 0.487, A2 0.440, and A1 0.073.","set":1},{"id":"da-s8-q16","session":8,"topic":"Contrast between two non-reference categories","question":"The male dummy coefficient is minus 0.6 for A2 versus A1 and plus 0.4 for A3 versus A1. At fixed age, how does the A3 versus A2 ratio change from women to men?","choices":["It is multiplied by exp(minus 0.2), because 0.4 plus (minus 0.6) equals minus 0.2.","It is multiplied by exp(1), because 0.4 minus (minus 0.6) equals 1.","It is multiplied by exp(minus 0.6), because only the A2 equation is needed.","It is multiplied by exp(0.4), because only the A3 equation is needed."],"correct_index":1,"explanation":"Subtract the two log reference ratios to obtain log(p3/p2). Its dummy coefficient is 0.4 minus (minus 0.6) = 1. Therefore moving from female 0 to male 1 multiplies that ratio by exp(1), about 2.718.","set":1},{"id":"da-s9-q1","session":9,"topic":"Time series definition","question":"Which data structure is a univariate time series rather than a cross sectional sample?","choices":["Several countries' GDP recorded once, sorted by country name.","One country's GDP recorded once, with several economic predictors.","One country's GDP recorded in successive years, retaining the chronological order.","Several countries' GDP recorded in one year, sorted from smallest to largest."],"correct_index":2,"explanation":"A univariate time series records one variable at successive times, generally equally spaced. Sorting units by magnitude or name does not create a time index. Several predictors for a single observation do not create a series either.","set":1},{"id":"da-s9-q2","session":9,"topic":"Objectives","question":"A time series analysis identifies long term growth, seasonal fluctuations and persistence after a shock. Which further aim is listed in the lecture?","choices":["Forecast future values of the series.","Prove that the time index causally changes the response.","Guarantee that every shock disappears immediately.","Discard chronological order before modelling the series."],"correct_index":0,"explanation":"Forecasting is one of the stated objectives, alongside evolution and persistence. Analysing an ordered series does not by itself identify causal effects, and shock persistence need not be zero. Discarding order removes essential information.","set":1},{"id":"da-s9-q3","session":9,"topic":"Backshift operator","question":"The backshift operator satisfies B y_t = y at t minus 1. What is B squared y_t?","choices":["y at t minus 2, applying the same shift twice.","y_t minus y at t minus 2, taking a two period difference.","y at t plus 2, advancing the index twice.","y_t squared, squaring the current observed value."],"correct_index":0,"explanation":"Repeated backshift moves the time index backward two periods. The operator power is not a power of the response, and a difference requires subtracting a past value from the current value.","set":1},{"id":"da-s9-q4","session":9,"topic":"R lag trap","question":"Using the lecture's convention for stats lag on a time series, which call corresponds to the backshift B?","choices":["stats::lag(y, 1), corresponding to the past value at t minus 1.","stats::diff(y, 1), corresponding to the past value alone at t minus 1.","stats::lag(y, minus 1), corresponding to the past value at t minus 1.","stats::lag(y, 0), corresponding to the past value at t minus 1."],"correct_index":2,"explanation":"The lecture warns that its base R lag convention has the opposite sign from backshift: negative lag gives B, while positive lag corresponds to the forward value under its time index notation. diff computes a change rather than a past value, and lag zero leaves the series unshifted.","set":1},{"id":"da-s9-q5","session":9,"topic":"Centered moving average, even order","question":"For the series 2, 6, 4, 5, 9, 7, 11, what is the first feasible centred moving average of order four?","choices":["5.2, using equal weights over the first five values.","5.125, using endpoint weights 1/8 and interior weights 1/4 over five values.","4.25, using equal weights over the first four values without centring.","10.25, using the centred weighted numerator but dividing it by four."],"correct_index":1,"explanation":"The first centred value is (2 + 2 times 6 + 2 times 4 + 2 times 5 + 9)/8 = 41/8 = 5.125. For even order four, centring requires five values with half weights at the endpoints, positioned at the third observation.","set":1},{"id":"da-s9-q6","session":9,"topic":"Moving average properties","question":"Quarterly data have regular four quarter seasonality. Why does the decomposition begin with a centred moving average of order four?","choices":["It isolates each quarter's seasonality while retaining all irregular fluctuations.","It guarantees that the resulting trend is a stationary white noise process.","It estimates the seasonal indices directly and forces their average to zero.","It averages across the seasonal cycle and smooths irregular fluctuations to estimate trend."],"correct_index":3,"explanation":"A moving average of order equal to seasonal period reduces or removes regular seasonal oscillations while smoothing noise. It yields a trend estimate, not the normalized seasonal indices or a guarantee of stationarity or white noise.","set":1},{"id":"da-s9-q7","session":9,"topic":"Multiplicative vs additive","question":"A multiplicative seasonal index is 1.114 for the third quarter. How is this interpreted under the lecture normalization?","choices":["An additive increase of 1.114 response units above zero.","About 114% above the neutral seasonal level of one.","About 11.4% below the neutral seasonal level of one.","About 11.4% above the neutral seasonal level of one."],"correct_index":3,"explanation":"Multiplicative indices are normalized around 1. Subtract 1 from 1.114 to obtain a proportional seasonal uplift of 0.114, or 11.4%. Additive indices use a different scale centred on zero.","set":1},{"id":"da-s9-q8","session":9,"topic":"Decomposition steps","question":"In multiplicative decomposition, ratios y_t/M_t estimate seasonality times irregularity. How does step three obtain seasonal indices?","choices":["Average ratios within each year across seasons, then subtract their overall mean.","Average ratios for each matching season across years, then divide each average by their overall mean.","Divide every ratio by the moving average again, then normalize the result to zero.","Use every individual ratio as a separate seasonal index without averaging or normalization."],"correct_index":1,"explanation":"Averaging repeated occurrences of the same quarter or month reduces irregularity. Renormalizing by the mean makes seasonal indices average 1. Averaging across different seasons removes the pattern of interest, and additive normalization or skipping the steps changes the procedure.","set":1},{"id":"da-s10-q1","session":10,"topic":"Stochastic process view","question":"What distinguishes the observed values y1,...,yT from the stochastic process Yt in the lecture's probabilistic view?","choices":["The observed series contains all possible realizations of every time indexed random variable.","The observed series is one finite realization of the time indexed random variables.","The observed series is the deterministic mean function of every time indexed random variable.","The observed series consists only of the independent errors of every time indexed random variable."],"correct_index":1,"explanation":"Yt denotes a random variable at time t, while yt is its realized value in the observed series. A finite sequence of observations is not every outcome, necessarily the mean, or necessarily an independent error sequence.","set":1},{"id":"da-s10-q2","session":10,"topic":"Weak stationarity","question":"A process has constant finite mean and positive constant variance, but its lag two correlation changes with calendar time. Is it weakly stationary?","choices":["No, since lag specific correlations must also be independent of calendar time.","Yes, since constant mean and variance alone are sufficient.","Yes, since changing lag correlations are permitted when they are below one.","No, since weak stationarity requires every lag correlation to equal zero."],"correct_index":0,"explanation":"Weak stationarity requires mean and variance constant and autocorrelation depending only on lag, not on t. Correlations need not vanish, but a fixed lag cannot change with calendar time. Being below one does not remove this requirement.","set":1},{"id":"da-s10-q3","session":10,"topic":"ACF vs PACF","question":"What additional adjustment distinguishes lag two partial autocorrelation from lag two autocorrelation?","choices":["It removes the linear contribution of the intermediate value at lag one.","It removes the squared contribution of the current value at lag zero.","It removes the calendar time labels while keeping observations unordered.","It removes all variance from the value at lag two before correlation."],"correct_index":0,"explanation":"PACF measures lagged association after controlling linear effects of intermediate variables. At lag two the intermediate value is Y at t minus 1. It is not a transformation that removes all variance or chronological order.","set":1},{"id":"da-s10-q4","session":10,"topic":"White noise","question":"Which property is inconsistent with the lecture's definition of white noise?","choices":["A constant finite variance across calendar time.","Zero autocorrelation at every nonzero lag.","A mean that increases with calendar time.","Autocorrelation equal to one at lag zero."],"correct_index":2,"explanation":"White noise has zero mean, constant variance, and no nonzero lag autocorrelation. Lag zero correlation is one for a positive variance process. Joint normality is an additional Gaussian white noise assumption, not needed for this definition.","set":1},{"id":"da-s10-q5","session":10,"topic":"Random walk definition","question":"A process satisfies Yt = Y at t minus 1 + epsilon_t, where epsilon is white noise. Which statement describes this random walk?","choices":["It damps each past shock by a factor less than one in every following period.","It equals only the current shock, so past shocks disappear immediately.","It averages recent shocks, with earlier shocks removed after a fixed number of periods.","It accumulates shocks, with each shock retained in all later levels."],"correct_index":3,"explanation":"Iterating the random walk adds all past innovations with unit weight. This yields permanent shock effects in the level. A current shock alone is white noise, finite shock memory is a moving average feature, and geometric damping belongs to a different recursion.","set":1},{"id":"da-s10-q6","session":10,"topic":"Random walk properties","question":"A random walk begins at Y0 = 0 and has uncorrelated innovations of variance 4. What is Var(Y10)?","choices":["4, using only one innovation variance.","0.4, dividing one innovation variance by the number of periods.","40, summing variances across ten uncorrelated accumulated innovations.","400, squaring the number of accumulated periods."],"correct_index":2,"explanation":"Y10 is the sum of ten uncorrelated innovations, so variance is 10 times 4 = 40. Variances add under uncorrelated shocks. They are not constant at 4, multiplied by 10 squared, or divided by 10.","set":1},{"id":"da-s10-q7","session":10,"topic":"Random walk autocorrelation","question":"A zero drift random walk has constant mean zero but variance t sigma squared. What does this establish about weak stationarity?","choices":["It is stationary because its mean is constant across calendar time.","It is stationary because successive values are strongly correlated.","It is not stationary because every realization must have a deterministic trend.","It is not stationary because its variance depends on calendar time."],"correct_index":3,"explanation":"A constant mean is only one stationarity condition. Growing variance violates another, so the process is not weakly stationary. Strong serial correlation alone does not decide stationarity, and sample wandering does not require a deterministic trend.","set":1},{"id":"da-s10-q8","session":10,"topic":"Random walk with drift","question":"A random walk with drift has Y0 = 0, drift c = 2 and innovation variance 4. What are its mean and variance at time 10?","choices":["Mean 20 and variance 400.","Mean 20 and variance 40.","Mean 2 and variance 4.","Mean 0 and variance 40."],"correct_index":1,"explanation":"The drift accumulates to t times c = 20. Innovation variances accumulate to t times sigma squared = 40. Adding deterministic drift changes the mean but not innovation variance. The zero mean would describe the same initialization without drift.","set":1},{"id":"da-s11-q1","session":11,"topic":"AR(1) stationarity","question":"Consider the lecture's causal AR(1) model with white noise innovations. Which autoregressive coefficient permits a stationary solution?","choices":["Minus 1, which is on the stationarity boundary.","Minus 0.8, whose absolute value is below one.","Plus 1.2, whose absolute value exceeds one.","Plus 1, which gives a unit root recursion."],"correct_index":1,"explanation":"For the lecture's causal AR(1), stationarity requires absolute phi below 1. Negative coefficients are allowed. A value of 1 gives a random walk, and either boundary or an explosive magnitude does not satisfy this condition.","set":1},{"id":"da-s11-q2","session":11,"topic":"AR(1) moments","question":"A stationary AR(1) has phi = minus 0.5. What are its autocorrelations at lags one, two and three?","choices":["Minus 0.5, minus 0.25 and minus 0.125.","Plus 0.5, plus 0.25 and plus 0.125.","Minus 0.5, zero and zero.","Minus 0.5, plus 0.25 and minus 0.125."],"correct_index":3,"explanation":"The autocorrelation is phi to the lag power. A negative phi alternates signs and decays in absolute value: minus 0.5, 0.25, minus 0.125. The ACF does not cut off after one, unlike the PACF of this model.","set":1},{"id":"da-s11-q3","session":11,"topic":"ACF/PACF signature of AR","question":"After stationarity is established, estimated ACF values decay while PACF has material spikes through lag two and little thereafter. Which simple model signature is suggested?","choices":["White noise, since any declining ACF indicates zero serial dependence.","A random walk, since every declining ACF indicates a unit root.","AR(2), since its PACF cuts off after order two.","MA(2), since its PACF cuts off after order two."],"correct_index":2,"explanation":"A pure AR(p) typically has a decaying ACF and PACF cutoff at p. A pure MA(q) has the reverse signature. Estimated plots suggest candidates rather than prove a unique specification, so residual checks and comparisons remain necessary.","set":1},{"id":"da-s11-q4","session":11,"topic":"MA(q) properties","question":"Yt = epsilon_t + 5 epsilon at t minus 1, with white noise innovations of variance sigma squared. What are its stationarity and variance properties?","choices":["Nonstationary because the coefficient magnitude exceeds one.","Stationary with variance 6 sigma squared.","Nonstationary with variance t sigma squared.","Stationary with variance 26 sigma squared."],"correct_index":3,"explanation":"Finite MA models are stationary for any finite coefficients. Uncorrelated innovation variances add with squared weights: (1 + 25) sigma squared. The AR(1) magnitude condition does not govern MA stationarity, and its variance does not accumulate with t.","set":1},{"id":"da-s11-q5","session":11,"topic":"MA(1) autocorrelation","question":"For MA(1), lag one correlation equals theta/(1 + theta squared). Which comparison between theta = 1 and theta = 5 is correct?","choices":["The correlations are 0.5 and 0.833, so correlation increases directly with coefficient magnitude.","The correlations are 0.5 and approximately 0.192, so a larger coefficient need not mean larger correlation.","The correlations are 0.5 and zero, because theta = 5 makes the model nonstationary.","The correlations are 1 and 5, so correlation increases directly with the coefficient."],"correct_index":1,"explanation":"At theta = 1, the ratio is 1/2 = 0.5, its maximum. At theta = 5, it is 5/26 = 0.1923. MA stationarity is preserved, even though variance is higher and lag one correlation lower.","set":1},{"id":"da-s11-q6","session":11,"topic":"ARIMA special cases","question":"An ARIMA(0,1,0) without drift has white noise first differences. What are its level dynamics?","choices":["The current level equals the preceding level plus a new innovation.","The current level equals only the new innovation, with no accumulated past shocks.","The current level equals a weighted average of the preceding two innovations.","The current level equals a stationary AR(1) with a coefficient below one."],"correct_index":0,"explanation":"First differencing gives Yt minus Y at t minus 1 = epsilon_t, so the level is a random walk. White noise describes the differences, not the level. No MA term or subunit AR coefficient is introduced by this order selection.","set":1},{"id":"da-s11-q7","session":11,"topic":"Model selection","question":"A stationary candidate series has a decaying ACF and a final material PACF spike at lag three. How should this guide ARIMA selection?","choices":["Set the differencing order d = 3, since PACF controls differencing directly.","Set the moving average order q = 3, since a PACF cutoff identifies pure MA order.","Consider an autoregressive order p = 3, then estimate and check residuals.","Accept an AR(3) immediately, since its estimated PACF guarantees white noise residuals."],"correct_index":2,"explanation":"The PACF cutoff suggests the autoregressive order. Differencing concerns stationarity, and an ACF cutoff instead suggests pure MA order. These are general identification clues, not guarantees, especially for mixed models.","set":1},{"id":"da-s11-q8","session":11,"topic":"ADF and Ljung-Box","question":"ADF rejects its unit root null at 5%, but a Ljung Box test rejects zero residual autocorrelations through lag ten. What assessment is justified?","choices":["There is evidence against a unit root, but remaining serial correlation still challenges the fitted model.","There is evidence of white noise, because rejecting ADF automatically establishes zero autocorrelations.","There is evidence of a unit root, because rejecting ADF supports its null hypothesis.","There is no remaining serial correlation, because rejecting Ljung Box establishes its null hypothesis."],"correct_index":0,"explanation":"The ADF null concerns a unit root, whereas Ljung Box tests zero autocorrelations through a chosen lag. Evidence against the former does not establish white noise. Rejecting the latter indicates residual correlation, so diagnostics remain important.","set":1},{"id":"da-s12-q1","session":12,"topic":"Basic methods","question":"The last observed series value is 120 and the sample mean is 100. What is the naive forecast three periods ahead?","choices":["140, extending the gap between the last observation and sample mean.","100, using the average of the observed sample.","120, using the last observation at every future horizon.","360, multiplying the last observation by the horizon."],"correct_index":2,"explanation":"The naive method sets every future forecast to the last observed value. It neither averages the sample nor extends a trend. A sample mean forecast is a separate method, and no drift is specified here.","set":1},{"id":"da-s12-q2","session":12,"topic":"SES weights","question":"In SES, the level update is alpha times yt plus (1 minus alpha) times the prior level. What does alpha = 1 imply?","choices":["The updated level is yt plus the prior level and future forecasts accumulate both.","The updated level is the sample average and all observations have equal weight.","The updated level is the prior level and new observations have no effect.","The updated level is yt and future forecasts equal the latest observation."],"correct_index":3,"explanation":"Setting alpha to one removes the prior level term, giving lt = yt. SES forecasts are then the naive forecasts. Zero weight on new observations instead corresponds to the other boundary, and summing levels is not a convex update.","set":1},{"id":"da-s12-q3","session":12,"topic":"SES applicability","question":"Why is simple exponential smoothing poorly matched to a series with sustained trend and regular seasonality?","choices":["Its forecasts at all future horizons require the response to be binary.","Its forecasts at all future horizons reproduce fitted seasonal indices.","Its forecasts at all future horizons equal the last estimated level.","Its forecasts at all future horizons extrapolate a fitted linear trend."],"correct_index":2,"explanation":"SES has a level but no explicit trend or seasonal equation, yielding flat forecasts. Holt adds trend, and Holt Winters adds seasonality as well. The limitation has nothing to do with a binary response.","set":1},{"id":"da-s12-q4","session":12,"topic":"Holt equations","question":"Holt's latest estimated level is 100 and latest trend is 2 per period. What is its forecast three periods ahead?","choices":["6, using three times trend without the level.","300, multiplying level by the horizon.","102, using level plus trend only once.","106, using level plus three times trend."],"correct_index":3,"explanation":"Holt forecasts lt + h bt. Substitute 100 + 3 times 2 = 106. The horizon scales the trend, not the level, and the forecast includes both components.","set":1},{"id":"da-s12-q5","session":12,"topic":"Parameter selection","question":"Two smoothing parameter settings give forecast errors (1, 1, 1) and (0, 0, 2) on the same three observed periods. Which has the smaller MSE?","choices":["The second, because two exact forecasts outweigh the final squared error.","The first, with MSE 1 versus 4/3 for the second.","The second, with MSE 2/3 versus 1 for the first.","They tie, because the total errors have the same sign."],"correct_index":1,"explanation":"MSE averages squared errors. The first sum is 3 and the second is 4, so their MSE values are 1 and 4/3. Using absolute errors gives a different criterion, and error sign does not determine a squared error comparison.","set":1},{"id":"da-s12-q6","session":12,"topic":"R HoltWinters","question":"A series has trend and seasonality whose amplitude grows with its level. What does HoltWinters(series, seasonal = \"mult\") request in the lecture?","choices":["Level only forecasts, because multiplicative removes both trend and seasonality.","Trend and multiplicative seasonality, with smoothing parameters estimated by the error criterion.","An ARIMA likelihood fit, because all forecasting functions estimate autoregressive orders.","Trend and additive seasonality, because additive is the function's only permitted variant."],"correct_index":1,"explanation":"The explicit mult option selects the multiplicative seasonal variant. Holt Winters includes level, trend and seasonality and estimates its smoothing parameters. Additive is the default, not the only option. This is not automatic ARIMA order selection.","set":1},{"id":"da-s12-q7","session":12,"topic":"ARMA forecasting rules","question":"In the lecture's ARMA forecast, the current observed residual is 0.2. Which treatment of innovations is correct when forecasting future values?","choices":["Use 0.2 where the current observed residual enters, and zero for future unobserved innovations.","Use zero for both the current observed residual and all future unobserved innovations.","Use 0.2 for the current residual and for every future unobserved innovation.","Use a randomly chosen future innovation for each point forecast to reproduce uncertainty."],"correct_index":0,"explanation":"Observed innovations are approximated by residuals. Future innovations have forecast expectation zero, so point forecasts use zero for them. This does not assert future realized errors will be zero. Their uncertainty belongs in prediction intervals, not arbitrary draws in the point forecast.","set":1},{"id":"da-s12-q8","session":12,"topic":"ARIMA forecasting","question":"An ARIMA first difference forecast is 0.5072 and the last observed level is 16.9146. What is the next level forecast?","choices":["17.4218, adding the forecast change to the last level.","16.4074, subtracting the forecast change from the last level.","8.5791, multiplying the forecast change by the last level.","0.5072, reporting the change without returning to the level."],"correct_index":0,"explanation":"First differences are next level minus current level. Reverse differencing by adding the forecast difference: 16.9146 + 0.5072 = 17.4218. Reporting only the difference is the wrong scale, and subtraction or multiplication does not invert this transformation.","set":1}],"cr":[{"id":"cr-s1-q1","session":1,"topic":"Agency problem","question":"Shareholders want managers to choose investments that create value. Which decision most clearly creates an agency conflict?","choices":["Buying a prestige acquisition for personal status despite destroying shareholder value","Buying a risky acquisition with a supported positive expected value","Keeping a temporarily loss-making division with a credible value-creating turnaround plan","Rejecting an acquisition whose price exceeds its expected benefits"],"correct_index":0,"explanation":"An agency conflict arises when managers pursue private benefits at owners' expense. The prestige acquisition deliberately sacrifices shareholder value for status. Risk or temporary accounting losses alone do not establish such a conflict.","set":1},{"id":"cr-s1-q2","session":1,"topic":"Information asymmetry","question":"Managers and outside shareholders read the same published financial statements. Why may managers still know more about the company?","choices":["Audited financial statements eliminate any information gap between insiders and outside investors","Managers also have direct access to daily operations and internal forecasts","Public filings contain the same forward-looking detail as internal budgets","Managers' only information advantage is private access to the company's auditors"],"correct_index":1,"explanation":"Financial reporting reduces the information gap but does not close it. Managers run the business day to day and see internal forecasts and operational data that never enter the published statements, so an asymmetry remains. An audit verifies the statements rather than equalising information, filings are periodic summaries rather than internal budgets, and contact with auditors is not the source of managers' operational knowledge.","set":1},{"id":"cr-s1-q3","session":1,"topic":"Motives for regulation","question":"A regulation requires disclosures to protect inexperienced savers from exploitation. Which rationale focuses on that protection rather than only on market efficiency?","choices":["Correcting market imperfections solely to increase total efficiency","Lowering companies' cost of capital through comparable statements","Protecting less sophisticated investors and the distribution of wealth","Ensuring all market participants receive the same information at the same time"],"correct_index":2,"explanation":"Regulation can be justified on efficiency grounds (comparability, lower capital costs, equal access to information) or on protection grounds, which care about who is exposed to exploitation and how outcomes are distributed. Requiring disclosures to shield inexperienced savers is the protection rationale. The other three options are efficiency arguments, even the equal-information one.","set":1},{"id":"cr-s1-q4","session":1,"topic":"Sources of regulation","question":"Which is not one of the main sources of a company's financial reporting regulatory framework?","choices":["Stock-exchange financial disclosure rules","Accounting standards","National tax legislation on deductible expenses","Company law on annual accounts"],"correct_index":2,"explanation":"The regulatory framework for financial reporting has three main sources: legislation such as company law, accounting standards, and stock exchange regulations. Tax legislation governs the tax charge, not the content of financial statements, even though tax and reporting rules sometimes interact. This is the framework distinction drawn in the course and in the textbook's first chapter.","set":1},{"id":"cr-s1-q5","session":1,"topic":"GAAP vs IFRS","question":"A company states that it prepares accounts under Italian GAAP. What does GAAP refer to in this context?","choices":["The tax accounting rules applicable in that country","The IFRS Accounting Standards issued by the IASB","The company's internal management reporting conventions","The accounting rules and principles accepted in that jurisdiction"],"correct_index":3,"explanation":"GAAP refers to generally accepted accounting practice or principles in a jurisdiction. It includes the relevant accounting rules and conventions, rather than only tax schedules or a company's internal procedures.","set":1},{"id":"cr-s1-q6","session":1,"topic":"IFRS Foundation vs IASB","question":"What is the IFRS Foundation's role in relation to the IASB?","choices":["Its Trustees appoint IASB members and oversee funding and governance.","The IASB appoints the Foundation's Trustees as its staff.","The Foundation replaces the Interpretations Committee in deciding every application issue.","The Monitoring Board writes Standards while the Foundation enforces them against issuers."],"correct_index":0,"explanation":"The IASB is the independent accounting standard-setting board within the IFRS Foundation structure. The Foundation's Trustees oversee governance and funding and appoint board members. Issuer enforcement is not the Foundation's role.","set":1},{"id":"cr-s1-q7","session":1,"topic":"IASB composition","question":"Which description best distinguishes the IASB from a national enforcement body?","choices":["It investigates every listed company's financial statements.","It is solely an interpretations committee.","It develops and amends IFRS Accounting Standards.","It is a national securities regulator approving individual filings."],"correct_index":2,"explanation":"The IASB is an independent standard setter. Enforcement bodies and securities regulators assess compliance in their jurisdictions. Developing a rule and investigating a particular issuer's compliance are different functions.","set":1},{"id":"cr-s1-q8","session":1,"topic":"IFRIC vs Advisory Council","question":"Which body addresses application questions and interpretations of IFRS Accounting Standards rather than providing broad strategic advice?","choices":["The IFRS Advisory Council","The IFRS Interpretations Committee","The Monitoring Board","The IFRS Foundation Trustees"],"correct_index":1,"explanation":"Application questions and interpretations of the Standards are handled by the IFRS Interpretations Committee, which issues IFRIC Interpretations. The Advisory Council gives broad strategic advice to the IASB, the Monitoring Board oversees the Trustees, and the Trustees handle governance and funding. None of those three writes interpretations.","set":1},{"id":"cr-s1-q9","session":1,"topic":"IASB due process","question":"Which sequence best describes the development of an IFRS Accounting Standard when a discussion paper is used?","choices":["Exposure draft and comments, discussion paper, then final standard","Final standard issued first, comments and exposure draft after","Discussion paper and comments, exposure draft and comments, then final standard","Discussion paper, final standard, then exposure draft and comments"],"correct_index":2,"explanation":"A discussion paper can explore an issue and invite views before the more developed exposure draft. Comments are considered before final issuance. A final Standard is not issued before the exposure-draft consultation stage.","set":1},{"id":"cr-s1-q10","session":1,"topic":"EU endorsement","question":"An IASB Standard has been issued but has not completed the European Union endorsement process. Can international issuance alone make it part of EU-endorsed IFRS?","choices":["Yes, IFRS apply directly in the EU once the IASB issues them","Yes, if EFRAG has published technical advice supporting the text","Yes, individual member states can endorse it for their own markets","No, the separate EU endorsement process must be completed"],"correct_index":3,"explanation":"Within the EU an IASB Standard becomes part of EU-endorsed IFRS only after the EU's own endorsement process. EFRAG's advice feeds that process but cannot complete it, and member states cannot endorse standards individually for the single market. IASB issuance alone creates no EU legal effect.","set":1},{"id":"cr-s1-q11","session":1,"topic":"Global adoption","question":"A group listed on an EU exchange prepares its consolidated accounts, and a domestic US issuer files its statements with the SEC. Which comparison correctly states the frameworks that apply?","choices":["US domestic issuers file under IFRS endorsed by the SEC, as EU groups do under EU-endorsed IFRS","EU listed groups use EU-endorsed IFRS for consolidated accounts, while US domestic issuers generally report under US GAAP","Both jurisdictions apply the same endorsement process before IFRS can be used","EU listed groups may choose between EU-endorsed IFRS and US GAAP for their consolidated accounts"],"correct_index":1,"explanation":"In the EU, listed groups prepare consolidated accounts under EU-endorsed IFRS. The United States permits foreign private issuers to file IFRS statements but has not adopted IFRS for domestic issuers, who report under US GAAP. There is no SEC endorsement of IFRS for domestic filers, no shared endorsement process, and no US GAAP option for EU listed groups.","set":1},{"id":"cr-s1-q12","session":1,"topic":"Principles vs rules","question":"A Standard states a broad accounting principle and also provides detailed application guidance. How should these be used together?","choices":["Apply the principle with its relevant supporting requirements and guidance","Apply the principle only where the Standard gives no example","Treat the application guidance as optional background material","Follow the closest example even when it conflicts with the principle"],"correct_index":0,"explanation":"A Standard's principles and its mandatory application requirements and guidance form a single package and are applied together. Guidance is not optional background, examples do not override the principle they illustrate, and the principle applies across the whole Standard rather than only where no example exists.","set":1},{"id":"cr-s1-q13","session":1,"topic":"IFRS1","question":"A company is preparing its first IFRS financial statements after previously using national GAAP. Which task is within IFRS 1?","choices":["Setting requirements for the first public issue of shares","Applying transition requirements and reconciling previous GAAP to IFRS","Accounting for the first subsidiary acquisition","Adopting each IFRS Standard from its own original effective date"],"correct_index":1,"explanation":"IFRS 1 governs the transition from previous GAAP to IFRS, including opening-statement adjustments and reconciliations. A first share issue is a listing matter, a first subsidiary acquisition is business-combination accounting under IFRS 3, and IFRS 1 grants transition-specific reliefs rather than forcing adoption of every Standard back to its original effective date.","set":1},{"id":"cr-s1-q14","session":1,"topic":"Why enforcement conditions the benefit of adoption","question":"Two countries adopt IFRS mandatorily in the same year. In country A, regulators actively sanction misreporting; in country B, enforcement is weak and compliance is largely nominal. Based on the course's discussion of Florou and Pope (2012), which outcome is the more likely contrast?","choices":["Institutional investors raise their holdings equally in both, because the standards adopted are identical on paper","Institutional investors favour country B, because weaker enforcement leaves managers more reporting flexibility","Institutional ownership falls in both countries, because mandatory adoption raises compliance costs","Institutional investors raise their holdings more in country A, because enforcement makes the adopted standards credible"],"correct_index":3,"explanation":"The course's discussion of Florou and Pope (2012) links the gains from mandatory IFRS adoption to enforcement: strong enforcement makes the reported numbers credible, which attracts institutional investment. Identical nominal standards without enforcement do not deliver the same comparability, and reporting flexibility is not what institutional investors reward.","set":1},{"id":"cr-s1-q15","session":1,"topic":"Stewardship","question":"An investor uses financial reports to assess how well management has used the company's resources. How does this stewardship assessment fit the Conceptual Framework's objective?","choices":["It is a separate objective unrelated to resource decisions","It informs decisions about providing resources to the entity","It falls outside general purpose financial reporting entirely","It is relevant only to the statement of cash flows"],"correct_index":1,"explanation":"Assessing management's stewardship helps investors and other capital providers make resource-allocation decisions. It is part of the information useful for those decisions, not an objective unrelated to them.","set":1},{"id":"cr-s2-q1","session":2,"topic":"Status of the Conceptual Framework","question":"A specific IFRS Accounting Standard requires a measurement that management believes conflicts with a Conceptual Framework principle. Which requirement takes priority?","choices":["Use the higher asset value as a matter of prudence.","Use the Framework instead of the Standard.","Use neither until an interpretation is issued.","Use the applicable Standard."],"correct_index":3,"explanation":"The Framework is not an Accounting Standard and does not override one. Its concepts assist policy development and interpretation, but they do not authorise a departure from a specific requirement.","set":1},{"id":"cr-s2-q2","session":2,"topic":"Purposes of the Conceptual Framework","question":"Which activity is outside the purposes of the IASB Conceptual Framework?","choices":["Helping preparers develop policies when no Standard applies","Overriding an explicit requirement of an existing Standard","Helping the IASB develop consistent Standards","Helping users interpret information in the statements"],"correct_index":1,"explanation":"The Conceptual Framework guides judgement where no Standard applies or where a Standard leaves a question open. It assists the IASB in developing Standards, preparers in developing policies in the absence of a Standard, and users and auditors in understanding them. But where a Standard states an explicit requirement, that requirement prevails: invoking the Framework to depart from it is not one of the Framework's purposes.","set":1},{"id":"cr-s2-q3","session":2,"topic":"Sole objective","question":"A lender uses a company's financial reports to decide whether to provide a loan. Which objective of general purpose financial reporting covers that decision?","choices":["Calculating the company's legally distributable profit","Determining the corporate tax rate applicable to the company","Providing useful information for decisions about providing resources","Guaranteeing the return that management has promised investors"],"correct_index":2,"explanation":"The primary users are existing and potential investors, lenders and other creditors. Financial reporting provides information useful in deciding whether to provide resources. It does not guarantee returns or replace legal and tax calculations.","set":1},{"id":"cr-s2-q4","session":2,"topic":"Fundamental characteristics","question":"According to the Conceptual Framework, which two qualitative characteristics are fundamental to useful financial information?","choices":["Comparability and verifiability","Timeliness and understandability","Relevance and faithful representation","Relevance and prudence"],"correct_index":2,"explanation":"Information must be relevant to decisions and faithfully represent the economic phenomenon. Comparability, verifiability, timeliness and understandability enhance information that meets these fundamental requirements.","set":1},{"id":"cr-s2-q5","session":2,"topic":"Predictive vs confirmatory value","question":"A company reports actual margins that allow an analyst to check an earlier sales forecast. Which aspect of relevance does that comparison illustrate?","choices":["Confirmatory value","Absence of relevance because the forecast already existed","Predictive value only","Direct verifiability of future outcomes"],"correct_index":0,"explanation":"Confirmatory value helps users confirm or change previous evaluations. Actual results remain informative even when they match earlier expectations. The same information may also help later forecasts.","set":1},{"id":"cr-s2-q6","session":2,"topic":"Faithful representation components","question":"Which combination describes the components of faithful representation?","choices":["Complete, deliberately conservative and perfectly accurate","Complete, neutral and free from material error","Neutral, timely and exact to the last cent","Complete, consistently understated and externally audited"],"correct_index":1,"explanation":"A faithful depiction is complete, neutral and free from error in its description and process. That does not mean every uncertain estimate must predict its final settlement perfectly. Deliberate conservative bias is not neutrality.","set":1},{"id":"cr-s2-q7","session":2,"topic":"Prudence","question":"What does prudence mean in the Conceptual Framework?","choices":["Deliberately overstating liabilities whenever outcomes are uncertain","Consistently understating assets to create hidden reserves","Avoiding estimates whenever the outcome is uncertain","Exercising caution when making judgements under uncertainty"],"correct_index":3,"explanation":"Prudence supports neutral judgement when outcomes are uncertain. It does not authorise deliberate overstatement of liabilities or understatement of assets to create hidden reserves.","set":1},{"id":"cr-s2-q8","session":2,"topic":"Enhancing characteristics","question":"Which set contains all four enhancing qualitative characteristics?","choices":["Relevance, comparability, timeliness and prudence","Comparability, verifiability, timeliness and understandability","Faithful representation, verifiability, materiality and understandability","Comparability, relevance, consistency and neutrality"],"correct_index":1,"explanation":"The enhancing characteristics are comparability, verifiability, timeliness and understandability. Relevance and faithful representation are fundamental. Materiality, consistency and prudence have related but different roles.","set":1},{"id":"cr-s2-q9","session":2,"topic":"Elements of financial statements","question":"Which definition describes a liability in the Conceptual Framework?","choices":["A present economic resource controlled because of past events","A present obligation to transfer an economic resource because of past events","Any possible future payment, whether or not an obligation exists","The residual interest after deducting liabilities from assets"],"correct_index":1,"explanation":"A liability is a present obligation arising from past events to transfer an economic resource. It need not be certain in amount. A resource under control is an asset, and the residual interest is equity.","set":1},{"id":"cr-s2-q10","session":2,"topic":"Asset definition","question":"Which situation gives a company an asset under the Conceptual Framework?","choices":["It expects to pay an adverse court settlement.","It plans to buy a machine once finance is obtained.","It hopes employees will remain despite having no control over their services.","It has bought and controls a production machine."],"correct_index":3,"explanation":"The purchased machine is a present economic resource controlled as a result of a past event. A future purchase plan is not yet that resource. Expected payments are not assets, and uncontrolled future employee services do not satisfy control on the stated facts.","set":1},{"id":"cr-s2-q11","session":2,"topic":"Underlying assumptions","question":"A company expects to continue operating and records the effects of transactions when they occur rather than only when cash is paid or received. Which concepts does this describe?","choices":["Materiality and the cost constraint","Historical cost and current value","Going concern and accrual accounting","Relevance and verifiability"],"correct_index":2,"explanation":"Going concern concerns continuing operations without intended or necessary liquidation. Accrual accounting recognises economic effects in the periods in which they occur, even if cash moves in a different period.","set":1},{"id":"cr-s2-q12","session":2,"topic":"Recognition criteria","question":"A right meets the definition of an asset. What further consideration supports recognising it under the Conceptual Framework?","choices":["Its measurement must be possible without using any estimates at all","Its future economic benefits must be certain in every possible outcome","The company must legally own the physical item underlying the right","It gives relevant and faithfully represented information, subject to cost"],"correct_index":3,"explanation":"Definition and recognition are separate assessments. Recognition should make the financial statements useful, taking account of uncertainty and the cost constraint. Neither perfect certainty nor legal ownership is a universal condition.","set":1},{"id":"cr-s2-q13","session":2,"topic":"Measurement bases","question":"Does the Conceptual Framework require every item in a set of financial statements to use the same measurement basis?","choices":["No, historical cost and appropriate current-value bases may be combined.","Yes, value in use must be used for every liability.","Yes, the basis giving the highest equity must be used throughout.","Yes, current values may only appear in notes."],"correct_index":0,"explanation":"Different items can use different measurement bases when the resulting information is useful and applicable Standards are followed. Value in use relates to assets and fulfilment value to liabilities. Maximising equity is not a selection criterion.","set":1},{"id":"cr-s2-q14","session":2,"topic":"Full disclosure constraints","question":"Why does the Conceptual Framework not require unlimited disclosure of every possible detail?","choices":["Materiality and the cost constraint limit information requirements","Faithful representation prohibits disclosing uncertain estimates","Neutrality prevents disclosing information that could influence decisions","Verifiability limits disclosure to amounts confirmed by auditors"],"correct_index":0,"explanation":"Useful information is bounded by materiality (omitting immaterial detail cannot influence decisions) and by the cost constraint (benefits must justify the cost of providing information). Faithful representation requires estimates to be shown honestly rather than suppressed, neutrality does not mean withholding decision-useful information, and verifiability is not restricted to audited amounts.","set":1},{"id":"cr-s2-q15","session":2,"topic":"Fundamental vs enhancing mix-up","question":"A student calls comparability a fundamental qualitative characteristic. Which correction is accurate?","choices":["Comparability enhances information that is relevant and faithfully represented.","Comparability is fundamental only in consolidated accounts.","Comparability replaces faithful representation when peer information exists.","Comparability is an underlying assumption like going concern."],"correct_index":0,"explanation":"Relevance and faithful representation are fundamental. Comparability is enhancing because it helps users identify similarities and differences in information that is already useful.","set":1},{"id":"cr-s3-q1","session":3,"topic":"IAS1 five components","question":"Which report is outside a complete set of financial statements under IAS 1?","choices":["The statement of comprehensive income","The statement of cash flows","A separately published sustainability report","Notes to the financial statements"],"correct_index":2,"explanation":"A complete set includes financial position, financial performance, changes in equity, cash flows and notes, with the required comparative information. A separate sustainability report is not one of those financial statements.","set":1},{"id":"cr-s3-q2","session":3,"topic":"Accruals basis exception","question":"Which statement reports receipts and payments rather than using accrual accounting?","choices":["The statement of financial position","The statement of changes in equity","The statement of cash flows","The statement of comprehensive income"],"correct_index":2,"explanation":"The cash-flow statement reports actual cash movements. The other financial statements use accrual accounting, recognising economic effects in the relevant period even when cash is received or paid later.","set":1},{"id":"cr-s3-q3","session":3,"topic":"Current asset test","question":"Inventory will be realised within a company's normal 18-month operating cycle, although not within 12 months after the reporting date. How is it classified under IAS 1?","choices":["Current because it is realised within the normal operating cycle","Non-current because realisation takes more than 12 months","Non-current until the operating cycle is shortened","Current only after it becomes a trade receivable"],"correct_index":0,"explanation":"Realisation within the normal operating cycle is sufficient for current classification. The operating cycle may be longer than 12 months. The 12-month test is not the only route to current classification.","set":1},{"id":"cr-s3-q4","session":3,"topic":"Offsetting","question":"A company has an asset and liability involving the same counterparty. Is that fact alone enough to offset them under IAS 1?","choices":["No, an IFRS requirement must permit or require the offsetting","Yes, if offsetting improves the company's financial ratios","Yes, a shared counterparty always permits net presentation","Yes, if management applies offsetting consistently over time"],"correct_index":0,"explanation":"IAS 1 generally prohibits offsetting unless IFRS permits or requires it. A shared counterparty, a preferred ratio or consistent practice does not by itself satisfy the relevant conditions.","set":1},{"id":"cr-s3-q5","session":3,"topic":"Statement of changes in equity formula","question":"A company's total comprehensive income is €80 million, including a €10 million gain on revaluation recognised in other comprehensive income. It issues shares for €30 million and pays €20 million of dividends. How much does total equity change?","choices":["An increase of €110 million","An increase of €90 million","An increase of €80 million","An increase of €30 million"],"correct_index":1,"explanation":"Equity rises by €90m: the full €80m of comprehensive income (the €10m OCI gain is part of comprehensive income), plus €30m of owner contributions, minus €20m of distributions. The €110m option omits the dividend deduction. The €80m option wrongly removes the OCI gain from comprehensive income. The €30m option treats the share issue as reducing equity.","set":1},{"id":"cr-s3-q6","session":3,"topic":"IFRS 18 categories in practice","question":"A retailer presents its first IFRS 18 statement of profit or loss. It reports revenue, cost of sales, interest expense on its bank borrowings, and its share of profit of an equity-accounted associate. Which classification complies with IFRS 18's categories?","choices":["Interest expense in the operating category and the associate's profit in the investing category","Interest expense in the financing category and the associate's profit in the investing category","Interest expense in the financing category and the associate's profit in the operating category","Interest expense and the associate's profit both in the operating category"],"correct_index":1,"explanation":"IFRS 18 places income and expenses from liabilities that arise from raising finance, such as interest on borrowings, in the financing category, and returns from investments that generate returns largely independently of operations, including equity-accounted associates, in the investing category. The operating category is the residual for the main business activities, so misclassifying either item distorts operating profit.","set":1},{"id":"cr-s3-q7","session":3,"topic":"IFRS18 five categories","question":"Which is one of IFRS 18's five categories of income and expenses in profit or loss?","choices":["Investing","Extraordinary","Non-recurring","Other comprehensive income"],"correct_index":0,"explanation":"The categories are operating, investing, financing, income taxes and discontinued operations. Other comprehensive income is outside profit or loss. Extraordinary and non-recurring are not separate IFRS 18 categories.","set":1},{"id":"cr-s3-q8","session":3,"topic":"IFRS18 subtotals","question":"Which subtotal must be presented in an IFRS 18 statement of profit or loss?","choices":["Earnings before interest, tax, depreciation and amortisation","Operating profit or loss","Gross profit in every business","Net working capital"],"correct_index":1,"explanation":"IFRS 18 requires operating profit or loss as a subtotal. EBITDA and gross profit are not universally required subtotals, and net working capital is not a profit-or-loss subtotal.","set":1},{"id":"cr-s3-q9","session":3,"topic":"Selecting an accounting policy","question":"No IFRS Accounting Standard directly applies to a transaction. Which source does IAS 8 require management to consider first in developing an accounting policy?","choices":["Accepted industry practice","IFRS requirements for similar and related issues","Conceptual Framework definitions alone","Other national standard setters' pronouncements"],"correct_index":1,"explanation":"IAS 8 gives priority to relevant IFRS requirements for similar and related issues, then Framework concepts. Other standard-setter material and industry practice are lower-priority sources and cannot conflict with those requirements.","set":1},{"id":"cr-s3-q10","session":3,"topic":"Change in accounting policy","question":"A voluntary accounting policy change is justified under IAS 8. There are no specific transition rules and retrospective application is practicable. How is it applied?","choices":["Prospectively to future periods only","Only to current opening balances, leaving comparatives unchanged","Only to the comparative profit subtotal","Retrospectively, with relevant comparative and opening-balance adjustments"],"correct_index":3,"explanation":"Apply the new policy as though it had always been used, to the extent practicable. Restate the affected comparative amounts and opening equity where necessary. A note alone does not replace the required restatement.","set":1},{"id":"cr-s3-q11","session":3,"topic":"Change in accounting estimate","question":"New information changes a machine's estimated remaining useful life. Earlier estimates were reasonable. How is the resulting depreciation change applied?","choices":["Restate every prior period presented in the statements","Correct it as a prior-period error under IAS 8","Restate prior periods only if the revision is material","Apply it prospectively to current and future periods, no restatement"],"correct_index":3,"explanation":"Useful life is an accounting estimate. A revision based on new information is applied prospectively, using the current carrying amount and revised remaining life. It is not a correction of a previous reasonable estimate.","set":1},{"id":"cr-s3-q12","session":3,"topic":"Prior period errors","question":"A material error occurred before the earliest comparative period presented. Retrospective correction is practicable. Which balances are adjusted under IAS 8?","choices":["Current opening equity only, leaving comparative opening balances unchanged","Current-year profit only","Opening assets, liabilities and equity of the earliest comparative period","Comparative closing balances only, leaving their opening balances unchanged"],"correct_index":2,"explanation":"Correct the opening balances of the earliest comparative period because the error arose earlier. This carries the cumulative prior effect into the restated comparatives rather than charging the discovery year's profit.","set":1},{"id":"cr-s3-q13","session":3,"topic":"Adjusting vs non-adjusting events","question":"A customer becomes bankrupt after year-end but before the financial statements are authorised. The bankruptcy confirms financial distress already present at year-end. What treatment follows under IAS 10?","choices":["Disclose only a non-adjusting event.","Adjust the year-end receivable for the confirmed existing condition.","Recognise a loss only in the following year.","Ignore the bankruptcy because it occurred after year-end."],"correct_index":1,"explanation":"The later event supplies evidence about a condition that already existed at the reporting date. It is adjusting. A wholly new condition arising only after year-end would require a different assessment.","set":1},{"id":"cr-s3-q14","session":3,"topic":"IAS1 vs IAS8","question":"A junior accountant proposes to disclose the company's accounting policies only inside the note describing this year's voluntary policy change, to avoid duplication. Which assessment is correct under IAS 1 and IAS 8?","choices":["The proposal works if no other accounting policy changed during the year","The proposal works because IAS 8 change disclosures replace the IAS 1 policy note","Material accounting policy information belongs in management commentary instead","The standing policy note is still required; the change disclosures come on top of it"],"correct_index":3,"explanation":"IAS 1 requires material accounting policy information in the notes every year, whether or not a policy changed. IAS 8's disclosures about the change (its nature, reasons and effects) are additional, not a replacement. Management commentary is outside the financial statements and cannot host the required note.","set":1},{"id":"cr-s3-q15","session":3,"topic":"Materiality","question":"An item is small in amount but could influence users' decisions because of its nature. How should materiality be assessed?","choices":["Ignore it if it is below a standard percentage of total assets","Use nature for the notes but size alone for recognition errors","Judge whether omission or misstatement could influence users' decisions","Wait until a user proves an actual decision has changed"],"correct_index":2,"explanation":"Materiality depends on size, nature or both in the reporting entity's circumstances. A fixed numerical threshold is not a complete assessment, and proof of an actual changed decision is not required.","set":1},{"id":"cr-s4-q1","session":4,"topic":"Purpose of IAS7","question":"A company reports a profit but cannot pay its suppliers on time. Which feature of accrual accounting explains why profit is not a measure of available cash?","choices":["It recognises only revenue that has already been collected","It includes cash movements from share issues in profit","It recognises income and expenses independently of when cash moves","It includes only items that increase working capital"],"correct_index":2,"explanation":"Revenue can be recognised before customers pay, and expenses can be recognised before or after cash payment. Asset purchases and loan repayments also use cash without being expenses in full. Profit and cash therefore measure different things.","set":1},{"id":"cr-s4-q2","session":4,"topic":"Bank overdraft treatment","question":"A company has €10 million in bank deposits and a €3 million overdraft. The overdraft is repayable on demand and forms an integral part of the company's cash management. What net cash and cash equivalents balance is reported under IAS 7?","choices":["€13 million","€7 million","€10 million","€3 million"],"correct_index":1,"explanation":"Under IAS 7 an overdraft that is repayable on demand and integral to cash management is a component of cash and cash equivalents, so it is offset: €10m − €3m = €7m. Without those cash-management conditions a bank borrowing does not become negative cash.","set":1},{"id":"cr-s4-q3","session":4,"topic":"Three activity classes","question":"Under IAS 7, which categories respectively contain customer cash receipts, cash purchases of equipment and proceeds from a new bank loan?","choices":["Operating, financing and investing","Operating, investing and financing","Investing, operating and financing","Financing, investing and operating"],"correct_index":1,"explanation":"Customer receipts arise from revenue-producing activities and are operating. Buying equipment is investing. Receiving loan proceeds changes borrowings and is financing.","set":1},{"id":"cr-s4-q4","session":4,"topic":"Classifying a cash flow","question":"A delivery company sells a van that it used in its business and receives cash. It does not routinely rent out and then sell vehicles. Where are the proceeds classified under IAS 7?","choices":["Outside the statement of cash flows","Operating activities","Financing activities","Investing activities"],"correct_index":3,"explanation":"The van is property, plant and equipment. Cash proceeds from disposing of it are investing. The fact that it was used in operations does not make the disposal receipt operating.","set":1},{"id":"cr-s4-q5","session":4,"topic":"Financing activities example","question":"A company issues ordinary shares for €12 million, repays €5 million of a bank loan, pays €2 million of dividends which its established policy classifies as financing, and buys equipment for €7 million. What is its net cash flow from financing activities?","choices":["An outflow of €2 million","An inflow of €12 million","An inflow of €7 million","An inflow of €5 million"],"correct_index":3,"explanation":"Financing nets to +€5m: +€12m shares issued, −€5m loan repaid, −€2m dividends under the stated financing policy. The equipment purchase is investing, so the −€2m option wrongly includes it. The €12m option misses both the repayment and the dividends. The €7m option wrongly treats the dividends as operating and leaves them out of financing.","set":1},{"id":"cr-s4-q6","session":4,"topic":"Direct vs indirect method","question":"A company uses the direct and indirect methods to calculate operating cash flow for the same year, with identical classification policies. What differs between the two methods?","choices":["How operating cash flow is presented and calculated","The total net operating cash flow","The closing balance of cash and cash equivalents","Which transactions count as cash receipts"],"correct_index":0,"explanation":"The direct method reports major classes of receipts and payments. The indirect method starts with a profit subtotal and adjusts for non-cash items, working capital and items reported elsewhere. Both arrive at the same operating cash-flow total.","set":1},{"id":"cr-s4-q7","session":4,"topic":"Indirect method starting point (pre-IFRS18)","question":"Before adopting IFRS 18, a company chooses to start its indirect operating cash-flow reconciliation with profit before tax. How must it account for operating income tax payments when calculating net operating cash flow?","choices":["Leave them in the starting profit figure with no adjustment.","Add them as a non-cash expense.","Deduct the actual operating income tax paid later in the reconciliation.","Report them as financing payments."],"correct_index":2,"explanation":"Profit before tax has not deducted tax expense. After reconciling that subtotal to cash generated from operations, deduct actual operating income taxes paid. Do not deduct tax expense instead of the cash payment.","set":1},{"id":"cr-s4-q8","session":4,"topic":"Working capital adjustment","question":"Trade receivables increase by €6 million and trade payables decrease by €2 million, with no write-offs or other working capital movements. What is the combined working capital adjustment when reconciling profit to operating cash flow under the indirect method?","choices":["Add €4 million","Subtract €4 million","Subtract €8 million","Add €8 million"],"correct_index":2,"explanation":"Subtract €8m in total. A €6m rise in receivables means revenue exceeded collections, so subtract €6m; a €2m fall in payables means suppliers were paid more than the expense recognised, so subtract €2m more. The −€4m option gets the payables sign wrong, +€4m gets the receivables sign wrong, and +€8m reverses both.","set":1},{"id":"cr-s4-q9","session":4,"topic":"Pre-IFRS18 treatment of dividends paid","question":"A company has not yet adopted IFRS 18. Under IAS 7, which classification choices are available for dividends paid, applied consistently from period to period?","choices":["Operating or investing","Financing only","Operating only","Operating or financing"],"correct_index":3,"explanation":"Before the IFRS 18 amendments, IAS 7 permits dividends paid to be classified as either operating or financing, consistently. They are not an investing payment.","set":1},{"id":"cr-s4-q10","session":4,"topic":"IFRS18 changes to IAS7","question":"A company applies IFRS 18 and the associated IAS 7 amendments. Where must it classify cash dividends paid to its ordinary shareholders?","choices":["Financing activities","Investing activities","Operating activities","Either operating or financing consistently"],"correct_index":0,"explanation":"The amendments require dividends paid to be financing cash flows. The earlier operating-or-financing choice no longer applies once these amendments are applied.","set":1},{"id":"cr-s4-q11","session":4,"topic":"IFRS18 and interest paid","question":"A manufacturer applies IFRS 18 and the related IAS 7 amendments. Investing in assets and providing finance to customers are not its main business activities. Where is cash interest paid on its borrowings classified?","choices":["Operating activities","Financing activities","Investing activities","Excluded from cash-flow totals"],"correct_index":1,"explanation":"For the manufacturer described, the amended IAS 7 requires interest paid to be financing. Special rules for entities with specified main business activities do not apply to these facts.","set":1},{"id":"cr-s4-q12","session":4,"topic":"IAS7 disclosure","question":"Which cash-related disclosure is required by IAS 7 rather than merely encouraged?","choices":["A full cash-flow statement presented for every operating segment","A forecast of next year's expected cash flows in the notes","The components of cash and cash equivalents and their reconciliation","The amount of all undrawn borrowing facilities available"],"correct_index":2,"explanation":"IAS 7 requires the components and their reconciliation to corresponding items in the statement of financial position. Segment cash-flow information and undrawn facilities are examples of additional encouraged disclosures, not the required reconciliation.","set":1},{"id":"cr-s4-q13","session":4,"topic":"Cash equivalents definition","question":"A company holds investments to meet short-term cash commitments. Which investment normally meets IAS 7's cash-equivalent conditions?","choices":["A bill acquired two years before maturity that is now three months from maturity","A treasury bill bought three months before maturity, convertible to a known amount","A corporate bond acquired five years before maturity, now three months out","Listed ordinary shares exposed to significant daily price changes"],"correct_index":1,"explanation":"A qualifying cash equivalent is short-term and highly liquid, readily convertible to a known cash amount, with insignificant value risk. Maturity is normally three months or less from acquisition. A long-term investment does not become a cash equivalent simply by approaching maturity.","set":1},{"id":"cr-s4-q14","session":4,"topic":"Common mistake: classification schemes","question":"A company applies IFRS 18 to profit or loss and IAS 7 to cash flows. Does the use of operating, investing and financing labels mean the two statements have identical classification rules?","choices":["No, each statement has its own classification requirements.","Yes, every profit-or-loss category determines the matching cash-flow category.","Yes, IAS 7's categories are replaced by IFRS 18's categories.","No, IFRS 18 leaves the statement of cash flows unchanged."],"correct_index":0,"explanation":"Each statement keeps its own classification scheme: IAS 7 classifies cash receipts and payments, while IFRS 18 classifies income and expenses. The last option fails because IFRS 18 also amends parts of IAS 7, including the classification of interest and dividends and the indirect-method starting point. Shared labels do not make the two sets of rules identical.","set":1},{"id":"cr-s5-q1","session":5,"topic":"Three standards, three jobs","question":"A company must calculate the subsequent amortised-cost carrying amount of a bond liability. Which Standard contains the relevant measurement requirements?","choices":["IAS 32","IFRS 7","IFRS 9","IAS 1"],"correct_index":2,"explanation":"IFRS 9 covers recognition and measurement of financial assets and liabilities. IAS 32 covers presentation and liability-versus-equity classification. IFRS 7 covers disclosures.","set":1},{"id":"cr-s5-q2","session":5,"topic":"IAS32 objective","question":"Which task falls primarily within IAS 32?","choices":["Measuring expected credit losses","Distinguishing a financial liability from equity","Disclosing exposure to liquidity risk","Classifying operating cash receipts"],"correct_index":1,"explanation":"IAS 32 sets presentation principles for financial instruments, including the issuer's distinction between financial liabilities and equity. Expected credit losses are in IFRS 9, risk disclosures in IFRS 7 and cash-flow classification in IAS 7.","set":1},{"id":"cr-s5-q3","session":5,"topic":"Substance over form","question":"A company issues preference shares that it must redeem for cash in five years. No exception applies. What determines whether the issuer reports a liability or equity?","choices":["The legal label of the instrument","The issuer's country of incorporation","The classification management prefers","The contractual cash-payment obligation"],"correct_index":3,"explanation":"The issuer has an unavoidable contractual obligation to deliver cash, so the instrument is a financial liability. Calling it a share does not override the substance of that obligation.","set":1},{"id":"cr-s5-q4","session":5,"topic":"Two-part equity test","question":"A company issues an instrument legally described as a share. Under IAS 32, which term would make the issuer classify it as a financial liability?","choices":["The holder can demand repayment of the capital for a fixed amount","The issuer expects to pay regular but fully discretionary dividends","Management intends to describe the instrument as debt in internal reporting","The instrument's legal form is a share issue rather than a loan agreement"],"correct_index":0,"explanation":"IAS 32 classifies by substance: an instrument is equity only if it includes no contractual obligation to deliver cash or another financial asset. A holder right to require repayment for a fixed or determinable amount creates exactly that obligation, as with redeemable preference shares. Discretionary dividends create no obligation, and neither management's internal labels nor the legal form of a share changes the contractual analysis.","set":1},{"id":"cr-s5-q5","session":5,"topic":"Redeemable preference shares","question":"Preference shares must be redeemed for cash after five years and carry mandatory annual cash distributions. No classification exception applies. How does the issuer report the instrument and the distributions?","choices":["Equity and distributions directly in equity","Equity and expenses in profit or loss","A financial liability and finance costs in profit or loss","A contingent liability and note disclosure only"],"correct_index":2,"explanation":"Mandatory redemption creates a financial liability. Distributions relating to that liability are finance costs in profit or loss, even though company law calls them dividends.","set":1},{"id":"cr-s5-q6","session":5,"topic":"Compound instrument","question":"A bond requires cash coupons and principal repayment unless the holder converts into a fixed number of ordinary shares. The conversion option satisfies IAS 32 equity conditions. How is the bond reported at issue?","choices":["Entirely as a liability until conversion","Entirely as equity because conversion is possible","Unclassified until the holder chooses settlement","As separate liability and equity components"],"correct_index":3,"explanation":"The bond is a compound financial instrument. Measure the debt component first as comparable non-convertible debt, then allocate the residual proceeds to equity. Both components are recognised at issue.","set":1},{"id":"cr-s5-q7","session":5,"topic":"Split accounting discount rate","question":"Which discount rate is used to measure the liability component of a convertible bond whose conversion option qualifies as equity?","choices":["The convertible bond's coupon rate","The risk-free rate without the issuer's credit risk","The required return on the issuer's ordinary shares","The market yield on comparable non-convertible debt"],"correct_index":3,"explanation":"Use the yield that the issuer would pay for comparable debt without the conversion option. Discount the contractual coupons and principal at that rate. The difference between issue proceeds and this liability is equity.","set":1},{"id":"cr-s5-q8","session":5,"topic":"Equity component of a compound instrument","question":"A company receives €500,000 for a convertible bond. The conversion option qualifies as equity and the separately measured liability is €450,000. There are no issue costs. What equity component is initially recognised?","choices":["€50,000","€450,000","Nil","€500,000"],"correct_index":0,"explanation":"Equity is the residual: €500,000 of proceeds − €450,000 for the liability component = €50,000. The €450,000 option mistakes the liability component for the equity residual, nil treats the convertible as pure debt, and €500,000 treats it as pure equity; those last two skip the required split of the proceeds.","set":1},{"id":"cr-s5-q9","session":5,"topic":"Presenting interest and dividends","question":"An annual cash payment is legally called a dividend, but the underlying preference shares are classified as a financial liability. Where is the financing cost reported?","choices":["Directly in equity","As a reduction of principal only","In profit or loss","Only in a note"],"correct_index":2,"explanation":"The accounting follows the liability classification. Interest and distributions relating to a financial liability are expenses in profit or loss. The legal dividend label does not make the payment an equity distribution.","set":1},{"id":"cr-s5-q10","session":5,"topic":"Presenting equity distributions","question":"A company pays a dividend to holders of its own ordinary shares, correctly classified as equity. How is the dividend accounted for?","choices":["As an expense in profit or loss","As an expense in other comprehensive income","As a distribution directly reducing equity","As repayment of a financial liability only"],"correct_index":2,"explanation":"A distribution to owners acting as owners is recognised directly in equity. It is excluded from income and expenses and therefore does not reduce profit or total comprehensive income.","set":1},{"id":"cr-s5-q11","session":5,"topic":"Financial asset definition","question":"Which item is a financial asset under IAS 32?","choices":["A contractual trade receivable","An internally generated brand","A production machine","A warehouse of finished goods"],"correct_index":0,"explanation":"A trade receivable is a contractual right to receive cash. Brands, machinery and inventories are non-financial assets even though they may generate cash through use or sale.","set":1},{"id":"cr-s5-q12","session":5,"topic":"Derivative","question":"A company enters a forward currency contract. Its value changes with the exchange rate, no significant initial investment is required, and settlement occurs in three months. What type of financial instrument is it?","choices":["A direct holding of foreign cash","A derivative","An ordinary equity instrument","A trade receivable from a completed sale"],"correct_index":1,"explanation":"A derivative's value responds to an underlying variable, requires little or no initial net investment relative to similar exposure, and settles at a future date. A forward currency contract meets these conditions without requiring direct ownership of the currency today.","set":1},{"id":"cr-s5-q13","session":5,"topic":"Classify then measure an instrument","question":"A company issues perpetual notes with no contractual repayment obligation and discretionary coupons, and separately holds a customer loan it intends to hold to collect contractual principal and interest payments. Which accounting applies?","choices":["The notes are a financial liability because they are called notes, and the loan is at amortised cost","The notes are equity, and the loan is at fair value through profit or loss as the default category","Both instruments are financial liabilities measured at amortised cost","The notes are equity under the IAS 32 substance test, and the loan is at amortised cost under IFRS 9"],"correct_index":3,"explanation":"Classification looks to substance: without a contractual obligation to deliver cash, the perpetual notes are equity under IAS 32 despite their legal label. A loan held within a hold-to-collect business model whose cash flows are solely principal and interest is measured at amortised cost under IFRS 9; fair value through profit or loss is not the default for such a loan.","set":1},{"id":"cr-s5-q14","session":5,"topic":"Common mistake: dividend classification","question":"A mandatory annual payment is called a dividend. When is it treated as a finance expense rather than an equity distribution?","choices":["When the underlying instrument is classified as a financial liability","Whenever the company has distributable profits","Whenever cash is paid before financial statements are authorised","Whenever the holder reports a financial asset"],"correct_index":0,"explanation":"The issuer's instrument classification determines the distinction. Distributions on a financial liability are finance costs, while distributions on an equity instrument are recognised directly in equity. The holder's classification does not decide the issuer's treatment.","set":1},{"id":"cr-s6-q1","session":6,"topic":"IFRS9 recognition trigger","question":"A company becomes party to a binding financial instrument contract today. The first contractual payment occurs next month. Under IFRS 9's general recognition principle, when is the instrument recognised?","choices":["When the company becomes party to the contractual provisions","When a regulator formally registers the signed contract","At the next reporting date, when it is first measured","When the first contractual payment actually occurs"],"correct_index":0,"explanation":"The general trigger is becoming a party to the instrument's contractual provisions. Registration, payment and annual reporting are not substitute recognition dates. Specific regular-way purchase conventions require separate consideration where relevant.","set":1},{"id":"cr-s6-q2","session":6,"topic":"Initial measurement","question":"Ignoring transaction costs and specific exceptions for trade receivables, at what basis are financial assets and liabilities generally measured on initial recognition under IFRS 9?","choices":["Fair value at initial recognition","Historical cost regardless of fair value","Face value plus all future interest","Nominal value in every case"],"correct_index":0,"explanation":"The general starting point is fair value. Qualifying transaction costs and specified exceptions can modify the initial amount. Subsequent measurement categories do not eliminate the initial fair-value requirement.","set":1},{"id":"cr-s6-q3","session":6,"topic":"Four asset categories","question":"Which proposed treatment is not an IFRS 9 financial-asset measurement category?","choices":["Historical-cost changes recognised through equity","Debt at amortised cost","Debt at fair value through other comprehensive income","Fair value through profit or loss"],"correct_index":0,"explanation":"IFRS 9 uses amortised cost and the relevant fair-value categories. Historical-cost changes through equity is not a category. Debt and elected equity fair value through other comprehensive income also have different disposal rules.","set":1},{"id":"cr-s6-q4","session":6,"topic":"Debt-FVOCI vs equity-FVOCI","question":"A company sells two investments, one qualifying debt at fair value through other comprehensive income and one non-trading equity investment validly designated in that category. Which accumulated gains are reclassified to profit or loss on disposal?","choices":["Neither investment's gains","Only the equity gains","Both investments' gains","Only the debt gains"],"correct_index":3,"explanation":"Accumulated debt gains in other comprehensive income are recycled to profit or loss on derecognition. Gains on designated non-trading equity investments are not subsequently recycled there. The common category label does not make their disposal accounting identical.","set":1},{"id":"cr-s6-q5","session":6,"topic":"Amortised cost test (two-part)","question":"A bond is not designated at fair value through profit or loss. Which combination normally supports amortised-cost measurement?","choices":["Principal-and-interest cash flows and a trading business model","Commodity-linked cash flows and a hold-to-collect model","Commodity-linked cash flows and a trading model","Principal-and-interest cash flows and a hold-to-collect model"],"correct_index":3,"explanation":"Both tests must be satisfied: qualifying cash flows solely of principal and interest, and a business model aimed at collecting those flows. Passing only one does not establish amortised cost.","set":1},{"id":"cr-s6-q6","session":6,"topic":"Deriving effective interest income","question":"A debt investment measured at amortised cost opens the year at €100 million and closes at €103 million. The only cash received during the year is €5 million of interest; there are no purchases, sales or impairment. What effective interest income does the entity recognise in profit or loss?","choices":["€3 million","€8 million","€5 million","€2 million"],"correct_index":1,"explanation":"Closing amortised cost equals opening plus effective interest income minus cash received, so effective interest is €103m − €100m + €5m = €8m. Choice A forgets to add back the cash collected, choice C mistakes cash interest for effective interest income, and choice D nets the accretion against the cash instead of adding it back.","set":1},{"id":"cr-s6-q7","session":6,"topic":"Effective interest rate","question":"An investor buys a bond at a discount to its repayment amount. What determines interest income under the effective interest method?","choices":["The coupon rate alone, whatever the purchase price was","The rate equating future receipts to the initial carrying amount","The central bank policy rate, whatever the contract says","The change in the bond's fair value over the year"],"correct_index":1,"explanation":"The effective rate links initial carrying amount with future cash receipts. It incorporates the purchase discount or premium and eligible transaction costs. The coupon rate sets cash payments, not necessarily accounting interest income.","set":1},{"id":"cr-s6-q8","session":6,"topic":"Zero-coupon bond example","question":"An eight-year zero-coupon liability is initially measured at the present value of its €1 million repayment amount, using a 10% effective rate. No cash is paid before maturity. How does the liability change over time?","choices":["It stays unchanged until all interest is expensed at maturity.","It grows each year as effective interest accrues toward €1 million.","It decreases each year because interest expense reduces liabilities.","It starts at €1 million, with the discount held as a separate asset."],"correct_index":1,"explanation":"Each year's effective interest is added to the liability because no coupon is paid. The carrying amount grows from discounted initial proceeds to the €1m redemption amount. The full discount is not postponed to the final year.","set":1},{"id":"cr-s6-q9","session":6,"topic":"Subsequent measurement of liabilities","question":"An ordinary bond liability is neither held for trading nor designated at fair value through profit or loss. No special exception applies. What is its normal subsequent measurement basis?","choices":["Fair value because the lender might sell its asset","Face value with all discount recognised at maturity","Unchanged proceeds with only cash coupons expensed","Amortised cost using the effective interest method"],"correct_index":3,"explanation":"Most ordinary financial liabilities are subsequently at amortised cost. Effective interest spreads premiums, discounts and eligible costs over their life. A lender's ability to trade the corresponding asset does not change the issuer's category.","set":1},{"id":"cr-s6-q10","session":6,"topic":"Initial measurement of a short-term trade receivable","question":"A retailer sells goods for €200,000 on 60-day terms with no interest charged, its normal practice on ordinary sales. At what amount is the trade receivable initially recognised?","choices":["€200,000 discounted at the customer's incremental borrowing rate for 60 days","€200,000, the invoiced transaction price","€200,000 plus interest imputed over the 60-day credit period","Fair value, remeasured through profit or loss at each reporting date"],"correct_index":1,"explanation":"A short-term trade receivable without a significant financing component is initially measured at its transaction price, the invoice amount. Imputing or discounting interest over 60 days adds spurious precision, and fair value through profit or loss is not the measurement of an ordinary trade receivable held to collect.","set":1},{"id":"cr-s6-q11","session":6,"topic":"FVPL as default","question":"A financial asset does not qualify for amortised cost or any permitted fair-value-through-other-comprehensive-income treatment. What is IFRS 9's residual measurement category?","choices":["Equity fair value through other comprehensive income whenever management prefers it","Fair value through profit or loss","Amortised cost whenever no quoted price exists","Historical cost without remeasurement"],"correct_index":1,"explanation":"Fair value through profit or loss is the residual category. A preference for lower reported volatility does not create eligibility for another category. Unquoted status alone does not authorise defaulting to unchanged historical cost.","set":1},{"id":"cr-s6-q12","session":6,"topic":"Applying IFRS 9 classification at transition","question":"On 1 January 2018 a company applies IFRS 9 for the first time. Its treasury holds plain fixed-rate bonds, collecting the coupon and principal payments to maturity; it has never traded such bonds and the contracts contain no leverage or optionality features. How are these bonds measured under IFRS 9?","choices":["At fair value through profit or loss: IFRS 9 makes it the default for all debt instruments","At fair value through other comprehensive income: all former held-to-maturity portfolios move there","At amortised cost: the hold-to-collect business model and principal-and-interest cash flows meet the conditions","They keep their IAS 39 category unchanged, because IFRS 9 grandfathers existing classifications"],"correct_index":2,"explanation":"Under IFRS 9 a debt instrument held in a business model whose objective is collecting contractual cash flows, where those flows are solely payments of principal and interest, is measured at amortised cost. Fair value through profit or loss is the residual default rather than the rule, and IFRS 9 replaces the IAS 39 categories instead of preserving them.","set":1},{"id":"cr-s6-q13","session":6,"topic":"Held-to-collect test failure","question":"A debt investment pays only principal and basic lending interest, but the investor holds it for active short-term trading. How is it normally measured?","choices":["Amortised cost because the contractual cash flows qualify","Debt at fair value through other comprehensive income because trading includes sales","Fair value through profit or loss because the business model is trading","Principal at amortised cost and coupons at fair value"],"correct_index":2,"explanation":"Qualifying contractual cash flows alone are insufficient for amortised cost. The trading business model leads to fair value through profit or loss. It is not the qualifying collect-and-sell model merely because sales occur.","set":1},{"id":"cr-s7-q1","session":7,"topic":"IFRS9's five measurement areas","question":"Which list identifies measurement topics governed by IFRS 9 rather than treating it as only an initial-measurement standard?","choices":["Initial and subsequent values only, with impairment under IFRS 7","Initial value and liability/equity presentation only","Initial and subsequent values and disclosures, with impairment under IAS 37","Initial and subsequent measurement, reclassification, gains and losses, and impairment"],"correct_index":3,"explanation":"IFRS 9 covers recognition and measurement across an instrument's life, including classification-related measurement, gains and losses, and impairment. IAS 32 addresses presentation and IFRS 7 addresses disclosures. These roles should not be interchanged.","set":1},{"id":"cr-s7-q2","session":7,"topic":"ECL model vs incurred loss model","question":"An ordinary loan is subject to the general IFRS 9 impairment model. How does expected-loss recognition differ from waiting for an incurred-loss event?","choices":["It waits for objective evidence of a loss event.","It starts only after significant credit deterioration.","It recognises only shortfalls payable in the current year.","It recognises an allowance before a triggering loss event occurs."],"correct_index":3,"explanation":"The expected-loss model is forward-looking. An ordinary Stage 1 loan already has 12-month expected credit losses, even if it performs as agreed. This supplements the course's brief overview and should not be confused with an incurred-loss trigger.","set":1},{"id":"cr-s7-q3","session":7,"topic":"ECL Stage 1","question":"Under the general IFRS 9 impairment model, a loan has not experienced a significant increase in credit risk since initial recognition and remains in Stage 1. What allowance basis applies?","choices":["No allowance until deterioration","Lifetime expected credit losses","12-month expected credit losses","The entire gross carrying amount"],"correct_index":2,"explanation":"Stage 1 requires 12-month expected credit losses, not automatically zero. Lifetime losses are generally required after significant deterioration in Stage 2. The general staging model is assumed here, rather than a simplified trade-receivable approach.","set":1},{"id":"cr-s7-q4","session":7,"topic":"ECL Stage 3","question":"An ordinary loan moves from Stage 2 to Stage 3 because it becomes credit-impaired. It was not purchased or originated credit-impaired. How does its interest calculation change?","choices":["It continues on the gross carrying amount.","It uses original principal regardless of repayments.","It uses the carrying amount net of the loss allowance.","It stops recognising interest altogether."],"correct_index":2,"explanation":"Stage 2 uses gross carrying amount for interest. For the stated Stage 3 loan, the effective rate applies to net amortised cost after the allowance. Both stages use lifetime expected losses, but that does not make their interest bases the same.","set":1},{"id":"cr-s7-q5","session":7,"topic":"IFRS7 purpose","question":"Why does IFRS 7 require financial instrument disclosures in addition to recognition and measurement?","choices":["To explain tax uncertainties arising from the instruments","To report the historical trading positions of investors","To replace the executive-pay disclosures in the notes","To explain the instruments' significance and their risks"],"correct_index":3,"explanation":"IFRS 7 helps users assess the significance of financial instruments for position and performance, and the nature and extent of related risks. Measurement provides recognised amounts, but it does not by itself explain all exposure and risk-management information.","set":1},{"id":"cr-s7-q6","session":7,"topic":"Three IFRS7 risk categories","question":"Which set identifies the three broad financial risk categories that IFRS 7 disclosures address?","choices":["Market, credit and liquidity risk","Political, currency and reputation risk","Operational, strategy and compliance risk","Interest rate, inflation and tax risk"],"correct_index":0,"explanation":"The categories are market, credit and liquidity risk. Currency, interest-rate and other price risks are types of market risk. They do not replace credit risk or liquidity risk in the broad classification.","set":1},{"id":"cr-s7-q7","session":7,"topic":"Market risk definition","question":"A bond portfolio falls in fair value after market interest rates rise. Which description identifies the financial risk shown?","choices":["A counterparty fails to perform its obligation.","Market prices change the instrument's value.","Available funding is insufficient to repay liabilities.","A regulator requires an accounting-policy revision."],"correct_index":1,"explanation":"This is market risk from interest-rate changes. A fall in bond value can occur without borrower default and without a funding shortfall. Default is credit risk, while difficulty settling liabilities is liquidity risk.","set":1},{"id":"cr-s7-q8","session":7,"topic":"Common mistake: choosing which risks to disclose","question":"A company has material market, credit and liquidity exposures. Which approach is consistent with IFRS 7's risk-disclosure objectives?","choices":["Disclose market and credit risk, but omit liquidity until default.","Explain all relevant exposures rather than select only one category.","Replace the different risks with a single unexplained net number.","Disclose only risks that created a recognised loss allowance."],"correct_index":1,"explanation":"Material exposures do not become irrelevant because another risk is also disclosed or because no allowance has arisen. Market, credit and liquidity risks answer different questions and need information appropriate to their nature.","set":1},{"id":"cr-s7-q9","session":7,"topic":"IFRS7 vs IFRS9","question":"An analyst wants disclosure about a company's interest-rate exposure rather than a rule for measuring its debt. Which standard directly addresses this request?","choices":["IFRS 7 financial instrument disclosures","IAS 32 liability/equity presentation","IFRS 9 measurement requirements","IAS 1 measurement-category selection"],"correct_index":0,"explanation":"IFRS 7 addresses financial instrument risk disclosures, including material interest-rate exposure. IAS 32 presentation and IFRS 9 recognition and measurement have different roles. A request for sensitivity information is not a request to choose a measurement category.","set":1},{"id":"cr-s7-q10","session":7,"topic":"Liquidity risk definition","question":"Which situation illustrates liquidity risk rather than market risk or credit risk?","choices":["Equity holdings fall after quoted share prices decline.","The company has difficulty meeting its financial liabilities when due.","A customer defaults on a receivable.","Bond values fall after interest rates rise."],"correct_index":1,"explanation":"Liquidity risk concerns meeting obligations associated with financial liabilities. Falling quoted prices and interest-rate-related value changes are market risks. A customer's failure to pay is credit risk.","set":1},{"id":"cr-s8-q1","session":8,"topic":"Default treatment of traded shares","question":"A fund buys listed shares intending to sell them within weeks when prices move. At the reporting date the shares show an unrealised gain. Under IFRS 9, where does that gain appear?","choices":["In other comprehensive income, with recycling to profit or loss when the shares are sold","In other comprehensive income without recycling, because that treatment is mandatory for all shares","Nowhere until disposal, because gains are recognised only when realised","In profit or loss, because equity investments are measured at fair value through profit or loss by default"],"correct_index":3,"explanation":"Equity investments default to fair value through profit or loss under IFRS 9, and a trading intention rules out the FVOCI election in any case. Recycling of equity gains through profit or loss does not exist under IFRS 9, the no-recycling treatment is an election rather than a mandate, and realised-only recognition belongs to superseded practice.","set":1},{"id":"cr-s8-q2","session":8,"topic":"FVOCI election and disposal","question":"A manufacturer buys a 4% stake in a key supplier as a long-term strategic holding, not for trading, and makes the IFRS 9 election available for such equity investments at initial recognition. Years later it sells the stake at a gain. What happens to the cumulative fair value gains held in other comprehensive income?","choices":["They are recycled to profit or loss as part of the gain on disposal","They stay within equity, for example transferred to retained earnings, and never pass through profit or loss","They reverse against the cost of any replacement investment in the same supplier","They are reclassified to profit or loss only if the stake was held for more than five years"],"correct_index":1,"explanation":"For equity investments designated at fair value through other comprehensive income, IFRS 9 prohibits recycling: on disposal the cumulative gains remain in equity and may be transferred between equity reserves, but they never enter profit or loss. Choices A and D import the old available-for-sale recycling model, and choice C invents a netting that no standard contains.","set":1},{"id":"cr-s8-q3","session":8,"topic":"Default classification for equity investments","question":"An ordinary equity investment is within IFRS 9 and no equity FVOCI election is made. No special exception applies. What subsequent measurement category is the default?","choices":["Amortised cost using effective interest","FVOCI automatically for shares","Historical cost without value updates","Fair value through profit or loss"],"correct_index":3,"explanation":"FVTPL is the default for in-scope equity investments. An eligible non-trading holding can use the equity FVOCI election only when that election is made at initial recognition. Shares do not qualify for amortised cost merely because they are held for investment.","set":1},{"id":"cr-s8-q4","session":8,"topic":"FVOCI election scope","question":"Which investment could qualify for IFRS 9's equity FVOCI election, assuming all other eligibility requirements are met?","choices":["Ordinary shares acquired for non-trading investment","Debt held exclusively for active trading","A government bond held to collect coupons","Ordinary shares acquired exclusively for active trading"],"correct_index":0,"explanation":"The election concerns eligible equity instruments not held for trading. A debt instrument is assessed under debt classification rules, not this election. A trading equity investment cannot elect FVOCI just to avoid profit volatility.","set":1},{"id":"cr-s8-q5","session":8,"topic":"FVOCI election mechanics","question":"For an eligible non-trading equity holding, which statement correctly describes the FVOCI election?","choices":["A reversible policy choice for the entire portfolio","An irrevocable choice for each instrument at initial recognition","A reversible choice at any later reporting date","An automatic result after twelve months of ownership"],"correct_index":1,"explanation":"The election is made instrument by instrument when the holding is initially recognised, and is irrevocable. It is neither automatic after a holding period nor a later choice made after seeing the investment's performance.","set":1},{"id":"cr-s8-q6","session":8,"topic":"Dividends under equity FVOCI","question":"An elected equity FVOCI investment pays an ordinary dividend that is investment income rather than a clear recovery of cost. Where is that dividend generally recognised?","choices":["In OCI alongside every price movement","In profit or loss as dividend income","As a cost reduction without income","Nowhere because FVOCI prevents investment income"],"correct_index":1,"explanation":"Ordinary dividends generally enter profit. Fair-value changes on the elected equity holding enter OCI. Distinguishing these items prevents the mistaken assumption that FVOCI moves all returns out of profit.","set":1},{"id":"cr-s8-q7","session":8,"topic":"Recycling under equity FVOCI","question":"An elected equity FVOCI investment is sold with accumulated gains in OCI. What treatment is permitted for those accumulated gains?","choices":["Recycle gains but never losses into profit","Recognise them as disposal revenue","Transfer them within equity without recycling into profit","Reverse them against the asset and omit sale proceeds"],"correct_index":2,"explanation":"The accumulated equity FVOCI gain is not recycled into profit on sale. The company may transfer it between equity components, for example to retained earnings. That internal transfer is not income and does not change total equity.","set":1},{"id":"cr-s8-q8","session":8,"topic":"Worked example: FVTPL treatment","question":"An FVTPL equity investment is purchased for €160 million, closes at €122 million fair value and pays a €7 million ordinary dividend. Ignore fees and tax. Which items enter profit or loss?","choices":["Neither the price loss nor the dividend","Dividend income €7m but no price loss","Price loss €38m but no dividend","Price loss €38m and dividend income €7m"],"correct_index":3,"explanation":"FVTPL recognises the €160m − €122m = €38m price loss in profit even before sale. The €7m ordinary dividend also enters profit, giving a net €31m loss.","set":1},{"id":"cr-s8-q9","session":8,"topic":"Worked example: FVOCI treatment","question":"An eligible equity investment is validly elected FVOCI, purchased for €160 million and remeasured to €122 million at year-end. It pays an ordinary €7 million dividend that is not a cost recovery. Ignore fees and tax. What enters profit or loss?","choices":["A €38m price loss without dividend income","A €38m price loss plus €7m dividend income","€7m dividend income without the price loss","Neither dividend income nor price loss"],"correct_index":2,"explanation":"The €7m dividend enters profit, while the €38m price loss enters OCI. The asset still closes at €122m and total comprehensive loss is €31m. Keeping the price loss out of profit does not mean it is unrecognised.","set":1},{"id":"cr-s8-q10","session":8,"topic":"ECL impairment for equity FVOCI","question":"An elected equity FVOCI holding loses value. How does IFRS 9 treat the decline compared with debt expected-credit-loss accounting?","choices":["Add a debt ECL expense to the full fair-value loss in OCI.","Wait for an incurred-loss trigger before any loss recognition.","Recognise the fair-value change in OCI without a separate ECL allowance.","Recycle the credit-related portion into profit before sale."],"correct_index":2,"explanation":"The equity FVOCI holding is remeasured through OCI and has no separate ECL allowance. Qualifying debt exposures may have an expected-credit-loss layer. Applying the debt staging model again to this equity holding would confuse distinct measurement rules.","set":1},{"id":"cr-s8-q11","session":8,"topic":"Choosing presentation for non-trading equities","question":"An investment company holds listed shares it views as long-term positions. Its board accepts that the shares' fair values are reliable but wants to keep short-term market swings out of net income. Which step was available under IFRS 9, and when?","choices":["Electing fair value through other comprehensive income at any later reporting date, once volatility appears","Moving the shares to amortised cost, because they are held for the long term","No step exists: every equity investment's fair value movements must stay in profit or loss","Electing fair value through other comprehensive income, but only at initial recognition and only because the shares are not held for trading"],"correct_index":3,"explanation":"The FVOCI election for non-trading equity investments must be made at initial recognition and is irrevocable; it cannot be adopted later when volatility turns unwelcome. Amortised cost is impossible for equity instruments, and profit or loss is only the default, not the sole destination.","set":1},{"id":"cr-s8-q12","session":8,"topic":"Applying the classification checklist","question":"Before choosing IFRS 9 measurement and IFRS 7 disclosures, an issuer first classifies the instrument under IAS 32. What does that first step determine?","choices":["Which risk sensitivity analyses must be disclosed","The amount of the expected credit loss allowance","The effective interest rate to apply to the instrument","Whether the instrument is a financial asset, a liability or equity"],"correct_index":3,"explanation":"Begin with the instrument's contractual substance and the relevant definitions under IAS 32. Then address recognition and measurement under IFRS 9 and disclosure under IFRS 7. Starting with a desired accounting result reverses the decision process.","set":1},{"id":"cr-s9-q1","session":9,"topic":"IAS16 scope exclusions","question":"Which property is normally investment property under IAS 40 rather than owner-used PPE under IAS 16?","choices":["Machinery used to produce goods","An office building held to earn rent from unrelated tenants","A van used to deliver the company's goods","Offices used by the company's administrative staff"],"correct_index":1,"explanation":"Property held to earn rentals is normally investment property. Machinery, delivery vehicles and owner-occupied administrative offices serve the company's own operations and fall under IAS 16 on these facts. The purpose of holding the building matters.","set":1},{"id":"cr-s9-q2","session":9,"topic":"PP&E definition","question":"Which item meets the basic PPE description of a tangible asset used in operations for more than one period?","choices":["Finished goods held for ordinary resale","Listed shares bought for short-term trading","An internally generated trademark","A delivery van used for several years"],"correct_index":3,"explanation":"The van is tangible, used in the business and expected to serve more than one period. Finished goods are inventory, shares are financial assets and a trademark is intangible. A long holding period alone would not make all of these PPE.","set":1},{"id":"cr-s9-q3","session":9,"topic":"Applying the IAS 16 recognition conditions","question":"On 28 December a manufacturer takes delivery of a machine that will clearly serve production for years, at an invoiced price of €410,000 payable in 60 days. Installation finishes the following January, so the machine stands unused at year end, and the purchase was never entered in the capital budget. Future economic benefits are probable and the cost is reliably measurable. Is an asset recognised at year end?","choices":["No: the machine is not yet in use, and IAS 16 recognition requires operation to have begun","No: the price is unpaid at year end, and an asset cannot exceed the amounts already paid","Yes: the recognition conditions are met, and use, payment and budget approval are not among them","No: without a capital budget line and internal approval, the cost fails the recognition test"],"correct_index":2,"explanation":"IAS 16 adds two recognition conditions to the definition of property, plant and equipment: probable future economic benefits and a reliably measurable cost. Both are met. Use, settlement and internal paperwork are irrelevant: the machine is recognised with a corresponding liability, the unpaid price does not block recognition, and budget lines are internal control rather than a recognition condition.","set":1},{"id":"cr-s9-q4","session":9,"topic":"Three elements of initial cost","question":"Assuming each item meets the relevant conditions, which combination describes the main elements of initial PPE cost?","choices":["Purchase price, directly attributable preparation costs and initial restoration estimate","Purchase price, product marketing and general administration","Purchase price, staff training and all feasibility spending","Purchase price alone, excluding necessary installation"],"correct_index":0,"explanation":"Initial cost includes net purchase price, directly attributable costs of readiness and a qualifying initial dismantling or restoration estimate. Marketing, staff training and unrelated overheads are not included merely because they are paid near acquisition.","set":1},{"id":"cr-s9-q5","session":9,"topic":"Directly attributable costs","question":"Which cost is directly attributable to preparing a machine for its intended operation?","choices":["Unrelated head-office administration","Training the future machine operators","Necessary installation and calibration","Abnormal material waste during construction"],"correct_index":2,"explanation":"Installation and calibration prepare the machine itself for use. Staff training prepares people, while unrelated administration and abnormal waste do not qualify as machine preparation costs. A construction-period payment is not automatically capitalisable.","set":1},{"id":"cr-s9-q6","session":9,"topic":"Capitalisation cutoff","question":"A machine has reached the required location and condition and can operate as intended, but is below planned output and not yet profitable. When does capitalisation of its initial preparation costs cease?","choices":["When full output is first reached","When it becomes capable of operating as intended","Twelve months after purchase","When it first earns a profit"],"correct_index":1,"explanation":"Readiness for intended operation is the boundary. Output and profitability targets concern later operating performance, not the machine's initial location and condition. Delaying full production does not extend preparation indefinitely.","set":1},{"id":"cr-s9-q7","session":9,"topic":"Excluded costs example","question":"A retailer renovates a store before opening. Which item is an operating cost rather than renovation cost on these facts?","choices":["Structural work necessary to reopen","Renovation needed for the intended operating condition","Ordinary shop staff wages unrelated to constructing the renovations","Shelving installation needed to make the store usable"],"correct_index":2,"explanation":"Necessary renovation work prepares the store. Ordinary operating staff wages do not qualify merely because the store has not opened. Direct labour actually constructing an asset can be different, so the nature of the work must be clear.","set":1},{"id":"cr-s9-q8","session":9,"topic":"Component approach","question":"An aircraft engine is significant relative to the aircraft's total cost and has a shorter useful life than the airframe. How does IAS 16 component depreciation apply?","choices":["Use one life because the aircraft has one registration.","Depreciate the significant engine separately from the remainder.","Separate the engine only if it can be sold alone.","Allocate a separate engine cost but use the airframe's life for both."],"correct_index":1,"explanation":"Separate depreciation reflects the significant parts' different useful lives or consumption patterns. Legal registration as one aircraft does not eliminate component accounting. The engine need not be independently saleable to require its own depreciation.","set":1},{"id":"cr-s9-q9","session":9,"topic":"Borrowing costs, qualifying asset","question":"What makes an asset a qualifying asset for IAS 23 borrowing-cost capitalisation?","choices":["Its financing loan lasts more than twelve months.","Its purchase price exceeds annual interest expense.","It will be used for many years after completion.","It necessarily takes a substantial period to get ready for intended use or sale."],"correct_index":3,"explanation":"The preparation period is central. An asset's price, loan term or later useful life is not the qualifying test. A ready-to-use asset does not qualify just because it is expensive or financed by long-term debt.","set":1},{"id":"cr-s9-q10","session":9,"topic":"Borrowing costs, specific vs general","question":"A qualifying construction project uses general borrowings rather than a separate project loan. How is the applicable capitalisation rate normally determined?","choices":["Use the weighted average rate of the relevant general borrowings.","Use the largest loan's rate alone.","Use a hypothetical project-loan rate unrelated to the pool.","Use zero because there is no specific loan."],"correct_index":0,"explanation":"The weighted average rate reflects borrowing costs and balances in the relevant general pool. A single selected facility or an imagined rate would not represent that pool. Lack of a specific loan does not itself prevent capitalisation.","set":1},{"id":"cr-s9-q11","session":9,"topic":"Machine cost worked example","question":"A machine is delivered to a site that is not yet ready. The company pays €0.7 million to store it while waiting, separately from €1.2 million necessary transport and €0.9 million installation costs. The storage is an avoidable holding cost, not necessary preparation. Which item is excluded from machine cost on these facts?","choices":["The €0.7m storage cost","The €1.2m necessary transport","The €0.9m necessary installation","All three, because delivery occurred before site readiness"],"correct_index":0,"explanation":"The stated storage outlay is not necessary to bring the machine to its intended location and condition. Necessary transport and installation qualify. The conclusion depends on the specified nature of storage, not a rule that every cost before readiness is capitalised.","set":1},{"id":"cr-s9-q12","session":9,"topic":"Service contract fee","question":"A company buys equipment for €620,000 and separately pays €42,000 in advance for routine servicing over the next year. The service is not installation. How is the service payment treated?","choices":["Deduct it from the equipment purchase price.","Add it to the equipment's initial cost.","Recognise a prepayment, then expense it as service is received.","Recognise an unpaid provision despite having paid it."],"correct_index":2,"explanation":"The future routine service is separate from the equipment asset. Advance payment creates a prepayment for services, released to expense over the service period. Neither capitalising it into PPE nor expensing unreceived services immediately gives the right separation.","set":1},{"id":"cr-s10-q1","session":10,"topic":"Subsequent costs: capitalise or expense","question":"Which later PPE expenditure can be capitalised when recognition criteria are satisfied?","choices":["A required major inspection replacing the previous inspection","Relocating an already usable machine to another operating site","Routine repairs consumed in the current period","Routine annual maintenance consumed in the current period"],"correct_index":0,"explanation":"A qualifying major inspection is recognised as an asset cost and depreciated over its benefit period. Derecognise any remaining balance of the previous inspection. Ordinary servicing is expensed rather than treated as an additional inspection asset.","set":1},{"id":"cr-s10-q2","session":10,"topic":"Component replacement","question":"A significant component is replaced and the new part meets asset-recognition criteria. What happens to the old and new component amounts?","choices":["Restate the old component as a prior-period error.","Keep the old component and capitalise the new one.","Keep the old component and expense the new one.","Derecognise the old component and capitalise the replacement."],"correct_index":3,"explanation":"Remove the old component's remaining carrying amount and recognise the qualifying replacement. Keeping both would overstate the machine. A planned replacement is not evidence that the original accounting was an error.","set":1},{"id":"cr-s10-q3","session":10,"topic":"Wall lining worked example","question":"A kiln carries at €460,000 including an old lining with €25,000 remaining carrying amount. A new lining costing €110,000 is installed and the old one is removed without proceeds. Ignoring depreciation during replacement, what is the revised kiln carrying amount?","choices":["€545,000","€570,000","€485,000","€110,000"],"correct_index":0,"explanation":"Remove the old lining and add the new one: €460,000 − €25,000 + €110,000 = €545,000. The replacement lining is capitalised as a component, and the removed part's €25,000 remaining balance is derecognised rather than preserved in the asset.","set":1},{"id":"cr-s10-q4","session":10,"topic":"Cost model","question":"What carrying basis applies to a machine under IAS 16's cost model?","choices":["Fair value remeasured at every reporting date","Original cost without depreciation or impairment","Cost less accumulated depreciation and impairment losses","Expected selling price less completion and selling costs"],"correct_index":2,"explanation":"The cost model starts from historical cost and deducts accumulated depreciation and impairment. It is not recurring fair value and not an inventory net-realisable-value measure. The machine's original cost is not left unchanged throughout its life.","set":1},{"id":"cr-s10-q5","session":10,"topic":"Three depreciation methods","question":"A machine's economic benefits are consumed according to how many units it produces. Which depreciation method directly matches that pattern?","choices":["Diminishing-balance depreciation","Equal annual straight-line charges","Units-of-production depreciation","Periodic fair-value remeasurement"],"correct_index":2,"explanation":"The units-of-production method allocates depreciable amount by output or usage. Straight line assumes even time-based consumption, and diminishing balance gives larger earlier charges. Revaluation changes a measurement amount, not the method of allocating consumption.","set":1},{"id":"cr-s10-q6","session":10,"topic":"Land depreciation","question":"A company purchases ordinary freehold land and an office building for its own use. How is the land normally treated, assuming its useful life is unlimited?","choices":["Combine it with the building and use the building's life.","Classify it as investment property because prices may rise.","Treat yearly price falls as ordinary depreciation.","Account for it separately and do not depreciate it."],"correct_index":3,"explanation":"Land and buildings are separate assets even if bought together. Land with an unlimited useful life is normally not depreciated, while the finite-life building is. Possible appreciation does not turn owner-used land into investment property.","set":1},{"id":"cr-s10-q7","session":10,"topic":"Revaluation model application","question":"A company uses revaluation for some machines but wants to leave similar machines in the same class at old cost-based amounts. What does IAS 16 require?","choices":["Revalue only assets chosen for external appraisal.","Apply the revaluation model to the entire relevant class.","Revalue only assets with price increases.","Choose a different policy for each machine according to purchase intention."],"correct_index":1,"explanation":"A revaluation policy is class-wide rather than a tool for selecting favourable individual outcomes. Revaluations must be sufficiently regular to avoid materially stale carrying amounts. Similar machines within the same class cannot simply be left out because their values fell.","set":1},{"id":"cr-s10-q8","session":10,"topic":"First revaluation surplus","question":"A first IAS 16 revaluation increases an asset's carrying amount. There is no prior deficit in profit to reverse. Where is the increase recognised?","choices":["In OCI and accumulated in revaluation surplus","In current profit as investment income","Half in profit and half in OCI","Only in disclosures until the asset is sold"],"correct_index":0,"explanation":"The unreversed upward revaluation enters OCI and revaluation surplus. It is recognised before disposal. A later uplift reversing a previous profit-recognised deficit would have different presentation to the extent of that reversal.","set":1},{"id":"cr-s10-q9","session":10,"topic":"Subsequent deficit reversing a reserve","question":"An asset has an existing €32 million revaluation surplus and now suffers a €47 million downward revaluation. The surplus relates entirely to that asset. Ignore tax and other movements. How is the decrease presented?","choices":["€47m profit expense and OCI nil","€15m profit expense and €32m OCI decrease","Profit nil and €47m OCI decrease","€32m profit expense and €15m OCI decrease"],"correct_index":1,"explanation":"Use the asset's €32m surplus first through OCI. The remaining €47m − €32m = €15m is an expense in profit. The surplus cannot become negative merely to keep the entire decline out of profit.","set":1},{"id":"cr-s10-q10","session":10,"topic":"Depreciation after revaluation","question":"A finite-life machine is revalued upward under IAS 16. What happens to later depreciation?","choices":["Keep the old charge because the uplift only affects equity.","Depreciate only the uplift and ignore the original balance.","Stop until carrying amount falls below historical cost.","Continue using the revised depreciable amount and remaining life."],"correct_index":3,"explanation":"Revaluation does not stop depreciation. Use the revalued carrying amount less relevant residual value and allocate it over remaining useful life according to the consumption pattern. Any permitted equity reserve transfer is separate from depreciation expense.","set":1},{"id":"cr-s10-q11","session":10,"topic":"IAS40 investment property definition","question":"Which property is normally investment property under IAS 40?","choices":["A factory used to make the company's products","An office used by the company's own staff","An office held for rental income and capital appreciation","Apartments held for ordinary-course resale by a property trader"],"correct_index":2,"explanation":"Investment property is held for rentals, capital appreciation or both. A factory and own administrative office are owner-occupied PPE. Ordinary-course property held for sale is inventory, even if its price might rise.","set":1},{"id":"cr-s10-q12","session":10,"topic":"IAS40 fair value model, key contrasts with IAS16","question":"For a building, which combination describes the IAS 40 fair-value model, as distinct from IAS 16 revaluation?","choices":["Periodic fair values, continued depreciation, changes in OCI","Fair value at reporting dates, no depreciation, changes in profit","Fair value at reporting dates, continued depreciation, changes in OCI","Periodic fair values, no depreciation, gains deferred until sale"],"correct_index":1,"explanation":"Under IAS 40 fair value, update the property to fair value at reporting dates, recognise changes in profit and do not depreciate. IAS 16 revaluation retains depreciation and generally uses OCI for upward amounts that do not reverse prior profit deficits.","set":1},{"id":"cr-s10-q13","session":10,"topic":"Diminishing balance worked example","question":"A machine costs €75,000 and uses 40% diminishing-balance depreciation from purchase. It is available for the entire first year and has zero residual value. What is first-year depreciation?","choices":["€12,000","€45,000","€30,000","€75,000"],"correct_index":2,"explanation":"First-year charge is €75,000 × 40% = €30,000. The resulting €45,000 carrying amount is not the depreciation expense. In later years the rate applies to the reduced balance, subject to the relevant depreciation estimates.","set":1},{"id":"cr-s10-q14","session":10,"topic":"Common mistake: investment property depreciation","question":"An accountant charges ordinary depreciation on a building already measured under IAS 40's fair-value model. Which correction is appropriate?","choices":["Remove depreciation because that model uses fair-value measurement without it.","Keep depreciation because every finite-life building must be depreciated under every model.","Move depreciation to OCI while leaving profit unchanged.","Deduct depreciation and keep that deduction in addition to the closing fair value."],"correct_index":0,"explanation":"IAS 40 fair-value property is not depreciated. Recognise the fair-value movement in profit instead. This rule does not extend to IAS 40's cost model, which still includes depreciation and impairment.","set":1},{"id":"cr-s11-q1","session":11,"topic":"Intangible asset three-part definition","question":"Assuming the recognition criteria are met, which description matches IAS 38's definition of an intangible asset?","choices":["An identifiable monetary asset with physical substance","An identifiable non-monetary asset without physical substance","A non-monetary asset with physical substance","An identifiable physical resource with reliably measurable cost"],"correct_index":1,"explanation":"The definition requires identifiability, non-monetary nature and lack of physical substance. Recognition additionally requires the applicable benefit and measurement conditions. Not every non-physical item is therefore automatically recognised.","set":1},{"id":"cr-s11-q2","session":11,"topic":"Identifiability","question":"A company holds a broadcasting licence granted by the regulator. The licence cannot be sold or transferred separately from the company. Which feature can still make the licence identifiable under IAS 38?","choices":["Its basis in contractual and legal rights","Nothing: an asset that cannot be sold separately is never identifiable","Its probability of generating future economic benefits","The company's ability to measure its cost reliably"],"correct_index":0,"explanation":"IAS 38 gives two alternative routes to identifiability: arising from contractual or other legal rights, or being separable. A non-transferable licence still qualifies through its legal basis, which is exactly what distinguishes it from goodwill. B treats separability as the only route. C and D are the recognition criteria (probability of benefits, reliable measurement), a separate test applied after the definition is met.","set":1},{"id":"cr-s11-q3","session":11,"topic":"Goodwill and identifiability","question":"Why is acquired goodwill distinguished from separately identifiable intangible assets?","choices":["It represents benefits not individually identifiable and separable from the business.","It must always have a finite contractual life.","It is an enforceable cash receivable from the seller.","It can always be sold alone without the acquired business."],"correct_index":0,"explanation":"Goodwill concerns future benefits from assets or factors not individually identified and separately recognised. That does not mean it lacks value. Identifiable patents, licences or relationships are assessed separately rather than all being labelled goodwill.","set":1},{"id":"cr-s11-q4","session":11,"topic":"Four acquisition routes","question":"A qualifying identifiable intangible is recognised as part of a business combination. What is its initial measurement basis in the acquirer's acquisition accounting?","choices":["The acquiree's old cost under a separate-purchase rule","Acquisition-date fair value under the business-combination rules","A nominal amount under a government-grant option","Nil because no individual purchase price was agreed"],"correct_index":1,"explanation":"IFRS 3 acquisition accounting uses acquisition-date fair value for qualifying identifiable intangibles. Lack of a separately negotiated price does not force a zero amount. Separate purchases and government grants are different acquisition routes with their own measurement rules.","set":1},{"id":"cr-s11-q5","session":11,"topic":"Items that always fail recognition","question":"Which item is specifically prohibited from recognition as an internally generated intangible asset?","choices":["A patent bought separately from a third party","Software meeting all development-recognition conditions","A qualifying trademark acquired in a business combination","A customer list generated through the company's own business"],"correct_index":3,"explanation":"IAS 38 prohibits recognition of internally generated customer lists and similar items. Their costs cannot be distinguished adequately from developing the business as a whole. Acquired identifiable assets and qualifying development are different cases.","set":1},{"id":"cr-s11-q6","session":11,"topic":"Revaluation model for intangibles","question":"What additional market condition is needed to use IAS 38's revaluation model for an intangible?","choices":["An active market by reference to which fair value can be determined","An independent estimate even with no active market","Management's forecast supported by goodwill","A quoted price for a similar whole business only"],"correct_index":0,"explanation":"IAS 38 requires an active market, which is unusual for unique intangible assets. A professional valuation or business forecast alone is insufficient. A market for whole businesses is not automatically an active market for the particular intangible right.","set":1},{"id":"cr-s11-q7","session":11,"topic":"Finite vs indefinite useful life","question":"A recognised intangible has no foreseeable limit to its benefit period and is properly classified as indefinite-life. What subsequent treatment applies?","choices":["Amortise over a long forecast period and test only on indicators.","Do not amortise and test only after an adverse event.","Always amortise over legal life despite the supported assessment.","Do not amortise, and test impairment at least annually."],"correct_index":3,"explanation":"An indefinite-life asset is not amortised while the classification is appropriate. It still needs annual impairment testing and testing when relevant indicators exist. Indefinite means no foreseeable limit, not endless value or exemption from reassessment.","set":1},{"id":"cr-s11-q8","session":11,"topic":"Contractual/legal rights and useful life","question":"A licence has ten years of contractual rights remaining, but its benefits will be consumed over six years with no residual use. What useful life applies?","choices":["Ten years","Six years","Sixteen years","Indefinite life"],"correct_index":1,"explanation":"Use the six-year expected benefit period, which is within the ten-year legal limit. Contract duration limits the life but does not require using the maximum when economic usefulness ends sooner.","set":1},{"id":"cr-s11-q9","session":11,"topic":"Research vs development","question":"A company's internal project is still in the research phase. How is current research expenditure treated under IAS 38?","choices":["Capitalise once technical feasibility alone is shown.","Expense as incurred.","Reinstate it as an asset if later development succeeds.","Defer all recognition until abandonment or commercialisation."],"correct_index":1,"explanation":"Internal research expenditure is expensed as incurred. Later success does not reinstate those costs. This is not the same as acquiring in-process research through a business combination, which has different acquisition-accounting rules.","set":1},{"id":"cr-s11-q10","session":11,"topic":"Development expenditure capitalisation","question":"Technical feasibility has been demonstrated for a development project. What must be established before further costs can be capitalised?","choices":["All required development-recognition conditions, not feasibility alone","Intention to finish without evidence of resources or benefits","Later success, which also restores past research costs","Reliable cost records without assessing ability to use or sell"],"correct_index":0,"explanation":"All six development criteria must be demonstrated. These concern feasibility, intention, ability to use or sell, probable benefits, resources and reliable measurement of attributable expenditure. A favourable result on only one criterion is insufficient.","set":1},{"id":"cr-s11-q11","session":11,"topic":"Add-on module amortisation","question":"A qualifying software module is ready after one year of a system's five-year useful life. It has no usefulness beyond that system, and the system life estimate is unchanged. Over what period is the module amortised?","choices":["A fresh five years","An indefinite life","The system's four remaining years","A restarted five years for the whole system"],"correct_index":2,"explanation":"The module's benefit ends with the system, so use the remaining four years. This conclusion relies on the stated shared end date. Adding functionality does not automatically restart the original asset's useful life.","set":1},{"id":"cr-s11-q12","session":11,"topic":"Purchased patent useful life","question":"A patent has ten years of legal protection remaining but only six years of expected economic use. There is no alternative use or residual value. What amortisation period is appropriate?","choices":["Six years","Sixteen years","No amortisation while rights exist","Ten years"],"correct_index":0,"explanation":"The expected benefit period is six years. Legal protection sets the maximum, but the economic useful life can be shorter. Amortising for ten years would allocate costs beyond the period in which benefits are expected.","set":1},{"id":"cr-s11-q13","session":11,"topic":"Website development costs","question":"A website project includes exploratory planning, technical development work, content used solely to advertise products and routine operating support. Which tranche can be capitalised when all IAS 38 conditions are met?","choices":["Exploratory planning","Purely promotional content","Technical development work","Routine operating support"],"correct_index":2,"explanation":"Development meeting all IAS 38 conditions may create a recognised intangible. The planning research, promotional content and routine support are expensed. This distinguishes cost types explicitly rather than assuming all website content must always receive identical treatment.","set":1},{"id":"cr-s11-q14","session":11,"topic":"Goodwill amortisation","question":"Which subsequent treatment is shared by acquired goodwill and properly classified indefinite-life intangible assets under IFRS?","choices":["Amortise both over management's planning period.","Do not amortise and test only after a specific indicator.","Amortise goodwill but test indefinite-life intangibles annually.","No amortisation and impairment testing at least annually."],"correct_index":3,"explanation":"Both acquired goodwill and indefinite-life intangibles require annual impairment testing and are not systematically amortised. Finite-life intangibles are different because they are amortised as well as subject to impairment requirements.","set":1},{"id":"cr-s12-q1","session":12,"topic":"Impairment loss definition","question":"An asset carries at €140 million and has €108 million recoverable amount. What does IAS 36 measure as its impairment loss?","choices":["Its market-price decline regardless of carrying amount","All accumulated depreciation since purchase","The €32m excess of carrying amount over recoverable amount","Its entire original purchase price"],"correct_index":2,"explanation":"The impairment loss is €140m − €108m = €32m. A price decline or accumulated depreciation alone is not the measured impairment. The comparison uses current carrying and recoverable amounts.","set":1},{"id":"cr-s12-q2","session":12,"topic":"Recoverable amount","question":"An asset has €114 million value in use and €103 million fair value less disposal costs. What is its recoverable amount?","choices":["€103 million","€108.5 million","€217 million","€114 million"],"correct_index":3,"explanation":"Recoverable amount is the higher of the two measures, here €114m. It reflects recovery through use or disposal. Do not average or add the alternatives, and do not select the more conservative lower amount.","set":1},{"id":"cr-s12-q3","session":12,"topic":"Mandatory annual testing","question":"Which items require annual IAS 36 impairment testing even without an identified adverse indicator?","choices":["Every asset whose life exceeds the planning horizon","Every acquired intangible, including finite-life assets already in use","Goodwill, indefinite-life intangibles and intangibles not yet available for use","Every revalued asset regardless of its type"],"correct_index":2,"explanation":"These specified categories have an annual testing requirement. The rule is not that every long-lived asset or every unfinished tangible asset must have the same annual test. Other assets normally require testing when indicators exist.","set":1},{"id":"cr-s12-q4","session":12,"topic":"External impairment indicator","question":"Which fact is an external impairment indicator rather than an internal one?","choices":["Physical damage to production machinery","Internal reports showing worse-than-expected performance","The company's net-asset carrying amount exceeds market capitalisation","Management plans to change an asset's use"],"correct_index":2,"explanation":"Market capitalisation supplies external market evidence. Damage, internal reports and management usage plans are internal signals. An indicator initiates further recoverability work rather than fixing the precise amount of every loss.","set":1},{"id":"cr-s12-q5","session":12,"topic":"Impairment loss for a revalued asset","question":"An impairment affects a revalued asset that has an existing revaluation surplus for that same asset. How is the loss normally presented?","choices":["Charge everything to profit without using surplus.","Split it equally between profit and surplus.","Recognise no loss because the asset was revalued.","Use the relevant surplus through OCI, then expense any excess."],"correct_index":3,"explanation":"A revalued-asset impairment is treated as a revaluation decrease. Reduce that asset's surplus through OCI to the extent available, with excess in profit. A reserve related to other assets is not automatically available to absorb it.","set":1},{"id":"cr-s12-q6","session":12,"topic":"Cash-generating unit (CGU)","question":"Two assets generate cash only when operated together. What feature identifies the appropriate CGU for impairment?","choices":["Every asset has a positive carrying amount.","Each asset has its own legal entity.","Management assigns an operating-segment label.","It is the smallest identifiable group generating largely independent inflows."],"correct_index":3,"explanation":"The CGU boundary follows cash generation, not simply legal organisation or asset count. If individual recoverable amounts cannot be determined, the smallest appropriate independent-inflow group supplies the testing level.","set":1},{"id":"cr-s12-q7","session":12,"topic":"When to use CGU-level testing","question":"A dedicated conveyor is essential to a quarry but has no largely independent cash inflows and no separately determinable recoverable amount. The quarry does have independent inflows. What is the appropriate test?","choices":["Test the conveyor alone at scrap value regardless of its role.","Include it in the quarry CGU.","Exclude it because it does not generate separate sales.","Combine all quarries despite their independent inflows."],"correct_index":1,"explanation":"The conveyor contributes to the quarry's cash generation and is tested with that CGU on these facts. Lack of separate inflows does not make it worthless. It also does not justify combining otherwise independent operations to conceal a loss.","set":1},{"id":"cr-s12-q8","session":12,"topic":"Goodwill impairment testing","question":"Goodwill has no independent cash inflows. How is it incorporated into impairment testing?","choices":["Value goodwill alone from its historical purchase amount.","Allocate it only according to legal-entity net assets.","Allocate it to appropriate units or groups benefiting from acquisition synergies.","Allocate it to whichever units currently report the highest profit."],"correct_index":2,"explanation":"Goodwill is allocated to appropriate CGUs or groups expected to benefit from the combination. Compare their carrying amounts including allocated goodwill with recoverable amounts. Testing is annual and when indicators arise, rather than based on an isolated goodwill cash stream.","set":1},{"id":"cr-s12-q9","session":12,"topic":"Order of testing within a CGU with goodwill","question":"Individual assets within a goodwill-bearing CGU require impairment testing at the same time as the CGU. What is the testing order?","choices":["Test goodwill alone before the other assets.","Test the relevant individual assets before the CGU including goodwill.","Use no sequence and compare every amount simultaneously.","Test only the largest individual asset."],"correct_index":1,"explanation":"First recognise any required individual-asset losses, then test the CGU including goodwill on the updated carrying amounts. This testing sequence differs from allocating a unit loss, where goodwill absorbs the loss first.","set":1},{"id":"cr-s12-q10","session":12,"topic":"Impairment loss allocation order within a CGU","question":"A cash-generating unit carries goodwill of €150,000, development costs of €250,000 and property, plant and equipment of €500,000. Its recoverable amount is €630,000. The property, plant and equipment has a fair value less costs of disposal of €430,000, no individual value in use can be determined for it, and the development costs have no measurable fair value or value in use. What amount of the impairment loss is allocated to development costs?","choices":["€40,000","€50,000","€75,000","€70,000"],"correct_index":1,"explanation":"Total loss = 900,000 − 630,000 = €270,000. IAS 36 allocates it first to goodwill (€150,000), then pro rata over the other assets: development costs 120,000 × 250/750 = €40,000 and property, plant and equipment 120,000 × 500/750 = €80,000. The floor for property, plant and equipment is €430,000, the highest of its fair value less costs of disposal, its value in use (not determinable) and zero, so it absorbs only €70,000. The €10,000 excess is reallocated to development costs, which have no floor of their own: 40,000 + 10,000 = €50,000. €40,000 stops before the floor reallocation, €75,000 spreads the whole loss over all assets including goodwill, €70,000 is the property, plant and equipment allocation.","set":1},{"id":"cr-s12-q11","session":12,"topic":"Floor test during allocation","question":"During CGU impairment allocation, an asset has €46 million measurable fair value less disposal costs and €58 million determinable value in use. Its carrying amount before allocation is €70 million. What is the relevant floor?","choices":["Nil","€70 million unchanged","€46 million","€58 million"],"correct_index":3,"explanation":"The floor is the highest of measurable fair value less disposal costs, determinable value in use and zero. Here that is €58m. The unit allocation cannot reduce this asset below that amount, even if an unconstrained pro-rata allocation would do so.","set":1},{"id":"cr-s12-q12","session":12,"topic":"Reversing a goodwill impairment","question":"A CGU's prospects improve after goodwill allocated to it was impaired. What happens to the previously recognised goodwill loss?","choices":["It is not reversed.","It is reversed whenever unit headroom appears.","It is reversed if the original forecast assumptions improve.","It is reversed through OCI instead of profit."],"correct_index":0,"explanation":"IAS 36 prohibits reversal of goodwill impairment. The later improvement can reflect internally generated goodwill rather than restoration of the originally acquired amount. Other assets' reversal rules do not remove this prohibition.","set":1},{"id":"cr-s12-q13","session":12,"topic":"Reversal ceiling for non-goodwill assets","question":"Changed estimates justify reversing a past impairment on a cost-model machine. Apart from current recoverable amount, what ceiling limits the restored carrying amount?","choices":["The depreciated amount that would exist today without the impairment","Current market price regardless of the depreciation path","The original impairment loss without allowing for later depreciation","Original acquisition cost without elapsed depreciation"],"correct_index":0,"explanation":"The restored amount cannot exceed the carrying amount that would have existed after normal depreciation if no impairment had occurred. Current recoverable amount is also a limit. Original cost or the original loss alone is not the current ceiling.","set":1},{"id":"cr-s12-q14","session":12,"topic":"Corporate assets","question":"A headquarters asset cannot reasonably be allocated to one CGU but can be allocated consistently to a small group of CGUs. What test sequence addresses it?","choices":["Test the CGU without that allocation, then the smallest appropriate group including headquarters.","Force an equal allocation to individual units despite its being unreasonable.","Ignore headquarters because it has no independent inflows.","Test headquarters only at disposal value."],"correct_index":0,"explanation":"First test the unit without the unallocable corporate asset. Then test the smallest group to which headquarters can reasonably and consistently be allocated. Corporate assets cannot simply disappear from the recoverability assessment.","set":1},{"id":"cr-s13-q1","session":13,"topic":"Step acquisition to control","question":"A group has held 50% of a joint venture for years and accounts for its stake as a single equity-method investment line. It then buys the remaining 50% and obtains control. What changes in the group accounts at the acquisition date?","choices":["The equity-method line stays, and the newly bought half is added alongside it as a second investment line carried at cost","Only the newly purchased half of the target's assets and liabilities enters the consolidation line by line","The equity-method line is replaced by full line-by-line consolidation, and the previously held stake is remeasured at fair value through profit or loss","Nothing changes until the target's own next reporting date, when consolidation of the target begins"],"correct_index":2,"explanation":"Buying the remaining 50% moves the holding from joint control to control: a step acquisition under IFRS 3. The equity-method line is derecognised, the previously held interest is remeasured at fair value through profit or loss, and the whole target is consolidated line by line. Stakes do not accumulate as parallel investment lines, consolidation is not limited to the slice just bought, and control takes effect at the acquisition date rather than the target's next year end.","set":1},{"id":"cr-s13-q2","session":13,"topic":"Balance sheet impact","question":"After buying full control of its Chinese stent joint venture, a medical device group sees goodwill and other intangible assets move from about 4% to about 62% of its total assets. Why does that shift matter for the impairment review?","choices":["The shift is purely presentational and leaves impairment testing unaffected","The increase is itself an impairment charge that must be recognised immediately in profit or loss","The new asset mix proves the acquisition created value for the group's shareholders","Most of the asset base now rests on forecast-driven values that must be tested for recovery"],"correct_index":3,"explanation":"Goodwill and intangibles from acquisitions rest on allocation choices, useful lives and forecast assumptions. When they grow from 4% to 62% of total assets, most of the balance sheet depends on values IAS 36 requires to be tested for recoverability.","set":1},{"id":"cr-s13-q3","session":13,"topic":"Identifiable intangibles versus goodwill","question":"In a purchase price allocation, an acquirer separately values the target's customer relationships at US$130 million and recognises goodwill of US$600 million. Why can the customer relationships appear as a separate intangible asset instead of sitting inside goodwill?","choices":["Because every asset bought in a business combination must be shown outside goodwill","Because they are identifiable, so they are recognised apart from the residual goodwill","Because the target had already capitalised them in its own statement of financial position","Because finite-lived intangibles are prohibited from forming part of goodwill"],"correct_index":1,"explanation":"An acquired intangible is recognised separately when it is identifiable, meaning it is separable or arises from contractual or legal rights; customer relationships can qualify on that basis. Goodwill remains the residual of the allocation. No prior book balance in the target is required, the finite life drives amortisation rather than separateness, and not everything acquired qualifies for separate recognition.","set":1},{"id":"cr-s13-q4","session":13,"topic":"Why customer relationships could be recognised","question":"Customer relationships acquired in a business combination meet identifiability and other relevant conditions. Why can they be separately recognised even though a company's internally generated customer list is prohibited?","choices":["Acquisition permits qualifying identifiable assets to be recognised at fair value.","The deal allows every future marketing cost to be capitalised.","The target must first have recorded them in its own accounts.","Each customer relationship must be individually saleable."],"correct_index":0,"explanation":"The acquisition route allows recognition of qualifying identifiable customer relationships at acquisition-date fair value. It does not require an old target book balance, nor does it convert all internal spending into assets. Identifiability remains necessary, as stated in the question.","set":1},{"id":"cr-s13-q5","session":13,"topic":"Land use rights amortisation timing","question":"At its 31 March 2012 reporting date, a group reports land use rights of US$4.932 million on which no amortisation has been charged. The lease period for these rights starts on 1 April 2012. What explains the absence of amortisation?","choices":["Land use rights are permanently exempt from any amortisation charge under IAS 38","They are not yet available for use, because the lease starts after year end","The rights are tied up in unresolved ownership litigation at year end","Management revalued the rights upward precisely to avoid amortisation"],"correct_index":1,"explanation":"Amortisation begins when the asset is available for use. The lease period starts after the reporting date, so no amortisation is due yet. The rights are still tested annually for impairment while unavailable for use.","set":1},{"id":"cr-s13-q6","session":13,"topic":"Goodwill residual measurement","question":"For a simple 100% business acquisition with no previously held stake and no non-controlling interest, how is positive goodwill measured at the acquisition date?","choices":["Consideration transferred minus the fair value of the identifiable net assets acquired","Consideration transferred minus the book value of the target's net assets","Fair value of the identifiable net assets minus the consideration transferred","Consideration transferred minus the target's net assets including the goodwill it already carried"],"correct_index":0,"explanation":"Goodwill is the residual once identifiable net assets are measured at acquisition-date fair value: consideration transferred minus that fair value. Using the target's book values, or the net assets including the target's own previously carried goodwill, mismeasures the residual, and inverting the subtraction would describe a bargain purchase gain rather than positive goodwill.","set":1},{"id":"cr-s13-q7","session":13,"topic":"Allocating an impairment charge across units","question":"A group carries goodwill in four cash-generating units and reports a total goodwill impairment of US$12 million. Testing shows recoverable shortfalls in three long-established units, while the unit acquired this year still shows headroom above its carrying amount. How is the charge presented?","choices":["It is spread evenly across the four units to keep their margins comparable","It is charged entirely to the newly acquired unit, which carries the most goodwill","It is held at group level unallocated, because goodwill is a group-level asset","It is allocated to the three units whose recoverable amounts fell below their carrying amounts"],"correct_index":3,"explanation":"IAS 36 impairment is recognised unit by unit, wherever carrying amount exceeds recoverable amount. Headroom in the newest unit means no charge arises there, whatever its size or its share of total goodwill. Spreading the charge evenly, blaming the newest unit by default, or holding it unallocated at group level all misstate which units actually lost value.","set":1},{"id":"cr-s13-q8","session":13,"topic":"Value-in-use inputs","question":"A group builds a value-in-use model for a cash-generating unit under IAS 36. Which input set is internally consistent with the standard?","choices":["Five-year budgets, cash flows beyond extrapolated at 8% while the long-term market average is 2% and no higher rate is justified, discounted at a 12% pre-tax rate","Five-year budgets, cash flows beyond extrapolated at 2% within the long-term market average, discounted at a 12% pre-tax rate","Five-year pre-tax cash flows discounted at a 12% post-tax rate, for consistency with the tax charge","Five-year budgets plus the cash inflows expected from a planned enhancement of the unit's main asset, discounted at a 12% pre-tax rate"],"correct_index":1,"explanation":"Value in use discounts pre-tax cash flows at a pre-tax rate. Projections rest on the most recent budgets, extrapolated beyond the budget period at a steady or declining growth rate unless an increasing rate can be justified, and cash flows are estimated for the asset in its current condition. Extrapolating at 8% against a 2% long-term average with no justification overstates the terminal value, a post-tax rate mismatches pre-tax flows, and expected enhancement inflows do not belong in a current-condition estimate.","set":1},{"id":"cr-s13-q9","session":13,"topic":"Reliability of a no-impairment conclusion","question":"A discounted cash flow model supports a no-impairment conclusion for a recently acquired cash-generating unit. Why does that conclusion still require judgement?","choices":["The historical acquisition price automatically proves recoverability","Management is free to choose a goodwill amortisation rate instead","It depends on forecast performance, growth and discount assumptions","The acquisition-date allocation permanently fixes the recoverable amount"],"correct_index":2,"explanation":"A discounted cash flow conclusion depends on supported future cash flow and discount assumptions. Changing those estimates can consume headroom, so the conclusion carries judgement and uncertainty, and sensitivity analysis matters.","set":1},{"id":"cr-s13-q10","session":13,"topic":"Market capitalisation as a cross-check","question":"A group's net-asset book value exceeds its market capitalisation. Why does that matter in an IAS 36 review?","choices":["It fixes the exact amount of the goodwill loss to recognise","It replaces all unit-level testing with quoted share prices","It requires a loss equal to the entire market-value gap","It supplies an external indicator of possible impairment"],"correct_index":3,"explanation":"A market capitalisation below net-asset book value is an external indicator of possible impairment that triggers further analysis. Recognised impairment still depends on carrying and recoverable amounts at unit level.","set":1},{"id":"cr-s13-q11","session":13,"topic":"Acquisition multiple is not proof","question":"The price paid for an additional 50% of a business equals about 25 times the buyer's share of the target's historical profit for the year. What can that high earnings multiple establish by itself?","choices":["The exact impairment amount through a mandatory formula","Conclusive proof of overpayment under a mandatory IAS 36 threshold","A full replacement for any future cash-flow analysis","A valuation discussion point, not conclusive proof of overpayment"],"correct_index":3,"explanation":"A high historical multiple may challenge the assumptions needed to justify the price, but it is not an IFRS impairment threshold. Expected growth, risks and comparability all matter, and impairment is measured from recoverable amount, not from a past multiple.","set":1},{"id":"cr-s14-q1","session":14,"topic":"Provision recognition test","question":"Which combination of conditions is required before an IAS 37 provision is recognised?","choices":["A firm intention to spend, a probable outflow and a reliable estimate","A present obligation from a past event, a merely possible outflow and an unreliable estimate","A future obligation, a certain outflow and an exact amount","A present obligation from a past event, a probable outflow and a reliable estimate"],"correct_index":3,"explanation":"Recognition needs all three: a present obligation, legal or constructive, arising from a past event; a probable outflow of resources; and a reliable estimate. A mere intention to spend is not an obligation, a possible outflow or the absence of a reliable estimate leads to contingent-liability disclosure instead, and certainty with an exact amount is not the threshold.","set":1},{"id":"cr-s14-q2","session":14,"topic":"Legal versus constructive obligation","question":"Which situation creates a constructive obligation rather than a legal one?","choices":["A binding statute or a signed contract requires the payment to be made","An established public commitment creates a valid expectation in those affected","A future court decision is merely anticipated by management and advisors","Directors privately discuss adopting a cleanup policy next year"],"correct_index":1,"explanation":"A constructive obligation arises when published policy or established practice creates a valid expectation in other parties that the entity will act. A statute or contract creates a legal obligation instead. Anticipating a court outcome and holding private boardroom discussions create no expectation in anyone outside the entity.","set":1},{"id":"cr-s14-q3","session":14,"topic":"Contaminated land example","question":"A company has polluted land. No law requires cleanup, but its published commitment and established conduct create a valid expectation of cleanup. Outflow is probable and costs reliably estimable. Why recognise a provision?","choices":["The past contamination and conduct create a constructive obligation.","A voluntary policy is automatically a statute.","Only disclosure is allowed without a legal duty.","Recognition must wait until cleanup cash is paid."],"correct_index":0,"explanation":"The qualifying present obligation can be constructive. These facts establish the expectation plus probable outflow and reliable measurement. Legal enforceability is not required in every provision case, though a vague promise alone would not establish the expectation.","set":1},{"id":"cr-s14-q4","session":14,"topic":"Uncertainty spectrum","question":"In a simplified spectrum from ordinary accrued liabilities through provisions to contingencies, which item generally carries the greatest uncertainty?","choices":["An accrued expense payable","A recognised provision","A contingent liability requiring assessment","An ordinary recognised payable of fixed amount"],"correct_index":2,"explanation":"A contingent liability may be only a possible obligation, or a present obligation that fails outflow or reliable-estimate recognition conditions. A provision is recognised despite timing or amount uncertainty, while an ordinary payable is typically more definite.","set":1},{"id":"cr-s14-q5","session":14,"topic":"Where each item is reported","question":"A present obligation probably requires settlement, but no reliable estimate can be made. How is it treated under IAS 37?","choices":["Recognise a provision despite no reliable estimate.","Disclose a contingent liability rather than recognise a provision.","Recognise a fixed accrued liability instead.","Omit all mention because measurement is uncertain."],"correct_index":1,"explanation":"Reliable estimation is a provision condition. In the rare case where no reliable estimate is possible, the matter is disclosed as a contingent liability rather than recognised. Uncertainty does not automatically justify silence.","set":1},{"id":"cr-s14-q6","session":14,"topic":"Measuring one-off events","question":"For one individual lawsuit, the most likely settlement also represents the supported best estimate after considering other outcomes. No other outcome materially changes it. What amount is used for the provision?","choices":["The most likely settlement in this stated case","The maximum payout regardless of likelihood","A large-population warranty formula regardless of this case","The minimum payout regardless of likelihood"],"correct_index":0,"explanation":"For a single obligation the most likely outcome may be the best estimate, as expressly established here. Other outcomes still need consideration when they materially affect the estimate. This is not a universal instruction to ignore the distribution in every lawsuit.","set":1},{"id":"cr-s14-q7","session":14,"topic":"Warranty expected value worked example","question":"A large assurance-warranty population has 80% expected no defects, 15% minor and 5% major defects. Repair cost would be €2 million if every product had minor defects or €5 million if every product had major defects. Ignore discounting. What provision is measured?","choices":["€550,000","€5 million","€300,000","€2 million"],"correct_index":0,"explanation":"Expected cost is 80% × nil + 15% × €2m + 5% × €5m = €550,000. Use the weighted population cost rather than the most likely no-defect outcome or the worst-case total. The supplied totals already cover the whole population.","set":1},{"id":"cr-s14-q8","session":14,"topic":"Present value of a provision","question":"A long-term obligation has a material time-value effect. What initial measurement and later time-passage treatment are appropriate?","choices":["Present value, with later unwind deducted directly from equity","Undiscounted settlement, then discount only on payment","Market value, with every change called interest","Present value initially, with discount unwind as finance cost"],"correct_index":3,"explanation":"Discount future settlement when time value is material. As settlement approaches, unwinding raises the liability and is finance cost. A changed settlement estimate or discount rate is a separate remeasurement, not automatically all time-passage expense.","set":1},{"id":"cr-s14-q9","session":14,"topic":"Expected disposal gains and provisions","question":"A company measures a provision for settling an obligation at its best estimate of €1,000,000. It also expects a €200,000 gain on selling surplus equipment next year. At what amount is the provision measured?","choices":["€800,000","€1,200,000","€1,000,000","€200,000"],"correct_index":2,"explanation":"IAS 37 measures the provision at the best estimate of the expenditure required to settle the obligation, and expected gains on the disposal of assets are not taken into account in that measurement. €800,000 nets the gain against the obligation, €1,200,000 adds it, and €200,000 confuses the expected disposal gain with the settlement itself.","set":1},{"id":"cr-s14-q10","session":14,"topic":"Future operating losses","question":"Management forecasts future operating losses without a present obligation for those losses. What response is appropriate?","choices":["Do not provide, but assess related impairment indicators.","Recognise a provision when the operating budget is approved.","Disclose the whole forecast as a contingent liability without a past obligation.","Write down assets by the forecast total without measuring recovery."],"correct_index":0,"explanation":"Future operating losses are not provisions because they do not represent a present obligation. Their forecast may indicate asset impairment, which requires an IAS 36 test rather than a mechanical deduction of the budgeted loss.","set":1},{"id":"cr-s14-q11","session":14,"topic":"Onerous contract measurement","question":"A retailer is locked into a warehouse lease it no longer uses. The unavoidable rentals under the contract are €400,000 and the penalty for terminating early is €250,000, with no expected sublease income. What does IAS 37 require?","choices":["A provision of €250,000, the lower of the cost of fulfilling and the cost of exiting the contract","A provision of €400,000, the full unavoidable cost of remaining in the contract","No provision, because the lease payments fall due only in future periods","A provision of €150,000, the difference between the two measures"],"correct_index":0,"explanation":"The contract is onerous because its unavoidable costs exceed the economic benefits expected from it. IAS 37 measures the provision at the lower of the net cost of fulfilling the contract and the penalty for failing to fulfil it, here €250,000. Taking the full €400,000 ignores the cheaper exit route, the future timing of the payments does not remove the present obligation, and €150,000 is a difference between measures rather than a measure of either.","set":1},{"id":"cr-s14-q12","session":14,"topic":"Restructuring provision recognition","question":"A company has a detailed formal restructuring plan. What action can create the required valid expectation among those affected?","choices":["Keeping it in confidential board minutes","Adding expected severance to an internal draft budget","Discussing several options without committing","Starting implementation or announcing the main features to affected people"],"correct_index":3,"explanation":"The plan must be accompanied by a valid expectation that it will be carried out. Implementation or communication of its main features can create that expectation. Private deliberations or an internal budget alone normally do not.","set":1},{"id":"cr-s14-q13","session":14,"topic":"Restructuring provision scope","question":"Which cost belongs in a qualifying restructuring provision?","choices":["Retraining employees who remain in the business","Direct unavoidable restructuring expenditure unrelated to continuing activities","Marketing future products of the continuing business","Building a new distribution network for continuing operations"],"correct_index":1,"explanation":"Include only direct costs necessarily entailed by restructuring and not associated with ongoing activities. Training, marketing and a new network concern future operations. Their presence in one restructuring budget is insufficient for provision recognition.","set":1},{"id":"cr-s14-q14","session":14,"topic":"Contingent asset disclosure","question":"A possible legal recovery has a probable inflow, but realisation is not virtually certain. What is the IAS 37 treatment?","choices":["Recognise an asset at the expected amount.","Neither recognise nor disclose it.","Disclose the contingent asset without recognising it.","Recognise the expected gain immediately in profit."],"correct_index":2,"explanation":"Probable contingent-asset inflows are disclosed but not recognised. When realisation becomes virtually certain, the item is no longer contingent and asset recognition is appropriate. The normal provision outflow threshold cannot simply be copied to uncertain gains.","set":1},{"id":"cr-s16-q1","session":16,"topic":"Right to control test","question":"A coffee chain signs a five-year contract for the exclusive use of a specified retail unit in a shopping centre. Under IFRS 16, which two rights must the chain have throughout the period of use for the contract to contain a lease?","choices":["The right to obtain substantially all economic benefits from using the unit only","The right to decide how and for what purpose the unit is used only","Both the right to obtain substantially all economic benefits from use and the right to direct how and for what purpose the unit is used","The right to buy the unit at the end of the contract"],"correct_index":2,"explanation":"IFRS 16 treats a contract as a lease only if the customer controls the use of an identified asset. Control requires both rights together: obtaining substantially all the economic benefits from use and directing how and for what purpose the asset is used. Holding only one of the two is not enough.","set":1},{"id":"cr-s16-q2","session":16,"topic":"Why firms lease","question":"A treasurer argues for leasing equipment rather than buying it with a loan. Which argument reflects a genuine commercial reason for leasing, rather than an accounting artifact?","choices":["The lease can finance the full cost at fixed rentals, with no down payment and often lighter covenants than a loan","The lease keeps the asset off the balance sheet, which lowers reported leverage","Leasing usually costs less than buying the same asset over its whole useful life","Lease rentals are operating costs, so they never affect the balance sheet"],"correct_index":0,"explanation":"The commercial reasons for leasing are full financing at fixed payments, protection against obsolescence and flexibility through lighter covenants. Off balance sheet treatment was an accounting consequence, removed for lessees by IFRS 16, and leasing is not generally cheaper than buying over the whole life of the asset.","set":1},{"id":"cr-s16-q3","session":16,"topic":"IAS17 dual model","question":"Under IAS 17, the standard that IFRS 16 replaced, what made a lease a finance lease?","choices":["The presence of a renewal option, whatever the economics of the contract","A lease term longer than twelve months, whatever the economics of the contract","A transfer to the lessee of substantially all the risks and rewards of ownership","A low value for the underlying asset, whatever the contract says"],"correct_index":2,"explanation":"IAS 17 applied a dual model based on substance over legal form. A lease that transferred substantially all the risks and rewards of ownership was a finance lease and was capitalised. Other leases were operating leases and stayed off the balance sheet, whatever their term or their options.","set":1},{"id":"cr-s16-q4","session":16,"topic":"IFRS16 single model","question":"For a lessee applying IFRS 16, what has replaced the old finance versus operating lease classification test?","choices":["A single model: the lessee recognises a right of use asset and a lease liability for all leases, apart from the short term and low value exemptions","A single model that applies only to finance leases, while operating leases stay off balance sheet","The lessor's classification, mirrored in the lessee's own financial statements","A fair value model in which all later changes in the right of use pass through profit or loss"],"correct_index":0,"explanation":"IFRS 16 removed the lessee classification test. Except for short term leases of 12 months or less and leases of low value assets, the lessee recognises a right of use asset and a lease liability at commencement. The dual model survives only in lessor accounting.","set":1},{"id":"cr-s16-q5","session":16,"topic":"Lessor accounting","question":"How did lessor accounting change when IFRS 16 replaced IAS 17?","choices":["It was substantially unchanged: lessors still classify leases as finance or operating, with additional disclosure about the risks in their residual interest","Lessors adopted the lessee single model and now recognise a right of use asset instead of the underlying asset","The finance versus operating distinction was abolished, but only for leases signed after 2019","Lessors keep the asset on their balance sheet for every lease and record all payments as operating income"],"correct_index":0,"explanation":"IFRS 16 targeted lessee accounting. Lessor accounting kept the IAS 17 classification principles: a finance lease transfers substantially all risks and rewards and produces a receivable, while an operating lease keeps the asset recognised. The main novelty is wider disclosure on residual value risk.","set":1},{"id":"cr-s16-q6","session":16,"topic":"Motivation for the change","question":"Before IFRS 16, operating leases stayed off the balance sheet. According to the course, how did analysts commonly estimate this hidden lease debt?","choices":["By capitalising the whole undiscounted schedule of future commitments, ignoring timing","By adding one single year of rental expense to debt as the full adjustment","By treating the fair value of the lessor's asset as the lessee's entire lease debt","By using a rule of thumb such as eight times the annual lease expense"],"correct_index":3,"explanation":"The course describes the common practice of estimating the lease liability at about eight times annual lease expense, and interest at about one third of lease expense. These were analyst shortcuts to reverse engineer off balance sheet debt, not IFRS measurement rules.","set":1},{"id":"cr-s16-q7","session":16,"topic":"Three goals of the reform","question":"Which set of objectives does the course attribute to the lease accounting reform?","choices":["Identical treatment for lessees and lessors, one depreciation rate for all assets and the end of renewal judgements","More precise cash totals, the disappearance of rent payments and cheaper financing","Less disclosure, compulsory ownership transfer and uniform legal titles","Faithful representation of lease assets and obligations, better comparability and fewer opportunities for off balance sheet manipulation"],"correct_index":3,"explanation":"The reform aims at substance over legal form, comparability between firms that lease and firms that buy, and less scope for hiding financing off balance sheet. Ratio changes such as higher leverage are consequences of the reform, not its stated objectives.","set":1},{"id":"cr-s16-q8","session":16,"topic":"Recognition vs disclosure literature","question":"The course cites research comparing amounts recognised on the balance sheet with amounts only disclosed in the notes. What is the general finding?","choices":["Disclosed amounts weigh more, because note detail can replace recognition","Recognised amounts tend to be more relevant to investors than merely disclosed ones","Both carry exactly the same weight once the figure appears anywhere in the report","Recognition becomes irrelevant as soon as analysts can build their own adjustment from the notes"],"correct_index":1,"explanation":"Studies on stock options, post retirement benefits, derivatives and investment property generally find that recognised values explain stock prices better than disclosed values. This is a typical empirical result, not a law that holds for every investor.","set":1},{"id":"cr-s16-q9","session":16,"topic":"Real effects of capitalisation","question":"According to Ma and Thomas (2023), cited in the course, how did firms change their behaviour once lease capitalisation became mandatory?","choices":["Fewer long term operating leases, more short term leases and more capital expenditure","More long term operating leases, fewer short term leases and less capital expenditure","Fewer leases of every kind and less capital expenditure","More leases of every kind and more capital expenditure"],"correct_index":0,"explanation":"Ma and Thomas document substitution: firms cut long term operating leases, shifted toward short term leases and bought more assets outright. Recognition rules changed real contract choices, not just presentation.","set":1},{"id":"cr-s16-q10","session":16,"topic":"Real effects, fixed vs variable payments","question":"A retailer pays a fixed monthly rent for a store plus a percentage of monthly sales, with no minimum amount. Which part enters the initial lease liability under IFRS 16?","choices":["Both parts, because every payment due under the contract is a lease payment","Neither part, because variable payments keep the whole contract out of the liability","Only the fixed rent, because genuinely sales based payments do not depend on an index or a rate","Only the sales based part, because variable payments are more predictable than fixed ones"],"correct_index":2,"explanation":"The lease liability covers fixed payments, in substance fixed payments and variable payments that depend on an index or a rate. A genuine percentage of sales with no floor stays out of the initial liability and is expensed as the sales occur. Heese et al. (2025), cited in the course, find that firms shifted toward such variable payments after the reform.","set":1},{"id":"cr-s16-q11","session":16,"topic":"Costs of lease capitalisation","question":"What real effects does Chen et al. (2023), cited in the course, attribute to the introduction of the new lease capitalisation rules?","choices":["Higher investment, profitability and employment, concentrated in financially distressed firms","Lower investment, profitability and employment, with stronger effects for lease intensive and financially distressed firms","Lower investment in unconstrained firms only, with no profitability or employment effects","No change in investment, only a different presentation of expenses"],"correct_index":1,"explanation":"Chen et al. report that capitalisation was costly: investment, profitability and employment fell on average, and the effect was strongest where leases mattered most and where firms were financially distressed.","set":1},{"id":"cr-s16-q12","session":16,"topic":"First response to capitalisation historically","question":"When an earlier rule forced finance leases onto the balance sheet, many firms shifted to operating leases and to financing outside any lease. A new standard now forces those operating leases onto the balance sheet too. What does the same contract design logic predict?","choices":["Little change, because accounting recognition does not alter real financing decisions","A new round of structuring, toward shorter terms or arrangements that fall outside the lease definition","A shift from leasing to outright purchase, whatever the financing and flexibility cost","The same contracts kept in place, with the classification argued in the notes instead"],"correct_index":1,"explanation":"Contract design responds to recognition rules: the documented reaction to the earlier rule was substitution toward whatever stayed unrecognised. Disclosure cannot repair classification, buying has real costs that explain why firms leased in the first place, and recognition does change financing decisions, which is exactly why firms pay to structure around it.","set":1},{"id":"cr-s16-q13","session":16,"topic":"Common exam trap","question":"A student concludes that because IFRS 16 imposes a single model on lessees, lessors no longer classify leases either. What is wrong with this conclusion?","choices":["Nothing: lessor classification follows the lessee whenever a right of use asset is recognised","The single model applies to lessees only, and lessors keep the finance versus operating classification","Lessors use the single model for new leases but still apply IAS 17 to older contracts","Lessors may freely pick either model as an accounting policy choice for each class of assets"],"correct_index":1,"explanation":"IFRS 16 changed lessee accounting, not the lessor framework. A lessor still asks whether substantially all risks and rewards of ownership have transferred and classifies the lease as finance or operating accordingly.","set":1},{"id":"cr-s17-q1","session":17,"topic":"Recognition exemptions","question":"IFRS 16 lets a lessee skip recognising a right of use asset and a lease liability for two categories of leases. Which two?","choices":["Leases of real estate and leases of production equipment","Leases of twelve months or less and leases of low value assets","Leases between related parties and leases with third parties","Leases with a purchase option and leases of other equipment"],"correct_index":1,"explanation":"The recognition exemptions cover short term leases of twelve months or less and leases whose underlying asset is of low value, such as a laptop or small office furniture. A lease with a purchase option cannot be short term. The exemption is an election, expensed straight line, not an obligation.","set":1},{"id":"cr-s17-q2","session":17,"topic":"Lease term anti-avoidance","question":"A lessee holds a renewal option it is reasonably certain to exercise. Why does IFRS 16 add that optional period to the lease term?","choices":["To make lease payments look cheaper than buying the asset","Because every renewal option is legally non cancellable from inception","Because management is allowed to ignore renewals once classification is done","To reflect the expected period of use and stop firms from structuring artificially short leases"],"correct_index":3,"explanation":"Without this rule, a company could sign a one-year lease with rolling renewal options and keep the liability tiny. The lease term includes extension periods the lessee is reasonably certain to use, so the liability reflects the real expected commitment.","set":1},{"id":"cr-s17-q3","session":17,"topic":"ROU asset initial cost","question":"Which of the following is not part of the initial cost of the lessee's right of use asset?","choices":["The initial measurement of the lease liability","The price the lessor paid to buy the underlying asset","Lease payments made at or before the commencement date","Initial direct costs incurred by the lessee"],"correct_index":1,"explanation":"The cost of the right of use asset combines the initial lease liability, payments made at or before commencement net of incentives received, the lessee's initial direct costs and any estimated restoration obligation. What the lessor originally paid for the asset never enters the lessee's measurement.","set":1},{"id":"cr-s17-q4","session":17,"topic":"Lease liability initial measurement","question":"A lease includes fixed rentals, payments linked to an inflation index, amounts expected under a residual value guarantee, and extra payments that depend purely on how much the asset is used. Which of these stays out of the initial lease liability?","choices":["The genuinely usage based payments","The fixed rental payments due after commencement","The variable payments linked to the inflation index","The amounts expected under the residual value guarantee"],"correct_index":0,"explanation":"The initial liability includes fixed payments, variable payments tied to an index or a rate, expected residual value guarantee payouts, purchase option exercise prices and termination penalties where relevant. Payments that vary purely with usage, with no floor, are expensed as they arise instead.","set":1},{"id":"cr-s17-q5","session":17,"topic":"Subsequent measurement of the lease liability","question":"No remeasurement or modification occurs during a lease. How is interest on the lease liability calculated each period?","choices":["By applying the current market rate each year to the original payment schedule","By applying the implicit rate to the original principal for the whole term","By applying the original rate only to the cash payments, not the balance","By applying the original discount rate to the remaining liability balance"],"correct_index":3,"explanation":"IFRS 16 requires a constant periodic rate of interest on the remaining balance of the liability, using the rate that measured the liability initially. Interest is therefore higher early on and falls as the liability is repaid. A revised rate is needed only for specific remeasurements or modifications.","set":1},{"id":"cr-s17-q6","session":17,"topic":"Income statement presentation","question":"A lessee wants to show one single lease expense line in its income statement, combining right of use depreciation and interest on the lease liability. Is that allowed?","choices":["No, depreciation and interest must remain separately identifiable","Yes, if management finds the combined figure more useful internally","Yes, if the notes confirm that the single line equals interest plus depreciation","Yes, if the lessor treats the same agreement as an operating lease"],"correct_index":0,"explanation":"IFRS 16 requires interest expense on the lease liability to be presented separately from depreciation of the right of use asset. Interest is a finance cost. The rule does not require every depreciation item to have a separate face line: it may be included in the relevant depreciation or functional expense presentation. A single undifferentiated lease expense would hide the required distinction.","set":1},{"id":"cr-s17-q7","session":17,"topic":"Cash flow statement classification","question":"Where does a lessee present the principal portion of its lease payments in the cash flow statement? Apply IAS 7 before the IFRS 18 amendments, without early applying those amendments.","choices":["Within cash flows from operating activities","Within cash flows from investing activities","Within cash flows from financing activities","Nowhere, because lease payments are not cash flows"],"correct_index":2,"explanation":"Repaying the principal of a lease liability is a financing outflow, like repaying a loan. Only the interest portion can go to operating or financing, following the company's IAS 7 policy for interest paid.","set":1},{"id":"cr-s17-q8","session":17,"topic":"Lessor accounting by lease type","question":"A lessor classifies a lease as an operating lease. What happens to the underlying asset and to the rental income?","choices":["The asset is derecognised and replaced by a net investment receivable","The asset stays on the balance sheet and rental income is recognised over the lease term","The asset stays on the balance sheet but the whole rental stream is recognised as income at commencement","The asset is replaced by a right of use asset matching the lessee's liability"],"correct_index":1,"explanation":"In an operating lease the lessor keeps the risks and rewards, so the asset stays in its books and keeps being depreciated. The rentals are recognised as income, normally straight line over the lease term. Derecognition and a receivable belong to finance leases.","set":1},{"id":"cr-s17-q9","session":17,"topic":"Lessor finance lease accounting","question":"A lessor classifies a lease as a finance lease. What happens to the underlying asset in its accounts?","choices":["It is derecognised and replaced by a receivable equal to the net investment in the lease","It stays on the balance sheet next to a new right of use asset for the retained interest","It stays recognised, and the full undiscounted rental stream is booked as income immediately","It stays recognised, and a receivable for the full rental stream is added on top"],"correct_index":0,"explanation":"A finance lease transfers substantially all risks and rewards to the lessee, so the lessor derecognises the asset and recognises a receivable at the present value of the lease payments plus any unguaranteed residual value accruing to it. Finance income is then recognised at a constant rate on that net investment.","set":1},{"id":"cr-s17-q10","session":17,"topic":"Financial statement effects, EBITDA","question":"A lease that used to be treated as an operating lease is now capitalised under IFRS 16. Why does EBITDA typically rise?","choices":["Because the cash rent payments fall by the amount of the new depreciation","Because interest becomes operating revenue instead of a financing expense","Because the rent expense disappears from operating expenses and is replaced by depreciation and interest, both excluded from EBITDA","Because depreciation reduces the lease liability instead of hitting any income statement subtotal"],"correct_index":2,"explanation":"Under the old treatment the full rent sat in operating expenses, inside EBITDA. Under IFRS 16 the same contract produces depreciation and interest, and both sit below EBITDA. The measure rises mechanically even though the cash leaving the company has not changed.","set":1},{"id":"cr-s17-q11","session":17,"topic":"Financial statement effects, profit pattern","question":"Take a capitalised lease with constant payments, straight line depreciation and no remeasurement. Early in the lease term, how does the total expense compare with the old straight line rent?","choices":["Lower, because depreciation only starts once the liability matures","Identical, because interest stays constant over the whole term","Higher, because interest is charged on a still large outstanding balance","Impossible to say, because it depends on the lessor's accounting policy"],"correct_index":2,"explanation":"Straight line depreciation is constant, but interest is calculated on the remaining liability, which is largest at the start. The total charge is therefore front loaded: higher than the old rent early in the lease and lower near the end. This is why IFRS 16 can reduce early year profits even when totals over the full term match.","set":1},{"id":"cr-s17-q12","session":17,"topic":"Common mistake, discount rate","question":"Three years into an unchanged lease, a student recalculates interest using the current market rate. No modification or remeasurement event has occurred. What is the correct approach?","choices":["Use the current market yield while keeping the future payments unchanged","Use the coupon embedded in each payment rather than any discount rate","Stop recognising interest once the remaining term drops below twelve months","Keep the discount rate that was used when the liability was first measured"],"correct_index":3,"explanation":"For an unchanged liability, interest keeps accruing at the original discount rate so that the rate stays constant on the remaining balance. Updating to market rates is only required for the specific remeasurement or modification events defined by IFRS 16, none of which occurred here.","set":1},{"id":"cr-s18-q1","session":18,"topic":"Tweedie quote","question":"A former standard setter said he hoped one day to fly in an aircraft that actually appears on the airline's balance sheet. What was he criticising?","choices":["Airlines valuing owned aircraft at historical cost instead of market value","Airlines recognising ticket revenue long before the flights take place","Airlines depreciating aircraft over lives far longer than manufacturers suggest","Airlines keeping huge aircraft commitments off balance sheet through operating leases"],"correct_index":3,"explanation":"Under IAS 17, airlines ran most of their fleets through operating leases, so neither the aircraft nor the obligation to pay for it appeared on the balance sheet. IFRS 16 was designed to end exactly this, which is why airlines became the emblematic industry of the reform.","set":1},{"id":"cr-s18-q2","session":18,"topic":"Two criticisms of IAS17","question":"Which pair of weaknesses of the old dual lease model did the move to a single on balance sheet model aim to fix?","choices":["Lessors forced to capitalise operating leases, and lessees unable to claim any depreciation","Poor comparability, and a bright line that contracts could be structured around to stay off balance sheet","Slow recognition of rental income, and no guidance on lease term for lessees","Heavy disclosure costs for lessees, and mandatory yearly fair value remeasurement of every lease"],"correct_index":1,"explanation":"Economically similar leases were reported differently, hurting comparability, and the sharp finance versus operating line invited structuring contracts to fall just on the operating side. The other options describe requirements the old standard never had.","set":1},{"id":"cr-s18-q3","session":18,"topic":"Industry impact","question":"Two listed groups are similar in size. An airline finances most of its fleet through long term operating leases, while a manufacturer owns most of its plant outright. When both first capitalise their leases, how should the changes in reported debt and EBITDA compare?","choices":["Both rise more for the manufacturer, because its owned plant is revalued at first adoption","Both rise more for the airline, because its off balance sheet commitments were large relative to its balance sheet","Debt rises more for the airline, but EBITDA rises more for the manufacturer, whose lease expense was smaller","Debt rises similarly for both, while EBITDA is unchanged, because capitalisation only grosses up the balance sheet"],"correct_index":1,"explanation":"Capitalising operating leases creates a lease liability and replaces rent with depreciation and interest, so both reported debt and EBITDA rise. The effect scales with how much activity was financed off balance sheet, which is why retailers and airlines topped the industry impact estimates discussed in the course. The lease standard does not revalue owned assets.","set":1},{"id":"cr-s18-q4","session":18,"topic":"Balance sheet effect","question":"When an airline adopted the new lease standard, property, plant and equipment rose by HKD 19,937 million while current and non current lease liabilities of HKD 4,073 million and HKD 15,894 million appeared. How should this be read?","choices":["Assets rose by about HKD 19.9 billion and lease liabilities by about HKD 20.0 billion, the two sides growing almost one for one","Assets rose by about HKD 19.9 billion while liabilities were unchanged, because rentals were still expensed","Assets fell by about HKD 19.9 billion as leased aircraft left owned assets, while liabilities rose by HKD 20.0 billion","Assets were unchanged while liabilities rose by about HKD 20.0 billion, because only debt was recognised"],"correct_index":0,"explanation":"Right of use assets and lease liabilities are recognised together, so the balance sheet grows on both sides by nearly the same amount. The two liability portions sum to 4,073 + 15,894 = 19,967, within 30 million of the asset increase, the small gap reflecting other adjustments.","set":1},{"id":"cr-s18-q5","session":18,"topic":"Income statement effect","question":"Under the new standard an airline no longer recorded operating lease rentals of HKD 4,507 million, but depreciation rose by HKD 3,849 million and finance charges by HKD 744 million. What was the effect on first year profit?","choices":["Profit was HKD 86 million higher","Profit was HKD 86 million lower","Profit was HKD 4,507 million higher","Profit was HKD 4,593 million lower"],"correct_index":1,"explanation":"The new charges total 3,849 + 744 = 4,593, against rentals saved of 4,507. The excess of 86 makes profit HKD 86 million lower than under the old rules. The gap reflects front loading: interest is highest early in a lease, so total expense exceeds straight line rent in the early years.","set":1},{"id":"cr-s18-q6","session":18,"topic":"Cash flow effect","question":"How did the new standard change Cathay Pacific's cash flow statement in 2019?","choices":["Total net cash flow was unchanged, because only the split between operating and financing activities moved","Total net cash flow fell by HKD 3,701 million, because lease repayments became new cash outflows","Total net cash flow rose by HKD 4,445 million, because rentals were no longer paid in cash","Total net cash flow rose by HKD 744 million, because interest left operating activities"],"correct_index":0,"explanation":"Cash generated from operations rose by 4,445, interest paid of 744 stayed in operating, and loan and lease repayments of 3,701 moved to financing. The same cash left the company as before. Only its classification changed, so the net total is unaffected.","set":1},{"id":"cr-s18-q7","session":18,"topic":"Ratio effects","question":"Cathay Pacific's EBITDA rose from HKD 14.7 billion to HKD 19.3 billion after adoption, while gearing went from 0.96 to 1.31. Why did EBITDA rise?","choices":["Aircraft leases were renegotiated on cheaper terms during the year","Impairment of right of use assets is excluded from EBITDA and offsets the new interest","Rent that used to sit above EBITDA was replaced by depreciation and interest that sit below it","Lease interest was reclassified into revenue, lifting sales and EBITDA together"],"correct_index":2,"explanation":"EBITDA excludes depreciation and interest. Moving the lease cost out of operating expenses into those two lines therefore lifts EBITDA mechanically, with no change in cash or in the economics of the fleet. Gearing rises at the same time because the new lease liabilities count as debt.","set":1},{"id":"cr-s18-q8","session":18,"topic":"EPS effect","question":"Cathay Pacific's EBITDA rose 31.1% under the new standard, yet EPS slipped from 43.7 to 43.0 HK cents. What explains the fall in EPS?","choices":["EPS is calculated before depreciation, so it ignored the lower rental expense","The new depreciation and finance charges slightly exceeded the rentals removed, cutting net profit by HKD 86 million","The share count rose sharply when part of the lease liability was converted into equity","The EBITDA gain was fully offset by extra tax charged on the capitalised leases"],"correct_index":1,"explanation":"EBITDA ignores the new depreciation and interest, but EPS is built on net profit. Those two charges exceeded the removed rent by HKD 86 million, so net profit and EPS edged down even as EBITDA jumped by a third.","set":1},{"id":"cr-s18-q9","session":18,"topic":"Residual value risk","question":"Under an old IAS 17 operating lease, an airline returns an aircraft at the end of the lease and it is worth less than expected. Who bears that loss? Assume no residual value guarantee, purchase obligation or other contractual exposure to the resale shortfall.","choices":["The manufacturer, through the original warranty on the aircraft's value","Both parties equally, because IAS 17 required a residual value guarantee in every lease","The lessor, because the lessee simply stops paying rent and hands the aircraft back","The lessee, because it carried the aircraft as an owned asset during the term"],"correct_index":2,"explanation":"Under the stated contract, the lessor bears the aircraft resale shortfall. This follows from the absence of a guarantee or other exposure, not from the operating lease label alone. IAS 17 classification assessed substantially all risks and rewards, not whether the lessee had absolutely no risks.","set":1},{"id":"cr-s18-q10","session":18,"topic":"Residual value risk under IFRS16","question":"Cathay Pacific's CFO argues that the new standard does not reflect how companies actually manage residual value risk. What is the substance of his objection?","choices":["Lessors must now deduct residual value losses from the depreciation they charge lessees","Lessees must now guarantee the residual value of every asset they lease","Recognition puts a potentially impaired use right on the lessee balance sheet, although the aircraft resale risk can remain with the lessor","The standard forces yearly revaluation of right of use assets through other comprehensive income"],"correct_index":2,"explanation":"This is the CFO's objection to the perceived accounting picture, not a claim that IFRS 16 transfers the aircraft's resale shortfall to the lessee. The lessee can incur impairment of its own use right under IAS 36 while the lessor bears the unguaranteed residual value of the aircraft. Those are different assets and risks. Recognition does not change their contractual allocation.","set":1},{"id":"cr-s18-q11","session":18,"topic":"Common mistakes and exam traps","question":"A colleague says Cathay Pacific's 2019 result proves that the new lease standard always lowers reported profit. Why is that conclusion wrong?","choices":["The 2019 effect was an error that Cathay Pacific corrected later","Lessee profit is never affected, because only the balance sheet changes","The standard lowers profit only in the adoption year and never afterwards","That year's outcome reflects its particular lease mix, and the sign can flip as front loaded interest declines"],"correct_index":3,"explanation":"Lease expense is front loaded: total charges exceed straight line rent early in a lease and fall below it later, because interest shrinks with the liability. One year with a given mix of new and maturing leases says nothing about a permanent direction for every company and every year.","set":1},{"id":"cr-s18-q12","session":18,"topic":"Commercial responses","question":"A lease intensive airline wants to keep some of its payments outside the IFRS 16 lease liability. Which contractual change achieves that?","choices":["Moving to payments that vary genuinely with usage rather than with an index or a rate","Replacing fixed payments with payments linked to a published inflation index","Adding a purchase option the airline is reasonably certain to exercise","Electing operating lease treatment, which IFRS 16 still offers lessees"],"correct_index":0,"explanation":"Genuinely usage based payments with no floor stay out of the lease liability and are expensed as incurred. Index linked payments and reasonably certain purchase options are included, and IFRS 16 gives lessees no operating category to elect. This is the lever behind the shift to variable leases documented by Heese et al. (2025).","set":1},{"id":"cr-s19-q1","session":19,"topic":"Tax expense formula","question":"All of a company's tax effects run through profit or loss. Current tax for the year is 28,200 and the deferred tax liability grows by 2,400. What tax expense does the income statement show?","choices":["25,800","28,200","30,600","2,400"],"correct_index":2,"explanation":"The income statement tax charge is current tax plus the movement in deferred tax. A growing deferred tax liability is a deferred tax expense, so the total is 28,200 + 2,400 = 30,600.","set":1},{"id":"cr-s19-q2","session":19,"topic":"Permanent differences","question":"A company pays a regulatory fine that tax law never allows as a deduction. What does this do to deferred tax?","choices":["Nothing: the difference never reverses, so it affects only the current tax of that year","Deferred tax is recognised now and released in the year the fine is paid","A deferred tax asset arises, because the fine will cut taxable profit later","A deferred tax liability arises, because the expense was booked before becoming deductible"],"correct_index":0,"explanation":"A fine that is never deductible is a permanent difference: it enters accounting profit but never taxable profit, in any year. Permanent differences change current tax for the period and never reverse, so they create no deferred tax asset or liability.","set":1},{"id":"cr-s19-q3","session":19,"topic":"Current tax formula","question":"Pre-tax accounting profit is 800,000, including 30,000 of non taxable government bond interest and 50,000 of disallowed expenses. The tax rate is 25%. What is the current tax?","choices":["205,000","195,000","200,000","220,000"],"correct_index":0,"explanation":"Taxable profit starts from accounting profit: add back the 50,000 of disallowed expenses and remove the 30,000 of exempt interest, giving 820,000. Current tax is 25% of 820,000 = 205,000.","set":1},{"id":"cr-s19-q4","session":19,"topic":"Why temporary differences create deferred tax","question":"A company books a warranty expense of 10,000 this year, but tax law allows the deduction only when the cost is actually paid next year. Future taxable profit is probable. Why does this create deferred tax?","choices":["The difference reverses when the cost becomes deductible, and that future tax saving is recognised now","Accounting and taxable profit must be equal every year, so the gap is corrected immediately","The provision is taxed twice, so the second charge is booked as a liability","The expense is never deductible, so accounting profit is permanently overstated"],"correct_index":0,"explanation":"This year taxable profit exceeds accounting profit because the deduction is denied. Next year, when the warranty is paid, taxable profit will be lower than accounting profit and less tax will be paid. That future saving is a deferred tax asset, and recognising it matches the tax effect to the year that bears the warranty cost.","set":1},{"id":"cr-s19-q5","session":19,"topic":"Deferred tax asset condition","question":"A company receives customer subscriptions in advance. Tax law taxes the cash on receipt, while accounting recognises the revenue next year when the service is delivered. What does this create? Assume sufficient probable future taxable profit for recovery and no recognition exception.","choices":["A deferred tax liability, because revenue enters accounting profit later","A deferred tax asset, because taxable profit is higher now and will be lower than accounting profit when the revenue is recognised","No deferred tax, because the cash has already been taxed","A permanent difference, because the two systems use different years"],"correct_index":1,"explanation":"The company pays tax now on income it has not yet recognised in its accounts. When the revenue is recognised next year, accounting profit will exceed taxable profit and no second tax will be due. Paying more tax now and less later is a future benefit: a deferred tax asset. The gap reverses, so it is temporary, not permanent.","set":1},{"id":"cr-s19-q6","session":19,"topic":"Deferred tax liability condition","question":"A company deducts a prepaid insurance premium in full for tax this year, while accounting spreads the cost over three years. What does this create?","choices":["A deferred tax asset, because accounting profit will be higher later","A deferred tax liability, because taxable profit is lower now and will be higher than accounting profit in later years","A deferred tax asset, because the tax deduction has already been fully used","No deferred tax, because both systems deduct the same total cost"],"correct_index":1,"explanation":"The tax deduction is taken immediately, so taxable profit is below accounting profit this year and less tax is paid now. In the next two years accounting still charges the premium while tax no longer does, so taxable profit will exceed accounting profit and more tax will be paid then. That future obligation is a deferred tax liability.","set":1},{"id":"cr-s19-q7","session":19,"topic":"Balance sheet approach, asset","question":"A machine has a carrying amount of 16,000 and a tax base of 11,200. The tax rate is 19%. What deferred tax arises?","choices":["A deferred tax liability of 3,040","A deferred tax liability of 912","A deferred tax asset of 912","A deferred tax asset of 2,128"],"correct_index":1,"explanation":"The temporary difference is 16,000 - 11,200 = 4,800. The carrying amount exceeds the tax base, meaning accounting has depreciated less than tax has allowed, so more tax will be due in the future: a taxable difference and a liability. At 19% the liability is 912.","set":1},{"id":"cr-s19-q8","session":19,"topic":"Balance sheet approach, liability","question":"Accrued expenses of 8,000 have been deducted in accounting profit but will only be deductible for tax when paid. Future taxable profit is probable and the tax rate is 19%. What deferred tax arises?","choices":["A deferred tax asset of 8,000","No deferred tax at all","A deferred tax asset of 1,520","A deferred tax liability of 1,520"],"correct_index":2,"explanation":"The liability's tax base is its carrying amount minus the future deduction: 8,000 - 8,000 = zero. Settling the liability later will cut future tax, which is a deductible temporary difference of 8,000. At 19% that gives a deferred tax asset of 1,520.","set":1},{"id":"cr-s19-q9","session":19,"topic":"Tax base definition","question":"Interest receivable of 3,000 is recognised as income this year but will only be taxed when the cash is received. The tax rate is 19%. What are the tax base of the receivable and the resulting deferred tax?","choices":["Tax base 3,000 and no deferred tax","Tax base zero and a deferred tax asset of 570","Tax base zero and a deferred tax liability of 570","Tax base 3,000 and a deferred tax liability of 570"],"correct_index":2,"explanation":"The tax base is the amount deductible against the future taxable benefits of the asset. When the 3,000 is collected it will be taxed in full with no deduction, so the tax base is zero. The carrying amount of 3,000 exceeds it, a taxable temporary difference, giving a deferred tax liability of 19% of 3,000 = 570.","set":1},{"id":"cr-s19-q10","session":19,"topic":"Mandrigo Ltd example","question":"A company reports pre-tax profit of 650,000, which includes a non deductible fine of 15,000 and non taxable government bond interest of 40,000. The tax rate is 20%. What is the current tax?","choices":["135,000","141,000","119,000","125,000"],"correct_index":3,"explanation":"Add back the fine of 15,000 and remove the exempt interest of 40,000: taxable profit is 650,000 + 15,000 - 40,000 = 625,000. Current tax is 20% of 625,000 = 125,000.","set":1},{"id":"cr-s19-q11","session":19,"topic":"Journal entries","question":"The only book to tax difference is that tax depreciation exceeds accounting depreciation, so taxable profit is below accounting profit this year. There are no permanent differences. How is the year's tax expense recorded?","choices":["Tax expense is reduced by a transfer from the deferred tax account, using up a deferred tax asset","Tax expense equals current tax only, and the gap stays unrecorded until reversal","The gap is posted directly to equity, because it does not belong in profit or loss","Tax expense is current tax plus a transfer to the deferred tax account, building a deferred tax liability"],"correct_index":3,"explanation":"Accelerated tax depreciation cuts current tax now but creates a taxable temporary difference: future years will show less tax depreciation and more tax. The transfer to the deferred tax account charges that future cost to this year, so total tax expense still reflects accounting profit.","set":1},{"id":"cr-s19-q12","session":19,"topic":"Discounting deferred tax","question":"A deferred tax liability is expected to reverse in fifteen years. How does IAS 12 require it to be measured?","choices":["At present value, using a risk free government bond yield of matching maturity","At present value, using the company's own borrowing rate","At fair value, the price a market participant would pay to assume it","At the undiscounted amount, using the tax rate expected to apply on reversal"],"correct_index":3,"explanation":"IAS 12 prohibits discounting deferred taxes, even for distant reversals, and requires the rate enacted or substantively enacted for the reversal period. The book amount can therefore overstate the economic burden of a long dated balance, something analysts adjust for.","set":1},{"id":"cr-s20-q1","session":20,"topic":"Bad debt example","question":"A company books an allowance of 2,000 for a customer in financial difficulty. The allowance is deductible for tax only when the debt is actually written off, future taxable profit is probable and the rate is 25%. What deferred tax arises in the year of the allowance?","choices":["A deferred tax asset of 500","A deferred tax asset of 2,000","A deferred tax liability of 500","No deferred tax until the write off"],"correct_index":0,"explanation":"The allowance cuts accounting profit now but not taxable profit, so the company pays more current tax than its accounting profit implies. The 2,000 difference reverses when the debt is written off and deducted, so it is temporary: 2,000 × 25% = 500 of deferred tax asset.","set":1},{"id":"cr-s20-q2","session":20,"topic":"Accelerated depreciation example","question":"An asset is depreciated straight line at 5,000 a year in the accounts. In year two, tax law allows depreciation of 8,000. The rate is 40%. How does the deferred tax balance move in year two?","choices":["The deferred tax liability rises by 3,000","The deferred tax asset rises by 1,200","The deferred tax liability rises by 1,200","It does not move, because total depreciation is the same"],"correct_index":2,"explanation":"Tax depreciation exceeds book depreciation by 3,000, so taxable profit and current tax fall now. The 3,000 is a taxable temporary difference that will reverse when tax depreciation drops below book depreciation, so 40% of it, 1,200, is added to the deferred tax liability.","set":1},{"id":"cr-s20-q3","session":20,"topic":"Valuation allowance definition","question":"A deferred tax asset arose through profit or loss. At year end, management concludes that part of it can no longer be recovered through future taxable profit. What does the accounting require?","choices":["Charge the reduction directly to equity, because it relates to past trading","Reduce the deferred tax liability by the same amount, since the balances offset","Reduce the deferred tax asset and recognise the reduction as income tax expense in profit or loss","Leave the balance unchanged and mention the doubt only in the notes"],"correct_index":2,"explanation":"IAS 12 recognises a deferred tax asset only to the extent recovery is probable. Reduce the carrying amount when that support falls. Because the original tax effect arose in profit or loss, this reduction is also tax expense in profit or loss. US GAAP describes its separate contra asset mechanism as a valuation allowance.","set":1},{"id":"cr-s20-q4","session":20,"topic":"Valuation allowance mechanics","question":"A company set up a valuation allowance against a deferred tax asset two years ago. Profit forecasts have improved sharply since. What happens to the allowance? The original asset and its reduction both related to profit or loss, and recovery is now probable.","choices":["It can be reversed, and the reversal is a gain in the income statement","It can be reversed, but only by crediting an equity reserve","It cannot be reversed and stays until the asset is fully used","It reverses automatically in the year the deferred tax asset expires"],"correct_index":0,"explanation":"The supported benefit is recognised again when recovery becomes probable. On the stated facts the restoration is an income tax benefit in profit or loss. It is not automatic on expiry and is not prohibited merely because recognition was reduced before. In US GAAP presentation this may be described as reversing a valuation allowance.","set":1},{"id":"cr-s20-q5","session":20,"topic":"Country differences","question":"In a simplified comparison, Company A applies financial reporting rules that create many temporary differences from tax rules. Company B has no such differences because its accounting and tax bases coincide. All else equal, which company has greater scope for deferred tax balances?","choices":["Company B, because book and tax alignment creates more temporary differences","Both equally, because IAS 12 eliminates differences in tax law","Company A, because IAS 12 imposes an additional tax on divergent accounting","Company A, because its accounting carrying amounts diverge from the relevant tax bases"],"correct_index":3,"explanation":"Deferred tax follows temporary differences between accounting carrying amounts and tax bases, subject to recognition requirements. A has scope for these balances, B does not under the stated assumptions. This comparison does not assert a universal current rule for any country.","set":1},{"id":"cr-s20-q6","session":20,"topic":"Analytical use of deferred taxes","question":"An analyst values a fast growing firm whose capital spending keeps pushing its deferred tax liability higher every year. How should that liability be treated in the forecast?","choices":["As debt to discount at the firm's borrowing cost before deduction","As a balance that may keep rolling forward without reversing, working like an interest free loan from the government","As equity, because a balance never paid belongs with retained earnings","As a cash outflow within a year, because every temporary difference must reverse soon"],"correct_index":1,"explanation":"For a growing firm, new taxable differences arise faster than old ones reverse, so the liability persists and even grows. The analyst should judge case by case whether a reversal, and therefore a real cash outflow, is actually likely, rather than treating the whole balance as imminent debt.","set":1},{"id":"cr-s20-q7","session":20,"topic":"Academic evidence, earnings quality","question":"Firm A has reported accounting profit well above taxable income for several years, while firm B's book and taxable income track each other closely. Other things equal, what does the evidence on book tax gaps imply?","choices":["A's earnings are less persistent: a wide positive gap is a red flag for earnings quality","A's earnings deserve a premium, because a wide gap signals efficient tax management","Both firms are equally informative, because book tax differences reverse over time and cancel out","A's gap carries no implication for earnings quality, because taxable income is set independently of reporting choices"],"correct_index":0,"explanation":"Larger positive book tax gaps come with less persistent earnings, and investors price that, as the Hanlon (2005) evidence discussed in the course shows. The gap is not proof of fraud: part of it can reflect tax strategy or legitimate judgement, and the conformity evidence shows the two measures are not independent. Reversal over time does not restore informativeness.","set":1},{"id":"cr-s20-q8","session":20,"topic":"Academic evidence, book-tax conformity","question":"A tax reform forces firms to compute taxable income with the same accrual rules they use in their financial statements, so book and tax income can no longer diverge. What does the evidence on book tax conformity predict for the information content of accounting earnings?","choices":["Earnings become more informative, because conformity removes all scope for judgement in accounting","Earnings become less informative, because part of the gap reflected judgement independent of tax rules","Earnings become more persistent, because conformity removes the noise of independent accrual choices","Nothing changes, because tax returns are not a source of information for investors"],"correct_index":1,"explanation":"When firms were forced to switch from cash to accrual accounting for tax, narrowing the gap, their earnings became less informative, as Hanlon, Maydew and Shevlin (2008) found. A wide gap is not purely bad news: it partly reflects accounting judgement exercised independently of the tax rules.","set":1},{"id":"cr-s20-q9","session":20,"topic":"Berkshire Hathaway framing","question":"A newspaper describes a large, steadily growing deferred tax liability as a possible interest free government loan. What is the point?","choices":["The company holds government bonds funded at zero interest, creating a tax deduction","The company was refunded overpaid taxes and must repay the refund later","The liability is unrecognised, hiding the true amount owed to the tax authorities","A liability that keeps rolling forward postpones cash tax indefinitely while new differences replace reversing ones, like free financing"],"correct_index":3,"explanation":"A deferred tax liability delays cash tax payments. If new taxable differences keep arising as old ones reverse, the postponement never ends and the government has in effect lent the company the money without charging interest. The liability is fully recognised; the question is when, if ever, it becomes cash.","set":1},{"id":"cr-s20-q10","session":20,"topic":"Balance sheet approach, Bulb Ltd","question":"A company has received customer deposits of 15,000 in advance. Tax law taxed them on receipt, while accounting holds them as a liability until the revenue is earned. Future taxable profit is probable and the rate is 20%. What deferred tax arises?","choices":["None, because the deposits were already taxed","A deferred tax asset of 3,000","A deferred tax asset of 15,000","A deferred tax liability of 3,000"],"correct_index":1,"explanation":"The liability has a carrying amount of 15,000 and a tax base of zero, because nothing more will be taxed when the revenue is recognised. That is a deductible temporary difference: at 20% the deferred tax asset is 3,000, reflecting the tax saved when accounting catches up.","set":1},{"id":"cr-s20-q11","session":20,"topic":"Balance sheet approach, development costs","question":"A company capitalises development costs of 90,000 and amortises them over time, while tax law deducted the costs in full when incurred. The rate is 20%. What deferred tax arises?","choices":["A deferred tax liability of 18,000","A deferred tax liability of 90,000","None, because the cash is already spent","A deferred tax asset of 18,000"],"correct_index":0,"explanation":"The asset's carrying amount of 90,000 sits above a tax base of zero, so recovering it will bring taxable benefits with no matching deduction: a taxable temporary difference. At 20% the deferred tax liability is 18,000, reflecting that accounting will charge the cost after tax already has.","set":1},{"id":"cr-s20-q12","session":20,"topic":"Common mistake, valuation allowance scope","question":"A manager proposes setting up valuation allowances against both the deferred tax assets and the deferred tax liabilities. What is wrong with that?","choices":["Allowances apply only to liabilities, because they may never be paid","Allowances apply only to assets, because their benefit depends on uncertain future taxable profit","Allowances apply to current tax payable, so deferred balances cannot be reduced at all","Allowances apply to both, because both rest on estimates of future profit"],"correct_index":1,"explanation":"A deferred tax asset is worth something only if enough future taxable profit will absorb it, which is why it is reviewed and cut when recovery stops being probable. A liability does not depend on future profitability in that way, so no valuation allowance ever attaches to it.","set":1},{"id":"cr-s21-q1","session":21,"topic":"Sale and leaseback definition","question":"Which of these transactions is a sale and leaseback?","choices":["A manufacturer sells its warehouse to an investor and leases a different warehouse from another owner","A manufacturer leases a warehouse from an investor with an option to buy it at the end","A manufacturer buys a warehouse from a supplier and leases it to a subsidiary","A manufacturer sells its warehouse to an investor and immediately leases the same warehouse back for its own use"],"correct_index":3,"explanation":"The defining feature is that the seller sells an asset and at once leases that same asset back from the buyer, so it keeps using it without interruption. A deal involving a different asset or a different user is not a sale and leaseback.","set":1},{"id":"cr-s21-q2","session":21,"topic":"Seller-lessee benefit","question":"A retailer needs liquidity but must keep using its head office. What does selling the building and leasing it back achieve for that need?","choices":["It removes property related operating obligations as well as legal ownership","It eliminates future rent by replacing the property's cost with sale proceeds","It guarantees a higher lifetime return because releasing cash creates an accounting gain","It releases cash tied up in the property at once while operations continue without interruption"],"correct_index":3,"explanation":"The seller receives an immediate cash inflow it can use elsewhere and never loses use of the asset, which is why the structure suits cash strapped but asset rich firms.","set":1},{"id":"cr-s21-q3","session":21,"topic":"Key question governing treatment","question":"A machine owner transfers the machine to a bank, then continues using it under a leaseback. Which assessment determines whether the parties apply sale accounting or financing accounting?","choices":["Whether the lease payments are fixed or depend on how much the machine is used","Whether the transfer meets the IFRS 15 test for a sale, meaning control of the machine passed to the bank","Whether the sale price is above the carrying amount of the machine at the date of sale","Whether the leaseback term is longer than half of the machine's remaining useful life"],"correct_index":1,"explanation":"Everything branches on whether control transferred under IFRS 15. If it did, asset sale accounting and lease accounting apply. If it did not, both sides treat the cash as a secured loan, whatever the paperwork calls it.","set":1},{"id":"cr-s21-q4","session":21,"topic":"If the transfer is NOT a sale","question":"A seller-lessee receives 500,000 from a buyer, but the transfer does not meet the IFRS 15 test for a sale. How does the seller-lessee account for the 500,000?","choices":["It keeps the asset on its books and records the 500,000 as a financial liability under IFRS 9","It derecognises the asset and records a right of use asset at fair value","It derecognises the asset and records a gain equal to the excess over carrying amount","It records the 500,000 as deferred revenue released over the lease term"],"correct_index":0,"explanation":"Without a transfer of control there is no sale, so the asset stays on the seller's books and the cash received is a financial liability. The buyer mirrors this with a financial asset, not an asset purchase.","set":1},{"id":"cr-s21-q5","session":21,"topic":"ROU asset measurement in a qualifying sale and leaseback","question":"A building with a carrying amount of 600,000 is sold for its fair value of 800,000 and leased back. The present value of the lease payments is 200,000 and the sale qualifies under IFRS 15. At what amount is the right of use asset measured? Leaseback rentals are at market and no off market adjustment applies.","choices":["450,000","200,000","150,000","600,000"],"correct_index":2,"explanation":"The retained share is 200,000 / 800,000 = 25%. The right of use asset is that proportion of the previous carrying amount: 25% × 600,000 = 150,000, not the lease liability or a fresh fair value.","set":1},{"id":"cr-s21-q6","session":21,"topic":"Gain recognition in a qualifying sale and leaseback","question":"A building with a carrying amount of 600,000 is sold for its fair value of 800,000 and leased back. The present value of the lease payments is 200,000 and the sale qualifies under IFRS 15. What gain does the seller-lessee recognise? Leaseback rentals are at market and no off market adjustment applies.","choices":["200,000","100,000","150,000","50,000"],"correct_index":2,"explanation":"The total economic gain is 200,000, but the seller keeps 25% of the rights (200,000 / 800,000), so only the transferred 75% is recognised: 150,000. The retained quarter of the gain stays embedded in the right of use asset.","set":1},{"id":"cr-s21-q7","session":21,"topic":"Worked example figures","question":"A building has a carrying amount of 450,000 and is sold for its fair value of 600,000, with leaseback payments whose present value is 120,000. The sale qualifies. Which set of figures is right? Leaseback rentals are at market and no off market adjustment applies.","choices":["Right of use asset 90,000, lease liability 120,000 and gain 30,000","Right of use asset 90,000, lease liability 90,000 and gain 120,000","Right of use asset 120,000, lease liability 120,000 and gain 150,000","Right of use asset 90,000, lease liability 120,000 and gain 120,000"],"correct_index":3,"explanation":"The retained share is 120,000 / 600,000 = 20%, so the right of use asset is 20% × 450,000 = 90,000 and the liability is the 120,000 present value. Of the total gain of 150,000, only the transferred 80% is recognised: 120,000.","set":1},{"id":"cr-s21-q8","session":21,"topic":"Tax rate change adjustment formula","question":"A company has accumulated taxable timing differences of 200,000 measured at 30%, all arising through profit or loss. The government enacts a rate cut to 25%. How is the deferred tax liability adjusted?","choices":["It falls by 10,000, recognised at once as lower tax expense","It rises by 10,000, recognised at once as higher tax expense","It falls by 10,000, credited directly to equity","It falls by 10,000, spread over the remaining years of reversal"],"correct_index":0,"explanation":"The catch up is the accumulated difference of 200,000 times the 5 point rate change: 10,000. Because these differences arose through profit or loss, the adjustment is a one off credit to tax expense in the period of enactment, not a deferral.","set":1},{"id":"cr-s21-q9","session":21,"topic":"Direction of DTA adjustment on a rate increase","question":"A company has a deferred tax asset of 40,000 measured at a 20% rate, all related to profit or loss items. The government enacts a rate rise to 25%. What is the effect? The underlying deductible difference is unchanged and the asset remains fully recoverable.","choices":["The asset stays at 40,000 until the underlying differences reverse","The asset rises by 10,000 and tax expense falls by 10,000","The asset rises by 10,000 and tax expense rises by 10,000","The asset falls by 10,000 and tax expense rises by 10,000"],"correct_index":1,"explanation":"A deferred tax asset is a future tax saving, and a higher rate makes that saving worth more. The restated asset is 40,000 × 25/20 = 50,000, and the 10,000 uplift is a benefit credited against tax expense.","set":1},{"id":"cr-s21-q10","session":21,"topic":"Direction of DTL adjustment on a rate decrease","question":"A company has a deferred tax liability of 90,000 measured at a 30% rate, all related to profit or loss items. The government enacts a rate cut to 24%. What is the effect?","choices":["The liability falls by 18,000 and the company reports a lower tax expense","The liability rises by 18,000 and the company reports a higher tax expense","The liability falls by 18,000 and the company reports a higher tax expense","The liability stays at 90,000 because it relates to differences from past years"],"correct_index":0,"explanation":"A liability is a future tax cost, which shrinks when the rate falls. The restated balance is 90,000 × 24/30 = 72,000, and the 18,000 decrease is a benefit through tax expense in the period of enactment.","set":1},{"id":"cr-s21-q11","session":21,"topic":"Common mistake, ROU asset measurement","question":"In a qualifying sale and leaseback, a student measures the right of use asset at the fair value of the right retained. What is the correct measurement basis?","choices":["The fair value of the whole asset at the date of the sale","The present value of the leaseback payments, which is also the lease liability","The proportion of the asset's previous carrying amount that relates to the rights retained","The sale price minus the gain the seller-lessee recognises"],"correct_index":2,"explanation":"The right of use asset starts from the seller's own pre transaction carrying amount, scaled down by the share of rights retained. Neither a fresh fair value nor the lease liability amount is the required basis.","set":1},{"id":"cr-s21-q12","session":21,"topic":"Common mistake, tax rate change timing","question":"A tax rate cut is enacted in December and applies from next year. A company has a large deferred tax liability. When is the adjustment recognised? All underlying differences reverse at the new rate and the balance arose through profit or loss.","choices":["Gradually, spread over the future years in which the differences reverse","Once, in the period of enactment, as a catch up on the whole balance","Only in the first year the new rate applies to taxable profit","Only as each individual temporary difference reverses"],"correct_index":1,"explanation":"Deferred tax balances must reflect the rate expected to govern reversal, so the whole balance is remeasured immediately once the change is enacted or substantively enacted. The adjustment is not amortised forward.","set":1},{"id":"cr-s22-q1","session":22,"topic":"Why IFRS15 replaced prior standards","question":"A mobile operator sells a contract bundled with a free phone. Why did the rules before IFRS 15 handle such bundles badly?","choices":["Both regimes required revenue to be recognised when cash was received","IAS 18 was vague and US GAAP was industry specific, so similar bundles were accounted for differently","Both regimes banned revenue on bundles until the whole contract had ended","Both regimes applied only to listed companies and left private firms without guidance"],"correct_index":1,"explanation":"IAS 11 and IAS 18 were hard to apply consistently, while US GAAP had detailed rules that varied by industry, so economically similar deals got different accounting. IFRS 15 replaced this with one principles based model built to improve comparability and cope with newer business models like bundled phone contracts.","set":1},{"id":"cr-s22-q2","session":22,"topic":"Core principle","question":"A customer pays 1,200 on 1 December for a service that will be delivered the following March. What does a company applying IFRS 15 do in December?","choices":["Recognises 1,200 of revenue in December, because the cash has arrived","Recognises revenue evenly from December to March, because the contract was signed in December","Records cash and a liability, and recognises revenue only when the service is transferred","Records nothing until March, because cash movements are irrelevant before delivery"],"correct_index":2,"explanation":"Revenue follows the transfer of goods or services to the customer, not the cash. The advance payment is a contract liability until control of the service passes.","set":1},{"id":"cr-s22-q3","session":22,"topic":"Step 1 conditions","question":"A supplier signs an 18 month framework agreement that sets prices, rebates and shipping terms, but names no goods or quantities. When does an IFRS 15 contract exist? Until an order is accepted, neither party has an enforceable obligation to supply or purchase, and all other IFRS 15 contract criteria are met on acceptance.","choices":["At signing, because the agreement already has enforceable prices and terms","When the first payment arrives, because cash shows commitment","Only when the customer places a specific order that identifies the goods and quantities","When the supplier ships the first goods, whatever the order says"],"correct_index":2,"explanation":"A contract needs identifiable rights to the goods or services, identifiable payment terms, commitment, commercial substance and probable collection. With no agreed goods or quantities, the criteria are not met at signing. the agreement combined with a specific order meets them.","set":1},{"id":"cr-s22-q4","session":22,"topic":"Distinct good or service test","question":"A company sells a software licence together with consulting that significantly customises and integrates it, for a total of 600,000. How many performance obligations does the contract contain?","choices":["One, but only if the total price is below the sum of the stand alone prices","Two, because the customer could benefit from the licence on its own","Two, because the licence and the consulting are itemised separately in the contract","One, because the licence and the consulting are not separately identifiable once they are heavily integrated"],"correct_index":3,"explanation":"A promise is distinct only if the customer can benefit from it on its own and it is separately identifiable in the contract. The significant customisation and integration here make the two promises one combined performance obligation. Integration decides the unit of account, not by itself whether revenue is recognised over time.","set":1},{"id":"cr-s22-q5","session":22,"topic":"Variable consideration, expected value vs most likely amount","question":"Assume the estimate passes the significant reversal constraint. A contractor will receive a fixed 800,000 plus a 50,000 bonus if it finishes on time, and no bonus if it is late by even a day. The probability of finishing on time is 90%. Which method fits and what is the transaction price?","choices":["Expected value, giving a price of 805,000","Most likely amount, giving a price of 850,000","Expected value, giving a price of 845,000","Most likely amount, giving a price of 800,000"],"correct_index":1,"explanation":"For a single binary bonus the most likely amount best predicts the consideration: the likely bonus is the full 50,000, so the price is 850,000. Including it also requires the stated assumption that a significant revenue reversal is highly unlikely.","set":1},{"id":"cr-s22-q6","session":22,"topic":"Late delivery penalty example","question":"Assume the estimate passes the significant reversal constraint. A contract price is 300,000 with a 10,000 penalty for each week of delay. The probabilities are 70% on time, 20% one week late and 10% two weeks late. What is the transaction price?","choices":["296,000","290,000","280,000","300,000"],"correct_index":0,"explanation":"With a range of possible outcomes the expected value method applies. The expected penalty is 20% × 10,000 + 10% × 20,000 = 4,000, so the transaction price is 300,000 - 4,000 = 296,000.","set":1},{"id":"cr-s22-q7","session":22,"topic":"Allocation of a bundle discount","question":"Three items with stand alone prices of 30, 70 and 20 are sold together for 90. There is no evidence that the discount relates to any single item. How much of the 90 is allocated to the item priced at 70?","choices":["60.00","45.00","70.00","52.50"],"correct_index":3,"explanation":"The stand alone prices total 120 against a bundle price of 90, and with no specific evidence the discount is allocated proportionately. The 70 item receives 70/120 × 90 = 52.50.","set":1},{"id":"cr-s22-q8","session":22,"topic":"Point in time vs over time recognition","question":"Assume the connection is distinct and the continuing services are provided evenly. A network provider receives 35,000 on 1 July for a connection, one year of network access and one year of troubleshooting. How is the revenue recognised?","choices":["The connection share on delivery, and the continuing service shares over the year","The connection and access shares on delivery, and the troubleshooting share over the year","All three shares at contract end, when the final obligation is fulfilled","All three shares over the year, using time elapsed for the combined arrangement"],"correct_index":0,"explanation":"Each performance obligation is recognised when it is satisfied. The connection is transferred at a point in time, while access and troubleshooting are provided continuously over the year, so their allocated shares are recognised over time.","set":1},{"id":"cr-s22-q9","session":22,"topic":"Contract costs","question":"Winning a five year outsourcing contract triggers a 10,000 commission that would not otherwise be paid. Recovery is expected, there are no renewals and monthly customer payments are 20,000. How should the supplier account for the commission?","choices":["Recognised as an asset and amortised over the five year term of the contract","Expensed immediately, because the cost was paid before any revenue arose","Deducted from the first year's revenue, because the contract is won that year","Recorded as a contract liability and released as the customer pays each month"],"correct_index":0,"explanation":"The incremental cost of obtaining a contract is capitalised when it is recoverable, then amortised in line with the revenue the contract produces over its term. Immediate expensing would mismatch cost and benefit.","set":1},{"id":"cr-s22-q10","session":22,"topic":"Contract asset vs receivable","question":"Phase one is a distinct, satisfied performance obligation. A contractor has delivered phase one of a two phase contract, but payment for phase one falls due only once phase two is also delivered. What does the contractor record?","choices":["A receivable, treating performance alone as sufficient despite the payment condition","A contract liability, treating the lack of customer payment as an unsatisfied obligation","Deferred revenue, postponing the satisfied phase until both phases are complete","A contract asset, because the right to payment depends on further performance and not only on time"],"correct_index":3,"explanation":"A receivable is an unconditional right, limited only by the passage of time. Here payment also depends on future performance, so the right is conditional and the earned consideration is a contract asset.","set":1},{"id":"cr-s22-q11","session":22,"topic":"Contract liability","question":"A service provider collects 12,000 before supplying a year of service at a uniform rate. Three months of service are complete. What revenue and remaining contract liability should it show?","choices":["Revenue of zero and a contract liability of 12,000","Revenue of 3,000 and a contract liability of 9,000","Revenue of 3,000 and a contract asset of 9,000","Revenue of 12,000 and no liability"],"correct_index":1,"explanation":"Payment before performance creates a contract liability of 12,000. After three of twelve months of even service, 3,000 is earned as revenue, leaving 9,000 of liability.","set":1},{"id":"cr-s22-q12","session":22,"topic":"CRM software example","question":"The customer controls the hospital as it is built. A builder manages a whole hospital project covering site clearance, procurement, installation and finishing, and integrates all of it into one building. How is the revenue recognised?","choices":["As four separate obligations, each recognised when its activity finishes","As one obligation, recognised evenly as customer instalments arrive","As one performance obligation, over time, using a measure of progress","As one obligation, recognised in full when the hospital is handed over"],"correct_index":2,"explanation":"Highly interrelated goods and services integrated into one combined item form a single performance obligation. Because the customer obtains control as the work proceeds, revenue is recognised over time using a faithful measure of progress.","set":1},{"id":"cr-s23-q1","session":23,"topic":"Loyalty programme, material right","question":"A retailer gives customers points that earn discounts on future purchases which they could not otherwise get. How are the points treated under IFRS 15?","choices":["As a reduction of revenue recognised only in the period the points expire","As a contingent liability disclosed in the notes, with no allocation of the price","As a marketing expense when the points are issued, with sales revenue unchanged","As a separate performance obligation, so part of the sale price is allocated to them and deferred"],"correct_index":3,"explanation":"Points that provide a material right are a promise of future goods or services. A share of the transaction price belongs to them and sits as a contract liability until redemption or expiry.","set":1},{"id":"cr-s23-q2","session":23,"topic":"BA miles allocation","question":"An airline sells a ticket for 270. The ticket has a stand alone price of 250 and the award miles included have a stand alone price of 50. How is the 270 allocated?","choices":["Flight 220 and miles 50","Flight 250 and miles 20","Flight 270 and miles zero","Flight 225 and miles 45"],"correct_index":3,"explanation":"Stand alone prices total 300. The flight receives 250/300 × 270 = 225 and the miles receive 50/300 × 270 = 45. The allocation is proportional. there is no residual method here.","set":1},{"id":"cr-s23-q3","session":23,"topic":"BA miles, when is the miles revenue recognised?","question":"An airline allocates part of a ticket price to award miles. The customer uses those miles two years after the original flight. If no expected breakage is recognised early, what event releases the miles allocation into revenue?","choices":["At redemption, or at expiry if unused, sitting as a contract liability until then","At the date the ticket was sold, because the cash was received then","Evenly over the expected life of the loyalty programme as a whole","At the date of the flight, because the miles were earned on that trip"],"correct_index":0,"explanation":"With no earlier breakage recognition on these facts, the award revenue is recognised when the obligation is fulfilled or expires. IFRS 15 can permit proportional recognition of expected breakage, so expiry is not a universal timing rule.","set":1},{"id":"cr-s23-q4","session":23,"topic":"Right of return, transaction price","question":"A company sells 200 units at 50 each with a 30 day full refund right. A constrained estimate concludes it will retain consideration for 192 units. What is the transaction price?","choices":["10,000","400","9,600","9,400"],"correct_index":2,"explanation":"The consideration the company expects to keep covers 192 units: 192 × 50 = 9,600. The 8 units expected to come back are not consideration it is entitled to.","set":1},{"id":"cr-s23-q5","session":23,"topic":"Right of return, refund liability","question":"A retailer sells 200 goods for 50 each, with a cost of 30 each. Eight full refunds are expected, and the returned goods can be resold without recovery costs or any reduction in value. Alongside revenue, which return balances are needed?","choices":["A refund liability of 400 and no asset, because returned goods are written off","A refund liability of 240 and a right to recover goods asset of 400","A refund liability of 400 and a right to recover goods asset of 240","A refund liability of 240 and no asset, because the goods stay in inventory"],"correct_index":2,"explanation":"The refund liability is the selling price of the expected returns: 8 × 50 = 400. The recovery asset is measured at the cost of the goods expected back: 8 × 30 = 240, with cost of sales adjusted accordingly.","set":1},{"id":"cr-s23-q6","session":23,"topic":"Non-refundable up-front fees","question":"A gym charges a non-refundable joining fee of 100 that covers registration, and renewals carry no further fee. How is the fee treated at signing? Registration is only an administrative activity and transfers no separate service to the customer.","choices":["It is not a separate performance obligation, so it is deferred over the period of the future services","It is recognised as revenue immediately, because the cash can never be refunded","It is a separate performance obligation satisfied when the customer is registered","It is held as a liability and repaid if the customer leaves in the first year"],"correct_index":0,"explanation":"Registration is an internal administrative activity that transfers nothing to the customer on its own. The fee is an advance payment for future club access, so revenue follows that access.","set":1},{"id":"cr-s23-q7","session":23,"topic":"Non-refundable up-front fees, recognition period","question":"Joining a gym requires a non-refundable upfront fee, but renewing does not. The waived renewal fee is a material right. What period should recognition of that joining consideration reflect?","choices":["The period to the first renewal decision, with any balance written off after that","The time needed to complete registration, usually under a month","The expected period of the customer relationship, because renewals carry no new fee","The first contractual year only, because that is the stated term"],"correct_index":2,"explanation":"Because the fee also pays for access the customer receives after renewing, the recognition period can extend beyond the first year, over the expected relationship. Set up costs that meet the capitalisation criteria are amortised over the same period.","set":1},{"id":"cr-s23-q8","session":23,"topic":"Percentage of completion, output method","question":"The performance obligation qualifies for recognition over time. A fixed price service contract is for 900,000. A surveyor assesses it as one third complete at year end and the company judges this output measure depicts progress faithfully. Costs to date are 300,000 with 300,000 more to come, and the customer has paid 540,000. How much revenue is recognised?","choices":["450,000","300,000","900,000","540,000"],"correct_index":1,"explanation":"Revenue follows the faithful output measure: one third of 900,000 = 300,000. A cost to cost method would give 450,000, but the output measure is the one specified as faithful here. Cash received never decides revenue.","set":1},{"id":"cr-s23-q9","session":23,"topic":"Percentage of completion, cost recognition","question":"All stated costs relate to performance already delivered, not future services. Revenue of 300,000 is recognised on a contract, costs incurred to date are 300,000 and the customer has paid 540,000. How are the costs and the cash shown?","choices":["Costs expensed as incurred, and a receivable of 240,000 for the excess cash","Costs expensed as incurred, and the 240,000 of cash received in excess of revenue as a contract liability","Costs expensed as incurred, and the 240,000 excess recognised as extra revenue","Costs capitalised until completion, and the 240,000 excess as a contract asset"],"correct_index":1,"explanation":"The customer has paid 240,000 more than the company has performed, so that excess is a contract liability. Costs are expensed as incurred, which can produce a loss when output progress runs behind spending.","set":1},{"id":"cr-s23-q10","session":23,"topic":"Common mistake, loyalty programmes","question":"An airline includes a material right to future awards in a ticket, but books the entire ticket consideration as revenue on the flight date. How is current revenue misstated before any award is redeemed?","choices":["Revenue is overstated in later periods, because the points are redeemed after the flight","Current period revenue is overstated, because the share for the points should be deferred until redemption","Current period revenue is understated, because points are costs to deduct at once","Revenue is correct, because the cost of points is recorded as a later expense"],"correct_index":1,"explanation":"Part of the price relates to the points and should sit as a contract liability until they are redeemed or expire. Booking all of it at the flight pulls revenue forward into the current period.","set":1},{"id":"cr-s23-q11","session":23,"topic":"Common mistake, right of return","question":"A company books the full invoiced 10,000 as revenue at the date of sale and records refunds as an expense when they happen. What is wrong with that approach?","choices":["Nothing: full revenue first, with later refunds as operating costs","Nothing: full revenue is fine if expected returns are disclosed without a refund liability","It should defer all revenue until the return right expires, whatever the estimates say","The transaction price must already be reduced for expected returns, with a refund liability recognised"],"correct_index":3,"explanation":"Revenue is recognised only for the consideration the company expects to keep. Expected returns reduce revenue immediately and create a refund liability. waiting for actual refunds overstates current revenue.","set":1},{"id":"cr-s24-q1","session":24,"topic":"Full retrospective method","question":"A company's 2017 annual report shows its 2016 income statement differently from the one originally published, marked as restated for the new revenue standard. Which transition method did it use, and what does that imply?","choices":["Full retrospective, so every period presented is on the new standard basis","Early adoption by cumulative catch up, so prior periods are only described in a note","Modified retrospective, so only the opening retained earnings balance is adjusted","Prospective adoption, so only contracts signed after the adoption date are affected"],"correct_index":0,"explanation":"Full retrospective restates the comparative periods as if the standard had always applied. General Dynamics did this and showed 2015 and 2016 on the new basis.","set":1},{"id":"cr-s24-q2","session":24,"topic":"Modified retrospective method","question":"A company shows its prior year columns exactly as originally reported and records one adjustment to opening retained earnings on adopting the new revenue standard. What must it also disclose in the year of adoption?","choices":["What the current year amounts would have been under the old revenue rules","Restated prior year comparatives only, with nothing about the current year old basis","Only the cumulative opening adjustment, treated as a full substitute for the bridge","Only the deferred tax effect, because revenue differences need no reconciliation"],"correct_index":0,"explanation":"The modified retrospective method leaves prior periods unrestated, so users need comparability for the adoption year itself. The company discloses how the current year figures would have looked under the previous rules.","set":1},{"id":"cr-s24-q3","session":24,"topic":"General Dynamics driver","question":"Before adopting a new revenue policy, a jet manufacturer recognised profit partly on green aircraft acceptance and partly on final delivery. Afterwards, recognition waits for final delivery. What happens to opening retained earnings for profitable aircraft accepted but not yet delivered?","choices":["An increase, because recognising revenue once avoids double counting","No effect, because total revenue per aircraft is unchanged","A decrease, because profit already recognised on aircraft not yet delivered is reversed","An increase, because costs of unfinished aircraft are now capitalised"],"correct_index":2,"explanation":"The old approach front loaded revenue before delivery. Moving to a single delivery date defers profit that had already been recognised, so the cumulative effect on retained earnings is negative.","set":1},{"id":"cr-s24-q4","session":24,"topic":"Ford driver","question":"A carmaker changes from deferring profit on vehicles with guaranteed resale values to recognising that profit at shipment. For shipped vehicles whose profit was still deferred at transition, what is the direction of the opening retained earnings adjustment?","choices":["A decrease, because revenue is now recognised before cash arrives","An increase, because revenue that was held back is treated as earned earlier","A decrease, because the guaranteed resale value becomes a new liability","No effect, because deferral and shipment recognition give the same total"],"correct_index":1,"explanation":"Accelerating previously deferred revenue pulls it into the cumulative catch up, so opening retained earnings rises. Ford's revenue standard effect was a 36 million dollar increase.","set":1},{"id":"cr-s24-q5","session":24,"topic":"Sign of the adjustment","question":"Two revenue adopters report opening equity adjustments of opposite signs. Someone calls the positive sign proof of good performance and the negative sign proof of misconduct. What is wrong with interpreting transition that way?","choices":["It shows whether earlier revenue is now deferred or deferred revenue accelerated, not earnings quality","The sign establishes earnings quality, because earlier recognition means better performance","The sign depends solely on the transition method, not on the underlying contracts","The sign establishes a prior period error rather than a change of recognition policy"],"correct_index":0,"explanation":"General Dynamics had a negative sign and Ford a positive sign because their contracts moved in opposite directions under the new rules. The sign reflects timing, not good or bad management.","set":1},{"id":"cr-s24-q6","session":24,"topic":"Comparing the two companies","question":"Two companies adopt the new revenue standard in the same year. Company X restates its prior year column onto the new basis. Company Y adjusts opening retained earnings only and leaves its prior year column on the old basis. Which comparison between the two firms remains meaningful?","choices":["Revenue growth, because both adopted the same standard in the same year","Current year revenue levels, because both report the current year on the new basis","Revenue growth after deducting Y's opening retained earnings adjustment from its revenue","Revenue levels and growth, because the transition method affects equity only"],"correct_index":1,"explanation":"Under the modified retrospective method the prior year column stays on the old basis, so Y's reported growth mixes two measurement bases while X's does not. Both firms still report the current year under the new standard, so current year levels are comparable. The opening equity catch up is not current year revenue, and the transition method changes revenue measurement, not only equity. This is what separated General Dynamics (full retrospective) from Ford (modified) in the course case.","set":1},{"id":"cr-s24-q7","session":24,"topic":"Ford's unrelated adjustment","question":"A carmaker's retained earnings rose from 15,634 million dollars to 16,200 million at 1 January 2017. One cause was a 530 million adjustment for a stock compensation standard. What amount is attributable to the revenue standard?","choices":["16,200 million dollars","530 million dollars","566 million dollars","36 million dollars"],"correct_index":3,"explanation":"The total change is 566. Removing the 530 for the unrelated stock compensation standard leaves 36 for the revenue standard: 15,634 + 530 + 36 = 16,200.","set":1},{"id":"cr-s24-q8","session":24,"topic":"Revenue recognition profile","question":"An aerospace group has four revenue streams. Under IFRS 15, which one is recognised at a point in time rather than over time?","choices":["Long term defense work measured by costs incurred relative to total estimated costs","Shipbuilding recognised as performance progresses on each vessel","Time and materials services billed monthly as hours are worked","Business jets recognised on delivery and customer acceptance of the finished aircraft"],"correct_index":3,"explanation":"Control of a finished jet passes on delivery and acceptance, a point in time. The other streams satisfy an over time criterion, so revenue follows progress. In the General Dynamics adoption discussed in the course, the point in time share came mainly from business jets.","set":1},{"id":"cr-s24-q9","session":24,"topic":"Comparing the two transition methods","question":"Assume identical contracts, measurement and transition relief at the same comparison date. Two companies have the same underlying revenue change, one adopting full retrospective and the other modified retrospective. How do their total cumulative effects compare?","choices":["The full method gives a larger total, because it covers more years of history","The totals match, but one is spread across restated periods and the other is one opening adjustment","The modified method gives a smaller total, because it ignores contracts begun earlier","The totals match, but the modified method runs its effect through the income statement"],"correct_index":1,"explanation":"Both methods measure the same accounting change. They differ only in presentation: restated comparatives versus a single catch up in opening retained earnings.","set":1},{"id":"cr-s24-q10","session":24,"topic":"Assignment framework","question":"An adopter recorded a 372 million dollar cut to retained earnings at the transition date. Restated 2015 net earnings rose by 71 million and restated 2016 net earnings fell by 383 million. Which reconciliation gives the cumulative adjustment?","choices":["Minus 372, plus 71 and plus 383: a net increase of 82 million","Minus 372, plus 71 and minus 383: a net reduction of 684 million","Plus 372, plus 71 and minus 383: a net increase of 60 million","Minus 372, minus 71 and plus 383: a net reduction of 60 million"],"correct_index":1,"explanation":"The opening charge and the two yearly effects sum to the 684 million reduction shown at the end of 2016, where retained earnings moved from 25,227 to 24,543.","set":1},{"id":"cr-s25-q1","session":25,"topic":"IFRS2 scope","question":"Which transaction falls within the scope of IFRS 2?","choices":["A company raises cash through a rights issue to its existing shareholders","A company issues its own shares to a supplier as payment for goods delivered","A company pays an ordinary cash dividend to its shareholders","A company converts a convertible bond into shares at the holder's request"],"correct_index":1,"explanation":"IFRS 2 covers payments made in shares, or in amounts based on share prices, in exchange for goods or services. Dividends and general share issues for cash fall outside it.","set":1},{"id":"cr-s25-q2","session":25,"topic":"Equity-settled vs cash-settled","question":"Firm X has a fully vested employee award settled in a fixed number of its own shares. Firm Y has a vested employee award payable in cash equal to the value of 1,000 of its shares and still outstanding at year end. The share price rises after grant. How do they treat the later price rise?","choices":["Both remeasure, because both payments depend on the share price at the reporting date","Firm X does not remeasure, but Firm Y remeasures its liability to fair value through profit or loss","Neither remeasures anything, because fair value was fixed when the goods arrived","Firm X remeasures its equity, while Firm Y keeps its liability unchanged"],"correct_index":1,"explanation":"For this equity settled employee award, the grant date fair value is not remeasured for later share price movements. The outstanding cash settled liability is remeasured at fair value at each reporting date and settlement, with the change in profit or loss. This question does not concern a nonemployee measurement date.","set":1},{"id":"cr-s25-q3","session":25,"topic":"Measurement hierarchy","question":"A consultant completes services and accepts the client company own shares as payment. Under IFRS 2, what is the primary measurement basis for those nonemployee services?","choices":["At the consultant's cost of providing the services","At the nominal value of the shares issued","At the fair value of the shares issued, whenever the supplier asks for shares","At the fair value of the services received, unless that cannot be measured reliably"],"correct_index":3,"explanation":"The standard starts from the fair value of what the entity received. The fair value of the equity instruments granted is the fallback, used when the goods or services cannot be measured reliably, as is typical for employee services.","set":1},{"id":"cr-s25-q4","session":25,"topic":"Vesting condition taxonomy","question":"An executive award requires both three years of service and a share price above 5 euros at that date. Which kind of vesting condition is the own share price hurdle?","choices":["A service condition, because the executive must remain employed","A non-vesting condition, because the company does not control its share price","A non-market performance condition, because it measures the success of the whole business","A market performance condition, because it refers to the price of the entity's own equity instruments"],"correct_index":3,"explanation":"Targets based on the price of the entity's own shares are market conditions, while targets based on the entity's operations, like sales or profit, are non-market conditions. The three year stay is the service condition.","set":1},{"id":"cr-s25-q5","session":25,"topic":"Recognition timing rule","question":"An employee must supply three years of service to earn an award of 10 options. Over which period does the employer recognise the compensation cost?","choices":["At the end of year three, when the service condition is met","Over the three year vesting period, as the services are received","Immediately at grant date, because the options are measured then","At exercise date, when the employees receive the shares"],"correct_index":1,"explanation":"The expense for an equity settled employee award is spread over the vesting period during which the services are received. An award that vests immediately is expensed at once, because the related service has already been received.","set":1},{"id":"cr-s25-q6","session":25,"topic":"Measurement rule","question":"Assume equity settled employee awards. Options are granted when the share price is 1 euro and each option has a fair value of 0.75 euros. The share price is 3 euros when they vest. What amount per option is expensed in total?","choices":["3.00 euros, the share price at vesting","2.00 euros, the intrinsic value at vesting","0.75 euros, the fair value at grant date","1.88 euros, the average of grant and vesting values"],"correct_index":2,"explanation":"The expense rests on the grant date fair value, fixed once and for all. Later share price movements never change the charge for an equity settled award.","set":1},{"id":"cr-s25-q7","session":25,"topic":"Multi-year vesting example","question":"Assume equity settled employee awards. Six executives each receive 10,000 options with a grant date fair value of 0.60 euros each, vesting after three years of service, and nobody leaves. What is the annual expense?","choices":["12,000 euros","6,000 euros","36,000 euros","18,000 euros"],"correct_index":0,"explanation":"The total fair value is 6 × 10,000 × 0.60 = 36,000, spread over three years: 12,000 a year. Later share price movements are irrelevant.","set":1},{"id":"cr-s25-q8","session":25,"topic":"Forfeiture, service condition failure","question":"Assume equity settled employee awards. Six executives each hold options with a total grant date value of 6,000 euros per executive and a three year service condition. One leaves at the start of year two and forfeits. Year one expense was 12,000. What is the year two expense?","choices":["10,000 euros","12,000 euros","2,000 euros","8,000 euros"],"correct_index":3,"explanation":"After the departure, the cumulative expense at the end of year two should be 5 × 6,000 × 2/3 = 20,000. Deducting the 12,000 already booked leaves a year two charge of 8,000.","set":1},{"id":"cr-s25-q9","session":25,"topic":"Forfeiture, market condition failure","question":"Assume equity settled employee awards. Options vest on three years of service and a share price above 5 euros. All executives stay, but the price is only 4 euros at the end. What happens to the expense already recognised?","choices":["It is remeasured to the options' intrinsic value at the end of year three","It is reversed in full, because not all vesting conditions were met","Nothing changes, because the chance of missing the price target was built into the grant date fair value","It is reversed in part, in proportion to the shortfall between 4 and 5 euros"],"correct_index":2,"explanation":"Failing a market condition triggers no adjustment, because that possibility was already priced into the grant date fair value. Only failure of a service or non-market performance condition revises the expense.","set":1},{"id":"cr-s25-q10","session":25,"topic":"Expiry after vesting","question":"Assume equity settled employee awards. Vested options expire unexercised at the end of their exercise period, and the company had recognised an expense of 56,250 euros. How does it account for the expiry?","choices":["It may transfer the 56,250 within equity, without changing profit or total equity","It reclassifies the balance to a liability payable to the executives","It remeasures the balance to zero and reduces total equity","It reverses the earlier expense through profit or loss as a gain"],"correct_index":0,"explanation":"Expiry does not reverse the expense for services already received and does not change total equity. Moving the reserve between equity components is permitted, not required.","set":1},{"id":"cr-s25-q11","session":25,"topic":"Exercise entry, balancing figure","question":"Assume equity settled employee awards. Five executives exercise 10,000 options each at 0.20 euros per share. The nominal value is 0.10 euros per share and the stock option reserve is 30,000 euros. What is the credit to share premium?","choices":["40,000 euros","25,000 euros","35,000 euros","45,000 euros"],"correct_index":2,"explanation":"Cash received is 50,000 × 0.20 = 10,000 and share capital is 50,000 × 0.10 = 5,000. Share premium is the balancing figure: 10,000 + 30,000 - 5,000 = 35,000.","set":1},{"id":"cr-s25-q12","session":25,"topic":"Common mistake, remeasurement","question":"The share price rose from 1 euro at grant to 3 euros at vesting, and a manager wants to increase the expense on the equity settled options to match. Why is that wrong? These are unchanged equity settled employee awards with no modification.","choices":["The cost is fixed at grant date fair value, and only cash settled awards are remeasured for later price changes","The cost must be remeasured each year end, but only when the price has doubled","The cost must be remeasured each year end, exactly like a cash settled award","The cost is remeasured only on the exercise date, when shares are issued"],"correct_index":0,"explanation":"Equity settled awards keep their grant date measurement throughout. Remeasurement at each reporting date belongs to cash settled awards, where a liability exists.","set":1},{"id":"cr-s26-q1","session":26,"topic":"The case hook","question":"A company reports net income of 48 million dollars under the intrinsic value method, which expenses only the gap between share price and exercise price at grant. Its notes show a loss of almost 91 million had options been expensed at fair value. What explains the two pictures?","choices":["The reported figure excludes cash compensation that the pro forma figure includes","The reported figure carries no option cost, while the pro forma figure includes it","The reported figure includes tax benefits the pro forma figure leaves out","The pro forma figure includes a one off impairment the reported figure excludes"],"correct_index":1,"explanation":"Under the intrinsic value method an at the money option produced no expense, while the fair value method expensed the full value of the options. Same business, two accounting measures.","set":1},{"id":"cr-s26-q2","session":26,"topic":"APB25 intrinsic value method","question":"Under APB 25 an option is granted when the share price is 40 dollars and the exercise price is 35 dollars. What is the expense per option at grant? Consider a historical fixed award with no further service requirement.","choices":["0 dollars","35 dollars","40 dollars","5 dollars"],"correct_index":3,"explanation":"APB 25 measures expense as the gap between the stock's fair value and the exercise price at grant date. This option is 5 dollars in the money at grant, so the expense is 5 dollars.","set":1},{"id":"cr-s26-q3","session":26,"topic":"At the money options under APB25","question":"Why did most executive options produce no expense under APB 25?","choices":["They were granted at the money, so their intrinsic value was zero","Their fair value was near zero because they were far from expiry","Their expense was deferred until exercise, when shares were issued","APB 25 exempted executive options from any compensation expense"],"correct_index":0,"explanation":"Intrinsic value is the gap between share price and exercise price at grant. For an at the money option that gap is zero, however valuable the option may later become.","set":1},{"id":"cr-s26-q4","session":26,"topic":"SFAS123 fair value method","question":"Two option valuations use the same current share and exercise prices. Why can a pricing model give positive value when the intrinsic amount is zero?","choices":["The tax saving the company receives when employees exercise","The dividends the employee is expected to receive over the vesting period","The employee's personal discount rate, applied to the future exercise gain","Time value, which depends on expected volatility and the life of the option"],"correct_index":3,"explanation":"An option is worth more than any immediate spread, because the holder shares in upside without bearing downside. Time value rises with volatility and with the time left to expiry.","set":1},{"id":"cr-s26-q5","session":26,"topic":"IFRS2 relationship to these two methods","question":"Under the old US rules a firm could recognise option cost at intrinsic value or merely disclose fair value in the notes. How does IFRS 2 compare for equity settled awards?","choices":["It lets companies choose between the two methods when they report","It matches the intrinsic value method, so at the money options produce no expense","It requires grant date fair value to be expensed, matching the fair value method","It requires fair value to be disclosed in the notes but not recognised in profit"],"correct_index":2,"explanation":"IFRS 2 combined fair value measurement with mandatory recognition. A footnote only presentation of the fair value cost, allowed historically in the US, is not available under IFRS.","set":1},{"id":"cr-s26-q6","session":26,"topic":"Grant-date fair value vs exercise price gap","question":"A company's option disclosure prints an average grant date fair value of 103.79 dollars and an average strike of 62.69 dollars for the year's grants. What can these two averages establish?","choices":["Dividend payments account for the entire difference between the two averages","Every grant was at the money and exceeded its stock price legitimately","Time value matters, but the averages alone do not reconcile the grant assumptions","Intrinsic value equals the reported fair value minus the reported exercise price"],"correct_index":2,"explanation":"The same disclosure reports 115% volatility and a three year expected life. High volatility adds time value, but a standard call cannot exceed the underlying stock price, so if every grant were at the money and the averages were comparable, fair value could not exceed the strike. The printed averages need further reconciliation rather than proving that claim.","set":1},{"id":"cr-s26-q7","session":26,"topic":"Recognition vs disclosure theme","question":"Two otherwise identical firms account for the same option cost differently: one recognises it in the income statement, the other discloses it only in the notes. What does the investor relevance evidence on recognition versus disclosure support?","choices":["Investors ignore option costs in both cases, because no cash is involved","Investors give disclosed values more weight, because notes are audited more closely","Investors treat the two the same way, so the location of the figure makes no difference","Investors give recognised values more weight than disclosed ones, favouring the income statement"],"correct_index":3,"explanation":"Recognition carries more weight than disclosure in investor decisions. A reader of the income statement alone can miss a cost that sits only in the notes, as the historical gap between reported profit and pro forma loss illustrates.","set":1},{"id":"cr-s26-q8","session":26,"topic":"Common mistake, at the money assumption","question":"An analyst claims every historical intrinsic value award has zero compensation cost. How does an option granted below the current market share price challenge that claim?","choices":["No: an option granted in the money gives an expense equal to price minus exercise price","No: the method requires fair value for options with more than three years to run","Yes for equity settled awards, and no for cash settled awards under the method","Yes, because the method ignores every element of option value at grant date"],"correct_index":0,"explanation":"Zero expense is the outcome for at the money options only. An option granted with the exercise price below the share price has intrinsic value at grant and creates an expense.","set":1},{"id":"cr-s26-q9","session":26,"topic":"Common mistake, historical framework confusion","question":"A student argues that IFRS 2 allows disclosing the fair value cost of employee options in a footnote only, without recognising any expense. What is wrong with that claim?","choices":["IFRS 2 requires recognition for cash settled awards and disclosure for equity settled ones","IFRS 2 allows it, but only when the fair value appears in the strategic report","IFRS 2 has always required recognition at fair value, so that approach is not available under IFRS","IFRS 2 allows it, but only for options granted at the money"],"correct_index":2,"explanation":"APB 25 and SFAS 123 coexisted in the US, one for recognition and one for disclosure. IFRS 2 never made fair value optional or disclosure only.","set":1},{"id":"cr-s26-q10","session":26,"topic":"Interpreting the pro forma loss","question":"A company's fair value pro forma statement reports a loss for the year, driven by a noncash option compensation adjustment. Can that adjustment alone establish weak operating cash generation?","choices":["Yes, because option costs are cash costs paid to employees","No: a non-cash option expense alone does not determine operating cash generation","Yes, because the loss shows the share price was below the exercise price","No, because the pro forma figures exclude tax and so overstate the cost"],"correct_index":1,"explanation":"Fair value compensation expense reflects employee services paid with options rather than an immediate cash payment. It affects earnings and can dilute shareholders, but on its own it says nothing about operating cash flow.","set":1},{"id":"cr-s27-q1","session":27,"topic":"Four categories of employee benefits","question":"Employees receive a redundancy offer that is now irrevocable. At what point must the employer recognise the termination benefit obligation?","choices":["When the board first discusses the plan in a private meeting","Over the remaining service of the affected employees, as it is rendered","When the offer can no longer be withdrawn, or earlier if restructuring costs are recognised","When the cash is paid to the employees who accept"],"correct_index":2,"explanation":"Termination benefits are not earned through service. The liability arises when the entity is demonstrably committed and cannot withdraw the offer, or when it recognises the related restructuring costs under IAS 37, whichever is earlier.","set":1},{"id":"cr-s27-q2","session":27,"topic":"Defined contribution plans","question":"A company pays 8% of salary into an external fund and has no obligation to pay more if the fund falls short. How does it account for the plan?","choices":["As a defined contribution plan, expensing the contributions due, with the investment risk borne by employees","As a defined benefit plan, deducting the contributions from the net obligation","As a defined benefit plan, because the company funds the plan through an external fund","As a defined contribution plan, but with the investment risk borne by the company"],"correct_index":0,"explanation":"The company's cost is fixed at the contributions due. Employees receive whatever the fund produces, so the actuarial and investment risk sits with them, which is exactly the defined contribution classification.","set":1},{"id":"cr-s27-q3","session":27,"topic":"Defined benefit plans","question":"A plan promises a pension of 60% of final salary, and the fund's investments earn less than expected. Who bears the shortfall and how does it show?","choices":["The fund trustees bear it, so the employer's accounts do not change","The employer and employees share it, in proportion to their contributions","The employees bear it, because their pensions are reduced automatically","The employer bears it, and the net defined benefit liability increases"],"correct_index":3,"explanation":"In a defined benefit plan the employer promises the benefit. Worse than expected returns or actuarial experience raise the employer's net obligation. the promise does not shrink with the assets.","set":1},{"id":"cr-s27-q4","session":27,"topic":"Projected unit credit method","question":"A lump sum of 200 is earned for each year of service, and the employee will leave after five years. At the end of year two, three years remain and the discount rate is 10%. What is the closing obligation?","choices":["400.00","300.53","150.26","363.64"],"correct_index":1,"explanation":"Two units are accrued: 400. Discounting over the remaining three years at 10% gives 400 / 1.331 = 300.53. The 150.26 figure is the current service cost, one unit discounted.","set":1},{"id":"cr-s27-q5","session":27,"topic":"Discount rate","question":"A deep market in high quality euro corporate bonds exists. A pension plan pays benefits in euros with an average term of twelve years. Which discount rate does IAS 19 require?","choices":["The rate at which the company itself could borrow from its bank today","The rate stated in the plan documents when the plan was set up","The market yield at the reporting date on high quality corporate bonds of a matching term","The expected return on the plan assets over the next twelve years"],"correct_index":2,"explanation":"The discount rate reflects the time value of money, not the risk of the plan assets or of the employer. It uses high quality corporate bond yields in the same currency and with a similar term at the reporting date.","set":1},{"id":"cr-s27-q6","session":27,"topic":"P&L cost components","question":"In accounting for a defined benefit pension, which two components belong in current profit or loss rather than remeasurement OCI or balance sheet cash movements?","choices":["Service cost and remeasurements of the defined benefit obligation","Employer contributions and remeasurements of the plan assets","Net interest and benefits paid to retired employees in the year","Service cost and net interest on the net defined benefit liability"],"correct_index":3,"explanation":"Profit or loss carries the cost of service and the net effect of discounting. Remeasurements go to other comprehensive income, while contributions and benefits paid are balance sheet movements.","set":1},{"id":"cr-s27-q7","session":27,"topic":"Remeasurements","question":"A fall in the discount rate raises a defined benefit obligation by 30,000, and plan assets earn 10,000 more than the interest income credited. What is the effect?","choices":["A net charge of 30,000 in OCI, since asset gains are ignored","A net charge of 20,000 in OCI, never recycled to profit or loss","A net charge of 20,000 in OCI, recycled to profit when the plan ends","A net charge of 20,000 in profit or loss for the year"],"correct_index":1,"explanation":"Remeasurements of the obligation and the excess return on assets both go to OCI. They net to a 20,000 charge and are never recycled to profit or loss.","set":1},{"id":"cr-s27-q8","session":27,"topic":"Plan assets, interest income","question":"Assume all contributions and benefit payments occur at year end. Plan assets at the start of the year are 450,000, the discount rate is 10% and the actual return is 50,000. How is the return reported?","choices":["50,000 as interest income in profit or loss and nothing in OCI","5,000 as interest income in profit or loss and 45,000 in OCI","45,000 as interest income in profit or loss and 5,000 as a remeasurement in OCI","45,000 and 5,000 both in profit or loss, since both relate to plan assets"],"correct_index":2,"explanation":"Interest income uses the discount rate on the opening assets: 45,000. The extra 5,000 of actual return above that is a remeasurement and goes to OCI.","set":1},{"id":"cr-s27-q9","session":27,"topic":"Other long-term benefits vs defined benefit","question":"Revised assumptions add 20,000 to a long service leave liability classified as an other long term employee benefit. Does the remeasurement enter profit or loss or OCI?","choices":["In profit or loss, because other long term benefits have no OCI split","In OCI, never recycled to profit or loss","In OCI, recycled to profit when the leave is taken","Directly in equity, outside both profit or loss and OCI"],"correct_index":0,"explanation":"Other long term benefits use mechanics similar to defined benefit plans, but every remeasurement runs through profit or loss. The OCI treatment belongs to post employment defined benefit plans only.","set":1},{"id":"cr-s27-q10","session":27,"topic":"Past service cost","question":"In July an employer improves pension benefits for service already rendered. The amendment raises the obligation by 40,000. When does that past service cost enter the accounts?","choices":["Over the remaining service lives of the current employees","Immediately in profit or loss at the amendment date","When the extra benefits are paid out to retirees","In OCI, because it relates to earlier periods"],"correct_index":1,"explanation":"Past service cost is recognised at once in profit or loss, because the plan change creates an obligation for service already rendered. It is never spread forward.","set":1},{"id":"cr-s27-q11","session":27,"topic":"Comprehensive example","question":"Assume all contributions and benefit payments occur at year end. A plan starts the year with an obligation of 500,000 and assets of 450,000, with a 10% discount rate. During the year the service cost is 150,000, benefits paid are 80,000, contributions are 100,000, the actuarial remeasurement of the obligation is 75,000 and the actual return on assets is 50,000. What is the net liability at year end?","choices":["175,000","695,000","100,000","275,000"],"correct_index":0,"explanation":"The obligation is 500,000 + 50,000 interest + 150,000 service + 75,000 remeasurement - 80,000 paid = 695,000. Assets are 450,000 + 50,000 actual return + 100,000 contributions - 80,000 paid = 520,000. Net liability: 175,000.","set":1},{"id":"cr-s27-q12","session":27,"topic":"Common mistake, contributions and benefits paid","question":"In a funded defined benefit plan, a student records an employer contribution of 100,000 and benefits paid of 80,000 as expenses of the year. What is wrong?","choices":["Benefits paid are an expense, but contributions are only a balance sheet movement","Both are expenses, but only after being netted against the interest income","Contributions are an expense, but benefits paid are only a balance sheet movement","Neither: contributions raise plan assets, and benefits paid reduce both the obligation and the assets"],"correct_index":3,"explanation":"Cash moving into the fund and cash paid out of it change the balance sheet only. The year's expense is service cost plus net interest, not the funding flows.","set":1},{"id":"cr-s28-q1","session":28,"topic":"Five standards framework","question":"A parent reports investments in its subsidiaries in its own separate financial statements, rather than presenting the group as one entity. Which standard governs that separate reporting?","choices":["IAS 27, because separate statements are outside the scope of IFRS 10","IFRS 12, because it sets out how investments are presented","IAS 28, because it covers investments a parent holds in other entities","IFRS 10, because it governs every set of statements showing subsidiaries"],"correct_index":0,"explanation":"IFRS 10 covers consolidated statements and IAS 27 the parent's separate statements. IAS 28 sets the equity method, IFRS 11 deals with joint arrangements and IFRS 12 with disclosures.","set":1},{"id":"cr-s28-q2","session":28,"topic":"Investment treatment by type","question":"In its consolidated statements a company holds a 30% stake with significant influence in one entity and a 5% stake without influence in a listed entity. How are the two treated?","choices":["The first by full consolidation, and the second at fair value under IFRS 9","The first by the equity method, and the second at fair value under IFRS 9","Both by the equity method, because both are minority holdings","Both at cost, because neither stake gives control"],"correct_index":1,"explanation":"Associates are accounted for by the equity method under IAS 28, while investments without significant influence are financial assets at fair value under IFRS 9. Full consolidation applies only to subsidiaries.","set":1},{"id":"cr-s28-q3","session":28,"topic":"Three-part control test","question":"An investor holds 45% of an investee. A contract gives it the power to direct the activities that most affect returns, and its returns vary with the investee's results. Does it control the investee? It can use those direction rights to affect its variable returns.","choices":["Yes, because it has power, exposure to variable returns and the ability to use its power to affect them","No, because exposure to variable returns is never enough without a majority","Yes, but only if it also appoints most of the board","No, because control always requires more than half of the voting rights"],"correct_index":0,"explanation":"Control needs all three elements, and power can come from contractual rights, not only from a voting majority. A 45% holder can control when the test is met.","set":1},{"id":"cr-s28-q4","session":28,"topic":"Protective rights","question":"A bank lends to a company and has a covenant letting it veto the sale of major assets, but no say in operating decisions. Does the bank control the company?","choices":["No, because the veto is a protective right and gives no power over the relevant activities","No, but only because the bank holds less than half of the voting rights","Yes, because the veto lets the bank stop any decision that harms its loan","Yes, because the covenant is extensive and covers the largest transactions"],"correct_index":0,"explanation":"Protective rights shield the holder's interest without giving power, however extensive they seem. Control requires the ability to direct the relevant activities.","set":1},{"id":"cr-s28-q5","session":28,"topic":"Substantive rights","question":"Relevant decisions must be made before the needed approval can be obtained. An investor holds 40% of the votes and an option over another 20%, exercisable only after a regulatory approval it cannot influence and has not yet received. Does the option count in assessing power?","choices":["Yes, but only if the option is in the money at the reporting date","Yes, because any option over voting shares counts","No: the unresolved approval prevents practical exercise when the relevant decisions must occur","No, but it must be disclosed as a contingent asset"],"correct_index":2,"explanation":"Potential voting rights count only if they are substantive, meaning practically exercisable when decisions about the relevant activities need to be made. Here the unresolved approval removes that ability, though IFRS 10 does not universally demand immediate exercisability at the reporting date.","set":1},{"id":"cr-s28-q6","session":28,"topic":"Consolidation exemption","question":"A wholly owned company is unlisted, has no publicly traded debt or equity instruments and has not filed with any regulator, and its ultimate parent publishes IFRS group accounts that are publicly available. It is not an investment entity. Must it prepare group accounts for its own subsidiaries?","choices":["Yes, because wholly owned parents must consolidate even when exemption conditions are satisfied","No, because being unlisted alone exempts every parent","Yes, unless some subsidiaries are individually immaterial to its own statements","No, because all the conditions for the exemption are met"],"correct_index":3,"explanation":"A parent may skip consolidation when it is itself owned by another entity, is not publicly traded, has not filed with a regulator and its ultimate parent publishes IFRS group accounts. On the stated facts every condition holds.","set":1},{"id":"cr-s28-q7","session":28,"topic":"Simple elimination mechanics","question":"Alfa pays 800 for 80% of Gamma, whose equity of 1,000 equals fair value, so no goodwill arises. What non-controlling interest appears on consolidation?","choices":["1,000","200","0","800"],"correct_index":1,"explanation":"The investment of 800 is eliminated against 80% of Gamma's equity, and the remaining 20% of 1,000 is the non-controlling interest: 200.","set":1},{"id":"cr-s28-q8","session":28,"topic":"Step-up direction","question":"At acquisition a patent carried at 500 has a fair value of 1,000, the tax base stays at 500 and the tax rate is 50%. What is the effect in the consolidated balance sheet?","choices":["The patent rises by 500 and a deferred tax asset of 250 arises, with no income effect","The patent rises by 500 and no deferred tax arises, because the step up is a group entry","The patent rises by 500 and the 500 is recognised as income in the acquisition year","The patent rises by 500 and a deferred tax liability of 250 arises, with no income statement effect"],"correct_index":3,"explanation":"The step up is a balance sheet adjustment at acquisition. The asset now exceeds its tax base, a taxable temporary difference, so a deferred tax liability of 250 arises alongside it.","set":1},{"id":"cr-s28-q9","session":28,"topic":"Goodwill formula, partial method","question":"Alfa pays 7,000 for 70% of Delta, and Delta's fair value of net assets, after step ups and deferred tax, is 9,000. What goodwill arises under the partial method?","choices":["2,000","2,700","700","1,400"],"correct_index":2,"explanation":"The parent's share of net assets is 70% × 9,000 = 6,300, so goodwill is 7,000 - 6,300 = 700. The non-controlling interest is 30% × 9,000 = 2,700.","set":1},{"id":"cr-s28-q10","session":28,"topic":"Goodwill formula, full method","question":"Alfa pays 7,000 for 70% of Delta, the 30% non-controlling stake has a fair value of 3,000 and Delta's fair value of net assets is 9,000. What goodwill arises under the full method?","choices":["300","1,000","2,000","700"],"correct_index":1,"explanation":"Full goodwill is consideration of 7,000 plus the non-controlling interest at fair value of 3,000, less net assets of 9,000: 1,000. It exceeds the partial method figure because it also captures the minority's share of goodwill.","set":1},{"id":"cr-s28-q11","session":28,"topic":"Negative goodwill","question":"Reassessment confirms all acquisition measurements are correct. A parent pays 5,000 for 100% of a subsidiary whose fair value of net assets is 5,800. How is the difference treated?","choices":["As a liability of 800 released over the following three years","As a negative asset of 800 amortised over its useful life","As a gain of 800 in profit or loss at the acquisition date","As an 800 reduction of reserves taken directly to equity"],"correct_index":2,"explanation":"A bargain purchase, after the required reassessment, is recognised immediately as income in profit or loss. It is the opposite of positive goodwill, which sits as an asset tested for impairment.","set":1},{"id":"cr-s28-q12","session":28,"topic":"Common mistake, control and voting majority","question":"An investor holds 55% of the votes, but a regulator has appointed a trustee who directs all the relevant activities and the investor cannot remove the trustee. Does the majority give control?","choices":["Yes, because majority votes override the trustee's direction","No, solely because a majority eliminates exposure to variable returns","Yes, because legal share ownership supplies power even when it cannot direct decisions","No, because a majority does not give power when the rights are not substantive"],"correct_index":3,"explanation":"Control requires power in practice. When the holder cannot direct the relevant activities, a voting majority on paper is not enough.","set":1},{"id":"cr-s29-q1","session":29,"topic":"Intra-group balances","question":"A parent lends 20,000 to its 80% subsidiary and receives 1,000 of interest during the year. How is this treated in the consolidated statements?","choices":["The loan is cancelled in full, but the interest stays as group income","The loan is shown net within the non-controlling interest, and the interest is cancelled","The loan receivable and payable, and the interest income and expense, are all cancelled in full","The loan is cancelled at 80% only, and the interest at the same percentage"],"correct_index":2,"explanation":"A group cannot owe money to itself or earn interest from itself. Intragroup balances and flows are eliminated in full, whatever the ownership percentage.","set":1},{"id":"cr-s29-q2","session":29,"topic":"Downstream unrealised profit","question":"A parent sells goods to its 80% subsidiary for 3,000. They cost the parent 2,000, and all are unsold at year end. Who bears the 1,000 profit elimination?","choices":["Group retained earnings bear all 1,000, and the non-controlling interest bears nothing","No one, because the profit is eliminated only when the goods are later sold","The non-controlling interest bears all 1,000, because the goods sit in the subsidiary","Group retained earnings bear 800 and the non-controlling interest bears 200"],"correct_index":0,"explanation":"The profit was earned by the parent, which belongs to the group shareholders alone. The minority did not generate it, so none of a downstream elimination is charged to the non-controlling interest.","set":1},{"id":"cr-s29-q3","session":29,"topic":"Upstream unrealised profit","question":"A 75% owned subsidiary sells goods to its parent with an unrealised profit of 800. All the goods are unsold at year end. How is the elimination allocated?","choices":["600 against group retained earnings and 200 against the non-controlling interest","200 against group retained earnings and 600 against the non-controlling interest","800 against group retained earnings and nothing against the non-controlling interest","Nothing against group retained earnings and 800 against the non-controlling interest"],"correct_index":0,"explanation":"The partly owned subsidiary generated the profit, so an upstream elimination is shared in proportion to ownership: 75% by the group and 25% by the minority.","set":1},{"id":"cr-s29-q4","session":29,"topic":"Step-up depreciation post-acquisition","question":"At acquisition an item of equipment was stepped up by 2,000. It has ten years of remaining life and the tax rate is 40%. What is the yearly consolidation effect?","choices":["Extra depreciation of 200, with an 80 deferred tax asset recognised","Extra depreciation of 200, with 80 of the deferred tax liability reversed","Extra depreciation of 2,000 in the first year, with 800 of the liability reversed","Extra depreciation of 200, with no deferred tax effect since it is a group entry"],"correct_index":1,"explanation":"The step up is depreciated over the remaining life: 2,000 / 10 = 200 a year. The deferred tax liability recognised at acquisition unwinds by 40% × 200 = 80, as a tax benefit.","set":1},{"id":"cr-s29-q5","session":29,"topic":"Inventory unrealised profit example","question":"Assume sufficient probable future taxable profit and no recognition exception. A subsidiary sells goods to its parent for 6,000. They cost the subsidiary 4,500, and all are unsold at year end. The tax rate is 40%. What are the consolidation adjustments to inventory and deferred tax? Assume the buyer tax base follows the internal transfer price.","choices":["Inventory is reduced by 1,500 and a deferred tax liability of 600 is recognised","Inventory is reduced by 6,000 and a deferred tax asset of 2,400 is recognised","Inventory is reduced by 1,500 and a deferred tax asset of 600 is recognised","Inventory is reduced by 1,500 and no deferred tax arises on the elimination"],"correct_index":2,"explanation":"Inventory returns to its original group cost of 4,500, a reduction of 1,500. The seller already paid tax on a profit the group has not yet earned, so a deferred tax asset of 40% × 1,500 = 600 arises.","set":1},{"id":"cr-s29-q6","session":29,"topic":"Inventory write-down absorption","question":"Goods costing the group 1,600 are transferred internally for 2,000. Still unsold at year end, the buyer has already reduced them to an NRV of 1,800. What additional internal profit remains to eliminate?","choices":["200","0","600","400"],"correct_index":0,"explanation":"The internal profit was 400. The subsidiary's write down of 200 has already absorbed half of it, so only the remaining 200 must be eliminated.","set":1},{"id":"cr-s29-q7","session":29,"topic":"Genuine losses","question":"An internal inventory transfer records a loss because goods with a group cost of 1,000 are sold for 700. Their NRV has genuinely fallen to 700 and they remain unsold. Should consolidation reverse that loss?","choices":["The loss is deferred and released only when the subsidiary sells the goods outside the group","The inventory is restored to 1,000 as an unrealised loss created by the internal sale","No adjustment is made, because the loss reflects a genuine decline in value","The inventory is restored to 1,000 and a deferred tax liability is recognised on the 300"],"correct_index":2,"explanation":"The parent would have written the inventory down to net realisable value anyway. Only losses created by internal pricing, not real declines in value, are reversed on consolidation.","set":1},{"id":"cr-s29-q8","session":29,"topic":"Fixed asset intra-group sale","question":"Assume sufficient probable future taxable profit and no recognition exception. A parent sells a machine to a subsidiary for 900. Its book value was 600. The subsidiary depreciates it by 180 in the year, and the parent would have charged 120. The tax rate is 50%. What is the reduction in consolidated pre-tax profit and the deferred tax asset? Assume the buyer tax base follows the internal transfer price and, for machinery, its tax depreciation matches its booked depreciation.","choices":["A reduction of 240 and a deferred tax liability of 120","A reduction of 240 and a deferred tax asset of 120","A reduction of 300 and a deferred tax asset of 150","A reduction of 360 and a deferred tax asset of 180"],"correct_index":1,"explanation":"The gain of 300 is eliminated and the excess depreciation of 60 is reversed, so pre-tax profit falls by 240. The group carrying amount is below the tax base by 240, giving a deferred tax asset of 50% × 240 = 120.","set":1},{"id":"cr-s29-q9","session":29,"topic":"Intra-group dividends","question":"A 75% owned subsidiary pays total dividends of 2,000. What happens on consolidation?","choices":["The non-controlling interest falls by the full 2,000, because the subsidiary paid it","All 2,000 is eliminated against group reserves, and the non-controlling interest is unchanged","The parent's 1,500 stays as group income, and the non-controlling interest falls by 500","The parent's 1,500 of dividend income is eliminated, and the non-controlling interest falls by 500"],"correct_index":3,"explanation":"The group cannot pay itself a dividend, so the parent's 1,500 share of the income is cancelled. Only the 500 paid to outside minority shareholders leaves the group and reduces their equity.","set":1},{"id":"cr-s29-q10","session":29,"topic":"NCI's share of net income, golden rule","question":"A subsidiary is 60% owned, and a step up on its equipment adds 100 of depreciation. How is the adjustment applied before the non-controlling interest is computed?","choices":["At 40% only, because the adjustment affects the minority alone","At 100% in full, and the minority's share is separated afterwards","At 60% only, which is the group's share of the subsidiary","At 100% but only for the group, with the minority's share ignored"],"correct_index":1,"explanation":"Consolidation takes in the subsidiary in full, and so does every adjustment to its figures. The non-controlling interest is split out only at the end of the process.","set":1},{"id":"cr-s29-q11","session":29,"topic":"NCI net income formula","question":"A subsidiary reports net income of 2,000 and has 20% minority holders. Depreciation on a step up of its own assets reduces income by 150 after tax. A downstream sale by the parent reduces group income by 300 after tax. What is the minority's share of net income?","choices":["340","310","400","370"],"correct_index":3,"explanation":"Only adjustments arising in the subsidiary affect the minority's base: 20% × (2,000 - 150) = 370. The parent's downstream adjustment is charged wholly to the group.","set":1},{"id":"cr-s29-q12","session":29,"topic":"Common mistake, downstream vs upstream","question":"An analyst splits the unrealised profit on a sale from a parent to its partly owned subsidiary between the group and the minority in proportion to ownership. What is wrong with that?","choices":["Only the subsidiary ownership percentage should be eliminated, leaving the minority's part in group profit","The elimination should be allocated to the NCI because the subsidiary still holds the unsold goods","The profit should be eliminated only when the subsidiary eventually sells the inventory outside the group","The wholly owned parent earned the profit, so the whole elimination is charged to group retained earnings"],"correct_index":3,"explanation":"The proportionate split applies to upstream sales, where the partly owned subsidiary made the profit. For downstream sales the minority bears nothing.","set":1},{"id":"cr-s30-q1","session":30,"topic":"Definition of a business","question":"Assume the organised scientists perform substantive processes critical to developing the facility's products. A company buys a research facility with scientists and intellectual property but no sales yet. Does IFRS 3 treat it as a business?","choices":["No, because a business must already be producing goods or services for customers","Yes, because substantive inputs and processes can make it a business even without outputs yet","No, because intellectual property is not an input that can be integrated","Yes, but only if sales are expected within twelve months of the purchase date"],"correct_index":1,"explanation":"A business is an integrated set of inputs and processes with the capability to produce outputs. Staff, intellectual property and ongoing research can meet the definition before any sales exist.","set":1},{"id":"cr-s30-q2","session":30,"topic":"IFRS3 scope, exclusions","question":"Two subsidiaries of the same parent merge. Does the merger fall within IFRS 3? The same ultimate party controls both before and after, and that control is not transitory.","choices":["No, but only because no cash is paid to the shareholders","Yes, because the larger of the two subsidiaries is treated as the acquirer","Yes, because one of them issues shares to the other as consideration","No, because combinations under common control are excluded from IFRS 3"],"correct_index":3,"explanation":"IFRS 3 excludes combinations of entities under common control, where the same parent controls both before and after. The absence of cash is not the reason.","set":1},{"id":"cr-s30-q3","session":30,"topic":"Four steps of the acquisition method","question":"To apply IFRS 3, an acquirer must establish control and the acquisition date before measuring the acquisition balances. Which ordering correctly takes the acquisition method through to goodwill?","choices":["Identify the acquirer, recognise goodwill, set the acquisition date, then measure net assets","Measure net assets, identify the acquirer, set the acquisition date, then recognise goodwill","Identify the acquirer, set the date, measure net assets, NCI and consideration, then recognise goodwill","Set the acquisition date, recognise goodwill, measure net assets, then identify the acquirer"],"correct_index":2,"explanation":"The acquirer and the date come first, because fair values are taken at the date control passes. Goodwill is the last step, since it depends on all the measured amounts.","set":1},{"id":"cr-s30-q4","session":30,"topic":"Reverse acquisitions","question":"Company X issues new shares to acquire 100% of Company Y. Afterwards Y's former shareholders own 70% of the combined entity, hold five of seven board seats and supply the CEO. Which company is the accounting acquirer?","choices":["Company X, because it issued the shares and is the surviving legal entity","Company Y, because its shareholders and management end up controlling the combined entity","Company X, because it paid for the shares by issuing new ones","Neither, because the transaction is a merger of equals"],"correct_index":1,"explanation":"IFRS 3 looks through the legal form to control. X is the legal acquirer, but Y's holders have the votes, the board and the management, so this is a reverse acquisition with Y as the accounting acquirer.","set":1},{"id":"cr-s30-q5","session":30,"topic":"Consideration transferred","question":"The price for a business comprises cash of 500 now, a deferred cash payment of 300 with a present value of 255, shares worth 100 and an earnout worth 40 at acquisition. What total consideration enters goodwill?","choices":["800","855","940","895"],"correct_index":3,"explanation":"Each component is measured at its acquisition date fair value: 500 + 255 + 100 + 40 = 895. Deferred payments are discounted and contingent consideration is included.","set":1},{"id":"cr-s30-q6","session":30,"topic":"Acquisition-related costs","question":"A business purchase generates legal advice fees of 30 and share issuance costs of 20. The shares are issued as consideration. Which separate accounting applies to those two cost categories?","choices":["Both are expensed in profit or loss as the services are received","Both are added to goodwill as part of the cost of the acquisition","Both are added to the consideration transferred and so to the cost of the investment","The legal fees are expensed, and the share issue costs are deducted from the issue proceeds"],"correct_index":3,"explanation":"Acquisition related advisory costs are expensed as the services are received. Costs of issuing equity are deducted from equity under IAS 32. They never enter the consideration or goodwill.","set":1},{"id":"cr-s30-q7","session":30,"topic":"Acquisition date","question":"The buyer signs on 10 June, gains control on shareholder approval on 20 June and receives legal title on 1 July. Which date anchors IFRS 3 acquisition measurements?","choices":["10 June, the date the agreement was signed by both parties","1 July, the date legal title transfers to the buyer","20 June, the date control passes to the buyer","30 June, the end of the reporting period for the buyer"],"correct_index":2,"explanation":"The acquisition date is the date control passes, which can differ from the signing or the legal transfer date. Fair values are measured at that date.","set":1},{"id":"cr-s30-q8","session":30,"topic":"Previously unrecognised assets","question":"The acquiree developed customer relationships internally and carries no asset for them. At acquisition the relationships satisfy either the contractual rights or separability criterion. What must the acquirer do with their fair value?","choices":["It recognises them at fair value as an identifiable intangible asset at the acquisition date","It does not recognise them, because internally generated intangibles are never recorded","It includes them in goodwill, because they cannot be sold separately from the business","It recognises them only if they produced revenue in the last financial year"],"correct_index":0,"explanation":"Acquisition accounting applies its own fair value recognition, not the acquiree's criteria. Internally generated intangibles that failed the acquiree's tests are recognised when they are identifiable.","set":1},{"id":"cr-s30-q9","session":30,"topic":"Goodwill formula","question":"Acquisition date amounts are consideration 6,000, fair value NCI 1,500, a prior interest worth 500 and identifiable net assets of 7,200. What residual goodwill results?","choices":["800","300","2,300","1,300"],"correct_index":0,"explanation":"Goodwill is consideration plus NCI plus the previously held interest, minus net assets: 6,000 + 1,500 + 500 - 7,200 = 800.","set":1},{"id":"cr-s30-q10","session":30,"topic":"Step acquisitions","question":"A company holds a 25% associate carried at 400, with a fair value of 500. It buys another 45% for 1,000 and gains control. How is the 25% treated? The acquired set is a business, and no prior OCI balance or other remeasurement effect exists.","choices":["It is remeasured to fair value of 500, and the 100 gain goes to profit or loss","It is remeasured to 500, and the 100 gain goes to other comprehensive income","It is remeasured to its cost, which is the price paid for the new shares","It stays at 400, because only the new shares are accounted for under IFRS 3"],"correct_index":0,"explanation":"Gaining control is treated as a new business combination. The earlier stake is remeasured to its acquisition date fair value, with the gain or loss in profit or loss.","set":1},{"id":"cr-s30-q11","session":30,"topic":"Disposals without losing control","question":"A parent sells 10% of a subsidiary and keeps control. The proceeds exceed the carrying amount of the interest sold by 80. Where is the 80 recognised?","choices":["As a reduction in goodwill, because the group's share has decreased","In equity, because a disposal that keeps control is an equity transaction","In other comprehensive income, as a gain on a financial asset","In profit or loss, as a gain on disposal of part of the subsidiary"],"correct_index":1,"explanation":"Control does not change, so the group's economic entity is the same. The difference is reallocated within equity between the parent and the non-controlling interest, never through profit or loss.","set":1},{"id":"cr-s30-q12","session":30,"topic":"Common mistake, contingent liabilities","question":"An acquired lawsuit is a present obligation from past events. Its fair value is reliably measurable at 90, although an outflow is possible rather than probable. What is its acquisition date treatment under IFRS 3?","choices":["It is recognised only if the target had already recorded it in its own accounts","It is only disclosed in the notes, because it is a possible obligation","It is recognised as a liability at its fair value of 90 in the acquisition accounting","It is not recognised, because the outflow is not probable under IAS 37"],"correct_index":2,"explanation":"IFRS 3 recognises a contingent liability assumed in a business combination when it is a present obligation from past events and its fair value is reliably measurable, even if payment is not probable. A merely possible obligation does not meet this test.","set":1},{"id":"cr-s31-q1","session":31,"topic":"Control assessment","question":"Lyradon holds 65% and four of six board seats. Meetings also require an Alpine director for quorum, with no fallback specified. What must be assessed before concluding sole control?","choices":["Whether Alpine can substantively block decisions through the mandatory quorum rule","Whether the earn-out is settled before board appointment rights become effective","Whether the majority shareholding automatically overrides every contractual quorum requirement","Whether the minority stake is too small to have any contractual rights"],"correct_index":0,"explanation":"The agreement requires an Alpine appointed director for quorum. Four seats and simple majority voting do not alone prove practical unilateral power if meetings can be blocked. The rights and the practical operation of the quorum need assessment under IFRS 10 before concluding sole control.","set":1},{"id":"cr-s31-q2","session":31,"topic":"Alpine's veto rights","question":"Assess only the listed extraordinary consent rights, excluding the separate quorum issue. Alpine, a 30% holder, must consent to dividends, buybacks, capital reductions and financing above 50 million euros. What do these rights do to Lyradon's control? Lyradon otherwise directs the relevant operating activities, and the listed reserved matters do not themselves direct those activities in this case.","choices":["They reduce Lyradon to significant influence, because it cannot act alone on every matter","Nothing, because a shareholder with less than half the votes cannot hold any substantive right","They remove control, because Alpine's consent makes the two investors jointly in control","Nothing, because they are protective rights that guard Alpine's interest and do not direct ordinary activities"],"correct_index":3,"explanation":"On these stated extraordinary matters, the rights protect Alpine against major changes and do not by themselves direct the ordinary relevant activities. This classification does not settle the separate Alpine presence quorum issue or guarantee sole control over the complete case.","set":1},{"id":"cr-s31-q3","session":31,"topic":"What would flip the conclusion","question":"Which change would be most likely to make Alpine's rights substantive and call Lyradon's sole control into question? Assume Lyradon otherwise has a board majority and the listed new rights govern the activities that most affect returns.","choices":["Raising the financing consent threshold from 50 million euros to 100 million euros","Giving Alpine a second board seat while board decisions still pass by simple majority","Adding a right for Alpine to receive annual financial statements within 60 days","Requiring Alpine's consent for annual budgets, research programmes and major commercial contracts"],"correct_index":3,"explanation":"Rights become substantive when they reach the decisions that drive the investee's returns. A higher threshold or an information right makes Alpine's rights more protective, and a second seat cannot block a simple majority.","set":1},{"id":"cr-s31-q4","session":31,"topic":"Acquisition date","question":"Signing occurs on 3 June 2024, but substantive control passes only at completion on 1 July 2024. On which date does the business combination occur for accounting purposes?","choices":["31 December 2025, when the earn-out period ends","1 July 2024, when control transfers at completion","30 June 2024, the day before completion","3 June 2024, when the agreement is signed"],"correct_index":1,"explanation":"The acquisition date is the date control passes. Signing the agreement does not transfer control, and the earn-out period does not delay it.","set":1},{"id":"cr-s31-q5","session":31,"topic":"Fair value of net identifiable assets","question":"Before fair value adjustments, Velquanta has equity of 13,000 thousand euros. Acquisition recognition adds property 3,000, developed technology 8,000, customer relationships 5,000 and in-process research 2,000, and adds a liability of 1,000. With tax excluded, what net identifiable assets result?","choices":["31,000","28,000","30,000","17,000"],"correct_index":2,"explanation":"The net adjustment is 3,000 + 8,000 + 5,000 + 2,000 - 1,000 = 17,000, and 13,000 + 17,000 = 30,000. Leaving out the liability would give 31,000.","set":1},{"id":"cr-s31-q6","session":31,"topic":"Goodwill, partial method","question":"Using only the cash consideration of 48,000 thousand euros for 65%, net identifiable assets of 30,000 and the partial method, what is goodwill? Ignore the earn-out and deferred tax.","choices":["27,850","18,000","39,550","28,500"],"correct_index":3,"explanation":"The group's share of net assets is 65% × 30,000 = 19,500, so goodwill is 48,000 - 19,500 = 28,500. A positive fair value earnout would increase consideration and goodwill, holding these other amounts fixed.","set":1},{"id":"cr-s31-q7","session":31,"topic":"NCI, partial method","question":"Net identifiable assets are 30,000 thousand euros and the non-controlling holders own 35%. Under the partial method, what is the non-controlling interest?","choices":["10,500","4,550","9,000","10,850"],"correct_index":0,"explanation":"The partial method measures the NCI at its proportionate share of the fair value of net identifiable assets: 35% × 30,000 = 10,500.","set":1},{"id":"cr-s31-q8","session":31,"topic":"Contingent consideration","question":"An EBITDA based earnout forms part of the business purchase price and is not pay for continued employment. Its future payout is capped and uncertain. Which value of that earnout belongs in acquisition consideration?","choices":["It is left out until it is paid, because it depends on a future event","Its fair value at the acquisition date is included in the consideration transferred","It is included only if the EBITDA target is met and the payment becomes probable","It is expensed as compensation, because it depends on future performance"],"correct_index":1,"explanation":"IFRS 3 requires contingent consideration at its acquisition date fair value as part of the price. Waiting for the outcome would understate goodwill.","set":1},{"id":"cr-s31-q9","session":31,"topic":"Previously unrecognised intangibles","question":"All three items meet the acquisition date identifiability requirements. Velquanta never recorded its developed technology, customer relationships or in-process research, which are valued at 15,000 thousand euros together. How does Lyradon treat them?","choices":["It recognises them at zero and shows their value only in the notes","It recognises them at fair value in the acquisition accounting, even though Velquanta could not","It leaves them out, because internally generated intangibles are never recognised","It includes them in goodwill, because they cannot be sold separately from the business"],"correct_index":1,"explanation":"Identifiable acquired intangibles are recognised at acquisition fair value even if absent from the acquiree's accounts. This does not mean internally developed technology could never qualify for recognition under IAS 38 before the acquisition.","set":1},{"id":"cr-s31-q10","session":31,"topic":"Transaction and due diligence costs","question":"Apart from the business purchase price, Lyradon pays advisers 1.2 million euros for due diligence covering legal, financial and tax work. Does that payment create goodwill or a service expense?","choices":["They are expensed when incurred and not included in goodwill or the consideration","They are added to goodwill, because they were necessary to complete the acquisition","They are added to the cost of the investment in Lyradon's separate statements only","They are spread over the first five years as a cost of the transaction"],"correct_index":0,"explanation":"Acquisition related costs are expenses of the period when the services are received. They are not part of what the buyer pays for the business.","set":1},{"id":"cr-s31-q11","session":31,"topic":"Common mistake, veto rights and control","question":"In assessing Lyradon control, someone treats the word veto as enough to deny consolidation. Which assessment should replace that label based conclusion?","choices":["Veto rights matter only when the earn-out price is finally settled","Veto rights count only after the minority first uses them in practice","Assess relevant activity rights and practical quorum effects, not the label veto","A 30% holding is too small for any veto right to matter"],"correct_index":2,"explanation":"The protective versus substantive assessment concerns what the rights actually enable. Extraordinary consent rights may be protective, but the separate Alpine presence quorum provision needs an assessment of practical blocking power. Neither all vetoes nor a majority alone settles control.","set":1},{"id":"cr-s14-d20261024-l1-q1","session":14,"level":1,"set":2,"supplement":"2026-10-24","topic":"Warranty portfolio","question":"A retailer sold 2,000 products with assurance warranties. Each product has a 70% chance of no repair, a 20% chance of a €30 repair and a 10% chance of a €90 repair. Claims arise from these sales and discounting is immaterial. What IAS 37 provision is required?","choices":["€12,000","€18,000","€30,000","€60,000"],"correct_index":2,"explanation":"Expected repair cost per item is 20% × €30 + 10% × €90 = €15. The provision is 2,000 × €15 = €30,000. Assess the large warranty population together, not each individual claim in isolation."},{"id":"cr-s14-d20261024-l1-q2","session":14,"level":1,"set":2,"supplement":"2026-10-24","topic":"Constructive obligation","question":"Before year-end, a factory polluted land. No law requires cleanup, but its public cleanup policy and consistent past practice have created a valid expectation that it will clean the land. Cleanup is probable and reliably estimated at €160,000. What is the treatment?","choices":["Recognise a €160,000 provision for the cleanup.","Disclose €160,000 without recognising a provision.","Recognise €160,000 only when the work begins.","Spread €160,000 over future production periods."],"correct_index":0,"explanation":"The pollution is a past event. The published policy and established conduct create a constructive obligation. With a probable outflow and a reliable estimate, IAS 37 requires a provision now, even without a legal duty."},{"id":"cr-s14-d20261024-l1-q3","session":14,"level":1,"set":2,"supplement":"2026-10-24","topic":"Avoidable future costs","question":"A company plans a mandatory safety inspection in three years if it keeps operating a machine. It can sell the machine before then without paying for the inspection. No present inspection obligation exists. Which treatment follows IAS 37?","choices":["Provide one third of the inspection cost this year.","Provide the discounted inspection cost this year.","Provide the cost when next year's budget is approved.","Do not provide for the planned inspection this year."],"correct_index":3,"explanation":"The inspection depends on the company's future decision to continue using the machine. It can avoid the expenditure by selling. A budget or a desire to spread future costs does not create a present obligation."},{"id":"cr-s14-d20261024-l1-q4","session":14,"level":1,"set":2,"supplement":"2026-10-24","topic":"Recognition threshold","question":"At year-end, a company has a present legal obligation. Legal advisers assess a 40% chance of paying €300,000 and a 60% chance of paying nothing. No other outcomes exist. The exposure is material. What is required under IAS 37?","choices":["Recognise a €120,000 provision for expected damages.","Disclose a contingent liability without a provision.","Recognise a €300,000 provision for full damages.","Omit both recognition and disclosure of the case."],"correct_index":1,"explanation":"An outflow is possible but not probable because the probability is 40%. The material exposure is disclosed as a contingent liability. Multiplying damages by probability does not overcome the recognition threshold for this single obligation."},{"id":"cr-s14-d20261024-l1-q5","session":14,"level":1,"set":2,"supplement":"2026-10-24","topic":"Contingent assets","question":"A company claims damages from a supplier. At year-end, receipt of €240,000 is probable but not virtually certain. The claim is material. Which treatment follows IAS 37?","choices":["Recognise €240,000 as an asset and income.","Recognise the probability-weighted claim as income.","Disclose the claim without recognising an asset.","Defer disclosure until settlement cash is received."],"correct_index":2,"explanation":"A probable inflow from a contingent asset is disclosed, not recognised. Recognition requires virtual certainty, at which point it is no longer a contingent asset. The liability recognition threshold cannot be reused for gains."},{"id":"cr-s14-d20261024-l1-q6","session":14,"level":1,"set":2,"supplement":"2026-10-24","topic":"Unwinding","question":"On 1 January, a provision for an existing cleanup obligation is €200,000 at present value. Its discount rate is 5%. No settlement, estimate change or rate change occurs during the year. What is the 31 December balance?","choices":["€200,000, with no finance cost","€210,000, with €10,000 finance cost","€190,000, with €10,000 finance income","€205,000, with €5,000 finance cost"],"correct_index":1,"explanation":"One year of unwinding adds €200,000 × 5% = €10,000. The closing provision is €210,000 and the increase is a finance cost, not a new operating estimate."},{"id":"cr-s14-d20261024-l1-q7","session":14,"level":1,"set":2,"supplement":"2026-10-24","topic":"Reimbursement presentation","question":"An existing lawsuit requires a €180,000 provision. The company remains liable for all damages. An insurer will reimburse €120,000, and receipt if the company settles is virtually certain. What balances should be recognised?","choices":["Provision €60,000 and no reimbursement asset","Provision €180,000 and no reimbursement asset","Provision €60,000 and asset €120,000","Provision €180,000 and asset €120,000"],"correct_index":3,"explanation":"Recognise the full obligation because the company remains liable if the insurer fails. Recognise the virtually certain reimbursement separately. A net expense presentation may be allowed, but the statement of financial position does not net these balances."},{"id":"cr-s14-d20261024-l1-q8","session":14,"level":1,"set":2,"supplement":"2026-10-24","topic":"Onerous contract","question":"A non-cancellable service contract has €90,000 remaining benefits and €130,000 directly related fulfilment costs. The company can instead terminate it for €25,000. No dedicated assets require impairment. Discounting is immaterial. What provision is required?","choices":["€25,000","€40,000","€90,000","€130,000"],"correct_index":0,"explanation":"The net cost of fulfilling is €130,000 − €90,000 = €40,000. Exiting costs €25,000. The least net cost of the unavoidable obligation is therefore €25,000."},{"id":"cr-s14-d20261024-l1-q9","session":14,"level":1,"set":2,"supplement":"2026-10-24","topic":"Restructuring trigger","question":"On 20 December, directors approve a detailed restructuring plan but keep it confidential. Implementation has not begun. Employees first learn the main features on 10 January. There is no legal obligation at year-end. What is the year-end IAS 37 treatment?","choices":["Provide when the confidential plan is approved.","Provide when the expected savings are quantified.","Do not provide for the restructuring at year-end.","Provide only for the plan's expected cash payments."],"correct_index":2,"explanation":"Approval alone has not created a valid expectation among those affected. Without implementation or communication of the main features by year-end, there is no constructive restructuring obligation at that date."},{"id":"cr-s14-d20261024-l1-q10","session":14,"level":1,"set":2,"supplement":"2026-10-24","topic":"Use of provisions","question":"A warranty provision is €75,000. The company incurs €10,000 of warranty repairs and €8,000 of unrelated advertising. No estimate change occurs. What closing warranty provision is appropriate?","choices":["€57,000","€65,000","€67,000","€75,000"],"correct_index":1,"explanation":"Only expenditure for the purpose for which the provision was established may be charged against it. Warranty repairs reduce it to €65,000. Advertising is a separate expense and cannot consume a warranty provision."},{"id":"cr-s14-d20261024-l2-q1","session":14,"level":2,"set":3,"supplement":"2026-10-24","topic":"Warranty estimate rollforward","question":"A warranty provision opens at €72,000. Repairs of €28,000 use the provision. At year-end, the remaining obligations require a best estimate of €61,000, including warranties on current-year sales. Discounting is immaterial. What additional warranty expense is needed?","choices":["€11,000","€28,000","€33,000","€17,000"],"correct_index":3,"explanation":"The balance after repairs is €72,000 − €28,000 = €44,000. Reaching the required closing balance of €61,000 needs an additional €17,000 expense. The repairs are not charged to expense a second time."},{"id":"cr-s14-d20261024-l2-q2","session":14,"level":2,"set":3,"supplement":"2026-10-24","topic":"Discount and reassessment","question":"A cleanup provision is €100,000 on 1 January at a 5% discount rate. At 31 December, after unwinding, the revised best estimate is a single €132,300 payment due two years later. The rate remains 5%. What closing balance and remeasurement increase are required?","choices":["€120,000 balance and €15,000 increase","€120,000 balance and €20,000 increase","€126,000 balance and €21,000 increase","€132,300 balance and €27,300 increase"],"correct_index":0,"explanation":"Unwinding first gives €105,000. The revised present value is €132,300 ÷ 1.05² = €120,000. The remeasurement increase is €120,000 − €105,000 = €15,000, separate from the €5,000 finance cost."},{"id":"cr-s14-d20261024-l2-q3","session":14,"level":2,"set":3,"supplement":"2026-10-24","topic":"Costs of fulfilling a contract","question":"A fixed-price supply contract will bring €220,000. Remaining direct materials are €140,000, direct labour €60,000 and allocated depreciation of equipment used to fulfil this contract €35,000. Unrelated head-office costs are €20,000. Exit compensation is €24,000. Dedicated assets are unimpaired. What IAS 37 provision is required?","choices":["€0","€15,000","€24,000","€35,000"],"correct_index":1,"explanation":"Directly related costs include materials, labour and the allocated equipment depreciation: €235,000. Unrelated head-office costs are excluded. The net fulfilment cost is €15,000, lower than the €24,000 exit compensation."},{"id":"cr-s14-d20261024-l2-q4","session":14,"level":2,"set":3,"supplement":"2026-10-24","topic":"Reimbursement cap","question":"A company must recognise a €250,000 provision and remains liable for the whole obligation. Under an indemnity it would receive €280,000 if it settles. Receipt is virtually certain. The indemnity relates only to this obligation. What amounts does IAS 37 permit?","choices":["Provision €250,000 and asset €280,000","Provision nil and asset €30,000","Provision €250,000 and asset €250,000","Provision €30,000 and asset €280,000"],"correct_index":2,"explanation":"A reimbursement asset cannot exceed the provision to which it relates. Recognise the full €250,000 obligation and a separate €250,000 asset. The extra contractual amount does not become an IAS 37 reimbursement asset in this fact pattern."},{"id":"cr-s14-d20261024-l2-q5","session":14,"level":2,"set":3,"supplement":"2026-10-24","topic":"Restructuring eligible costs","question":"An announced restructuring creates a valid obligation by year-end. Direct closure penalties are €85,000. Retraining continuing staff costs €30,000, future marketing €20,000 and new IT systems €45,000. All amounts are reliably estimated and discounting is immaterial. What restructuring provision is required?","choices":["€85,000","€115,000","€135,000","€180,000"],"correct_index":0,"explanation":"Only the direct closure penalties are necessarily entailed by the restructuring and unrelated to continuing activities. Retraining, marketing and new systems support future operations and are excluded."},{"id":"cr-s14-d20261024-l2-q6","session":14,"level":2,"set":3,"supplement":"2026-10-24","topic":"Portfolio recognition","question":"A company has sold 500 identical items with assurance warranties. Each has a 10% chance of a €200 repair and a 90% chance of no repair. Claims across the large population are independent, and an overall outflow is probable. What provision follows IAS 37?","choices":["€0","€20,000","€100,000","€10,000"],"correct_index":3,"explanation":"For the population, expected repairs cost 500 × 10% × €200 = €10,000. The low probability on each individual warranty does not eliminate a provision when settlement of the class as a whole is probable."},{"id":"cr-s14-d20261024-l2-q7","session":14,"level":2,"set":3,"supplement":"2026-10-24","topic":"Changing probability","question":"At the previous year-end, a material lawsuit was disclosed with no provision because an outflow was not probable. This year-end, a present obligation exists and advisers judge an outflow probable. They support €420,000 as the best estimate, payable next year. Discounting is immaterial. What is this year's treatment?","choices":["Retain disclosure alone until the court decides.","Recognise €420,000 expense and provision now.","Recognise the prior-year expected value instead.","Charge €420,000 directly to opening equity."],"correct_index":1,"explanation":"Provisions and contingent liabilities are reassessed at each reporting date. The current facts now satisfy recognition and support €420,000. This is current-period recognition from changed circumstances, not automatically a prior-period error."},{"id":"cr-s14-d20261024-l2-q8","session":14,"level":2,"set":3,"supplement":"2026-10-24","topic":"Reversal and purpose","question":"A company has a €95,000 litigation provision. At year-end, fresh evidence makes any outflow remote. Separately, it forecasts €60,000 operating losses next year, with no present obligation. How should it account for these two matters?","choices":["Retain €60,000 and reverse the other €35,000.","Transfer €60,000 to an operating-loss provision.","Reverse €95,000 and make no loss provision.","Retain €95,000 until the litigation is settled."],"correct_index":2,"explanation":"The litigation provision is reversed because a probable outflow no longer exists. Expected future operating losses do not create a present obligation. A provision cannot be retained or redirected merely to absorb future costs."},{"id":"cr-s14-d20261024-l2-q9","session":14,"level":2,"set":3,"supplement":"2026-10-24","topic":"Single obligation estimate","question":"For one lawsuit, an outflow is probable. Advisers say €400,000 is the most likely payment but identify substantial other outcomes, all above €400,000. Management proposes using €400,000 solely because it is the mode. What does IAS 37 require?","choices":["Assess whether higher outcomes require a higher best estimate.","Use the modal €400,000 without considering other outcomes.","Use the highest possible outcome as the required provision.","Avoid recognition because several payment amounts are possible."],"correct_index":0,"explanation":"The most likely outcome may be the best estimate for one obligation, but other outcomes must still be considered. When they are mostly higher, a higher amount may be appropriate. Neither automatic maximum nor automatic mode is the rule."},{"id":"cr-s14-d20261024-l2-q10","session":14,"level":2,"set":3,"supplement":"2026-10-24","topic":"Reimbursement expense display","question":"A company recognises a €310,000 litigation provision and a separate €190,000 reimbursement asset because recovery is virtually certain. No cash has moved. Which presentation is permitted by IAS 37?","choices":["Liability €120,000 and reimbursement asset nil.","Liability €120,000 and reimbursement asset €190,000.","Liability €310,000 and reimbursement asset nil.","Liability €310,000, asset €190,000, net expense €120,000."],"correct_index":3,"explanation":"Keep the provision and reimbursement asset separate in the statement of financial position. IAS 37 permits the related expense to be presented net of the recognised reimbursement, producing €120,000 net expense here."},{"id":"cr-s14-d20261024-l3-q1","session":14,"level":3,"set":4,"supplement":"2026-10-24","topic":"Integrated cleanup rollforward","question":"A provision for past environmental damage opens at €240,000. The annual discount rate is 5%. No cash is paid. At year-end, after one year of unwinding, the best estimate of the obligation is remeasured to €280,000 present value. An insurer's €90,000 reimbursement is probable, not virtually certain. What closing balances are correct?","choices":["Provision €190,000 and reimbursement asset nil.","Provision €280,000 and reimbursement asset nil.","Provision €280,000 and reimbursement asset €90,000.","Provision €292,000 and reimbursement asset nil."],"correct_index":1,"explanation":"Unwinding adds €12,000, taking the old estimate to €252,000. Remeasurement adds €28,000 to reach €280,000, not €292,000. The probable reimbursement is not recognised because virtual certainty is required."},{"id":"cr-s14-d20261024-l3-q2","session":14,"level":3,"set":4,"supplement":"2026-10-24","topic":"Onerous contract asset sequencing","question":"A contract-specific machine has a €90,000 carrying amount and €65,000 recoverable amount, so a €25,000 impairment is required. After this impairment, the remaining net fulfilment loss is €38,000. The alternative exit penalty is €30,000. No double counting exists in those net costs. What total loss and separate provision are required?","choices":["Total loss €38,000 and provision €13,000.","Total loss €55,000 and provision €55,000.","Total loss €63,000 and provision €38,000.","Total loss €55,000 and provision €30,000."],"correct_index":3,"explanation":"Recognise the €25,000 asset impairment first. Then recognise the lower remaining net contract cost, €30,000 rather than €38,000, as a separate provision. The total loss is €25,000 + €30,000 = €55,000."},{"id":"cr-s14-d20261024-l3-q3","session":14,"level":3,"set":4,"supplement":"2026-10-24","topic":"Two independent legal claims","question":"At year-end, Claim A creates a present obligation with probable outflow and a €360,000 best estimate. Claim B is the company's separate claim against a supplier for €140,000, with probable but not virtually certain inflow. The claims cannot be legally offset and discounting is immaterial. What should be recognised?","choices":["Provision €360,000 and no asset for Claim B.","Provision €220,000 and no asset for Claim B.","Provision €360,000 and asset €140,000 for Claim B.","No provision or asset until both claims are resolved."],"correct_index":0,"explanation":"Claim A meets the liability recognition criteria, requiring €360,000. Claim B remains a contingent asset and is disclosed if material, without recognition. Independent uncertain gains cannot reduce a recognised obligation."},{"id":"cr-s14-d20261024-l3-q4","session":14,"level":3,"set":4,"supplement":"2026-10-24","topic":"Uniform range measurement","question":"A large population of similar warranty obligations has a continuous range of equally likely total settlement outcomes from €180,000 to €300,000. A present obligation and probable outflow exist. Payment is due in one year, and the appropriate discount rate is 4%. What provision is closest?","choices":["€173,077","€240,000","€230,769","€288,462"],"correct_index":2,"explanation":"For an equally likely continuous range, use the midpoint: (€180,000 + €300,000) ÷ 2 = €240,000. Discount it for one year: €240,000 ÷ 1.04 = €230,769. Do not use either endpoint or leave the material discount unrecognised."},{"id":"cr-s14-d20261024-l3-q5","session":14,"level":3,"set":4,"supplement":"2026-10-24","topic":"Closure and continuing operations","question":"A company has created a valid restructuring obligation before year-end. Closing a site requires €150,000 unavoidable contract cancellation payments. It also expects €45,000 retraining of retained workers, €70,000 future trading losses and €35,000 advertising at its surviving sites. Which amount belongs in the restructuring provision?","choices":["€195,000","€150,000","€265,000","€300,000"],"correct_index":1,"explanation":"Only the €150,000 direct closure payments arise necessarily from the restructuring and are unrelated to continuing operations. Retraining and advertising support future operations. Future trading losses are not present obligations."},{"id":"cr-s14-d20261024-l3-q6","session":14,"level":3,"set":4,"supplement":"2026-10-24","topic":"Present value and reimbursement timing","question":"A company must pay €220,500 to settle an existing legal obligation in two years. The appropriate annual discount rate is 5%. A third party will reimburse 60% at the same settlement date, receipt is virtually certain, and the same rate is appropriate. The company remains fully liable. What year-end balances are required?","choices":["Provision €80,000 and asset nil.","Provision €220,500 and asset €132,300.","Provision €200,000 and asset €132,300.","Provision €200,000 and asset €120,000."],"correct_index":3,"explanation":"The obligation is €220,500 ÷ 1.05² = €200,000. The reimbursement has the same timing and discount rate, so its present value is 60% × €200,000 = €120,000. Recognise these separately rather than netting the liability."},{"id":"cr-s14-d20261024-l3-q7","session":14,"level":3,"set":4,"supplement":"2026-10-24","topic":"Settlement versus new estimate","question":"A provision opens at €150,000. During the year, €40,000 is paid for the original obligation. At year-end, management's current best estimate of all remaining settlement expenditure is €125,000. Discounting is immaterial. Which pair correctly states the closing provision and current-year additional expense?","choices":["Provision €125,000 and expense €15,000.","Provision €125,000 and expense €55,000.","Provision €110,000 and expense nil.","Provision €165,000 and expense €15,000."],"correct_index":0,"explanation":"The payment uses the old provision, leaving €110,000. A €15,000 expense raises the balance to the revised remaining obligation of €125,000. The €40,000 settlement is not added again to the revised remaining estimate."},{"id":"cr-s14-d20261024-l3-q8","session":14,"level":3,"set":4,"supplement":"2026-10-24","topic":"Technological change evidence","question":"An existing cleanup obligation would cost €600,000 using current methods. A new method would reduce it to €450,000. Independent engineering evidence supports that method's availability when settlement occurs. No other risk or timing adjustment is needed. How should IAS 37 treat the supported future technology?","choices":["Ignore it until the method is already used commercially.","Use €600,000 because future changes are always excluded.","Include the supported change in the €450,000 estimate.","Recognise a €150,000 asset against a €600,000 provision."],"correct_index":2,"explanation":"Future events affecting settlement cost are reflected when sufficient objective evidence supports them. The facts supply that evidence, so use €450,000. Unsupported optimism would not qualify, and a cost reduction is not a reimbursement asset."},{"id":"cr-s14-d20261024-l3-q9","session":14,"level":3,"set":4,"supplement":"2026-10-24","topic":"Potential new law","question":"A company has already contaminated land. No existing law, published policy or past practice creates a cleanup obligation. A proposed law would require cleanup, but its enactment as drafted is not virtually certain. Management estimates cleanup at €500,000. Which conclusion follows IAS 37 on these facts?","choices":["Recognise the full €500,000 provision now.","Do not recognise a provision yet.","Recognise €500,000 weighted by enactment probability.","Recognise the discounted €500,000 provision now."],"correct_index":1,"explanation":"Pollution alone is insufficient here because no legal or constructive obligation currently exists. An obligation from proposed legislation is recognised only when enactment as drafted is virtually certain. A possible obligation may require disclosure, assessed separately."},{"id":"cr-s14-d20261024-l3-q10","session":14,"level":3,"set":4,"supplement":"2026-10-24","topic":"Finance cost versus reassessment","question":"A discounted provision opens at €320,000 with a 5% annual rate. One year passes with no payment. A reassessment then reduces the required closing present value to €300,000. What finance cost and remeasurement credit arise?","choices":["Finance cost nil and credit €20,000.","Finance cost €15,000 and credit €35,000.","Finance cost €16,000 and credit €20,000.","Finance cost €16,000 and credit €36,000."],"correct_index":3,"explanation":"Unwinding gives €320,000 × 5% = €16,000 finance cost and an intermediate balance of €336,000. Reducing that balance to €300,000 creates a €36,000 remeasurement credit. Net movement is a €20,000 reduction, but that is not the remeasurement alone."},{"id":"cr-s12-d20261025-l1-q1","session":12,"level":1,"set":2,"supplement":"2026-10-25","topic":"Scope of IAS 36","question":"Which asset falls within the scope of IAS 36 impairment testing?","choices":["Inventories held for sale in the ordinary course of business","Financial assets accounted for under IFRS 9","A production machine measured under the IAS 16 cost model","Investment property measured at fair value"],"correct_index":2,"explanation":"IAS 36 applies to tangible and intangible fixed assets whatever the chosen accounting treatment, and to investments in subsidiaries, associates and joint ventures. It does not apply to assets covered by a separate standard, such as inventories, financial assets or investment property at fair value."},{"id":"cr-s12-d20261025-l1-q2","session":12,"level":1,"set":2,"supplement":"2026-10-25","topic":"Definition of impairment loss","question":"Under IAS 36, when does an entity recognise an impairment loss on an asset or cash-generating unit?","choices":["Whenever the fair value of the asset falls below its original cost","Only when the asset is physically damaged or obsolete","When the asset's remaining useful life is revised downward","When the carrying amount exceeds the recoverable amount"],"correct_index":3,"explanation":"IAS 36 defines an impairment loss as the amount by which the carrying amount of an asset or cash-generating unit exceeds its recoverable amount. If the carrying amount is below the recoverable amount, no impairment is recorded."},{"id":"cr-s12-d20261025-l1-q3","session":12,"level":1,"set":2,"supplement":"2026-10-25","topic":"Recoverable amount logic","question":"A machine's carrying amount is €500,000. Its fair value less costs of disposal is reliably measured at €520,000. The entity has not yet calculated value in use, and no goodwill or indefinite-life intangible is involved. What must the entity do for impairment purposes?","choices":["Calculate value in use, because every asset requires both measures before any impairment conclusion","Recognise a loss for any shortfall of value in use below the carrying amount","No impairment work: the higher-of rule means the recoverable amount is at least €520,000, already above the carrying amount","No impairment work, because fair value less costs of disposal is always the recoverable amount"],"correct_index":2,"explanation":"Recoverable amount is the higher of fair value less costs of disposal and value in use. Once one measure exceeds the carrying amount, no impairment exists and computing the other measure is unnecessary for an ordinary asset. Choice D reaches the right conclusion for the wrong reason: value in use can exceed fair value less costs of disposal and then becomes the recoverable amount. Choices A and B wrongly impose a mandatory two-measure computation or a loss on an asset that cannot be impaired on these facts."},{"id":"cr-s12-d20261025-l1-q4","session":12,"level":1,"set":2,"supplement":"2026-10-25","topic":"Fair value less costs of disposal","question":"A dealer offers €95,000 cash for a machine. To complete the sale the entity would pay €2,000 of legal fees and €3,000 to dismantle and ship the machine to the buyer. Closing the production line would also trigger €10,000 of redundancy costs for its operators. What is the machine's fair value less costs of disposal?","choices":["€95,000","€80,000","€93,000","€90,000"],"correct_index":3,"explanation":"Fair value less costs of disposal is the €95,000 price minus the incremental costs directly attributable to the disposal: €2,000 legal fees and €3,000 shipping give €90,000. The redundancy costs are excluded because they follow from ceasing to use the asset, not from selling it. Choice A forgets disposal costs entirely, choice B wrongly deducts the redundancies, and choice C deducts only the legal fees."},{"id":"cr-s12-d20261025-l1-q5","session":12,"level":1,"set":2,"supplement":"2026-10-25","topic":"Internal and external indicators","question":"At the reporting date an entity reviews its plant for impairment indicators. Which finding is an internal source of impairment indications under IAS 36?","choices":["A fall in the machine's market value greater than expected from the passage of time or normal use","Evidence from the maintenance department that a machine is physically damaged","An increase in market interest rates that raises the discount rate applied to the machine","New environmental legislation that restricts how the machine may operate"],"correct_index":1,"explanation":"Physical damage observed inside the entity is an internal source, together with obsolescence evidence and worse budgeted performance. Market value declines, interest rate movements and legal or environmental changes are external sources. The review must scan both lists at each reporting date before deciding whether to estimate a recoverable amount."},{"id":"cr-s12-d20261025-l1-q6","session":12,"level":1,"set":2,"supplement":"2026-10-25","topic":"Indicators trigger an immediate estimate","question":"Halfway through the year, a company's market capitalisation falls below the carrying amount of its net assets, and internal budgets start showing declining margins on a pool of cost-model machines. No annual impairment test is scheduled until year end. What does IAS 36 require now?","choices":["Wait for the scheduled annual test, because indicators matter only at year end","Estimate the recoverable amount of the affected assets without waiting, because both external and internal indicators exist","Recognise an immediate loss equal to the market-capitalisation shortfall","Only disclose the indicators in the interim notes, with no estimate required"],"correct_index":1,"explanation":"Indicators of impairment, whether external (market capitalisation below net asset carrying amount) or internal (worse budgeted performance), require the entity to estimate the recoverable amount when they arise, not at the next scheduled test. The market-capitalisation gap is evidence, not a measurement, so choice C converts an indicator directly into a loss, and choice D reduces the requirement to disclosure."},{"id":"cr-s12-d20261025-l1-q7","session":12,"level":1,"set":2,"supplement":"2026-10-25","topic":"Active market and CGU identification","question":"A division produces a component entirely consumed by another division of the same group, but an active market exists for that component. For IAS 36 purposes, the producing division:","choices":["Is identified as a cash-generating unit, even though its output is used internally","Cannot be a cash-generating unit because it has no external sales","Is always merged with the consuming division into one cash-generating unit","Is tested for impairment only every three years"],"correct_index":0,"explanation":"If there is an active market for the product of a business or group of businesses, that business or group must be identified as a CGU, even if some or all of the products are used internally."},{"id":"cr-s12-d20261025-l1-q8","session":12,"level":1,"set":2,"supplement":"2026-10-25","topic":"CGU consistency","question":"How must an entity identify the cash-generating units of the same activity from one year to the next?","choices":["It may freely redefine its cash-generating units every year to reflect optimism","It must use consistent criteria year after year, unless a change can be justified","It must rotate the identification criteria set by its statutory auditor","It must always identify one single cash-generating unit for the whole group"],"correct_index":1,"explanation":"The CGUs of the same activity or of the same types of activities must be identified with criteria consistent from year to year, unless the change can be justified."},{"id":"cr-s12-d20261025-l1-q9","session":12,"level":1,"set":2,"supplement":"2026-10-25","topic":"CGU carrying amount","question":"When determining the carrying amount of a cash-generating unit for the impairment test, a recognised liability is:","choices":["Always included, because liabilities reduce the unit's value","Always excluded, even if the recoverable amount cannot be determined without it","Converted into an asset before the test","Excluded, unless the recoverable amount of the unit cannot be determined without taking the liability into account"],"correct_index":3,"explanation":"The net book value of a CGU includes only assets that can be attributed directly or allocated on a reasonable and consistent basis, and excludes any recognised liability unless the recoverable amount of the unit cannot be determined without taking that liability into account."},{"id":"cr-s12-d20261025-l1-q10","session":12,"level":1,"set":2,"supplement":"2026-10-25","topic":"Reversal recognition","question":"A cost-model asset was impaired two years ago. Changed estimates now justify a reversal within the IAS 36 ceiling. Where is the reversal recognised?","choices":["Immediately in profit or loss, unless the asset is carried at a revalued amount","Directly in retained earnings, because it corrects a past estimate","In other comprehensive income as a separate reversal reserve","It is never recognised, because impairment losses are permanent"],"correct_index":0,"explanation":"A reversal of an impairment loss is recognised immediately in profit or loss, unless the asset is carried at a revalued amount, in which case the reversal is treated as a revaluation increase under the relevant standard. Only goodwill impairment can never be reversed."},{"id":"cr-s12-d20261025-l2-q1","session":12,"level":2,"set":3,"supplement":"2026-10-25","topic":"Value in use calculation","question":"A machine generates net cash inflows of €15,000 at the end of each of the next three years and will then be sold for €8,000 at the end of year 3. The appropriate discount factors are 0.893 for year 1, 0.797 for year 2 and 0.712 for year 3. What is the machine's value in use?","choices":["€37,454","€41,726","€53,000","€45,090"],"correct_index":1,"explanation":"Value in use is 15,000 × 0.893 + 15,000 × 0.797 + (15,000 + 8,000) × 0.712 = 13,395 + 11,955 + 16,376 = €41,726. The sale proceeds are part of the year 3 cash flow and are discounted at the year 3 factor."},{"id":"cr-s12-d20261025-l2-q2","session":12,"level":2,"set":3,"supplement":"2026-10-25","topic":"Recoverable amount selection","question":"A cost-model asset has a carrying amount of €130,000. It could be sold for €120,000 with disposal costs of €5,000, and its value in use is €118,000. What impairment loss, if any, is recognised?","choices":["€10,000","€15,000","No impairment loss","€12,000"],"correct_index":3,"explanation":"Fair value less costs of disposal is 120,000 − 5,000 = €115,000. The recoverable amount is the higher of €115,000 and value in use of €118,000, so €118,000. The impairment loss is 130,000 − 118,000 = €12,000."},{"id":"cr-s12-d20261025-l2-q3","session":12,"level":2,"set":3,"supplement":"2026-10-25","topic":"Pro rata allocation without goodwill","question":"A cash-generating unit with no goodwill contains buildings of €600,000, equipment of €300,000 and machinery of €100,000. The unit's recoverable amount is €940,000 and no individual asset floor applies. What impairment loss is allocated to the equipment?","choices":["€18,000","€36,000","€60,000","€6,000"],"correct_index":0,"explanation":"The unit carries at €1,000,000 against a recoverable amount of €940,000, so the loss is €60,000. With no goodwill, the loss is allocated pro rata to carrying amounts. The equipment bears 300,000 / 1,000,000 = 30%, that is €18,000."},{"id":"cr-s12-d20261025-l2-q4","session":12,"level":2,"set":3,"supplement":"2026-10-25","topic":"Depreciation after impairment","question":"An asset is impaired from €100,000 to a recoverable amount of €80,000. Its residual value is €8,000 and its remaining useful life is four years, straight-line. What annual depreciation is charged after the impairment?","choices":["€25,000","€20,000","€18,000","€23,000"],"correct_index":2,"explanation":"The new carrying amount becomes the depreciable base. The depreciable amount is 80,000 − 8,000 = €72,000, spread over four years, so €18,000 per year."},{"id":"cr-s12-d20261025-l2-q5","session":12,"level":2,"set":3,"supplement":"2026-10-25","topic":"Reversal ceiling","question":"A cost-model asset was impaired in the past and now carries at €42,000. Had no impairment been recognised, its depreciated carrying amount today would be €50,000. Its recoverable amount is now €55,000. What reversal is recognised?","choices":["€13,000, restoring the asset to its recoverable amount","€5,000, limited to the excess of the ceiling over the recoverable amount","No reversal, because the asset was previously impaired","€8,000, because the reversal cannot exceed the depreciated no-impairment ceiling"],"correct_index":3,"explanation":"The increased carrying amount after a reversal must not exceed the carrying amount that would have existed, net of depreciation, had no impairment been recognised, here €50,000. The asset is increased from €42,000 to €50,000, a reversal of €8,000, even though the recoverable amount is €55,000."},{"id":"cr-s12-d20261025-l2-q6","session":12,"level":2,"set":3,"supplement":"2026-10-25","topic":"Goodwill absorbs the loss first","question":"A cash-generating unit carries goodwill of €15 million and other assets of €85 million. Its recoverable amount is €70 million. How much of the impairment loss is allocated to the other assets?","choices":["€30 million","€15 million","€70 million","€45 million"],"correct_index":1,"explanation":"The unit carries at €100 million against a recoverable amount of €70 million, a loss of €30 million. The loss first reduces goodwill from €15 million to zero, and the remaining €15 million is allocated pro rata to the other assets."},{"id":"cr-s12-d20261025-l2-q7","session":12,"level":2,"set":3,"supplement":"2026-10-25","topic":"Allocation floor binding","question":"A cash-generating unit with no goodwill contains asset A at €50 million, asset B at €25 million and asset C at €25 million. The unit's recoverable amount is €70 million. Asset A has a measurable fair value less costs of disposal of €44 million, while no floor is determinable for B or C. What is asset B's carrying amount after the allocation?","choices":["€17.5 million","€20.5 million","€13 million","€25 million"],"correct_index":2,"explanation":"The loss is €30 million. A first pro rata allocation gives A €15 million, B €7.5 million and C €7.5 million, but A cannot fall below €44 million, so A absorbs only €6 million. The unallocated €9 million is redistributed equally to B and C, €4.5 million each. B ends at 25 − 7.5 − 4.5 = €13 million."},{"id":"cr-s12-d20261025-l2-q8","session":12,"level":2,"set":3,"supplement":"2026-10-25","topic":"Corporate asset two-step test","question":"CGU1 carries at €100 million with a recoverable amount of €95 million, and CGU2 carries at €60 million with a recoverable amount of €65 million. A headquarters asset of €40 million cannot be allocated to either CGU individually but can be allocated to the two CGUs together, whose combined recoverable amount is €190 million. What impairment is recognised at the second step, after the individual tests?","choices":["€10 million","€5 million","€0, because both CGUs were already tested","€45 million"],"correct_index":1,"explanation":"Step one: CGU1 is impaired by €5 million and CGU2 is not impaired. Step two: the smallest group to which the corporate asset can be allocated carries at 95 + 60 + 40 = €195 million against a recoverable amount of €190 million, so a further €5 million impairment is recognised."},{"id":"cr-s12-d20261025-l2-q9","session":12,"level":2,"set":3,"supplement":"2026-10-25","topic":"Discounting in value in use","question":"An asset is expected to produce net cash inflows of €100,000 at the end of each of the next two years and nothing thereafter. At a 10% discount rate the factors are 0.909 for year 1 and 0.826 for year 2. The asset carries at €180,000 and no fair value is available. What impairment loss is recognised?","choices":["€20,000, the excess of undiscounted inflows over carrying amount","No impairment, because the undiscounted inflows exceed the carrying amount","€6,500, the excess of carrying amount over discounted value in use","€26,500, using only the year 2 discount factor"],"correct_index":2,"explanation":"Value in use is 100,000 × 0.909 + 100,000 × 0.826 = €173,500. The recoverable amount is €173,500, so the impairment loss is 180,000 − 173,500 = €6,500. Undiscounted inflows are irrelevant to value in use."},{"id":"cr-s12-d20261025-l2-q10","session":12,"level":2,"set":3,"supplement":"2026-10-25","topic":"Impairment of a revalued asset","question":"A revalued asset carries at €60 million and its recoverable amount is €45 million. A revaluation surplus of €8 million exists for this same asset. How is the €15 million impairment loss recognised?","choices":["€8 million against the revaluation surplus in other comprehensive income and €7 million as an expense in profit or loss","The full €15 million as an expense in profit or loss","The full €15 million against the revaluation surplus in other comprehensive income","€7 million against the revaluation surplus and €8 million in profit or loss"],"correct_index":0,"explanation":"For a revalued asset, the impairment loss is first debited to the revaluation reserve to the extent of any credit balance existing for that same asset, shown as a negative figure in other comprehensive income, here €8 million. Any excess, here €7 million, is recognised as an expense."},{"id":"cr-s12-d20261025-l3-q1","session":12,"level":3,"set":4,"supplement":"2026-10-25","topic":"CGU with goodwill and binding floor","question":"A cash-generating unit carries goodwill of €30 million, patents of €40 million and plant of €160 million. Its recoverable amount is €150 million. No value in use is determinable for the individual assets, the patents have no measurable fair value, and the plant's fair value less costs of disposal is €130 million. After allocating the impairment loss, at what amount are the patents carried?","choices":["€30 million","€26 million","€20 million","€10 million"],"correct_index":2,"explanation":"The loss is 230 − 150 = €80 million. Goodwill absorbs €30 million first. The remaining €50 million is allocated 20% to patents (€10 million) and 80% to plant (€40 million), but the plant cannot fall below its €130 million floor, so it absorbs only €30 million. The excess €10 million is reallocated to the patents, which end at 40 − 10 − 10 = €20 million."},{"id":"cr-s12-d20261025-l3-q2","session":12,"level":3,"set":4,"supplement":"2026-10-25","topic":"Goodwill in a disposal gain or loss","question":"A cash-generating unit carries €320,000 of assets including €80,000 of allocated goodwill. The entity sells one operation of the unit for €150,000. That operation's carrying amount excluding goodwill is €120,000, and its recoverable amount is 30% of the recoverable amount of the whole unit; no other method better reflects the goodwill attached to it. What gain or loss on disposal is recognised?","choices":["Gain of €30,000","Loss of €50,000","Gain of €6,000","Gain of €24,000"],"correct_index":2,"explanation":"The disposed operation takes its share of goodwill on relative values: 30% of €80,000 = €24,000. The disposal carrying amount is €120,000 + €24,000 = €144,000 against proceeds of €150,000, a gain of €6,000. Choice A ignores goodwill in the disposal, choice B derecognises the entire €80,000 of goodwill, and choice D mistakes the goodwill share itself for the gain."},{"id":"cr-s12-d20261025-l3-q3","session":12,"level":3,"set":4,"supplement":"2026-10-25","topic":"Timing of the annual goodwill test","question":"An entity carries goodwill allocated to a cash-generating unit. Management proposes two policies: skip the unit's impairment test in any year with no indicators of impairment, and perform each year's test at whatever date suits the budget calendar, varying from year to year. Which proposal complies with IAS 36?","choices":["Both: indicators drive all impairment tests, and any date within the period is acceptable","Skipping is acceptable because goodwill follows the general indicator rule, but the test date must stay constant","Skipping is unacceptable, but the test date may move freely from one year to the next","Neither: goodwill is tested every year regardless of indicators, at the same time each year"],"correct_index":3,"explanation":"Goodwill is tested annually irrespective of indicators; the indicator-only regime governs ordinary assets. The annual test may be performed at any time during the annual period, but at the same time every year. Choices A and B wrongly extend the indicator rule to goodwill, and choice C keeps the annual duty but misses the consistency requirement."},{"id":"cr-s12-d20261025-l3-q4","session":12,"level":3,"set":4,"supplement":"2026-10-25","topic":"Order of testing","question":"A cash-generating unit contains goodwill and several individual assets that show their own impairment indicators. In what order are the impairment tests performed?","choices":["Test the goodwill-bearing unit first, then the individual assets if a loss remains","Test only the unit, because testing the assets separately is prohibited","Test the individual assets first, then the cash-generating unit to which goodwill is allocated","Test goodwill and the individual assets simultaneously and allocate the larger loss"],"correct_index":2,"explanation":"The various assets assigned to a CGU must be subjected to an impairment test before the test for impairment of the goodwill-bearing unit. Individual losses are recognised first, then the unit's carrying amount, net of those losses, is compared with its recoverable amount."},{"id":"cr-s12-d20261025-l3-q5","session":12,"level":3,"set":4,"supplement":"2026-10-25","topic":"Reversal with goodwill in the unit","question":"Two years ago a cash-generating unit recognised an impairment loss of €15 million, of which €10 million reduced goodwill to zero and €5 million reduced a machine. Changed estimates now justify a reversal, and the machine's reversal ceiling is not binding. What may be reversed?","choices":["The full €15 million, because the unit has recovered","€10 million, the portion that reduced goodwill","€5 million, because a goodwill impairment loss can never be reversed","€0, because impairment losses in a CGU are permanent"],"correct_index":2,"explanation":"An impairment loss recognised for goodwill cannot be reversed in future periods. Only the €5 million allocated to the machine may be reversed, subject to the ceiling of the depreciated carrying amount that would have existed without the impairment."},{"id":"cr-s12-d20261025-l3-q6","session":12,"level":3,"set":4,"supplement":"2026-10-25","topic":"Reversal ceiling with depreciation","question":"At the start of year 1 a cost-model machine carried at €100,000 and was impaired to €60,000, with five years of remaining life and zero residual value. At the end of year 2 its recoverable amount is estimated at €70,000. Without the past impairment, annual depreciation would have been €20,000. What reversal, if any, is recognised at the end of year 2?","choices":["€24,000, limited by the depreciated no-impairment ceiling","€34,000, restoring the asset to its recoverable amount","€14,000, the difference between recoverable amount and original cost","No reversal, because the recoverable amount exceeds the ceiling"],"correct_index":0,"explanation":"After impairment the machine depreciates by 60,000 / 5 = €12,000 per year, so it carries at €36,000 at the end of year 2. The ceiling is the depreciated no-impairment amount, 100,000 − 2 × 20,000 = €60,000. The asset is increased from €36,000 to €60,000, a reversal of €24,000, below the recoverable amount of €70,000."},{"id":"cr-s12-d20261025-l3-q7","session":12,"level":3,"set":4,"supplement":"2026-10-25","topic":"Assets always tested annually","question":"Which pair must be tested for impairment every year, even when no impairment indicator exists?","choices":["A building used as the head office and a five-year-old delivery fleet","Goodwill allocated to a cash-generating unit and an intangible asset not yet available for use","A fully depreciated machine and a financial asset under IFRS 9","A patent with a ten-year legal life and an equity-accounted associate"],"correct_index":1,"explanation":"Regardless of the existence of indicators, an annual impairment test is required for intangible assets with an indefinite useful life, for intangible assets not yet ready for use, and for goodwill."},{"id":"cr-s12-d20261025-l3-q8","session":12,"level":3,"set":4,"supplement":"2026-10-25","topic":"CGU identification with internal use","question":"A steel plant sells 20% of its output externally and transfers 80% to the group's construction division at cost. An active market exists for the plant's steel, and management monitors the plant's margin as a separate product line. For IAS 36, the plant is:","choices":["A cash-generating unit, because an active market exists for its output even though most of it is used internally","Never a cash-generating unit, because most of its output is transferred internally","Tested jointly with the construction division, because internal transfers make its inflows dependent on that division","Measured at transfer cost for the impairment test, because that is the price the division actually records"],"correct_index":0,"explanation":"If there is an active market for the product of a business or group of businesses, that business must be identified as a cash-generating unit, even if some or all of the products are used internally; management monitoring by product line supports the identification. Choice B treats internal use as disqualifying, which the active-market rule overrides. Choice C merges units whose inflows are measurable separately through the market, and choice D confuses internal transfer pricing with the cash inflows the market would pay."},{"id":"cr-s12-d20261025-l3-q9","session":12,"level":3,"set":4,"supplement":"2026-10-25","topic":"External indicator mechanics","question":"Market interest rates have risen significantly, and this increases the discount rate an entity must apply in its value in use calculations. For IAS 36 this fact is:","choices":["An external impairment indicator, because the higher discount rate reduces value in use","An internal impairment indicator, because discounting is an internal estimate","Not an indicator while the change is market-wide, because IAS 36 tracks only entity-specific events","An indicator that requires recognising the full value-in-use decline as an immediate loss"],"correct_index":0,"explanation":"An increase in market interest rates that affects the discount rate used in calculating value in use is listed by IAS 36 as an external source of impairment evidence. It triggers an estimate of the recoverable amount, not an automatic loss. Choice B misclassifies the source because the rate comes from the market rather than from the entity, choice C wrongly limits indicators to entity-specific events, and choice D skips the required measurement step by treating the indicator itself as the loss."},{"id":"cr-s12-d20261025-l3-q10","session":12,"level":3,"set":4,"supplement":"2026-10-25","topic":"Full impairment and depreciation chain","question":"A cost-model asset carries at €200,000. It would sell for €90,000 with €4,000 of disposal costs. It will generate €40,000 of net cash inflows at the end of each of the next four years and then be sold for €12,000. Discount factors are 0.909, 0.826, 0.751 and 0.683 for years 1 to 4. After recognising any impairment, what annual straight-line depreciation is charged over the four remaining years, keeping the €12,000 residual value?","choices":["€30,739","€28,250","€32,000","€47,000"],"correct_index":0,"explanation":"Value in use is 40,000 × (0.909 + 0.826 + 0.751) + 52,000 × 0.683 = 99,440 + 35,516 = €134,956, which exceeds fair value less costs of disposal of €86,000. The impairment loss is 200,000 − 134,956 = €65,044. The new base is €134,956, so annual depreciation is (134,956 − 12,000) / 4 = €30,739."},{"id":"cr-s13-d20261026-l1-q1","session":13,"level":1,"set":2,"supplement":"2026-10-26","topic":"Composition of the consideration","question":"A buyer pays for an acquisition with US$122.331 million in cash, 260 million of its own ordinary shares valued at US$229.581 million, and convertible notes valued at US$126.549 million. What total consideration transferred enters the goodwill computation?","choices":["US$478.461 million","US$356.130 million","US$351.912 million","US$248.880 million"],"correct_index":0,"explanation":"Consideration transferred includes cash paid and the acquisition-date fair value of equity instruments issued: US$122.331 million plus US$229.581 million plus US$126.549 million equals US$478.461 million. The distractors each drop one component."},{"id":"cr-s13-d20261026-l1-q2","session":13,"level":1,"set":2,"supplement":"2026-10-26","topic":"Remeasurement gain presentation","question":"A group that already held 50% of a joint venture buys the other 50% and obtains control. On that date it remeasures its previously held stake to fair value and recognises a gain of US$273.245 million. Where does IFRS 3 require this gain to be reported?","choices":["As a reduction of acquisition goodwill","In other comprehensive income without recycling","In profit or loss, within other income","As a direct credit to retained earnings"],"correct_index":2,"explanation":"In a step acquisition, obtaining control triggers remeasurement of the previously held interest to fair value through profit or loss. The gain is neither netted against goodwill nor parked in equity."},{"id":"cr-s13-d20261026-l1-q3","session":13,"level":1,"set":2,"supplement":"2026-10-26","topic":"Transaction costs","question":"A buyer completes an acquisition and pays US$262,000 of advisory and legal fees directly related to the deal. How are these transaction costs accounted for under IFRS 3?","choices":["Added to the consideration transferred","Expensed as incurred in profit or loss","Capitalised as a separate intangible asset","Deducted from the fair value of shares issued"],"correct_index":1,"explanation":"Acquisition-related costs are expensed as incurred. They never enter the consideration transferred, so they cannot inflate goodwill, and they are not an asset."},{"id":"cr-s13-d20261026-l1-q4","session":13,"level":1,"set":2,"supplement":"2026-10-26","topic":"Allocating goodwill to the units that benefit","question":"A medical device group acquires a stent manufacturer. The acquired production will merge into the group's existing cardiac cash-generating unit, and the group's cardiology research cash-generating unit will exploit the acquired patents. Group headquarters will coordinate the integration but generates no independent cash inflows. To which units is the acquired goodwill allocated for impairment testing?","choices":["To the whole group as a single unit, because goodwill never attaches below group level","To headquarters, because it will coordinate the units receiving the benefits","To the cardiac unit and the research unit, the units expected to benefit from the combination's synergies","To the acquired legal entity as its own unit, whatever the operational integration"],"correct_index":2,"explanation":"IAS 36 allocates goodwill from the acquisition date to each cash-generating unit expected to benefit from the synergies, here the cardiac unit and the research unit. Headquarters is not a beneficiary unit merely by coordinating, the legal structure does not define cash-generating units, and testing goodwill only at whole-group level skips the required allocation."},{"id":"cr-s13-d20261026-l1-q5","session":13,"level":1,"set":2,"supplement":"2026-10-26","topic":"Change in useful life","question":"A group amortises acquired patents straight-line over ten years. Partway through a patent's life, management revises its expected useful life because of technological developments. How is that revision accounted for?","choices":["As an error correction: prior-year financial statements are restated retrospectively","As a change in accounting estimate, applied prospectively from the revision date","As a reclassification: the remaining carrying amount of the patent moves into goodwill","As an impairment indicator that always triggers an immediate write-down of the asset"],"correct_index":1,"explanation":"Amortisation periods and methods are reviewed at least at each balance sheet date. A revision of expected useful life is a change in accounting estimate, applied prospectively by changing the amortisation period or method."},{"id":"cr-s13-d20261026-l1-q6","session":13,"level":1,"set":2,"supplement":"2026-10-26","topic":"Impairment loss mechanics","question":"A group recognises goodwill impairment losses of US$12.232 million on some of its older cash-generating units, following IAS 36. How are these losses presented, and what happens if the affected units recover later?","choices":["They are recognised in other comprehensive income, and reversed when conditions improve","They are deducted from the goodwill line only on the balance sheet, with reversal allowed","They are recognised in profit or loss, and impairment of goodwill is never reversed","They are deferred and spread over the remaining useful life of the related patents"],"correct_index":2,"explanation":"Impairment losses on goodwill go to profit or loss. IAS 36 prohibits reversing goodwill impairment in subsequent periods, whatever the later recovery."},{"id":"cr-s13-d20261026-l1-q7","session":13,"level":1,"set":2,"supplement":"2026-10-26","topic":"Net cash outflow on acquisition","question":"In a business acquisition, the buyer pays US$122.331 million in cash and obtains US$105.086 million of cash balances with the acquired business. What net cash outflow from the acquisition appears in the investing section of the cash flow statement?","choices":["US$17.245 million","US$227.417 million","US$105.086 million","US$122.331 million"],"correct_index":0,"explanation":"The net outflow nets the cash paid against the cash acquired: US$122.331 million minus US$105.086 million equals US$17.245 million."},{"id":"cr-s13-d20261026-l1-q8","session":13,"level":1,"set":2,"supplement":"2026-10-26","topic":"Purpose of pro-forma disclosure","question":"IFRS 3 requires disclosing the revenue and profit contributed by an acquiree since the acquisition date, plus pro-forma figures as if the combination had occurred at the start of the reporting period. A group reports that its newly acquired subsidiary contributed about 17% of group revenue but only about 2% of group profit since acquisition. What is the purpose of the pro-forma part of this disclosure?","choices":["It restates the prior-year comparative financial statements as if the acquiree had always been owned","It replaces the annual impairment test for the goodwill recognised on the acquisition","It measures the gain or loss the group would record if it sold the acquiree at year end","It shows what the period's revenue and profit would have been with the business owned all year"],"correct_index":3,"explanation":"The pro-forma disclosure answers a simple question: what would the period have looked like with the business owned from day one. It aids comparability. It changes neither the reported figures nor the impairment requirements."},{"id":"cr-s13-d20261026-l1-q9","session":13,"level":1,"set":2,"supplement":"2026-10-26","topic":"Goodwill as the residual","question":"An acquisition attributes US$876.461 million in total, being the consideration transferred plus the fair value of a previously held interest, against US$268.791 million of identifiable net assets measured at fair value. What does the difference of US$607.670 million represent?","choices":["A bargain purchase gain in profit or loss","Goodwill arising from the acquisition","A deferred tax liability on the uplift","A non-controlling interest retained"],"correct_index":1,"explanation":"Goodwill is the excess of the consideration transferred plus the previously held interest over the identifiable net assets at fair value: US$876.461 million minus US$268.791 million equals US$607.670 million."},{"id":"cr-s13-d20261026-l1-q10","session":13,"level":1,"set":2,"supplement":"2026-10-26","topic":"Non-deductible goodwill","question":"The goodwill recognised on an acquisition is not expected to be deductible for income tax purposes. What does this mean for the acquiring group?","choices":["The goodwill must be amortised over ten years so that the accounts match the tax treatment","The acquisition price must be restated net of tax in the following year's financial statements","Later write-downs of this goodwill bring no tax deduction and create no deferred tax","A deferred tax asset is recognised immediately for the full amount of the goodwill"],"correct_index":2,"explanation":"If goodwill is not tax-deductible, later write-downs bring no tax relief and no deferred tax attaches to it. Under IFRS goodwill is not amortised. Instead it is tested annually for impairment."},{"id":"cr-s13-d20261026-l2-q1","session":13,"level":2,"set":3,"supplement":"2026-10-26","topic":"Goodwill computation","question":"A buyer acquires the remaining 50% of a joint venture and obtains control. Consideration transferred is US$478.461 million, and the previously held 50% interest has a fair value of US$398.000 million at the acquisition date. Identifiable net assets acquired have a fair value of US$268.791 million. What goodwill is recognised?","choices":["US$209.670 million","US$80.461 million","US$607.670 million","US$876.461 million"],"correct_index":2,"explanation":"Goodwill equals consideration plus the previously held interest at fair value minus identifiable net assets: US$478.461 million plus US$398.000 million minus US$268.791 million equals US$607.670 million. Omitting the old stake would wrongly give US$209.670 million."},{"id":"cr-s13-d20261026-l2-q2","session":13,"level":2,"set":3,"supplement":"2026-10-26","topic":"Carrying amount of the old stake","question":"A previously held 50% interest in a joint venture is remeasured to a fair value of US$398.000 million when the acquirer obtains control, producing a gain of US$273.245 million in profit or loss. What was the carrying amount of that stake immediately before the remeasurement?","choices":["US$671.245 million","US$124.755 million","US$273.245 million","US$398.000 million"],"correct_index":1,"explanation":"The gain is the fair value minus the carrying amount, so the carrying amount is US$398.000 million minus US$273.245 million, which equals US$124.755 million."},{"id":"cr-s13-d20261026-l2-q3","session":13,"level":2,"set":3,"supplement":"2026-10-26","topic":"Profit excluding the one-off gain","question":"A group reported net profit of about US$364.268 million for the year, which included a one-off US$273.245 million gain on remeasuring a previously held equity stake to fair value when it obtained control. Excluding only that gain, what was the group's profit?","choices":["About US$91.023 million","About US$637.513 million","About US$273.245 million","About US$364.268 million"],"correct_index":0,"explanation":"Removing the non-recurring gain gives US$364.268 million minus US$273.245 million, about US$91.023 million. Most of the reported bottom line came from the remeasurement rather than from operations."},{"id":"cr-s13-d20261026-l2-q4","session":13,"level":2,"set":3,"supplement":"2026-10-26","topic":"Value-in-use sensitivity","question":"A group estimates the value in use of a cash-generating unit with a discounted cash flow model built on five-year budgets. Which set of assumptions is the recoverable amount most sensitive to?","choices":["The historical cost of the acquired assets and the legal life of the patents","The discount rate, the expected cash inflows and the terminal growth rate","The share price on the acquisition date and the number of shares issued","The tax rate and the residual value of property, plant and equipment"],"correct_index":1,"explanation":"Value in use moves primarily with the discount rate, the level of expected cash inflows and the growth rate used to extrapolate beyond the explicit forecast. This is why IAS 36 asks for disclosure of these key assumptions."},{"id":"cr-s13-d20261026-l2-q5","session":13,"level":2,"set":3,"supplement":"2026-10-26","topic":"Reading assumption revisions","question":"For one cash-generating unit, a group revises its average growth assumption from 21% to 15% and its pre-tax discount rate from 16% to 17%. The unit is impaired that year. Which statement best explains why these revisions point towards impairment?","choices":["A higher discount rate increases value in use, while a lower growth assumption leaves it unchanged","Lower growth only affects the terminal value and never the explicit five-year forecast period","A higher discount rate signals stronger expected performance and therefore supports the carrying amount","Both revisions reduce value in use, through smaller projected inflows and a smaller present value"],"correct_index":3,"explanation":"Value in use falls when forecast cash inflows shrink or when the discount rate rises. The unit suffered both revisions, which is consistent with the impairment recognised."},{"id":"cr-s13-d20261026-l2-q6","session":13,"level":2,"set":3,"supplement":"2026-10-26","topic":"Acquired receivables at fair value","question":"In a business combination, acquired trade receivables have a gross contractual amount of US$10.669 million but a fair value of US$10.445 million, because US$0.224 million of contractual cash flows is not expected to be collected. How are these receivables reflected in the acquisition accounting?","choices":["Recognised at US$10.669 million gross, together with a separate US$0.224 million allowance for doubtful debts","Excluded from identifiable net assets until the cash is actually collected from customers","Recognised at their US$10.445 million fair value, with no separate acquired allowance carried over","Recognised at US$10.669 million gross, with the US$0.224 million shortfall added to goodwill"],"correct_index":2,"explanation":"In a business combination, acquired receivables are recognised at fair value, which already embeds the expected uncollectible amount. The US$0.224 million gap between gross and fair value exists for exactly this reason."},{"id":"cr-s13-d20261026-l2-q7","session":13,"level":2,"set":3,"supplement":"2026-10-26","topic":"Reading pro-forma disclosure","question":"A group's business combination note discloses that if the combination had taken place at the beginning of the financial year, group revenue from continuing operations would have been about 17% higher, while profit for the year, net of tax, would have been approximately the same. What does this pro-forma information tell a reader?","choices":["The acquiree added meaningful revenue scale but only a marginal contribution to profit over the period","The acquiree was loss-making and dragged the group's profit down by about 17% over the period","The acquisition roughly doubled the group's overall profitability compared with the previous financial year","Pro-forma disclosures replace the annual impairment test for the goodwill on this acquisition"],"correct_index":0,"explanation":"The pro-forma note separates scale from profitability: a full year of the acquiree would have lifted revenue by about 17% but left profit broadly unchanged, so the acquired business added little to the bottom line in this period."},{"id":"cr-s13-d20261026-l2-q8","session":13,"level":2,"set":3,"supplement":"2026-10-26","topic":"Implied total valuation","question":"A buyer transfers total consideration of US$478.461 million for an additional 50% interest in a joint venture. Treating that price as proportionate, what total equity value does it imply for 100% of the business at the acquisition date?","choices":["About US$239.2 million","About US$478.5 million","About US$1,434.4 million","About US$956.9 million"],"correct_index":3,"explanation":"Doubling the price paid for half the company gives about US$956.9 million. Halving it, or treating the payment as the price of the whole, misreads the proportion acquired."},{"id":"cr-s13-d20261026-l2-q9","session":13,"level":2,"set":3,"supplement":"2026-10-26","topic":"Customer relationships amortisation","question":"A group reports net customer relationships of about US$131.236 million at year end, with an average remaining amortisation period of six years. Using straight-line amortisation with zero residual value, what approximate annual charge does this imply?","choices":["About US$13.1 million per year","About US$65.6 million per year","About US$21.9 million per year","About US$6.0 million per year"],"correct_index":2,"explanation":"Dividing US$131.236 million by six years gives about US$21.9 million per year. The shorter distractors divide by ten or invert the computation."},{"id":"cr-s13-d20261026-l2-q10","session":13,"level":2,"set":3,"supplement":"2026-10-26","topic":"Working back to net assets","question":"A group reports goodwill of US$622.181 million and other intangible assets of US$162.008 million, together representing about 70% of its net assets. What approximate net asset total does that imply?","choices":["About US$784 million","About US$1,120 million","About US$549 million","About US$2,240 million"],"correct_index":1,"explanation":"The two items sum to US$784.189 million, and dividing by 70% gives about US$1,120 million of net assets. Multiplying by 70% instead of dividing yields the US$549 million distractor."},{"id":"cr-s13-d20261026-l3-q1","session":13,"level":3,"set":4,"supplement":"2026-10-26","topic":"Deferred tax and goodwill","question":"In a purchase price allocation, the acquirer recognises a deferred tax liability of US$21.027 million linked to the fair value uplift of identifiable assets. The notes state that none of the recognised goodwill is tax-deductible and no deferred tax is recognised on it. Which reasoning is consistent with this treatment?","choices":["Deferred tax is recognised on goodwill but it is netted against the deferred tax arising on the other identified intangibles","Goodwill is exempt from deferred tax on initial recognition, unlike the temporary differences on identified assets","The absence of tax deductibility forces an immediate impairment test and write-down of the goodwill","Goodwill generates a deferred tax asset that exactly offsets the deferred tax liability on the other assets"],"correct_index":1,"explanation":"Fair value uplifts on identified assets create taxable temporary differences and a deferred tax liability. Goodwill is different: standards prohibit recognising deferred tax on its initial recognition, and here the goodwill is also not tax-deductible, so no deferred tax attaches to it."},{"id":"cr-s13-d20261026-l3-q2","session":13,"level":3,"set":4,"supplement":"2026-10-26","topic":"Goodwill disposed on relative values","question":"A cash-generating unit holds US$80 million of goodwill. The entity sells one operation of the unit. The operation represents 40% of the unit's total recoverable amount but 55% of the unit's total carrying amount excluding goodwill, and no other method better reflects the goodwill attached to the operation. What amounts of goodwill are derecognised with the operation and retained in the unit?","choices":["Derecognised US$44 million and retained US$36 million","Derecognised US$80 million and retained nothing","Derecognised nothing until the unit's next annual test","Derecognised US$32 million and retained US$48 million"],"correct_index":3,"explanation":"Goodwill leaving with a disposed operation is measured on the relative VALUES of the operation sold and the part retained: 40% of US$80 million = US$32 million derecognised and US$48 million retained. Choice A applies the 55% carrying-amount share, which is not the IAS 36 basis, choice B strips the whole unit's goodwill into one disposal, and choice C defers a derecognition that the disposal triggers immediately."},{"id":"cr-s13-d20261026-l3-q3","session":13,"level":3,"set":4,"supplement":"2026-10-26","topic":"Measuring equity consideration","question":"As consideration for an acquisition, the buyer issues 260 million ordinary shares and convertible notes. The ordinary shares are valued at the published share price at the acquisition date, S$1.155 each for US$229.581 million in total, while the convertible notes are valued using an appropriate valuation model for US$126.549 million. Why are two different measurement approaches used?","choices":["Shares are measured at fair value, but convertible instruments must always be measured at their historical issue proceeds","The convertible notes were measured at par because no market price existed for them on the acquisition date","Both instruments were measured at the book value of the buyer's equity before the deal was signed","Fair value is required for both: quoted shares use the market price, the notes need a model for the conversion feature"],"correct_index":3,"explanation":"Consideration is measured at fair value at the acquisition date whatever its form. Listed shares take the published price, while a convertible note embeds an equity conversion option whose fair value requires a valuation model."},{"id":"cr-s13-d20261026-l3-q4","session":13,"level":3,"set":4,"supplement":"2026-10-26","topic":"Market price pressure as an indicator","question":"Shortly after recognising US$607.670 million of goodwill on an acquisition, tested using 18% average growth, a 2% terminal growth rate and a 12% pre-tax discount rate, a medical device group expects price cuts of 15% to 20% in its main market because of competitive tendering. Which analysis is most consistent with IAS 36?","choices":["The expected cuts pressure forecast inflows, so they belong in the value-in-use estimates even if no impairment is recognised","Price cuts expected after the acquisition cannot affect value in use, because goodwill is fixed at its acquisition-date amount","The 2% terminal growth rate largely immunises the valuation against changes in market prices","Impairment indicators only matter for goodwill after five years of forecasts have been missed"],"correct_index":0,"explanation":"Goodwill is tested annually and whenever an indication arises. Expected tender-driven price cuts of 15% to 20% are exactly the kind of adverse market evidence that must feed the forecast cash inflows in the value-in-use model."},{"id":"cr-s13-d20261026-l3-q5","session":13,"level":3,"set":4,"supplement":"2026-10-26","topic":"No reversal of goodwill impairment","question":"A group's policy, following IAS 36, states that impairment losses recognised for goodwill are not reversed in subsequent periods. A unit's goodwill was written down by US$10 million last year, and this year the unit's recoverable amount rises US$25 million above the reduced carrying amount. What does IAS 36 require?","choices":["A full US$10 million reversal recognised in this year's profit or loss","A reversal capped at the increase in the group's market capitalisation over the year","No reversal, so the goodwill stays at its reduced carrying amount","A reversal only if the recovery persists for two consecutive reporting years"],"correct_index":2,"explanation":"Goodwill impairment is never reversed under IAS 36, whatever the later recovery, because any rebound is economically indistinguishable from internally generated goodwill, which cannot be recognised."},{"id":"cr-s13-d20261026-l3-q6","session":13,"level":3,"set":4,"supplement":"2026-10-26","topic":"Grouping units for goodwill testing","question":"A group tests goodwill on a cash-generating unit that actually combines two of its businesses, because goodwill is allocated to the units expected to benefit from the synergies of the combination. What is the correct rationale for testing goodwill at such a grouped level?","choices":["Grouping units is a free choice that management can use to offset weak units against strong ones without any real limit","Goodwill has no independent cash flows, so it is tested with the smallest unit group that benefits from the synergies","Goodwill must always be tested at the whole-entity level, so grouping two businesses is only a presentation shortcut","Units may be grouped only when they operate in the same country and report in the same currency"],"correct_index":1,"explanation":"Because goodwill produces no cash flows on its own, IAS 36 attaches it to the units that benefit from the synergies and tests it there. The grouping follows the synergies. It is not an open licence to bury weak units inside strong ones."},{"id":"cr-s13-d20261026-l3-q7","session":13,"level":3,"set":4,"supplement":"2026-10-26","topic":"Reconstructing an underlying result","question":"A group's net profit is about US$364.268 million. It includes a US$273.245 million one-off gain on remeasuring a previously held stake to fair value, and it is stated after US$12.232 million of goodwill impairment on older units. Because the goodwill is not tax-deductible, that impairment had no tax effect. An analyst who removes the gain and adds back the impairment arrives at what approximate adjusted profit?","choices":["About US$78.8 million","About US$115.5 million","About US$649.7 million","About US$103.3 million"],"correct_index":3,"explanation":"Starting from US$364.268 million, removing the gain gives US$91.023 million, and adding back the impairment with no tax effect gives about US$103.255 million. Subtracting the impairment instead of adding it produces the US$78.8 million distractor."},{"id":"cr-s13-d20261026-l3-q8","session":13,"level":3,"set":4,"supplement":"2026-10-26","topic":"Step acquisition logic","question":"In a step acquisition, the acquirer obtains control by buying the remaining 50% of a joint venture. It both recognises a US$273.245 million gain on its old stake in profit or loss and uses that stake's fair value when computing goodwill. Which statement captures the logic?","choices":["The old interest is exchanged at fair value and the whole business acquired, so the uplift hits profit or loss and feeds goodwill","The gain is recognised because the old stake was sold to an independent third party at the same time as control was obtained","The old stake keeps its carrying amount in the goodwill computation, and the remeasurement gain is deferred until the shares are actually sold","The remeasurement gain offsets goodwill directly on the balance sheet, which avoids counting the uplift twice"],"correct_index":0,"explanation":"A step acquisition is accounted for as if the previously held interest were disposed of at fair value and the whole business acquired at once. The fair value uplift therefore runs through profit or loss and also forms part of the total value compared against identifiable net assets."},{"id":"cr-s13-d20261026-l3-q9","session":13,"level":3,"set":4,"supplement":"2026-10-26","topic":"Allocation of an impairment loss","question":"A group's goodwill impairment of US$12.232 million was absorbed entirely by the goodwill of the affected cash-generating units, while their other assets kept their carrying amounts. Under the IAS 36 allocation approach, when a cash-generating unit's impairment loss exceeds its goodwill, what happens next?","choices":["The excess is rolled forward as a deferred charge and amortised against future profits","The loss stops at goodwill and any excess above it is simply never recognised","The remaining loss is allocated pro rata to the unit's other assets, within their floors","The excess reduces the carrying amount of the unit's liabilities before touching other assets"],"correct_index":2,"explanation":"Impairment absorbs goodwill first, which is why this loss touched only goodwill. Any excess would then be allocated pro rata to the other assets of the unit, without pushing any asset below the applicable floor."},{"id":"cr-s13-d20261026-l3-q10","session":13,"level":3,"set":4,"supplement":"2026-10-26","topic":"Seller gain versus buyer goodwill","question":"On the sale of a 50% stake in a joint venture, the seller recognises a disposal gain of about US$421 million and receives convertible notes that make it the buyer's largest shareholder with 21.6% after conversion. The buyer, which thereby obtains full control, recognises US$607.670 million of goodwill. Which statement best reconciles these two outcomes?","choices":["The seller's gain and the buyer's goodwill are two labels for the same economic number, computed on identical baselines","A large disposal gain for the seller proves the buyer overpaid and forces an immediate impairment of the goodwill","The convertible notes eliminate the goodwill because the seller keeps an economic interest in the combined group","They measure different things against different baselines, so the two figures can both be large"],"correct_index":3,"explanation":"The seller compares the price with the carrying amount it derecognises. The buyer compares the total value transferred with the fair value of identifiable net assets. Different baselines explain why both numbers can be large at once. Neither figure proves impairment on its own."}],"fm":[{"id":"fm-s6-q15","session":"6","topic":"Three debt strategies","question":"A borrower takes a three-year floating-rate loan at SOFR + 2%, reset annually. Which component of its interest cost is certain, and which is not?","choices":["The SOFR base rate is locked for three years; only the credit spread is uncertain.","Both components are locked for the full three years.","The credit spread is locked for three years; only the SOFR base rate resets annually.","Both components reset at every annual rollover."],"correct_index":2,"explanation":"Unlike the one-year rollover strategy, a floating-rate loan fixes the credit spread for the whole maturity; only the base rate (SOFR) resets, so the borrower carries rate risk but no spread renegotiation risk.","set":2},{"id":"fm-s6-q16","session":"6","topic":"Interest payable","question":"A company has an $8,000,000 floating-rate loan at SOFR + 1.8%. SOFR is currently 4%. What total interest does it pay over one year if SOFR stays flat?","choices":["$464,000.","$320,000.","$144,000.","$580,000."],"correct_index":0,"explanation":"Total rate = 4.0% + 1.8% = 5.8%; 5.8% x $8,000,000 = $464,000. $320,000 forgets the spread; $144,000 is the spread alone; $580,000 applies a wrong total rate.","set":2},{"id":"fm-s6-q17","session":"6","topic":"Swap net interest","question":"A firm pays SOFR + 1.8% on its bank loan. It enters a swap to pay fixed 4.5% and receive SOFR. What is its net interest cost after the swap?","choices":["4.5%, because the swap replaces the loan rate entirely.","2.7%, because the spread is subtracted from the fixed rate.","9.0%, because loan and swap costs simply add up.","6.3%, because the SOFR legs cancel and the spread stays."],"correct_index":3,"explanation":"Net cost = (SOFR + 1.8%) + 4.5% - SOFR = 6.3%. The floating leg received from the swap offsets the floating leg paid on the loan; the credit spread always remains.","set":2},{"id":"fm-s6-q18","session":"6","topic":"Up-front fee","question":"Two three-year loans have the same notional and the same interest rate, but loan B charges a 2% up-front fee on the notional while loan A charges none. How do their all-in costs compare?","choices":["Identical, because the fee is a financing cost and not an interest cost of the loan.","Loan B costs more, as the fee cuts proceeds while interest runs on the full notional.","Loan B costs less, because the fee reduces the taxable interest base of the borrower.","Loan B costs more only if rates rise during the three years of the loan."],"correct_index":1,"explanation":"The all-in cost is the IRR of the loan cash flows. The up-front fee cuts the net proceeds at year 0, but interest and repayment are computed on the full notional, so the IRR sits above the nominal rate.","set":2},{"id":"fm-s6-q19","session":"6","topic":"Swap tenor","question":"A company has three years left on a five-year floating-rate loan and wants to lock its rate with an interest rate swap. What swap maturity should it choose?","choices":["Five years, matching the loan's original maturity.","Three years, matching the loan's remaining life.","One year, so the swap can be renegotiated annually.","Ten years, to hedge future refinancings as well."],"correct_index":1,"explanation":"The swap must cover the remaining exposure: a swap longer than the remaining loan life leaves an open derivative position after the loan is repaid, and a shorter one leaves the loan unhedged at the end.","set":2},{"id":"fm-s6-q20","session":"6","topic":"Quality spread differential","question":"Bank A can borrow at 10.0% fixed or SOFR + 0.5% floating. Company B can borrow at 11.5% fixed or SOFR + 1.2% floating. What total gain can a fixed-for-floating swap between them create?","choices":["0.8%, the fixed-rate gap of 1.5% minus the floating-rate gap of 0.7%.","0.7%, the difference between the two floating spreads.","1.5%, the difference between the two fixed rates.","2.2%, the sum of the fixed-rate and floating-rate gaps."],"correct_index":0,"explanation":"The quality spread differential is (11.5% - 10.0%) - (1.2% - 0.5%) = 1.5% - 0.7% = 0.8%. A positive QSD is the necessary condition for a swap to benefit both counterparties and the swap bank.","set":2},{"id":"fm-s7-q17","session":"7","topic":"Risk-free proxy","question":"When estimating the CAPM risk-free rate for a business valuation (cash flows projected over very long periods), which security is the right proxy?","choices":["A three-month Treasury bill, because it is the most liquid government security.","A zero-coupon default-free government bond with maturity matching the cash-flow horizon.","The twelve-month interbank rate, because it is the main money market benchmark.","A ten-year coupon government bond, whatever the duration of the cash flows."],"correct_index":1,"explanation":"The risk-free rate requires two conditions: no default risk (a genuinely default-free government) and no reinvestment uncertainty, which forces a zero-coupon bond whose maturity matches the cash-flow horizon. A short rate creates reinvestment risk.","set":2},{"id":"fm-s7-q18","session":"7","topic":"MRP estimation","question":"Three approaches coexist for estimating the market risk premium (MRP): survey, historical and implied premium. Which statement is correct?","choices":["The survey approach delivers stable, reasonable, long-term premiums.","The historical approach is immune to survivorship bias in market selection.","The historical approach depends neither on the period nor on the averaging method chosen.","The survey approach produces volatile, short-term estimates with no reasonableness constraint."],"correct_index":3,"explanation":"Surveys of money managers look at most one year ahead, are volatile and can deliver implausible premiums. The historical approach suffers from survivorship bias (US markets survived) and stays highly sensitive to the period, the risk-free security and the arithmetic/geometric choice.","set":2},{"id":"fm-s7-q19","session":"7","topic":"Beta determinants","question":"Given the economic determinants of beta, which firm should show the highest beta, all else equal?","choices":["A producer of basic necessity goods whose costs are mostly variable.","A basic food retailer with a flexible cost structure and little debt.","A regulated utility with stable, predictable cash flows and low leverage.","A maker of cyclical luxury goods with a high share of fixed costs and high leverage."],"correct_index":3,"explanation":"Three determinants push beta up: a discretionary, cyclical product, high operating leverage (share of fixed costs) and high financial leverage. The luxury maker cumulates all three; the other profiles minimize them.","set":2},{"id":"fm-s7-q20","session":"7","topic":"After-tax cost of debt","question":"A firm can borrow today at 5.0%. Its marginal tax rate is 30%. Which cost of debt belongs in the WACC?","choices":["5.0%, because the WACC always uses the pre-tax cost of debt.","1.5%, the tax saving generated by deductibility.","3.5%, because interest is tax-deductible: 5.0% x (1 - 0.30).","6.5%, because taxes raise the rate lenders require."],"correct_index":2,"explanation":"Interest is deductible from taxable income, so the after-tax cost of debt is kd x (1 - tc) = 5.0% x 0.70 = 3.5%. That net figure is what enters the WACC.","set":2},{"id":"fm-s7-q21","session":"7","topic":"Synthetic rating","question":"A firm has no public rating and no liquid bonds outstanding. To estimate its cost of debt, you build a synthetic rating. Which ratio does this approach rest on?","choices":["The current ratio: current assets over current liabilities.","The interest coverage ratio: EBIT over interest expenses.","Financial leverage: net debt over the period's EBITDA.","Return on equity: net income over book equity."],"correct_index":1,"explanation":"A synthetic rating maps the interest coverage ratio ICR = EBIT / interest expenses to a default spread. Other models exist (Altman Z-score) but the ICR is the base tool of the course.","set":2},{"id":"fm-s7-q22","session":"7","topic":"Return computation","question":"Over one year, a stock moves from 50 to 54 euros and pays a 2 euro dividend. To regress its beta against the market correctly, which stock return should be used for the period?","choices":["8%, the price appreciation alone.","4%, the dividend over the initial price.","12%, adding the dividend to the capital gain.","6%, the average of the two return components."],"correct_index":2,"explanation":"Returns must include dividends: (54 - 50 + 2) / 50 = 12%. Dropping the dividend understates the return and biases the regression; stock and index must be measured consistently, dividends included.","set":2},{"id":"fm-s8-q15","session":"8","topic":"Beta levering","question":"A firm has an unlevered beta of 0.8, a debt-to-equity ratio D/E of 0.5 (market values) and a marginal tax rate of 30%. What is its levered (equity) beta?","choices":["0.92","0.80","1.20","1.08"],"correct_index":3,"explanation":"Levered beta = unlevered beta x (1 + (1 - t) x D/E) = 0.8 x (1 + 0.7 x 0.5) = 0.8 x 1.35 = 1.08. Dropping the (1 - t) term gives 1.20; leverage always raises the risk borne by shareholders.","set":2},{"id":"fm-s8-q16","session":"8","topic":"FCFO build","question":"A company reports EBIT of 500 million euros, taxes on EBIT of 150 million, D&A of 80 million, a 40 million increase in working capital and net capex of 120 million. What is its operating cash flow (FCFO)?","choices":["350 million euros.","310 million euros.","270 million euros.","190 million euros."],"correct_index":2,"explanation":"NOPAT = 500 - 150 = 350. FCFO = NOPAT + D&A - change in WC - net capex = 350 + 80 - 40 - 120 = 270 million euros. 310 forgets working capital; 190 forgets to add back D&A; 350 is only NOPAT.","set":2},{"id":"fm-s8-q17","session":"8","topic":"Financing need","question":"A growing company earns a positive NOPAT, but its working capital rises sharply and its investment program is heavy. What is its financing position?","choices":["It is self-financed: a positive NOPAT always guarantees a cash surplus.","It has a structural external financing need, because rising working capital and capex absorb its NOPAT.","It can ignore working capital, which only matters for mature firms.","It must stop investing immediately to restore financial balance."],"correct_index":1,"explanation":"Profitability alone says nothing about the financing need: if the change in working capital and net capex absorb the NOPAT, a growing firm must raise external capital, unlike the self-sufficient firm whose FCFO comfortably covers its uses.","set":2},{"id":"fm-s8-q18","session":"8","topic":"Debt strategies","question":"In the debt-strategy typology, what separates debt for growth from aggressive leverage?","choices":["Debt for growth funds visible programs (capex/debt > 50%); aggressive leverage means NFP/EBITDA above 3.0x, the LBO zone.","Debt for growth requires NFP/EBITDA above 3.0x; aggressive leverage is limited to working-capital funding.","Both strategies target a D/E below the industry average to preserve flexibility.","Debt for growth is reserved for start-ups; aggressive leverage for declining firms."],"correct_index":0,"explanation":"Debt for growth funds long-term programs where future cash flows are visible (capex/debt > 50%). Aggressive leverage (NFP/EBITDA > 3.0x, D/E above the industry) funds competitive offensives and LBOs that maximize sponsor IRR.","set":2},{"id":"fm-s8-q19","session":"8","topic":"Capital structure practice","question":"What do real-world companies actually do about capital structure, according to the course?","choices":["They target a credit rating and a leverage range rather than a single point, and adjust opportunistically.","They compute one optimal leverage point and stick to it permanently.","They maximize leverage, because debt is always the cheapest source of funding.","They avoid all debt in order to preserve financial flexibility."],"correct_index":0,"explanation":"In practice frictions dominate the theoretical optimal point: market timing, financial flexibility (keeping unused debt capacity), ratings and covenants, management incentives. Firms target a range and a rating (e.g. investment grade), not a single point.","set":2},{"id":"fm-s8-q20","session":"8","topic":"U-shaped WACC","question":"On the U-shaped WACC curve, why does the WACC fall while leverage stays below the optimal level D/E*?","choices":["Because the cost of debt kd falls mechanically as leverage rises.","Because the firm's unlevered beta declines as it takes on debt.","Because shareholders accept a lower return when debt is present.","Because the marginal benefit of the tax shield exceeds the marginal cost of financial distress."],"correct_index":3,"explanation":"Left of D/E*, the tax advantage of debt (deductible interest, debt cheaper than equity) outweighs the rise of kd and ke. Beyond D/E*, distress and agency costs dominate and the WACC rises again.","set":2},{"id":"fm-s9-q1","session":"9","topic":"LBO definition","question":"What fundamentally defines a leveraged buyout?","choices":["An acquisition financed mostly with equity and a thin slice of debt, repaid from the sponsor's own funds.","An acquisition financed mostly with debt, where the target's own cash flow services and repays the acquisition debt over the holding period.","A merger between two listed companies paid entirely in shares of the combined entity.","The purchase of a minority stake in a private company with a bank loan guaranteed by the sponsor."],"correct_index":1,"explanation":"In an LBO, debt funds roughly 60-80% of the purchase price and the acquired company's own cash flow repays it; the sponsor only writes the equity cheque.","set":1},{"id":"fm-s9-q2","session":"9","topic":"PE fund economics","question":"In a typical private equity limited partnership, how is the general partner compensated?","choices":["A flat salary paid by the limited partners plus a bonus tied to fund headcount.","A management fee of 5-10% of committed capital, with no share of the fund's profits.","A 50% carried interest on all profits, with no annual management fee.","A 1-2% management fee plus 20% carried interest, earned only above the LPs' hurdle."],"correct_index":3,"explanation":"GPs charge a 1-2% management fee and about 20% carried interest, subject to a hurdle: the carry is earned only once LPs have received their minimum required return.","set":1},{"id":"fm-s9-q3","session":"9","topic":"Value creation engines","question":"A sponsor buys a company for 7.0x EBITDA and sells it five years later for 9.0x EBITDA, with EBITDA and net debt unchanged over the hold. Which value creation engine generated the entire return?","choices":["Operational improvement, because margins were stable throughout the hold.","Leverage, because net debt stayed constant over the five years.","Arbitrage, because the whole gain comes from multiple expansion between entry and exit.","Cash sweep, because free cash flow was used to pay a dividend each year."],"correct_index":2,"explanation":"With unchanged EBITDA and net debt, the only source of gain is buying at 7.0x and selling at 9.0x: multiple expansion, which is the arbitrage engine (A of A-L-O).","set":1},{"id":"fm-s9-q4","session":"9","topic":"Leverage and MOIC","question":"A company is bought for 100 million euros and sold five years later for 180 million euros, with debt held constant. If 70% of the purchase was funded with debt, the sponsor's money-on-money multiple (MOIC) is closest to:","choices":["1.8x","2.6x","3.7x","6.0x"],"correct_index":2,"explanation":"Equity in = 30% x 100 = 30m. Equity out = 180 - 70 debt = 110m. MOIC = 110 / 30 = 3.7x. The same sale with all-equity funding would give only 1.8x: leverage amplifies the equity return.","set":1},{"id":"fm-s9-q5","session":"9","topic":"LBO candidate profile","question":"Which profile is the LEAST attractive LBO candidate?","choices":["A mature manufacturer with stable operating cash flows and little existing debt.","A market leader with high barriers to entry, moderate capex and excess cash on its balance sheet.","An underperforming retailer whose margins lag peers but whose cash flows are predictable.","A biotech startup with negative and highly volatile cash flows and heavy R&D spending needs."],"correct_index":3,"explanation":"Good LBO candidates have stable, predictable cash flows that can service acquisition debt, moderate capex and R&D, and ideally low existing leverage. Volatile negative cash flows cannot carry debt.","set":1},{"id":"fm-s9-q6","session":"9","topic":"Exit routes","question":"Five years after entry, a sponsor has the portfolio company take on new debt and pays itself a large dividend, without selling the business. This exit route is called:","choices":["a secondary buyout.","an initial public offering.","a trade sale to a strategic buyer.","a dividend recapitalisation."],"correct_index":3,"explanation":"A dividend recapitalisation re-levers the company to return cash to the sponsor without a full exit. The other routes all transfer ownership: to a corporate buyer, to another sponsor, or to public market investors.","set":1},{"id":"fm-s9-q7","session":"9","topic":"Sources and uses","question":"An LBO shows total uses of 500 million euros (purchase price, transaction fees and minimum cash). Lenders provide 325 million euros across all debt tranches. The sponsor equity cheque required to balance sources and uses is:","choices":["325 million euros.","175 million euros.","825 million euros.","500 million euros."],"correct_index":1,"explanation":"Sponsor equity is the balancing plug: sources must equal uses, so equity = 500 - 325 = 175 million euros.","set":1},{"id":"fm-s9-q8","session":"9","topic":"LBO debt stack","question":"In a typical LBO capital stack, which tranche prices cheapest, and why?","choices":["Subordinated notes, because their longer maturity reduces the lender's risk.","Sponsor equity, because it carries no contractual coupon at all.","The revolving credit facility, because it is senior, secured and first in priority.","Senior unsecured notes, because they are callable after four years at par."],"correct_index":2,"explanation":"Pricing steps up down the stack: the senior secured revolver and term loans price first and cheapest, and each junior layer adds roughly 100 bps for weaker seniority plus about 50 bps for longer maturity.","set":1},{"id":"fm-s9-q9","session":"9","topic":"Cash sweep mechanics","question":"Under a 100% cash sweep, why are high-yield bonds typically NOT prepaid with excess free cash flow?","choices":["Bondholders must vote to accept early repayment, and they vote once a year.","Prepaying the bonds would trigger a call premium, so the sweep repays term loans first.","The sweep applies only to amounts drawn on the revolving credit facility.","The bonds rank above the term loans in the repayment waterfall."],"correct_index":1,"explanation":"High-yield notes are bullets that cannot be swept without paying a call premium; the contractual sweep therefore forces excess cash onto the term loans (TLA first, then TLB) in seniority order.","set":1},{"id":"fm-s9-q10","session":"9","topic":"Levered free cash flow","question":"A portfolio company reports EBITDA of 400 million euros, maintenance capex of 40 million, a 10 million increase in net working capital, cash interest of 150 million and cash taxes of 60 million. Its levered free cash flow available for debt repayment is:","choices":["140 million euros.","200 million euros.","250 million euros.","340 million euros."],"correct_index":0,"explanation":"Levered FCF = EBITDA - maintenance capex - change in NWC - cash interest - cash taxes = 400 - 40 - 10 - 150 - 60 = 140 million euros.","set":1},{"id":"fm-s9-q11","session":"9","topic":"Model circularity","question":"Why does an LBO model contain a deliberate circular reference, and how is it resolved in Excel?","choices":["Interest depends on average debt balances, which depend on the cash sweep, which itself depends on interest; enabling iterative calculation lets the loop settle.","EBITDA depends on the exit multiple, which depends on entry debt; the modeller must break the loop by hardcoding the exit year.","Taxes depend on dividends, which depend on the sponsor's hurdle rate; the modeller runs goal seek once at entry.","There is no circularity in practice: interest is always computed on opening balances only."],"correct_index":0,"explanation":"Interest on average balances needs the closing balance, which needs the sweep, which needs interest. The loop is a feature: iterative calculation resolves it each forecast year.","set":2},{"id":"fm-s9-q12","session":"9","topic":"Trading vs transaction multiples","question":"What distinguishes a transaction multiple from a trading multiple?","choices":["Transaction multiples use forecast profits, trading multiples use historical profits.","Transaction multiples reflect control deals and a premium, trading multiples reflect listed peers.","Trading multiples always exceed transaction multiples because listed stocks are overpriced.","Transaction multiples apply only to equity value, trading multiples only to enterprise value."],"correct_index":1,"explanation":"Trading multiples price a minority, liquid stake from market quotes; transaction multiples price control, embedding a control premium and expected synergies, from actual M&A deal prices.","set":2},{"id":"fm-s9-q13","session":"9","topic":"Multiple consistency","question":"Which pairing of numerator and profit measure is consistent when applying a multiple?","choices":["Enterprise value over net income.","Equity value over EBITDA.","Price per share over earnings per share.","Enterprise value over free cash flow to equity."],"correct_index":2,"explanation":"Enterprise value pairs with asset-side profits (EBIT, EBITDA, FCFO); equity prices pair with equity-side profits (net income, EPS, FCFE). Price per share over EPS is the consistent equity-side pair; mixing the two sides is the classic valuation error.","set":2},{"id":"fm-s9-q14","session":"9","topic":"IRR vs MOIC","question":"A sponsor reports a 1.8x MOIC and a 12% IRR on the same exit. What does the pair tell you that the MOIC alone does not?","choices":["The IRR captures timing: the same 1.8x achieved a year earlier would give a higher IRR.","Nothing, because the MOIC already reflects timing and the IRR adds no information.","The IRR measures absolute cash profit, independent of the holding period.","A 12% IRR always corresponds to a 1.8x MOIC whatever the exit year."],"correct_index":0,"explanation":"MOIC is cash in divided by cash out and ignores timing; IRR is annualised, so it falls as the same multiple is achieved later. Both are reported together for exactly that reason.","set":2},{"id":"fm-s1-q1","session":"1","topic":"Toys R Us case","question":"A retailer has heavy debt service and must invest to adapt to online competition. Why can positive accounting profit still fail to protect it from bankruptcy?","choices":["Cash available for debt service and reinvestment can be insufficient.","Depreciation creates cash that can replace customer collections.","A positive income statement removes the need to refinance debt.","Profit automatically finances investment even before customers pay."],"correct_index":0,"explanation":"Profit and cash are different. The Toys R Us slides link financial charges and limited cash to difficulty servicing debt and maintaining investment, not to an absence of accounting entries.","set":1},{"id":"fm-s1-q2","session":"1","topic":"Value creation","question":"A company reports a profit but cannot pay suppliers and has an unsustainable balance sheet. Which assessment fits the three equilibria framework?","choices":["Income statement success alone does not establish sustainable value creation.","Income statement success offsets any balance sheet or cash flow imbalance.","Cash flow equilibrium can replace both profitability and balance sheet equilibrium.","Balance sheet equilibrium matters only when the company reports a loss."],"correct_index":0,"explanation":"The framework requires income statement, balance sheet and cash flow equilibria together. A profit does not resolve a liquidity shortage or an unsustainable financing structure.","set":1},{"id":"fm-s1-q3","session":"1","topic":"Value creation rationale","question":"Why is revenue growth alone an inadequate substitute for value creation as a corporate objective?","choices":["Revenue growth provides the same sustainability test across all business models.","Revenue growth measures the market value of equity without valuation.","Revenue can grow without supporting sustainable development and returns.","Revenue growth ensures that cash inflows exceed all financing obligations."],"correct_index":2,"explanation":"The slide calls value creation rational, measurable, broadly accepted and applicable across sectors and life stages. It warns that revenue and market share do not necessarily track sustainable success.","set":1},{"id":"fm-s1-q4","session":"1","topic":"Business plan vs financial plan","question":"A business plan proposes rapid expansion into a new market. What should its financial plan test?","choices":["Whether financial projections can replace the proposed operating strategy.","Whether historical accounts make future funding forecasts unnecessary.","Whether projected sales alone are sufficient to approve the expansion.","Whether expansion is sustainable given projected earnings, cash and funding."],"correct_index":3,"explanation":"The financial plan is the financial profile of the business plan. It tests feasibility and sustainability and sets financial goals consistent with the operating strategy.","set":1},{"id":"fm-s1-q5","session":"1","topic":"Planning under uncertainty","question":"Forecast errors and the spread between plausible scenarios are increasing. Which planning response fits the uncertainty challenges in the slides?","choices":["Freeze estimates for longer so that forecasts appear more consistent.","Revise estimates more frequently as assumptions and actual results change.","Replace scenario ranges with one figure to remove business uncertainty.","Stop comparing forecasts with actuals because volatility invalidates comparison."],"correct_index":1,"explanation":"The slides identify greater volatility, wider forecast gaps, more dispersed scenarios and more frequent revisions. Updating estimates addresses changed information rather than pretending that uncertainty has disappeared.","set":1},{"id":"fm-s1-q6","session":"1","topic":"Momentum case","question":"Management forecasts sales without new initiatives, then adds a separate contribution for each proposed initiative. Which planning practice is this?","choices":["Back testing by comparing last month's forecast with realized sales.","Building a momentum case from a baseline with initiatives added separately.","Disaggregating inflation by forecasting each input cost separately.","Building a bear case by assuming every initiative fails simultaneously."],"correct_index":1,"explanation":"A momentum case separates the baseline trajectory from management actions. This makes the incremental contribution of each initiative visible. A bear case is a distinct downside scenario.","set":1},{"id":"fm-s1-q7","session":"1","topic":"Disaggregating inflation","question":"Energy costs are rising faster than service costs, while selling prices adjust slowly. How should inflation enter the forecast?","choices":["Model the components separately and check that revenue and cost assumptions fit together.","Use selling price inflation for every input because both are measured in money.","Apply one CPI rate to all costs and assume selling prices move by the same rate.","Exclude inflation from costs and include it only in the revenue forecast."],"correct_index":0,"explanation":"Disaggregation captures different inflation pressures across business components. Checking revenue and cost assumptions together avoids hiding margin pressure behind a single blended rate.","set":1},{"id":"fm-s1-q8","session":"1","topic":"Planning toolkit","question":"Treasury needs weekly detail on cash shortages over the next nine months. Which tool best matches that need in the course table?","choices":["A historical income statement reporting accrued revenue and expenses.","A financial budget focused on annual operating and investment targets.","A cash budget focused on inflows, outflows and periodic balances.","A financial plan updated annually over a strategic five year horizon."],"correct_index":2,"explanation":"The cash budget has monthly or weekly frequency, high granularity and a horizon of six months to one year. It supports treasury and liquidity management rather than strategic valuation.","set":1},{"id":"fm-s1-q9","session":"1","topic":"Planning toolkit","question":"A company wants to assess funding needs for a five year expansion strategy. Which planning design matches the course table?","choices":["A monthly income statement without balance sheet or cash flow projections.","An annually updated financial plan covering projected statements over several years.","An annual financial budget limited to the coming year's resource allocation.","A weekly cash budget restricted to the next six months of collections."],"correct_index":1,"explanation":"The table assigns the financial plan a medium to long horizon of three, five or seven years, with annual updates. Its purpose includes supporting strategy and assessing funding needs.","set":1},{"id":"fm-s1-q10","session":"1","topic":"Why cost/revenue is not cash","question":"A company records depreciation, sells on credit and repays loan principal. Why must its cash budget adjust the income statement information?","choices":["These involve a noncash expense, delayed collection and a cash payment outside profit.","All three are noncash entries that should be omitted from every cash forecast.","These affect profit only, so their timing does not matter for cash balances.","All three involve cash payments in the same period as income statement expenses."],"correct_index":0,"explanation":"Depreciation is noncash, credit sales can be collected later and principal repayments reduce cash without being expenses. The cash budget must translate accrual events and include cash events outside the income statement.","set":1},{"id":"fm-s1-q11","session":"1","topic":"Cash budget identity","question":"June ends with €20,000 cash. July has €50,000 collections, €60,000 payments and €1,000 interest charges, none counted twice. What is July's closing cash?","choices":["€11,000, after treating the interest charge as cash income.","A €11,000 deficit, after resetting July's opening cash to zero.","€19,000, after ignoring the operating cash deficit.","€9,000, after carrying June's closing balance into July."],"correct_index":3,"explanation":"July opens with June's €20,000. Collections less payments reduce cash by €10,000 and interest charges reduce it by another €1,000, leaving €9,000. Each cash flow is included once.","set":2},{"id":"fm-s1-q12","session":"1","topic":"Timing mismatch categories","question":"A machine was paid for last year and generates €12,000 depreciation this year. Ignoring tax effects, how should that depreciation enter this year's cash budget?","choices":["It creates a €12,000 investing payment when depreciation is recorded.","It creates a supplier payment deferred until the depreciation period ends.","It creates no current cash payment despite reducing accounting profit.","It creates a €12,000 financing receipt that replenishes the cash balance."],"correct_index":2,"explanation":"Depreciation allocates a past investment cost to accounting periods. It is a noncash expense. The machine's payment belongs in the period when cash was actually paid, not every depreciation period.","set":2},{"id":"fm-s1-q13","session":"1","topic":"Timing mismatch categories","question":"A company repays €8,000 of loan principal and pays €500 interest. Which treatment correctly distinguishes cash and profit?","choices":["Only principal reduces cash because interest is an accounting accrual.","Only interest reduces cash because principal is recorded on the balance sheet.","Both reduce cash, but only the interest is an expense in this simplified example.","Both reduce cash and both are expenses because the bank receives them."],"correct_index":2,"explanation":"Principal repayment is a cash use outside the income statement. Interest is a financing cost and a cash payment when paid. Recording principal as an expense would confuse financing repayment with profit measurement.","set":2},{"id":"fm-s1-q14","session":"1","topic":"Sources of cash","question":"An operating firm's cash forecast weakens because customers are taking longer to pay. Which line should treasury examine first to diagnose this problem?","choices":["Asset valuations, because increases are immediately available to pay suppliers.","The timing of collections from customers, a usual major source of operating cash.","Share capital balances, because they become cash each time a sale is invoiced.","Depreciation charges, because they generate the cash used to finance receivables."],"correct_index":1,"explanation":"Customer payments are usually the largest cash source in the planning slides. Slower collection shifts inflows later even if revenue has already been recognized. Financing can cover a gap but does not diagnose its origin.","set":2},{"id":"fm-s1-q15","session":"1","topic":"Clank case","question":"Clank must demonstrate financial sustainability before receiving IPO proceeds. Which forecast best serves the case objective?","choices":["A cash budget that includes IPO proceeds as opening cash before funds are received.","A balance sheet projection that omits monthly collection and payment timing.","An income statement that treats all invoices as cash collected immediately.","A cash budget for the next twelve months that excludes the anticipated IPO cash injection."],"correct_index":3,"explanation":"The Clank case requires a twelve month assessment on a pre money basis. The cash budget must reflect collection delays and actual payment dates. Assuming IPO cash is already available would bypass the test the case asks for.","set":2},{"id":"fm-s1-q16","session":"1","topic":"Clank case, capex","question":"Clank pays 50% of its €150,000 CRM investment in September. What is the September cash use for that installment, separately from depreciation?","choices":["€22,500, because annual depreciation determines the installment paid.","€12,500, because the investment must be spread evenly across twelve months.","€150,000, because the full investment must be paid in each installment month.","€75,000, because the cash budget follows the investment payment schedule."],"correct_index":3,"explanation":"The specified September installment is 50% of €150,000, which is €75,000. Annual depreciation of €22,500 is an accounting allocation, not the cash payment. The case classifies the project as expansion capex.","set":2},{"id":"fm-s2-q1","session":"2","topic":"Root cause","question":"Several managers improve their individual targets while receivables and inventory absorb more cash. What common problem does the HBR article suggest investigating?","choices":["The absence of a single industry ratio that all departments should maximize.","Performance measures that reward local results without accounting for capital tied up.","A need to remove every performance measure instead of changing incentives.","A cash shortage that must be explained entirely by unfavorable market conditions."],"correct_index":1,"explanation":"The article links working capital mistakes to metrics and incentives that overlook balance sheet effects. Its response is a culture of value and dialogue, with measures used thoughtfully rather than followed blindly.","set":1},{"id":"fm-s2-q2","session":"2","topic":"Mistake 1","question":"A buyer earns a bonus for purchase price savings and accepts a bulk discount that ties up excess inventory. What is missing from the decision?","choices":["A larger inventory target to make the purchase price bonus more reliable.","A rule rejecting every discount regardless of its economic benefit.","A comparison of the discounted unit price with last year's unit price alone.","A comparison of price savings with the cost of capital and other inventory costs."],"correct_index":3,"explanation":"Income statement incentives can favor a discount while ignoring capital tied up. The firm should compare all relevant costs and gains, including the opportunity cost of inventory, before accepting the offer.","set":1},{"id":"fm-s2-q3","session":"2","topic":"Metals refining case","question":"The metals refining case reports $8 million annual capital cost savings and $3 million margin lost after faster collection. What does this comparison show?","choices":["The reported savings exceed the margin loss by about $5 million annually.","The reported margin loss exceeds the savings by about $5 million annually.","The fall in sales proves faster collection destroyed value despite the savings.","The recovered capital itself is an additional recurring annual profit."],"correct_index":0,"explanation":"On the article's figures, $8 million less $3 million gives a net annual benefit of about $5 million. The $115 million capital released is a stock of funds, not a recurring annual profit. The source uses dollars, not euros.","set":1},{"id":"fm-s2-q4","session":"2","topic":"Mistake 2","question":"Salespeople receive bonuses based only on sales volume. Which behavior illustrates the working capital risk identified in the article?","choices":["Rejecting orders whenever the customer asks for any payment delay.","Requesting payment on delivery and reducing stock even when sales are lost.","Pricing each sale only after charging for its full working capital requirement.","Offering long payment terms and demanding extra stock to avoid losing sales."],"correct_index":3,"explanation":"Volume incentives can encourage concessions on payment timing and oversized inventories. Both can tie up cash even when reported sales improve. A good sales decision considers the capital needed to support the deal.","set":1},{"id":"fm-s2-q5","session":"2","topic":"China receivables case","question":"A manufacturer blames slow collection in China on local payment customs. What action matches the actual diagnosis in the article?","choices":["Raise finished goods inventories to offset errors in invoice collection.","Correct invoice documentation and pricing that disguised rebates as extended terms.","Leave documentation unchanged and accept longer terms as an unavoidable local rule.","Shorten supplier terms to make customer invoices legally collectible."],"correct_index":1,"explanation":"The task force identified incorrect price positioning and documentation that delayed collection. Fixing those processes released cash without harming market share. The article does not establish a universal rule about customers in China.","set":1},{"id":"fm-s2-q6","session":"2","topic":"Mistake 3","question":"Extra production checks lengthen the cycle, but customers will not pay a higher price. What economic cost should management assess?","choices":["Additional capital tied up in work in progress versus the quality benefit.","A rise in cash collections caused automatically by holding more unfinished goods.","The reduction in capital employed that must follow a longer production cycle.","The disappearance of all warranty costs whenever production takes longer."],"correct_index":0,"explanation":"Quality can reduce defects, but extra process time also ties up capital in work in progress. Management should compare that cost with quality benefits customers value, rather than treating fewer defects as the only objective.","set":1},{"id":"fm-s2-q7","session":"2","topic":"Drive-systems case","question":"The drive systems producer shortened work in progress by 20 days and released €20 million. What management change explains the result in the article?","choices":["Increasing inspection time to maximize defect reduction regardless of cash use.","Reducing production time and quality additions that customers did not value enough.","Maintaining every extra feature and relying only on a higher selling price.","Treating the released inventory capital as a recurring €20 million sales increase."],"correct_index":1,"explanation":"The producer shifted attention toward reducing work in progress and nonvalue adding quality. Cash was released even though its cycle remained longer than peers. Released capital is not the same as additional recurring revenue.","set":1},{"id":"fm-s2-q8","session":"2","topic":"Mistake 4","question":"A supplier demands faster payment. Why should a company not automatically impose the same reduction on its customers?","choices":["Bargaining power and switching costs can differ between the two relationships.","Supplier credit and customer credit are legally the same financing contract.","The company's customer terms must always be longer than its supplier terms.","A customer term change has no effect on demand in a competitive market."],"correct_index":0,"explanation":"Receivables and payables involve separate counterparties and economics. Mirroring terms can lose customers if they can switch easily, even when the company cannot easily switch suppliers.","set":1},{"id":"fm-s2-q9","session":"2","topic":"Machine tools example","question":"In the machine tools example, tighter customer terms release $3.8 million but reduce annual profit by $6 million. What is the article's conclusion for the first year?","choices":["Both amounts recur annually, so the company gains $9.8 million each year.","The $3.8 million release exceeds the profit loss, so cash improves overall.","The profit loss exceeds the cash released, so the response worsens cash overall.","The supplier's $20 million cash demand proves the customer change creates value."],"correct_index":2,"explanation":"The article contrasts a $3.8 million receivables release with a $6 million profit loss and concludes that cash falls in year one. A supplier shock does not make a harmful customer policy economically sound.","set":1},{"id":"fm-s2-q10","session":"2","topic":"Mistake 5, ratios","question":"A CFO increases receivables to improve liquidity ratios while collections become slower. Why can the ratios give a misleading signal?","choices":["Receivables are excluded from both ratios, so their collection timing is irrelevant.","Receivables can raise current and quick ratios while leaving less cash available now.","A higher current ratio measures only the cash generated during the period.","A higher quick ratio proves that every receivable can be collected immediately."],"correct_index":1,"explanation":"Both ratios include receivables, but a larger receivable balance need not mean more usable cash. The article warns against maximizing ratios at the expense of cash generation. Inventory is excluded from the quick ratio.","set":1},{"id":"fm-s2-q11","session":"2","topic":"French consumer goods case","question":"A company reports much higher current and quick ratios, then becomes insolvent six months later. What lesson does the French case support?","choices":["The quick ratio measures future cash flows more directly than a cash budget.","The current ratio can rise only when customers settle invoices faster.","Improved ratios alone do not establish that cash generation and liquidity are healthy.","Improved ratios are sufficient evidence that insolvency cannot occur soon."],"correct_index":2,"explanation":"The reported case shows that ratios can look stronger while the firm still fails. Assess the quality and timing of current assets and cash generation. The case does not prove that every rise in a ratio causes insolvency.","set":2},{"id":"fm-s2-q12","session":"2","topic":"Mistake 6","question":"A company's working capital metrics beat every direct competitor. What further step fits the article's benchmarking advice?","choices":["Reject all benchmarks because comparisons cannot inform a working capital review.","Adopt the industry average as a minimum inventory requirement for every product.","Look for useful comparisons outside the industry and investigate remaining inefficiencies.","Stop reviewing processes because leading the industry establishes the economic optimum."],"correct_index":2,"explanation":"An entire industry can share inefficient practices. Wider comparisons can reveal improvements missed by peer rankings. The article calls benchmarking useful but warns against letting it limit ambition.","set":2},{"id":"fm-s2-q13","session":"2","topic":"Dell case","question":"Why did comparing Dell with retailers lead to a different conclusion than comparing it only with computer makers?","choices":["The wider comparison exposed room to improve despite strong performance among computer makers.","The wider comparison made Dell's reported sales a direct measure of cash collected.","The wider comparison established that computer makers and retailers need identical credit terms.","The wider comparison showed that no working capital measures could be applied to Dell."],"correct_index":0,"explanation":"Dell looked strong relative to computer peers. Retailer comparisons showed that its working capital performance was less exceptional, prompting a review. A benchmark reveals possibilities, not an instruction to copy every policy.","set":2},{"id":"fm-s2-q14","session":"2","topic":"Watch Out, HBR case data","question":"How should a manager use the financial amounts in this May 2009 HBR article when reviewing a company today?","choices":["Use the case amounts as current universal targets because all industries face the same costs.","Assume every case guarantees the same cash release when its policy is copied.","Treat each case amount as inflation adjusted because the article has no valuation date.","Learn the tradeoff logic and check current company data before setting numerical targets."],"correct_index":3,"explanation":"The article reports cases in a specific historical context. They illustrate how capital release, profit and incentives interact. Their amounts are not current company forecasts or universal benchmarks. No assumption of anonymization is needed for this conclusion.","set":2},{"id":"fm-s2-q15","session":"2","topic":"Diagnostic question","question":"A production manager keeps adding costly features that customers will not pay for. Which question best targets the article's incentive diagnosis?","choices":["Which accounting period lets the firm ignore all cash invested in work in progress?","Which exchange rate should replace the inventory carrying cost in the evaluation?","Which rewarded performance measure favors the additions despite their capital cost?","Which competitor has the highest share price irrespective of production practices?"],"correct_index":2,"explanation":"The article asks management to notice when people optimize their own rewarded metrics at the company's expense. Checking what the bonus rewards helps explain the behavior and directs a review of the full economic tradeoff.","set":2},{"id":"fm-s3-q1","session":"3","topic":"DSO/DPO/DI denominators","question":"Using the course's 365 day convention, which pairing of balances and daily flows is correct?","choices":["Receivables and inventory use daily sales, while payables use daily COGS.","Receivables use daily sales, while inventory and payables use daily COGS.","Receivables use daily COGS, while inventory and payables use daily sales.","Receivables and payables use daily sales, while inventory uses daily COGS."],"correct_index":1,"explanation":"DSO divides receivables by daily sales. DI and DPO divide inventory and payables by daily cost of goods sold. Using a sales denominator for a cost based balance distorts the measured period.","set":1},{"id":"fm-s3-q2","session":"3","topic":"Cash cycle formula","question":"Inventory and collection days stay unchanged while supplier payment days increase by ten. What happens to the cash cycle?","choices":["It falls by twenty days because supplier credit reduces both inventory and receivables.","It rises by ten days because every working capital period is added to the cycle.","It falls by ten days because supplier credit finances more of the operating cycle.","It stays unchanged because only inventory and receivables enter the cash cycle."],"correct_index":2,"explanation":"The cash cycle equals DI plus DSO minus DPO. A ten day rise in DPO therefore shortens it by ten days, holding the other periods constant. The operating cycle itself is unchanged.","set":1},{"id":"fm-s3-q3","session":"3","topic":"Worked calculation, DSO","question":"Annual sales are $6,133 million and receivables $764 million. Using 365 days, what is DSO to the nearest whole day?","choices":["59 days, using inventory of $879 million rather than receivables.","8 days, dividing annual sales by receivables without annualizing.","51 days, dividing receivables by daily COGS of $5,464 million.","45 days, dividing receivables by annual sales expressed per day."],"correct_index":3,"explanation":"DSO is 764 divided by (6,133 divided by 365), or 45.47 days. Rounding gives 45 days. The million dollar unit cancels. COGS is not the DSO denominator.","set":1},{"id":"fm-s3-q4","session":"3","topic":"Worked calculation, DI","question":"Inventory is $879 million and annual COGS $5,464 million. Using 365 days, what is DI to the nearest whole day?","choices":["6 days, dividing annual COGS by inventory without annualizing.","46 days, using payables of $682 million rather than inventory.","52 days, dividing inventory by daily sales of $6,133 million.","59 days, dividing inventory by annual COGS expressed per day."],"correct_index":3,"explanation":"DI is 879 divided by (5,464 divided by 365), or 58.72 days. Rounding gives 59 days. Inventory is measured against cost of goods sold, not sales revenue.","set":1},{"id":"fm-s3-q5","session":"3","topic":"Worked calculation, cash cycle","question":"Sales are $6,133 million, COGS $5,464 million, inventory $879 million, receivables $764 million and payables $682 million. Use 365 days and round only the final result. What is the cash cycle?","choices":["58 days, combining the already rounded component periods.","59 days, combining the unrounded periods before rounding.","150 days, adding the payable period rather than subtracting it.","104 days, omitting the payable period from the calculation."],"correct_index":1,"explanation":"The unrounded DI, DSO and DPO are 58.718, 45.469 and 45.558 days. DI plus DSO minus DPO is 58.629, which rounds to 59. Combining rounded components gives 58 instead. The slide's final 59 is consistent with unrounded data.","set":1},{"id":"fm-s3-q6","session":"3","topic":"Walmart vs Boeing","question":"Walmart has roughly 42 inventory days, 4 receivable days and 44 payable days in the example. Why is its cash cycle close to zero?","choices":["Retail receivables must be zero regardless of the balances reported.","Supplier credit covers almost all inventory and receivable periods combined.","The payable period should be added to inventory and receivable periods.","Fast inventory turnover makes supplier payment timing irrelevant."],"correct_index":1,"explanation":"The rounded calculation is 42 plus 4 minus 44, or about 2 days. Fast turnover helps, but supplier financing and short collection times also matter. No single balance alone explains the cycle.","set":1},{"id":"fm-s3-q7","session":"3","topic":"Walmart vs Boeing","question":"Boeing has about 196 inventory days, 36 receivable days and 53 payable days. Which interpretation fits these figures?","choices":["A positive cash cycle proves the company has negative accounting profit.","The payable period dominates because it adds 53 days to the operating cycle.","The large inventory period dominates a cash cycle of roughly 179 days.","The collection period eliminates the financing need created by inventory."],"correct_index":2,"explanation":"The approximate cycle is 196 plus 36 minus 53, or 179 days. Inventory is the largest component. Cash cycle figures do not alone determine accounting profitability.","set":1},{"id":"fm-s3-q8","session":"3","topic":"Inventory trade-off","question":"Annual demand stays fixed and a firm places larger, less frequent orders. What happens to carrying cost in the course model?","choices":["It rises because average inventory and capital tied up increase.","It disappears because larger orders always earn bulk discounts.","It falls because the firm places fewer purchase orders each year.","It stays unchanged because carrying cost depends only on sales."],"correct_index":0,"explanation":"The carrying cost curve rises with order size. Larger orders increase average inventory, raising storage and opportunity costs. Fewer orders reduce ordering cost, which is a different component.","set":1},{"id":"fm-s3-q9","session":"3","topic":"Inventory trade-off","question":"Demand and cost per order stay fixed. A firm doubles order size and places half as many orders. What happens to annual ordering cost?","choices":["It falls to zero because larger orders remove all handling costs.","It falls by half because there are half as many ordering events.","It doubles because each order contains twice as many units.","It stays constant because the annual quantity purchased is unchanged."],"correct_index":1,"explanation":"With fixed cost per order, annual ordering cost depends on the number of orders. Half as many orders means half the ordering cost. Total inventory cost need not halve because carrying cost rises.","set":1},{"id":"fm-s3-q10","session":"3","topic":"Reorder point","question":"A firm orders a fixed quantity whenever stock falls to a specified minimum. What is that minimum?","choices":["The maximum stock allowed immediately after every delivery.","The supplier payment date that determines the payable period.","The selling price needed to cover annual carrying costs.","The reorder point that triggers the next replenishment order."],"correct_index":3,"explanation":"The reorder point specifies when an order is triggered. The predetermined order quantity specifies how much to order. These are separate parts of the inventory policy.","set":1},{"id":"fm-s3-q11","session":"3","topic":"Inventory scaling","question":"Sales rise by 20%. Which inventory pattern fits the scaling relationship described in the slides?","choices":["Optimal inventory falls to zero as growth removes buffer needs.","Optimal inventory rises by more than 20% in every case.","Optimal inventory rises by exactly 20% in every case.","Optimal inventory rises, but by less than 20%."],"correct_index":3,"explanation":"The slides state that optimal inventory increases less than proportionately with sales. This is the taught economy of scale relationship, not a guarantee about every firm's observed inventory regardless of other changes.","set":2},{"id":"fm-s3-q12","session":"3","topic":"JIT","question":"Which setting best fits the slides' conditions for just in time inventory with little safety stock?","choices":["A supplier network whose delivery timing changes unpredictably.","An erratic production flow with frequent unexpected input shortages.","A steady and predictable production flow with limited buffer needs.","An unforecastable seasonal surge requiring immediate delivery."],"correct_index":2,"explanation":"The course describes just in time as suitable when production is steady and predictable. Unpredictable flows make reducing safety inventory riskier. Product category alone does not establish suitability.","set":2},{"id":"fm-s3-q13","session":"3","topic":"Receivables management structure","question":"A manager reviews payment deadlines, repayment likelihood, credit limits and overdue invoices. Which mapping fits the framework?","choices":["Terms of sale, credit analysis, credit decision and collection policy.","Credit analysis, collection policy, terms of sale and credit decision.","Collection policy, credit decision, credit analysis and terms of sale.","Credit decision, terms of sale, collection policy and credit analysis."],"correct_index":0,"explanation":"Terms of sale set payment conditions. Credit analysis assesses who is likely to pay. The credit decision sets credit extended. Collection policy governs recovery after payment becomes due.","set":2},{"id":"fm-s3-q14","session":"3","topic":"Credit decision","question":"In the single order model, a seller refuses credit and makes no sale. What is incremental expected gain relative to not taking the order?","choices":["Zero, since neither the order's margin nor its production cost arises.","A loss equal to production cost, although the order is not undertaken.","Sales margin, since costs disappear while customer revenue remains.","Full sales revenue, since refusing credit avoids the risk of default."],"correct_index":0,"explanation":"The slide's refusal branch has a payoff of zero. This is an incremental order decision, not a claim that the firm has no existing costs or no possible future customer value.","set":2},{"id":"fm-s3-q15","session":"3","topic":"Credit decision formula","question":"A credit sale brings $100 if paid and costs $70 in either outcome. Payment probability is 80%, default recovery is zero and discounting is ignored. What is expected gain?","choices":["$24, weighing the $30 margin but ignoring default losses.","$86, subtracting only the probability weighted default cost from certain revenue.","$10, weighing a $30 profit against a $70 default loss.","$30, treating the promised customer payment as certain."],"correct_index":2,"explanation":"Expected gain is 0.8 times 30 minus 0.2 times 70, or $10. Equivalently, expected revenue is $80 and cost is $70. The default branch loses the cost rather than yielding zero profit.","set":2},{"id":"fm-s3-q16","session":"3","topic":"Credit allocation principles","question":"One policy avoids all defaults but rejects profitable risky orders. Another permits some defaults and has higher expected present value. Which objective fits the slides?","choices":["Maximize expected present value rather than minimize default counts.","Give all customers the same credit limit instead of analyzing risk.","Maximize sales even when their expected present value is negative.","Minimize default counts even when expected present value is lower."],"correct_index":0,"explanation":"The credit manager weighs payment gains against default losses to maximize present value. Defaults are a cost to assess, not an outcome to eliminate regardless of sacrificed profitable business.","set":2},{"id":"fm-s45-q1","session":"4-5","topic":"Types of financial risk","question":"An A2A style financing agreement becomes more costly if sustainability targets are missed. Which illustrated risk does this most directly represent?","choices":["Rating downgrade risk from changes in the firm's published credit category.","Interest rate risk from changes in benchmark borrowing rates.","Sustainability covenant risk from failing the specified performance targets.","Liquidity risk from an obligation to settle every invoice immediately."],"correct_index":2,"explanation":"The A2A exhibit lists failure to meet sustainability performance targets or allocate funds to eligible investments under sustainability covenant risks. It separately lists liquidity, rating downgrade and interest rate risks.","set":1},{"id":"fm-s45-q2","session":"4-5","topic":"FX exposure types","question":"A European company has issued an invoice payable in pounds in three months. The pound's euro value changes before collection. Which exposure is directly involved?","choices":["Translation exposure from consolidating a foreign subsidiary's accounts.","Operating exposure from future sales that have not yet been contracted.","Interest rate exposure from changes in the firm's domestic borrowing rate.","Transaction exposure on an existing contractual foreign currency receivable."],"correct_index":3,"explanation":"Transaction exposure concerns settling existing foreign currency obligations. The invoice amount is already fixed, while its euro value can change before collection.","set":1},{"id":"fm-s45-q3","session":"4-5","topic":"FX exposure types","question":"Reported euro equity changes when a group translates foreign subsidiary accounts, with no cash conversion or settlement. Which exposure is this?","choices":["Transaction exposure from collecting an existing foreign currency invoice.","Operating exposure from changes in future demand for exported products.","Liquidity exposure from an immediate payment to a foreign supplier.","Translation exposure from consolidating accounts in different currencies."],"correct_index":3,"explanation":"Translation exposure affects consolidated accounting amounts. Translation itself does not require cash settlement. This does not mean reported amounts can never have indirect contractual consequences.","set":1},{"id":"fm-s45-q4","session":"4-5","topic":"FX exposure types","question":"A stronger home currency makes exports less competitive and changes cash flows from future orders not yet contracted. Which exposure is this?","choices":["Credit exposure confined to failure to pay an existing customer invoice.","Operating exposure through competitiveness and expected future cash flows.","Transaction exposure confined to an already fixed foreign currency invoice.","Translation exposure confined to converting subsidiary accounts for consolidation."],"correct_index":1,"explanation":"Operating or economic exposure concerns future cash flows affected by competitiveness. Transaction exposure concerns existing contracts, while translation exposure concerns accounting consolidation.","set":1},{"id":"fm-s45-q5","session":"4-5","topic":"What hedging does","question":"A hedge narrows the possible home currency receipts from a fixed foreign invoice. Which conclusion fits the course's risk definition?","choices":["Every business risk disappears once the foreign currency invoice is hedged.","Cash flow variability falls without a guaranteed increase in expected receipts.","Customer default becomes impossible because the exchange rate is hedged.","Expected receipts rise because reducing variance always creates cash income."],"correct_index":1,"explanation":"The slides define hedging as reducing variability around expected cash flows. This need not improve expected receipts. An FX hedge does not by itself eliminate customer credit risk or other business risks.","set":1},{"id":"fm-s45-q6","session":"4-5","topic":"Forward positions","question":"A US importer must pay £2 million in six months and wants a fixed dollar cost. Which forward position matches the payable?","choices":["Buy £2 million forward for dollars at the agreed rate and maturity.","Sell £2 million forward for dollars at the agreed rate and maturity.","Buy dollars forward using the pounds due to be paid to the supplier.","Sell pounds forward only if their dollar price rises before settlement."],"correct_index":0,"explanation":"A payable requires the firm to obtain the foreign currency. A long forward fixes its purchase price. A short pound forward adds an obligation to deliver pounds rather than providing the pounds needed.","set":1},{"id":"fm-s45-q7","session":"4-5","topic":"Forward positions","question":"A US exporter will receive £2 million in six months and wants fixed dollar proceeds. Which forward position matches the receivable?","choices":["Buy pounds forward only if their dollar price falls before collection.","Buy £2 million forward for dollars at the agreed rate and maturity.","Sell £2 million forward for dollars at the agreed rate and maturity.","Sell dollars forward for pounds to enlarge the pound balance at collection."],"correct_index":2,"explanation":"The receivable supplies pounds the exporter will sell for dollars. A short pound forward fixes the sale rate. A long pound forward would add pounds rather than offset the receipt.","set":1},{"id":"fm-s45-q8","session":"4-5","topic":"Importer/exporter options rule","question":"An importer owes pounds and wants protection if pounds strengthen while benefiting if they weaken. Which purchased option fits?","choices":["A call on pounds, giving a right to buy pounds at the strike.","A sold call on pounds, creating an obligation to supply pounds.","A sold put on pounds, creating an obligation to buy more pounds.","A put on pounds, giving a right to sell pounds at the strike."],"correct_index":0,"explanation":"A call caps the foreign currency purchase price before premium costs. If pounds become cheaper, the importer can buy spot and let the call expire. The premium remains a cost in either case.","set":1},{"id":"fm-s45-q9","session":"4-5","topic":"Importer/exporter options rule","question":"An exporter has a pound receivable and wants a minimum dollar value while retaining gains from a stronger pound. Which option fits?","choices":["A sold call on pounds, creating an obligation to sell at the strike.","A sold put on pounds, creating an obligation to buy at the strike.","A purchased call on pounds, giving a right to buy at the strike.","A purchased put on pounds, giving a right to sell at the strike."],"correct_index":3,"explanation":"A purchased put floors the currency sale price before premium costs. If spot is higher, the exporter can sell spot instead. A purchased call protects a buyer of pounds rather than this seller.","set":1},{"id":"fm-s45-q10","session":"4-5","topic":"Woolens importer example","question":"An importer hedges a £100 million payable at $1.50 per pound. At maturity spot is $1.20 per pound. Ignoring fees, what is its hedged dollar cost?","choices":["$90 million, retaining the spot saving despite the forward obligation.","$150 million, while an unhedged spot purchase would cost $120 million.","$180 million, adding the forward loss to the contracted cost again.","$120 million, since a forward buyer can choose the cheaper spot rate."],"correct_index":1,"explanation":"The forward fixes the purchase at $150 million. Relative to spot, its $30 million loss offsets the $30 million saving on the underlying payable. The favorable currency benefit is removed along with adverse rate risk.","set":1},{"id":"fm-s45-q11","session":"4-5","topic":"Break-even spot rate, receivable","question":"A receivable is protected by a put with strike equal to the forward rate F. P is its positive premium per unit at settlement value. When does the unexercised put strategy match forward proceeds?","choices":["At F, because premiums apply only when options are exercised.","At F minus P, where spot proceeds plus P equal F.","At F plus P, where spot proceeds less P equal F.","At P, because the forward rate does not enter the comparison."],"correct_index":2,"explanation":"With the put unexercised, net proceeds are spot minus P per unit. Equating that with F gives spot equal to F plus P. Strike and premium timing matter when applying this comparison.","set":2},{"id":"fm-s45-q12","session":"4-5","topic":"Break-even spot rate, payable","question":"A payable's call strike equals forward rate F. P is its positive premium per unit at settlement value. When does the unexercised call strategy match forward cost?","choices":["At F plus P, where spot purchase cost less P equals F.","At F minus P, where spot purchase cost plus P equals F.","At P, because only the premium determines currency purchase cost.","At F, because an unexercised option's premium is refunded."],"correct_index":1,"explanation":"The unexercised call strategy costs spot plus P per unit. Equating that with F gives spot equal to F minus P. Premium timing must be consistent with the forward's settlement cost.","set":2},{"id":"fm-s45-q13","session":"4-5","topic":"Boeing receivable exercise","question":"Boeing sells £10 million forward at $1.46 per pound or buys a put with the same strike and a $0.02 premium. Ignoring premium financing, when do net proceeds match?","choices":["At $1.46 per pound, because identical strikes cancel the premium.","At $1.44 per pound, with both giving $14.4 million.","At $1.50 per pound, because the premium is charged twice.","At $1.48 per pound, with both giving $14.6 million."],"correct_index":3,"explanation":"The forward gives $14.6 million. Above the strike, the put expires and net proceeds are (spot minus $0.02) times £10 million. At $1.48 this equals $14.6 million, matching the graph.","set":2},{"id":"fm-s45-q14","session":"4-5","topic":"Over-hedging definition","question":"A firm sells $1 million forward but its customer receipt is only $600,000. What remains after using that receipt?","choices":["A $400,000 forward delivery obligation unsupported by the receipt.","A $400,000 customer receivable created by the forward contract.","A $600,000 shortfall because receipts cannot be used for delivery.","No exposure since a forward shrinks automatically to the invoice amount."],"correct_index":0,"explanation":"The hedge exceeds the underlying receipt by $400,000. The excess is an uncovered currency position, not a hedge of cash earned from the customer. It can gain or lose as spot changes.","set":2},{"id":"fm-s45-q15","session":"4-5","topic":"Over-hedging worked example","question":"A firm sells $100 forward at 1.3 dollars per euro but receives only $50. Settlement spot is 1 dollar per euro. What loss arises on the unsupported $50 portion alone?","choices":["About €50, ignoring euros received when purchased dollars are delivered.","About €11.54, paying €50 spot and receiving €38.46 forward.","About €15, multiplying dollars by the indirect quote to calculate proceeds.","About €38.46, treating all forward proceeds as a loss."],"correct_index":1,"explanation":"The missing $50 costs €50 spot. Delivering it forward returns 50 divided by 1.3, or €38.46. The loss is €11.54. This isolates the uncovered position from lower sales and other operating costs.","set":2},{"id":"fm-s45-q16","session":"4-5","topic":"Hedging policy design","question":"A company hedges forecast exports before invoices exist. Which pair of decisions addresses the quantity risk discussed in the slides?","choices":["Which bank has the lowest fee and whether all forecasts must be fully hedged.","Which reporting currency to adopt and which depreciation method to use.","Whether to forecast sales and whether to omit exchange rates from budgets.","When exposure is certain enough to hedge and what forecast share to cover."],"correct_index":3,"explanation":"The slides ask when to begin hedging and how much to hedge. Early protection can leave an unsupported contract if forecast sales fall short. Timing and coverage should reflect exposure certainty.","set":2},{"id":"fm-s45-q17","session":"4-5","topic":"Forward hedge and expected outcome","question":"A matched forward protects an exporter from a weaker foreign currency. If that currency instead strengthens, what tradeoff does the exporter face?","choices":["It cancels the forward without cost and takes the better spot conversion.","It receives a guaranteed increase in expected proceeds since no premium was paid.","It receives the contracted rate and gives up the better spot conversion.","It receives forward proceeds and the full spot gain on the same receipt."],"correct_index":2,"explanation":"A forward binds both sides at the agreed rate. It removes rate uncertainty on a matched amount, but also removes benefits from favorable spot moves. It does not guarantee improved expected value.","set":2},{"id":"fm-s45-q18","session":"4-5","topic":"Direct quotation","question":"A euro based investor sees a quote of 1.25 dollars per euro. What is the corresponding direct quotation?","choices":["€0. 80 per dollar, using the reciprocal of 1. 25.","€0. 25 per dollar, subtracting one from the quote.","€2. 25 per dollar, adding one to the quote.","€1. 25 per dollar, retaining the same number."],"correct_index":0,"explanation":"A direct quote gives home currency per foreign currency unit. The reciprocal of 1.25 dollars per euro is 0.80 euros per dollar. Reversing the unit without changing the number is incorrect.","set":2},{"id":"fm-s45-q19","session":"4-5","topic":"Forward premium/discount","question":"A currency is quoted in dollars per unit, and its forward rate exceeds spot. What follows from the premium calculation alone?","choices":["The currency must appreciate by that premium before maturity.","The currency trades at a discount since higher rates always mean weakness.","The currency trades at a forward premium in this quote convention.","The currency's spot rate is certain to equal forward at settlement."],"correct_index":2,"explanation":"A positive forward minus spot difference produces a positive annualized premium. This describes quoted prices, not a guaranteed future spot rate or direction of movement.","set":2},{"id":"fm-s45-q20","session":"4-5","topic":"Recap comparison","question":"A European exporter has a certain USD 75 receivable. At maturity, spot can be USD 1.32 per EUR or USD 1.06 per EUR. A forward fixes USD 1.15 per EUR on the full receipt. Ignore all fees. What does comparing the euro receipts show?","choices":["The forward trades currency upside and downside for a fixed receipt.","The unhedged position removes rate risk since no premium is paid.","An option must beat both strategies since exercise is optional.","The forward gives a higher receipt in every possible spot scenario."],"correct_index":0,"explanation":"Without a hedge, receipts are 75/1.32 = EUR 56.82 or 75/1.06 = EUR 70.75. The forward fixes 75/1.15 = EUR 65.22 in either state. It removes the exchange rate uncertainty by giving up favorable movements as well as protection against unfavorable ones.","set":2},{"id":"fm-s7-q1","session":"7","topic":"Cost of capital definition","question":"A firm uses only its loan interest rate to evaluate an investment funded with debt and equity. What is missing from that financing hurdle?","choices":["Historical stock price growth as a replacement for every financing cost.","Revenue growth as an identical measure of the required financing return.","Principal repayment as an addition to the annual interest percentage.","The return required by shareholders as well as the return required by lenders."],"correct_index":3,"explanation":"Cost of capital is the minimum return satisfying debt and equity investors. A loan rate captures only debt. The course ties required returns to systematic risk rather than treating all financing as borrowing.","set":1},{"id":"fm-s7-q2","session":"7","topic":"WACC","question":"Market value debt is 40% of financing, equity 60%, debt cost 5%, equity cost 10% and corporate tax 25%. Under the course formula, what is WACC?","choices":["6.25%, swapping the debt and equity financing weights.","7.5%, applying the tax adjustment to debt but not equity.","8.0%, omitting the tax adjustment on debt interest.","6.0%, applying the tax adjustment to both debt and equity."],"correct_index":1,"explanation":"Debt contributes 5% times 0.75 times 0.40, or 1.5 percentage points. Equity contributes 10% times 0.60, or 6 points. WACC is 7.5%. This formula assumes the stated debt tax benefit is applicable.","set":1},{"id":"fm-s7-q3","session":"7","topic":"Risk-free rate","question":"A certain cash flow arrives in euros in five years. Which instrument best fits the slides' ideal risk free rate conditions?","choices":["A three month euro Treasury bill reinvested repeatedly until year five.","A five year default free dollar bond used without currency adjustment.","A default free euro zero coupon security maturing in five years.","A five year euro corporate zero coupon bond with material default risk."],"correct_index":2,"explanation":"Matching maturity avoids reinvestment uncertainty, and a default free issuer avoids credit risk. The rate must also fit the cash flow currency. Short bills create reinvestment risk, while a dollar instrument creates a currency mismatch.","set":1},{"id":"fm-s7-q4","session":"7","topic":"MRP approaches","question":"A survey estimate of the market risk premium changes sharply between responses. Which concern matches the limitations in the slides?","choices":["Survey estimates equal the premium implied by market prices by construction.","Survey answers eliminate the need to assess respondent expectations or horizons.","Surveying investors automatically corrects bias in every historical return database.","Survey expectations can be volatile and need not stay within plausible bounds."],"correct_index":3,"explanation":"The slides warn that surveyed expectations can be volatile, short horizon and unconstrained in plausibility. Surveys are distinct from premiums derived directly from prices and do not correct historical databases by themselves.","set":1},{"id":"fm-s7-q5","session":"7","topic":"Historical MRP choices","question":"Following the course's historical MRP convention, which average is associated with serially correlated returns and a longer term view?","choices":["The geometric average rather than the next year arithmetic convention.","The median premium because the slides equate it with compounded returns.","The arithmetic average because it is assigned to every horizon in the slides.","The largest annual premium because longer horizons require the strongest year."],"correct_index":0,"explanation":"The slide associates geometric averaging with serial correlation and a long term view. It associates arithmetic averaging with uncorrelated returns and a next year estimate. This tests the stated course convention, not a universal statistical theorem.","set":1},{"id":"fm-s7-q6","session":"7","topic":"Beta regression","question":"A regression of stock on market returns has intercept 0.002, slope 1.3 and R squared 0.45. Which figure is estimated beta?","choices":["1.3, the slope measuring sensitivity to market returns.","1.75, the sum of slope and R squared used as sensitivity.","0.45, the R squared used as the sensitivity coefficient.","0.002, the intercept measuring sensitivity to market returns."],"correct_index":0,"explanation":"In Rj equals a plus b times Rm, beta is b. The intercept and R squared describe other regression features and do not replace the slope. This sensitivity estimate is not proof of a causal relationship.","set":1},{"id":"fm-s7-q7","session":"7","topic":"Beta estimation choices","question":"An analyst switches to daily returns for a thinly traded stock solely to get more observations. Which issue should be checked?","choices":["The larger sample eliminates all bias from trading related noise.","Illiquidity and trading related noise can bias beta despite the larger sample.","Daily returns make dividends unnecessary for both stock and market.","Daily returns prevent changes in business risk during the estimation period."],"correct_index":1,"explanation":"Shorter intervals produce more observations but can introduce trading related noise. The practical summary warns of liquidity bias. More observations alone do not ensure reliability, and total returns should still include dividends.","set":1},{"id":"fm-s7-q8","session":"7","topic":"Beta determinants","question":"Two otherwise similar firms sell equally cyclical products. One has a higher fixed cost share. What fits the operating leverage discussion?","choices":["The firm with more fixed costs is expected to have higher business beta.","The firm with more fixed costs is expected to have lower business beta.","Only debt can affect beta, so fixed cost structure is irrelevant.","The firms must have identical betas because costs cannot affect business risk."],"correct_index":0,"explanation":"A larger fixed cost share is greater operating leverage. The slides associate it with higher firm beta, other things equal. Financial leverage is a separate amplifier of equity risk.","set":1},{"id":"fm-s7-q9","session":"7","topic":"Levered vs unlevered beta","question":"Using the course formula with negligible debt beta, unlevered beta is 0.8, market D/E is 0.5 and tax is 25%. What is levered beta?","choices":["0.675, subtracting the tax rate times D/E from 0.8.","0.58, dividing 0.8 by one plus 0.75 times 0.5.","1.10, multiplying 0.8 by one plus 0.75 times 0.5.","1.20, multiplying 0.8 by one plus 0.5 without tax adjustment."],"correct_index":2,"explanation":"The leverage factor is 1 plus (1 minus 0.25) times 0.5, or 1.375. Multiplying 0.8 by 1.375 gives 1.10. Market values and the negligible debt beta assumption define the version of the formula used here.","set":1},{"id":"fm-s7-q10","session":"7","topic":"Cost of debt estimation","question":"A firm has no public rating. EBIT is €12 million and annual interest expense €3 million. What input fits the synthetic rating method?","choices":["A debt cost of 4%, treating the coverage ratio directly as a borrowing rate.","A market risk premium of €9 million, subtracting interest expense from EBIT.","An interest coverage ratio of 0.25, dividing interest expense by EBIT.","An interest coverage ratio of 4, used to infer a rating and default spread."],"correct_index":3,"explanation":"ICR is EBIT divided by interest expense, here 12 divided by 3 equals 4. A synthetic rating maps coverage to a credit category and default spread. Coverage itself is dimensionless, not a borrowing rate.","set":1},{"id":"fm-s6-q1","session":"6","topic":"Debt vs equity","question":"According to the slides' debt-versus-equity comparison, which set of characteristics belongs to debt?","choices":["A fixed, tax-deductible claim, high priority in financial trouble, no management control.","A residual claim, lowest priority, with management control.","An infinite-life claim that is not tax deductible and carries voting rights.","A claim paid only after every other claim, with full control over decisions."],"correct_index":0,"explanation":"Slides 2-3: debt is a fixed claim, high priority, tax deductible, no control, finite life; equity is a residual claim, low priority, with control, infinite life, not tax deductible.","set":1},{"id":"fm-s6-q2","session":"6","topic":"Three debt strategies","question":"A borrower needs $1 million for three years. Which strategy makes the interest rate certain for the full three years?","choices":["Borrowing for three years at SOFR + 2%, reset annually.","Borrowing for three years at a fixed rate.","Borrowing for one year at a fixed rate and renewing each year.","Borrowing for one year at a floating rate, then fixing at renewal."],"correct_index":1,"explanation":"Strategy 1 locks the rate for the whole horizon; strategies 2 and 3 reprice every year, so only their first year's rate is certain.","set":1},{"id":"fm-s6-q3","session":"6","topic":"Repricing vs credit risk","question":"Among the three debt strategies, why does rolling over a one-year fixed-rate loan annually carry the most credit-spread risk?","choices":["The rate locks for three years, freezing the original spread and the loan terms.","SOFR resets each year but the spread stays fixed, so credit risk disappears.","The loan is renegotiated each year, so the lender can reprice rate and terms on creditworthiness.","Annual renewal removes the lender's ability to reprice, as the contract fixes terms."],"correct_index":2,"explanation":"Strategy 3 carries little repricing risk (fixed each year) but the most credit risk: both rate and terms are renegotiated annually. Strategy 2 fixes only the spread; strategy 1 fixes everything.","set":1},{"id":"fm-s6-q4","session":"6","topic":"Credit spreads","question":"A chart of US corporate credit spreads plots spreads by maturity for each rating category. What does it show?","choices":["Spreads fall with maturity for every rating category.","Speculative-grade borrowers pay roughly the same spread as AAA borrowers.","Spreads depend only on maturity, not on credit quality.","Spreads rise with maturity and jump sharply once a borrower falls below investment grade."],"correct_index":3,"explanation":"The longer the maturity, the wider the spread, and the increase is much steeper below investment grade.","set":1},{"id":"fm-s6-q5","session":"6","topic":"All-in cost","question":"How is the all-in cost (AIC) of a floating-rate loan computed?","choices":["The IRR of the full loan cash flows, including the up-front fee and principal repayment.","The reference rate plus the credit spread for the first year, ignoring later resets.","The up-front fee divided by the notional amount, added to the quoted rate.","The average SOFR over the maturity of the loan, plus the contractual spread."],"correct_index":0,"explanation":"AIC is the IRR of proceeds, interest payments and principal repayment; the fee reduces year-0 proceeds, so the AIC exceeds the quoted rate.","set":1},{"id":"fm-s6-q6","session":"6","topic":"Loan proceeds","question":"A company takes an $8,000,000 three-year floating-rate loan with a 2% up-front fee on the notional. What are its year-0 loan proceeds?","choices":["$8,000,000","$7,840,000","$8,160,000","$7,680,000"],"correct_index":1,"explanation":"Proceeds = notional minus the fee: 8,000,000 x (1 - 0.02) = $7,840,000.","set":1},{"id":"fm-s6-q7","session":"6","topic":"Loan AIC example","question":"A three-year floating-rate loan has a notional of $8,000,000, SOFR flat at 5%, a 1.5% spread and a 1.5% up-front fee. What is its all-in cost?","choices":["Exactly 6.50%","About 5.00%","About 7.07%","About 8.52%"],"correct_index":2,"explanation":"The quoted rate is 6.50%, but the 1.5% fee reduces proceeds to 7,880,000, pushing the IRR of the cash flows to about 7.072%.","set":1},{"id":"fm-s6-q8","session":"6","topic":"AIC sensitivity","question":"A three-year floating-rate loan has a notional of $8,000,000, a 1.5% spread and a 1.5% up-front fee. SOFR starts at 5% and rises by 25 bps each year (5.25% in year 1, 5.50% in year 2, 5.75% in year 3). What is the loan's all-in cost?","choices":["7.072%","6.578%","6.500%","7.565%"],"correct_index":3,"explanation":"Interest steps up to 6.75%, 7.00% and 7.25% on the $8,000,000 notional; year-0 proceeds are 7,880,000 after the fee. The IRR of the full cash flow stream gives an AIC of about 7.565% (versus 7.072% with SOFR flat).","set":1},{"id":"fm-s6-q9","session":"6","topic":"Three tools","question":"Which three tools do the slides list for managing interest rate risk?","choices":["Interest rate swap, forward rate agreement, interest rate option.","Interest rate swap, money market hedge, invoice factoring.","Forward rate agreement, currency future, credit default swap.","Interest rate option, operating hedge, back-to-back loan."],"correct_index":0,"explanation":"The three tools are the interest rate swap, the forward rate agreement and the interest rate option; the session develops the swap.","set":1},{"id":"fm-s6-q10","session":"6","topic":"Swap net interest","question":"Firm A pays SOFR + 1.5% on its loan and enters a swap to pay fixed 5.75% and receive SOFR. What is its net interest rate?","choices":["5.75%","7.25%","4.25%","8.75%"],"correct_index":1,"explanation":"Net rate = fixed leg + credit spread = 5.75% + 1.50% = 7.25%; the SOFR legs cancel.","set":1},{"id":"fm-s6-q11","session":"6","topic":"Loan plus swap table","question":"A company takes a $10,000,000 three-year floating-rate loan at SOFR + 1.5% with a 1.5% up-front fee and enters an interest rate swap paying a 5.75% fixed leg and receiving SOFR. The combined loan-plus-swap all-in cost is:","choices":["7.250%","7.072%","7.830%","6.500%"],"correct_index":2,"explanation":"The fee lowers proceeds to 9,850,000 and net interest is 725,000 a year, so the IRR of the combined cash flows is about 7.83%, above the 7.25% flat net rate.","set":2},{"id":"fm-s6-q12","session":"6","topic":"MedStat case","question":"MedStat pays LIBOR + 1.25% on its $40 million loan and swaps to receive LIBOR against paying a 3.85% fixed rate. Its resulting fixed cost is:","choices":["3.85%","1.25%","2.60%","5.10%"],"correct_index":3,"explanation":"Floating legs cancel: the company ends up paying 3.85% fixed plus its 1.25% credit spread, i.e. 5.10%.","set":2},{"id":"fm-s6-q13","session":"6","topic":"Swap and debt structure","question":"According to the slides, how do A/AA companies such as Walmart or IBM often use the plain-vanilla swap market?","choices":["They issue floating-rate debt and swap all of it into fixed.","They issue fixed-rate debt and swap selective amounts into floating to reach their target mix.","They avoid swaps because of their credit quality.","They swap floating into fixed, which raises their debt cost."],"correct_index":1,"explanation":"High-quality firms use swaps to manage their debt structure: issue fixed, then swap part into floating (swap-and-distribute) to hit the desired fixed/floating mix.","set":2},{"id":"fm-s6-q14","session":"6","topic":"Quality spread differential","question":"What is the necessary condition for a fixed-for-floating swap to benefit both counterparties, as the slides put it?","choices":["An inverted yield curve at the swap's maturity.","Identical credit ratings for both counterparties.","A positive quality spread differential between the two borrowers.","A negative credit spread on the floating leg."],"correct_index":2,"explanation":"Swap gains rest on comparative advantage: the quality spread differential must be positive for both sides to come out ahead.","set":2},{"id":"fm-s8-q1","session":"8","topic":"WACC and enterprise value","question":"Under the DCF approach, holding operating cash flows constant, enterprise value is maximized exactly when:","choices":["the cost of debt is minimized.","leverage is maximized.","the WACC is minimized.","the cost of equity equals the cost of debt."],"correct_index":2,"explanation":"With cash flows fixed, minimizing the WACC maximizes enterprise value; the optimal capital structure is the one that minimizes WACC.","set":1},{"id":"fm-s8-q2","session":"8","topic":"WACC formula","question":"Which expression is the WACC as decomposed on the slides?","choices":["D/(D+E) x ke + E/(D+E) x kd x (1 - t)","ke + kd x (1 - t)","E/(D+E) x kd x (1 - t) + D/(D+E) x ke","E/(D+E) x ke + D/(D+E) x kd x (1 - t)"],"correct_index":3,"explanation":"WACC weights ke by the equity share and the after-tax cost of debt kd(1-t) by the debt share.","set":1},{"id":"fm-s8-q3","session":"8","topic":"Cost of debt","question":"As leverage rises, why does the cost of debt kd increase?","choices":["Higher default probability leads lenders to demand a wider credit spread.","The tax shield makes debt progressively more expensive.","Shareholders require a higher dividend yield.","Interest stops being tax deductible at any leverage."],"correct_index":0,"explanation":"More debt raises the probability of default, so banks and bondholders widen the credit spread they require, pushing kd up.","set":1},{"id":"fm-s8-q4","session":"8","topic":"Cost of equity","question":"According to the slides, leverage raises the cost of equity because:","choices":["dividends must grow in line with debt, so equity holders demand a higher return.","financial risk shifts to shareholders and the levered beta rises with D/E, lifting ke.","the tax shield reduces the value of equity, so shareholders require compensation.","the levered beta falls as D/E rises, but the market risk premium rises faster."],"correct_index":1,"explanation":"Debt concentrates risk on shareholders; the levered beta beta_L = beta_U[1 + (1-t)D/E] rises with leverage, and ke = rf + beta_L x MRP follows.","set":1},{"id":"fm-s8-q5","session":"8","topic":"U-shaped WACC","question":"Why is the WACC curve U-shaped rather than monotonic?","choices":["kd falls faster than ke rises at every leverage level, so WACC keeps falling.","The tax rate falls as leverage rises, so the shield is progressively lost.","The tax shield pulls WACC down at first, then distress and agency costs push it up.","Equity becomes cheaper than debt beyond the optimal D/E, which reverses the curve."],"correct_index":2,"explanation":"Three forces act at once; the net effect is a U-shaped WACC, minimized at the optimal capital structure D/E*.","set":1},{"id":"fm-s8-q6","session":"8","topic":"Optimal leverage","question":"At the optimal leverage D/E* on the slides' WACC curve:","choices":["the interest tax shield is exactly zero.","distress and agency costs are minimized.","kd equals ke.","WACC is minimized and enterprise value is maximized."],"correct_index":3,"explanation":"D/E* is where the marginal benefit of the tax shield stops offsetting the rising costs of debt; WACC is at its minimum, so enterprise value is at its maximum.","set":1},{"id":"fm-s8-q7","session":"8","topic":"Capital structure in practice","question":"What do firms actually do, according to the 'Capital Structure in the Real World' slide?","choices":["They target a credit rating such as BBB and keep leverage within a range.","They compute the optimal D/E once and hold it exactly through the cycle.","They always minimize today's WACC regardless of risk to the credit rating.","They avoid debt entirely to preserve flexibility for acquisitions and downturns."],"correct_index":0,"explanation":"In practice firms optimize risk, not just the current WACC: they pick a rating target (e.g. BBB) and stay within a leverage range, accepting suboptimal points inside it.","set":1},{"id":"fm-s8-q8","session":"8","topic":"Real-world frictions","question":"Which of these is NOT one of the real-world frictions the slides list?","choices":["Market timing","Interest tax shields","Financial flexibility","Ratings and covenants"],"correct_index":1,"explanation":"The frictions are market timing, financial flexibility, ratings and covenants, and management incentives; the tax shield is a benefit of debt, not a friction.","set":1},{"id":"fm-s8-q9","session":"8","topic":"Life cycle and LBO","question":"At which life-cycle stage does the leveraged buyout belong, and why?","choices":["Start-up, because uncertainty is highest there.","Decline, because cash flows are falling.","Maturity, because stable predictable cash flows can safely carry high debt.","Development, because revenue is scaling."],"correct_index":2,"explanation":"As cash flows become stable and predictable in maturity, debt capacity opens: the cost of financial distress falls and leverage is safe - the LBO stage.","set":1},{"id":"fm-s8-q10","session":"8","topic":"Aggressive leverage","question":"A firm with NFP/EBITDA above 3.0x and D/E above its industry average sits in which debt strategy?","choices":["Low leverage.","Ordinary debt.","Debt for growth.","Aggressive leverage - the LBO zone."],"correct_index":3,"explanation":"The aggressive-leverage quadrant (LBO funds, mature firms, stable cash flows) combines NFP/EBITDA above 3.0x with D/E above the industry average.","set":1},{"id":"fm-s8-q11","session":"8","topic":"Low leverage","question":"Why do Armani, Apple and Microsoft carry little or no debt, according to the slides?","choices":["Volatile cash flows, wish for flexibility and signaling of financial strength.","They have no access to debt markets because lenders refuse large technology groups.","Their WACC is already zero because equity financing carries no required return.","Their net capex exceeds 50% of their debt, which makes borrowing unnecessary."],"correct_index":0,"explanation":"Low leverage (NFP/EBITDA at or below 1.0x, D/E below industry) is typical of start-ups and firms with volatile cash flows that want to keep flexibility and signal financial strength.","set":2},{"id":"fm-s8-q12","session":"8","topic":"FCFO build","question":"Which sequence builds free cash flow to the firm (FCFO) on the slides?","choices":["EBIT plus taxes gives NOPAT, then subtract D&A, add the change in working capital and add net capex.","NOPAT from EBIT less taxes, plus D&A, minus the change in working capital, minus net capex.","Net income plus interest expense minus net capex, ignoring the working capital change.","EBITDA minus net income minus the change in working capital, ignoring taxes on EBIT."],"correct_index":1,"explanation":"FCFO = NOPAT + D&A - change in working capital - net capex; D&A is added back because it is not a cash cost.","set":2},{"id":"fm-s8-q13","session":"8","topic":"Financing need","question":"A growing firm has positive NOPAT but still needs external financing. According to the slides, why?","choices":["Its NOPAT turns negative after taxes, so it must raise capital.","D&A is a cash outflow, so NOPAT overstates the cash generated.","Its FCFO always exceeds its needs, so financing remains a choice.","Working capital growth and capex absorb NOPAT, leaving a financing need."],"correct_index":3,"explanation":"A growing firm's working-capital increase and net capex eat up NOPAT, so FCFO is negative and the gap must be financed with debt or equity; a self-sufficient firm's NOPAT covers its needs.","set":2},{"id":"fm-s8-q14","session":"8","topic":"Ordinary debt","question":"The slides explain 'ordinary debt' firms (working capital over debt above 50%) as:","choices":["A short-term focus for agility, or limited access to long-term debt.","Aggressive LBO positioning with long-term debt and high leverage.","NFP/EBITDA above 3x, with stable cash flows supporting the debt.","Mature cash flows that open new long-term debt capacity."],"correct_index":0,"explanation":"Ordinary debt (short-term debt, working capital over debt above 50%) reflects either a focus on short-term agility - sometimes a management myopia warning - or difficulty accessing long-term debt.","set":2},{"id":"fm-s7-q23","session":"7","topic":"Estimation period","question":"When estimating a stock's beta by regression, why do data services typically use 2 to 5 years of returns rather than a much longer history?","choices":["Longer windows add observations, but the risk profile changes, so distant data bias the estimate.","Regulations forbid using more than 5 years of market data for beta estimation.","Longer windows reduce the standard error so much that the regression becomes unusable.","Market indices are rebased every 5 years, which breaks any longer series."],"correct_index":0,"explanation":"The trade-off: more data lowers statistical noise, but companies change (business mix, leverage), so old returns describe a different firm. Practice settles on 2 to 5 years.","set":2},{"id":"fm-s7-q24","session":"7","topic":"Bottom-up beta","question":"You need the beta of a division that is not traded on any market, so a regression is impossible. What does the bottom-up approach prescribe?","choices":["Assign the market beta of 1.0, since an untraded asset carries average risk.","Use listed comparable firms: unlever their betas, average them, then relever for the division's own D/E.","Use the beta of the parent group's stock, which already consolidates the division.","Estimate beta from the division's earnings volatility against its own revenue."],"correct_index":1,"explanation":"For non-traded assets, comparable listed firms provide the reference: strip their financial leverage to get unlevered business betas, average them, then apply the target's own leverage. This is the Heinz case approach.","set":2},{"id":"fm-s7-q25","session":"7","topic":"Cost of debt estimation","question":"A firm has several bonds outstanding and different bonds carry different ratings. To estimate its cost of debt from public ratings, what should you use?","choices":["The best rating, because lenders price the firm's strongest bond.","The worst rating, to stay conservative on default risk.","The median rating of the firm, then the default spread attached to that rating.","A simple average of the coupons actually paid on its bonds."],"correct_index":2,"explanation":"When ratings differ across bonds of the same firm, take the median rating and map it to a default spread over the risk-free rate. Past coupons reflect old market conditions, not the current borrowing rate.","set":2},{"id":"fm-s7-q26","session":"7","topic":"Systematic risk","question":"Why does the cost of capital differ from one sector of activity to another?","choices":["Only systematic risk is paid, and sectors differ in cost structure, cyclicality and growth.","Some sectors are legally allowed to promise higher returns to their own investors.","Specific risks are fully remunerated in regulated sectors, so required returns differ.","The risk-free rate is set sector by sector by central banks, so sector returns differ."],"correct_index":0,"explanation":"Investors are only paid for systematic risk, since specific risk is diversified away. A sector's systematic risk comes from its economics: fixed versus variable costs, cyclical sensitivity, predictability of the activity and growth.","set":2},{"id":"fm-s9-q15","session":"9","topic":"Debt amortization","question":"In a typical LBO debt schedule, how do the repayment profiles of Term Loan A and Term Loan B differ?","choices":["The TLB amortizes about 20% per year while the TLA is a pure bullet at maturity.","Both tranches repay in equal annual installments over the holding period.","The TLA amortizes about 20% per year while the TLB repays about 1% per year and a bullet at exit.","Both tranches are bullets repaid only at exit, with no scheduled amortization."],"correct_index":2,"explanation":"Mandatory amortization hits the TLA hard (about 20% a year) while the TLB repays only about 1% a year, the balance coming due as a bullet. The cash sweep then prepays the TLA until it is gone.","set":2},{"id":"fm-s9-q16","session":"9","topic":"Deleveraging engine","question":"A sponsor buys a company for 500 million euros (5.0x EBITDA of 100) with 300 of debt and 200 of equity. Five years later it exits at the same 5.0x multiple with EBITDA unchanged, but net debt has fallen to 150. What is the equity multiple, and which engine produced it?","choices":["1.0x, because nothing changed between entry and exit.","1.75x, produced by deleveraging: equity value rose from 200 to 350 as debt was repaid.","2.5x, produced by arbitrage on the entry multiple.","1.5x, produced by operational improvement of the business."],"correct_index":1,"explanation":"Exit EV = 5.0 x 100 = 500; equity out = 500 - 150 = 350; MOIC = 350 / 200 = 1.75x. With multiple and EBITDA flat, the whole gain comes from paying down debt: the leverage engine.","set":2},{"id":"fm-s9-q17","session":"9","topic":"Revolver purpose","question":"Why does an LBO model typically keep the revolving credit facility undrawn?","choices":["Drawing it is prohibited by the term loan covenants.","It serves as a liquidity backstop for working-capital swings, drawn only when cash runs short.","It exists only to pay the arrangement fees of the other tranches.","It is kept for the sponsor's dividend payments in year one."],"correct_index":1,"explanation":"The revolver is the deal's liquidity buffer: undrawn in the base case, it absorbs temporary cash shortfalls (working capital, timing) so the company never misses debt service; if drawn, it costs a floating rate like SOFR + 200 bps.","set":2},{"id":"fm-s9-q18","session":"9","topic":"Sweep order","question":"After mandatory amortization, in which order does a 100% cash sweep apply excess free cash flow?","choices":["It prepays the high-yield bonds first, since they carry the highest coupon.","It prepays all tranches pro rata to their outstanding balances.","It prepays the revolver, then the sponsor's subordinated loan.","It prepays the Term Loan A until it is fully repaid, then the Term Loan B."],"correct_index":3,"explanation":"The contractual waterfall forces excess cash onto the term loans in seniority order: TLA first until extinguished, then TLB. High-yield notes stay outstanding because early repayment would trigger a call premium.","set":2},{"id":"fm-s9-q19","session":"9","topic":"Operational engine","question":"A sponsor buys a company for 480 million euros (6.0x EBITDA of 80) with 200 of net debt. At exit, EBITDA has grown to 100 and the same 6.0x multiple applies, with net debt still 200. What is the equity multiple, and which engine produced it?","choices":["1.25x, produced by arbitrage between the entry and exit multiples.","1.43x, produced by EBITDA growth at a constant multiple, an operational engine.","1.43x, produced by deleveraging over the holding period, with net debt falling.","2.00x, produced by the cash sweep mechanics during the holding period."],"correct_index":1,"explanation":"Equity in = 480 - 200 = 280; exit EV = 6.0 x 100 = 600; equity out = 600 - 200 = 400; MOIC = 400 / 280 = 1.43x. Multiple and net debt are unchanged, so the gain is pure EBITDA growth: the operational engine.","set":2},{"id":"fm-s9-q20","session":"9","topic":"Covenant metrics","question":"Which set of indicators do lenders monitor to track the credit quality of a leveraged buyout?","choices":["Share price momentum, dividend yield and free float turnover of the listed debt.","Price-to-earnings, price-to-book and earnings per share growth over the holding period.","Net debt/EBITDA, interest cover, debt service cover and liquidity with the undrawn revolver.","Days sales outstanding, inventory turnover and gross margin, with no leverage ratios."],"correct_index":2,"explanation":"Leveraged-credit monitoring rests on leverage (net debt / EBITDA), coverage (EBITDA / interest, (EBITDA - capex) / debt service) and liquidity (cash on hand plus undrawn revolver) against covenant thresholds.","set":2},{"id":"fm-s1-q17","session":"1","topic":"Three equilibria","question":"A firm shows a healthy profit and a growing order book, yet it cannot fund its investments from operating cash and its balance sheet keeps deteriorating. Under the session's framework, value creation requires equilibrium across which three statements?","choices":["The cash flow statement, the income statement and the balance sheet.","The cash budget, the financial budget and the strategic plan.","The income statement, the sales budget and the production plan.","The balance sheet, the tax return and the payroll ledger."],"correct_index":0,"explanation":"Value creation rests on three simultaneous equilibria: cash flow statement, income statement and balance sheet. Profitability alone is not enough if cash and financial structure are out of balance.","set":2},{"id":"fm-s1-q18","session":"1","topic":"Back testing","question":"A planning team revises its model every week, systematically comparing each forecast with the actual figures that came in. Which of the six planning practices is the team applying?","choices":["Building a momentum case from a do-nothing baseline.","Assigning explicit probability values to all assumptions.","Back testing the model against actuals.","Disaggregating inflation rates by cost component."],"correct_index":2,"explanation":"Back testing means regularly revising the model (for example weekly) and comparing forecasts with actuals, so assumptions improve over time.","set":2},{"id":"fm-s1-q19","session":"1","topic":"Financial budget","question":"A finance team needs integrated balance sheet, income statement and cash flow projections at annual or quarterly frequency, over roughly a one-year horizon, to drive operational and investment budgeting. Which tool fits this need?","choices":["The cash budget, run weekly.","The financial budget.","The strategic plan, over seven years.","The aging schedule."],"correct_index":1,"explanation":"The financial budget sits between the cash budget and the financial plan: integrated BS, IS and CF at annual or quarterly frequency over a medium (one year) horizon, used for operational and investment budgeting.","set":2},{"id":"fm-s1-q20","session":"1","topic":"Cash budget steps","question":"What is the correct sequence of steps for building a cash budget?","choices":["Forecast uses of cash, then sources of cash, then set the opening balance.","Plan the funding first, then forecast sources and uses of cash for the period.","Compute the surplus or shortage first, then forecast sources and uses of cash.","Forecast sources and uses of cash, compute shortage or surplus, then plan funding."],"correct_index":3,"explanation":"The cash budget starts from forecast sources, subtracts forecast uses to find the periodic shortage or surplus, and only then draws up the plan for raising or investing cash.","set":2},{"id":"fm-s2-q16","session":"2","topic":"Operating vs cash cycle","question":"A firm's inventory period is 60 days and its receivable period is 45 days; it pays its suppliers in 40 days. What are its operating cycle and its cash cycle?","choices":["Operating cycle 65 days, cash cycle 105 days.","Operating cycle 145 days, cash cycle 105 days.","Operating cycle 105 days, cash cycle 145 days.","Operating cycle 105 days, cash cycle 65 days."],"correct_index":3,"explanation":"The operating cycle is inventory period plus receivable period (60 + 45 = 105 days). The cash cycle subtracts the payables period (105 - 40 = 65 days), measuring how long the firm's own cash is tied up.","set":2},{"id":"fm-s2-q17","session":"2","topic":"Aging schedule","question":"Within its collection policy, what does a firm use an aging schedule for?","choices":["Tracking the age of inventory sitting in the warehouse.","Tracking the seniority and tenor of its supplier base.","Tracking the maturity profile of its outstanding bank debt.","Tracking the proportion of receivables that are mildly or badly overdue."],"correct_index":3,"explanation":"The aging schedule shows the proportion of accounts that are mildly or badly overdue, so the firm can monitor how promptly bills are paid.","set":2},{"id":"fm-s2-q18","session":"2","topic":"Factoring","question":"A small firm cannot afford a fully fledged credit and collection operation, while a large rival reaps economies of scale in record keeping, billing and collection. What does the session suggest for the small firm?","choices":["Farm out part of the credit and collection job to a factor.","Stop granting trade credit to any customer.","Demand cash before delivery from all customers.","Extend its payables instead of managing receivables."],"correct_index":0,"explanation":"A small firm that cannot support a full credit operation can farm out part of the job to a factor, which handles record keeping, billing and collection.","set":2},{"id":"fm-s2-q19","session":"2","topic":"Credit analysis focus","question":"A credit manager with limited time must decide where to concentrate credit analysis effort on the customer portfolio. What do the slides recommend?","choices":["Spread effort equally across all credit applications.","Concentrate on the large and doubtful accounts.","Concentrate on customers with the longest relationship.","Concentrate on accounts below the materiality threshold."],"correct_index":1,"explanation":"Credit work should concentrate on the dangerous accounts: large exposures and doubtful payers, not spread evenly over every application.","set":2},{"id":"fm-s2-q20","session":"2","topic":"Terms of sale","question":"According to the slides, a seller may reasonably allow more extended payment terms when which conditions hold?","choices":["Goods resell quickly and customer accounts are small, so the seller recovers cash fast.","The seller is facing a liquidity squeeze and needs to finance customers cheaply.","Customers are low-risk, accounts are large, buyers need time to check quality, and resale is slow.","The goods are perishable and the industry demands short terms from every supplier."],"correct_index":2,"explanation":"Sellers grant longer terms when customers are low-risk, accounts are large, buyers need time to check the quality of the goods, and the goods are not quickly resold.","set":2},{"id":"fm-s3-q17","session":"3","topic":"Direct input","question":"While building a financial plan, an analyst enters next year's new bank loan issues by typing the contractual emission amounts year by year, exactly as agreed with the bank. Which forecasting technique is this?","choices":["Indirect input driven by a ratio.","Direct input forecasting.","A control account closure.","Back testing against actuals."],"correct_index":1,"explanation":"Direct input means forecasting currency amounts explicitly, as with scheduled new debt issues. Indirect input instead derives the figure from a driver such as a percentage of revenues.","set":2},{"id":"fm-s3-q18","session":"3","topic":"Control account","question":"How does a control account forecast a balance sheet item such as tangible assets?","choices":["By applying a fixed percentage of sales to the closing balance of the item.","By holding the item constant over the plan horizon, unless new investment occurs.","By forecasting increases and decreases separately, with EOP equal to BOP plus increases minus decreases.","By deriving the item directly from the forecast cash flow statement, without assumptions."],"correct_index":2,"explanation":"A control account introduces no new forecasting assumption for the closing balance: increases (for example capex) and decreases (depreciation) are forecast separately, and EOP equals BOP plus increases minus decreases.","set":2},{"id":"fm-s3-q19","session":"3","topic":"Circularity","question":"Why does a financial plan become circular once interest income and expense are modeled on cash and debt balances?","choices":["Dividends depend on share capital, which depends on dividends paid in the same period.","Depreciation depends on historical capex, which in turn depends on depreciation.","Sales depend on market share, which in turn depends on sales in the same period.","Interest depends on debt and cash balances, which depend on cash flow, itself affected by interest."],"correct_index":3,"explanation":"Interest is computed on average debt and cash, but those balances depend on the cash flow of the year, which is only known after interest is included. The loop is closed with iterative calculation or by linking interest to opening balances only.","set":2},{"id":"fm-s3-q20","session":"3","topic":"Top-down sales forecast","question":"Under the top-down approach to forecasting sales in a financial plan, how are revenues computed?","choices":["Market volume times market price, times the company's market share.","The sum of business unit forecasts built bottom-up.","Last year's sales grown at the consumer inflation rate.","Production capacity times the utilization rate."],"correct_index":0,"explanation":"The top-down approach estimates total industry size and the company's share of it: revenues equal (market volume times market price) times market share. Bottom-up instead aggregates business units and adds organic and M&A growth.","set":2},{"id":"fm-s1-q21","session":"1","topic":"Toys R Us sequence","question":"Which sequence correctly orders the four stages of the Toys R Us case discussed in the session?","choices":["Market shift, liquidity strain, pre-crisis leverage, then crisis and bankruptcy.","Leveraged buyout in 2005, e-commerce shift, liquidity strain, then the 2017 filing.","Pre-crisis profitability, crisis in 2005, market shift, then recovery by 2017.","Liquidity strain, pre-crisis buyout, crisis, then market shift toward e-commerce."],"correct_index":1,"explanation":"The case runs: leveraged buyout in 2005, rise of e-commerce pressure, high debt charges straining cash and capex, then failure to adapt and the 2017 Chapter 11 filing.","set":3},{"id":"fm-s1-q22","session":"1","topic":"Value creation rationale","question":"The session gives several reasons why firms should focus on value creation. Which reason concerns its applicability?","choices":["It is required by accounting regulators in every jurisdiction, whatever the sector.","It always maximizes short-term market share in every industry.","It removes the need for financial measurement because value follows strategy.","It is sector and lifecycle agnostic, so it applies to any industry and any stage."],"correct_index":3,"explanation":"Value creation is rational, broadly accepted by stakeholders, measurable through valuation techniques, and sector and lifecycle agnostic.","set":3},{"id":"fm-s1-q23","session":"1","topic":"Business plan functions","question":"Beyond financing and restructuring, a financial plan embedded in a structured planning process serves several functions. Which of the following is NOT one of them?","choices":["Clarifying business content and feasibility.","Supporting performance tracking of forecast versus actual.","Facilitating communication and negotiation with debt and equity markets.","Guaranteeing the accuracy of the forecasts it contains."],"correct_index":3,"explanation":"The plan clarifies feasibility, tests realism, supports forecast-versus-actual tracking, acts as a management tool and facilitates market communication. It cannot guarantee forecast accuracy.","set":3},{"id":"fm-s1-q24","session":"1","topic":"Uncertainty trends","question":"According to the World Uncertainty Index evidence shown in the session, what is the recent pattern of uncertainty spikes?","choices":["Spikes are becoming rarer but more severe.","Spikes are becoming more frequent and are getting higher.","Spikes have disappeared since 2020.","Spikes follow a stable ten-year cycle."],"correct_index":1,"explanation":"The WUI shows spikes becoming more frequent and getting higher over time, which is why planning must explicitly handle uncertainty.","set":3},{"id":"fm-s1-q25","session":"1","topic":"Explicit probabilities","question":"A head of FP&A requires every planning assumption to carry a clear probability estimate and appoints a single model owner to keep scenarios consistent. Which of the six practices for planning under uncertainty is being applied?","choices":["Using explicit probability values for all assumptions.","Disaggregating inflation rates.","Back testing the model weekly.","Building the momentum case."],"correct_index":0,"explanation":"The first McKinsey practice is to attach explicit probability values to assumptions, with a model owner (ideally the Head of FP&A) ensuring consistency.","set":3},{"id":"fm-s1-q26","session":"1","topic":"Bear case","question":"Why do the planning guidelines insist on making an explicit bear case, citing the line that everyone has a plan until they get punched in the mouth?","choices":["A bear case removes the need for probability estimates of the other scenarios.","A bear case guarantees the firm survives a crisis if its assumptions hold.","A plausible downside lets the team adjust as warning signals emerge and avoid paralysis.","A bear case is required to calculate the momentum case in the base scenario."],"correct_index":2,"explanation":"Including a plausible downside scenario prepares the organization to react to early warning signals instead of freezing when conditions deteriorate.","set":3},{"id":"fm-s1-q27","session":"1","topic":"Macro assumptions","question":"When setting macroeconomic assumptions such as GDP growth for a plan, what do the planning guidelines recommend?","choices":["Use the most optimistic single forecast available, to stay consistent with the strategy.","Use the company's own internal estimate only, since it knows its markets best.","Use credible sources, weight independent forecasts, and compare them with historical data.","Fix assumptions once at the start of the plan and never revisit them."],"correct_index":2,"explanation":"Clarity and consistency in macro assumptions come from credible sources, weighted averages of independent forecasts and comparison with history.","set":3},{"id":"fm-s1-q28","session":"1","topic":"Cash budget purpose","question":"What is the primary purpose of a cash budget?","choices":["Forecast periodic cash balances so the firm can plan funding or use of surpluses.","Maximize reported accounting profit through timing of cash receipts.","Set the firm's dividend policy for the coming years.","Replace the income statement in the firm's tax filing."],"correct_index":0,"explanation":"The cash budget forecasts periodic cash balances to plan funding needs or the investment of surpluses, translating accrual events into cash flows.","set":3},{"id":"fm-s1-q29","session":"1","topic":"Sources of cash","question":"In a cash budget, the sale of a warehouse, a paid-in capital increase and interest received on a deposit belong to which categories of sources?","choices":["All three are operating sources.","Investing, financing and other activities respectively.","Financing, investing and operating respectively.","All three are financing sources."],"correct_index":1,"explanation":"Selling property is an investing source, a paid-in capital increase is a financing source, and interest income falls under other activities.","set":3},{"id":"fm-s1-q30","session":"1","topic":"Uses of cash","question":"Which grouping correctly classifies uses of cash in a cash budget?","choices":["Salaries are investing, loan repayments are operating, equipment purchases are financing.","Taxes are financing, dividends are operating, bond repayments are investing.","Cash purchases are operating, equipment purchases are investing, loan repayments and dividends are financing.","Rent is financing, interest payments are operating, inventory purchases are investing."],"correct_index":2,"explanation":"Operating uses cover purchases, salaries, rent and taxes; investing uses cover purchases of PPE, securities and intangibles; financing uses cover interest, loan repayments and dividends.","set":3},{"id":"fm-s2-q21","session":"2","topic":"Period definitions","question":"In the cash cycle framework, what does the receivable period measure?","choices":["The delay between the purchase of raw materials and their payment.","The delay between the sale of goods and the moment customers pay their bills.","The delay between investing in inventories and selling the finished goods.","The delay between ordering and receiving raw materials."],"correct_index":1,"explanation":"The receivable period runs from the sale to cash collection. The inventory period runs from the investment in inventories to the sale, and the payables period from purchase to payment of raw materials.","set":3},{"id":"fm-s2-q22","session":"2","topic":"Benefits of holding inventory","question":"Which list gives the benefits of holding inventory named in the session?","choices":["Delivery on time, bulk purchase discounts, ability to meet unexpected increases in demand.","Higher order costs, slower production, more receivables.","Tax advantages, depreciation shields, supplier financing.","Lower storage costs, lower capital costs, fewer orders."],"correct_index":0,"explanation":"Holding inventory lets the firm deliver on time, buy in bulk at a discount and meet unexpected demand. These benefits trade off against carrying and order costs.","set":3},{"id":"fm-s2-q23","session":"2","topic":"Carrying vs order costs","question":"In the inventory trade-off, what do carrying costs include?","choices":["Handling and delivery costs of each order.","The purchase price of the goods.","The cost of storage and the opportunity cost of capital tied up in stock.","The cost of negotiating with suppliers."],"correct_index":2,"explanation":"Carrying costs are the cost of storage plus the opportunity cost of the capital invested in inventory; order costs are handling and delivery costs.","set":3},{"id":"fm-s2-q24","session":"2","topic":"Order frequency","question":"A firm faces high carrying costs and low order costs. According to the inventory trade-off, what ordering pattern makes sense?","choices":["Rare, very large orders.","More frequent orders in smaller quantities.","A single annual order covering all demand.","Ordering only after stockouts occur."],"correct_index":1,"explanation":"When storage and capital costs are high while placing an order is cheap, the firm minimizes total cost by ordering more often in smaller lots.","set":3},{"id":"fm-s2-q25","session":"2","topic":"Terms of sale, COD and CBD","question":"Not all sales involve trade credit. What do cash on delivery (COD) and cash before delivery (CBD) have in common?","choices":["Both give the customer a long period to pay.","Both require the seller to run credit analysis first.","Both eliminate or avoid granting payment time to the customer.","Both apply only to perishable goods."],"correct_index":2,"explanation":"COD and CBD are terms of sale without trade credit: payment happens at or before delivery, so no collection period arises.","set":3},{"id":"fm-s2-q26","session":"2","topic":"Credit analysis sources","question":"A credit manager wants an outside view on whether customers will pay. Which sources do the slides name?","choices":["Specialist assessors such as Dun and Bradstreet or Cerved, and Moody's or S&P for rated issuers.","The customer's marketing materials, which describe its market position and growth.","The seller's sales force opinions, which reflect each customer relationship.","The customer's tax returns, which show its profitability over several years."],"correct_index":0,"explanation":"Credit analysis combines the firm's own reading of customer financial statements with specialist views: Dun and Bradstreet or Cerved for small companies, Moody's and S&P for bond issuers.","set":3},{"id":"fm-s2-q27","session":"2","topic":"Look beyond the order","question":"A borderline customer applies for credit on a single order, but there is a good chance it will become a regular and reliable buyer. What does the credit allocation guidance say?","choices":["Extend credit only if the order is prepaid, since the relationship is uncertain.","Judge every order in isolation from the relationship with the customer.","Always refuse borderline applicants, because default losses exceed any later gain.","Credit decisions are dynamic: accepting a weaker risk today can pay off in future business."],"correct_index":3,"explanation":"Credit decisions should look beyond the immediate order: the value of a future regular customer can justify accepting a relatively poor current risk.","set":3},{"id":"fm-s2-q28","session":"2","topic":"Lending when the bank refuses","question":"A customer's bank cuts its credit line. Under which conditions can it still make sense for the supplier to keep extending trade credit?","choices":["Never: if the bank refuses credit, the supplier must refuse as well.","Always: trade credit is safer than bank lending to the same customer.","Only if the customer offers to pay interest on the overdue balance in advance.","When the supplier knows the customer better than the bank, or risks losing profitable sales."],"correct_index":3,"explanation":"Two reasons justify continuing: an information advantage over the bank, and the loss of profitable future sales if the customer goes out of business.","set":3},{"id":"fm-s2-q29","session":"2","topic":"Sales-collection synergy","question":"What does a synergetic link between the sales department and the collection department look like in practice?","choices":["Sales decides which invoices will never be collected, regardless of collection.","Collection sets the product prices, based on payment history.","The firm may support a customer financially, for example by lending when its bank cuts it off.","The two departments never exchange information, to keep their incentives independent."],"correct_index":2,"explanation":"The slides illustrate synergy with the sales and collection functions cooperating, even to the point of supporting a customer cut off by its bank.","set":3},{"id":"fm-s2-q30","session":"2","topic":"Cash cycle interpretation","question":"Firm A has a cash cycle of 20 days and firm B one of 80 days, in the same industry. All else equal, what does the difference indicate?","choices":["Firm B ties up its own cash for 60 more days, so it needs more working capital financing.","Firm B is more profitable by definition, since a longer cycle reflects more sales.","Firm A must be paying its suppliers too late, which explains its shorter cycle.","The cash cycle says nothing about financing needs, as it is an operating measure."],"correct_index":0,"explanation":"The cash cycle measures how long the firm's own cash is locked into the operating process; a longer cycle means more working capital to finance.","set":3},{"id":"fm-s3-q21","session":"3","topic":"Business plan definition","question":"What does a business plan do, in the definition given in the session?","choices":["It files the company's annual tax return and the related tax computations.","It outlines strategic and operational direction and generates performance and capital needs.","It lists only the marketing initiatives for next year and their expected costs.","It replaces the financial statements for investors during the first years of operations."],"correct_index":1,"explanation":"The business plan defines objectives, business model, investment needs and organization, and it is the foundation on which financial planning is built.","set":3},{"id":"fm-s3-q22","session":"3","topic":"Three requirements","question":"A plan shows aggressive revenue growth that the cash flow statement cannot fund. Which of the three business plan requirements is failing?","choices":["Reliability of assumptions, because the growth rate is too aggressive.","Consistency with the industrial plan, because capacity does not match sales.","Financial sustainability, the ability to self-finance and stay solvent over time.","The presentation format, because the financing gap is not displayed clearly."],"correct_index":2,"explanation":"Financial sustainability requires the plan to keep the company self-financed and solvent. Reliability concerns realistic assumptions, consistency the alignment with strategy and timing.","set":3},{"id":"fm-s3-q23","session":"3","topic":"Modeling definition","question":"What is financial modeling, as defined in the session?","choices":["The design of the company's logo and investor deck for the plan presentation.","A statistical forecast of the company's share price over the plan horizon.","The audit of the historical financial statements used as plan inputs.","Turning the business plan into integrated balance sheet, income statement and cash flow models."],"correct_index":3,"explanation":"Financial modeling represents the business plan as integrated, dynamic BS, IS and CF statements; the forecast financials are one part of the wider strategic business plan.","set":3},{"id":"fm-s3-q24","session":"3","topic":"Plan purposes by user","question":"Match the user to the typical purpose of a financial model: an investment banker working on an acquisition, and a research analyst.","choices":["Both use it mainly for variance analysis.","Valuation backup for the deal, and an investment recommendation respectively.","Both use it mainly to renegotiate debt terms.","Payroll planning, and tax filing respectively."],"correct_index":1,"explanation":"In M&A the model backs the valuation (including exit planning); equity research analysts use it to support investment recommendations. Management uses it for long-term plans and variance analysis.","set":3},{"id":"fm-s3-q25","session":"3","topic":"Model principles","question":"A model builder strips out every feature that does not serve the model's end use, keeping it as simple as possible while meeting user needs. Which two key principles does this apply?","choices":["Fitness for purpose and simplicity.","Consistency and integrity.","Clarity and efficiency only.","Integrity and fitness for purpose."],"correct_index":0,"explanation":"Fitness for purpose ties design to the end use; simplicity keeps the model as simple as possible while meeting user needs. Clarity, efficiency, consistency and integrity complete the six principles.","set":3},{"id":"fm-s3-q26","session":"3","topic":"Indirect input steps","question":"An analyst forecasts service costs as a percentage of revenues. What is the correct three-step sequence of this indirect forecasting?","choices":["Apply the ratio first, then compute the historical driver, then choose the forecast driver.","Choose the forecast driver, apply it, then audit the historical figures.","Compute the historical driver ratio, choose the forecast driver, then apply the ratio to it.","Fix costs constant, then grow revenues, then reconcile the two forecasts."],"correct_index":2,"explanation":"Indirect input starts from the historical driver ratio (for example service costs as a percentage of revenues), selects the forecast driver value, and applies the ratio in reverse to get the forecast amount.","set":3},{"id":"fm-s3-q27","session":"3","topic":"Opex drivers","question":"Which approaches to forecasting variable operating costs does the session describe?","choices":["Only a historical average, kept constant over the horizon.","Only the inflation rate applied to last year's costs, kept for each year.","Only management discretion with no driver, reviewed once each year.","An indirect driver such as percent of sales, flat, growing or glidepath to a target."],"correct_index":3,"explanation":"Variable opex uses an indirect driver such as percentage of sales or volumes; the ratio can be flatlined, growing (for example economies of scale) or glide toward a final-year management target.","set":3},{"id":"fm-s3-q28","session":"3","topic":"D&A detailed approach","question":"Under the detailed approach to D&A, how is each year's capex depreciated, and what is the first-year convention?","choices":["Each year's capex is depreciated in full over one year.","Only past capex is depreciated and new capex is expensed later.","Each year's capex is depreciated over its useful life, with a halved first-year charge.","All capex is expensed immediately and no depreciation schedule is needed."],"correct_index":2,"explanation":"The detailed approach depreciates each vintage of capex over its useful life (charge equals asset over life or asset times the amortization rate), halving the first year's D&A; historical fixed assets keep amortizing until expiry.","set":3},{"id":"fm-s3-q29","session":"3","topic":"Tax forecast","question":"Which two drivers does the session offer for forecasting income taxes, and why is the tax line incomplete at that stage?","choices":["Only the statutory rate, because revenues are not yet forecast at that stage.","The historical effective rate or regulatory rates, but EBT still lacks interest.","Only the VAT rate, because dividends are not yet modeled at that stage.","Only last year's taxes, because capex is not yet forecast at that stage."],"correct_index":1,"explanation":"Taxes are forecast with the historical effective rate or with regulatory rates (for example Italy's IRES 24% plus IRAP 3.9%); the base EBT is incomplete until interest is modeled.","set":3},{"id":"fm-s3-q30","session":"3","topic":"Debt forecast approaches","question":"What distinguishes the two gross debt forecasting approaches in the session?","choices":["Maturity schedule (BOP plus issues minus repayments) versus a leverage-ratio target for EOP debt.","One applies only to bonds and the other only to equity financing instruments.","One uses interest rates and the other uses tax rates to forecast the debt.","There is no difference: both ignore repayments and rely on closing balances."],"correct_index":0,"explanation":"The schedule approach closes debt as a control account from known issues and repayments; the leverage-target approach sets EOP debt at once via a ND/E driver, implicitly netting new raising against repayment.","set":3},{"id":"fm-s45-q21","session":"4-5","topic":"Annualized forward premium","question":"A currency is quoted in dollars per unit. Spot is $0.80 and the 90-day forward is $0.804. Using a 360-day year and (F / S - 1) x 360 / 90, what is the annualized forward premium?","choices":["0.5%, the premium over the 90-day period.","2.0%, the 90-day premium annualized four times.","0.125%, the premium divided by four.","4.0%, the forward price minus the spot price."],"correct_index":1,"explanation":"The 90-day premium is 0.804 / 0.80 - 1 = 0.5%. Multiplying by 360 / 90 gives a 2.0% annualized premium. The quote convention is stated explicitly.","set":3},{"id":"fm-s45-q22","session":"4-5","topic":"Forward cash settlement","question":"A US exporter will receive EUR 2 million in six months and sells that amount forward at $1.12 per euro. At settlement, spot is $1.18 per euro. Ignoring fees, what are the total dollar proceeds from the receivable and matched forward?","choices":["$2.36 million, because spot replaces the forward rate.","$2.48 million, adding the forward gain to spot proceeds.","$2.24 million, because the forward fixes the conversion.","$2.12 million, subtracting the loss twice from the receipt."],"correct_index":2,"explanation":"The receivable is worth $2.36 million at spot, while the short forward loses EUR 2 million x ($1.18 - $1.12) = $0.12 million. Together they produce $2.24 million, equal to EUR 2 million x $1.12.","set":3},{"id":"fm-s45-q23","session":"4-5","topic":"Put net floor","question":"A US exporter expects a GBP 3 million contractual receipt and buys puts on the entire amount with a strike of $1.25 per pound. The premium is $0.03 per pound, paid today. Ignore financing of the premium. What is the minimum net dollar receipt after premium?","choices":["$3.66 million, using the strike less the premium.","$3.75 million, ignoring the cost of protection.","$3.84 million, adding the premium to the strike.","$0.09 million, using only the premium payment."],"correct_index":0,"explanation":"The put guarantees gross conversion at $1.25 per pound. Subtracting the $0.03 premium gives a $1.22 net floor. GBP 3 million x $1.22 = $3.66 million.","set":3},{"id":"fm-s45-q24","session":"4-5","topic":"Call above strike","question":"A US importer owes GBP 4 million. It buys calls with a $1.30 per pound strike and a $0.02 per pound premium. At maturity, spot is $1.38 per pound. Ignoring premium financing, what total dollar cost does the importer incur?","choices":["$5.52 million, buying all pounds at spot and ignoring the call.","$5.12 million, deducting the premium from the strike cost.","$5.60 million, paying spot plus the premium despite exercise.","$5.28 million, paying the strike price plus the premium."],"correct_index":3,"explanation":"The importer exercises because spot exceeds the strike. The currency costs GBP 4 million x $1.30 = $5.20 million, plus GBP 4 million x $0.02 = $0.08 million premium, for $5.28 million.","set":3},{"id":"fm-s45-q25","session":"4-5","topic":"Call below strike","question":"A US importer owes GBP 4 million. It buys calls with a $1.30 per pound strike and a $0.02 per pound premium. At maturity, spot is $1.24 per pound. Ignoring premium financing, what total dollar cost does the importer incur?","choices":["$4.96 million, because an unused option has no premium cost.","$5.28 million, because the call forces purchase at the strike.","$5.04 million, buying at spot and retaining the premium cost.","$5.20 million, because the premium is refunded on expiry."],"correct_index":2,"explanation":"The call expires unused and pounds are purchased at spot for $4.96 million. The $0.08 million premium remains a cost even without exercise. Total cost is $5.04 million.","set":3},{"id":"fm-s45-q26","session":"4-5","topic":"Hedge comparison","question":"A US exporter will receive GBP 2 million. It can sell pounds forward at $1.40 or buy a put with strike $1.38 and premium $0.02 per pound. At maturity, spot is $1.45. Ignoring premium financing, which strategy yields more net dollars?","choices":["The forward by $40,000, since its rate exceeds the strike.","The put by $60,000, after selling at spot and paying premium.","The put by $100,000, since its premium is refunded.","Both give $2.80 million because either contract fixes proceeds."],"correct_index":1,"explanation":"The forward yields GBP 2 million x $1.40 = $2.80 million. The unexercised put strategy yields GBP 2 million x ($1.45 - $0.02) = $2.86 million. The difference is $60,000.","set":3},{"id":"fm-s45-q27","session":"4-5","topic":"Partial forward coverage","question":"A euro-based exporter has a certain $1 million receipt and sells $600,000 forward at EUR 0.90 per dollar. At settlement, spot is EUR 0.85 per dollar. Ignoring fees, what total euro receipt results?","choices":["EUR 850,000, converting the entire receipt at spot.","EUR 900,000, applying the forward to the entire receipt.","EUR 540,000, omitting the uncovered portion of the receipt.","EUR 880,000, combining covered and uncovered portions."],"correct_index":3,"explanation":"The covered $600,000 gives EUR 540,000. The remaining $400,000 converts at spot for EUR 340,000. Total proceeds are EUR 880,000. Only the uncovered portion remains exposed to spot movements.","set":3},{"id":"fm-s45-q28","session":"4-5","topic":"Quantity risk reversal","question":"A euro-based exporter sells a forecast $1 million receipt forward at EUR 0.90 per dollar. Actual receipts fall to $700,000. At settlement, spot is EUR 0.95 per dollar. What is the gain or loss on the unsupported $300,000 forward portion alone?","choices":["A EUR 15,000 loss from buying dollars above the delivery rate.","A EUR 15,000 gain from receiving the higher spot rate.","A EUR 285,000 loss with no proceeds from forward delivery.","No gain or loss because the forecast automatically resizes the hedge."],"correct_index":0,"explanation":"The firm must buy the missing $300,000 at EUR 0.95, costing EUR 285,000, then deliver those dollars for EUR 270,000 under the forward. The unsupported portion loses EUR 15,000.","set":3},{"id":"fm-s45-q29","session":"4-5","topic":"Two-stage forward policy","question":"A euro-based exporter will certainly collect $500,000. At budget time it could lock EUR 0.92 per dollar, but it waits until invoicing and locks EUR 0.88. Ignoring fees, how do the two forward choices compare?","choices":["Waiting raises fixed euro receipts by EUR 20,000.","Both lock EUR 460,000 because the dollar amount is unchanged.","Waiting lowers fixed euro receipts by EUR 20,000.","Waiting leaves the full receipt exposed to settlement spot."],"correct_index":2,"explanation":"An early forward would lock $500,000 x EUR 0.92 = EUR 460,000. The later forward locks EUR 440,000. Waiting changed the available rate before the hedge, reducing locked receipts by EUR 20,000.","set":3},{"id":"fm-s45-q30","session":"4-5","topic":"Spot versus contractual forecast","question":"A European exporter has two dollar exposures: a signed invoice payable in 90 days, and possible sales next year that depend on competitiveness. Which distinction matters when using matched currency forwards?","choices":["Both have identical certainty of amount, so both can always be fully matched.","The invoice has a contractual amount, while future sales carry quantity uncertainty.","Only future sales are transaction exposure, while the invoice is translation exposure.","Neither creates currency risk until cash has already been converted into euros."],"correct_index":1,"explanation":"A signed foreign-currency invoice creates transaction exposure with a known contractual amount. Future sales depend on competitive conditions and may differ from forecasts. Hedging them in full before certainty can create an unsupported forward obligation.","set":3},{"id":"fm-s6-q21","session":"6","topic":"Swap settlement amount","question":"A company has a $12 million floating loan at SOFR + 1.4%. A matching swap requires it to pay 4.2% fixed and receive SOFR annually on $12 million. SOFR is 5.0% for the year. What net cash flow arises from the swap alone?","choices":["A $96,000 receipt, because the floating leg exceeds the fixed leg.","A $96,000 payment, because the fixed leg exceeds the floating leg.","A $672,000 payment, including the separate loan interest.","A $504,000 receipt, ignoring the floating leg of the swap."],"correct_index":0,"explanation":"The swap pays $12 million x 4.2% = $504,000 and receives $12 million x 5.0% = $600,000. The net swap receipt is $96,000. The loan is separate from this swap-only calculation.","set":3},{"id":"fm-s6-q22","session":"6","topic":"Fixed to floating conversion","question":"A firm pays a 6.0% fixed coupon on $10 million of debt. It enters a matched swap to receive 5.0% fixed and pay SOFR on the same notional. Ignoring fees, what effective interest rate results?","choices":["A fixed 1.0%, because all floating payments disappear.","SOFR minus 1.0%, subtracting the debt coupon from receipts.","A fixed 11.0%, adding both fixed rates and ignoring SOFR.","SOFR plus 1.0%, combining the debt and both swap legs."],"correct_index":3,"explanation":"The combined rate is 6.0% debt coupon minus 5.0% received on the swap plus SOFR paid on the swap. The result is SOFR + 1.0%, converting fixed debt into floating exposure.","set":3},{"id":"fm-s6-q23","session":"6","topic":"Notional mismatch","question":"A firm has a $10 million loan at SOFR + 1.5%, but swaps only $6 million by paying 4.0% fixed and receiving SOFR. All rates reset annually on the same date. If SOFR rises by 1 percentage point, by how much does annual combined interest cost rise?","choices":["$100,000, because the swap provides no interest protection.","$40,000, because only $4 million remains floating.","$60,000, because the covered portion remains floating.","$0, because any swap fixes the entire loan balance."],"correct_index":1,"explanation":"The swap cancels SOFR on $6 million only. SOFR still applies to $4 million of the loan. A 1 percentage point increase therefore raises annual combined cost by $4 million x 1% = $40,000.","set":3},{"id":"fm-s6-q24","session":"6","topic":"Loan spread survives swap","question":"A borrower pays SOFR + 2.0% on its loan and swaps a matching notional to pay 4.5% fixed and receive SOFR. Loan terms allow the spread to rise to 2.5% after a covenant breach. If that happens, what is the combined rate?","choices":["4.5%, because the swap absorbs every component of loan cost.","6.5%, because the original spread cannot affect the swap.","7.0%, because the new spread remains payable above 4.5%.","SOFR + 2.5%, because the covenant breach cancels the swap."],"correct_index":2,"explanation":"The matched SOFR legs cancel, but the swap does not cancel the loan spread. The new combined rate is 4.5% + 2.5% = 7.0%. Fixing the reference rate does not remove a separate contractual spread change.","set":3},{"id":"fm-s6-q25","session":"6","topic":"IRR cash flow construction","question":"A $5 million three-year bullet loan charges a 2% up-front fee, withheld at inception, and 6% annual interest on the full notional. Principal is repaid with the final coupon. Which cash flows should be used to calculate the borrower's all-in cost?","choices":["+$4.90m today, then -$0.30m, -$0.30m, -$5.30m annually.","+$5.00m today, then -$0.30m, -$0.30m, -$5.30m annually.","+$4.90m today, then -$0.294m, -$0.294m, -$5.194m annually.","+$4.90m today, then -$0.30m, -$0.30m, -$0.30m annually."],"correct_index":0,"explanation":"The fee reduces proceeds to $5 million x 98% = $4.90 million. Interest remains 6% x $5 million = $0.30 million per year. The year-three outflow includes the full $5 million principal, giving $5.30 million.","set":3},{"id":"fm-s6-q26","session":"6","topic":"All-in cost after hedge","question":"A $4 million three-year bullet loan has a 1% up-front fee withheld today and pays SOFR + 1.0% annually. A matched swap pays 3.0% fixed and receives SOFR, with no swap fee. What are the combined initial proceeds and annual interest payment?","choices":["$4.00 million and $160,000, ignoring the loan fee.","$3.96 million and $120,000, omitting the loan spread.","$3.96 million and $158,400, using proceeds as notional.","$3.96 million and $160,000, with the full principal repaid at maturity."],"correct_index":3,"explanation":"Initial proceeds are $4 million x 99% = $3.96 million. After SOFR cancellation the rate is 3.0% + 1.0% = 4.0% on $4 million, or $160,000 annually. The fee affects IRR through proceeds, not the interest notional.","set":3},{"id":"fm-s6-q27","session":"6","topic":"Comparative borrowing advantage","question":"Firm A can borrow at 5.0% fixed or SOFR + 0.2%. Firm B can borrow at 6.4% fixed or SOFR + 0.8%. Using the fixed-rate gap minus the floating-rate gap, what total annual saving is available before intermediary fees?","choices":["2.0 percentage points, adding both borrowing gaps.","0.6 percentage points, using only the floating gap.","0.8 percentage points, subtracting 0.6 from 1.4.","1.4 percentage points, using only the fixed gap."],"correct_index":2,"explanation":"The fixed-rate quality gap is 6.4% - 5.0% = 1.4 percentage points. The floating-rate gap is 0.8% - 0.2% = 0.6 percentage points. Their difference is 0.8 percentage points, or 80 basis points, before fees.","set":3},{"id":"fm-s6-q28","session":"6","topic":"Allocation of swap benefit","question":"A proposed fixed-for-floating financing swap offers total savings of 80 basis points. The intermediary keeps 10 basis points and the borrowers split the remaining saving equally. How much does each borrower save annually on a $20 million notional?","choices":["$80,000, using 40 basis points before the intermediary fee.","$70,000, using 35 basis points after sharing the fee.","$140,000, allocating the full net saving to each borrower.","$20,000, allocating the intermediary fee to each borrower."],"correct_index":1,"explanation":"The net saving is 80 - 10 = 70 basis points. Each borrower receives 35 basis points, or 0.35%. On $20 million that equals $70,000 annually.","set":3},{"id":"fm-s6-q29","session":"6","topic":"Refinancing versus repricing","question":"A borrower needs funds for three years. Strategy A is one committed three-year floating-rate loan. Strategy B is a one-year fixed-rate loan renewed each year. Which risk is added by strategy B at each renewal?","choices":["The lender may refuse renewal or require a new credit spread.","The principal becomes equity without the borrower's consent.","The existing one-year coupon changes before its fixed period ends.","The borrower must exchange principal through an interest rate swap."],"correct_index":0,"explanation":"Annual renewal requires a new credit decision, creating refinancing or credit availability risk as well as uncertainty about the new terms. A committed three-year floating loan has reference-rate repricing, but no scheduled annual refinancing need.","set":3},{"id":"fm-s6-q30","session":"6","topic":"Effect of lower reference rate","question":"A company pays SOFR + 1.2% on a loan and has a perfectly matched swap paying 4.0% fixed and receiving SOFR. If SOFR falls from 5.0% to 3.0%, ignoring fees, what happens to its combined interest rate?","choices":["It falls from 6.2% to 4.2%, as though no swap existed.","It falls from 5.2% to 3.2%, keeping the full SOFR benefit.","It rises from 5.2% to 7.2%, because the swap doubles the fall.","It remains 5.2%, since lower loan interest is offset by lower swap receipts."],"correct_index":3,"explanation":"The combined rate is always SOFR + 1.2% + 4.0% - SOFR = 5.2%. Lower SOFR reduces the loan payment but also reduces the floating amount received on the swap by the same amount.","set":3},{"id":"fm-s7-q27","session":"7","topic":"Market value weights","question":"A firm has market debt of EUR 60 million and market equity of EUR 140 million. Its book debt is EUR 50 million and book equity EUR 50 million. Which debt weight belongs in the course WACC formula?","choices":["25%, using book debt over total market financing.","50%, using the book capital structure.","30%, using market debt over total market financing.","42.9%, using market debt divided by market equity."],"correct_index":2,"explanation":"The debt weight is D / (D + E) using market values: 60 / (60 + 140) = 30%. D/E is a different ratio, and book weights do not enter this formula.","set":3},{"id":"fm-s7-q28","session":"7","topic":"CAPM calculation","question":"A firm has an equity beta of 1.2, a risk-free rate of 3% and a market risk premium of 5%. Using CAPM, what is its cost of equity?","choices":["9.0%, adding beta times the premium to the risk-free rate.","6.0%, multiplying beta by the premium without adding the base rate.","9.6%, multiplying the entire expected market return by beta.","8.0%, adding the premium without adjusting for beta."],"correct_index":0,"explanation":"CAPM gives ke = rf + beta x MRP = 3% + 1.2 x 5% = 9%. The risk-free return is added once, not multiplied by beta.","set":3},{"id":"fm-s7-q29","session":"7","topic":"Unlever peer beta","question":"A listed peer has equity beta 1.5, market D/E of 0.5 and a 20% marginal tax rate. Using betaL = betaU x [1 + (1 - t) x D/E], with negligible debt beta, what is its unlevered beta?","choices":["0.75, dividing equity beta by two.","1.20, multiplying equity beta by one minus tax.","2.10, levering the equity beta a second time.","About 1.071, dividing equity beta by 1.4."],"correct_index":3,"explanation":"The leverage adjustment is 1 + 0.8 x 0.5 = 1.4. Removing it gives betaU = 1.5 / 1.4 = 1.0714. This separates business risk from the peer's financing risk.","set":3},{"id":"fm-s7-q30","session":"7","topic":"Bottom-up beta arithmetic","question":"Two comparable firms have unlevered betas of 0.8 and 1.0. Use their simple average for a target with market D/E of 0.6 and tax rate 25%. With negligible debt beta, what target equity beta follows?","choices":["0.90, because unlevered beta is already an equity beta.","1.305, relevering the average business beta at target leverage.","1.44, multiplying the average by one plus D/E without tax.","0.621, dividing the average by the target leverage adjustment."],"correct_index":1,"explanation":"The average unlevered beta is (0.8 + 1.0) / 2 = 0.9. Relever at the target structure: 0.9 x [1 + (1 - 0.25) x 0.6] = 0.9 x 1.45 = 1.305.","set":3},{"id":"fm-s7-q31","session":"7","topic":"Historical premium uncertainty","question":"Annual equity returns have a standard deviation of 18%. Using standard error = standard deviation / square root of years, what standard error results from 81 independent annual observations?","choices":["18.0 percentage points, unchanged by sample length.","0.22 percentage points, dividing by all 81 years.","2.0 percentage points, dividing by the square root of 81.","9.0 percentage points, taking the square root of 81 as the answer."],"correct_index":2,"explanation":"The square root of 81 is 9. Standard error is 18% / 9 = 2 percentage points. Even a long historical sample can leave material uncertainty around the risk premium estimate.","set":3},{"id":"fm-s7-q32","session":"7","topic":"Risk-free consistency","question":"An analyst discounts long-horizon euro cash flows using a default-free long-term euro rate, but estimates the historical market risk premium relative to short-term bills. Which correction best addresses consistency?","choices":["Use a risk premium measured relative to a risk-free security consistent with the chosen base rate.","Remove the base rate entirely because the premium already includes every return.","Keep the mismatch because any government security is interchangeable at every maturity.","Use the firm's debt coupon as the base rate without changing the premium."],"correct_index":0,"explanation":"The historical MRP depends on the risk-free benchmark chosen. A consistent cost of equity combines a base rate with a premium estimated using a compatible benchmark, rather than mixing bill-based and long-bond-based conventions.","set":3},{"id":"fm-s7-q33","session":"7","topic":"Current borrowing cost","question":"A firm's old fixed-rate bond pays a 2% coupon. A liquid straight bond of the firm with the relevant maturity now yields 5%. Ignoring tax, which rate is the better observable input for its current cost of debt?","choices":["2%, since past contractual coupons define all new funding.","3%, subtracting the original coupon from the current yield.","7%, adding the original coupon to the current yield.","5%, reflecting the return now required by debt investors."],"correct_index":3,"explanation":"Cost of debt is the rate at which the firm can currently borrow for the relevant maturity. The current yield on suitable liquid debt is informative, whereas the old coupon describes a historical contract.","set":3},{"id":"fm-s7-q34","session":"7","topic":"Synthetic spread arithmetic","question":"A firm's EBIT is EUR 18 million and annual interest EUR 3 million. A supplied synthetic rating table assigns a 1.2% default spread to coverage between 5x and 7x. With a 3% risk-free rate, what pretax cost of debt does this method imply?","choices":["3.0%, since coverage removes the default spread.","4.2%, adding the assigned spread to the risk-free rate.","7.2%, multiplying the spread by the coverage ratio.","6.0%, treating the coverage ratio as a percentage rate."],"correct_index":1,"explanation":"Coverage is 18 / 3 = 6x, which falls in the supplied 5x to 7x band. The assigned spread is 1.2%, so pretax cost of debt is 3% + 1.2% = 4.2%. The table is supplied in the question, not assumed.","set":3},{"id":"fm-s7-q35","session":"7","topic":"Integrated WACC","question":"A company has market debt of EUR 80 million and equity of EUR 120 million. Its pretax debt cost is 5%, marginal tax rate 25%, risk-free rate 3%, equity beta 1.1 and market risk premium 5%. What is its WACC?","choices":["6.60%, combining 40% after-tax debt and 60% CAPM equity.","7.10%, combining the weights but ignoring the debt tax shield.","5.65%, reversing the debt and equity weights.","8.50%, using the cost of equity for every financing source."],"correct_index":0,"explanation":"CAPM gives ke = 3% + 1.1 x 5% = 8.5%. After-tax kd is 5% x 75% = 3.75%. Market weights are 40% debt and 60% equity. WACC = 0.4 x 3.75% + 0.6 x 8.5% = 6.6%.","set":3},{"id":"fm-s7-q36","session":"7","topic":"Business versus financial risk","question":"Two divisions have the same unlevered beta of 0.9 and the same 30% tax rate. Division A has D/E of zero, while division B has D/E of 1.0. Using the course leverage adjustment, which pair of equity betas is correct?","choices":["A 0.9 and B 0.9, since business risk is the same.","A 0.9 and B 0.27, reducing beta by the tax rate.","A 0.9 and B 1.53, adding financing risk to B's equity.","A 1.53 and B 0.9, assigning more risk to the unlevered division."],"correct_index":2,"explanation":"A has no debt, so its equity beta equals 0.9. For B, betaL = 0.9 x [1 + 0.7 x 1] = 1.53. Identical business risk does not imply identical equity risk when leverage differs.","set":3},{"id":"fm-s8-q21","session":"8","topic":"Debt weight versus D/E","question":"A firm has market D/E of 0.5. What proportion of its total debt plus equity financing is debt?","choices":["50.0%, treating D/E as a debt weight.","33.3%, converting D/E into D/(D+E).","66.7%, using the equity share instead.","25.0%, dividing D/E by two regardless of capital mix."],"correct_index":1,"explanation":"Set E = 1 and D = 0.5. Total financing is 1.5, so the debt weight is 0.5 / 1.5 = one third. Leverage ratios and financing weights are related but not interchangeable.","set":3},{"id":"fm-s8-q22","session":"8","topic":"Unused debt capacity","question":"A profitable firm expects a large acquisition next year. It keeps borrowing capacity unused even though more debt might lower its current financing cost. Which rationale best explains the decision?","choices":["It assumes equity investors require no return.","It treats every unused credit line as cash already received.","It expects all debt interest to become tax-free income.","It values financial flexibility for future funding needs."],"correct_index":3,"explanation":"Unused debt capacity can help fund later opportunities and withstand shocks. Capital structure practice therefore weighs financial flexibility alongside today's financing cost, rather than mechanically using all available debt.","set":3},{"id":"fm-s8-q23","session":"8","topic":"Rating discontinuity","question":"A company considers extra borrowing that could push its rating below investment grade. Its lenders would then require a sharply higher spread. Which practical factor must the company include in its capital structure decision?","choices":["A rating threshold can cause a discontinuous increase in funding cost.","Debt cost must decline continuously whenever leverage increases.","A rating change affects accounting profit but never cash interest.","The tax shield guarantees that a higher spread cannot matter."],"correct_index":0,"explanation":"Ratings and covenants are real-world frictions. Crossing an investment-grade threshold can make funding much more expensive, so the cost of extra leverage need not change smoothly.","set":3},{"id":"fm-s8-q24","session":"8","topic":"Working capital cash release","question":"A company has EBIT of EUR 200 million, taxes on EBIT of EUR 50 million, D&A of EUR 30 million, a EUR 20 million decrease in working capital and EUR 70 million net capex. What is FCFO?","choices":["EUR 90 million, treating the working-capital decrease as a cash use.","EUR 160 million, omitting net capex.","EUR 130 million, including the working-capital release as a source.","EUR 70 million, subtracting D&A rather than adding it back."],"correct_index":2,"explanation":"NOPAT is 200 - 50 = 150. FCFO = 150 + 30 - (-20) - 70 = 130. A decrease in working capital releases cash, so subtracting its negative change adds cash.","set":3},{"id":"fm-s8-q25","session":"8","topic":"External funding gap","question":"A growing firm forecasts NOPAT of EUR 90 million, D&A of EUR 20 million, a EUR 35 million working-capital increase and EUR 100 million net capex. It has no opening spare cash or other cash flows. What external funding is needed to cover this operating plan?","choices":["EUR 25 million, because FCFO is negative by that amount.","EUR 45 million, omitting the D&A cash-flow add-back.","EUR 75 million, treating capex as a source of financing.","No funding, because positive NOPAT guarantees positive FCFO."],"correct_index":0,"explanation":"FCFO = 90 + 20 - 35 - 100 = -25. With no available opening cash or other sources, the plan needs EUR 25 million of external funding. Accounting profitability alone does not cover investment and working capital.","set":3},{"id":"fm-s8-q26","session":"8","topic":"Debt maturity alignment","question":"A company finances a long-lived production facility entirely with debt that must be renewed every three months. Cash receipts from the facility arrive gradually over several years. Which issue is most directly relevant to avoiding financial tension?","choices":["The accounting depreciation method must equal the loan coupon.","Long-lived assets make refinancing risk disappear.","The company can ignore debt maturities if EBIT is positive.","Cash inflow timing must be aligned with debt maturities."],"correct_index":3,"explanation":"Capital structure management includes matching cash generation with payment obligations. Funding long-lived investment with repeatedly renewed short-term debt can create a refinancing need well before the asset generates enough cash.","set":3},{"id":"fm-s8-q27","session":"8","topic":"Debt-strategy classification","question":"Firm A has working capital / debt of 65% and uses debt mainly for short-term operations. Firm B has capex / debt of 70% and uses borrowing for a predictable expansion programme. Which course categories fit best?","choices":["A debt for growth and B ordinary debt.","A ordinary debt and B debt for growth.","Both low leverage because their assets are productive.","Both aggressive leverage solely because either ratio exceeds 50%."],"correct_index":1,"explanation":"The course typology associates working capital / debt above 50% with ordinary debt, and capex / debt above 50% with debt for growth. High investment shares alone do not establish the aggressive leverage category.","set":3},{"id":"fm-s8-q28","session":"8","topic":"Downside debt capacity","question":"Two firms have identical average operating cash flow. Firm A's cash flow is stable through the cycle, while firm B often has sharply negative cash flow in downturns. Other things equal, why can A support more debt?","choices":["A's stable cash flow removes all lender default risk.","Average cash flow is irrelevant to every financing decision.","Predictable cash flow makes scheduled debt service easier to sustain.","B's volatility guarantees higher tax shields in every downturn."],"correct_index":2,"explanation":"Debt requires scheduled payments even in weak periods. Stable cash generation supports those payments more reliably. Averages alone hide downside shortfalls, and stability does not mean risk is zero.","set":3},{"id":"fm-s8-q29","session":"8","topic":"Tax shield calculation","question":"A firm has EUR 100 million of debt at a 6% interest rate and a 25% marginal tax rate. Assume interest is fully deductible and the firm can use the deduction this year. What is the annual interest tax saving?","choices":["EUR 1.5 million, equal to interest expense times the tax rate.","EUR 4.5 million, equal to the after-tax interest expense.","EUR 6.0 million, equal to the entire interest payment.","EUR 25.0 million, applying the tax rate directly to principal."],"correct_index":0,"explanation":"Annual interest is EUR 100 million x 6% = EUR 6 million. The tax deduction saves EUR 6 million x 25% = EUR 1.5 million. After-tax interest cost is the remaining EUR 4.5 million.","set":3},{"id":"fm-s8-q30","session":"8","topic":"Leverage sensitivity","question":"A company has unlevered beta 0.8 and a 25% tax rate. Market D/E rises from 0.5 to 1.0, with business risk unchanged. Using betaL = betaU x [1 + (1 - t) x D/E], what happens to equity beta?","choices":["It stays at 0.8 because business risk has not changed.","It falls from 1.4 to 1.1 because debt absorbs the risk.","It rises from 1.1 to 1.4 because equity carries more financing risk.","It rises from 1.2 to 1.6 because tax never enters the adjustment."],"correct_index":2,"explanation":"At D/E 0.5, betaL = 0.8 x 1.375 = 1.1. At D/E 1.0, betaL = 0.8 x 1.75 = 1.4. More debt increases the risk borne by the residual equity claim even with unchanged business risk.","set":3},{"id":"fm-s9-q21","session":"9","topic":"Exit equity bridge","question":"At an LBO exit, EBITDA is EUR 60 million and the enterprise-value multiple is 8x. Gross financial debt is EUR 200 million and cash EUR 30 million. Ignoring fees, what equity proceeds are available to the sponsor?","choices":["EUR 280 million, subtracting gross debt but ignoring cash.","EUR 480 million, treating enterprise value as equity value.","EUR 650 million, adding net debt to enterprise value.","EUR 310 million, subtracting EUR 170 million net debt."],"correct_index":3,"explanation":"Enterprise value is 60 x 8 = 480. Net debt is 200 - 30 = 170. Equity value is EV minus net debt: EUR 480 million - EUR 170 million = EUR 310 million.","set":3},{"id":"fm-s9-q22","session":"9","topic":"Entry price discipline","question":"A sponsor expects EUR 400 million of equity proceeds at exit. Financing and all exit assumptions are unchanged. If the sponsor's initial equity cheque rises from EUR 160 million to EUR 200 million, how does MOIC change?","choices":["It rises from 2.0x to 2.5x because the sponsor invested more.","It falls from 2.5x to 2.0x because the same proceeds cost more.","It stays at 2.5x because exit proceeds are unchanged.","It falls from 2.5x to 1.0x because equity cannot exceed proceeds."],"correct_index":1,"explanation":"MOIC is cash received divided by initial equity invested. It falls from 400 / 160 = 2.5x to 400 / 200 = 2.0x. Paying more reduces the return without requiring any deterioration in the business.","set":3},{"id":"fm-s9-q23","session":"9","topic":"Annualized sponsor return","question":"A sponsor invests EUR 100 million and receives EUR 172.8 million exactly three years later, with no interim distributions. What is the annual IRR?","choices":["20%, since 1.20 cubed equals 1.728.","24.27%, dividing the total percentage gain by three.","72.8%, treating the total gain as a one-year return.","17.28%, dividing proceeds by ten times the investment."],"correct_index":0,"explanation":"With one initial outflow and one exit receipt, IRR = (172.8 / 100)^(1/3) - 1 = 20%. Dividing total growth by years ignores compounding.","set":3},{"id":"fm-s9-q24","session":"9","topic":"Cash sweep arithmetic","question":"An LBO generates EUR 45 million free cash flow before principal repayment. Mandatory amortization is EUR 10 million. After that payment, TLA has EUR 20 million outstanding and TLB EUR 80 million. Under a 100% sweep to TLA then TLB, how is the remaining cash allocated?","choices":["EUR 45 million to TLA, because mandatory amortization is separate.","EUR 10 million to TLA and EUR 35 million to TLB.","EUR 20 million to TLA and EUR 15 million to TLB.","EUR 35 million to TLB while TLA remains outstanding."],"correct_index":2,"explanation":"Mandatory amortization leaves 45 - 10 = EUR 35 million for the sweep. TLA is paid off with EUR 20 million, and the remaining EUR 15 million goes to TLB. Cash cannot be swept twice.","set":3},{"id":"fm-s9-q25","session":"9","topic":"SOFR floor","question":"A term loan pays SOFR plus 3%, with a 1% floor on SOFR. Its contract uses the greater of observed SOFR and the floor, then adds the spread. If observed SOFR is 0.4%, what coupon applies?","choices":["3.4%, adding the spread directly to observed SOFR.","3.0%, since a floor eliminates the reference-rate component.","1.0%, using the floor as the entire loan coupon.","4.0%, applying the 1% reference-rate floor before the spread."],"correct_index":3,"explanation":"The reference rate is max(0.4%, 1.0%) = 1.0%. Adding the 3% spread gives a 4% coupon. The question specifies that the floor applies to the base rate, not the all-in coupon.","set":3},{"id":"fm-s9-q26","session":"9","topic":"Average debt interest","question":"A debt tranche opens the year at EUR 120 million and closes at EUR 80 million after repayments. The model calculates annual cash interest at 6% on the simple average of opening and closing balances. What is the interest expense?","choices":["EUR 7.2 million, using only the opening balance.","EUR 6.0 million, applying 6% to EUR 100 million average debt.","EUR 4.8 million, using only the closing balance.","EUR 12.0 million, applying 6% to the sum of both balances."],"correct_index":1,"explanation":"Average debt is (120 + 80) / 2 = EUR 100 million. Interest is 6% x EUR 100 million = EUR 6 million. Using an average is why same-year repayments can interact with interest calculations.","set":3},{"id":"fm-s9-q27","session":"9","topic":"Peer median valuation","question":"Three comparable businesses trade at EV/EBITDA multiples of 6x, 8x and 16x. Apply the median to a target with EUR 25 million EBITDA and EUR 50 million net debt. Ignoring other adjustments, what equity value results?","choices":["EUR 150 million, bridging median-based enterprise value to equity.","EUR 200 million, omitting the net-debt adjustment.","EUR 250 million, adding net debt instead of subtracting it.","EUR 350 million, using the highest peer multiple."],"correct_index":0,"explanation":"The median multiple is 8x. Target EV is 8 x 25 = EUR 200 million, then equity value is 200 - 50 = EUR 150 million. The median limits the effect of the 16x observation.","set":3},{"id":"fm-s9-q28","session":"9","topic":"Liquidity headroom","question":"An LBO company has EUR 12 million cash and a EUR 40 million committed revolver, of which EUR 15 million is drawn. Assume the undrawn amount is fully available and there are no restrictions. What immediate liquidity buffer is available?","choices":["EUR 52 million, adding the entire revolver without subtracting drawings.","EUR 27 million, adding cash to the drawn revolver amount.","EUR 37 million, adding cash to EUR 25 million undrawn capacity.","EUR 25 million, ignoring the cash already on hand."],"correct_index":2,"explanation":"Undrawn revolver capacity is 40 - 15 = EUR 25 million. The liquidity buffer is cash plus available undrawn capacity: 12 + 25 = EUR 37 million. Drawn debt is not additional unused capacity.","set":3},{"id":"fm-s9-q29","session":"9","topic":"Leverage downside","question":"A sponsor buys a company for EUR 200 million with EUR 140 million debt and EUR 60 million equity. At exit, enterprise value has fallen to EUR 160 million and debt is unchanged. Ignoring fees and dividends, what is the sponsor's equity loss percentage?","choices":["20.0%, equal to the decline in enterprise value.","40.0%, treating the value decline as a percentage of debt.","33.3%, treating EUR 20 million proceeds as the loss.","66.7%, since equity proceeds fall from EUR 60 million to EUR 20 million."],"correct_index":3,"explanation":"Exit equity is 160 - 140 = EUR 20 million. The equity loss is 60 - 20 = EUR 40 million, or 40 / 60 = 66.7%. Debt held flat magnifies the downside relative to the 20% fall in enterprise value.","set":3},{"id":"fm-s9-q30","session":"9","topic":"Coverage calculation","question":"An LBO company has EBITDA of EUR 90 million, capex of EUR 30 million and annual cash interest of EUR 20 million. A supplied covenant requires (EBITDA - capex) / interest of at least 2.5x. Does it meet that test?","choices":["No, because the ratio is 1.5x using capex divided by interest.","Yes, because the ratio is 3.0x after subtracting capex.","Yes, because the ratio is 4.5x when capex is ignored.","No, because the ratio is 0.33x using interest divided by available cash."],"correct_index":1,"explanation":"The specified coverage measure is (90 - 30) / 20 = 3.0x, above 2.5x. EBITDA / interest is a different metric and would ignore the capex deduction required by this covenant.","set":3}],"cg":[{"id":"cg-s1-q1","session":"1","topic":"Definitions of CG","question":"A report describes corporate governance as \"the system by which companies are directed and controlled\" and makes the board accountable to shareholders. Which source does this wording come from?","choices":["Shleifer & Vishny (1996)","Sheridan & Kendall (1992)","Cadbury Committee (1992)","Blair (1995)"],"correct_index":2,"explanation":"The quoted wording is the Cadbury definition, which places the board of directors at the centre as the accountable body. Shleifer & Vishny is the narrow finance view, Sheridan & Kendall is the broad stakeholder view and Blair describes the whole set of legal, cultural and institutional arrangements.","set":1},{"id":"cg-s1-q2","session":"1","topic":"Definitions of CG","question":"A student says \"governance only concerns how investors get their money back\". Which definition does this match, and why is it the narrowest one?","choices":["Shleifer & Vishny, because it covers only how suppliers of finance secure a return","Cadbury, because it limits governance to the decisions the board of directors takes","Sheridan & Kendall, because it ranks the owners' goals above all other interests","Blair, because it counts only securities and bankruptcy law as relevant arrangements"],"correct_index":0,"explanation":"Shleifer & Vishny (1996) say governance is about how suppliers of finance ensure a return on their investment. Cadbury centres on the board, Sheridan & Kendall add employees, community, customers and compliance, and Blair covers many institutions beyond securities and bankruptcy law.","set":1},{"id":"cg-s1-q3","session":"1","topic":"EssilorLuxottica case","question":"Delfin's bylaws require 88% approval for any decision. What governance risk does this create for the Del Vecchio heirs?","choices":["The widow can decide alone, because her block is the largest of the family","Outsiders can buy Delfin cheaply, because control needs only a simple majority","The EssilorLuxottica board picks the heirs' representatives, which ends the family's say","Near unanimity can paralyse family decision making despite undisputed ownership rights"],"correct_index":3,"explanation":"With capital split among eight heirs and an 88% threshold, no single branch can decide alone. Decisions need near unanimity, so concentrated control can produce deadlock even when nobody disputes who owns what.","set":1},{"id":"cg-s1-q4","session":"1","topic":"Meta / Zuckerberg case","question":"Zuckerberg holds about 13% of Meta's economic ownership but about 58% of the votes. Which feature explains this gap?","choices":["A pyramid of holding companies that multiplies his stake at each layer","Class B shares provide more votes per share than publicly held shares","A poison pill that gives him extra votes whenever a bid appears","A shareholder agreement that binds the other founders to vote with him"],"correct_index":1,"explanation":"Meta uses a dual-class structure and Zuckerberg owns 99.8% of the Class B shares. Votes and cash-flow rights are therefore separated. A pyramid, a poison pill or a shareholder agreement are different entrenchment tools and are not what the case describes.","set":1},{"id":"cg-s1-q5","session":"1","topic":"Public company","question":"A listed company is called a \"public company\" (PC) in this session. Which further condition must hold?","choices":["The State holds most shares and directs the listed company as a public asset","Ownership is fragmented, leaving each holder little incentive for active governance","Multiple share classes separate economic ownership from the listed company voting rights","Independent directors occupy most board seats and replace executive participation"],"correct_index":1,"explanation":"A PC is a listed company with fragmented ownership, where no single holder has a stake large enough to justify active governance. Listing alone does not make a company a PC in this sense.","set":1},{"id":"cg-s1-q6","session":"1","topic":"Shareholder behaviour in PCs","question":"Why do shareholders of a public company typically \"vote with their feet\" when they dislike governance decisions?","choices":["The law prevents small holders from voting on directors, leaving sale as their legal remedy","The board must repurchase shares from dissatisfied holders, making exit a guaranteed repayment","Selling shares creates fiduciary protection, while remaining invested removes that legal protection","Small holdings yield little monitoring benefit per holder, making exit cheaper than intervention"],"correct_index":3,"explanation":"With dispersed ownership each shareholder bears the full cost of intervening but gets only a tiny share of the benefit. Selling the shares is the rational response. Nothing in the law forbids voting or forces buybacks.","set":1},{"id":"cg-s1-q7","session":"1","topic":"Agency theory","question":"A principal expects the agent to act in its own interest when the two interests diverge. What follows for the principal?","choices":["It builds costly safeguards for delegation through contracts, controls and incentives","It gives the agent the residual control rights so that interests align automatically","It gives up delegating, because delegation always destroys value","It relies on the agent's utility maximising behaviour to produce aligned decisions"],"correct_index":0,"explanation":"Agency theory assumes both sides maximise utility, so the principal anticipates divergence and sets up safeguards. These safeguards are costly, which is the source of agency costs. Delegation still happens, and handing over residual rights would worsen the problem.","set":1},{"id":"cg-s1-q8","session":"1","topic":"Agency costs","question":"Shareholders pay for an annual audit, managers sign a contract limiting their perks, and some value is still lost because interests never align perfectly. In order, these three items are:","choices":["Bonding cost, monitoring cost, residual loss","Residual loss, bonding cost, monitoring cost","Monitoring cost, bonding cost, residual loss","Monitoring cost, monitoring cost, residual loss"],"correct_index":2,"explanation":"The principal pays monitoring costs such as audits. The agent pays bonding or guarantee costs to commit credibly. Residual losses are what remains after both. Perk limits that managers accept are bonding, not monitoring.","set":1},{"id":"cg-s1-q9","session":"1","topic":"Three ownership/board configurations","question":"A controlling family sits on the board and in management of a firm with other outside shareholders. Besides the classic shareholder and manager problem, which conflict now matters?","choices":["Creditors against shareholders over risky asset substitution after lending","Majority shareholders against minority shareholders over alignment of interests","Auditors against the board over the scope of their reporting duties","Dispersed holders against an index fund over how votes are cast"],"correct_index":1,"explanation":"With concentrated ownership and overlap between ownership, governance and management, a second agency problem appears between majority and minority shareholders. It is distinct from the shareholder and manager conflict of the first two configurations.","set":1},{"id":"cg-s1-q10","session":"1","topic":"Managerial misbehaviour","question":"One manager launches risky acquisitions that raise personal power but cut profitability. Another avoids every risky project and works the minimum. These behaviours are respectively:","choices":["Empire building and shirking","Shirking and empire building","Entrenchment and wealth extraction","Short termism and nepotism"],"correct_index":0,"explanation":"Empire building is risky growth over profitability to gain power, perks and pay. Shirking is the opposite failure mode, with overly risk-averse choices and minimal effort. Entrenchment is about defences against removal.","set":1},{"id":"cg-s1-q11","session":"1","topic":"Managerial misbehaviour","question":"A firm uses staggered boards, supermajority clauses and poison pills to shield its managers from removal. In which context is this entrenchment more likely, according to the course table?","choices":["Markets with intense competition and efficient financial discipline","Large firms with strong internal leadership and networking","Markets with weak competition and low operational discipline","Financial markets with limited development and takeover discipline"],"correct_index":3,"explanation":"The table pairs entrenchment with underdeveloped financial markets. Large firms with networking favour personal enrichment, and inefficient markets with low competition favour shirking.","set":1},{"id":"cg-s1-q12","session":"1","topic":"Historical failures","question":"Which case combined accounting fraud through off-balance-sheet entities and hidden debt with a board that failed to monitor and auditors who colluded?","choices":["Parmalat (2003)","WorldCom (2002)","Enron (2001)","Satyam (2009)"],"correct_index":2,"explanation":"Enron is the case of off-balance-sheet entities and hidden debt. Parmalat involved 14bn euro of fake assets, WorldCom about 11bn dollars of inflated earnings with weak internal controls, and Satyam about 1.5bn dollars of false reporting.","set":1},{"id":"cg-s1-q13","session":"1","topic":"Governance mechanisms","question":"How does a hostile takeover discipline underperforming management?","choices":["A raider acquires majority voting control through a tender offer, enabling management replacement","The existing owners negotiate a merger with management consent, enabling an agreed governance change","A shareholder gathers proxy votes without buying majority ownership, seeking a different board slate","Shareholders challenge directors through a fiduciary lawsuit, seeking remedies for breached duties"],"correct_index":0,"explanation":"The hostile route obtains voting control despite incumbent opposition through a tender offer. A negotiated agreement is the friendly route. Collecting proxies is a proxy fight, while a fiduciary lawsuit enforces duties. These are distinct mechanisms of management discipline.","set":1},{"id":"cg-s1-q14","session":"1","topic":"Blockholders","question":"A blockholder owns 30% of a listed company and can replace managers. Which statement is correct?","choices":["It always protects minorities, because its wealth is tied to firm value","Only institutional blockholders can ever expropriate minority shareholders","Having the power to replace managers means it cannot misuse that power","It can monitor effectively yet also exploit minority shareholders"],"correct_index":3,"explanation":"Blockholders have both the incentive and the power to monitor, but expropriation is as plausible as good monitoring. Institutional investors such as CalPERS or BlackRock are the typical example of good watchdogs, yet this is not automatic.","set":1},{"id":"cg-s1-q15","session":"1","topic":"LLSV framework","question":"In a country where the law protects shareholders and creditors weakly, which ownership pattern does the LLSV logic predict?","choices":["Dispersed ownership, because investors diversify away the legal risk","Concentrated ownership, because large holders protect themselves where the law will not","Dispersed ownership, because weak creditor rights push firms to raise equity widely","No clear pattern, because ownership is unrelated to legal origin"],"correct_index":1,"explanation":"Weak legal protection makes ownership concentration a substitute for law. Dispersed ownership becomes viable only where legal protection is strong. LLSV shows that protection varies systematically by legal origin.","set":1},{"id":"cg-s2-q1","session":"2","topic":"Shareholder view core assumptions","question":"A retailer invests in logistics efficiency mainly to lift profitability. In the shareholder view, how are employees, customers and suppliers treated?","choices":["As co-owners whose claims rank equally with those of shareholders","As residual claimants who share the profit left after debt is paid","As means to the end of shareholder value, not as ends in themselves","As agents who act for shareholders on the instructions of the board"],"correct_index":2,"explanation":"The core assumptions say stakeholders count only instrumentally. Shareholders are the residual claimants and managers are their agents, so the roles in the other options are assigned to the wrong parties.","set":1},{"id":"cg-s2-q2","session":"2","topic":"Shareholder view core assumptions","question":"What does it mean that shareholders are the \"residual claimants\" of a firm?","choices":["They are paid first, ahead of all contractual claims, because they own the firm","They control the board automatically through their claim on profit","They are protected against dilution when the firm issues new shares","They receive only what remains after debt, wages and taxes have been paid"],"correct_index":3,"explanation":"Residual claimants get the leftover after every other obligation is met. This makes them the most exposed to losses and the most interested in the firm's performance. It gives them no priority in payment, no automatic board control and no protection from dilution.","set":1},{"id":"cg-s2-q3","session":"2","topic":"Extended assumptions","question":"The extended assumptions of the shareholder view include efficient markets, a disciplining stock price, stock-based pay and a market for corporate control. How should they be read?","choices":["As facts shown to hold in every listed firm, so the argument is always valid","As necessary conditions whose failure weakens the case for shareholder value","As rules set by securities regulators that every listed firm must follow","As rights that stakeholders hold against the board and the shareholders"],"correct_index":1,"explanation":"The extended assumptions are not independent facts. The claim that maximising shareholder value is good for everyone holds only if they are true. If markets are inefficient or incentive pay fails to align interests, the argument weakens.","set":1},{"id":"cg-s2-q4","session":"2","topic":"Residual rights","question":"A contract is silent on whether a firm should cut its dividend. Who decides, and which right is used?","choices":["Shareholders use residual control rights, while income rights concern leftover profit","Managers decide, through residual income rights, since they run the firm every day","Creditors decide, through residual control rights, since they are paid before shareholders","Shareholders decide, through residual income rights, since the two rights are the same thing"],"correct_index":0,"explanation":"Residual control rights are the right to decide when a contract is silent or incomplete. Residual income rights are the claim on profit left after obligations. Both go to shareholders, but they are distinct rights.","set":1},{"id":"cg-s2-q5","session":"2","topic":"Nexus of contracts","question":"Why do ownership rights become the key governance mechanism in a nexus of contracts?","choices":["Shareholders hold residual control because their contracts guarantee payment before all other stakeholders","Ownership replaces the board because complete contracts already settle every possible decision","Managers receive ownership automatically because explicit contracts cannot govern any management decision","Ownership allocates residual decision rights because contracts cannot specify every future contingency"],"correct_index":3,"explanation":"Because contracts are incomplete, ownership rights handle what contracts do not specify. Shareholders get the residual control rights because they receive the residual income and are exposed to expropriation when contracts have gaps.","set":1},{"id":"cg-s2-q6","session":"2","topic":"General Electric case","question":"After years of poor results at General Electric in 2018, how did shareholders use their residual control rights?","choices":["They sold their shares in bulk and let the falling price discipline management","They changed directors, pushed CEO removal and approved restructuring","They took the board to court for breach of fiduciary duty","They approved a dual-class recapitalisation to protect the founders"],"correct_index":1,"explanation":"In the General Electric example shareholders acted from inside, replacing directors, pushing out the CEO and approving a restructuring. This is use of control rights, not exit.","set":1},{"id":"cg-s2-q7","session":"2","topic":"Limits of ownership rights","question":"How does the course describe ownership rights as a governance solution?","choices":["A full solution, because giving the rights to shareholders removes agency costs","A full solution in common law countries, where courts enforce contracts efficiently","A governance tool without guarantees, since controllers can exploit contract gaps","Irrelevant, since contracts already cover every possible situation"],"correct_index":2,"explanation":"Ownership rights help to mitigate conflicts and agency costs, but contracts are incomplete and courts and markets are imperfect. Controlling shareholders can themselves expropriate other stakeholders.","set":1},{"id":"cg-s2-q8","session":"2","topic":"Property vs social entity","question":"A board says it exists to balance profit with social and environmental goals for many stakeholders. In the social entity conception, what is the managers' role?","choices":["Trustees who balance the interests of several stakeholders","Agents who maximise value for shareholders only","Residual claimants who keep the profit left after obligations","Representatives of the State who set social goals for the firm"],"correct_index":0,"explanation":"In the social entity conception the firm is a social institution and managers are trustees balancing diverse interests. In the property conception they are agents of shareholders.","set":1},{"id":"cg-s2-q9","session":"2","topic":"Property vs social entity","question":"Which pairing of company and conception of the firm does the course use as its illustration?","choices":["ExxonMobil for the social entity conception and Unilever for the property conception","Apple for the social entity conception and ExxonMobil for the property conception","Unilever for both conceptions, since its plan covers shareholders and stakeholders","ExxonMobil for the property conception and Unilever for the social entity conception"],"correct_index":3,"explanation":"ExxonMobil, with its focus on shareholder returns, illustrates the property conception. Unilever's Sustainable Living Plan, which balances profit with social and environmental goals, illustrates the social entity conception.","set":1},{"id":"cg-s2-q10","session":"2","topic":"Stakeholder map","question":"A local community protests a new plant to defend its \"social license to operate\". Which type of stakeholder power does this illustrate?","choices":["Equity voting power, using ownership to influence corporate resolutions","Political and regulatory power, using taxes and formal public licences","Environmental and social power, using community legitimacy and opposition","Economic contractual power, using employment or supplier trading relationships"],"correct_index":2,"explanation":"The stakeholder map lists local communities defending their social license to operate under environmental and social power. Formal licences issued by authorities belong to political and regulatory power, which is a different channel.","set":1},{"id":"cg-s2-q11","session":"2","topic":"Stakeholder map","question":"A pension fund uses its shares to remove two directors and to approve a merger. Which type of stakeholder power is this?","choices":["Voting power, exercised through the rights attached to equity stakes","Economic power, exercised through labour or supply contracts","Political and regulatory power, exercised through taxes and subsidies","Environmental and social power, exercised through sustainability demands"],"correct_index":0,"explanation":"Voting power comes from equity stakes and includes electing or removing board members and approving dividends, M&A and by-law changes.","set":1},{"id":"cg-s2-q12","session":"2","topic":"Four definitions of CG's purpose","question":"A commentator argues that, in practice, governance serves managers' empire building, perks and job security. Which of the four definitions of corporate governance does this match?","choices":["The shareholder definition","The managerial definition","The stakeholder definition","The firm definition"],"correct_index":1,"explanation":"The managerial definition puts managers' own interests at the centre, and the lecture cites Enron as an example of managerial capture. The shareholder definition stresses shareholder value, the stakeholder definition balances all interests and the firm definition stresses the firm's own survival and competitiveness.","set":1},{"id":"cg-s2-q13","session":"2","topic":"Business Roundtable 2019","question":"What was the 2019 Business Roundtable statement signed by 181 CEOs?","choices":["A binding amendment to US corporate law requiring duties to stakeholders","An SEC rule forcing firms to disclose their spending on stakeholders","A shareholder resolution that removed profit as a corporate goal","A voluntary shift toward stakeholders without changing corporate law"],"correct_index":3,"explanation":"The statement redefined corporate purpose toward stakeholder capitalism, echoed by Larry Fink of BlackRock. It is voluntary and does not change corporate law, so treating it as binding is a listed exam trap.","set":1},{"id":"cg-s2-q14","session":"2","topic":"Exam traps","question":"What is the structural difference between the property and the social entity conceptions of the firm?","choices":["How firms allocate charitable spending among employees, customers and local communities","Whether governance uses a board or replaces it with stakeholder meetings","Who assets belong to and whether managers are shareholder agents or stakeholder trustees","Whether firms may earn profits or must reinvest every surplus in social projects"],"correct_index":2,"explanation":"The conceptions differ structurally. In the property conception the assets belong to shareholders and managers are their agents. In the social entity conception the assets serve several stakeholders and managers are trustees. The difference is not simply how nice the firm is.","set":1},{"id":"cg-s3-q1","session":"3","topic":"Enron business model","question":"Which change set Enron apart from a traditional energy utility?","choices":["It moved from trading into production, buying more power plants and gas pipelines","It moved from production into trading, centred on derivatives and financial engineering","It moved from private to State ownership, which secured cheaper long term financing","It dropped long term contracts and relied on spot sales to reduce its commitments"],"correct_index":1,"explanation":"Enron shifted from energy production to energy trading and became a trading house. It focused on financial engineering and derivatives rather than core operations.","set":1},{"id":"cg-s3-q2","session":"3","topic":"Mark-to-market accounting","question":"Enron signs a 20-year contract to supply gas. How did its accelerated earnings method inflate reported profit?","choices":["It recognised estimated lifetime contract profit immediately, rather than as gas was delivered","It recognised revenue only on cash collection, postponing all early contract earnings","It recorded every contract expense twice, making later reported profits appear higher","It exchanged contract debt for equity, eliminating the associated interest expense"],"correct_index":0,"explanation":"Under mark-to-market, Enron recognised the whole estimated future profit immediately. Reported profit lost its link with cash flow and could stay on the books even if the contract later lost money.","set":1},{"id":"cg-s3-q3","session":"3","topic":"Mark-to-market accounting","question":"A student claims mark-to-market accounting is fraudulent in itself. How does the course correct this?","choices":["The technique itself was illegal on every long contract, regardless of measurement and disclosure","The technique became globally prohibited after Enron, regardless of asset type and market information","Enron did not use the technique, so the course attributes every reported profit solely to SPEs","The abuse lay in Enron's application and estimated contract profits, not inherent illegality of the technique"],"correct_index":3,"explanation":"The fiche warns that the technique is not the fraud. The problem was the application, which disconnected profit from actual cash flows. SPEs were a second, separate tool used together with it.","set":1},{"id":"cg-s3-q4","session":"3","topic":"Special Purpose Entities","question":"How did Enron abuse Special Purpose Entities?","choices":["It paid higher dividends through them to push up the share price","It used them for risk management and disclosed every liability","It moved debt into them and reported only the profits from the arrangements","It folded them back into its accounts each quarter to show consolidated losses"],"correct_index":2,"explanation":"Enron transferred debt to SPEs to keep it off its own balance sheet and reported only the profits. Complex and opaque structures discouraged banks and auditors from asking questions. Using SPEs for risk management with full disclosure is their legitimate purpose, not the abuse.","set":1},{"id":"cg-s3-q5","session":"3","topic":"Why banks failed to scrutinize Enron","question":"Which explanation does the course give for banks failing to do adequate due diligence on Enron's SPEs?","choices":["A rule barred banks from examining the off-balance-sheet vehicles of a client company","The banks earned fees, underestimated reputational risk and faced opaque structures","Arthur Andersen had certified the SPEs, which legally replaced checks by the banks","The banks held no exposure to Enron and so saw no reason to look closely at its SPEs"],"correct_index":1,"explanation":"The three reasons are conflicts of interest because banks earned fees, underestimated reputational risk and complexity and opacity. No legal bar prevented the checks.","set":1},{"id":"cg-s3-q6","session":"3","topic":"Enron governance failures","question":"Along with the board, which auditor failed to challenge Enron's management?","choices":["Deloitte audit firm","KPMG audit firm","PwC audit firm","Arthur Andersen firm"],"correct_index":3,"explanation":"The course names Arthur Andersen as the auditor that, together with the board, failed to challenge Enron's management.","set":1},{"id":"cg-s3-q7","session":"3","topic":"Theranos business model","question":"What did Theranos claim its technology could do?","choices":["Run hundreds of blood tests from a single finger prick sample","Replace laboratory staff with robots and halve testing costs","Replace blood tests with a software model that predicts disease from health records","Screen for cancer from a single saliva sample"],"correct_index":0,"explanation":"Theranos promised to revolutionise healthcare with hundreds of blood tests from a finger prick. In 2015 investigations showed the technology never worked as advertised.","set":1},{"id":"cg-s3-q8","session":"3","topic":"Theranos vs Enron","question":"What is the key structural difference between the Theranos fraud and the Enron fraud?","choices":["Theranos relied on SPEs while Enron relied on a secret technology","Theranos had many public shareholders while Enron was privately held","Theranos rested on false scientific claims, while Enron rested on accounting manipulation","Theranos had a broad executive team while Enron was driven by one founder"],"correct_index":2,"explanation":"The Theranos fraud was tied to scientific and technical claims, not accounting tricks. Theranos was also pre-IPO with no widespread public shareholders and was heavily founder-driven. The other options reverse these facts.","set":1},{"id":"cg-s3-q9","session":"3","topic":"Theranos vs Enron","question":"Which description fits Theranos as the lecture contrasts it with Enron and Satyam?","choices":["Listed, with a large public shareholder base and a broad executive team","Pre IPO and founder driven, without a widespread public shareholder base","Audited by Arthur Andersen, which failed to challenge the founder","Built on accounting tricks rather than on technical claims"],"correct_index":1,"explanation":"Theranos was early-stage and pre-IPO, with no widespread public investors, and heavily founder-driven. Its fraud concerned technology, not accounting. Arthur Andersen is linked to Enron.","set":1},{"id":"cg-s3-q10","session":"3","topic":"Theranos governance failures","question":"Why could the Theranos board not effectively challenge Elizabeth Holmes's claims?","choices":["Loyalty to Holmes combined with inadequate medical and biotech expertise","It was legally barred from questioning the founder's technical statements","It had many medical experts who chose to stay silent","It met only once a year and so never saw the test results"],"correct_index":0,"explanation":"The fiche says the board was loyal to Holmes but inexperienced in biotechnology, so even a well-meaning board could not evaluate the claims. The cause is lack of relevant expertise combined with loyalty, not a legal bar.","set":1},{"id":"cg-s3-q11","session":"3","topic":"Investor behaviour at Theranos","question":"What role did fear of missing out play in the Theranos case?","choices":["It pushed investors to demand peer reviewed validation before investing","It made investors sell their stakes once the secrecy was noticed","It had no effect, because the company relied on public market scrutiny","It led venture firms and wealthy individuals to invest with weak due diligence"],"correct_index":3,"explanation":"Investors were eager to join the next big thing, and FOMO led to weak due diligence. Theranos relied on private capital and had no early public market scrutiny.","set":1},{"id":"cg-s3-q12","session":"3","topic":"Common thread across both cases","question":"Despite very different fraud mechanisms, what governance failure do Enron and Theranos share?","choices":["Both boards had too many independent directors who lacked time","Both frauds were uncovered by internal auditors before any outside report","Oversight structures failed to challenge a dominant management figure or story","Both firms were State-owned, so private investors had little say"],"correct_index":2,"explanation":"Both cases are governance failures because boards and oversight structures failed to challenge a dominant management figure or narrative. The mechanisms differed, accounting engineering at Enron and false scientific claims at Theranos.","set":1},{"id":"cg-s3-q13","session":"3","topic":"SPE mechanics","question":"In the simplified example, Enron borrows 1 billion dollars through an SPE. What does Enron's own balance sheet show?","choices":["The cash inflow, with debt in the SPE but risk retained","The full debt of 1 billion together with the cash inflow","Neither the cash inflow nor the debt, so the loan does not appear","A liability twice the size of the loan, to reflect the guarantee to the SPE"],"correct_index":0,"explanation":"In the example the SPE holds the debt and Enron shows only the cash inflow. The balance sheet looks clean but the underlying risk remains Enron's.","set":1},{"id":"cg-s3-q14","session":"3","topic":"Syllabus vs actual content","question":"The syllabus lists lecture 3 as \"Global governance failure: Enron\". A student prepares only Enron. What is missing, according to the fiche?","choices":["Parmalat, which the fiche covers instead of the parallel Theranos case","Theranos, which the slides and fiche develop alongside the Enron case","WorldCom, which the fiche develops as a third detailed SPE case","Nothing, since the slides and fiche cover only the Enron case"],"correct_index":1,"explanation":"The syllabus mentions only Enron, but the slides are titled Enron and Theranos and cover both. The slides are the primary source in case of a gap.","set":1},{"id":"cg-s47-q1","session":"4-7","topic":"Board roles","question":"A board approves a new strategic plan, reviews management's results and meets key investors to protect the company's reputation. Which three board tasks does this show?","choices":["Operational, financial, compliance","Strategic, executive, audit","Monitor, networking, operational","Strategic, monitor, networking"],"correct_index":3,"explanation":"Approving the plan is the strategic task, reviewing management is the monitor task and managing relationships with investors and key stakeholders is the networking task. Running operations is a management job, not a board task.","set":1},{"id":"cg-s47-q2","session":"4-7","topic":"Why boards aren't automatically effective","question":"A new director complains that the board meets rarely and receives only summaries chosen by management. Which view of boards does this support?","choices":["Boards are effective by definition because they stand detached from daily operations","Board effectiveness depends on actual working practices rather than formal status alone","Boards have no real authority, because the law gives them only an advisory role","Boards should be replaced by shareholder votes on every major decision"],"correct_index":1,"explanation":"The course lists the limits in practice: irregular and infrequent meetings, information that is limited or biased by management, uncertain impact and no consensus on priorities. The conclusion is that effectiveness depends on working practice.","set":1},{"id":"cg-s47-q3","session":"4-7","topic":"Director types","question":"A director also serves as the company's finance chief. Which type of director is this?","choices":["Executive (inside) director","Independent director","Non-executive (outside) director","Lead independent director"],"correct_index":0,"explanation":"Executive or inside directors hold management roles in the firm. Non executive directors hold none, and independent directors are non-executives free of compromising ties.","set":1},{"id":"cg-s47-q4","session":"4-7","topic":"Board size","question":"One board has 25 members and decides slowly, while another has 3 members and lacks technical expertise. What principle does this illustrate?","choices":["Larger boards are always better because they bring more expertise","Size is irrelevant, because only the share of independent directors counts","Size balances skills and efficiency, avoiding inadequate expertise or slow decisions","The best board is the smallest possible, since advisers can supply any expertise"],"correct_index":2,"explanation":"The course says size depends on firm size, ownership structure and industry. A small board lacks expertise, a large one loses efficiency, so the aim is the right size with the right mix of skills. The slides give 7 to 15 members as an ideal range.","set":1},{"id":"cg-s47-q5","session":"4-7","topic":"CEO duality","question":"One person is both CEO and Chairman of a company. What is this called, and what is the main risk?","choices":["CEO duality, with a risk of indecision between two leaders","A lead independent directorship, with a risk of weak oversight","CEO duality, with a risk of excessive concentration of power","A board interlock, with a risk of conflicts in financial reporting"],"correct_index":2,"explanation":"CEO duality means one person holds both the CEO and Chairman roles. It can give strong leadership but risks excessive concentration of power.","set":1},{"id":"cg-s47-q6","session":"4-7","topic":"Lead Independent Director","question":"According to the lecture, when is a Lead Independent Director appointed, and for what purpose?","choices":["When CEO duality exists, to provide checks and balances","When the board has fewer than seven members, to add expertise","When no director is independent, to replace the audit committee","When the Chairman is a non-executive, to chair the meetings"],"correct_index":0,"explanation":"The Lead Independent Director role exists when one person is both CEO and Chairman. Its effectiveness depends on the person's real independence and involvement.","set":1},{"id":"cg-s47-q7","session":"4-7","topic":"Board effectiveness framework","question":"Which combination produces board effectiveness in the overall framework?","choices":["Structure and composition alone, with working processes assumed to have no effect","Independence, committees and size alone, with board roles assumed to be equivalent","Stakeholder pressure, regulation and size alone, without internal board working practices","Structure, working processes and board roles together, influenced by contingent conditions"],"correct_index":3,"explanation":"Effectiveness comes from the interaction of input, processes and board roles, shaped by contingent variables such as firm size and ownership structure and by stakeholder and regulatory pressure.","set":1},{"id":"cg-s47-q8","session":"4-7","topic":"Independence vs process","question":"Enron, Theranos and WorldCom all had a majority of outside directors. What does the course conclude?","choices":["Independent directors raise the risk of failure, so firms should prefer insider directors","Independence is necessary but not sufficient, because people and board functioning drive effectiveness","The independence ratio is the best single predictor of board quality across firms","Outsider majorities became common only after 2008 and did not exist at these firms then"],"correct_index":1,"explanation":"The slides say independence alone is not enough, since many failed firms had outsider majorities. What drives effectiveness is interaction, dynamics and decision making.","set":1},{"id":"cg-s47-q9","session":"4-7","topic":"Effective board behaviour","question":"How should an effective board deal with disagreement with the CEO?","choices":["Through constructive conflict, with open debate focused on the decision","By avoiding conflict, to keep the team cohesive","By deferring to the CEO on strategy and monitoring only the results","By voting unanimously by default, to show unity to investors"],"correct_index":0,"explanation":"The course describes constructive, not destructive, conflict especially with the CEO. The board still works as a cohesive team. Avoiding debate leads to the board silence the course warns against.","set":1},{"id":"cg-s47-q10","session":"4-7","topic":"Board information","question":"Directors receive only last quarter's profit figures, sent the evening before the meeting. Which requirement is not met?","choices":["Information should come only from the CEO, so that directors receive a single version","Information should be minimal, since directors set their own agenda and ask when needed","Information should be timely, complete and reliable, covering results, budgets and strategy","Information should cover financial results only, since strategy belongs to management alone"],"correct_index":2,"explanation":"The information dimension requires timely, complete and reliable information on financial results, budgets, strategy and competition. Late and narrow information fails this test.","set":1},{"id":"cg-s47-q11","session":"4-7","topic":"Board evaluation","question":"In the 2018 Italian sample of 202 companies, which pair describes the board reviews?","choices":["24% did a review and 84% signalled specific improvements","84% did a review and 24% signalled specific improvements","84% did a review and 27% signalled specific improvements","27% did a review and 24% used an external advisor"],"correct_index":1,"explanation":"84% of companies made a board review, supported by an external advisor in 27% of cases. Only 24% of companies signalled specific improvements in their governance.","set":1},{"id":"cg-s47-q12","session":"4-7","topic":"Board evaluation with advisors","question":"Informal meetings and induction improved at 35.6% of firms with an external advisor and 4.1% without one. What does this show?","choices":["Advisors make no difference, since both improvement rates are low in absolute terms","Advisors reduce reported improvements, because they find fewer issues to fix","Advisors cause improvement in every area, so every firm should hire an advisor","Advisors were associated with higher improvement rates, without proving cause"],"correct_index":3,"explanation":"The table shows higher improvement rates with an advisor in every area. It reports an association between advisors and reported improvements, not proof that advisors cause them.","set":1},{"id":"cg-s47-q13","session":"4-7","topic":"Board evaluation exam trap","question":"Which risk does the course flag for board self-assessments?","choices":["They are barred by Italian law for all listed companies and their boards","They are more rigorous than external reviews and therefore too costly for most firms","They need shareholder approval before directors can read the results of the review","Self assessments can lack a genuinely independent super partes attitude"],"correct_index":3,"explanation":"Among the challenges of board reviews are self-serving assessments and a frequent lack of true independence. This is why reviews should go beyond box-ticking.","set":2},{"id":"cg-s47-q14","session":"4-7","topic":"Hard law vs soft law","question":"What distinguishes hard law from soft law in board regulation?","choices":["Hard law is set by shareholders and soft law by regulators","Hard law covers private companies only and soft law covers listed companies only","Hard law binds legally, while soft law provides voluntary governance codes","Hard law is voluntary guidance and soft law is binding legislation"],"correct_index":2,"explanation":"Hard law means binding rules such as the Civil Code. Soft law means self-regulatory Corporate Governance Codes adopted voluntarily by listed companies.","set":2},{"id":"cg-s47-q15","session":"4-7","topic":"Comply or explain","question":"A listed company does not follow one recommendation of its Corporate Governance Code. What is it expected to do?","choices":["Disclose its noncompliance reasons under the voluntary governance Code","Pay a legal penalty, since Codes are binding rules","Nothing, since the Code has no disclosure duty","Ask a court for permission, since only financial firms may deviate"],"correct_index":0,"explanation":"Under comply or explain, listed firms must disclose why they do not comply. They are not legally forced to comply, so treating Codes as binding is an exam trap.","set":2},{"id":"cg-s47-q16","session":"4-7","topic":"Board vs TMT","question":"Who develops the strategy and business plan, and who reviews and approves it?","choices":["The board develops the plan, then the CEO led TMT critically reviews and approves it","The CEO led TMT develops the plan, then the board critically reviews and approves it","The CEO led TMT develops and approves the plan, then the board receives it for information","The Chairman develops the plan alone, then shareholders critically review and approve it"],"correct_index":1,"explanation":"The board gives guidelines and oversight. The TMT led by the CEO develops strategies and business plans, which are submitted to the board for approval and critical review.","set":2},{"id":"cg-s47-q17","session":"4-7","topic":"Independent director definition","question":"Which description fits an independent director?","choices":["Any director who does not hold the CEO position in the company or its subsidiaries","A non-executive director chosen by the controlling shareholder to represent its interests","A non-executive director with no financial, professional or personal ties affecting judgment","An executive director with no family ties to the CEO or to the controlling shareholder"],"correct_index":2,"explanation":"An independent director is non-executive and free of ties that may compromise independent judgment. A significant shareholder's representative or an executive does not meet this.","set":2},{"id":"cg-s47-q18","session":"4-7","topic":"Independence thresholds","question":"A director has sat on the board for 10 of the last 12 years, not consecutively. What do the Italian Code examples conclude?","choices":["Independence is compromised, since service above 9 years counts even if not consecutive","Independence is intact, since only consecutive service counts","Independence is compromised only after 15 years","Independence is compromised only if the director also held an executive role in the last 3 years"],"correct_index":0,"explanation":"The tenure rule is more than 9 years of service, even non-consecutive, within the last 12. It is separate from the 3-year look-back used for executive roles, significant relations and extra pay.","set":2},{"id":"cg-s47-q19","session":"4-7","topic":"Independence-compromising ties","question":"Which situation compromises a director's independence according to the Italian Code examples?","choices":["Having studied at the same university as the CEO several years earlier","Living in the city where the company has its headquarters and main offices","Having worked for a competitor more than 10 years before the appointment","Significant extra pay beyond board fees during the previous three years"],"correct_index":3,"explanation":"Significant additional remuneration in the last 3 years is on the list. The other situations are not listed as compromising independence.","set":2},{"id":"cg-s47-q20","session":"4-7","topic":"Chairman vs CEO roles","question":"According to the lecture, who sets the board agenda and chairs its meetings, and what executive power does that person hold?","choices":["The CEO, with full executive power over the board's work","The Chairman, with no executive powers except information rights","The Chairman, with executive powers equal to the CEO's","The Lead Independent Director, with power over daily management"],"correct_index":1,"explanation":"The Chairman organises the board's work, sets the agenda and chairs meetings, with no executive powers except information rights. The CEO manages within delegated powers.","set":2},{"id":"cg-s47-q21","session":"4-7","topic":"Board committees","question":"Directors want a committee to oversee internal controls, risk management and financial reporting. Which one?","choices":["The Appointments Committee body","Audit & Risk Committee","The Remuneration Committee body","The Sustainability Committee body"],"correct_index":1,"explanation":"The Audit & Risk Committee oversees internal controls, risk management and financial reporting. Appointments covers nominations and succession, Remuneration covers pay and Sustainability covers ESG issues.","set":2},{"id":"cg-s47-q22","session":"4-7","topic":"Board activities","question":"How often does a board typically meet, and what preparation is expected of directors?","choices":["2 to 3 times a year, with no preparation, since the CEO briefs at the meeting","12 to 15 times a year, with one week of study each time","Once a quarter for 8 to 10 hours, with papers handed out at the meeting","6 to 8 yearly meetings lasting 2 to 4 hours, plus 0.5 to 1 preparation day"],"correct_index":3,"explanation":"The course gives 6 to 8 meetings a year of 2 to 4 hours each. Directors receive documents in advance and are expected to study them for half a day to a day.","set":2},{"id":"cg-s47-q23","session":"4-7","topic":"Gender gap timeline","question":"Which Italian instrument first introduced mandatory gender quotas in boards and control bodies?","choices":["The 2011 Golfo-Mosca Law","The 2018 Corporate Governance Code","The 2020 Budget Law","The 2020 Code update"],"correct_index":0,"explanation":"The 2011 Golfo-Mosca Law introduced the mandatory quotas. The 2018 Code only recommended reserving seats, and the 2020 Budget Law tightened the quotas.","set":2},{"id":"cg-s47-q24","session":"4-7","topic":"Gender gap 2020 changes","question":"What did the 2020 Budget Law change in the Italian gender quotas?","choices":["It reduced the quota to 33% and shortened its application to three mandates","It removed mandatory quotas and replaced them with voluntary board recommendations","It raised the quota to 40% and extended its application to six mandates","It imposed a 50% quota on every private firm, regardless of listing status"],"correct_index":2,"explanation":"The 2020 Budget Law extended quotas to six mandates and raised the requirement to at least 40%. The 2020 Code update still refers to 33% for boards.","set":2},{"id":"cg-s47-q25","session":"4-7","topic":"Gender pay gap trend","question":"In the Italian data for 2012 to 2017, what happened to the director gender pay gap, and why?","choices":["It narrowed, as more female executive directors received higher average pay","It stayed unchanged, as female executive and independent director pay rose together","It widened, as female executive average pay fell despite rising representation","It reversed, as female independent directors came to earn more than men"],"correct_index":2,"explanation":"The lecture reports a wider gap. More women became executive directors, but their average pay fell. Independent female directors became more numerous with only a small pay rise. Representation gains therefore did not establish pay convergence.","set":3},{"id":"cg-s47-q26","session":"4-7","topic":"Board tasks vs TMT","question":"Which body approves the strategic plan, sets the organisational and control systems and defines directors' remuneration?","choices":["The board, which approves key plans, systems and remuneration decisions","The TMT, which handles these decisions and only reports them afterwards","External auditors, who approve strategy, internal organisation and director remuneration","The remuneration committee, which has final authority over all three decisions"],"correct_index":0,"explanation":"The board is not only a formal body. It approves strategic plans and key decisions, sets organisational and control systems and defines directors' remuneration. Committees prepare proposals for it.","set":3},{"id":"cg-s47-q27","session":"4-7","topic":"Diversity","question":"How does the course define diversity on a board?","choices":["A legal quota for gender only, set by law and checked by the regulator every year","A balance of ages and lengths of tenure, so that no single cohort dominates the board","A range of shareholder types on the board, so that every large holder has a seat","A mix of competences, gender and nationality, professional backgrounds and leadership styles"],"correct_index":3,"explanation":"Diversity covers competences and knowledge, gender and nationality balance, varied professional backgrounds and different leadership styles. Gender quotas are only one part of it.","set":3},{"id":"cg-s47-q28","session":"4-7","topic":"Committee composition","question":"Who decides the tasks and composition of a board committee?","choices":["Shareholders, by direct vote at the meeting","The board, based on members' competence and experience","The CEO alone, to match the needs of management","The regulator, with the same list for all firms"],"correct_index":1,"explanation":"The board defines the committees' tasks and composition, with priority to competence and experience. Committees have investigative, advisory and preparatory roles.","set":3},{"id":"cg-s47-q29","session":"4-7","topic":"Board's market relations responsibility","question":"Which task falls under the board's responsibility for relations with the market?","choices":["Open, timely communication with investors and equal access to information","Negotiating supplier prices and payment terms to improve the company's margins","Briefing a few selected analysts first, to protect the share price after results","Approving promotions and pay rises for middle managers in the business units"],"correct_index":0,"explanation":"Relations with the market, for example through investor relations, mean transparent and timely communication and equal access to information. Early briefing of selected analysts would break equal access.","set":3},{"id":"cg-s47-q30","session":"4-7","topic":"Independence re-assessment","question":"How often is a director's independence assessed?","choices":["Only at appointment, after which it is considered permanent","Every 3 years, in line with the look back period of the rule","At appointment, every year, and whenever relevant circumstances arise","Every 9 years, at the end of the tenure limit set in the Code"],"correct_index":2,"explanation":"Independence is assessed at appointment and re-assessed annually, with ongoing monitoring if relevant circumstances arise.","set":3},{"id":"cg-s47-q31","session":"4-7","topic":"CEO duality prevalence","question":"Where is CEO duality common, and where is it rare?","choices":["Common in the UK and rare in the US","Equally common in the US and the UK","Rare in both the US and the UK","Common in the US and rare in the UK"],"correct_index":3,"explanation":"The course describes CEO duality as common in the US and rare in the UK.","set":3},{"id":"cg-s47-q32","session":"4-7","topic":"Networking task","question":"A board member meets major shareholders and stakeholders to defend the firm's reputation. Which task is this?","choices":["Strategic task, because it defines the mission and vision","Networking task, because it manages reputation and key relationships","Monitor task, because it oversees management behaviour","Executive task, because it manages daily operations"],"correct_index":1,"explanation":"The networking task enhances reputation and legitimacy and manages relationships with shareholders and key stakeholders. Daily operations belong to management.","set":3},{"id":"cg-s47-q33","session":"4-7","topic":"Monitor task","question":"Which activity belongs to the board's monitor task?","choices":["Defining the mission and vision of the company and its strategic direction","Building the company's reputation and relationships with key stakeholders","Overseeing management conduct and performance against strategic objectives","Running the company day to day within the powers delegated by the board"],"correct_index":2,"explanation":"The monitor task is about overseeing performance and management behaviour, covering operational and strategic objectives. Mission and vision are strategic, reputation is networking and running operations is for the CEO.","set":3},{"id":"cg-s47-q34","session":"4-7","topic":"Board evaluation scope","question":"Which set describes what a board evaluation typically assesses?","choices":["Board composition and functioning, strategy and monitoring roles, internal control and risk management","CEO performance and share price alone, leaving board processes and internal control outside the review","Shareholder satisfaction and dividend yield alone, leaving composition and board effectiveness outside the review","Attendance and director fees alone, leaving strategy, monitoring and internal control outside the review"],"correct_index":0,"explanation":"The scope covers board size and composition, functioning of the board and committees, the role in defining strategy and monitoring management, and internal control and risk management systems.","set":3},{"id":"cg-s47-q35","session":"4-7","topic":"Hard law examples","question":"Which of these is an example of hard law for boards, as opposed to soft law?","choices":["A national Corporate Governance Code","The Consolidated Law on Finance","An investor association's best practice guideline","An ESG rating agency's scoring method"],"correct_index":1,"explanation":"The Civil Code and the Consolidated Law on Finance are the course's examples of hard law. Governance Codes are soft law.","set":3},{"id":"cg-s47-q36","session":"4-7","topic":"Independence exam trap","question":"A student applies the 3-year rule to a director's board tenure. What is the error?","choices":["The 3 year rule applies only to family ties and to links with the auditor network","The two rules are the same one, and both apply to every circumstance on the list","Tenure is not an independence criterion in the Italian Code examples in the course","Tenure has its own test, over 9 years in the last 12, while 3 years covers other links"],"correct_index":3,"explanation":"The thresholds apply to different circumstances. The 3-year look-back covers executive roles, significant relations and extra remuneration. Board tenure uses more than 9 years, even non-consecutive, within the last 12.","set":3},{"id":"cg-s9-q1","session":"9","topic":"Models of capitalism","question":"A country has competitive, transparent financial markets, dispersed ownership with growing institutional investors and relatively easy hostile takeovers. Which governance model is this?","choices":["German/Japanese model, a network oriented insider system with bank influence","Anglo-Saxon model, an outsider system oriented toward competitive financial markets","Latin model, a system dominated by the State and by controlling families","Anglo-Saxon model, an insider system where banks hold most of the shares"],"correct_index":1,"explanation":"These traits describe the Anglo-Saxon outsider system (USA, UK, Canada, Australia), where markets monitor managers. The German/Japanese model is a network-oriented insider system, and the Latin model relies on State and family control.","set":1},{"id":"cg-s9-q2","session":"9","topic":"Models of capitalism","question":"In the German/Japanese model, what role do banks typically play in governance?","choices":["They are barred from holding equity and only lend to firms in the country","They hold small stakes and leave most monitoring to the stock market","They act mainly as short term lenders with weak ties to the firms they fund","They play a central role and often act as controlling shareholders themselves"],"correct_index":3,"explanation":"In the insider German/Japanese system, banks play a central role, often as controlling shareholders, alongside industrial groups and cross-shareholdings. In the Latin model banks are mainly important for debt financing.","set":1},{"id":"cg-s9-q3","session":"9","topic":"Models of capitalism","question":"Most firms in a country are controlled by families through pyramids, the State acts as shareholder and financer, and financial markets play a limited role. Which model is this?","choices":["Latin model, as in Italy, France, Spain and Greece","Anglo-Saxon model, since the State regulates the markets","German/Japanese model, since groups hold cross-shareholdings","Anglo-Saxon model, since pyramids are common in the US"],"correct_index":0,"explanation":"The Latin model has a strong State, family control, frequent pyramidal groups and shareholder agreements, with limited financial markets. The Anglo-Saxon model relies on markets and dispersed ownership.","set":1},{"id":"cg-s9-q4","session":"9","topic":"Control-Enhancing Mechanisms","question":"What defines a Control Enhancing Mechanism (CEM)?","choices":["A legal rule that bans every hostile takeover of listed companies in a given country","A tax rule that rewards controlling holders for paying out dividends each year","A tool giving controlling shareholders more votes than their cash flow rights justify","An accounting method that consolidates subsidiaries into the group results of the parent"],"correct_index":2,"explanation":"CEMs let shareholders, typically controlling ones, exercise voting power disproportionate to cash-flow rights. The three forms are deviations from one share one vote, shareholders' agreements and pyramidal groups.","set":1},{"id":"cg-s9-q5","session":"9","topic":"Pyramidal groups math","question":"Shareholder A owns 51% of Company B, and B owns 51% of Company C. What does A hold in C?","choices":["51% of both the votes and the cash-flow rights, since control passes along the chain","26% of both the votes and the cash-flow rights, since both are multiplied","No control, because A has no direct stake in C","Control of C's votes through B, but only about 26% of C's cash-flow rights"],"correct_index":3,"explanation":"A controls B and B controls C, so A exercises 51% of the votes in C. Cash flow rights multiply, 51% times 51% gives about 26% of C's equity. This gap is what makes the pyramid a CEM.","set":1},{"id":"cg-s9-q6","session":"9","topic":"CEM legality","question":"Are Control Enhancing Mechanisms inherently illegal?","choices":["Yes, they are a form of securities fraud under the rules of every system","No, legal or contractual mechanisms can separate control and cash-flow rights","Yes, but only inside the Anglo-Saxon model, where hostile takeovers are easy","No, because they keep votes proportional to cash-flow rights"],"correct_index":1,"explanation":"The course treats CEMs as legal or contractual governance tools, not inherently as fraud. They can separate voting power from cash-flow rights. Their defining feature is that control gap, not an automatic ban or equality of the two rights.","set":1},{"id":"cg-s9-q7","session":"9","topic":"Ownership-governance-strategy interdependence","question":"According to the course, what role does past performance play in changes of a firm's ownership, governance and strategy system?","choices":["Typically only extreme results, very good or very bad, trigger a change","Any small fall in yearly earnings makes owners reshape the system","None, since owners' values alone decide and performance is irrelevant","None, since these systems stay fixed once they are chosen"],"correct_index":0,"explanation":"Past performance is one driver, and only extreme results tend to trigger change. The others are owners' values and resources, the competitive environment, the institutional context and other contextual conditions.","set":1},{"id":"cg-s9-q8","session":"9","topic":"Ownership dichotomies","question":"Which dichotomy separates a controlling shareholder free of political pressure from one that is politically driven?","choices":["Strong versus weak controlling shareholder","Unique versus coalition controlling shareholder","Private versus public controlling shareholder","Financial versus industrial controlling shareholder"],"correct_index":2,"explanation":"A private controlling shareholder is free of political pressure, while a public one is politically driven. The other dichotomies concern the size of the stake, the number of holders and the type of investor.","set":1},{"id":"cg-s9-q9","session":"9","topic":"Financially-constrained controlling shareholders","question":"A controlling shareholder carries heavy debt from a leveraged buyout. Which behaviour does the course predict?","choices":["It accepts low dividends and backs heavy long term R&D spending","It favours dividends to service debt, resists risky expansion and capital increases","It pushes for capital increases, since it can inject new cash into the firm","It stays indifferent to dividend policy, since the debt sits at holding level"],"correct_index":1,"explanation":"A debt-constrained controlling shareholder needs cash from the firm, prefers short-term cash-generating activities and opposes capital increases. A cash-rich shareholder behaves the opposite way.","set":1},{"id":"cg-s9-q10","session":"9","topic":"Shareholder activism drivers","question":"Which firm is most exposed to shareholder activism according to the lecture?","choices":["A small firm with strong results, high managerial ownership and pay linked to performance","A firm paying a dividend above the industry average, with strong managerial ownership","A firm with many independent directors, since independence clearly predicts activism","A large firm with weak results, low managerial ownership and misaligned executive pay"],"correct_index":3,"explanation":"Underperformance, weak managerial ownership, pay-performance misalignment and institutional ownership make a firm more exposed. The evidence on independent directors is described as mixed, and a high dividend is not listed.","set":1},{"id":"cg-s9-q11","session":"9","topic":"Aberdeen case","question":"How does the Aberdeen case differ from the Elliott case at TIM?","choices":["Aberdeen was a targeted campaign against one company, Elliott portfolio wide stewardship","Aberdeen was led by the State, while Elliott was a campaign run by a private fund","Aberdeen was portfolio wide stewardship by a dedicated team, Elliott a targeted campaign","Aberdeen was led by employees through unions, while Elliott was a shareholder campaign"],"correct_index":2,"explanation":"Aberdeen, with stakes in 385 UK companies, uses a Governance & Stewardship team across its portfolio. Elliott's campaign at TIM targeted a single company. The cases show two models of activism.","set":2},{"id":"cg-s9-q12","session":"9","topic":"Elliott vs Vivendi at TIM","question":"What was the result of the 2018 contest at TIM for board independence?","choices":["13 of 15 directors were independent, including the Chairman, matching Elliott's aims","A board controlled by Vivendi nominees after it raised its stake above 50%","A board made up entirely of directors chosen by CDP, which took control","The old board stayed in place, since Elliott's proposal failed"],"correct_index":0,"explanation":"After the contest the new board had 13 of 15 independent directors, including the Chairman. Vivendi held 24%, Elliott had doubled its stake to 10%, and CDP was rumoured to take 5%.","set":2},{"id":"cg-s9-q13","session":"9","topic":"Elliott vs Vivendi at TIM","question":"What goal set CDP apart from Vivendi and Elliott in the TIM contest?","choices":["Maximising short-term financial returns for shareholders, as Elliott did","Integrating telecom with media assets, as Vivendi wanted to do","Taking TIM private by delisting it and buying out the other shareholders","Protecting TIM's strategic national role while rebalancing Vivendi and Elliott"],"correct_index":3,"explanation":"Vivendi wanted industrial control and integration with media, Elliott wanted independent, value-oriented governance and returns, and CDP wanted to protect a national strategic asset. The slides describe CDP's stake as rumoured.","set":2},{"id":"cg-s9-q14","session":"9","topic":"ESG assessment","question":"What does the MSCI ESG rating framework produce?","choices":["A pass or fail mark based only on whether the company meets legal requirements","An overall rating from AAA (leader) to CCC (laggard), aggregated from E, S and G indicators","A single carbon emissions figure for each company, compared across its whole sector","A compliance certificate that the regulator issues to each company once a year"],"correct_index":1,"explanation":"MSCI scores companies on E, S and G indicators, each measuring exposure to a risk or opportunity and how well it is managed. The scores are aggregated into one rating from AAA to CCC.","set":2},{"id":"cg-s9-q15","session":"9","topic":"ESG investing strategies","question":"Norway's Government Pension Fund Global excludes tobacco, coal and controversial weapons. Which ESG strategy is this?","choices":["Negative sector screening","Sector leadership selection","Sustainability theme allocation","Measured impact investing"],"correct_index":0,"explanation":"Avoiding sectors linked to harmful products or practices is exclusions or negative screening. Best-in-class picks the strongest performers in each sector.","set":2},{"id":"cg-s9-q16","session":"9","topic":"ESG investing strategies","question":"A fund such as Triodos chooses investments for their measurable social or environmental outcomes. Which ESG strategy is this?","choices":["Best-in-class","Exclusions","Impact investing","Engagement and voting"],"correct_index":2,"explanation":"Impact investing targets measurable social or environmental outcomes, for example microfinance, healthcare and renewable energy. Best-in-class ranks sector leaders, exclusions avoid harmful sectors and engagement uses dialogue and votes.","set":2},{"id":"cg-s9-q17","session":"9","topic":"NFD Italy","question":"According to the lecture, what is Italy's Non-Financial Declaration (NFD or DNF)?","choices":["A voluntary national sustainability report, with participation determined by each company rather than statute","A mandatory environmental tax return, filed by large companies together with annual financial statements","A domestic reporting rule for small firms, with no connection to an EU disclosure directive","A mandatory Italian implementation of the EU nonfinancial disclosure directive for large public-interest entities"],"correct_index":3,"explanation":"In the historical lecture framework, Legislative Decree 254/2016 implements Directive 2014/95/EU. The fiche describes mandatory disclosure since 2017 for large public-interest entities with more than 500 employees. The later question separately covers the lecture's CSRD transition.","set":2},{"id":"cg-s9-q18","session":"9","topic":"NFD evidence","question":"In the sample of 197 Italian companies, how do the share describing main ESG risks and the share with an explicit ESG risk integration objective compare?","choices":["96% described main ESG risks, versus 13% with an explicit further-integration objective","96% described their main ESG risks and 88% stated integration as an explicit objective","13% described their main ESG risks and 96% stated integration as an explicit objective","13% described their main ESG risks and 88% described mitigation methods"],"correct_index":0,"explanation":"96% described main risks and 88% described the management or mitigation methods, but only 13% stated integrating ESG into risk management as an explicit objective. The 88% is about mitigation methods, not about integration.","set":2},{"id":"cg-s9-q19","session":"9","topic":"NFD to CSRD transition","question":"How does the lecture present the relation between the NFD and the CSRD?","choices":["The NFD remains the final regime, while CSRD reporting is relevant only outside the EU","The historical slides describe a CSRD transition with broader scope, ESRS standards and assurance","The CSRD replaced the NFD in 2016, eliminating nonfinancial assurance and reducing reporting scope","The NFD covers ESG information, while the CSRD is limited to conventional financial accounts"],"correct_index":1,"explanation":"The closing slides describe a transition from the NFD to the CSRD, with ESRS standards, wider scope including SMEs and assurance requirements. The NFD is a starting point, not the final regime.","set":2},{"id":"cg-s9-q20","session":"9","topic":"Exam traps","question":"A student offers \"small family firm\" and \"public controlling shareholder\" as examples of the three models of capitalism. What is wrong?","choices":["Nothing is wrong, since the archetypes are the three models of capitalism under other names","The archetypes apply only inside the Anglo-Saxon model and say nothing about other systems","Models are country level systems, while archetypes describe firm level ownership in any system","Models apply only to private firms, while archetypes apply only to listed firms in any country"],"correct_index":2,"explanation":"The three models are country-level governance systems. Archetypes and dichotomies describe firm-level ownership situations that can appear in any of them.","set":2},{"id":"cg-s10-q1","session":"10","topic":"Why family firms matter","question":"How do family firms perform against their peers according to the HBR (2012) evidence, and how does this fit with their structural weaknesses?","choices":["They underperform during crises and over longer periods, consistent with the listed structural weaknesses","They outperform briefly but underperform during crises, because informal structures prevent financial discipline","They match their peers in every period, because strengths exactly offset the listed structural weaknesses","They outperform during crises and over longer periods, despite the listed structural weaknesses"],"correct_index":3,"explanation":"The HBR evidence shows resilience in crises and long run outperformance. The course stresses that this coexists with structural weaknesses, so saying that family firms underperform is a listed exam trap.","set":1},{"id":"cg-s10-q2","session":"10","topic":"HBR explanations","question":"Which of the following is one of the five HBR explanations for the outperformance of family firms?","choices":["Aggressive acquisitions, with larger deals to gain scale","High leverage, with debt-funded growth","Financial discipline, with frugality, limited capex and low leverage","Local focus, with growth limited to the home territory"],"correct_index":2,"explanation":"The five explanations are financial discipline, strategic caution (fewer and smaller acquisitions), diversification, global orientation and people advantage. Aggressive acquisitions, high leverage and local focus contradict the listed explanations.","set":1},{"id":"cg-s10-q3","session":"10","topic":"Governance levels","question":"At which governance level does the Top Management Team execute the strategy and run daily operations?","choices":["Operating governance, where the TMT executes strategy and manages daily operations","Ownership governance, where shareholders define values, vision and ultimate control","Corporate governance, where the board monitors management and guides major strategy","Family governance, where the family manages membership rules and relationships"],"correct_index":0,"explanation":"Operating governance is the Top Management Team executing strategy and running daily operations. Ownership governance sets vision, values and ultimate control, and corporate governance is the board's oversight and guidance. The family level is an extra layer in family firms.","set":1},{"id":"cg-s10-q4","session":"10","topic":"When governance is critical","question":"Which family firm most needs structured governance, according to the course?","choices":["A stable single-owner firm with no growth, no conflicts and no succession issue","A firm with one owner-manager who plans no change in ownership","A firm in a steady state where informal habits already settle every dispute","A firm whose founder is ageing and whose heirs ask for clear rules of entry"],"correct_index":3,"explanation":"Governance becomes critical with growth and success, tensions and conflicts, ownership changes and generational factors. An ageing leader and heirs asking for entry rules are generational factors.","set":1},{"id":"cg-s10-q5","session":"10","topic":"Good and bad","question":"A family firm keeps a long-term focus over short-term returns and has built up trust and reputation over decades. How does the course classify these features?","choices":["As weaknesses, the \"bad\" of family firms","As strengths, the \"good\" of family firms","As costs of designing governance","As exit barriers that lock owners in"],"correct_index":1,"explanation":"Patient capital, social capital and unique resources belong to the \"good\" of family firms, together with emotional commitment, stable culture and resilience. The \"bad\" is nepotism, appropriation, conservatism, conflict burden and generational risk.","set":1},{"id":"cg-s10-q6","session":"10","topic":"Key figures","question":"According to the lecture, which pair gives the survival rates of family firms in generational transfers?","choices":["15% for first to second, 30% for second to third generation","50% for first to second, 30% for second to third generation","30% for first to second, 15% for second to third generation","13% for first to second, 13% for second to third generation"],"correct_index":2,"explanation":"The slides give 30% for the transfer from the first to the second generation and 15% from the second to the third. The 13% figure is a different statistic, the share of family firms that reach the third generation.","set":1},{"id":"cg-s10-q7","session":"10","topic":"Holding vs operating BoD","question":"A family firm needs a body to draft and review family agreements and to assess the suitability of heirs. Which body does this?","choices":["The holding-level board, through its family-related responsibilities","The operating board, which appoints the CEO and approves plans","The Top Management Team, which runs daily operations","The statutory auditors, who review compliance"],"correct_index":0,"explanation":"The holding board has two blocks of duties, corporate and group duties and family-related duties. The family-related block covers family agreements, next generation development and the suitability of heirs. The operating board appoints management and approves plans and budgets.","set":1},{"id":"cg-s10-q8","session":"10","topic":"Effective boards","question":"Which board design matches the good practices of an effective board?","choices":["3 members, one annual meeting, no preparation and an informal voting process","7 to 9 members, at least 6 annual meetings, substantial preparation and an active culture","An unlimited number of members, crisis-only meetings, minimal preparation and passive approval","7 to 9 members, 6 annual meetings, one total preparation hour and informal voting"],"correct_index":1,"explanation":"The lecture recommends 7 to 9 directors and at least 6 meetings a year. Preparation should be about 3 hours per meeting hour, with active discussion and clear voting rules. Size and meeting count alone are not enough.","set":1},{"id":"cg-s10-q9","session":"10","topic":"Traumatic succession","question":"Which situation is most likely to cause a traumatic generational transition?","choices":["A merit-based selection among several heirs","An external professional manager appointed as CEO","An unfit heir chosen by family logic, ignoring merit","Parallel ventures created so that each heir has a business"],"correct_index":2,"explanation":"Traumatic transitions come from sudden loss of the entrepreneur, no willing heirs, unfit heirs chosen by family logic and irreconcilable family conflicts. Merit based selection, non-family leadership and parallel ventures are tools for managing succession.","set":1},{"id":"cg-s10-q10","session":"10","topic":"Outsiders","question":"A family firm adds directors from outside the family circle. Which three types of outsiders does the course distinguish?","choices":["Bankers, auditors and consultants who advise the family and the board","Executive, non-executive and independent directors sitting on the operating board","Shareholders, stakeholders and managers who take part in the family meetings","Non-operating family members, affiliated non-family members and independent non-family members"],"correct_index":3,"explanation":"The three types are uninvolved family members, affiliated non-family directors and independent non-family directors. They play different roles, so treating all outsiders as independent is an exam trap.","set":1}]},"QCM_DATA":{"da":[{"id":"dd-sup-1","dataset":"SUP","session":2,"topic":"Prediction with dummies","question":"SUP model: intercept 78.5686, S slope 1.3578, HDyes 64.1552, AEaverage 3.3731 and AEhigh 22.8031. References are HD no and AE low. What mean CN is fitted for S = 800, HD no and AE high?","choices":["About 1251.8, including surface, delivery and the high access contrast.","About 1187.6, including surface and the high access contrast.","About 1168.2, including surface and the average access contrast.","About 1164.8, including surface but neither dummy contrast."],"correct_index":1,"explanation":"78.5686 + 1.3578 times 800 + 22.8031 = 1187.6117. HD no contributes zero. Adding HDyes gives 1251.7669, omitting AEhigh gives 1164.8086, and using AEaverage gives 1168.1817."},{"id":"dd-sup-2","dataset":"SUP","session":1,"topic":"Reading summary()","question":"The SUP HDyes row reports estimate 64.1552 and standard error 67.0423. What is its coefficient t statistic?","choices":["About 0.340, reading the reported p value instead.","About 64.16, reading the estimate without standardization.","About 1.045, dividing standard error by estimate.","About 0.957, dividing estimate by standard error."],"correct_index":3,"explanation":"64.1552/67.0423 is approximately 0.957. The reciprocal ratio, raw estimate and p value are different summary quantities. This statistic tests the coefficient against zero given the other model predictors."},{"id":"dd-sup-3","dataset":"SUP","session":2,"topic":"Contrast between two dummies","question":"In SUP, AEaverage = 3.3731 and AEhigh = 22.8031 both compare with low. Holding S and HD fixed, what is the high versus average gap and its relevant test?","choices":["19.43, tested through the high minus average coefficient contrast.","22.80, tested through the high minus average coefficient contrast.","26.18, tested by adding both coefficients and their individual tests.","19.43, tested by the AEhigh versus low coefficient test alone."],"correct_index":0,"explanation":"The fitted contrast is 22.8031 minus 3.3731 = 19.43. Neither original coefficient t test compares high with average. Relevel average as reference and refit, or test this contrast directly using its correct uncertainty."},{"id":"dd-sup-4","dataset":"SUP","session":1,"topic":"Confidence interval","question":"The SUP HDyes coefficient has a two sided t test p value 0.340. What follows for its corresponding 90% confidence interval under the same model?","choices":["It contains zero only if the standard error is smaller than the estimate.","It contains zero because 0.340 is above the corresponding 0.10 test level.","It excludes zero because the coefficient estimate is positive.","It excludes zero because 0.340 is above the corresponding 0.10 test level."],"correct_index":1,"explanation":"A matching two sided level 0.10 test and 90% confidence interval agree on zero inclusion. The test does not reject, so the interval contains zero. Estimate sign and a comparison of estimate with standard error do not replace the appropriate critical value."},{"id":"dd-sup-5","dataset":"SUP","session":1,"topic":"Reasonable prediction","question":"SUP has observed S range 341.8 to 1500, HD levels no/yes and AE levels low/average/high. Which case passes these range and factor level checks, without claiming they prove full joint sample support?","choices":["S 350, HD no and AE average.","S 300, HD yes and AE low.","S 1000, HD yes and AE medium.","S 1600, HD no and AE high."],"correct_index":0,"explanation":"350 is within the surface range and both categories are observed levels. 300 and 1600 extrapolate, and medium is not a valid level. Passing marginal checks alone does not prove this exact combination is well represented in the joint sample."},{"id":"dd-sup-6","dataset":"SUP","session":2,"topic":"Partial F-test","question":"SUP has n = 150. The complete model contains S, HDyes, AEaverage, AEhigh and an intercept. The reduced model removes both AE terms. What are the partial F degrees of freedom?","choices":["1 and 146, for one factor label and an intermediate residual count.","2 and 147, for two added terms and reduced model residual degrees of freedom.","2 and 145, for two added terms and complete model residual degrees of freedom.","3 and 145, for three retained terms and complete model residual degrees of freedom."],"correct_index":2,"explanation":"AE contributes two coefficients, so numerator degrees of freedom are 2. Complete model residual degrees of freedom are 150 minus 4 minus 1 = 145. A categorical variable's label does not determine its coefficient count."},{"id":"dd-sup-7","dataset":"SUP","session":2,"topic":"Partial F-test decision","question":"Adding both AE terms to S and HD in SUP gives partial F = 0.0449 with p value 0.9561. Under a 5% test based selection rule, what conclusion is justified?","choices":["Keep the complete model, since any increase in predictor count establishes contribution.","Keep the reduced model, since the test proves AE has no effect in every specification.","Keep the complete model, since the large p value means a large joint effect.","Keep the reduced model, since the test gives insufficient evidence of added AE contribution."],"correct_index":3,"explanation":"The p value exceeds 0.05, so the added group null is not rejected. Under the stated rule the simpler model is retained. This is insufficient evidence conditional on S and HD, not proof that AE is irrelevant in every setting or a measure of effect size."},{"id":"dd-sup-8","dataset":"SUP","session":1,"topic":"Marginal effect","question":"SUP's S coefficient is 1.3578 clients per square metre, with standard error 0.1414. What fitted mean change corresponds to 100 extra square metres, HD and AE fixed?","choices":["Exactly 135.8 clients for every supermarket, regardless of individual errors.","About 1.36 clients, reading the per square metre coefficient without scaling.","About 135.8 clients, scaling the coefficient by 100.","About 14.1 clients, scaling the standard error by 100."],"correct_index":2,"explanation":"100 times 1.3578 = 135.78 is the change in conditional mean. Standard error measures coefficient uncertainty rather than response change. The fitted mean relation is not a deterministic change for every individual supermarket."},{"id":"dd-sup-9","dataset":"SUP","session":2,"topic":"Non-nested models","question":"On the same SUP sample, model1 uses S, HD and AE with adjusted R squared 0.383. Model2 uses S, HD and CA with adjusted R squared 0.404. Which comparison follows the lecture?","choices":["Prefer model1 inferentially, because replacing AE with CA tests AE jointly against zero.","Prefer model2 descriptively by adjusted R squared, without treating these models as nested.","Prefer model1 descriptively, because a larger predictor count always improves adjusted fit.","Prefer model2 inferentially by a partial F test, because it has fewer predictor coefficients."],"correct_index":1,"explanation":"Neither predictor set contains the other, so this partial F procedure does not compare them. Adjusted R squared offers the lecture's descriptive comparison and favours 0.404. That preference is not itself a significance test."},{"id":"dd-sup-10","dataset":"SUP","session":1,"topic":"Confidence interval","question":"SUP's S estimate is 1.3578 with standard error 0.1414. Using a supplied 99% t multiplier of 2.61, what interval is obtained?","choices":["Approximately [0.989, 1.727], with margin 2.61 times 0.1414.","Approximately [1.078, 1.637], with margin 1.98 times 0.1414.","Approximately [1.216, 1.499], with margin one standard error.","Approximately [1.358, 1.727], retaining only the upper confidence bound."],"correct_index":0,"explanation":"The margin is 0.369054. Subtracting and adding it gives 0.988746 and 1.726854. A different multiplier changes the confidence level, and keeping only half of a symmetric interval is not the stated two sided interval."},{"id":"dd-sup-11","dataset":"SUP","session":2,"topic":"Global F-test","question":"SUP summary reports a global F test on 4 and 145 degrees of freedom. With S, HDyes, AEaverage and AEhigh as its slopes, what is the null?","choices":["Only AEaverage and AEhigh are zero jointly, leaving S and HD unrestricted.","The intercept and all four slope coefficients are zero jointly.","All four slope coefficients are zero jointly, leaving the intercept unrestricted.","Only S is zero, leaving the remaining coefficients unrestricted."],"correct_index":2,"explanation":"The global comparison is with an intercept only model, so it tests all four slopes but not the intercept. Testing AE alone is partial, and testing S alone is an individual coefficient hypothesis."},{"id":"dd-pan-1","dataset":"PAN","session":5,"topic":"Fixed effects prediction","question":"A within panel model has common adv slope 25.0203. Firm1's full intercept from fixef is 144.048. What is fitted sales for firm1 at adv = 10?","choices":["About 394.3, adding the unit intercept to the common slope contribution.","About 169.1, adding only one unit of the common slope contribution.","About 250.2, using only the common slope contribution.","About 194.7, using firm2's intercept of minus 55.524 instead."],"correct_index":0,"explanation":"144.048 + 25.0203 times 10 = 394.251. The alternatives omit the intercept, fail to scale adv, or use the wrong firm. A specific firm prediction requires its own full intercept."},{"id":"dd-pan-2","dataset":"PAN","session":5,"topic":"Fixed effects","question":"In the same common slope fixed effects model, firm1 has intercept 144.048 and firm2 minus 55.524. At equal adv, what is their fitted sales gap, firm1 minus firm2?","choices":["25.0203 at every common adv value.","199.572 at every common adv value.","199.572 times adv, so the gap changes with advertising.","88.524 at every common adv value."],"correct_index":1,"explanation":"At equal adv the common slope contributions cancel. The gap is 144.048 minus (minus 55.524) = 199.572. Adding the signed intercepts gives 88.524, reading the slope gives a different quantity, and multiplying the intercept gap by adv is incorrect."},{"id":"dd-pan-3","dataset":"PAN","session":5,"topic":"Hausman test","question":"A Hausman comparison of fixed and random effects has p value 0.0774. Applying the lecture rule separately at 5% and 10%, which selections follow?","choices":["Random effects at both 5% and 10%.","Fixed effects at both 5% and 10%.","Fixed effects at 5% and random effects at 10%.","Random effects at 5% and fixed effects at 10%."],"correct_index":3,"explanation":"0.0774 exceeds 0.05 but is below 0.10. The random effects validity null is not rejected at 5%, but is rejected at 10%. Rejection leads to fixed effects, so the choice depends on the selected significance level."},{"id":"dd-gr-1","dataset":"GR","session":5,"topic":"Hausman test","question":"For Grunfeld models with value and capital, the supplied Hausman result has statistic 2.3304, two tested slope differences and p value 0.3119. At 5%, which reading is correct?","choices":["The two slope comparisons give two degrees of freedom, and fixed effects is selected.","The two models themselves give two degrees of freedom, and fixed effects is selected.","The two slope comparisons give two degrees of freedom, and random effects is selected.","The two models themselves give two degrees of freedom, and random effects is selected."],"correct_index":2,"explanation":"The two degrees of freedom correspond to the two coefficient differences compared, not simply two fitted models. With p value above 0.05, the lecture rule does not reject the random effects null and selects REM. The values are explicitly supplied for this exercise."},{"id":"dd-gr-2","dataset":"GR","session":5,"topic":"REM output","question":"The Grunfeld random effects output gives individual variance 5977.20 and idiosyncratic variance 7472.57. What proportion of combined unexplained variance is individual?","choices":["About 44.4%, using 5977.20 divided by their sum.","About 55.6%, using 7472.57 divided by their sum.","About 80.0%, using 5977.20 divided by 7472.57.","About 16.6%, reading the value slope rather than the variance share."],"correct_index":0,"explanation":"5977.20/(5977.20 + 7472.57) = about 0.4444. The idiosyncratic share is about 0.5556. Dividing one component by the other is a component ratio rather than its total share, and a slope is not a variance proportion."},{"id":"dd-gr-3","dataset":"GR","session":5,"topic":"FEM output","question":"A Grunfeld model fitted with plm(..., model = \"within\") reports slopes but not a common intercept. Which output is needed for the lecture's unit specific intercept prediction?","choices":["The mean response, selecting one common value for every firm's intercept.","phtest(mod, other), selecting the test p value as the firm intercept.","coef(mod)[1], selecting the first slope as the firm intercept.","fixef (mod), selecting the relevant firm's full estimated individual intercept effect."],"correct_index":3,"explanation":"The within transformation absorbs individual intercepts. fixef recovers the individual effects used for the lecture's predictions. A slope, Hausman p value, or unadjusted response mean is not the firm's fitted intercept."},{"id":"dd-gr-4","dataset":"GR","session":5,"topic":"FEM vs REM estimate","question":"Grunfeld estimates for value are about 0.19 under fixed effects and 0.166 under random effects. What can be concluded from that difference alone?","choices":["It proves fixed effects is more efficient, since its estimated slope is larger.","It does not establish validity or efficiency, so assumptions and a Hausman comparison still matter.","It proves random effects is invalid, since valid estimators must coincide exactly in the sample.","It proves the unit component is correlated with value, regardless of sampling variability."],"correct_index":1,"explanation":"Finite sample estimates can differ under valid procedures. Estimate magnitude alone measures neither efficiency nor consistency and does not prove error predictor correlation. The lecture uses Hausman with its assumptions to guide the comparison."},{"id":"dd-cl-1","dataset":"CL","session":7,"topic":"Odds ratio over 10 units","question":"In CL's additive logit model, AGE has coefficient minus 0.0389. With vehicle category fixed, how do high claim odds change for a driver ten years older?","choices":["The event probability falls by exactly 32.2%, irrespective of its starting value.","They are multiplied by exp(minus 0.0389), approximately a 3.8% reduction.","They are multiplied by exp(minus 0.389), approximately a 32.2% reduction.","They fall by exactly 38.9%, multiplying the coefficient magnitude by ten."],"correct_index":2,"explanation":"Ten years change log odds by 10 times minus 0.0389 = minus 0.389. exp(minus 0.389) is approximately 0.678, so odds fall about 32.2%. Odds changes compound, and the same proportional probability change is not implied."},{"id":"dd-cl-2","dataset":"CL","session":7,"topic":"predict() output","question":"For a fitted glm binary logit, predict(model1, newdata) is called without type = \"response\". If its linear predictor is minus 1.473928, what is returned?","choices":["About 0.186346 on the event probability scale.","About 0.813654 on the nonevent probability scale.","About 0.229024 on the event odds scale.","Minus 1.473928 on the log odds link scale."],"correct_index":3,"explanation":"The default glm prediction is on its link scale, here log odds. type response returns probability. Exponentiating the default output gives odds, while subtracting probability from one gives the nonevent probability."},{"id":"dd-cl-3","dataset":"CL","session":7,"topic":"Prediction","question":"In the additive CL model, a fifty year old category B driver's fitted log odds are minus 1.473928, and AGE slope is minus 0.03892. What is the probability for a thirty year old category B driver?","choices":["About 0.186, retaining the fifty year old driver's probability.","About 0.333, converting the revised log odds of minus 0.696.","About 0.667, using the revised complementary probability.","About 0.499, treating the revised odds as the event probability."],"correct_index":1,"explanation":"Twenty fewer years add 20 times 0.03892 = 0.7784 to log odds, giving minus 0.695528. Logistic conversion gives about 0.3328. Its odds are about 0.4988, not its probability. The complementary probability reverses the event."},{"id":"dd-cl-4","dataset":"CL","session":7,"topic":"Deviances","question":"A CL model on 200 observations has residual deviance 159.84 and global LRT statistic 77.344 against the intercept only model. What are null deviance and null residual degrees of freedom?","choices":["About 237.184 and 199, adding the LRT reduction and retaining one fitted intercept.","About 159.84 and 199, assuming deviance is unchanged across predictor sets.","About 82.496 and 199, subtracting the LRT reduction from complete deviance.","About 237.184 and 196, using the complete model residual degrees of freedom."],"correct_index":0,"explanation":"LRT statistic is null deviance minus complete deviance, so null deviance is 159.84 + 77.344 = 237.184. An intercept only model has 200 minus 1 = 199 residual degrees of freedom. The complete model's 196 degrees of freedom do not apply to the null model."},{"id":"dd-cl-5","dataset":"CL","session":7,"topic":"AIC","question":"The CL age only model has residual deviance 229.042 with one predictor and an intercept. What AIC follows?","choices":["229.042, omitting the complexity penalty.","231.042, adding twice the single predictor only.","233.042, adding twice the two fitted coefficients.","237.042, adding the four coefficient penalty of the larger model."],"correct_index":2,"explanation":"AIC = deviance + 2(p + 1). Here p = 1, so add 4 to obtain 233.042. The intercept counts in this penalty, and the larger age plus vehicle model's coefficient count does not belong to the age only model."},{"id":"dd-cl-6","dataset":"CL","session":7,"topic":"Global test, AGE alone","question":"CL's null deviance is 237.18 and age only deviance 229.04. For one added coefficient, the supplied 1% chi square critical value is 6.63. What does the global age only test conclude?","choices":["Do not reject at 1%, since the deviance drop 8.14 exceeds 6.63.","Reject at 1% on two degrees of freedom, because two models are fitted.","Reject at 1% using 69.202, the larger model's vehicle contribution.","Reject at 1%, since the deviance drop 8.14 exceeds 6.63."],"correct_index":3,"explanation":"The statistic is 237.18 minus 229.04 = 8.14 on one degree of freedom. It exceeds the supplied threshold, so age alone is significant even at 1%. Two models do not imply two degrees of freedom, and the vehicle comparison addresses another group."},{"id":"dd-cl-7","dataset":"CL","session":7,"topic":"Z-test","question":"AGE estimate minus 0.0389 is significant at 5% but not at 1% under a two sided Z test. Supplied critical magnitudes are 1.96 and 2.576. Which standard error is compatible?","choices":["0.017, giving an absolute Z statistic of about 2.288.","0.025, giving an absolute Z statistic of about 1.556.","0.039, giving an absolute Z statistic of about 0.997.","0.010, giving an absolute Z statistic of about 3.890."],"correct_index":0,"explanation":"The statistic must lie above 1.96 and below 2.576. 0.0389/0.017 = 2.288. A smaller SE of 0.010 makes both tests reject, while the two larger SE values make neither reject."},{"id":"dd-cl-8","dataset":"CL","session":7,"topic":"Confusion matrix","question":"The CL confusion table has 128 true negatives, 40 true positives, 16 false positives and 16 false negatives. What is the overall error rate?","choices":["36%, from 72 observed positives out of 200 cases.","20%, from 40 correct positive classifications out of 200 cases.","16%, from 32 errors out of 200 cases.","84%, from 168 correct classifications out of 200 cases."],"correct_index":2,"explanation":"Errors are both off diagonal counts: 16 + 16 = 32. Their proportion is 32/200 = 16%. 84% is accuracy, not error. There are 56 observed positives, not 72, and true positives alone do not give the error rate."},{"id":"dd-cl-9","dataset":"CL","session":7,"topic":"Threshold","question":"For a claim with fitted probability 0.186, classify Y as 1 when p is at least the chosen cutoff. What changes when the cutoff moves from 0.5 to 0.15?","choices":["The class changes from 1 to 0, while its fitted probability stays 0.186.","The probability changes to 0.15, because the cutoff defines the fitted probability.","The class stays 0, because a cutoff other than 0.5 is not allowed.","The class changes from 0 to 1, while its fitted probability stays 0.186."],"correct_index":3,"explanation":"0.186 is below 0.5 but above 0.15. Classification depends on the cutoff, while the fitted probability from the model does not change merely because a different decision rule is chosen. The lecture permits other thresholds."},{"id":"dd-cl-10","dataset":"CL","session":7,"topic":"Dummy odds ratio","question":"VCB has coefficient 1.1268 with A as vehicle reference, and exp(1.1268) is about 3.086. At the same age, which comparison is correct?","choices":["Category B high claim odds are about 3.086% above category A odds.","Category B high claim odds are about 3.086 times category A odds.","Category B high claim odds are about 3.086 times category C odds.","Category B high claim probability is about 3.086 times category A probability."],"correct_index":1,"explanation":"Exponentiation yields an odds multiplier against the reference A, not a probability multiplier or a comparison with C. A factor of 3.086 is about 208.6% higher odds, not 3.086% higher."},{"id":"dd-cl-11","dataset":"CL","session":7,"topic":"Joint test in R","question":"model2 is HC ~ AGE and model1 is HC ~ AGE + VC, with VC represented by two dummies on the same sample. Which command and degrees of freedom test VC jointly given AGE?","choices":["anova(model2, model1, test = \"Chisq\"), jointly comparing the two additional VC dummy coefficients.","Two separate Z tests for VCB and VCC, treated as one joint two coefficient test.","anova(model0, model1, test = \"Chisq\"), comparing all three slopes jointly.","Compare model1 and model0 AIC values, treated as a two coefficient significance test."],"correct_index":0,"explanation":"The nested comparison retains age in both models and removes only the two VC coefficients, giving a partial LRT on two degrees of freedom. The intercept only comparison is global, separate Z tests are not the joint null, and AIC is descriptive."},{"id":"dd-st-1","dataset":"STUD","session":8,"topic":"Odds ratio","question":"The academic versus general multinomial equation has score slope 0.0579. With ses fixed, what fitted ratio change corresponds to ten extra score points?","choices":["About a 6.0% increase in academic versus general ratio, using a one point change.","About a 78.4% increase in academic versus general ratio, from exp(0.579).","About a 57.9% increase in academic versus general ratio, adding coefficient percentages linearly.","About a 78.4% increase in academic probability itself, irrespective of other equations."],"correct_index":1,"explanation":"The ten point change adds 0.579 to log(pacademic/pgeneral). exp(0.579) is about 1.784, an increase of 78.4% in that ratio. The individual probability depends on all equations, and the multiplier compounds rather than adding percentages."},{"id":"dd-st-2","dataset":"STUD","session":8,"topic":"Contrast between two equations","question":"Score slopes are minus 0.0557 for vocation versus general and plus 0.0579 for academic versus general. How does vocation versus academic ratio change for one extra point?","choices":["It is multiplied by exp(0.0022), about a 0.2% increase.","It cannot be calculated from these coefficients without refitting the model.","It is multiplied by exp(minus 0.0557), about a 5.4% reduction.","It is multiplied by exp(minus 0.1136), about a 10.7% reduction."],"correct_index":3,"explanation":"Subtract academic's reference equation from vocation's to obtain log(pvocation/pacademic). The slope is minus 0.0557 minus 0.0579 = minus 0.1136. Exponentiation gives about 0.8926. A refit can express the same contrast but is not necessary for its point estimate."},{"id":"dd-st-3","dataset":"STUD","session":8,"topic":"Predicted probabilities","question":"A multinomial prediction gives general 0.2334, academic 0.4159 and vocation 0.3507. What is the academic versus general probability ratio?","choices":["About 0.561, dividing general probability by academic probability.","About 0.712, dividing academic probability by all other categories together.","About 1.186, dividing academic probability by vocation probability.","About 1.782, dividing academic probability by general probability."],"correct_index":3,"explanation":"0.4159/0.2334 is about 1.782. In the specified contrast, the denominator is general, not 1 minus academic or vocation. Reversing numerator and denominator produces the reciprocal ratio."},{"id":"dd-st-4","dataset":"STUD","session":8,"topic":"Model size","question":"program has three categories and one reference. Predictors are score and ses, with ses represented by two dummies. Including intercepts, how many coefficients does the multinomial specification estimate?","choices":["Six, from two equations while omitting both intercepts.","Four, from treating every equation as having one shared coefficient set.","Eight, from two equations each containing four coefficients.","Twelve, from three equations each containing four coefficients."],"correct_index":2,"explanation":"There are k minus 1 = 2 equations. Each has an intercept, score, sesmiddle and seshigh, giving 2 times 4 = 8. The reference response has no separate equation, and coefficients are not all forced to be shared."},{"id":"dd-st-5","dataset":"STUD","session":8,"topic":"Dummy interpretation","question":"The academic versus general equation has seshigh coefficient 1.1628. ses low is reference and score is fixed. What does exp(1.1628), about 3.20, describe?","choices":["The high versus low multiplier of the academic versus general probability ratio.","The high versus middle multiplier of the academic versus general probability ratio.","The high versus low multiplier of academic probability without normalization.","The high versus low increase of 116.28% in the academic versus general ratio."],"correct_index":0,"explanation":"The predictor dummy compares high with low and the outcome equation compares academic with general. The multiplier is about 3.20 on that ratio. Middle requires a coefficient contrast, and the raw coefficient is a log ratio change rather than a percentage change."},{"id":"dd-st-6","dataset":"STUD","session":8,"topic":"Dummy interpretation","question":"sesmiddle coefficient is 0.8246 in the vocation versus general equation, with low as ses reference. What percentage change in that ratio corresponds to middle versus low at fixed score?","choices":["About plus 228.1%, treating the multiplier as the percentage increase.","About plus 128.1%, since exp (0.8246) gives an odds ratio of approximately 2.281.","About minus 56.2%, using the inverse ratio instead of the requested direction.","About plus 82.46%, treating the coefficient as a direct percentage increase."],"correct_index":1,"explanation":"The ratio multiplier is about 2.281. Subtract 1 and multiply by 100 for an increase of about 128.1%. The inverse factor addresses low versus middle, while exponentiating is required before deriving a percentage change."},{"id":"dd-st-7","dataset":"STUD","session":8,"topic":"p-values in R","question":"For a multinom coefficient estimate b and standard error s, which R expression computes the lecture's approximate two sided individual p value?","choices":["2 * (1-pnorm(abs(b*s))), multiplying estimate by standard error.","1-pnorm(b/s), using just one tail without absolute value.","2 * (1-pnorm(abs(b/s))), using absolute standardized estimate and two tails.","2 * pnorm(abs(b/s)), using cumulative probability rather than tail probability."],"correct_index":2,"explanation":"Use z = b/s, take its absolute value, calculate the upper standard normal tail, and double it. A single tail is not two sided, multiplication by s does not standardize, and doubling the lower tail at positive magnitude gives the wrong probability."}]},"FLASHCARDS":{"da":[{"id":"da-s1-f1","session":1,"front":"What are the three purposes a regression analysis can serve? (knowing / explaining / forecasting)","back":"Knowing: do x1,...,xp have an effect on Y, and what does it look like? Explaining: can Y's variability be (partly) explained by the x's? Forecasting: how do you predict/estimate Y for units with specific x values?"},{"id":"da-s1-f2","session":1,"front":"Theoretical equation of the linear regression model","back":"Y = β0 + β1x1 + ... + βpxp + ε. Y is random; the x's are treated as fixed/known; β0,...,βp are unknown parameters; ε is the random error absorbing everything else affecting Y."},{"id":"da-s1-f3","session":1,"front":"List the five assumptions of the linear regression model","back":"1) E(εi)=0 (zero-mean error) 2) Var(εi)=σ² constant (homoskedasticity) 3) Cov(εk,εi)=0 for k≠i (uncorrelated errors) 4) εi~N(0,σ²) (normal errors) 5) No perfect multicollinearity among the x's."},{"id":"da-s1-f4","session":1,"front":"What does assumption 1 (zero-mean error) imply about E(Yi)?","back":"E(Yi) = β0 + β1xi1 + ... + βpxip — on average, Y sits exactly on the hyperplane (or line if p=1) defined by the x's."},{"id":"da-s1-f5","session":1,"front":"Why is 'uncorrelated errors' (assumption 3) weaker than 'independent errors'?","back":"Uncorrelated only rules out linear association between any two errors; it does not require full statistical independence."},{"id":"da-s1-f6","session":1,"front":"What does 'linear' mean in 'linear regression model'?","back":"Linear with respect to the parameters βj, not necessarily with respect to the x's — the same theory covers models with x² or log(x) terms."},{"id":"da-s1-f7","session":1,"front":"Least squares objective (what is minimized, and over what)","back":"Minimize Σi=1..n [yi − (β0+β1xi1+...+βpxip)]² over β0,...,βp. The minimizing values b0,...,bp are the least squares estimates."},{"id":"da-s1-f8","session":1,"front":"What is y-hat (the estimated equation)?","back":"y-hat = b0 + b1x1 + ... + bpxp — the fitted/predicted value; since E(Y) is linear in the x's, y-hat estimates the mean of Y at given x values, not an individual Y."},{"id":"da-s1-f9","session":1,"front":"Marginal effect of xj (definition and formula)","back":"bj = the estimated average change in Y when xj increases by one unit, all other x's held constant. Derivation: y-hat_incr − y-hat = bj, since all other terms cancel in the subtraction."},{"id":"da-s1-f10","session":1,"front":"Define spurious effect (effet fallacieux)","back":"An apparent effect of xj on Y that is actually caused by one or more omitted variables correlated with both xj and Y — those hidden variables are what's really driving the observed relationship."},{"id":"da-s1-f11","session":1,"front":"Confidence interval formula for βj","back":"(bj − t^(n−p−1)_(α/2)·sbj, bj + t^(n−p−1)_(α/2)·sbj). Start from point estimate bj, add/subtract margin of error = Student's t quantile × standard error."},{"id":"da-s1-f12","session":1,"front":"Hypothesis test on βj: H0, test statistic, decision rule","back":"H0: βj=0, H1: βj≠0. toss = bj/sbj. Reject H0 at level α if |toss| ≥ t^(n−p−1)_(α/2), equivalently if p-value = 2P(T≥|toss|) < α."},{"id":"da-s1-f13","session":1,"front":"What does rejecting H0: βj=0 tell you?","back":"Evidence that xj really does affect the mean of Y, other variables held constant — xj is then called 'significant'."},{"id":"da-s1-f14","session":1,"front":"Two different prediction questions in regression, and how their point predictions compare","back":"1) Predict Y for one specific unit at given x. 2) Predict the mean of Y for all units sharing those x values. Both use the exact same point-prediction formula y-hat0, but the single-unit prediction has a wider interval (it also carries ε's uncertainty)."},{"id":"da-s1-f15","session":1,"front":"What is extrapolation and why is it risky?","back":"Predicting y-hat0 for x values outside the range observed in the sample. It silently assumes, with no evidence, that the fitted relationship continues to hold there — can produce absurd predictions."},{"id":"da-s1-f16","session":1,"front":"Deviance decomposition (Total = Residual + Explained)","back":"Σ(yi−mean(y))² = Σ(yi−y-hat_i)² + Σ(y-hat_i−mean(y))². Total Deviance depends only on observed y's; Residual Deviance = what the model fails to explain; Explained Deviance = what the x's actually explain."},{"id":"da-s1-f17","session":1,"front":"R² formula and range","back":"R² = Explained Deviance / Total Deviance, in [0,1]. R²=1 when the model explains 100% of variability; R²=0 when y-hat_i = mean(y) for everyone (x's add nothing)."},{"id":"da-s1-f18","session":1,"front":"Why does adjusted R² exist, and its formula","back":"Because raw R² never decreases when adding a variable (even a useless one), so it can't fairly compare models with different p. Adjusted R² = 1 − (1−R²)·(n−1)/(n−p−1), which penalizes model size p."},{"id":"da-s1-f19","session":1,"front":"When should you use the partial F-test vs adjusted R² to compare two models?","back":"Nested models → partial F-test (inferential, correct comparison). Non-nested models → adjusted R² only (descriptive comparison), since the partial F-test doesn't apply."},{"id":"da-s2-f1","session":2,"front":"Dummy variable coding convention","back":"1 = the characteristic is present, 0 = it is absent. A dummy simply splits the population into the group coded 0 and the group coded 1."},{"id":"da-s2-f2","session":2,"front":"What does a dummy variable's coefficient estimate?","back":"The difference in the average of Y between the group coded 1 and the group coded 0, all other explanatory variables held constant ('controlling for the other variables')."},{"id":"da-s2-f3","session":2,"front":"k−1 dummy rule","back":"A categorical variable with k>2 categories needs k−1 dummy variables, one per category except one. The excluded category becomes the reference category; every dummy coefficient is a comparison against it."},{"id":"da-s2-f4","session":2,"front":"Why can't you code a k>2 category variable as 0,1,2,...?","back":"It would impose an artificial numeric order and spacing between categories that has no real meaning (e.g. 'zone B minus zone A' isn't inherently worth more than 'zone C minus zone B')."},{"id":"da-s2-f5","session":2,"front":"With zones A (reference), B, C: what does bB estimate? What about bC?","back":"bB = estimated price gap between zone B and zone A, age held constant. bC = same idea, zone C vs zone A. Neither gives the B-vs-C comparison directly."},{"id":"da-s2-f6","session":2,"front":"How do you get the zone-C-vs-zone-B comparison if A is the reference?","back":"Compute y-hatC − y-hatB directly (this equals bC − bB); its significance needs its own test — it can't be read off a single t-test on bB or bC."},{"id":"da-s2-f7","session":2,"front":"How is a dummy variable's coefficient tested for significance?","back":"Exactly the same as any quantitative variable's coefficient — same confidence interval formula, same t-test (H0: βj=0)."},{"id":"da-s2-f8","session":2,"front":"Nested models definition (reduced vs complete)","back":"RED.M has q variables x1,...,xq. COMP.M has p>q variables — the same q plus p−q extra ones. 'Complete' and 'reduced' are relative labels for one specific comparison, not permanent model names."},{"id":"da-s2-f9","session":2,"front":"Partial F-test: hypotheses and formula","back":"H0: βq+1=...=βp=0. F = [(RES.DEV.RED−RES.DEV.COMP)/(p−q)] / [RES.DEV.COMP/(n−p−1)]. Under H0, F ~ Fisher(p−q, n−p−1)."},{"id":"da-s2-f10","session":2,"front":"When must you use the partial F-test instead of separate t-tests?","back":"When testing the joint significance of a group of variables together (e.g. all k−1 dummies of one categorical variable) — separate t-tests on each dummy don't answer this joint question."},{"id":"da-s2-f11","session":2,"front":"Global F-test: hypotheses and relation to the partial F-test","back":"H0: β1=...=βp=0 (the whole model has no effect). It's the partial F-test with the null model (only the intercept) as the reduced model: F = (EXP.DEV./p) / (RES.DEV./(n−p−1))."},{"id":"da-s2-f12","session":2,"front":"Why does the null model's residual deviance equal the total deviance?","back":"The null model has no explanatory variables, so its explained deviance is 0 — meaning all of its residual deviance is exactly the total deviance."},{"id":"da-s2-f13","session":2,"front":"What stays fixed across different models fit on the same sample/Y?","back":"Total deviance — it depends only on the observed yi values, never on which variables are included. Only residual and explained deviance change between models."},{"id":"da-s2-f14","session":2,"front":"What does 'not rejecting H0' mean in the global F-test?","back":"Insufficient evidence, at this α, that the variables are jointly significant — NOT proof that the model has zero effect."},{"id":"da-s2-f15","session":2,"front":"Partial F-test vs adjusted R² for model comparison","back":"Nested models → partial F-test is the correct inferential comparison. Non-nested models → the partial F-test is inapplicable; adjusted R² is the only (descriptive) option."},{"id":"da-s3-f1","session":3,"front":"Two hidden assumptions of the base linear-additive model","back":"Linearity: each xj's effect is constant regardless of its own starting value. Additivity: each variable's effect doesn't depend on the level of any other variable."},{"id":"da-s3-f2","session":3,"front":"Which tool fixes non-linearity, and which fixes non-additivity?","back":"Non-linearity → variable transformation (e.g. log(x), x²). Non-additivity → interaction term (a product of two variables)."},{"id":"da-s3-f3","session":3,"front":"Three practical rules for using variable transformations","back":"1) log(x) requires strictly positive x. 2) If you add x², keep the lower-order term x too. 3) Whether to transform is decided by context (does an accelerating/decelerating effect make sense?) plus the sample data (significance tests, adjusted R² for non-nested specs)."},{"id":"da-s3-f4","session":3,"front":"Derivative vs finite difference — when to use each","back":"Derivative (local rate) tells you the instantaneous marginal effect at one exact point of x — never read it as 'the change for one full extra unit.' Finite difference gives the real/total change in y-hat between two specific x values — use it for an actual comparison."},{"id":"da-s3-f5","session":3,"front":"Log(x) 1% shortcut formula and its limit","back":"y-hat_incr − y-hat ≈ 0.01·b1 for a 1% increase in x (model y-hat=b0+b1·log(x)). This is a first-order approximation only — not exact for large percentage jumps."},{"id":"da-s3-f6","session":3,"front":"Two equivalent readings of b1 in a model with log(x)","back":"1) A 1% rise in x → mean(Y) changes by about 0.01·b1. 2) b1 itself = the exact estimated change in mean(Y) for a one-unit increase in log(x)."},{"id":"da-s3-f7","session":3,"front":"Interaction term — definition and equation","back":"The product x1·x2 of two explanatory variables, added to a model that already has x1 and x2 as main effects, so the effect of one can depend on the level of the other. Y = β0+β1x1+β2x2+βint·x1x2+ε."},{"id":"da-s3-f8","session":3,"front":"Quantitative × dummy interaction: the two resulting lines","back":"x2=0: y-hat=b0+b1x1. x2=1: y-hat=(b0+b2)+(b1+bint)x1. Two lines with BOTH a different intercept AND a different slope — not just parallel shifts."},{"id":"da-s3-f9","session":3,"front":"What if the interaction coefficient bint is not significant?","back":"The model effectively collapses to two parallel lines (same slope, different intercepts) — always check bint's significance before concluding the effect genuinely differs by group."},{"id":"da-s3-f10","session":3,"front":"Interaction between a quantitative variable and a k-category variable","back":"Needs one product term per non-reference dummy (e.g. x1xB and x1xC for k=3). Produces k distinct lines, each with its own intercept AND its own slope on x1."},{"id":"da-s3-f11","session":3,"front":"Interaction between two quantitative variables — rewritten form","back":"y-hat = b0 + x1(b1+bint·x2) + b2x2. The effective slope on x1 is itself a function of x2 (and symmetrically, the effective slope on x2 depends on x1) — no single fixed slope exists anymore."},{"id":"da-s3-f12","session":3,"front":"Testing one interaction term vs several at once","back":"One interaction term → simple t-test on bint (H0: βint=0). Several interaction terms together (e.g. a whole categorical interaction, or a variable appearing in multiple forms) → partial F-test for joint significance."},{"id":"da-s3-f13","session":3,"front":"Why can't associative language ('increases/decreases') be read as causal in this session's examples?","back":"Finite-difference readings from a fitted regression model are statistical/associative statements, not causal claims — this warning applies throughout Session 3's worked examples."},{"id":"da-s3-f14","session":3,"front":"A variable appears as a main effect, in an interaction, and in a squared term — how do you judge if it matters overall?","back":"Test ALL its terms jointly with one partial F-test. A non-significant t-test on just one form (say the main effect alone) says nothing about the variable's overall relevance once its other forms are accounted for."},{"id":"da-s4-f1","session":4,"front":"Define multicollinearity","back":"The presence of a (linear) relationship among a model's explanatory variables — i.e. overlap in the informational content different x's carry about Y. Some degree of it is always present in real data."},{"id":"da-s4-f2","session":4,"front":"The real exam question about multicollinearity","back":"Not 'is there multicollinearity?' (there always is some) but 'is the level of multicollinearity high enough to cause a real problem?'"},{"id":"da-s4-f3","session":4,"front":"Main effect of high multicollinearity on hypothesis testing","back":"Standard errors of the involved coefficients inflate → |t| shrinks → p-values rise → higher chance of failing to reject H0: βj=0, i.e. wrongly concluding a variable isn't significant."},{"id":"da-s4-f4","session":4,"front":"Extreme multicollinearity signature","back":"None of the correlated variables is individually significant, yet the model overall is globally significant (high R², significant global F-test) — real total information, but no single variable's marginal contribution stands out."},{"id":"da-s4-f5","session":4,"front":"VIF formula and what it's computed from","back":"VIFj = 1/(1−Rj²), where Rj² comes from an auxiliary regression of xj on all the OTHER explanatory variables — this regression never uses Y at all."},{"id":"da-s4-f6","session":4,"front":"VIF threshold and dummy-variable equivalent","back":"VIF > 10 is the conventional (somewhat arbitrary) threshold for 'high' multicollinearity. For dummy variables, use the Generalized VIF (GVIF) instead — same interpretation, different technical definition."},{"id":"da-s4-f7","session":4,"front":"Three remedies for high multicollinearity","back":"1) Remove one of the correlated variables (risk: losing real information). 2) Increase sample size n (reduces standard errors generally). 3) Use factor analysis or PCA to combine the overlapping variables."},{"id":"da-s4-f8","session":4,"front":"What do the two 'residuals vs fitted values' plots check?","back":"Zero-mean/linearity (no systematic pattern expected) and homoskedasticity (constant spread expected — a funnel shape means heteroskedasticity)."},{"id":"da-s4-f9","session":4,"front":"Reading a residuals-vs-fitted plot: parabola shape vs funnel shape","back":"A systematic parabola-like curve → non-linearity. A widening/narrowing 'funnel' → heteroskedasticity. Different shapes, different violations, different fixes."},{"id":"da-s4-f10","session":4,"front":"What does a Q-Q plot check, and how do you read it?","back":"Checks normality of the (standardized) residuals. Points aligned on a straight line → normality plausible. Curvature/systematic deviation → non-normal errors."},{"id":"da-s4-f11","session":4,"front":"Log-lin vs log-log model — what's transformed","back":"Log-lin: log(Y) = β0+β1x1+ε (only Y is logged). Log-log: log(Y)=β0+β1log(x1)+ε (both Y and x1 are logged) — often used to restore linearity that log-lin alone would break."},{"id":"da-s4-f12","session":4,"front":"Once Y is log-transformed, how do you read a coefficient?","back":"As an approximate percentage effect on Y (b1% for a small % change in x1 in log-log; b1 in log(Y) per unit of x1 in log-lin) — no longer as raw units of Y."},{"id":"da-s4-f13","session":4,"front":"Outlier (regression outlier) — definition and rule of thumb","back":"An observation with a large residual — its predicted value is far from its actual observed Y. Rule of thumb: standardized residual > 3 in absolute value (sometimes 2)."},{"id":"da-s4-f14","session":4,"front":"Leverage point — definition and rule of thumb","back":"An observation with unusual values on the explanatory variables (not on Y). Rule of thumb: leverage exceeds (2p+1)/n or (3p+1)/n."},{"id":"da-s4-f15","session":4,"front":"Influential observation — definition, and the two measures used","back":"An observation whose removal would substantially change the regression results (typically the coefficients). dfbeta (per coefficient, threshold ≥2/√n) and Cook's distance (one combined value per observation, threshold ≥1, sometimes ≥0.5) formalize this."},{"id":"da-s4-f16","session":4,"front":"Is every outlier or leverage point automatically influential?","back":"No — influence must be checked directly with dfbeta or Cook's distance; an outlier or leverage point is not automatically influential."},{"id":"da-s5-f1","session":5,"front":"Define panel (longitudinal) data","back":"Data with both a cross-sectional dimension (n units) and a time dimension (T instants) at once — each unit observed repeatedly over time, giving n·T observations per variable."},{"id":"da-s5-f2","session":5,"front":"What does 'balanced panel' mean?","back":"Every unit is observed at every one of the T time instants, with no missing values — so a balanced panel with n units and T instants always has exactly n×T observations per variable."},{"id":"da-s5-f3","session":5,"front":"Why doesn't classic regression work well on panel data?","back":"Repeated observations of the same unit over time are generally not independent, violating the 'uncorrelated errors' assumption from Session 1."},{"id":"da-s5-f4","session":5,"front":"Pooling Model — definition and its core flaw","back":"Treats all n·T panel observations as if they were completely unrelated units, ignoring which observations belong to the same unit; estimated by plain OLS. Reintroduces the same omitted-variable/spurious-correlation risk as an ordinary cross-section."},{"id":"da-s5-f5","session":5,"front":"Fixed Effects Model (FEM) — error decomposition and interpretation of μi","back":"uit = μi + εit, where μi is a fixed/deterministic, unit-specific effect (unobserved heterogeneity, constant over time) and εit behaves like an ordinary regression error."},{"id":"da-s5-f6","session":5,"front":"FEM equivalent form with unit-specific intercepts","back":"Yit = αi + βxit + εit, with αi := α + μi — each unit gets its own intercept ('line of departure'), but all units share the same slope β."},{"id":"da-s5-f7","session":5,"front":"Random Effects Model (REM) — what's different from FEM","back":"Same error split uit=μi+εit, but μi is now random (not a fixed parameter) and must be uncorrelated with the x's. Only α and β are actually estimated — not n separate μi values."},{"id":"da-s5-f8","session":5,"front":"When is REM preferable to FEM, and why?","back":"When REM's validity assumption holds (μi uncorrelated with the x's) — REM then estimates far fewer parameters (only α, β vs α, β plus n μi's for FEM), making it more efficient."},{"id":"da-s5-f9","session":5,"front":"What happens to REM estimates if μi IS correlated with the x's?","back":"REM's estimates become inconsistent (unreliable) — this is exactly the condition the Hausman test checks."},{"id":"da-s5-f10","session":5,"front":"Individual-specific error μi vs idiosyncratic error εit","back":"μi: time-constant, persistent characteristics unique to each unit (e.g. innate worker skill, firm culture). εit: random fluctuations varying by both unit and time (short-term shocks, measurement noise)."},{"id":"da-s5-f11","session":5,"front":"How to read a large individual-error variance share vs a large idiosyncratic-error variance share","back":"Individual variance dominates → most unexplained variability comes from persistent between-unit differences (may hint at a missing time-constant variable, but coefficients stay reliable). Idiosyncratic variance dominates → most variability comes from within-unit fluctuations over time."},{"id":"da-s5-f12","session":5,"front":"Hausman test — hypotheses and decision rule","back":"H0: REM's assumptions hold (consistent and more efficient). H1: REM's assumptions fail (inconsistent). Reject H0 (p-value ≤ α) → use FEM. Don't reject H0 (p-value > α) → use REM."},{"id":"da-s5-f13","session":5,"front":"Common Hausman-test mistake to avoid","back":"Rejecting H0 means REM's hypotheses FAIL — you should switch to FEM, not 'keep REM.' Easy to invert by mistake."},{"id":"da-s5-f14","session":5,"front":"R syntax: FEM, REM, and the Hausman test","back":"FEM: plm(Y ~ X, data=..., model='within'). REM: plm(Y ~ X, data=..., model='random'). Hausman test: phtest(mod_fem, mod_rem) — order of the two models doesn't matter."},{"id":"da-s5-f15","session":5,"front":"Predicting for a specific unit in a FEM — which intercept to use","back":"Always use that unit's own fixef() intercept — never a generic or averaged intercept across units. fixef() gives one intercept per unit; the slope β stays common to all."},{"id":"da-s5-f16","session":5,"front":"Extending FEM/REM to multiple explanatory variables","back":"Works exactly like moving from simple to multiple regression — just add more xjit terms, each with its own βj. μi/εit play the same roles; transformations and interactions can be added the same way as in ordinary multiple regression."},{"id":"da-s6-f1","session":6,"front":"Define the odds of an event E with probability p.","back":"ODDS = p / (1-p), the ratio between the probability the event occurs and the probability it does not."},{"id":"da-s6-f2","session":6,"front":"What range does p cover, and what range does ODDS cover?","back":"p ranges between 0 and 1. ODDS ranges between 0 and +infinity. There is a one-to-one increasing correspondence between them: p = ODDS/(1+ODDS)."},{"id":"da-s6-f3","session":6,"front":"What is the quick rule linking ODDS to whether p is above or below 0.5?","back":"ODDS > 1 means p > 0.5. ODDS < 1 means p < 0.5. ODDS = 1 means p = 0.5."},{"id":"da-s6-f4","session":6,"front":"What happens to log(ODDS) as p approaches 0, and as p approaches 1?","back":"As p -> 0, log(ODDS) -> minus infinity. As p -> 1, log(ODDS) -> plus infinity. log(ODDS) is a strictly increasing function of p."},{"id":"da-s6-f5","session":6,"front":"In the logistic regression model, what type of variable is Y, and what does p represent for it?","back":"Y is a dichotomous (Bernoulli/dummy) variable: Y=1 with probability p, Y=0 with probability 1-p. p also equals the mean E(Y)."},{"id":"da-s6-f6","session":6,"front":"Write the standard (log-odds) formulation of the logit model equation.","back":"log(p/(1-p)) = beta0 + beta1x1 + ... + betapxp, i.e. the log-odds of Y=1 as a linear function of the explanatory variables."},{"id":"da-s6-f7","session":6,"front":"How are the logit model's coefficients estimated?","back":"By Maximum Likelihood Estimation (MLE), computed by R; the estimates are denoted b0, b1, ..., bp."},{"id":"da-s6-f8","session":6,"front":"For a quantitative xj with estimated coefficient bj, what does e^bj represent?","back":"The estimated odds ratio: the ratio of the odds of Y=1 for xj increased by one unit versus xj not increased, other variables held constant."},{"id":"da-s6-f9","session":6,"front":"For a dichotomous xj with estimated coefficient bj, what does e^bj represent?","back":"The estimated odds ratio between the odds of Y=1 when xj=1 and the odds of Y=1 when xj=0, other variables held constant."},{"id":"da-s6-f10","session":6,"front":"If bj > 0, what happens to the estimated odds and probability of Y=1?","back":"e^bj > 1, so the estimated odds increase, and therefore the estimated probability of the event also increases."},{"id":"da-s6-f11","session":6,"front":"If bj < 0, what happens to the estimated odds and probability of Y=1?","back":"e^bj < 1, so the estimated odds decrease, and therefore the estimated probability of the event also decreases."},{"id":"da-s6-f12","session":6,"front":"In the awareness example, b1(age)=0.2 so e^0.2=1.2214. State the interpretation.","back":"Holding x2 (gender) fixed, the estimated odds of awareness increase by 22.14% for each additional year of age (multiplied by 1.2214)."},{"id":"da-s6-f13","session":6,"front":"In the awareness example, b2(female)=-0.8 so e^-0.8=0.4493. State the interpretation.","back":"Holding age fixed, the estimated odds of awareness for females are 44.93% of the odds for males (i.e. lower)."},{"id":"da-s6-f14","session":6,"front":"What is H0 and H1 for the test on an individual logit coefficient betaj?","back":"H0: betaj = 0 (no effect in the population). H1: betaj is not equal to 0."},{"id":"da-s6-f15","session":6,"front":"How is the test statistic zoss computed for an individual coefficient, and what does it follow under H0?","back":"zoss = bj / SE(bj). Under H0 it follows approximately a standard normal distribution."},{"id":"da-s6-f16","session":6,"front":"What is the decision rule for rejecting H0: betaj=0 at significance level alpha?","back":"Reject H0 if |zoss| > z(alpha/2), or equivalently if p-value = 2*P(Z > |zoss|) < alpha."},{"id":"da-s6-f17","session":6,"front":"Why is it wrong to say e^bj tells you exactly how much the probability changes?","back":"e^bj is a multiplicative factor on the ODDS, not the probability. It tells you the direction of the probability change, but generally not its exact magnitude."},{"id":"da-s6-f18","session":6,"front":"What must you always state when interpreting a logit coefficient bj?","back":"That the interpretation holds with all other explanatory variables held constant (ceteris paribus), exactly as in linear regression."},{"id":"da-s7-f1","session":7,"front":"Why is a chi-square (LRT) test needed beyond the Session 6 individual Z-test?","back":"The Z-test only tests one coefficient at a time. To test whether a group of variables, or the whole model, is jointly significant, a chi-square based test is needed instead."},{"id":"da-s7-f2","session":7,"front":"What is the reduced model M_red and complete model M_compl in the partial chi-square test?","back":"M_red contains only x1,...,xq. M_compl contains all variables x1,...,xq,xq+1,...,xp. The test asks whether the extra variables xq+1,...,xp are jointly significant."},{"id":"da-s7-f3","session":7,"front":"How is the global chi-square test related to the partial chi-square test?","back":"The global test is a special case of the partial test where q=0, i.e. the reduced model is the null model (no explanatory variables)."},{"id":"da-s7-f4","session":7,"front":"Define residual deviance for a model M.","back":"RES.DEV = -2 log L(M), where L(M) is the maximum likelihood of the estimated model M. Lower residual deviance means a better fit."},{"id":"da-s7-f5","session":7,"front":"Write the chi-square test statistic for a group of variables, and its degrees of freedom under H0.","back":"chi2 = RES.DEV(M_red) - RES.DEV(M_compl), following approximately a chi-square distribution with p-q degrees of freedom under H0."},{"id":"da-s7-f6","session":7,"front":"Write the chi-square test statistic for the whole model (global test), and its degrees of freedom.","back":"chi2 = RES.DEV(M_null) - RES.DEV(M_compl), following approximately a chi-square distribution with p degrees of freedom (since q=0)."},{"id":"da-s7-f7","session":7,"front":"Why are these chi-square tests also called LRT?","back":"LRT stands for Likelihood Ratio Test, because the tests are based on the likelihood function (via the residual deviance, which is -2 log likelihood)."},{"id":"da-s7-f8","session":7,"front":"List, in order, what can be predicted from an estimated logit model for fixed explanatory variable values.","back":"The log-odds of Y=1, then the odds of Y=1 (exponentiate the log-odds), then the probability of Y=1 (via the odds-probability relationship), then the predicted value of Y itself (0 or 1)."},{"id":"da-s7-f9","session":7,"front":"What is the default rule (per the fiche) for predicting Y=1 versus Y=0 from a predicted probability p-hat0?","back":"y-hat0 = 1 if p-hat0 >= 0.5, y-hat0 = 0 if p-hat0 < 0.5 (a different threshold is also possible depending on context)."},{"id":"da-s7-f10","session":7,"front":"Define AIC for a logit model M.","back":"AIC = -2 log L(M) + 2(p+1), combining the residual deviance (fit) with a penalty of 2(p+1) for model complexity (p = number of explanatory variables)."},{"id":"da-s7-f11","session":7,"front":"According to AIC, is a lower or higher value considered a better model?","back":"Lower AIC indicates a better model, per this criterion."},{"id":"da-s7-f12","session":7,"front":"For comparing nested models, which tool is more appropriate, AIC or the partial chi-square test?","back":"The partial chi-square test remains the most appropriate tool for nested models; AIC is more useful for comparing models that are not necessarily nested."},{"id":"da-s7-f13","session":7,"front":"In the insurance example, AGE has coefficient -0.0389 (e^-0.0389=0.9618). State the interpretation.","back":"Holding vehicle category (VC) constant, a one-year increase in driver age is associated with an estimated 3.92% decrease in the odds of a high claim."},{"id":"da-s7-f14","session":7,"front":"In the insurance example, the global chi-square test gave chi2=77.344, 3 df, p-value < 2.2e-16. What is the conclusion?","back":"The model (AGE + VC) is globally significant compared to the null model; H0 (all coefficients = 0) is rejected."},{"id":"da-s7-f15","session":7,"front":"In the insurance example, what did the partial chi-square test on VC (comparing AGE-only to AGE+VC) conclude?","back":"chi2=69.202, 2 df, p-value close to 0: VC is jointly significant, it meaningfully improves the model beyond AGE alone."},{"id":"da-s7-f16","session":7,"front":"In the insurance example's confusion matrix, 168 of 200 predictions were correct. What percentage is this?","back":"84% correct predictions (168/200), combining 128 correctly predicted 'no' and 40 correctly predicted 'yes'."},{"id":"da-s7-f17","session":7,"front":"What does the 'response' option do in R's predict() function for a logit model?","back":"It returns the predicted probability directly. Without it, predict() returns the predicted log-odds, which must be exponentiated to get the predicted odds."},{"id":"da-s8-f1","session":8,"front":"When is a multinomial logit model used instead of a binary logit model?","back":"When the dependent variable is qualitative with k > 2 categories. If k=2, the model reduces to the binary logit model."},{"id":"da-s8-f2","session":8,"front":"How many equations does a multinomial logit model with k categories use?","back":"k-1 equations, one for each non-reference category, expressing its conditional log-odds relative to the chosen reference category."},{"id":"da-s8-f3","session":8,"front":"What do the k-1 equations of the multinomial logit model express?","back":"The conditional log-odds of each non-reference category Ai relative to the reference category A1, as a linear function of the explanatory variables."},{"id":"da-s8-f4","session":8,"front":"Are the coefficients of the same explanatory variable identical across the different equations of a multinomial logit model?","back":"No, they are generally different from one equation to another (e.g. beta12 is not equal to beta13 in general)."},{"id":"da-s8-f5","session":8,"front":"For a quantitative x1 with coefficient b12 in the equation for A2 vs reference A1, what is the percentage change formula for the odds?","back":"(e^b12 - 1) x 100%, the percentage change in the odds of A2 vs A1 for a one-unit increase in x1, other variables held constant."},{"id":"da-s8-f6","session":8,"front":"For a dichotomous x2 with coefficient b22 in the equation for A2 vs reference A1, what does (e^b22 - 1) x 100% represent?","back":"The percentage change in the odds of A2 vs A1 when x2=1 compared to x2=0, other variables held constant."},{"id":"da-s8-f7","session":8,"front":"What is H0 and H1 for the individual coefficient test betaji in the multinomial model?","back":"H0: betaji = 0 (xj has no effect on the conditional odds of Ai vs the reference). H1: betaji is not equal to 0."},{"id":"da-s8-f8","session":8,"front":"Which tests for the multinomial logit model are explicitly NOT covered in this course?","back":"Tests on groups of coefficients, or on the entire set of coefficients (chi-square based); only the individual coefficient test is examinable."},{"id":"da-s8-f9","session":8,"front":"Describe the general method to predict p1, ..., pk in a multinomial logit model.","back":"Substitute the fixed x values into the k-1 log-odds equations, exponentiate to get k-1 ratios pi/p1, then solve the linear system formed by those ratios plus the constraint sum(pi)=1."},{"id":"da-s8-f10","session":8,"front":"In the brand example, for a 30-year-old female (x1=30, x2=0), log(p2/p1)=2.1 and log(p3/p1)=1.4. What are the resulting probabilities?","back":"p1=0.0757, p2=0.6175, p3=0.3068, obtained by exponentiating (p2/p1=8.1662, p3/p1=4.0552) then solving with p1+p2+p3=1."},{"id":"da-s8-f11","session":8,"front":"In the student program-choice R example, which categories did R automatically choose as reference for 'program' and for 'ses'?","back":"'general' for program, and 'low' for ses. Always verify which reference category R selected rather than assuming it."},{"id":"da-s8-f12","session":8,"front":"In the student example, the coefficient of score in the academic-vs-general equation was 0.0579 (e^0.0579=1.0596). State the interpretation.","back":"Holding ses constant, a one-point increase in score is associated with an estimated 5.96% increase in the odds of choosing academic over general."},{"id":"da-s8-f13","session":8,"front":"In the student example, what were the predicted probabilities for a student with score=50, ses=middle?","back":"General approximately 0.2334, academic approximately 0.4159, vocation approximately 0.3507 (from predict(mod1, ..., type='probs'))."},{"id":"da-s8-f14","session":8,"front":"Why is it wrong to interpret b13 as 'the effect of x1 on the overall probability of A3'?","back":"b13 measures the effect of x1 on the conditional odds of A3 relative to the reference category A1 only, never a direct statement about the raw probability p3."},{"id":"da-s8-f15","session":8,"front":"Why can't b12 and b13 be directly compared as if they measured the same contrast?","back":"Each coefficient describes a different category-vs-reference contrast (A2 vs A1, and A3 vs A1 respectively); they are not the same comparison, so comparing them naively is a common mistake."},{"id":"da-s8-f16","session":8,"front":"In R's multinom() output for the student example, what package and function are used?","back":"The multinom() function from the nnet package (which must be installed and loaded) is used to fit the multinomial logistic regression."},{"id":"da-s9-f1","session":9,"front":"What is a univariate time series?","back":"A set of numerical data ordered in time: one variable measured at successive (usually evenly spaced) points in time."},{"id":"da-s9-f2","session":9,"front":"What are the main objectives of time series analysis?","back":"Study the long-term trend and seasonal fluctuations; study persistence (how long shock effects last); predict future values."},{"id":"da-s9-f3","session":9,"front":"Classical vs modern time series analysis?","back":"Classical: descriptive procedures identifying trend, seasonality, irregularity. Modern: probabilistic models (stochastic processes) fitted by statistical procedures."},{"id":"da-s9-f4","session":9,"front":"Define the backshift operator B and the difference operator D.","back":"B y_t = y_{t-1} (B^0 = 1, B^2 y_t = y_{t-2}). D y_t = y_t - y_{t-1} = (1-B) y_t."},{"id":"da-s9-f5","session":9,"front":"In base R, how do you compute B y_t with lag()?","back":"lag(y, -1): base-R lag moves the series FORWARD (lag(y,1) = y_{t+1}), so the backshift needs a negative lag."},{"id":"da-s9-f6","session":9,"front":"How is a centered moving average of EVEN order k computed?","back":"Weighted average of k+1 values around t (k/2 before, value at t, k/2 after): extremes get weight 1/(2k), the others 1/k. You lose k/2 values at each end."},{"id":"da-s9-f7","session":9,"front":"Why does a moving average of order k remove seasonality of period k?","back":"Each averaged value spans exactly one full period with the same weight on each period position, so regular oscillations of period k cancel out; the MA also smooths the irregular component."},{"id":"da-s9-f8","session":9,"front":"Name the three components of a time series and their meaning.","back":"Trend (trend-cycle): medium/long-term behaviour. Seasonality: constant-periodicity variations (monthly, quarterly...). Irregular/error: everything else, random fluctuations without regular periodicity or trend."},{"id":"da-s9-f9","session":9,"front":"Multiplicative vs additive decomposition: formulas and index centers?","back":"Multiplicative: y = T x S x E, seasonal indices around 1, divisions. Additive: y = T + S + E, indices around 0, subtractions. A log transform turns multiplicative into additive."},{"id":"da-s9-f10","session":9,"front":"What are the 4 steps of the classical decomposition (multiplicative)?","back":"1) MA of order = seasonal period (estimates T). 2) y_t / MA (estimates S x E). 3) Period-by-period averages renormalized to mean 1 (= seasonal indices). 4) Divide step-2 ratios by the indices (= irregular component, random around 1)."},{"id":"da-s10-f1","session":10,"front":"What does it mean that a time series is a realization of a stochastic process?","back":"The process (Y_t) is a countable family of random variables; the observed series y_1..y_T is one finite realization of it. Probabilistic analysis builds parametric models for the process."},{"id":"da-s10-f2","session":10,"front":"Define the mean, variance and autocorrelation functions of a process.","back":"mu_t = E[Y_t]; sigma^2_t = Var[Y_t]; rho_{k,t} = Corr[Y_t, Y_{t-k}] = Cov(Y_t,Y_{t-k}) / (sigma_t sigma_{t-k}). rho_{0,t} = 1 always."},{"id":"da-s10-f3","session":10,"front":"Define weak stationarity.","back":"Mean and variance constant over time, and autocorrelation at lag k depends only on k (not on t): E[Y_t]=mu, Var[Y_t]=sigma^2, Corr[Y_t,Y_{t-k}]=rho_k."},{"id":"da-s10-f4","session":10,"front":"ACF vs PACF: what is the difference?","back":"ACF at lag k includes correlations transmitted through intermediate time points; PACF at lag k is the correlation between Y_t and Y_{t-k} after removing the linear effect of Y_{t-1},...,Y_{t-k+1}."},{"id":"da-s10-f5","session":10,"front":"Define a white noise process and its properties.","back":"Zero mean, constant variance sigma^2, zero autocorrelations for k != 0. It is (weakly) stationary, completely random and unpredictable; Gaussian white noise if the variables are jointly normal."},{"id":"da-s10-f6","session":10,"front":"What should the plot and autocorrelograms of a white noise series look like?","back":"Irregular random fluctuations of similar magnitude around zero; no significant correlations in the ACF and PACF."},{"id":"da-s10-f7","session":10,"front":"Define a random walk and give its mean, variance and autocorrelation functions.","back":"Y_t = Y_{t-1} + eps_t (eps white noise) = cumulated sum of all past shocks. Mean 0; Var(Y_t) = t sigma^2; rho_{k,t} = 1 - k/t. NOT stationary."},{"id":"da-s10-f8","session":10,"front":"Why do shocks persist indefinitely in a random walk?","back":"Because Y_t is the unweighted cumulative sum of all past white noise values: each shock stays in the level forever."},{"id":"da-s10-f9","session":10,"front":"Random walk with drift: equation and moments?","back":"Y_t = c + Y_{t-1} + eps_t. Mean = t*c (deterministic linear trend, sign of c), variance = t sigma^2, rho_{k,t} = 1 - k/t. Still non-stationary."},{"id":"da-s10-f10","session":10,"front":"Which R functions plot a series and its autocorrelograms?","back":"plot(y) for the series; acf(y) for the ACF; pacf(y) for the PACF."},{"id":"da-s11-f1","session":11,"front":"Write the AR(p) equation and the AR(1) stationarity condition.","back":"Y_t = phi_0 + phi_1 Y_{t-1} + ... + phi_p Y_{t-p} + eps_t. AR(1) stationary iff |phi_1| < 1 (phi_1 = 1 gives a random walk)."},{"id":"da-s11-f2","session":11,"front":"For a stationary AR(1): mean, variance, autocorrelations?","back":"mu = phi_0/(1-phi_1); Var = sigma^2/(1-phi_1^2); rho_k = phi_1^k (decays with k; alternates sign if phi_1 < 0)."},{"id":"da-s11-f3","session":11,"front":"ACF/PACF signature of an AR(p) vs an MA(q)?","back":"AR: ACF decays (exponential/sinusoidal), PACF cuts off with a last peak at order p. MA: ACF cuts off after order q, PACF decays. The two patterns are reversed."},{"id":"da-s11-f4","session":11,"front":"Write the MA(q) equation. Is it stationary?","back":"Y_t = eps_t + theta_1 eps_{t-1} + ... + theta_q eps_{t-q} (theta_0 = 1). Always stationary, for any coefficients and any q; autocorrelations are zero for k > q."},{"id":"da-s11-f5","session":11,"front":"MA(1): what is rho_1 and its range?","back":"rho_1 = theta_1/(1+theta_1^2), the only non-zero autocorrelation; it lies in [-0.5, 0.5] (max 0.5 at theta_1=1, min -0.5 at theta_1=-1). theta_1=0 gives white noise."},{"id":"da-s11-f6","session":11,"front":"What does the 'I' in ARIMA(p,d,q) mean, and what does 'differencing d times' mean?","back":"Integration, the inverse of differencing: the model applies to the series differenced d times (to make it stationary). D^2 y = D(Dy) - the difference of the difference, NOT a difference of order d."},{"id":"da-s11-f7","session":11,"front":"Give the ARIMA special cases.","back":"ARIMA(p,0,q)=ARMA(p,q); (p,0,0)=AR(p); (0,0,q)=MA(q); (0,0,0) with phi_0=0 = white noise; (0,1,0)=random walk (with drift if phi_0 != 0)."},{"id":"da-s11-f8","session":11,"front":"Outline the 4 steps of ARIMA model selection.","back":"1) Choose d (plot + tests; avoid d > 2). 2) Choose p and q (PACF peak at p, ACF peak at q; or minimize AIC). 3) Estimate parameters (typically MLE). 4) Diagnose: residuals should look like white noise."},{"id":"da-s11-f9","session":11,"front":"arima() vs auto.arima() in R?","back":"arima(y, order=c(p,d,q)) estimates a fixed-order ARIMA (MLE default; include.mean option). auto.arima(y) selects orders automatically (default: AIC minimization); lambda=\"auto\" adds an automatic Box-Cox transform. Always check residuals afterwards."},{"id":"da-s11-f10","session":11,"front":"ADF test and Ljung-Box test: null hypotheses and R functions?","back":"ADF (adf.test, tseries): H0 = non-stationary, H1 = stationary; rejecting H0 is evidence of stationarity. Ljung-Box (Box.test(x, lag=k, type=\"Ljung-Box\")): H0 = all autocorrelations up to lag k are zero."},{"id":"da-s12-f1","session":12,"front":"What is a forecast, formally?","back":"A function of the observed values y_0..y_T used to predict y_{T+1} (or y_{T+h}); the choice depends on trend, seasonality and the model, and can target minimizing an error measure."},{"id":"da-s12-f2","session":12,"front":"Naive method and simple mean method?","back":"Naive: y_hat_{T+h} = y_T (last observed value). Simple mean: y_hat_{T+h} = average of all observations. Both are weighted averages with extreme weight schemes."},{"id":"da-s12-f3","session":12,"front":"Simple exponential smoothing: formula and role of alpha?","back":"y_hat_{T+h} = alpha y_T + alpha(1-alpha) y_{T-1} + alpha(1-alpha)^2 y_{T-2} + ... Weights decay exponentially; alpha near 1 = little smoothing (limit = naive), alpha near 0 = nearly equal weights (limit = simple mean)."},{"id":"da-s12-f4","session":12,"front":"SES level and forecast equations?","back":"Level: l_t = alpha y_t + (1-alpha) l_{t-1}, l_0 = y_0. Forecast: y_hat_{T+h} = l_T (constant for all h)."},{"id":"da-s12-f5","session":12,"front":"When is SES appropriate, and what do Holt and Holt-Winters add?","back":"SES suits series with no trend and no seasonality. Holt adds a trend equation (b_t = beta(l_t - l_{t-1}) + (1-beta) b_{t-1}; forecast l_T + h b_T). Holt-Winters adds a seasonal equation (additive or multiplicative variant)."},{"id":"da-s12-f6","session":12,"front":"How are the smoothing parameters selected? What is the MSE here?","back":"By minimizing the MSE: the average of the squared differences between observed and predicted values at each observed time point (residuals / forecast errors)."},{"id":"da-s12-f7","session":12,"front":"Holt-Winters in R?","back":"HW <- HoltWinters(series, seasonal = \"mult\") (default additive); predict(HW, 5) for 5 forecasts; predict(HW, 5, prediction.interval=TRUE, level=0.9) adds prediction intervals (wider for longer horizons)."},{"id":"da-s12-f8","session":12,"front":"How do you forecast with an estimated AR(p)?","back":"Substitute the estimated coefficients into the equation: y_hat_{T+1} = phi0_hat + phi1_hat y_T + ... + phip_hat y_{T-p+1}. For h=2, iterate using y_hat_{T+1} in place of the unknown y_{T+1}."},{"id":"da-s12-f9","session":12,"front":"The 3 substitution rules for ARMA forecasting?","back":"1) Parameters -> their estimates. 2) Errors eps_t -> residuals e_t at observed times, 0 at future times. 3) Future series values -> their forecasts."},{"id":"da-s12-f10","session":12,"front":"How does forecasting work for ARIMA (d >= 1), and which R function computes it?","back":"Forecast the differenced series, then un-difference (for d=1: y_hat_{T+1} = y_hat'_{T+1} + y_T). Intervals usually assume Gaussian white noise. R: forecast(model, h) from the forecast package; the object carries point forecasts plus 80% and 95% intervals."}],"cr":[{"id":"cr-s1-f1","session":1,"front":"Agency problem","back":"Conflict of interest between a principal (owner) and an agent (manager), arising because their interests may diverge once ownership is separated from control."},{"id":"cr-s1-f2","session":1,"front":"Information asymmetry","back":"The condition where managers possess superior information about the firm relative to shareholders and other external users."},{"id":"cr-s1-f3","session":1,"front":"Two motives for regulation","back":"Market imperfections (objective: improve economic efficiency) and protection of unsophisticated investors (objective: redistribute wealth)."},{"id":"cr-s1-f4","session":1,"front":"Three sources of regulation","back":"Legislation, accounting standards, and stock exchange regulations."},{"id":"cr-s1-f5","session":1,"front":"GAAP","back":"The complete set of accounting regulations and conventions applicable in a given jurisdiction (e.g. UK GAAP, US GAAP), as opposed to IFRS which is the IASB's global standard set."},{"id":"cr-s1-f6","session":1,"front":"IFRS Foundation","back":"The oversight body that appoints and funds the IASB and governs its operations; monitored by the Monitoring Board."},{"id":"cr-s1-f7","session":1,"front":"IASB","back":"Independent board of 14 members that develops and amends IFRS Accounting Standards."},{"id":"cr-s1-f8","session":1,"front":"IFRS Advisory Council","back":"The body that advises the IASB on its agenda and priorities."},{"id":"cr-s1-f9","session":1,"front":"IFRS Interpretations Committee (IFRIC)","back":"The committee that interprets IFRS and provides practical guidance on matters not covered by the standards."},{"id":"cr-s1-f10","session":1,"front":"IASB's three formal objectives","back":"1) Develop a single set of high-quality, understandable, enforceable global standards; 2) promote their use and rigorous application; 3) work with national standard-setters to converge national standards with IFRS."},{"id":"cr-s1-f11","session":1,"front":"IASB due process (6 steps)","back":"Topic identification -> apply Conceptual Framework -> consultation with national standard-setters/Foundation/Advisory Council -> discussion document + comments -> exposure draft + comments -> final standard."},{"id":"cr-s1-f12","session":1,"front":"Structure of an IFRS standard","back":"Introduction; objectives and scope; definitions; body of the standard; effective date and transitional provisions; formal IASB approval (+ dissenting opinions); basis for conclusions; application guidance/illustrative examples."},{"id":"cr-s1-f13","session":1,"front":"Global IFRS adoption status","back":"Required for listed companies in 100+ countries (all EU from 2005), permitted in 14 more; not mandatory in the US, though the SEC has allowed IFRS filings by foreign private issuers without reconciliation since Nov 2007."},{"id":"cr-s1-f14","session":1,"front":"EU endorsement mechanism","back":"The European Commission oversees the framework; the IASB creates IFRS; the ARC (advised by EFRAG/SARG) must individually endorse each standard before it is mandatory in the EU; enforcement is national (e.g. Consob, FRRP), coordinated by ESMA (via EECS)."},{"id":"cr-s1-f15","session":1,"front":"Principle (definition)","back":"A general statement intended to support the true and fair presentation of the economic consequences of transactions — a guide to action, not a precise rule."},{"id":"cr-s1-f16","session":1,"front":"Rule (definition)","back":"A means of establishing an unambiguous decision-making method; whether following the rules actually achieves conformity to the underlying principle is a matter of judgement."},{"id":"cr-s1-f17","session":1,"front":"Principles vs rules, the exam-safe framing","back":"Officially a false distinction — the difference is not clear-cut, and a combination of both is generally necessary and appropriate; don't overstate the US GAAP (rules) vs IFRS (principles) framing."},{"id":"cr-s1-f18","session":1,"front":"IFRS1","back":"Governs an entity's first IFRS financial statements; requires certain reconciliations between local GAAP and IFRS for the transition period."},{"id":"cr-s1-f19","session":1,"front":"Stewardship under the Revised Conceptual Framework","back":"Folded into the single decision-usefulness objective, not treated as a second, separate objective."},{"id":"cr-s2-f1","session":2,"front":"Conceptual Framework status","back":"Not itself an IFRS; if it conflicts with a specific IFRS Standard, the IFRS prevails."},{"id":"cr-s2-f2","session":2,"front":"Conceptual Framework's three stated purposes","back":"Assist regulators (consistent standards), assist preparers (when no Standard applies or a choice is allowed), assist users (interpreting Standards)."},{"id":"cr-s2-f3","session":2,"front":"Eight chapters of the Conceptual Framework","back":"Objective of financial reporting; qualitative characteristics; financial statements and the reporting entity; elements; recognition/de-recognition; measurement; presentation and disclosure; concepts of capital and capital maintenance."},{"id":"cr-s2-f4","session":2,"front":"Sole objective of general purpose financial reporting","back":"Provide information useful to existing/potential investors, lenders and other creditors for decisions about providing resources to the entity; stewardship is included, not separate."},{"id":"cr-s2-f5","session":2,"front":"Relevance","back":"Information is relevant if capable of making a difference to users' decisions, via predictive value, confirmatory value, or both."},{"id":"cr-s2-f6","session":2,"front":"Predictive value vs confirmatory value","back":"Predictive value = useful as an input to users' own predictions about the future. Confirmatory value = confirms or changes past/present expectations. Highly predictable info (e.g. straight-line depreciation) may still lack predictive value for a given purpose."},{"id":"cr-s2-f7","session":2,"front":"Faithful representation","back":"Financial statements present fairly when information is reliable, unbiased and represents what it purports to represent; requires completeness, neutrality, and freedom from MATERIAL (not all) error."},{"id":"cr-s2-f8","session":2,"front":"Completeness","back":"The depiction includes all information necessary for faithful representation of the phenomenon; an omission can make information false or misleading."},{"id":"cr-s2-f9","session":2,"front":"Neutrality","back":"Absence of bias intended to attain a predetermined result or induce particular behaviour."},{"id":"cr-s2-f10","session":2,"front":"Prudence (Revised Framework)","back":"The exercise of caution under uncertainty; supports neutrality by preventing overstatement/understatement of assets, liabilities, income or expenses."},{"id":"cr-s2-f11","session":2,"front":"Four enhancing characteristics","back":"Comparability (consistent treatments across entities/time), verifiability (direct/indirect corroboration), timeliness (available in time to influence decisions), understandability (clear, concise presentation)."},{"id":"cr-s2-f12","session":2,"front":"Five elements of financial statements","back":"Asset, liability, equity (elements of financial position); income and expenses (elements of financial performance)."},{"id":"cr-s2-f13","session":2,"front":"Equity (definition)","back":"The residual interest in the assets of the entity after deducting all its liabilities."},{"id":"cr-s2-f14","session":2,"front":"Income (definition)","back":"Increases in assets or decreases in liabilities that result in increases in equity, other than contributions from equity holders."},{"id":"cr-s2-f15","session":2,"front":"Expenses (definition)","back":"Decreases in assets or increases in liabilities that result in decreases in equity, other than distributions to equity holders."},{"id":"cr-s2-f16","session":2,"front":"Going concern vs accruals basis","back":"Going concern: entity assumed to continue operating for the foreseeable future. Accruals: transactions recognised when they occur, not when cash is paid/received."},{"id":"cr-s2-f17","session":2,"front":"Three recognition criteria","back":"Relevant information about the element; a faithful representation of the element; benefits of the information exceed the costs of providing it."},{"id":"cr-s2-f18","session":2,"front":"Two measurement bases","back":"Historical cost (amount paid/received at acquisition/incurrence) vs current value (fair value; or value in use for assets / fulfilment value for liabilities)."},{"id":"cr-s2-f19","session":2,"front":"Full disclosure constraints","back":"Materiality (omission/misstatement could influence user decisions) and the cost constraint (benefits must justify costs of providing information)."},{"id":"cr-s2-f20","session":2,"front":"Common exam trap: reliability","back":"The current framework's term is 'faithful representation,' not 'reliability' — don't use the old term as if it were the fundamental characteristic."},{"id":"cr-s3-f1","session":3,"front":"IAS1 objective","back":"Provide information about financial position, performance and cash flows useful to a wide range of users for economic decisions, via 4 primary statements plus notes."},{"id":"cr-s3-f2","session":3,"front":"IAS1 five components","back":"Statement of financial position; statement of profit or loss and OCI; statement of changes in equity; statement of cash flows (IAS7); the notes."},{"id":"cr-s3-f3","session":3,"front":"Going concern basis","back":"Financial statements are generally prepared assuming the entity will continue operating, unless it intends to cease trading or has no realistic alternative."},{"id":"cr-s3-f4","session":3,"front":"Accruals basis exception","back":"All statements are accruals-based except the statement of cash flows, which is cash-based by nature."},{"id":"cr-s3-f5","session":3,"front":"Current asset test (4 conditions, any one)","back":"Expected to be realised in the normal operating cycle; held for trading; expected to be realised within 12 months; or is cash/cash equivalent (IAS7). Satisfying ANY ONE makes it current."},{"id":"cr-s3-f6","session":3,"front":"Current liability test (4 conditions, any one)","back":"Due to be settled in the normal operating cycle; held for trading; due within 12 months; or the entity lacks the right to defer settlement 12+ months. ANY ONE condition suffices."},{"id":"cr-s3-f7","session":3,"front":"Offsetting rule","back":"Assets/liabilities and income/expenses must not be offset against each other, UNLESS another IFRS Standard specifically permits or requires it."},{"id":"cr-s3-f8","session":3,"front":"Statement of changes in equity formula","back":"Closing balance = Opening balance + total comprehensive income +/- accounting-policy-change effects + share issues - dividends paid, tracked per component of equity."},{"id":"cr-s3-f9","session":3,"front":"IFRS18","back":"Issued April 2024, supersedes IAS1, mandatory for periods beginning on or after 1 Jan 2027; introduces 5 P&L categories and new mandatory subtotals plus note disclosures for management-defined performance measures."},{"id":"cr-s3-f10","session":3,"front":"IFRS18's five P&L categories","back":"Operating, investing, financing, income taxes, discontinued operations."},{"id":"cr-s3-f11","session":3,"front":"IFRS18 mandatory subtotals","back":"Operating profit or loss; profit or loss before financing and income taxes; profit or loss."},{"id":"cr-s3-f12","session":3,"front":"Accounting policy hierarchy (no IFRS applies)","back":"1) IFRS dealing with similar/related issues; 2) the Conceptual Framework; 3) other standard-setters' pronouncements; 4) accounting literature and industry practice."},{"id":"cr-s3-f13","session":3,"front":"Change in accounting policy","back":"Permitted only if required by an IFRS, or if it gives more reliable/relevant information. IFRS-driven changes follow that standard's own transition rules; otherwise, retrospective (restate comparatives)."},{"id":"cr-s3-f14","session":3,"front":"Accounting estimate change","back":"Always accounted for PROSPECTIVELY — no restatement of prior comparatives (contrast with policy changes and material errors, which are retrospective)."},{"id":"cr-s3-f15","session":3,"front":"Prior period errors","back":"Omissions/misstatements from failing to use reliable information that was available and reasonably obtainable when the prior statements were authorised. Material errors are corrected retrospectively."},{"id":"cr-s3-f16","session":3,"front":"Adjusting event (IAS10)","back":"Evidence of conditions existing at period-end; requires the financial statements to be adjusted."},{"id":"cr-s3-f17","session":3,"front":"Non-adjusting event (IAS10)","back":"Indicative of conditions arising after period-end; no adjustment, but must be disclosed if material."},{"id":"cr-s3-f18","session":3,"front":"IAS1 vs IAS8 roles","back":"IAS1: what policies must be disclosed (the notes requirement). IAS8: how policies are selected, and when/how they may be changed."},{"id":"cr-s4-f1","session":4,"front":"Statement of cash flows (purpose)","back":"Reports cash inflows/outflows during a period; exists because profit (accruals-based) is not a reliable indicator of cash health."},{"id":"cr-s4-f2","session":4,"front":"Cash (IAS7)","back":"Cash on hand and demand deposits; a bank overdraft is treated as negative cash (netted, not a financing item)."},{"id":"cr-s4-f3","session":4,"front":"Cash equivalents (IAS7)","back":"Short-term, highly liquid investments readily convertible to known cash amounts, with insignificant risk of value change."},{"id":"cr-s4-f4","session":4,"front":"Three IAS7 activity classes","back":"Operating (principal revenue-producing activities), investing (acquisition/disposal of long-term assets/investments), financing (changes in size/composition of equity and borrowings)."},{"id":"cr-s4-f5","session":4,"front":"Direct method","back":"Discloses major classes of operating receipts and payments individually (e.g. cash from customers, cash to suppliers, cash to employees)."},{"id":"cr-s4-f6","session":4,"front":"Indirect method (pre-IFRS18)","back":"Starts from profit before tax, adds back non-cash expenses, subtracts non-cash income, adjusts for working-capital changes, strips out non-operating items."},{"id":"cr-s4-f7","session":4,"front":"Indirect method formula","back":"Cash from operations = Profit before tax + non-cash expenses - non-cash income +/- working capital changes - non-operating items."},{"id":"cr-s4-f8","session":4,"front":"Working capital sign rule","back":"A decrease in a current asset (other than cash) or an increase in a current liability = source of cash (add); the reverse = use of cash (subtract)."},{"id":"cr-s4-f9","session":4,"front":"Pre-IFRS18 interest/dividends/tax treatment","back":"Interest received & dividends received -> investing. Interest paid -> usually operating (or financing). Dividends paid -> operating or financing (choice). Tax -> operating unless tied to investing/financing."},{"id":"cr-s4-f10","session":4,"front":"IFRS18 amendments to IAS7 (3 changes)","back":"1) Indirect method starts from an IFRS18 subtotal, not profit before tax. 2) Dividends paid -> financing (mandatory). 3) Interest paid -> financing in most cases (mandatory)."},{"id":"cr-s4-f11","session":4,"front":"IAS7 disclosure requirement","back":"Reconcile cash/cash-equivalent components to the statement of financial position (mandatory); segment cash flow analysis and undrawn borrowing facilities are only encouraged."},{"id":"cr-s4-f12","session":4,"front":"IFRS18 effective date (as for IAS1)","back":"Mandatory for periods beginning on or after 1 January 2027."},{"id":"cr-s4-f13","session":4,"front":"Common trap: IAS7 vs IFRS18 categories","back":"IAS7's operating/investing/financing (for cash flows) and IFRS18's five P&L categories (operating/investing/financing/income taxes/discontinued operations) are separate schemes for separate statements."},{"id":"cr-s5-f1","session":5,"front":"Three standards, three jobs","back":"IAS32 = presentation/classification (financial asset/liability/equity). IFRS9 = recognition/measurement. IFRS7 = disclosure."},{"id":"cr-s5-f2","session":5,"front":"Financial instrument (IAS32)","back":"Any contract giving rise to a financial asset of one entity and a financial liability or equity instrument of another."},{"id":"cr-s5-f3","session":5,"front":"Financial asset (IAS32)","back":"Cash, an equity instrument of another entity, or a contractual right to receive cash (or another financial asset) from another entity, among other categories."},{"id":"cr-s5-f4","session":5,"front":"Financial liability (IAS32)","back":"A contractual obligation to deliver cash (or another financial asset) to another entity."},{"id":"cr-s5-f5","session":5,"front":"Equity instrument (IAS32)","back":"Any contract evidencing a residual interest in the assets of an entity after deducting all of its liabilities."},{"id":"cr-s5-f6","session":5,"front":"Derivative","back":"Transfers the financial risks of an underlying primary financial instrument; parties effectively take bets on the underlying's future value."},{"id":"cr-s5-f7","session":5,"front":"Two-part equity test (both required)","back":"Part A: no contractual obligation to deliver cash/exchange unfavourably. Part B: will/may be settled in the issuer's own equity instruments. Must satisfy BOTH to be equity."},{"id":"cr-s5-f8","session":5,"front":"Redeemable preference shares","back":"Fail Part A (obligation to redeem in cash) -> classified as a liability, not equity; their 'dividends' are an expense."},{"id":"cr-s5-f9","session":5,"front":"Compound financial instrument","back":"Contains both a liability component and an equity component (e.g. convertible bonds); IAS32 requires split accounting at issuance."},{"id":"cr-s5-f10","session":5,"front":"Split accounting method","back":"Liability component = PV of contractual cash flows discounted at the MARKET rate for an equivalent non-convertible instrument. Equity component = issue proceeds - liability component (residual)."},{"id":"cr-s5-f11","session":5,"front":"Presenting interest/dividends by classification","back":"Liability-related interest/dividends -> profit or loss (expense). Equity distributions -> debited directly to equity, never P&L."},{"id":"cr-s5-f12","session":5,"front":"Recognition (IFRS9) vs measurement (IFRS9)","back":"Recognition = WHEN an asset/liability first appears on the balance sheet. Measurement = the AMOUNT at which it is shown, initially and subsequently."},{"id":"cr-s6-f1","session":6,"front":"IFRS9 recognition rule","back":"A financial asset/liability is recognised only when the entity becomes party to the contractual provisions — the contract, not the cash flow, triggers recognition."},{"id":"cr-s6-f2","session":6,"front":"Initial measurement (assets AND liabilities)","back":"Always fair value at initial recognition, regardless of the category used for subsequent measurement."},{"id":"cr-s6-f3","session":6,"front":"Four measurement categories for financial assets","back":"1) Debt at amortised cost. 2) Debt at FVOCI (recycles to P&L on derecognition). 3) Equity designated at FVOCI (never recycles). 4) FVPL (default/residual — debt, derivatives, equity)."},{"id":"cr-s6-f4","session":6,"front":"Equity-FVOCI designation","back":"An irrevocable designation made at initial recognition, not automatic — must be elected instrument by instrument."},{"id":"cr-s6-f5","session":6,"front":"Amortised cost two-part test","back":"BOTH required: (1) SPPI — cash flows are solely payments of principal and interest; (2) hold-to-collect business model objective."},{"id":"cr-s6-f6","session":6,"front":"Amortised cost (definition)","back":"Initial carrying amount, plus interest earned to date at the effective rate, minus repayments received to date."},{"id":"cr-s6-f7","session":6,"front":"Effective interest method","back":"Calculates interest earned using the rate that exactly discounts estimated future cash receipts to the initial carrying amount; folds in premiums/discounts, not just stated interest."},{"id":"cr-s6-f8","session":6,"front":"Amortised cost formula","back":"Amortised cost = Initial carrying amount + Interest earned (effective rate) - Repayments received to date."},{"id":"cr-s6-f9","session":6,"front":"Zero-coupon bond mechanics","back":"Issued at PV of face value discounted at the effective (yield) rate; carrying amount accretes toward face value via accrued interest each period, with no cash interest paid until maturity."},{"id":"cr-s6-f10","session":6,"front":"Subsequent measurement of liabilities","back":"Amortised cost by default (effective interest method); fair value if held for trading (gains/losses usually to P&L)."},{"id":"cr-s6-f11","session":6,"front":"Trade receivables/payables practical expedient","back":"May use the original invoice amount instead of discounting, when the discounting effect is immaterial."},{"id":"cr-s6-f12","session":6,"front":"Where P&L/OCI land on the balance sheet","back":"Profit or loss flows into retained earnings; OCI flows into accumulated OCI; the two together form total comprehensive income for the period."},{"id":"cr-s6-f13","session":6,"front":"IFRS9 effective date","back":"Replaced IAS39 from 1 January 2018 (earlier application permitted); applies to all entities and financial instruments, subject to 11 scope exceptions."},{"id":"cr-s7-f1","session":7,"front":"IFRS9's measurement scope","back":"Spans initial measurement, subsequent measurement, reclassifications, gains/losses, AND impairment/uncollectability — impairment is part of IFRS9, not separate."},{"id":"cr-s7-f2","session":7,"front":"Expected credit loss (ECL) model","back":"Forward-looking: a loss allowance is recognised for expected credit losses from initial recognition onward, updated each reporting date — replaces IAS39's 'incurred loss' approach."},{"id":"cr-s7-f3","session":7,"front":"Three-stage ECL structure","back":"Stage 1 (no significant credit-risk increase): 12-month ECL. Stage 2 (significant increase, not yet impaired): lifetime ECL. Stage 3 (credit-impaired): lifetime ECL + interest on NET carrying amount."},{"id":"cr-s7-f4","session":7,"front":"IFRS7 purpose","back":"Let users evaluate (a) the significance of financial instruments for the entity's position/performance, and (b) the nature/extent of risks from them and how they're managed."},{"id":"cr-s7-f5","session":7,"front":"IFRS7's three risk categories","back":"Market risk (price exposure: rates, FX, equity prices), credit risk (counterparty default), liquidity risk (difficulty meeting financial-liability obligations)."},{"id":"cr-s7-f6","session":7,"front":"IFRS7 vs IFRS9 vs IAS32 (recap)","back":"IAS32 = classification. IFRS9 = recognition, measurement, reclassification, gains/losses, impairment. IFRS7 = disclosure of significance and risk exposure."},{"id":"cr-s8-f1","session":8,"front":"Berkshire Q1 2018 case shock","back":"Reported net loss of $(1.138)bn despite $5.288bn operating earnings, driven by ~$6.2bn unrealised equity-portfolio losses newly required (by US GAAP ASU 2016-01) to flow through earnings."},{"id":"cr-s8-f2","session":8,"front":"ASU 2016-01 status","back":"A US GAAP rule change, NOT an IFRS rule — used only as a real-world hook to compare against IFRS9's treatment."},{"id":"cr-s8-f3","session":8,"front":"IFRS9 equity default","back":"FVTPL (fair value through profit or loss) — any fair-value change hits profit or loss."},{"id":"cr-s8-f4","session":8,"front":"FVOCI election, four exam-critical features","back":"1) Only for non-trading equity instruments. 2) Instrument-by-instrument, not a blanket policy. 3) Made at initial recognition, irrevocable. 4) Dividends still to P&L; fair-value changes to OCI, never recycled, and no separate ECL model."},{"id":"cr-s8-f5","session":8,"front":"Equity-FVOCI vs debt-FVOCI recycling","back":"Equity-FVOCI: NEVER recycles to P&L, not even on disposal. Debt-FVOCI: DOES recycle to P&L on derecognition. This is the most tested distinction in the course on financial instruments."},{"id":"cr-s8-f6","session":8,"front":"Decision sequence for any financial-instrument question","back":"1) IAS32 classification. 2) IFRS9 initial measurement at fair value. 3) Subsequent measurement (debt: business model + SPPI; equity: FVTPL default/FVOCI election). 4) Presentation: P&L vs OCI."},{"id":"cr-s8-f7","session":8,"front":"The case's own framing","back":"\"A presentation case more than a valuation case\" — nobody disputes the fair value; the debate is which financial statement line shows its movement."},{"id":"cr-s8-f8","session":8,"front":"Three perspectives on what net income should communicate","back":"Buffett's view: fair-value swings on a long-term portfolio obscure operating trends. Standard setter's view: fair value should flow through net income as it occurs. Investor's view: use net income, OCI, operating earnings and disclosures together."},{"id":"cr-s9-f1","session":9,"front":"IAS16 objective","back":"Prescribe accounting for PP&E so users can discern info on the entity's PP&E investment; issues = recognition, carrying amounts, depreciation, impairment."},{"id":"cr-s9-f2","session":9,"front":"IAS16 scope exclusions","back":"PP&E held for sale (IFRS5); biological assets (IAS41); exploration/evaluation assets (IFRS6); mineral rights/reserves; investment property (IAS40)."},{"id":"cr-s9-f3","session":9,"front":"PP&E definition","back":"Tangible assets (a) held for production/supply/rental/admin purposes, and (b) expected to be used for more than one period."},{"id":"cr-s9-f4","session":9,"front":"PP&E recognition test","back":"BOTH required: cost measurable reliably, AND probable future economic benefits will flow to the entity."},{"id":"cr-s9-f5","session":9,"front":"Three elements of initial cost","back":"Purchase price + directly attributable costs (delivery, installation, professional fees, site prep) + estimated dismantling/restoration cost (recognised as a provision)."},{"id":"cr-s9-f6","session":9,"front":"Costs excluded from initial cost","back":"Administrative overheads, feasibility studies, staff training, abnormal waste of materials/labour in self-construction."},{"id":"cr-s9-f7","session":9,"front":"Capitalisation cutoff rule","back":"Stops once the asset is CAPABLE of operating as intended by management — not once it is actually at full planned use/capacity."},{"id":"cr-s9-f8","session":9,"front":"Costs never capitalisable post-cutoff","back":"Costs incurred once capable of operating (even if not yet at full capacity); initial operating losses; relocation/reorganisation costs."},{"id":"cr-s9-f9","session":9,"front":"Component approach (IAS16 par 43)","back":"Each significant part of a PP&E item, with a materially different cost/useful life, is depreciated separately (e.g. aircraft engine vs airframe vs seats)."},{"id":"cr-s9-f10","session":9,"front":"Borrowing costs (IAS23)","back":"Directly attributable to a qualifying asset -> capitalised as part of its cost. All other borrowing costs -> expensed as incurred."},{"id":"cr-s9-f11","session":9,"front":"Qualifying asset (IAS23)","back":"An asset that necessarily takes a substantial period of time to get ready for its intended use or sale."},{"id":"cr-s9-f12","session":9,"front":"Capitalisation rate by funding source","back":"Specific borrowings -> use that borrowing's own interest rate. General borrowings -> weighted average rate across all general borrowings, time-apportioned by months outstanding."},{"id":"cr-s9-f13","session":9,"front":"Capitalised borrowing cost formula","back":"Sum over tranches of: Qualifying expenditure x Weighted average borrowing rate x (Months outstanding / 12)."},{"id":"cr-s10-f1","session":10,"front":"Subsequent costs, capitalise vs expense","back":"Capitalise: additions/improvements/replacements that increase future service potential; major non-routine (e.g. legally mandated) inspections. Expense: ordinary repairs/maintenance; re-arrangement/re-organisation costs."},{"id":"cr-s10-f2","session":10,"front":"Component replacement accounting","back":"Derecognise the old component's remaining carrying amount (recognising any loss) and capitalise the new component's cost — practical application of the component approach."},{"id":"cr-s10-f3","session":10,"front":"Cost model","back":"Cost less accumulated depreciation less accumulated impairment losses (IAS16 par 30)."},{"id":"cr-s10-f4","session":10,"front":"Three depreciation methods","back":"Straight-line (constant charge); diminishing-balance (decreasing charge, appropriate when productivity/revenue is higher early or maintenance rises later); units-of-production (based on output)."},{"id":"cr-s10-f5","session":10,"front":"Land","back":"Not depreciated; must be accounted for separately from any building acquired jointly with it."},{"id":"cr-s10-f6","session":10,"front":"Revaluation model","back":"Carried at fair value at the revaluation date, net of subsequent accumulated depreciation/impairment; applied to an ENTIRE class of PP&E, no selective revaluation."},{"id":"cr-s10-f7","session":10,"front":"Revaluation frequency","back":"Must be carried out regularly; every 3-5 years is sufficient absent significant fluctuations (annual not required)."},{"id":"cr-s10-f8","session":10,"front":"Revaluation surplus/deficit rule (the key mechanical rule)","back":"First surplus -> OCI/reserve. First deficit -> P&L. Subsequent surplus reversing a prior P&L deficit -> credited back to P&L up to that deficit, excess to reserve. Subsequent deficit reversing a prior reserve surplus -> debited against reserve first, excess to P&L."},{"id":"cr-s10-f9","session":10,"front":"Revalued assets continue to be depreciated","back":"Under IAS16's revaluation model, depreciation continues after revaluation (only the rate/base may need adjusting) — contrast with IAS40 fair value model, where depreciation stops."},{"id":"cr-s10-f10","session":10,"front":"IAS40 investment property (definition)","back":"Land or a building (or part of one), held by the owner or lessee (as a right-of-use asset), to earn rentals or for capital appreciation, or both — distinct from owner-occupied property (stays under IAS16)."},{"id":"cr-s10-f11","session":10,"front":"IAS40 fair value model, three key contrasts with IAS16 revaluation","back":"1) Remeasured every YEAR (not 3-5 years). 2) Ceases to be depreciated once fair-valued. 3) Both gains and losses go through P&L directly, never OCI/reserve."},{"id":"cr-s10-f12","session":10,"front":"Investment property initial measurement","back":"At cost, exactly as under IAS16; subsequently the entity chooses between the cost model and the fair value model, applied consistently to the whole class."},{"id":"cr-s11-f1","session":11,"front":"Intangible asset (IAS38), three-part test","back":"Non-monetary + identifiable + without physical substance — all three required simultaneously."},{"id":"cr-s11-f2","session":11,"front":"Identifiability test","back":"Separable (can be sold/transferred/licensed/rented/exchanged separately) OR arises from contractual/legal rights — an 'or' test. Distinguishes a specific intangible from goodwill."},{"id":"cr-s11-f3","session":11,"front":"Control","back":"Ability to control future economic benefits from the item; legal protection (patent, trademark) is one way, not the only way."},{"id":"cr-s11-f4","session":11,"front":"Four acquisition routes and initial measurement","back":"Separate acquisition -> cost. Business combination -> fair value (IFRS3). Government grant -> fair value or nominal + directly attributable costs (IAS20). Internally generated -> capitalised outlays subject to R&D split."},{"id":"cr-s11-f5","session":11,"front":"Items that always fail recognition when internal","back":"Internally generated goodwill, start-up costs, training costs, advertising/promotional costs, reorganisation costs, internally developed customer portfolios/trademarks/mastheads/publishing titles/customer lists."},{"id":"cr-s11-f6","session":11,"front":"Same items via acquisition","back":"Trademarks, customer lists, etc. that fail recognition when internally generated CAN be recognised if acquired from a third party or via a business combination — the problem is internal generation, not the item itself."},{"id":"cr-s11-f7","session":11,"front":"Revaluation model for intangibles","back":"Only permitted where fair value can be determined via an ACTIVE MARKET — rare (examples: production quotas, fishing licences, taxi licences)."},{"id":"cr-s11-f8","session":11,"front":"Finite vs indefinite useful life","back":"Finite -> amortise over useful life + impairment test if indicators exist. Indefinite (and goodwill) -> never amortised, impairment test at least annually. 'Indefinite' does not mean 'infinite.'"},{"id":"cr-s11-f9","session":11,"front":"Useful life cap from legal/contractual rights","back":"Cannot exceed the duration of those rights, but may be shorter if the entity expects shorter use."},{"id":"cr-s11-f10","session":11,"front":"Research expenditure","back":"Always expensed as incurred — no capitalisation permitted, ever."},{"id":"cr-s11-f11","session":11,"front":"Development expenditure, six capitalisation conditions (ALL required)","back":"Technical feasibility; intention to complete and use/sell; ability to use/sell; how it will generate probable future benefits; adequate resources available; reliable measurement of attributable expenditure."},{"id":"cr-s11-f12","session":11,"front":"Add-on module to an in-use asset","back":"Amortised over the REMAINING useful life of the underlying asset, not a fresh full term."},{"id":"cr-s11-f13","session":11,"front":"Website development costs (exercise)","back":"Planning -> expensed. Development -> capitalisable if probable future benefits shown. Content development -> expensed. Operating (running the live site) -> expensed."},{"id":"cr-s11-f14","session":11,"front":"Goodwill treatment","back":"Never amortised; tested for impairment at least annually — same treatment as indefinite-life intangibles."},{"id":"cr-s12-f1","session":12,"front":"Impairment loss","back":"Carrying amount (NBV) minus recoverable amount, when NBV exceeds recoverable amount; no impairment if NBV <= recoverable amount."},{"id":"cr-s12-f2","session":12,"front":"Recoverable amount","back":"The GREATER of (a) fair value less costs to sell and (b) value in use (PV of expected future cash flows)."},{"id":"cr-s12-f3","session":12,"front":"Mandatory annual impairment testing","back":"Indefinite-life intangibles, goodwill, and assets not yet ready for use — tested annually regardless of indicators. All other assets: tested only when an indicator exists."},{"id":"cr-s12-f4","session":12,"front":"External impairment indicators","back":"Unexpected decline in market value; adverse legal/technological/market/economic changes; rising interest rates (affecting discount rate); book value of net assets exceeding market capitalisation."},{"id":"cr-s12-f5","session":12,"front":"Internal impairment indicators","back":"Obsolescence/physical damage; changes in asset use (restructuring, planned disposal); internal reporting showing worse-than-expected economic performance."},{"id":"cr-s12-f6","session":12,"front":"Impairment loss for revalued assets (exception)","back":"Debited first against any revaluation reserve balance for that asset (as negative OCI); only the excess beyond the reserve is a P&L expense."},{"id":"cr-s12-f7","session":12,"front":"Cash-generating unit (CGU)","back":"The smallest identifiable group of assets generating cash inflows largely independent of other assets/groups — used when an individual asset's own recoverable amount can't be estimated."},{"id":"cr-s12-f8","session":12,"front":"Goodwill impairment testing approach","back":"Allocated to each CGU (or group) expected to benefit from combination synergies; each such CGU must be at or below the level of an IFRS8 operating segment; CGU's own assets tested before goodwill."},{"id":"cr-s12-f9","session":12,"front":"Impairment loss allocation order within a CGU","back":"1) Goodwill first, down to zero. 2) Remaining loss pro rata to other assets by carrying amount. 3) Floor: no asset below its own fair-value-less-costs-to-sell or value-in-use."},{"id":"cr-s12-f10","session":12,"front":"Reversal rules","back":"Goodwill: NEVER reversed. Other assets: reversal capped at pre-impairment carrying amount net of notional depreciation; recognised in P&L normally, or via OCI/reserve if the asset is carried at a revalued amount."},{"id":"cr-s12-f11","session":12,"front":"Corporate assets","back":"Assets like HQ buildings/IT systems serving shared activities with no independent cash inflows; allocated to CGUs where reasonably possible, else tested at the smallest group level they can be allocated to."},{"id":"cr-s13-f1","session":13,"front":"Biosensors International Group (BIG) and JW Medical Systems (JWMS) deal","back":"Biosensors International Group acquired the remaining 50% of JW Medical Systems for US$478m in October 2011 (having held 50% since 2003), about 25x JWMS's FY2011 profit after tax."},{"id":"cr-s13-f2","session":13,"front":"Balance sheet shift","back":"Intangibles + goodwill moved from 4% to 62% of Biosensors International Group (BIG)'s total assets between 2011 and 2012, driven almost entirely by the JW Medical Systems (JWMS) acquisition."},{"id":"cr-s13-f3","session":13,"front":"Intangibles acquired (US$'000)","back":"Patents 18,825; customer relationships 135,128 (net 131,236, the dominant component); land use rights 1,841 — total 155,794 of 162,008 total intangibles."},{"id":"cr-s13-f4","session":13,"front":"Why customer relationships were recognisable here","back":"Acquired via a business combination — Session 11's rule that internally generated customer lists/relationships can never be recognised does not apply to items acquired externally."},{"id":"cr-s13-f5","session":13,"front":"Land use rights amortisation delay","back":"Not amortised at 31 March 2012 because the lease period only began 1 April 2012 — consistent with the 'capable of operating as intended' recognition cutoff."},{"id":"cr-s13-f6","session":13,"front":"Goodwill recognition and subsequent measurement","back":"Initially at cost = consideration transferred (+ NCI) minus net identifiable assets/liabilities acquired; subsequently at cost less accumulated impairment only, never amortised."},{"id":"cr-s13-f7","session":13,"front":"Where Biosensors International Group (BIG)'s FY2012 goodwill impairment actually hit","back":"Three smaller cash-generating units (the original device unit BSI, Bio Japan and the Bifurcation stents unit) totalling US$12,232k, not the much larger JW Medical Systems (JWMS) goodwill balance. Illustrates unit-specific, not company-wide, testing."},{"id":"cr-s13-f8","session":13,"front":"JW Medical Systems (JWMS) value-in-use assumptions","back":"Five-year DCF, 18% average growth rate, 2% terminal growth rate, 12% pre-tax discount rate, all management-set and not independently verifiable."},{"id":"cr-s13-f9","session":13,"front":"Market capitalisation as an impairment cross-check","back":"Session 12's external indicator (book value exceeding market cap) applied concretely: Biosensors International Group (BIG)'s market-value range (~US$1.48bn-2.31bn) vs net book value (~US$1.12bn) as an independent sanity check."},{"id":"cr-s13-f10","session":13,"front":"The Biosensors case study's own caution","back":"Deliberately does not conclude whether Biosensors International Group (BIG)'s 'no impairment' determination was appropriate: it hands the reader the raw inputs for classroom judgement, not a verified answer."},{"id":"cr-s14-f1","session":14,"front":"Provision (IAS37, par 10)","back":"A liability of uncertain timing or amount, recognised when: (a) present obligation from a past event; (b) probable outflow of resources; (c) reliable estimate possible — ALL THREE required."},{"id":"cr-s14-f2","session":14,"front":"Obligating event","back":"A past event creating a legal obligation (contract, legislation, operation of law) OR a constructive obligation (entity's own conduct creates a valid expectation), leaving no realistic alternative to settling it."},{"id":"cr-s14-f3","session":14,"front":"Uncertainty spectrum","back":"Accrued liabilities (least uncertain) -> provisions (uncertain timing/amount, still probable/estimable) -> contingent liabilities (most uncertain: not probable, or not reliably estimable, or outside entity control)."},{"id":"cr-s14-f4","session":14,"front":"Balance sheet treatment by category","back":"Accrued liabilities & provisions -> on balance sheet (provisions shown separately). Contingent liabilities with probable-but-unreliable estimate -> notes only. Remote contingent liabilities -> nothing recognised or disclosed."},{"id":"cr-s14-f5","session":14,"front":"Recognition decision tree","back":"Present/possible obligation? -> No -> nothing. Yes -> probable outflow? -> No & remote -> nothing; No & not remote -> disclose. Yes -> reliable estimate? -> No -> disclose; Yes -> RECOGNISE a provision (and disclose)."},{"id":"cr-s14-f6","session":14,"front":"Measurement by population type","back":"One-off events (lawsuit, restructuring) -> most likely amount. Large-population events (warranties) -> probability-weighted expected value."},{"id":"cr-s14-f7","session":14,"front":"Expected value formula","back":"Sum of (Probability of each outcome x Cost of that outcome), probabilities summing to 100%."},{"id":"cr-s14-f8","session":14,"front":"Present value / unwinding of discount","back":"When material, provisions are measured at PV of expected settlement expenditure; the provision grows each period toward the undiscounted amount, with the increase recognised as a finance cost in P&L."},{"id":"cr-s14-f9","session":14,"front":"Netting rule","back":"Expected gains from an anticipated asset disposal must NEVER be netted against a related provision, however closely linked."},{"id":"cr-s14-f10","session":14,"front":"Future operating losses vs onerous contracts","back":"Future operating losses -> NEVER a provision (triggers an IAS36 impairment test on related assets instead). Onerous contracts -> ALWAYS recognised and measured as a provision."},{"id":"cr-s14-f11","session":14,"front":"Restructuring provision recognition conditions (both required)","back":"1) A detailed formal plan (business/part concerned, locations, employees affected, expenditures, timing). 2) A valid expectation raised in those affected (implementation started, or main features announced)."},{"id":"cr-s14-f12","session":14,"front":"Restructuring provision scope","back":"Only direct expenditures necessarily entailed by the restructuring and unrelated to ongoing activities — excludes ordinary retraining, marketing, and new distribution network investment."},{"id":"cr-s14-f13","session":14,"front":"Contingent asset (IAS37)","back":"A possible asset from past events, confirmed only by uncertain future events outside the entity's control; never recognised on the balance sheet."},{"id":"cr-s14-f14","session":14,"front":"Contingent asset disclosure by probability","back":"Not probable -> nothing. Probable but not virtually certain -> disclose only. Virtually certain -> no longer contingent, recognise as an ordinary asset."},{"id":"cr-s16-f1","session":16,"front":"Define a lease under IFRS16.","back":"A contract that gives the lessee the right to control the use of an identified asset for a period of time, typically in exchange for periodic rent payments."},{"id":"cr-s16-f2","session":16,"front":"What two conditions together define the right to control an asset?","back":"The lessee must obtain substantially all the economic benefits from using the asset, and have the right to direct how and for what purpose the asset is used. Both are required."},{"id":"cr-s16-f3","session":16,"front":"Name the three commercial reasons firms lease.","back":"100% financing at fixed rates (no down payment, fixed schedule), protection against obsolescence (can return the asset), and flexibility (looser covenants than other debt)."},{"id":"cr-s16-f4","session":16,"front":"IAS17's dual model, what were the two tests for a finance lease?","back":"Are the risks and rewards of ownership transferred to the lessee, and is the lease economically similar to purchasing the asset. A yes to either meant finance lease treatment."},{"id":"cr-s16-f5","session":16,"front":"IFRS16's single model in one line.","back":"There is no lease classification test for lessees, a lessee recognises a right of use asset and a lease liability for essentially every lease."},{"id":"cr-s16-f6","session":16,"front":"Did IFRS16 change lessor accounting substantially?","back":"No. Lessor accounting is largely unchanged, IFRS16 mainly adds disclosure about how lessors manage residual value risk."},{"id":"cr-s16-f7","session":16,"front":"What rough rule of thumb did investors use pre-IFRS16 to informally capitalise operating leases?","back":"Lease liability is roughly 8 times annual lease expense, and interest expense is roughly one third of lease expense."},{"id":"cr-s16-f8","session":16,"front":"What did Altamuro et al. (2014) find about bank loan spreads?","back":"Loan spreads were better explained by financial ratios adjusted for operating lease capitalisation than by unadjusted ratios."},{"id":"cr-s16-f9","session":16,"front":"What are the three stated goals of the IFRS16 reform?","back":"Facilitate faithful representation, enhance comparability, and mitigate opportunities for accounting manipulation."},{"id":"cr-s16-f10","session":16,"front":"What does the recognition versus disclosure literature consistently find?","back":"Investors treat recognised amounts as more value relevant than merely disclosed amounts, across settings like stock options, post retirement benefits, derivatives and investment property fair value."},{"id":"cr-s16-f11","session":16,"front":"What did Ma and Thomas (2023) find firms did after IFRS16/Topic 842?","back":"Decreased long term operating leases, increased short term operating leases, and increased capital expenditure instead of leasing."},{"id":"cr-s16-f12","session":16,"front":"Why would a firm shift toward variable, non-index lease payments after IFRS16?","back":"Because the lease liability is built from fixed and index or rate linked payments, so purely variable non-index payments can be kept out of the measured liability."},{"id":"cr-s16-f13","session":16,"front":"What real economic costs did Chen et al. (2023) associate with lease capitalisation rules?","back":"Decreases in firm level investment, profitability and employment, concentrated in lease intensive and financially distressed firms."},{"id":"cr-s16-f14","session":16,"front":"How did firms respond the first time finance leases were required on balance sheet (SFAS13)?","back":"They substituted finance leases with operating leases and other non-lease financing, restructuring to stay off balance sheet, per Imhoff and Thomas (1988)."},{"id":"cr-s16-f15","session":16,"front":"Exam trap, does IFRS16 remove the finance versus operating distinction for lessors too?","back":"No. That distinction was removed for lessees only. Lessors still classify every lease as finance or operating under the same dual model logic as before."},{"id":"cr-s17-f1","session":17,"front":"What are the two, and only two, IFRS16 recognition exemptions for lessees?","back":"Short term leases (term of 12 months or less) and low value leases (example threshold given as around 5000 euros). Both are simply expensed straight line, no balance sheet recognition."},{"id":"cr-s17-f2","session":17,"front":"Why does the lease term include reasonably certain renewal options?","back":"IFRS16's anti-avoidance rule looks through to what the lessee actually expects to do, closing the loophole of negotiating artificially short terms to dodge capitalisation."},{"id":"cr-s17-f3","session":17,"front":"List the four components of the ROU asset's initial cost.","back":"The initial lease liability amount, lease payments made at or before commencement, initial direct costs, and estimated dismantling or restoration costs."},{"id":"cr-s17-f4","session":17,"front":"List the components of the lease liability's initial measurement.","back":"Fixed payments, index or rate linked variable payments, expected residual value guarantee payments, purchase option price if reasonably certain to exercise, and termination penalties if applicable."},{"id":"cr-s17-f5","session":17,"front":"How is the ROU asset depreciated and tested subsequently?","back":"Depreciated under IAS16 rules, typically straight line over the shorter of useful life and lease term, and subject to IAS36 impairment testing."},{"id":"cr-s17-f6","session":17,"front":"What interest method applies to the lease liability after initial recognition?","back":"A constant periodic rate of interest on the remaining balance, the same effective interest method already used for financial liabilities, using the original discount rate throughout."},{"id":"cr-s17-f7","session":17,"front":"Can depreciation and interest on a lease be combined on the income statement?","back":"No, IFRS16 requires them to stay separately identifiable line items."},{"id":"cr-s17-f8","session":17,"front":"How is the principal portion of a lease payment classified in the cash flow statement, and the interest portion?","back":"Principal is always financing activities. Interest follows the entity's general accounting policy for interest presentation, operating or financing."},{"id":"cr-s17-f9","session":17,"front":"Operating lease, lessor side, what happens to the asset and income?","back":"The lessor keeps the asset on its own balance sheet and recognises lease income on a straight line basis."},{"id":"cr-s17-f10","session":17,"front":"Finance lease, lessor side, what does the lessor recognise?","back":"It derecognises the underlying asset and recognises a lease receivable (net investment in the lease), then earns interest income and reduces the receivable as payments are collected."},{"id":"cr-s17-f11","session":17,"front":"Why does EBITDA typically rise after lease capitalisation?","back":"Rent expense, previously above the EBITDA line, is replaced by depreciation and interest, both of which sit below EBITDA, a presentation effect not a change in economics."},{"id":"cr-s17-f12","session":17,"front":"Why is total lease expense typically front loaded under IFRS16?","back":"Interest is calculated on a larger outstanding liability balance in early years, so total depreciation plus interest exceeds straight line rent early on, then the pattern reverses."},{"id":"cr-s17-f13","session":17,"front":"General direction of ratio effects from lease capitalisation (unverified per the fiche, but as taught).","back":"Leverage typically rises, asset turnover typically falls, current ratio typically falls, interest coverage typically falls, since new debt and interest appear that were not there before."},{"id":"cr-s18-f1","session":18,"front":"What did Sir David Tweedie's remark about flying in an aircraft on the balance sheet highlight?","back":"How thoroughly IAS17's off balance sheet operating leases let airlines hide enormous financing commitments from the face of the balance sheet."},{"id":"cr-s18-f2","session":18,"front":"Name the two criticisms of IAS17's dual model raised by the case.","back":"It hurt comparability across time and firms, and it created opportunities for manipulative structuring of leases to land on the operating (off balance sheet) side of the classification line."},{"id":"cr-s18-f3","session":18,"front":"How did airlines rank in the PwC study of IFRS16 industry impact?","back":"Second most affected of eight industries studied, with a 47% median debt increase and 33% median EBITDA increase, behind only retailers."},{"id":"cr-s18-f4","session":18,"front":"Cathay Pacific 2019, balance sheet effect in one line.","back":"PP&E/ROU assets rose about HKD 19,937 million, lease liabilities rose about HKD 19,967 million (split between current and non-current portions)."},{"id":"cr-s18-f5","session":18,"front":"Cathay Pacific 2019, net profit effect and why.","back":"Profit worsened by about HKD 86 million, because depreciation plus finance charges (4,593) exceeded the eliminated rental expense (4,507)."},{"id":"cr-s18-f6","session":18,"front":"Cathay Pacific 2019, cash flow effect.","back":"Total net cash flow was unchanged, operating cash flow rose (rent left operating activities), financing cash outflows rose (principal repayments), classification shifted but the total did not."},{"id":"cr-s18-f7","session":18,"front":"Cathay Pacific 2019, gearing, EBITDA and EPS changes.","back":"Gearing rose about 36.5% (0.96 to 1.31), EBITDA rose about 31.1%, EPS fell about 1.6% (43.7 cents to 43.0 cents)."},{"id":"cr-s18-f8","session":18,"front":"Define residual value risk.","back":"The possibility that an asset's actual residual value at the end of the lease term falls below the value originally estimated at lease inception."},{"id":"cr-s18-f9","session":18,"front":"Who bore residual value risk under IAS17's true operating leases, and how does IFRS16 change this practically?","back":"Under IAS17, the lessor bore it entirely. Under IFRS16, the lessee's balance sheet now carries an ROU asset subject to impairment testing, so residual value volatility can hit the lessee too, even without any contractual change."},{"id":"cr-s18-f10","session":18,"front":"Name three possible lessee responses to IFRS16 discussed in the case.","back":"Renegotiate or restructure existing and new leases, shift toward variable non-index-linked payments, and reassess whether leasing remains the right way to access assets at all."},{"id":"cr-s18-f11","session":18,"front":"Exam trap, does IFRS16 adoption always reduce reported profit?","back":"No, the direction depends on the specific mix of new versus maturing leases in a given year, and the front loading effect can reverse in later years of a lease's life."},{"id":"cr-s19-f1","session":19,"front":"Formula, total tax expense.","back":"Tax expense = current tax + deferred tax, both governed by IAS12."},{"id":"cr-s19-f2","session":19,"front":"Define permanent differences and give two examples.","back":"Items that enter accounting profit but never taxable profit, or vice versa, and never reverse. Examples, tax exempt bond interest, fines and penalties, dividends from consolidated subsidiaries."},{"id":"cr-s19-f3","session":19,"front":"Define temporary differences.","back":"Differences between accounting and taxable profit arising because an item is recognised in a different period for accounting versus tax purposes, they reverse over time and generate deferred tax."},{"id":"cr-s19-f4","session":19,"front":"When does a deferred tax asset arise?","back":"When taxable profit is currently higher than accounting profit (paying more tax now), so less tax will be paid in the future when the difference reverses."},{"id":"cr-s19-f5","session":19,"front":"When does a deferred tax liability arise?","back":"When taxable profit is currently lower than accounting profit (paying less tax now), so more tax will be paid in the future when the difference reverses."},{"id":"cr-s19-f6","session":19,"front":"Balance sheet approach formula for a temporary difference.","back":"Temporary difference = carrying amount minus tax base. Then deferred tax asset or liability = temporary difference times the statutory tax rate."},{"id":"cr-s19-f7","session":19,"front":"Balance sheet approach, asset with carrying amount greater than tax base, what results?","back":"A taxable temporary difference, giving a deferred tax liability."},{"id":"cr-s19-f8","session":19,"front":"Balance sheet approach, liability with carrying amount less than tax base, what results?","back":"A deductible temporary difference, giving a deferred tax asset."},{"id":"cr-s19-f9","session":19,"front":"Name five common sources of temporary differences.","back":"Depreciation rate differences, bad debt expense timing, warranty expense timing, pension expense timing (actuarial vs actual), and investment income (unrealised vs realised gains)."},{"id":"cr-s19-f10","session":19,"front":"What is the tax base of an asset or liability?","back":"The amount attributed to that asset or liability for tax purposes, which can differ from its accounting carrying amount."},{"id":"cr-s19-f11","session":19,"front":"Must deferred tax balances be discounted to present value?","back":"No, IAS12 requires them to be reported undiscounted regardless of when reversal is expected."},{"id":"cr-s19-f12","session":19,"front":"Where is the deferred tax balance presented on the balance sheet?","back":"Always as a non-current asset or liability, regardless of the actual expected timing of reversal."},{"id":"cr-s20-f1","session":20,"front":"Define a valuation allowance.","back":"A contra account against deferred tax assets, reviewed each period and reduced if it is no longer probable that sufficient future taxable profit will be available to use the asset."},{"id":"cr-s20-f2","session":20,"front":"How does a valuation allowance affect profit or loss?","back":"It flows through as a loss when established or increased, and as a gain if it is later reversed as the profitability outlook improves."},{"id":"cr-s20-f3","session":20,"front":"Over the full life of a temporary difference, what happens to total tax paid under accelerated versus straight line depreciation?","back":"It converges to the same total amount, only the timing of when it is paid differs, confirmed by the deferred tax balance unwinding to exactly zero by the end of the asset's tax life."},{"id":"cr-s20-f4","session":20,"front":"In which countries are deferred taxes comparatively more material, and why?","back":"In countries like the UK where accounting rules are independent of tax rules, producing many temporary differences. In Germany and France, where the two are closely aligned, deferred taxes matter less."},{"id":"cr-s20-f5","session":20,"front":"Why can a growing firm's depreciation related deferred tax liability persist indefinitely rather than reverse?","back":"Rising capital expenditure can generate new temporary differences faster than old ones reverse, effectively rolling the liability forward, described as similar to an interest free government loan."},{"id":"cr-s20-f6","session":20,"front":"What did Hanlon (2005) find about large positive book-tax differences?","back":"Investors treat them as a red flag, reducing their expectation of future earnings persistence, and larger gaps associate with less persistent earnings generally."},{"id":"cr-s20-f7","session":20,"front":"What did Hanlon et al. (2008) find about forcing book-tax conformity higher?","back":"It reduced the informativeness of reported accounting earnings, showing the book-tax gap is not purely a sign of manipulation, sometimes it reflects informative independent judgement."},{"id":"cr-s20-f8","session":20,"front":"Can a valuation allowance apply to a deferred tax liability?","back":"No. Valuation allowances apply only to deferred tax assets, there is no equivalent discretionary write-down mechanism for liabilities."},{"id":"cr-s20-f9","session":20,"front":"What three factors should an analyst weigh when judging whether a deferred tax balance will actually reverse?","back":"Future tax rates, laws and standards that could change; the firm's growth rate (capex driven DTLs may keep rolling forward); and whether the temporary difference is recurring or a one-off."},{"id":"cr-s21-f1","session":21,"front":"Define a sale and leaseback transaction.","back":"The seller-lessee sells an asset to the buyer-lessor and immediately leases that same asset back from them."},{"id":"cr-s21-f2","session":21,"front":"What determines the accounting treatment of a sale and leaseback?","back":"Whether the transfer of the asset qualifies as a sale under IFRS15, i.e. whether control has actually transferred to the buyer-lessor."},{"id":"cr-s21-f3","session":21,"front":"If the transfer is not a sale, how do both parties treat the cash exchanged?","back":"As a loan, a financial liability under IFRS9 for the seller-lessee and a financial asset under IFRS9 for the buyer-lessor."},{"id":"cr-s21-f4","session":21,"front":"If the transfer is a sale, how is the seller-lessee's ROU asset measured?","back":"At the proportion of the asset's previous carrying amount relating to the rights of use retained, not at fair value."},{"id":"cr-s21-f5","session":21,"front":"If the transfer is a sale, how much gain does the seller-lessee recognise?","back":"Only the portion of the total potential gain relating to the rights actually transferred to the buyer-lessor, proportional to rights given up."},{"id":"cr-s21-f6","session":21,"front":"Formula, tax rate change adjustment.","back":"Beginning balance of accumulated timing differences times (former tax rate minus new tax rate), applied once as an immediate catch up."},{"id":"cr-s21-f7","session":21,"front":"Direction rule, DTA and DTL when the tax rate rises.","back":"Both increase when the rate rises (DTA more valuable, DTL more costly), and both decrease when the rate falls, they always move in the same direction as the rate."},{"id":"cr-s21-f8","session":21,"front":"Is a tax rate change adjustment spread over future periods?","back":"No, it is recognised immediately as a one time catch up on the existing balance, in the period the rate change is enacted."},{"id":"cr-s21-f9","session":21,"front":"Self-check for any tax rate change calculation.","back":"The new DTA/DTL balance after the adjustment must equal the cumulative timing difference revalued at the new rate."},{"id":"cr-s22-f1","session":22,"front":"State IFRS15's core principle.","back":"Recognise revenue when (not necessarily when cash is paid) promised goods or services transfer to the customer, in the amount of the transaction price."},{"id":"cr-s22-f2","session":22,"front":"List the five conditions for a contract to exist under IFRS15.","back":"Parties committed to the contract, each party's rights identifiable, payment terms identifiable, commercial substance, and it is probable the entity will collect the consideration."},{"id":"cr-s22-f3","session":22,"front":"Define a distinct good or service.","back":"One the customer can benefit from on its own, and whose promise of transfer is separately identifiable within the contract. Both conditions are required."},{"id":"cr-s22-f4","session":22,"front":"Name the two methods for estimating variable consideration and when each applies.","back":"Expected value method (probability weighted sum) for a range of outcomes, most likely amount method for an essentially binary (all or nothing) outcome."},{"id":"cr-s22-f5","session":22,"front":"List IFRS15's five steps.","back":"1. Identify the contract, 2. Identify performance obligations, 3. Determine the transaction price, 4. Allocate the transaction price, 5. Recognise revenue as obligations are satisfied."},{"id":"cr-s22-f6","session":22,"front":"How is the transaction price allocated across performance obligations?","back":"Proportionally, based on each obligation's stand-alone selling price, with exceptions when observable evidence points a bundle discount at only some obligations."},{"id":"cr-s22-f7","session":22,"front":"Name the two methods for measuring progress on an over time performance obligation.","back":"Output methods (direct measurement of transferred goods/services, e.g. units delivered) and input methods (entity's inputs to date relative to total required, e.g. costs incurred)."},{"id":"cr-s22-f8","session":22,"front":"When are contract costs capitalised as a contract asset?","back":"When they relate directly to the specific contract, generate resources expected to be used to satisfy obligations, and are expected to be recovered."},{"id":"cr-s22-f9","session":22,"front":"Distinguish a contract asset from a receivable.","back":"A contract asset's right to consideration is still conditional on something beyond the passage of time (more performance needed). A receivable is unconditional except for time."},{"id":"cr-s22-f10","session":22,"front":"Define a contract liability.","back":"Recognised when the customer has paid before the entity has transferred the related goods or services."},{"id":"cr-s22-f11","session":22,"front":"Why did IFRS15 replace IAS11 and IAS18?","back":"To create a single principles based revenue standard consistent across industries and with US GAAP, fixing US GAAP's overly detailed inconsistent rules and IAS11/18's vagueness, and to better handle evolving bundled business models."},{"id":"cr-s22-f12","session":22,"front":"What items are explicitly excluded from revenue?","back":"Borrowings, amounts contributed by shareholders (e.g. equity issues), and gains such as gains on disposal of non-current assets."},{"id":"cr-s23-f1","session":23,"front":"Why do customer loyalty award miles get their own performance obligation?","back":"Because they grant the customer a material right they would not receive without entering the contract, so part of the transaction price must be allocated to them and deferred until redemption or expiry."},{"id":"cr-s23-f2","session":23,"front":"Right of return, formula for the transaction price.","back":"Expected consideration for the units expected to be kept (not returned), using the most likely amount method when returns are estimable from historical experience."},{"id":"cr-s23-f3","session":23,"front":"Right of return, name the two items recognised alongside reduced revenue.","back":"A refund liability (for expected returns at selling price) and a right to recover returned goods asset (at cost), recognised together, not replacing each other."},{"id":"cr-s23-f4","session":23,"front":"Why is a non-refundable joining fee not its own performance obligation?","back":"Because the act of registering the customer is not itself a good or service the customer benefits from on its own, so the fee is deferred as an advance payment for future services instead."},{"id":"cr-s23-f5","session":23,"front":"Over what period is a non-refundable joining fee typically recognised, if renewal carries no further fee?","back":"Over the expected period of the overall customer relationship, not just the first stated contract term."},{"id":"cr-s23-f6","session":23,"front":"Percentage of completion example, why use one third complete rather than the cost-to-cost ratio?","back":"Because the facts state progress was directly assessed as one third complete (an output measure), and the entity may use whichever method (output or input) faithfully depicts actual progress."},{"id":"cr-s23-f7","session":23,"front":"Can an over time contract show a reported loss even though it will ultimately be profitable?","back":"Yes, if progress is measured by an output method that does not track cost incurrence one for one, costs expensed as incurred can exceed revenue recognised in a given period."},{"id":"cr-s24-f1","session":24,"front":"Define the full retrospective transition method.","back":"The company fully restates prior comparative period financial statements as if the new standard had always applied, so every period presented is on a like for like basis."},{"id":"cr-s24-f2","session":24,"front":"Define the modified retrospective transition method.","back":"No restatement of prior periods, instead a single one-time cumulative effect adjustment hits the opening balance of retained earnings in the adoption year, plus required disclosure of what results would have been under the old rules."},{"id":"cr-s24-f3","session":24,"front":"General Dynamics 2017, method and driver of its negative 684 million dollar adjustment.","back":"Full retrospective method. Driver, business jet contracts moved from two milestone revenue recognition to single point in time recognition at delivery, deferring previously recognised profit."},{"id":"cr-s24-f4","session":24,"front":"Ford 2017, method and driver of its positive 36 million dollar adjustment.","back":"Modified retrospective method. Driver, certain previously deferred vehicle sales (guaranteed resale value, Ford owned entity deliveries) moved to recognition at shipment, accelerating previously deferred revenue."},{"id":"cr-s24-f5","session":24,"front":"Does the sign of a cumulative effect adjustment indicate good or bad news about the company?","back":"No, it simply reflects whether the new standard defers revenue that was recognised earlier under the old rules (negative) or accelerates revenue that was deferred (positive), not earnings quality."},{"id":"cr-s24-f6","session":24,"front":"Why must an analyst take care comparing companies that used different transition methods?","back":"One restated its historical financials (full retrospective), the other did not (modified retrospective), so a shared year label like 2016 can mean two different accounting bases across the two companies."},{"id":"cr-s24-f7","session":24,"front":"What share of General Dynamics 2017 revenue was recognised over time versus at a point in time?","back":"71% over time (mostly defense contracts, cost to cost progress method), 29% at a point in time (mostly business jet aircraft, delivery and acceptance)."},{"id":"cr-s25-f1","session":25,"front":"What does IFRS2 apply to, and what is explicitly excluded?","back":"Applies to share based payments for goods or services received. Excludes dividends and a general issue of shares for cash (e.g. a rights issue)."},{"id":"cr-s25-f2","session":25,"front":"Key difference between equity-settled and cash-settled accounting.","back":"Cash-settled liabilities are remeasured to fair value at every reporting date until settlement. Equity-settled cost is fixed once, at grant date, and never remeasured for later share price movements."},{"id":"cr-s25-f3","session":25,"front":"Measurement hierarchy for share based payments to non-employees.","back":"Measured at the fair value of the goods or services received (at date of receipt) unless that cannot be measured reliably, in which case use the fair value of the equity instruments granted (at grant date)."},{"id":"cr-s25-f4","session":25,"front":"Define the three key dates in a stock option scheme.","back":"Grant date (option awarded), vesting/service date (end of the service period), maturity date (end of the period during which a vested option can still be exercised)."},{"id":"cr-s25-f5","session":25,"front":"Distinguish a market condition from a non-market performance condition.","back":"Market condition, defined by reference to the price or value of the entity's own equity instruments. Non-market condition, defined by reference to the entity's own operational performance."},{"id":"cr-s25-f6","session":25,"front":"Recognition timing, no vesting condition vs a vesting condition.","back":"No vesting condition, full expense recognised immediately at grant date. Vesting condition present, expense spread over the vesting period."},{"id":"cr-s25-f7","session":25,"front":"At what date is the cost of an equity-settled award measured, and is it ever revisited?","back":"At grant date fair value, fixed once, never revisited for later market condition changes like share price movements."},{"id":"cr-s25-f8","session":25,"front":"What happens to cumulative expense on failure of a service or non-market performance condition (forfeiture)?","back":"It is revised to the best estimate of instruments actually expected to vest, backing out the forfeited award's share of the expense."},{"id":"cr-s25-f9","session":25,"front":"What happens to cumulative expense on failure of a market condition?","back":"Nothing, no accounting adjustment at all, the expense continues exactly as originally planned since the probability was already built into grant date fair value."},{"id":"cr-s25-f10","session":25,"front":"What happens when a vested option expires unexercised?","back":"A pure equity reclassification (from stock options equity to expired stock options equity), zero effect on P&L, assets, liabilities or total equity."},{"id":"cr-s25-f11","session":25,"front":"In the exercise date journal entry, which figure is always the balancing plug?","back":"Share premium. Cash received and nominal-value share capital are both directly computable from the facts."},{"id":"cr-s26-f1","session":26,"front":"eBay 2000, as reported profit versus pro forma fair value result.","back":"As reported (APB25) net income of about 48.3 million dollars, versus a pro forma (SFAS123 fair value) net loss of about 90.7 million dollars, same company, same year."},{"id":"cr-s26-f2","session":26,"front":"Define APB25's intrinsic value method.","back":"Compensation expense = fair value of stock minus exercise price, both measured at grant date, zero for an at-the-money grant."},{"id":"cr-s26-f3","session":26,"front":"Define SFAS123's fair value method.","back":"Compensation cost measured using an option pricing model (Black-Scholes), capturing the option's full fair value including time value and expected volatility, used by eBay only for pro forma disclosure, not recognition."},{"id":"cr-s26-f4","session":26,"front":"Why did most of eBay's options generate zero APB25 expense?","back":"Because they were granted at the money (exercise price equal to grant date stock price), making the intrinsic value spread exactly zero."},{"id":"cr-s26-f5","session":26,"front":"What does IFRS2 require that neither APB25 nor SFAS123's disclosure-only regime required?","back":"Mandatory recognition of the full grant date fair value in the primary financial statements, not merely pro forma footnote disclosure."},{"id":"cr-s26-f6","session":26,"front":"eBay 2000 grants, exercise price versus grant date fair value, and why the gap.","back":"Weighted average exercise price 62.69, weighted average grant date fair value 103.79. The gap is time value, driven mainly by a 115% expected volatility assumption and multi year expected life."},{"id":"cr-s26-f7","session":26,"front":"How does the eBay case connect to the Session 16 recognition versus disclosure literature?","back":"It is a concrete illustration that investors treat recognised values as more relevant than merely disclosed pro forma values, the same pattern found generally for stock option expense (Aboody 1996)."},{"id":"cr-s26-f8","session":26,"front":"Does the pro forma loss mean eBay's underlying business was failing in 2000?","back":"No, eBay was profitable and cash generative, the pro forma loss reflects an accounting reclassification of stock compensation cost, not the underlying business economics."},{"id":"cr-s27-f1","session":27,"front":"List IAS19's four categories of employee benefits.","back":"Short-term benefits, post-employment benefits, other long-term benefits, and termination benefits."},{"id":"cr-s27-f2","session":27,"front":"Defined contribution versus defined benefit, who bears the risk?","back":"Defined contribution, risk (actuarial and investment) sits with the employee. Defined benefit, risk sits with the entity."},{"id":"cr-s27-f3","session":27,"front":"What actuarial method estimates the defined benefit obligation?","back":"The projected unit credit method, incorporating demographic assumptions (turnover, mortality) and financial assumptions (salary growth, inflation), discounted to present value."},{"id":"cr-s27-f4","session":27,"front":"How is the IAS19 discount rate determined?","back":"By reference to market yields at the reporting date on high quality corporate bonds (or, absent a deep market, government bonds), matching the obligation's currency and estimated term."},{"id":"cr-s27-f5","session":27,"front":"List the five components of defined benefit accounting and where each is recognised.","back":"Service cost (P&L), net interest (P&L), remeasurements (OCI, never recycled), employer contributions (balance sheet only), benefits paid (balance sheet only)."},{"id":"cr-s27-f6","session":27,"front":"How is interest income on plan assets computed?","back":"The same discount rate used for the obligation, applied to the plan assets' opening fair value. Any gap between this and the actual return is a remeasurement in OCI."},{"id":"cr-s27-f7","session":27,"front":"Are defined benefit remeasurements ever recycled from OCI to P&L?","back":"No, they are permanently excluded from profit or loss once recognised in OCI."},{"id":"cr-s27-f8","session":27,"front":"How does other long-term benefits' OCI treatment differ from post-employment defined benefit?","back":"All remeasurement changes for other long-term benefits go through P&L, there is no OCI split at all, unlike the defined benefit P&L/OCI split."},{"id":"cr-s27-f9","session":27,"front":"When is past service cost recognised?","back":"Immediately in P&L, at the earlier of the date of the plan amendment/curtailment or when related restructuring costs are recognised, not spread over future service."},{"id":"cr-s27-f10","session":27,"front":"Are employer contributions and benefits paid P&L items?","back":"No, both are pure balance sheet movements. Contributions increase plan assets, benefits paid reduce both the obligation and plan assets, neither is an income statement expense."},{"id":"cr-s28-f1","session":28,"front":"Name the five standards governing investments in other entities and what each covers.","back":"IFRS10 (consolidation requirements), IAS27 (parent's separate financial statements), IAS28 (equity method for associates/JVs), IFRS11 (joint arrangements), IFRS12 (disclosure)."},{"id":"cr-s28-f2","session":28,"front":"How are investments in associates treated in consolidated and separate financial statements?","back":"The equity method (IAS28), in both consolidated and the parent's own separate financial statements."},{"id":"cr-s28-f3","session":28,"front":"State IFRS10's three-part test for control.","back":"1. Power over the investee, 2. Exposure or rights to variable returns from involvement with it, 3. The ability to use that power to affect those returns. All three are required."},{"id":"cr-s28-f4","session":28,"front":"Define protective rights and their effect on control.","back":"Rights designed only to protect the holder's own interest without conferring the ability to direct relevant activities, they never give power however extensive they appear."},{"id":"cr-s28-f5","session":28,"front":"What makes a right substantive?","back":"The holder has the practical ability to exercise it, with no barriers to doing so, non-substantive rights cannot confer power."},{"id":"cr-s28-f6","session":28,"front":"Formula, fair value of net assets acquired.","back":"Book equity of the acquiree at acquisition plus step-ups (net of deferred tax) minus step-downs (net of deferred tax)."},{"id":"cr-s28-f7","session":28,"front":"A step-up produces what deferred tax item, and why?","back":"A deferred tax liability, because the asset is now carried above its tax base, a taxable temporary difference exactly like the Session 19 rule."},{"id":"cr-s28-f8","session":28,"front":"Compare NCI measurement and resulting goodwill, partial versus full goodwill method.","back":"Partial method, NCI at proportionate share of net assets, smaller total goodwill. Full method, NCI at its own fair value, larger total goodwill (includes NCI's implied share of goodwill)."},{"id":"cr-s28-f9","session":28,"front":"How is negative goodwill (a bargain purchase) treated?","back":"Recognised immediately as income, increasing group reserves at the acquisition date, the opposite of ordinary goodwill's asset treatment."},{"id":"cr-s28-f10","session":28,"front":"Does control require a majority of voting shares?","back":"No, power can exist without a voting majority via substantive contractual rights, and a bare voting majority can also fail to give power if the related rights are not substantive."},{"id":"cr-s29-f1","session":29,"front":"How are intra-group balances (loans, receivables, payables) treated on consolidation?","back":"Cancelled out entirely, since a group cannot owe money to or earn interest from itself."},{"id":"cr-s29-f2","session":29,"front":"Downstream versus upstream unrealised profit elimination.","back":"Downstream (parent to subsidiary), entirely against group retained earnings, none to NCI. Upstream (subsidiary to parent), split proportionately between group retained earnings and NCI."},{"id":"cr-s29-f3","session":29,"front":"What happens to a fair value step-up on a depreciable asset after acquisition?","back":"It must be depreciated or amortised over the asset's remaining useful life, with a matching partial reversal of the deferred tax liability originally recognised on it each period."},{"id":"cr-s29-f4","session":29,"front":"Inventory unrealised profit example, why does a deferred tax asset arise on elimination?","back":"Because the selling group company already paid tax on the profit, but the profit is not yet realised from the group's perspective (goods still unsold within the group), creating a deferred tax asset."},{"id":"cr-s29-f5","session":29,"front":"When is no further unrealised profit elimination needed on inventory?","back":"When the buying company's own write-down of the inventory already equals or exceeds the intra-group profit embedded in it."},{"id":"cr-s29-f6","session":29,"front":"Are genuine fair value losses on intra-group sales reversed in consolidation?","back":"No, only artificial losses created by internal pricing are reinstated, a loss reflecting a real fair value decline stands as is."},{"id":"cr-s29-f7","session":29,"front":"List the three adjustments needed to eliminate unrealised profit on an intra-group fixed asset sale.","back":"Eliminate the gain on disposal, reduce depreciation back to what it would have been on the seller's original cost basis, and restate the carrying amount to the group-level net book value."},{"id":"cr-s29-f8","session":29,"front":"Intra-group dividend elimination, what happens to group retained earnings and NCI equity?","back":"Group retained earnings falls by the full amount distributed (the parent's own dividend income is cancelled against it). NCI equity falls only by the portion actually paid out to minority shareholders."},{"id":"cr-s29-f9","session":29,"front":"State the golden rule of consolidation regarding ownership percentage.","back":"Every subsidiary's assets, liabilities, revenues, expenses and consolidation adjustments are consolidated at 100% first, regardless of actual ownership percentage, NCI's share is carved out only afterward."},{"id":"cr-s29-f10","session":29,"front":"Formula, NCI's share of net income.","back":"% NCI times (the subsidiary's net income plus or minus consolidation adjustments originating with that specific subsidiary, e.g. its own step-up depreciation or upstream unrealised profit)."},{"id":"cr-s30-f1","session":30,"front":"Define a business under IFRS3.","back":"An integrated set of activities and assets capable of being managed to provide goods/services, investment income, or other ordinary income, consisting of inputs, processes and the capability to produce outputs, even without outputs yet existing."},{"id":"cr-s30-f2","session":30,"front":"List the four steps of the IFRS3 acquisition method.","back":"1. Identify the acquirer, 2. Determine the acquisition date, 3. Recognise and measure identifiable net assets/NCI/consideration, 4. Recognise goodwill or a bargain purchase gain."},{"id":"cr-s30-f3","session":30,"front":"In a reverse acquisition, who is the accounting acquirer?","back":"Not necessarily the legal acquirer, IFRS3 looks through legal form to which party's shareholders and management actually end up controlling the combined entity."},{"id":"cr-s30-f4","session":30,"front":"How are acquisition-related costs (legal, consulting, valuation fees) treated?","back":"Expensed as incurred, never part of consideration transferred or goodwill, except debt/equity issuance costs which follow IFRS9's own rules instead."},{"id":"cr-s30-f5","session":30,"front":"Define the acquisition date.","back":"The date control actually passes to the acquirer, which drives when fair value measurements are taken, not necessarily the same as the legal transfer date."},{"id":"cr-s30-f6","session":30,"front":"Can previously unrecognised intangibles (like customer relationships) be recognised on acquisition?","back":"Yes, because acquisition accounting applies a fair value recognition threshold that differs from the acquiree's own historical recognition criteria (e.g. IAS38's ban on capitalising internally generated intangibles)."},{"id":"cr-s30-f7","session":30,"front":"Formula, goodwill under IFRS3.","back":"Consideration transferred plus NCI plus fair value of any previously held interest, minus the net fair value of identifiable assets acquired. Negative result = bargain purchase gain to P&L."},{"id":"cr-s30-f8","session":30,"front":"Step acquisition, what happens to the previously held interest when control is obtained?","back":"It is remeasured to fair value at the acquisition date, with the resulting gain or loss recognised in profit or loss, regardless of how the prior stake was previously classified."},{"id":"cr-s30-f9","session":30,"front":"How is a disposal of shares that does NOT cause loss of control treated?","back":"As a pure equity transaction, no P&L impact, the difference is reallocated directly between the parent's equity and NCI."},{"id":"cr-s30-f10","session":30,"front":"Can a contingent liability be recognised in a business combination even if it fails IAS37's normal threshold?","back":"Yes, IFRS3 recognises an acquiree's contingent liability at fair value if reliably measurable, a lower recognition bar than IAS37's standalone probable test."},{"id":"cr-s31-f1","session":31,"front":"What combination of facts establishes Lyradon's control over Velquanta despite only 65% ownership?","back":"65% equity stake giving variable returns, combined with a 4-of-6 board majority and simple majority voting, giving Lyradon the structurally guaranteed power to win ordinary board decisions."},{"id":"cr-s31-f2","session":31,"front":"Why are Alpine Ventures' veto rights classified as protective, not substantive?","back":"They are confined to capital structure and distribution decisions (dividends, buybacks, capital reduction, large financing) and preserving Alpine's own contractual rights, not extending into Velquanta's ordinary operating or strategic decisions."},{"id":"cr-s31-f3","session":31,"front":"What would make Alpine's rights substantive instead of protective?","back":"If they extended into ordinary-course operating or strategic decisions (like approving annual budgets or R&D programmes), or if the financing threshold were lowered enough to routinely capture ordinary financing activity."},{"id":"cr-s31-f4","session":31,"front":"What is Velquanta's acquisition date, and why?","back":"1 July 2024, the stated completion date, since the acquisition date is strictly when control actually transfers, not the earlier signing date (3 June 2024)."},{"id":"cr-s31-f5","session":31,"front":"Formula and result, fair value of net identifiable assets in this case (EUR'000).","back":"Book equity 13,000 plus net fair value adjustments 17,000 (PPE +3,000, developed tech +8,000, customer relationships +5,000, IPR&D +2,000, contingent liability -1,000) = 30,000."},{"id":"cr-s31-f6","session":31,"front":"Goodwill and NCI under the partial method in this case (EUR'000).","back":"Goodwill = 48,000 - 65%x30,000 = 28,500. NCI = 35%x30,000 = 10,500."},{"id":"cr-s31-f7","session":31,"front":"Is the 28,500 goodwill figure final?","back":"No, it is a cash-only floor. The contingent consideration (earn-out)'s fair value, once estimated, must still be added to consideration transferred and therefore to goodwill."},{"id":"cr-s31-f8","session":31,"front":"Why can Velquanta's developed technology and customer relationships be recognised now even though never capitalised by Velquanta itself?","back":"Business combination accounting uses a fair value recognition threshold that overrides the acquiree's own historical IAS38-based recognition restrictions on internally generated intangibles."},{"id":"cr-s31-f9","session":31,"front":"How are Lyradon's EUR 1.2 million transaction costs treated?","back":"Expensed in the period incurred, explicitly kept separate from and excluded from the consideration transferred and from goodwill."}],"fm":[{"id":"fm-s1-f1","session":"1","front":"What is the central lesson of the Toys \"R\" Us case?","back":"Profitability on paper is not sufficient if the company cannot generate and access enough cash to service debt and reinvest. Financial planning exists to catch this gap before it becomes a solvency crisis."},{"id":"fm-s1-f2","session":"1","front":"Define value creation per this session.","back":"The outcome of three simultaneous equilibria a firm must maintain: income statement equilibrium, balance sheet equilibrium, and cash flow statement equilibrium. A firm profitable on the IS but insolvent on the BS or cash-starved on the CF is not creating sustainable value."},{"id":"fm-s1-f3","session":"1","front":"Name the four reasons given for targeting value creation over market share or revenue growth.","back":"It is rational (reflects ability to grow long term), broadly accepted (aligns with stakeholder interests), sector- and lifecycle-agnostic (applies regardless of industry or life stage), and measurable (valuation techniques exist to quantify it)."},{"id":"fm-s1-f4","session":"1","front":"What is the World Uncertainty Index (WUI)?","back":"An index built from the frequency of the term \"uncertainty\" in EIU quarterly country reports, trending upward since 1990 with spikes at events like the Gulf War, 9/11, the 2008 credit crunch, Brexit, COVID-19, the war in Ukraine, and the 2023 banking turmoil."},{"id":"fm-s1-f5","session":"1","front":"List McKinsey's six practices to improve FP&A accuracy under uncertainty.","back":"Use explicit probability values for assumptions, build a momentum case, make the bear case explicit, ensure clarity and consistency in macro assumptions, disaggregate inflation rates, back-test regularly."},{"id":"fm-s1-f6","session":"1","front":"What is a bear case in FP&A, and why include one?","back":"An explicit, plausible downside scenario, included so the firm can adjust assumptions as warning signals emerge and avoid decision paralysis."},{"id":"fm-s1-f7","session":"1","front":"Compare the frequency of the cash budget, financial budget, and financial plan.","back":"Cash budget is monthly or weekly; financial budget is annual or quarterly; financial plan is annual."},{"id":"fm-s1-f8","session":"1","front":"Compare the horizon of the cash budget, financial budget, and financial plan.","back":"Cash budget is short term (6 months to 1 year); financial budget is medium term (1 year); financial plan is medium-long term (3, 5 or 7 years)."},{"id":"fm-s1-f9","session":"1","front":"What is the purpose of a cash budget versus a financial plan?","back":"Cash budget ensures solvency and manages cash (treasury and liquidity management); financial plan supports long-term vision and assesses funding needs (strategic and financial planning)."},{"id":"fm-s1-f10","session":"1","front":"Define a cash budget.","back":"A forecast of periodic cash balances (typically monthly or weekly) used to plan for funding needs or the deployment of a potential cash surplus."},{"id":"fm-s1-f11","session":"1","front":"State the cash budget identity and what each term means.","back":"Cash(EOP) = Cash(BOP) + (Sources of cash − Uses of cash) + Financial income (charges) on the cash balance. BOP and EOP are beginning/end of period cash balances; financial income or charges is interest earned or paid on the balance."},{"id":"fm-s1-f12","session":"1","front":"Name the three reasons cost/revenue differ from cash outflow/inflow.","back":"Timing mismatch between accrual and cash accounting, non-monetary events like depreciation, and events entirely outside the income statement like loan repayments."},{"id":"fm-s1-f13","session":"1","front":"List the four categories of sources and uses of cash.","back":"Operating activities, investing activities, financing activities, and other activities (interest, dividends, royalties, rental income)."},{"id":"fm-s1-f14","session":"1","front":"What is the largest typical source of cash for a firm?","back":"Payments from the firm's own customers (cash sales and collections of receivables), not financing activity."},{"id":"fm-s1-f15","session":"1","front":"In the Clank case, why is a large cash outflow (CRM platform capex) not matched by an equally large accounting cost?","back":"Because €150,000 of expansion capex is paid in cash on an uneven schedule (10% May, 50% September, 20% October, 20% November), but only €22,500 of annual depreciation hits the income statement, a large cash outflow with a much smaller accounting footprint."},{"id":"fm-s1-f16","session":"1","front":"How is Clank's monthly revenue actually collected, per the case?","back":"Revenue is recognized (invoiced) monthly, but only 70% is collected 90 days later and 30% after 120 days, a textbook timing mismatch between accrual and cash."},{"id":"fm-s1-f17","session":"1","front":"What creates the overdraft cost risk in the Clank case?","back":"If the cash balance goes negative, an overdraft facility (limit €90,000) charges 1% monthly interest, billed quarterly, with no interest earned on positive balances."},{"id":"fm-s1-f18","session":"1","front":"Name the three-step process for building a cash budget.","back":"Forecast the sources of cash, forecast the uses of cash, then calculate whether the firm faces a cash shortage or surplus and plan accordingly."},{"id":"fm-s2-f1","session":"2","front":"What is the central thesis of Kaiser & Young's HBR 2009 article?","back":"Most companies have a lot of capital needlessly tied up in receivables and inventory, and correcting six recurring, incentive-driven mistakes can free enough cash to matter for survival."},{"id":"fm-s2-f2","session":"2","front":"Name all six working-capital mistakes from the article.","back":"1) Managing to the income statement, 2) rewarding the sales force for growth alone, 3) overemphasizing quality in production, 4) tying receivables to payables, 5) applying current and quick ratios, 6) benchmarking competitors."},{"id":"fm-s2-f3","session":"2","front":"Why does a purchasing manager judged on reported profit alone have no incentive to decline a bulk discount that requires excess inventory?","back":"Inventory holding costs never appear on the income statement, so even if those costs exceed the price gain, accepting the discount doesn't hurt the manager's own compensation."},{"id":"fm-s2-f4","session":"2","front":"State the receivables trade-off break-even rule (Mistake 1).","back":"Accept a change in payment terms if the expected profit loss is smaller than the return you could earn on the capital freed up; reject it otherwise."},{"id":"fm-s2-f5","session":"2","front":"What incidental benefit came from increased customer contact under the new receivables policy (metals refining case)?","back":"It surfaced early warning signs of customers' financial distress, letting at-risk customers be shifted to pay-on-delivery terms before defaulting, cutting bad receivables from 12% to under 0.5%."},{"id":"fm-s2-f6","session":"2","front":"Why does sales compensation tied only to volume inflate both receivables and inventory?","back":"Salespeople are pushed to book sales at any cost: granting long payment delays, avoiding pressure on late payers, and demanding oversized finished-goods inventory to avoid stock-outs."},{"id":"fm-s2-f7","session":"2","front":"What did the European drive-systems producer's case reveal about quality bonuses?","back":"Bonuses for defect reduction produced a manufacturing cycle nearly three times longer than competitors' while customers lacked the sophistication to value the extra quality; cutting WIP inventory (not defending the price premium) freed €20 million."},{"id":"fm-s2-f8","session":"2","front":"Why are receivables and payables relationships independent (Mistake 4)?","back":"Relative bargaining power, competition, industry structure, and switching costs differ across the customer and supplier relationships, so tightening customer terms whenever a supplier tightens theirs is usually the wrong move."},{"id":"fm-s2-f9","session":"2","front":"Give the McDonald's example used to illustrate Mistake 4.","back":"McDonald's takes 30 to 45 days to pay its suppliers, but this does not mean it gives restaurant customers 45 days to pay for a meal, the two relationships operate under entirely different economics."},{"id":"fm-s2-f10","session":"2","front":"Define the current ratio and the quick ratio.","back":"Current ratio = short-term assets (cash + inventory + debtors) ÷ short-term liabilities (creditors + taxes + deferred dividends). Quick ratio = (short-term assets − inventory) ÷ short-term liabilities."},{"id":"fm-s2-f11","session":"2","front":"Why does optimizing the current or quick ratio tend to destroy value?","back":"A higher ratio is typically achieved by carrying higher receivables and inventory and lower payables, exactly the opposite of sound working-capital practice; the more closely a company chases the ratio, the more likely it is to face a liquidity crisis."},{"id":"fm-s2-f12","session":"2","front":"What is the French appliance manufacturer example used to illustrate Mistake 4's resolution?","back":"The firm applied identical terms to every counterparty despite being strong versus suppliers and weak versus giant retail customers (Wal-Mart, Carrefour, Metro); renegotiating terms per segment put €35 million back in the bank."},{"id":"fm-s2-f13","session":"2","front":"Why does benchmarking only within your own industry (Mistake 6) breed complacency?","back":"A company's numbers can look good relative to industry norms even when the whole industry is inefficient; the best companies benchmark radically, often outside their own industry."},{"id":"fm-s2-f14","session":"2","front":"What allowed the metals refining VP to push receivables from 185 to 45 days despite being told 185 days was \"industry norm\"?","back":"He realized the firm's product quality and reputation meant it did not need to follow the norm, convincing customers to accept one month of inventory cover backed by late-delivery penalties and early-payment discounts."},{"id":"fm-s2-f15","session":"2","front":"What is the unifying diagnostic question the fiche recommends asking on any working-capital case question?","back":"\"What is this person's bonus tied to?\", since nearly every mistake traces back to a performance metric that rewards an action that destroys enterprise value."},{"id":"fm-s2-f16","session":"2","front":"What does \"building a culture of value\" mean as opposed to managing by numbers alone?","back":"A culture where managers across functions engage in ongoing dialogue about value creation with each other, suppliers, and customers, while leadership stays alert to managers gaming metrics, illustrated by Toyota's participative production culture."},{"id":"fm-s2-f17","session":"2","front":"Why is it a mistake to treat a \"better than industry average\" current ratio as evidence of health?","back":"Dell shows a company can already be best-in-class within its industry (computer makers) and still leave huge cash on the table once benchmarked outside it (against retailers)."},{"id":"fm-s3-f1","session":"3","front":"Define the cash cycle in one sentence.","back":"The net delay between paying cash out for inputs and collecting cash in from customers, once the delay the firm itself gets from its own suppliers is netted out."},{"id":"fm-s3-f2","session":"3","front":"What three periods make up the operating cycle plus payable period, and how do they combine into the cash cycle?","back":"Inventory period + receivable period = operating cycle. Cash cycle = operating cycle − accounts payable period = DI + DSO − DPO."},{"id":"fm-s3-f3","session":"3","front":"Write the formulas for DSO, DPO, and DI.","back":"DSO = Accounts Receivable ÷ (Sales ÷ 365). DPO = Accounts Payable ÷ (COGS ÷ 365). DI = Inventory ÷ (COGS ÷ 365)."},{"id":"fm-s3-f4","session":"3","front":"Why is it a common calculation error to scale DI and DPO by daily sales?","back":"DI and DPO are both properly scaled by daily COGS, not sales, only DSO uses daily sales as its denominator."},{"id":"fm-s3-f5","session":"3","front":"Walk through computing the cash cycle with Sales $6,133m, COGS $5,464m, Inventory $879m, AR $764m, AP $682m.","back":"DSO = 764/(6133/365) = 45 days. DPO = 682/(5464/365) = 46 days. DI = 879/(5464/365) = 59 days. Cash Cycle = 59 + 45 − 46 = 58 days."},{"id":"fm-s3-f6","session":"3","front":"Why does Walmart have a cash cycle near zero while Boeing's is close to 179 days?","back":"Walmart is a fast-turnover retailer (low DI, low DSO); Boeing is a long-manufacturing-cycle industrial firm with very high days inventory (~196 days), illustrating how business model shapes the cash cycle."},{"id":"fm-s3-f7","session":"3","front":"What is the carrying-cost vs order-cost trade-off in inventory management?","back":"Carrying cost (storage plus opportunity cost of capital tied up) rises with order size; order cost (handling and delivery of placing/receiving an order) falls with order size. The optimal order size balances the two to minimize total cost."},{"id":"fm-s3-f8","session":"3","front":"What is the reorder point?","back":"The inventory management approach of waiting until stock reaches a minimum threshold, then replenishing with a predetermined order quantity."},{"id":"fm-s3-f9","session":"3","front":"Does optimal inventory scale proportionally with sales?","back":"No, as sales grow the optimal inventory level rises but less than proportionately, an economy of scale in inventory management."},{"id":"fm-s3-f10","session":"3","front":"What condition must hold for just-in-time (JIT) inventory to work?","back":"The flow of production must be steady and predictable, so that no significant safety buffer is needed."},{"id":"fm-s3-f11","session":"3","front":"List the four questions that structure receivables management.","back":"Terms of sale, credit analysis, the credit decision, and collection policy."},{"id":"fm-s3-f12","session":"3","front":"What is \"terms of sale\"?","back":"How long a firm gives customers to pay their bills, and whether it offers a cash discount for prompt payment. Not all sales involve credit: some are cash on delivery or cash before delivery."},{"id":"fm-s3-f13","session":"3","front":"What is credit analysis, and where should analytical effort concentrate?","back":"The process of determining which customers are likely to pay on time, using financial statements or specialist agencies (Dun & Bradstreet, Cerved, Moody's, S&P). Effort should concentrate on the largest clients, not be spread evenly."},{"id":"fm-s3-f14","session":"3","front":"State the expected-gain formula for the credit decision.","back":"E[gain | grant credit] = p × PV(Revenue − Cost) − (1−p) × PV(Cost), where p is the probability the customer pays and PV is present value; grant credit only if this exceeds $0."},{"id":"fm-s3-f15","session":"3","front":"List the three basic principles for exercising judgment in credit allocation.","back":"1) Maximize profit (present value), not minimize the number of bad accounts. 2) Concentrate effort on the dangerous (large or doubtful) accounts. 3) Look beyond the immediate order, a poor risk today can be worth accepting if the customer becomes a regular buyer."},{"id":"fm-s3-f16","session":"3","front":"What is collection policy, and what tool tracks it?","back":"The process for collecting money once due and responding to reluctant payers or defaulters; firms typically keep an aging schedule showing what proportion of accounts are mildly or badly overdue."},{"id":"fm-s3-f17","session":"3","front":"When can it make sense for a firm to extend credit to a customer just cut off by its own bank?","back":"When the firm has more information than the bank about the customer's business, or needs to look beyond the immediate transaction to protect future profitable sales."},{"id":"fm-s3-f18","session":"3","front":"Why is minimizing bad debts the wrong objective for a credit manager?","back":"The goal is to maximize present value by weighing the best case (on-time payment) against the worst case (default); a high profit margin justifies a more liberal credit policy even if it means more bad debts."},{"id":"fm-s45-f1","session":"4-5","front":"List the main types of financial risk a firm faces, per the A2A example categories.","back":"Market risk, credit risk, liquidity risk, operational risk, foreign exchange risk, interest rate risk, business risk, reputational risk, and commodity risk, all interconnected."},{"id":"fm-s45-f2","session":"4-5","front":"Define transaction exposure.","back":"The change in value of outstanding financial obligations that are already contractually fixed, caused by exchange-rate moves before those obligations are settled. It deals with actual cash flow changes on existing contracts."},{"id":"fm-s45-f3","session":"4-5","front":"Define operating/economic exposure.","back":"The change in a firm's expected future cash flows (not yet contracted) caused by an exchange-rate move that affects the firm's international competitiveness, e.g. a stronger home currency makes exports pricier abroad."},{"id":"fm-s45-f4","session":"4-5","front":"Define translation/accounting exposure.","back":"The impact of FX volatility on the consolidation of foreign subsidiaries' accounts into the group's financial statements. It changes reported consolidated numbers but not actual cash flow."},{"id":"fm-s45-f5","session":"4-5","front":"What does hedging transaction exposure actually reduce?","back":"The variability of expected cash flows around their mean, it narrows the range of possible outcomes; it does not necessarily increase the expected cash flow itself."},{"id":"fm-s45-f6","session":"4-5","front":"What are the three basic choices when facing a transaction exposure?","back":"Remain unhedged (accept the FX rate on the settlement date), hedge in the forward market (lock in a rate today), hedge in the options market (pay a premium for the right, not the obligation, to transact at a set rate)."},{"id":"fm-s45-f7","session":"4-5","front":"Which forward position do you take if you have a payable (owe FX)? Which if you have a receivable (will receive FX)?","back":"Payable: long forward (agree to buy the FX at maturity at the forward price). Receivable: short forward (agree to sell the FX at maturity)."},{"id":"fm-s45-f8","session":"4-5","front":"State the importer/exporter options rule.","back":"Importers who owe foreign currency should buy call options (locks an upper limit on the dollar cost); exporters with a foreign-currency receivable should buy put options (locks a lower limit on the dollar value)."},{"id":"fm-s45-f9","session":"4-5","front":"Why is an option's premium always relevant even if the option is never exercised?","back":"The premium is paid regardless of outcome, so it must be netted against the payoff either way, not treated as a cost that only applies when the option is exercised."},{"id":"fm-s45-f10","session":"4-5","front":"Give the break-even spot rate formula for a receivable hedged with a put, and explain what it means.","back":"S*T = F + premium. Above this spot rate, the un-exercised put's payoff (spot minus premium) overtakes the forward's fixed payoff; below it, the forward wins."},{"id":"fm-s45-f11","session":"4-5","front":"Give the break-even spot rate formula for a payable hedged with a call, and explain what it means.","back":"S*T = F − premium. Below this spot rate, the un-exercised call's cost (spot plus premium) falls under the forward's fixed cost, making the option the cheaper choice."},{"id":"fm-s45-f12","session":"4-5","front":"Walk through the woolens importer forward-hedge example.","back":"A US importer owes £100 million in one year, 1-year forward = $1.50/£. Unhedged outcome swings ±$30m with the spot rate. Hedged at $1.50/£, the forward's gain/loss exactly mirrors the unhedged payable's gain/loss, so the hedged total cost is flat at $1.50/£ regardless of the spot rate, that flat line is the entire point of hedging."},{"id":"fm-s45-f13","session":"4-5","front":"In Aidan's case (receivable of £1,000,000, forward €1.0760/£), what does the forward hedge guarantee?","back":"A fixed €1,076,000 in June, whatever the spot rate turns out to be, versus an entirely uncertain euro amount if left unhedged."},{"id":"fm-s45-f14","session":"4-5","front":"In the Boeing landing-gear example (forward $1.46/£, put premium $0.02/£), compute the break-even spot rate.","back":"S*T = F + premium = $1.46 + $0.02 = $1.48/£."},{"id":"fm-s45-f15","session":"4-5","front":"What is over-hedging?","back":"Hedging a larger foreign-currency amount than what actually materializes, turning a risk-reducing hedge into a speculative position on the un-realized portion, since the firm becomes contractually obligated to deliver currency it doesn't actually have."},{"id":"fm-s45-f16","session":"4-5","front":"Walk through why over-hedging created a loss in the worked example (CFO sold 100% of expected $100 forward at T0, actual revenue only $50 at T1).","back":"At collection, the CFO gets $50 from the real sale but must deliver $100 under the forward, so must buy the missing $50 on the spot market and hand it over at the worse forward rate, a loss of €11.5 purely from over-hedging, on top of the ordinary budgeted margin."},{"id":"fm-s45-f17","session":"4-5","front":"What two design questions must every hedging policy answer?","back":"When should hedging start (at budget stage or only once the sale is invoiced/exposure certain), and how much should be hedged (100% of the expected amount or a smaller, more conservative share)."},{"id":"fm-s45-f18","session":"4-5","front":"In the final recap table, why does \"do nothing\" produce both the best-case and the worst-case outcome?","back":"Because remaining unhedged has the widest range of outcomes across the two spot scenarios, exactly the risk hedging is meant to remove; the forward is most stable but gives up upside; the option sits in between, protecting the downside while keeping most of the upside."},{"id":"fm-s45-f19","session":"4-5","front":"Define the forward premium/discount and its formula.","back":"fN,j = [FN($/j) − S($/j)] ÷ S($/j) × (360÷N). A positive result means currency j trades at a forward premium (expected to strengthen); a negative result means a forward discount (expected to weaken)."},{"id":"fm-s45-f20","session":"4-5","front":"What does \"direct quotation\" mean from a European investor's point of view?","back":"How many units of home currency (€) buy one unit of foreign currency ($), e.g. €/$; the indirect quotation is the reciprocal, $/€."},{"id":"fm-s45-f21","session":"4-5","front":"Why does a \"stronger dollar\" mean a lower $/€ number, and why does that matter for a euro-receiving exporter?","back":"A lower $/€ number means fewer dollars are needed to buy one euro, i.e. the dollar is stronger. Since the exporter earns dollars and converts to euros, a stronger dollar converts into more euros, so the lower numeric spot rate is actually the \"good\" scenario for them."},{"id":"fm-s45-f22","session":"4-5","front":"Contrast a forward hedge and an options hedge on cost and payoff shape.","back":"A forward has no premium and gives a symmetric, mirror-image gain/loss that exactly offsets the underlying exposure. An option costs a premium paid regardless of outcome but keeps the favorable-side upside, since it is a right, not an obligation."},{"id":"fm-s7-f1","session":"7","front":"Define the cost of capital and what shapes it.","back":"The minimum return on investments satisfying both shareholders (k_e) and debtholders (k_d): the total cost of financing. Shaped by systematic risk of assets-in-place and sector characteristics: cost structure, sensitivity to the environment, predictability, growth rates."},{"id":"fm-s7-f2","session":"7","front":"Write the WACC formula.","back":"WACC = k_d (1 - t_c) D/(D+E) + k_e E/(D+E), with k_d, k_e expected returns on debt and equity, t_c the corporate tax rate, D and E MARKET values of debt and equity."},{"id":"fm-s7-f3","session":"7","front":"Write the CAPM equation for the cost of equity.","back":"k_e = r_f + beta_levered x MRP: current risk-free rate + beta of the asset x market risk premium."},{"id":"fm-s7-f4","session":"7","front":"What two conditions must a risk-free asset satisfy?","back":"No default risk (generally a government security, if the government is default-free) and no uncertainty about reinvestment rates (zero-coupon security with the same maturity as the cash flow analyzed)."},{"id":"fm-s7-f5","session":"7","front":"Which risk-free rate for valuing a company (very long horizon)?","back":"A long-term government bond rate (e.g. 30-year Treasury), as the best proxy for a zero-coupon bond matched to the long cash-flow horizon - NOT the 3-month T-bill."},{"id":"fm-s7-f6","session":"7","front":"Define the market risk premium and its three properties.","back":"The premium investors demand for an average-risk investment over the risk-free rate. Greater than zero; increases with investors' risk aversion; increases with the riskiness of the average investment."},{"id":"fm-s7-f7","session":"7","front":"Three approaches to estimate the MRP, with one limitation each.","back":"Survey (money managers' expectations): volatile, short-term, unbounded. Historical: sensitive to period, risk-free choice, arithmetic vs geometric average; noisy (SE > 2% even with 80 years) and survivorship bias. Implied premium: derived from current market prices."},{"id":"fm-s7-f8","session":"7","front":"Top-down beta estimation: regression and four practical choices.","back":"Regress stock returns on market returns: R_j = a + b R_m; the slope b is the beta. Choices: period (2-5 years), return interval (daily = more data but liquidity bias towards one), returns including dividends, market index (increasingly international, e.g. MSCI)."},{"id":"fm-s7-f9","session":"7","front":"The three determinants of beta?","back":"Nature of product/service (discretionary = higher beta); operating leverage (more fixed costs = higher beta); financial leverage (more debt = higher equity beta)."},{"id":"fm-s7-f10","session":"7","front":"Levered vs unlevered beta formula, and the bottom-up approach for non-traded assets.","back":"beta_L = beta_u (1 + (1 - t_c) D/E). For non-traded assets: use comparable traded firms - unlever their betas, relever at the target's capital structure."},{"id":"fm-s7-f11","session":"7","front":"What drives the cost of debt?","back":"1) Risk-free rate (base component); 2) default risk of the company (default spread; related to country risk but exposure varies across companies); 3) tax shield: after-tax cost = pre-tax cost x (1 - t_c)."},{"id":"fm-s7-f12","session":"7","front":"Three approaches to estimate the cost of debt?","back":"1) Recent borrowing history (YTM on a liquid straight bond - rarely available); 2) public rating (median rating -> default spread); 3) synthetic rating from the interest coverage ratio ICR = EBIT / interest expenses (or Altman's Z-score)."}],"cg":[{"id":"cg-s1-f1","session":"1","front":"What are the four competing definitions of corporate governance covered in Session 1?","back":"Shleifer & Vishny (1996), narrow/finance view, investor returns. Sheridan & Kendall (1992), broader view, owners plus employees, environment, customers/suppliers, legal compliance. Cadbury Committee (1992), board-centred, 'directed and controlled'. Blair (1995), systemic view, the entire legal/cultural/institutional arrangement."},{"id":"cg-s1-f2","session":"1","front":"What does 'public company' (PC) mean in this course's specific sense?","back":"A listed company whose ownership is so fragmented that no single shareholder holds a stake large enough to make it convenient to take an active part in governing the company."},{"id":"cg-s1-f3","session":"1","front":"What do public-company shareholders typically do instead of fighting to change governance decisions?","back":"They 'vote with their feet', selling their shares when they disagree, rather than exercising real nomination power over directors."},{"id":"cg-s1-f4","session":"1","front":"Define an agency relationship.","back":"A contract under which a principal delegates to an agent the power to take decisions on the principal's behalf, in order to accomplish some task."},{"id":"cg-s1-f5","session":"1","front":"What are the three components of agency costs?","back":"Monitoring costs (what the principal spends to observe/constrain the agent), guarantee/bonding costs (what the agent spends to credibly commit not to act against the principal), and residual losses (the welfare loss remaining even after monitoring and bonding)."},{"id":"cg-s1-f6","session":"1","front":"List the three ownership/board configurations of the agency relationship.","back":"1) Dispersed ownership with an independent board. 2) Dispersed ownership with a management-dominated board. 3) Concentrated ownership with overlap between ownership, governance and management (adds a majority-vs-minority shareholder conflict)."},{"id":"cg-s1-f7","session":"1","front":"List the six managerial misbehaviour patterns.","back":"Empire building, shirking, wealth extraction, entrenchment, short-termism/window dressing, favouritism/nepotism and insider trading."},{"id":"cg-s1-f8","session":"1","front":"What is 'entrenchment' as a managerial misbehaviour, and what context favours it?","back":"Defensive tools that insulate incumbent management/directors from being removed (golden parachutes, poison pills, pyramidal groups, shareholder agreements). Favoured by underdeveloped financial markets."},{"id":"cg-s1-f9","session":"1","front":"Name the five historical governance failures cited in Session 1 and their country/year.","back":"Enron (US, 2001), Parmalat (Italy, 2003), WorldCom (US, 2002), Satyam (India, 2009), Theranos (US, 2015)."},{"id":"cg-s1-f10","session":"1","front":"What recurring ingredients does the lecture identify across Enron, Parmalat, WorldCom, Satyam and Theranos?","back":"Ineffective boards (lacking independence or expertise), conflicts of interest among auditors/advisors/dominant families, weak transparency and internal controls, and excessive concentration of power in a CEO or founder."},{"id":"cg-s1-f11","session":"1","front":"What are the three families of governance response mechanisms?","back":"1) Make markets efficient and rely on them. 2) Define and impose structures, rules and mechanisms (board structure, internal/external controls). 3) Privilege some ownership structures over others (public company, blockholding, institutional-investor ownership)."},{"id":"cg-s1-f12","session":"1","front":"Through what three channels does the market for corporate control operate?","back":"Proxy fights (gathering proxies for an alternative board slate), friendly takeovers (agreed reshaping of governance), and hostile takeovers (a raider buying over 50% of voting shares to gain control)."},{"id":"cg-s1-f13","session":"1","front":"Why is debt sometimes described as a governance device?","back":"Debt carries a reimbursement plan and mandatory interest payments, which reduces free cash flow and managerial discretion to spend it outside the firm's stated objectives."},{"id":"cg-s1-f14","session":"1","front":"What two conflicts does debt as a governance device itself create?","back":"Asset substitution (shareholders tempted into risky investments since they capture the upside while creditors bear the downside) and debt overhang (a highly indebted firm can lose good investment opportunities because it struggles to find new funding)."},{"id":"cg-s1-f15","session":"1","front":"What is the LLSV logic linking legal protection to ownership concentration?","back":"Where legal protection of shareholders/creditors is weak, ownership concentration substitutes for the law (blockholders protect their own interests directly). Where legal protection is strong, dispersed ownership becomes viable because minority shareholders can trust the law."},{"id":"cg-s1-f16","session":"1","front":"In the LLSV table, which legal origin has the highest antidirector rights score, and which has the lowest?","back":"Common law has the highest (4.00 out of 5/6). French civil law has the lowest (2.33, tied with German civil law)."},{"id":"cg-s1-f17","session":"1","front":"What is a fiduciary duty, per this session?","back":"Legal duties directors owe to the corporation, including the duty of loyalty, to pursue the company's objectives rather than personal interests. Directors' fiduciary duties run to shareholders specifically."},{"id":"cg-s1-f18","session":"1","front":"Distinguish residual income rights from residual control rights (as first introduced conceptually via agency costs in Session 1, developed further in Session 2).","back":"Residual income rights are the right to profits left over after obligations are paid. Residual control rights are the right to decide when a contract is silent or incomplete. Both matter because the principal (shareholders) is exposed when contracts are incomplete."},{"id":"cg-s2-f1","session":"2","front":"State the shareholder view's core claim.","back":"The corporation exists primarily to maximize shareholder value, shareholders, as residual claimants, are the ultimate owners, and managers act as their agents."},{"id":"cg-s2-f2","session":"2","front":"List the four core assumptions of the shareholder view.","back":"1) Purpose is to maximize shareholder value. 2) Shareholders are residual claimants of profits. 3) Managers and boards act as agents of shareholders. 4) Stakeholders are considered only instrumentally."},{"id":"cg-s2-f3","session":"2","front":"List the five extended assumptions the shareholder view depends on.","back":"Maximizing shareholder value maximizes corporate value, financial markets are efficient, shareholder value maximization disciplines managers (falling stock price), stock-based incentives align managers with shareholders, and the market for corporate control disciplines managers."},{"id":"cg-s2-f4","session":"2","front":"What is 'the firm as a nexus of contracts'?","back":"The firm is a web of implicit (informal expectations, e.g. job security) and explicit (legal agreements, e.g. salary) contracts regulating the rights and duties of its stakeholders."},{"id":"cg-s2-f5","session":"2","front":"Define residual income rights and residual control rights, and who holds them.","back":"Residual income rights, the right to profits after all contractual obligations are met. Residual control rights, the right to decide when a contract is silent or incomplete. Both allocated to shareholders, because they receive residual income and are most exposed to expropriation when contracts are incomplete."},{"id":"cg-s2-f6","session":"2","front":"What is the key question the ownership-rights session poses?","back":"Who should control a corporation to maximize its long-term survival and prosperity?"},{"id":"cg-s2-f7","session":"2","front":"Compare the property conception and social entity conception of the firm across definition, assets, and managers' role.","back":"Property, nexus of contracts, assets belong to shareholders, managers are agents of shareholders. Social entity, a social institution, assets used for multiple stakeholders, managers are trustees balancing diverse interests."},{"id":"cg-s2-f8","session":"2","front":"What are the four types of stakeholder power in the stakeholder map?","back":"Voting power (equity stakes), political and regulatory power (governments/regulators), environmental and social power (customers, communities, environmental standards), economic power (employees, customers, suppliers, competitors)."},{"id":"cg-s2-f9","session":"2","front":"List the four definitions of what corporate governance is for.","back":"Shareholder definition (maximize shareholder value), stakeholder definition (balance all interests), managerial definition (managers' own interests), firm definition (firm's own long-term survival/competitiveness)."},{"id":"cg-s2-f10","session":"2","front":"What did the 2019 Business Roundtable Statement commit signatory CEOs to?","back":"Delivering long-term value to customers, investing in employees (training, fair pay, diversity), dealing fairly with suppliers, supporting communities, and generating long-term value for shareholders, a voluntary shift from shareholder primacy toward stakeholder capitalism."},{"id":"cg-s2-f11","session":"2","front":"Who echoed the Business Roundtable's message, and how?","back":"BlackRock CEO Larry Fink, by calling on companies to serve a 'social purpose' alongside profit."},{"id":"cg-s2-f12","session":"2","front":"Why are residual control rights allocated specifically to shareholders rather than another stakeholder group?","back":"Because shareholders are the ones who receive residual income and are therefore most exposed to being expropriated by managers when contracts are incomplete, so they need decision rights over matters like dividend policy, capital increases, and board elections."},{"id":"cg-s2-f13","session":"2","front":"Is the shareholder value maximization argument a description of fact or a conditional argument, per the fiche's exam trap?","back":"A conditional argument, it only holds together if the extended assumptions (efficient markets, effective discipline mechanisms) also hold, it is not a description of how all firms always actually behave."},{"id":"cg-s2-f14","session":"2","front":"What limits does the fiche place on ownership rights as a governance solution?","back":"They are an important tool to mitigate conflicts and agency costs, not a guarantee, controlling shareholders can themselves expropriate other stakeholders, and both contracts and legal enforcement are imperfect."},{"id":"cg-s2-f15","session":"2","front":"Give the property-conception and social-entity-conception company examples from the fiche.","back":"Property conception, ExxonMobil (focus on shareholder returns). Social entity conception, Unilever (Sustainable Living Plan, balancing profits with social/environmental goals)."},{"id":"cg-s2-f16","session":"2","front":"What example illustrates the 'shareholder value maximization disciplines managers' extended assumption?","back":"Boeing's CEO being dismissed after the 737 Max crisis, poor performance/reputation damage led to a falling stock price and management change."},{"id":"cg-s3-f1","session":"3","front":"When and how was Enron founded, and how big did it become?","back":"Founded in 1985 in Houston, Texas, from the merger of two gas companies. At its peak it was ranked 7th in the Fortune 500 before collapsing in 2001."},{"id":"cg-s3-f2","session":"3","front":"What made Enron different from a traditional energy company?","back":"It shifted from energy production to energy trading, focusing on financial engineering, derivatives and risk-taking, effectively becoming a 'trading house'."},{"id":"cg-s3-f3","session":"3","front":"Define mark-to-market / accelerated earnings accounting as Enron used it.","back":"A method that allowed Enron to recognize revenues from long-term contracts immediately (the estimated total future profit), instead of spreading them over the life of the contract, disconnecting accounting from actual cash flows."},{"id":"cg-s3-f4","session":"3","front":"Define a Special Purpose Entity (SPE) and how Enron abused it.","back":"A legal entity created outside the main company to hold assets/debt separately. Enron transferred debt to SPEs (keeping it off its own balance sheet), reported only the profits, and used complex opaque structures so banks/auditors wouldn't question them."},{"id":"cg-s3-f5","session":"3","front":"List Enron's five key governance failures.","back":"Aggressive mark-to-market accounting, SPEs hiding debt, the board and auditors (Arthur Andersen) failing to challenge management, a toxic culture of risk-taking/greed/conflicts of interest, and regulatory gaps."},{"id":"cg-s3-f6","session":"3","front":"What is Enron's stated lesson, per the lecture?","back":"Without independent oversight and transparent reporting, complex financial innovations (mark-to-market, SPEs) can be exploited to conceal risk and inflate performance. Effective governance needs strong independent boards, auditor accountability, and regulation that keeps pace with innovation."},{"id":"cg-s3-f7","session":"3","front":"When was Theranos founded, by whom, and what was its peak valuation?","back":"Founded in 2003 by Elizabeth Holmes in Silicon Valley. Reached a $9 billion valuation as a celebrated 'Unicorn' before the fraud was revealed in 2015."},{"id":"cg-s3-f8","session":"3","front":"What three factors made the Theranos scam technically possible?","back":"The proprietary technology was kept secret, demonstrations to investors/partners were misleading, and there was a lack of peer review or external scientific validation of the claimed technology."},{"id":"cg-s3-f9","session":"3","front":"List the three main differences between Theranos and cases like Enron/Satyam.","back":"1) Theranos was early-stage/pre-IPO with no widespread public shareholders. 2) The fraud was scientific/technical, not accounting-based. 3) It was heavily founder-driven, centred on Elizabeth Holmes."},{"id":"cg-s3-f10","session":"3","front":"List Theranos's five key governance failures.","back":"A charismatic founder who concentrated power in herself, no independent board expertise in biotech/medicine, secrecy/opacity limiting investor access to data, unicorn hype culture producing FOMO, and weak due diligence by VCs and retail investors."},{"id":"cg-s3-f11","session":"3","front":"What is Theranos's stated lesson, per the lecture?","back":"Independence, transparency and sector expertise are essential for board oversight in innovative startups."},{"id":"cg-s3-f12","session":"3","front":"What common thread does the lecture draw between Enron and Theranos despite their different fraud mechanisms?","back":"Boards and oversight structures that failed to challenge a dominant management figure or story, accounting engineering in Enron's case, false scientific claims in Theranos's case."},{"id":"cg-s3-f13","session":"3","front":"What role did the Elizabeth Holmes leadership style play at Theranos?","back":"She held centralized power as both CEO and public face, cultivated a cult-like leadership style, and the board, though loyal to her, was inexperienced in biotechnology."},{"id":"cg-s3-f14","session":"3","front":"How did Enron's business model shift affect what kind of company it 'really was'?","back":"It moved from being a traditional gas/energy production utility to effectively a financial trading house focused on derivatives and financial engineering rather than core energy operations."},{"id":"cg-s47-f1","session":"4-7","front":"What are the three board roles?","back":"Strategic task (mission, vision, strategic plans), monitor task (overseeing performance and management behavior), and networking task (reputation, stakeholder relationships)."},{"id":"cg-s47-f2","session":"4-7","front":"List the four types of directors distinguished in the lecture.","back":"CEO, executive (inside) directors, non-executive (outside) directors, and independent directors (a subset of non-executive directors free of compromising ties)."},{"id":"cg-s47-f3","session":"4-7","front":"What is the ideal board size range, per the lecture?","back":"7 to 15 members, balancing enough expertise against efficiency, a board too small lacks expertise, one too large loses efficiency."},{"id":"cg-s47-f4","session":"4-7","front":"Define CEO duality and its main risk.","back":"One person holding both the CEO and Chairman roles simultaneously. Can provide strong leadership but risks excessive concentration of power. Common in the US, rare in the UK."},{"id":"cg-s47-f5","session":"4-7","front":"What is the Lead Independent Director role for?","back":"Appointed specifically when CEO duality exists, to ensure checks and balances, its effectiveness depends on the individual's real independence and involvement."},{"id":"cg-s47-f6","session":"4-7","front":"List the typical board committees.","back":"Audit/Risk/Control, Remuneration, Nomination (Appointments), and increasingly Sustainability, with an executive committee used in specific cases."},{"id":"cg-s47-f7","session":"4-7","front":"What three elements make up the overall board effectiveness framework?","back":"INPUT (structure/composition), PROCESSES (working style, meetings, information, decision-making), and BOARD ROLES (control, service/advice, networking), shaped by contingent variables and stakeholder pressures."},{"id":"cg-s47-f8","session":"4-7","front":"What does the fiche say about board independence at Enron, Theranos and WorldCom?","back":"All three had a majority of outside/independent directors on their boards, yet all failed, showing independence alone is not enough, people and how the board works matter more."},{"id":"cg-s47-f9","session":"4-7","front":"What three process elements does board working style depend on?","back":"Meetings (frequency, duration, quality of setting), information (timely, complete, reliable, covering financials/budgets/strategy/competition), and decision-making style (open debate, avoiding 'board silence')."},{"id":"cg-s47-f10","session":"4-7","front":"Summarize the 2018 Italian board evaluation evidence.","back":"Sample of 202 companies (47 financial, 155 industrial), 84% conducted a board review (27% with an external advisor), but only 24% reported specific governance improvements as a result."},{"id":"cg-s47-f11","session":"4-7","front":"How did external advisor involvement affect Italian board review improvement rates?","back":"Substantially higher improvement rates across the board, e.g. informal meetings/induction programs improved in 35.6% of cases with an advisor versus 4.1% without one."},{"id":"cg-s47-f12","session":"4-7","front":"Distinguish hard law from soft law in board governance.","back":"Hard law, binding legal rules (Civil Code, Consolidated Law on Finance). Soft law, self-regulatory Corporate Governance Codes voluntarily adopted, enforced via 'comply or explain' disclosure rather than legal sanction."},{"id":"cg-s47-f13","session":"4-7","front":"What does 'comply or explain' mean?","back":"Listed firms must disclose reasons for any non-compliance with a Corporate Governance Code, rather than being legally forced to comply, since the codes are non-binding soft law."},{"id":"cg-s47-f14","session":"4-7","front":"Distinguish the Board of Directors from the Top Management Team (TMT).","back":"The board provides guidelines, oversight, and approves strategy/key decisions. The TMT, led by the CEO, develops strategies and business plans that are then submitted to the board for approval and critical review."},{"id":"cg-s47-f15","session":"4-7","front":"Define an independent director precisely.","back":"A non-executive director without financial, professional or personal ties that may compromise their independent judgment, assessed at appointment and re-assessed annually."},{"id":"cg-s47-f16","session":"4-7","front":"List the circumstances that compromise a director's independence, per the Italian Code examples.","back":"Being a significant shareholder, being an executive/top manager of the company or major shareholders in the last 3 years, significant commercial/financial/professional relations in the last 3 years, significant additional remuneration in the last 3 years, more than 9 years of board tenure (within 12), an executive position in a firm where a company executive is also a director, auditor-network ties, and family ties to controlling shareholders/executive directors."},{"id":"cg-s47-f17","session":"4-7","front":"Distinguish the Chairman's role from the CEO's role.","back":"Chairman, organizes/manages board work, sets the agenda, chairs meetings, holds no executive powers except information rights. CEO/Managing Director, manages the company within delegated powers, with certain strategic decisions still requiring board approval."},{"id":"cg-s47-f18","session":"4-7","front":"What are the four main board committees listed?","back":"Appointments Committee (nominations/succession), Remuneration Committee (pay policies), Audit & Risk Committee (internal controls/risk/financial reporting), and the optional Sustainability Committee (ESG/stakeholder engagement)."},{"id":"cg-s47-f19","session":"4-7","front":"How often do boards typically meet, and how much prep time do directors get?","back":"6 to 8 times per year (2 to 4 hours each), with 0.5 to 1 day of study expected in advance of receiving documentation."},{"id":"cg-s47-f20","session":"4-7","front":"List the milestones in Italian board gender quota regulation.","back":"2011 Golfo-Mosca Law (mandatory quotas introduced), 2018 Corporate Governance Code (recommended reserved seats), 2020 Budget Law (quotas extended to six mandates, raised to 40%), 2020 Code update (still 33% for boards specifically, but broadens equal-opportunity principle company-wide)."},{"id":"cg-s47-f21","session":"4-7","front":"What happened to the Italian director gender pay gap between 2012 and 2017?","back":"It actually increased, female executive directors grew in number but saw reduced average compensation, while independent women directors grew steadily but their compensation only slightly increased."},{"id":"cg-s47-f22","session":"4-7","front":"What board responsibilities exist around market relations and integrity safeguards?","back":"Transparent, timely communication with investors with equal access to information for all stakeholders, plus preventing misuse of confidential/price-sensitive information and requiring disclosure/abstention in conflict-of-interest situations."},{"id":"cg-s47-f23","session":"4-7","front":"What does the fiche mean by 'board silence' as a risk?","back":"Passive or disengaged board members failing to participate in open debate and constructive conflict, undermining the decision-making style dimension of board effectiveness."},{"id":"cg-s9-f1","session":"9","front":"List the three models of capitalism and their core logic.","back":"Anglo-Saxon (market/outsider system, dispersed ownership, active markets, easy hostile takeovers). German/Japanese (network/insider system, banks central, cross-shareholdings). Latin (State and family dominant, pyramidal groups, weak financial markets)."},{"id":"cg-s9-f2","session":"9","front":"Define Control-Enhancing Mechanisms (CEMs) and list the three main forms.","back":"Legal/contractual tools letting controlling shareholders exercise voting power disproportionate to cash-flow rights. Three forms, deviation from one-share-one-vote (dual-class shares), shareholders' agreements, and pyramidal groups."},{"id":"cg-s9-f3","session":"9","front":"Walk through the pyramidal group worked example.","back":"A owns 51% of B, B owns 51% of C. A's cash-flow rights in C = 51% x 51% = 26%. A's voting rights in C = 51% (since A controls B which controls C). The gap between 51% voting power and 26% cash-flow rights is what defines the CEM."},{"id":"cg-s9-f4","session":"9","front":"What five factors drive changes in a firm's ownership/governance/strategy system?","back":"Past performance (only extreme results trigger change), owners' values/resources, competitive environment, institutional context, and other contextual conditions (markets, infrastructure, education, technology)."},{"id":"cg-s9-f5","session":"9","front":"List the ownership-strategy archetypes mentioned in the lecture.","back":"Small family firm, large managerial corporation, state-owned company, small venture-backed start-up, franchising network, cooperative, local utility, and joint venture/consortium/association."},{"id":"cg-s9-f6","session":"9","front":"Contrast a cash-rich unconstrained controlling shareholder with one under debt pressure.","back":"Cash-rich, willing to invest heavily long term, open to risky strategies, supports R&D, accepts lower dividends. Debt-constrained, requires high dividends to service its own debt, reluctant to invest/expand, opposes capital increases, favors short-term cash generation."},{"id":"cg-s9-f7","session":"9","front":"What traits make companies more exposed to shareholder activism?","back":"Large underperforming firms, weak managerial ownership, pay-performance misalignment, boards with many independent directors (mixed evidence), and significant institutional ownership."},{"id":"cg-s9-f8","session":"9","front":"Summarize the Aberdeen Standard Investments case.","back":"The largest UK asset manager, $670bn AUM, stakes in 385 listed UK companies. Its Governance & Stewardship team voted against management in 33% of its 'Governance Health Warning' watchlist companies versus 14% of others, illustrating broad portfolio-wide stewardship."},{"id":"cg-s9-f9","session":"9","front":"Summarize the Elliott versus Vivendi contest at TIM (2018).","back":"Elliott (activist hedge fund) took a 5% stake and proposed replacing 6 directors. 8 directors resigned including Vivendi's CEO. A new board was elected with 13/15 independent members. CDP (Italian state investor) entered as a third actor to safeguard TIM as a strategic asset."},{"id":"cg-s9-f10","session":"9","front":"What three distinct goals did Vivendi, Elliott and CDP each pursue at TIM?","back":"Vivendi, industrial control and integrating telecom with media. Elliott, independent value-oriented governance and shorter-term financial returns. CDP, safeguarding TIM as a national strategic asset and rebalancing power between the other two."},{"id":"cg-s9-f11","session":"9","front":"What does the MSCI ESG rating framework measure, and what is its scale?","back":"Companies scored across Environmental, Social and Governance indicators (each measuring a specific risk/opportunity and management quality), aggregated into a rating from AAA (leader) to CCC (laggard)."},{"id":"cg-s9-f12","session":"9","front":"List the seven ESG investment strategies with one example each.","back":"Exclusions (Norway's fund excluding tobacco/coal/weapons), engagement & voting (BlackRock on climate), ESG integration (Goldman Sachs AM), norms-based screening (APG vs UN Global Compact), best in class (RobecoSAM), thematic (iShares Clean Energy ETF), impact investing (Triodos, Leapfrog)."},{"id":"cg-s9-f13","session":"9","front":"Define Italy's Non-Financial Declaration (NFD) and its legal basis.","back":"The Italian implementation (Legislative Decree 254/2016) of EU Directive 2014/95/EU, mandatory since 2017 for large public-interest entities (more than 500 employees), covering environment, social issues, human rights, anti-corruption and workforce policies."},{"id":"cg-s9-f14","session":"9","front":"What is the CSRD, and how does it relate to the NFD?","back":"The Corporate Sustainability Reporting Directive (2024-2026 rollout), introducing ESRS standards, broadening scope to SMEs, and adding assurance requirements. The NFD is the starting point of an ongoing transition toward the CSRD, not the final EU disclosure regime."},{"id":"cg-s9-f15","session":"9","front":"What NFD evidence gap does the lecture highlight?","back":"96% of companies described their main ESG risks and 88% described mitigation methods, but only 13% stated integrating ESG into risk management as an explicit objective, a gap between disclosure and genuine integration."},{"id":"cg-s9-f16","session":"9","front":"What correlation did the FTSE MIB findings show between sustainability plans and incentive systems?","back":"A strong correlation, 95% of companies with a declared sustainability plan also had incentives tied to it, versus only 5% of companies without a sustainability plan."},{"id":"cg-s9-f17","session":"9","front":"List the key ownership dichotomies used for governance analysis.","back":"Controlling vs no controlling shareholder, strong (>50%) vs weak controlling shareholder, unique vs coalition, private vs public, weak vs strong stakeholder pressure, financial vs industrial shareholder, weak vs strong business knowledge, cash-rich vs debt-constrained, weak vs strong institutional investor activism."},{"id":"cg-s9-f18","session":"9","front":"Why does the fiche warn about the folder label 'Session 9' for this content?","back":"The source file's title slide reads 'SESSION 9' but its content actually matches syllabus topic 7 (OGS, shareholder activism, ESG investing), not syllabus topic 9 (private/family firm governance design), Blackboard's own session numbering doesn't line up with the printed syllabus."},{"id":"cg-s10-f1","session":"10","front":"What does the HBR (2012) evidence say about family firms, and what are the 5 explanations?","back":"They outperform peers during crises and in the long run. Explanations: financial discipline, strategic caution, diversification, global orientation, people advantage (talent retention)."},{"id":"cg-s10-f2","session":"10","front":"Name the three governance levels and who acts at each.","back":"Ownership governance: owner(s) define vision, values, ultimate control. Corporate governance: Board of Directors (oversight, strategic guidance). Operating governance: Top Management Team (execution, daily operations)."},{"id":"cg-s10-f3","session":"10","front":"In family firms, which bodies cover the company / ownership / family levels?","back":"Company: BoD of operating companies, executive committees. Ownership: holding's Board, holding chairman/CEO, informal committees. Family: family board/committee, periodic family meetings."},{"id":"cg-s10-f4","session":"10","front":"When does governance become critical (4 situations)?","back":"Growth & success; tensions & conflicts; ownership changes (more family members, external shareholders, financial investors); generational factors (aging leader, succession planning, heirs' entry rules)."},{"id":"cg-s10-f5","session":"10","front":"List the benefits of effective governance in family firms.","back":"Stronger decision-making; better risk monitoring and control; improved reputation and credibility; easier to attract/retain strategic partners; reduced family tensions; clearer family-business relationships."},{"id":"cg-s10-f6","session":"10","front":"Name the 7 peculiarities of family-owned firms.","back":"Relational culture; concentration & stability; role overlap; diverse (economic + emotional) objectives; high personal investment; exit barriers; local roots."},{"id":"cg-s10-f7","session":"10","front":"The 'good' vs the 'bad' of family firms?","back":"Good: patient capital, emotional commitment, stable culture, social capital, unique resources, continuity/resilience. Bad: resource appropriation, nepotism/bias, conservatism, conflict management burden, generational risk."},{"id":"cg-s10-f8","session":"10","front":"Key figures on generational transition.","back":"18% declared need vs 9% actual transitions (2011-16); 13% reach 3rd generation; 23% led by over-70 CEOs; 49% of entrepreneurs never retire; survival 30% (1st->2nd), 15% (2nd->3rd)."},{"id":"cg-s10-f9","session":"10","front":"Founder's succession dilemma: which three specific issues?","back":"Charismatic leadership (founder identified with the company, fears losing control); founder-shaped business model never tested without the founder; succession inexperience."},{"id":"cg-s10-f10","session":"10","front":"Three tools for generational transition with multiple successors?","back":"Merit-based selection (skills, competences, values); non-family leadership (external professional manager); parallel ventures (new businesses allocated among heirs)."},{"id":"cg-s10-f11","session":"10","front":"Holding BoD vs operating BoD: core split?","back":"Holding BoD: corporate/group responsibilities (financial oversight, group governance, strategic monitoring, legal duties) + family-related ones (family agreements, next-gen development, family in management, family-firm interface). Operating BoD: appoint CEO/senior management, approve strategies/plans/budgets, monitor execution, submit proposals to shareholders."},{"id":"cg-s10-f12","session":"10","front":"What makes a board effective?","back":"Balanced composition (executive/non-executive, independence, competence); 7-9 members; 6+ meetings/year; annual calendar on strategic issues; materials in advance; ~3h preparation per meeting hour; active culture (no rubber stamp); clear voting rules; chairman leading agenda and debate; minutes and self-assessment."},{"id":"cg-s10-f13","session":"10","front":"Why do outsiders matter, and what do independent directors contribute?","back":"Outsiders increase transparency and reduce the 'closed system' risk. Contributions in control (discipline, conflict-of-interest protection, minorities), strategy (expertise, managerialization, stakeholder relations) and family-firm relations (succession planning, next-gen training, professional conflict management)."},{"id":"cg-s10-f14","session":"10","front":"What does managerialization require?","back":"A careful assessment and re-design of the organizational structure, of managers' profiles and behaviors, and the overall evolution towards a modern management model (fixing oversimplified structures, unclear roles, inconclusive committees)."}]},"CHEATSHEET":{"da":"## Session 1, Introduction to Regression Models\n\n- A regression model expresses Y (dependent variable) as a function of x1,...,xp (explanatory variables), to know/explain/forecast Y's variability.\n- Equation: Y = β0 + β1x1 + ... + βpxp + ε. \"Linear\" means linear in the β's, not necessarily in the x's.\n- Five assumptions: zero-mean error, homoskedasticity (constant variance), uncorrelated errors, normal errors, no perfect multicollinearity.\n- Least squares picks b0,...,bp to minimize the sum of squared residuals. y-hat estimates the mean of Y, not one individual Y.\n- bj = marginal effect of xj: average change in Y per one-unit increase in xj, other x's held constant.\n- Watch for spurious effects: an omitted variable correlated with both xj and Y can flip or fake a relationship (coastal housing example — age drove both distance and price).\n- CI for βj: point estimate ± Student's t quantile × standard error. Higher confidence → wider interval.\n- Test H0: βj=0 via toss = bj/sbj, or via p-value < α.\n- Never extrapolate y-hat0 outside the observed x range.\n- R² = explained/total deviance, never decreases when adding a variable. Adjusted R² penalizes model size — use it to compare models with different p (only for non-nested comparisons; nested models need the partial F-test from Session 2).\n\n## Session 2, Categorical Variables and F-tests\n\n- Dummy variable: 0/1 coding, 1 = characteristic present. Its coefficient = average Y gap between the two groups, other variables held constant.\n- k>2 categories → k−1 dummies (never k — that creates perfect collinearity with the intercept). The excluded category is the reference; every dummy coefficient compares against it, never against another non-reference category directly.\n- To get a non-reference-vs-non-reference gap (e.g. zone C vs zone B when A is reference), compute the difference of the two fitted values yourself — no single coefficient gives it.\n- Dummy coefficients are tested exactly like quantitative ones (same CI, same t-test).\n- Partial F-test: tests joint significance of a GROUP of variables (e.g. all dummies of one categorical variable) between two nested models (reduced ⊂ complete). One term removed → t-test and partial F-test agree. Several terms removed together → only the partial F-test is valid.\n- Global F-test = partial F-test with the null model (intercept only) as the reduced model. Tests whether the whole model matters at all.\n- Total deviance never changes across models fit on the same Y/sample — only residual and explained deviance move.\n- Not rejecting H0 in an F-test = insufficient evidence, not proof of zero effect.\n\n## Session 3, Transformations and Interactions\n\n- Two hidden assumptions of the base model: linearity (effect of xj constant regardless of xj's own value) and additivity (effect of one variable doesn't depend on another variable's level). Both can be wrong, independently.\n- Non-linearity → fixed by transforming a variable (log(x), x², etc.). Non-additivity → fixed by adding an interaction term (product of two variables). Don't confuse the two fixes.\n- With a transformed variable (e.g. x²), the effect is no longer one fixed coefficient: use either the derivative (local, at one exact point) or the finite difference (real change between two specific x values) — never read the raw coefficient as a flat per-unit effect.\n- log(x) shortcut: a ~1% rise in x → mean(Y) changes by about 0.01·b1 (small-change approximation only).\n- Interaction term x1·x2 lets the effect of x1 depend on x2's level (and vice versa). Quantitative × dummy interaction → two lines with both a different intercept AND a different slope (not just parallel shifts).\n- If the interaction coefficient isn't significant, the model behaves like the no-interaction case (parallel lines) — always check its significance before claiming the effect differs by group.\n- One interaction term → t-test. Several interaction terms together, or a variable appearing in several forms (main effect + interaction + quadratic) → one joint partial F-test, never separate t-tests.\n\n## Session 4, Multicollinearity, Assumption Violations, Influential Points\n\n- Multicollinearity (overlap between x's information) is always present a little — the real question is whether it's high enough to matter.\n- High multicollinearity → inflated standard errors → smaller |t| → larger p-values → risk of wrongly concluding a variable isn't significant, even though the group is jointly significant (check: is the global F-test significant even when individual t-tests aren't? That's the multicollinearity signature).\n- VIFj = 1/(1−Rj²) from regressing xj on the OTHER x's (never on Y). VIF > 10 = conventional \"high\" threshold. Use GVIF for dummy variables.\n- Three remedies: drop a variable, increase n, or use PCA/factor analysis.\n- Residuals-vs-fitted plot: no pattern → assumptions OK. Parabola shape → non-linearity. Funnel shape → heteroskedasticity (different problem, different look).\n- Q-Q plot → checks normality; straight line = good, curvature = violation.\n- Y transformed to log(Y) (log-lin or log-log) can fix heteroskedasticity/restore linearity — but then coefficients read as approximate PERCENTAGE effects on Y, not raw units.\n- Outlier = bad fit on Y (large residual, |residual|>3 rule of thumb). Leverage point = unusual on the x's (not Y). They're judged on different axes — one without the other is possible.\n- Influential = removing it changes the results meaningfully. Measured by dfbeta (per coefficient) or Cook's distance (overall). Not every outlier/leverage point is automatically influential — check directly.\n\n## Session 5, Panel Data Models\n\n- Panel data = n units × T time points, each observed repeatedly (both cross-sectional and time dimensions at once). Balanced panel → exactly n×T observations per variable.\n- Classic regression fails on panel data because repeated observations of the same unit are usually correlated over time — violates the uncorrelated-errors assumption.\n- Pooling Model = plain OLS on all n·T points, ignoring panel structure — generally wrong, same spurious-correlation risk as a naive cross-section.\n- FEM: uit = μi + εit, μi fixed/deterministic per unit (absorbs unobserved, time-constant heterogeneity) → each unit gets its own intercept αi, same slope β for all.\n- REM: same split, but μi is random and must be uncorrelated with the x's. Only α and β are estimated (not n separate μi's) → more efficient when valid.\n- μi (individual error) = persistent, time-constant unit differences. εit (idiosyncratic error) = fluctuations varying by unit AND time (short-term shocks/noise).\n- Hausman test: H0 = REM valid. Reject H0 (small p-value) → use FEM. Don't reject → use REM. (Easy trap: rejecting H0 means REM FAILS, switch away from it — don't invert this.)\n- Predicting a specific panel unit under FEM: always use that unit's own fixef() intercept, never a generic/averaged one.\n- FEM/REM extend to multiple x's exactly like simple → multiple regression: just add more xj terms, same logic for μi/εit.\n\n## Session 6, Logistic regression for binary variables (logit model)\n\n- Odds of an event E with probability p, ODDS = p/(1-p). Increasing correspondence with p, ODDS>1 means p>0.5, ODDS<1 means p<0.5.\n- The logit model uses log(ODDS), the log-odds, which is strictly increasing in p, going to minus infinity as p to 0 and plus infinity as p to 1.\n- Y is dichotomous (0/1), p = E(Y). Model equation, log(p/(1-p)) = beta0 + beta1x1 + ... + betapxp, i.e. log-odds is linear in the x's.\n- Coefficients estimated by Maximum Likelihood (not OLS), R does the computation.\n- e^bj is the odds ratio, quantitative xj, effect of +1 unit; dichotomous xj, effect of xj=1 vs xj=0. Always \"other variables held constant.\"\n- bj>0 means odds (and probability) go up; bj<0 means they go down. e^bj is a factor on the ODDS, not a direct percentage change in probability.\n- Individual test, H0: betaj=0, statistic zoss=bj/SE(bj), approx standard normal under H0, reject if |zoss|>z(alpha/2) or p-value<alpha.\n\n## Session 7, significance tests, prediction, model quality\n\n- Individual Z-test only checks one coefficient. For a group of variables or the whole model, use the chi-square (LRT) test instead.\n- chi2 = RES.DEV(reduced) - RES.DEV(complete), df = difference in residual df of the two models. Global test = partial test with the null model as reduced (q=0).\n- Residual deviance RES.DEV = -2 log L(M). Lower is a better fit.\n- Prediction order, log-odds by substitution, exponentiate for odds, convert to probability, threshold 0.5 (default) for predicted Y.\n- AIC = -2logL(M) + 2(p+1), lower is better. Use the partial chi-square test (not AIC) for nested models specifically.\n- Insurance example to remember, AGE coefficient negative (odds go down with age), VC jointly significant via partial chi-square, 84% correct predictions in the confusion matrix.\n\n## Session 8, multinomial logit model\n\n- Used when Y has k>2 unordered categories (k=2 reduces to Session 6's binary model). k-1 equations, each vs one fixed reference category.\n- log(pi/p1) = beta0i + beta1i x1 + ... , coefficients differ across equations for the same variable, always check which category R picked as reference.\n- Coefficient reading, (e^bji - 1) x 100% = percent change in the odds of Ai vs the reference category, other variables held constant.\n- Individual test same logic as Session 6 (z = bji/SE(bji)). Group/global chi-square tests for the multinomial model exist but are explicitly not covered, don't try to compute them.\n- Prediction, substitute x's into the k-1 equations, exponentiate to get ratios pi/p1, solve with sum(pi)=1 to get each probability.\n- Common trap, a coefficient is always relative to the reference category only, never a statement about the raw probability, and coefficients from different equations are not directly comparable to each other.\n","cr":"## Session 1, Global Financial Reporting Regulation and Accounting Principles\n\n- Agency problem, once ownership separates from control, managers (agents) may hold interests diverging from owners (principals); information asymmetry is the resulting gap financial reporting tries to bridge.\n- Regulation has two motives, market imperfections (efficiency) and protecting unsophisticated investors (wealth redistribution). Three sources, legislation, accounting standards, stock exchange rules.\n- GAAP is jurisdiction specific, IFRS is the IASB's attempt at a global standard operating alongside or instead of local GAAPs.\n- IFRS Foundation appoints and funds the IASB (14 members), not the other way round. Advisory Council sets agenda priorities, IFRIC interprets standards.\n- Due process, topic, Conceptual Framework, consultation, discussion document, exposure draft, final standard.\n- EU endorsement is not automatic, each IFRS needs individual ARC endorsement (advised by EFRAG/SARG), enforced nationally, coordinated by ESMA.\n- IFRS required in 100+ countries, permitted in 14 more, not mandatory in the US.\n- Principles vs rules is officially a false distinction, a mix of both is normal.\n\n## Session 2, The IFRS Conceptual Framework\n\n- Not itself an IFRS, a specific standard prevails in case of conflict. Eight chapters.\n- Sole objective, decision usefulness for investors, lenders, creditors, stewardship is included in it, not separate.\n- Fundamental characteristics, relevance (predictive and or confirmatory value) and faithful representation (complete, neutral, free from material error, not ALL error).\n- Enhancing characteristics, comparability, verifiability, timeliness, understandability, they only help once the fundamentals are already there.\n- Prudence supports neutrality, it does not conflict with it.\n- Five elements, asset (present economic resource from past events), liability (present obligation to transfer a resource), equity (residual interest), income and expenses.\n- Two assumptions, going concern and accruals. Recognition needs relevance, faithful representation, and benefits exceeding costs.\n- Two measurement bases, historical cost and current value (fair value, value in use, fulfilment value).\n\n## Session 3, IAS1 and IFRS18, IAS8, IAS10\n\n- Five components of financial statements, position, profit or loss and OCI, changes in equity, cash flows, notes.\n- Cash flow statement is the only one not on an accruals basis.\n- Current asset or liability tests are OR tests (any one condition), not AND tests.\n- Offsetting is prohibited unless another IFRS specifically allows it.\n- IFRS18 replaces IAS1 only from periods beginning 1 January 2027, introduces five P&L categories and new mandatory subtotals.\n- Accounting policy changes are retrospective (restate comparatives), accounting estimate changes are prospective only, material prior period errors are corrected retrospectively.\n- Adjusting events existed at period end (adjust the numbers), non adjusting events arose after (disclose only if material).\n\n## Session 4, IAS7 Statement of Cash Flows\n\n- Cash flow statement exists because profit is accruals based and not a reliable indicator of cash health.\n- Overdraft counts as negative cash, not a financing item. Three activities, operating, investing, financing.\n- Direct and indirect methods give the same bottom line, only presentation differs. Indirect starts from profit before tax (pre IFRS18) and adjusts for non cash items and working capital changes.\n- Working capital sign rule, a decrease in a current asset or increase in a current liability is a source of cash, add it.\n- Pre IFRS18, interest paid usually operating or financing, dividends paid operating or financing, tax operating unless tied elsewhere.\n- IFRS18 forces dividends paid to financing, and interest paid to financing in most cases, and changes the indirect method's starting subtotal.\n- Reconciliation of cash and cash equivalents to the balance sheet is mandatory, segment cash flow analysis is only encouraged.\n\n## Session 5, Financial Instruments I, IAS32 Presentation and Classification\n\n- Three standards, three jobs, IAS32 presentation and classification, IFRS9 recognition and measurement, IFRS7 disclosure.\n- Substance over form, an instrument's legal label does not determine its classification.\n- Equity test needs BOTH Part A (no obligation to deliver cash or exchange unfavourably) AND Part B (settled in own equity instruments).\n- Redeemable preference shares fail Part A, so they are a liability, their dividends are an expense.\n- Compound instruments (like convertible bonds) get split accounting, liability component is the present value of contractual cash flows at the MARKET rate for an equivalent non convertible instrument, equity component is the residual.\n- Liability related interest and dividends go through profit or loss, equity distributions are debited directly to equity, never through P&L.\n\n## Session 6, Financial Instruments II, IFRS9 Recognition and Measurement\n\n- Recognition happens when the entity becomes party to the contract, not when cash moves.\n- Initial measurement is always fair value, for both assets and liabilities.\n- Four asset categories, amortised cost, debt FVOCI (recycles to P&L eventually), equity FVOCI (designated, never recycles), FVPL (default).\n- Amortised cost test needs BOTH the SPPI cash flow test AND the hold to collect business model, failing either forces fair value.\n- Effective interest rate is calibrated to the instrument's real price and cash flows, not the coupon rate, a zero coupon bond has 0 percent coupon but a positive effective rate.\n- Liabilities default to amortised cost, fair value only if held for trading. Trade receivables and payables can use invoice amount if discounting is immaterial.\n\n## Session 7, Financial Instruments III, Derecognition, Impairment, Disclosure\n\n- Impairment and uncollectability is explicitly one of IFRS9's own measurement topics, alongside initial measurement, subsequent measurement, reclassifications, gains and losses.\n- Expected credit loss model is forward looking, a loss allowance is recognised from initial recognition, no need to wait for a loss event, unlike the old incurred loss model.\n- Three stages, Stage 1 (no significant risk increase) 12 month ECL, Stage 2 (significant increase) lifetime ECL, Stage 3 (credit impaired) lifetime ECL plus interest on the net carrying amount.\n- IFRS7 lets users assess significance of instruments and their risks. Three risk categories, market, credit, liquidity, all three should be covered where relevant, not a choice of one.\n\n## Session 8, Financial Instruments IV, Case Study Berkshire Hathaway\n\n- The case's own rule change (US GAAP ASU 2016 01) is not an IFRS rule, use it only as a comparison hook.\n- Equity investments default to FVTPL under IFRS9, FVOCI needs an irrevocable election, instrument by instrument, only for non trading holdings, at initial recognition.\n- Under FVOCI, dividends still go to P&L, only fair value changes go to OCI, and those OCI amounts NEVER recycle to P&L, not even on disposal, this is the single most tested distinction versus debt FVOCI.\n- No separate ECL impairment model exists for equity FVOCI.\n- Decision sequence for any instrument question, IAS32 classification, IFRS9 initial fair value, subsequent measurement, then presentation (P&L vs OCI).\n- The case is framed as a presentation case, not a valuation case, the debate is which line shows the movement, not what the fair value is.\n\n## Session 9, Non Current Assets I, PP&E Recognition and Initial Cost\n\n- IAS16 excludes assets held for sale, biological assets, exploration assets, mineral rights, and investment property (that is IAS40).\n- PP&E needs (a) use in production, supply, rental or admin AND (b) expected use over more than one period.\n- Recognition needs reliable cost measurement AND probable future economic benefits, both required.\n- Three cost elements, purchase price, directly attributable costs, estimated dismantling and restoration cost as a provision.\n- Excluded, admin overheads, feasibility studies, staff training, abnormal waste.\n- Capitalisation stops once the asset is capable of operating as intended, not once it is actually at full capacity.\n- Component approach, depreciate significant parts separately when useful lives differ (aircraft engine vs seats vs airframe).\n- Borrowing costs on qualifying assets are capitalised, specific borrowing rate for dedicated loans, weighted average rate (time apportioned by months) for general borrowings.\n\n## Session 10, Non Current Assets II, Subsequent Costs, Revaluation, Investment Property\n\n- Capitalise additions, improvements, replacements, major non routine inspections. Expense ordinary repairs and relocation or reorganisation costs.\n- Replacing a component means derecognising the old component's carrying amount and capitalising the new one.\n- Cost model, cost minus accumulated depreciation minus accumulated impairment. Three depreciation methods, straight line, diminishing balance, units of production.\n- Land is never depreciated, must be split from any building bought with it.\n- Revaluation model applies to an entire class, no selective revaluation, needed every 3 to 5 years absent big swings.\n- Surplus deficit rule, first surplus to OCI reserve, first deficit to P&L, later moves reverse the prior one first, splitting between reserve and P&L at the point the prior balance runs out.\n- Revalued PP&E keeps being depreciated. IAS40 investment property under the fair value model is the opposite, remeasured every year, no more depreciation, gains AND losses go straight through P&L, never OCI.\n\n## Session 11, Non Current Assets III, Intangible Assets IAS38\n\n- Three part test, non monetary, identifiable (separable OR from contractual/legal rights), no physical substance.\n- Identifiability is what separates a specific intangible from goodwill.\n- Four acquisition routes, separate acquisition at cost, business combination at fair value (IFRS3), government grant at fair value or nominal (IAS20), internally generated at capitalised outlays subject to the R&D split.\n- Internally generated trademarks, mastheads, customer lists are never recognisable, but the same items ARE recognisable if acquired externally or via a business combination.\n- Finite life intangibles are amortised and impairment tested if indicators exist, indefinite life intangibles and goodwill are never amortised but tested for impairment at least annually.\n- Research is always expensed, development is capitalised only if all six conditions hold simultaneously (technical feasibility, intention, ability to use or sell, probable future benefits, adequate resources, reliable measurement).\n- An add on module to an already in use asset is amortised over the REMAINING useful life of the original asset, not a fresh term.\n\n## Session 12, Impairment of Assets I, IAS36 Recognition, CGUs, Goodwill\n\n- Impairment loss equals carrying amount minus recoverable amount, when carrying amount is higher. Recoverable amount is the higher of fair value less costs to sell and value in use.\n- Indefinite life intangibles, goodwill, and not yet in use assets are tested annually regardless of indicators, everything else only when an indicator appears.\n- External indicators, market value decline, adverse environment changes, rising rates, book value above market cap. Internal indicators, damage, changed use, worse than expected internal reporting.\n- A CGU is the smallest group generating largely independent cash inflows, used when an individual asset cannot be tested on its own, it is a fallback, not a default.\n- Goodwill is allocated to CGUs expected to benefit from synergies, the CGU's own assets are tested before goodwill.\n- Allocation order within a CGU, goodwill absorbs the loss first (down to zero), then the rest is spread pro rata across other assets, never below each asset's own fair value less costs to sell or value in use floor.\n- Goodwill impairment can NEVER be reversed. Other assets can be reversed up to what the carrying amount would have been net of notional depreciation.\n\n## Session 13, Impairments II, Case Study Biosensors International Group\n\n- BIG bought the remaining 50 percent of JWMS for 478 million dollars in 2011, taking intangibles plus goodwill from 4 percent to 62 percent of total assets.\n- Customer relationships dominated the acquired intangibles (131 million net of 162 million total), recognisable specifically because they came from a business combination.\n- Land use rights were not yet amortised because the lease had not started yet, consistent with the capable of operating cutoff rule.\n- Goodwill is measured at cost (consideration minus net identifiable assets and liabilities), never amortised, allocated to CGUs.\n- The actual FY2012 impairment hit three SMALLER CGUs, not JWMS, proof that goodwill testing is CGU specific, not company wide.\n- The no impairment conclusion for JWMS rests entirely on management's own DCF assumptions (18 percent growth, 2 percent terminal growth, 12 percent discount rate), not independently verifiable, market capitalisation is offered as an external cross check.\n\n## Session 14, Provisions, Contingent Liabilities and Contingent Assets IAS37\n\n- Provision recognition needs all three, present obligation from a past event, probable outflow, reliable estimate.\n- Legal obligation comes from contract or law, constructive obligation comes from the entity's own conduct creating a valid expectation, both count as obligating events.\n- Uncertainty spectrum, accrued liabilities (most certain, on balance sheet), provisions (on balance sheet, shown separately), contingent liabilities (notes only, or nothing if remote).\n- One off events use the most likely amount, large populations (warranties) use probability weighted expected value.\n- Discount to present value when material, unwind the discount each period as a finance cost.\n- Never net an expected disposal gain against a provision, even if closely linked.\n- Future operating losses are never a provision, they may trigger an IAS36 impairment test instead. Onerous contracts ARE always provided for.\n- Restructuring provisions need both a detailed formal plan AND a valid expectation raised in those affected, only direct restructuring specific costs count, not ordinary retraining or marketing.\n- Contingent assets are never recognised, disclosed only if probable, become ordinary assets once virtually certain.\n\n## Session 16\n\n- A lease conveys the right to control an identified asset only if the lessee gets both the economic benefits AND the right to direct how/for what purpose it's used.\n- Three reasons firms lease: 100% fixed rate financing, protection against obsolescence, contractual flexibility.\n- IAS17 was a dual model (finance vs operating lease, via risk/reward and purchase-similarity tests). IFRS16 is a single model, lessees recognise a ROU asset and lease liability for essentially every lease.\n- IFRS16 barely changed lessor accounting, mainly added disclosure.\n- Before IFRS16, investors and rating agencies already informally capitalised operating leases with rough rules of thumb (liability roughly 8x lease expense).\n- Three goals of the reform: faithful representation, comparability, less room for manipulation.\n- Recognised amounts are consistently found more value relevant to investors than merely disclosed amounts (multiple settings, not just leases).\n- Real effects, firms restructured leases (shorter terms, variable payments, more capex) after capitalisation rules, sometimes with real costs to investment/profitability/employment.\n\n## Session 17\n\n- Only two recognition exemptions, short term leases (12 months or less) and low value leases, both just expensed straight line.\n- Lease term includes reasonably certain renewal periods and reasonably certain non-exercised termination options, an anti-avoidance rule.\n- ROU asset initial cost = initial lease liability + payments at/before commencement + initial direct costs + estimated restoration costs.\n- Lease liability initial measurement = PV of fixed payments + index/rate variable payments + expected residual guarantee payments + purchase option (if likely) + termination penalties.\n- Subsequent, ROU asset depreciated under IAS16, tested for impairment under IAS36. Lease liability uses effective interest, same rate as at initial measurement.\n- Depreciation and interest can never be combined into one income statement line.\n- Principal payments always go to financing cash flows, interest follows the entity's normal interest presentation policy.\n- Lessor accounting is basically unchanged, still operating vs finance lease classification.\n- General ratio direction, leverage up, asset turnover down, current ratio down, interest coverage down (unverified but logically consistent).\n\n## Session 18\n\n- Tweedie's quip about flying on an aircraft that's on the balance sheet captures exactly what IFRS16 fixed for airlines.\n- Airlines were the second most IFRS16-impacted industry (47% median debt increase, 33% EBITDA increase), because of heavy off balance sheet aircraft leasing.\n- Cathay Pacific 2019, ROU/PP&E and lease liabilities both rose about HKD 19.9-20bn, gearing rose 36.5%, EBITDA rose 31.1%, EPS fell 1.6%, net profit worsened by HKD 86m (depreciation + finance charges slightly exceeded eliminated rent).\n- Total cash flow was unchanged, only the classification across operating/financing shifted.\n- Residual value risk shifted from lessor-only (under old operating leases) to partly lessee-exposed (via ROU asset impairment risk under IFRS16), even without any change to the actual contract.\n- Possible lessee responses, renegotiate leases, shift to variable non-index payments, reconsider lease vs buy.\n- Exam trap, IFRS16 adoption does not always hurt profit, the direction depends on each year's mix of new vs maturing leases and can reverse later in a lease's life.\n\n## Session 19\n\n- Tax expense = current tax + deferred tax.\n- Permanent differences never reverse, no deferred tax (fines, tax exempt interest). Temporary differences do reverse, they create deferred tax.\n- Deferred tax asset, paying more tax now than accounting profit implies (will pay less later). Deferred tax liability, paying less tax now (will pay more later).\n- Balance sheet approach, temporary difference = carrying amount minus tax base. Asset with carrying > tax base, or liability with carrying < tax base, both give a liability. The opposite pairing gives an asset.\n- Common temporary difference sources, depreciation rate gaps, bad debt/warranty timing, pension timing, unrealised vs realised investment income.\n- Deferred tax is always reported undiscounted and always as non-current, regardless of when it's expected to reverse.\n\n## Session 20\n\n- Worked examples confirm, total tax paid always converges to the same amount regardless of accounting vs tax timing, only the timing of payment differs.\n- Valuation allowance, a contra account reducing a deferred tax ASSET (never a liability) when future taxable profit is no longer probable, flows through P&L as a loss to establish, a gain to reverse.\n- Deferred taxes matter more where accounting and tax rules diverge (UK) than where they're closely aligned (Germany, France).\n- For a growing firm, capex driven deferred tax liabilities can keep rolling forward rather than reversing, described as similar to an interest free loan from the government.\n- Academic evidence on the book-tax gap is two sided, associated with lower earnings quality in some studies, but forcing conformity (narrowing the gap) has also been shown to reduce earnings informativeness.\n\n## Session 21\n\n- Sale and leaseback, seller-lessee sells then immediately leases back the same asset. Whole treatment hinges on whether the transfer is a sale under IFRS15 (control transfer).\n- If a sale, ROU asset = previous carrying amount x (PV of leaseback / fair value). Gain recognised = (fair value - carrying amount) x (1 - that same ratio).\n- If not a sale, both sides treat the cash as a loan under IFRS9.\n- Tax rate change adjustment = beginning cumulative timing difference x (old rate - new rate), a one time catch up, never spread forward.\n- DTA and DTL always move in the SAME direction as the tax rate, both rise when the rate rises, both fall when it falls.\n- Self check, the new DTA/DTL balance after a rate change must equal the cumulative timing difference revalued at the new rate.\n\n## Session 22\n\n- Core principle, recognise revenue when control transfers to the customer, not when cash is received. Amount = transaction price.\n- Five steps, identify the contract (5 conditions), identify distinct performance obligations, determine the transaction price, allocate it by stand-alone selling price, recognise as obligations are satisfied.\n- Distinct = customer can benefit on its own AND separately identifiable in the contract. Highly integrated bundles (CRM+consulting, hospital design-build) are ONE obligation.\n- Variable consideration, expected value method for a range of outcomes, most likely amount method for an essentially binary outcome.\n- Point in time vs over time recognition, over time uses output (units, milestones) or input (costs incurred) progress methods.\n- Contract asset (performance done, payment still conditional beyond timing) vs receivable (unconditional except for timing) vs contract liability (paid before performance).\n\n## Session 23\n\n- Loyalty/miles programmes granting a material right are their own performance obligation, allocate part of the transaction price, defer it until redemption or expiry.\n- Right of return, transaction price = expected consideration net of expected returns, PLUS a refund liability and a right-to-recover-goods asset, not instead of the reduced revenue.\n- Non-refundable up-front fees not tied to a distinct service are deferred, recognised over the expected customer relationship period, not just the stated contract term.\n- Contract acquisition/set-up costs meeting the capitalisation criteria are amortised over the same period as the revenue they relate to.\n- Progress on an over time obligation can be measured by output (assessed % complete) or input (cost to cost), and the two need not agree, use whichever faithfully depicts progress. This can even produce a reported loss in a period despite an ultimately profitable contract.\n\n## Session 24\n\n- Full retrospective, restates ALL prior comparative periods shown. Modified retrospective, no restatement, one cumulative catch up to opening retained earnings in the adoption year.\n- General Dynamics (full retrospective, -$684m), business jet contracts moved from two milestone recognition to single point-in-time recognition at delivery, deferring previously recognised profit.\n- Ford (modified retrospective, +$36m), certain previously deferred vehicle sales moved to recognition at shipment, accelerating previously deferred revenue.\n- The sign of the adjustment says nothing about earnings quality, it just reflects whether revenue was deferred (negative) or accelerated (positive) by the new rules.\n- Comparing companies with different transition methods around the adoption year risks mixing a restated and a non-restated historical basis.\n\n## Session 25\n\n- IFRS2 covers share based payment for goods/services only, not dividends or a general cash share issue.\n- Equity-settled, measure goods/services fair value (or equity fair value if unreliable), never remeasured later for market moves. Cash-settled, a liability, remeasured to fair value every period until settlement.\n- No vesting condition, full expense at grant date. Vesting condition present, expense spread over the vesting period.\n- Cost is always fixed at grant date fair value, subsequent share price moves are irrelevant to the P&L charge.\n- Forfeiture (service/non-market condition failure), revise cumulative expense to the revised number expected to vest. Market condition failure, no change at all. Expiry after vesting, pure equity reclassification, zero P&L effect.\n- In the exercise journal entry, share premium is always the balancing plug figure.\n\n## Session 26\n\n- eBay 2000, $48.3m profit as reported (APB25 intrinsic value) versus a $90.7m pro forma LOSS under SFAS123 fair value, same company, same year.\n- APB25, expense = stock fair value minus exercise price at grant date, zero for at-the-money grants (most of eBay's options).\n- SFAS123/IFRS2 style fair value captures full option value including time value via Black-Scholes, not just the immediate spread.\n- The 103.79 vs 62.69 gap (fair value vs exercise price) is time value, driven by eBay's 115% expected volatility, not a pricing error.\n- IFRS2 requires mandatory recognition of the SFAS123-style fair value, closing exactly the gap this case illustrates.\n- The pro forma loss does not mean eBay's business was failing, it's an accounting reclassification of compensation cost, not a cash economics statement.\n\n## Session 27\n\n- Four benefit categories, short term (undiscounted, as earned), post-employment (this session), other long-term (similar mechanics but ALL remeasurement to P&L, no OCI split), termination.\n- Defined contribution, risk on employee, simple expense-as-due accounting. Defined benefit, risk on employer, full actuarial/discounting model via the projected unit credit method.\n- P&L = service cost + net interest (discount rate x opening net position). OCI (never recycled) = all remeasurements.\n- Same discount rate used for the obligation AND for plan assets' interest income.\n- Past service cost (plan amendments) is recognised immediately, not spread over future service, unlike ordinary service cost.\n- Employer contributions and benefits paid are pure balance sheet movements, never P&L items.\n\n## Session 28\n\n- Five standards, IFRS10 (consolidation), IAS27 (parent's separate FS), IAS28 (equity method), IFRS11 (joint arrangements), IFRS12 (disclosure).\n- Control = power + exposure to variable returns + ability to use power to affect returns, all three required together.\n- Protective rights and non-substantive rights never confer power, however extensive they look.\n- Consolidation mechanics, eliminate the investment against the subsidiary's pre-acquisition equity, recognise NCI for the minority share.\n- Fair value of net assets = book equity + step-ups - step-downs, both net of deferred tax (step-up gives a DTL, step-down gives a DTA).\n- Partial goodwill, NCI at proportionate share of net assets, smaller goodwill. Full goodwill, NCI at its own fair value, larger goodwill (includes NCI's own implied share).\n- Negative goodwill (bargain purchase) goes straight to income, the opposite of ordinary goodwill.\n\n## Session 29\n\n- Intra-group balances (loans, receivables, payables) are fully cancelled on consolidation.\n- Unrealised profit is eliminated in full. Downstream (parent to sub) hits group retained earnings only. Upstream (sub to parent) splits proportionately between group retained earnings and NCI.\n- Step-up/step-down adjustments continue post-acquisition, depreciate/amortise over remaining useful life with a partial deferred tax reversal each period.\n- Inventory already written down for unrelated reasons absorbs some/all of the intra-group profit automatically, only eliminate what remains.\n- Fixed asset intra-group sale needs three adjustments together, eliminate the gain, correct depreciation to the original cost basis, restate carrying amount to group-level NBV.\n- Intra-group dividends, eliminate the parent's dividend income against the subsidiary's distribution, only dividends actually paid to NCI reduce NCI's equity.\n- Golden rule, consolidate everything at 100% first, then carve out NCI's share of net income only at the end, using only adjustments that originated with that subsidiary.\n\n## Session 30\n\n- A business = inputs + processes capable of producing outputs, even without outputs yet existing (a research facility with no sales can still qualify).\n- IFRS3 excludes joint arrangements, common control combinations, and JV formation.\n- Four steps, identify the acquirer, determine the acquisition date, measure net assets/NCI/consideration at fair value, recognise goodwill or a bargain purchase.\n- In a reverse acquisition, the accounting acquirer can differ from the legal acquirer, look at who actually ends up controlling the combined entity.\n- Acquisition-related costs (legal, consulting, valuation) are always expensed, never capitalised into goodwill, except debt/equity issuance costs (IFRS9's own rules).\n- Acquisition date = when control actually passes, not necessarily the legal transfer date.\n- Previously unrecognised intangibles (customer relationships etc) can now be recognised at fair value, overriding the acquiree's own historical IAS38 restrictions.\n- Goodwill = consideration + NCI + FV of any previously held interest - net FV of identifiable assets. Step acquisitions remeasure the prior stake to fair value through P&L when control is obtained.\n\n## Session 31\n\n- Lyradon controls Velquanta via 65% equity (variable returns) plus a 4-of-6 board majority with simple majority voting (power and the ability to use it).\n- Alpine's veto rights (dividends, buybacks, capital reduction, financing over EUR 50m) are protective, not substantive, they don't reach ordinary operating/strategic decisions.\n- What would flip this, if Alpine's consent rights reached ordinary budgets/R&D/commercial decisions, or if the financing threshold were low enough to capture routine financing.\n- Acquisition date = 1 July 2024, the completion date, not the 3 June signing date.\n- Fair value of net assets = 13,000 book equity + 17,000 net fair value adjustments (PPE, developed tech, customer relationships, IPR&D, minus a contingent liability) = 30,000 (EUR'000).\n- Goodwill (partial method, cash only) = 48,000 - 65%x30,000 = 28,500, this is a floor, the earn-out's fair value still needs to be added.\n- Previously unrecognised intangibles get recognised now under the fair value threshold, even though Velquanta itself never capitalised them.\n- Transaction costs (EUR 1.2m) are expensed, explicitly kept out of consideration transferred and goodwill.\n","fm":"## Session 1\n\n- Value creation means holding three equilibria together: income statement profitable, balance sheet solvent, cash flow statement cash generative. Toys \"R\" Us failed despite paper profitability.\n- The business plan simulates the company's trajectory; the financial plan tests whether that model is actually sustainable and aligns financial goals with business strategy.\n- Under rising uncertainty (WUI trending up since 1990), use McKinsey's six practices: explicit probabilities, a momentum case, an explicit bear case, consistent macro assumptions, disaggregated inflation, weekly back-testing.\n- Three planning tools differ by horizon and frequency: cash budget is short term and monthly/weekly, financial budget is medium term and annual/quarterly, financial plan is medium-long term (3, 5, 7 years) and annual.\n- Cash budget purpose: forecast periodic cash balances to plan funding needs or surplus deployment. Three-step build: sources, uses, then shortage/surplus.\n- Cost/revenue differs from cash inflow/outflow for three reasons: timing mismatch, non-monetary events like depreciation, events entirely outside the income statement like loan repayments.\n- Cash identity: Cash(EOP) = Cash(BOP) + (Sources − Uses) + Financial income/charges. BOP of month t equals EOP of month t-1.\n- Largest source of cash is normally customer collections, not financing activity, don't default to \"raise debt\" first.\n- In the Clank case, expansion capex (CRM platform) is a large cash outflow with a much smaller depreciation footprint. Know the mechanics, not a specific numeric answer, since input tables are missing from the extraction.\n\n## Session 2\n\n- Root cause behind all six working-capital mistakes: badly designed performance metrics and incentives, not bad luck. Ask \"what is this person's bonus tied to\" on any case question.\n- Mistake 1, managing to the income statement: balance sheet costs like inventory never show up there, so managers have no incentive to avoid locking up cash.\n- Mistake 2, rewarding sales on volume alone inflates both receivables and inventory. The metals refining case cut receivables from 185 to 45 days just by adding a courtesy reminder call.\n- Mistake 3, quality-only production bonuses build WIP inventory customers won't pay for. Refocusing on WIP reduction (not defending the price premium) freed €20 million at a European drive-systems producer.\n- Mistake 4, receivables and payables are separate relationships governed by different bargaining power, never mechanically mirror a supplier term change onto customers.\n- Mistake 5, current ratio and quick ratio: a \"better\" ratio is usually achieved by carrying more receivables/inventory and fewer payables, exactly the wrong direction. A French firm went insolvent six months after proudly reporting improved ratios.\n- Mistake 6, benchmarking only within your industry breeds complacency. Dell was best in class among computer makers but still had huge room to improve once benchmarked against retailers.\n- Building a culture of value beats managing by numbers alone. Toyota's JIT culture rewards constant process experimentation, not blind metric chasing.\n\n## Session 3\n\n- Cash cycle = DI + DSO − DPO = operating cycle (DI+DSO) minus the payable period.\n- DSO = AR ÷ (Sales ÷ 365). DPO = AP ÷ (COGS ÷ 365). DI = Inventory ÷ (COGS ÷ 365). DSO uses sales, DI and DPO both use COGS, a common calculation trap.\n- Worked numbers to remember the pattern: Sales 6,133, COGS 5,464, Inventory 879, AR 764, AP 682 gives DSO 45, DPO 46, DI 59, Cash Cycle 58 days.\n- Walmart (fast-turnover retailer) has a near-zero cash cycle; Boeing (long manufacturing cycle) has one near 179 days, the contrast illustrates the formula.\n- Inventory trade-off: carrying cost rises with order size, order cost falls with order size, optimal order size balances the two. Reorder point triggers replenishment at a minimum threshold.\n- Inventory does not scale proportionally with sales, it rises less than proportionately, an economy of scale. JIT only works with steady, predictable production flow.\n- Four receivables management questions: terms of sale, credit analysis, the credit decision, collection policy.\n- Credit decision rule: E[gain|grant] = p×PV(Revenue−Cost) − (1−p)×PV(Cost), grant only if this beats $0. Goal is maximizing present value, not minimizing bad debts.\n- Concentrate credit-analysis effort on large or doubtful accounts, not spread evenly. An aging schedule tracks overdue receivables.\n\n## Session 4-5\n\n- Three FX exposure types: transaction (already-contracted cash flows), operating/economic (future competitiveness), translation (consolidation accounting only, no cash flow impact).\n- Hedging reduces variability of cash flows around the mean, it does not necessarily raise expected cash flow.\n- Payable: go long forward (agree to buy FX at maturity). Receivable: go short forward (agree to sell FX at maturity).\n- Importer/exporter options rule: importers who owe FX buy calls, exporters who receive FX buy puts, easy to get backwards.\n- For quotes in home currency per unit of foreign currency and an option strike equal to the forward rate, an unexercised receivable put matches the forward at spot = forward + settlement value of premium per foreign currency unit. An unexercised payable call matches at spot = forward minus that premium. Invert foreign currency per home currency quotes first and check that the option is unexercised at the candidate break even.\n- Option premium is paid regardless of outcome, always net it against the payoff, never treat it as a cost only when exercised.\n- Over-hedging: hedging more currency than actually materializes turns the hedge into a speculative position on the unrealized gap, forcing the firm to buy the missing amount on the spot market to deliver against the forward.\n- Two hedging-policy questions every case raises: when to start hedging (budget stage vs invoicing/certain exposure), how much to hedge (100% vs a smaller conservative share).\n- Forward hedge does not improve the expected outcome, it removes variance, meaning you may give up upside as the price of removing downside. Options sit between the forward and doing nothing.\n- Direct quotation (European investor) = home currency per unit of foreign currency, indirect is the reciprocal. Forward premium formula fN,j = [FN($/j) − S($/j)] ÷ S($/j) × (360÷N), positive describes a forward premium in that quote convention, not a guarantee of future appreciation.\n","cg":"## Session 1\n\n- Four CG definitions differ on whose interests are centred, Shleifer & Vishny (investor returns only), Sheridan & Kendall (owners plus stakeholders plus compliance), Cadbury (board-centred), Blair (whole institutional system).\n- Public company (PC), ownership so fragmented no shareholder bothers to actively govern, shareholders \"vote with their feet\" (sell) instead of contesting board seats.\n- Agency relationship, principal delegates to agent, both utility maximisers, so safeguards are costly. Agency costs = monitoring + bonding + residual losses.\n- Three ownership/board configurations, dispersed+independent board, dispersed+management-dominated board, concentrated+overlapping (adds a majority vs minority shareholder conflict on top of the classic one).\n- Six misbehaviours, empire building (excess risk for personal power) vs shirking (its opposite, risk aversion), wealth extraction, entrenchment, short-termism, favouritism/insider trading.\n- Five historical failures, Enron 2001, Parmalat 2003, WorldCom 2002, Satyam 2009, Theranos 2015, common ingredients are weak boards, conflicts of interest, weak transparency, concentrated power.\n- Three response families, efficient markets, structures/rules/mechanisms, privileged ownership structures, concretised as market for corporate control, blockholders, incentives, fiduciary duties, financial debt.\n- LLSV, weak legal protection means ownership concentration substitutes for the law, strong protection means dispersed ownership becomes viable.\n\n## Session 2\n\n- Shareholder view core claim, maximize shareholder value, shareholders as residual claimants, managers as agents, stakeholders only instrumental.\n- Extended assumptions are conditions the argument depends on (efficient markets, discipline via stock price, stock incentives, market for corporate control), not proven facts.\n- Residual income rights (claim on leftover profit) vs residual control rights (right to decide when contracts are silent), both go to shareholders because they're exposed when contracts are incomplete.\n- Property conception (nexus of contracts, managers as agents) vs social entity conception (social institution, managers as trustees), example ExxonMobil vs Unilever.\n- Four stakeholder power types, voting, political/regulatory, environmental/social, economic.\n- Four definitions of what CG is for, shareholder, stakeholder, managerial, firm.\n- 2019 Business Roundtable, 181 CEOs voluntary statement toward stakeholder capitalism, echoed by Larry Fink, not a legal change.\n\n## Session 3\n\n- Enron shifted from energy production to energy trading, a \"trading house\" built on financial engineering.\n- Mark-to-market let Enron book a 20-year contract's whole estimated future profit immediately, the technique itself isn't fraud, the application was.\n- SPEs hid debt off Enron's own balance sheet while keeping only the profits visible, banks failed to check due to fee conflicts, reputational blindness, and opacity.\n- Enron failures, aggressive accounting, hidden debt via SPEs, board/Arthur Andersen failure to challenge, toxic risk culture, regulatory gaps.\n- Theranos promised blood tests from a finger-prick, hit $9bn valuation, collapsed 2015, fraud was scientific/technical, not accounting, pre-IPO so no public shareholders.\n- Theranos board was loyal to Holmes but lacked biotech expertise, that's the precise failure, not just \"didn't ask questions\".\n- Shared lesson across both, boards failed to challenge a dominant management narrative, different mechanisms, same governance root cause.\n\n## Session 4-7\n\n- Three board roles, strategic, monitor, networking. Ideal size 7 to 15.\n- CEO duality (one person as CEO and Chairman) risks power concentration, common in the US, the Lead Independent Director exists to counterbalance it.\n- Effectiveness framework, input (structure) plus processes (working style) plus board roles, and crucially, Enron/Theranos/WorldCom all had independent-majority boards yet still failed, independence alone is not enough.\n- Board evaluation, Italian evidence, 84% did a review but only 24% reported real improvement, advisor-backed reviews perform much better (35.6% vs 4.1% on one metric).\n- Hard law (Civil Code) vs soft law (Corporate Governance Codes, comply-or-explain, not legally binding).\n- Independence compromised by, being a significant shareholder, executive role in last 3 years, significant relations/remuneration in last 3 years, more than 9 years of tenure (within 12), cross-directorships, auditor ties, family ties to controllers.\n- Board vs TMT, board oversees and approves, TMT (led by CEO) develops strategy/business plans for board approval.\n- Main committees, Appointments, Remuneration, Audit & Risk, optional Sustainability.\n- Italian gender quotas tightened over time (2011 Golfo-Mosca, 2020 Budget Law to 40%), yet the director pay gap still widened 2012-2017.\n\n## Session 9\n\n- Three capitalism models, Anglo-Saxon (market/outsider, dispersed), German/Japanese (network/insider, banks central), Latin (State plus family, pyramidal groups).\n- Control-Enhancing Mechanisms, dual-class shares, shareholders' agreements, pyramidal groups, all create a gap between voting power and cash-flow rights. Worked example, 51% times 51% equals 26% cash-flow rights but still 51% voting control.\n- Ownership, governance and strategy move together, driven by past performance (only extreme results trigger change), owner values, competition, institutional context.\n- Cash-rich controlling shareholders invest long-term and accept lower dividends, debt-constrained ones need high dividends and avoid risk, know this contrast cold.\n- Activism drivers, underperformance, weak managerial ownership, pay-performance misalignment, institutional ownership. Aberdeen equals broad portfolio stewardship, Elliott/TIM equals a targeted single-company campaign, don't mix the two models up.\n- MSCI ESG rating, AAA to CCC across E, S, G indicators. Seven ESG strategies, exclusions, engagement/voting, integration, norms-based screening, best in class, thematic, impact investing, each is a distinct mechanism.\n- Italy's NFD (mandatory since 2017, Legislative Decree 254/2016) is transitioning to the CSRD, not the final regime, and most firms disclose ESG risk without truly integrating it into risk management (96% disclose, only 13% integrate).\n"},"PARTIELS":{"exams":[{"id":"fm-p1","course":"fm","code":"FM","name":"Financial Management and Financial Markets","label":"Partial Exam I","date":"2026-10-20T09:00","dateLabel":"mardi 20 octobre 2026 · 9h00","kind":"exam","format":"4 QCM à 3 options + 2 questions ouvertes · 45 min · closed book · calculatrice scientifique","scope":"Sessions 1 à 11 · exclusions : money market hedge, currency swaps (pp.109-117), DCF valuation, guest lectures","items":["fm-p1-b3","fm-p1-official","fm-p1-b2","fm-p1-b1","fm-p1-mk"]},{"id":"cr-p1","course":"cr","code":"CR","name":"Corporate Reporting","label":"Partial Exam I","date":"2026-10-27T09:00","dateLabel":"mardi 27 octobre 2026 · 9h00","kind":"exam","format":"15 à 20 QCM · 45 min","scope":"Sessions 1 à 15","items":["cr-p1-mk","cr-p1-b2","cr-p1-b1"]},{"id":"da-mock","course":"da","code":"DA","name":"Data Analysis","label":"Mock final exam","date":"2026-10-30T18:15","dateLabel":"vendredi 30 octobre 2026 · 18h15","kind":"exercise","format":"Séance d'exercices en classe · activité de cours, pas un examen officiel","scope":"","items":[]}],"items":{"fm-p1-b3":{"id":"fm-p1-b3","exam":"fm-p1","type":"blanc","title":"Mock FM #3 · hors moule","duration":45,"revision":1,"intro":"Mock original au format officiel, volontairement décalé du mock Blackboard pour couvrir ce qu'aucun mock précédent ne teste. 4 QCM à 3 options sur le cash budget, la décision de crédit, le QSD et la structure optimale, puis un WACC avec recapitalisation et une couverture côté importateur. Chaque mauvaise option correspond à une erreur précise, expliquée dans le corrigé. Énoncés en anglais comme à l'examen. Prévois 12 minutes pour les QCM, 17 pour le WACC, 13 pour le change et 3 pour relire.","mcq":[{"session":"Session 1 · Cash budget","q":"A distributor sold EUR 400 thousand in February and EUR 500 thousand in March. Customers pay 40% in the month of sale and 60% the following month. In March the company pays suppliers EUR 320 thousand and wages EUR 90 thousand, repays EUR 60 thousand of bank loan principal and records EUR 25 thousand of depreciation. Cash on 1 March is EUR 50 thousand and the company must hold at least EUR 40 thousand at month end. How much short term financing does March require?","choices":["EUR 45 thousand.","EUR 20 thousand.","None, March ends with EUR 80 thousand of cash."],"correct":1,"expl":"Collections = 40% × 500 + 60% × 400 = 200 + 240 = 440. Cash outflows = 320 + 90 + 60 = 470. Depreciation is not a cash flow, the principal repayment is a cash flow even though it never hits the income statement. Ending cash before financing = 50 + 440 − 470 = 20, below the 40 minimum, so the company borrows 40 − 20 = EUR 20 thousand. Option A deducts depreciation as if it were cash (ending −5, borrowing 45). Option C either ignores the principal repayment or uses March sales instead of March collections, which both give 80."},{"session":"Session 3 · Credit decision","q":"A new customer orders goods that cost EUR 1,000 to produce today. If credit is granted, the customer is invoiced EUR 1,200 payable in three months. The relevant discount rate is 2% for the three month period. If the customer defaults, nothing is recovered. Credit is refused if the expected gain is not positive. What is the minimum probability of payment that justifies granting credit?","choices":["15.0%.","83.3%.","85.0%."],"correct":2,"expl":"E[gain | grant] = p × PV(Revenue − Cost) − (1 − p) × PV(Cost). PV(Revenue) = 1,200 / 1.02 = 1,176.47, and the cost is incurred today, so PV(Revenue − Cost) = 176.47 and PV(Cost) = 1,000. Setting the expected gain to zero gives p × 176.47 = (1 − p) × 1,000, so p = 1,000 / 1,176.47 = 85.0%. Option B forgets to discount the revenue (1,000 / 1,200 = 83.3%), which understates the hurdle. Option A is the maximum acceptable default probability, not the payment probability."},{"session":"Session 6 · Quality spread differential","q":"Firm A (rated AA) can borrow fixed at 4.0% or floating at Euribor + 0.2%. Firm B (rated BBB) can borrow fixed at 5.5% or floating at Euribor + 0.9%. A wants floating rate debt and B wants fixed rate debt. Which statement is correct?","choices":["The QSD is 0.8%. A should borrow fixed and B floating, then swap.","The QSD is 0.8%. B should borrow fixed and A floating, then swap.","The QSD is 2.2%. A should borrow fixed and B floating, then swap."],"correct":0,"expl":"Fixed rate differential = 5.5% − 4.0% = 1.5%. Floating differential = (Euribor + 0.9%) − (Euribor + 0.2%) = 0.7%. QSD = 1.5% − 0.7% = 0.8%, positive, so a swap can create value. A has an absolute advantage in both markets but its comparative advantage is largest in the fixed market (1.5% versus 0.7%), so A borrows fixed, B borrows floating, and the swap converts each into its desired exposure. Option B puts each firm in the market where it is comparatively weaker, which destroys the gain. Option C adds the differentials instead of subtracting them."},{"session":"Session 8 · Optimal capital structure","q":"A company estimates its costs of capital at four leverage levels, with D/(D+E) of 0%, 20%, 40% and 60%. The pretax cost of debt is respectively not applicable, 4.0%, 5.0% and 7.0%. The cost of equity is respectively 9.0%, 9.8%, 11.2% and 14.5%. The tax rate is 25%. Which leverage level maximizes enterprise value?","choices":["20% debt, with a WACC of 8.64%.","60% debt, with a WACC of 8.95%.","40% debt, with a WACC of 8.22%."],"correct":2,"expl":"Enterprise value is maximized where the WACC is minimized. WACC = E/V × ke + D/V × kd × (1 − t). At 0%, 9.00%. At 20%, 0.8 × 9.8% + 0.2 × 4.0% × 0.75 = 7.84% + 0.60% = 8.44%. At 40%, 0.6 × 11.2% + 0.4 × 5.0% × 0.75 = 6.72% + 1.50% = 8.22%. At 60%, 0.4 × 14.5% + 0.6 × 7.0% × 0.75 = 5.80% + 3.15% = 8.95%. The U shaped curve bottoms at 40%. Option A forgets the tax shield (pretax WACC 8.64% at 20%, which is then the pretax minimum). Option B assumes more cheap debt always lowers the WACC and ignores the rising ke and kd."}],"open":[{"title":"Open question 1 · WACC and a debt financed recapitalization","body":"Ortensia S.p.A. is an unlisted Italian group with two businesses. Specialty chemicals represents 70% of enterprise value and its listed peers have an average levered beta of 1.25 and an average market D/E of 50%. Industrial distribution represents 30% of enterprise value and its peers have an average levered beta of 0.80 and an average market D/E of 25%.\n\nAdditional information on Ortensia (EUR million)\n- Last year EBIT 120, interest expense 20.\n- Financial debt is a single bond with face value 500, annual coupon 4% (20 per year) and 4 years of residual maturity. Use the gross market value of this bond as D. Ignore cash.\n- A recent transaction between independent parties implies a market value of equity of 1,200.\n- Tax rate 25% for Ortensia and peers. Risk free rate 3.5%. Equity risk premium 5.5%. Assume a zero debt beta and βL = βU × [1 + (1 − t) × D/E].\n\nSynthetic rating table, spread over the risk free rate\n- Coverage above 6.0, AA, 1.00%\n- Coverage above 4.5 up to 6.0, A, 1.50%\n- Coverage above 3.0 up to 4.5, BBB, 2.25%\n- Coverage above 2.0 up to 3.0, BB, 3.50%\n- Coverage of 2.0 or less, B, 5.00%\n\na) Estimate Ortensia's unlevered (asset) beta with the bottom up approach.\nb) Estimate the pretax and after tax cost of debt with the synthetic rating, and the market value of the bond.\nc) Estimate the levered beta, the cost of equity and the WACC.\nd) The board proposes to borrow an additional 300 at par and use it to buy back shares at market value. EBIT is unchanged. After the transaction, assume all debt costs the new pretax rate implied by the new rating, interest expense for the rating test is 20 + 300 × the new pretax rate, D becomes the current bond market value plus 300 and E becomes 1,200 − 300. Find the new rating (check that it is consistent), then recompute βL, ke and the WACC. Does the recapitalization create value? Explain in two or three sentences.","solution":"a) Unlever each peer group. Chemicals βU = 1.25 / (1 + 0.75 × 0.50) = 1.25 / 1.375 = **0.9091**. Distribution βU = 0.80 / (1 + 0.75 × 0.25) = 0.80 / 1.1875 = **0.6737**. Weight by Ortensia's EV mix. βU = 0.70 × 0.9091 + 0.30 × 0.6737 = 0.6364 + 0.2021 = **0.8385**.\n\nb) ICR = 120 / 20 = **6.0**. The AA band requires coverage above 6.0, so exactly 6.0 falls in the A band, spread **1.50%**. This boundary is the trap of the question. Pretax kd = 3.5% + 1.5% = **5.00%**. After tax kd = 5.00% × 0.75 = **3.75%**. The bond is priced at the current pretax kd. Discount factor 1 / 1.05^4 = 0.822702. Annuity factor (1 − 0.822702) / 0.05 = 3.545951. MVD = 20 × 3.545951 + 500 × 0.822702 = 70.92 + 411.35 = **EUR 482.27 million**, below face value because the 4% coupon is below the 5% market rate.\n\nc) D/E = 482.27 / 1,200 = 0.4019. βL = 0.8385 × (1 + 0.75 × 0.4019) = 0.8385 × 1.3014 = **1.0912**. ke = 3.5% + 1.0912 × 5.5% = **9.50%**. V = 1,200 + 482.27 = 1,682.27, so E/V = 71.33% and D/V = 28.67%. WACC = 71.33% × 9.50% + 28.67% × 3.75% = 6.78% + 1.08% = **7.85%**.\n\nd) The rating depends on the interest expense, which depends on the rating, so test the candidates. If A (5.00%), interest = 20 + 15 = 35 and ICR = 3.43, which is not an A coverage, so A is inconsistent. If BBB (5.75%), interest = 20 + 300 × 5.75% = 37.25 and ICR = 120 / 37.25 = **3.22**, inside the BBB band, consistent. New pretax kd = **5.75%**, after tax **4.3125%**. New D = 482.27 + 300 = 782.27, new E = 900, D/E = **0.8692**. βL = 0.8385 × (1 + 0.75 × 0.8692) = 0.8385 × 1.6519 = **1.3851**. ke = 3.5% + 1.3851 × 5.5% = **11.12%**. V = 1,682.27 (unchanged by construction), E/V = 53.50%, D/V = 46.50%. WACC = 53.50% × 11.12% + 46.50% × 4.3125% = 5.95% + 2.01% = **7.95%**.\n\nThe WACC rises from 7.85% to 7.95%, so at constant operating cash flows enterprise value falls and the recapitalization destroys value. The extra tax shield is more than offset by the downgrade, which raises kd by 0.75 points on all the debt, and by the jump in ke from the higher financial risk. Ortensia is already past the bottom of its U shaped WACC curve. A frequent mistake is to keep the old 5% kd after the transaction, which gives a misleading WACC of 7.69% and the opposite conclusion."},{"title":"Open question 2 · Hedging a dollar payable","body":"A European manufacturer imports components from the United States and pays its supplier in US dollars. T0 is the budgeting date, T1 the invoicing date and T2 the payment date. T1 is three months after T0 and T2 is three months after T1. At T1 the treasurer can do nothing, buy dollars forward for 100% of the exposure, or buy a call option on dollars for 100% of the exposure. All quotes are USD per EUR.\n\n- Invoiced payable at T1, USD 5 million\n- Budget exchange rate at T0, 1.10\n- Spot rate at T1, 1.08\n- Three month forward rate at T1, 1.075\n- Call strike equal to the T1 spot, 1.08 (right to buy each dollar for 1/1.08 euros)\n- Call premium, 3% of the USD exposure, paid at T1\n- Cost of capital, 6% per year\n\na) Compute the euro cost paid at T2 under each strategy if the T2 spot is 1.00 or 1.20. State whether the call is exercised.\nb) Compute the maximum euro cost per dollar guaranteed by the call, net of premium.\nc) Compute the break even spot rate between the call and the forward. Verify the exercise region.\nd) The treasurer also considers hedging 50% forward and leaving 50% open. Compute its euro cost at both spots and explain when such a partial hedge makes sense.","solution":"a) Do nothing costs Q / S2. At 1.00 it costs 5 / 1.00 = **EUR 5.0000 million**. At 1.20 it costs 5 / 1.20 = **EUR 4.1667 million**.\n\nForward costs Q / F = 5 / 1.075 = **EUR 4.6512 million** in both scenarios.\n\nCall premium = 3% × USD 5 million = USD 0.15 million, converted at the T1 spot, 0.15 / 1.08 = EUR 0.1389 million, carried three months at the cost of capital, 0.1389 × (1 + 6% × 3/12) = 0.1389 × 1.015 = **EUR 0.1410 million**. The call is exercised when S2 is below the strike, because the market then charges more euros per dollar than 1/1.08. Call cost = Q / max(S2, K) + carried premium.\nAt 1.00 the call is exercised. 5 / 1.08 + 0.1410 = 4.6296 + 0.1410 = **EUR 4.7706 million**.\nAt 1.20 the call is not exercised. 5 / 1.20 + 0.1410 = 4.1667 + 0.1410 = **EUR 4.3076 million**.\nEx post, at 1.00 the forward is cheapest, at 1.20 doing nothing is cheapest, and the call is in between in both cases.\n\nb) Ceiling = 1/K + (premium % / S1) × (1 + r × t) = 0.925926 + 0.027778 × 1.015 = **EUR 0.9541 per USD**, i.e. EUR 4.7706 million in total. For an importer the premium is added to the cost, never deducted.\n\nc) When exercised, the call costs 4.7706, always above the forward's 4.6512, so equality can only happen in the non exercise region. 5 / S* + 0.1410 = 4.6512, so 5 / S* = 4.5102 and **S* = 1.1086 USD per EUR**. This is above the 1.08 strike, so the call is indeed unexercised there. Above 1.1086 (a dollar weaker by about 2.6% versus the T1 spot) the call beats the forward. Below it the forward is cheaper.\n\nd) 50% forward plus 50% open costs 2.5 / 1.075 + 2.5 / S2. At 1.00, 2.3256 + 2.5000 = **EUR 4.8256 million**. At 1.20, 2.3256 + 2.0833 = **EUR 4.4089 million**. The partial hedge halves the exposure without paying a premium. It fits a treasurer with a moderate view that the dollar may weaken, or a policy that hedges a fixed share of exposures. The budget cost is 5 / 1.10 = EUR 4.5455 million. The forward exceeds it by EUR 0.1057 million in both scenarios, because the dollar had already strengthened between T0 (1.10) and T1 (forward 1.075). At 1.00 every strategy costs more than budget. At 1.20 doing nothing, the call and the partial hedge all come in below budget."}]},"cr-p1-b2":{"id":"cr-p1-b2","exam":"cr-p1","type":"blanc","title":"Partiel blanc CR #2","duration":45,"revision":3,"intro":"Deuxième mock CR réécrit dans le style des mocks de référence du cours: 18 QCM à 4 options en 45 minutes, pas de points négatifs, sessions 1 à 14. Aucune question ne reprend le partiel blanc #1. Une question par enjeu, chaque mauvaise option correspond à une erreur précise démontée dans le corrigé qui cite la norme. Prévois 2 minutes par question et 8 minutes de relecture, sans notes.","formatNote":"18 QCM à 4 options · pas de points négatifs · aucune question ouverte","materialNote":"Closed book · calculatrice · corrigé détaillé dévoilé à la fin","open":[],"mcq":[{"session":"Session 1 · EU endorsement","q":"The IASB issues a new IFRS. What gives the standard legal effect for EU listed groups' consolidated financial statements?","choices":["Endorsement by the European Commission after EFRAG advice and an ARC opinion","Approval by the IFRS Foundation Trustees after the IASB's due process review","Registration with ESMA after a positive opinion of the European Parliament","Adoption by national parliaments following publication in the Official Journal"],"correct":0,"expl":"In the EU an IFRS becomes binding law through a Commission endorsement regulation, prepared with EFRAG's technical advice and the Accounting Regulatory Committee's opinion, then published in the Official Journal. The IASB and its Trustees govern the standard's content but cannot create EU law. ESMA enforces consistent application but registers no standards. EU regulations apply directly in all member states with no national transposition."},{"session":"Session 2 · Conceptual Framework versus a standard","q":"The Conceptual Framework and a specific IFRS standard appear to conflict on a transaction. What prevails when the entity prepares its financial statements?","choices":["The Conceptual Framework, as the highest level of IFRS authority","The requirements of the specific IFRS standard","Whichever treatment gives the most relevant information","National GAAP, applied as a fallback"],"correct":1,"expl":"The Framework is not a standard and does not override any IFRS requirement. It guides the IASB when writing standards and guides preparers only when no standard applies to a transaction (the IAS 8 hierarchy). Where a specific standard exists, its requirements govern, and national GAAP has no role in an IFRS reporter."},{"session":"Session 3 · IAS 10 events after the reporting period","q":"After the reporting date but before the statements are authorised, a court settles a case against the company, confirming an obligation that existed at the reporting date. In the same period a customer goes bankrupt because of a fire that occurred after the year end. Which event is adjusting?","choices":["Only the court settlement","Only the customer's bankruptcy","Both events","Neither event"],"correct":0,"expl":"The settlement confirms an obligation that already existed at the reporting date, so the statements are adjusted (IAS 10). The bankruptcy caused by a post-year-end fire reflects a condition that arose after the reporting date, so it is non-adjusting and only disclosed if material. Choosing both ignores the cause of the bankruptcy, choosing neither wastes the settlement evidence."},{"session":"Session 3 · IAS 8 prior period error","q":"During 2027 an internal review reveals that the closing inventory reported at 31 December 2026 was overstated by €80,000 because of a counting mistake. The error is material and the tax rate is 25%. How is it corrected?","choices":["Charge €80,000 against the profit of 2027","Disclose the error in the 2027 notes only","Restate the 2026 comparatives and reduce opening 2027 retained earnings by €60,000","Restate the 2026 comparatives and reduce opening 2027 retained earnings by €80,000"],"correct":2,"expl":"A material prior-period error is corrected retrospectively by restating comparatives (IAS 8), and the equity effect is net of tax: 80,000 × (1 − 25%) = €60,000 against opening retained earnings. Charging 2027 profit is prospective treatment, notes alone never suffice for a material error, and €80,000 ignores the tax relief."},{"session":"Session 4 · IAS 7 indirect method","q":"Profit before tax is €600,000 after depreciation of €90,000 and a loss on disposal of equipment of €14,000. Trade receivables decreased by €18,000, inventories increased by €22,000 and trade payables increased by €10,000. Interest paid of €25,000 and tax paid of €80,000 are both classified as operating. What is net cash from operating activities?","choices":["€710,000","€577,000","€593,000","€605,000"],"correct":3,"expl":"Cash generated from operations: 600,000 + 90,000 + 14,000 + 18,000 − 22,000 + 10,000 = €710,000. Then deduct interest paid €25,000 and tax paid €80,000 to reach €605,000. €710,000 stops before interest and tax, €577,000 deducts the disposal loss instead of adding it back, €593,000 inverts the working-capital signs."},{"session":"Session 4 · IAS 7 classification","q":"Which of the following is classified as a financing cash flow under IAS 7?","choices":["Cash proceeds from issuing shares","Cash received from selling equipment","Interest received on a bank deposit","Cash paid to purchase a patent"],"correct":0,"expl":"Issuing shares changes the size and composition of the entity's contributed equity, which is the definition of financing activities. Selling equipment and buying a patent are investing, and interest received is reported as operating or investing under the policy election, never as financing for the party that receives it."},{"session":"Session 5 · IAS 32 settlement in own shares","q":"A company issues a note that it must settle in three years by delivering a variable number of its own shares with a value equal to €1,000,000. How is the instrument classified?","choices":["Equity, because settlement is in shares","A financial liability, because the number of shares varies","A compound instrument with two components","Neither asset nor liability until settlement occurs"],"correct":1,"expl":"Under IAS 32, an obligation to deliver a variable number of own shares worth a fixed amount uses the shares as currency, so the instrument is a financial liability. Equity classification requires a fixed amount of cash for a fixed number of shares. There is no residual discretion that could form an equity component, and the obligation exists from inception."},{"session":"Session 5 · IAS 32 convertible bond entry","q":"An entity issues €1,500,000 of 5% convertible bonds at par, repayable in three years. At issue the fair value of a similar liability without the conversion option is €1,380,000. What is the initial recognition entry?","choices":["A liability of €1,500,000 and no equity component","An equity component of €1,500,000 and no liability","A liability of €1,380,000 and an equity component of €120,000","A liability of €1,380,000 and a day-one loss of €120,000"],"correct":2,"expl":"IAS 32 measures the liability component first at the fair value of a similar non-convertible liability (€1,380,000) and assigns the residual proceeds (€120,000) to equity. The residual is never a day-one loss, booking the full proceeds as liability denies the conversion option's value, and full equity ignores the repayment obligation."},{"session":"Session 6 · IFRS 9 classification of debt instruments","q":"An entity holds bonds whose cash flows are solely payments of principal and interest. Its business model is both to collect the contractual cash flows and to sell the bonds regularly to manage liquidity. How are the bonds measured after initial recognition?","choices":["At amortised cost using the effective interest method","At fair value through profit or loss","At fair value through other comprehensive income","At cost less impairment"],"correct":2,"expl":"The cash flow test is met and the business model is hold to collect and sell, so IFRS 9 requires FVOCI with recycling of gains to profit on disposal. Amortised cost requires a pure hold-to-collect model, FVTPL is the residual when neither model applies, and cost less impairment is not an IFRS 9 category for debt."},{"session":"Session 6 · Amortized cost and the effective interest method","q":"An entity buys five-year bonds with a nominal value of €100,000 for €95,000 and pays €2,000 of transaction costs. The bonds are held to collect contractual cash flows. At what amount are they initially recognised, and which rate amortises the difference to nominal?","choices":["€95,000, using the coupon rate","€97,000, using the effective interest rate","€100,000, using the effective interest rate","€97,000, using the coupon rate"],"correct":1,"expl":"Under the amortised cost model the asset is initially recognised at fair value plus transaction costs: 95,000 + 2,000 = €97,000. The effective interest rate then accretes the €3,000 discount to nominal over the five years. The coupon rate only sets the cash received, and €100,000 wrongly starts from the nominal amount."},{"session":"Session 7 · Stage 3 interest revenue","q":"A loan has a gross carrying amount of €200,000 and is credit-impaired, with a lifetime ECL allowance of €50,000. The effective interest rate is 6%. What interest revenue is recognised for the year?","choices":["€12,000","€3,000","€9,000","€0"],"correct":2,"expl":"For a credit-impaired asset (Stage 3), interest revenue is calculated on the net carrying amount: (200,000 − 50,000) × 6% = €9,000. €12,000 applies the rate to the gross amount, which is the Stage 1 and Stage 2 basis, €3,000 applies it to the allowance, and the loan does not stop accruing interest altogether."},{"session":"Session 8 · Disposal of an FVOCI equity investment","q":"A company sells for €180,000 an equity investment that it had irrevocably elected to measure at FVOCI. The investment cost €120,000 and cumulative fair value gains of €60,000 sit in OCI. What happens on disposal?","choices":["A gain of €60,000 is recycled from OCI to profit or loss","No gain in profit or loss, the €60,000 may move within equity","A gain of €60,000 is recognised in profit or loss for the year","The €60,000 in OCI is reversed against the cost of the asset"],"correct":1,"expl":"For an elected FVOCI equity investment, IFRS 9 prohibits recycling: the cumulative gain never passes through profit or loss and may only move within equity, for example to retained earnings. Recycling to profit describes the FVOCI debt treatment, the classic confusion, and the OCI reserve is not netted against the asset's cost."},{"session":"Session 9 · IAS 16 initial cost","q":"A company buys equipment with a list price of €180,000 and receives a €10,000 trade discount. It pays delivery of €4,000, site preparation of €9,000 and annual insurance of €3,000. What is the cost of the equipment under IAS 16?","choices":["€183,000","€196,000","€193,000","€186,000"],"correct":0,"expl":"Cost is the cash price net of trade discounts plus directly attributable costs: (180,000 − 10,000) + 4,000 + 9,000 = €183,000. Insurance is a recurring operating expense. €193,000 forgets the discount, €186,000 includes the insurance, €196,000 makes both errors at once."},{"session":"Session 10 · Revaluation entry after a previous surplus","q":"A machine is carried at €300,000, and a revaluation surplus of €50,000 recognised in OCI exists for it. The machine is now revalued down to €230,000. How is the €70,000 decrease recognised?","choices":["€70,000 in profit or loss","€50,000 in other comprehensive income and €20,000 in profit or loss","€70,000 in other comprehensive income","€20,000 in other comprehensive income and €50,000 in profit or loss"],"correct":1,"expl":"IAS 16 requires a revaluation decrease to be charged in OCI to the extent of any existing surplus on the same asset (€50,000), with the excess (€20,000) expensed in profit or loss. Charging everything to profit ignores the reserve built for this asset, charging everything to OCI overuses it, and the inverted split misapplies the order."},{"session":"Session 11 · IAS 38 development costs","q":"A company capitalised development costs of €150,000. The product became available for use on 1 April. The reporting year ends 31 December and the useful life is 5 years with no residual value. What is the carrying amount at year end?","choices":["€150,000","€127,500","€120,000","€135,000"],"correct":1,"expl":"Amortisation starts when the asset is available for use, here 1 April, so nine months are charged: 150,000 / 5 × 9/12 = €22,500, leaving €127,500 (IAS 38). €150,000 forgets amortisation entirely, €120,000 charges a full year, €135,000 charges only six months as if use started in July."},{"session":"Session 12 · Allocating a CGU impairment loss","q":"A cash-generating unit has a carrying amount of €600,000: goodwill €80,000, machinery €320,000 and intangibles €200,000. Its recoverable amount is €460,000. The machinery's own fair value less costs of disposal is €290,000. What impairment loss is allocated to the machinery?","choices":["€36,923","€80,000","€23,077","€30,000"],"correct":3,"expl":"The total loss is €140,000: goodwill absorbs €80,000 first, leaving €60,000. A simple pro rata would give the machinery 320/520 × 60,000 = €36,923, but no asset may fall below its own recoverable amount, so the machinery is capped at 320,000 − 290,000 = €30,000 and the excess passes to the intangibles (IAS 36). €36,923 skips the floor, €23,077 is the intangibles' share."},{"session":"Session 13 · Goodwill impairment, Biosensors logic","q":"A group tests an acquired subsidiary for impairment. The subsidiary's carrying amount is €800,000 including goodwill of €250,000. A five-year discounted cash flow gives a value in use of €760,000, and fair value less costs of disposal is €720,000. What is recognised?","choices":["An impairment of €40,000 against goodwill in profit or loss","An impairment of €80,000 against goodwill in profit or loss","An impairment of €40,000 recognised in other comprehensive income","No impairment, because value in use is close to the carrying amount"],"correct":0,"expl":"Recoverable amount is the higher of value in use (€760,000) and fair value less costs of disposal (€720,000), so the loss is €40,000. IAS 36 allocates it to goodwill first, through profit or loss, and goodwill impairment is never reversed. €80,000 takes the lower measure, OCI is not available for goodwill, and proximity to the carrying amount does not exempt the test."},{"session":"Session 14 · Restructuring provision","q":"On 10 December the board approves a detailed plan to close a division and announces it to the employees affected. Expected costs are redundancy €300,000, retraining of continuing staff €40,000, relocation of equipment €60,000 and future operating losses of the division €100,000. The year ends 31 December. What restructuring provision is recognised?","choices":["€500,000","€300,000","€360,000","€400,000"],"correct":1,"expl":"The announcement creates a constructive obligation, but IAS 37 limits the provision to costs necessarily entailed by the restructuring: only the €300,000 redundancy qualifies. Retraining and relocation relate to the ongoing business, and future operating losses are not a present obligation, so €360,000, €400,000 and €500,000 all sweep in excluded costs."}]},"cr-p1-mk":{"id":"cr-p1-mk","exam":"cr-p1","type":"mustknow","title":"Must know · CR Partial I","sub":"Synthèse des Must Know Absolutely, session par session, périmètre du 27/10","body":"# Must Know · CR Partial Exam I (mardi 27 octobre 2026, 9h00)\nPages du book : 8e édition Melville, celle envoyée par Alexandre. Page du PDF = page imprimée + 13. Le syllabus cite la 9e édition 2025, la numérotation peut y différer.\n## Comment lire cette page\nChaque session commence par un court paragraphe qui explique de quoi il s'agit et pourquoi, puis vient la liste des points à connaître absolument pour l'examen, avec les sigles développés à leur première occurrence. Les sessions de calcul proposent un mini exemple chiffré avec ses étapes. Périmètre : sessions 1 à 15. Format officiel : 15 à 20 QCM en 45 minutes, pas de points négatifs, mélange de questions conceptuelles, de calculs et d'écritures. Session 15 = séance de révision : refais les Practice Questions IA et IB disponibles sur Blackboard (dossier Review Session I du cours).\n\n### Session 1 · Régulation du reporting financier\nBook : ch. 1, p. 3 à 16, dont IFRS 1 p. 12 à 14. Exercices p. 15 à 16.\nCette session pose la question de départ du cours : pourquoi les états financiers sont-ils réglementés au lieu d'être laissés au libre choix des entreprises ? La réponse tient en un problème de confiance entre ceux qui dirigent l'entreprise et ceux qui y placent leur argent. Le reste de la session présente les organismes qui fabriquent les normes IFRS et la façon dont l'Europe les adopte.\n- Le problème d'agence : dans une grande société, les propriétaires (les actionnaires) ne gèrent pas, et les dirigeants ne possèdent pas ou peu. Les dirigeants en savent beaucoup plus que les investisseurs sur la santé réelle de l'entreprise : c'est l'asymétrie d'information. Sans règles communes, les comptes pourraient être présentés de façon trop favorable, les investisseurs le savent, et ils exigeraient des rendements plus élevés ou refuseraient de financer.\n- Deux motifs officiels de la régulation : l'efficience du marché (des informations comparables et fiables permettent au capital d'aller vers les meilleures entreprises) et la protection des investisseurs non sophistiqués (ceux qui ne peuvent pas analyser les comptes eux-mêmes).\n- Qui fabrique les normes : la IFRS Foundation nomme et finance l'IASB (International Accounting Standards Board), un collège de 14 membres qui rédige les normes IFRS. L'IFRIC (IFRS Interpretations Committee) publie des interprétations quand une norme prête à débat. L'Advisory Council oriente l'agenda des travaux.\n- Le due process (la procédure d'élaboration d'une norme) : identification du sujet, recours au cadre conceptuel, consultation publique, discussion paper (document de réflexion), exposure draft (projet de norme soumis aux commentaires), puis norme finale. Idée clé : le public est consulté à chaque étape formelle.\n- En Union européenne, une norme IFRS ne s'applique pas automatiquement : elle est endossée (adoptée) une par une. L'EFRAG (European Financial Reporting Advisory Group) rend un avis technique, l'ARC (Accounting Regulatory Committee, le comité des États membres) vote, puis la Commission publie le règlement. L'ESMA (European Securities and Markets Authority) coordonne le contrôle de l'application par les autorités nationales.\n- IFRS 1 gouverne la toute première application des IFRS par une entreprise. La date de transition est le début de la période comparative la plus ancienne présentée dans les premiers états IFRS. Exemple : premiers états IFRS au 31/03/2027 avec deux exercices comparatifs, donc transition au 01/04/2024. L'entreprise doit aussi présenter des réconciliations entre ses anciens GAAP locaux (son référentiel comptable national antérieur) et les IFRS : les capitaux propres à la date de transition et à la clôture du dernier exercice local, plus le résultat global de ce dernier exercice. Ce sont les questions 2 et 3 de la Review IA.\n\n### Session 2 · Cadre conceptuel\nBook : ch. 2, p. 17 à 36. Exercices p. 35 à 36.\nLe Cadre conceptuel (Conceptual Framework) est la constitution du système IFRS : il définit à quoi servent les états financiers et ce qu'est un actif, un passif, un produit, une charge. Attention : ce n'est pas une norme, et une IFRS spécifique prime toujours en cas de conflit. Il sert de base à l'IASB pour écrire des normes cohérentes, et il donne la logique derrière presque toutes les questions conceptuelles de l'examen.\n- Objectif unique : l'utilité décisionnelle. Les états financiers servent à aider les investisseurs actuels et potentiels, les prêteurs et autres créanciers à décider d'acheter, de vendre ou de prêter.\n- Deux caractéristiques fondamentales : la pertinence (l'information peut changer une décision, par sa valeur prédictive ou confirmative) et la représentation fidèle (complète, neutre et sans erreur matérielle). La matérialité (significativité) fait partie de la pertinence : une information est matérielle si son omission pourrait changer une décision.\n- Quatre caractéristiques d'amélioration : comparabilité, vérifiabilité, rapidité de publication, intelligibilité.\n- Les éléments : un actif est une ressource économique présente contrôlée du fait d'événements passés. Un passif est une obligation présente de transférer une ressource. Les capitaux propres sont l'intérêt résiduel, c'est à dire les actifs moins les passifs. Les produits et les charges se définissent à partir des variations d'actifs et de passifs.\n- Deux hypothèses de base : la continuité d'exploitation (l'entreprise va survivre) et la comptabilité d'exercice (on comptabilise les effets quand les événements ont lieu, pas quand l'argent bouge).\n- Évaluation : coût historique (le prix d'origine) ou valeur actuelle (juste valeur de marché, ou valeur d'utilité pour l'usage interne). Le choix dépend de ce qui donne l'information la plus pertinente et fidèle pour chaque élément.\n\n### Session 3 · IAS 1, IAS 8, IAS 10\nBook : ch. 3, p. 37 à 67, ch. 4, p. 68 à 82, et ch. 12, p. 204 à 209 pour IAS 10. Exercices p. 63 à 67 et p. 76 à 82.\nTrois normes de présentation générale. IAS 1 dit à quoi ressemblent les états financiers et comment classer les postes entre courant et non courant. IAS 8 fixe les règles quand une entreprise change de méthode ou corrige une erreur. IAS 10 traite des événements qui surviennent entre la clôture et la publication des comptes.\n- IAS 1 : les états financiers complets ont cinq composantes : bilan, compte de résultat et autres éléments du résultat global (OCI, other comprehensive income), tableau de variation des capitaux propres, tableau des flux de trésorerie, et les notes. Deux principes : pas de compensation entre actifs et passifs ou entre produits et charges, et un comparatif de l'exercice précédent obligatoire.\n- Le classement courant ou non courant : un actif est courant s'il est réalisé dans le cycle d'exploitation normal, s'il est détenu pour la transaction, s'il est attendu dans les 12 mois, ou s'il s'agit de trésorerie. Tout le reste est non courant. La même logique vaut pour les passifs avec le cycle d'exploitation et l'horizon de 12 mois.\n- IFRS 18 remplacera IAS 1 à partir de 2027 : le compte de résultat sera découpé en cinq catégories (opérationnel, investissement, financement, impôts, activités abandonnées) avec de nouveaux sous-totaux obligatoires. À connaître comme évolution future, le programme du partiel reste IAS 1.\n- IAS 8 distingue trois situations. Changement de méthode comptable : autorisé seulement si une norme l'exige ou si l'information devient plus pertinente, et appliqué rétrospectivement (on réécrit les comparatifs comme si la nouvelle méthode avait toujours été utilisée). Changement d'estimation (durée de vie, provision) : toujours prospectif, on ne touche pas au passé. Erreur matérielle : corrigée rétrospectivement.\n- IAS 10 : un événement postérieur à la clôture est ajustant s'il confirme une condition qui existait déjà à la clôture, et on corrige alors les chiffres. Sinon il est non ajustant, avec une simple note si l'impact est matériel. Exemple classique : la faillite d'un client après la clôture ajuste la créance si ses difficultés existaient déjà avant la clôture.\n\n### Session 4 · IAS 7 flux de trésorerie\nBook : ch. 16, p. 259 à 284. Exercices p. 272 à 284.\nLe profit n'est pas de la trésorerie : le résultat est calculé en comptabilité d'exercice, avec des produits et des charges qui ne font pas toujours bouger l'argent. Le tableau des flux de trésorerie répond à une question simple : d'où vient l'argent et où est-il allé. C'est la session la plus calculatoire du partiel, et la Review IA y consacre plusieurs questions.\n- Trésorerie et équivalents : placements à court terme, très liquides, dont le risque de variation de valeur est insignifiant. Le découvert bancaire ne compte en trésorerie négative que s'il est remboursable à vue et intégré à la gestion quotidienne de la trésorerie, sinon c'est un emprunt classé en financement.\n- Trois classes de flux : opérationnel (l'activité courante), investissement (achats et cessions d'actifs durables), financement (capital, emprunts, dividendes).\n- Classification des intérêts et dividendes : l'IAS 7 actuel laisse le choix, appliqué de façon constante. Le cours retient : intérêts et dividendes reçus en investissement, intérêts payés en opérationnel ou en financement, dividendes payés en opérationnel ou en financement. IFRS 18 changera cela en 2027 : méthode indirecte au départ du résultat opérationnel, dividendes payés en financement, intérêts payés en financement dans la plupart des cas.\n- Méthode indirecte : on part du résultat avant impôt, on retire tout ce qui n'est pas de la trésorerie, puis on corrige le décalage de trésorerie lié aux stocks, aux clients et aux fournisseurs (le besoin en fonds de roulement).\n- Ajustement 1 : + amortissements et + pertes sur cession, car ce sont des charges sans sortie d'argent.\n- Ajustement 2 : + baisse des créances clients, car on a encaissé plus que facturé.\n- Ajustement 3 : - hausse des stocks, car l'argent est sorti sans charge comptable.\n- Ajustement 4 : + hausse des dettes fournisseurs, car on n'a pas encore payé.\n- Exemple type Review IA, départ : résultat avant impôt 350.\n- Exemple, étape 1 : + amortissement 55 et + perte sur cession 20.\n- Exemple, étape 2 : + baisse clients 15, - hausse stocks 30, + hausse fournisseurs 12.\n- Exemple, total : 350 + 55 + 20 + 15 - 30 + 12 = 422 de flux opérationnel.\n- Méthode directe : on liste les encaissements et décaissements réels, reconstruits en deux étapes à partir du compte de résultat et des variations du bilan.\n- Côté clients : encaissé = ventes + créances d'ouverture - créances de clôture.\n- Côté fournisseurs, étape 1 : achats = coût des ventes + stock de clôture - stock d'ouverture.\n- Côté fournisseurs, étape 2 : payé = achats + dettes d'ouverture - dettes de clôture.\n- Exemple, données : coût des ventes 480, stocks de 110 à 95, dettes fournisseurs de 70 à 88.\n- Exemple, étape 1 : achats = 480 + 95 - 110 = 465.\n- Exemple, étape 2 : payé = 465 + 70 - 88 = 447.\n\n### Session 5 · IAS 32 présentation et classification\nBook : ch. 11, p. 181 à 195.\nLes instruments financiers sont partagés entre trois normes : IAS 32 décide de la classification (dette ou capitaux propres chez l'émetteur), IFRS 9 gère l'évaluation (session 6) et IFRS 7 impose les informations à donner (session 7). La question centrale ici : quand l'entreprise émet un titre, est-ce de la dette ou des capitaux propres ? La réponse change les ratios et le résultat.\n- Le test capitaux propres, deux conditions cumulatives : pas d'obligation contractuelle de livrer des liquidités (ni remboursement forcé, ni dividende obligatoire) ET règlement en instruments propres. Si une condition manque, le titre est un passif financier.\n- Conséquence importante : les actions préférentielles remboursables sont un passif financier malgré le mot actions, et leurs dividendes sont une charge d'intérêts dans le résultat, pas une distribution de bénéfice. C'est la question 12 de la Review IA.\n- Instruments composés comme l'obligation convertible : on découpe le produit de l'émission en deux. La part dette est la valeur actualisée des coupons et du remboursement, calculée au taux de marché d'un emprunt comparable sans conversion. La part capitaux propres est le résidu, c'est à dire le prix d'émission moins la part dette. Exemple : convertible émis à 1 020 000, flux actualisés 980 000, donc dette 980 000 et capitaux propres 40 000. C'est la logique de la question 17 de la Review IA.\n- Frais d'émission d'actions : déduits des capitaux propres, jamais passés en charge du résultat.\n- Actions propres rachetées (treasury shares) : déduites des capitaux propres, et aucun gain ni perte en résultat lors du rachat ou de la revente. Frais d'émission et actions propres forment la question 13 de la Review IA.\n\n### Session 6 · IFRS 9 évaluation\nBook : ch. 11, p. 181 à 195.\nIFRS 9 répond à deux questions : à quel moment comptabilise-t-on un instrument financier, et à quelle valeur figure-t-il au bilan. L'idée directrice : la juste valeur est le point de départ, et la classification dépend de la façon dont l'instrument rapporte de l'argent.\n- Comptabilisation dès que l'entité devient partie au contrat, pas à l'échange des liquidités.\n- Évaluation initiale toujours à la juste valeur. Les coûts de transaction directement attribuables s'ajoutent à la valeur d'un actif au coût amorti et se déduisent d'un passif au coût amorti, mais ils sont passés en charge pour les instruments FVPL. C'est la question 16 de la Review IA.\n- Quatre catégories d'actifs financiers : coût amorti (les intérêts sont étalés au taux effectif), FVOCI dette (juste valeur au bilan, variations en OCI recyclées en résultat à la cession), FVOCI capitaux propres (option, jamais recyclée), et FVPL par défaut (fair value through profit or loss, les variations passent directement en résultat).\n- Le coût amorti exige deux tests cumulatifs : le test SPPI (solely payments of principal and interest, les flux contractuels ne sont que du principal et des intérêts, comme un prêt classique) et le modèle d'affaires hold to collect (on détient l'instrument pour encaisser les flux, pas pour le revendre). C'est la question 15 de la Review IA.\n- Passifs financiers : coût amorti par défaut, juste valeur s'ils sont détenus pour la transaction.\n\n### Session 7 · IFRS 9 dépréciation et IFRS 7\nBook : ch. 11, p. 181 à 195. Exercices p. 194 à 195.\nAprès la crise de 2008, le vieux modèle a été critiqué : il ne comptabilisait les pertes sur crédit que lorsque le défaut était avéré, donc trop tard. IFRS 9 a introduit le modèle ECL (expected credit losses, pertes de crédit attendues) : on provisionne dès l'origine les pertes que l'on anticipe, sans attendre un événement déclencheur.\n- Trois stades selon la dégradation du risque. Stade 1 : crédit sain, on provisionne la perte attendue à 12 mois et les intérêts sont calculés sur l'encours brut. Stade 2 : hausse significative du risque de crédit, on passe à la perte attendue à vie, intérêts toujours sur le brut. Stade 3 : crédit déprécié, perte à vie, et les intérêts sont calculés sur l'encours net de la dépréciation.\n- IFRS 7 fixe l'information à fournir : expliquer le rôle des instruments financiers dans la situation financière et la performance, et exposer les risques pris, à savoir risque de marché, risque de crédit et risque de liquidité. C'est la question 14 de la Review IA.\n\n### Session 8 · Participations en actions (cas Berkshire)\nBook : ch. 11, p. 181 à 195. Le cas Berkshire reste sur Blackboard.\nCette session applique IFRS 9 aux participations en actions, c'est à dire les actions d'autres sociétés détenues en portefeuille, à travers le cas Berkshire Hathaway. La vraie question du cas n'est pas à quelle valeur comptabiliser, mais où afficher les variations de valeur : dans le résultat ou dans l'OCI.\n- Règle par défaut : les actions sont en FVTPL, les variations de cours passent dans le résultat de l'exercice.\n- L'option FVOCI : irrévocable, choisie instrument par instrument à l'acquisition, et réservée aux titres qui ne sont pas détenus pour la transaction. Sous FVOCI : les variations passent en OCI et ne sont jamais recyclées en résultat, même à la vente, les dividendes restent en résultat, et il n'y a pas de modèle ECL (pas de pertes attendues sur des actions).\n- Morale du cas Berkshire : le choix de présentation change le résultat affiché sans changer la réalité économique, d'où l'importance de lire aussi les OCI.\n\n### Session 9 · IAS 16 coût d'entrée\nBook : ch. 5, p. 83 à 107.\nIAS 16 traite des immobilisations corporelles (machines, bâtiments, terrains). Cette session répond à la première question : à quel coût l'actif entre-t-il au bilan ? Le principe : tout ce qui est nécessaire pour rendre l'actif utilisable entre dans le coût, le reste part en charge.\n- Coût initial : prix d'achat + coûts directement attribuables (transport, installation, honoraires liés à l'acquisition) + estimation du démantèlement futur, comptabilisée en provision selon IAS 37.\n- Exclus du coût : administration générale, études de faisabilité, formation du personnel, pertes d'exploitation initiales, coûts de déménagement.\n- La capitalisation cesse quand l'actif peut fonctionner comme prévu par la direction, même s'il n'a pas encore atteint sa pleine capacité. Les coûts après ce point sont des charges.\n- Approche par composants : les parties significatives d'un actif qui ont des durées de vie différentes s'amortissent séparément (la coque et les moteurs d'un avion, par exemple).\n- IAS 23 : les coûts d'emprunt liés à un actif qualifié (long à construire) sont capitalisés pendant la construction au lieu d'être passés en charge. Taux utilisé : le taux spécifique pour les emprunts dédiés au projet, la moyenne pondérée des autres emprunts pour le financement général. La Review IB teste le calcul de cette moyenne pondérée.\n\n### Session 10 · IAS 16 suite, réévaluation et IAS 40\nBook : ch. 5, p. 83 à 107. Exercices p. 104 à 107.\nDeuxième volet d'IAS 16 : que faire des dépenses engagées après l'achat, et que se passe-t-il si l'entreprise choisit de réévaluer ses actifs. On y ajoute IAS 40, la norme des immeubles de placement, qui applique une logique de juste valeur.\n- Dépenses ultérieures : capitalisées si elles augmentent les avantages économiques futurs (extensions, améliorations, remplacements de composants, inspections majeures). Les réparations et l'entretien ordinaires restent des charges.\n- Modèle de réévaluation : un premier excédent de réévaluation va en OCI (la réserve de réévaluation), un premier déficit va en résultat. Ensuite les mouvements résorbent d'abord le solde antérieur : un déficit après un excédent puise dans la réserve OCI avant de toucher le résultat, et une reprise d'un ancien déficit repasse par le résultat d'abord.\n- IAS 40 : un immeuble de placement (détenu pour les loyers ou la plus-value, pas pour l'usage propre) évalué au modèle juste valeur n'est pas amorti : les gains et pertes de valeur passent directement dans le résultat de l'exercice.\n\n### Session 11 · IAS 38 incorporels\nBook : ch. 6, p. 108 à 125. Exercices p. 123 à 125.\nLes actifs incorporels (brevets, logiciels, marques, goodwill) sont des actifs non monétaires, sans substance physique, et ils doivent être identifiables : séparables de l'entreprise ou issus d'un droit contractuel ou légal. La grande difficulté de la session : la recherche et le développement générés en interne, où la norme trace une frontière stricte entre ce qui se capitalise et ce qui part en charge.\n- Quatre voies d'entrée au bilan : acquisition séparée (au coût), regroupement d'entreprises (à la juste valeur selon IFRS 3), subvention publique (IAS 20), génération interne (soumise à la frontière recherche et développement).\n- Recherche : toujours en charge, jamais capitalisée. Développement : capitalisé seulement si six conditions sont réunies : faisabilité technique, intention d'achever, capacité à utiliser ou à vendre, avantages économiques futurs probables, ressources suffisantes pour finir, dépenses mesurables de façon fiable.\n- Marques et fichiers clients générés en interne : jamais comptabilisés à l'actif, car leur coût ne peut pas être distingué du coût de développement de l'activité dans son ensemble.\n- Durée de vie finie : amortissement, qui commence quand l'actif est disponible pour l'usage prévu, pas quand il est utilisé. Durée indéfinie et goodwill : jamais d'amortissement, mais un test de dépréciation annuel obligatoire (IAS 36, session 12).\n\n### Session 12 · IAS 36 dépréciation\nBook : ch. 7, p. 126 à 141.\nUn actif ne peut pas rester au bilan pour plus que ce qu'il rapportera. IAS 36 impose de comparer la valeur comptable à la valeur recouvrable, et de comptabiliser une perte si l'actif est surévalué. C'est une session de calcul : la Review IB en fait ses trois premières questions.\n- Perte de valeur = valeur comptable moins valeur recouvrable, seulement si la comptable est supérieure.\n- Valeur recouvrable = le maximum entre la juste valeur moins les coûts de sortie (prix de vente net) et la valeur d'utilité (les flux futurs attendus, actualisés, méthode DCF pour discounted cash flows). Exemple : valeur comptable 500, juste valeur nette 430, valeur d'utilité 460. La recouvrable est 460, la perte est 40.\n- Test annuel obligatoire, même sans signal d'alerte, pour trois catégories : le goodwill, les actifs à durée indéfinie, les actifs pas encore en service. Les autres actifs ne sont testés qu'en présence d'un indicateur de perte (chute de marché, obsolescence, capitalisation boursière sous l'actif net).\n- CGU (cash-generating unit, unité génératrice de trésorerie) : le plus petit groupe d'actifs qui génère des flux de trésorerie largement indépendants. On teste à ce niveau quand un actif seul ne produit pas de flux autonomes.\n- Ordre d'allocation de la perte dans une CGU : le goodwill d'abord jusqu'à zéro, puis les autres actifs au prorata de leur valeur comptable, sans descendre sous leur plancher individuel (leur propre valeur recouvrable).\n- Reprise de perte : jamais pour le goodwill. Pour les autres actifs, la reprise est plafonnée à la valeur comptable qu'aurait eue l'actif sans la perte, nette des amortissements intermédiaires.\n\n### Session 13 · Cas Biosensors\nBook : ch. 7, p. 126 à 141. Exercices p. 139 à 141. Le cas Biosensors reste sur Blackboard.\nLe cas Biosensors illustre IAS 36 en conditions réelles : une entreprise de dispositifs médicaux qui a payé très cher une acquisition, puis qui doit tester la dépréciation du goodwill qui en résulte.\n- Acquisition de JWMS pour 478 M USD, environ 25 fois le résultat FY2011 : une telle prime signifie que l'essentiel du prix payé ne correspond à aucun actif identifiable, donc qu'il tombe dans le goodwill.\n- Le goodwill n'est jamais amorti. Il est alloué aux CGU qui profitent de l'acquisition et testé chaque année en comparant la valeur comptable à la valeur d'utilité estimée par DCF.\n- Point clé du cas : la dépréciation FY2012 touche trois petites CGU (BSI, Bio Japan, Bifurcation stents) mais pas JWMS, la plus grosse. La dépréciation de goodwill se décide CGU par CGU, pas au niveau du groupe.\n- Signal d'alerte à retenir : une capitalisation boursière durablement inférieure à l'actif net comptable est un indicateur externe de dépréciation.\n\n### Session 14 · IAS 37 provisions\nBook : ch. 12, p. 196 à 203. Exercices p. 206 à 209.\nUne provision est un passif dont le montant ou l'échéance est incertain. IAS 37 pose un garde-fou essentiel : on ne provisionne que des obligations réelles nées d'événements passés, jamais des coussins de prudence pour l'avenir. La Review IB y consacre plusieurs questions.\n- Trois conditions cumulatives : une obligation présente issue d'un événement passé, une sortie probable de ressources, et une estimation fiable du montant.\n- L'obligation peut être légale (contrat ou loi) ou constructive : l'entreprise a créé par son comportement passé ou ses annonces une attente valable chez les tiers, au point de ne plus avoir d'alternative réaliste.\n- Passif éventuel (obligation seulement possible, ou non mesurable de façon fiable) : note en annexe uniquement, et rien du tout si la probabilité est faible (remote). Actif éventuel : jamais comptabilisé, note seulement si l'entrée est probable.\n- Mesure : montant le plus probable pour une obligation unique, valeur espérée (moyenne pondérée par les probabilités) pour une population de cas, actualisation si l'effet du temps est matériel. La désactualisation annuelle (unwinding) passe en charges financières.\n- Jamais de provision pour de simples pertes d'exploitation futures. En revanche un contrat déficitaire (onéreux), où les coûts inévitables dépassent les bénéfices attendus, donne toujours lieu à une provision.\n- Restructuration : provision seulement avec un plan formel détaillé ET une attente valable créée chez les personnes concernées (annonce ou début de mise en œuvre). Coûts directement liés uniquement, pas les coûts de l'activité qui continue.\n\n### Session 15 · Review Session I\nSéance de révision : le meilleur entraînement reste de refaire les Practice Questions IA et IB sur Blackboard (dossier Review Session I). IA couvre IFRS 1, IAS 7, IAS 32 et IFRS 9. IB couvre IAS 36, IAS 37, IAS 38, IAS 16, IAS 23 et IAS 40. Les QCM du site pour les sessions 1 à 14 ont été enrichis de questions originales construites sur les mêmes gabarits de calcul que ces Practice Questions."},"cr-p1-b1":{"id":"cr-p1-b1","exam":"cr-p1","type":"blanc","title":"Partiel blanc CR #1","duration":45,"revision":3,"intro":"Mock CR réécrit dans le style des mocks de référence du cours: 18 QCM à 4 options en 45 minutes, pas de points négatifs. Une question par enjeu, énoncés compacts, calculs nets, chaque mauvaise option correspond à une erreur précise démontée dans le corrigé qui cite la norme. Couverture des sessions 1 à 14. Prévois 2 minutes par question et 8 minutes de relecture, sans notes.","formatNote":"18 QCM à 4 options · pas de points négatifs · aucune question ouverte","materialNote":"Closed book · calculatrice · corrigé détaillé dévoilé à la fin","mcq":[{"session":"Session 1 · Regulation and the agency problem","q":"Shareholders delegate decisions to managers whose actions they cannot fully observe. In the agency rationale for mandatory audited financial statements, what is their main purpose?","choices":["To support investors' valuation of the firm's shares for trading decisions","To align managerial pay with the firm's reported performance","To reduce the information gap between managers and shareholders","To transfer day-to-day operating control from managers to shareholders"],"correct":2,"expl":"In the agency rationale, audited statements give owners verified information about management's stewardship and so mitigate the information asymmetry created by the separation of ownership and control. Supporting market valuation is the decision-usefulness objective, not the agency rationale for mandatory reporting. Aligning pay is a role of compensation contracts, not of financial statements. Reporting leaves operating control with managers while making them accountable for it."},{"session":"Session 2 · Conceptual Framework","q":"The Conceptual Framework divides the qualitative characteristics of useful financial information into fundamental and enhancing. Which of the following is an enhancing characteristic?","choices":["Comparability","Relevance","Faithful representation","Materiality"],"correct":0,"expl":"Relevance and faithful representation are the two fundamental characteristics. Comparability, verifiability, timeliness and understandability are enhancing characteristics. Materiality is an entity-specific aspect of relevance, not a stand-alone enhancing characteristic."},{"session":"Session 3 · IAS 8 policies and estimates","q":"On 1 January 2023 a company buys a machine for €240,000 and depreciates it on a straight line basis over a 10 year life, expecting no residual value. On 1 January 2026 the company revises the total useful life down to 6 years. What depreciation charge is recognised for 2026?","choices":["€24,000","€40,000","€33,600","€56,000"],"correct":3,"expl":"Carrying amount at 1 January 2026: 240,000 − 3 × 24,000 = €168,000. The revised remaining life is 3 years, so 168,000 / 3 = €56,000. IAS 8 applies a change in estimate prospectively, with no restatement. €24,000 keeps the old charge, €40,000 redepreciates the original cost over the new total life ignoring elapsed years, €33,600 uses a five-year remainder."},{"session":"Session 10 · IAS 16 revaluation entry","q":"A building carried at €500,000 is revalued to €560,000. A revaluation deficit of €40,000 on the same building was recognised in profit or loss in a previous year. How is the €60,000 surplus recognised?","choices":["€60,000 in other comprehensive income","€40,000 in profit or loss and €20,000 in other comprehensive income","€60,000 in profit or loss","€20,000 in profit or loss and €40,000 in other comprehensive income"],"correct":1,"expl":"IAS 16 first reverses a prior revaluation deficit of the same asset through profit or loss (€40,000), and only the excess (€20,000) goes to the revaluation surplus in OCI. Putting the whole €60,000 in OCI skips the reversal, putting it all in profit or loss overcompensates the prior deficit, and the €20,000/€40,000 split inverts the order."},{"session":"Session 4 · IAS 7 indirect method","q":"Profit before tax is €420,000 after depreciation of €70,000 and a gain on disposal of equipment of €10,000. Trade receivables increased by €25,000, inventories decreased by €15,000 and trade payables decreased by €8,000. What is the cash generated from operations, before deducting interest paid and income taxes paid?","choices":["€482,000","€498,000","€462,000","€322,000"],"correct":2,"expl":"420,000 + 70,000 depreciation added back − 10,000 disposal gain moved to investing − 25,000 + 15,000 − 8,000 working capital = €462,000. €482,000 adds the gain instead of deducting it, €498,000 inverts every working-capital sign, €322,000 deducts depreciation as if it were a cash cost."},{"session":"Session 4 · IAS 7 classification","q":"A company pays €120,000 to acquire a trademark. In which section of the statement of cash flows does this payment appear?","choices":["Operating activities","Investing activities","Financing activities","It is not a cash flow and is disclosed only"],"correct":1,"expl":"IAS 7 presents cash payments to acquire intangible assets as investing activities, because they create resources that generate future income. Operating covers the principal revenue-producing activities, financing covers changes in equity and borrowings, and the payment is a real cash outflow, so disclosure-only is wrong."},{"session":"Session 5 · IAS 32 debt versus equity","q":"A company issues 100,000 preference shares at €10 each. Holders receive a fixed 6% annual dividend and the company must redeem the shares for cash in four years. How are the shares classified?","choices":["Entirely as equity, because legally they are shares","As a compound instrument with liability and equity components","Entirely as a financial liability","As equity until the redemption date, then reclassified"],"correct":2,"expl":"IAS 32 looks at substance: the contractual obligation to deliver cash at redemption makes the instrument a financial liability despite its legal form as shares, and the mandatory dividend is a finance cost, not a distribution. There is no discretionary element left, so no equity component exists, and classification is set at inception, not at redemption."},{"session":"Session 5 · IAS 32 compound instrument","q":"On 1 January a company issues €2,000,000 of 4% convertible bonds at par, repayable at par in 3 years, interest paid annually in arrears. Similar bonds without the conversion option yield 7%. The annuity factor for 3 years at 7% is 2.6243 and the year 3 discount factor is 0.8163. What is the equity component at issue?","choices":["€157,456","€1,842,544","€240,000","€2,000,000"],"correct":0,"expl":"The liability component is measured first: interest 80,000 × 2.6243 = 209,944 plus principal 2,000,000 × 0.8163 = 1,632,600, total €1,842,544. The residual 2,000,000 − 1,842,544 = €157,456 is the equity component (IAS 32). €1,842,544 is the liability, €240,000 is three years of interest, €2,000,000 skips the split entirely."},{"session":"Session 6 · IFRS 9 classification","q":"A company buys listed bonds whose cash flows are solely payments of principal and interest on set dates. The company's business model is to hold the bonds to collect those cash flows. How are the bonds measured after initial recognition?","choices":["At fair value through profit or loss","At fair value through other comprehensive income","At amortised cost using the effective interest method","At cost, with no interest accrual"],"correct":2,"expl":"The SPPI test is passed and the hold-to-collect business model is met, so IFRS 9 requires amortised cost with the effective interest method. FVOCI requires a collect-and-sell model, FVTPL is the residual category when the tests fail, and amortised cost still accrues interest, so cost with no accrual is wrong."},{"session":"Session 6 · IFRS 9 effective interest","q":"At the start of the year an entity purchases for €280,000 a bond with a nominal value of €300,000. The bond pays a 4% coupon annually in arrears and the effective interest rate is 6%. It is held to collect contractual cash flows. What is the carrying amount at year end?","choices":["€284,800","€292,000","€280,000","€296,800"],"correct":0,"expl":"Interest income is 280,000 × 6% = €16,800, the cash coupon is 300,000 × 4% = €12,000, and the €4,800 difference accretes the purchase discount: 280,000 + 4,800 = €284,800. €292,000 adds the coupon instead of the effective income, €280,000 ignores accretion, €296,800 adds the income without deducting the coupon received."},{"session":"Session 7 · IFRS 9 expected credit losses","q":"Under the IFRS 9 general model, a loan's credit risk has increased significantly since origination, but the loan is not credit-impaired. Which combination of loss allowance and interest basis applies?","choices":["12-month ECL, interest on the gross carrying amount","Lifetime ECL, interest on the gross carrying amount","Lifetime ECL, interest on the net carrying amount","No allowance until a default event occurs"],"correct":1,"expl":"A significant increase in credit risk without impairment is Stage 2: lifetime expected credit losses are recognised, but interest revenue is still calculated on the gross carrying amount. The net basis applies only once the asset is credit-impaired (Stage 3), 12-month ECL is Stage 1, and the model is forward-looking so no default event is needed."},{"session":"Session 8 · IFRS 9 equity FVOCI election","q":"At initial recognition a company irrevocably elects FVOCI for a non-trading equity investment. The shares gain €150,000 in fair value and pay ordinary dividends of €20,000 before being sold at the same price. Ignore tax. What total amount is recognised in profit or loss over the holding period?","choices":["€170,000","€150,000","Nil","€20,000"],"correct":3,"expl":"For an elected FVOCI equity investment, only the €20,000 of ordinary dividends enters profit or loss. The €150,000 fair value gain stays in OCI and is never recycled on disposal, though it may be transferred within equity. €170,000 adds the gain to the dividend, €150,000 recognises only the gain, and nil forgets the dividend."},{"session":"Session 9 · IAS 16 initial cost","q":"A company buys a machine for €250,000. It also pays transport of €6,000, installation of €14,000, net testing costs of €10,000, staff training of €8,000 and a two-year maintenance contract of €12,000. What is the cost of the machine under IAS 16?","choices":["€280,000","€300,000","€292,000","€264,000"],"correct":0,"expl":"Cost includes the purchase price and directly attributable costs of bringing the asset to working condition: 250,000 + 6,000 + 14,000 + 10,000 = €280,000. Training and maintenance are expensed as incurred. €292,000 adds the maintenance contract, €300,000 adds both excluded items, €264,000 forgets transport and testing."},{"session":"Session 10 · IAS 23 borrowing costs","q":"On 1 March a company borrows €1,000,000 at 7% specifically to build a plant. Construction starts immediately and the plant is ready for use on 31 December. €200,000 of the funds is temporarily invested at 2% for 6 months. What borrowing cost is capitalised in the year?","choices":["€56,333","€58,333","€70,000","€66,000"],"correct":0,"expl":"Capitalisation runs from the start of construction to readiness: 1,000,000 × 7% × 10/12 = €58,333, less income from the temporary investment 200,000 × 2% × 6/12 = €2,000, giving €56,333 (IAS 23). €58,333 forgets the investment income offset, €70,000 capitalises a full year, €66,000 deducts twelve months of investment income."},{"session":"Session 11 · IAS 38 research and development","q":"During the year a company spends €120,000 on research and €200,000 on developing a new product. The IAS 38 capitalisation criteria are met only from 1 October, and €60,000 of the development spending arose before that date. What amount is expensed in profit or loss for the year?","choices":["€180,000","€320,000","€120,000","€60,000"],"correct":0,"expl":"Research is always expensed, and development spending before the criteria are met can never be capitalised later: 120,000 + 60,000 = €180,000 expensed, €140,000 capitalised. €320,000 expenses the qualifying development too, €120,000 wrongly capitalises the early development, €60,000 forgets the research."},{"session":"Session 12 · IAS 36 impairment loss","q":"An item of equipment has a carrying amount of €600,000, fair value less costs of disposal of €520,000 and value in use of €545,000. A revaluation surplus of €30,000 exists for this asset. How is the impairment loss recognised?","choices":["€55,000 in profit or loss","€80,000: €30,000 in other comprehensive income and €50,000 in profit or loss","€55,000 in other comprehensive income","€30,000 in other comprehensive income and €25,000 in profit or loss"],"correct":3,"expl":"Recoverable amount is the higher of the two measures, €545,000, so the loss is 600,000 − 545,000 = €55,000. On a revalued asset the loss first cancels the existing surplus in OCI (€30,000) and the excess (€25,000) goes to profit or loss. €80,000 uses the lower measure, and an all-P&L or all-OCI treatment misallocates the loss."},{"session":"Session 13 · IAS 36 goodwill in a CGU","q":"A cash-generating unit has a carrying amount of €900,000 including goodwill of €150,000. Its recoverable amount is €700,000. No other asset would fall below its own recoverable amount. How is the impairment loss allocated?","choices":["€200,000 entirely against goodwill","€150,000 against goodwill and €50,000 pro rata against the other assets","€200,000 pro rata across all assets including goodwill","€50,000 against goodwill and €150,000 pro rata against the other assets"],"correct":1,"expl":"IAS 36 sets the order: the €200,000 loss first reduces goodwill (€150,000), and only the remainder (€50,000) is allocated pro rata to the other assets, subject to their individual floors. Capping the loss at goodwill understates it, pro rata across everything ignores the order, and the inverted split misreads the amounts."},{"session":"Session 14 · IAS 37 warranty provision","q":"A company sells 10,000 products with a one-year warranty. Experience shows 3% of units need major repairs costing €80 each and 7% need minor repairs costing €20 each. What warranty provision is recognised at year end?","choices":["€24,000","€38,000","€14,000","€50,000"],"correct":1,"expl":"IAS 37 uses the expected value over the whole population: major repairs 10,000 × 3% × €80 = €24,000, minor repairs 10,000 × 7% × €20 = €14,000, total €38,000. €24,000 and €14,000 each count one repair class only, €50,000 averages the two repair costs across repaired units instead of weighting each class by its own probability."}],"open":[]},"fm-p1-mk":{"id":"fm-p1-mk","exam":"fm-p1","type":"mustknow","title":"Must know · FM Partial I","sub":"Synthèse des Must Know Absolutely, session par session, périmètre filtré du 20/10","body":"# Must Know — FM Partial Exam I (mardi 20 octobre 2026, 9h00)\n## Synthèse par session, extraite des sections \"Must Know Absolutely\" des fiches exam-grade\nPérimètre : sessions 1-11, exclusions annonce 14/10 (money market hedge, currency swaps pp.109-117, DCF valuation, guest lecture s10). Session 11 = closing thoughts (pas de fiche, rien de chiffré attendu).\n\n### Session 1 — Cash & financial planning\n- Cash budget = prévoir les soldes de trésorerie pour planifier besoins/excédents. Build en 3 étapes : sources, uses, shortage/surplus.\n- Identité : Cash(EOP) = Cash(BOP) + (Sources − Uses) + financial income/charges.\n- Coût/revenu ≠ cash flow (décalages, non-monétaire, hors IS comme le remboursement de principal).\n- Cash Budget = CT/mensuel/trésorerie ; Financial Budget = MT/annuel-trimestriel/opérations ; Financial Plan = LT/annuel/stratégie.\n- Création de valeur = 3 équilibres simultanés (IS + BS + CF). Plus grosse source de cash : les encaissements clients.\n- Sous incertitude : scénarios pondérés, momentum case, bear case explicite, hypothèses macro cohérentes, back-testing hebdo.\n\n### Session 2 — Working capital discipline (HBR, six erreurs)\n- Erreur 1 : piloter au seul compte de résultat ignore le coût d'opportunité du cash bloqué en stocks/créances.\n- Règle d'arbitrage : ne changer les conditions de crédit que si la perte de profit attendue < rendement du capital libéré.\n- Erreurs 2-3 : rémunérer les ventes au volume gonfle créances et stocks ; bonus qualité-seule → WIP invendable.\n- Erreur 4 : créances et dettes fournisseurs sont des relations séparées — ne jamais les lier mécaniquement.\n- Current ratio = ST assets/ST liabilities ; Quick = (ST assets − stock)/ST liabilities ; les deux se \"gament\".\n- Erreur 6 : benchmarker uniquement son secteur → complaisance. Cause racine des six : métriques/incitations mal conçues.\n\n### Session 3 — Cash conversion cycle & receivables\n- DSO = AR ÷ (Ventes ÷ 365) ; DPO = AP ÷ (COGS ÷ 365) ; DI = Stock ÷ (COGS ÷ 365). DI et DPO sur COGS, pas sur ventes.\n- Cash Cycle = DI + DSO − DPO = cycle opérationnel (DI+DSO) − délai fournisseurs. Garder les décimales jusqu'au résultat final.\n- Stock optimal : arbitrage carrying cost (stockage + coût d'opportunité) vs order cost ; croît moins que proportionnellement aux ventes ; JIT exige un flux stable.\n- Décision de crédit : E[gain] = p×PV(Rev−Cost) − (1−p)×PV(Cost) — maximiser la PV, pas minimiser les impayés.\n- Aging schedule pour le suivi ; concentrer l'analyse sur les gros comptes douteux.\n\n### Sessions 4-5 — Transaction exposure (FX)\n- Identifier devise domestique, montant, sens (recevoir/payer), date de règlement. Cotation directe/indirecte = réciproques.\n- Recevoir une devise : short forward ou put acheté. Payer une devise : long forward ou call acheté.\n- Forward apparié = montant domestique figé. Put = prix minimum de vente garanti moins prime. Call = prix maximum d'achat garanti plus prime. Ces prix sont exprimés en devise domestique par unité de devise étrangère.\n- Le strike décide de l'exercice ; l'égalité des nets décide du break-even forward/option.\n- Mettre la prime dans la bonne devise, capitalisée selon la convention de temps énoncée.\n- Juger sous-jacent + dérivé ensemble : le sur-hedging crée une position spéculative non couverte.\n\n### Session 6 — Interest rate risk & swaps\n- Dette = claim fixe, déductible, prioritaire, sans contrôle. Equity = résiduel, non déductible, dernière priorité, contrôle.\n- AIC = IRR du flux complet du prêt (proceeds nets de fee, intérêts, intérêts+principal) — toujours au-dessus du taux coté à cause de la fee.\n- 3 outils : Interest Rate Swap (développé), FRA, Interest Rate Option (nommés seulement).\n- Swap plain-vanilla : payer fixe / recevoir floating + prêt floating sous-jacent → les jambes flottantes s'annulent, net fixe = taux fixe du swap + spread de crédit.\n- QSD = différentiel de taux fixes − différentiel de taux flottants entre deux emprunteurs ; doit être positif pour que le swap crée de la valeur.\n- Attendre pour swapper n'est pas sans risque : le taux fixe offert bouge avec le taux de référence.\n- EXCLU du partiel : currency swaps (pp.109-117).\n\n### Session 7 — Cost of capital\n- WACC = kd(1−tc)·D/(D+E) + ke·E/(D+E) — valeurs de marché, dette après impôt (le (1−tc) ne s'applique qu'à la dette).\n- CAPM : ke = rf + βL × MRP. rf = zéro-coupon souverain aligné sur l'horizon.\n- MRP : 3 méthodes (survey, historique — biais de survie, arithmétique vs géométrique —, implied).\n- Beta top-down = pente de Rj = a + b·Rm (choix : fenêtre 2-5 ans, intervalle, dividendes, indice).\n- Déterminants du beta : produits discrétionnaires, levier opérationnel, levier financier.\n- βL = βu(1 + (1−tc)·D/E) ; actifs non cotés → bottom-up par comparables.\n- kd = taux d'emprunt courant ; 3 estimations : historique récent, rating public (médiane), synthetic rating (ICR = EBIT/intérêts).\n\n### Session 8 — Optimal capital structure\n- EV max ⟺ WACC min ; le management agit sur les poids D/E, kd et ke s'ajustent.\n- 3 forces : kd monte (défaut), ke monte (βL), le tax shield tire le WACC vers le bas → courbe en U, optimum D/E*.\n- En pratique : cible de rating + plage de levier (timing, flexibilité, covenants, incitations), pas l'optimum théorique.\n- Cycle de vie : la capacité d'endettement croît avec la stabilité des cash flows ; le LBO vit dans la maturité.\n- 4 stratégies d'endettement : low leverage, ordinary debt, debt for growth, aggressive leverage (NFP/EBITDA > 3.0x = zone LBO).\n- FCFO = EBIT − impôts sur EBIT + D&A − ΔWC − capex net ; le besoin de financement vient du BFR et de l'investissement.\n\n### Session 9 — Private equity & LBO\n- PE : equity illiquide de contrôle ; LP/GP (1-2% fees + 20% carry) ; fonds 10-12 ans.\n- Création de valeur = A-L-O : arbitrage (multiple), leverage (désendettement), opérationnel (marges).\n- LBO ≈ 60-80% dette / 20-40% equity ; la dette est remboursée par les cash flows de la cible ; cible : sous-évaluée, sous-performante, sous-levieragée, cash flows stables, capex modéré.\n- Le levier amplifie le MOIC (debt paydown convertit l'EV en equity) — symétriquement à la baisse.\n- Modèle en 8 étapes : sizing (EBITDA × multiple) → sources & uses (equity = plug) → tranches → P&L → FCF → debt schedule (cash sweep) → circularité → IRR/MOIC.\n- 5 leviers de retour : prix d'entrée, multiple de sortie, levier, croissance, marge.\n- Sécurité : levier ≤ ~6x net debt/EBITDA, couverture EBITDA/intérêts, liquidité ; un LBO sain se désendette.\n"},"fm-p1-b1":{"id":"fm-p1-b1","exam":"fm-p1","type":"blanc","title":"Partiel blanc #1","duration":45,"intro":"Format officiel du partial : 4 QCM à 3 options et 2 questions ouvertes multi-parties, 45 minutes, closed book, calculatrice scientifique autorisée. Périmètre : sessions 1 à 11 avec les exclusions officielles. Pas de chrono imposé ici : chronomètre-toi, le corrigé détaillé se dévoile à la fin. Questions originales calibrées sur le format officiel. Corrigé FX révisé le 16 octobre. Les anciens résultats restent enregistrés et sont signalés séparément.","mcq":[{"session":"Session 2 · Working capital","q":"In year 0, a distributor has annual revenues of €240 million and COGS equal to 65% of revenues. Working capital parameters: DSO = 45 days, DI = 60 days, DPO = 60 days. In year 1, revenues grow to €300 million and management renegotiates terms: DSO = 60 days, DI = 75 days, DPO = 75 days. Which statement best describes the net effect?","choices":["Working capital decreases and the cash conversion cycle decreases","Working capital increases although the cash conversion cycle decreases","Both working capital and the cash conversion cycle increase"],"correct":2,"expl":"WC0 = 156×60/365 + 240×45/365 − 156×60/365 = 29.6 M€ ; WC1 = 195×75/365 + 300×60/365 − 195×75/365 = 49.3 M€ (les termes DI et DPO s'annulent car égaux et calculés sur le même COGS). CCC0 = 60+45−60 = 45 jours ; CCC1 = 75+60−75 = 60 jours. Working capital et cash conversion cycle augmentent tous les deux : la croissance des revenus domine."},{"session":"Sessions 4-5 · FX option hedge","q":"A European exporter will receive USD 200,000 in three months. Dollar puts allow conversion at a strike of USD 1.20 per EUR. The premium is 2% of the USD notional, paid today and converted into euros at the current spot of USD 1.22 per EUR. Ignore interest on the premium. What is the minimum net euro receipt per dollar after premium?","choices":["EUR 0.8503 per USD","EUR 0.8333 per USD","EUR 0.8169 per USD"],"correct":2,"expl":"Gross guaranteed proceeds are 200,000 / 1.20 = EUR 166,666.67. The USD 4,000 premium costs 4,000 / 1.22 = EUR 3,278.69. Net minimum proceeds are EUR 163,387.98, or EUR 0.81694 per USD. Invert the USD per EUR strike before subtracting the euro premium. The reciprocal is about USD 1.22408 per EUR, not a minimum dollar per euro rate."},{"session":"Session 6 · Interest rate swap","q":"A company borrows $10 million externally at a fixed rate of 6% and enters a plain-vanilla interest rate swap on a $10 million notional, paying SOFR + 1% and receiving a fixed rate of 5%. What is the all-in cost of the combined position?","choices":["SOFR","SOFR + 2%","SOFR + 1%"],"correct":1,"expl":"Coût total = 6% (emprunt fixe) + (SOFR + 1%) payé sur le swap − 5% reçu du swap = SOFR + 2%. Les jambes fixes ne s'annulent pas : 6% payés, 5% reçus, il reste 1% plus le spread de 1%."},{"session":"Session 9 · LBO pricing","q":"A financial sponsor evaluates a target with: EBITDA₀ = €50, growing 4% per year; debt capacity = 4.0x EBITDA₀, split 40% senior (fully repaid by the target's cash flows over 5 years) and 60% junior (bullet repayment after year 5, interest paid in cash); exit at the end of year 5 at EV₅ = 5.5x EBITDA₅; target IRR 25%. Ignore transaction costs and cash on balance sheet at exit. What is the maximum Enterprise Value the sponsor can pay today, and the implied entry multiple on EBITDA₀?","choices":["~€245 (≈4.9x EBITDA₀)","~€300 (≈6.0x EBITDA₀)","~€270 (≈5.4x EBITDA₀)"],"correct":2,"expl":"EBITDA₅ = 50 × 1.04⁵ = 60.83 ; EV₅ = 5.5 × 60.83 = 334.6 ; dette totale = 4.0 × 50 = 200, dont junior bullet 120 encore dû à la sortie ; equity à la sortie = 334.6 − 120 = 214.6 ; equity max aujourd'hui = 214.6 / 1.25⁵ = 70.3 ; EV max = 70.3 + 200 = 270.3 ≈ 5.4x EBITDA₀."}],"open":[{"title":"Question ouverte 1 · WACC estimation (sessions 7-8)","body":"Bellaria S.p.A. est un groupe italien non coté actif dans deux métiers : food processing (70% de la valeur d'entreprise) et specialty packaging (30%). Les actionnaires demandent une estimation du WACC du groupe à partir de comparables cotés.\n- Food processing (70% de l'EV) : bêta levé moyen des pairs 1.20, D/E de marché moyen des pairs 50%\n- Specialty packaging (30% de l'EV) : bêta levé moyen des pairs 0.80, D/E de marché moyen des pairs 25%\n- EBIT : 60 M€ ; frais financiers : 15 M€\n- Dette financière au bilan : 320 M€, maturité résiduelle moyenne 4 ans (intérêts annuels de 15 M€)\n- Une transaction récente sur une participation minoritaire entre parties indépendantes implique une valeur de marché des fonds propres de 750 M€\n- Taux d'impôt (Bellaria et pairs) : 24%\n- Taux sans risque (Bund 10 ans) : 3% ; prime de risque actions : 5%\n- Table de synthetic rating (spread sur le sans risque) : ICR > 6.0 → AA → 1.00% ; 4.5 à 6.0 → A → 1.50% ; 3.0 à 4.5 → BBB → 2.25% ; 2.0 à 3.0 → BB → 3.50% ; < 2.0 → B → 5.00%\n\nTravail demandé : a) le bêta désendetté (asset bêta) de Bellaria par approche bottom-up ; b) le coût de la dette avant et après impôt par synthetic rating, et la valeur de marché de la dette ; c) le bêta levé et le coût des fonds propres (CAPM) ; d) le WACC de Bellaria.","solution":"a) βu food = 1.20 / (1 + 0.76×0.5) = 0.870 ; βu packaging = 0.80 / (1 + 0.76×0.25) = 0.672 ; asset bêta = 0.7×0.870 + 0.3×0.672 = **0.810**.\nb) ICR = 60/15 = 4.0 → BBB → spread 2.25% ; kd = 3% + 2.25% = **5.25%** ; kd après impôt = 5.25% × 0.76 = **3.99%** ; valeur de marché de la dette = 15 × annuité(4 ans, 5.25%) + 320 / 1.0525⁴ = 53.1 + 260.6 = **313.7 M€**.\nc) D/E = 313.7 / 750 = 0.418 ; βL = 0.810 × (1 + 0.76×0.418) = **1.068** ; ke = 3% + 1.068 × 5% = **8.34%**.\nd) WACC = (750 / 1063.7) × 8.34% + (313.7 / 1063.7) × 3.99% = **7.06%**."},{"title":"Question ouverte 2 · FX hedging strategies (sessions 4-5)","body":"Une multinationale européenne est exportatrice nette aux USA et encaisse ses revenus en dollars. T0 = budgeting, T1 = facturation, T2 = encaissement ; T1 est trois mois après T0, T2 trois mois après T1. En T1, les managers choisissent entre : ne rien faire, acheter un forward couvrant 100% de l'exposition, ou acheter un put couvrant 100% de l'exposition.\n- Exposition facturée en T1 : 400 M$\n- Cours de budget en T0 : 1.12 $/€\n- Spot en T1 : 1.10 $/€\n- Forward en T1 : 1.11 $/€\n- Strike du put (= spot en T1) : 1.10 $/€\n- Prime du put : 3% de l'équivalent euro\n- Coût du capital (annuel) : 5.0%\n\na) Calcule la performance ex-post de chaque stratégie (ne rien faire, forward, option) en euros encaissés en T2, sous deux spots à maturité : 0.98 $/€ et 1.22 $/€.\nb) Calcule le spot break-even entre l'option et le forward, interprète-le, et explique dans quelles conditions de marché chaque stratégie est préférable.","solution":"Prime = 3% × (400 / 1.10) = 10.91 M€ en T1, capitalisée à T2 (5% annuel, 3 mois) ≈ **11.05 M€**.\nForward : 400 / 1.11 = **360.4 M€** dans tous les cas.\na) Spot T2 = 0.98 : ne rien faire = 400/0.98 = 408.2 M€ ; option non exercée = 408.2 − 11.05 = **397.1 M€** ; forward = 360.4 M€. Spot T2 = 1.22 : ne rien faire = 400/1.22 = 327.9 M€ ; option exercée = 400/1.10 − 11.05 = 363.6 − 11.05 = **352.6 M€** ; forward = 360.4 M€.\nb) Break-even : 400/S − 11.05 = 360.4 → S = **1.077 $/€**. En dessous de 1.077 (dollar fort), l'option bat le forward ; au-dessus, le forward est préférable. L'option ne justifie sa prime que si le dollar s'apprécie suffisamment ; le forward fige le cours sans prime mais renonce à tout gain."}],"revision":2},"fm-p1-b2":{"id":"fm-p1-b2","exam":"fm-p1","type":"blanc","title":"Mock FM #2","duration":45,"revision":1,"intro":"Nouveau mock original aligné sur le format officiel. 4 QCM à 3 options et 2 questions ouvertes multi-parties. Les énoncés sont en anglais et autonomes. Prévois 10 minutes pour les QCM, 18 pour le WACC, 14 pour le change et 3 pour relire. Réponds avant de consulter le corrigé final.","mcq":[{"session":"Sessions 4-5 · FX units and premium","q":"A euro area exporter expects USD 360,000 in six months. A dollar put guarantees conversion at USD 1.15 per EUR. Its premium is 1.8% of the USD notional, paid today at spot USD 1.20 per EUR. Ignore interest on the premium. What is the minimum net euro receipt per USD after premium?","choices":["EUR 0.8846 per USD","EUR 0.8546 per USD","USD 1.1293 per EUR"],"correct":1,"expl":"Convert the strike first: 1 / 1.15 = EUR 0.869565 per USD. Premium per USD is 0.018 / 1.20 = EUR 0.015. The net floor is 0.854565 euros per dollar. Total net proceeds are 360,000 / 1.15 minus 6,480 / 1.20 = EUR 307,643.48. Adding the premium or subtracting a percentage from the inverted quote gives the wrong floor."},{"session":"Session 2 · Working capital and missing data","q":"At year 0, a wholesaler has revenue EUR 480 million, cost of goods sold equal to 60% of revenue, days sales outstanding 45, inventory days 50 and payable days 40. For year 1 it plans days sales outstanding of 55, inventory days of 35 and payable days of 60. Neither year 1 revenue nor year 1 cost of goods sold is forecast. What follows without assuming unchanged activity?","choices":["The cash conversion cycle falls, but the change in the working capital balance is not determined.","Working capital must decrease because the cash conversion cycle falls.","Both the working capital balance and cash conversion cycle must increase."],"correct":0,"expl":"The cash conversion cycle falls from 45 + 50 minus 40 = 55 days to 55 + 35 minus 60 = 30 days. Working capital is revenue times receivable days / 365 plus cost of goods sold times (inventory days minus payable days) / 365. Year 1 revenue and cost of goods sold are missing. A shorter cycle alone does not fix the euro balance."},{"session":"Session 9 · Paper LBO","q":"A sponsor buys a target with current EBITDA EUR 80 million. EBITDA grows 3% annually for five years. Entry borrowing is 4.5 times current EBITDA, 60% senior and 40% junior. Operating cash repays all senior principal by the exit date. Junior principal remains outstanding when the sponsor sells its equity, and is repaid after that sale. Interest is paid in cash. Exit enterprise value is 6 times year 5 EBITDA. The sponsor requires a 22% annual equity return. Ignore cash at exit, interim sponsor distributions and transaction costs. What maximum entry enterprise value can it pay?","choices":["About EUR 432.69 million, or 5.41 times current EBITDA.","About EUR 565.89 million, or 7.07 times current EBITDA.","About EUR 512.61 million, or 6.41 times current EBITDA."],"correct":2,"expl":"Entry borrowing is EUR 360 million. Senior principal of EUR 216 million has been repaid at exit, but junior principal of EUR 144 million remains. Year 5 EBITDA is 80 times 1.03^5 = EUR 92.7419 million. Exit enterprise value is EUR 556.4516 million. Exit equity is EUR 412.4516 million. Entry sponsor equity is 412.4516 / 1.22^5 = EUR 152.6068 million. Maximum entry enterprise value is EUR 512.6068 million, or 6.4076 times current EBITDA. Deducting all initial debt at exit ignores the senior repayment. Ignoring junior debt overstates exit equity."},{"session":"Session 6 · Swap cash flows","q":"A company has a EUR 18 million fixed rate loan costing 6.2% a year. It enters a swap on the same principal, paying three month Euribor plus 0.8% and receiving fixed 5.5%. Assume matching payment dates, equal accrual fractions and no fees. What annual all in rate does the loan plus swap produce?","choices":["Euribor plus 0.8%.","Euribor plus 1.5%.","Euribor minus 0.7%."],"correct":1,"expl":"Add external interest and the paid swap leg, then deduct the received swap leg: 6.2% + Euribor + 0.8% minus 5.5% = Euribor plus 1.5%. The fixed legs do not cancel because their rates differ."}],"open":[{"title":"Open question 1 · Bottom up WACC","body":"Neris Group is an unlisted euro area business with two divisions. Estimate its cost of capital using the inputs below. All amounts are in EUR million.\n\n- Equipment servicing contributes 40% of group enterprise value. Its listed peers have average equity beta 1.30 and market debt to equity 0.60.\n- Medical supplies contributes 60% of enterprise value. Its peers have average equity beta 0.90 and market debt to equity 0.25.\n- All peers and Neris pay corporate tax at 25%. Assume zero debt beta and use beta equity = beta asset times [1 + (1 minus tax) times debt/equity].\n- Neris EBIT is 70 and annual interest expense is 14.\n- Neris has a single five year bond with face and book value 350, paying an annual coupon of 14 and returning 350 principal at the end of year 5. There is no cash to net from debt.\n- A recent independent equity transaction implies a market equity value of 600.\n- The risk free euro rate is 4% and the equity market risk premium is 5%.\n- Use this synthetic rating rule. Interest coverage above 6 implies a 1% spread. Coverage above 4 and up to 6 implies a 2% spread. Coverage above 2 and up to 4 implies a 3.5% spread. Coverage at most 2 implies a 6% spread.\n\na) Unlever each division's peer beta and calculate the group's asset beta.\nb) Calculate interest coverage, the current pretax and after tax debt cost, and the bond's market value using the current pretax debt cost as its discount rate.\nc) Relever the group asset beta using market values, then calculate the equity cost using CAPM.\nd) Calculate the group's WACC. Explain why the bond's book value and its old coupon rate must not replace current market inputs.","solution":"a) Servicing asset beta = 1.30 / (1 + 0.75 times 0.60) = 0.896552. Supplies asset beta = 0.90 / (1 + 0.75 times 0.25) = 0.757895. Group asset beta = 40% times servicing beta + 60% times supplies beta = **0.813358**. Business weights are enterprise value weights.\n\nb) Interest coverage = 70 / 14 = **5.0**. The specified spread is 2%, so current pretax debt cost is 4% + 2% = **6.0%**. After tax cost is 6% times 75% = **4.5%**. Market debt value is the present value of five coupons and the final principal: 14 times [1 minus 1.06^(-5)] / 0.06 + 350 / 1.06^5 = **EUR 320.5135 million**.\n\nc) Market debt/equity = 320.5135 / 600 = 0.534189. Equity beta = 0.813358 times [1 + 0.75 times 0.534189] = **1.139223**. Equity cost = 4% + beta times 5% = **9.6961%**.\n\nd) Equity weight = 600 / (600 + 320.5135) = 0.651810. Debt weight is 0.348190. WACC = equity weight times 9.6961% + debt weight times 4.5% = **7.8869%**. The old coupon is 14/350 = 4%, but current lenders require 6%. That higher discount rate places debt below face value. Book debt is not the current capital weight. Round only the final figures."},{"title":"Open question 2 · Forward versus dollar put","body":"A euro area software exporter invoices a certain USD 12 million today, collectible in six months. Its euro budget uses USD 1.18 per EUR. Today spot is USD 1.20 per EUR and the six month forward is USD 1.23 per EUR. All quotes below are USD per EUR.\n\nThe treasury can leave the receipt unhedged, sell all dollars forward, or buy puts on all dollars. The put lets each dollar be exchanged for 1/1.25 euros. Its premium is 2% of the USD notional, paid today in euros at today's spot. The euro premium is borrowed for six months at 4% simple annual interest and repaid at collection. Ignore taxes, fees and counterparty risk.\n\na) Calculate today's euro premium and the amount repaid at collection. Calculate net euro proceeds for all three strategies at maturity spots 1.10 and 1.40. State whether the put is exercised in each case.\nb) Express the option's minimum net receipt per dollar in EUR per USD. Explain why a larger USD per EUR quote is unfavorable to this exporter.\nc) Find the maturity spot where the unexercised option strategy and the forward produce identical net euros. Verify that the put is unexercised at that rate.\nd) Compare all three outcomes with the original budget euro proceeds and explain the tradeoff between certainty, retained upside and the premium cost.","solution":"a) Today's premium is USD 12 million times 2% = USD 0.24 million, converted at 1.20 to **EUR 0.200 million**. Six month financing multiplies this by 1 + 4% times 0.5 = 1.02. Repayment is **EUR 0.204 million**.\n\nAt 1.10, unhedged receipt = 12 / 1.10 = **EUR 10.909091 million**. The put is not exercised because the market pays more euros per dollar than the strike. Its net receipt is 12 / 1.10 minus 0.204 = **EUR 10.705091 million**. Forward receipt = 12 / 1.23 = **EUR 9.756098 million**.\n\nAt 1.40, unhedged receipt = 12 / 1.40 = **EUR 8.571429 million**. The put is exercised. Its net receipt is 12 / 1.25 minus 0.204 = **EUR 9.396000 million**. The forward still gives **EUR 9.756098 million**.\n\nb) Minimum net receipt per USD = 1 / 1.25 minus 0.02 / 1.20 times 1.02 = **EUR 0.783000 per USD**. A larger USD per EUR number buys one euro with more dollars, so a fixed dollar receipt converts into fewer euros. Do not subtract a euro premium from a USD per EUR quote.\n\nc) In the nonexercise region, equality is 12 / S minus 0.204 = 12 / 1.23. Thus S = 12 / (9.756098 + 0.204) = **USD 1.204807 per EUR**. This is below 1.25, so selling dollars at market beats exercising and the assumed region is valid. For S below this break even, the option beats the forward. Above it, the forward wins because even the exercised option floor is below the forward.\n\nd) Budget proceeds are 12 / 1.18 = **EUR 10.169492 million**. At 1.10 both the unhedged receipt and option net receipt exceed budget, while the forward is below budget. At 1.40 all three are below budget. The forward fixes receipts, not necessarily the budget amount. Puts preserve the favorable currency move after paying the premium and set a lower guaranteed net receipt. Remaining unhedged avoids the premium but keeps all downside."}]},"fm-p1-official":{"id":"fm-p1-official","exam":"fm-p1","type":"official","title":"Mock officiel FM et corrigé","sub":"Blackboard · accès Bocconi requis","body":"Documents officiels consultables sur Blackboard. Aucun PDF officiel n’est republié sur class40. Le corrigé contient une ambiguïté sur la dette dans la question ouverte WACC. L’énoncé et le document de solutions ne décrivent pas la dette de façon identique. Les mocks maison donnent des hypothèses explicites pour éviter cette ambiguïté.","links":[{"label":"Ouvrir l’énoncé officiel v2","url":"https://blackboard.unibocconi.it/bbcswebdav/pid-2663202-dt-content-rid-36250205_1/xid-36250205_1"},{"label":"Ouvrir le corrigé officiel v2","url":"https://blackboard.unibocconi.it/bbcswebdav/pid-2663203-dt-content-rid-36229323_1/xid-36229323_1"}]}}},"QCM_LEVELS":{"fm":{"9":[{"id":"fm-s9-level1-v1-q1","session":"9","level":1,"topic":"Entry funding","question":"A buyout target has EBITDA of EUR 80 million and is purchased at 7.5 times EBITDA. Existing debt of EUR 90 million is repaid at closing, and the seller receives enterprise value less that debt. Transaction fees are 2% of enterprise value. New lenders provide EUR 360 million. There is no cash. How much equity must the sponsor invest?","choices":["EUR 252 million.","EUR 162 million.","EUR 240 million.","EUR 342 million."],"correct_index":0,"explanation":"Enterprise value is 80 × 7.5 = 600. Seller proceeds are 510, refinancing is 90 and fees are 12. Uses are 612 and equity is 612 − 360 = 252. Existing debt is not subtracted twice."},{"id":"fm-s9-level1-v1-q2","session":"9","level":1,"topic":"Cash to repay debt","question":"A company has EBITDA of EUR 120 million, depreciation of EUR 20 million, cash interest of EUR 24 million, maintenance investment of EUR 25 million and a EUR 6 million increase in working capital. Cash taxes equal 25% of positive profit after depreciation and interest. All remaining cash repays debt. What is the repayment?","choices":["EUR 41 million.","EUR 46 million.","EUR 65 million.","EUR 70 million."],"correct_index":1,"explanation":"Taxable profit is 120 − 20 − 24 = 76 and taxes are 19. Cash is 120 − 24 − 19 − 25 − 6 = 46. Depreciation reduces taxable profit, not cash directly."},{"id":"fm-s9-level1-v1-q3","session":"9","level":1,"topic":"Exit equity bridge","question":"At exit, EBITDA is EUR 70 million and the enterprise value multiple is 9 times. Gross debt is EUR 250 million and excess cash is EUR 30 million. The sponsor owns all equity and invested EUR 205 million. There are no exit fees or interim distributions. What are equity proceeds and the investment multiple?","choices":["EUR 380 million and 1.85 times.","EUR 630 million and 3.07 times.","EUR 410 million and 2.00 times.","EUR 350 million and 1.71 times."],"correct_index":2,"explanation":"Enterprise value is 630. Net debt is 250 − 30 = 220. Equity proceeds are 630 − 220 = 410 and 410 ÷ 205 = 2.00. Cash is added once."},{"id":"fm-s9-level1-v1-q4","session":"9","level":1,"topic":"Repayment waterfall","question":"A buyout generates EUR 50 million cash before principal repayment. Required repayments are EUR 12 million for Term Loan A and EUR 3 million for Term Loan B. After those repayments, Term Loan A still has EUR 20 million outstanding. All remaining cash sweeps first to Term Loan A then Term Loan B. How much total principal does Term Loan B receive?","choices":["EUR 15 million.","EUR 35 million.","EUR 38 million.","EUR 18 million."],"correct_index":3,"explanation":"Required repayments leave 50 − 12 − 3 = 35. Of this, 20 clears Term Loan A and 15 sweeps to Term Loan B. Including its required 3, Term Loan B receives 18. Total repayments remain 50."},{"id":"fm-s9-level1-v1-q5","session":"9","level":1,"topic":"Entry versus exit valuation","question":"An investor buys a company with EBITDA of EUR 50 million for 8 times EBITDA using EUR 240 million debt and EUR 160 million equity. At exit, EBITDA is EUR 60 million, the multiple is still 8 times, and debt is EUR 180 million. There is no cash or fee. How much is the equity gain, and how much of that gain comes from debt repayment?","choices":["EUR 140 million gain, including EUR 60 million from debt repayment.","EUR 80 million gain, including EUR 60 million from debt repayment.","EUR 140 million gain, including EUR 80 million from debt repayment.","EUR 300 million gain, including EUR 60 million from debt repayment."],"correct_index":0,"explanation":"Exit enterprise value is 480 and equity is 480 − 180 = 300. Gain is 300 − 160 = 140. Operating growth contributes (60 − 50) × 8 = 80, while debt repayment contributes 240 − 180 = 60."},{"id":"fm-s9-level1-v1-q6","session":"9","level":1,"topic":"Annualised return","question":"A sponsor invests EUR 125 million and receives EUR 216 million exactly three years later, with no interim distributions. Which pair correctly reports the multiple on invested capital and internal rate of return?","choices":["1.728 times and 24.3% per year.","1.728 times and 20.0% per year.","0.728 times and 20.0% per year.","1.200 times and 72.8% per year."],"correct_index":1,"explanation":"The multiple is 216 ÷ 125 = 1.728. The annual return solves (1 + r)^3 = 1.728, so r = 20%. Dividing the total gain percentage by three is not compounding."},{"id":"fm-s9-level1-v1-q7","session":"9","level":1,"topic":"Coverage analysis","question":"A company has EBITDA of EUR 96 million, maintenance investment of EUR 24 million, interest of EUR 40 million, debt of EUR 500 million and cash of EUR 20 million. Lenders require net debt divided by EBITDA at most 6 and EBITDA less maintenance investment divided by interest at least 2. Which test fails?","choices":["Only the net leverage test fails.","Both tests fail.","Only the cash interest coverage test fails.","Neither test fails."],"correct_index":2,"explanation":"Net leverage is (500 − 20) ÷ 96 = 5.0, within 6. Cash interest coverage is (96 − 24) ÷ 40 = 1.8, below 2. The EBITDA interest ratio of 2.4 is not the specified coverage test."},{"id":"fm-s9-level1-v1-q8","session":"9","level":1,"topic":"Comparable selection","question":"A private target has EBITDA of EUR 40 million and net debt of EUR 50 million. Three genuinely comparable control acquisitions have enterprise value to EBITDA multiples of 7, 9 and 14. Apply their median. A fourth listed minority stake trades at 5 times but is excluded. What equity value results?","choices":["EUR 270 million.","EUR 360 million.","EUR 350 million.","EUR 310 million."],"correct_index":3,"explanation":"The retained median is 9. Enterprise value is 9 × 40 = 360 and equity is 360 − 50 = 310. Mixing the excluded minority multiple into the median changes the valuation basis."},{"id":"fm-s9-level1-v1-q9","session":"9","level":1,"topic":"Floating loan pricing","question":"A Term Loan B has EUR 200 million opening principal. Its reference rate is floored at 1.5%, observed reference rate is 0.8%, and its spread is 2.5%. Interest uses opening principal. Required principal repayment is 1% of original principal. Cash before interest and principal, after taxes and investment, is EUR 28 million. All remaining cash repays this loan. What is closing debt?","choices":["EUR 180 million.","EUR 178 million.","EUR 178.6 million.","EUR 182 million."],"correct_index":0,"explanation":"Coupon is max(0.8%, 1.5%) + 2.5% = 4%, so interest is 8. Total principal repayment is 28 − 8 = 20, including the required 2. Closing debt is 180. The required repayment is not extra cash."},{"id":"fm-s9-level1-v1-q10","session":"9","level":1,"topic":"Leverage and downside","question":"A company is bought for EUR 300 million using EUR 210 million debt and EUR 90 million equity. It is later sold for EUR 240 million, with debt still EUR 210 million and no cash or distributions. An unlevered investor would have lost 20% on the same business. What is the leveraged sponsor loss?","choices":["20.0% of the initial equity.","66.7% of the initial equity.","33.3% of the initial equity.","85.7% of the initial equity."],"correct_index":1,"explanation":"Exit equity is 240 − 210 = 30. Loss is 90 − 30 = 60 and 60 ÷ 90 = 66.7%. Debt magnifies the loss, even though enterprise value falls only 20%."},{"id":"fm-s9-level2-v1-q1","session":"9","level":2,"topic":"Two year debt roll forward","question":"A buyout starts with EUR 300 million debt. For each of the next two years EBITDA is EUR 100 million, depreciation EUR 20 million, maintenance investment EUR 20 million and working capital change zero. Interest is 10% of opening debt. Taxes are 25% of profit after depreciation and interest. All available cash repays debt at year end. What is debt after year 2?","choices":["EUR 225.0000 million.","EUR 219.3750 million.","EUR 222.1875 million.","EUR 212.5000 million."],"correct_index":2,"explanation":"Year 1 interest 30, tax 12.5 and cash 37.5 leave debt 262.5. Year 2 interest 26.25, taxable profit 53.75, tax 13.4375 and cash 40.3125 leave 222.1875. Retain precision between years."},{"id":"fm-s9-level2-v1-q2","session":"9","level":2,"topic":"Full entry to exit","question":"A target has entry EBITDA of EUR 40 million and costs 8 times EBITDA. Existing debt is EUR 50 million, no cash, and it is refinanced at closing. Fees are EUR 10 million and new debt is EUR 200 million. EBITDA grows 10% annually for two years. At exit, the multiple is 9 times and debt is EUR 150 million. There are no other cash flows. What is the investment multiple?","choices":["Approximately 2.38 times.","Approximately 2.86 times.","Approximately 1.97 times.","Approximately 2.20 times."],"correct_index":3,"explanation":"Enterprise value at entry is 320. Seller 270 plus refinance 50 plus fees 10 means uses 330 and equity 130. Exit EBITDA is 40 × 1.1^2 = 48.4. Exit equity is 48.4 × 9 − 150 = 285.6. Multiple is 285.6 ÷ 130 = 2.1969."},{"id":"fm-s9-level2-v1-q3","session":"9","level":2,"topic":"Repayment of two loans","question":"Opening Term Loan A is EUR 90 million and Term Loan B EUR 160 million. EBITDA is EUR 100 million, depreciation EUR 10 million, interest EUR 20 million, maintenance investment EUR 15 million and working capital increase EUR 5 million. Taxes equal 30% of positive pretax profit. Required principal repayments are 18 for Loan A and 2 for Loan B. All remaining cash sweeps to Loan A. What are closing balances?","choices":["Loan A EUR 53 million and Loan B EUR 158 million.","Loan A EUR 35 million and Loan B EUR 158 million.","Loan A EUR 51 million and Loan B EUR 160 million.","Loan A EUR 72 million and Loan B EUR 139 million."],"correct_index":0,"explanation":"Tax is (100 − 10 − 20) × 30% = 21. Cash is 100 − 20 − 21 − 15 − 5 = 39. Required payments use 20, leaving a sweep of 19. Loan A ends at 90 − 18 − 19 = 53 and B at 158."},{"id":"fm-s9-level2-v1-q4","session":"9","level":2,"topic":"Return target and price ceiling","question":"A sponsor expects EUR 432 million equity proceeds after three years and requires 20% annual return. The acquisition will use EUR 300 million debt. Fees are 2% of entry enterprise value. There is no existing debt or cash and no interim distribution. What is the maximum entry enterprise value?","choices":["Approximately EUR 550.00 million.","Approximately EUR 539.22 million.","Approximately EUR 545.00 million.","Approximately EUR 423.53 million."],"correct_index":1,"explanation":"Maximum equity is 432 ÷ 1.2^3 = 250. Funding required is 1.02 × enterprise value and funding available is 250 + 300 = 550. Maximum enterprise value is 550 ÷ 1.02 = 539.2157. This discounts equity proceeds, not operating cash flows."},{"id":"fm-s9-level2-v1-q5","session":"9","level":2,"topic":"Growth and multiple compression","question":"A sponsor invests EUR 200 million in a company purchased for EUR 500 million with EUR 300 million debt. Entry EBITDA is EUR 50 million. After five years, EBITDA is EUR 70 million, the sale multiple is 8 times and debt is EUR 200 million. No cash or dividends. Relative to valuing operating growth at the entry multiple and then multiple change on exit EBITDA, what explains the EUR 160 million equity gain?","choices":["Growth adds 200, multiple compression subtracts 100, and debt repayment adds 60.","Growth adds 160, multiple compression subtracts 100, and debt repayment adds 100.","Growth adds 200, multiple compression subtracts 140, and debt repayment adds 100.","Growth adds 200, multiple compression subtracts 140, and debt repayment adds 200."],"correct_index":2,"explanation":"Entry multiple is 10. Growth adds (70 − 50) × 10 = 200. Multiple compression adds (8 − 10) × 70 = −140. Debt repayment adds 100. Sum 160 matches exit equity 70 × 8 − 200 = 360 less investment 200."},{"id":"fm-s9-level2-v1-q6","session":"9","level":2,"topic":"Early exit comparison","question":"A sponsor invests EUR 100 million. There are no interim cash flows. Sale after year 3 produces enterprise value of EUR 300 million with EUR 150 million debt. Sale after year 4 produces enterprise value of EUR 320 million with EUR 120 million debt. No cash or fees. Which outcome is correct?","choices":["Year 3 gives the higher annual return because the holding period is shorter.","Year 4 gives 2.00 times but only 16.7% annual return.","Year 3 gives 3.00 times and about 44.2% annual return.","Year 4 gives 2.00 times and about 18.9% annual return, both above year 3."],"correct_index":3,"explanation":"Year 3 equity is 150, multiple 1.5 and annual return 1.5^(1/3) − 1 = 14.47%. Year 4 equity is 200, multiple 2 and annual return 2^(1/4) − 1 = 18.92%. A shorter hold does not dominate when proceeds differ."},{"id":"fm-s9-level2-v1-q7","session":"9","level":2,"topic":"Working capital release","question":"Revenue falls from EUR 500 million to EUR 450 million. EBITDA margin is 20%, depreciation EUR 15 million and maintenance investment EUR 18 million. Net working capital stays at 10% of revenue. Opening debt is EUR 200 million at 8% interest, and taxes are 25% of positive pretax profit. All cash repays debt. What is closing debt?","choices":["EUR 153.75 million.","EUR 163.75 million.","EUR 158.75 million.","EUR 148.75 million."],"correct_index":0,"explanation":"EBITDA is 90, interest 16 and taxes (90 − 15 − 16) × 25% = 14.75. Working capital falls by 5, releasing cash. Repayment is 90 − 16 − 14.75 − 18 + 5 = 46.25, leaving 153.75."},{"id":"fm-s9-level2-v1-q8","session":"9","level":2,"topic":"Net debt and exit fee","question":"Exit EBITDA is EUR 75 million and the enterprise value multiple is 8 times. Gross debt is EUR 240 million, excess cash EUR 40 million and exit fees 2% of enterprise value. Initial equity is EUR 160 million. There are no other receipts. What multiple does the sponsor earn?","choices":["2.500 times.","2.425 times.","2.175 times.","2.625 times."],"correct_index":1,"explanation":"Enterprise value is 600. Fees are 12. Equity proceeds are 600 − 240 + 40 − 12 = 388. Divide by 160 to get 2.425. Fees apply to enterprise value and cash is added only once."},{"id":"fm-s9-level2-v1-q9","session":"9","level":2,"topic":"Choose a financing structure","question":"Two structures finance the same EUR 400 million purchase. Structure A uses EUR 200 million debt and EUR 200 million equity. Structure B uses debt 280 and equity 120. Forecast exit enterprise value is EUR 500 million. After interest and all repayments, exit debt is 150 under A and 250 under B. No cash or dividends. Which comparison is correct?","choices":["A has the higher equity multiple because its equity proceeds are larger.","B has an equity multiple of 2.92 versus 1.75 for A.","B has the higher equity multiple, about 2.08 versus 1.75.","Both have the same multiple because enterprise value is identical."],"correct_index":2,"explanation":"A receives 500 − 150 = 350, or 1.75 times 200. B receives 250, or 2.0833 times 120. The larger debt burden leaves B with less cash proceeds but a smaller original equity investment. It also carries greater downside risk."},{"id":"fm-s9-level2-v1-q10","session":"9","level":2,"topic":"Covenant and investment capacity","question":"Debt is EUR 480 million, cash EUR 20 million, EBITDA EUR 100 million and interest EUR 40 million. Net leverage must not exceed 5 and cash interest coverage, defined as EBITDA less maintenance investment divided by interest, must be at least 1.8. No repayment occurs before testing. What is the maximum maintenance investment compatible with both tests?","choices":["EUR 20 million.","EUR 44 million.","EUR 32 million.","EUR 28 million."],"correct_index":3,"explanation":"Net leverage is 460 ÷ 100 = 4.6, within 5. Coverage requires (100 − investment) ÷ 40 ≥ 1.8, hence investment ≤ 28. Testing EBITDA divided by interest alone would miss the investment constraint."},{"id":"fm-s9-level3-v1-q1","session":"9","level":3,"topic":"Solve circular interest","question":"A company starts a year with EUR 200 million debt at 10% interest on the average of opening and closing debt. EBITDA is EUR 80 million, depreciation 10, maintenance investment 10 and working capital change zero. Cash taxes are 25% of profit after depreciation and interest. All cash after interest, tax and investment repays debt at year end. What is closing debt, retaining full precision?","choices":["Approximately EUR 161.04 million.","Approximately EUR 162.50 million.","Approximately EUR 157.14 million.","Approximately EUR 158.44 million."],"correct_index":0,"explanation":"Let repayment be P. Average debt is 200 − P/2, interest is 20 − 0.05P, and tax is 25% × (70 − interest). Cash equals 52.5 − 0.75 × interest = 37.5 + 0.0375P. Thus 0.9625P = 37.5, P = 38.9610 and closing debt = 161.0390."},{"id":"fm-s9-level3-v1-q2","session":"9","level":3,"topic":"Entry price with leverage linked to price","question":"A sponsor expects EUR 600 million equity proceeds in five years and requires 20% annual return. Lenders will fund 60% of entry enterprise value, not 60% of total uses. Fees are 2% of enterprise value. There is no old debt, cash or interim distribution. What is the maximum entry enterprise value?","choices":["Approximately EUR 602.82 million.","Approximately EUR 574.11 million.","Approximately EUR 590.50 million.","Approximately EUR 241.13 million."],"correct_index":1,"explanation":"Required initial equity is 600 ÷ 1.2^5 = 241.1265. Equity funds 1.02V − 0.60V = 0.42V. Therefore V = 241.1265 ÷ 0.42 = 574.1107. Funding fees with the wrong debt percentage changes the answer."},{"id":"fm-s9-level3-v1-q3","session":"9","level":3,"topic":"Minimum exit EBITDA","question":"A sponsor invests EUR 150 million and needs a 25% annual return over four years. Forecast exit debt is EUR 180 million and excess cash EUR 20 million. Exit fees equal 2% of enterprise value and the sale multiple is 8 times EBITDA. There are no interim receipts. What minimum exit EBITDA is required?","choices":["Approximately EUR 65.78 million.","Approximately EUR 62.12 million.","Approximately EUR 67.12 million.","Approximately EUR 69.78 million."],"correct_index":2,"explanation":"Required equity is 150 × 1.25^4 = 366.2109. Exit equity is 0.98 × 8 × EBITDA − 180 + 20. Thus EBITDA = (366.2109 + 160) ÷ 7.84 = 67.1187. Fees apply before the debt and cash bridge."},{"id":"fm-s9-level3-v1-q4","session":"9","level":3,"topic":"Two year integrated buyout","question":"Entry EBITDA is EUR 50 million and the purchase multiple is 8. New debt is EUR 250 million and fees EUR 10 million. No existing debt or cash. For years 1 and 2 EBITDA is 60 then 70, depreciation and maintenance investment are each 10 per year, and working capital rises 5 per year. Interest is 8% of opening debt, tax is 25% of positive pretax profit, and all available cash repays debt. Sell at 7 times year 2 EBITDA with no exit fee or cash. What is the two year annual equity return?","choices":["Approximately 29.90%.","Approximately 36.01%.","Approximately 43.37%.","Approximately 33.12%."],"correct_index":3,"explanation":"Initial equity is 400 + 10 − 250 = 160. Year 1 interest 20, tax 7.5, cash 17.5, debt 232.5. Year 2 interest 18.6, tax 10.35, cash 26.05, debt 206.45. Exit equity is 490 − 206.45 = 283.55. Return is (283.55 ÷ 160)^(1/2) − 1 = 33.1235%, approximately 33.12%."},{"id":"fm-s9-level3-v1-q5","session":"9","level":3,"topic":"Downside equity survival","question":"A company is acquired with EBITDA of EUR 100 million at 9 times EBITDA. Debt is EUR 630 million, equity EUR 270 million, and there are no fees or cash. By exit, EUR 90 million of debt has been repaid. Exit EBITDA falls 20% from entry. What minimum exit multiple preserves the sponsor initial equity, with no other distributions?","choices":["10.125 times.","9.000 times.","6.750 times.","11.250 times."],"correct_index":0,"explanation":"Exit EBITDA is 80 and remaining debt 540. To preserve equity 270, enterprise value must be 810. The multiple must be 810 ÷ 80 = 10.125. Merely covering debt at 6.75 times avoids zero equity but does not preserve the investment."},{"id":"fm-s9-level3-v1-q6","session":"9","level":3,"topic":"Debt capacity from two constraints","question":"A company has EBITDA of EUR 120 million, depreciation EUR 20 million, maintenance investment EUR 20 million and zero working capital change. New debt bears 8% interest on opening principal. Taxes are 25% of positive profit after depreciation and interest. Lenders require opening debt at most 5 times EBITDA and annual cash available for principal repayment at least 10% of opening debt. No other debt or cash exists. What is maximum debt?","choices":["EUR 600.00 million.","EUR 468.75 million.","EUR 562.50 million.","EUR 500.00 million."],"correct_index":1,"explanation":"Cash for principal is 120 − 20 − 0.08D − 0.25(100 − 0.08D) = 75 − 0.06D. Requiring at least 0.10D gives 75 ≥ 0.16D, or D ≤ 468.75. The leverage cap is 600, so repayment capacity is tighter. Taxable income remains positive at the solution."},{"id":"fm-s9-level3-v1-q7","session":"9","level":3,"topic":"Full cash sweep with fixed notes","question":"A company has a EUR 100 million secured loan at 6% on opening debt and EUR 200 million fixed notes at 10%. EBITDA is 90, depreciation 10, maintenance investment 15 and working capital increase 5, all in millions of euros. Taxes are 25% of positive profit after depreciation and interest. Required loan repayment is 5. All additional cash sweeps to the loan, never the notes. What are closing loan and notes, and excess cash?","choices":["Loan 64.5, notes 200 and cash zero.","Loan 95.0, notes 174.5 and cash zero.","Loan 69.5, notes 200 and cash zero.","Loan 69.5, notes 195 and cash 5.0."],"correct_index":2,"explanation":"Interest is 100 × 6% + 200 × 10% = 26. Taxes are (90 − 10 − 26) × 25% = 13.5. Cash is 90 − 26 − 13.5 − 15 − 5 = 30.5. This includes required repayment 5 plus sweep 25.5. The loan ends at 69.5, notes remain 200, and cash is zero."},{"id":"fm-s9-level3-v1-q8","session":"9","level":3,"topic":"Combined operating downside and repricing","question":"Opening debt is EUR 400 million at reference rate plus 3%, with a 2% reference rate floor. Baseline revenue is EUR 600 million. In the downside, revenue falls 10%, EBITDA margin is 15%, observed reference rate is 4%, depreciation EUR 12 million and maintenance investment EUR 15 million. Working capital is 10% of revenue and falls from its baseline level. Tax is 25% of positive pretax profit. All cash repays debt. What is closing debt?","choices":["EUR 379.25 million.","EUR 361.25 million.","EUR 359.25 million.","EUR 366.25 million."],"correct_index":3,"explanation":"Revenue becomes 540 and EBITDA 81. Coupon is max(4%, 2%) + 3% = 7%, interest 28. Taxes are (81 − 12 − 28) × 25% = 10.25. Working capital releases 6. Repayment is 81 − 28 − 10.25 − 15 + 6 = 33.75, so closing debt is 366.25."},{"id":"fm-s9-level3-v1-q9","session":"9","level":3,"topic":"Net cash after loan fully repaid","question":"A company begins the final hold year with a EUR 20 million loan and EUR 100 million bullet notes. Cash available after interest, taxes and investment but before principal is EUR 45 million. Required loan repayment of EUR 2 million is included in this amount. All remaining cash first clears the loan and then accumulates as excess cash. Notes cannot be swept. Exit enterprise value is EUR 350 million and initial sponsor equity was EUR 125 million. No exit fee or prior distribution. What is the exit equity multiple?","choices":["2.20 times.","2.00 times.","2.36 times.","2.184 times."],"correct_index":0,"explanation":"Of 45 cash, 20 clears the entire loan including the required 2, leaving 25 excess cash. Notes remain 100. Exit equity is 350 − 100 + 25 = 275 and the multiple is 275 ÷ 125 = 2.20. Cash is not used to repay notes and also added to equity."},{"id":"fm-s9-level3-v1-q10","session":"9","level":3,"topic":"Break even growth with multiple compression","question":"Entry EBITDA is EUR 80 million and enterprise value is 9 times EBITDA. Funding is EUR 480 million debt and EUR 240 million equity, with no fees or cash. After three years, debt will be EUR 360 million and the exit multiple 7.5 times. With no distributions or excess cash, what minimum annual EBITDA growth preserves the original equity investment?","choices":["Approximately 6.27% per year.","0.00% per year.","Approximately 9.54% per year.","Approximately negative 5.90% per year."],"correct_index":1,"explanation":"Preserving equity 240 requires exit enterprise value 240 + 360 = 600. At 7.5 times, required EBITDA is 600 ÷ 7.5 = 80, equal to entry. Debt repayment of 120 offsets multiple compression of (9 − 7.5) × 80 = 120, so no growth is needed."}],"7":[{"id":"fm-s7-level1-v1-q1","session":"7","level":1,"topic":"Market weights and tax","question":"A company has market equity of EUR 150 million and market debt of EUR 100 million. Book equity is EUR 80 million. Its cost of equity is 12%, current pretax borrowing cost 6% and marginal tax rate 25%. Using market weights, what is the weighted average cost of capital?","choices":["9.00%.","8.67%.","9.60%.","10.00%."],"correct_index":0,"explanation":"Debt weight is 100/250 = 40% and equity weight 60%. After tax debt cost is 6% × 75% = 4.5%. Weighted cost is 60% × 12% + 40% × 4.5% = 9%. Book equity is irrelevant to the weights."},{"id":"fm-s7-level1-v1-q2","session":"7","level":1,"topic":"Premium versus market return","question":"A share has beta 1.3. The risk free rate is 3% and the expected market return 8%. Using the capital asset pricing model, what equity return is required, and what premium above the risk free rate does it contain?","choices":["13.4% return and 10.4% equity risk premium.","9.5% return and 6.5% equity risk premium.","10.4% return and 7.4% equity risk premium.","8.0% return and 5.0% equity risk premium."],"correct_index":1,"explanation":"The market premium is 8% − 3% = 5%, not 8%. The stock premium is 1.3 × 5% = 6.5% and required return is 3% + 6.5% = 9.5%."},{"id":"fm-s7-level1-v1-q3","session":"7","level":1,"topic":"Unlever a comparable","question":"A comparable has equity beta 1.5, market debt of EUR 60 million and market equity of EUR 100 million. Its marginal tax rate is 25%. Assume zero debt beta and use beta equity = beta assets × [1 + (1 − tax) × debt/equity]. What is its asset beta?","choices":["Approximately 0.9375.","Approximately 1.3043.","Approximately 1.0345.","Approximately 2.1750."],"correct_index":2,"explanation":"The leverage factor is 1 + 0.75 × 0.6 = 1.45. Asset beta is 1.5/1.45 = 1.03448. Divide to remove financing risk, rather than multiplying or using debt as a fraction of total capital."},{"id":"fm-s7-level1-v1-q4","session":"7","level":1,"topic":"Relever to target weights","question":"A private business has asset beta 0.8. Its target debt share of total market capital is 40%, with equity 60%. Tax rate is 25% and debt beta zero. Use the standard tax adjusted relevering formula. What equity beta and cost of equity result if the risk free rate is 3% and market risk premium 5%?","choices":["Beta 1.04 and cost of equity 8.20%.","Beta 0.80 and cost of equity 7.00%.","Beta 1.40 and cost of equity 10.00%.","Beta 1.20 and cost of equity 9.00%."],"correct_index":3,"explanation":"Debt/equity is 40/60 = 2/3. Equity beta is 0.8 × [1 + 0.75 × 2/3] = 1.2. Required equity return is 3% + 1.2 × 5% = 9%."},{"id":"fm-s7-level1-v1-q5","session":"7","level":1,"topic":"Current debt cost","question":"A bond has a 4% coupon but the company can currently borrow at a government base rate of 3% plus a default spread of 2.5%. The marginal tax rate is 30%, with fully usable interest deductions. Which pretax and after tax debt costs belong in the current weighted cost of capital?","choices":["5.50% pretax and 3.85% after tax.","4.00% pretax and 2.80% after tax.","5.50% pretax and 1.65% after tax.","2.50% pretax and 1.75% after tax."],"correct_index":0,"explanation":"Use the current required borrowing yield, 3% + 2.5% = 5.5%, not the historical coupon. The after tax cost is 5.5% × (1 − 30%) = 3.85%."},{"id":"fm-s7-level1-v1-q6","session":"7","level":1,"topic":"Total returns and beta data","question":"A stock starts a month at EUR 50 and ends at EUR 49, paying a EUR 2 dividend during that month. Its market index total return is 1%. What stock return should enter a regression on that market total return, and what is the difference from using price return alone?","choices":["Negative 2%, with no dividend adjustment.","2%, which is 4 percentage points above price return.","4%, which is 6 percentage points above price return.","6%, which is 8 percentage points above price return."],"correct_index":1,"explanation":"Total return is (49 − 50 + 2)/50 = 2%. Price return alone is (49 − 50)/50 = −2%. Ignoring the dividend understates the observation by 4 percentage points."},{"id":"fm-s7-level1-v1-q7","session":"7","level":1,"topic":"Coverage based debt spread","question":"A company has operating profit of EUR 48 million and interest expense EUR 12 million. A supplied synthetic rating table assigns a 1.5% spread when interest coverage is at least 4, and a 3% spread below 4. The risk free rate is 3% and tax rate 25%. What after tax borrowing cost follows?","choices":["4.500%.","4.875%.","3.375%.","2.250%."],"correct_index":2,"explanation":"Coverage is 48/12 = 4, so the inclusive at least 4 band gives a 1.5% spread. Pretax debt cost is 4.5%, and after tax it is 4.5% × 75% = 3.375%."},{"id":"fm-s7-level1-v1-q8","session":"7","level":1,"topic":"Historical premium uncertainty","question":"Annual market excess returns have standard deviation 24%. Assume independent annual observations and use standard error = standard deviation divided by square root of years. How much history is required for a 3 percentage point standard error, and what is the error with only 16 years?","choices":["8 years, and 1.5 percentage points with 16 years.","64 years, and 1.5 percentage points with 16 years.","32 years, and 6 percentage points with 16 years.","64 years, and 6 percentage points with 16 years."],"correct_index":3,"explanation":"Solve 24%/sqrt(n) = 3%, so sqrt(n)=8 and n=64. With 16 years, 24%/4 = 6%. More observations reduce sampling error but do not remove survivorship or structural bias."},{"id":"fm-s7-level1-v1-q9","session":"7","level":1,"topic":"Infer the market premium","question":"A stock equity beta is 1.4 and its required return is 11.4%. The matching risk free rate is 3%. If a second stock has beta 0.9 in the same market, what return does the model require for that second stock?","choices":["8.4%.","7.56%.","10.56%.","9.0%."],"correct_index":0,"explanation":"Market premium is (11.4% − 3%)/1.4 = 6%. The second return is 3% + 0.9 × 6% = 8.4%. Do not scale the risk free part with beta."},{"id":"fm-s7-level1-v1-q10","session":"7","level":1,"topic":"Risk free consistency","question":"A company prepares nominal euro forecasts over a long horizon. An analyst uses a dollar government rate and then adds the full euro sovereign spread as though it were a market equity premium. What is the most direct correction before computing the equity cost?","choices":["Keep the dollar rate because government rates are interchangeable across currencies.","Use a suitable default free euro rate and a separately estimated consistent equity market premium.","Keep the euro sovereign yield and treat its whole level as the market equity premium.","Use the short term dollar rate and multiply both rate and premium by the equity beta."],"correct_index":1,"explanation":"The risk free input must match the currency and horizon of the cash flows and exclude default risk. The equity market premium is excess expected equity return, not a sovereign yield or an arbitrary cross currency spread."},{"id":"fm-s7-level2-v1-q1","session":"7","level":2,"topic":"Bottom up complete weighted cost","question":"Two peers have equity betas 1.2 and 1.5, debt/equity ratios 0.5 and 1.0, and tax rates of 20% each. Assume zero debt beta and average their unlevered betas equally. A target uses debt/equity 0.75, tax 25%, risk free rate 3%, market risk premium 5% and debt cost 6%. What is its weighted cost of capital?","choices":["Approximately 7.602%.","Approximately 8.274%.","Approximately 7.416%.","Approximately 6.406%."],"correct_index":2,"explanation":"Peer asset betas are 1.2/1.4 = 0.857143 and 1.5/1.8 = 0.833333, averaging 0.845238. Target equity beta is 0.845238 × 1.5625 = 1.320685. Equity cost is 9.603423%. With equity weight 1/1.75 and debt weight .75/1.75, weighted cost is 7.41624%."},{"id":"fm-s7-level2-v1-q2","session":"7","level":2,"topic":"Correct book weight error","question":"An analyst reports weighted cost of capital of 8.0% using equal book weights, equity cost 12% and after tax debt cost 4%. Actual market equity is EUR 300 million and debt EUR 100 million. What is the corrected rate and the size of the original understatement?","choices":["9.0%, understated by 1.0 percentage point.","8.0%, with no correction required.","11.0%, understated by 3.0 percentage points.","10.0%, understated by 2.0 percentage points."],"correct_index":3,"explanation":"Market equity weight is 75% and debt weight 25%. Correct rate is .75 × 12% + .25 × 4% = 10%. The 8% book weighted result understated the hurdle by 2 percentage points."},{"id":"fm-s7-level2-v1-q3","session":"7","level":2,"topic":"New capital structure and spread","question":"A firm has asset beta 0.9, zero debt beta and tax rate 25%. It changes debt share from 20% to 50% of total market capital. At 20% debt its borrowing cost is 4%, at 50% debt it is 7%. Risk free rate is 3%, market risk premium 5%. What is weighted cost of capital at 50% debt?","choices":["8.0625%.","7.3125%.","6.7500%.","9.3750%."],"correct_index":0,"explanation":"Debt/equity at 50% debt is 1. Equity beta is .9 × 1.75 = 1.575 and cost of equity is 10.875%. Weighted cost is .5 × 10.875% + .5 × 7% × .75 = 8.0625%. Repricing debt must not be omitted."},{"id":"fm-s7-level2-v1-q4","session":"7","level":2,"topic":"Reverse engineer beta","question":"A firm has weighted cost of capital 8%, market debt weight 40%, pretax debt cost 5% and tax rate 25%. Risk free rate is 3% and market risk premium 5%. What equity beta is implied?","choices":["Approximately 1.0667.","Approximately 1.5667.","Approximately 1.3000.","Approximately 2.1667."],"correct_index":1,"explanation":"Debt contribution is .4 × 5% × .75 = 1.5%. Equity cost solves .6 × cost = 8% − 1.5%, giving 10.8333%. Beta is (10.8333% − 3%)/5% = 1.56667."},{"id":"fm-s7-level2-v1-q5","session":"7","level":2,"topic":"Business mix asset beta","question":"A group has two business segments worth EUR 120 million and EUR 180 million at market value. Their asset betas are 0.6 and 1.2. Group debt/equity is 0.8 and tax rate 25%, with zero debt beta. Risk free rate is 2.5% and market premium 6%. What group equity cost follows?","choices":["11.140%.","8.260%.","11.716%.","12.100%."],"correct_index":2,"explanation":"Weighted asset beta is .4 × .6 + .6 × 1.2 = .96. Equity beta is .96 × (1 + .75 × .8) = 1.536. Equity cost is 2.5% + 1.536 × 6% = 11.716%."},{"id":"fm-s7-level2-v1-q6","session":"7","level":2,"topic":"New issue yield versus coupon","question":"A firm can issue debt with a 3% coupon at a market price of 90 per 100 of principal. A supplied market yield to maturity is 5.5%. Market debt weight is 30%, equity cost 11% and tax rate 20%. What weighted cost of capital should be used, with fully usable deductions?","choices":["8.42%.","9.35%.","8.60%.","9.02%."],"correct_index":3,"explanation":"The borrowing opportunity cost is the supplied 5.5% market yield. After tax it is 4.4%. Weighted cost is .7 × 11% + .3 × 4.4% = 9.02%. The coupon does not reflect the discount issue price."},{"id":"fm-s7-level2-v1-q7","session":"7","level":2,"topic":"Peer tax mismatch","question":"Peer A has equity beta 1.4, debt/equity 0.5 and tax 20%. Peer B has equity beta 1.5, debt/equity 1 and tax 50%. Assume zero debt beta. Use the equal average of correctly unlevered peer betas. A target has debt/equity 0.6 and tax 25%. What is target equity beta?","choices":["1.45.","1.53.","1.35.","1.61."],"correct_index":0,"explanation":"Peer A asset beta is 1.4/(1+.8×.5)=1.0. Peer B asset beta is 1.5/(1+.5×1)=1.0. Average is 1. Target beta is 1×(1+.75×.6)=1.45. Use each peer own tax when unlevering."},{"id":"fm-s7-level2-v1-q8","session":"7","level":2,"topic":"Portfolio beta and financing","question":"A company has market asset value EUR 500 million, including EUR 100 million excess cash with beta zero. Its measured whole asset beta is 0.8. Remove cash before estimating the operating risk. The operating business target debt/equity is 0.5 and tax rate 20%, debt beta zero. What operating equity beta results?","choices":["1.12.","1.40.","1.00.","1.60."],"correct_index":1,"explanation":"Whole asset beta is .8 × operating beta + .2 × zero. Operating beta is .8/.8 = 1.0. Relever operating beta using 1+.8×.5 = 1.4. Applying leverage directly to the cash diluted beta understates operating equity risk."},{"id":"fm-s7-level2-v1-q9","session":"7","level":2,"topic":"Hurdle by business risk","question":"A group has average equity beta 1.0, but a new project has asset beta 1.2 and target debt/equity 0.5. Tax is 25%, debt beta zero, risk free rate 3%, market premium 5% and project debt cost 6%. What project weighted cost of capital follows?","choices":["7.00%.","9.75%.","9.00%.","10.50%."],"correct_index":2,"explanation":"Project equity beta is 1.2 × (1+.75×.5)=1.65. Cost of equity is 11.25%. Debt weight is 1/3 and equity 2/3. Weighted cost is (2/3)×11.25%+(1/3)×4.5%=9.0%. Group equity beta is not the project risk."},{"id":"fm-s7-level2-v1-q10","session":"7","level":2,"topic":"Debt spread sensitivity","question":"A firm has debt weight 35%, marginal tax 30% and equity cost unchanged. Its risk free rate and all capital weights stay fixed, but its default spread widens 1.2 percentage points. All interest deductions are usable. By how many percentage points does its weighted cost of capital rise?","choices":["0.420 percentage points.","0.840 percentage points.","0.126 percentage points.","0.294 percentage points."],"correct_index":3,"explanation":"Only the debt contribution changes: .35 × 1.2 × (1−.30) = .294 percentage points. This exercise holds equity risk and weights fixed, unlike a full recapitalisation model."},{"id":"fm-s7-level3-v1-q1","session":"7","level":3,"topic":"Solve target leverage from hurdle","question":"A business has asset beta 0.8, zero debt beta, tax rate 25%, risk free rate 3% and market premium 6%. Pretax debt cost stays at 5% over the relevant range. Use the tax adjusted relevering formula and market weights. What debt/equity ratio produces weighted cost of capital exactly 7%?","choices":["No nonnegative debt/equity ratio attains 7%.","Debt/equity approximately 1.0323.","Debt/equity approximately 0.5080.","Debt/equity approximately 1.6000."],"correct_index":0,"explanation":"Let x=D/E. Equity cost is 3%+.8(1+.75x)×6%=7.8%+3.6%x. Weighted cost is [7.8%+(3.6%+3.75%)x]/(1+x). This approaches 7.35%, so 7% is not attainable for nonnegative leverage. No nonnegative debt/equity ratio works."},{"id":"fm-s7-level3-v1-q2","session":"7","level":3,"topic":"Circular synthetic debt rating","question":"A business has operating profit EUR 60 million and debt EUR 200 million. A supplied rating rule gives a 4% borrowing rate when operating profit divided by interest is at least 6, otherwise 7%. Interest is debt times the assigned rate. What rates are internally consistent with this rule?","choices":["Only 4% is consistent because coverage would be 7.5.","Both 4% and 7% are self consistent, so the rule alone does not select a unique rate.","Only 7% is consistent because coverage would be below 6.","Neither rate is consistent, so the firm cannot borrow."],"correct_index":1,"explanation":"At 4%, interest is 8 and coverage 7.5, supporting 4%. At 7%, interest is 14 and coverage about 4.286, supporting 7%. The circular rating rule has two fixed points. More market or rating information is needed."},{"id":"fm-s7-level3-v1-q3","session":"7","level":3,"topic":"Reconstruct segment risk","question":"A group has market equity EUR 360 million and debt EUR 240 million, tax 25%, equity beta 1.65 and zero debt beta. Segment A is 40% of operating asset value and has asset beta 0.8. Segment B is 60%. There is no cash. What is segment B asset beta?","choices":["Approximately 1.0333.","Approximately 1.6333.","Approximately 1.3000.","Approximately 1.1000."],"correct_index":2,"explanation":"Group asset beta is 1.65/[1+.75×(240/360)] = 1.1. Solve 1.1=.4×.8+.6×beta B, giving beta B=1.3. Unlever the group before inferring the operating business mix."},{"id":"fm-s7-level3-v1-q4","session":"7","level":3,"topic":"Find maximum business risk","question":"A project is funded with 40% debt and 60% equity. Tax is 25%, risk free rate 3%, market premium 5%, pretax debt cost 6% and debt beta zero. The maximum acceptable weighted cost of capital is 9%. Under the tax adjusted relevering formula, what is the maximum project asset beta?","choices":["1.80.","1.32.","1.00.","1.20."],"correct_index":3,"explanation":"Debt/equity is 2/3. Equity beta is 1.5×asset beta. Weighted cost is .6×(3%+7.5%×asset beta)+.4×4.5%=3.6%+4.5%×asset beta. Setting 9% yields asset beta 1.2."},{"id":"fm-s7-level3-v1-q5","session":"7","level":3,"topic":"Leverage under spread jump","question":"A company has asset beta 1.0 and debt beta zero. Tax rate is 30%, risk free rate 3%, market premium 6%. Candidate debt weights are 20%, 40% and 60%, with pretax debt costs respectively 4%, 5% and 9%. Relever beta separately at each mix. Which has the lowest weighted cost of capital?","choices":["40% debt, with weighted cost 8.48%.","20% debt, with weighted cost 9.04%.","60% debt, with weighted cost 8.10%.","All three have the same weighted cost of capital."],"correct_index":0,"explanation":"At 20% debt, equity beta 1.175 and equity cost 10.05%, weighted cost 8.60%. At 40%, beta 1.466667 and equity cost 11.8%, weighted cost 8.48%. At 60%, beta 2.05 and equity cost 15.3%, weighted cost 9.90%. More debt eventually costs more because of the spread jump."},{"id":"fm-s7-level3-v1-q6","session":"7","level":3,"topic":"Simultaneous equity and debt shocks","question":"A firm has debt weight 40%, equity beta 1.2, risk free rate 2% and market premium 5%. Debt cost is base rate plus 2% spread. Tax is 25%. Weights and beta stay fixed. In a stress, risk free rate rises 1 percentage point, market premium rises 2 points, and debt spread rises 1 point. What is the increase in weighted cost of capital?","choices":["2.04 percentage points.","2.64 percentage points.","3.04 percentage points.","2.24 percentage points."],"correct_index":1,"explanation":"Equity cost rises 1 + 1.2×2 = 3.4 percentage points. Debt cost rises 1+1 = 2 points. Weighted change is .6×3.4 + .4×2×.75 = 2.64 points. A spread shock alone is not the whole debt rate shock."},{"id":"fm-s7-level3-v1-q7","session":"7","level":3,"topic":"Market weighting with nontraded target","question":"A target has asset beta 0.9. A financing plan specifies debt/equity 1.5 at market values. Tax is 20%, risk free rate 3%, market premium 5%, debt cost 7% and zero debt beta. An analyst mistakenly treats 1.5 as a debt weight. What is the correctly calculated weighted cost of capital?","choices":["9.90%.","7.08%.","8.52%.","10.68%."],"correct_index":2,"explanation":"Debt weight is 1.5/2.5=.6 and equity weight .4. Equity beta is .9×(1+.8×1.5)=1.98. Equity cost is 12.9%. Weighted cost is .4×12.9%+.6×7%×.8=8.52%. Debt/equity is not debt divided by total capital."},{"id":"fm-s7-level3-v1-q8","session":"7","level":3,"topic":"Infer operating risk from weighted hurdle","question":"A company has weighted cost of capital 9.2%, debt/equity 0.5, marginal tax 20%, risk free rate 3%, market premium 6%, debt cost 6% and debt beta zero. What asset beta is implied by the internally consistent equity cost and relevering formula?","choices":["Approximately 1.4000.","Approximately 0.8571.","Approximately 1.1429.","Approximately 1.0000."],"correct_index":3,"explanation":"With equity weight 2/3 and debt weight 1/3, debt contributes 1.6 percentage points. Equity cost is (9.2−1.6)/(2/3)=11.4%. Equity beta is (11.4−3)/6=1.4. Divide by 1+.8×.5=1.4 to get asset beta 1."},{"id":"fm-s7-level3-v1-q9","session":"7","level":3,"topic":"Target weights after equity repricing","question":"A company has debt market value EUR 200 million and 20 million shares. The share price falls from EUR 20 to EUR 15 with debt value unchanged. Asset beta is 0.8, tax 25%, debt beta zero, risk free rate 3%, market premium 5% and debt cost 6%, all fixed. Recompute equity beta at the new market ratio. What is the new weighted cost of capital?","choices":["7.20%.","7.80%.","8.50%.","9.00%."],"correct_index":0,"explanation":"New equity value is 300 and debt/equity 2/3. Equity beta is .8×(1+.75×2/3)=1.2 and cost of equity 9%. Market weights are .6 equity and .4 debt. Weighted cost is .6×9%+.4×6%×.75=7.2%."},{"id":"fm-s7-level3-v1-q10","session":"7","level":3,"topic":"Benchmark consistency under revised assumptions","question":"An analyst uses a 2% risk free rate and a 6% historical market premium, estimated as 8% equity return less a 2% bond return. The chosen risk free rate is then changed to 4%. For this exercise only, the expected market return remains 8%, so the premium must be recomputed. Equity beta is 1.5, debt weight 40%, debt cost 6% and tax 25%. What corrected weighted cost of capital follows?","choices":["9.60%.","7.80%.","10.80%.","6.60%."],"correct_index":1,"explanation":"Consistent premium becomes 8−4=4%. Equity cost is 4%+1.5×4%=10%. Weighted cost is .6×10%+.4×6%×.75=7.8%. Keeping the stale 6% premium would produce 9.6%. This is a supplied fixed market return scenario, not a universal claim about rate changes."}],"6":[{"id":"fm-s6-level1-v1-q1","session":"6","level":1,"topic":"Partial hedge cash flow","question":"A borrower owes EUR 20 million at an annual benchmark rate plus 1.5%. It enters a swap on EUR 12 million, paying fixed 4% and receiving the same benchmark. Benchmark is 5% for the full year. There are no fees, principal changes or day count adjustments. What is combined annual loan and swap interest?","choices":["EUR 1.18 million.","EUR 1.10 million.","EUR 1.30 million.","EUR 0.78 million."],"correct_index":0,"explanation":"Loan interest is 20×6.5%=1.30. Swap net receipt is 12×(5%-4%)=.12. Combined outflow is 1.18. Only 60% of the benchmark exposure is fixed."},{"id":"fm-s6-level1-v1-q2","session":"6","level":1,"topic":"Fee and cash proceeds","question":"A three year bullet loan has face value EUR 10 million, an upfront fee of 2% of face value and annual interest of 6% on face value. No other cash flows occur before principal repayment. What are the initial net receipt and the year 3 total outflow?","choices":["Receipt EUR 10 million and outflow EUR 10.8 million.","Receipt EUR 9.8 million and outflow EUR 10.6 million.","Receipt EUR 9.8 million and outflow EUR 10.588 million.","Receipt EUR 9.4 million and outflow EUR 10.6 million."],"correct_index":1,"explanation":"The upfront fee reduces proceeds by.2 but does not reduce contractual principal or the.6 annual coupon. At maturity principal 10 plus interest.6 is paid."},{"id":"fm-s6-level1-v1-q3","session":"6","level":1,"topic":"Converting fixed to floating","question":"A company pays 6% fixed on EUR 15 million of debt. A matching swap makes it pay the benchmark and receive 4.5% fixed. Benchmark is 3.5% this year. Ignore fees and principal exchange. What is its combined annual interest rate and cash interest?","choices":["2.0% and EUR 0.30 million.","6.5% and EUR 0.975 million.","5.0% and EUR 0.75 million.","9.5% and EUR 1.425 million."],"correct_index":2,"explanation":"Combined rate is 6%+3.5%-4.5%=5%. Cash interest is 15×5%=.75. Paying floating and receiving fixed changes a fixed rate debt into floating exposure plus a spread."},{"id":"fm-s6-level1-v1-q4","session":"6","level":1,"topic":"Residual spread risk","question":"A company owes EUR 10 million at benchmark plus a credit spread that may reset. A matching swap on the full amount receives benchmark and pays 4% fixed. The benchmark rises from 3% to 5% while the loan spread rises from 1% to 2%. Ignore fees and use full year rates. By how much does combined annual interest rise?","choices":["It does not change because all borrowing risk is hedged.","EUR 0.20 million.","EUR 0.30 million.","EUR 0.10 million."],"correct_index":3,"explanation":"The benchmark cancels, but the spread does not. Combined rate rises from 4%+1%=5% to 4%+2%=6%, a 1% increase on 10 million."},{"id":"fm-s6-level1-v1-q5","session":"6","level":1,"topic":"Remaining maturity hedge","question":"A five year floating loan is now two years old and has three years remaining. Its full remaining principal is EUR 30 million and its contractual spread is 1.2%. A swap for the remaining three years receives the same floating benchmark and pays 3.8% fixed on EUR 30 million. No fee applies. What combined rate and annual interest result while principal stays constant?","choices":["5.0% and EUR 1.5 million.","3.8% and EUR 1.14 million.","2.6% and EUR 0.78 million.","5.0% and EUR 2.5 million."],"correct_index":0,"explanation":"Benchmark cancels over the remaining three years. The loan spread remains, so the combined rate is 3.8%+1.2%=5%. Interest is 30×5%=1.5. The already elapsed two years do not enter the new hedge."},{"id":"fm-s6-level1-v1-q6","session":"6","level":1,"topic":"Benchmark mismatch","question":"A loan of EUR 25 million pays reference A plus 1.4%. A swap on the same notional pays fixed 4% and receives reference B. Over the year A is 5% and B is 4.6%. No other cash flows or fees occur. What is the combined effective annual interest rate?","choices":["5.4%.","5.8%.","6.4%.","4.0%."],"correct_index":1,"explanation":"Combined rate is A+1.4%+4%-B=5%+1.4%+4%-4.6%=5.8%. The.4 percentage point difference between benchmarks is residual basis exposure."},{"id":"fm-s6-level1-v1-q7","session":"6","level":1,"topic":"Amortisation and swap notional","question":"At the start of a year, loan principal falls from EUR 20 million to EUR 15 million. The remaining loan pays benchmark plus 1%. A swap remains at EUR 20 million and pays 4% fixed while receiving benchmark. Benchmark is 5% all year. Ignore fees. What is combined cash interest for that year?","choices":["EUR 0.75 million.","EUR 0.90 million.","EUR 0.70 million.","EUR 1.00 million."],"correct_index":2,"explanation":"Loan costs 15×6%=.90. The swap receives net 20×1%=.20. Combined cost.70. With a 20 million swap against 15 million debt, there is an excess 5 million benchmark receipt."},{"id":"fm-s6-level1-v1-q8","session":"6","level":1,"topic":"Rate change and hedge ratio","question":"A borrower has EUR 40 million of floating debt and a pay fixed, receive benchmark swap on EUR 30 million. The loan and swap use the same benchmark and dates, and the loan spread and swap fixed rate do not change. If the benchmark rises by 1.5 percentage points, how much does annual combined interest rise?","choices":["EUR 0.60 million.","EUR 0.45 million.","It does not rise.","EUR 0.15 million."],"correct_index":3,"explanation":"Only 40-30=10 million remains floating. A 1.5% change on that residual equals.15 million. The matching 30 million exposure is offset by increased swap receipts."},{"id":"fm-s6-level1-v1-q9","session":"6","level":1,"topic":"Repricing versus refinancing","question":"Company A has a committed three year loan at an annual benchmark plus a fixed 2% spread. Company B has a one year fixed loan that must be renegotiated each year for three years. Both need continuous funding for all three years. Which comparison is correct?","choices":["A has benchmark repricing risk, while B also faces the risk that renewal is unavailable or repriced by lenders.","A has no interest rate risk because its spread is fixed.","B has no credit or refinancing risk because the first year is fixed.","A must renegotiate principal funding annually merely because its rate resets."],"correct_index":0,"explanation":"Resetting a contractual benchmark is distinct from asking lenders to renew a maturing facility. B must refinance, while A retains committed funding under the stated contract."},{"id":"fm-s6-level1-v1-q10","session":"6","level":1,"topic":"Swap versus total borrowing cost","question":"A borrower can take a two year bullet loan at benchmark plus 1.6%, with an upfront fee of 1%, and enter a matching swap paying 4.2% fixed and receiving benchmark. Ignore default and all other charges. Which statement about the annual combined coupon and the all in annualised cost is correct?","choices":["Coupon and all in cost are both 4.2%.","Coupon is 5.8%, and the all in cost is higher than 5.8%.","Coupon is 5.8%, and the all in cost is lower because the fee reduces principal repaid.","Coupon is 4.2%, and the all in cost is exactly 5.2%."],"correct_index":1,"explanation":"The combined coupon is 4.2%+1.6%=5.8%. The fee reduces the initial receipt while contractual interest and principal remain based on full face value, so the internal rate of return exceeds the coupon."},{"id":"fm-s6-level2-v1-q1","session":"6","level":2,"topic":"Fee adjusted all in cost","question":"A three year bullet loan pays EUR 10 million at inception less an upfront 2% fee. It requires annual interest of 6% on face value and repays the entire EUR 10 million at the end of year 3. What annual internal rate of return measures its all in cost, rounded to two decimals?","choices":["6.00%.","6.76%.","6.67%.","8.00%."],"correct_index":1,"explanation":"Cash flows from the borrower perspective are+9.8,-.6,-.6,-10.6 million at years 0,1,2,3. Solving their net present value equal to zero gives 6.75875%. Simple fee divided by maturity is only an approximation."},{"id":"fm-s6-level2-v1-q2","session":"6","level":2,"topic":"Floating path and fees","question":"An EUR 8 million three year bullet loan pays a fixed spread of 1.8% over the annual benchmark, which is 4%,4.5% and 5% in years 1,2,3. An upfront fee is 2% of face value. Annual payments are in arrears and no other flows occur. What is its all in annual internal rate of return, rounded to two decimals?","choices":["6.30%.","6.98%.","7.04%.","8.30%."],"correct_index":2,"explanation":"Net initial receipt 7.84. Coupons are.464,.504,.544 million. Final outflow 8.544. The internal rate of return of 7.84,-.464,-.504,-8.544 is 7.0400%, using the timing of each rate rather than only their arithmetic mean."},{"id":"fm-s6-level2-v1-q3","session":"6","level":2,"topic":"Partial swap and fee adjusted cost","question":"An EUR 10 million three year bullet loan pays annual benchmark plus 1.5%, with a 1.5% upfront fee. The benchmark is 3%,4%,5% in years 1,2,3. A swap on EUR 6 million receives that benchmark and pays fixed 5% throughout. All payments occur at each year end. What is the all in annual internal rate of return, rounded to two decimals?","choices":["6.80%.","7.08%.","8.00%.","6.65%."],"correct_index":3,"explanation":"Combined coupon is .15 million loan spread plus .30 million fixed swap leg plus the benchmark on 4 million. Coupons are.57,.61,.65 million, with initial net receipt 9.85 and final principal 10. The internal rate of return of 9.85,-.57,-.61,-10.65 is about 6.65%."},{"id":"fm-s6-level2-v1-q4","session":"6","level":2,"topic":"Amortising hedge budget","question":"A loan has principal EUR 20 million in year 1 and EUR 12 million in year 2, pays benchmark plus 1.5%, and has a swap paying 4% fixed and receiving benchmark on EUR 15 million in both years. Benchmark is 3% in year 1 and 6% in year 2. Ignore fees and principal in the interest calculation. What is total combined interest across both years?","choices":["EUR 1.65 million.","EUR 1.76 million.","EUR 1.80 million.","EUR 1.95 million."],"correct_index":0,"explanation":"Year 1 loan 20×4.5%=.90 and swap 15×(4%-3%)=.15, giving 1.05. Year 2 loan 12×7.5%=.90 and swap 15×(4%-6%)=-.30, giving.60. Total 1.65. The second year is overhedged."},{"id":"fm-s6-level2-v1-q5","session":"6","level":2,"topic":"Hedge ratio from interest ceiling","question":"A firm has EUR 50 million of debt at benchmark plus 1.2% and can pay 4% fixed, receive benchmark on swap notional H. In the stress case benchmark is 7% for a full year. Ignore fees and day count. What is the minimum H needed to keep combined annual interest at or below EUR 3.2 million?","choices":["EUR 20 million.","EUR 30 million.","EUR 40 million.","EUR 45 million."],"correct_index":1,"explanation":"Unhedged cost is 50×8.2%=4.1 million. Each million swapped saves.03 million in the stress case. Need 4.1-.03 H≤3.2, hence H≥30."},{"id":"fm-s6-level2-v1-q6","session":"6","level":2,"topic":"All in hedge versus direct fixed debt","question":"A company needs EUR 5 million face value of two year bullet funding. Direct fixed debt costs 7% annually with a 2% upfront fee. Alternatively, a fee free floating loan at benchmark plus 1.5% can be fully swapped by paying 6% fixed and receiving the same benchmark. All payments are annual in arrears. Which has the lower all in cost?","choices":["Direct fixed debt at 7.00%, versus 7.50% for the swap route.","Direct fixed debt at 8.00%, versus 9.00% for the swap route.","The swapped loan at 7.50%, versus about 8.12% for direct fixed debt.","They are equal after the loan benchmark cancels."],"correct_index":2,"explanation":"Direct cash flows are 4.9,-.35,-5.35 million, with internal rate of return 8.12344%. The fee free swapped route pays 6%+1.5%=7.5%. Comparing coupons alone misranks the choices."},{"id":"fm-s6-level2-v1-q7","session":"6","level":2,"topic":"Spread differential allocation","question":"Company A can borrow fixed at 5% or floating at benchmark plus 0.5%. Company B can borrow fixed at 7% or floating at benchmark plus 1.2%. A wants floating debt and B fixed debt. Assume each borrows where it has comparative advantage, and a swap dealer retains 0.3 percentage point per year from the total potential saving. If A and B share the remaining saving equally, what are their resulting annual rates?","choices":["A pays benchmark plus 0.2% and B pays 6.7%.","A pays benchmark minus 0.5% and B pays 6.0%.","A pays benchmark plus 0.5% and B pays 7.0%.","A pays benchmark and B pays 6.5%."],"correct_index":3,"explanation":"Fixed quality spread is 2%, floating quality spread.7%, so potential gain 1.3%. After dealer.3%, each saves.5%. A improves from benchmark+.5% to benchmark, B from 7% to 6.5%."},{"id":"fm-s6-level2-v1-q8","session":"6","level":2,"topic":"Break even benchmark with partial hedge","question":"A EUR 24 million loan costs benchmark plus 1%. A swap on EUR 18 million pays 4.5% fixed and receives benchmark. Another fee free financing choice costs 5.2% fixed on all EUR 24 million. All payments cover one year. At what benchmark rate do the combined loan and swap interest equal the fixed alternative?","choices":["3.3%.","4.2%.","4.5%.","5.2%."],"correct_index":0,"explanation":"Combined interest in millions is 6×benchmark+.24+.81. The fixed alternative costs 24×.052=1.248. Thus 6×benchmark=.198 and benchmark=.033. The benchmark is applied only to residual 6 million."},{"id":"fm-s6-level2-v1-q9","session":"6","level":2,"topic":"Basis and spread simultaneous stress","question":"A EUR 30 million loan costs reference A plus 1.5%. A full notional swap pays 4% fixed and receives reference B. In the base case A=B=3%. In stress A=6%, B=5.6% and the loan spread resets to 2%. What is the increase in annual combined cash interest?","choices":["EUR 0.12 million.","EUR 0.27 million.","EUR 0.15 million.","EUR 0.90 million."],"correct_index":1,"explanation":"Base rate is 5.5%. Stress rate is 6%+2%+4%-5.6%=6.4%. The.9 percentage point increase consists of.4% basis widening and.5% spread widening, costing.27 million on 30."},{"id":"fm-s6-level2-v1-q10","session":"6","level":2,"topic":"Opposite direction after asset sale","question":"A borrower has EUR 40 million floating debt and a full matching swap paying 4% fixed and receiving benchmark. It then repays EUR 15 million of debt, leaving the swap unchanged. The remaining debt spread is 1%. Benchmark falls from 4% to 2% for the following full year. How does annual combined interest change relative to a benchmark staying at 4%, on the same reduced debt?","choices":["It falls by EUR 0.50 million.","It falls by EUR 0.80 million.","It rises by EUR 0.30 million.","It does not change."],"correct_index":2,"explanation":"After repayment the net benchmark position is 25 million paid minus 40 million received, or a 15 million floating receipt. A 2 percentage point rate fall reduces that net receipt by.30 million, raising cost."},{"id":"fm-s6-level3-v1-q1","session":"6","level":3,"topic":"Integrated two year early exit","question":"A company receives a three year EUR 10 million bullet loan less a 2% upfront fee. It owes benchmark plus 1.5% and has a matching swap paying 5% fixed and receiving benchmark. It unexpectedly repays all debt at the end of year 2. At that moment, a separate EUR 0.4 million swap termination payment is due in addition to year 2 interest and principal. No other costs apply. What is the all in annual internal rate of return through exit, rounded to two decimals?","choices":["7.62%.","8.50%.","9.55%.","6.50%."],"correct_index":2,"explanation":"Combined annual coupon is.65 million. Cash flows are 9.8,-.65,-11.05 million, because year 2 pays 10 principal,.65 interest and.4 termination cost. The internal rate of return is about 9.55%. Omitting termination understates the realised financing cost."},{"id":"fm-s6-level3-v1-q2","session":"6","level":3,"topic":"Feasible hedge interval","question":"A company owes EUR 40 million for one year at benchmark plus 1%. It can swap H million, paying 4% fixed and receiving benchmark. H must lie between 0 and 40. Management requires combined interest no greater than 2.6 million if benchmark is 7%, and no greater than 1.7 million if benchmark is 2%. Which hedge notionals meet both limits?","choices":["Every H from 0 through 20 million.","Every H from 25 through 40 million.","No notional can meet both limits.","Every H from 20 million through 25 million, inclusive."],"correct_index":3,"explanation":"At 7%, cost is 3.2-.03 H, requiring H≥20. At 2%, cost is 1.2+.02 H, requiring H≤25. Their intersection is[20,25]. A hedge that protects the high rate budget can make low rate costs exceed a separate budget."},{"id":"fm-s6-level3-v1-q3","session":"6","level":3,"topic":"Time varying credit spread","question":"A EUR 12 million four year bullet loan carries a 2% upfront fee and annual benchmark plus a credit spread. A full matching swap pays 4.5% fixed and receives benchmark. Loan spreads are 2.2%,1.2%,0.2% and minus 0.8% in years 1 through 4, respectively, as explicitly contracted. All coupons are paid annually in arrears. What is the all in annual internal rate of return, rounded to two decimals?","choices":["5.85%.","5.20%.","6.70%.","7.20%."],"correct_index":0,"explanation":"Net proceeds 11.76 million. The benchmark cancels and the combined coupons are 6.7%,5.7%,4.7%,3.7% on 12 million, namely.804,.684,.564,.444. Cash flows 11.76,-.804,-.684,-.564,-12.444 give 5.84611%. The varying spread is not removed by the benchmark swap."},{"id":"fm-s6-level3-v1-q4","session":"6","level":3,"topic":"Maximum upfront fee","question":"A company can take an EUR 10 million three year bullet loan and swap the whole benchmark exposure. The final combined annual coupon is 6.5% of face value. It will accept the route only if the annual internal rate of return is no more than 8%. The only other charge is an upfront fee deducted from proceeds. What is the maximum fee as a percentage of face value, rounded to two decimals?","choices":["1.50%.","3.87%.","4.50%.","6.50%."],"correct_index":1,"explanation":"At the limit, net proceeds must equal the present value at 8% of.65,.65,10.65 million. This is 9.61344 million, so maximum fee is.38656 million, or 3.86565% of face value. Fees cannot be compared by simply subtracting coupon rates."},{"id":"fm-s6-level3-v1-q5","session":"6","level":3,"topic":"Quality spread and dealer consistency","question":"Company A can borrow fixed at 4.8% or floating at benchmark plus 0.4%. B can borrow fixed at 6.6% or floating at benchmark plus 1.0%. A wants floating and B fixed. A borrows fixed and enters a swap paying benchmark and receiving fixed x%. B borrows floating and swaps by paying fixed y% and receiving benchmark. The dealer earns y minus x. Both companies require a 0.4 percentage point annual saving versus borrowing directly in their desired form. What x,y and dealer margin meet the requirements?","choices":["x=4.4%, y=5.6%, dealer margin 1.2%.","x=5.2%, y=4.8%, dealer margin minus 0.4%.","x=4.8%, y=5.2%, dealer margin 0.4%.","x=4.8%, y=5.6%, dealer margin 0.8%."],"correct_index":2,"explanation":"A final rate is benchmark+4.8%-x. Saving.4% versus benchmark+.4% requires x=4.8%. B final rate is 1%+y, and saving.4% versus 6.6% requires y=5.2%. Dealer retains.4%, leaving.8% to the two firms from the 1.2% differential."},{"id":"fm-s6-level3-v1-q6","session":"6","level":3,"topic":"Matching amortisation and cost","question":"A EUR 20 million loan falls to EUR 12 million immediately after the first annual interest payment, and is fully repaid after the second. The loan spread is 1.5%. A swap pays 4% fixed and receives the matching benchmark on 20 million in year 1 and 12 million in year 2. An upfront loan fee is 1% of initial face value. Ignore all other costs. What is the all in annual internal rate of return, rounded to two decimals?","choices":["5.50%.","6.00%.","7.00%.","6.18%."],"correct_index":3,"explanation":"Net initial proceeds 19.8 million. Year 1 coupon 1.1 plus principal 8 gives 9.1 outflow. Year 2 coupon.66 plus remaining principal 12 gives 12.66. The internal rate of return of 19.8,-9.1,-12.66 is about 6.18%. The fee is recovered over the actual amortising cash flows, not a bullet maturity."},{"id":"fm-s6-level3-v1-q7","session":"6","level":3,"topic":"Minimum swap fixed rate concession","question":"A company needs one year EUR 20 million funding. Direct fixed debt offers 6.4% with no fees. A floating loan pays benchmark plus 1.3%, has a 1% upfront fee and must repay full face value at year end. A matching swap receives benchmark and pays fixed K. What is the maximum K that makes the swapped route all in cost no greater than the direct fixed alternative?","choices":["4.036%.","5.100%.","4.100%.","5.036%."],"correct_index":0,"explanation":"Net proceeds are 19.8. One year all in cost is[20×(1+K+.013)/19.8]-1. Set it equal to.064, so 1+K+.013=.99×1.064=1.05336 and K=.04036. The upfront fee compounds the effective cost, rather than adding exactly 1% to it."},{"id":"fm-s6-level3-v1-q8","session":"6","level":3,"topic":"Loan replacement but swap survives","question":"A company has EUR 30 million debt paying benchmark A plus 1%. It fully hedges with a swap receiving A and paying 4% fixed. After a refinancing, debt still equals 30 million but now costs benchmark B plus 1.8%, while the old swap stays in place. During the next full year A=3.5% and B=4.2%. Ignore fees. What are the new combined annual interest and the increase versus retaining the old loan under the same A?","choices":["EUR 1.74 million, an increase ofEUR 0.24 million.","EUR 1.95 million, an increase ofEUR 0.45 million.","EUR 1.50 million, no increase.","EUR 2.10 million, an increase ofEUR 0.60 million."],"correct_index":1,"explanation":"New combined rate is 4.2%+1.8%+4%-3.5%=6.5%, costing 1.95 million. The old loan plus swap would cost 5%=1.5 million. Difference.45 includes both.8% higher spread and.7% benchmark mismatch."},{"id":"fm-s6-level3-v1-q9","session":"6","level":3,"topic":"Debt and swap downside feasibility","question":"A firm has EUR 50 million floating debt at benchmark plus 1%, annual EBIT 5 million and a covenant requiring EBIT/combined cash interest at least 2.5. It may pay 4% fixed and receive benchmark on swap notional H between 0 and 50 million. Benchmark may be either 2% or 7%. No fees or other costs apply. Can any H satisfy the covenant in both states?","choices":["Yes. H=50 million guarantees coverage exactly 2.5.","Yes. Any H between 25 and 50 million works.","No. The high rate state requires H at least 66.67 million, above the allowed maximum.","No. The low rate state alone requires H below zero."],"correct_index":2,"explanation":"Maximum interest allowed is 5/2.5=2 million. At 7%, interest is 50×8%-.03 H=4-.03 H. Need H≥66.667, impossible with H≤50. Even fully hedged, fixed 4% plus spread 1% costs 2.5 million and coverage is 2.0."},{"id":"fm-s6-level3-v1-q10","session":"6","level":3,"topic":"Swap termination break even","question":"A borrower has two annual payments remaining on EUR 10 million debt at benchmark plus 1%. Its full matching swap pays 5% fixed and receives benchmark, fixing combined coupons at 6%. The firm can terminate the swap now for a cash payment F and expects benchmark 2% for both remaining years. Principal repayment is unchanged. Discount incremental cash flows at 4% annually. What maximum F makes termination no worse in present value than retaining the swap, rounded to the nearest thousand euros?","choices":["EUR 600,000.","EUR 555,000.","EUR 300,000.","EUR 566,000."],"correct_index":3,"explanation":"Retaining costs.6 million annually. Terminating leaves the loan at 3%, or.3 million annually. Savings are.3 each year. Their present value is.3/1.04+.3/1.04²=.565828 million. Pay no more than that today. The common principal repayment cancels from this comparison."}],"8":[{"id":"fm-s8-level1-v1-q1","session":"8","level":1,"topic":"Financing gap","question":"A mature firm has EBIT of EUR 120 million, a 25% operating tax rate, depreciation of EUR 20 million, an increase in working capital of EUR 35 million and cash capital spending of EUR 90 million. There are no divestitures. Using EBIT after tax plus depreciation minus working capital investment minus capital spending, how much external finance is needed before dividends and debt service?","choices":["EUR 15 million.","EUR 5 million.","EUR 35 million.","No finance is needed because EBIT is positive."],"correct_index":0,"explanation":"Operating cash flow is 120 × .75 + 20 - 35 - 90 = -15. Positive profit does not prevent a cash financing gap."},{"id":"fm-s8-level1-v1-q2","session":"8","level":1,"topic":"Value sensitivity","question":"A business generates perpetual annual operating cash flow of EUR 18 million, with no growth. A feasible recapitalisation reduces its weighted average cost of capital from 9% to 8%, without changing cash flows. What is the increase in enterprise value?","choices":["EUR 2 million.","EUR 25 million.","EUR 22.5 million.","EUR 225 million."],"correct_index":1,"explanation":"Old value is 18/.09 = 200. New value is 18/.08 = 225. The increase is 25, not the new value itself."},{"id":"fm-s8-level1-v1-q3","session":"8","level":1,"topic":"Market leverage","question":"Two feasible structures finance the same business. Structure A has debt/equity of 0.5, equity cost 11% and pretax debt cost 5%. Structure B has debt/equity of 1.0, equity cost 13% and pretax debt cost 6%. The tax rate is 30% and operating cash flows are identical. Which has the lower weighted average cost of capital?","choices":["B, because its debt weight is 100%.","B, at 7.10% versus A at 8.50%.","A, at 8.50% versus B at 8.60%.","They are equal because operating cash flows are equal."],"correct_index":2,"explanation":"A uses debt weight 1/3 and equity weight 2/3, so its cost is 11% × 2/3 + 5% × .7/3 = 8.50%. B costs 13% × .5 + 6% × .7 × .5 = 8.60%."},{"id":"fm-s8-level1-v1-q4","session":"8","level":1,"topic":"Debt strategy diagnosis","question":"A firm has debt of 200, working capital of 120, capital spending of 60 and net financial debt of 150, all in the same units. Its EBITDA is 60. A diagnostic scheme calls working capital/debt above 50% ordinary debt, capital spending/debt above 50% debt for growth and net financial debt/EBITDA above 3 aggressive leverage. Which classification is supported by these figures?","choices":["Debt for growth only.","Aggressive leverage only.","All three classifications.","Ordinary debt only."],"correct_index":3,"explanation":"Working capital/debt is 60%, capital spending/debt 30% and net financial debt/EBITDA 2.5. Only the first stated threshold is exceeded."},{"id":"fm-s8-level1-v1-q5","session":"8","level":1,"topic":"Cash flow versus profit","question":"A firm has EBIT of 80, a 25% operating tax rate, depreciation of 15, a decrease in working capital of 10 and cash capital spending of 50. All amounts are in millions, with no divestitures. What is operating cash flow before financing?","choices":["35.","15.","25.","55."],"correct_index":0,"explanation":"After tax EBIT is 60. The decrease in working capital releases 10, so operating cash flow is 60 + 15 + 10 - 50 = 35."},{"id":"fm-s8-level1-v1-q6","session":"8","level":1,"topic":"Value and funding","question":"A firm has perpetual operating cash flow of 24 and a feasible weighted average cost of capital of 8%. Its debt has market value 100, there is no excess cash, and values are in millions. What are enterprise value and equity value?","choices":["Enterprise value 200 and equity value 100.","Enterprise value 300 and equity value 200.","Enterprise value 300 and equity value 400.","Enterprise value 400 and equity value 300."],"correct_index":1,"explanation":"Enterprise value is 24/.08 = 300. Debt is a claim on that value, so equity is 300 - 100 = 200. Do not deduct interest again from operating cash flow."},{"id":"fm-s8-level1-v1-q7","session":"8","level":1,"topic":"Liquidity constraint","question":"A business has 10 of cash available for financing at the start of the year and generates operating cash flow of 25 during the year, before debt payments. Interest is 8 and debt principal due is 32. Management requires a closing cash buffer of 5. All figures are in millions. What is the minimum new financing needed?","choices":["0.","5.","10.","15."],"correct_index":2,"explanation":"Cash before new financing ends at 10 + 25 - 8 - 32 = -5. Raising 10 restores the required buffer of 5."},{"id":"fm-s8-level1-v1-q8","session":"8","level":1,"topic":"Sustainable minimum","question":"A company compares three feasible leverage structures with identical perpetual operating cash flow. At debt/equity of 0.4, 0.8 and 1.2, the weighted average costs of capital are 8.2%, 7.8% and 8.0% respectively. The board limits debt/equity to 0.9. Which structure maximises enterprise value among the choices?","choices":["Debt/equity 0.4.","Debt/equity 1.2.","Any structure because financing cannot affect this stated valuation.","Debt/equity 0.8."],"correct_index":3,"explanation":"The 1.2 structure violates the limit and has a higher cost anyway. Among feasible structures, 0.8 has the lowest discount rate and therefore the highest value for unchanged positive operating cash flows."},{"id":"fm-s8-level1-v1-q9","session":"8","level":1,"topic":"Growth consumes cash","question":"A growing company reports EBIT of 100, tax rate 30%, depreciation of 20, working capital investment of 45 and cash capital spending of 70, all in millions. A second plan cuts working capital investment by 15 without changing EBIT or any other item. How does the external financing gap change, before financing payments?","choices":["It falls from 25 to 10.","It falls from 45 to 30.","It rises from 25 to 40.","It disappears because EBIT is positive."],"correct_index":0,"explanation":"Base cash flow is 70 + 20 - 45 - 70 = -25. Releasing 15 of the planned working capital investment raises cash flow to -10."},{"id":"fm-s8-level1-v1-q10","session":"8","level":1,"topic":"Flexibility versus narrow optimum","question":"A cyclical company can reduce its calculated current weighted average cost of capital by 0.1 percentage point with more debt, but the added debt removes all unused credit capacity just before a large uncertain investment. The calculation holds future operating cash flows fixed and ignores funding constraints. Which conclusion is most defensible?","choices":["The small reduction proves that all unused debt capacity should be consumed.","The calculation alone cannot establish that the added debt is the best sustainable structure.","Unused credit capacity has no possible economic value.","The company should maximise debt regardless of the investment."],"correct_index":1,"explanation":"A narrow discount rate minimum relies on its assumptions. Financial flexibility and the ability to fund future investments can matter, especially when the calculation excludes them."},{"id":"fm-s8-level2-v1-q1","session":"8","level":2,"topic":"Operating leverage and capital weights","question":"A company has unlevered beta 0.8, risk free rate 3%, equity risk premium 5% and tax rate 25%. At debt/equity 1, pretax debt cost is 6%. Use levered beta = unlevered beta × [1 + (1 - tax rate) × debt/equity]. What weighted average cost of capital results?","choices":["6.50%.","8.00%.","7.25%.","10.00%."],"correct_index":2,"explanation":"Levered beta is .8 × 1.75 = 1.4. Equity costs 3% + 1.4 × 5% = 10%. Equal debt and equity weights give .5 × 10% + .5 × 6% × .75 = 7.25%."},{"id":"fm-s8-level2-v1-q2","session":"8","level":2,"topic":"Cash flow and valuation trade off","question":"Plan A produces perpetual operating cash flow of 30 at a weighted average cost of capital of 8%. Higher leverage in Plan B reduces that cost to 7.5%, but suppliers impose terms that permanently reduce annual operating cash flow to 27. Values are in millions and no growth occurs. Which is more valuable?","choices":["B by 25.","B by 15.","A by 3.","A by 15."],"correct_index":3,"explanation":"A is worth 30/.08 = 375. B is worth 27/.075 = 360. Minimising the rate only maximises value when operating cash flows are held constant."},{"id":"fm-s8-level2-v1-q3","session":"8","level":2,"topic":"Debt capacity and timing","question":"A company starts with cash of 8 and debt of 90. Annual operating cash flow before financing is 20, interest is 6, principal repayment is 18 and the closing cash minimum is 10. EBITDA is 30. All amounts are millions. A covenant caps closing net financial debt at 2.5 times EBITDA. What is the minimum new borrowing and is it feasible?","choices":["Borrow 6. It is feasible, with closing net financial debt 68.","Borrow 6. It is infeasible, with closing net financial debt 86.","Borrow 4. It is feasible, with closing net financial debt 66.","Borrow 18. It is the minimum needed."],"correct_index":0,"explanation":"Pre financing closing cash is 8+20-6-18=4, so 6 is needed. Closing gross debt is 90-18+6=78 and net debt is 78-10=68, below the cap of 75."},{"id":"fm-s8-level2-v1-q4","session":"8","level":2,"topic":"Rating constraint","question":"Three structures have debt weights of 20%, 40% and 60%, equity costs of 10%, 12% and 16%, and pretax debt costs of 4%, 5% and 8%, respectively. The tax rate is 25%. The board permits only structures with pretax debt cost no higher than 6%. Cash flows are unchanged. Which allowed structure minimises the weighted average cost of capital?","choices":["40% debt, with a cost of 8.70%.","20% debt, with a cost of 8.60%.","60% debt, with a cost of 8.80%.","20% debt, with a cost of 8.00%."],"correct_index":1,"explanation":"At 20% debt cost .8×10%+.2×4%×.75=8.60%, below 40% debt at .6×12%+.4×5%×.75=8.70%. The 60% structure is excluded."},{"id":"fm-s8-level2-v1-q5","session":"8","level":2,"topic":"Working capital and maturity","question":"A firm expects EBIT of 90, tax rate 20%, depreciation of 18, working capital investment of 25 and cash capital spending of 50, all in millions. It has no available opening cash. Interest is 5 and principal due is 20. What is the financing shortfall after operating cash flow and scheduled debt payments?","choices":["5.","15.","10.","25."],"correct_index":2,"explanation":"Operating cash flow is 90×.8+18-25-50=15. Debt payments are 25, leaving a shortfall of 10. Operating profitability is not debt service cash availability."},{"id":"fm-s8-level2-v1-q6","session":"8","level":2,"topic":"Value break even","question":"A firm currently generates perpetual operating cash flow of 20 at a weighted average cost of capital of 8%. A recapitalisation raises the cost to 9% but funds a permanent cash flow improvement. What minimum annual operating cash flow would preserve the existing enterprise value?","choices":["20.0.","21.0.","25.0.","22.5."],"correct_index":3,"explanation":"Existing value is 20/.08=250. At 9%, cash flow must be 250×.09=22.5. The rate rises 12.5% relative to its old level, so cash flow must rise 12.5% too."},{"id":"fm-s8-level2-v1-q7","session":"8","level":2,"topic":"Joint leverage constraints","question":"A company has EBITDA 50, net financial debt 140 and equity market value 100, all in millions. It will borrow new debt and immediately spend the proceeds on a project, leaving cash unchanged. The board caps net financial debt/EBITDA at 3.2 and net financial debt/equity at 1.5. EBITDA and equity do not yet change. What is the maximum additional debt?","choices":["10.","20.","30.","50."],"correct_index":0,"explanation":"The EBITDA test allows debt up to 160, so 20 of new borrowing. The equity test allows 150, so 10. The tighter constraint determines the result."},{"id":"fm-s8-level2-v1-q8","session":"8","level":2,"topic":"Project funding and retained cash","question":"A business has 12 of available opening cash and targets a closing balance of 8. EBIT is 100, the tax rate 25%, depreciation 20 and working capital investment 30. It plans cash capital spending of 80 and dividends of 10, with no debt payments. Values are in millions. How much external finance must it raise?","choices":["17.","21.","25.","29."],"correct_index":1,"explanation":"Operating cash flow is 75+20-30-80=-15. Closing cash before financing is 12-15-10=-13. Raising 21 reaches 8. The available opening buffer is 4, not 12."},{"id":"fm-s8-level2-v1-q9","session":"8","level":2,"topic":"Investment changes the objective","question":"A stable company at its current leverage has value 500 from annual perpetual operating cash flow of 40 at 8%. A new debt funded programme would add annual perpetual operating cash flow of 6 but raise the weighted average cost of capital to 9%. The programme costs 30 immediately, a cash outflow additional to those perpetual flows. Assess incremental value, treating the cost separately from the operating perpetuity.","choices":["Value rises by about 11.11.","Value rises by about 36.67.","Value falls by about 18.89.","Value falls by exactly 30."],"correct_index":2,"explanation":"The new operating value is 46/.09=511.111. Deduct the incremental immediate cost 30 to compare net values:481.111 versus 500, a loss 18.889. A lower cost of capital is not the only decision variable."},{"id":"fm-s8-level2-v1-q10","session":"8","level":2,"topic":"Downside coverage","question":"A company has debt of 160 at a fixed 6% interest rate. Base EBIT is 36 and depreciation 12. A downturn cuts EBITDA by 25%, while depreciation stays unchanged. All monetary amounts are millions. The board requires EBIT/interest at least 2.5. Does it meet the downside test?","choices":["Yes, with downside coverage of 3.75.","No, with downside coverage of 1.88.","No, because base EBITDA/interest is below 2.5.","Yes, with downside EBIT/interest of 2.50."],"correct_index":3,"explanation":"Base EBITDA is 48, stressed EBITDA 36 and stressed EBIT 24. Interest is 9.6, so coverage is 24/9.6=2.5. Do not stress EBIT directly or confuse EBIT with EBITDA."},{"id":"fm-s8-level3-v1-q1","session":"8","level":3,"topic":"Integrated sustainable structure","question":"A firm has EBIT of 100, depreciation of 20, tax rate 25%, working capital investment of 15 and annual cash capital spending of 30, all in millions. These operating inputs repeat forever with no growth. Three structures have debt/equity ratios of 0, 0.5 and 1, and pretax debt costs of 0%, 5% and 8%. Unlevered beta is 1, risk free rate 3% and equity risk premium 5%. Use the stated beta relevering formula beta =1×[1+.75×debt/equity]. Which structure maximises operating enterprise value?","choices":["Debt/equity 0.5, at enterprise value about 638.30.","Debt/equity 0, at enterprise value 625.00.","Debt/equity 1, at enterprise value about 754.72.","Debt/equity 1, at enterprise value 625.00."],"correct_index":0,"explanation":"Operating cash flow is 75+20-15-30=50. Costs are 8% at zero debt, (9.875%+ .5×5%×.75)/1.5=7.83333% at .5, and(11.75%+8%×.75)/2=8.875% at 1. Values are 625,638.298 and 563.380. The middle structure wins."},{"id":"fm-s8-level3-v1-q2","session":"8","level":3,"topic":"Endogenous debt weights","question":"A firm has perpetual operating cash flow of 30 and fixed debt market value 100, in millions. Cost of equity is 12%, pretax debt cost 5%, tax rate 20% and no excess cash. Equity equals enterprise value minus debt. Using those market weights and value = cash flow/weighted average cost of capital, solve for enterprise value.","choices":["250.00.","316.67.","300.00.","350.00."],"correct_index":1,"explanation":"Write WACC=[.12(V-100)+.05×.8×100]/V=.12-8/V. Then V×WACC=30 implies .12 V-8=30 and V=316.667. Equity is 216.667, so weights must not be guessed from book values."},{"id":"fm-s8-level3-v1-q3","session":"8","level":3,"topic":"Cost cliff and cash flow loss","question":"A firm compares two structures. Under A, debt/equity is .5, equity cost 11%, pretax debt cost 5% and perpetual operating cash flow 30. Under B, debt/equity is 1, equity cost 14%, pretax debt cost 7% and perpetual cash flow 28 because financial tension harms operations. Tax rate is 25%, no growth occurs and figures are millions. How much lower is B enterprise value than A?","choices":["About 28.66.","About 36.36.","About 58.61.","About 75.00."],"correct_index":2,"explanation":"A WACC=(.11+.5×.05×.75)/1.5=.0858333 and value 349.5146. B WACC=(.14+.07×.75)/2=.09625 and value 290.9091. The difference is 58.6055."},{"id":"fm-s8-level3-v1-q4","session":"8","level":3,"topic":"Maximum sustainable dividend","question":"A firm starts with cash 15 and gross debt 120. During the year it has EBIT 80, tax rate 25%, depreciation 10, working capital investment 20, cash capital spending 35, interest 8 and mandatory principal repayment 15. EBITDA for the closing covenant is 90. All amounts are millions. It can borrow at most 10 of new debt, must end with cash at least 12 and closing net financial debt/EBITDA at most 1.2. What is the maximum dividend?","choices":["2.","8.","10.","5."],"correct_index":3,"explanation":"Operating cash flow is 60+10-20-35=15. Before new debt or dividend closing cash is 15+15-8-15=7. Borrow 10 gives 17, permitting dividend 5 while retaining 12. Closing gross debt 115 and net debt 103, below 108. The cash and borrowing limits bind first."},{"id":"fm-s8-level3-v1-q5","session":"8","level":3,"topic":"Debt capacity with repricing","question":"A firm has EBITDA 60 and depreciation 12, all in millions. For total debt up to 150 the entire debt costs 5%. Above 150 the entire debt costs 7%. The board requires EBIT/interest at least 4 and gross debt/EBITDA at most 3. Debt may take any nonnegative value. What is the maximum feasible debt?","choices":["About 171.43.","150.00.","180.00.","240.00."],"correct_index":0,"explanation":"EBIT is 48. In the upper tier, interest must be at most 12, so debt≤12/.07=171.4286. This exceeds 150 and is consistent with the tier. The leverage cap 180 is looser. Applying 5% above 150 overstates capacity."},{"id":"fm-s8-level3-v1-q6","session":"8","level":3,"topic":"Price of financial flexibility","question":"Plan A has perpetual operating cash flow 40 and weighted average cost of capital 8%. Plan B has cash flow 40 and cost 7.8%, but loses the ability to undertake a separate future project. At today's date that lost project has net present value 20. There is no other difference, no growth and all values are millions. Which plan has higher total value, including the project opportunity?","choices":["B by about 12.82.","A by about 7.18.","B by about 7.18.","A by exactly 20."],"correct_index":1,"explanation":"A total value is 40/.08+20=520. B is 40/.078=512.8205. The small static discount rate gain 12.8205 is less than the lost opportunity 20."},{"id":"fm-s8-level3-v1-q7","session":"8","level":3,"topic":"Two year liquidity stress","question":"A company starts year 1 with cash 10 and debt 100. Year 1 operating cash flow before financing is 15, interest 6 and principal due 20. Year 2 operating cash flow is 18, interest 5 and principal due 25. It requires cash at least 8 at each year end. It may draw a committed facility only at the end of year 1 and cannot borrow in year 2. The facility has no interest during these two years and no scheduled repayment. All values are millions. What minimum facility draw makes both year ends feasible?","choices":["9.","12.","21.","30."],"correct_index":2,"explanation":"Without a draw, year 1 cash is 10+15-6-20=-1, so year 1 alone needs 9. Year 2 burns 12 more, leaving -13 before the initial draw. A 21 draw leaves 20 at endyear 1 and 8 at endyear 2. Optimising one year in isolation misses the later maturity."},{"id":"fm-s8-level3-v1-q8","session":"8","level":3,"topic":"Maximum operating damage","question":"A company has perpetual annual operating cash flow 50 at a weighted average cost of capital 10%. A recapitalisation reduces the cost to 9% but creates a permanent annual operating cash flow loss x. There is also a one off implementation cost of 10 today. Figures are millions and no growth occurs. What is the largest x that leaves total value no lower than before?","choices":["5.00.","4.00.","4.90.","4.10."],"correct_index":3,"explanation":"Require (50-x)/.09 -10 ≥500. Thus 50-x≥45.9, giving x≤4.1. Ignoring the implementation cost would allow a loss of 5 instead."},{"id":"fm-s8-level3-v1-q9","session":"8","level":3,"topic":"Fixed point under a rating schedule","question":"A firm has perpetual operating cash flow 24, debt market value 120, equity equal to enterprise value minus debt, equity cost 12% and tax rate 25%. Pretax debt cost is 5% if debt/enterprise value is at most 40%, and 8% otherwise. Use market weights and value = cash flow/weighted average cost of capital. Which enterprise value is self consistent?","choices":["260.00, in the 8% debt cost tier only.","300.00, in the 5% debt cost tier only.","282.35 and 300.00 are both self consistent.","282.50, in the 5% debt cost tier only."],"correct_index":0,"explanation":"For 5% debt, .12 V-(.12-.0375)×120=24 gives V=282.5, implying 42.48% debt, inconsistent. For 8% debt, .12 V-(.12-.06)×120=24 gives V=260 and debt 46.15%, consistent. Only 260 is valid."},{"id":"fm-s8-level3-v1-q10","session":"8","level":3,"topic":"Funding growth under covenant stress","question":"A company has opening cash 20 and debt 140, with no scheduled repayment. EBIT is 80, depreciation 20, tax rate 25%, working capital investment 35 and cash capital spending 50. Interest cash cost is 10 and the minimum closing cash is 10. A downside covenant uses EBITDA 80 and requires closing net financial debt/EBITDA no greater than 2.0. All values are millions. It borrows only what is needed to reach the cash minimum. After financing the base plan, what is the maximum additional cash capital spending fundable by extra debt under the covenant, with EBITDA unchanged?","choices":["15.","25.","20.","30."],"correct_index":1,"explanation":"Base operating cash flow is 60+20-35-50=-5. Closing cash before finance is 20-5-10=5, so base borrowing 5 gives debt 145 and cash 10. Base net debt 135. Covenant ceiling is 160, leaving 25 of debt funded spending. Any additional draw is spent, so cash stays 10 and net debt rises one for one."}],"1":[{"id":"fm-s1-level1-v1-q1","session":"1","level":1,"topic":"Accrual to collections","question":"A company sells 200 in January, collecting 30% immediately and 70% the following month. December sales were 160 under the same terms. All amounts are thousands of euros and all customers pay on time. What January customer collections belong in the cash budget?","choices":["200.","140.","172.","220."],"correct_index":2,"explanation":"Collect 60 from January sales and 112 from December sales, for 172. Current revenue and current collections differ because of the contractual lag."},{"id":"fm-s1-level1-v1-q2","session":"1","level":1,"topic":"Profit and cash","question":"A company reports profit 40 after depreciation 15. Receivables rise 20 and inventory rises 10, while payables rise 5. There are no other operating adjustments or tax timing differences. All figures are thousands of euros. What is cash from operations?","choices":["40.","50.","20.","30."],"correct_index":3,"explanation":"Start with profit 40, add noncash depreciation 15, subtract 20 and 10 of working capital investment, then add 5 supplier finance. Cash from operations is 30."},{"id":"fm-s1-level1-v1-q3","session":"1","level":1,"topic":"Financing cash versus expense","question":"A month begins with cash 25. Collections are 70, supplier and wage payments 60, a machine costs 20, loan principal repayment 10 and cash interest 2. Profit already includes the 2 interest expense. All amounts are thousands of euros. With no new funding, what is closing cash?","choices":["3.","13.","23.","1."],"correct_index":0,"explanation":"Closing cash is 25+70-60-20-10-2=3. Principal is a cash outflow even though it is not an income statement expense. Do not subtract interest twice because it also appears in profit."},{"id":"fm-s1-level1-v1-q4","session":"1","level":1,"topic":"Minimum cash buffer","question":"A business starts a month with cash 12, collects 45 and has scheduled cash outflows 54. It must end with at least 8. Amounts are thousands of euros. What is the minimum funding draw, ignoring financing charges?","choices":["0.","5.","3.","8."],"correct_index":1,"explanation":"Before funding, cash is 12+45-54=3. The required draw is 8-3=5. A positive closing balance can still be below the operating cash minimum."},{"id":"fm-s1-level1-v1-q5","session":"1","level":1,"topic":"Purchases and payments","question":"A company pays 40% of inventory purchases in the purchase month and 60% the next month. January purchases are 90 and December purchases 70, in thousands of euros. What cash payment for purchases occurs in January?","choices":["90.","84.","78.","70."],"correct_index":2,"explanation":"Pay 36 on January purchases plus 42 on December purchases, totalling 78. Inventory purchases and payments need separate timing schedules."},{"id":"fm-s1-level1-v1-q6","session":"1","level":1,"topic":"Temporary liquidity gap","question":"A business starts January with 20 of cash. January net cash flow before financing is minus 35 and February net flow is plus 40. It cannot have negative cash at any month end. Figures are thousands of euros and financing charges are ignored. What is the minimum temporary facility needed despite the positive two month total?","choices":["0.","20.","35.","15."],"correct_index":3,"explanation":"January ends at minus 15 without funding. A facility of 15 bridges that low point. February can restore cash, but a later surplus cannot pay an earlier obligation without a financing bridge."},{"id":"fm-s1-level1-v1-q7","session":"1","level":1,"topic":"Noncash adjustment","question":"A company has revenue 100, cash operating costs 70 and depreciation 12 for the month. All revenue is collected and all cash costs paid in the month. It buys equipment for 20 in cash, has no taxes and no other flows. What are profit and net cash change?","choices":["Profit 18 and cash increase 10.","Profit 30 and cash increase 18.","Profit 18 and cash decrease 2.","Profit minus 2 and cash increase 10."],"correct_index":0,"explanation":"Profit is 100-70-12=18. Cash change is 100-70-20=10. Depreciation is noncash, while equipment purchase is a cash use rather than an immediate full expense."},{"id":"fm-s1-level1-v1-q8","session":"1","level":1,"topic":"Surplus use versus obligations","question":"A treasury budget projects 30 of available cash after all operating payments, but a 20 debt principal repayment next week is not included. The company needs a minimum cash buffer 8. Values are millions. How much can safely be placed in an investment that cannot be liquidated before the repayment?","choices":["10.","2.","22.","30."],"correct_index":1,"explanation":"Reserve 20 for the principal payment and 8 for minimum liquidity, leaving 2. Surplus is measured after relevant future cash obligations, not just current operating costs."},{"id":"fm-s1-level1-v1-q9","session":"1","level":1,"topic":"Momentum versus management action","question":"Without new action, a company expects revenue 100 and cash costs 90. An approved campaign would add revenue 20 and cash costs 15. Management presents revenue 120 and costs 105 as the unchanged business baseline. What correction makes the forecast useful for accountability?","choices":["Treat all 120 revenue as certain because the campaign is approved.","Remove the campaign costs but retain its revenue.","Keep the 100/90 momentum baseline separate from the 20/15 initiative.","Use only the campaign outcome and discard the baseline."],"correct_index":2,"explanation":"Separating the no action case from incremental initiative effects makes the 5 improvement in contribution visible. It avoids hiding execution dependence inside an apparently automatic baseline."},{"id":"fm-s1-level1-v1-q10","session":"1","level":1,"topic":"Different planning horizons","question":"A three year strategy generates positive cumulative cash, yet payroll is due in ten days and customer collections arrive in six weeks. Which planning response directly addresses the uncovered risk?","choices":["Rely on the cumulative three year surplus to prove solvency today.","Replace cash forecasts with revenue growth targets only.","Record the expected six week collection as cash today.","Build a near term dated cash budget and arrange the identified bridge funding."],"correct_index":3,"explanation":"A long term plan does not show whether payments can be met on a specific earlier date. Treasury needs cash timing and committed liquidity, not just eventual profitability."},{"id":"fm-s1-level2-v1-q1","session":"1","level":2,"topic":"Three month collection schedule","question":"Sales in December, January and February are 100,150 and 200 respectively, in thousands of euros. Every sale is collected 20% in its sale month,50% one month later and 30% two months later. What customer collections occur in February?","choices":["155.","175.","200.","145."],"correct_index":3,"explanation":"February receipts are .2×200 + .5×150 + .3×100 =40+75+30=145. Each cohort follows its own collection schedule."},{"id":"fm-s1-level2-v1-q2","session":"1","level":2,"topic":"Funding with investment and dividend","question":"A company begins with cash 18 and needs a minimum closing balance 10. Customer collections 80, cash operating payments 65, equipment purchase 25, tax payment 6 and dividend 5 all occur this month. All amounts are thousands of euros. What minimum new funding is needed?","choices":["13.","3.","8.","18."],"correct_index":0,"explanation":"Before financing cash is 18+80-65-25-6-5=-3. Raising 13 restores the minimum 10. Dividends and equipment spending must be included even if operating cash generation is positive."},{"id":"fm-s1-level2-v1-q3","session":"1","level":2,"topic":"Seasonal facility limit","question":"Opening cash is 10 and the minimum month end cash is 5. Net cash flows before financing are minus 12 in January, plus 4 in February and plus 20 in March. Amounts are thousands of euros and charges are ignored. A revolver can be drawn as needed and repaid when possible. What is the peak draw required?","choices":["2.","7.","5.","12."],"correct_index":1,"explanation":"January cash without funding is minus 2, requiring 7 to reach 5. February can repay 4, reducing debt to 3. March clears the remainder. The peak is 7, not the full January outflow 12."},{"id":"fm-s1-level2-v1-q4","session":"1","level":2,"topic":"Forecast error and cause","question":"A company forecasts sales 200 with 50% collected in the same month, plus 80 of collections from earlier sales. Actual sales are 180 and only 40% of current sales are collected immediately, while earlier collections remain 80. All values are thousands of euros. What collection shortfall versus budget occurs?","choices":["10.","20.","28.","36."],"correct_index":2,"explanation":"Budget receipts 180. Actual receipts 0.4×180+80=152. Shortfall 28 combines lower sales and slower conversion. At the old collection percentage, lower sales alone would explain only 10."},{"id":"fm-s1-level2-v1-q5","session":"1","level":2,"topic":"Payment deferral and next period","question":"A company has cash 8 and needs 5 at month end. It expects collections 50 and payments 60 in January. It can defer 10 of supplier payments from January to February, with no penalty. February net flow before this deferral is plus 4. There is no new funding. What are January and February closing balances after the deferral?","choices":["January 8 and February 12, so the deferral creates 10 permanent cash.","January minus 2 and February 2.","January 8 and February 5, because minimum cash is automatic.","January 8 and February 2, so the deferral shifts rather than solves the minimum cash problem."],"correct_index":3,"explanation":"January becomes 8+50-50=8. February then adds 4 but pays the delayed 10, ending 2. Delaying payment is a timing change and leaves February below the required 5."},{"id":"fm-s1-level2-v1-q6","session":"1","level":2,"topic":"Accrual tax and actual payment","question":"A monthly profit forecast is 30 after an 8 tax expense and 10 depreciation. Receivables increase 12, inventory is unchanged and payables increase 3. Actual cash tax paid is 5, not 8. No other items change. All figures are thousands of euros. What cash from operations results?","choices":["34.","31.","29.","26."],"correct_index":0,"explanation":"Profit 30+depreciation 10-receivables 12+payables 3=31 assuming accrued taxes were paid. Paying 3 less than accrued adds 3, giving 34. Tax expense timing differs from cash tax timing."},{"id":"fm-s1-level2-v1-q7","session":"1","level":2,"topic":"Do not duplicate financing","question":"Opening cash is 20 and operating cash inflow net of operating payments is 15. Capital spending is 25. A financing schedule already includes a new loan 10, principal repayment 8 and interest 2. All values are millions. The operating net flow excludes these financing items. What closing cash follows?","choices":["20.","10.","18.","0."],"correct_index":1,"explanation":"Cash is 20+15-25+10-8-2=10. A new loan is a cash source, principal repayment is a use, and financing charges must be recorded once, in the schedule where they occur."},{"id":"fm-s1-level2-v1-q8","session":"1","level":2,"topic":"Inflation drivers","question":"A company spends 60 on materials and 40 on services, in millions. Materials prices are expected to rise 10% and services prices 2%, with quantities unchanged. Revenue pricing rises 3%. What forecast cash cost and implication are correct?","choices":["Cost 103.0. Revenue inflation should drive every cost.","Cost 112.0. The two rates should be added then applied to all spending.","Cost 106.8. Applying 3% to all costs would understate the cash need by 3.8.","Cost 108.0. Use the simple average of the two inflation rates."],"correct_index":2,"explanation":"Materials become 66 and services 40.8, total 106.8. Applying 3% to 100 gives 103 and misses 3.8. Distinct cost exposures require their own drivers, even if selling prices rise at another rate."},{"id":"fm-s1-level2-v1-q9","session":"1","level":2,"topic":"Expected cash versus protection","question":"Month end cash before any new facility will be 20 with probability 75% and minus 12 with probability 25%. The required minimum is 4 in either state. Amounts are millions and no other source of cash is available. What facility size guarantees the minimum in the stated downside?","choices":["0, because expected cash is positive.","4, because that is the cash minimum.","12, because it covers only the negative balance.","16, even though expected cash is 12."],"correct_index":3,"explanation":"Expected cash is 0.75×20+.25×(-12)=12. Downside protection needs 4-(-12)=16. A probability weighted forecast is not a committed liquidity buffer."},{"id":"fm-s1-level2-v1-q10","session":"1","level":2,"topic":"Reconciliation across statements","question":"A business reports monthly profit 25 after depreciation 5 and interest 3. Receivables rise 8 and payables fall 4. It purchases equipment 12, repays principal 6 and raises new equity 10. All amounts are thousands of euros, with all other expenses paid and no additional items. What net cash change results?","choices":["10.","13.","16.","22."],"correct_index":0,"explanation":"Operating cash after already expensed interest is 25+5-8-4=18. Then subtract 12 capex and 6 principal and add 10 equity, leaving 10. Do not subtract the interest 3 again."},{"id":"fm-s1-level3-v1-q1","session":"1","level":3,"topic":"Peak funding not final funding","question":"A business starts with cash 12 and requires minimum cash 6 at each month end. Before financing, monthly net flows are minus 20, plus 5 and plus 25. It can draw and repay a revolver without charges. What are the peak revolver balance and the closing cash after all debt is repaid at the end of month 3?","choices":["Peak 14 and final cash 22.","Peak 8 and final cash 22.","Peak 14 and final cash 36.","Peak 20 and final cash 22."],"correct_index":0,"explanation":"Month 1 requires 14 to keep 6. Month 2 repays 5, leaving 9 debt and cash 6. Month 3 receives 25, repays 9 and ends 22. The final surplus cannot replace the need to arrange the 14 facility beforehand."},{"id":"fm-s1-level3-v1-q2","session":"1","level":3,"topic":"One time delay in customer collections","question":"A business has opening cash 15 and a cash minimum 5. Sales are 100 each month. Normally 50% is collected immediately and 50% next month. Starting in January, new sales are collected only the following month, while December balances follow old terms. Monthly operating payments are 90. Figures are thousands of euros. What new funding is needed in January and what is February cash after retaining that funding with no repayment?","choices":["January draw 40 and February cash 5.","January draw 30 and February cash 15.","January draw 0 and February cash 35.","January draw 30 and February cash 65."],"correct_index":1,"explanation":"January collects only 50 from December, so cash before funding is 15+50-90=-25. Draw 30 to reach 5. February collects 100 from January and pays 90, adding 10 to reach 15. Moving to slower terms creates an initial cash gap despite stable sales."},{"id":"fm-s1-level3-v1-q3","session":"1","level":3,"topic":"Supplier and customer shocks together","question":"A company expects opening cash 20, customer collections 100 and supplier payments 70, other payments 30, and requires closing cash 10. All amounts are millions. Customer delays reduce this month collections by 15, while a supplier accelerates 12 of next month payments into this month. What new funding is needed, and what is the correct interpretation?","choices":["27. The cash minimum must be added to every outflow regardless of opening cash.","5. Only customer delays affect operating cash.","17. The two timing shocks consume 27 of liquidity even if profit is unchanged.","0. Timing changes cannot alter cash if revenue and costs are unchanged."],"correct_index":2,"explanation":"Base closing cash 20. The two shocks reduce it by 27 to minus 7. Draw 17 to restore 10. Neither shock necessarily changes accrued profit, but both matter for payment capacity."},{"id":"fm-s1-level3-v1-q4","session":"1","level":3,"topic":"Cancellation of a planned initiative","question":"A baseline monthly cash budget has opening cash 10, cash collections 70 and payments 75. A planned initiative adds 20 of collections and 15 of payments during the month. Minimum closing cash is 8. The initiative is cancelled before any related cash flow occurs. All values are thousands of euros. How much does cancellation increase the required funding?","choices":["0, because both its receipts and payments disappear.","15, because only initiative costs should be removed.","20, because all cancelled receipts must be borrowed.","3, from 0 to 3."],"correct_index":3,"explanation":"With initiative closing cash is 10+90-90=10 and no draw is needed. Without it closing cash 5 requires 3 to reach 8. The funding increase is 3, not the full 5 net initiative contribution."},{"id":"fm-s1-level3-v1-q5","session":"1","level":3,"topic":"Back testing and a false plug","question":"Budget collections are 120 and operating payments 100. Actual collections are 100 and operating payments 108. A manager adds 28 of new borrowing into operating collections so that the operating cash variance disappears. What correction preserves the meaning of the cash budget?","choices":["Show operating cash deterioration of 28 and the 28 loan separately as financing.","Accept the loan as customer collections because both raise bank cash.","Reduce actual payments by 28 as an accounting balancing adjustment.","Erase the collections variance and retain only higher revenue targets."],"correct_index":0,"explanation":"Budget operating net inflow 20 becomes minus 8, a deterioration 28. Financing may cover the cash need but cannot turn borrowed cash into operating performance. Correct classifications keep cause and response visible."},{"id":"fm-s1-level3-v1-q6","session":"1","level":3,"topic":"Funding versus sustainable growth","question":"A company has rising accounting profit, but each extra 100 of annual sales needs 30 of additional working capital and 20 of cash capital spending. Extra operating cash before those investments is 25. A facility of 40 is available and existing cash is committed to other obligations. All values are millions. What is the maximum additional sales fundable for one year under these assumptions, and what must management recognise?","choices":["80. Only capital spending consumes cash.","160. Each 100 of sales absorbs 25 net cash, so growth consumes the finite facility.","200. The cash flow contribution 25 is ignored.","Unlimited. Profit growth proves that growth finances itself."],"correct_index":1,"explanation":"Each 100 adds 25-30-20=-25 cash. A 40 facility supports 40/25×100=160 extra sales. This addresses one year funding, not proof that indefinite growth or recurring investment needs are sustainable."},{"id":"fm-s1-level3-v1-q7","session":"1","level":3,"topic":"Cash floor and dividend choice","question":"Opening cash is 16, operating cash inflow after all operating payments is 12, equipment spending 18 and mandatory principal payment 6. A planned dividend 8 is discretionary. Minimum closing cash is 7. The company can borrow at most 4 this month and has no other cash source. All figures are millions. What largest dividend can it pay while meeting the minimum?","choices":["0.","4.","1.","5."],"correct_index":2,"explanation":"Before dividend or new debt cash is 16+12-18-6=4. Max borrowing 4 raises it to 8. Keeping 7 leaves dividend capacity 1. Borrowing 4 does not make the original dividend 8 affordable."},{"id":"fm-s1-level3-v1-q8","session":"1","level":3,"topic":"Intramonth timing","question":"A company starts with cash 10. On day 5 it must pay 25 to a supplier. On day 20 it receives 30 from customers and has no other flows. A month end budget therefore shows closing cash 15. Figures are millions, minimum cash is 0, and payments cannot be delayed. What funding conclusion follows?","choices":["No funding is needed because month end cash is 15.","A 25 bridge is needed because opening cash cannot pay suppliers.","A 30 permanent loan is needed because collections come later.","A 15 bridge is still needed before day 5 even though month end cash is positive."],"correct_index":3,"explanation":"Before the collection, available 10 falls short of the 25 payment by 15. Treasury must match actual payment dates, not assume that later monthly receipts can settle earlier obligations."},{"id":"fm-s1-level3-v1-q9","session":"1","level":3,"topic":"Three equilibria conflict","question":"A company forecasts growing net income and a balance sheet that balances because an automatic short term loan plug funds all cash shortfalls. The peak plug is 45, but banks have committed only 25 and there is no owner funding. Values are millions. Which assessment is correct?","choices":["The plan is arithmetically balanced but has an unfinanced liquidity gap of 20 and does not establish sustainability.","The balancing balance sheet proves the additional 45 will be available.","Profitable operations remove the need to verify lender commitments.","The missing 20 should be recorded as revenue to preserve income equilibrium."],"correct_index":0,"explanation":"An accounting funding plug is a requirement, not financing availability. Peak need 45 minus committed 25 leaves 20. Income, balance sheet and cash equilibria must be reconciled with actual funding constraints."},{"id":"fm-s1-level3-v1-q10","session":"1","level":3,"topic":"Comparing liquidity actions","question":"A company must cover an immediate cash shortage 12 and has no financing line. Action A sells inventory for 12 cash without losing future contribution. Action B recognises 18 of uncollected sales, with collection only next quarter. Action C defers depreciation 12 without changing asset cash payments. Figures are millions and no other effects apply. Which action actually covers the immediate shortage?","choices":["A and B.","Only A.","B and C.","All three."],"correct_index":1,"explanation":"Only A creates cash now under the stated assumptions. Accrued sales collected later and a noncash depreciation change cannot pay an immediate obligation. The question deliberately separates reported earnings from current liquidity."}],"2":[{"id":"fm-s2-level1-v1-q1","session":"2","level":1,"topic":"Cash conversion cycle","question":"A business holds inventory 45 days, collects customers after 35 days and pays suppliers after 30 days. What are its operating cycle and cash conversion cycle?","choices":["Operating cycle 50 days and cash conversion cycle 80 days.","Operating cycle 110 days and cash conversion cycle 80 days.","Operating cycle 45 days and cash conversion cycle 10 days.","Operating cycle 80 days and cash conversion cycle 50 days."],"correct_index":3,"explanation":"Operating cycle is 45+35=80 days. Supplier finance covers 30 of those days, leaving a 50 day cash conversion cycle."},{"id":"fm-s2-level1-v1-q2","session":"2","level":1,"topic":"Receivable cash release","question":"Annual credit sales are EUR 36 million, with a 360 day year and stable daily sales. A collection improvement reduces days sales outstanding from 50 to 35. With no sales loss or bad debt change, how much cash is released once?","choices":["EUR 1.5 million.","EUR 1.0 million.","EUR 3.5 million.","EUR 5.0 million."],"correct_index":0,"explanation":"Daily sales are 0.1 million. A 15 day reduction releases 15×.1=1.5 million. The release is a balance sheet cash effect, not 1.5 million of recurring extra annual revenue."},{"id":"fm-s2-level1-v1-q3","session":"2","level":1,"topic":"Inventory days denominator","question":"Annual sales are 120 and cost of goods sold 90, with average inventory 15, all in millions. Use 360 days. What inventory days result when measured at cost?","choices":["45 days.","60 days.","30 days.","80 days."],"correct_index":1,"explanation":"Inventory is measured at cost, so daily cost of goods sold is 90/360=.25. Inventory days are 15/.25=60. Using sales instead understates the period."},{"id":"fm-s2-level1-v1-q4","session":"2","level":1,"topic":"Supplier term change","question":"A firm has annual cost of goods sold 72 million euros on a 360 day basis. Suppliers cut payment terms from 45 days to 30 days, with purchases tracking cost of goods sold and no other change. What immediate funding effect follows at steady activity?","choices":["A EUR 3 million cash release.","A EUR 6 million cash need.","A EUR 3 million cash need.","No cash effect because operating profit is unchanged."],"correct_index":2,"explanation":"Daily supplier funded costs are 0.2 million. Losing 15 days of payable finance reduces payables by 3 million and creates an equal cash need."},{"id":"fm-s2-level1-v1-q5","session":"2","level":1,"topic":"Working capital versus ratios","question":"A company has cash 10, receivables 40, inventory 30 and operating payables 35, all in millions. Define operating working capital as receivables plus inventory minus operating payables. What amount is tied up?","choices":["45.","70.","105.","35."],"correct_index":3,"explanation":"Operating working capital is 40+30-35=35. Cash is excluded under the stated operating definition. A larger current asset balance is not automatically efficient cash management."},{"id":"fm-s2-level1-v1-q6","session":"2","level":1,"topic":"Credit expected gain","question":"A new customer offers an order priced 100 with a cash production cost 75. It pays in full with probability 80% and pays nothing otherwise. Ignore timing, tax and recovery. Refusing credit yields 0. What expected incremental gain follows from granting credit?","choices":["5.","20.","25.","Minus 15."],"correct_index":0,"explanation":"Expected receipt is 0.8×100=80 and production cost 75 is incurred whether payment arrives or not. Expected gain 5 equals 0.8×25-.2×75."},{"id":"fm-s2-level1-v1-q7","session":"2","level":1,"topic":"Credit threshold","question":"An order has selling price 120 and unavoidable cash cost 90 if accepted. Payment is all or nothing, with no recovery. Ignore discounting. What minimum payment probability makes its expected profit nonnegative?","choices":["25%.","75%.","60%.","90%."],"correct_index":1,"explanation":"Expected profit is 120 p-90. Set it at 0 to getp=.75. The risk tolerance depends on the margin rather than a blanket requirement that every customer pay with certainty."},{"id":"fm-s2-level1-v1-q8","session":"2","level":1,"topic":"Inventory and service","question":"A factory has highly variable delivery times and uncertain demand. Its manager proposes eliminating every inventory buffer solely to maximise cash release. Which assessment best reflects the inventory trade off?","choices":["Zero inventory is always optimal because storage has a cost.","Higher demand uncertainty automatically makes all inventory valueless.","Cash may be released, but lost sales and production interruptions must be weighed against lower carrying costs.","The decision can ignore customer service because inventory is a balance sheet item."],"correct_index":2,"explanation":"Inventory supports continuity and unexpected demand, while carrying and ordering cost cash. A stable, predictable flow makes lean inventory easier than the stated volatile setting."},{"id":"fm-s2-level1-v1-q9","session":"2","level":1,"topic":"Negative cash cycle","question":"A retailer collects from customers 10 days after purchase of its inventory and pays suppliers 30 days after purchase. Inventory is sold immediately on day 0, and both timings use the same purchase date. What cash conversion cycle and implication follow?","choices":["Plus 20 days, so suppliers are paid before collection.","Plus 40 days, because the two periods are added.","Zero days, because the stock is sold immediately.","Minus 20 days, so collections precede supplier payments."],"correct_index":3,"explanation":"Inventory days 0 plus receivable days 10 minus payable days 30 gives minus 20. This is a timing benefit, not a guarantee that the retailer is profitable."},{"id":"fm-s2-level1-v1-q10","session":"2","level":1,"topic":"Aging and hidden deterioration","question":"Total receivables stay at 40 million euros, but the amount overdue more than 90 days rises from 4 to 12 million. Sales are unchanged. What is the most useful interpretation?","choices":["Collection quality has worsened even though the total receivable balance is stable.","Collection risk is unchanged because total receivables are 40.","The overdue increase proves an 8 million cash inflow.","All 40 million must now be written off immediately under every accounting rule."],"correct_index":0,"explanation":"The aging mix identifies deterioration hidden in the aggregate. It prompts attention to delayed and doubtful accounts, without by itself determining a particular write off amount."},{"id":"fm-s2-level2-v1-q1","session":"2","level":2,"topic":"Several days changes","question":"A company uses a 360 day year, annual sales 180 and cost of goods sold 120, both in millions. It reduces receivable days by 6 and inventory days by 9 but loses 3 days of supplier credit. What net one time cash release follows, with activity unchanged?","choices":["7 million.","5 million.","6 million.","3 million."],"correct_index":1,"explanation":"Receivables release 6×.5=3. Inventory releases 9×(120/360)=3. Shorter payables consume 3×(120/360)=1. Net release 5 million."},{"id":"fm-s2-level2-v1-q2","session":"2","level":2,"topic":"Growth despite improved days","question":"Annual sales rise from 120 to 150 million euros and cost of goods sold remains 60% of sales. Use 360 days. Receivable days fall from 45 to 36, inventory days stay 30 and payable days stay 30. What change in operating working capital results?","choices":["A 3.75 million cash release.","A 3.75 million cash need.","No change.","A 7.5 million cash release."],"correct_index":2,"explanation":"Old receivables 120/360×45=15 and new 150/360×36=15. Inventory and payables offset at identical cost based days. Working capital remains 15 even though receivable days improve."},{"id":"fm-s2-level2-v1-q3","session":"2","level":2,"topic":"Profitable longer credit","question":"A firm has annual sales 100 million euros and contribution margin 30%. Extending payment terms raises annual sales by 10 million and increases average receivables by 8 million. Annual funding cost is 10% of the incremental receivables, and expected incremental bad debts are 0.5 million annually. Ignore tax and all other changes. What is the annual incremental profit after funding cost?","choices":["EUR 2.5 million.","EUR 2.2 million.","Minus EUR 5.5 million.","EUR 1.7 million."],"correct_index":3,"explanation":"Extra contribution is 10×30%=3. Funding costs 8×10%=.8 and extra bad debts 0.5. Incremental annual gain 1.7. The 8 million balance investment is not itself an annual expense."},{"id":"fm-s2-level2-v1-q4","session":"2","level":2,"topic":"Screening fee","question":"An order has selling price 200 and cash production cost 150. Payment probability is 78%, with zero payment on default. A one time screening cost 4 must be paid before supplying the customer and does not change payment probability. Ignore time and taxes. What expected gain remains after screening?","choices":["2.","6.","10.","Minus 4."],"correct_index":0,"explanation":"Expected receipts 0.78×200=156. Production plus screening cost 154, giving 2. Expected profit without screening is 6, but the screening is not free."},{"id":"fm-s2-level2-v1-q5","session":"2","level":2,"topic":"Customer prepayment","question":"An order is priced 100. A customer pays 20 upfront for certain and owes 80 later. Production costs 75 upfront. The deferred balance is paid with probability 65%, otherwise there is no further recovery. Ignore discounting. What expected incremental profit results?","choices":["Plus 10.","Minus 3.","Plus 17.","Minus 10."],"correct_index":1,"explanation":"Expected receipt is 20+.65×80=72. Subtract 75 cost to get minus 3. The certain deposit reduces credit exposure but does not automatically make a risky order worthwhile."},{"id":"fm-s2-level2-v1-q6","session":"2","level":2,"topic":"Inventories versus payables","question":"A company has annual cost of goods sold 144 million euros on a 360 day basis. A bulk order policy increases average inventory by 12 days but earns an annual purchase saving 1 million. Suppliers extend payment terms by 7 days. Funding cost is 12% annually on the net extra working capital. Ignore taxes and other costs. What net annual benefit follows?","choices":["EUR 0.424 million.","EUR 1.24 million.","EUR 0.76 million.","Minus EUR 1.0 million."],"correct_index":2,"explanation":"Net extra days 12-7=5, at 0.4 million daily cost, tying up 2 million. Funding cost 0.24 million. Net annual saving 1-.24=.76 million. The inventory and payable changes must be assessed together."},{"id":"fm-s2-level2-v1-q7","session":"2","level":2,"topic":"Credit rationing by expected value","question":"Two customers each require production cost 80 and would pay 100 if they pay in full. Customer A payment probability is 90%, B is 75%, with zero recovery and no future business effects. The company can fund only one order. Ignore timing. Which order should it fund to maximise expected gain?","choices":["B, because accepting more risk always means higher value.","Either, because both have a 20 gross margin if paid.","Neither, because a payment probability below 100% is unacceptable.","A, with expected gain 10 versus B minus 5."],"correct_index":3,"explanation":"A has 0.9×100-80=10 expected gain. B has 0.75×100-80=-5. Expected value includes the cost incurred in default, not only the margin in the successful state."},{"id":"fm-s2-level2-v1-q8","session":"2","level":2,"topic":"Faster collections but lost margin","question":"A credit tightening releases 4 million euros of receivables once. It also causes a permanent annual loss of 0.7 million in contribution, but saves 0.2 million of annual bad debts and 0.4 million in annual funding costs on the released receivables. Ignore tax. What is the recurring annual profit effect?","choices":["A decline ofEUR 0.1 million, despite the one time cash release.","An increase ofEUR 3.9 million every year.","An increase ofEUR 0.6 million.","No effect, because cash release and profit always coincide."],"correct_index":0,"explanation":"Annual effect is-.7+.2+.4=-.1 million. The 4 million release is a one time reduction of invested capital, not 4 million of annual earnings. This does not alone settle total value without a horizon."},{"id":"fm-s2-level2-v1-q9","session":"2","level":2,"topic":"Operating and cash cycles diverge","question":"A firm improves inventory days from 60 to 45 but customer collection days worsen from 30 to 40. Supplier payment days fall from 45 to 25. What happens to its operating cycle and cash conversion cycle?","choices":["Both cycles shorten 5 days.","Operating cycle shortens 5 days, but cash conversion cycle lengthens 15 days.","Operating cycle lengthens 15 days and cash cycle shortens 5 days.","Both cycles lengthen 15 days."],"correct_index":1,"explanation":"Operating cycle changes from 90 to 85. Cash cycle changes from 90-45=45 to 85-25=60. Losing supplier finance more than offsets the operating cycle improvement."},{"id":"fm-s2-level2-v1-q10","session":"2","level":2,"topic":"Balance sheet release versus recurring revenue","question":"A firm reduces working capital from 30 to 24 million euros without changing sales or costs. Its annual financing rate on working capital is 8%. Ignoring tax, what are the initial cash release and annual financing cost saving?","choices":["EUR 6 million per year and EUR 0.48 million once.","EUR 24 million once and EUR 1.92 million per year.","EUR 6 million once and EUR 0.48 million per year.","EUR 0.48 million once and EUR 6 million per year."],"correct_index":2,"explanation":"The stock reduction releases 6 million once. At 8% it avoids 0.48 million of annual finance cost while the reduction persists. Separating stocks from flows prevents overstating recurring benefits."},{"id":"fm-s2-level3-v1-q1","session":"2","level":3,"topic":"Integrated growth and supplier stress","question":"A company uses 360 days. Sales grow from 180 to 216 million euros, while cost of goods sold stays two thirds of sales. Receivable days improve from 50 to 45, inventory days stay 40 and supplier days fall from 35 to 25. What additional operating working capital is needed?","choices":["EUR 2 million, approximately.","EUR 5.333 million, approximately.","A EUR 2 million cash release.","EUR 6.333 million, approximately."],"correct_index":3,"explanation":"Old receivables 25, inventory 13.333 and payables 11.667 give 26.667 million. New receivables 27, inventory 16 and payables 10 give 33 million. Increase 6.333 million. Growth and lost supplier credit outweigh the collection improvement."},{"id":"fm-s2-level3-v1-q2","session":"2","level":3,"topic":"Credit risk and repeat orders","question":"A first order earns 20 if the customer pays and loses 80 if it defaults. Payment probability is 75%. If the first order is paid, there is a further 70% chance of a later relationship worth 15 in present value today. No later relationship follows default. Refusing yields 0. All amounts are thousands of euros and the future value is already discounted. What expected value follows from acceptance?","choices":["Plus 2.875.","Minus 5.","Plus 5.5.","Plus 10.75."],"correct_index":0,"explanation":"First order value is 0.75×20-.25×80=-5. Future conditional value is 0.75×.70×15=7.875. Total 2.875. Looking beyond the first order can change the decision, but only with explicit probabilities and cash value."},{"id":"fm-s2-level3-v1-q3","session":"2","level":3,"topic":"Minimum deposit for risky credit","question":"An order costs 90 upfront and has total selling price 120. A deposit d is paid certainly before production. The remaining 120-d is paid with probability 60%, with zero recovery on default. Ignore timing. What minimum deposit gives nonnegative expected profit?","choices":["18.","45.","30.","54."],"correct_index":1,"explanation":"Expected receipt isd+.6(120-d)=72+.4 d. Need 72+.4 d≥90, so d≥45. The deposit lowers the uncertain amount while total selling price stays 120."},{"id":"fm-s2-level3-v1-q4","session":"2","level":3,"topic":"Credit investigation conditional outcomes","question":"An order costs 80 and sells for 100. Without information the customer pays with probability 78%, with zero recovery. An investigation costing 2 reveals good type with probability 60% and bad type 40%. Payment probabilities are 95% for good and 52.5% for bad. The firm may reject after investigation, avoiding production cost. Ignore timing. What is the expected value of investigating and optimally deciding?","choices":["Minus 2.","9.","7.","13."],"correct_index":2,"explanation":"Good expected gain is 0.95×100-80=15 and bad gain 0.525×100-80=-27.5. Accept only good. Before the information cost, expected value 0.6×15=9. After 2, value 7. Without information value is 78-80=-2."},{"id":"fm-s2-level3-v1-q5","session":"2","level":3,"topic":"Profitability cost of a cash target","question":"A firm needs an immediate 3 million euros cash release. Reducing receivable days by 10 releases 2 million but loses 0.4 million annual contribution. Reducing inventory days by 5 releases 1 million but adds 0.1 million annual handling cost. Both actions can be implemented together and there are no other options. Annual finance rate is 10% on released funds. Ignore tax. If both actions are used, what are the immediate liquidity and recurring profit effects?","choices":["Cash release 3 million and annual profit increase 2.5 million.","Cash release 2 million and annual profit decline 0.1 million.","Cash release 3 million and annual profit increase 0.3 million.","Cash release 3 million and annual profit decline 0.2 million."],"correct_index":3,"explanation":"The actions meet the 3 million immediate target. Annual finance savings are 0.3 million, but contribution and handling losses total 0.5 million, leaving-.2 million per year. Meeting a liquidity constraint can have an economic cost."},{"id":"fm-s2-level3-v1-q6","session":"2","level":3,"topic":"Unexpected supplier payment and cash cycle","question":"A company has stable annual sales 360 and cost of goods sold 240 million euros on a 360 day year. Receivables are 40, inventory 30 and payables 20 million. A supplier change cuts payable days by 9 while a customer initiative cuts receivable days by 4. Inventory is unchanged. What are the net cash need and the new cash conversion cycle?","choices":["Cash need 2 million and cash cycle 60 days.","Cash release 2 million and cash cycle 50 days.","Cash need 5 million and cash cycle 60 days.","Cash release 4 million and cash cycle 51 days."],"correct_index":0,"explanation":"Initial receivable days 40, inventory 45 and payables 30 give 55 day cash cycle. Payables fall 9×(240/360)=6 million, while receivables release 4×1=4 million. Net cash need 2 million. New cycle 36+45-21=60 days."},{"id":"fm-s2-level3-v1-q7","session":"2","level":3,"topic":"Comparing collection policies with bad debt","question":"Current annual sales are 100 million euros with contribution margin 25%, average receivables 20 million and annual bad debts 2 million. A stricter policy reduces sales by 8 million, receivables by 6 million and bad debts by 1.3 million annually. Funding cost is 10% of receivables. No other cost or tax effects arise. What is the recurring annual profit change and one time cash release?","choices":["Annual profit rises 0.1 million and cash release 6 million.","Annual profit falls 0.1 million and cash release is 6 million.","Annual profit rises 5.9 million and cash release 0.","Annual profit falls 2 million and cash release 1.3 million."],"correct_index":1,"explanation":"Lost contribution 8×25%=2 million. Benefits 1.3 bad debt saving+.6 financing saving=1.9. Net annual change-.1 million, while reducing receivables releases 6 million once. The answer does not confuse avoided losses with retained sales."},{"id":"fm-s2-level3-v1-q8","session":"2","level":3,"topic":"Annual cash budget from working capital","question":"A firm has cash profit before working capital investment of 18 million euros this year. Receivables rise 7, inventory rises 4 and payables rise 3 million. It also pays 6 million capital spending and 5 million loan principal, with no other flows. Opening cash is 4 and the minimum closing cash is 3. What new funding is required?","choices":["3 million, because all receivable growth must be borrowed.","4 million, because working capital consumes 11 million.","No funding is required. Closing cash is 3 million.","5 million, because principal is not covered by profit."],"correct_index":2,"explanation":"Net working capital investment is 7+4-3=8. Operating cash after that is 10. After capex 6 and principal 5, cash falls 1. Opening 4 becomes 3, exactly the minimum. A positive working capital need does not by itself equal external funding need."},{"id":"fm-s2-level3-v1-q9","session":"2","level":3,"topic":"Inventory policy with customer consequences","question":"A company releases 5 million euros by reducing safety inventory. This saves 0.5 million annual financing cost and 0.2 million annual storage cost. Expected annual lost contribution from stockouts is 0.9 million. There are no other effects or tax. Over a one year evaluation, use the capital release only as available cash, not as revenue. Which conclusion is correct?","choices":["The 5 million release proves annual profit rises 4.8 million.","Profit rises 0.7 million because lost sales have no cash consequence.","There is no cash release because inventory is not a financial asset.","Liquidity improves by 5 million, but recurring operating and financing profit falls 0.2 million."],"correct_index":3,"explanation":"Recurring effects are+.5+.2-.9=-.2 million. The 5 million capital release is real liquidity, but it is not annual revenue. A cost saving inventory plan must consider service failures."},{"id":"fm-s2-level3-v1-q10","session":"2","level":3,"topic":"Selective credit and capacity","question":"A firm can produce only one of two orders. A costs 60 and sells for 90 with payment probability 75%. B costs 75 and sells for 100 with payment probability 90%. Payment is all or nothing, with zero default recovery. A buyer who pays orderA brings an additional future relationship worth 10 in present value, while B brings none. All values are thousands of euros, with no other costs. Which order maximises expected value?","choices":["They tie at 15 under the stated assumptions.","A, because its successful transaction margin is 30.","A, with expected value 17.5 versus B 15.","Either, because both expected first order values are equal."],"correct_index":0,"explanation":"A first order value 0.75×90-60=7.5. Conditional future value 0.75×10=7.5, so total 15. B value 0.9×100-75=15. They tie at 15 under the stated assumptions."}],"3":[{"id":"fm-s3-level1-v1-q1","session":"3","level":1,"topic":"Volume and price drivers","question":"A firm sells 100,000 units at EUR 50 each. Next year volume rises 10% and price rises 4%. No product mix changes. What forecast revenue results?","choices":["EUR 5.70 million.","EUR 5.50 million.","EUR 5.20 million.","EUR 5.72 million."],"correct_index":3,"explanation":"Forecast volume 110,000 and price 52 give revenue 5.72 million. The two growth factors multiply, rather than simply adding percentages."},{"id":"fm-s3-level1-v1-q2","session":"3","level":1,"topic":"Control account for assets","question":"Opening net fixed assets are 80, cash capital spending 25 and depreciation 12, all in millions. No disposals, impairments or revaluations occur. What closing net fixed asset balance results?","choices":["93.","117.","68.","105."],"correct_index":0,"explanation":"The control account closes at 80+25-12=93. It links the separately forecast additions and consumption of assets, rather than creating another growth assumption."},{"id":"fm-s3-level1-v1-q3","session":"3","level":1,"topic":"Forecast working capital","question":"Forecast annual sales are 180 million euros on a 360 day basis. Days sales outstanding are 40. What receivable balance is implied?","choices":["EUR 18 million.","EUR 20 million.","EUR 16.2 million.","EUR 4.5 million."],"correct_index":1,"explanation":"Daily sales are 180/360=.5 million, giving receivables 40×.5=20 million. The receivable forecast is a stock derived from the sales flow and collection delay."},{"id":"fm-s3-level1-v1-q4","session":"3","level":1,"topic":"Debt control account","question":"A company opens with 90 of debt, issues 20 and repays 15 principal during the year. Interest expense is 6 and is paid in cash rather than capitalised. Amounts are millions. What closing debt balance follows?","choices":["101.","89.","95.","125."],"correct_index":2,"explanation":"Debt principal closes at 90+20-15=95. Paid interest is not added to the principal control account under the stated cash interest assumption."},{"id":"fm-s3-level1-v1-q5","session":"3","level":1,"topic":"Equity link","question":"Opening equity is 100, forecast net income 18, dividends 6 and a new cash share issue 20, all in millions. No other equity changes occur. What closing equity results?","choices":["112.","138.","144.","132."],"correct_index":3,"explanation":"Equity closes at 100+18-6+20=132. Net income increases retained value, dividends reduce it, and the share issue is a separate capital addition."},{"id":"fm-s3-level1-v1-q6","session":"3","level":1,"topic":"Cost drivers and fixed costs","question":"Revenue is forecast to rise from 100 to 120 million euros. Variable cash cost is 60% of revenue, while fixed cash costs remain 20 million. What cash operating profit before depreciation results?","choices":["28 million.","24 million.","32 million.","48 million."],"correct_index":0,"explanation":"Variable cost becomes 72 and fixed cost remains 20. Cash operating profit is 120-72-20=28. Scaling fixed costs by revenue would assume away operating leverage."},{"id":"fm-s3-level1-v1-q7","session":"3","level":1,"topic":"Top down revenue forecast","question":"An industry sells 2 million units at an average priceEUR 80. A company expects market share 3%, with its own price equal to that market average. What revenue is implied?","choices":["EUR 6.0 million.","EUR 4.8 million.","EUR 48 million.","EUR 160 million."],"correct_index":1,"explanation":"Market revenue is 2 million×80=160 million euros. Company share 0.03 gives 4.8 million. Share is applied to the market once, not treated as a standalone euro amount."},{"id":"fm-s3-level1-v1-q8","session":"3","level":1,"topic":"Cash roll forward","question":"Opening cash is 12 million. Forecast cash flow before financing is minus 7, while new debt proceeds 10 and principal repayment 4 are the only financing flows. What closing cash should be linked into the balance sheet?","choices":["5 million.","15 million.","11 million.","19 million."],"correct_index":2,"explanation":"Cash closes at 12-7+10-4=11. The cash flow statement and closing balance sheet cash must use the same integrated calculation."},{"id":"fm-s3-level1-v1-q9","session":"3","level":1,"topic":"Forecast capacity constraint","question":"A business forecasts sales volume 100,000 units, but current annual capacity is 80,000 and the plan includes neither expansion nor outsourcing. What is the first modelling inconsistency to fix?","choices":["The plan must automatically increase selling price 25%.","The gap can be fixed by adding a cash balance plug.","Depreciation must be eliminated to create physical capacity.","The revenue volume exceeds the stated operating capacity."],"correct_index":3,"explanation":"Volume targets need operational support. A financial balancing entry cannot create production capacity. Revise volume or include a credible capacity action and its cash effects."},{"id":"fm-s3-level1-v1-q10","session":"3","level":1,"topic":"Model design for a user","question":"A bank restructuring discussion concerns payments due each month over the next year. The only model supplied contains annual totals for five years and no creditor schedule. What change best fits the purpose?","choices":["Add monthly creditor specific maturities and cash availability for the near term.","Add more decimal places to the annual revenue forecast.","Replace all payments with a terminal enterprise value.","Remove the financing schedule to keep the model short."],"correct_index":0,"explanation":"Fitness for purpose requires seeing when and to whom cash is due. More annual precision does not reveal a within year funding gap."},{"id":"fm-s3-level2-v1-q1","session":"3","level":2,"topic":"Detailed depreciation assumption","question":"Opening assets of 40 million euros have 4 years of remaining useful life and zero residual value. New capital spending of 12 million has a 6 year life and zero residual value. Use straight line depreciation and charge half a year on new spending in the first year. No assets are disposed of. What are first year depreciation and closing net assets?","choices":["Depreciation 11 million and closing assets 41 million.","Depreciation 12 million and closing assets 40 million.","Depreciation 10 million and closing assets 42 million.","Depreciation 7 million and closing assets 45 million."],"correct_index":0,"explanation":"Existing assets depreciate 40/4=10. New spending adds 12/6×.5=1. Total depreciation 11 and closing assets 40+12-11=41. The timing convention must be explicit."},{"id":"fm-s3-level2-v1-q2","session":"3","level":2,"topic":"Working capital by different denominators","question":"Forecast annual sales are 240 and cost of goods sold 180 million euros on 360 days. Receivable days 45, inventory days 40 and payable days 30 are used, with inventory and payables based on cost of goods sold. What operating working capital results?","choices":["30 million.","35 million.","40 million.","36.67 million."],"correct_index":1,"explanation":"Receivables 240/360×45=30, inventory 180/360×40=20 and payables 180/360×30=15. Net working capital 30+20-15=35 million."},{"id":"fm-s3-level2-v1-q3","session":"3","level":2,"topic":"A growing service ratio","question":"Forecast revenue is 150 million euros. Service cost was 30% of revenue last year, and management targets a 2 percentage point decrease this year. Other cash costs are 70 million. What cash operating profit before depreciation results if the target is met?","choices":["35 million.","35.9 million.","38 million.","42 million."],"correct_index":2,"explanation":"The ratio becomes 28%, so service cost 42 million. Cash operating profit 150-42-70=38. A 2 percentage point cut differs from reducing the 30% ratio by 2% relative."},{"id":"fm-s3-level2-v1-q4","session":"3","level":2,"topic":"Dividends after funding cost","question":"EBIT is 30 million, cash interest 6 million and the tax rate 25% on earnings before tax, with no other income or expense. Dividends are 40% of net income. What dividend and retained earnings increase result?","choices":["Dividend 9 million and retained earnings increase 13.5 million.","Dividend 12 million and retained earnings increase 6 million.","Dividend 7.2 million and retained earnings increase 18 million.","Dividend 7.2 million and retained earnings increase 10.8 million."],"correct_index":3,"explanation":"Earnings before tax 24, tax 6 and net income 18. Dividend 18×.4=7.2 and retained increase 18-7.2=10.8. Payout is based on completed net income after interest and tax."},{"id":"fm-s3-level2-v1-q5","session":"3","level":2,"topic":"Gross versus net debt interest","question":"A company has average gross debt 100 and average cash 30 million euros. Debt costs 6% and cash earns 2%. Interest and income accrue for a full year with no compounding. What net financial expense should be forecast?","choices":["5.4 million.","4.2 million.","6.6 million.","1.4 million."],"correct_index":0,"explanation":"Debt expense 6 million minus cash income 0.6 million gives 5.4. Applying 6% to net debt 70 would give 4.2 and wrongly assume the cash earns the borrowing rate."},{"id":"fm-s3-level2-v1-q6","session":"3","level":2,"topic":"Price volume and cost consistency","question":"A company sells 1 million units atEUR 10, with variable costEUR 6 per unit and annual fixed cash cost 2 million euros. Next year volume rises 20%, selling price rises 5% and unit variable cost rises 10%, while fixed costs stay unchanged. What cash operating profit is forecast?","choices":["EUR 2.80 million.","EUR 2.68 million.","EUR 3.04 million.","EUR 4.68 million."],"correct_index":1,"explanation":"Revenue 1.2 million×10.5=12.6 million. Variable cost 1.2 million×6.6=7.92 million. Subtract fixed 2 million to get 2.68 million. Cost and revenue inflation are separate assumptions."},{"id":"fm-s3-level2-v1-q7","session":"3","level":2,"topic":"Driver versus debt availability","question":"A forecast sets closing debt at 50% of projected equity 100 million euros. Opening debt is 30 million and 5 million principal matures during the year. No new loan has been approved. What does the forecast actually imply?","choices":["It implies only 20 million new borrowing, ignoring repayment.","No new borrowing is implied because the ratio is a balance sheet driver.","It implies 25 million of new borrowing that still needs a credible financing source.","It proves lenders have approved 25 million."],"correct_index":2,"explanation":"Target closing debt 50=opening 30+new issues-5 repayment, so new issues 25. A leverage target implies funding activity but does not authorise or guarantee lender capacity."},{"id":"fm-s3-level2-v1-q8","session":"3","level":2,"topic":"Consolidation in a planning model","question":"Business unitA sells 80 million euros externally and 20 million to unitB. UnitB sells 120 million externally. No other sales occur. What group revenue should the forecast show after eliminating the internal sale?","choices":["220 million.","180 million.","100 million.","200 million."],"correct_index":3,"explanation":"External group revenue is 80+120=200 million. The 20 internal sale is included in a unit view but eliminated for the group, otherwise it counts an internal transfer as customer revenue."},{"id":"fm-s3-level2-v1-q9","session":"3","level":2,"topic":"Working capital driver improvement","question":"Sales rise from 180 to 216 million euros, with 360 days. Receivable days fall from 50 to 40. What happens to receivables and cash invested in that account, assuming all else unchanged?","choices":["Receivables fall from 25 to 24 million, releasing 1 million.","Receivables rise from 25 to 30 million, consuming 5 million.","Receivables fall by 20%, releasing 5 million.","Receivables stay 25 million because growth and efficiency always cancel."],"correct_index":0,"explanation":"Old balance 180/360×50=25. New 216/360×40=24. The lower days more than offset sales growth in this particular case, releasing 1 million."},{"id":"fm-s3-level2-v1-q10","session":"3","level":2,"topic":"Missing linkage audit","question":"A model forecasts net income 20 million and dividends 5 million. It holds total equity at the opening 100 million despite no share transactions or other equity movements. The cash flow and all other schedules are correct. What equity correction is required?","choices":["Keep equity 100 million because profits are only an income statement item.","Close equity at 115 million by linking the 15 million retained profit.","Close equity 120 million and ignore dividends.","Reduce equity to 85 million because retention uses cash."],"correct_index":1,"explanation":"The missing control account movement is net income 20 minus dividends 5, adding 15 to equity. Correct statement links are necessary even before investigating cash funding."},{"id":"fm-s3-level3-v1-q1","session":"3","level":3,"topic":"Integrated income cash and assets","question":"A firm opens with cash 10 and net fixed assets 50 million euros. Forecast revenue 100 and cash operating costs 65 are fully collected and paid in the year. Depreciation 10, tax 25% of EBIT, cash capital spending 20 and a 6 million working capital increase are forecast. There is no debt or other flow. What closing cash and net fixed assets result?","choices":["Cash 18.75 million and net fixed assets 60 million.","Cash 12.75 million and net fixed assets 60 million.","Cash 12.75 million and net fixed assets 70 million.","Cash 2.75 million and net fixed assets 60 million."],"correct_index":1,"explanation":"EBIT 25 and tax 6.25 give net income 18.75. Cash flow is 18.75+10-6-20=2.75, so closing cash 12.75. Net assets 50+20-10=60. Depreciation affects profit and the asset roll forward, not cash directly."},{"id":"fm-s3-level3-v1-q2","session":"3","level":3,"topic":"Average balance circularity","question":"A company has opening cash 10 million euros and a forecast net cash inflow of 20 million before interest income. It has no debt and pays no tax. Cash earns 4% on the arithmetic average of opening and closing cash for the year. Interest is collected at year end. What closing cash solves the circularity, rounded to two decimals?","choices":["EUR 30.40 million.","EUR 31.20 million.","EUR 30.82 million.","EUR 30.80 million."],"correct_index":2,"explanation":"Let closing cashC. Then C=10+20+.04(10+C)/2=30.2+.02 C. Thus 0.98 C=30.2 andC=30.8163265. Using opening cash only would avoid circularity but understate income under this stated average convention."},{"id":"fm-s3-level3-v1-q3","session":"3","level":3,"topic":"Model sustainability under linked growth","question":"A company projects additional annual revenue 60 million euros with cash contribution margin 25%. Supporting that growth requires an additional 12 million working capital investment and 10 million immediate cash capital spending. There is no other incremental flow or available opening cash. A committed loan covers only 5 million. Ignore tax and interest for this planning test. What funding shortfall remains?","choices":["7 million.","17 million.","No shortfall because contribution is positive.","2 million."],"correct_index":3,"explanation":"Incremental cash contribution 15 less 12 working capital and 10 capital spending gives a 7 million cash need. The 5 million loan covers part, leaving 2 million unfinanced. Revenue and profit growth do not remove the cash investment."},{"id":"fm-s3-level3-v1-q4","session":"3","level":3,"topic":"Why balancing is not verification","question":"A three statement forecast balances only because every unexplained difference is posted to cash. Cash becomes positive, but there is no cash flow reconciling the added amount and no financing source. Which audit response is sound?","choices":["Trace and correct the missing statement link rather than accept the unexplained cash plug.","Accept the model because a balancing balance sheet proves cash availability.","Reclassify the difference as revenue without a transaction.","Move the difference to a hidden equity row so cash stays positive."],"correct_index":0,"explanation":"A balance check is necessary but not sufficient. Cash must roll forward from actual forecast sources and uses. A plug can hide missing cash flows, double counting or broken retained earnings links."},{"id":"fm-s3-level3-v1-q5","session":"3","level":3,"topic":"Separating operating initiative from funding","question":"A company plans a capacity expansion that adds 30 million euros of revenue at 40% cash contribution. It costs 18 million of capital spending now and needs 6 million additional working capital. Management inserts 12 million of new debt directly into revenue to eliminate the first year cash deficit. Ignore tax and all other flows. What is the correct correction?","choices":["Raise revenue by 12 million because borrowed funds increase cash.","Keep operating contribution 12 million, show a 12 million cash need before financing, and show the 12 million debt separately.","Reduce capital spending by 12 million as an accounting adjustment without changing capacity.","Remove working capital because revenue already appears in the income statement."],"correct_index":1,"explanation":"Operating contribution 30×.4=12. Investment uses 18+6=24, so the funding gap is 12. A loan can cover it as financing, but cannot be revenue or operating performance."},{"id":"fm-s3-level3-v1-q6","session":"3","level":3,"topic":"Tax and equity incompleteness","question":"A forecast has EBIT 40 million, interest expense not yet entered, and a 25% tax rate on earnings before tax. It currently shows tax 10 and net income 30. The debt schedule later produces 8 million interest, and dividends are 50% of net income. What final tax, net income and dividend should be linked?","choices":["Tax 10 million, net income 22 million and dividend 11 million.","Tax 8 million, net income 32 million and dividend 16 million.","Tax 8 million, net income 24 million and dividend 12 million.","Tax 10 million, net income 30 million and dividend 15 million."],"correct_index":2,"explanation":"Interest lowers earnings before tax to 32. Tax is 8, net income 24 and payout 12. Tax, net income, equity and cash schedules must be updated when financing assumptions are completed."},{"id":"fm-s3-level3-v1-q7","session":"3","level":3,"topic":"Double counted depreciation","question":"A model forecasts revenue 100 million euros, cash operating costs 60 million, depreciation 10 million and taxes 25% of EBIT. Capital spending is 20 million and working capital is unchanged. A cash flow schedule begins with net income and subtracts both depreciation 10 and capital spending 20. What is the correct operating plus investing cash flow and the error amount?","choices":["Correct cash flow 2.5 million. The model understates it by 10 million.","Correct cash flow 22.5 million. No adjustment is needed.","Correct cash flow minus 7.5 million. Depreciation is a cash payment.","Correct cash flow 12.5 million. The model understates it by 20 million."],"correct_index":3,"explanation":"EBIT 30 and tax 7.5 give net income 22.5. Add back noncash depreciation 10 and subtract capex 20 for 12.5. The faulty schedule subtracts 10 instead of adding 10, a 20 million understatement."},{"id":"fm-s3-level3-v1-q8","session":"3","level":3,"topic":"Operational forecast and financing limit","question":"A company can fund at most 15 million euros of new cash investment. Incremental sales require working capital equal to 20% of sales, capital spending 10% of sales and generate cash operating contribution 15% of sales within the year. No other cash effects or opening funds exist. What maximum incremental annual sales can the plan fund under these assumptions?","choices":["100 million.","50 million.","75 million.","150 million."],"correct_index":0,"explanation":"Each euro of sales absorbs 0.20+.10-.15=.15 euros net cash. Available 15 million supports 15/.15=100 million incremental sales. The operational drivers, not an unexplained debt plug, determine the cash requirement."},{"id":"fm-s3-level3-v1-q9","session":"3","level":3,"topic":"Scenario consistency audit","question":"A downside forecast cuts unit sales 20% from a baseline 1 million units, retains priceEUR 10 and variable costEUR 6 per unit, and keeps fixed cash cost 2 million euros. The model nevertheless leaves variable costs at the baseline 6 million. What downside cash operating profit and model error follow?","choices":["Correct profit 0 million. The baseline cost must remain fixed.","Correct profit 1.2 million. The model understates it by 1.2 million.","Correct profit 2 million. The model understates it by 2 million.","Correct profit 1.6 million. The model overstates it by 0.4 million."],"correct_index":1,"explanation":"Downside revenue 0.8 million×10=8 million and variable cost 0.8 million×6=4.8 million. Profit 8-4.8-2=1.2 million. Leaving variable costs 6 produces 0, understating profit by 1.2. Different costs must move with their actual drivers."},{"id":"fm-s3-level3-v1-q10","session":"3","level":3,"topic":"Investment before operational ramp","question":"A company starts with cash 8 million and must retain 3 million. A new project requires 12 million capital spending in month 1. It produces no cash until month 4, then generates 20 million by year end. Existing operations have zero net cash flow and no other investment occurs. The annual forecast shows positive project net cash of 8 million. What minimum funding bridge must be included and why?","choices":["No funding because annual project cash is positive.","12 million, because opening cash can never fund capex.","7 million, because month 1 spending exceeds available cash above the minimum.","20 million, because all future revenue must be borrowed first."],"correct_index":2,"explanation":"Only 8-3=5 million opening cash is available to invest while retaining the buffer. Month 1 capex 12 needs 7 million bridge funding. Later project cash can repay it, but does not arrive in time for month 1."}],"4-5":[{"id":"fm-s4-5-level1-v1-q1","session":"4-5","level":1,"topic":"Quoted units and partial forward","question":"A euro area exporter will receive USD 6 million. It sells USD 4 million forward at EUR 0.90 per USD and converts the other USD 2 million at the maturity spot of EUR 0.85 per USD. There are no fees. What total euro receipt results?","choices":["EUR 5.10 million.","EUR 5.30 million.","EUR 5.40 million.","EUR 6.00 million."],"correct_index":1,"explanation":"The hedged amount produces 4 × 0.90 = 3.60 million euros. The residual produces 2 × 0.85 = 1.70 million euros. Total receipt is 5.30 million euros."},{"id":"fm-s4-5-level1-v1-q2","session":"4-5","level":1,"topic":"Option receipt after premium","question":"A euro area exporter receives USD 5 million in one year. It buys puts on all USD 5 million at a strike of EUR 0.92 per USD and pays a premium of EUR 0.02 per USD today. Ignore interest on the premium. Maturity spot is EUR 0.88 per USD. What is the net euro receipt, including premium?","choices":["EUR 4.60 million.","EUR 4.40 million.","EUR 4.50 million.","EUR 4.70 million."],"correct_index":2,"explanation":"Exercise the puts to receive 5 × .92 = 4.60 million euros. Subtract the .10 million premium to get 4.50 million. The premium is paid whether the option is exercised or not."},{"id":"fm-s4-5-level1-v1-q3","session":"4-5","level":1,"topic":"Importer call with upside","question":"A euro area importer owes USD 3 million in one year. It buys calls on USD at EUR 0.95 per USD, with a premium of EUR 0.015 per USD. Ignore interest on premium. Maturity spot is EUR 0.90 per USD. What is its net euro cost?","choices":["EUR 2.850 million.","EUR 2.895 million.","EUR 2.700 million.","EUR 2.745 million."],"correct_index":3,"explanation":"Do not exercise the call because dollars are cheaper at spot. Buy 3 million at .90 for 2.70 million euros, then include .045 million of premium. Total cost is 2.745 million."},{"id":"fm-s4-5-level1-v1-q4","session":"4-5","level":1,"topic":"Inverse quotation","question":"A euro area firm receives USD 8 million and must pay euro operating costs of EUR 5 million. The maturity exchange rate is USD 1.25 per EUR, quoted as dollars per euro. There is no hedge. What operating margin in euros results?","choices":["EUR 1.40 million.","EUR 5.00 million.","EUR 1.25 million.","EUR 3.00 million."],"correct_index":0,"explanation":"Convert dollars by dividing by 1.25, giving 6.40 million euros. Deduct euro costs of 5 million. Multiplying the dollar receipt by an indirect dollar per euro quote reverses the conversion."},{"id":"fm-s4-5-level1-v1-q5","session":"4-5","level":1,"topic":"Netting contractual exposures","question":"A company has a USD 9 million receivable and a USD 4 million payable, both certain and due on the same date. Its functional currency is EUR. It wants to fix the remaining euro cash flow using one forward, with no fees. Which position is appropriate?","choices":["Buy USD 5 million forward.","Sell USD 5 million forward.","Sell USD 13 million forward.","Buy USD 9 million forward."],"correct_index":1,"explanation":"The contractual net exposure is a USD 5 million receipt. Selling that net amount fixes its euro value without hedging the naturally offset USD 4 million twice."},{"id":"fm-s4-5-level1-v1-q6","session":"4-5","level":1,"topic":"Forward versus put break even","question":"A euro area exporter has a certain USD 4 million receivable. A forward sells dollars at EUR 0.91 per USD. A put has strike EUR 0.90 per USD and premium EUR 0.02 per USD. Ignore premium interest. At which maturity spot rate does the put strategy first match the forward receipt as the dollar strengthens?","choices":["EUR 0.88 per USD.","EUR 0.90 per USD.","EUR 0.93 per USD.","EUR 0.91 per USD."],"correct_index":2,"explanation":"Above the strike, the put is not exercised. Net receipt per dollar is spot minus .02. Equality with .91 requires spot .93. The option floor of .88 is below the forward receipt."},{"id":"fm-s4-5-level1-v1-q7","session":"4-5","level":1,"topic":"Overhedging quantity shortfall","question":"A euro area exporter expected USD 10 million and sold all of it forward at EUR 0.90 per USD. Actual customer receipts are only USD 7 million. Maturity spot is EUR 1.00 per USD. Ignore fees. What net euro receipt remains after fulfilling the entire forward?","choices":["EUR 6.30 million.","EUR 7.00 million.","EUR 9.00 million.","EUR 6.00 million."],"correct_index":3,"explanation":"The forward produces 10 × .90 = 9 million euros. Buy the missing USD 3 million at spot for 3 million euros. Net receipt is 6 million. The excess forward becomes a speculative short dollar position."},{"id":"fm-s4-5-level1-v1-q8","session":"4-5","level":1,"topic":"Premium currency conversion","question":"A euro area exporter buys put protection on USD 2 million. The premium is USD 0.03 per USD of notional, paid today when spot is USD 1.20 per EUR. Ignoring interest, what euro premium must be included in the hedge comparison?","choices":["EUR 50,000.","EUR 60,000.","EUR 72,000.","EUR 25,000."],"correct_index":0,"explanation":"Dollar premium is 2 million × .03 = USD 60,000. At 1.20 dollars per euro this costs 60,000/1.20 = EUR 50,000. A premium quoted in dollars cannot be subtracted directly from euro proceeds."},{"id":"fm-s4-5-level1-v1-q9","session":"4-5","level":1,"topic":"Exposure type with a hedge limit","question":"A euro reporting firm has a signed USD 2 million export receivable, a US subsidiary whose accounts must be consolidated, and possible export orders next year affected by competitiveness. A forward exactly matches the signed receivable. Which exposure is directly fixed by that forward?","choices":["Every future export margin regardless of quantities.","The euro cash settlement of the signed USD 2 million receivable.","All translation changes in the subsidiary accounts.","All three exposures, because each involves USD."],"correct_index":1,"explanation":"The matching contract fixes a known foreign currency receipt. It does not automatically fix uncertain future orders or the accounting translation of a subsidiary. Exposure type and hedge size must match."},{"id":"fm-s4-5-level1-v1-q10","session":"4-5","level":1,"topic":"Forward premium with direct units","question":"Spot is EUR 0.80 per USD and the six month forward is EUR 0.82 per USD. Using simple annualisation of the percentage forward deviation relative to spot, what is the annualised USD forward premium in this euro per dollar quote?","choices":["2.5%.","4.88%.","5.0%.","Minus 5.0%."],"correct_index":2,"explanation":"The six month deviation is (.82-.80)/.80 = 2.5%. Multiplying by 12/6 gives 5%. This statement uses the specified direct quote and annualisation convention."},{"id":"fm-s4-5-level2-v1-q1","session":"4-5","level":2,"topic":"Two dates and a hedge mismatch","question":"An exporter receives USD 4 million in six months and USD 6 million in one year. It sells the first amount forward at EUR 0.91 per USD and half of the second at EUR 0.90 per USD. Six month spot is EUR 0.88 and one year spot EUR 0.96. Ignore fees and interest. What total euro receipt is obtained over the year?","choices":["EUR 9.00 million.","EUR 9.34 million.","EUR 9.40 million.","EUR 9.22 million."],"correct_index":3,"explanation":"First receipt is fixed at 4 × .91 = 3.64 million euros. The second is 3 × .90 + 3 × .96 = 5.58 million euros. Total 9.22 million. The first spot rate is irrelevant to its fully hedged receipt."},{"id":"fm-s4-5-level2-v1-q2","session":"4-5","level":2,"topic":"Premium carried to maturity","question":"A certain USD 5 million receipt is hedged with puts at EUR 0.92 per USD. Premium is EUR 0.025 per USD paid today and financed at a simple 4% annual rate for one year. Maturity spot is EUR 0.90 per USD. What is the net euro receipt at maturity after repaying the financed premium?","choices":["EUR 4.470 million.","EUR 4.475 million.","EUR 4.600 million.","EUR 4.450 million."],"correct_index":0,"explanation":"Exercise at .92 for 4.60 million euros. Premium .125 million grows to .130 million. Net receipt is 4.470 million. Use a common date for comparing the premium with maturity cash flows."},{"id":"fm-s4-5-level2-v1-q3","session":"4-5","level":2,"topic":"Minimum hedge for a margin floor","question":"A euro area exporter will receive USD 12 million and pay EUR 9 million of costs. It can sell H million dollars forward at EUR 0.90 per USD, leaving the rest unhedged. Worst case spot is EUR 0.75 per USD. There are no fees and H lies from 0 to 12. What minimum H ensures euro margin of at least EUR 1.2 million in the worst case?","choices":["USD 6 million.","USD 8 million.","USD 9 million.","USD 10 million."],"correct_index":1,"explanation":"Worst case euro receipt is .90 H + .75(12-H) = 9 + .15 H. Margin after costs is .15 H. To reach 1.2 requires H at least 8 million dollars."},{"id":"fm-s4-5-level2-v1-q4","session":"4-5","level":2,"topic":"Overhedged operating margin","question":"An exporter budgeted USD 15 million of sales and EUR 10 million of costs. It sells USD 12 million forward at EUR 0.88 per USD. Actual sales are USD 9 million, costs stay EUR 10 million and maturity spot is EUR 0.95 per USD. Ignore fees. What realised euro operating margin results after fulfilling the hedge?","choices":["Minus EUR 2.08 million.","Minus EUR 1.45 million.","Minus EUR 2.29 million.","Plus EUR 0.56 million."],"correct_index":2,"explanation":"Forward receipt is 12 × .88 = 10.56 million euros. Buy the missing USD 3 million for 2.85 million euros. Net sales receipt is 7.71 million. Subtract costs of 10 to get minus 2.29 million."},{"id":"fm-s4-5-level2-v1-q5","session":"4-5","level":2,"topic":"Importer hedge break even","question":"A euro area importer owes USD 8 million. A forward buys dollars at EUR 0.94 per USD. A call has strike EUR 0.93 and premium EUR 0.015 per USD, paid today and financed for one year at 4% simple interest. At which maturity spot rate does the call strategy have the same total euro cost as the forward?","choices":["EUR 0.9300 per USD.","EUR 0.9556 per USD.","EUR 0.9250 per USD.","EUR 0.9244 per USD."],"correct_index":3,"explanation":"The financed premium per dollar is .015 × 1.04 = .0156. Below the strike, cost is spot + .0156. Set equal to .94 to get .9244, which is indeed below .93. If exercised, cost .9456 exceeds the forward."},{"id":"fm-s4-5-level2-v1-q6","session":"4-5","level":2,"topic":"Inverse forward quotes and option floor","question":"A euro exporter has a USD 6 million receipt. It can sell dollars forward at USD 1.20 per EUR or buy dollar puts with a strike of USD 1.25 per EUR. The puts explicitly let it exchange each dollar for 1/1.25 euros. Their euro premium is EUR 0.012 per USD, with interest ignored. What is the difference between the forward receipt and the put strategy minimum net receipt?","choices":["EUR 272,000.","EUR 200,000.","EUR 72,000.","EUR 128,000."],"correct_index":0,"explanation":"Forward receipt is 6/1.20 = 5 million euros. Put floor is 6/1.25 - 6 × .012 = 4.728 million euros. Difference .272 million. Invert both dollar per euro quotes before comparing."},{"id":"fm-s4-5-level2-v1-q7","session":"4-5","level":2,"topic":"Mixed forward and put hedge","question":"A USD 10 million receivable is hedged 50% by a forward at EUR 0.90 per USD and 50% by puts at EUR 0.92 per USD with premium EUR 0.02 per USD. Ignore interest. Maturity spot is EUR 0.96 per USD. What net receipt results?","choices":["EUR 9.00 million.","EUR 9.20 million.","EUR 9.10 million.","EUR 9.60 million."],"correct_index":1,"explanation":"Forward half produces 4.50 million euros. Dollar puts expire unused, so the other half produces 4.80 million at spot less .10 million premium. Total 9.20 million."},{"id":"fm-s4-5-level2-v1-q8","session":"4-5","level":2,"topic":"Opposite currency directions","question":"A euro area company must pay USD 8 million and will receive USD 3 million on the same date. It buys USD 6 million forward at EUR 0.92 per USD. Maturity spot is EUR 0.85 per USD. Any excess dollars are sold at spot. Ignore fees. What net euro cash outflow settles both underlying contracts and the hedge?","choices":["EUR 4.60 million.","EUR 4.25 million.","EUR 4.67 million.","EUR 5.52 million."],"correct_index":2,"explanation":"The net underlying payable is USD 5 million. The forward delivers 6 million for 5.52 million euros. After paying the net obligation, sell the extra 1 million at .85 for .85 million euros. Net outflow 4.67 million."},{"id":"fm-s4-5-level2-v1-q9","session":"4-5","level":2,"topic":"Expected receipts after option premium","question":"A certain USD 4 million receipt is exposed to two equally likely maturity spots, EUR 0.80 and EUR 1.00 per USD. A forward is available at EUR 0.90 per USD. A put has strike EUR 0.90 and premium EUR 0.03 per USD, with interest ignored. What are expected net euro receipts under the forward and the put?","choices":["Forward EUR 3.60 million and put EUR 3.60 million.","Forward EUR 3.60 million and put EUR 3.80 million.","Forward EUR 3.68 million and put EUR 3.60 million.","Forward EUR 3.60 million and put EUR 3.68 million."],"correct_index":3,"explanation":"Put receipts are 4 × (.90-.03) = 3.48 million in the weak dollar state and 4 × (1-.03) = 3.88 million in the strong state. Their mean is 3.68 million. Forward fixes 3.60 million in both states."},{"id":"fm-s4-5-level2-v1-q10","session":"4-5","level":2,"topic":"Residual sensitivity with overhedging","question":"An exporter has a certain USD 5 million receivable but sells USD 8 million forward. The forward price is fixed and there are no fees. If maturity spot rises from EUR 0.90 to EUR 1.00 per USD, how does combined euro receipt change?","choices":["It falls by EUR 0.30 million.","It rises by EUR 0.50 million.","It rises by EUR 0.80 million.","It does not change."],"correct_index":0,"explanation":"Combined receipt equals 8 × forward rate plus (5-8) × spot, in millions. Its sensitivity is minus USD 3 million. A .10 euro per dollar rise reduces the receipt by .30 million euros."},{"id":"fm-s4-5-level3-v1-q1","session":"4-5","level":3,"topic":"Quantity and spot joint states","question":"A euro area exporter has two equally likely outcomes in one year. In state A, dollar receipts are USD 10 million and spot is EUR 0.80 per USD. In state B, receipts are USD 6 million and spot EUR 1.00. It sells USD 8 million forward at EUR 0.90. It delivers all receipts and buys or sells any residual dollars at spot. Ignore fees and interest. What expected euro receipt results?","choices":["EUR 6.40 million.","EUR 7.00 million.","EUR 6.80 million.","EUR 7.20 million."],"correct_index":1,"explanation":"State A receipt is 8 × .90 + 2 × .80 = 8.80 million euros. State B receipt is 8 × .90 - 2 × 1 = 5.20 million euros. Expected receipt is 7 million, not the product of mean quantity and mean spot."},{"id":"fm-s4-5-level3-v1-q2","session":"4-5","level":3,"topic":"Two sided budget constraints","question":"An exporter has a certain USD 10 million receipt and may sell H million dollars forward at EUR 0.90 per USD, with H between 0 and 10. Spot may be EUR 0.75 or EUR 1.05. There are no fees. It wants a receipt of at least EUR 8.7 million in the weak dollar state and at least EUR 9.3 million in the strong state. Which H meets both requirements?","choices":["Any amount from USD 6 million to USD 8 million.","Only USD 10 million.","Only USD 8 million.","No amount can meet both."],"correct_index":2,"explanation":"Weak state receipt is 7.5 + .15 H, requiring H≥8. Strong state receipt is 10.5-.15 H, requiring H≤8. Their intersection is exactly H=8."},{"id":"fm-s4-5-level3-v1-q3","session":"4-5","level":3,"topic":"Forward versus quantity flexible options","question":"An exporter expects USD 10 million but may receive only USD 6 million. It can either sell USD 10 million forward at EUR 0.90 per USD, or buy puts on USD 10 million at EUR 0.90 per USD for EUR 0.02 per USD. Puts are cash settled with payoff notional × max(strike minus spot,0), so they need no dollar delivery. Ignore interest. In the low quantity state, spot is EUR 1.00 per USD. What net euro receipt does each hedge produce?","choices":["Forward EUR 5.40 million and puts EUR 5.20 million.","Forward EUR 9.00 million and puts EUR 8.80 million.","Forward EUR 6.00 million and puts EUR 6.20 million.","Forward EUR 5.00 million and puts EUR 5.80 million."],"correct_index":3,"explanation":"Forward produces 9 million but requires buying missing USD 4 million at spot for 4 million, leaving 5 million euros. Puts expire unused at spot above strike. Convert the 6 million dollars for 6 million euros and subtract .2 million premium, leaving 5.8 million."},{"id":"fm-s4-5-level3-v1-q4","session":"4-5","level":3,"topic":"Probability of quantity shortfall","question":"An exporter has USD 12 million of receipts with probability 60% and USD 4 million with probability 40%. Maturity spot is EUR 0.80 per USD in the first state and EUR 1.10 in the second. It sells USD 8 million forward at EUR 0.90. Ignore fees. What is the expected euro benefit or loss from adding the forward compared with leaving the actual receipts unhedged?","choices":["An expected loss of EUR 160,000.","An expected gain of EUR 160,000.","An expected gain of EUR 320,000.","An expected loss of EUR 640,000."],"correct_index":0,"explanation":"Forward incremental cash flow is 8(.90-spot), independent of realised operating quantity. Gain .8 million in the first state, loss 1.6 million in the second. Expected increment .6×.8-.4×1.6=-.16 million euros. Quantity matters for delivery liquidity, not the derivative payoff formula."},{"id":"fm-s4-5-level3-v1-q5","session":"4-5","level":3,"topic":"Maximum affordable premium","question":"A euro exporter expects a certain USD 8 million receipt. A forward fixes EUR 0.90 per USD. Puts with strike EUR 0.90 have unknown euro premium p per USD, paid today and financed at 5% simple interest for one year. Maturity spot is EUR 0.80 with probability 40% and EUR 1.00 with probability 60%. What maximum p gives expected option net receipt at least equal to the forward?","choices":["EUR 0.06000 per USD.","About EUR 0.05714 per USD.","EUR 0.04000 per USD.","EUR 0.10000 per USD."],"correct_index":1,"explanation":"Expected gross option conversion rate is .4×.90+.6×1=.96. To match forward .90, financed premium must not exceed .06. Thus p≤.06/1.05=.0571429. This compares expected receipts, not identical downside protection."},{"id":"fm-s4-5-level3-v1-q6","session":"4-5","level":3,"topic":"Margin floor with a premium budget","question":"A euro exporter has USD 10 million of certain receipts and euro costs of EUR 8 million. It can buy cash settled puts on H million dollars with strike EUR 0.95 per USD at premium EUR 0.02 per USD. The premium is paid now and its interest is ignored. Worst case spot is EUR 0.80. Total premium budget is EUR 160,000, and H cannot exceed 10. What is the largest guaranteed worst case margin attainable within the budget?","choices":["EUR 1.20 million.","EUR 0.96 million.","EUR 1.04 million.","EUR 1.30 million."],"correct_index":2,"explanation":"The budget permits H≤.16/.02=8 million. Worst case total receipt net of premium is 8+.15 H-.02 H=8+.13 H. Margin after 8 million costs is .13 H, maximised atH 8, giving 1.04 million euros."},{"id":"fm-s4-5-level3-v1-q7","session":"4-5","level":3,"topic":"Forward settlement liquidity","question":"A company has sold USD 12 million forward at EUR 0.88 per USD against forecast exports. The customer cancels before settlement and no dollar receipt remains. The forward is physically settled, spot is EUR 1.02 per USD, and no net settlement or borrowing is available. The company has EUR 3 million of cash before settlement. What are the gross purchase cost and the hypothetical final net cash after both legs, showing the settlement funding problem?","choices":["Gross purchase EUR 1.68 million and final cash EUR 1.32 million.","Gross purchase EUR 10.56 million and final cash EUR 4.68 million.","Gross purchase EUR 12.24 million and final cash minus EUR 9.24 million.","Gross purchase EUR 12.24 million and final cash EUR 1.32 million."],"correct_index":3,"explanation":"Buying USD 12 million costs 12.24 million euros. Forward delivery then receives 10.56 million, so final cash is 3-12.24+10.56=1.32 million. The company nevertheless lacks the gross 12.24 million required before receiving the forward proceeds. The net loss and intraday funding need are different."},{"id":"fm-s4-5-level3-v1-q8","session":"4-5","level":3,"topic":"Inverse quote break even with financed premium","question":"A euro exporter has a certain USD 5 million receipt. It can sell forward at USD 1.20 per EUR or buy puts allowing each USD to be sold for EUR 0.82, with a premium of USD 0.024 per USD of notional. Premium is paid today at USD 1.25 per EUR and financed for one year at 4% simple interest in euros. In the region where the puts expire unused, at what maturity USD per EUR spot quote do the two strategies have equal net euro receipts, rounded to four decimals?","choices":["1.1719 USD per EUR.","1.2000 USD per EUR.","1.2283 USD per EUR.","1.1904 USD per EUR."],"correct_index":0,"explanation":"Premium in euros per dollar is .024/1.25=.0192, rising to .019968 at maturity. Equality requires euro spot per dollar =1/1.20+.019968=.85330133. The inverse is 1.171918. This exceeds the .82 strike in direct units, so nonexercise is consistent."},{"id":"fm-s4-5-level3-v1-q9","session":"4-5","level":3,"topic":"Separate net exposures and maturities","question":"A euro company will receive USD 9 million and pay USD 3 million at month 6, then receive USD 2 million and pay USD 7 million at month 12. It uses forwards to eliminate the net exposure at each date. Month 6 forward is EUR 0.90 per USD and month 12 forward EUR 0.94. Ignore fees and interest. What total net euro cash flow do the two correctly matched hedges fix?","choices":["A net receipt of EUR 0.90 million.","A net receipt of EUR 0.70 million.","A net payment of EUR 0.70 million.","A net receipt of EUR 0.94 million."],"correct_index":1,"explanation":"At month 6 sell the net USD 6 million for EUR 5.4 million. At month 12 buy net USD 5 million for EUR 4.7 million. Total net euro receipt is .7 million. Hedging only the overall USD 1 million net receipt would leave timing exposures."},{"id":"fm-s4-5-level3-v1-q10","session":"4-5","level":3,"topic":"Maximum forward under a quantity stress","question":"A euro exporter can receive either USD 10 million with spot EUR 0.80 per USD or USD 6 million with spot EUR 1.10. It sells H million dollars forward at EUR 0.90, with 0≤H≤10 and no fees. It requires euro receipts of at least EUR 7.4 million in the first state and EUR 6.0 million in the second. What is the largest feasible H?","choices":["USD 6 million.","USD 8 million.","USD 3 million.","No amount is feasible."],"correct_index":2,"explanation":"First state receipt is 8+.10 H and already exceeds 7.4 for every H≥0. Second is 6.6-.20 H, which must be at least 6, requiring H≤3. The quantity shortfall state limits the forward, even though a larger hedge would help in the weak dollar state."}]},"cr":{"1":[{"id":"cr-s1-level1-v1-q1","session":"1","level":1,"topic":"Information asymmetry","question":"Company managers can see daily sales orders and internal cash forecasts. Outside shareholders receive only published financial reports. How can financial reporting help those shareholders?","choices":["By giving shareholders priority over lenders","By removing all incentives for biased estimates","By transferring daily operating decisions to shareholders","By reducing the information gap between managers and shareholders"],"correct_index":3,"explanation":"Managers know more about daily operations than outside owners. Published reporting shares relevant financial information and helps owners assess decisions and stewardship. It reduces information asymmetry without eliminating all private information or conflicts of interest."},{"id":"cr-s1-level1-v1-q2","session":"1","level":1,"topic":"Standards versus enforcement","question":"Two countries adopt identical accounting standards. In country A regulators investigate material non-compliance and impose penalties. In country B enforcement is rare. Why may reporting credibility still differ?","choices":["The same written rules can be enforced differently.","The IASB must have issued the rules on different dates.","Identical standards necessarily contain different recognition rules.","International effective dates depend on local penalties."],"correct_index":0,"explanation":"Adopting written requirements and enforcing them are different steps. Stronger enforcement may improve compliance and credibility even when the accounting standards themselves are identical."},{"id":"cr-s1-level1-v1-q3","session":"1","level":1,"topic":"Several sources of regulation","question":"Company law requires annual accounts, an accounting standard specifies inventory measurement, and stock-exchange rules require quarterly reports. Which sources govern inventory measurement and quarterly publication in this example?","choices":["Company law and accounting standards","Accounting standards and stock-exchange rules","Stock-exchange rules and company law","Accounting standards and company law"],"correct_index":1,"explanation":"A regulatory framework can contain several layers. The accounting standard supplies the inventory rule, while the exchange imposes the separate quarterly publication requirement. Complying with one layer does not cancel the others."},{"id":"cr-s1-level1-v1-q4","session":"1","level":1,"topic":"Principles and judgement","question":"An agreement labelled as a service contract gives a company funds that it must repay with interest. To decide whether it creates a financial liability, should the company rely on the label or on another feature?","choices":["The title used for the contract and its legal documentation.","The classification used by the other party in its own accounts.","The contractual rights and obligations to pay cash.","The effect of each classification on the company's debt ratio."],"correct_index":2,"explanation":"Accounting follows the economic substance of the arrangement. A contractual obligation to repay cash is evidence of a financial liability, even if the contract is called a service agreement. Neither the preferred debt ratio nor the counterparty's accounting determines the company's classification."},{"id":"cr-s1-level1-v1-q5","session":"1","level":1,"topic":"International comparison costs","question":"An investor pays analysts to reconcile similar transactions reported under different national accounting rules. Both markets then adopt a common reporting framework. Which cost may fall most directly?","choices":["The issuer's audit cost","The issuer's currency hedging cost","The issuer's initial conversion cost","The investor's cost of comparing the reports"],"correct_index":3,"explanation":"A common accounting language can reduce the work needed to interpret and compare reports across markets. It does not automatically reduce every issuer cost or make the underlying businesses identical."},{"id":"cr-s1-level1-v1-q6","session":"1","level":1,"topic":"Standard setting roles","question":"A reporting issue requires an international accounting rule to be changed. A separate case concerns a company that failed to follow an existing rule. Which division of responsibilities is correct?","choices":["Standard setters amend requirements, while enforcement bodies investigate compliance.","Auditors amend requirements, while standard setters impose issuer penalties.","Enforcement bodies amend international requirements, while standard setters audit companies.","Auditors amend requirements through audit opinions, while regulators choose accounting estimates."],"correct_index":0,"explanation":"Standard-setting develops and amends the rules. Enforcement applies those rules to reporting entities and investigates non-compliance. Audit provides assurance but does not turn an auditor into the international standard setter."},{"id":"cr-s1-level1-v1-q7","session":"1","level":1,"topic":"Comparability not identity","question":"Two contracts have materially different economic rights. Applying the same accounting treatment hides those differences and produces similar reported margins. What would better support comparability?","choices":["Keep the treatment and omit the contractual differences.","Use appropriate treatments that make the economic differences visible.","Keep identical margins and change only statement headings.","Choose policies that equalise each company's industry ratios."],"correct_index":1,"explanation":"Comparability helps users identify similarities and differences. It is not the same as uniformity. Different economic arrangements should not be made to look identical merely by using the same accounting treatment."},{"id":"cr-s1-level1-v1-q8","session":"1","level":1,"topic":"Benefit and compliance cost","question":"Adopting common standards saves investors €3 million a year in comparison costs but adds €2 million a year in preparer audit and systems costs. There are no other effects. What is the net annual benefit?","choices":["€3 million","A loss of €2 million","€1 million","€5 million"],"correct_index":2,"explanation":"Net benefit = €3m savings − €2m additional costs = €1m a year. The calculation includes both sides even though investors receive the savings and preparers bear the additional costs."},{"id":"cr-s1-level1-v1-q9","session":"1","level":1,"topic":"Agency incentives","question":"A manager receives a bonus based on reported profit and prepares an estimate affecting that profit. Which control most directly checks whether the estimate reflects evidence rather than the bonus target?","choices":["Keep the estimate whenever it reaches the bonus threshold.","Reuse last year's estimate regardless of new evidence.","Disclose the bonus without checking the estimate.","Independently review the inputs, method and explanation against current evidence."],"correct_index":3,"explanation":"A profit-based bonus can create an incentive to bias estimates. Independent scrutiny of the supporting evidence helps assess whether the estimate is neutral and reasonable. The incentive is a risk, not proof that every judgement is dishonest."},{"id":"cr-s1-level1-v1-q10","session":"1","level":1,"topic":"Due process","question":"Before issuing a new accounting standard, a standard setter publishes a draft, invites comments and considers revisions. What is the purpose of this consultation?","choices":["Allow affected parties to test and comment on the proposal.","Give respondents a binding majority vote over the final rule.","Make the draft mandatory before consultation ends.","Transfer final recognition decisions to national enforcement bodies."],"correct_index":0,"explanation":"Consultation helps the standard setter understand practical effects and improve proposals. Considering comments does not give respondents a veto, and a proposal is not automatically a binding standard."},{"id":"cr-s1-level2-v1-q1","session":"1","level":2,"topic":"Mixed research outcomes","question":"After a reporting reform, a study finds a statistically supported increase in market liquidity. Its estimate of the effect on the cost of equity is inconclusive. Which summary is justified?","choices":["Liquidity rises and the cost of equity is shown to fall.","Liquidity rises, but the direction of the cost-of-equity effect is not established.","Liquidity is unchanged and the cost of equity falls.","Liquidity rises and the study proves no cost-of-equity effect."],"correct_index":1,"explanation":"Report the two findings separately. An inconclusive estimate establishes neither a reduction nor an absence of effect. Evidence about liquidity cannot fill that gap in a different outcome."},{"id":"cr-s1-level2-v1-q2","session":"1","level":2,"topic":"Confounded adoption effect","question":"A country adopts IFRS and strengthens enforcement in the same year. Reporting quality improves. The study has no comparison group or independent variation separating the reforms. What can it conclude about their individual effects?","choices":["The improvement is caused entirely by IFRS.","The improvement is caused entirely by enforcement.","Either reform or both may contribute, but their separate effects are not identified.","Each reform causes half the improvement."],"correct_index":2,"explanation":"Two factors changed together. The observed improvement does not isolate either factor's contribution. Separate evidence or a suitable comparison design is needed before assigning causal shares."},{"id":"cr-s1-level2-v1-q3","session":"1","level":2,"topic":"Rules based structuring","question":"An accounting rule changes classification when a ratio crosses 10%. Managers alter a contract from 10.1% to 9.9%, without materially changing its risks or cash flows. What problem does this illustrate?","choices":["Crossing the threshold necessarily changes economic substance.","The new classification proves lower financing risk.","A numerical threshold eliminates the need for judgement.","A bright-line rule can encourage structuring around form rather than substance."],"correct_index":3,"explanation":"The contract crosses a formal boundary while its economics remain nearly unchanged. Detailed thresholds can make rules clearer but can also encourage transactions designed to obtain a preferred accounting result."},{"id":"cr-s1-level2-v1-q4","session":"1","level":2,"topic":"Credible adoption","question":"Two firms announce that they use the same reporting framework. Firm A makes the required accounting changes and obtains credible independent review. Firm B changes only the report cover and retains non-compliant accounting. Must investors regard the two reports as equally credible?","choices":["No, implementation and review can lead to different credibility.","Yes, the shared framework label is enough.","No, firm B is more credible because its conversion cost is lower.","Yes, review changes fees but cannot affect credibility."],"correct_index":0,"explanation":"A reporting label does not establish compliance. The underlying policies, estimates and review determine whether the framework has been credibly implemented. The same announced adoption can therefore have different information effects."},{"id":"cr-s1-level2-v1-q5","session":"1","level":2,"topic":"Jurisdictional gate","question":"In a hypothetical jurisdiction, a new international standard becomes mandatory only after local endorsement. It has been issued internationally but not endorsed, and local early adoption is prohibited. Is international issuance alone enough to make it mandatory locally?","choices":["Yes, its international effective date overrides endorsement.","No, local endorsement is still required.","Yes, if the company explains the missing endorsement in a note.","Yes, once the text is translated."],"correct_index":1,"explanation":"The question expressly makes local endorsement a condition of application. International issuance and local legal applicability are separate steps. Existing binding requirements continue until properly replaced."},{"id":"cr-s1-level2-v1-q6","session":"1","level":2,"topic":"Accounting distance","question":"Firm A's existing policies are close to a new reporting framework. Firm B's policies differ substantially in measurement and disclosure. Other circumstances are identical. Which conversion-planning assumption is reasonable?","choices":["Both firms necessarily face identical conversion work.","Firm A necessarily needs more conversion work.","Firm B may need more conversion work because more policies and systems must change.","Policy differences measure recurring benefits but have no bearing on conversion work."],"correct_index":2,"explanation":"Moving from substantially different policies can require more reconciliation, training and systems work. This supports a planning expectation, not an exact cost estimate or a prediction of the direction of profit changes."},{"id":"cr-s1-level2-v1-q7","session":"1","level":2,"topic":"Different debt channels","question":"A study finds a statistically supported fall in borrowing costs for public bond issuers after reporting reform. Its estimate for private bank loans is inconclusive. Which conclusion stays within the evidence?","choices":["Borrowing costs fall equally for bonds and bank loans.","The bond effect is inconclusive while bank-loan costs fall.","Bond costs fall and bank-loan costs rise.","Bond costs fall, while a fall for bank loans is not established."],"correct_index":3,"explanation":"Public bond investors and private lenders may rely on different information and monitoring. A supported result for one channel should not be generalised to the other. Inconclusive does not mean unchanged or increased."},{"id":"cr-s1-level2-v1-q8","session":"1","level":2,"topic":"Net benefits over time","question":"A reporting conversion costs €4 million immediately. Over the following four years it adds annual reporting costs of €1 million and annual financing and information benefits of €2.5 million. Ignore discounting, tax and effects after year 4. What is the total net benefit?","choices":["€2 million","€6 million","€10 million","A loss of €2 million"],"correct_index":0,"explanation":"Annual net benefit = €2.5m − €1m = €1.5m. Four years produce €6m. Deduct the one-off €4m conversion cost to obtain €2m. Do not count the one-off cost every year or omit it."},{"id":"cr-s1-level2-v1-q9","session":"1","level":2,"topic":"Enforcement and foreign investors","question":"Two countries adopt the same standards. Foreign fund ownership rises only in country A, which has stronger enforcement. The study does not control for every other difference between the countries. What is a defensible interpretation?","choices":["The contrast isolates the effect of written standards alone.","The pattern is consistent with enforcement mattering, but does not prove a universal causal effect.","The written standards must differ because ownership differs.","The contrast proves enforcement is the sole cause."],"correct_index":1,"explanation":"The pattern supports an enforcement mechanism but does not eliminate other explanations. Common rules and credible implementation are distinct. A cross-country association is not automatically a clean causal estimate."},{"id":"cr-s1-level2-v1-q10","session":"1","level":2,"topic":"Interpreting additional audit fees","question":"Following a reporting reform, a company's annual audit fee rises by 30%. Analysts say comparisons are easier, but that benefit has not been valued. What is known about the reform's net economic value?","choices":["It is negative because only the cost has been measured.","It is positive because easier comparison always exceeds audit costs.","It remains unknown until the benefit and other relevant effects are assessed.","The audit fee is not a cost because it purchases assurance."],"correct_index":2,"explanation":"The higher audit fee is a measured cost, while the information benefit remains unvalued. Knowing one component does not determine the net result. The benefit may be real without yet being quantified."},{"id":"cr-s1-level2-v1-q11","session":"1","level":2,"topic":"IFRS1 date of transition","question":"A company's first IFRS financial statements are for the year ended 31 March 2027. They include full IFRS comparative information for the years ended 31 March 2026 and 31 March 2025. What is the date of transition to IFRS?","choices":["1 April 2026","1 April 2024","31 March 2025","1 April 2025"],"correct_index":1,"explanation":"The transition date is the beginning of the earliest period for which full IFRS comparative information is presented. The earliest comparative year ends on 31 March 2025, so it begins on 1 April 2024. Prepare the opening IFRS statement of financial position at that date."},{"id":"cr-s1-level3-v1-q1","session":"1","level":3,"topic":"Difference in changes","question":"Before a reporting reform, a reform group and a comparison group each have a quality score of 60. Afterwards, the reform group scores 75 and the comparison group 68. Assume the comparison captures the common trend and no other differential changes occur. What improvement is associated with the reform after removing that trend?","choices":["15 points","8 points","23 points","7 points"],"correct_index":3,"explanation":"The reform group improves 75 − 60 = 15 points. The comparison group improves 68 − 60 = 8 points. Difference in changes = 15 − 8 = 7 points. The interpretation depends on the stated common-trend assumption."},{"id":"cr-s1-level3-v1-q2","session":"1","level":3,"topic":"Common language with divergent incentives","question":"Two subsidiaries use the same standards for similar transactions. One faces covenant pressure, weak review and optimistic estimates. The other has independent review and well-supported neutral estimates. An analyst says identical standards guarantee equal reliability. What is the strongest response?","choices":["Shared rules do not prevent incentives and weak review from producing biased application.","The standards force every estimate to one value, so reliability is equal.","Review matters, but covenant pressure cannot affect estimates.","One subsidiary's independent review validates both subsidiaries."],"correct_index":0,"explanation":"Rules permit judgement in applying estimates to facts. Incentives and review affect how that judgement is used. A common framework helps comparison but does not eliminate bias or the need to examine evidence."},{"id":"cr-s1-level3-v1-q3","session":"1","level":3,"topic":"Selection and adoption","question":"Companies voluntarily adopting a framework already have stronger governance, more foreign investors and faster liquidity growth before adoption. A researcher compares only post-adoption liquidity levels and calls the entire gap an adoption effect. Which step best addresses this weakness?","choices":["Match companies only by adoption month.","Compare changes and pre-adoption trends while accounting for selection differences.","Remove foreign-owned firms to make the rest randomly assigned.","Add more adopters without changing the design."],"correct_index":1,"explanation":"Voluntary adopters differ before adoption, so the later gap can reflect selection and existing trends. Examining changes and pre-trends is a step toward separating those effects. More observations alone do not remove the bias."},{"id":"cr-s1-level3-v1-q4","session":"1","level":3,"topic":"Implementation economics and distribution","question":"A reform saves investors €8 million a year, adds €5 million annual preparer costs and €2 million annual enforcement costs, and costs €4 million once at the start. Over three years, ignoring discounting and other effects, what is the total net result?","choices":["A gain of €3 million","A loss of €4 million","A loss of €1 million","A gain of €5 million"],"correct_index":2,"explanation":"Annual net benefit = €8m − €5m − €2m = €1m. Three years yield €3m, less €4m initial costs = a €1m loss. Investors, preparers and enforcement bodies also bear different parts of the overall result."},{"id":"cr-s1-level3-v1-q5","session":"1","level":3,"topic":"Interpreting an exposure draft","question":"An exposure draft proposes a new measurement method. Existing binding standards still require another method, and early adoption is not permitted. May management use the draft as though it were already mandatory?","choices":["Yes, if it reconciles to the issued requirement in a note.","Yes, because consultation reveals the setter's preference.","Yes, by averaging the draft and issued methods.","No, a consultation proposal does not replace the current requirement."],"correct_index":3,"explanation":"An exposure draft invites views before final issuance. It is not itself a binding replacement for an applicable Standard. Preparing for a possible change is different from applying an unissued requirement."},{"id":"cr-s1-level3-v1-q6","session":"1","level":3,"topic":"No universal adoption gain","question":"A study finds comparability gains after reform only where enforcement is strong and previous policies differ substantially from the new framework. Which new case lies outside both conditions supporting that finding?","choices":["Weak enforcement and old policies already close to the new framework","Strong enforcement and old policies far from the new framework","Strong enforcement and old policies already close to the new framework","Weak enforcement and old policies far from the new framework"],"correct_index":0,"explanation":"The supported result has two conditions: strong enforcement and substantial policy change. Weak enforcement together with already similar policies satisfies neither. Applying the same estimated gain there requires evidence beyond the study's stated conditions."},{"id":"cr-s1-level3-v1-q7","session":"1","level":3,"topic":"Reporting change versus economic change","question":"After restatement to a new accounting framework, a company reports higher book equity and its market value rises. Its operating cash flows, contractual payments and business risks are unchanged. Does the market-value rise show that it generated more operating cash?","choices":["Yes, the book-equity increase is an operating receipt.","No, reported measures and investor assessments can change without new operating cash.","Yes, market value establishes higher cash sales.","Yes, it proves increased financing receipts."],"correct_index":1,"explanation":"Restatement changes reported accounting amounts. Investors may also change their assessment of the same business. Neither creates an operating cash receipt, and the question explicitly states that operating cash flows did not change."},{"id":"cr-s1-level3-v1-q8","session":"1","level":3,"topic":"Rules and principles together","question":"An accounting standard contains a general principle and detailed guidance. A company copies an example but ignores contractual features materially different from that example. What review approach is appropriate?","choices":["Apply the example and exclude the differing features.","Use only the principle and ignore binding detailed requirements.","Read the requirements in context and account for the actual contractual features.","Keep the example's treatment and mention the differences only in notes."],"correct_index":2,"explanation":"Principles and detailed guidance work together. An example must be applied in light of the actual transaction, including material differences. Neither mechanical copying nor dismissing binding guidance is a substitute for that analysis."},{"id":"cr-s1-level3-v1-q9","session":"1","level":3,"topic":"Conflicting outcome measures","question":"A reform study finds lower analyst forecast errors, €4 million higher annual audit fees and an inconclusive effect on the cost of capital. It does not value the forecast improvement in money. Which conclusion is justified?","choices":["Net benefit is negative and financing costs are unchanged.","Net benefit is positive and financing direction is unknown.","Net benefit is unknown and financing costs are proven unchanged.","Net benefit and the direction of the financing effect remain undetermined."],"correct_index":3,"explanation":"A measured cost and an unvalued information benefit do not establish net economic value. An inconclusive financing estimate establishes neither a decrease nor no effect. Keep the separate findings and their limits distinct."},{"id":"cr-s1-level3-v1-q10","session":"1","level":3,"topic":"Reconciling multiple regulatory layers","question":"In a hypothetical market, company law requires annual accounts, the exchange requires quarterly reports and an endorsed accounting standard governs measurement. A company measures every item correctly but publishes only annual accounts. What follows?","choices":["It still fails the separate quarterly reporting obligation.","Correct measurement automatically satisfies publication requirements.","Annual accounts suffice if quarterly figures would use the same policies.","The company must change measurement rather than publish additional reports."],"correct_index":0,"explanation":"Measurement compliance and publication duties are separate regulatory layers. Following the accounting standard does not cure failure to meet an applicable exchange reporting requirement."},{"id":"cr-s1-level3-v1-q11","session":"1","level":3,"topic":"IFRS1 reconciliations","question":"A company first reports under IFRS for the year ended 31 December 2026 and presents one year of full comparatives. Its last annual statements under previous GAAP were for 2025. Which previous-GAAP-to-IFRS reconciliations are required?","choices":["Equity at 1 January and 31 December 2025, and total comprehensive income for 2025","Equity at 31 December 2026 only","Total comprehensive income for 2026 only","Equity at 1 January 2026 only"],"correct_index":0,"explanation":"The transition date is 1 January 2025, the start of the earliest comparative year. Reconcile equity at that date and at the end of the last previous-GAAP annual period, 31 December 2025. Also reconcile total comprehensive income for that previous-GAAP period."}],"2":[{"id":"cr-s2-level1-v1-q1","session":"2","level":1,"topic":"Authority of the framework","question":"The IFRS standard governing a transaction mandates A and permits no alternative. Management argues that B fits the Conceptual Framework better. Which approach is required for IFRS compliance?","choices":["Use B and disclose a reconciliation to A in the notes.","Use B for material amounts and A for immaterial amounts.","Use A because the applicable Standard takes priority.","Use either A or B if the accounting policy is disclosed."],"correct_index":2,"explanation":"The Conceptual Framework is not an Accounting Standard and does not override a specific Standard. On these facts, treatment A is required. Explaining or reconciling treatment B in the notes would not make B compliant."},{"id":"cr-s2-level1-v1-q2","session":"2","level":1,"topic":"Controlled resource versus ownership","question":"A company does not own a machine, but has an enforceable use right and controls the economic benefits from that right. Can the use right meet the Conceptual Framework asset definition?","choices":["Only the machine itself, rather than the right to use it, can be an asset.","The right can be an asset only if all ownership risks pass to the company.","The right can be an asset only if the company can sell the machine.","The right can be an asset even though the company does not own the machine."],"correct_index":3,"explanation":"An asset is a present economic resource controlled by the entity as a result of past events. The resource can be a right to use an item rather than ownership of the item itself. The relevant Standard then determines recognition and measurement."},{"id":"cr-s2-level1-v1-q3","session":"2","level":1,"topic":"Owner capital versus income","question":"A company issues ordinary shares for cash and incurs no issue costs. What is the immediate effect on assets and income?","choices":["Assets increase and no income is recognised.","Assets and income both increase by the proceeds.","Assets are unchanged and income increases by the share premium.","Assets increase and income increases by the share premium."],"correct_index":0,"explanation":"Cash increases assets. The matching increase is an owner contribution within equity, not income. Both nominal capital and share premium are excluded from performance income."},{"id":"cr-s2-level1-v1-q4","session":"2","level":1,"topic":"Present obligation versus plan","question":"At its reporting date a company intends to buy equipment next year. It has signed no contract and made no binding commitment. Does its purchase plan create a liability?","choices":["Yes, an accrued payable at the quoted price.","No, intention alone creates no present obligation.","Yes, a provision for the expected price.","Yes, a contingent liability equal to the approved budget."],"correct_index":1,"explanation":"A liability requires a present obligation arising from past events. The company can still avoid the planned purchase. Approving a budget or expecting a future cash payment does not itself create a liability."},{"id":"cr-s2-level1-v1-q5","session":"2","level":1,"topic":"Prudence and bias","question":"Available evidence supports a warranty liability of €10 million. Management records €18 million solely to create a reserve that can improve reported profits in later years. Which aspect of faithful representation is most directly breached?","choices":["Comparability","Timeliness","Neutrality","Direct verifiability"],"correct_index":2,"explanation":"The extra €8m is deliberate bias. Prudence means caution when making uncertain judgements, not knowingly overstating liabilities or creating hidden reserves. A neutral estimate uses the available evidence."},{"id":"cr-s2-level1-v1-q6","session":"2","level":1,"topic":"Useful estimation","question":"A company estimates a warranty liability using a suitable method and all reasonably available evidence. It clearly explains the uncertainty. What does faithful representation require?","choices":["The estimate must be revised each period until it equals the final cash settlement.","The liability must be measured at a directly observable market price for the obligation.","The liability must be recorded at the highest settlement that the evidence cannot exclude.","The estimate must be chosen and applied without error, not predict the exact outcome."],"correct_index":3,"explanation":"An estimate can faithfully represent an uncertain amount when its description is complete and neutral and its method and inputs are applied without error. A later settlement that differs from the estimate does not by itself show the original accounting was wrong. Neither perfect prediction, a market quote nor the worst-case outcome is the faithful-representation test."},{"id":"cr-s2-level1-v1-q7","session":"2","level":1,"topic":"Equity and liabilities","question":"At the reporting date a company has assets of €120 million and liabilities of €75 million. What is its equity?","choices":["€45 million","€75 million","€120 million","€195 million"],"correct_index":0,"explanation":"Equity is the residual interest after liabilities are deducted from assets: €120m − €75m = €45m. It is not the sum of assets and liabilities."},{"id":"cr-s2-level1-v1-q8","session":"2","level":1,"topic":"Accrual basis","question":"A company completes a service in December and obtains an unconditional right to €20 million. All revenue recognition conditions are met. The customer pays in January. What is recognised in December?","choices":["Revenue in January only, with a December note.","A receivable and revenue of €20 million.","A contract liability of €20 million.","A receivable but no revenue until collection."],"correct_index":1,"explanation":"Under accrual accounting, recognise the service revenue when earned and the receivable when the right arises. January collection exchanges the receivable for cash. It does not create the original revenue."},{"id":"cr-s2-level1-v1-q9","session":"2","level":1,"topic":"Predictive and confirmatory value","question":"A report explains that an expansion failed to meet its previously announced sales target. It also provides demand information useful for forecasting future sales. Which aspects of relevance are present?","choices":["Confirmatory value only","Predictive value only","Both confirmatory and predictive value","Neither unless an exact forecast is provided"],"correct_index":2,"explanation":"The target comparison helps users confirm or revise an earlier assessment. The demand information is an input to future predictions. Information can have both kinds of value without itself being a forecast."},{"id":"cr-s2-level1-v1-q10","session":"2","level":1,"topic":"Materiality in context","question":"An accounting error is small compared with total assets, but correcting it changes whether an important loan covenant is met. Why may the error be material?","choices":["It appears in audited rather than unaudited accounts.","It is small compared with inventory.","It was discovered after year-end.","Its nature and effect could influence a lender's decision."],"correct_index":3,"explanation":"Materiality depends on size, nature or both in the entity's circumstances. An error affecting compliance with a significant covenant may influence decisions even if it is below a general numerical threshold."},{"id":"cr-s2-level2-v1-q1","session":"2","level":2,"topic":"Income from changing net assets","question":"Assets increase from €100 million to €132 million and liabilities from €40 million to €47 million. During the year owners contribute €10 million and receive €4 million dividends. There is no other comprehensive income or other equity movement. What profit is implied?","choices":["€25 million","€11 million","€31 million","€19 million"],"correct_index":3,"explanation":"Opening equity is €60m and closing equity €85m, an increase of €25m. Equity change = profit + €10m contributions − €4m dividends. Profit = €25m − €10m + €4m = €19m."},{"id":"cr-s2-level2-v1-q2","session":"2","level":2,"topic":"Measurement perspectives","question":"An asset was bought for €70 million. Its current orderly sale price in the market is €90 million. The present value of the entity's expected cash flows from use and disposal is €100 million. Ignore transaction costs and historical-cost adjustments. Which amounts are historical cost, fair value and value in use respectively?","choices":["€70m, €90m and €100m","€70m, €100m and €90m","€90m, €70m and €100m","€100m, €90m and €70m"],"correct_index":0,"explanation":"Historical cost starts with the acquisition amount, €70m. Fair value reflects the market-participant exit price, €90m. Value in use reflects the present value of the entity's own use and disposal cash flows, €100m."},{"id":"cr-s2-level2-v1-q3","session":"2","level":2,"topic":"Enhancing cannot rescue fundamental failure","question":"Accounts arrive promptly, are clearly written and apply consistent policies. They nevertheless intentionally omit a material debt. Do the good presentation qualities compensate for that omission?","choices":["Timeliness compensates for the omission because users receive information sooner.","The omission prevents faithful representation despite the other useful qualities.","The omission is acceptable if users can estimate the liability from other figures.","Consistent policies compensate for the omission by allowing comparisons over time."],"correct_index":1,"explanation":"Faithful representation requires a complete, neutral depiction free from material error. Leaving out a material liability makes the depiction incomplete. Timeliness, understandability and comparability enhance useful information but cannot compensate for this failure of a fundamental quality."},{"id":"cr-s2-level2-v1-q4","session":"2","level":2,"topic":"Definition versus recognition","question":"A controlled right meets the Conceptual Framework's definition of an asset, but its measurement is highly uncertain. Which additional question concerns recognition rather than the asset definition?","choices":["Did the right arise from a past transaction?","Does the entity control the right?","Would recognising it provide relevant information and faithful representation?","Can the right potentially produce economic benefits?"],"correct_index":2,"explanation":"Definition asks whether a controlled economic resource exists because of past events. Recognition asks whether including it in the statements provides useful information. Measurement uncertainty affects that separate recognition assessment."},{"id":"cr-s2-level2-v1-q5","session":"2","level":2,"topic":"Owner distribution versus expense","question":"A company pays €6 million dividends on ordinary equity shares and €9 million wages for employee services consumed this year. Which treatment is correct?","choices":["Both amounts are expenses.","Wages are an expense, but dividends do not change equity.","Neither amount affects profit.","Wages are an expense and dividends are an owner distribution."],"correct_index":3,"explanation":"The €9m wages reduce profit as the services are consumed. The €6m dividends reduce equity directly because they are distributions to owners acting as owners. A cash payment is not necessarily an expense."},{"id":"cr-s2-level2-v1-q6","session":"2","level":2,"topic":"Comparability and an improved policy","question":"Two companies initially use the same policy for similar transactions. One enters a transaction with genuinely different economic rights and uses a different permitted policy to reflect those rights. An analyst insists that both companies must report identical-looking results. What distinction is the analyst missing?","choices":["Comparability shows economic similarities and differences, while uniformity makes items look the same.","Comparability concerns only periods, while uniformity concerns only entities.","Comparability requires identical measurement, while uniformity requires identical headings.","Comparability means neutrality, while uniformity means timeliness."],"correct_index":0,"explanation":"Comparable information helps users identify what is alike and what differs. Treating genuinely different transactions identically can hide useful differences. The question assumes the different policy is permitted, so it is not a licence to ignore Standards."},{"id":"cr-s2-level2-v1-q7","session":"2","level":2,"topic":"Liability measurement perspectives","question":"A liability originally arose for €40 million. An orderly transfer to a market participant would now require €46 million. The present value of cash flows the entity expects to use to settle it is €43 million. Ignore cost adjustments. What do the €46 million and €43 million represent?","choices":["Fair value and fulfilment value, respectively €43m and €46m","Fair value and fulfilment value, respectively €46m and €43m","Historical cost and value in use","Fulfilment value and historical cost"],"correct_index":1,"explanation":"Fair value is the current market-participant transfer measure, €46m. Fulfilment value is the entity-specific present value of resources needed to settle the liability, €43m. The €40m original proceeds relate to historical cost."},{"id":"cr-s2-level2-v1-q8","session":"2","level":2,"topic":"Verifiability without identical forecasts","question":"Independent knowledgeable observers check an estimate's documented inputs and method. They agree that the estimate is reasonable, although several future settlement amounts remain possible. What does this show about verifiability?","choices":["It is impossible until the final settlement is known.","The actual future cash payment is directly observable today.","It can exist without every observer predicting the same future outcome.","It applies to methods but never to inputs."],"correct_index":2,"explanation":"Verification can be indirect: observers check inputs and recalculate the model. They need not all agree on one certain future outcome. Reasonable estimation uncertainty does not itself prevent verification."},{"id":"cr-s2-level2-v1-q9","session":"2","level":2,"topic":"Going concern and disclosure","question":"Management concludes that the going-concern basis remains appropriate, but a material uncertainty about refinancing may cast significant doubt on the company's ability to continue operating. What disclosure is needed?","choices":["None until refinancing negotiations fail.","None if management's preferred forecast is positive.","Internal board disclosure only.","Disclosure of the material going-concern uncertainty in the financial statements."],"correct_index":3,"explanation":"Using the going-concern basis and disclosing a material uncertainty are separate decisions. The basis may remain appropriate while users still need a clear explanation of the uncertainty."},{"id":"cr-s2-level2-v1-q10","session":"2","level":2,"topic":"Cost constraint and users","question":"A proposed disclosure costs €1 million to prepare and is expected to save users €3 million in decision costs. There are no other effects. Management rejects it solely because preparation costs are positive. What is wrong with that reasoning under the Framework's cost constraint?","choices":["Benefits should justify costs, not require costs to be zero.","Only benefits to the preparer can count.","User benefits count only if they directly reduce the company's interest payments.","Benefits to several users cannot be compared with one company's costs."],"correct_index":0,"explanation":"The stated benefits exceed the stated costs by €2m. Reporting need not be costless. The cost constraint considers whether benefits justify costs, while recognising that different parties may bear them."},{"id":"cr-s2-level3-v1-q1","session":"2","level":3,"topic":"Integrated equity reconciliation","question":"Opening assets are €180 million and liabilities €110 million. Closing assets are €225 million and liabilities €128 million. Owners contribute €20 million and receive €8 million dividends. There is no other comprehensive income or other equity movement. Management calls the €27 million increase in net assets profit. What is the correct profit?","choices":["€15 million, after removing the €12 million net owner contribution","€27 million, equal to the full net-asset increase","€39 million, after adding the net owner contribution","€7 million, after removing the share issue only"],"correct_index":0,"explanation":"Equity rises from €70m to €97m, an increase of €27m. Net owner contributions are €20m − €8m = €12m. Profit is €27m − €12m = €15m. Owner transactions change equity but are not performance."},{"id":"cr-s2-level3-v1-q2","session":"2","level":3,"topic":"Neutrality and symmetric uncertainty","question":"Evidence supports an asset estimate of €20 million and a liability estimate of €12 million. To make profits look cautious, management records the asset at €14 million and liability at €18 million. No Standard requires those adjustments. Compared with neutral estimates, what is the equity effect and conceptual problem?","choices":["Equity falls €6m because only the asset adjustment matters.","Equity falls €12m and the deliberate bias conflicts with neutrality.","Equity falls €12m and the bias is required by prudence.","Equity is unchanged because the adjustments offset."],"correct_index":1,"explanation":"The asset is understated €6m and the liability overstated €6m. Both reduce equity, so the total reduction is €12m. Prudence supports cautious neutral judgement, not deliberate systematic understatement of net assets."},{"id":"cr-s2-level3-v1-q3","session":"2","level":3,"topic":"Controlled right versus certain cash","question":"A company acquires and controls exclusive enforceable rights to a development project. Success is unlikely and estimated values vary widely. For this Conceptual Framework question, no specific Standard is being applied. Does the low probability of success prevent an asset from existing?","choices":["Yes, economic benefits must be more likely than not for any asset to exist.","No, and the full purchase price must therefore be recognised without further assessment.","No, potential benefits can satisfy the definition, while recognition requires a separate usefulness assessment.","Yes, although recognition can replace a failed asset definition."],"correct_index":2,"explanation":"An economic resource is a right with the potential to produce economic benefits. Low probability does not alone remove that potential. Recognition then considers relevance and faithful representation, including uncertainty. A specific applicable Standard could impose its own recognition requirements."},{"id":"cr-s2-level3-v1-q4","session":"2","level":3,"topic":"Estimate revisions and process quality","question":"At year-end a company estimates a warranty liability of €10 million using a sound method and all reasonably available information. A genuinely unforeseeable event in the following year raises expected settlement to €16 million. What does the increase establish about the original estimate?","choices":["It proves a €6m prior-period error.","It proves a failure to apply prudence.","It proves incomplete reporting of an eventual outcome.","It does not by itself show that the original estimate was wrong when made."],"correct_index":3,"explanation":"Assess the original estimate using evidence available at its date, not hindsight. New information may change an estimate prospectively without making the earlier reasonable estimate an error. Faithful representation is not perfect prediction."},{"id":"cr-s2-level3-v1-q5","session":"2","level":3,"topic":"Net cash is not performance","question":"Opening equity is €50 million. The company earns €12 million profit, issues shares for €30 million and pays €8 million dividends. It also borrows €20 million and buys equipment for €25 million cash, recognised at that amount. There are no other effects. What is closing equity?","choices":["€84 million","€79 million","€104 million","€54 million"],"correct_index":0,"explanation":"Equity = €50m + €12m profit + €30m share issue − €8m dividends = €84m. Borrowing increases cash and liabilities equally. The equipment purchase exchanges one asset for another and is not an immediate €25m expense."},{"id":"cr-s2-level3-v1-q6","session":"2","level":3,"topic":"Competing measurement questions","question":"An asset cost €60 million. Its current market-participant sale price is €75 million. Expected cash flows from the entity's use and eventual disposal are €50 million in one year and €40 million in two years. Use 10% annually and ignore transaction costs. What are fair value and value in use, to two decimals?","choices":["Fair value €78.51m and value in use €75.00m","Fair value €75.00m and value in use €78.51m","Fair value €75.00m and value in use €90.00m","Fair value €60.00m and value in use €78.51m"],"correct_index":1,"explanation":"Fair value is the stated market sale price, €75m. Value in use = €50m/1.10 + €40m/1.10² = €78.5124m. Original cost and undiscounted cash flows are not substitutes for these current-value measures."},{"id":"cr-s2-level3-v1-q7","session":"2","level":3,"topic":"Information overload and material omission","question":"A company includes a material obligation somewhere within 500 pages of mostly immaterial tables. The information is so poorly organised that users cannot readily understand the obligation. Does the volume of disclosure establish understandability?","choices":["Yes, because the amount appears somewhere.","Yes, provided the report has more detail than peers.","No, excessive irrelevant detail can obscure material information.","Yes, because users could read every table."],"correct_index":2,"explanation":"More pages do not necessarily mean better information. Material information can be obscured by immaterial detail. Presentation must help users understand the obligation rather than merely place its amount somewhere in the report."},{"id":"cr-s2-level3-v1-q8","session":"2","level":3,"topic":"Concepts and binding rules together","question":"A specific IFRS Accounting Standard prohibits recognition of an item. Management believes the item meets the Conceptual Framework's asset definition and wants to recognise it with an explanatory note. What is the correct conclusion?","choices":["Recognition is allowed if the note explains the conceptual argument.","The Standard's prohibition means the Framework's definition is invalid.","Recognition is allowed outside individual lines but within statement totals.","The Standard's prohibition applies and an explanatory note cannot override it."],"correct_index":3,"explanation":"The Framework helps develop and interpret accounting concepts but does not override a specific Standard. Meeting a broad definition does not automatically satisfy every Standard's recognition requirements. Disclosure cannot authorise prohibited recognition."},{"id":"cr-s2-level3-v1-q9","session":"2","level":3,"topic":"Performance reconciliation with liability release","question":"Opening assets are €100 million and liabilities €60 million. The company earns €8 million service revenue on credit. An unrelated creditor legally waives a €5 million liability. Owners receive a €3 million dividend. All recognition requirements are met and there are no other changes. What are closing equity and total income?","choices":["Equity €50m and income €13m","Equity €45m and income €8m","Equity €50m and income €10m","Equity €53m and income €13m"],"correct_index":0,"explanation":"Opening equity is €40m. Service revenue adds €8m and the liability release adds €5m income. The dividend is a €3m owner distribution, not an expense. Closing equity = €40m + €13m − €3m = €50m."},{"id":"cr-s2-level3-v1-q10","session":"2","level":3,"topic":"Two choices under uncertainty","question":"A present obligation can be reported using a well-supported estimate with clear uncertainty disclosure. Alternatively, an exact figure is available but deliberately excludes a material component of the obligation. No specific Standard or cost issue changes the choice. Which better meets the fundamental qualitative characteristics?","choices":["The exact but incomplete amount","The supported estimate with uncertainty explained","The exact amount in the statements and the full estimate only in a note","The exact amount until the excluded component becomes certain"],"correct_index":1,"explanation":"A supported estimate can be relevant and faithfully represented despite uncertainty. An exact figure that knowingly omits a material component is incomplete. Apparent precision does not compensate for missing substance."}],"3":[{"id":"cr-s3-level1-v1-q1","session":"3","level":1,"topic":"Operating cycle classification","question":"A manufacturer applies IAS 1 and has a normal operating cycle of 18 months. It expects to sell and realise €8 million inventory in 15 months, within that cycle. How is the inventory classified?","choices":["Non-current because realisation takes more than 12 months","Non-current because only receivables qualify for the operating-cycle test","Current because it is realised within the normal operating cycle","Current only if a customer has already signed an order"],"correct_index":2,"explanation":"IAS 1's normal-operating-cycle criterion is an alternative to its 12-month criterion. Inventory realised within the normal cycle is current even if the cycle lasts longer than a year."},{"id":"cr-s3-level1-v1-q2","session":"3","level":1,"topic":"Deferral right","question":"At year-end a €20 million loan is due in nine months. The borrower hopes to refinance it, but has no binding agreement or right to defer repayment at the reporting date. How is the loan classified under IAS 1?","choices":["Non-current because refinancing is expected","Non-current because the company is a going concern","Current only for the part not covered by planned refinancing","Current because no deferral right exists at year-end"],"correct_index":3,"explanation":"The loan is due within 12 months and the company has no reporting-date right to defer settlement. A future plan or expectation is not an existing contractual right, so the full €20m is current."},{"id":"cr-s3-level1-v1-q3","session":"3","level":1,"topic":"No general offsetting","question":"A company has a €10 million trade receivable and a €7 million trade payable with different counterparties. No IFRS requirement permits offsetting. What is the correct presentation?","choices":["A €10m asset and a separate €7m liability","A €3m net asset with gross amounts in a note","A €3m net asset because both items are operating","A €10m asset with the €7m payable deducted within assets"],"correct_index":0,"explanation":"IAS 1 generally prohibits offsetting unless another IFRS permits or requires it. Present both balances separately. A note cannot replace required gross recognition and presentation."},{"id":"cr-s3-level1-v1-q4","session":"3","level":1,"topic":"Estimate versus error","question":"At the start of the year a machine has a carrying amount of €60 million, a remaining useful life of six years and no residual value. New information changes the remaining life to four years. The previous estimate was reasonable. What annual straight-line depreciation and treatment now apply?","choices":["€10m, applied prospectively","€15m, applied prospectively","€15m, applied retrospectively","€20m, applied prospectively"],"correct_index":1,"explanation":"A useful-life revision based on new information is a change in estimate. Divide the current €60m carrying amount by the revised four remaining years to obtain €15m a year. Do not restate earlier reasonable estimates."},{"id":"cr-s3-level1-v1-q5","session":"3","level":1,"topic":"Policy change justification","question":"No new Standard requires a policy change. Which reason can justify a voluntary change from one permitted accounting policy to another under IAS 8?","choices":["It increases reported profit.","It reduces volatility in executives' bonus measures.","It provides reliable and more relevant information.","It makes past forecasts appear more accurate."],"correct_index":2,"explanation":"A voluntary policy change must result in reliable and more relevant information about transactions and other events. A preferred profit, bonus or forecast outcome is not the required justification."},{"id":"cr-s3-level1-v1-q6","session":"3","level":1,"topic":"Prior error evidence","question":"Last year's financial statements omitted a material unpaid invoice for services already consumed. The invoice and reliable records were available before those statements were authorised. The omission is found this year. What is it?","choices":["A current estimate revision","A voluntary accounting policy change","An ordinary current-year expense with no comparative effect","A prior-period error requiring retrospective correction when practicable"],"correct_index":3,"explanation":"The company failed to use reliable information available when the earlier statements were prepared. IAS 8 treats that as a prior-period error, not new estimation information. Material errors are corrected retrospectively unless impracticable."},{"id":"cr-s3-level1-v1-q7","session":"3","level":1,"topic":"Equity reconciliation","question":"Opening equity is €80 million. The company reports €12 million profit and €3 million other comprehensive income, issues shares for €10 million and pays €5 million dividends. There are no other movements. What is closing equity?","choices":["€100 million","€97 million","€110 million","€90 million"],"correct_index":0,"explanation":"Closing equity = €80m + €12m + €3m + €10m − €5m = €100m. Profit and other comprehensive income are performance items. The share issue and dividend are owner transactions, also included in the equity reconciliation."},{"id":"cr-s3-level1-v1-q8","session":"3","level":1,"topic":"Comparative period length","question":"After changing its year-end, a company presents a nine-month current period and a twelve-month comparative period under IAS 1. What must it explain?","choices":["The reason for the change and that the amounts are fully comparable.","The reason for the change and that the amounts are not entirely comparable.","Only annualised figures as though twelve months had actually elapsed.","Only the new year-end date, with no comparative figures."],"correct_index":1,"explanation":"Disclose the reason for using a period other than a year and that the reported amounts are not entirely comparable. Consistent accounting policies do not remove a difference in period length."},{"id":"cr-s3-level1-v1-q9","session":"3","level":1,"topic":"Expense analysis","question":"One company presents materials, employee costs and depreciation separately. Another presents cost of sales, distribution costs and administration costs. Which expense-analysis methods do they use?","choices":["First by function, second by nature","Both by nature","First by nature, second by function","Both by function"],"correct_index":2,"explanation":"Nature identifies the type of expense consumed, such as wages or depreciation. Function groups expenses by their role, such as production, distribution or administration."},{"id":"cr-s3-level1-v1-q10","session":"3","level":1,"topic":"Comprehensive income","question":"A company reports €18 million profit and a €4 million other comprehensive loss. It also receives a €6 million cash contribution from shareholders. What is total comprehensive income?","choices":["€20 million","€24 million","€18 million","€14 million"],"correct_index":3,"explanation":"Total comprehensive income = profit €18m − other comprehensive loss €4m = €14m. The €6m shareholder contribution increases equity but is not income or comprehensive income."},{"id":"cr-s3-level2-v1-q1","session":"3","level":2,"topic":"Two estimates linked","question":"At the start of the year a machine has a carrying amount of €48 million, six years of remaining life and zero residual value. New evidence changes the remaining life to five years and residual value to €3 million. Straight-line depreciation is used and there is no prior error. What are current-year depreciation and closing carrying amount?","choices":["€9.6m and €38.4m","€8m and €40m","€7.5m and €40.5m","€9m and €39m"],"correct_index":3,"explanation":"The revised depreciable amount is €48m − €3m = €45m. Spread it over five remaining years: €9m annual depreciation. Closing carrying amount is €48m − €9m = €39m. Apply both revised estimates prospectively."},{"id":"cr-s3-level2-v1-q2","session":"3","level":2,"topic":"Retrospective opening correction","question":"In year 3 a company discovers that it omitted a material €8 million expense and unpaid liability in year 1. Year 2 is the earliest comparative period presented. The liability is still unpaid and retrospective correction is practicable. Ignore tax. Which adjustment is made at the start of year 2?","choices":["Reduce retained earnings €8m and increase the liability €8m.","Reduce year 3 profit €8m and leave comparative opening balances unchanged.","Increase retained earnings €8m and reduce the liability €8m.","Reduce cash €8m and retained earnings €8m."],"correct_index":0,"explanation":"The error occurred before the earliest comparative period. Correct that period's opening liability and equity balances: record the €8m payable and reduce retained earnings €8m. Cash does not change because the expense remains unpaid."},{"id":"cr-s3-level2-v1-q3","session":"3","level":2,"topic":"Policy transition instructions","question":"A new IFRS Accounting Standard requires a policy change and specifies modified retrospective application without restating comparatives. Must a company instead use IAS 8's general retrospective method?","choices":["Yes, IAS 8 always overrides specific transition provisions.","No, follow the new Standard's transition provisions.","No, classify the change as a new estimate.","Yes, restate comparatives and also record the cumulative adjustment again."],"correct_index":1,"explanation":"Specific transition provisions govern initial application of a new Standard. IAS 8's general retrospective method does not override them. A policy change does not become an estimate change merely because comparatives are not restated."},{"id":"cr-s3-level2-v1-q4","session":"3","level":2,"topic":"Current assets total","question":"Under IAS 1 a company has unrestricted cash of €5 million, trading securities of €4 million, inventory of €7 million realised within its normal 18-month operating cycle, and equipment of €12 million used over five years. What is its total current assets?","choices":["€9 million","€21 million","€16 million","€28 million"],"correct_index":2,"explanation":"Cash, trading securities and normal-cycle inventory are current: €5m + €4m + €7m = €16m. The equipment is non-current. A normal operating cycle longer than 12 months does not make the inventory non-current."},{"id":"cr-s3-level2-v1-q5","session":"3","level":2,"topic":"Current liability total","question":"A company has €6 million trade payables settled within its normal 15-month operating cycle, a €4 million loan due in eight months with no deferral right, and a €10 million loan due in three years with an existing right to defer until then. No other current-liability criterion applies to the last loan. What is total current liabilities under IAS 1?","choices":["€4 million","€6 million","€20 million","€10 million"],"correct_index":3,"explanation":"Operating-cycle payables are current even when settlement exceeds 12 months. Add the €4m short-term loan to the €6m payables: €10m current liabilities. The €10m three-year loan is non-current on the stated rights."},{"id":"cr-s3-level2-v1-q6","session":"3","level":2,"topic":"Error versus new evidence","question":"A €2 million receivables-loss estimate was reasonable using all available year-end information. A wholly new customer event next year raises it to €5 million. Separately, the company finds that it previously misadded a material payable by €3 million despite having correct records. How are the two changes classified?","choices":["The customer event changes an estimate, and the arithmetic mistake is a prior-period error.","Both are prior-period errors.","Both are changes in estimate.","The customer event is an error, and the arithmetic mistake changes an estimate."],"correct_index":0,"explanation":"New evidence changes a previously reasonable estimate prospectively. An arithmetic mistake using available records is an error, corrected retrospectively when material and practicable. The fact both are discovered now does not make them the same type of change."},{"id":"cr-s3-level2-v1-q7","session":"3","level":2,"topic":"IFRS18 operating and investing categories","question":"Under IFRS 18, a manufacturer correctly classifies revenue of €200 million and expenses of €150 million as operating, income of €8 million as investing, and expense of €12 million as financing. Income tax expense is €10 million and there are no discontinued operations. What are operating profit, profit before financing and income taxes, and profit for the year?","choices":["€58m, €50m and €36m","€50m, €58m and €36m","€50m, €46m and €36m","€50m, €58m and €46m"],"correct_index":1,"explanation":"Operating profit = €200m − €150m = €50m. Add investing income €8m for €58m before financing and taxes. Deduct €12m financing and €10m tax for profit of €36m. The classifications are specified so only the subtotal calculation is tested."},{"id":"cr-s3-level2-v1-q8","session":"3","level":2,"topic":"Materiality and aggregation","question":"Two errors in the same expense class are each below a company's numerical materiality threshold. Their combined effect exceeds it. How should they be assessed?","choices":["Assess each separately and stop if each is below the threshold.","Offset them against unrelated income errors first.","Consider their combined effect as well as each error's nature and size.","Assess only the larger error to avoid double counting."],"correct_index":2,"explanation":"Errors can be material in aggregate even when individually small. Also assess their nature and the entity's circumstances rather than treating a numerical threshold as an automatic exemption."},{"id":"cr-s3-level2-v1-q9","session":"3","level":2,"topic":"Disclosure cannot cure recognition","question":"An applicable Standard requires a company to recognise a material liability. The company instead describes it only in a note and leaves it out of the statement of financial position. Is that sufficient?","choices":["Yes, if users can reconstruct the liability.","Yes, until cash is paid.","Yes, if the note is independently verified.","No, disclosure does not replace required recognition."],"correct_index":3,"explanation":"A note does not correct the omission of an amount that must be recognised. The company must apply the relevant recognition and measurement requirements as well as provide the necessary disclosures."},{"id":"cr-s3-level2-v1-q10","session":"3","level":2,"topic":"Profit error and tax effect","question":"A company omitted a material €10 million prior-year expense and unpaid payable. Correcting the error also reduces a previously recognised tax payable by €2.5 million. Retrospective correction is practicable and there are no other effects. By how much do corrected prior-year profit and closing retained earnings fall?","choices":["€7.5 million","€10 million","€12.5 million","€2.5 million"],"correct_index":0,"explanation":"The expense reduces pre-tax profit €10m, while the tax reduction increases after-tax profit €2.5m relative to that amount. Net reduction = €10m − €2.5m = €7.5m. The payable corrections have the same net €7.5m effect on equity."},{"id":"cr-s3-level3-v1-q1","session":"3","level":3,"topic":"Combined error and estimate","question":"At the start of year 3 a company finds a material €6 million unpaid expense omitted in year 1. Year 2 is its earliest comparative, and correction is practicable. An unrelated machine has a €30 million carrying amount at the start of year 3. New information reduces its remaining life from five to three years, with no residual value. Ignore tax. What are the opening year 2 retained-earnings correction and year 3 depreciation?","choices":["Reduce retained earnings €6m and charge depreciation €10m.","Reduce year 3 profit €6m and charge depreciation €6m.","Reduce retained earnings €6m and restate prior depreciation to €10m.","Leave retained earnings unchanged and charge depreciation €16m."],"correct_index":0,"explanation":"Correct the old error in opening year 2 balances by reducing retained earnings €6m and recording the liability. Separately, apply the new useful-life estimate prospectively: €30m ÷ 3 = €10m depreciation. Do not combine the prior error with the machine's current expense."},{"id":"cr-s3-level3-v1-q2","session":"3","level":3,"topic":"Multi period policy restatement","question":"A justified voluntary policy change is applied retrospectively. Restatement is practicable and there are no specific transition provisions. Compared with the old policy, opening year 2 retained earnings increase by €4 million, year 2 profit increases by €3 million and year 3 profit increases by €2 million. There are no tax effects or other equity changes. By how much do opening and closing year 3 retained earnings increase?","choices":["€4m and €6m","€7m and €9m","€3m and €5m","€7m and €2m"],"correct_index":1,"explanation":"Opening year 3 includes the €4m opening year 2 adjustment plus €3m additional year 2 profit, giving €7m. Add the €2m year 3 profit effect for a €9m closing increase. Earlier cumulative effects are not treated as year 3 income."},{"id":"cr-s3-level3-v1-q3","session":"3","level":3,"topic":"Current classification with financing hopes","question":"A covenant breach makes a €12 million loan payable on demand on 31 December 2026. At that reporting date the borrower has no right to delay payment for twelve months. The lender waives the breach on 20 January 2027 before accounts are authorised. Is the reporting date loan current or non-current?","choices":["Non-current because the lender grants the waiver before the statements are authorised.","Non-current because management expects that the lender will not demand repayment.","Current because the right to defer repayment did not exist at the reporting date.","Current only for the repayments management expects to make in the next 12 months."],"correct_index":2,"explanation":"The entire €12 million is current. Classification depends on rights existing at the reporting date. The January waiver does not create a deferral right retrospectively at 31 December. Management's expected repayments do not replace the contractual position."},{"id":"cr-s3-level3-v1-q4","session":"3","level":3,"topic":"Restatement with an owner flow","question":"Reported opening year 2 equity was €100 million. A material earlier error requires an €8 million retrospective reduction. Restated year 2 profit is €15 million and other comprehensive loss is €3 million. During year 2 owners contribute €10 million and receive €6 million dividends. Ignore tax and other movements. What is restated closing year 2 equity?","choices":["€116 million","€98 million","€114 million","€108 million"],"correct_index":3,"explanation":"Corrected opening equity = €100m − €8m = €92m. Closing equity = €92m + €15m − €3m + €10m − €6m = €108m. The old error has already been included in opening equity and must not be deducted again from year 2 profit."},{"id":"cr-s3-level3-v1-q5","session":"3","level":3,"topic":"Comparative error with current discovery","question":"Year 2 profit of €40 million omitted a material €5 million unpaid utility expense. The error is found in year 3, for which profit from current-year transactions is €30 million. Year 2 is the comparative and restatement is practicable. Ignore tax. What profits are presented for years 2 and 3?","choices":["Year 2 €35m and year 3 €30m","Year 2 €40m and year 3 €25m","Year 2 €35m and year 3 €25m","Year 2 €40m and year 3 €30m with no other correction"],"correct_index":0,"explanation":"Restate the comparative year 2 profit to €40m − €5m = €35m. Year 3 current profit remains €30m. Record the unpaid liability and corresponding opening retained-earnings correction, rather than charging the old expense again in year 3."},{"id":"cr-s3-level3-v1-q6","session":"3","level":3,"topic":"A policy label hides an error","question":"A company has long claimed to apply a Standard requiring recognition of a material obligation. Despite having reliable records, it omitted the obligation in previous periods. It now proposes to call first recognition a voluntary policy change and charge the entire amount to current profit. Correction is practicable. What should it do?","choices":["Treat first recognition as a policy change because the balance is new.","Correct the prior-period error retrospectively.","Treat discovery as a new estimate and apply it prospectively.","Leave comparatives unchanged and charge current profit with a note."],"correct_index":1,"explanation":"The error arose from failing to apply an existing requirement using available evidence. Renaming it does not make it a voluntary policy choice or new estimate. Correct the affected comparative and opening balances under IAS 8."},{"id":"cr-s3-level3-v1-q7","session":"3","level":3,"topic":"Presentation and performance reconciliation","question":"A manufacturer applying IFRS 18 has correctly classified revenue of €300 million, operating expenses of €220 million, investing income of €10 million, financing expense of €18 million and income tax expense of €16 million. A discontinued operation has a €4 million after-tax loss. Other comprehensive income is €7 million. What are profit and total comprehensive income?","choices":["Profit €56m and total comprehensive income €63m","Profit €59m and total comprehensive income €59m","Profit €52m and total comprehensive income €59m","Profit €52m and total comprehensive income €52m"],"correct_index":2,"explanation":"Continuing profit = €300m − €220m + €10m − €18m − €16m = €56m. Deduct discontinued loss €4m to get profit €52m. Add other comprehensive income €7m for total comprehensive income €59m."},{"id":"cr-s3-level3-v1-q8","session":"3","level":3,"topic":"Change in residual value and prior validity","question":"At the start of year 4 an asset has cost of €100 million and accumulated depreciation of €40 million. Earlier estimates were reasonable. New information changes its remaining life from six to four years and residual value from nil to €12 million. Straight-line depreciation applies. What are year 4 depreciation, closing carrying amount and treatment of prior statements?","choices":["€15m, €45m and no restatement","€12m, €48m and retrospective restatement","€22m, €38m and no restatement","€12m, €48m and no restatement"],"correct_index":3,"explanation":"Current carrying amount = €100m − €40m = €60m. Revised depreciation = (€60m − €12m) ÷ 4 = €12m. Closing amount = €60m − €12m = €48m. The new estimate applies prospectively, with no restatement of reasonable prior estimates."},{"id":"cr-s3-level3-v1-q9","session":"3","level":3,"topic":"Three distinct equity movements","question":"Opening equity of €150 million is reduced by a €9 million retrospective error correction. During the current year the company reports €24 million profit and a €5 million other comprehensive loss, pays €8 million dividends, issues shares for €12 million and repurchases its own shares for €10 million. What is closing equity?","choices":["€154 million","€163 million","€145 million","€174 million"],"correct_index":0,"explanation":"Corrected opening equity is €141m. Closing equity = €141m + €24m − €5m − €8m + €12m − €10m = €154m. The share issue, dividends and share repurchase are direct owner transactions rather than profit or loss."},{"id":"cr-s3-level3-v1-q10","session":"3","level":3,"topic":"Choosing a policy without a direct standard","question":"No IFRS Accounting Standard directly covers a transaction. A requirement for a similar transaction offers a relevant analogy. Industry practice conflicts with that requirement and with the Conceptual Framework. Which policy-selection approach follows IAS 8?","choices":["Use industry practice first to match competitors.","Consider similar IFRS requirements and Framework concepts before lower-priority industry practice.","Treat the IFRS analogy and industry practice as equally authoritative.","Use national tax treatment before considering IFRS analogies."],"correct_index":1,"explanation":"IAS 8 prioritises requirements for similar and related issues and then Framework concepts. Other standard-setter material or accepted industry practice may be considered only if it does not conflict with those higher-priority sources. Matching competitors does not reverse the hierarchy."}],"4":[{"id":"cr-s4-level1-v1-q1","session":"4","level":1,"topic":"Profit is not cash","question":"A company makes €90 million of credit sales and collects €65 million from customers during the year. It had no trade receivables at the start of the year. There are no returns, write-offs or other transactions. What does the remaining €25 million represent?","choices":["Revenue received in advance","A loan from customers","Revenue recognised but still owed by customers","Cash advanced to customers"],"correct_index":2,"explanation":"Closing trade receivables are €90m − €65m = €25m. Revenue is recognised when earned, while collection settles the receivable later. The unpaid amount is not cash received in advance."},{"id":"cr-s4-level1-v1-q2","session":"4","level":1,"topic":"Investment versus equivalent","question":"Listed ordinary shares can be sold immediately, but their price is exposed to significant movements. Which cash equivalent requirement is missing, even though they are highly liquid?","choices":["Cash equivalents must have an original maturity of no more than twelve months.","Cash equivalents must be available as security for short-term bank borrowing.","Cash equivalents must be traded on a market where prices are quoted daily.","Cash equivalents must convert to known cash amounts with insignificant value risk."],"correct_index":3,"explanation":"Liquidity alone is insufficient. Cash equivalents must be readily convertible to known amounts of cash and subject to an insignificant risk of changes in value. Significant share-price fluctuations fail this test even when the shares can be sold immediately."},{"id":"cr-s4-level1-v1-q3","session":"4","level":1,"topic":"Machine purchase","question":"A manufacturer pays €18 million cash for a machine that it will use for five years. How is the payment classified in its statement of cash flows?","choices":["An investing outflow of €18 million","An operating outflow of €18 million","A financing outflow of €18 million","No cash flow because the machine is capitalised"],"correct_index":0,"explanation":"Purchasing property, plant and equipment is an investing activity. Capitalising the machine means recognising an asset rather than an immediate expense. It does not eliminate the cash payment."},{"id":"cr-s4-level1-v1-q4","session":"4","level":1,"topic":"Principal versus interest","question":"A company pays €12 million to repay the principal of a bank loan. The payment includes no interest. In which IAS 7 category is the payment reported?","choices":["Operating activities","Financing activities","Investing activities","Non-cash transactions"],"correct_index":1,"explanation":"Repaying loan principal reduces borrowings and is a financing cash outflow. The classification of interest does not affect this principal repayment."},{"id":"cr-s4-level1-v1-q5","session":"4","level":1,"topic":"Depreciation adjustment","question":"A company reports profit before tax of €40 million after charging €8 million depreciation. It has no other non-cash items, working-capital changes or non-operating items. What is cash generated from operations before tax paid?","choices":["€32 million","€40 million","€48 million","€8 million"],"correct_index":2,"explanation":"Depreciation reduced profit but did not require a cash payment during the period. Add it back: €40m + €8m = €48m. The original purchase of the asset is dealt with separately as an investing activity."},{"id":"cr-s4-level1-v1-q6","session":"4","level":1,"topic":"Receivables movement","question":"Annual credit sales are €120 million. Trade receivables increase from €20 million to €35 million. There are no cash sales, write-offs, sales taxes or other changes in receivables. How much cash was received from customers?","choices":["€135 million","€120 million","€85 million","€105 million"],"correct_index":3,"explanation":"Cash receipts = opening receivables + credit sales − closing receivables = €20m + €120m − €35m = €105m. The €15m receivables increase means collections were €15m below revenue."},{"id":"cr-s4-level1-v1-q7","session":"4","level":1,"topic":"Tax classification condition","question":"A company sells a long-term investment and classifies the proceeds as investing cash flow. A separate income tax payment can be specifically identified with that sale. How is that tax payment classified under IAS 7?","choices":["Investing activity","Operating activity","Financing activity","A movement within cash equivalents"],"correct_index":0,"explanation":"Income taxes are normally operating cash flows. When a tax payment can be specifically identified with an investing transaction, IAS 7 classifies it as investing instead."},{"id":"cr-s4-level1-v1-q8","session":"4","level":1,"topic":"Direct and indirect consistency","question":"Using the same transactions and classification policies, a company calculates operating cash flow of €32 million by the direct method and €28 million by the indirect method. What does the difference indicate?","choices":["The methods recognise cash in different periods.","An error or inconsistent adjustment needs to be found.","The indirect method excludes working capital.","The company may report either total."],"correct_index":1,"explanation":"The direct method lists cash receipts and payments. The indirect method adjusts profit to the same underlying cash flow. A €4m difference is a reconciliation problem, not an allowed difference between methods."},{"id":"cr-s4-level1-v1-q9","session":"4","level":1,"topic":"Owner cash contribution","question":"A company issues its own ordinary shares and receives €15 million cash. There are no issue costs. How are the proceeds reported in its statement of cash flows?","choices":["An operating inflow of €15 million","An investing inflow of €15 million","A financing inflow of €15 million","Financing for nominal capital and operating for the premium"],"correct_index":2,"explanation":"Cash from issuing the entity's own shares is a financing inflow. This includes both nominal share capital and any share premium. The shareholders' investment perspective does not determine the issuer's cash-flow classification."},{"id":"cr-s4-level1-v1-q10","session":"4","level":1,"topic":"Cash reconciliation","question":"The cash flow statement groups cash with cash equivalents. The balance sheet instead shows some of those equivalents within short term investments. What must the company reconcile so a reader can connect the two reported totals?","choices":["Profit for the year to total current assets in the statement of financial position.","Current borrowings to non-current borrowings in the statement of financial position.","Operating cash flows to total comprehensive income for the reporting period.","Cash and cash equivalents to the corresponding statement of financial position items."],"correct_index":3,"explanation":"IAS 7 requires disclosure of the components of cash and cash equivalents and a reconciliation to the corresponding items in the statement of financial position. Here, that reconciliation explains how cash and the qualifying short-term investment together form the cash-flow total. It does not reconcile cash to profit or comprehensive income."},{"id":"cr-s4-level2-v1-q1","session":"4","level":2,"topic":"Supplier cash payments","question":"Cost of sales is €100 million. Inventory increases from €30 million to €42 million, and trade payables increase from €18 million to €25 million. All inventory purchases are on credit. There are no write-downs, sales taxes or other movements. How much cash is paid to suppliers?","choices":["€112 million","€119 million","€95 million","€105 million"],"correct_index":3,"explanation":"Purchases = €100m + €42m − €30m = €112m. Cash paid = purchases + opening payables − closing payables = €112m + €18m − €25m = €105m."},{"id":"cr-s4-level2-v1-q2","session":"4","level":2,"topic":"Operating reconciliation","question":"Profit before tax is €80 million after depreciation of €12 million and a €5 million gain on selling equipment. Trade receivables rise by €9 million, inventory falls by €4 million and trade payables fall by €6 million. There are no other adjustments. What is cash generated from operations before tax paid?","choices":["€76 million","€86 million","€88 million","€98 million"],"correct_index":0,"explanation":"Start with €80m. Add depreciation €12m, subtract the disposal gain €5m, subtract the receivables increase €9m, add the inventory decrease €4m and subtract the payables decrease €6m. Total: €76m. The equipment sale proceeds are investing cash flow."},{"id":"cr-s4-level2-v1-q3","session":"4","level":2,"topic":"Disposal gain versus cash","question":"Equipment with a carrying amount of €14 million is sold for €20 million cash. Profit before tax includes the €6 million disposal gain. What adjustments are needed in the statement of cash flows?","choices":["Deduct €20m in operating activities and report €6m investing inflow.","Deduct €6m in operating activities and report €20m investing inflow.","Add €6m in operating activities and report €20m operating inflow.","Keep the gain in operating activities and report €14m investing inflow."],"correct_index":1,"explanation":"Remove the €6m gain from profit in the indirect operating reconciliation. Report the full €20m cash proceeds as investing. The carrying amount determines the accounting gain, not the amount of cash received."},{"id":"cr-s4-level2-v1-q4","session":"4","level":2,"topic":"Interest policy before IFRS18","question":"Before adopting IFRS 18, a company classifies interest paid as financing. Profit before tax is €60 million after interest expense of €7 million, all paid. Depreciation is €10 million and operating income taxes paid are €12 million. There are no other adjustments. What is net cash from operating activities?","choices":["€58 million","€72 million","€65 million","€51 million"],"correct_index":2,"explanation":"Cash generated before tax = €60m + €10m depreciation + €7m interest = €77m. Deduct operating tax paid of €12m to get €65m. Add back the interest expense because the €7m payment is reported in financing, not operating activities."},{"id":"cr-s4-level2-v1-q5","session":"4","level":2,"topic":"Dividend policy before IFRS18","question":"Before adopting IFRS 18, a company consistently reports dividends paid as financing. Before a dividend payment, operating cash inflow is €45 million and financing cash outflow is €12 million. It then pays an €8 million dividend. What totals should it report?","choices":["Operating inflow €37m and financing outflow €12m","Operating inflow €45m and financing outflow €4m","Operating inflow €53m and financing outflow €20m","Operating inflow €45m and financing outflow €20m"],"correct_index":3,"explanation":"The €8m dividend is a financing payment under the stated policy. Operating inflow stays €45m. Financing outflow increases from €12m to €20m. Do not subtract the dividend from operating activities as well."},{"id":"cr-s4-level2-v1-q6","session":"4","level":2,"topic":"IFRS18 indirect starting point","question":"A manufacturer applies IFRS 18 and the related IAS 7 amendments. Operating profit is €70 million after €11 million depreciation. Operating trade receivables increase by €6 million. There are no other operating adjustments or operating tax payments. Which starting point and operating cash flow are correct under the indirect method?","choices":["Start with operating profit of €70m and report €75m cash inflow.","Start with profit after tax and report €70m cash inflow.","Start with operating profit of €70m and report €65m cash inflow.","Start with financing expense and report €87m cash inflow."],"correct_index":0,"explanation":"The amended IAS 7 indirect method starts with operating profit or loss. Add the €11m non-cash depreciation and subtract the €6m receivables increase: €70m + €11m − €6m = €75m."},{"id":"cr-s4-level2-v1-q7","session":"4","level":2,"topic":"Prepayments and accruals","question":"Profit before tax is €30 million. Operating prepayments increase by €4 million and accrued operating expenses increase by €6 million. There are no other adjustments or income tax payments. What is net operating cash flow?","choices":["€20 million","€32 million","€28 million","€40 million"],"correct_index":1,"explanation":"Subtract the €4m prepayments increase because cash paid exceeds the expense recognised. Add the €6m accruals increase because expense exceeds cash paid. Operating cash flow = €30m − €4m + €6m = €32m."},{"id":"cr-s4-level2-v1-q8","session":"4","level":2,"topic":"Net cash change","question":"Opening cash and cash equivalents are €12 million. Operating cash inflow is €55 million, investing cash outflow is €40 million and financing cash inflow is €9 million. There are no exchange effects or other movements. What is closing cash and cash equivalents?","choices":["€24 million","€18 million","€36 million","€116 million"],"correct_index":2,"explanation":"Net cash inflow = €55m − €40m + €9m = €24m. Add this movement to opening cash of €12m to obtain closing cash of €36m. The movement and closing balance are different amounts."},{"id":"cr-s4-level2-v1-q9","session":"4","level":2,"topic":"Noncash acquisition","question":"A company acquires equipment worth €25 million by issuing its own shares directly to the seller. Neither party pays cash. How is this transaction treated in the statement of cash flows?","choices":["Report €25m investing outflow and €25m financing inflow.","Report €25m investing outflow but no financing inflow.","Report €25m financing inflow but no investing outflow.","Exclude it from cash-flow totals and disclose the non-cash transaction separately."],"correct_index":3,"explanation":"There is no cash receipt or payment to report. The equipment acquisition and share issue are non-cash investing and financing transactions, disclosed separately where relevant. Reporting equal cash inflows and outflows would invent cash movements."},{"id":"cr-s4-level2-v1-q10","session":"4","level":2,"topic":"Overdraft included in cash","question":"A company has positive cash and cash equivalents of €6 million and a €9 million bank overdraft. The overdraft is repayable on demand, forms an integral part of cash management and meets the IAS 7 conditions for inclusion in cash and cash equivalents. What net balance is reported?","choices":["Negative €3 million","Positive €6 million","Positive €15 million","Zero"],"correct_index":0,"explanation":"Deduct the qualifying overdraft: €6m − €9m = negative €3m. Inclusion depends on the stated cash-management conditions. Ordinary bank borrowings do not automatically qualify for this treatment."},{"id":"cr-s4-level2-v1-q11","session":"4","level":2,"topic":"Indirect method computation","question":"Profit before tax is €350,000 after depreciation of €55,000 and a €20,000 loss on selling equipment. Trade receivables fall by €15,000, inventory rises by €30,000 and trade payables rise by €12,000. There are no other adjustments. What is cash generated from operations before tax paid?","choices":["€402,000","€422,000","€392,000","€482,000"],"correct_index":1,"explanation":"Add back depreciation and the disposal loss. Add the receivables decrease and payables increase, then subtract the inventory increase: €350,000 + €55,000 + €20,000 + €15,000 − €30,000 + €12,000 = €422,000. The equipment proceeds are reported as investing."},{"id":"cr-s4-level3-v1-q1","session":"4","level":3,"topic":"Direct indirect full bridge","question":"Credit sales are €240 million and receivables increase by €18 million. Cost of sales is €140 million, inventory increases by €12 million and trade payables increase by €9 million. Employee costs of €40 million are paid in full. Depreciation of €16 million is the only other expense. Operating taxes paid are €8 million. There are no sales taxes, write-offs or other movements. What is net operating cash flow?","choices":["€31 million","€47 million","€55 million","€49 million"],"correct_index":0,"explanation":"Customer receipts = €240m − €18m = €222m. Purchases = €140m + €12m = €152m, so supplier payments = €152m − €9m = €143m. Net operating cash = €222m − €143m − €40m − €8m = €31m. Check indirectly: profit before tax €44m + depreciation €16m − receivables €18m − inventory €12m + payables €9m − tax €8m = €31m."},{"id":"cr-s4-level3-v1-q2","session":"4","level":3,"topic":"Separate operating and disposal losses","question":"Before adopting IFRS 18, a company classifies interest paid as financing. Profit before tax is €50 million after depreciation of €9 million, a €4 million loss on selling equipment and €6 million interest expense, all paid. The equipment is sold for €11 million cash. Inventory rises by €7 million, receivables fall by €3 million and trade payables fall by €5 million. Operating taxes paid are €10 million. What are net operating cash flow and the investing inflow from the equipment sale?","choices":["Operating €44m and investing €11m","Operating €50m and investing €11m","Operating €46m and investing €15m","Operating €61m and investing €4m"],"correct_index":1,"explanation":"Operating cash flow = €50m + €9m + €4m + €6m − €7m + €3m − €5m − €10m = €50m. Add back the loss and financing interest to remove them from operating profit reconciliation. The investing receipt is the cash selling price of €11m, not the loss or carrying amount."},{"id":"cr-s4-level3-v1-q3","session":"4","level":3,"topic":"Method and regime change","question":"Before adopting IFRS 18, a manufacturer reports operating cash inflow of €90 million after interest paid of €8 million and dividends paid of €12 million. Financing cash outflow is €20 million, excluding these two payments. Under the IAS 7 amendments it must classify both payments as financing. If the underlying cash flows stay unchanged, what are the revised totals?","choices":["Operating inflow €90m and financing outflow €40m","Operating inflow €110m and financing outflow €20m","Operating inflow €110m and financing outflow €40m","Operating inflow €70m and financing outflow €40m"],"correct_index":2,"explanation":"Move €20m of payments out of operating activities, increasing operating inflow from €90m to €110m. Add them to financing payments, increasing financing outflow from €20m to €40m. Net cash from the two categories stays €70m."},{"id":"cr-s4-level3-v1-q4","session":"4","level":3,"topic":"Cash versus funding mix","question":"Opening cash is €10 million. During the year a company collects €100 million from customers, pays €76 million to suppliers and employees, and pays €6 million operating tax. It buys equipment for €30 million and sells old equipment for €5 million. It receives a new loan of €18 million, repays €4 million principal and pays €7 million dividends classified as financing. There are no other movements. Which operating, investing, financing and closing cash amounts are correct?","choices":["€24m, −€25m, €7m and €16m","€18m, −€30m, €7m and €5m","€18m, −€25m, €14m and €17m","€18m, −€25m, €7m and €10m"],"correct_index":3,"explanation":"Operating = €100m − €76m − €6m = €18m. Investing = −€30m + €5m = −€25m. Financing = €18m − €4m − €7m = €7m. Net movement is zero, so closing cash equals opening cash of €10m."},{"id":"cr-s4-level3-v1-q5","session":"4","level":3,"topic":"Receivables and noncash allowance","question":"Profit before tax is €60 million after €5 million impairment expense on trade receivables and €10 million depreciation. Gross receivables increase by €12 million. The loss allowance increases only by the €5 million expense, with no write-offs. There are no other adjustments or taxes paid. What is net operating cash flow?","choices":["€63 million","€58 million","€68 million","€73 million"],"correct_index":0,"explanation":"Using gross receivables, add back the non-cash impairment expense and depreciation, then deduct gross receivables growth: €60m + €5m + €10m − €12m = €63m. Alternatively, net receivables rise by €7m, so €60m + €10m − €7m = €63m. Do not add the impairment expense again in the second method."},{"id":"cr-s4-level3-v1-q6","session":"4","level":3,"topic":"Profit includes unpaid interest","question":"Before applying IFRS 18, a company classifies interest paid as financing. Profit before tax is €42 million after €9 million interest expense. Interest payable rises from €2 million to €5 million. Depreciation is €8 million and operating taxes paid are €7 million. There are no other movements. What are net operating cash flow and cash interest paid in financing activities?","choices":["Operating €49m and interest paid €9m","Operating €52m and interest paid €6m","Operating €46m and interest paid €6m","Operating €52m and interest paid €12m"],"correct_index":1,"explanation":"Operating cash = €42m + €9m interest expense + €8m depreciation − €7m tax = €52m. Cash interest = opening payable €2m + expense €9m − closing payable €5m = €6m. Because interest is financing, its payable movement is not also included in operating working capital."},{"id":"cr-s4-level3-v1-q7","session":"4","level":3,"topic":"Disposal tax specifically linked","question":"Operating cash inflow before tax is €38 million. The company pays €10 million income tax, of which €3 million is specifically attributable to an investing disposal and €7 million to operating activities. Equipment sale proceeds are €24 million and equipment purchases are €32 million. There are no other investing flows. What net operating and investing cash flows are reported?","choices":["Operating €28m and investing −€8m","Operating €31m and investing −€8m","Operating €31m and investing −€11m","Operating €28m and investing −€11m"],"correct_index":2,"explanation":"Operating cash = €38m − €7m = €31m. Investing cash = €24m − €32m − €3m = −€11m. The specifically identifiable disposal tax follows the investing activity. All €10m of tax is included once, not twice."},{"id":"cr-s4-level3-v1-q8","session":"4","level":3,"topic":"Diagnose an incorrect reconciliation","question":"A company starts its indirect cash-flow calculation with profit before tax of €80 million and adds depreciation of €14 million. It then incorrectly adds an inventory increase of €6 million, subtracts a receivables decrease of €4 million and adds a payables decrease of €3 million. There are no other adjustments or taxes paid. What is the correct operating cash flow and the overstatement in the company's calculation?","choices":["Cash flow €99m and no overstatement","Cash flow €89m and overstatement €20m","Cash flow €83m and overstatement €16m","Cash flow €89m and overstatement €10m"],"correct_index":3,"explanation":"Correct the working-capital signs: €80m + €14m − €6m + €4m − €3m = €89m. The company calculated €99m. The individual errors increase cash by €12m, reduce it by €8m and increase it by €6m, a net €10m overstatement."},{"id":"cr-s4-level3-v1-q9","session":"4","level":3,"topic":"Exchange difference is not a cash receipt","question":"Opening cash and cash equivalents are €20 million. Operating cash inflow is €30 million, investing outflow is €22 million and financing outflow is €5 million. Exchange-rate translation increases the reported cash balance by €2 million but involves no receipt or payment. How is closing cash reconciled?","choices":["Closing €25m, including €3m net cash inflow and €2m exchange effect","Closing €23m, excluding the exchange effect entirely","Closing €25m, including the exchange effect in operating receipts","Closing €27m, including the exchange effect in cash flow and again separately"],"correct_index":0,"explanation":"Net cash flow = €30m − €22m − €5m = €3m. Closing cash = €20m + €3m + €2m = €25m. Show the exchange effect separately in the reconciliation. It is not an operating cash receipt."},{"id":"cr-s4-level3-v1-q10","session":"4","level":3,"topic":"IFRS18 avoid adding interest twice","question":"A manufacturer applies IFRS 18 and starts its indirect cash-flow calculation with operating profit of €100 million. That profit includes €20 million depreciation but excludes €12 million financing interest expense. Inventory increases by €15 million. Operating taxes paid are €18 million. Interest is fully paid and reported as financing. With no other adjustments, what is net operating cash flow?","choices":["€99 million","€87 million","€75 million","€105 million"],"correct_index":1,"explanation":"Operating cash = €100m + €20m depreciation − €15m inventory increase − €18m tax = €87m. Do not add back the €12m interest: it was already excluded from the starting operating profit. Its payment is reported separately in financing."},{"id":"cr-s4-level3-v1-q11","session":"4","level":3,"topic":"Direct method cash paid to suppliers","question":"Cost of sales is €480,000. Inventory decreases from €110,000 to €95,000 and trade payables increase from €70,000 to €88,000. All purchases are on credit and all payables relate to inventory. There are no write-downs, sales taxes or other changes. How much cash is paid to suppliers?","choices":["€465,000","€447,000","€480,000","€483,000"],"correct_index":1,"explanation":"Purchases = €480,000 + €95,000 − €110,000 = €465,000. Cash paid = purchases + opening payables − closing payables = €465,000 + €70,000 − €88,000 = €447,000. Falling inventory reduces purchases, while rising payables reduces the amount paid."}],"5":[{"id":"cr-s5-level1-v1-q1","session":"5","level":1,"topic":"Contractual versus physical asset","question":"A company owns inventory worth €8 million and trade receivables of €6 million. Which item is a financial asset under IAS 32?","choices":["Both the inventory and the receivables","Only the inventory","Only the trade receivables","Neither item"],"correct_index":2,"explanation":"Trade receivables are contractual rights to receive cash, so they are financial assets. Inventory is a physical asset. The ability to sell inventory for cash does not itself make the inventory a financial asset."},{"id":"cr-s5-level1-v1-q2","session":"5","level":1,"topic":"Statutory versus contractual obligation","question":"A company owes €4 million income tax under tax law and €9 million under a bank loan contract. Which amount is a financial liability under IAS 32's contractual definition?","choices":["Both amounts","Only the income tax","Neither amount","Only the bank loan"],"correct_index":3,"explanation":"The loan creates a contractual obligation to deliver cash. Income tax arises from law rather than a contract, so it is not a financial liability within IAS 32, although it remains a liability in the financial statements."},{"id":"cr-s5-level1-v1-q3","session":"5","level":1,"topic":"Holder and issuer perspectives","question":"An investor purchases ordinary shares with no contractual redemption right or mandatory dividend. The issuer has no obligation to deliver cash or another financial asset. What classification applies in each party accounts?","choices":["Equity for the issuer and a financial asset for the investor.","A financial liability for the issuer and a financial asset for the investor.","Equity for the issuer and equity for the investor.","A financial liability for the issuer and equity for the investor."],"correct_index":0,"explanation":"The issuer has issued an equity instrument because it has no contractual obligation to deliver cash or another financial asset. The investor holds an equity instrument of another entity, which is a financial asset. It is not part of the investor's own equity."},{"id":"cr-s5-level1-v1-q4","session":"5","level":1,"topic":"Mandatory redemption","question":"Preference shares require the issuer to repay €20 million cash in five years. They have no conversion option and no equity-classification exception applies. What determines their classification by the issuer?","choices":["Their legal description as shares makes them equity.","The mandatory cash repayment makes them a financial liability.","Their fixed repayment date affects disclosure only.","An intention to refinance makes them equity."],"correct_index":1,"explanation":"A mandatory obligation to deliver cash is a financial liability. IAS 32 follows the contractual substance rather than the legal title of the instrument. A plan to refinance does not remove the existing obligation."},{"id":"cr-s5-level1-v1-q5","session":"5","level":1,"topic":"Discretionary distributions","question":"Preference shares have no redemption date. The issuer can unconditionally refuse every dividend and has no other obligation to deliver cash or another financial asset. No settlement in own shares is required. How are they classified by the issuer?","choices":["A liability because preference shareholders rank ahead of ordinary shareholders","A liability because the issuer has paid dividends in the past","Equity because the issuer has no contractual payment obligation","A compound instrument split between expected dividends and principal"],"correct_index":2,"explanation":"On these terms the issuer can avoid delivering cash or another financial asset, so the shares are equity. Expected or habitual dividends are not the same as an unavoidable contractual obligation."},{"id":"cr-s5-level1-v1-q6","session":"5","level":1,"topic":"Dividend label versus substance","question":"An issuer's preference shares are correctly classified as a financial liability. They require an annual cash payment called a dividend. How is that payment treated in measuring the issuer's performance?","choices":["As a distribution directly reducing equity","As an expense in other comprehensive income","As repayment of principal only","As a finance cost in profit or loss"],"correct_index":3,"explanation":"Distributions relating to an instrument classified as a financial liability are treated as finance costs, even if legally called dividends. The name does not turn a liability-related cost into an equity distribution."},{"id":"cr-s5-level1-v1-q7","session":"5","level":1,"topic":"Ordinary equity distributions","question":"A company declares and pays a €5 million dividend on ordinary shares classified as equity. How is the dividend reported?","choices":["A €5 million reduction directly in equity","A €5 million finance expense in profit or loss","A €5 million expense in other comprehensive income","A liability settlement with no reduction in equity"],"correct_index":0,"explanation":"A dividend to equity holders acting as owners is a distribution, not an expense. It reduces equity by €5m. Recording a payable between declaration and payment does not change that total equity effect."},{"id":"cr-s5-level1-v1-q8","session":"5","level":1,"topic":"Split accounting","question":"A bond requires cash interest and repayment of principal unless the holder converts it into ordinary shares. The conversion option meets IAS 32's equity conditions. There are no issue costs. How does the issuer account for the bond on issue?","choices":["Recognise the full proceeds as a liability.","Recognise separate liability and equity components.","Recognise the full proceeds as equity.","Wait until maturity to decide whether there is equity."],"correct_index":1,"explanation":"This is a compound financial instrument. The issuer first measures the liability as comparable debt without conversion, then recognises the residual proceeds as equity. Separation occurs at issue, not when the holder decides whether to convert."},{"id":"cr-s5-level1-v1-q9","session":"5","level":1,"topic":"Market discount rate","question":"A convertible bond pays a 3% cash coupon. Similar debt issued by the same company without a conversion option yields 7%. The option qualifies as equity. Which discount rate is used to measure the liability component at issue?","choices":["3%","5%","7%","The required return on ordinary equity"],"correct_index":2,"explanation":"Discount the contractual interest and principal payments at the market yield on comparable non-convertible debt, 7%. The coupon determines the cash payments, not the appropriate discount rate. The residual issue proceeds are equity."},{"id":"cr-s5-level1-v1-q10","session":"5","level":1,"topic":"Presentation versus measurement standards","question":"Which Standards respectively govern an issuer's liability-versus-equity presentation, subsequent amortised-cost measurement and disclosures about financial instrument risks?","choices":["IFRS 9, IAS 32 and IFRS 7","IAS 32, IFRS 7 and IFRS 9","IFRS 7, IFRS 9 and IAS 32","IAS 32, IFRS 9 and IFRS 7"],"correct_index":3,"explanation":"IAS 32 addresses presentation, including liability and equity classification. IFRS 9 addresses recognition and measurement. IFRS 7 addresses disclosures about the significance of financial instruments and their risks."},{"id":"cr-s5-level2-v1-q1","session":"5","level":2,"topic":"Initial split calculation","question":"A company receives €100 million for a convertible bond. The conversion option qualifies as equity. The present value of the contractual debt payments, discounted at the yield on comparable non-convertible debt, is €84 million. There are no issue costs. What amounts are initially recognised?","choices":["Liability €100m and equity €16m","Liability €16m and equity €84m","Liability €84m and income €16m","Liability €84m and equity €16m"],"correct_index":3,"explanation":"Measure the liability first at €84m. Equity is the residual: €100m proceeds − €84m liability = €16m. The total allocation equals the proceeds received. The residual is not income."},{"id":"cr-s5-level2-v1-q2","session":"5","level":2,"topic":"One year convertible","question":"A company issues a one-year convertible bond for €100 million. At the end of the year it must pay a €4 million coupon and repay €100 million principal unless the holder converts. The conversion option qualifies as equity and comparable non-convertible debt yields 8%. With no issue costs, what liability and equity are recognised at issue, to two decimals?","choices":["Liability €96.30m and equity €3.70m","Liability €92.59m and equity €7.41m","Liability €100m and equity nil","Liability €104m and equity negative €4m"],"correct_index":0,"explanation":"The contractual debt cash flow is €104m in one year. Liability = €104m ÷ 1.08 = €96.2963m. Equity = €100m − €96.2963m = €3.7037m. Omitting the coupon would understate the liability."},{"id":"cr-s5-level2-v1-q3","session":"5","level":2,"topic":"First year effective finance cost","question":"The liability component of a convertible bond is initially €80 million and its effective interest rate is 10%. A €5 million cash coupon is paid at the end of year 1. There are no other payments or conversions. What are year 1 finance cost and the liability immediately after payment?","choices":["Cost €5m and liability €80m","Cost €8m and liability €83m","Cost €10m and liability €85m","Cost €8m and liability €88m"],"correct_index":1,"explanation":"Effective interest = opening liability €80m × 10% = €8m. Closing liability = €80m + €8m − €5m coupon = €83m. The cash coupon is not the full finance cost."},{"id":"cr-s5-level2-v1-q4","session":"5","level":2,"topic":"Equity reserve not remeasured","question":"A conversion option qualifies as equity under IAS 32 and was recorded at €12 million when its bond was issued. The share price then doubles, but the contractual terms and equity classification do not change. Should the recorded equity amount be remeasured?","choices":["Increase it to €24 million and recognise the increase in other comprehensive income.","Remeasure it at fair value and recognise the change in profit or loss.","Keep it at its original amount without subsequent remeasurement.","Reduce it each year and transfer the reduction to retained earnings."],"correct_index":2,"explanation":"An equity-classified conversion option is not subsequently remeasured. A change in the issuer's share price therefore does not change the original €12 million equity component. A conversion feature classified as a liability would follow different measurement rules."},{"id":"cr-s5-level2-v1-q5","session":"5","level":2,"topic":"Issue cost allocation","question":"Before issue costs, a convertible bond's €50 million proceeds are allocated €40 million to liability and €10 million to equity. Direct issue costs are €1 million and are allocated in those proportions. What net initial amounts are recognised?","choices":["Liability €39m and equity €10m","Liability €40m and equity €9m","Liability €40.8m and equity €10.2m","Liability €39.2m and equity €9.8m"],"correct_index":3,"explanation":"The liability receives 40/50 = 80% of costs, or €0.8m, reducing it to €39.2m. Equity receives €0.2m, reducing it to €9.8m. The balances total the €49m net cash proceeds."},{"id":"cr-s5-level2-v1-q6","session":"5","level":2,"topic":"Treasury share transaction","question":"A company repurchases its own ordinary shares for €8 million, then resells the same shares for €11 million. There are no taxes or transaction costs. Compared with equity before both transactions, what is the overall change and the gain recognised in profit or loss?","choices":["Equity increases €3m and no gain is recognised in profit or loss.","Equity increases €3m and a €3m gain is recognised in profit or loss.","Equity increases €11m and a €3m gain is recognised in profit or loss.","Equity increases €3m and a €3m gain is recognised in other comprehensive income."],"correct_index":0,"explanation":"The repurchase reduces equity by €8m and the resale increases it by €11m. Net equity rises €3m. Transactions in the company's own equity instruments are recorded directly in equity, not as investment gains in profit or loss or other comprehensive income."},{"id":"cr-s5-level2-v1-q7","session":"5","level":2,"topic":"Variable own shares","question":"A non-derivative contract requires a company to deliver enough of its own ordinary shares to settle a fixed €10 million obligation. The number of shares changes with their market price. Why is the obligation a financial liability rather than equity?","choices":["No cash is paid, so it is a residual interest.","The company owes a fixed value and uses a variable number of shares to pay it.","The fixed euro value means the number of shares is fixed.","Any future share issue must be classified as equity."],"correct_index":1,"explanation":"The company must deliver a variable number of its own shares to satisfy a fixed-value obligation. It is using shares as a payment method rather than giving the holder a fixed residual ownership interest. Settlement in own shares does not automatically mean equity."},{"id":"cr-s5-level2-v1-q8","session":"5","level":2,"topic":"Holder redemption option","question":"An instrument has no maturity date, but its holder may require cash redemption at any time. The issuer cannot refuse payment. No puttable-instrument or other equity exception applies. How is it classified by the issuer?","choices":["Equity because it has no fixed maturity","Equity because redemption is not expected","A financial liability because the holder can demand cash","A compound instrument split by expected dividend and redemption payments"],"correct_index":2,"explanation":"The holder can force the issuer to deliver cash. The issuer therefore lacks an unconditional right to avoid payment. No scheduled maturity or low expected redemption rate removes that contractual obligation."},{"id":"cr-s5-level2-v1-q9","session":"5","level":2,"topic":"Cash raising and leverage","question":"A company has liabilities of €60 million and equity of €40 million. It receives €20 million from issuing mandatorily redeemable preference shares that qualify entirely as a financial liability. There are no issue costs. What is the new ratio of total liabilities to equity?","choices":["1.00","1.50","1.33","2.00"],"correct_index":3,"explanation":"Liabilities become €60m + €20m = €80m. Equity remains €40m. The ratio is €80m ÷ €40m = 2.00. The legal share label does not make the proceeds equity."},{"id":"cr-s5-level2-v1-q10","session":"5","level":2,"topic":"Mandatory share conversion and coupon","question":"A company issues an instrument for €30 million. At maturity it must deliver a fixed number of its own ordinary shares and cannot be required to repay principal in cash. It must pay annual cash coupons. The share-settlement component qualifies as equity under IAS 32. Which cash flows are included in measuring the initial liability component?","choices":["Only the mandatory cash coupons","The coupons plus €30m cash principal","No cash flows because principal converts into shares","Only €30m cash principal"],"correct_index":0,"explanation":"The liability reflects the unavoidable cash coupon payments. There is no contractual cash repayment of principal to discount. The residual proceeds are allocated to the qualifying equity component."},{"id":"cr-s5-level2-v1-q11","session":"5","level":2,"topic":"Equity issue costs and treasury shares","question":"A company pays €40,000 incremental legal costs directly attributable to a successful issue of ordinary shares. It also repurchases its own ordinary shares for €150,000. Ignore tax. How are the two amounts reported?","choices":["Expense €40,000 and recognise a financial asset of €150,000.","Deduct both €40,000 and €150,000 directly from equity.","Deduct €40,000 from equity and expense €150,000.","Expense both €40,000 and €150,000."],"correct_index":1,"explanation":"Qualifying equity issue costs are deducted from equity. Repurchased own shares are also deducted from equity. Neither amount produces a gain or loss in profit or loss."},{"id":"cr-s5-level3-v1-q1","session":"5","level":3,"topic":"Two year convertible split","question":"A company issues a two-year convertible bond for €100 million. Coupons of €5 million are payable at each year-end. Principal of €100 million is repayable at the end of year 2 unless the holder converts. The option qualifies as equity. Comparable non-convertible debt yields 10%. With no costs or taxes, what liability and equity are initially recognised, to two decimals?","choices":["Liability €91.32m and equity €8.68m","Liability €86.78m and equity €13.22m","Liability €100m and equity nil","Liability €95.45m and equity €4.55m"],"correct_index":0,"explanation":"Liability = €5m ÷ 1.10 + €105m ÷ 1.10² = €91.3223m. Equity = €100m − €91.3223m = €8.6777m. Include the first coupon and the final coupon plus principal."},{"id":"cr-s5-level3-v1-q2","session":"5","level":3,"topic":"Conversion to fixed shares","question":"A holder converts a whole convertible bond on its original terms. Just before conversion, the recorded liability is €50 million and the equity conversion reserve is €6 million. The issuer delivers 10 million ordinary shares of €1 nominal value each and transfers the entire reserve to share premium. With no cash or transaction costs, what are the share capital, share premium and profit or loss entries?","choices":["Share capital €10 million, share premium €40 million and a gain of €6 million.","Share capital €10 million, share premium €46 million and no gain in profit or loss.","Share capital €50 million, share premium €6 million and no gain in profit or loss.","Share capital €10 million, share premium €6 million and a gain of €40 million."],"correct_index":1,"explanation":"Share capital equals 10 million shares × €1 = €10 million. Converting the €50 million liability credits share capital by €10 million and share premium by €40 million. The stated transfer of the existing equity component adds another €6 million to share premium, giving €46 million. The liability is removed and no gain or loss is recognised. The original equity component stays within equity."},{"id":"cr-s5-level3-v1-q3","session":"5","level":3,"topic":"Mandatory conversion PV","question":"An instrument is issued for €60 million and must convert into a fixed number of the issuer's ordinary equity shares after three years. There is no cash principal repayment. Coupons of €3 million are payable at the end of each of the three years. The comparable debt yield is 10%. With no issue costs, what are the initial liability and equity, to two decimals?","choices":["Liability €52.54m and equity €7.46m","Liability €52.54m and equity nil","Liability €7.46m and equity €52.54m","Liability €60m and equity nil"],"correct_index":2,"explanation":"Discount only the mandatory cash coupons: €3m/1.1 + €3m/1.1² + €3m/1.1³ = €7.4606m. Equity is €60m − €7.4606m = €52.5394m. Do not include a cash principal repayment that the contract does not require."},{"id":"cr-s5-level3-v1-q4","session":"5","level":3,"topic":"Issue costs and changing effective rate","question":"A mandatorily convertible instrument has a liability component for cash coupons and a qualifying equity component for fixed-share settlement. Before issue costs, its €50 million proceeds are allocated €10 million to liability and €40 million to equity. Direct issue costs of €1 million are allocated proportionately. Coupon payments do not change. What is the net liability and how does its effective interest rate compare with the rate before costs?","choices":["Liability €10.2m and a lower rate","Liability €9m and the same rate","Liability €10m and no effective interest rate","Liability €9.8m and a higher rate"],"correct_index":3,"explanation":"The liability bears 10/50 = 20% of the €1m costs, or €0.2m, leaving €9.8m. The same future cash payments discounted to a lower initial amount require a higher effective rate. The remaining €0.8m costs reduce equity."},{"id":"cr-s5-level3-v1-q5","session":"5","level":3,"topic":"Combined liability and equity payments","question":"Preference shares classified as a financial liability have an opening carrying amount of €40 million and an effective interest rate of 8%. The company pays a €2 million mandatory cash distribution at year-end. Separately, it pays €3 million ordinary equity dividends. There are no other movements. What are finance cost, closing preference-share liability and the direct equity reduction from ordinary dividends?","choices":["€3.2m, €41.2m and €3m","€5m, €40m and nil","€2m, €40m and €3m","€3.2m, €43.2m and €5m"],"correct_index":0,"explanation":"Finance cost = €40m × 8% = €3.2m. Liability after the payment = €40m + €3.2m − €2m = €41.2m. The separate €3m ordinary dividend reduces equity directly. The mandatory preference distribution is a liability-related payment, not an ordinary owner distribution."},{"id":"cr-s5-level3-v1-q6","session":"5","level":3,"topic":"Two year finance cost bridge","question":"A convertible bond's initial liability component is €80 million. Its effective interest rate is 10% and its annual coupon is €5 million, paid at each year-end. There are no conversions or other movements in the first two years. What are year 2 finance cost and the liability after the year 2 coupon?","choices":["Cost €8m and liability €86m","Cost €8.3m and liability €86.3m","Cost €10m and liability €90m","Cost €8.3m and liability €91.3m"],"correct_index":1,"explanation":"After year 1, the liability is €80m + €8m − €5m = €83m. Year 2 interest is €83m × 10% = €8.3m. Closing year 2 liability = €83m + €8.3m − €5m = €86.3m. Apply the effective rate to each year's opening carrying amount."},{"id":"cr-s5-level3-v1-q7","session":"5","level":3,"topic":"Equity costs versus debt costs","question":"A company issues ordinary shares for €20 million and pays €1 million directly attributable issue costs. It also issues a bond measured at amortised cost for €30 million and pays €0.6 million directly attributable bond issue costs. Ignore taxes. What are the initial equity increase, bond liability and net increase in cash?","choices":["Equity €20m, liability €30m and cash €48.4m","Equity €19m, liability €30.6m and cash €49.6m","Equity €19m, liability €29.4m and cash €48.4m","Equity €19.4m, liability €29m and cash €48.4m"],"correct_index":2,"explanation":"Equity = €20m − €1m = €19m. The amortised-cost liability is initially €30m − €0.6m = €29.4m. Cash increases by €20m + €30m − €1m − €0.6m = €48.4m. Debt costs affect the effective interest rate later, while equity costs remain in equity."},{"id":"cr-s5-level3-v1-q8","session":"5","level":3,"topic":"Classification correction and ratios","question":"A company reports liabilities of €90 million and equity of €60 million. Equity incorrectly includes a €30 million instrument that must be redeemed in cash. The instrument should be classified entirely as a liability. Ignore taxes and finance-cost corrections. What are corrected liabilities, equity and the ratio of liabilities to equity?","choices":["€120m, €60m and 2.00","€90m, €30m and 3.00","€60m, €90m and 0.67","€120m, €30m and 4.00"],"correct_index":3,"explanation":"Transfer €30m from equity to liabilities. Liabilities become €120m and equity becomes €30m. The ratio is €120m/€30m = 4.00. The combined total remains €150m because this is a reclassification, not new financing."},{"id":"cr-s5-level3-v1-q9","session":"5","level":3,"topic":"Misleading coupon based split","question":"A company issues a convertible bond at par. Its coupon rate is below the market yield on comparable non-convertible debt, and the conversion option qualifies as equity. A preparer discounts all coupons and principal at the coupon rate, recognising the full proceeds as liability and no equity. What is wrong with this calculation?","choices":["Using the coupon rate overstates the liability and understates equity.","Equity cannot be recognised until the holder converts.","The liability should equal the expected market value of shares on conversion.","Only principal should be discounted at the market yield."],"correct_index":0,"explanation":"Use the market yield on equivalent debt without conversion, not the coupon rate. A higher discount rate produces a liability below the proceeds. The remaining proceeds represent the qualifying equity option. Both coupons and principal use the comparable debt yield."},{"id":"cr-s5-level3-v1-q10","session":"5","level":3,"topic":"Contingent cash obligation","question":"An instrument called a share must be redeemed for cash if the issuer's credit rating falls below a specified level. This genuine condition is outside the issuer's control and is not limited to liquidation. No equity exception applies. Management expects no downgrade. What classification is required?","choices":["Equity because redemption is not forecast","A financial liability because the issuer cannot unconditionally avoid cash settlement","Equity until a downgrade actually occurs","A compound instrument split using the probability of downgrade"],"correct_index":1,"explanation":"The genuine contingent cash-settlement condition is outside the issuer's control. The issuer therefore lacks an unconditional right to avoid delivering cash. An optimistic forecast does not remove the contractual liability on these facts."},{"id":"cr-s5-level3-v1-q11","session":"5","level":3,"topic":"Own-use scope exception","question":"A chocolate maker contracts to buy cocoa for physical delivery and normal production use. The contract was entered into and remains held for that purpose, qualifies for the own-use exception and is not designated at fair value through profit or loss. A trader's separate cocoa contract requires net cash settlement. Which contract is within IFRS 9?","choices":["Both contracts","Neither contract","Only the trader's net-cash-settled contract","Only the chocolate maker's physical-delivery contract"],"correct_index":2,"explanation":"The chocolate maker's contract is outside IFRS 9 under the stated own-use conditions. The trader's contract requires net cash settlement and is within IFRS 9. A non-financial underlying does not by itself exclude a net-settled contract."}],"6":[{"id":"cr-s6-level1-v1-q1","session":"6","level":1,"topic":"Binding contract recognition","question":"A lender becomes party to a binding financial instrument contract that creates an enforceable loan receivable. It has not yet received any interest. What generally triggers recognition under IFRS 9?","choices":["The first date interest is due","The first interest receipt","Becoming a party to the contractual provisions","The first annual reporting date after signing"],"correct_index":2,"explanation":"IFRS 9 generally requires recognition when the entity becomes a party to the instrument's contractual provisions. Interest collection and year-end reporting occur later and are not the general recognition trigger."},{"id":"cr-s6-level1-v1-q2","session":"6","level":1,"topic":"Two amortised cost conditions","question":"A bond pays only principal and basic lending interest. The investor's business model is to hold the bond to collect those contractual cash flows. There is no fair-value option designation or other exception. How is the bond normally measured after initial recognition?","choices":["Debt at fair value through other comprehensive income","Fair value through profit or loss","Unchanging face value without interest accrual","Amortised cost using the effective interest method"],"correct_index":3,"explanation":"Both conditions for amortised cost are met: qualifying principal-and-interest cash flows and a hold-to-collect business model. Amortised cost changes for effective interest, receipts and relevant impairment. It is not simply face value held unchanged."},{"id":"cr-s6-level1-v1-q3","session":"6","level":1,"topic":"Cash flow test fails","question":"A company holds a bond to collect its cash flows. However, the return is linked directly to a commodity price and fails IFRS 9's solely-payments-of-principal-and-interest test. No exception applies. How is the bond measured?","choices":["Fair value through profit or loss","Amortised cost because the company intends to hold it","Debt at fair value through other comprehensive income","Principal at amortised cost and commodity returns in other comprehensive income"],"correct_index":0,"explanation":"A hold-to-collect model is insufficient when the contractual cash-flow test fails. The bond is measured at fair value through profit or loss, rather than forcing the principal and linked return into separate invented categories."},{"id":"cr-s6-level1-v1-q4","session":"6","level":1,"topic":"Trading business model","question":"An investor buys a fixed-coupon bond for short-term trading gains. Its contractual cash flows are solely principal and interest. How is it normally classified under IFRS 9?","choices":["Amortised cost because its cash flows pass the contractual test","Fair value through profit or loss because it is held for trading","Debt at fair value through other comprehensive income because it may be sold","Principal at amortised cost and coupons at fair value through profit or loss"],"correct_index":1,"explanation":"The business model matters as well as contractual cash flows. A trading portfolio is not managed just to collect contractual cash flows or to collect and sell under the qualifying debt model. Trading assets are measured at fair value through profit or loss."},{"id":"cr-s6-level1-v1-q5","session":"6","level":1,"topic":"Asset costs at amortised cost","question":"A company buys a debt investment at fair value of €10 million and pays €0.2 million directly attributable transaction costs. The investment is measured at amortised cost. Ignore impairment. What is its initial carrying amount?","choices":["€10.0 million","€9.8 million","€10.2 million","€10.4 million"],"correct_index":2,"explanation":"For a financial asset not measured at fair value through profit or loss, add eligible transaction costs to initial fair value: €10m + €0.2m = €10.2m. Those costs are then reflected in the effective interest calculation."},{"id":"cr-s6-level1-v1-q6","session":"6","level":1,"topic":"Trading asset transaction costs","question":"An investor buys a trading bond at fair value of €12 million and pays €0.3 million broker fees. The bond is measured at fair value through profit or loss. What are the initial asset and immediate transaction-cost expense?","choices":["Asset €12.3m and no expense","Asset €11.7m and no expense","Asset €12m and a direct equity deduction of €0.3m","Asset €12m and expense of €0.3m"],"correct_index":3,"explanation":"An asset at fair value through profit or loss starts at fair value of €12m. Its transaction costs are expensed immediately rather than added to the asset or taken directly to equity."},{"id":"cr-s6-level1-v1-q7","session":"6","level":1,"topic":"Debt issue costs","question":"A company issues a bond measured at amortised cost for €20 million and immediately pays €0.4 million directly attributable issue costs. What is the initial carrying amount of the liability?","choices":["€19.6 million","€20.4 million","€20 million with no later interest effect","Nil until principal becomes due"],"correct_index":0,"explanation":"Deduct qualifying issue costs from the liability's initial fair value: €20m − €0.4m = €19.6m. The effective interest method spreads these costs over the liability's life."},{"id":"cr-s6-level1-v1-q8","session":"6","level":1,"topic":"Cash coupon versus effective income","question":"A bond asset measured at amortised cost has an opening carrying amount of €90 million and an effective interest rate of 8%. It pays a €5 million coupon at year-end. Ignore impairment. What interest income is recognised?","choices":["€5 million","€7.2 million","€8 million","€2.2 million"],"correct_index":1,"explanation":"Effective interest income = €90m × 8% = €7.2m. The €5m cash coupon is deducted when updating the carrying amount. Cash interest received and effective interest income need not be equal."},{"id":"cr-s6-level1-v1-q9","session":"6","level":1,"topic":"Zero coupon cost","question":"A zero-coupon bond liability is initially recognised at €50 million and has an effective annual interest rate of 10%. No cash is paid in year 1. What are year 1 finance cost and closing liability?","choices":["Nil cost and liability €50m","Cost €5m and liability €45m","Cost €5m and liability €55m","Cost €10m and liability €60m"],"correct_index":2,"explanation":"Interest accrues even without a cash coupon. Finance cost = €50m × 10% = €5m. Add it to the liability for a closing amount of €55m. This is the unwinding of the initial discount."},{"id":"cr-s6-level1-v1-q10","session":"6","level":1,"topic":"Immaterial discounting","question":"A short-term trade receivable has an invoice amount of €2 million. It has no significant financing component and requires no impairment adjustment. What amount is consistent with the practical measurement used in the course?","choices":["Nil until the customer pays","A discounted amount regardless of materiality","The resale value of the goods supplied","The €2 million invoice amount"],"correct_index":3,"explanation":"When there is no significant financing component and no impairment adjustment, use the transaction or invoice amount on these facts. This does not permit ignoring a material financing effect or an expected credit loss."},{"id":"cr-s6-level2-v1-q1","session":"6","level":2,"topic":"One year asset roll forward","question":"A debt investment begins the year at amortised cost of €80 million and earns effective interest at 9%. At year-end the investor receives a €4 million coupon and €10 million principal repayment. There are no losses or other movements. What is closing amortised cost?","choices":["€83.2 million","€76 million","€87.2 million","€73.2 million"],"correct_index":3,"explanation":"Interest income = €80m × 9% = €7.2m. Closing amount = €80m + €7.2m − €4m − €10m = €73.2m. Both the coupon and principal receipt reduce the balance."},{"id":"cr-s6-level2-v1-q2","session":"6","level":2,"topic":"Issue discount total cost","question":"A three-year bond is issued for €90 million and repaid at €100 million. Coupons of €5 million are paid at each year-end in addition to principal. There are no costs or other changes. What is total finance expense over the bond's full life?","choices":["€25 million","€15 million","€10 million","€115 million"],"correct_index":0,"explanation":"Total payments are €100m principal + 3 × €5m coupons = €115m. Deduct €90m initial proceeds to get €25m total finance expense. This comprises €15m coupons and the €10m issue discount."},{"id":"cr-s6-level2-v1-q3","session":"6","level":2,"topic":"Issue premium total cost","question":"A two-year bond is issued for €105 million and repaid at €100 million. It pays €6 million coupons at each year-end. There are no issue costs or other changes. What total finance expense is recognised over its life?","choices":["€12 million","€7 million","€17 million","€5 million"],"correct_index":1,"explanation":"Total payments are €100m principal + €12m coupons = €112m. Less €105m proceeds gives €7m total expense. The €5m issue premium reduces expense below total cash coupons."},{"id":"cr-s6-level2-v1-q4","session":"6","level":2,"topic":"Second year asset interest","question":"A bond asset starts year 1 at €100 million. Its effective rate is 6% and it pays a €4 million coupon at each year-end. There are no principal payments, impairments or other changes in the first two years. What are year 2 interest income and closing carrying amount?","choices":["Income €6m and amount €104m","Income €4m and amount €100m","Income €6.12m and amount €104.12m","Income €6.12m and amount €108.12m"],"correct_index":2,"explanation":"Year 1 closes at €100m + €6m − €4m = €102m. Year 2 interest = €102m × 6% = €6.12m. Closing year 2 amount = €102m + €6.12m − €4m = €104.12m."},{"id":"cr-s6-level2-v1-q5","session":"6","level":2,"topic":"AC versus FVTPL comparison","question":"A debt investment is bought for €100 million with no transaction costs. It pays a €5 million coupon during the year and has year-end fair value of €97 million. It is measured at fair value through profit or loss. Ignore tax. What are its total profit contribution and closing carrying amount?","choices":["Profit €6m and asset €101m","Loss €3m and asset €97m","Profit €5m and asset €100m","Profit €2m and asset €97m"],"correct_index":3,"explanation":"The coupon contributes €5m income and the fair-value fall contributes a €3m loss. Net profit contribution is €2m. The closing asset is its €97m fair value. Do not replace fair-value measurement with an amortised-cost amount."},{"id":"cr-s6-level2-v1-q6","session":"6","level":2,"topic":"Debt FVOCI versus equity FVOCI","question":"One investment is qualifying debt measured at fair value through other comprehensive income. Another is a non-trading equity investment validly designated in that category. On disposal, how do their accumulated fair-value gains differ?","choices":["Debt gains are recycled to profit or loss, while designated equity gains are not.","Both are recycled to profit or loss.","Neither can be recycled to profit or loss.","Equity gains are recycled, while debt gains are not."],"correct_index":0,"explanation":"Debt and elected equity fair-value-through-other-comprehensive-income accounting differ. Accumulated debt gains are reclassified to profit or loss on derecognition. Gains on designated non-trading equity are not subsequently recycled to profit or loss."},{"id":"cr-s6-level2-v1-q7","session":"6","level":2,"topic":"Zero coupon present value","question":"A zero-coupon liability requires a single €121 million payment after two years. Its effective annual interest rate is 10% and there are no issue costs. What are its initial amount and amount at the end of year 1?","choices":["€110m and €121m","€100m and €110m","€121m and €121m","€100m and €100m"],"correct_index":1,"explanation":"Initial present value = €121m/1.1² = €100m. Year 1 interest = €100m × 10% = €10m, giving €110m. Year 2 interest of €11m then brings it to the €121m settlement amount."},{"id":"cr-s6-level2-v1-q8","session":"6","level":2,"topic":"Holder transaction cost yield","question":"An investor pays €98 million for a one-year debt investment and €2 million of transaction costs directly related to the purchase. The investment is held to collect contractual cash flows that are solely payments of principal and interest, and it pays a single €105 million at maturity. Ignore impairment. What are its initial carrying amount and effective annual yield?","choices":["€98m and 7.14%","€96m and 9.375%","€100m and 5%","€100m and 7.14%"],"correct_index":2,"explanation":"Under the hold-to-collect model with solely principal-and-interest cash flows the investment is measured at amortised cost, and the transaction costs enter its carrying amount: €98m + €2m = €100m. The effective yield solves €100m × (1 + r) = €105m, so r = 5%. Calculating yield on the price alone ignores part of the investor's outlay."},{"id":"cr-s6-level2-v1-q9","session":"6","level":2,"topic":"Issuer transaction cost yield","question":"A company issues a one-year amortised-cost bond for €100 million and pays €4 million direct issue costs. It must pay €105.6 million in total at maturity. What are initial liability and effective annual interest rate?","choices":["€100m and 5.6%","€104m and 1.54%","€96m and 5.6%","€96m and 10%"],"correct_index":3,"explanation":"Initial liability = €100m − €4m = €96m. Effective rate = €105.6m/€96m − 1 = 10%. Issue costs raise the effective financing rate above the 5.6% return calculated using gross proceeds."},{"id":"cr-s6-level2-v1-q10","session":"6","level":2,"topic":"Mixed business model","question":"A debt portfolio has cash flows solely of principal and interest. Its business model is achieved by both collecting contractual cash flows and selling investments. The portfolio is not designated at fair value through profit or loss. How is it measured?","choices":["Debt at fair value through other comprehensive income","Amortised cost because principal and interest are collected","Fair value through profit or loss because any sale excludes the other categories","Equity at fair value through other comprehensive income"],"correct_index":0,"explanation":"The collect-and-sell model, together with solely principal-and-interest cash flows, leads to debt at fair value through other comprehensive income. The contractual cash-flow test alone does not establish amortised cost, because the business model is not hold-to-collect. This is a debt category, not an equity election."},{"id":"cr-s6-level3-v1-q1","session":"6","level":3,"topic":"Below market shareholder loan","question":"A parent lends its subsidiary €121 million interest-free, repayable in one amount after two years. Comparable borrowing yields 10%. In the subsidiary's separate accounts, the loan is initially at fair value and the shareholder benefit is a capital contribution. Ignore costs and tax. What are the initial liability, equity contribution and year 1 finance cost?","choices":["€100m, €21m and €10m","€121m, nil and nil","€100m, €21m income and €10m cost","€110m, €11m and €11m"],"correct_index":0,"explanation":"Present value = €121m/1.1² = €100m. Cash received exceeds the liability by €21m, recorded as the stated shareholder contribution in equity. Year 1 finance cost = €100m × 10% = €10m, increasing the liability to €110m."},{"id":"cr-s6-level3-v1-q2","session":"6","level":3,"topic":"Premium liability amortisation","question":"An amortised-cost liability starts year 1 at €110 million. Its effective annual interest rate is 5%, and it pays an €8 million coupon at the end of each of the next two years. No principal is repaid in those years and there are no other movements. What are year 2 finance cost and closing liability, to three decimals?","choices":["€5.500m and €105.000m","€5.375m and €104.875m","€8.000m and €110.000m","€5.375m and €112.875m"],"correct_index":1,"explanation":"Year 1 interest is €110m × 5% = €5.5m, leaving €107.5m after the coupon. Year 2 interest is €107.5m × 5% = €5.375m. Deduct the second €8m coupon to obtain €104.875m. A premium liability can fall while finance cost remains positive."},{"id":"cr-s6-level3-v1-q3","session":"6","level":3,"topic":"Cumulative zero coupon expense","question":"A zero-coupon liability is issued for €80 million with a 10% effective annual interest rate. No payments or other movements occur for three years. What are the liability and cumulative finance cost at the end of year 3?","choices":["Liability €104m and cost €24m","Liability €88m and cost €8m","Liability €106.48m and cost €26.48m","Liability €106.48m and cost €10.648m"],"correct_index":2,"explanation":"Compound the initial amount: €80m × 1.1³ = €106.48m. Cumulative expense is the increase of €26.48m. The individual annual costs are €8m, €8.8m and €9.68m. Do not confuse one year's cost with the three-year total."},{"id":"cr-s6-level3-v1-q4","session":"6","level":3,"topic":"FVTPL fees and disposal","question":"A trading bond is bought for €96 million plus €1 million broker fees. It pays €4 million interest in year 1 and its year-end fair value is €99 million. In year 2 it pays €2 million interest and is sold for €98 million, with no further fees. It is measured at fair value through profit or loss. Ignore tax. What are year 1, year 2 and cumulative profit contributions?","choices":["€7m, €1m and €8m","€6m, €4m and €10m","€3m, €1m and €4m","€6m, €1m and €7m"],"correct_index":3,"explanation":"Year 1: €4m interest + (€99m − €96m) fair-value gain − €1m fee = €6m. Year 2: €2m interest + (€98m − €99m) disposal loss = €1m. Cumulative profit is €7m, also total receipts €104m less total outlay €97m."},{"id":"cr-s6-level3-v1-q5","session":"6","level":3,"topic":"Staggered principal repayments","question":"A debt asset begins year 1 at €120 million with an effective annual rate of 8%. Total cash received is €10 million at the end of year 1 and €30 million at the end of year 2. These amounts already include all interest and principal receipts. There is no impairment or other movement. What are year 2 interest income and closing carrying amount?","choices":["€9.568m and €99.168m","€9.600m and €99.200m","€8.800m and €88.800m","€9.568m and €109.168m"],"correct_index":0,"explanation":"Year 1 closes at €120m + €9.6m − €10m = €119.6m. Year 2 interest = €119.6m × 8% = €9.568m. Closing amount = €119.6m + €9.568m − €30m = €99.168m. Do not subtract a coupon again when total receipts already include it."},{"id":"cr-s6-level3-v1-q6","session":"6","level":3,"topic":"Amortised cost plus impairment","question":"A debt asset has opening gross amortised cost of €100 million and a €1 million loss allowance. It remains non-credit-impaired. The effective rate is 6% and cash coupon €4 million. The required closing allowance is €3 million, with no write-offs or other movements. What are interest income, impairment expense and closing net carrying amount?","choices":["€5.94m, €3m and €99m","€6m, €2m and €99m","€6m, €3m and €97m","€4m, €2m and €97m"],"correct_index":1,"explanation":"Interest on the stated non-credit-impaired gross balance is €100m × 6% = €6m. Gross closing cost is €100m + €6m − €4m = €102m. Allowance expense is the increase from €1m to €3m, or €2m. Net closing amount = €102m − €3m = €99m."},{"id":"cr-s6-level3-v1-q7","session":"6","level":3,"topic":"Debt FVOCI total bridge","question":"A debt investment is initially recognised at €100 million and measured at fair value through other comprehensive income. Effective interest income of €5 million is fully received in cash. Closing fair value is €92 million. There is no impairment, foreign exchange, disposal or tax. What are the contributions to profit, other comprehensive income and total comprehensive income?","choices":["Loss €3m, nil and loss €3m","Profit €5m, loss €3m and income €2m","Profit €5m, loss €8m and loss €3m","Nil, loss €8m and loss €8m"],"correct_index":2,"explanation":"Interest of €5m enters profit. Because cash interest equals effective interest, the amortised-cost basis remains €100m. The fair-value decrease to €92m produces an €8m other comprehensive loss. Total comprehensive result = €5m − €8m = a €3m loss."},{"id":"cr-s6-level3-v1-q8","session":"6","level":3,"topic":"Two year yield and total expense","question":"A two-year zero-coupon bond is issued for €100 million gross. The issuer pays €4 million direct issue costs and must repay €116.16 million at maturity. There are no other payments or changes. What are the effective annual rate and total finance cost?","choices":["7.78% and €16.16m","10% and €16.16m","21% and €20.16m","10% and €20.16m"],"correct_index":3,"explanation":"Initial liability is €100m − €4m = €96m. The two-year factor is €116.16m/€96m = 1.21, so the annual rate is 10%. Total expense = €116.16m − €96m = €20.16m, including both the redemption difference and issue costs."},{"id":"cr-s6-level3-v1-q9","session":"6","level":3,"topic":"AC fair value temptation","question":"A qualifying hold-to-collect bond is correctly measured at amortised cost. Its opening carrying amount is €50 million, effective rate 8% and cash coupon €3 million. Closing market fair value is €57 million. There is no impairment or other movement. What are closing carrying amount and current interest income?","choices":["€51m and €4m","€57m and €10m","€53m and €3m","€50m and €4m"],"correct_index":0,"explanation":"Interest income = €50m × 8% = €4m. Closing amortised cost = €50m + €4m − €3m = €51m. The €57m market value does not replace the carrying amount in this measurement category."},{"id":"cr-s6-level3-v1-q10","session":"6","level":3,"topic":"Reconcile income with net cash","question":"An investor buys a zero-coupon asset for €81 million including transaction costs. Its effective annual rate is 10%. No cash is received until the asset is sold for €99 million immediately after year 2 interest accrues. There is no impairment. What are cumulative effective interest and the disposal gain or loss?","choices":["Interest €18m and no disposal gain","Interest €17.01m and gain €0.99m","Interest €16.2m and gain €1.8m","Interest €17.01m and loss €0.99m"],"correct_index":1,"explanation":"After two years the amortised-cost balance is €81m × 1.1² = €98.01m. Cumulative interest is €17.01m. Sale proceeds of €99m exceed that balance by €0.99m. Combined income of €18m equals proceeds less the original €81m outlay."}],"7":[{"id":"cr-s7-level1-v1-q1","session":"7","level":1,"topic":"Customer default exposure","question":"A supplier may lose money because a customer fails to pay a trade receivable. Which financial risk does this illustrate?","choices":["Liquidity risk","Interest rate risk","Credit risk","Currency risk"],"correct_index":2,"explanation":"Credit risk is the risk of financial loss when a counterparty fails to meet its obligation. A contractual right to receive cash is not a guarantee that the cash will be collected."},{"id":"cr-s7-level1-v1-q2","session":"7","level":1,"topic":"Maturity mismatch","question":"A company has valuable long-term assets but no accessible cash or funding to repay a loan tomorrow. Which risk is directly illustrated?","choices":["Equity price risk","Customer credit risk","Interest rate risk","Liquidity risk"],"correct_index":3,"explanation":"Liquidity risk concerns difficulty meeting financial obligations when due. Valuable assets or positive equity do not ensure that funds are available at the required date."},{"id":"cr-s7-level1-v1-q3","session":"7","level":1,"topic":"Variable rate exposure","question":"A loan's interest payments increase whenever its reference market rate rises. Which risk does the borrower face from this feature?","choices":["Interest rate risk","Counterparty credit risk","Equity price risk","Foreign currency risk"],"correct_index":0,"explanation":"The borrower's cash payments vary with market interest rates. This is interest rate risk, a type of market risk. It does not require a default or a foreign-currency exposure."},{"id":"cr-s7-level1-v1-q4","session":"7","level":1,"topic":"Foreign currency risk","question":"A company uses the euro as its functional currency but owes a fixed US-dollar amount. The euro weakens, so more euros are needed to pay the debt. Which risk caused this change?","choices":["Credit risk","Foreign currency risk","Equity price risk","Interest rate risk"],"correct_index":1,"explanation":"Currency risk arises because a foreign-currency amount changes in value when expressed in the functional currency. The dollar obligation can stay fixed while its euro settlement cost increases."},{"id":"cr-s7-level1-v1-q5","session":"7","level":1,"topic":"Forward looking recognition","question":"A performing loan is subject to IFRS 9's general expected credit loss model. Credit risk has not increased significantly since initial recognition, but expected losses are measurable. Does the absence of default justify no allowance?","choices":["Yes, an allowance starts only after a loss event.","Yes, an allowance starts only after significant deterioration.","No, a 12-month expected credit loss allowance is required.","No, every performing loan always requires lifetime losses."],"correct_index":2,"explanation":"Under the general model, Stage 1 already carries 12-month expected credit losses. The model is forward-looking and does not wait for default. Significant credit deterioration changes the measurement horizon, not the first existence of an allowance."},{"id":"cr-s7-level1-v1-q6","session":"7","level":1,"topic":"Stage2 without default","question":"Since initial recognition a loan's credit risk has increased significantly, but it is not credit-impaired. It is subject to the general IFRS 9 impairment model with no exception. What loss allowance is required?","choices":["12-month losses because no default has occurred","Lifetime losses with interest automatically on the net balance","12-month losses plus a separate reserve outside the allowance","Lifetime expected credit losses despite the absence of default"],"correct_index":3,"explanation":"A significant increase in credit risk moves an ordinary loan to Stage 2, which uses lifetime expected credit losses. It need not already be credit-impaired. Interest normally remains based on the gross carrying amount at this stage."},{"id":"cr-s7-level1-v1-q7","session":"7","level":1,"topic":"Stage3 interest base","question":"A loan is credit-impaired in Stage 3 of the general IFRS 9 model. It was not purchased or originated credit-impaired. Gross carrying amount is €10 million, loss allowance €3 million and effective rate 5%. What balance is normally used to calculate interest?","choices":["The €7 million net carrying amount","The €10 million gross carrying amount","The €3 million allowance alone","The original principal without the allowance"],"correct_index":0,"explanation":"For this Stage 3 loan, calculate interest on amortised cost net of the allowance: €10m − €3m = €7m. At 5%, that gives €0.35m on unchanged balances. Purchased or originated credit-impaired assets have separate requirements."},{"id":"cr-s7-level1-v1-q8","session":"7","level":1,"topic":"Disclosure versus measurement","question":"A company measures its loans correctly but omits material information about credit exposures and how it manages those risks. Why is the carrying amount alone insufficient?","choices":["IFRS 7 removes the need to recognise the loans.","IFRS 7 also requires disclosures about significance and financial risks.","Risk disclosures become optional if loans are measured correctly.","A generic risk statement always replaces exposure information."],"correct_index":1,"explanation":"Recognition, measurement and disclosure serve different purposes. IFRS 7 requires information enabling users to assess financial instruments' significance and the nature and extent of related risks. One correct balance does not explain all material exposures."},{"id":"cr-s7-level1-v1-q9","session":"7","level":1,"topic":"Simple expected loss","question":"For a simplified one-year loan, exposure at default is €20 million, probability of default 2% and loss given default 40%. Calculate expected loss as exposure × default probability × loss rate, ignoring discounting. What is the allowance?","choices":["€0.4 million","€8 million","€0.16 million","€0.008 million"],"correct_index":2,"explanation":"Expected loss = €20m × 0.02 × 0.40 = €0.16m, or €160,000. Default probability and loss severity are separate fractions. This is the simplified model specified here, not a replacement for a full probability-weighted cash-shortfall assessment."},{"id":"cr-s7-level1-v1-q10","session":"7","level":1,"topic":"Market disclosure scope","question":"A company has material currency, interest rate and listed-equity price exposures. It does not use a qualifying integrated risk model. What market-risk sensitivity information should it provide under IFRS 7?","choices":["Currency and interest sensitivities only, with equity carrying amounts instead of sensitivity","One interest-rate sensitivity applied to all three exposures","Sensitivities using the same percentage change for every risk variable","Sensitivities for each material market-risk type using changes reasonably possible for that variable"],"correct_index":3,"explanation":"Currency rates, interest rates and equity prices are different risk variables. Relevant sensitivity analysis covers each material type using reasonably possible changes. The same percentage is not required for every variable, and carrying amount alone does not replace price sensitivity."},{"id":"cr-s7-level2-v1-q1","session":"7","level":2,"topic":"Allowance increase","question":"A loan has a gross carrying amount of €50 million and opening loss allowance of €0.5 million. At year-end significant deterioration requires a €2 million lifetime loss allowance. There are no write-offs or other movements. What are current impairment expense and closing net carrying amount?","choices":["Expense €2m and net €48m","Expense €1.5m and net €49.5m","Expense €0.5m and net €50m","Expense €1.5m and net €48m"],"correct_index":3,"explanation":"Expense is the allowance increase: €2m − €0.5m = €1.5m. Closing net loan = €50m − €2m = €48m. Do not confuse the closing allowance with this year's expense."},{"id":"cr-s7-level2-v1-q2","session":"7","level":2,"topic":"Stage comparison interest","question":"Two loans each have €100 million gross carrying amount and a 6% effective rate. Loan A is in Stage 2 with an €8 million allowance and is not credit-impaired. Loan B is in Stage 3 with a €25 million allowance and was not purchased or originated credit-impaired. For unchanged balances, what annual interest income is recognised?","choices":["A €6m and B €4.5m","A €5.52m and B €6m","A €6m and B €6m","A €5.52m and B €4.5m"],"correct_index":0,"explanation":"Stage 2 interest is on gross amount: €100m × 6% = €6m. Stage 3 interest is on net amount: (€100m − €25m) × 6% = €4.5m. Both use lifetime loss allowances, but that does not make their interest bases identical."},{"id":"cr-s7-level2-v1-q3","session":"7","level":2,"topic":"Scenario weighted loss","question":"A receivable has three mutually exclusive outcomes: 70% probability of no shortfall, 20% probability of a €3 million shortfall and 10% probability of an €8 million shortfall. The amounts are already present values. What probability-weighted expected credit loss results?","choices":["€3 million","€1.4 million","€8 million","€0.8 million"],"correct_index":1,"explanation":"Weight all outcomes: 0.70 × nil + 0.20 × €3m + 0.10 × €8m = €1.4m. Neither the most likely no-loss outcome nor the worst outcome alone is the expected amount."},{"id":"cr-s7-level2-v1-q4","session":"7","level":2,"topic":"Time value of loss","question":"An expected cash shortfall is €2.42 million in two years. Probability weighting is already included. For this simplified calculation use a 10% annual discount rate. What is its present value?","choices":["€2.42 million","€2.2 million","€2 million","€2.9282 million"],"correct_index":2,"explanation":"Present value = €2.42m ÷ 1.10² = €2m. Discount rather than compound forward. Do not apply another probability adjustment because the amount is already an expected shortfall."},{"id":"cr-s7-level2-v1-q5","session":"7","level":2,"topic":"Liquidity bucket gap","question":"A company has €12 million accessible cash and €8 million of committed facilities available for drawing. Financial liabilities require €25 million payments in the next three months. There are no operating receipts, asset sales or other funding sources in that period. What funding shortfall remains?","choices":["€13 million","€17 million","No shortfall because undrawn facilities are not cash","€5 million"],"correct_index":3,"explanation":"Available funding is €12m + €8m = €20m. Payments of €25m leave a €5m shortfall. The available facility supplies liquidity capacity, although it is not already recognised as cash."},{"id":"cr-s7-level2-v1-q6","session":"7","level":2,"topic":"Concentration comparison","question":"Lender A has €100 million exposure to one borrower. Lender B has €100 million spread equally across 100 independent borrowers with similar individual default risk. What difference should credit-risk information explain?","choices":["A is more concentrated in one borrower despite equal total exposure.","B has a larger gross exposure because it has more borrowers.","The two portfolios have identical concentration because totals match.","B is more concentrated because more borrowers could default."],"correct_index":0,"explanation":"The same gross exposure can conceal very different concentrations. A single borrower's default directly affects all of A's exposure. B has dispersed single-name exposure on the stated independence assumptions. That is not a claim that all portfolio risks disappear."},{"id":"cr-s7-level2-v1-q7","session":"7","level":2,"topic":"Interest sensitivity","question":"A company has €80 million variable-rate debt and €30 million variable-rate cash investments. A one-percentage-point increase affects both for a full year. Ignore hedges, taxes and compounding. What is the net annual profit effect?","choices":["A €0.8m decrease","A €0.5m decrease","A €0.3m increase","A €1.1m decrease"],"correct_index":1,"explanation":"Debt interest increases €80m × 1% = €0.8m. Investment income increases €30m × 1% = €0.3m. Net profit falls €0.8m − €0.3m = €0.5m. Considering debt alone would miss the offsetting asset exposure."},{"id":"cr-s7-level2-v1-q8","session":"7","level":2,"topic":"Currency sensitivity","question":"A euro-functional-currency company holds dollar monetary assets worth €40 million and dollar monetary liabilities worth €55 million at the initial exchange rate. A stronger dollar increases both euro values by 10%. Ignore hedges and tax. What is the net exchange effect on profit?","choices":["A €4m gain","A €5.5m loss","A €1.5m loss","A €9.5m loss"],"correct_index":2,"explanation":"Assets gain €40m × 10% = €4m. Liabilities create a €55m × 10% = €5.5m loss. Net loss = €1.5m, equivalent to 10% of the €15m net dollar liability. Do not treat both gross movements as losses."},{"id":"cr-s7-level2-v1-q9","session":"7","level":2,"topic":"Allowance with write off","question":"Opening loss allowance is €4 million. Current impairment expense adds €2 million. A €1.5 million loan balance is written off entirely against the allowance. There are no recoveries or other movements. What is the closing allowance?","choices":["€6 million","€7.5 million","€2.5 million","€4.5 million"],"correct_index":3,"explanation":"Allowance = €4m + €2m expense − €1.5m write-off = €4.5m. A write-off covered by the allowance reduces both gross loans and the allowance. It does not automatically create another expense at that date."},{"id":"cr-s7-level2-v1-q10","session":"7","level":2,"topic":"12 month horizon interpretation","question":"A four-year loan is in Stage 1 of the general IFRS 9 model. A default in the next 12 months could cause cash shortfalls that continue into later years. What does 12-month expected credit loss include?","choices":["Lifetime shortfalls resulting from defaults possible in the next 12 months","Only payments falling due in the next 12 months","Losses from defaults possible at any time in the four years","Only losses from defaults that already occurred"],"correct_index":0,"explanation":"The 12-month horizon identifies possible default events, not the final date of their cash consequences. Include the resulting lifetime shortfalls from those defaults. Stage 2 instead considers default events over the remaining life."},{"id":"cr-s7-level3-v1-q1","session":"7","level":3,"topic":"Portfolio migration allowance","question":"A €200 million loan portfolio has an opening allowance of €2 million. At year-end, €120 million is in Stage 1 with a 1% 12-month loss rate, €60 million in Stage 2 with a 5% lifetime loss rate, and €20 million in Stage 3 with a 30% lifetime loss rate. Apply each rate directly to its group. With no write-offs or other movements, what closing allowance and current impairment expense result?","choices":["Allowance €10.2m and expense €8.2m","Allowance €10.2m and expense €10.2m","Allowance €4m and expense €2m","Allowance €8.2m and expense €6.2m"],"correct_index":0,"explanation":"The group allowances are €120m × 1% = €1.2m, €60m × 5% = €3m and €20m × 30% = €6m. Total allowance = €10.2m. Current expense is the increase over opening allowance: €10.2m − €2m = €8.2m. The rates already reflect the appropriate horizon for each stage."},{"id":"cr-s7-level3-v1-q2","session":"7","level":3,"topic":"Stage migration and interest base","question":"At the start of a year, an ordinary loan becomes credit-impaired. It was not purchased or originated credit-impaired. Gross carrying amount is €80 million, allowance €20 million and effective rate 5%. For a simplified annual calculation, assume these balances stay unchanged. What interest income is recognised, and how much would a gross-balance calculation overstate it?","choices":["Interest €4m with no overstatement","Interest €3m with a €1m overstatement","Interest €1m with a €3m overstatement","Interest €3m with a €4m overstatement"],"correct_index":1,"explanation":"The net interest base is €80m − €20m = €60m. Income is €60m × 5% = €3m. Using gross amount would give €4m, an overstatement of €1m. This question fixes balances to isolate the Stage 3 interest rule."},{"id":"cr-s7-level3-v1-q3","session":"7","level":3,"topic":"Scenario ECL with discount","question":"A loan has three mutually exclusive outcomes: 60% probability of no shortfall, 30% probability of a €4.4 million shortfall in one year and 10% probability of a €12.1 million shortfall in two years. Discount at 10% annually. What probability-weighted present value loss results?","choices":["€2.53 million","€1.4 million","€2.2 million","€6.2 million"],"correct_index":2,"explanation":"Discount the nonzero shortfalls: €4.4m ÷ 1.10 = €4m and €12.1m ÷ 1.10² = €10m. Then weight them: 30% × €4m + 10% × €10m = €2.2m. Weighting undiscounted amounts would give €2.53m and omit time value."},{"id":"cr-s7-level3-v1-q4","session":"7","level":3,"topic":"Credit loss versus liquidity stress","question":"A company has €10 million cash and €90 million loans collectible in two years with negligible expected credit losses. Its own €50 million debt matures in three months. It cannot refinance, sell the loans or obtain other cash before then. What conclusion follows?","choices":["There is no gap because loan collections exceed debt.","The funding gap is €50m because cash is excluded.","The company has an €80m near-term funding surplus.","Low expected credit losses coexist with a €40m near-term funding gap."],"correct_index":3,"explanation":"The loans may be highly recoverable but their cash arrives too late. Near-term cash of €10m against debt of €50m leaves €40m unfunded. Credit risk concerns collection, while liquidity risk concerns meeting payments when due."},{"id":"cr-s7-level3-v1-q5","session":"7","level":3,"topic":"Combined market sensitivities","question":"A company has €120 million variable-rate debt and €40 million variable-rate deposits. A 1.5-percentage-point rise affects both for a full year. Separately, a 10% dollar strengthening increases the euro value of its €20 million net dollar monetary liabilities. Assume additive effects, no hedges and no tax. What is the total profit reduction?","choices":["€3.2 million","€3.8 million","€2 million","€0.8 million"],"correct_index":0,"explanation":"Net extra interest cost = (€120m − €40m) × 1.5% = €1.2m. Exchange loss = €20m × 10% = €2m. Total reduction = €3.2m. The deposit interest offsets part of debt interest, not the currency loss."},{"id":"cr-s7-level3-v1-q6","session":"7","level":3,"topic":"Allowance bridge and net assets","question":"Opening gross loans are €100 million with a €5 million loss allowance. During the year the lender advances €10 million, collects €6 million principal and writes off €2 million against the allowance. It recognises €3 million impairment expense. No other movements occur. What are closing gross loans, allowance and net loans?","choices":["Gross €104m, allowance €8m, net €96m","Gross €102m, allowance €6m, net €96m","Gross €102m, allowance €8m, net €94m","Gross €104m, allowance €6m, net €98m"],"correct_index":1,"explanation":"Gross loans = €100m + €10m − €6m − €2m = €102m. Allowance = €5m + €3m − €2m = €6m. Net loans = €96m. A covered write-off reduces both gross loans and allowance, so it does not create a second net loss at write-off."},{"id":"cr-s7-level3-v1-q7","session":"7","level":3,"topic":"Lifetime default horizon","question":"For a simplified two-year loan, default probability is 2% in year 1 and 3% for surviving year 1 then defaulting in year 2. These are unconditional, mutually exclusive probabilities. Exposure is €100 million and loss given default 40% throughout. Ignore discounting. What are Stage 1 12-month ECL and Stage 2 lifetime ECL?","choices":["Stage 1 €2m and Stage 2 €2m","Stage 1 €0.8m and Stage 2 €1.2m","Stage 1 €0.8m and Stage 2 €2m","Stage 1 €0.02m and Stage 2 €0.05m"],"correct_index":2,"explanation":"Stage 1 uses default events in year 1: €100m × 2% × 40% = €0.8m. Lifetime losses include both disjoint default events: €100m × (2% + 3%) × 40% = €2m. The 3% is already unconditional, so do not multiply it by survival again."},{"id":"cr-s7-level3-v1-q8","session":"7","level":3,"topic":"Risk change versus loan growth","question":"A lender's gross loans grow from €100 million to €200 million and its allowance rises from €1 million to €2 million. Portfolio mix and expected loss rate remain unchanged at 1%. With no other effects, what explains the allowance increase?","choices":["The increase proves borrowers deteriorated.","The loss rate fell to 0.5%.","No expense arises because the percentage stayed unchanged.","More exposure requires more allowance at the same loss rate."],"correct_index":3,"explanation":"The allowance is 1% of loans at both dates. Doubling exposure therefore doubles the allowance without evidence of worse credit quality. A constant percentage does not prevent expense when the exposure base grows."},{"id":"cr-s7-level3-v1-q9","session":"7","level":3,"topic":"Liquidity commitments and sensitivity limits","question":"A company has €300 million positive net assets and only a small interest-rate sensitivity. It must pay €70 million next month but has only €45 million accessible cash and committed facilities, with no other inflows or funding. What must an assessment of financial risks still address?","choices":["A €25m funding gap despite positive net assets and low rate sensitivity","No gap because positive net assets cover maturities","A €70m gap because available facilities must be ignored","A €45m surplus because available funding is itself the surplus"],"correct_index":0,"explanation":"The shortfall is €70m − €45m = €25m. Net assets indicate neither cash timing nor funding availability. Interest-rate sensitivity addresses market risk, not the capacity to settle next month's obligations."},{"id":"cr-s7-level3-v1-q10","session":"7","level":3,"topic":"Meaningful ECL disclosure","question":"Two lenders each report €500 million gross loans and €15 million allowance. One mainly holds Stage 1 loans, the other mainly loans with significant deterioration and lifetime losses. Collateral and borrower concentrations also differ. Do equal totals establish equivalent credit risk?","choices":["Yes, a common 3% allowance proves equivalent risk distributions.","No, equal totals may conceal different stages, collateral and concentrations.","Yes, matching gross loans and allowances replace all stage information.","No, because Stage 1 loans can never have an allowance."],"correct_index":1,"explanation":"An aggregate allowance is a summary estimate, not a complete description of risk. Stages, collateral, concentrations, assumptions and allowance movements can differ behind identical totals. Stage 1 still has an allowance under the general model."}],"8":[{"id":"cr-s8-level1-v1-q1","session":"8","level":1,"topic":"Long term is not automatic FVOCI","question":"A company buys ordinary shares for long-term investment. The holding qualifies for the IFRS 9 equity FVOCI election, but the company makes no election at initial recognition. With no scope exception, what measurement category applies?","choices":["FVOCI automatically because the investment is long-term","Amortised cost because dividends are expected","Fair value through profit or loss","Cost less impairment until disposal"],"correct_index":2,"explanation":"FVTPL is the default for equity investments within IFRS 9. An eligible non-trading holding uses equity FVOCI only if the irrevocable election is actually made at initial recognition. Long-term intent alone is not that election."},{"id":"cr-s8-level1-v1-q2","session":"8","level":1,"topic":"Trading instrument cannot elect","question":"An investor buys ordinary shares for short-term trading. It wants to elect equity FVOCI so that price losses do not reduce profit. Is the election available?","choices":["Yes, because shares have no maturity date.","Yes, because the trading model is documented.","Yes, if the election reduces reported volatility.","No, shares held for trading are ineligible for that election."],"correct_index":3,"explanation":"The equity FVOCI election is limited to eligible non-trading equity instruments. Management cannot use a preference about earnings volatility to remove the trading restriction. The holding remains at FVTPL."},{"id":"cr-s8-level1-v1-q3","session":"8","level":1,"topic":"Timing of election","question":"An eligible non-trading share investment was initially recognised at FVTPL with no FVOCI election. Its price then falls. Can management make the equity FVOCI election at year-end for that same holding to keep the loss out of profit?","choices":["No, the election must be made at initial recognition.","Yes, while the shares remain unsold.","Yes, if the loss is material.","No, unless management now promises to hold it longer."],"correct_index":0,"explanation":"The equity FVOCI election is made at initial recognition and is irrevocable. Management cannot wait to observe gains or losses before choosing their presentation. A later change in intended holding period does not create the initial election."},{"id":"cr-s8-level1-v1-q4","session":"8","level":1,"topic":"Instrument by instrument","question":"A company buys two separate eligible non-trading share investments on the same date. Can it elect equity FVOCI for one and leave the other at FVTPL?","choices":["No, one election must cover the whole portfolio.","Yes, the initial election is instrument by instrument.","No, purchases on the same day form one classification unit.","Yes, and it may reverse either election at every year-end."],"correct_index":1,"explanation":"The election is instrument-specific and made at initial recognition. Separate eligible holdings need not have the same election. Instrument-specific choice does not mean the choice remains reversible afterwards."},{"id":"cr-s8-level1-v1-q5","session":"8","level":1,"topic":"Measurement versus location","question":"An equity investment validly designated FVOCI falls in fair value from €100 million to €80 million. There are no dividends, fees or taxes. Does the election prevent recognition of the €20 million fall?","choices":["Yes, no loss is recognised before sale.","Yes, the asset remains at cost and fair value is only disclosed.","No, the loss is recognised in other comprehensive income.","No, the loss is recognised in profit then reversed out of OCI."],"correct_index":2,"explanation":"The asset is still measured at fair value. Its €20m decrease is recognised in OCI rather than profit. FVOCI changes the location of the value change, not its existence or the closing €80m asset."},{"id":"cr-s8-level1-v1-q6","session":"8","level":1,"topic":"Ordinary dividends","question":"An equity FVOCI holding pays an ordinary €3 million dividend that is not clearly a recovery of investment cost. Where is the dividend generally recognised?","choices":["In OCI with all fair-value movements","As a reduction of the investment cost","Only on disposal when total return is known","In profit or loss as dividend income"],"correct_index":3,"explanation":"Ordinary dividend income generally enters profit even when changes in the share price go to OCI. The election does not move every investment-related item to OCI. A clear recovery of cost is a different fact pattern."},{"id":"cr-s8-level1-v1-q7","session":"8","level":1,"topic":"No equity recycling","question":"A company sells an equity FVOCI investment with a €10 million accumulated fair-value gain in OCI. How much of that accumulated gain is recycled into profit solely because of the sale?","choices":["Nil","A €10m gain","A €10m loss","The gain less past dividends"],"correct_index":0,"explanation":"Accumulated fair-value gains on elected equity FVOCI investments are not recycled to profit on disposal. A transfer between equity reserves is permitted, but it is not profit. This differs from debt FVOCI."},{"id":"cr-s8-level1-v1-q8","session":"8","level":1,"topic":"No separate equity ECL","question":"An equity investment designated FVOCI falls in fair value. Which treatment applies to that decline under IFRS 9?","choices":["Full fair-value loss in OCI plus a separate ECL expense","Fair-value loss in OCI without a separate ECL allowance","Lifetime ECL in profit with the remaining loss deferred","Credit-related loss in profit and all other price loss in OCI"],"correct_index":1,"explanation":"For elected equity FVOCI, recognise the fair-value movement in OCI without a separate expected credit loss layer. Debt impairment staging is not applied to this equity holding. The loss is still recognised through the fair-value measurement."},{"id":"cr-s8-level1-v1-q9","session":"8","level":1,"topic":"FVTPL first year result","question":"An FVTPL share investment is bought for €100 million, closes the year at €85 million fair value and pays €4 million ordinary dividends. Ignore fees and taxes. What is its profit contribution?","choices":["A €15m loss","A €4m gain","An €11m loss","Nil profit with an €11m OCI loss"],"correct_index":2,"explanation":"Profit includes the €15m fair-value loss and €4m dividend income, giving an €11m net loss. The loss does not wait for sale. Both items enter profit for this FVTPL holding."},{"id":"cr-s8-level1-v1-q10","session":"8","level":1,"topic":"FVOCI first year result","question":"An equity FVOCI investment starts at €100 million and closes at €85 million. It pays €4 million ordinary dividends that are not a cost recovery. With no fees or taxes, what are its profit, OCI and total comprehensive income contributions?","choices":["Profit loss €11m, OCI nil, total loss €11m","Profit €4m, OCI nil, total income €4m","Profit nil, OCI loss €11m, total loss €11m","Profit €4m, OCI loss €15m, total loss €11m"],"correct_index":3,"explanation":"Dividends of €4m enter profit. The €15m price decrease enters OCI. Total comprehensive income is €4m − €15m = an €11m loss. The election splits the result between profit and OCI without changing that total."},{"id":"cr-s8-level2-v1-q1","session":"8","level":2,"topic":"Sale after prior fall FVTPL","question":"An FVTPL share investment cost €100 million and was measured at €80 million at the end of year 1. It is sold for €90 million in year 2. There are no year 2 dividends, fees or taxes. What is year 2 profit from the investment?","choices":["A €10m loss","A €20m gain","Nil","A €10m gain"],"correct_index":3,"explanation":"Year 2 compares €90m proceeds with the €80m opening carrying amount, giving a €10m gain. The €20m fall from original cost was already recognised in year 1. Lifetime loss remains €10m, but it is not the current-year result."},{"id":"cr-s8-level2-v1-q2","session":"8","level":2,"topic":"Sale after prior fall equity FVOCI","question":"An equity FVOCI holding cost €100 million, closed year 1 at €80 million and is sold for €90 million in year 2. There are no year 2 dividends, fees or taxes. What are year 2 profit and OCI contributions?","choices":["Profit nil and OCI gain €10m, without recycling the cumulative loss","Profit loss €10m and OCI gain €20m, recycling the cumulative loss","Profit gain €10m and OCI nil","Profit loss €20m and OCI gain €10m"],"correct_index":0,"explanation":"The current value increase is €90m − €80m = €10m in OCI. The cumulative €10m loss from cost is not recycled into profit when the elected equity holding is sold. It may instead be transferred within equity."},{"id":"cr-s8-level2-v1-q3","session":"8","level":2,"topic":"Two year total economic result","question":"A share investment costs €120 million, pays ordinary dividends of €5 million in year 1 and €3 million in year 2, then is sold for €110 million. There are no fees or taxes. What is its lifetime total comprehensive result under either FVTPL or a valid equity FVOCI election?","choices":["A €10m loss","A €2m loss","An €8m gain","A €12m loss"],"correct_index":1,"explanation":"Total return is €5m + €3m + €110m − €120m = a €2m loss. FVTPL and equity FVOCI put price changes in different performance categories, but on these facts the lifetime total comprehensive result is the same."},{"id":"cr-s8-level2-v1-q4","session":"8","level":2,"topic":"Mixed portfolio current profit","question":"A company has an FVTPL share investment with a current €8 million price gain and an equity FVOCI investment with a current €6 million price loss. Each pays €2 million ordinary dividends. Ignore fees and taxes. What combined profit, OCI and total comprehensive income result?","choices":["Profit €6m, OCI nil, total €6m","Profit €10m, OCI loss €6m, total €4m","Profit €12m, OCI loss €6m, total €6m","Profit €4m, OCI gain €2m, total €6m"],"correct_index":2,"explanation":"Profit includes the €8m FVTPL price gain and both €2m dividends: €12m. The €6m FVOCI price loss enters OCI. Combined total comprehensive income is €12m − €6m = €6m."},{"id":"cr-s8-level2-v1-q5","session":"8","level":2,"topic":"Dividend and value transfer","question":"A share investment is worth €50 million immediately before an ordinary €5 million dividend. Immediately after payment it is worth €45 million. There are no other changes, fees or taxes. What total comprehensive result does the holder recognise over that interval?","choices":["A €5m gain","A €5m loss","A €10m loss","Nil"],"correct_index":3,"explanation":"Cash dividend income of €5m offsets the €5m decrease in the investment's value. Combined return is nil. FVTPL or equity FVOCI changes the location of the price movement, not the sum of dividend and price effects."},{"id":"cr-s8-level2-v1-q6","session":"8","level":2,"topic":"Commission at FVTPL","question":"An FVTPL share investment is purchased for €100 million plus €2 million broker commission. It closes at €108 million fair value and pays €3 million ordinary dividends. Ignore taxes. What are current profit and closing investment amount?","choices":["Profit €9m and asset €108m","Profit €11m and asset €108m","Profit €9m and asset €110m","Profit €3m and asset €102m"],"correct_index":0,"explanation":"The FVTPL asset starts at €100m and its €2m transaction cost is expensed. Profit is €8m fair-value gain + €3m dividends − €2m commission = €9m. The closing investment is measured at €108m fair value."},{"id":"cr-s8-level2-v1-q7","session":"8","level":2,"topic":"Nontrading election costs","question":"A share investment validly elected to fair value through other comprehensive income is bought for €100 million plus €2 million transaction costs directly related to the purchase. It closes at €108 million fair value and pays €3 million ordinary dividends. Ignore tax. What are current profit and OCI contributions?","choices":["Profit €9m and OCI nil","Profit €3m and OCI gain €6m","Profit €1m and OCI gain €8m","Profit €3m and OCI gain €8m"],"correct_index":1,"explanation":"Initial carrying amount includes the transaction costs: €102m. Remeasurement to €108m gives a €6m OCI gain. Ordinary dividends give €3m profit. Total comprehensive income of €9m equals final investment plus dividend less the €102m outlay."},{"id":"cr-s8-level2-v1-q8","session":"8","level":2,"topic":"Net income reconciliation","question":"Before investment effects a company earns €20 million operating profit. Its FVTPL share portfolio pays €4 million dividends and has a €30 million unrealised fair-value loss. Ignore tax and other items. What does the total result show?","choices":["Profit €24m because unrealised losses are omitted","Loss €10m because dividends are omitted","Loss €6m despite a positive €20m operating component","Loss €6m proving the operating business itself lost €30m"],"correct_index":2,"explanation":"Total profit is €20m + €4m − €30m = a €6m loss. A negative bottom line can coexist with profitable operations. Explaining the components does not remove the recognised investment loss from total profit."},{"id":"cr-s8-level2-v1-q9","session":"8","level":2,"topic":"Berkshire presentation distinction","question":"An investor agrees with the current fair values of a share portfolio but argues that its price movements obscure the industrial business's operating performance when included in net income. What is the main accounting issue in this objection?","choices":["Whether the portfolio's fair value is measured correctly","Whether the investments should be recognised as assets","When share purchases and sales should be recorded","Where value movements are presented in performance measures"],"correct_index":3,"explanation":"The objection accepts valuation but questions the location and interpretation of fair-value changes in performance reporting. This is a presentation issue. It is not necessarily a rejection of fair value or a claim that investment losses have no economic effect."},{"id":"cr-s8-level2-v1-q10","session":"8","level":2,"topic":"Disposal transfer within equity","question":"After selling an equity FVOCI investment, a company transfers its €12 million accumulated OCI gain to retained earnings within equity. What is the effect of this reserve transfer alone?","choices":["No profit effect and no change in total equity","Profit and total equity each increase €12m","Profit falls €12m and total equity stays unchanged","Profit is unchanged but total equity increases €12m"],"correct_index":0,"explanation":"Moving €12m between equity components changes neither profit nor total equity. It is not recycling through profit. The sale's cash and derecognition entries are separate from this internal reserve transfer."},{"id":"cr-s8-level3-v1-q1","session":"8","level":3,"topic":"Two year FVTPL with costs","question":"At the start of year 1 an investor buys FVTPL shares for €200 million plus €4 million transaction costs. Dividends are €6 million in year 1 and €5 million in year 2. Year 1 closing fair value is €150 million, and the shares sell for €180 million at the end of year 2. Ignore tax and other costs. What are year 1, year 2 and cumulative profit contributions?","choices":["Year 1 loss €48m, year 2 gain €35m, cumulative loss €13m","Year 1 loss €44m, year 2 gain €35m, cumulative loss €9m","Year 1 loss €48m, year 2 loss €15m, cumulative loss €63m","Year 1 loss €50m, year 2 gain €30m, cumulative loss €20m"],"correct_index":0,"explanation":"Year 1 profit = €6m dividend − €50m price loss − €4m costs = −€48m. Year 2 profit = €5m dividend + (€180m − €150m) = €35m. Combined loss is €13m. Check lifetime cash: €180m + €11m dividends − €204m outlay = −€13m."},{"id":"cr-s8-level3-v1-q2","session":"8","level":3,"topic":"Two year equity FVOCI with costs","question":"An eligible share investment is elected FVOCI and bought for €200 million plus €4 million transaction costs directly related to the purchase at the start of year 1. Dividends are €6 million in year 1 and €5 million in year 2. It closes year 1 at €150 million and sells at year 2 end for €180 million. Ignore tax. Before any internal reserve transfer, what are cumulative profit, OCI and total comprehensive result?","choices":["Profit loss €13m, OCI nil, total loss €13m","Profit €11m, OCI loss €24m, total loss €13m","Profit €11m, OCI loss €20m, total loss €9m","Profit loss €24m, OCI gain €11m, total loss €13m"],"correct_index":1,"explanation":"Initial amount is €204m including the transaction costs. OCI is −€54m in year 1 and +€30m in year 2, totalling −€24m. Ordinary dividends total €11m in profit. Total comprehensive result is −€13m. The cumulative equity FVOCI loss is not recycled on sale."},{"id":"cr-s8-level3-v1-q3","session":"8","level":3,"topic":"Classification does not change wealth","question":"Two investors each buy identical eligible shares for €100 million. One makes a valid equity FVOCI election, the other uses FVTPL. Each receives €4 million ordinary dividends and closes at €70 million fair value. Ignore fees and tax. Which comparison is correct?","choices":["Both lose €26m, but FVOCI leaves its asset at cost.","Both report a €26m profit loss and a €70m asset.","Both have a €26m comprehensive loss and a €70m asset, but profit differs by €30m.","Both have €70m assets, but FVOCI leaves total equity €30m higher."],"correct_index":2,"explanation":"FVTPL profit = €4m − €30m = −€26m. FVOCI profit is €4m and OCI is −€30m, giving the same −€26m total. Both assets close at €70m. The election changes the profit/OCI split, not total wealth on these assumptions."},{"id":"cr-s8-level3-v1-q4","session":"8","level":3,"topic":"Mixed election three instruments","question":"Three share holdings have these current results: A is FVTPL with a €12 million price gain and €2 million dividend. B is valid equity FVOCI with a €9 million price loss and €3 million ordinary dividend. C is held for trading with a €4 million price loss and €1 million dividend. Ignore fees and tax. What are combined profit, OCI and total comprehensive income?","choices":["Profit €5m, OCI nil, total €5m","Profit €18m, OCI loss €13m, total €5m","Profit €11m, OCI loss €9m, total €2m","Profit €14m, OCI loss €9m, total €5m"],"correct_index":3,"explanation":"A contributes €14m profit. B contributes €3m profit and −€9m OCI. Trading holding C contributes −€3m profit. Total profit = €14m + €3m − €3m = €14m. Total comprehensive income is €5m after the OCI loss. C cannot elect its trading loss into equity FVOCI."},{"id":"cr-s8-level3-v1-q5","session":"8","level":3,"topic":"Partial disposal equity FVOCI","question":"An equity FVOCI holding costs €100 million with no fees. At year-end its total fair value is €140 million. The investor immediately sells half for €70 million. There are no dividends, taxes or further value changes. What investment remains, and what profit arises solely from the sale?","choices":["A €70m asset and nil disposal profit","A €50m asset and €20m disposal profit","A €70m asset and €20m disposal profit","A €100m asset and €70m disposal profit"],"correct_index":0,"explanation":"First remeasure the full holding to €140m through OCI. Selling half removes €70m of the asset for €70m cash, leaving a €70m investment. The related accumulated OCI gain is not recycled into profit on the partial disposal."},{"id":"cr-s8-level3-v1-q6","session":"8","level":3,"topic":"Operating profit adjustment credibility","question":"A company reports an €18 million total loss after an FVTPL share-price loss of €40 million and ordinary dividend income of €2 million. There is no tax or other investment effect. An analyst removes both investment items to isolate profit before investment effects. What amount results, and how should it be interpreted?","choices":["€24m, with both investment items removed","€20m, a reconciled component rather than a replacement for total profit","€22m, excluding both investment effects","A €58m loss, after removing the price loss"],"correct_index":1,"explanation":"Start with −€18m, add back the €40m loss and deduct the €2m dividend: adjusted profit is €20m. This explains the component before investment effects. It does not erase the reported total loss, and its definition and reconciliation must remain clear."},{"id":"cr-s8-level3-v1-q7","session":"8","level":3,"topic":"Loss reversal without recycling","question":"An equity FVOCI investment costs €100 million. It closes year 1 at €60 million, year 2 at €90 million and sells at year 3 end for €105 million. There are no dividends, fees or taxes. What are year 3 OCI and lifetime profit effects?","choices":["Year 3 profit gain €5m and OCI gain €10m","Year 3 OCI gain €45m and lifetime profit €5m","Year 3 OCI gain €15m and lifetime profit nil","Year 3 profit gain €15m and cumulative OCI loss €10m"],"correct_index":2,"explanation":"Year 3 value change is €105m − €90m = €15m in OCI. Lifetime OCI is −€40m + €30m + €15m = €5m. No accumulated equity FVOCI gain is recycled to profit at sale, so lifetime profit from these facts remains nil."},{"id":"cr-s8-level3-v1-q8","session":"8","level":3,"topic":"Year2 dividends and realised loss","question":"An FVTPL share investment costs €100 million and is remeasured to €130 million at year 1 end. In year 2 it pays €4 million ordinary dividends and sells for €110 million. Ignore fees and tax. What are year 2 and cumulative profit contributions?","choices":["Year 2 gain €14m and cumulative gain €44m","Year 2 loss €20m and cumulative gain €10m","Year 2 gain €4m and cumulative gain €34m","Year 2 loss €16m and cumulative gain €14m"],"correct_index":3,"explanation":"Year 2 price result is €110m − €130m = −€20m. Add €4m dividend for a €16m current loss. With year 1's €30m gain, lifetime profit is €14m. That equals total cash €114m less €100m purchase cost."},{"id":"cr-s8-level3-v1-q9","session":"8","level":3,"topic":"Own equity versus investment shares","question":"A company buys another company's ordinary shares for €10 million for trading and repurchases its own ordinary shares for €8 million. Both quoted prices then rise 20%. There are no disposals, dividends, fees or taxes. What profit and own-share treatment follow?","choices":["Profit gain €2m, while own shares remain an €8m equity deduction","Profit gain €3.6m, with own shares shown as a €9.6m asset","Profit nil because both changes bypass profit","Profit gain €1.6m from remeasuring own shares only"],"correct_index":0,"explanation":"The external trading investment is an FVTPL asset, so its 20% gain is €2m in profit. Repurchased own equity is deducted from equity under IAS 32. It is not an investment asset and is not remeasured to produce profit from the issuer's own price rise."},{"id":"cr-s8-level3-v1-q10","session":"8","level":3,"topic":"Separate debt and equity OCI disposal","question":"On disposal, a debt FVOCI bond has a €7 million accumulated OCI gain and a separate elected equity FVOCI investment has a €9 million accumulated OCI gain. The debt gain is required to be recycled. There are no further value changes or other items. What profit arises from recycling?","choices":["A €16m gain from both reserves","A €7m gain from the debt reserve only","A €9m gain from the equity reserve only","Nil because both reserves stay outside profit"],"correct_index":1,"explanation":"The €7m debt FVOCI reserve is reclassified into profit on derecognition as stated. The €9m elected equity FVOCI reserve is not recycled into profit. Both involve OCI during holding, but they do not have the same disposal rule."}],"9":[{"id":"cr-s9-level1-v1-q1","session":"9","level":1,"topic":"Discount and freight","question":"A machine has a €12 million invoice price before a €2 million trade discount. Delivery to the required location costs €0.5 million and necessary installation €0.8 million. There are no other costs or taxes. What is its initial cost under IAS 16?","choices":["€13.3 million","€10 million","€11.3 million","€10.8 million"],"correct_index":2,"explanation":"Start with the actual purchase price after discount: €12m − €2m = €10m. Add delivery €0.5m and installation €0.8m because they bring the machine to its required location and condition. Total cost is €11.3m."},{"id":"cr-s9-level1-v1-q2","session":"9","level":1,"topic":"Nonrefundable tax","question":"A company buys equipment for €10 million and pays €1 million non-refundable purchase tax plus €2 million fully recoverable tax. There are no other costs. What is initial equipment cost?","choices":["€13 million","€10 million","€12 million","€11 million"],"correct_index":3,"explanation":"Cost includes the €10m price and €1m non-refundable tax, totalling €11m. Recoverable tax is not an equipment cost because the company can recover it separately. The cash invoice total is therefore not necessarily the asset cost."},{"id":"cr-s9-level1-v1-q3","session":"9","level":1,"topic":"Training is not asset readiness","question":"A machine is already capable of operating as management intends. The company pays €0.4 million to train its operators. How should it account for the training?","choices":["Expense the training as the service is received.","Include it in the machine's initial cost.","Recognise a separate workforce intangible asset.","Deduct it from accumulated depreciation."],"correct_index":0,"explanation":"Training prepares staff, not the machine's location and physical operating condition. IAS 16 does not include staff training in the machine's cost. Paying before commercial production begins does not by itself make an outlay capitalisable."},{"id":"cr-s9-level1-v1-q4","session":"9","level":1,"topic":"Capable versus full capacity","question":"A machine is capable of operating as intended, but weak initial demand causes operating losses before it reaches full capacity. What is the treatment of those losses?","choices":["Capitalise them until full capacity is reached.","Expense them in the periods in which they arise.","Capitalise them until the first profitable month.","Deduct them from accumulated depreciation."],"correct_index":1,"explanation":"Initial asset preparation ends when the machine is capable of operating as intended. It does not continue until demand, output or profit reaches a target. Operating losses after readiness are period expenses."},{"id":"cr-s9-level1-v1-q5","session":"9","level":1,"topic":"Environmental enabling equipment","question":"A factory must install €3 million pollution-control equipment to continue operating legally. The equipment enables future benefits from the existing factory, and its cost is reliably measurable. Can it qualify as property, plant and equipment without generating separate revenue?","choices":["No, every item must earn independent revenue.","No, compliance equipment can only be expensed.","Yes, enabling benefits from other assets can support recognition.","Yes, but it must be classified as an intangible right."],"correct_index":2,"explanation":"Economic benefits need not be an independent revenue stream from the item itself. The equipment allows the factory to continue earning benefits and meets the stated recognition conditions. It remains tangible equipment, not an intangible merely because regulation requires it."},{"id":"cr-s9-level1-v1-q6","session":"9","level":1,"topic":"Dismantling initial estimate","question":"A machine costs €10 million. Installation also creates a qualifying dismantling obligation with an initial present value of €2 million. No other amounts apply. What initial asset and liability are recognised?","choices":["Machine €10m, provision €2m and immediate expense €2m","Machine €8m and provision €2m","Machine €12m and no provision","Machine €12m and provision €2m"],"correct_index":3,"explanation":"Add the qualifying initial dismantling estimate to asset cost: €10m + €2m = €12m. Recognise the corresponding €2m provision. The obligation can be recognised before settlement cash is paid."},{"id":"cr-s9-level1-v1-q7","session":"9","level":1,"topic":"Routine service contract","question":"A supplier's invoice contains €9 million for a machine and €1 million for a separately priced routine maintenance contract covering the next year. The service is not installation or testing. What is the machine's initial cost?","choices":["€9 million","€10 million","€11 million","€8 million"],"correct_index":0,"explanation":"The machine costs €9m. The future routine service is a separate service item, not part of bringing the machine to working condition. If paid in advance, it is accounted for as a prepayment and expensed as service is received."},{"id":"cr-s9-level1-v1-q8","session":"9","level":1,"topic":"Component lives","question":"A €30 million machine includes a significant replaceable component with a five-year useful life. The rest lasts fifteen years. There are no residual values. How should depreciation reflect the component?","choices":["Depreciate it over fifteen years with the whole machine.","Depreciate the significant component separately over its own useful life.","Use one average life without separate depreciation.","Wait until replacement to expense the component."],"correct_index":1,"explanation":"IAS 16 requires significant parts to be depreciated separately. The five-year component and fifteen-year remainder have different benefit-consumption periods. One physical machine can therefore require more than one depreciation calculation."},{"id":"cr-s9-level1-v1-q9","session":"9","level":1,"topic":"Qualifying asset threshold","question":"A company buys a finished machine ready for immediate use and separately builds a complex plant that necessarily takes two years to prepare. On these facts, which meets IAS 23's substantial-preparation-time criterion for a qualifying asset?","choices":["Both, because both are expensive.","Neither, because preparation must exceed the operating cycle.","The two-year plant, not the immediately usable machine.","The finished machine, because purchase finance alone qualifies."],"correct_index":2,"explanation":"A qualifying asset necessarily takes a substantial period to get ready for intended use or sale. The two-year plant meets that stated condition. A high price or long useful life does not make a ready-to-use machine a qualifying asset."},{"id":"cr-s9-level1-v1-q10","session":"9","level":1,"topic":"Specific loan simple interest","question":"A qualifying construction project is funded by a specific €10 million loan at 6% for a full year. All interest relates to an eligible active construction period, with no temporary investment income or other adjustment. What borrowing cost is capitalised?","choices":["€0.06 million","€0.3 million","€0.9 million","€0.6 million"],"correct_index":3,"explanation":"Eligible interest is €10m × 6% = €0.6m. The question establishes both a qualifying asset and an eligible capitalisation period. Without those conditions, borrowing interest would not become asset cost simply because a loan exists."},{"id":"cr-s9-level2-v1-q1","session":"9","level":2,"topic":"Cost bundle exclusions","question":"A machine lists at €20 million with a €2 million trade discount. The buyer also pays €1 million non-refundable import duty, €0.5 million freight to the site and €1.5 million installation. Staff training costs €0.4 million and operating losses before the machine reaches full capacity are €0.6 million. What initial machine cost is recognised?","choices":["€22 million","€23 million","€19.5 million","€21 million"],"correct_index":3,"explanation":"Net price is €18m. Add the import duty €1m, freight €0.5m and installation €1.5m, the costs of bringing the machine to the location and condition needed for use, to obtain €21m. Staff training and the initial operating losses are expensed. An outlay's proximity to opening does not establish capitalisation."},{"id":"cr-s9-level2-v1-q2","session":"9","level":2,"topic":"Asset ready part year","question":"A €24 million machine is available for intended use for the final nine months of the year. Its straight-line life is eight years with zero residual value. With no other changes, what are current depreciation and closing carrying amount?","choices":["Depreciation €2.25m and carrying amount €21.75m","Depreciation €3m and carrying amount €21m","No depreciation and carrying amount €24m until full capacity","Depreciation €0.75m and carrying amount €23.25m"],"correct_index":0,"explanation":"Annual charge is €24m ÷ 8 = €3m. Nine months gives €3m × 9/12 = €2.25m, leaving €21.75m. Depreciation starts when available for intended use, not when the machine reaches full output."},{"id":"cr-s9-level2-v1-q3","session":"9","level":2,"topic":"Weighted general borrowing rate","question":"General borrowings stay unchanged all year: €10 million at 4% and €20 million at 7%. No other general debt exists. What weighted annual capitalisation rate applies to eligible expenditure financed from this pool?","choices":["5.5%","6%","7%","11%"],"correct_index":1,"explanation":"Annual interest is €10m × 4% + €20m × 7% = €1.8m. Divide by €30m total borrowings to get 6%. A simple average of 4% and 7% ignores that the 7% debt balance is twice as large."},{"id":"cr-s9-level2-v1-q4","session":"9","level":2,"topic":"General expenditure timing","question":"A qualifying project incurs €12 million eligible expenditure outstanding for nine months and a further €8 million outstanding for three months. Both use general borrowings at a 6% weighted rate. Construction is eligible throughout and the actual-interest cap does not bind. How much borrowing cost is capitalised?","choices":["€1.2 million","€0.9 million","€0.66 million","€0.4 million"],"correct_index":2,"explanation":"Time-weighted expenditure is €12m × 9/12 + €8m × 3/12 = €11m. Apply 6% to obtain €0.66m. The year-end expenditure total cannot be treated as outstanding for the whole year."},{"id":"cr-s9-level2-v1-q5","session":"9","level":2,"topic":"Specific loan eligible period","question":"A specific €20 million construction loan at 9% remains outstanding all year. Only eight months are an eligible capitalisation period for its qualifying asset. There is no investment income or other eligible use. What interest is capitalised and expensed?","choices":["Capitalise €1.8m and expense nil","Capitalise €0.6m and expense €1.2m","Capitalise nil and expense €1.8m","Capitalise €1.2m and expense €0.6m"],"correct_index":3,"explanation":"Annual interest is €20m × 9% = €1.8m. Eligible eight-month interest is €1.8m × 8/12 = €1.2m. The remaining €0.6m is a period expense on the stated facts."},{"id":"cr-s9-level2-v1-q6","session":"9","level":2,"topic":"Two component depreciation","question":"A €30 million machine comprises a €6 million significant component lasting three years and a €24 million body lasting twelve years. Both are available throughout the year, have zero residuals and use straight-line depreciation. What is the annual charge?","choices":["€4 million","€2.5 million","€10 million","€3 million"],"correct_index":0,"explanation":"Component depreciation is €6m ÷ 3 = €2m. Body depreciation is €24m ÷ 12 = €2m. Total is €4m. Applying only the body's life to the full machine would ignore the component's faster consumption."},{"id":"cr-s9-level2-v1-q7","session":"9","level":2,"topic":"Present value restoration","question":"A plant purchase costs €50 million and creates a qualifying restoration obligation requiring €12.1 million payment in two years. Use a 10% annual discount rate and ignore tax and other costs. What initial plant and provision amounts are recognised?","choices":["Plant €62.1m and provision €12.1m","Plant €60m and provision €10m","Plant €50m and provision €10m","Plant €40m and provision €10m"],"correct_index":1,"explanation":"Initial provision is present value: €12.1m ÷ 1.10² = €10m. Add it to the €50m plant purchase for a €60m asset. The future undiscounted payment is not the initial provision when discounting is material."},{"id":"cr-s9-level2-v1-q8","session":"9","level":2,"topic":"Abnormal construction waste","question":"A company constructs a machine using €10 million of materials consumed in normal production and €4 million direct construction labour. During construction an accidental spill ruins €2 million of additional materials, and €1 million is spent on head-office administration. No other costs arise. What machine cost is capitalised?","choices":["€17 million","€16 million","€14 million","€15 million"],"correct_index":2,"explanation":"Normal materials and directly attributable labour total €14m. The accidental spill is abnormal waste and the head-office administration is not needed to bring the machine to the location and condition for its intended operation, so both are expensed. Their occurrence during construction does not make them costs of the asset."},{"id":"cr-s9-level2-v1-q9","session":"9","level":2,"topic":"Initial spares separation","question":"A €15 million invoice includes equipment €12 million, delivery €0.4 million, necessary installation €0.6 million, servicing for the first two years of operation €1 million and small consumable spares €1 million. What is equipment cost?","choices":["€15 million","€14 million","€12 million","€13 million"],"correct_index":3,"explanation":"Equipment cost is €12m + €0.4m + €0.6m = €13m. The servicing covers periods after the equipment is ready for use, and small consumable spares are supplies rather than components of the machine, so both have their own accounting. Being bundled into one invoice does not turn them into equipment cost."},{"id":"cr-s9-level2-v1-q10","session":"9","level":2,"topic":"Stop capitalisation at readiness","question":"A qualifying plant becomes substantially ready for intended operation after ten months. Its specific €12 million loan at 6% stays outstanding for the whole year. There is no investment income or other qualifying use. What borrowing cost is capitalised and expensed?","choices":["Capitalise €0.6m and expense €0.12m","Capitalise €0.72m and expense nil","Capitalise €0.12m and expense €0.6m","Capitalise nil and expense €0.72m"],"correct_index":0,"explanation":"Full-year interest is €12m × 6% = €0.72m. Ten eligible months give €0.6m capitalised, with €0.12m expensed afterwards. Continuing to borrow, or choosing to leave a ready plant idle, does not extend preparation."},{"id":"cr-s9-level3-v1-q1","session":"9","level":3,"topic":"Integrated machine acquisition","question":"A machine lists at €40 million with a €4 million trade discount. The buyer also pays €2 million non-refundable import duty, €1 million transport to the site and €3 million installation, and the installation creates a dismantling obligation with an initial present value of €5 million. Separately it pays €6 million recoverable purchase tax, €1 million staff training and €2 million servicing of the machine's first year of operation, and it incurs €3 million operating losses before full capacity. What initial machine cost and dismantling provision are recognised?","choices":["Machine €47m and provision €5m","Machine €59m and provision €5m","Machine €42m and no provision before payment","Machine €52m and provision €5m"],"correct_index":0,"explanation":"Net price is €36m. Add the import duty, transport, installation and initial dismantling estimate: €36m + €2m + €1m + €3m + €5m = €47m cost, and recognise the matching €5m provision. The recoverable tax is refunded, and the training, first-year servicing and initial operating losses are not costs of bringing the machine to the condition needed for use. The dismantling estimate enters the cost once, not twice."},{"id":"cr-s9-level3-v1-q2","session":"9","level":3,"topic":"Weighted debt and timed spend","question":"General debt outstanding all year is €20 million at 5% and €30 million at 8%. A qualifying project incurs €10 million eligible expenditure outstanding all year and €20 million outstanding for six months. There is no specific debt, construction stays eligible, and the actual-interest cap does not bind. What interest is capitalised?","choices":["€1.98 million","€1.36 million","€1.3 million","€3.4 million"],"correct_index":1,"explanation":"Pool interest is €1m + €2.4m = €3.4m on €50m debt, giving 6.8%. Weighted expenditure is €10m + €20m × 6/12 = €20m. Capitalised interest is €20m × 6.8% = €1.36m, not a full-year charge on all closing expenditure."},{"id":"cr-s9-level3-v1-q3","session":"9","level":3,"topic":"Capitalisation cap","question":"For a project financed by general borrowings, the time-weighted qualifying-expenditure calculation gives €1.5 million potential borrowing cost. Actual borrowing costs incurred on the entire relevant general pool are only €1.2 million, and no other borrowing costs exist. Applying IAS 23's actual-cost cap, what is capitalised?","choices":["€1.5 million","€2.7 million","€1.2 million","€0.3 million"],"correct_index":2,"explanation":"The capitalised amount cannot exceed borrowing costs incurred during the period. Limit the €1.5m formula result to €1.2m actual cost. The calculation allocates real borrowing cost to an asset, not creates additional expense or a new liability."},{"id":"cr-s9-level3-v1-q4","session":"9","level":3,"topic":"Specific funds temporary income","question":"A specific construction borrowing incurs €1.6 million interest while construction of the asset is under way. Unused proceeds are temporarily invested during the same period and earn €0.2 million. With no other adjustments, what borrowing cost is capitalised under IAS 23?","choices":["€1.6 million","€1.8 million","€0.2 million","€1.4 million"],"correct_index":3,"explanation":"Under IAS 23, income from temporarily investing unused specific borrowings is deducted from the borrowing costs that can be capitalised: €1.6m − €0.2m = €1.4m. The income reduces, rather than increases, the capitalised amount."},{"id":"cr-s9-level3-v1-q5","session":"9","level":3,"topic":"Construction cost plus borrowing","question":"A company builds a plant for its own use. Direct construction costs are €30 million, staff training for operating the plant costs €2 million, and an accident during construction wastes €1 million of materials. The work is financed by a specific loan on which €1.8 million interest accrues during construction, and temporarily investing the unused proceeds earns €0.3 million. Building the plant creates a restoration obligation with a present value of €4 million. What initial plant cost results?","choices":["€35.5 million","€38.5 million","€35.8 million","€31.5 million"],"correct_index":0,"explanation":"Capitalised borrowing cost is €1.8m − €0.3m = €1.5m after deducting the temporary investment income. Add the direct construction costs €30m and the restoration estimate €4m to reach €35.5m. Staff training and the accidental waste are expensed even though they arise during the project, because they are not necessary to bring the plant to the condition intended."},{"id":"cr-s9-level3-v1-q6","session":"9","level":3,"topic":"Ready date and depreciation","question":"A plant's €48 million cost already includes all eligible borrowing costs up to readiness. It is available for intended use for the final three months of the year, but production is postponed until next year. Straight-line life is twelve years with zero residual. What depreciation and closing amount are recognised?","choices":["No depreciation and carrying amount €48m","Depreciation €1m and carrying amount €47m","Depreciation €4m and carrying amount €44m","Depreciation €3m and carrying amount €45m"],"correct_index":1,"explanation":"Annual depreciation is €48m ÷ 12 = €4m. Three months gives €1m, leaving €47m. Availability for intended use starts depreciation even if management delays production. Later financing cost is not added just because production has not begun."},{"id":"cr-s9-level3-v1-q7","session":"9","level":3,"topic":"Components plus half year","question":"A €60 million machine contains a €48 million body with twelve-year life and a significant €12 million component with four-year life. Both become available for the last six months of the year, have zero residuals and use straight-line depreciation. What are current depreciation and closing total carrying amount?","choices":["Depreciation €2.5m and carrying amount €57.5m","Depreciation €7m and carrying amount €53m","Depreciation €3.5m and carrying amount €56.5m","Depreciation €1.5m and carrying amount €58.5m"],"correct_index":2,"explanation":"Full-year body charge is €48m ÷ 12 = €4m and component charge €12m ÷ 4 = €3m. Six months of the €7m combined annual charge is €3.5m. Deduct it from €60m for a €56.5m closing amount."},{"id":"cr-s9-level3-v1-q8","session":"9","level":3,"topic":"Nonrefundable taxes and residual","question":"A machine lists at €20 million before a €2 million discount. Non-refundable tax is €1 million and necessary installation €3 million. Recoverable tax is €4 million. It is ready for the full year, has a €2 million residual value and a five-year straight-line life. What is first-year depreciation?","choices":["€4.4 million","€4.8 million","€3.6 million","€4 million"],"correct_index":3,"explanation":"Initial cost = €20m − €2m + €1m + €3m = €22m. Exclude recoverable tax. Depreciable amount = €22m − €2m residual = €20m, so annual depreciation is €4m. Residual value reduces the depreciation base, not initial recognised cost."},{"id":"cr-s9-level3-v1-q9","session":"9","level":3,"topic":"Readiness cost versus later loss","question":"Net purchase and eligible preparation costs of a machine total €25 million. After readiness it incurs €2 million operating losses, and business reorganisation costs €1 million. A qualifying initial dismantling obligation has present value €3 million. With no borrowing costs, what asset cost and non-capitalised period costs result?","choices":["Asset €28m and period costs €3m","Asset €31m and period costs nil","Asset €25m and period costs €6m","Asset €30m and period costs €1m"],"correct_index":0,"explanation":"Add the €3m initial dismantling estimate to €25m eligible purchase and preparation for €28m asset cost. Expense €2m post-readiness losses and €1m reorganisation. The provision's later settlement date does not remove its qualifying initial cost."},{"id":"cr-s9-level3-v1-q10","session":"9","level":3,"topic":"General rate excludes specific pool","question":"A company has a €10 million specific project loan at 9% and separate general borrowings of €20 million at 4% and €20 million at 6%. A second project uses only the general pool, with €12 million weighted eligible expenditure. The specific loan is excluded from that pool and the cap does not bind. What interest is capitalised on the second project?","choices":["€0.696 million","€0.6 million","€1.08 million","€0.48 million"],"correct_index":1,"explanation":"General pool rate = (€20m × 4% + €20m × 6%) ÷ €40m = 5%. Apply it to €12m for €0.6m. Including the separate specific loan would wrongly give 5.8% and €0.696m for this project."}],"10":[{"id":"cr-s10-level1-v1-q1","session":"10","level":1,"topic":"Cost model carrying amount","question":"A machine uses IAS 16's cost model. Original cost is €30 million, accumulated depreciation €9 million and accumulated impairment losses €2 million. What is its carrying amount?","choices":["€21 million","€28 million","€19 million","€30 million"],"correct_index":2,"explanation":"Cost-model carrying amount is cost less accumulated depreciation and impairment: €30m − €9m − €2m = €19m. Both deductions matter. A known market price does not automatically replace this basis."},{"id":"cr-s10-level1-v1-q2","session":"10","level":1,"topic":"Straight line residual","question":"A machine costs €24 million, has a €4 million residual value and a five-year useful life. It is available for a full year and depreciated straight-line. What is the annual charge?","choices":["€4.8 million","€5.6 million","€20 million","€4 million"],"correct_index":3,"explanation":"Depreciable amount is €24m − €4m = €20m. Allocate it over five years for €4m annually. The residual is the amount not expected to be consumed through use."},{"id":"cr-s10-level1-v1-q3","session":"10","level":1,"topic":"Diminishing balance second year","question":"A €20 million machine uses 30% diminishing-balance depreciation. It has zero residual and is held for two full years with no other adjustments. What is year 2 depreciation?","choices":["€4.2 million","€6 million","€14 million","€1.8 million"],"correct_index":0,"explanation":"Year 1 depreciation is €20m × 30% = €6m, leaving €14m. Apply 30% to that reduced balance in year 2: €4.2m. Applying the rate to original cost again would not be diminishing balance."},{"id":"cr-s10-level1-v1-q4","session":"10","level":1,"topic":"Units of production","question":"A machine costs €12 million, has a €2 million residual value and is expected to produce five million units over its life. It produces one million units this year and uses units-of-production depreciation. What is the charge?","choices":["€2.4 million","€2 million","€10 million","€1 million"],"correct_index":1,"explanation":"Depreciable amount is €10m. Divide by five million expected units to obtain €2 per unit, then multiply by one million current units for €2m. Deduct residual value before allocating consumption."},{"id":"cr-s10-level1-v1-q5","session":"10","level":1,"topic":"Land and building separation","question":"A €50 million property purchase is allocated €20 million to land with unlimited useful life and €30 million to a building with thirty-year life and zero residual. Under the cost model and straight-line depreciation for a full year, what charge results?","choices":["€50m ÷ 30 for the combined property","Nil because the purchase includes land","€1m on the building and no charge on the unlimited-life land","€20m on land plus €1m on the building"],"correct_index":2,"explanation":"Account for land and building separately. The building charge is €30m ÷ 30 = €1m. The stated unlimited-life land is not depreciated. Combining both costs under the building's life would depreciate land incorrectly."},{"id":"cr-s10-level1-v1-q6","session":"10","level":1,"topic":"Routine repair","question":"Ordinary maintenance keeps a machine in its existing working condition. The service is fully received this period and does not replace a qualifying component. How is its cost treated?","choices":["Capitalise it as a replacement component.","Deduct it from accumulated depreciation.","Prepay it over the machine's remaining life.","Recognise current maintenance expense."],"correct_index":3,"explanation":"Routine servicing is expensed in the period of service. Keeping the machine operational does not by itself create a new qualifying asset cost. The service is already consumed, so no prepayment remains."},{"id":"cr-s10-level1-v1-q7","session":"10","level":1,"topic":"Class wide revaluation","question":"A company adopts the IAS 16 revaluation model for a class of similar machines but wants to update only machines whose prices rose. What prevents this approach?","choices":["The model applies to the whole class, not selected favourable assets.","A note listing selected machines is sufficient.","Price falls may stay at cost while rises are recognised.","Management can select any existing assets while applying the model only to new purchases."],"correct_index":0,"explanation":"The revaluation policy applies to the entire relevant PPE class, with valuations sufficiently regular to avoid materially stale amounts. It cannot be used simply to recognise winners while ignoring similar assets with declines."},{"id":"cr-s10-level1-v1-q8","session":"10","level":1,"topic":"First upward revaluation","question":"IAS 16 land is carried at €40 million and revalued to €48 million for the first time. There is no earlier revaluation deficit in profit, no tax and no other change. Where is the €8 million increase recognised?","choices":["As an €8m profit gain","In OCI and accumulated in revaluation surplus","Directly in retained earnings without OCI","Nowhere until disposal"],"correct_index":1,"explanation":"An upward IAS 16 revaluation goes through OCI to revaluation surplus unless it reverses a prior decrease recognised in profit for that asset. None exists here. This is different from the IAS 40 fair-value model."},{"id":"cr-s10-level1-v1-q9","session":"10","level":1,"topic":"Investment property purpose","question":"A company owns one building rented to unrelated tenants for rental income and appreciation, and another used entirely as its own headquarters. There are no special arrangements. Which standards normally apply?","choices":["Both IAS 40 because both may appreciate","Both IAS 16 because both are owned","Rental property IAS 40 and headquarters IAS 16","Rental property IAS 16 and headquarters IAS 40"],"correct_index":2,"explanation":"IAS 40 concerns property held for rentals or capital appreciation. Owner-occupied administrative property is PPE under IAS 16. Ownership alone does not decide between them, and possible appreciation does not turn every operating building into investment property."},{"id":"cr-s10-level1-v1-q10","session":"10","level":1,"topic":"IAS40 fair value depreciation","question":"An investment property correctly uses IAS 40's fair-value model. Its fair value rises from €60 million to €66 million this year. Exclude rents, costs and tax. What measurement effect is recognised?","choices":["€6m OCI gain plus normal depreciation","No gain before sale, with depreciation","€6m profit gain plus cost-based depreciation","€6m profit gain without depreciation under this model"],"correct_index":3,"explanation":"IAS 40 fair-value changes enter profit or loss. The investment property is not depreciated under that model. IAS 16 revaluation differs because it retains depreciation and normally puts an unreversed upward surplus in OCI."},{"id":"cr-s10-level2-v1-q1","session":"10","level":2,"topic":"Replacement component","question":"A machine has an €18 million carrying amount including an old €2 million component. The old part is removed without proceeds and replaced with a qualifying €5 million component. Ignore depreciation during replacement. What are the new carrying amount and derecognition loss?","choices":["Asset €23m and loss nil","Asset €16m and loss €5m","Asset €21m and loss €5m","Asset €21m and loss €2m"],"correct_index":3,"explanation":"Remove the old component and add the new: €18m − €2m + €5m = €21m. The old €2m carrying amount is a derecognition loss. Retaining it would count both removed and replacement components in the asset."},{"id":"cr-s10-level2-v1-q2","session":"10","level":2,"topic":"Major inspection replacement","question":"An aircraft carries at €50 million including €3 million remaining from its previous major inspection. A new required inspection costs €8 million and meets capitalisation criteria. With no proceeds or other changes, what is the immediate revised aircraft carrying amount?","choices":["€55 million","€58 million","€47 million","€61 million"],"correct_index":0,"explanation":"Derecognise the old inspection balance and recognise the qualifying new cost: €50m − €3m + €8m = €55m. Capitalising the new inspection does not justify keeping the old one in the asset."},{"id":"cr-s10-level2-v1-q3","session":"10","level":2,"topic":"Revaluation deficit reserve","question":"Land carrying amount is €70 million with an existing €10 million revaluation surplus for that same land. Its new value is €55 million. Ignore tax and other changes. How is the €15 million decrease presented?","choices":["€15m expense in profit with no reserve change","€10m OCI decrease against surplus and €5m expense in profit","€15m OCI decrease, creating a negative surplus","€5m OCI decrease and €10m expense in profit"],"correct_index":1,"explanation":"Use the existing €10m asset-specific surplus first through OCI. The excess €5m is a profit expense. Surplus on unrelated assets cannot be treated as a general pool that absorbs any revaluation loss."},{"id":"cr-s10-level2-v1-q4","session":"10","level":2,"topic":"Upward reversal of prior deficit","question":"Land is carried at €45 million after an earlier €10 million revaluation decrease recognised in profit. It is now revalued to €60 million, with no other movements or tax. How is the €15 million increase allocated?","choices":["€15m OCI and no profit","€15m profit and no OCI","€10m profit reversing the earlier deficit and €5m OCI surplus","€5m profit and €10m OCI surplus"],"correct_index":2,"explanation":"The increase reverses the prior profit-recognised deficit up to €10m. Recognise that part in profit and the remaining €5m in OCI. The rule is not that every upward revaluation bypasses profit regardless of history."},{"id":"cr-s10-level2-v1-q5","session":"10","level":2,"topic":"Depreciation after revaluation","question":"At the start of a year a building is revalued to €36 million. Remaining useful life is twelve years, residual value zero, and straight-line depreciation continues. With no other adjustment, what annual charge is required?","choices":["Nil","€1.5 million","€4 million","€3 million"],"correct_index":3,"explanation":"Use the revised depreciable amount over remaining life: €36m ÷ 12 = €3m. An IAS 16 revaluation changes the depreciation base. It does not stop depreciation on a finite-life building."},{"id":"cr-s10-level2-v1-q6","session":"10","level":2,"topic":"IAS40 cost model","question":"An IAS 40 investment property uses the cost model. Cost is €40 million, accumulated depreciation €8 million and impairment nil. Fair value is €50 million. What carrying amount is recognised under the stated model?","choices":["€32 million","€50 million","€40 million","€42 million"],"correct_index":0,"explanation":"Cost-model carrying amount is €40m − €8m = €32m. A fair value that may be disclosed does not replace the recognised amount under this model. IAS 40's cost model still uses depreciation and impairment."},{"id":"cr-s10-level2-v1-q7","session":"10","level":2,"topic":"Revaluation surplus then depreciation","question":"A machine starts at €20 million with four years remaining life and zero residual. At the start of the year it is revalued to €28 million with no prior deficit. It then has a full year of straight-line depreciation. Ignore tax and reserve transfers. What are OCI, depreciation and closing asset?","choices":["OCI gain €8m, depreciation €5m, asset €23m","OCI gain €8m, depreciation €7m, asset €21m","Profit gain €8m, depreciation €7m, asset €21m","OCI gain €8m, depreciation nil, asset €28m"],"correct_index":1,"explanation":"The €8m uplift enters OCI. Revised annual depreciation is €28m ÷ 4 = €7m, leaving €21m. The uplift bypassing profit does not mean that depreciation on the revalued amount also bypasses profit."},{"id":"cr-s10-level2-v1-q8","session":"10","level":2,"topic":"Reserve transfer on use","question":"A revalued asset has €6 million annual depreciation rather than the €4 million charge on historical cost. The company makes a permitted €2 million transfer from revaluation surplus to retained earnings within equity. What additional profit effect does that transfer create?","choices":["A €2m profit gain reversing excess depreciation","A further €2m profit expense","None, it is a transfer between equity components","A new €2m OCI gain"],"correct_index":2,"explanation":"The full €6m depreciation remains recognised in performance. A direct equity transfer is not income and does not reverse depreciation. It reallocates existing equity between surplus and retained earnings without changing total equity."},{"id":"cr-s10-level2-v1-q9","session":"10","level":2,"topic":"Partial year replacement depreciation","question":"A new separately depreciated component costs €12 million and becomes available for use halfway through the year. Its useful life is six years and residual value zero. Ignore the old component and other costs. What straight-line charge applies this year?","choices":["€2 million","€6 million","Nil until a complete year passes","€1 million"],"correct_index":3,"explanation":"Full-year depreciation is €12m ÷ 6 = €2m. Half a year of availability gives €1m. Recognition of a new component does not remove the need to match depreciation to when it becomes available."},{"id":"cr-s10-level2-v1-q10","session":"10","level":2,"topic":"Fair value versus rental income","question":"An IAS 40 fair-value investment property opens at €80 million and closes at €75 million. It earns €6 million net rental income. There are no purchases, disposals or tax effects. What is its current profit contribution?","choices":["€1m profit","€6m profit because the price fall is OCI","€5m loss because rent is omitted","€11m loss because rent is an expense"],"correct_index":0,"explanation":"Net rental income is €6m and the fair-value loss is €5m. Both enter profit, giving €1m net income. No additional depreciation is charged under the fair-value model."},{"id":"cr-s10-level3-v1-q1","session":"10","level":3,"topic":"Two year revaluation sequence","question":"A machine starts year 1 at €100 million with five years remaining life and zero residual. Straight-line depreciation is followed by year-end revaluation to €90 million in year 1 and €60 million in year 2. Year 2 starts with four years remaining. There are no earlier reserves, taxes or reserve transfers. What are year 2 depreciation, revaluation OCI decrease and revaluation profit expense?","choices":["Depreciation €22.5m, OCI decrease €7.5m, profit revaluation expense nil","Depreciation €20m, OCI decrease €10m, profit expense nil","Depreciation €22.5m, OCI decrease €10m, profit expense €2.5m","Depreciation €22.5m, OCI nil, profit expense €7.5m"],"correct_index":0,"explanation":"Year 1 depreciation of €20m leaves €80m, then revaluation to €90m creates €10m surplus. Year 2 depreciation is €90m ÷ 4 = €22.5m, leaving €67.5m. The €7.5m fall to €60m fits entirely within that asset's €10m surplus, leaving €2.5m and no revaluation expense in profit."},{"id":"cr-s10-level3-v1-q2","session":"10","level":3,"topic":"Three year reserve exhaustion","question":"A machine begins year 1 at €100 million with five years remaining life and zero residual. Straight-line depreciation precedes each year-end revaluation: €90 million after year 1, €60 million after year 2 and €35 million after year 3. Remaining life is four years at year 2 start and three years at year 3 start. No earlier reserves, taxes or reserve transfers exist. What are year 3 depreciation, OCI decrease and revaluation profit expense?","choices":["Depreciation €20m, OCI decrease €5m, profit expense nil","Depreciation €20m, OCI decrease €2.5m, profit expense €2.5m","Depreciation €22.5m, OCI nil, profit expense €2.5m","Depreciation €20m, OCI nil, profit expense €5m"],"correct_index":1,"explanation":"Year 1 produces surplus €90m − (€100m − €20m) = €10m. Year 2 depreciation is €22.5m, then a €7.5m fall to €60m leaves surplus €2.5m. Year 3 depreciation is €60m ÷ 3 = €20m, leaving €40m. The €5m decrease to €35m uses €2.5m surplus through OCI and charges €2.5m to profit."},{"id":"cr-s10-level3-v1-q3","session":"10","level":3,"topic":"Replacement plus ongoing depreciation","question":"A machine's opening €30 million carrying amount includes an old €4 million component. At year start it is removed without proceeds and replaced by a qualifying €10 million component with five-year life. The remaining €26 million machine has thirteen-year life. All residuals are zero and straight-line depreciation applies for the full year. What total expense and closing machine amount result?","choices":["Expense €4m and asset €36m","Expense €6m and asset €34m","Expense €8m and asset €32m","Expense €10m and asset €30m"],"correct_index":2,"explanation":"Derecognising the old component causes a €4m loss. New component depreciation is €10m ÷ 5 = €2m and remainder depreciation €26m ÷ 13 = €2m. Total expense is €8m. Replacement creates a €36m balance before €4m depreciation, so closing asset is €32m."},{"id":"cr-s10-level3-v1-q4","session":"10","level":3,"topic":"Two depreciation methods","question":"Two machines each cost €40 million, have zero residual and are held for two full years. A uses 20% diminishing balance. B uses straight-line depreciation over five years. There are no other changes. What are year 2 depreciation and closing carrying amount for each?","choices":["A charge €8m, asset €24m. B charge €8m, asset €24m.","A charge €6.4m, asset €33.6m. B charge €8m, asset €32m.","A charge €8m, asset €32m. B charge €6.4m, asset €25.6m.","A charge €6.4m, asset €25.6m. B charge €8m, asset €24m."],"correct_index":3,"explanation":"A closes year 1 at €32m, then charges 20% × €32m = €6.4m and closes at €25.6m. B charges €40m ÷ 5 = €8m each year and closes year 2 at €24m. Current depreciation is not the same as cumulative depreciation."},{"id":"cr-s10-level3-v1-q5","session":"10","level":3,"topic":"PPE versus investment property","question":"Two buildings each start the year at €50 million and finish at €55 million fair value. A is owner-occupied under IAS 16 revaluation, with ten-year remaining life and zero residual, revalued after full-year straight-line depreciation. B is IAS 40 fair-value investment property. Ignore rent, prior reserves or deficits, taxes and other changes. What profit and OCI effects arise?","choices":["A profit expense €5m and OCI gain €10m. B profit gain €5m and OCI nil.","Both profit gain €5m and OCI nil.","A profit expense €5m and OCI gain €5m. B profit gain €5m.","A OCI gain €10m without depreciation. B OCI gain €5m without profit."],"correct_index":0,"explanation":"A depreciates by €5m to €45m, then revalues to €55m for a €10m OCI gain. B is not depreciated under IAS 40 fair value and recognises its €5m increase in profit. Both have a €5m comprehensive gain, but their profit and OCI components differ."},{"id":"cr-s10-level3-v1-q6","session":"10","level":3,"topic":"Revaluation upward after loss","question":"Land cost €100 million. In year 1 it was revalued to €80 million, with the €20 million deficit in profit. In year 2 it is revalued to €110 million. There is no depreciation, tax or other change. What are year 2 profit gain and OCI gain, and the cumulative comprehensive result since purchase?","choices":["Profit €30m, OCI nil, cumulative gain €10m","Profit €20m, OCI €10m, cumulative gain €10m","Profit €20m, OCI €10m, cumulative gain €30m","Profit nil, OCI €30m, cumulative gain €10m"],"correct_index":1,"explanation":"Year 2 uplift is €30m. The first €20m reverses the earlier profit deficit, and the remaining €10m goes to OCI. Across both years, −€20m + €20m + €10m = €10m total gain, matching closing €110m less original €100m."},{"id":"cr-s10-level3-v1-q7","session":"10","level":3,"topic":"Remaining useful life estimate","question":"A cost-model machine carries at €36 million. New reasonable information at year start revises its remaining life from six to four years and residual value from nil to €4 million. There is no prior error or revaluation. What current straight-line depreciation and closing balance follow?","choices":["Depreciation €6m and asset €30m using the old life","Depreciation €9m and asset €27m ignoring residual","Depreciation €8m and asset €28m, applied prospectively","Depreciation €8m and asset €28m, with earlier charges restated"],"correct_index":2,"explanation":"The new depreciable amount is €36m − €4m = €32m over four remaining years, giving €8m this year and €28m closing balance. This is a change in estimate based on new information, applied prospectively. Earlier reasonable charges are not restated."},{"id":"cr-s10-level3-v1-q8","session":"10","level":3,"topic":"Proportional gross revaluation","question":"A machine has €100 million gross cost and €40 million accumulated depreciation. It is revalued to €90 million using proportionate restatement of both gross amount and accumulated depreciation. No prior deficit exists. What new gross amount, accumulated depreciation and surplus result?","choices":["Gross €130m, accumulated depreciation €40m, surplus €30m","Gross €90m, accumulated depreciation €40m, surplus €30m","Gross €150m, accumulated depreciation €40m, surplus €50m","Gross €150m, accumulated depreciation €60m, surplus €30m"],"correct_index":3,"explanation":"Old net amount is €60m. The revaluation factor is €90m ÷ €60m = 1.5. Multiply gross €100m and accumulated depreciation €40m by 1.5 to obtain €150m and €60m. New net is €90m and surplus €30m. The stated restatement method determines these gross balances."},{"id":"cr-s10-level3-v1-q9","session":"10","level":3,"topic":"Reserve transfer plus revaluation fall","question":"An asset has €12 million revaluation surplus at period start. After depreciation, the company makes a permitted direct €3 million transfer from that surplus to retained earnings. A later downward revaluation of the same asset is €11 million. Ignore taxes and other movements. How is the decline allocated?","choices":["€9m against surplus through OCI and €2m expense in profit","€11m against surplus because the original reserve was €12m","€12m against surplus and €1m gain in profit","€8m against surplus and €3m expense in profit"],"correct_index":0,"explanation":"The prior transfer leaves €12m − €3m = €9m in the asset's revaluation surplus. Use that €9m through OCI, with the €2m excess decline in profit. The transferred amount is not still available in the surplus to absorb the loss."},{"id":"cr-s10-level3-v1-q10","session":"10","level":3,"topic":"Sale of revalued land","question":"IAS 16 land carries at €120 million with €20 million associated revaluation surplus. It sells for €125 million without selling costs or taxes. The company directly transfers the entire surplus to retained earnings on disposal. What profit gain arises, and what does the internal reserve transfer do to total equity?","choices":["Profit €25m, with no extra total equity from the transfer","Profit €5m, with no total-equity change from the transfer","Profit €20m, plus a further €20m increase in total equity","Profit nil, taking the sale difference to OCI"],"correct_index":1,"explanation":"Disposal gain is €125m proceeds − €120m carrying amount = €5m in profit. The €20m reserve transfer stays within equity and neither enters profit nor increases total equity again. The sale gain and reserve transfer are separate entries."}],"11":[{"id":"cr-s11-level1-v1-q1","session":"11","level":1,"topic":"Contract rights versus separability","question":"A company acquires an enforceable licence that cannot be sold separately. It controls the benefits and meets all other recognition conditions. Does lack of separate transferability necessarily prevent the licence from being identifiable under IAS 38?","choices":["Yes, legal rights and separate sale are both mandatory.","Yes, every non-transferable licence must be included in goodwill.","No, contractual or legal rights can establish identifiability without separability.","No, but every such right must be recorded as a prepaid service."],"correct_index":2,"explanation":"Identifiability has alternative routes: separability, or contractual/legal rights. A right can qualify even if it is not transferable or separable from the company. Meeting this test is distinct from satisfying the other recognition criteria, which are given here."},{"id":"cr-s11-level1-v1-q2","session":"11","level":1,"topic":"Useful life bounded by use","question":"A purchased patent costs €12 million and has ten years of legal protection remaining. The company expects to use it for only six years, with no residual proceeds. What annual straight-line amortisation applies for a full year?","choices":["€1.2 million","Nil until legal expiry","€12 million only in year 10","€2 million"],"correct_index":3,"explanation":"Expected useful life can be shorter than the legal term. The benefit period here is six years, so annual amortisation is €12m ÷ 6 = €2m. Legal protection sets a limit, not an instruction to ignore expected obsolescence or discontinued use."},{"id":"cr-s11-level1-v1-q3","session":"11","level":1,"topic":"Legal life binds expected use","question":"A €15 million licence could be economically useful for eight years, but the non-renewable legal right ends after five years. Residual value is zero. What full-year straight-line amortisation is required?","choices":["€3 million","€1.875 million","Nil because expected benefits exceed the legal term","Immediate €15m expense because the legal term is finite"],"correct_index":0,"explanation":"The company cannot use the right beyond its non-renewable legal term. Useful life is therefore five years, giving €15m ÷ 5 = €3m annually. A finite legal life does not itself require immediate expensing."},{"id":"cr-s11-level1-v1-q4","session":"11","level":1,"topic":"Finite despite unlimited legal life","question":"A separately bought trademark costs €9 million and has no legal expiry. Its product will be discontinued in three years, with no alternative use or residual value. What amortisation treatment fits these facts?","choices":["No amortisation because the legal right has no expiry","Straight-line amortisation of €3m over the three-year benefit period","€1m a year over nine years","Immediate €9m expense because three years is too short"],"correct_index":1,"explanation":"An unlimited legal term does not establish an indefinite economic life. The stated benefit period is only three years, so the finite-life asset is amortised at €9m ÷ 3 = €3m annually. Expected consumption, not the cost amount, determines the period."},{"id":"cr-s11-level1-v1-q5","session":"11","level":1,"topic":"Research and qualifying development","question":"A project incurs €2 million research costs before development-recognition conditions are met. After all IAS 38 conditions are demonstrated, it incurs €5 million development costs. No other amounts arise. What intangible cost is recognised?","choices":["€7 million","€2 million","€5 million","Nil"],"correct_index":2,"explanation":"Capitalisation starts when all development criteria are met, so the asset is €5m. The earlier €2m research remains expense. Later success does not reinstate expenditure already expensed as research."},{"id":"cr-s11-level1-v1-q6","session":"11","level":1,"topic":"Recognition conditions not optional","question":"A development project is technically feasible and management intends to finish it. However, the company cannot demonstrate adequate funding or other resources to complete it. Do the favourable technical facts alone justify capitalisation?","choices":["Yes, resources need only be checked after completion.","Yes, capitalise now and rely on future impairment tests.","No, because only projects with separately invoiced sales qualify.","No, the required completion-resources condition is not demonstrated."],"correct_index":3,"explanation":"All development-recognition conditions must be met, including adequate technical, financial and other resources. Feasibility and intention alone are insufficient. Future cost savings can be benefits, so lack of separate sales is not the issue described here."},{"id":"cr-s11-level1-v1-q7","session":"11","level":1,"topic":"Software and training separation","question":"An internal software project incurs €8 million development expenditure after all IAS 38 recognition criteria are demonstrated, €1 million staff training and €0.5 million of allocated general overhead. What software cost is recognised?","choices":["€8 million","€9.5 million","€9 million","€7.5 million"],"correct_index":0,"explanation":"Recognise only the €8m development costs incurred after all criteria are demonstrated. Staff training and allocated general overhead are expensed, even when incurred close to software completion. A project budget does not turn every related payment into an asset."},{"id":"cr-s11-level1-v1-q8","session":"11","level":1,"topic":"Finite life start of amortisation","question":"A recognised €12 million software asset is available for intended use for the final four months of the year. Useful life is three years, zero residual, straight line. Management has not yet launched it commercially. What current amortisation applies, rounded to three decimals?","choices":["Nil until launch","€1.333 million","€4 million","€3 million"],"correct_index":1,"explanation":"Annual amortisation is €12m ÷ 3 = €4m. Four months gives €4m × 4/12 = €1.333m. Availability for intended use starts amortisation, not a later marketing launch or first profitable sale."},{"id":"cr-s11-level1-v1-q9","session":"11","level":1,"topic":"Indefinite not infinite","question":"An acquired brand meets recognition conditions and has no foreseeable limit to its expected benefit period after a supported analysis. What follows while its useful life remains classified as indefinite?","choices":["No amortisation and impairment testing only after an indicator","Amortise over an arbitrary long finite period","No systematic amortisation, but required impairment testing continues","Expense immediately because a precise end date is unknown"],"correct_index":2,"explanation":"An indefinite useful life means no foreseeable limit, not infinite value or immunity from loss. Such an asset is not amortised but is tested for impairment at least annually and when relevant indicators arise. The life assessment must remain supportable."},{"id":"cr-s11-level1-v1-q10","session":"11","level":1,"topic":"Revaluation needs active market","question":"Management obtains a bespoke valuation for a patent, but there is no active market for the rights. Is that valuation alone enough to use IAS 38's revaluation model?","choices":["Yes, any reliable estimate replaces an active market.","Yes, if an independent valuer updates it annually.","No, so use the estimate as a profit gain instead.","No, the model requires fair value by reference to an active market."],"correct_index":3,"explanation":"IAS 38 revaluation has a restrictive active-market condition, which is uncommon for unique intangible rights. An independent or plausible valuation alone does not establish that condition. It also does not authorise a substitute profit remeasurement."},{"id":"cr-s11-level2-v1-q1","session":"11","level":2,"topic":"Capitalisation cutoff","question":"A development project incurs €12 million this year. All recognition criteria first become demonstrable midway through the year: €5 million was spent before that point and €7 million afterwards. What asset cost and current expense are recognised before amortisation?","choices":["Asset €12m and expense nil","Asset €5m and expense €7m","Asset nil and expense €12m despite later qualification","Asset €7m and expense €5m"],"correct_index":3,"explanation":"Capitalisation begins at the date all criteria are met. The later €7m becomes an asset, while the earlier €5m stays expense. Meeting criteria later does not retrospectively convert all project spending into recognised cost."},{"id":"cr-s11-level2-v1-q2","session":"11","level":2,"topic":"Software amortisation two pieces","question":"Software capitalised at €20 million has a five-year life and zero residual. After one full year, a qualifying €4 million module becomes ready at year 2 start. It has no benefit beyond the original system's four remaining years. What is total year 2 straight-line amortisation?","choices":["€5 million","€4.8 million","€4 million","€6 million"],"correct_index":0,"explanation":"The original system continues at €20m ÷ 5 = €4m annually. The module is amortised over its four-year benefit period at €4m ÷ 4 = €1m. Total is €5m. Adding a module does not automatically restart the original life."},{"id":"cr-s11-level2-v1-q3","session":"11","level":2,"topic":"Acquired cost and expected life","question":"A patent is purchased for €18 million, with €2 million of legal fees to register it. Staff training to work with the patent costs €1 million. The patent has ten-year legal protection but only five-year expected use, zero residual and a full year of availability. What cost and straight-line annual amortisation are recognised?","choices":["Cost €21m and charge €4.2m","Cost €20m and charge €4m","Cost €20m and charge €2m","Cost €18m and charge €3.6m"],"correct_index":1,"explanation":"Initial cost is €18m + €2m = €20m: the registration fees are directly attributable to securing the patent, while the training is expensed. Five-year expected use is shorter than the legal term, so annual amortisation is €20m ÷ 5 = €4m. Both the cost base and the benefit period must be assessed."},{"id":"cr-s11-level2-v1-q4","session":"11","level":2,"topic":"Internally generated versus acquired brand","question":"A company spends €6 million creating its own brand and separately buys an identifiable brand for €10 million in a transaction meeting recognition conditions. Which amounts qualify as brand assets?","choices":["Both, totalling €16m","Neither brand","The acquired €10m brand, not the internally generated €6m brand","Only the internally generated €6m brand"],"correct_index":2,"explanation":"IAS 38 prohibits recognising internally generated brands as intangible assets. A separately acquired identifiable brand can qualify. Measurable internal spending does not remove the specific prohibition or make the two acquisition routes identical."},{"id":"cr-s11-level2-v1-q5","session":"11","level":2,"topic":"Cost model impairment and amortisation","question":"An intangible under the cost model has €30 million original cost, €8 million accumulated amortisation and €3 million accumulated impairment losses. What is its carrying amount?","choices":["€22 million","€27 million","€30 million","€19 million"],"correct_index":3,"explanation":"Deduct both accumulated amortisation and impairment: €30m − €8m − €3m = €19m. They are separate reductions, not alternative methods from which management chooses one."},{"id":"cr-s11-level2-v1-q6","session":"11","level":2,"topic":"Finite life estimate revision","question":"Software carries at €15 million at year start. New evidence reduces remaining useful life from five years to three, with zero residual. The previous estimate was reasonable. What current straight-line amortisation and treatment of earlier years apply?","choices":["€5m, with a prospective estimate change","€3m, retaining the old estimate","€5m, with prior years retrospectively recomputed","€7.5m, treating three years as total original life"],"correct_index":0,"explanation":"Allocate current €15m over three remaining years: €5m annually. A reasonable estimate revised using new information changes current and future allocation, not earlier comparative charges. It is not automatically a prior-period error."},{"id":"cr-s11-level2-v1-q7","session":"11","level":2,"topic":"Promotion and development mixed","question":"A digital project incurs €3 million software coding after all development recognition criteria are met, €2 million content promoting the company's products, €1 million exploratory planning research and €0.5 million routine operating support. No other costs arise. What intangible cost is recognised?","choices":["€6.5 million","€3 million","€5 million","€4 million"],"correct_index":1,"explanation":"Only the €3m development coding enters the asset, because it is incurred after all recognition criteria are met. Promotion, research and routine support do not become capital costs simply because they concern the same digital project. The nature and timing of each cost matter."},{"id":"cr-s11-level2-v1-q8","session":"11","level":2,"topic":"Indefinite life annual impairment","question":"A recognised indefinite-life trademark carries at €25 million. No adverse indicator is identified this year. Can management omit the annual impairment test for that reason?","choices":["Yes, only an indicator triggers testing.","Yes, no amortisation also means no impairment testing.","No, an annual test is still required.","No, absence of an indicator forces immediate finite-life amortisation."],"correct_index":2,"explanation":"Annual impairment testing of indefinite-life intangibles is required even without an adverse indicator. No amortisation is not a testing exemption. The absence of an indicator also does not by itself change the supported useful-life classification."},{"id":"cr-s11-level2-v1-q9","session":"11","level":2,"topic":"Purchased customer relationships","question":"A business combination includes qualifying identifiable customer relationships with €12 million acquisition-date fair value. The acquiree had expensed the internal costs of building them. The acquirer later pays ordinary internal marketing costs. Which treatment is correct?","choices":["Include relationships in goodwill, then capitalise marketing.","Expense the acquired relationships, then expense marketing.","Recognise relationships separately, then capitalise marketing.","Recognise relationships separately, then expense ordinary marketing."],"correct_index":3,"explanation":"A qualifying acquisition-date identifiable intangible can be recognised separately from goodwill even if the acquiree could not recognise its internal spending. That acquisition rule does not relax the prohibition or expense treatment for later ordinary internal marketing."},{"id":"cr-s11-level2-v1-q10","session":"11","level":2,"topic":"Research cannot be relabelled","question":"A company spends €4 million exploring alternative technologies before technical feasibility can be demonstrated. Its budget calls the phase development and management expects eventual success. Does that label establish an intangible asset?","choices":["No, research substance and unmet conditions override the label.","Yes, the budget heading establishes development.","Yes, expected success is enough before feasibility.","No, every cost before a first commercial sale is always research."],"correct_index":0,"explanation":"Assess what the work is and whether all recognition criteria are met. Exploratory research is not converted into qualifying development by a budget title. Equally, a first sale is not a universal condition that prevents all earlier qualifying development recognition."},{"id":"cr-s11-level3-v1-q1","session":"11","level":3,"topic":"Integrated development year","question":"A project incurs €3 million research, €4 million development before all recognition criteria are met, €9 million development afterwards and €2 million staff training. The completed asset is available for the last six months of the year, with three-year life and zero residual. What are total current expense including straight-line amortisation and closing intangible?","choices":["Expense €10.5m and asset €7.5m","Expense €3m and asset €15m","Expense €9m and asset €9m","Expense €12m and asset €6m"],"correct_index":0,"explanation":"Capitalise €9m only. Six-month amortisation is €9m ÷ 3 × 6/12 = €1.5m. Other expenses are €3m + €4m + €2m = €9m, so total current expense is €10.5m. Closing asset is €9m − €1.5m = €7.5m. The earlier research and pre-criteria development are not reinstated."},{"id":"cr-s11-level3-v1-q2","session":"11","level":3,"topic":"Module midyear and remaining life","question":"Software originally cost €24 million with six-year straight-line life and zero residual. At year 3 start it has been used for two full years. A qualifying €8 million module becomes ready halfway through year 3 and is useful only until the original system ends. Its life at readiness is therefore 3.5 years. What total year 3 amortisation applies, rounded to three decimals?","choices":["€5 million","€5.143 million","€6 million","€4.667 million"],"correct_index":1,"explanation":"Original amortisation remains €24m ÷ 6 = €4m. Module amortisation for its first half year is €8m ÷ 3.5 × 0.5 = €1.142857m. Combined charge is €5.143m. Neither a new six-year life for the module nor a restart of the original system is supported."},{"id":"cr-s11-level3-v1-q3","session":"11","level":3,"topic":"Retrospective error versus new life","question":"Recognised software carries at €18 million at year start. New information reduces its remaining life from six to three years, with zero residual, and the old estimate was reasonable. Separately, a material prior-year research cost of €3 million was wrongly capitalised and requires retrospective removal from its separate asset balance and opening equity. Ignore tax and prior amortisation on that research item. What are current software amortisation and the error correction?","choices":["Software charge €9m and no opening correction","Software charge €3m and opening equity reduction €3m","Software charge €6m and opening equity reduction €3m","Software charge €6m and current research expense €3m instead of restatement"],"correct_index":2,"explanation":"The software estimate changes prospectively: €18m ÷ 3 = €6m current amortisation. The independent material research error requires the stated retrospective €3m reduction of opening equity. Discovering both this year does not make them the same kind of accounting change."},{"id":"cr-s11-level3-v1-q4","session":"11","level":3,"topic":"Revaluation with amortisation","question":"An intangible has an active market supporting revaluation. At year start it carries at €20 million with five-year remaining life and zero residual. It is revalued then to €30 million, with no prior deficit, and amortised straight-line for the full year. Ignore tax and reserve transfers. What OCI, amortisation and closing asset result?","choices":["Profit gain €10m, charge €6m, asset €24m","OCI gain €10m, charge €4m, asset €26m","OCI gain €10m, charge nil, asset €30m","OCI gain €10m, charge €6m, asset €24m"],"correct_index":3,"explanation":"Recognise the €10m uplift in OCI on the stated history. Revised annual amortisation is €30m ÷ 5 = €6m, leaving €24m. Revaluation does not change the finite useful life into an indefinite one or stop allocation of consumption."},{"id":"cr-s11-level3-v1-q5","session":"11","level":3,"topic":"Research success does not reinstate","question":"A company expensed €5 million research in year 1. At year 2 start all development criteria are met, and it then incurs €12 million development costs and €2 million training. The asset becomes ready only at year-end, so assume no year 2 amortisation. What year 2 asset and expense arise from these listed costs?","choices":["Asset €12m and expense €2m","Asset €17m and expense €2m","Asset €19m and expense nil","Asset €12m and expense €7m"],"correct_index":0,"explanation":"Year 2 development meeting all criteria creates a €12m asset, and training creates €2m current expense. The €5m research was already expensed in year 1. It is neither restored to the asset nor charged a second time in year 2."},{"id":"cr-s11-level3-v1-q6","session":"11","level":3,"topic":"Goodwill versus identifiable intangible","question":"A business combination recognises €8 million identifiable patents and €20 million acquired goodwill. Patents have four-year remaining life and zero residual. Goodwill is not systematically amortised under IFRS. After one full year with no impairment, what amortisation and closing combined balance result?","choices":["Amortisation €7m and combined asset €21m","Amortisation €2m and combined asset €26m","Amortisation nil and combined asset €28m","Amortisation €2m and combined asset €6m after expensing goodwill"],"correct_index":1,"explanation":"Patent amortisation is €8m ÷ 4 = €2m, leaving €6m. Acquired goodwill remains €20m absent impairment, so the combined balance is €26m. The ban on internally generated goodwill does not erase goodwill recognised in a business combination."},{"id":"cr-s11-level3-v1-q7","session":"11","level":3,"topic":"Useful life and legal renewal","question":"A purchased licence costs €16 million. Its non-renewable legal term is eight years, but technology is expected to become obsolete in four years. It is available for nine months this year, with zero residual and straight-line amortisation. What current charge and closing balance result?","choices":["Charge €1.5m and asset €14.5m","Charge €4m and asset €12m","Charge €3m and asset €13m","Charge nil until legal expiry"],"correct_index":2,"explanation":"Use the shorter four-year economic benefit period. Annual amortisation is €16m ÷ 4 = €4m. Nine months gives €3m, leaving €13m. Legal protection is an upper bound, not a reason to ignore earlier obsolescence."},{"id":"cr-s11-level3-v1-q8","session":"11","level":3,"topic":"Separate software and routine support","question":"Software opens at €20 million with five years remaining life and zero residual. At year start, a €6 million enhancement that extends the software's functionality is ready for use, with an independent three-year life. Support of the existing software costs €1 million and staff training costs €0.5 million. With full-year straight-line amortisation, what total current expense and closing combined intangible result?","choices":["Expense €6m and asset €21.5m","Expense €5.5m and asset €22m","Expense €7.5m and asset €18.5m","Expense €7.5m and asset €20m"],"correct_index":3,"explanation":"Original amortisation is €20m ÷ 5 = €4m and enhancement amortisation is €6m ÷ 3 = €2m. Add support €1m and training €0.5m, both expensed as incurred, for total expense €7.5m. Closing assets are €20m + €6m − €6m amortisation = €20m. Service and training costs never enter that balance."},{"id":"cr-s11-level3-v1-q9","session":"11","level":3,"topic":"Indefinite reassessed as finite","question":"At year start an indefinite-life intangible carries at €30 million. A supported reassessment now establishes five-year remaining useful life and zero residual. The required impairment assessment produces no loss. What full-year straight-line amortisation and closing amount follow?","choices":["Charge €6m and asset €24m","Charge nil and asset €30m, retaining the initial life forever","Immediate expense €30m and asset nil","Charge €6m and asset €24m, plus retrospective charges for all prior years"],"correct_index":0,"explanation":"The supported finite-life reassessment applies prospectively. With no impairment, allocate €30m over five remaining years for €6m, leaving €24m. A changed expectation does not automatically mean the previous indefinite-life assessment was an error."},{"id":"cr-s11-level3-v1-q10","session":"11","level":3,"topic":"Four costs and economic savings","question":"A software project incurs €4 million research, €10 million development after all recognition conditions are met, €2 million promotional content and €1 million routine maintenance. The software provides controlled future cost savings, not separate sales revenue. Does lack of a standalone sales stream prevent recognition, and what cost qualifies?","choices":["Yes, no asset qualifies without separate sales.","No, cost savings can be benefits and €10m qualifies.","No, all €17m qualifies because the project saves costs.","No, €12m qualifies including promotional content."],"correct_index":1,"explanation":"Future benefits can be cost savings as well as revenue. Recognise the €10m qualifying development tranche. The savings do not make research, promotion or maintenance eligible merely because all expenditure relates to the same project."}],"12":[{"id":"cr-s12-level1-v1-q1","session":"12","level":1,"topic":"Recoverable amount uses the higher measure","question":"A cost-model machine carries at €80 million. Its fair value less costs of disposal is €60 million and value in use €72 million. What are recoverable amount and impairment loss?","choices":["Recoverable €60m and loss €20m","Recoverable €66m and loss €14m","Recoverable €72m and loss €8m","Recoverable €80m and loss nil"],"correct_index":2,"explanation":"Recoverable amount is the higher of €60m and €72m: €72m. Carrying amount exceeds it by €80m − €72m = €8m. Neither the lower valuation nor an average measures recoverable amount."},{"id":"cr-s12-level1-v1-q2","session":"12","level":1,"topic":"No upward impairment gain","question":"A cost-model asset carries at €40 million and has €55 million recoverable amount. It has never been impaired and is not revalued. What does the IAS 36 test itself recognise?","choices":["A €15m gain increasing the asset to recoverable amount","A €15m impairment loss","A €15m OCI surplus despite the cost model","No impairment and no automatic €15m gain"],"correct_index":3,"explanation":"The asset is not impaired because recoverable amount exceeds carrying amount. This is a loss test, not an automatic upward valuation of a cost-model asset. There is also no prior impairment to reverse."},{"id":"cr-s12-level1-v1-q3","session":"12","level":1,"topic":"Disposal costs matter","question":"An asset carries at €50 million. Fair value is €48 million, disposal costs €3 million and value in use €44 million. What is recoverable amount?","choices":["€45 million","€48 million","€44 million","€47 million"],"correct_index":0,"explanation":"Fair value less disposal costs is €48m − €3m = €45m. It is higher than €44m value in use, so recoverable amount is €45m. Using gross selling value would ignore the cost of realising that value."},{"id":"cr-s12-level1-v1-q4","session":"12","level":1,"topic":"Cash flows need not be independent","question":"A dedicated transport system serves one factory and has no largely independent inflows or separately determinable recoverable amount. The factory generates largely independent cash inflows. At what level is the transport system tested?","choices":["Alone at scrap value regardless of its operating role","Within the factory cash-generating unit","With every factory in the group despite independent inflows","At its legal owner's level regardless of cash generation"],"correct_index":1,"explanation":"Use the smallest relevant group generating largely independent inflows when individual recoverable amount cannot be determined. The transport system supports the factory's cash generation. A shared inflow does not make a support asset worthless or justify arbitrary group-wide pooling."},{"id":"cr-s12-level1-v1-q5","session":"12","level":1,"topic":"Annual goodwill testing","question":"Goodwill is allocated to a cash-generating unit. No adverse impairment indicator is apparent this year. What test is still required?","choices":["Only indicator-based testing if the unit remains profitable","Annual goodwill amortisation instead of testing","Annual impairment testing of the unit including goodwill","Testing only identifiable assets until goodwill is sold"],"correct_index":2,"explanation":"Goodwill requires annual impairment testing, as well as testing when indications arise. Profitability or absence of an indicator does not remove the annual requirement. Goodwill is tested with the relevant unit rather than by inventing independent goodwill inflows."},{"id":"cr-s12-level1-v1-q6","session":"12","level":1,"topic":"Not yet ready intangible","question":"A recognised intangible is not yet available for use, so amortisation has not begun. Does this also postpone its IAS 36 impairment testing?","choices":["Yes, all testing starts only when ready.","Yes, except for tests triggered by indicators, with no annual requirement.","No, begin amortisation early instead of testing.","No, annual impairment testing applies before availability for use."],"correct_index":3,"explanation":"Intangibles not yet available for use require annual impairment testing. The start of amortisation and the need for impairment testing are separate questions. No current amortisation does not guarantee that the carrying amount is recoverable."},{"id":"cr-s12-level1-v1-q7","session":"12","level":1,"topic":"Indicator is not a fixed loss amount","question":"A listed company's market capitalisation falls below the carrying amount of its net assets. What does this mean for IAS 36?","choices":["It is an impairment indicator, not a direct asset-by-asset loss measurement.","Every asset is written down by the same percentage shortfall.","The entire difference must immediately be charged to goodwill.","It is irrelevant until operating cash receipts also fall."],"correct_index":0,"explanation":"This external signal calls for recoverable-amount analysis. It does not replace identifying assets or CGUs and comparing their appropriate amounts. A market-capitalisation gap is not automatically the recognised impairment charge."},{"id":"cr-s12-level1-v1-q8","session":"12","level":1,"topic":"Goodwill allocation first","question":"A CGU contains €10 million goodwill and €90 million other assets. Recoverable amount is €94 million. No individual losses or allocation limits change the calculation. What closing goodwill results?","choices":["€10m, with all loss on other assets","€4m, after allocating the €6m loss first to goodwill","Nil, because any CGU loss eliminates all goodwill","€9.4m, after pro-rata allocation across everything"],"correct_index":1,"explanation":"Total carrying amount is €100m and loss €6m. Allocate that loss first to goodwill, leaving €10m − €6m = €4m. There is no need to eliminate goodwill beyond the measured loss."},{"id":"cr-s12-level1-v1-q9","session":"12","level":1,"topic":"No goodwill reversal","question":"Last year a company recognised an €8 million goodwill impairment. Prospects improve and management wants to restore that same goodwill amount. What does IAS 36 permit?","choices":["Reverse up to original goodwill cost.","Reverse through OCI rather than profit.","No reversal of recognised goodwill impairment.","Reverse any amount supported by current CGU headroom."],"correct_index":2,"explanation":"Goodwill impairment is not reversed. Improved prospects may reflect internally generated goodwill rather than recovery of the originally recognised asset. Rules allowing reversals for some other assets do not override this prohibition."},{"id":"cr-s12-level1-v1-q10","session":"12","level":1,"topic":"Revised depreciation after impairment","question":"A machine is impaired from €30 million to €24 million. After the test it has four years remaining life and zero residual. What annual straight-line depreciation applies?","choices":["€7.5 million","€4.5 million","€8 million","€6 million"],"correct_index":3,"explanation":"Allocate the revised €24m carrying amount over four remaining years: €6m annually. The impairment is a separate loss at the test date, and subsequent depreciation uses the reduced base."},{"id":"cr-s12-level2-v1-q1","session":"12","level":2,"topic":"Discounted terminal receipt","question":"An asset produces net cash receipts of €11 million at year 1 end and €12.1 million at year 2 end, with nothing thereafter. Use a 10% annual discount rate. Fair value less disposal costs is €18 million and carrying amount €25 million. What are value in use and impairment?","choices":["VIU €23.1m and loss €1.9m","VIU €18m and loss €7m","VIU €21m and loss €4m","VIU €20m and loss €5m"],"correct_index":3,"explanation":"Present values are €11m ÷ 1.10 = €10m and €12.1m ÷ 1.10² = €10m. VIU is €20m, higher than €18m disposal measure. Recoverable amount is €20m and impairment €25m − €20m = €5m."},{"id":"cr-s12-level2-v1-q2","session":"12","level":2,"topic":"CGU proportional residual loss","question":"A CGU has €20 million goodwill, €60 million plant and a €40 million patent. Recoverable amount is €90 million. There are no earlier individual losses and no asset floors bind. What are the closing balances?","choices":["Goodwill nil, plant €54m, patent €36m","Goodwill €15m, plant €45m, patent €30m","Goodwill nil, plant €42m, patent €28m","Goodwill €20m, plant €42m, patent €28m"],"correct_index":0,"explanation":"Loss is €120m − €90m = €30m. First eliminate €20m goodwill. Allocate the remaining €10m to plant and patent in their 60:40 carrying proportions: €6m and €4m losses. They close at €54m and €36m."},{"id":"cr-s12-level2-v1-q3","session":"12","level":2,"topic":"Same asset reserve limit","question":"An IAS 16 revalued asset carries at €40 million with €30 million recoverable amount. Its existing revaluation surplus is €6 million, all for that same asset. Ignore tax. How is the impairment presented?","choices":["OCI decrease €10m and profit nil","OCI decrease €6m and profit expense €4m","Profit expense €10m with surplus unchanged","OCI decrease €4m and profit expense €6m"],"correct_index":1,"explanation":"The loss is €40m − €30m = €10m. Treat the revalued-asset loss as a revaluation decrease: €6m consumes the same asset's surplus through OCI, with €4m excess in profit. The reserve is not an unlimited shield."},{"id":"cr-s12-level2-v1-q4","session":"12","level":2,"topic":"Reversal ceiling binding","question":"A cost-model asset now carries at €36 million after impairment and depreciation. Without the past impairment it would carry at €44 million today. Recoverable amount is €50 million and reversal conditions are met. What reversal and closing balance are permitted?","choices":["Reverse €14m to close at €50m.","Reverse nil because no impairment can ever be reversed.","Reverse €8m to close at €44m.","Reverse €4m to close at €40m."],"correct_index":2,"explanation":"The no-impairment depreciated amount is the reversal ceiling. Restore only to €44m despite €50m recoverable amount. Reversal is €44m − €36m = €8m. This asset is not goodwill, so the goodwill prohibition does not apply."},{"id":"cr-s12-level2-v1-q5","session":"12","level":2,"topic":"Reversal recoverable amount binding","question":"A cost-model asset carries at €20 million. Its current recoverable amount is €25 million and its depreciated no-impairment ceiling €28 million. Reversal conditions are satisfied. What reversal is recognised?","choices":["€8m to reach the ceiling","€25m, treating recoverable amount as the gain","Nil until disposal","€5m to reach €25m"],"correct_index":3,"explanation":"Restored carrying amount is limited by both recoverable amount and the no-impairment ceiling. The lower limit is €25m, so increase €20m by €5m. Headroom up to €28m is not recoverable on the stated current estimate."},{"id":"cr-s12-level2-v1-q6","session":"12","level":2,"topic":"Floor reallocation","question":"A CGU with no goodwill contains A at €60 million and B at €40 million. Recoverable amount is €80 million. Applicable allocation floors are €55 million for A and €10 million for B, with no other limits. What closing amounts result?","choices":["A €55m and B €25m","A €48m and B €32m","A €55m and B €32m","A €60m and B €20m"],"correct_index":0,"explanation":"The €20m loss would initially allocate €12m to A and €8m to B. A can lose only €5m before its €55m floor. Reallocate the €7m excess to B, which loses €15m in total and closes at €25m. The final balances sum to €80m."},{"id":"cr-s12-level2-v1-q7","session":"12","level":2,"topic":"Corporate assets included consistently","question":"A CGU has €80 million operating assets and €10 million reasonably allocated corporate IT. Its €84 million recoverable amount consistently includes the benefits of that shared IT. There is no goodwill or floor constraint. What impairment is required?","choices":["Nil, comparing only operating assets","€6m, including the corporate asset allocation","€10m, writing off IT before any comparison","A €4m gain after excluding corporate IT"],"correct_index":1,"explanation":"Compare like with like. Carrying amount including relevant IT is €90m, against consistently measured recoverable amount €84m. The €6m shortfall is impairment. Excluding the supporting asset while retaining its benefits understates the tested carrying amount."},{"id":"cr-s12-level2-v1-q8","session":"12","level":2,"topic":"Individual test before CGU","question":"A CGU initially contains goodwill €10 million, a machine €50 million and other assets €40 million. The machine first incurs a separately measured €8 million impairment. The CGU is then tested against €86 million recoverable amount. With no other constraints, what additional unit loss and closing goodwill result?","choices":["Additional loss €14m and goodwill nil","Additional loss nil and goodwill €10m","Additional loss €6m and goodwill €4m","Additional loss €8m and goodwill €2m"],"correct_index":2,"explanation":"The individual loss reduces the unit's carrying amount from €100m to €92m. Its additional shortfall is €92m − €86m = €6m. Allocate that to goodwill, leaving €4m. Comparing the original €100m again would double-count the first loss."},{"id":"cr-s12-level2-v1-q9","session":"12","level":2,"topic":"Recoverable amount and discount sensitivity","question":"With cash forecasts unchanged, a higher appropriate discount rate reduces value in use from €70 million to €62 million. Current fair value less disposal costs remains €66 million and carrying amount €68 million. What recoverable amount and impairment now apply?","choices":["Recoverable €62m and loss €6m","Recoverable €70m and loss nil","Recoverable €64m and loss €4m","Recoverable €66m and loss €2m"],"correct_index":3,"explanation":"Use current measures, not the old VIU. Recoverable amount is the higher of €62m VIU and €66m disposal value: €66m. The loss is €68m − €66m = €2m. Which valuation provides the higher amount can change over time."},{"id":"cr-s12-level2-v1-q10","session":"12","level":2,"topic":"CGU definition versus organisation chart","question":"Two divisions each generate largely independent cash inflows. There is no goodwill or corporate asset requiring a higher-level test. Management wants to combine them so one division's headroom offsets the other's shortfall. What testing boundary is appropriate?","choices":["Each division as its own CGU","Their combined management summary","The legal company regardless of independent inflows","The entire group because shareholders are common"],"correct_index":0,"explanation":"CGUs follow the smallest identifiable groups with largely independent inflows. An arbitrary aggregate can hide impairment at the appropriate lower level. Common ownership or a convenient reporting summary is not sufficient to combine these two units."},{"id":"cr-s12-level3-v1-q1","session":"12","level":3,"topic":"Goodwill and binding asset floor","question":"A CGU contains €20 million goodwill, €80 million plant and €40 million patents. Recoverable amount is €95 million. Plant has an applicable €70 million impairment floor and patents a €10 million floor. There are no individual losses or other constraints. What are closing balances?","choices":["Goodwill nil, plant €70m, patents €25m","Goodwill nil, plant €63.333m, patents €31.667m","Goodwill nil, plant €70m, patents €31.667m","Goodwill €5m, plant €60m, patents €30m"],"correct_index":0,"explanation":"Loss is €140m − €95m = €45m. Eliminate €20m goodwill, leaving €25m. Plant's pro-rata share would exceed its permitted €10m loss, so plant closes at its €70m floor. Patents absorb €15m and close at €25m, above their floor. Total closes at €95m."},{"id":"cr-s12-level3-v1-q2","session":"12","level":3,"topic":"Two floors with residual reallocation","question":"A CGU without goodwill contains A at €50 million, B at €30 million and C at €20 million. Recoverable amount is €70 million. Allocation floors are A €45 million, B €20 million and C nil. No other constraints apply. What closing amounts result after allocating the full loss?","choices":["A €35m, B €21m, C €14m","A €45m, B €20m, C €5m","A €45m, B €21m, C €14m","A €50m, B €20m, C nil"],"correct_index":1,"explanation":"Allocate a €30m loss subject to each floor. A can lose only €5m and B only €10m, so C absorbs the remaining €15m. Balances are €45m, €20m and €5m, totalling €70m. An allocation must both respect every floor and account for the full permitted loss."},{"id":"cr-s12-level3-v1-q3","session":"12","level":3,"topic":"Reversal after a year of depreciation","question":"At year 1 start a cost-model machine carries at €60 million and is impaired to €36 million. Remaining life is six years with zero residual, straight line. After one year, recoverable amount rises to €55 million and reversal conditions are met. What reversal and year-end amount are permitted?","choices":["Reverse €25m to close at €55m.","Reverse €19m to close at €49m.","Reverse €20m to close at €50m.","Reverse €24m to close at €54m."],"correct_index":2,"explanation":"After impairment, annual depreciation is €36m ÷ 6 = €6m, leaving €30m. Without impairment it would have been €60m − €10m depreciation = €50m. That ceiling limits restoration despite €55m recoverable amount. Reverse €20m, not the whole original €24m loss."},{"id":"cr-s12-level3-v1-q4","session":"12","level":3,"topic":"Mixed reversal constraints","question":"A cost-model machine carries at €24 million, with €30 million recoverable amount and €32 million depreciated no-impairment ceiling. A separate patent carries at €10 million, with €18 million recoverable amount and €15 million ceiling. Both meet reversal conditions. The CGU also previously lost €12 million goodwill, which cannot be reversed. What total reversal gain is permitted?","choices":["€23m including goodwill","€14m restoring both assets to ceilings","€6m on the machine only","€11m with no goodwill restoration"],"correct_index":3,"explanation":"Machine gain is min(€30m, €32m) − €24m = €6m. Patent gain is min(€18m, €15m) − €10m = €5m. Combined gain is €11m. Each asset has its own limit, and the goodwill loss is not reinstated."},{"id":"cr-s12-level3-v1-q5","session":"12","level":3,"topic":"PV operating and disposal flows","question":"An asset carries at €50 million. Expected net operating receipts are €11 million at each of the next two year-ends, plus €12.1 million net disposal proceeds at year 2 end. Use a 10% annual discount rate. Current fair value less disposal costs is €28 million. What VIU and impairment result, rounded to three decimals?","choices":["VIU €29.091m and loss €20.909m","VIU €34.1m and loss €15.9m","VIU €19.091m and loss €22m","VIU €28m and loss €22m"],"correct_index":0,"explanation":"Year 1 present value is €11m ÷ 1.10 = €10m. Year 2 combines €11m operating and €12.1m disposal cash, giving €23.1m ÷ 1.10² = €19.090909m. VIU is €29.090909m, above €28m disposal measure. Impairment is €50m − €29.090909m = €20.909m."},{"id":"cr-s12-level3-v1-q6","session":"12","level":3,"topic":"Corporate group second test","question":"Two CGUs carry at €60 million and €40 million before a shared €20 million headquarters asset. That asset cannot reasonably be allocated to either alone. Individual recoverable amounts are €65 million and €45 million, so both pass their own tests. The smallest group including both units and headquarters has consistently measured recoverable amount €110 million. What additional loss is required?","choices":["Nil","€10 million","€20 million","€15 million"],"correct_index":1,"explanation":"The higher-level carrying amount is €60m + €40m + €20m = €120m. Against €110m recoverable amount it has a €10m shortfall. Passing each lower-level test does not eliminate a separate group test needed for an unallocable corporate asset."},{"id":"cr-s12-level3-v1-q7","session":"12","level":3,"topic":"Separate impairment then residual CGU loss","question":"A CGU initially has €30 million goodwill, €100 million machine and €50 million patent. The machine first incurs a separately measured €10 million impairment. The CGU then has €130 million recoverable amount. No asset floor binds. What are total impairment and final machine and patent balances, rounded to three decimals?","choices":["Loss €50m, machine €83.333m, patent €46.667m","Loss €40m, machine €90m, patent €50m","Loss €50m, machine €83.571m, patent €46.429m","Loss €60m, machine €78m, patent €42m"],"correct_index":2,"explanation":"Individual loss leaves machine €90m and total CGU €170m. Further unit loss is €40m. Remove €30m goodwill, then allocate €10m over machine €90m and patent €50m. Losses are €6.428571m and €3.571429m. Closing balances total €130m. Total expense is the individual €10m plus unit €40m."},{"id":"cr-s12-level3-v1-q8","session":"12","level":3,"topic":"Two periods reserve and impairment","question":"Non-depreciating revalued land carries at €100 million with €20 million revaluation surplus for that land. Recoverable amount falls to €70 million and impairment is recognised. Next period it returns to €100 million, and the applicable revaluation treatment permits restoration to that amount. Ignore tax. What profit expense arises first and profit gain second?","choices":["Expense €30m then gain €30m","Expense nil then gain nil","Expense €10m then gain €30m","Expense €10m then gain €10m"],"correct_index":3,"explanation":"The initial €30m decline uses €20m surplus through OCI and €10m expense in profit. The later permitted €30m restoration first reverses that €10m profit expense, then restores €20m through OCI. Neither movement belongs wholly in profit on this history."},{"id":"cr-s12-level3-v1-q9","session":"12","level":3,"topic":"CGU loss and next year depreciation","question":"A CGU contains €10 million goodwill and a €90 million machine. Recoverable amount is €80 million and no allocation floor binds. After impairment the machine has four years remaining life and zero residual. What machine amount and subsequent annual straight-line depreciation result?","choices":["Machine €80m and depreciation €20m","Machine €72m and depreciation €18m","Machine €90m and depreciation €22.5m","Machine €80m and depreciation €22.5m"],"correct_index":0,"explanation":"CGU loss is €100m − €80m = €20m. First eliminate €10m goodwill, then reduce the machine by the remaining €10m to €80m. Future depreciation is €80m ÷ 4 = €20m. The old depreciation base no longer applies."},{"id":"cr-s12-level3-v1-q10","session":"12","level":3,"topic":"Recovery below historical ceiling","question":"A cost-model intangible carries at €12 million. Its recoverable amount is €18 million and depreciated no-impairment ceiling €20 million. Conditions for reversal are met. A separate goodwill impairment of €5 million cannot be reversed. What total current gain is allowed?","choices":["€11m including restored goodwill","€6m on the intangible only","€8m restoring the intangible to its ceiling","Nil because goodwill cannot be restored"],"correct_index":1,"explanation":"Restore the intangible to the lower of €18m recoverable amount and €20m ceiling. Gain is €18m − €12m = €6m. The separate €5m goodwill loss remains unrecognised as a reversal. Goodwill's exception does not prohibit every other asset reversal."}],"13":[{"id":"cr-s13-level1-v1-q1","session":"13","level":1,"topic":"Acquisition explains a balance sheet shift","question":"In a business combination, the acquirer identifies contractual customer relationships with an acquisition-date fair value of €120 million and computes a residual of €80 million after recognising all other identifiable net assets. In the same period it runs a €10 million internal advertising campaign to rebuild the acquiree's brand. Before amortisation or impairment, what amount is capitalised as intangible assets and goodwill from these facts?","choices":["€200m: relationships as an intangible, the residual as goodwill, campaign expensed","€210m: the campaign joins the other intangibles because it supports the acquired brand","€80m: the relationships stay in goodwill because the acquiree never recognised them","€120m: the residual is expensed because it cannot be identified"],"correct_index":0,"explanation":"The contractual relationships meet the identifiability criterion and are recognised at acquisition-date fair value, separately from goodwill, whatever the acquiree's books showed. The residual after identifiable net assets is goodwill. Internally generated brand building through advertising is expensed, in the combination as outside it: 120 + 80 = €200m capitalised, €10m expensed."},{"id":"cr-s13-level1-v1-q2","session":"13","level":1,"topic":"Control after buying remaining interest","question":"A company holds 50% of a joint venture and buys the other 50%, obtaining control and full ownership. In its consolidated accounts after obtaining control, what presentation replaces the old investment line?","choices":["Consolidate only the newly purchased half.","Keep one investment line representing 100%.","Recognise underlying assets for only the new half.","Consolidate the subsidiary's underlying assets and liabilities."],"correct_index":3,"explanation":"Obtaining control changes the basis to consolidation of the subsidiary. The prior joint-venture investment line is not retained for the old half alongside partial consolidation. Acquisition-date remeasurement and allocation are separate parts of that change."},{"id":"cr-s13-level1-v1-q3","session":"13","level":1,"topic":"Residual acquired goodwill","question":"A buyer acquires 100% of a business for €300 million. The identifiable net assets have an acquisition-date fair value of €180 million. The buyer also pays €6 million of advisory fees for the deal. There is no prior stake, no non-controlling interest and no tax adjustment. What is the goodwill?","choices":["€126m, because deal related spending adds to the cost of the acquisition","€120m, because advisory fees are expensed rather than added to consideration","€114m, because advisory fees reduce the consideration paid","€300m, because all amounts paid are part of goodwill until allocated"],"correct_index":1,"explanation":"Goodwill is the residual between consideration transferred (€300m) and identifiable net assets at fair value (€180m), so €120m. Acquisition related advisory fees are expensed as incurred: they are not part of consideration transferred and do not change goodwill."},{"id":"cr-s13-level1-v1-q4","session":"13","level":1,"topic":"Customer relationships recognition","question":"A business combination includes identifiable customer contractual relationships with €30 million acquisition-date fair value. All recognition conditions are met. The acquiree carried them at nil because they were internally generated. With no tax complication, what separate intangible amount does the acquirer recognise?","choices":["Nil, carrying over the acquiree's non-recognition","€30m despite the acquiree's nil balance","€30m within goodwill rather than as an identified asset","€30m marketing expense"],"correct_index":1,"explanation":"A qualifying identifiable acquired intangible is measured at acquisition-date fair value. Recognition is not limited by the acquiree's historical book balance. This does not reopen or reinstate the acquiree's earlier marketing expenses in its own accounts."},{"id":"cr-s13-level1-v1-q5","session":"13","level":1,"topic":"Amortisation versus goodwill","question":"An acquisition recognises a €20 million patent with five-year remaining life, zero residual, and €60 million goodwill. There is no impairment in the first full year. What annual IFRS amortisation is recognised?","choices":["€16m on patent and goodwill together","Nil on both balances","€4m on the patent, with no systematic goodwill amortisation","€12m on goodwill, with no patent amortisation"],"correct_index":2,"explanation":"The finite-life patent is amortised at €20m ÷ 5 = €4m. Acquired goodwill is not systematically amortised under IFRS and instead requires impairment testing. Acquiring both in one deal does not give them the same subsequent treatment."},{"id":"cr-s13-level1-v1-q6","session":"13","level":1,"topic":"Delayed land right commencement","question":"A recognised land-use intangible will not be available for intended use until the next reporting period, so no amortisation is charged yet. Does that automatically remove impairment testing?","choices":["Yes, annual testing starts only when use begins.","Yes, except for indicator-triggered tests, with no annual requirement.","No, because annual testing applies to goodwill and indefinite-lived intangibles but never to finite-lived assets.","No, an intangible not yet available for use still requires annual testing."],"correct_index":3,"explanation":"Amortisation commencement and impairment testing are separate. An intangible not yet available for use has an annual IAS 36 testing requirement. Postponing use does not protect its carrying amount from a loss of recoverability."},{"id":"cr-s13-level1-v1-q7","session":"13","level":1,"topic":"Acquisition multiple is not proof","question":"A buyer pays a high multiple of a target's historical earnings. Can that multiple alone determine an IAS 36 impairment loss?","choices":["No, it informs valuation questions but does not replace a recoverable-amount test.","Yes, the percentage above the sector multiple is the loss rate.","Yes, price above historical net assets is automatically impairment.","No, purchase valuation can never be relevant to recoverability."],"correct_index":0,"explanation":"A high multiple invites analysis of forecasts, comparability and future returns. IAS 36 measures impairment by comparing carrying and recoverable amounts, not a universal earnings-multiple threshold. A valuation signal is not a completed loss calculation."},{"id":"cr-s13-level1-v1-q8","session":"13","level":1,"topic":"No impairment statement limits","question":"An acquired CGU carries at €150 million and has €165 million current recoverable amount on supported assumptions. What headroom and interpretation follow?","choices":["Headroom €165m, equal to recoverable amount","Headroom €15m, with no current loss but no promise against future impairment","Impairment €15m because recoverable amount is higher","No headroom because it cannot exceed goodwill"],"correct_index":1,"explanation":"Headroom is recoverable amount less carrying amount: €165m − €150m = €15m. No current impairment is required. That conclusion depends on the model and assumptions at this date and does not guarantee future acquisition returns."},{"id":"cr-s13-level1-v1-q9","session":"13","level":1,"topic":"Discount rate direction","question":"A CGU's only remaining net receipt is €110 million in one year. Carrying amount is €99 million and no alternative recoverable measure exceeds VIU. The appropriate discount rate rises from 10% to 12% without changing cash forecasts. What are new VIU and impairment, rounded to three decimals?","choices":["VIU €100m and loss nil","VIU €110m and headroom €11m","VIU €98.214m and loss €0.786m","VIU €98.214m and loss €1.786m"],"correct_index":2,"explanation":"At 12%, VIU is €110m ÷ 1.12 = €98.214286m. Loss is €99m − €98.214286m = €0.785714m. Unchanged nominal cash flows do not mean unchanged present value when the appropriate discount rate changes."},{"id":"cr-s13-level1-v1-q10","session":"13","level":1,"topic":"Cash and share consideration","question":"A buyer acquires a business by transferring €40 million in cash and issuing shares worth €60 million at the acquisition date. It also pays €3 million of due diligence fees, and agrees to pay the sellers up to €10 million more in two years if the target meets an earnings target. That contingent payment has an acquisition-date fair value of €4 million. What is the consideration transferred for the goodwill computation?","choices":["€100m, because contingent amounts count only when they are paid","€104m, including the contingent consideration at acquisition-date fair value","€107m, including the due diligence fees as part of the price","€110m, using the maximum contingent payment"],"correct_index":1,"explanation":"Consideration transferred is the sum of cash (€40m), the acquisition-date fair value of the shares issued (€60m) and the acquisition-date fair value of contingent consideration (€4m), so €104m. Due diligence and other acquisition related costs are expensed, and contingent consideration is measured at fair value, not at its maximum and not when paid."},{"id":"cr-s13-level2-v1-q1","session":"13","level":2,"topic":"Step acquisition goodwill","question":"A buyer obtains full ownership by paying €240 million for the remaining interest. Its old stake has €210 million acquisition-date fair value and €150 million carrying amount. Identifiable net assets are €300 million at fair value. There is no NCI, tax or other adjustment. What goodwill and old-stake remeasurement gain result?","choices":["Goodwill negative €60m and gain nil","Goodwill €90m and gain €60m","Goodwill €150m and gain €210m","Goodwill €150m and gain €60m"],"correct_index":3,"explanation":"Total acquisition value is €240m new consideration + €210m prior-stake fair value = €450m. Deduct €300m net assets for €150m goodwill. Old-stake gain is €210m − €150m = €60m, not the whole stake value."},{"id":"cr-s13-level2-v1-q2","session":"13","level":2,"topic":"Net acquisition cash flow","question":"Acquisition consideration totals €200 million, comprising €150 million shares and €50 million cash. The acquired business includes €32 million cash. Ignoring fees and other cash movements, what net investing acquisition outflow is reported?","choices":["€18 million","€168 million","€50 million","€200 million"],"correct_index":0,"explanation":"Net cash paid is €50m cash consideration − €32m cash acquired = €18m. Shares are non-cash consideration. Neither total transaction value nor the prior stake's value becomes a cash outflow simply because it enters acquisition accounting."},{"id":"cr-s13-level2-v1-q3","session":"13","level":2,"topic":"Intangible fair value and future earnings","question":"Acquired customer relationships start at €80 million fair value, have ten-year useful life and zero residual, and are ready for a full year. With no impairment and straight-line amortisation, what closing amount and annual charge result?","choices":["Asset €80m and no charge until rights expire","Asset €72m and amortisation €8m","Asset €72m and goodwill impairment €8m","Asset €70m and amortisation €10m"],"correct_index":1,"explanation":"Annual amortisation is €80m ÷ 10 = €8m, leaving €72m. Separate recognition of a finite-life acquired intangible creates scheduled amortisation. That charge is not a goodwill impairment just because both balances arose in one deal."},{"id":"cr-s13-level2-v1-q4","session":"13","level":2,"topic":"Intangible concentration ratio","question":"A group has €1,000 million total assets, including €420 million goodwill and €180 million other intangibles. What share of total assets do those two items represent together?","choices":["42%","18%","60%","140%"],"correct_index":2,"explanation":"Combined balance is €420m + €180m = €600m. Divide by €1,000m assets for 60%. A large concentration makes life and recoverability assumptions important, but does not by itself establish an impairment loss."},{"id":"cr-s13-level2-v1-q5","session":"13","level":2,"topic":"Market capitalisation cross check","question":"A group's market capitalisation is €700 million against €900 million net-asset carrying amount. What is the appropriate impairment-review conclusion?","choices":["Automatically impair goodwill by €200m.","Write down all assets to make equity equal market capitalisation.","Ignore the gap unless cash flows are negative.","Investigate an external impairment indicator, without mechanically fixing the loss."],"correct_index":3,"explanation":"Market value below book net assets is an external indicator. It calls for analysis of recoverable amounts and relevant CGUs. It is not automatically a €200m goodwill charge or a requirement that accounting equity always equal the stock-market value."},{"id":"cr-s13-level2-v1-q6","session":"13","level":2,"topic":"Forecast margin pressure","question":"A CGU forecast has €100 million annual revenue and a 30% cash operating margin. Supported price pressure reduces that margin to 24%, with revenue unchanged. Ignore discounting for this one-year comparison. How much does forecast operating cash flow fall?","choices":["€6 million","€24 million","€30 million","€0.06 million"],"correct_index":0,"explanation":"Cash flow falls from €100m × 30% = €30m to €100m × 24% = €24m, a €6m reduction. The six-percentage-point change is applied to revenue. It is not merely 6% of the previous cash flow."},{"id":"cr-s13-level2-v1-q7","session":"13","level":2,"topic":"Headroom and downside","question":"A CGU carries at €200 million. Base VIU is €230 million and fair value less disposal costs €180 million. In a supported downside VIU falls to €190 million while the disposal measure stays unchanged. What base headroom and downside loss result?","choices":["Headroom €50m and loss €20m","Headroom €30m and loss €10m","Headroom €30m and loss €20m","Headroom nil and loss €10m"],"correct_index":1,"explanation":"Base recoverable amount is max(€230m, €180m) = €230m, giving €30m headroom. Downside recoverable amount is max(€190m, €180m) = €190m, giving €10m loss. The whole €40m VIU decline is not itself the impairment."},{"id":"cr-s13-level2-v1-q8","session":"13","level":2,"topic":"Noncash gain in reported profit","question":"Reported profit before tax is €160 million, including a €100 million non-cash gain from remeasuring a previously held stake. An analyst removes that gain and makes no other adjustment. What adjusted profit before tax results?","choices":["€260 million","€160 million","€60 million","€100 million"],"correct_index":2,"explanation":"Deduct the included gain: €160m − €100m = €60m. This is a defined analytical adjustment, not a rejection of the recognised gain. It also does not directly measure operating cash flow or prove the remaining profit is sustainable."},{"id":"cr-s13-level2-v1-q9","session":"13","level":2,"topic":"Impairment belongs to identified CGUs","question":"A group reports €12 million total goodwill impairment. The notes allocate it to older CGUs and state no loss for a newly acquired target. What can an analyst conclude about that target?","choices":["Allocate some loss to it in proportion to goodwill anyway.","Assign the loss to it if it has the largest goodwill.","Its lack of current loss proves it can never be impaired.","The note allocation does not support attributing this loss to the target."],"correct_index":3,"explanation":"Use the disclosed allocation rather than assuming a group total belongs to the most recent deal. A loss elsewhere does not establish target impairment. Conversely, no current target loss is not a permanent guarantee of recoverability."},{"id":"cr-s13-level2-v1-q10","session":"13","level":2,"topic":"Purchase allocation deferred tax assumption","question":"A 100% acquisition has €500 million consideration. Identifiable assets have €400 million fair value and assumed liabilities €100 million, including every relevant deferred-tax amount. There is no prior interest or NCI. What net identifiable assets and goodwill result?","choices":["Net assets €300m and goodwill €200m","Net assets €400m and goodwill €100m","Net assets €500m and goodwill nil","Net assets €300m and goodwill €100m"],"correct_index":0,"explanation":"Net identifiable assets are €400m − €100m = €300m. Goodwill is €500m − €300m = €200m. Since relevant deferred tax is already included in liabilities, do not add an unstated duplicate adjustment."},{"id":"cr-s13-level3-v1-q1","session":"13","level":3,"topic":"Integrated step acquisition and cash","question":"A buyer pays €300 million for the remaining interest in a business, using €80 million cash and €220 million shares. Its old stake has €250 million fair value and €170 million carrying amount. Identifiable net assets have €350 million fair value, including €50 million acquired cash. There is no NCI or other adjustment. What goodwill, stake gain and net acquisition cash outflow result?","choices":["Goodwill €200m, gain €80m, cash outflow €30m","Goodwill €200m, gain €80m, cash outflow €250m","Goodwill €120m, gain €80m, cash outflow €30m","Goodwill €200m, gain €250m, cash outflow €80m"],"correct_index":0,"explanation":"Acquisition value is €300m + €250m = €550m, so goodwill is €200m after €350m net assets. Remeasurement gain is €250m − €170m = €80m. Net cash outflow is €80m cash paid − €50m acquired = €30m. Shares and remeasurement are not additional cash payments."},{"id":"cr-s13-level3-v1-q2","session":"13","level":3,"topic":"Amortisation and impairment sequence","question":"At year start an acquired CGU contains customer relationships €60 million with six-year life and zero residual, goodwill €90 million and other assets €100 million. Ignore depreciation of those other assets. After full-year straight-line amortisation, recoverable amount is €210 million. No floors or separate asset losses apply. What amortisation, impairment and closing goodwill result?","choices":["Amortisation €10m, impairment €40m, goodwill €50m","Amortisation €10m, impairment €30m, goodwill €60m","Amortisation nil, impairment €40m, goodwill €50m","Amortisation €10m, impairment €30m, goodwill €90m"],"correct_index":1,"explanation":"First amortise relationships by €60m ÷ 6 = €10m. The CGU then carries at €50m + €90m + €100m = €240m. Its €30m shortfall is allocated to goodwill, leaving €60m. Testing the old €250m total would omit the required amortisation before comparison."},{"id":"cr-s13-level3-v1-q3","session":"13","level":3,"topic":"Growth rate sensitivity supplied model","question":"For a supplied simplified model, value equals next-year perpetual cash flow divided by discount rate minus growth. Cash flow is €12 million, discount rate 10% and base growth 2%. Value is measured at the same date as €140 million CGU carrying amount, with no other flows or alternative recoverable measure. If growth falls to 1%, what base headroom and downside loss result, rounded to three decimals?","choices":["Headroom €10m and loss €16.667m","Headroom nil and loss €6.667m","Headroom €10m and loss €6.667m","Headroom €20m and loss €10m"],"correct_index":2,"explanation":"Base value is €12m ÷ (10% − 2%) = €150m, so headroom is €10m. Downside value is €12m ÷ (10% − 1%) = €133.333m, giving €6.667m impairment. The formula and matching valuation date are supplied, so no extra period of discounting is added."},{"id":"cr-s13-level3-v1-q4","session":"13","level":3,"topic":"Forecast cash and discount combined","question":"A CGU's only net receipt is €121 million in two years. Discount rate is 10%, fair value less disposal costs €90 million and carrying amount €98 million. A downside reduces the receipt to €108.9 million with the rate unchanged. What base headroom and downside impairment result?","choices":["Headroom €23m and loss nil","Headroom €2m and loss €10.9m","Headroom €8m and loss €2m","Headroom €2m and loss €8m"],"correct_index":3,"explanation":"Base VIU is €121m ÷ 1.10² = €100m, above the €90m alternative and €2m above carrying amount. Downside VIU is €108.9m ÷ 1.10² = €90m. Recoverable amount is then €90m, so loss is €98m − €90m = €8m."},{"id":"cr-s13-level3-v1-q5","session":"13","level":3,"topic":"Intangible misclassification effect","question":"Correct acquisition accounting recognises €40 million customer relationships with five-year life and €80 million goodwill. Instead, a preparer puts all €120 million in goodwill. There is no impairment or tax in the first full year, and the relationships have zero residual. Under straight-line amortisation, how are profit and closing assets misstated?","choices":["Both are overstated by €8m.","Profit is understated €8m and assets are correct.","Both are correct because initial asset totals match.","Profit is overstated €40m and assets are correct."],"correct_index":0,"explanation":"Correct annual relationship amortisation is €40m ÷ 5 = €8m. Misclassification as non-amortised goodwill omits it, overstating profit and closing assets by €8m. Identical initial totals do not guarantee correct later measurement."},{"id":"cr-s13-level3-v1-q6","session":"13","level":3,"topic":"Goodwill ratio after loss","question":"A group starts with €800 million assets, €300 million liabilities and €200 million goodwill included in assets. It recognises €50 million goodwill impairment without tax or other changes. What are closing equity and goodwill as a percentage of equity?","choices":["Equity €500m and ratio 30%","Equity €450m and ratio 33.3%","Equity €450m and ratio 44.4%","Equity €550m and ratio 27.3%"],"correct_index":1,"explanation":"Initial equity is €800m − €300m = €500m. Impairment reduces equity to €450m and goodwill to €150m. The ratio is €150m ÷ €450m = 33.3%. Both numerator and denominator change, not just goodwill."},{"id":"cr-s13-level3-v1-q7","session":"13","level":3,"topic":"Cash flow adjusted profit","question":"A simplified group reports €150 million profit before tax including a €90 million non-cash stake-remeasurement gain, €15 million goodwill impairment and €5 million intangible amortisation. There are no other non-cash, working-capital, tax or cash-classification adjustments. What cash-generated figure follows under the indirect bridge?","choices":["€40 million","€170 million","€80 million","€60 million"],"correct_index":2,"explanation":"Start with €150m, remove the €90m non-cash gain and add back €15m and €5m non-cash expenses: €80m. The gain and charges remain recognised in accounting profit. The bridge removes their non-cash effects for this explicitly simplified cash calculation."},{"id":"cr-s13-level3-v1-q8","session":"13","level":3,"topic":"Valuation range needs allocation","question":"Two CGUs each carry at €100 million including goodwill. A has €80 million recoverable amount and B €130 million. They require separate tests, with no shared higher-level goodwill arrangement changing the assessment. What total impairment is recognised?","choices":["Nil because aggregate recovery exceeds aggregate carrying amount","€30m, equal to B's headroom","A €10m gain from aggregate headroom","€20m because B's headroom cannot offset A's shortfall"],"correct_index":3,"explanation":"A requires €100m − €80m = €20m loss. B has no impairment, but its €30m headroom is not an offsetting recognised profit. Combining these separately tested units would hide A's required loss."},{"id":"cr-s13-level3-v1-q9","session":"13","level":3,"topic":"Acquisition profit not sustainable earnings proof","question":"A group reports €300 million profit including a one-off €220 million non-cash step-acquisition gain, €10 million amortisation and €20 million impairment. An analyst defines an adjusted measure removing all three items, ignoring tax. What amount results and what caveat applies?","choices":["€110m, a defined adjustment rather than proof of sustainable cash earnings","€80m, equivalent to free cash flow","€550m, adding the gain and charges","€110m, proving the charges have no economic relevance"],"correct_index":0,"explanation":"Adjusted measure = €300m − €220m + €10m + €20m = €110m. Removing specified accounting items can aid comparison, but impairment and amortisation may convey economic information. The result alone is neither sustainable earnings proof nor a cash-flow measure."},{"id":"cr-s13-level3-v1-q10","session":"13","level":3,"topic":"Sensitivity tied to headroom","question":"A CGU carries at €250 million and has €275 million base recoverable amount. A supported downside reduces recoverable amount by 12%, with no higher alternative measure or other change. What loss follows?","choices":["€33m, the whole valuation decline","€8m, after the decline consumes €25m base headroom","Nil because the base case had headroom","€25m, equal to the initial headroom"],"correct_index":1,"explanation":"Base headroom is €275m − €250m = €25m. Downside value is €275m × 88% = €242m, a €33m decline. The first €25m consumes headroom and the remaining €8m is impairment. A passing base case does not make downside assumptions irrelevant."}],"14":[{"id":"cr-s14-level1-v1-q1","session":"14","level":1,"topic":"Warranty portfolio expected cost","question":"A company has sold 10,000 products with an IAS 37 assurance warranty. For each product, 80% need no repair, 15% need a €20 repair and 5% a €100 repair. The population is large and discounting immaterial. What provision is required?","choices":["€30,000","€50,000","€80,000","€1,000,000"],"correct_index":2,"explanation":"Expected cost per product is 80% × nil + 15% × €20 + 5% × €100 = €8. For 10,000 products the provision is €80,000. The most common no-repair outcome does not make a large portfolio's expected obligation nil."},{"id":"cr-s14-level1-v1-q2","session":"14","level":1,"topic":"Present obligation not future intention","question":"At year-end a board has a private €200,000 factory-closure plan. No implementation, announcement, legal duty or valid expectation exists. A separate past event creates a present legal obligation with probable outflow and reliable €45,000 best estimate. Ignore discounting. What total provision is recognised?","choices":["€245,000","€200,000","Nil","€45,000"],"correct_index":3,"explanation":"Only the €45,000 legal obligation meets recognition conditions. The internal closure decision has not yet created a legal or constructive obligation. Its absence does not prevent recognising the separate qualifying matter."},{"id":"cr-s14-level1-v1-q3","session":"14","level":1,"topic":"Constructive environmental obligation","question":"A company has contaminated land. No law requires cleanup, but its specific published policy and consistent conduct have created a valid expectation among affected people that it will clean up. Outflow is probable and reliably estimable. What is required?","choices":["Recognise a provision for the existing constructive obligation.","Disclose only because no statute requires payment.","Wait until cleanup work starts.","Wait until an affected person files a legal claim."],"correct_index":0,"explanation":"The past contamination and established expectation create a constructive obligation on the stated facts. A legal statute is not the only source of a present obligation. A vague promise would not automatically suffice, but the necessary valid expectation is expressly given here."},{"id":"cr-s14-level1-v1-q4","session":"14","level":1,"topic":"Possible lawsuit outflow","question":"One past event creates a present legal obligation with probable outflow and reliable €80,000 best estimate. Another unrelated matter is only a possible obligation with a non-remote but non-probable €50,000 potential outflow. Ignore discounting. What provision and second-matter treatment follow?","choices":["Provide €130,000 and disclose neither.","Provide €80,000 and disclose the €50,000 contingency.","Provide €50,000 and disclose only €80,000.","Recognise nothing until both are virtually certain."],"correct_index":1,"explanation":"Recognise the first obligation at €80,000. The second is a non-remote contingent liability disclosed rather than recognised. Virtual certainty is not the normal provision-recognition threshold, and unrelated matters are assessed separately."},{"id":"cr-s14-level1-v1-q5","session":"14","level":1,"topic":"Remote lawsuit","question":"A present obligation has probable outflow and a reliable €60,000 best estimate. An unrelated possible €100,000 penalty has only a remote chance of outflow. No other disclosure requirement applies. Ignoring discounting, what IAS 37 outcome follows?","choices":["Provide €160,000 including the remote penalty.","Provide only the largest €100,000 exposure.","Provide €60,000, with no ordinary contingent disclosure for the remote penalty.","Provide €60,000 with mandatory disclosure of that remote penalty."],"correct_index":2,"explanation":"Recognise the €60,000 qualifying obligation. A remote possible outflow does not ordinarily require an IAS 37 provision or contingent-liability disclosure. The different items should not be pooled as though they met the same conditions."},{"id":"cr-s14-level1-v1-q6","session":"14","level":1,"topic":"Future operating losses","question":"Next year's forecast includes €3 million operating losses, but no present legal or constructive obligation from a past event exists for those losses. What is the appropriate response?","choices":["Provide €3m once the budget is approved.","Disclose the forecast as a contingent liability.","Immediately reduce all assets by €3m without testing recovery.","Do not provide for the losses, but consider whether they indicate asset impairment."],"correct_index":3,"explanation":"Expected future operating losses do not create a present obligation. The forecast may nevertheless signal that related assets are not recoverable, requiring a separate IAS 36 assessment. Not recognising a provision does not mean ignoring the forecast."},{"id":"cr-s14-level1-v1-q7","session":"14","level":1,"topic":"Probable asset claim","question":"A company has an ordinary recognised €20,000 receivable meeting its asset conditions. Separately, a legal claim could bring €70,000 and receipt is probable but not virtually certain. What total asset is recognised from these two items under the stated facts?","choices":["€20,000, with the probable uncertain claim disclosed only","€90,000 using the same probable threshold for the claim","€70,000 replacing the ordinary receivable","€20,000 with no disclosure until the claim is virtually certain"],"correct_index":0,"explanation":"The ordinary €20,000 receivable stays recognised. The unrelated probable legal inflow remains a contingent asset, disclosed but not recognised until virtually certain. That special uncertain-claim threshold does not prevent recognition of every ordinary receivable."},{"id":"cr-s14-level1-v1-q8","session":"14","level":1,"topic":"Virtual certainty recognition","question":"All substantive uncertainty about a damages receipt is resolved and realisation is now virtually certain. What IAS 37 conclusion follows?","choices":["Keep it contingent until cash arrives.","It is no longer contingent and recognition of the related asset is appropriate.","Wait for a payment date even though realisation is virtually certain.","Recognise a liability offset rather than a separate asset."],"correct_index":1,"explanation":"When receipt becomes virtually certain, it is no longer a contingent asset. Recognise the related asset as appropriate. Waiting for cash despite resolution of uncertainty would extend the contingent-gain restriction beyond its intended conditions."},{"id":"cr-s14-level1-v1-q9","session":"14","level":1,"topic":"Discount unwinding","question":"A discounted provision opens at €100,000. One year passes at a 5% annual discount rate, with no payment or change in estimate. What finance cost arises from unwinding?","choices":["Nil because it was already recognised","€100,000","€5,000","€95,000"],"correct_index":2,"explanation":"Unwinding is €100,000 × 5% = €5,000, increasing the provision as settlement approaches. It is the cost of time passing, not recognition of the whole obligation again or a deduction from it."},{"id":"cr-s14-level1-v1-q10","session":"14","level":1,"topic":"Expected asset disposal proceeds","question":"A company has a qualifying present cleanup obligation estimated at €1 million. It separately expects €300,000 proceeds from selling an unrelated asset. Discounting is immaterial. What provision is measured?","choices":["€700,000 after expected sale proceeds","€1.3m including sale receipts","Nil until the sale funds cleanup","€1m without deducting expected disposal proceeds"],"correct_index":3,"explanation":"The cleanup provision measures the obligation independently. Expected asset-sale gains or proceeds are not used to reduce it. A planned source of funding is not the same as a reduction in the settlement burden."},{"id":"cr-s14-level2-v1-q1","session":"14","level":2,"topic":"Discounted cleanup and unwind","question":"A present cleanup obligation requires €121,000 in exactly two years. Time value is material and the annual discount rate is 10%. There is no risk or estimate change. What initial provision and first-year unwind are recognised?","choices":["Initial €121,000 and unwind €12,100","Initial €110,000 and unwind €11,000","Initial €100,000 and unwind €21,000","Initial €100,000 and unwind €10,000"],"correct_index":3,"explanation":"Initial present value is €121,000 ÷ 1.10² = €100,000. First-year finance cost is €100,000 × 10% = €10,000, leaving €110,000. The full two-year discount of €21,000 is not all charged in year 1."},{"id":"cr-s14-level2-v1-q2","session":"14","level":2,"topic":"Restructuring direct costs only","question":"A valid current restructuring obligation exists. The plan includes €400,000 unavoidable closure costs, €120,000 retraining retained staff, €80,000 marketing and €200,000 for a new distribution system. Only closure is necessarily entailed by restructuring rather than continuing activities. With no material discounting, what restructuring provision is recognised?","choices":["€400,000","€800,000","€600,000","€520,000"],"correct_index":0,"explanation":"Only €400,000 direct unavoidable closure costs qualify. Retraining, marketing and the new distribution network concern continuing operations. A valid restructuring obligation does not make every item in the plan part of that provision."},{"id":"cr-s14-level2-v1-q3","session":"14","level":2,"topic":"Separate obligation probabilities","question":"Two unrelated lawsuits arise from past events. A is a present obligation with probable outflow and a €90,000 best estimate. B has a possible non-remote €60,000 outflow, but does not meet provision conditions. Ignore discounting. What is reported?","choices":["Provide €150,000 with no contingency.","Provide €90,000 and disclose the €60,000 contingency.","Provide €60,000 and disclose only €90,000.","Provide nil and disclose both because neither is certain."],"correct_index":1,"explanation":"Assess the matters separately. A meets recognition conditions at €90,000. B is disclosed as a non-remote contingency rather than added to A's liability. Certainty is not required for an ordinary provision, but a merely possible outflow does not meet the probable threshold."},{"id":"cr-s14-level2-v1-q4","session":"14","level":2,"topic":"Warranty mix change","question":"A large warranty portfolio is expected to have 70% no defects, 25% minor and 5% major defects. Repairing every product for minor defects would cost €2 million, and repairing every product for major defects €6 million. Discounting is immaterial. What expected provision results?","choices":["€500,000","€300,000","€800,000","€2 million"],"correct_index":2,"explanation":"Expected total cost = 70% × nil + 25% × €2m + 5% × €6m = €0.8m. The supplied costs are totals for the whole population under each severity, so no extra unstated product count is multiplied."},{"id":"cr-s14-level2-v1-q5","session":"14","level":2,"topic":"Single case best estimate explicit","question":"A single present legal obligation could settle for €100,000 or €200,000. After considering both outcomes and all evidence, counsel determines €150,000 is the amount the company would rationally pay to settle at the reporting date. Outflow is probable and discounting immaterial. What provision is recognised?","choices":["€100,000","€200,000","Nil","€150,000"],"correct_index":3,"explanation":"Use the supported best estimate supplied in the facts: €150,000. A single obligation does not automatically mean choosing the minimum or maximum. Other outcomes must be considered when they affect the best estimate, rather than assumed probabilities being invented."},{"id":"cr-s14-level2-v1-q6","session":"14","level":2,"topic":"Recognition date before announcement","question":"At 31 December a board has a private restructuring plan, with no implementation or legal obligation. On 10 January it first communicates the main features to affected parties and creates a valid expectation. Ignoring separate material subsequent-event disclosure, when does that constructive obligation first arise?","choices":["10 January when the expectation is created","31 December when the board approved the plan","31 December because a later announcement always proves an earlier obligation","Only when cash payments begin"],"correct_index":0,"explanation":"The facts locate creation of the valid expectation on 10 January. An unannounced internal decision is insufficient, and the later announcement does not backdate a newly created obligation. Payment can occur later than recognition."},{"id":"cr-s14-level2-v1-q7","session":"14","level":2,"topic":"Reliable objective future technology evidence","question":"A current cleanup duty costs €500,000 using existing methods. Sufficient objective evidence supports a technological improvement reducing cost to €440,000. A further hypothetical invention could reduce cost to €300,000 but lacks adequate evidence. Ignore discounting. What best estimate is supported?","choices":["€500,000","€440,000","€300,000","€360,000"],"correct_index":1,"explanation":"Reflect the sufficiently supported future improvement, giving €440,000. Do not assume an unsupported invention simply because it would be cheaper. Measurement considers evidence for future events rather than always freezing current methods or adopting the most optimistic possibility."},{"id":"cr-s14-level2-v1-q8","session":"14","level":2,"topic":"Two dated cash payments","question":"A recognised obligation requires €55,000 in one year and €60,500 in two years. The annual discount rate is 10%, and there are no other uncertainties or changes. What initial provision is recognised?","choices":["€115,500","€105,000","€100,000","€95,454.55"],"correct_index":2,"explanation":"Discount each dated payment: €55,000 ÷ 1.10 = €50,000 and €60,500 ÷ 1.10² = €50,000. Total is €100,000. Different settlement dates cannot be handled as one undiscounted total or with the same single discount period."},{"id":"cr-s14-level2-v1-q9","session":"14","level":2,"topic":"Onerous contract economic deficit","question":"An existing non-cancellable contract must be performed and has no exit alternative. Remaining unavoidable fulfilment costs are €180,000 and economic benefits €100,000. Required asset impairment has already been assessed without further adjustment. With immaterial discounting, what onerous-contract provision is recognised?","choices":["€180,000","€100,000","Nil until performance finishes","€80,000"],"correct_index":3,"explanation":"The unavoidable net burden is €180,000 − €100,000 = €80,000. This is an existing onerous contract, not simply a forecast of future operating losses. Gross performance cost alone overstates the net obligation."},{"id":"cr-s14-level2-v1-q10","session":"14","level":2,"topic":"Liability versus asset thresholds","question":"Separate past events create a present legal obligation with probable €200,000 outflow and a damages claim with probable but not virtually certain €150,000 inflow. Estimates are reliable and discounting immaterial. What is recognised?","choices":["A €200,000 provision and no claim asset","A €50,000 net provision","A €200,000 provision and €150,000 claim asset","Neither item until settlement is certain"],"correct_index":0,"explanation":"The obligation meets provision conditions. The uncertain claim is a contingent asset disclosed for probable inflow, but not recognised until virtually certain. The two recognition thresholds differ, and these unrelated amounts are not offset."},{"id":"cr-s14-level3-v1-q1","session":"14","level":3,"topic":"Two period provision rollforward","question":"A provision starts at €200,000 for €242,000 settlement in two years, discounted at 10%. At year 1 end, after unwinding and before payment, the expected settlement increases to €253,000 still due one year later. The rate stays 10%. What closing provision, unwind and separate estimate increase result?","choices":["Closing €230,000, unwind €20,000, estimate increase €10,000","Closing €253,000, unwind €20,000, estimate increase €33,000","Closing €230,000, unwind €30,000, estimate increase nil","Closing €220,000, unwind €20,000, estimate increase nil"],"correct_index":0,"explanation":"Passage of time first adds €200,000 × 10% = €20,000, leaving €220,000. Revised present value is €253,000 ÷ 1.10 = €230,000. The extra €10,000 is a remeasurement, separate from unwinding. The payment remains future, so it is still discounted."},{"id":"cr-s14-level3-v1-q2","session":"14","level":3,"topic":"Warranty balance and new sales","question":"Opening warranty provision is €90,000. During the year €40,000 claims are paid against it. The closing best estimate for obligations on old sales is €35,000, and new sales add €60,000 expected warranty cost. Discounting is immaterial. What closing provision and net current warranty expense result?","choices":["Closing €110,000 and expense €60,000","Closing €95,000 and expense €45,000","Closing €95,000 and expense €5,000","Closing €135,000 and expense €85,000"],"correct_index":1,"explanation":"After claims, €90,000 − €40,000 = €50,000 remains. Reduce old-sales obligations to €35,000, releasing €15,000. Add €60,000 for new sales. Closing provision is €95,000 and net expense €60,000 − €15,000 = €45,000. Paying provided claims is not a second expense."},{"id":"cr-s14-level3-v1-q3","session":"14","level":3,"topic":"Portfolio probability and present value","question":"A warranty portfolio has a 60% probability of no cost, 30% probability of €500,000 cost and 10% probability of €2 million cost. For this model every outcome is settled exactly two years later. Discount at 10% annually. What initial provision is recognised, to the nearest euro?","choices":["€350,000","€318,182","€289,256","€2 million"],"correct_index":2,"explanation":"Expected nominal settlement is 30% × €500,000 + 10% × €2m = €350,000. Present value is €350,000 ÷ 1.10² = €289,256. Both probability weighting and time value apply. Neither the worst outcome nor the undiscounted expectation is the initial discounted provision."},{"id":"cr-s14-level3-v1-q4","session":"14","level":3,"topic":"Mixed restructuring obligation review","question":"Before year-end a detailed restructuring plan is announced and creates a valid expectation. It includes €300,000 direct unavoidable closure costs due in one year, €70,000 retraining retained staff and €90,000 next-year operating losses. Only closure costs qualify. Use 10% discounting with material time value and ignore other obligations. What initial provision is recognised, nearest euro?","choices":["€460,000","€418,182","€300,000","€272,727"],"correct_index":3,"explanation":"Exclude continuing retraining and future operating losses. Discount the €300,000 qualifying closure cost for one year: €300,000 ÷ 1.10 = €272,727. A valid plan does not convert every budgeted expenditure into a present restructuring obligation."},{"id":"cr-s14-level3-v1-q5","session":"14","level":3,"topic":"Contract net cost and termination alternative","question":"An existing onerous contract can be performed for €420,000 remaining unavoidable costs and €300,000 benefits, or terminated for an €80,000 penalty with no further costs or receipts. Use the lower unavoidable net settlement burden. Relevant asset impairment is resolved and discounting immaterial. What provision is recognised?","choices":["€80,000","€120,000","€420,000","€200,000"],"correct_index":0,"explanation":"Performance has €420,000 − €300,000 = €120,000 net burden. Termination costs €80,000, so the lower unavoidable settlement burden is €80,000. Gross fulfilment costs are not themselves the provision when benefits or a cheaper exit are relevant."},{"id":"cr-s14-level3-v1-q6","session":"14","level":3,"topic":"Contingencies do not become reserves","question":"A recognised legal provision is €120,000. Management wants to add a private €200,000 future closure plan with no legal obligation or valid expectation, then deduct an unrelated €50,000 damages receipt that is probable but not virtually certain. Ignore discounting and other changes. What provision remains correct?","choices":["€270,000","€120,000","€320,000","€70,000"],"correct_index":1,"explanation":"The existing legal provision remains €120,000. The private closure plan creates no present obligation, and the uncertain unrelated claim is not recognised or offset. Neither proposed adjustment changes this qualifying liability."},{"id":"cr-s14-level3-v1-q7","session":"14","level":3,"topic":"Independent large populations","question":"Two large assurance-warranty populations arise from completed sales. A has 2,000 products, each with 90% no repair and 10% a €200 repair. B has 1,000 products, each with 80% no repair, 15% a €100 repair and 5% a €500 repair. Discounting is immaterial. What combined provision results?","choices":["€40,000","€60,000","€80,000","€100,000"],"correct_index":2,"explanation":"A costs 2,000 × 10% × €200 = €40,000 expected. B costs 1,000 × (15% × €100 + 5% × €500) = €40,000. Combined expected cost is €80,000. Most individual products having no repair does not eliminate the populations' obligations."},{"id":"cr-s14-level3-v1-q8","session":"14","level":3,"topic":"Provision versus related impairment","question":"A company forecasts €100,000 future operating losses, has an existing onerous contract with €30,000 unavoidable net burden, and a machine carrying at €120,000 with €90,000 recoverable amount. The machine loss is separate and does not change the contract burden. Ignore discounting. What provision and combined current expense result?","choices":["Provision €130,000 and expense €160,000","Provision €60,000 and expense €60,000","Provision nil and expense €30,000","Provision €30,000 and expense €60,000"],"correct_index":3,"explanation":"Recognise €30,000 onerous-contract provision. The separate machine impairment is €120,000 − €90,000 = €30,000. Combined expense is €60,000, but only €30,000 is a provision. Future operating losses are not added as a present liability."},{"id":"cr-s14-level3-v1-q9","session":"14","level":3,"topic":"Rate revision after unwinding","question":"A cleanup provision opens at €100,000 for €121,000 expected settlement in two years at 10%. After one year the cash estimate remains €121,000 with one year left, but the appropriate discount rate falls to 5%. What closing provision and rate-remeasurement increase after old-rate unwind result, nearest euro?","choices":["Closing €115,238 and remeasurement €5,238","Closing €110,000 and remeasurement nil","Closing €121,000 and remeasurement €11,000","Closing €115,238 and remeasurement €15,238"],"correct_index":0,"explanation":"Old-rate time passage first raises the balance to €110,000. Revised present value is €121,000 ÷ 1.05 = €115,238.095. The separate rate effect is €5,238.095 above €110,000. Total annual movement includes both €10,000 unwind and this remeasurement."},{"id":"cr-s14-level3-v1-q10","session":"14","level":3,"topic":"Mixed recognition closing balances","question":"At year-end a company has a present legal obligation with probable outflow and €70,000 reliable best estimate, a remote possible €100,000 penalty, and a virtually certain separate €40,000 receivable. No offsetting basis exists and discounting is immaterial. What balance-sheet amounts are recognised?","choices":["A €30,000 net provision","A €70,000 provision and separate €40,000 asset","A €170,000 provision and €40,000 asset","A €70,000 provision with no asset until cash collection"],"correct_index":1,"explanation":"The qualifying obligation is €70,000. The remote penalty is not provided for. The virtually certain receipt is recognised as an asset but cannot be netted against the unrelated liability on these facts. Recognition and presentation are separate questions."}],"16":[{"id":"cr-s16-level1-v1-q1","session":"16","level":1,"topic":"Control requires both rights","question":"A logistics customer signs a five-year contract for the whole capacity of a specified warehouse. The supplier decides how and for what purpose the warehouse is used, and the contract predetermines none of these decisions. Does the customer control the use of the warehouse?","choices":["Yes, because it receives the whole output of the warehouse","Yes, because the contract names one specific asset","No, because it does not direct how and for what purpose the warehouse is used, even though it receives all the economic benefits","Control is shared, because each party holds one of the two required rights"],"correct_index":2,"explanation":"Control needs both rights at once: substantially all economic benefits and direction of use. Here the customer has the benefits but the supplier keeps every relevant use decision, so the contract contains no lease. Rights held by two different parties cannot be added together."},{"id":"cr-s16-level1-v1-q2","session":"16","level":1,"topic":"Legal title not the recognition test","question":"A company leases a machine for six years. The lessor keeps legal title and no recognition exemption applies. What does the lessee recognise at commencement?","choices":["A lease liability but no asset","A right of use asset but no liability","Nothing, and the rentals are expensed over the term","Both a right of use asset and a lease liability"],"correct_index":3,"explanation":"The lessee's asset is its right to use the machine, which it controls, not legal title. With no short term or low value exemption, IFRS 16 requires both the right of use asset and the liability for future lease payments."},{"id":"cr-s16-level1-v1-q3","session":"16","level":1,"topic":"Different parties different models","question":"For one and the same lease, the lessee recognises a right of use asset under IFRS 16 with no exemption, while the lessor concludes that substantially all risks and rewards of ownership have not transferred. Which lessor treatment is consistent with these facts?","choices":["An operating lease: the lessor keeps the underlying asset and recognises rental income","A finance lease, because the lessee's right of use asset forces the lessor to mirror it","A second right of use asset in the lessor's own balance sheet","Derecognition of the asset with no receivable, since the lessee now shows the use right"],"correct_index":0,"explanation":"The two parties apply different frameworks. The lessee uses the single recognition model, while the lessor still classifies the lease. If risks and rewards have not transferred, the lessor has an operating lease, keeps the asset and spreads the rental income. The two balance sheets do not have to carry matching labels."},{"id":"cr-s16-level1-v1-q4","session":"16","level":1,"topic":"Comparability numerical bridge","question":"Two identical firms each report 100 million euros of recognised debt. Firm A also discloses 20 million of legacy operating lease obligations measured at present value. Firm B owns the equivalent assets, and the related borrowing is already inside its 100 million. An analyst wants lease adjusted debt that makes the two firms comparable. What are the adjusted figures?","choices":["A at 100 million and B at 100 million, because disclosed leases stay out of debt","A at 120 million and B at 100 million","A at 80 million and B at 100 million, deducting the leases from reported debt","A at 120 million and B at 120 million, adding an ownership adjustment for B as well"],"correct_index":1,"explanation":"Only A carries an unrecognised lease obligation, so the analyst adds the 20 million to A alone. B's equivalent funding is already inside its reported debt, and adding it again would double count. The exercise gives the present value directly, so no arbitrary rent multiple is needed."},{"id":"cr-s16-level1-v1-q5","session":"16","level":1,"topic":"Exemption requires eligibility","question":"A company leases an expensive machine for an enforceable term of eighteen months, with no purchase option and no termination right. Rentals are billed monthly. Which term decides whether the short term lease exemption is available?","choices":["One month, the billing interval","Twelve months, the reporting horizon","Eighteen months, the enforceable lease term","Six months, the part of the term beyond twelve months"],"correct_index":2,"explanation":"The exemption looks at the lease term itself, not at how often payments are billed. Eighteen months exceeds the twelve month ceiling, and an expensive machine is not a low value asset, so the lessee must recognise a right of use asset and a lease liability."},{"id":"cr-s16-level1-v1-q6","session":"16","level":1,"topic":"Reasonably certain renewal","question":"A lease runs for three non cancellable years, and the lessee holds a two year extension option that it is reasonably certain to exercise. What lease term is used to measure the lease liability?","choices":["Three years","Four years","Two years","Five years"],"correct_index":3,"explanation":"IFRS 16 includes periods covered by an extension option when the lessee is reasonably certain to exercise it. This anti avoidance rule stops firms from signing short leases with rolling options to keep debt off the balance sheet. Three plus two gives five years."},{"id":"cr-s16-level1-v1-q7","session":"16","level":1,"topic":"Uncertainty does not mean no obligation","question":"A lease combines fixed contractual payments with genuinely usage based payments that do not depend on any index or rate, and there are no disguised fixed minimums. How is the initial lease liability measured?","choices":["It includes the fixed payments only, and the usage based payments are excluded at inception","It includes the fixed payments plus the expected usage payments, all discounted","It includes the fixed payments plus usage payments at their maximum possible level","It excludes the fixed payments because variable payments exist in the same contract"],"correct_index":0,"explanation":"The liability captures fixed and in substance fixed payments and variable payments tied to an index or a rate. Genuine usage variability stays out of the initial measurement and becomes an expense as the usage occurs. Excluded at inception does not mean the payments never affect the accounts."},{"id":"cr-s16-level1-v1-q8","session":"16","level":1,"topic":"Disclosure reform does not create cash","question":"On the first day of a lease, a company recognises a right of use asset of 30 million euros and a lease liability of 30 million. No payment is made that day. What is the immediate effect on cash and on recognised gross debt?","choices":["Cash falls by 30 million, as if the liability were an upfront payment","Cash is unchanged and recognised gross debt rises by 30 million","Cash rises by 30 million, as if the right of use asset were loan proceeds","Gross debt is unchanged, because the right of use asset nets against the liability"],"correct_index":1,"explanation":"Initial recognition is a non cash event: assets and liabilities both grow by 30 million and no money moves. Gross debt rises because the new liability is a debt like obligation, and the right of use asset is not cash that could be netted against it."},{"id":"cr-s16-level1-v1-q9","session":"16","level":1,"topic":"Research result is not a universal forecast","question":"A study cited in the course finds that lease intensive firms cut investment after capitalisation rules arrived. Which use of this finding is legitimate?","choices":["Treat the average decline as the adjustment every firm must book","Conclude that recognising a lease liability directly causes a cash outflow","Read it as evidence of possible real effects on business behaviour, not as a forecast that every firm will invest less","Conclude that replacing leases is the best economic choice for every firm in the sample"],"correct_index":2,"explanation":"An empirical average over a sample describes behaviour in that setting. It is not a journal entry, not a uniform forecast and not proof for any individual firm. The finding matters because it shows that accounting rules can change real decisions."},{"id":"cr-s16-level1-v1-q10","session":"16","level":1,"topic":"Covenant definition matters","question":"A loan agreement freezes its definition of debt at the date of signing. A later accounting change pushes the borrower's reported liabilities up. Which debt measure decides whether the covenant is breached?","choices":["Reported IFRS debt, including every newly recognised liability","The adjusted debt figure the borrower prefers in its investor presentations","The fair value of the leased assets behind the new liabilities","Debt computed under the frozen definition written into the loan agreement"],"correct_index":3,"explanation":"A covenant is a contract, and the contract text governs the test. If the agreement froze the accounting definitions, the new reporting rules do not rewrite it. Reported leverage can rise while the covenant test still passes."},{"id":"cr-s16-level2-v1-q1","session":"16","level":2,"topic":"Gross and net leverage bridge","question":"A company reports debt of 200 million euros, cash of 40 million and equity of 160 million. It then recognises a right of use asset and a lease liability of 60 million each, with no effect on cash or equity. Using net debt equals debt minus cash, what is the new net debt to equity ratio?","choices":["1.00","1.625","0.625","1.375"],"correct_index":3,"explanation":"Debt becomes 200 + 60 = 260. Net debt is 260 - 40 = 220. Dividing by the unchanged equity of 160 gives 1.375. The right of use asset is not cash, so it never enters the net debt subtraction."},{"id":"cr-s16-level2-v1-q2","session":"16","level":2,"topic":"EBITDA and EBIT bridge","question":"The only accounting change in a year is that a legacy operating rent of 40 million euros is replaced by right of use depreciation of 32 million and lease interest of 12 million. What happens to EBITDA, EBIT and profit before tax?","choices":["EBITDA rises 40, EBIT rises 8 and profit before tax falls 4","EBITDA rises 40, EBIT rises 40 and profit before tax rises 28","EBITDA rises 8, EBIT falls 4 and profit before tax falls 4","EBITDA rises 40, EBIT rises 8 and profit before tax rises 4"],"correct_index":0,"explanation":"The old rent sat inside operating expenses, so removing it lifts EBITDA by 40, while depreciation and interest stay below EBITDA. EBIT changes by 40 - 32 = +8. Profit before tax changes by 40 - 32 - 12 = -4, because the new charges of 44 exceed the old rent."},{"id":"cr-s16-level2-v1-q3","session":"16","level":2,"topic":"Ratio denominator effect","question":"Revenue is 500 million euros and total assets are 400 million before lease recognition. A pure non cash recognition then adds 100 million of right of use assets, with no change in revenue or other assets. Using closing total assets, what happens to asset turnover?","choices":["It rises from 1.00 to 1.25","It falls from 1.25 to 1.00","It stays at 1.25 because cash did not move","It falls from 1.25 to 0.80"],"correct_index":1,"explanation":"Before recognition the ratio is 500/400 = 1.25. After recognition the denominator is 400 + 100 = 500, so the ratio becomes 500/500 = 1.00. Sales did not change. The ratio moved only because the asset base grew."},{"id":"cr-s16-level2-v1-q4","session":"16","level":2,"topic":"Current liability recognition effect","question":"Current assets are 150 million euros and current liabilities are 100 million. Lease recognition adds a current lease liability of 20 million and a non current liability of 80 million. The right of use asset is non current. What is the new current ratio?","choices":["0.75","1.50","1.25","1.875"],"correct_index":2,"explanation":"Only the 20 million current portion enters current liabilities, which become 100 + 20 = 120. The ratio is 150/120 = 1.25, down from 1.50. Using the full 100 of new lease debt would overstate the short term burden."},{"id":"cr-s16-level2-v1-q5","session":"16","level":2,"topic":"Old analyst approximation versus PV","question":"An analyst uses the old rule of thumb and multiplies annual rent of 12 million euros by 8 to estimate lease debt. A proper present value calculation gives 72 million. How far apart are the two figures, and which one is the IFRS 16 initial measurement basis?","choices":["The rule of thumb is 24 million lower, and the present value governs","The rule of thumb is 24 million higher, and the rent multiple governs initial recognition","Both give the same figure, because the multiple captures the same cash flows","The rule of thumb is 24 million higher, and the present value governs"],"correct_index":3,"explanation":"Eight times 12 is 96, which is 24 above the present value of 72. The multiple was a pre IFRS 16 analyst shortcut for off balance sheet leases. The standard requires discounting the actual lease payments."},{"id":"cr-s16-level2-v1-q6","session":"16","level":2,"topic":"Lease term and payable amounts","question":"A lease has two non cancellable years plus a three year extension the lessee is reasonably certain to exercise. Payments are 10,000 euros at the end of each included year. Ignoring discounting, what total rent falls inside the lease term?","choices":["50,000 euros","20,000 euros","30,000 euros","10,000 euros"],"correct_index":0,"explanation":"The lease term is 2 + 3 = 5 years because the extension is reasonably certain to be exercised. Five payments of 10,000 give 50,000. This is the undiscounted contractual total. The liability itself would be measured at present value."},{"id":"cr-s16-level2-v1-q7","session":"16","level":2,"topic":"Operating cash metric policy","question":"A lease payment of 30 million euros splits into 24 million of principal and 6 million of interest. The company presents interest paid within operating activities, which IAS 7 permits. How does the payment appear in the cash flow statement? Apply IAS 7 before the IFRS 18 amendments, without early applying those amendments.","choices":["Operating outflow of 30 and financing outflow of zero","Operating outflow of 6 and financing outflow of 24","Operating outflow of zero and financing outflow of 30","Investing outflow of 24 and operating outflow of 6"],"correct_index":1,"explanation":"IFRS 16 sends the principal portion of lease payments to financing activities. The interest portion follows the company's IAS 7 policy for interest paid, which the facts set as operating. Total cash flow is unaffected. Only the classification changes."},{"id":"cr-s16-level2-v1-q8","session":"16","level":2,"topic":"Recognition exemptions and service cost","question":"A company pays 10 million euros a year on capitalised leases, 3 million on short term leases for which it elected the recognition exemption, and 2 million on maintenance services accounted for separately. In a simple EBITDA bridge for the capitalised leases only, which payment pool is removed from operating expenses?","choices":["15 million","13 million","10 million","12 million"],"correct_index":2,"explanation":"The bridge concerns only the 10 million that used to be rent for the capitalised leases. The exempt short term leases keep their expense treatment under the election, and the separately accounted services were never lease payments. Neither of those pools is relabelled."},{"id":"cr-s16-level2-v1-q9","session":"16","level":2,"topic":"Finance versus operating lessor assessment","question":"A leased asset is so specialised that only the lessee can use it without major modification, the lease cannot be cancelled, and the payments cover substantially all of the asset's fair value. How should the lessor classify this lease?","choices":["Operating, because the lessor keeps legal ownership","Operating, because the lessee recognises a right of use asset","Finance, but only once the lessee actually obtains legal title","Finance, because substantially all the risks and rewards of ownership have transferred"],"correct_index":3,"explanation":"Specialised nature, a non cancellable term and payments covering substantially all fair value are classic indicators that risks and rewards passed to the lessee. Legal title staying with the lessor does not decide classification. Substance does."},{"id":"cr-s16-level2-v1-q10","session":"16","level":2,"topic":"Economic exposure versus new accounting line","question":"A lessee pays fixed rentals and gives no residual value guarantee. IFRS 16 recognition does not change the contract itself. Who bears the risk that the right of use asset becomes impaired, and who bears an unguaranteed shortfall when the lessor resells the returned asset?","choices":["The lessee bears the right of use impairment risk, and the lessor keeps the unguaranteed residual value risk","Both risks move to the lessee once the right of use asset is recognised","The lessor bears the impairment risk on the lessee's asset, and the lessee bears the resale shortfall","Neither risk exists once the lease liability is recognised"],"correct_index":0,"explanation":"The right of use asset sits in the lessee's books, so the lessee tests it for impairment under IAS 36. The residual value risk of the underlying asset stays with its owner, the lessor, unless a guarantee transfers it. Recognising a liability does not rewrite the risk allocation in the contract."},{"id":"cr-s16-level3-v1-q1","session":"16","level":3,"topic":"Integrated ratios and expense bridge","question":"Before an accounting change, a company reports debt of 300 million euros, cash of 50 million, equity of 250 million and EBITDA of 100 million. Lease capitalisation then adds 80 million of lease debt and replaces annual rent of 20 million with depreciation of 16 million and interest of 7 million. Cash and equity are unchanged. Using net debt equals debt minus cash, what are the new net debt to EBITDA ratio and the change in profit before tax?","choices":["2.75, and profit before tax falls by 3 million","3.30, and profit before tax rises by 20 million","2.50, and profit before tax falls by 3 million","2.75, and profit before tax rises by 4 million"],"correct_index":0,"explanation":"Net debt becomes 300 + 80 - 50 = 330. EBITDA becomes 100 + 20 = 120 because the rent disappears while depreciation and interest sit below EBITDA. The ratio is 330/120 = 2.75. Profit before tax changes by 20 - 16 - 7 = -3."},{"id":"cr-s16-level3-v1-q2","session":"16","level":3,"topic":"EBIT interest coverage ambiguity made explicit","question":"EBIT is 60 million euros after deducting rent of 15 million, and existing interest expense is 10 million. Lease capitalisation replaces the rent with depreciation of 12 million and adds lease interest of 6 million. Defining interest coverage as EBIT divided by total interest expense, what is coverage before and after?","choices":["6.0 before and 7.5 after","6.0 before and 3.9375 after","4.0 before and 6.0 after","6.0 before and 4.6875 after"],"correct_index":1,"explanation":"Before, coverage is 60/10 = 6. After, EBIT is 60 + 15 - 12 = 63 because the rent leaves operating expenses and only depreciation remains, while total interest is 10 + 6 = 16. Coverage falls to 63/16 = 3.9375 even though EBITDA improves."},{"id":"cr-s16-level3-v1-q3","session":"16","level":3,"topic":"Cash reclassification exact bridge","question":"Operating cash flow is 90 million euros after deducting rent of 30 million, and financing cash flow is minus 40 million. Under the company's policy the 30 million lease payment splits into principal of 24 million in financing and interest of 6 million in operating. What are the new operating and financing totals?","choices":["Operating 120 and financing minus 70","Operating 114 and financing minus 40, with 24 million of new cash created","Operating 114 and financing minus 64, with the combined total unchanged","Operating 90 and financing minus 64, cutting total cash by 24"],"correct_index":2,"explanation":"Only the principal of 24 leaves operating for financing: operating becomes 90 + 24 = 114 and financing becomes -40 - 24 = -64. The interest of 6 stays in operating under the stated policy. Combined cash flow is still 50. Classification moves cash between sections and does not create or destroy it."},{"id":"cr-s16-level3-v1-q4","session":"16","level":3,"topic":"Covenant scope versus headline leverage","question":"A loan covenant freezes the accounting definitions in force when it was signed and caps debt at 220 million euros. On those frozen definitions the borrower's debt stays at 200 million. IFRS 16 then adds 60 million of lease liabilities to reported debt. What is the position?","choices":["Reported debt is 260, covenant debt is 260, and the covenant is breached by 40","Reported debt is 200, covenant debt is 200, because the contract rewrites the IFRS total","Reported debt is 220, covenant debt is 220, because the cap sets the measurement","Reported debt is 260, covenant debt is 200, and this change alone causes no breach"],"correct_index":3,"explanation":"Two different questions are being answered. The financial statements follow IFRS 16 and show 260. The covenant follows its own frozen definitions and still shows 200, inside the 220 cap. A reporting change can raise headline leverage without triggering a frozen covenant."},{"id":"cr-s16-level3-v1-q5","session":"16","level":3,"topic":"Comparability avoids double capitalisation","question":"An analyst comparing legacy accounts routinely adds 80 million euros of estimated lease debt and adds back 20 million of rent to EBITDA. The company then adopts IFRS 16, so reported debt already includes the 80 and reported EBITDA no longer contains the 20 rent. The analyst repeats both old adjustments. What is the effect?","choices":["Adjusted debt is overstated by 80 and adjusted EBITDA is overstated by 20","Nothing is misstated, because comparable figures always need the same adjustments","Debt is overstated by 80 while EBITDA is unaffected, since rent can be added twice","Debt is understated by 80 and EBITDA is understated by 20"],"correct_index":0,"explanation":"After adoption the adjustments the analyst used to make are already inside the reported numbers. Adding the lease debt again counts the same obligation twice, and adding back rent that no longer sits in expenses inflates EBITDA. Comparability work must start from reconciled definitions."},{"id":"cr-s16-level3-v1-q6","session":"16","level":3,"topic":"Same EBITDA different profit patterns","question":"Two identical companies each capitalise a lease that replaces annual rent of 24 million euros with straight line depreciation of 20 million. Company A records lease interest of 8 million this year and Company B records 2 million. What happens to EBITDA and profit before tax in each company?","choices":["EBITDA rises 24 in both, and profit before tax falls 4 in both","EBITDA rises 24 in both, while profit before tax falls 4 in A and rises 2 in B","EBITDA rises 4 in A and 2 in B","Profit before tax rises 24 in both, because cash rent is unchanged"],"correct_index":1,"explanation":"Removing the rent lifts EBITDA by 24 in both, since depreciation and interest sit below EBITDA. Profit before tax changes by 24 - 20 - 8 = -4 in A but 24 - 20 - 2 = +2 in B. Interest is higher early in a lease and falls as the liability is repaid, so two otherwise identical leases can show opposite profit effects in the same year."},{"id":"cr-s16-level3-v1-q7","session":"16","level":3,"topic":"Lease versus service financing optics","question":"Two five-year contracts each reserve the whole capacity of a specified warehouse, with no substitution right. Under contract A, the customer decides the product mix, the timing and the destination of dispatches, while the supplier operates and maintains the building. Under contract B, the supplier makes those decisions to deliver an agreed storage service and the customer can only check service quality. Which contract contains a lease?","choices":["Both, because exclusive capacity in a specified building is reserved for five years in each","Neither, because the supplier operates and maintains both warehouses","A only, because its customer directs the relevant use decisions while B's customer receives a service","B only, because exclusive storage output gives its customer control of the building"],"correct_index":2,"explanation":"Operating and maintaining an asset is not the same as deciding how and for what purpose it is used. Under A the customer takes all capacity and makes the use decisions, so the contract contains a lease. Under B the supplier keeps those decisions and delivers an output, so the customer buys a service. Exclusive capacity alone is not enough for control."},{"id":"cr-s16-level3-v1-q8","session":"16","level":3,"topic":"Percentage leverage change","question":"A company reported debt to equity of 0.8 under the old lease rules. Capitalisation then adds 60 million of lease debt to existing debt of 160 million, with equity unchanged at 200 million. What are the new ratio and its percentage increase?","choices":["1.1 and a 30% increase","0.8 and a 37.5% increase","1.375 and a 60% increase","1.1 and a 37.5% increase"],"correct_index":3,"explanation":"New debt is 160 + 60 = 220, so the ratio is 220/200 = 1.1. The relative increase is (1.1 - 0.8)/0.8 = 37.5%. The ratio rises by 0.3 in absolute terms, which is not the same as a 30% increase."},{"id":"cr-s16-level3-v1-q9","session":"16","level":3,"topic":"Single model does not imply identical expense","question":"Two lessees each recognise a lease liability and a right of use asset of 100 million euros. The first lease runs 3 years, the second 5 years. Neither transfers ownership or holds a purchase option, and both use straight line depreciation. Both underlying assets have useful lives of at least five years. Ignoring interest, what annual depreciation does each record?","choices":["About 33.3 million for the first and 20 million for the second","20 million for both, because the initial liabilities are identical","33.3 million for both, because the single model imposes one pattern","Zero for both, because depreciation stays with the lessor until title passes"],"correct_index":0,"explanation":"With no ownership transfer or purchase option, the right of use asset is depreciated over the shorter of the asset useful life and lease term, which is the lease term here: 100/3 = 33.3 million and 100/5 = 20 million. The single recognition model does not make the annual charge uniform. The lease term still drives it."},{"id":"cr-s16-level3-v1-q10","session":"16","level":3,"topic":"ROA needs defined numerator and denominator","question":"Profit is 50 million euros and total assets are 400 million. Capitalisation adds 100 million of right of use assets and replaces rent of 20 million, already deducted in the 50, with depreciation of 18 and interest of 6. Ignoring tax and using closing assets, what is the new return on assets?","choices":["10.0%, with profit unchanged","9.2%, down from 12.5%","13.0%, because EBITDA rises by 20","11.5%, using the old asset base"],"correct_index":1,"explanation":"Adjusted profit is 50 + 20 - 18 - 6 = 46. Closing assets are 400 + 100 = 500. Return on assets is 46/500 = 9.2%, against 50/400 = 12.5% before. The numerator here is profit after depreciation and interest, so EBITDA or EBIT cannot be substituted."}],"17":[{"id":"cr-s17-level1-v1-q1","session":"17","level":1,"topic":"Initial ROU versus liability","question":"A lessee measures its initial lease liability at 80,000 euros. It pays 10,000 at commencement and incurs 2,000 of initial direct costs. There are no incentives, restoration costs or other adjustments. What is the initial cost of the right of use asset?","choices":["80,000 euros","90,000 euros","92,000 euros","78,000 euros"],"correct_index":2,"explanation":"The right of use asset costs 80,000 + 10,000 + 2,000 = 92,000. The 10,000 paid at commencement is not inside the liability, which only covers payments due after commencement, but it is part of the cost of the use right, as are the initial direct costs."},{"id":"cr-s17-level1-v1-q2","session":"17","level":1,"topic":"First year liability schedule","question":"A lease liability opens at 100,000 euros, the interest rate is 8% and a payment of 30,000 is made at year end. What is the closing liability?","choices":["70,000 euros","108,000 euros","62,000 euros","78,000 euros"],"correct_index":3,"explanation":"Interest of 8,000 accrues first, taking the liability to 108,000. The 30,000 payment then brings it down to 78,000. The payment covers both the interest and 22,000 of principal."},{"id":"cr-s17-level1-v1-q3","session":"17","level":1,"topic":"Timing at commencement","question":"A lease requires 20,000 euros immediately at commencement and another 20,000 in one year. The discount rate is 10% and there are no other payments or costs. Right after the commencement payment, what are the lease liability and the right of use asset?","choices":["Liability 18,181.82 and right of use asset 38,181.82","Liability 38,181.82 and right of use asset 38,181.82","Liability 40,000 and right of use asset 20,000","Liability 18,181.82 and right of use asset 18,181.82"],"correct_index":0,"explanation":"Only the payment due after commencement is discounted into the liability: 20,000/1.1 = 18,181.82. The 20,000 already paid is not a liability anymore. It is added to the right of use asset, which therefore starts at 20,000 + 18,181.82 = 38,181.82."},{"id":"cr-s17-level1-v1-q4","session":"17","level":1,"topic":"Depreciation period no title transfer","question":"A right of use asset costs 120,000 euros for a four year lease of a machine whose economic life is ten years. Ownership does not transfer, there is no purchase option, residual value is zero and depreciation is straight line. What is the annual depreciation?","choices":["12,000 euros","30,000 euros","120,000 euros","18,000 euros"],"correct_index":1,"explanation":"Without ownership transfer or a reasonably certain purchase option, depreciation runs over the shorter of useful life and lease term. Here four years is shorter than ten, so €120,000 ÷ 4 = €30,000 annually. Useful life is still relevant to the shorter-of test, even without title transfer."},{"id":"cr-s17-level1-v1-q5","session":"17","level":1,"topic":"Lease payment split","question":"At a payment date, a lessee pays 45,000 euros in cash on its lease. Interest accrued for the period is 9,000 and nothing else changes. By how much does the principal of the lease liability fall?","choices":["45,000 euros","54,000 euros","36,000 euros","9,000 euros"],"correct_index":2,"explanation":"The payment first covers the 9,000 of interest, and the remaining 45,000 - 9,000 = 36,000 reduces the principal. Interest expense and cash paid are not the same quantity."},{"id":"cr-s17-level1-v1-q6","session":"17","level":1,"topic":"Expected guarantee payout","question":"A lessee guarantees that the leased asset will be worth at least 30,000 euros at the end of the lease. The expected residual value is 24,000, so the expected payout under the guarantee is 6,000, due in two years. The discount rate is 10%. What amount for this guarantee enters the initial lease liability?","choices":["24,793.39 euros","30,000 euros","6,000 euros","4,958.68 euros"],"correct_index":3,"explanation":"The liability includes the amount expected to be paid under the guarantee, which is 6,000, discounted for two years: 6,000/1.1^2 = 4,958.68. The maximum guaranteed value of 30,000 and the expected resale value of 24,000 are not what the lessee expects to pay."},{"id":"cr-s17-level1-v1-q7","session":"17","level":1,"topic":"ROU impairment remains possible","question":"A right of use asset is carried at 70,000 euros and its recoverable amount is 62,000. The lease liability, measured separately, stands at 68,000. No modification, payment or remeasurement event occurs. What does impairment do?","choices":["The right of use asset falls by 8,000 and the lease liability is unchanged","Both the asset and the liability fall by 8,000 to keep them matched","No impairment is booked, because the 68,000 liability floors the recoverable amount","The asset falls by 2,000 only, capping the loss at the gap between asset and liability"],"correct_index":0,"explanation":"Under IAS 36 the loss is 70,000 - 62,000 = 8,000 and it reduces the asset. The obligation to pay the rentals still exists in full, so the liability does not move. A fall in the asset's recoverable amount does not cancel the debt."},{"id":"cr-s17-level1-v1-q8","session":"17","level":1,"topic":"Lessor operating lease depreciation","question":"A lessor keeps an operating leased asset that cost 60,000 euros, with a ten year useful life, a residual value of 10,000 and straight line depreciation. Annual rent is 9,000. Ignoring direct costs and taxes, what are the annual depreciation and the profit contribution?","choices":["Depreciation 6,000 and profit 3,000","Depreciation 5,000 and profit 4,000","Depreciation zero and profit 9,000","Depreciation 9,000 and profit zero"],"correct_index":1,"explanation":"The depreciable amount is 60,000 - 10,000 = 50,000, spread over ten years for 5,000 a year. Profit is rent of 9,000 minus depreciation of 5,000, giving 4,000. The rental price set in the contract does not drive the depreciation."},{"id":"cr-s17-level1-v1-q9","session":"17","level":1,"topic":"Lessor finance lease receivable","question":"A lessor's net investment in a finance lease opens at 200,000 euros, earns 5% and receives 60,000 at year end. What are the finance income and the closing net investment?","choices":["Income 60,000 and closing 200,000","Income 10,000 and closing 140,000","Income 10,000 and closing 150,000","Income zero and closing 140,000"],"correct_index":2,"explanation":"Finance income is 5% of 200,000 = 10,000, which grows the net investment to 210,000. The 60,000 receipt then reduces it to 150,000. The same constant rate logic applies as for the lessee's liability, just seen from the lessor's side."},{"id":"cr-s17-level1-v1-q10","session":"17","level":1,"topic":"Variable rent excluded not ignored","question":"A lease liability correctly excluded genuinely usage based rent at inception. During the year the lessee incurs 12,000 euros of that rent, paid immediately and not forming the cost of another asset. How is it accounted for?","choices":["As a liability settlement with no expense, because it relates to a lease","As a retrospective addition to the opening liability and the right of use asset","As an addition to the right of use asset, depreciated over the remaining term","As an expense of 12,000 in the period, even though it was never in the liability"],"correct_index":3,"explanation":"Variable payments outside the initial liability are not free forever. They become an expense in the period in which the usage occurs. Exclusion from the opening measurement simply reflects that no obligation existed at commencement."},{"id":"cr-s17-level2-v1-q1","session":"17","level":2,"topic":"Two year arrears PV","question":"A lease requires 55,000 euros at the end of each of the next two years and nothing else. The discount rate is 10%. What is the initial lease liability, to two decimals?","choices":["100,000 euros","110,000 euros","90,909.09 euros","95,454.55 euros"],"correct_index":3,"explanation":"Each payment is discounted for its own waiting period: 55,000/1.1 = 50,000 and 55,000/1.1^2 = 45,454.55. The liability is 95,454.55. Two equal payments at different dates do not have the same present value."},{"id":"cr-s17-level2-v1-q2","session":"17","level":2,"topic":"Two periods liability rollforward","question":"A lease liability starts at 95,454.55 euros, covering two annual payments of 55,000 in arrears at 10%. What is the liability right after the first year end payment?","choices":["50,000 euros","40,454.55 euros","55,000 euros","45,454.55 euros"],"correct_index":0,"explanation":"Year one interest is 10% of 95,454.55 = 9,545.45, bringing the balance to 105,000. The 55,000 payment leaves 50,000. Check: that 50,000 grows by 5,000 of year two interest and the final 55,000 settles it exactly."},{"id":"cr-s17-level2-v1-q3","session":"17","level":2,"topic":"Integrated initial ROU cost","question":"A lessee's initial lease liability is 150,000 euros. It also pays 20,000 at commencement, incurs 4,000 of initial direct costs, recognises a restoration obligation at a present value of 6,000, and has received a lease incentive of 3,000. None of these is inside the 150,000. What is the initial cost of the right of use asset?","choices":["183,000 euros","177,000 euros","171,000 euros","150,000 euros"],"correct_index":1,"explanation":"Cost is 150,000 + 20,000 + 4,000 + 6,000 - 3,000 = 177,000. The commencement payment, initial direct costs and restoration estimate all add to the asset, while the incentive received reduces it."},{"id":"cr-s17-level2-v1-q4","session":"17","level":2,"topic":"Advance payment and annual expense","question":"A three year lease requires 30,000 euros at commencement and 30,000 at the start of each of the next two years. Discounted at 10%, the liability right after the commencement payment is 52,066.12. There is no title transfer, purchase option or residual value, and depreciation is straight line. What are the year one depreciation and interest? The underlying useful life is at least as long as the remaining lease term, with no reasonably certain purchase option.","choices":["Depreciation 17,355.37 and interest 5,206.61","Depreciation 30,000 and interest 8,206.61","Depreciation 27,355.37 and interest 5,206.61","Depreciation 27,355.37 and interest 8,206.61"],"correct_index":2,"explanation":"The right of use asset is 52,066.12 + 30,000 = 82,066.12, depreciated over three years for 27,355.37 a year. Interest is 10% of the outstanding liability of 52,066.12, which is 5,206.61. Interest accrues on the liability, not on the larger asset figure."},{"id":"cr-s17-level2-v1-q5","session":"17","level":2,"topic":"Exempt lease straight line expense","question":"A lessee elects the short term exemption for a ten month lease with no purchase option. Total rent is 50,000 euros, of which 40,000 is paid at commencement and 10,000 at the end. The asset is used evenly. What rent expense is recognised after the first four months?","choices":["40,000 euros","10,000 euros","50,000 euros","20,000 euros"],"correct_index":3,"explanation":"Under the exemption the payments are expensed on a straight line basis over the lease term: 50,000/10 = 5,000 per month, so 20,000 after four months. Paying most of the cash up front does not accelerate the expense."},{"id":"cr-s17-level2-v1-q6","session":"17","level":2,"topic":"Lessor residual value component","question":"A finance lessor expects rentals of 40,000 euros in one year and 40,000 in two years, plus an unguaranteed residual value of 24,200 at the end of year two. Discounting at 10%, what is the initial net investment in the lease?","choices":["89,421.49 euros","69,421.49 euros","104,200 euros","93,621.49 euros"],"correct_index":0,"explanation":"The rentals are worth 40,000/1.1 + 40,000/1.1^2 = 69,421.49 and the residual is worth 24,200/1.1^2 = 20,000, for a net investment of 89,421.49. The unguaranteed residual belongs in the lessor's net investment even though no lessee will ever pay it as rent."},{"id":"cr-s17-level2-v1-q7","session":"17","level":2,"topic":"Useful life when ownership transfers","question":"A lease transfers ownership of the asset to the lessee at the end for no further consideration. The right of use asset costs 90,000 euros, the underlying asset's useful life is six years with zero residual value, the payment term is three years and depreciation is straight line. What is the annual depreciation?","choices":["30,000 euros","15,000 euros","90,000 euros","45,000 euros"],"correct_index":1,"explanation":"Because ownership transfers, the lessee will enjoy the asset for its whole six year useful life, not just the three payment years. Depreciation is 90,000/6 = 15,000 a year. The payment schedule and the consumption of the asset are different things."},{"id":"cr-s17-level2-v1-q8","session":"17","level":2,"topic":"Existing liability and principal CF","question":"A lease liability opens at 80,000 euros at 5%. The year end payment is 24,000 and there is no remeasurement. The company presents interest paid within financing activities, which IAS 7 permits. What are the closing liability and the total financing cash outflow for this payment? Apply IAS 7 before the IFRS 18 amendments, without early applying those amendments.","choices":["Closing 56,000 and financing outflow 20,000","Closing 60,000 and financing outflow 20,000","Closing 60,000 and financing outflow 24,000","Closing 84,000 and financing outflow 4,000"],"correct_index":2,"explanation":"Interest of 4,000 accrues, then the 24,000 payment leaves a liability of 80,000 + 4,000 - 24,000 = 60,000. The payment splits into 20,000 of principal and 4,000 of interest, and under the stated policy both are financing outflows, so the full 24,000 sits in financing."},{"id":"cr-s17-level2-v1-q9","session":"17","level":2,"topic":"ROU closing after impairment","question":"A right of use asset opens at 100,000 euros with four years remaining, no title transfer, zero residual and straight line depreciation. At year end, after the normal depreciation charge, the recoverable amount is 60,000. What are the closing carrying amount and the total asset related expense for the year? The underlying useful life is at least as long as the remaining lease term, with no reasonably certain purchase option.","choices":["Closing 60,000 and total expense 15,000","Closing 75,000 and total expense 25,000","Closing 35,000 and total expense 65,000","Closing 60,000 and total expense 40,000"],"correct_index":3,"explanation":"Depreciation of 100,000/4 = 25,000 takes the asset to 75,000. An impairment of 15,000 then brings it to the recoverable amount of 60,000. The year's total expense is 25,000 + 15,000 = 40,000, not just the impairment."},{"id":"cr-s17-level2-v1-q10","session":"17","level":2,"topic":"Index payments and true usage distinction","question":"For initial measurement, a lease's fixed and index linked payments have a combined present value of 70,000 euros using the commencement date index. A genuinely usage based component has a forecast present value of 15,000, with no minimum making it fixed in substance. What is the initial lease liability?","choices":["70,000 euros","85,000 euros","55,000 euros","15,000 euros"],"correct_index":0,"explanation":"The liability includes the fixed and index linked components at 70,000. The genuine usage component is excluded from the initial measurement and expensed as it arises. A forecast present value does not turn a true variable payment into a recognisable obligation."},{"id":"cr-s17-level3-v1-q1","session":"17","level":3,"topic":"PV ROU expense complete case","question":"A lease requires 50,000 euros at commencement and 55,000 at each of the next two year ends. The discount rate is 10%, initial direct costs are 3,000, a restoration obligation has a present value of 2,000, and there are no incentives, ownership transfer or purchase option. The use right lasts two years with zero residual and straight line depreciation. What are the initial liability, the right of use cost and the year one depreciation, to the nearest euro? The underlying useful life is at least as long as the remaining lease term, with no reasonably certain purchase option.","choices":["Liability 95,455, right of use 150,455, depreciation 75,227","Liability 145,455, right of use 150,455, depreciation 75,227","Liability 95,455, right of use 100,455, depreciation 50,227","Liability 110,000, right of use 165,000, depreciation 82,500"],"correct_index":0,"explanation":"Only the two future payments are discounted: 55,000/1.1 + 55,000/1.1^2 = 95,455. The right of use asset adds the 50,000 paid at commencement, the 3,000 of direct costs and the 2,000 of restoration, giving 150,455. Depreciation is 150,455/2 = 75,227. A payment already made is not an outstanding liability."},{"id":"cr-s17-level3-v1-q2","session":"17","level":3,"topic":"Year 2 cost pattern","question":"A lease liability and a right of use asset both open at 200,000 euros. Four annual year end payments of 60,000 are due, plus an additional fixed terminal payment of 14,360 at the end of year four, already included in the opening liability, the rate is 10%, depreciation is 50,000 a year and there is no impairment. What are the year two interest, the closing liability after the second payment and the combined year two depreciation plus interest?","choices":["Interest 20,000, closing 120,000, combined expense 70,000","Interest 16,000, closing 116,000, combined expense 66,000","Interest 14,000, closing 94,000, combined expense 64,000","Interest 16,000, closing 100,000, combined expense 60,000"],"correct_index":1,"explanation":"After year one the liability is 200,000 + 20,000 - 60,000 = 160,000. Year two interest is 10% of 160,000 = 16,000, and the second payment leaves 160,000 + 16,000 - 60,000 = 116,000. Adding the unchanged 50,000 of depreciation gives a combined 66,000, below the year one charge because interest falls as the balance shrinks. After four regular payments the remaining liability is 14,360, settled by the additional terminal payment. Thus the opening balance is consistent with all contractual cash flows."},{"id":"cr-s17-level3-v1-q3","session":"17","level":3,"topic":"Lessee versus lessor residual scope","question":"A finance lease has rental payments with a present value of 100,000 euros and an unguaranteed residual value accruing to the lessor with a present value of 25,000. There is no residual value guarantee, commencement payment, initial direct cost or other payment. Using the same appropriate discount rate, what are the initial lessee liability and the lessor net investment?","choices":["Both 125,000 euros","Both 100,000 euros","Lessee 100,000 and lessor 125,000 euros","Lessee 125,000 and lessor 100,000 euros"],"correct_index":2,"explanation":"The lessee owes only the rental payments, so its liability is 100,000. The lessor net investment also includes the unguaranteed residual value accruing to it, giving 100,000 + 25,000 = 125,000. The residual asset value is not a payment obligation of the lessee."},{"id":"cr-s17-level3-v1-q4","session":"17","level":3,"topic":"Initial recognition separate restoration liability","question":"A lease's initial rental liability is 120,000 euros, with a 10,000 prepayment at commencement and a restoration obligation at a present value of 8,000. No cash is paid for the restoration at commencement. Right after the prepayment, what are the right of use asset and the total of newly recognised liabilities?","choices":["Right of use 128,000 and liabilities 128,000","Right of use 138,000 and liabilities 138,000","Right of use 130,000 and liabilities 120,000","Right of use 138,000 and liabilities 128,000"],"correct_index":3,"explanation":"The asset is 120,000 + 10,000 + 8,000 = 138,000. The liabilities are the outstanding lease liability of 120,000 plus the separate restoration provision of 8,000, giving 128,000. The 10,000 already paid reduced cash and built the asset but is not an outstanding debt."},{"id":"cr-s17-level3-v1-q5","session":"17","level":3,"topic":"Operating lessor direct costs","question":"A lessor's operating leased asset cost 100,000 euros, with a ten year life, a residual value of 20,000 and straight line depreciation. Arranging the four year lease gives rise to 4,000 of initial direct costs. Annual rental income is 15,000. What are the year one profit contribution and the closing total carrying amount?","choices":["Profit 6,000 and carrying amount 95,000","Profit 7,000 and carrying amount 96,000","Profit 2,000 and carrying amount 91,000","Profit 15,000 and carrying amount 104,000"],"correct_index":0,"explanation":"Underlying depreciation is (100,000 - 20,000)/10 = 8,000. Under IFRS 16 the lessor adds initial direct costs to the carrying amount of the underlying asset and expenses them over the lease term: 4,000/4 = 1,000 a year. Profit is 15,000 - 8,000 - 1,000 = 6,000. The total carrying amount starts at 104,000 and falls by 9,000 of combined charges to 95,000."},{"id":"cr-s17-level3-v1-q6","session":"17","level":3,"topic":"Final payment including expected guarantee","question":"A lease liability opens its final year at 60,000 euros at 10%. The final settlement is fixed rent of 50,000 plus an expected residual value guarantee payment of 16,000 that was correctly included in the initial measurement. No estimate changes. What are the final year interest and the closing liability?","choices":["Interest 6,000 and closing 16,000","Interest 6,000 and closing zero","Interest 5,000 and closing minus 1,000","Interest 16,000 and closing 10,000"],"correct_index":1,"explanation":"The 60,000 balance grows by 6,000 of interest to 66,000. The final settlement pays 50,000 of rent plus the 16,000 guarantee payout, so the liability closes at exactly zero. The guarantee cash was inside the measurement all along and must be part of the final settlement, not left as a phantom balance."},{"id":"cr-s17-level3-v1-q7","session":"17","level":3,"topic":"ROU impairment and later depreciation","question":"A right of use asset opens at 120,000 euros with four years remaining, straight line, zero residual and no title transfer. At the end of year one, after depreciation, it is impaired to 60,000. The lease term does not change. What are the year one total asset expense and the annual depreciation afterwards? The underlying useful life is at least as long as the remaining lease term, with no reasonably certain purchase option.","choices":["Year one expense 30,000 and later depreciation 30,000","Year one expense 60,000 and later depreciation 15,000","Year one expense 60,000 and later depreciation 20,000","Year one expense 90,000 and later depreciation 10,000"],"correct_index":2,"explanation":"Year one depreciation of 120,000/4 = 30,000 leaves 90,000, then impairment of 30,000 brings the asset to 60,000, so the year one total is 60,000. The remaining 60,000 is then spread over the three remaining years, giving 20,000 a year, not the original 30,000."},{"id":"cr-s17-level3-v1-q8","session":"17","level":3,"topic":"Timing error two year arrears versus advance","question":"Two identical two year leases each require two payments of 55,000 euros at 10%. Lease A pays at each year end. Lease B pays at commencement and at the end of year one. What is the difference between the initial right of use costs, B minus A, to the nearest euro?","choices":["Zero, because the nominal cash totals are equal","55,000 euros","5,000 euros","9,545 euros"],"correct_index":3,"explanation":"A's cost is 55,000/1.1 + 55,000/1.1^2 = 95,455. B's cost is 55,000 + 55,000/1.1 = 105,000. The difference is 9,545, the time value of paying a year earlier. Equal nominal totals do not mean equal present values."},{"id":"cr-s17-level3-v1-q9","session":"17","level":3,"topic":"Profit and liability different movements","question":"A right of use asset costs 180,000 euros for a three year lease, straight line, no title transfer, zero residual. The lease liability opens at 150,000, accrues 8% during year one and a payment of 70,000 is made at year end. No impairment or remeasurement occurs. What are the year one total of depreciation plus interest, and the closing liability? The underlying useful life is at least as long as the remaining lease term, with no reasonably certain purchase option.","choices":["Expense 72,000 and closing liability 92,000","Expense 70,000 and closing liability 80,000","Expense 62,000 and closing liability 92,000","Expense 72,000 and closing liability 80,000"],"correct_index":0,"explanation":"Depreciation is 180,000/3 = 60,000. Interest is 8% of 150,000 = 12,000, so the total expense is 72,000. The liability moves to 150,000 + 12,000 - 70,000 = 92,000. Cash paid, expense recognised and principal repaid are three different quantities."},{"id":"cr-s17-level3-v1-q10","session":"17","level":3,"topic":"Recognised liability components dated separately","question":"A lease has two fixed year end payments, 44,000 euros at year one and 48,400 at year two, plus an expected residual value guarantee payout of 12,100 due at the end of year two. Discounting at 10%, with no other payments or costs, what are the initial liability and the closing liability after the year one payment?","choices":["Initial 80,000 and closing 44,000","Initial 90,000 and closing 55,000","Initial 104,500 and closing 70,950","Initial 90,000 and closing 46,000"],"correct_index":1,"explanation":"Present values are 44,000/1.1 = 40,000, 48,400/1.1^2 = 40,000 and 12,100/1.1^2 = 10,000, totalling 90,000. Year one interest of 9,000 brings it to 99,000, and the 44,000 payment leaves 55,000. Check: 55,000 grows by 5,500 and the final 60,500 of rent plus guarantee settles it."}],"18":[{"id":"cr-s18-level1-v1-q1","session":"18","level":1,"topic":"Airline adoption balance sheet","question":"On adoption, an airline recognises right of use aircraft assets of 180 million euros, current lease liabilities of 30 million and non current lease liabilities of 155 million. Ignoring tax and all other adjustments, what happens to equity?","choices":["Equity rises by 180 million","Equity is unchanged, because adoption is a non cash event","Equity falls by 5 million","Equity falls by 185 million"],"correct_index":2,"explanation":"Assets rise by 180 and liabilities by 30 + 155 = 185. The balancing figure is a 5 million fall in equity. A non cash accounting change can still move equity whenever the asset and liability adjustments differ."},{"id":"cr-s18-level1-v1-q2","session":"18","level":1,"topic":"Airline profit bridge","question":"An airline removes legacy rental expense of 60 million euros and instead records right of use depreciation of 50 million and lease interest of 14 million. Ignoring tax, what is the change in profit before tax?","choices":["An increase of 60 million","An increase of 10 million","A decrease of 14 million","A decrease of 4 million"],"correct_index":3,"explanation":"The change is 60 - 50 - 14 = -4. The rental saving must be compared with both replacement charges together. Looking at depreciation alone, or at EBITDA, would miss the interest."},{"id":"cr-s18-level1-v1-q3","session":"18","level":1,"topic":"EBITDA numerical comparison","question":"An airline's EBITDA was 120 million euros under the old lease rules. Capitalisation removes annual rental expense of 30 million from EBITDA, and every replacement charge is depreciation or interest. What is the new EBITDA, and what does it say about cash generation?","choices":["EBITDA is 150 million, with no proof of any additional cash generation","EBITDA is 150 million, showing 30 million of extra operating cash","EBITDA is 90 million, because the new depreciation reduces the metric","EBITDA is 120 million, because the removed rent is offset inside the metric"],"correct_index":0,"explanation":"Removing the rent adds 30 to EBITDA while the new depreciation and interest sit outside it, giving 150. The contracted cash payments did not change, so the higher metric reflects presentation, not extra cash."},{"id":"cr-s18-level1-v1-q4","session":"18","level":1,"topic":"Gearing unit versus relative percent","question":"An airline's debt to equity ratio was 1.0 before adoption and 1.25 after. What is the relative increase in the ratio?","choices":["0.25%","25%","125%","20%"],"correct_index":1,"explanation":"The relative change is (1.25 - 1.0)/1.0 = 25%. The ratio rose by 0.25 in absolute terms, which is not 0.25%, and 1.25 is the new level, not the size of the increase."},{"id":"cr-s18-level1-v1-q5","session":"18","level":1,"topic":"Cash flows do not improve in total","question":"Adoption reclassifies 20 million euros of an airline's lease payments from operating to financing outflows. Everything else is unchanged. What happens to total net cash flow?","choices":["It rises by 20 million","It falls by 20 million","Nothing, although operating cash flow improves by 20 million","It rises by 40 million, because two categories change"],"correct_index":2,"explanation":"Operating cash flow gains 20 and financing cash flow loses the same 20, so the sum is flat. A better looking operating section is not a new source of cash."},{"id":"cr-s18-level1-v1-q6","session":"18","level":1,"topic":"Current ratio airline","question":"An airline has current assets of 240 million euros and current liabilities of 160 million. Adoption adds current lease liabilities of 40 million, with no change in current assets. What is the new current ratio?","choices":["1.5","0.8333","2.0","1.2"],"correct_index":3,"explanation":"Current liabilities become 160 + 40 = 200, so the ratio is 240/200 = 1.2, down from 1.5. The newly recognised right of use aircraft are non current assets and do not enter the numerator."},{"id":"cr-s18-level1-v1-q7","session":"18","level":1,"topic":"Residual contractual risk remains distinct","question":"An airline returns a leased aircraft at the end of the term. It gave no residual value guarantee, so the lessor bears any shortfall when the aircraft is sold. Adopting IFRS 16 did not amend the contract. Which distinction matters?","choices":["The airline's right of use asset can still be impaired, while the resale shortfall stays with the lessor","Recognising the right of use asset makes the airline responsible for resale shortfalls","Impairment of the right of use asset reduces the fixed lease payments without any amendment","The fixed rentals remove both impairment risk and resale exposure from the deal"],"correct_index":0,"explanation":"Two different risks are in play. The recoverability of the airline's own use right is an IAS 36 question for the airline. The residual value of the aircraft belongs to the lessor, which owns it. Recognising an asset does not rewrite the contract's risk allocation."},{"id":"cr-s18-level1-v1-q8","session":"18","level":1,"topic":"Short term label not enough","question":"An airline signs a two year enforceable aircraft lease and is invoiced monthly. There are no options and the aircraft is not low value. Does the monthly invoicing make the short term exemption available?","choices":["Yes, monthly invoicing resets the contract term to one month","No, the two year lease term is unaffected by how often invoices arrive","Yes, small monthly amounts make the aircraft a low value asset","No, but only because the short term ceiling is twenty four months"],"correct_index":1,"explanation":"Exemption eligibility depends on the lease term and the nature of the asset, not on billing frequency. The term is two years, above the twelve month ceiling, and an aircraft is not a low value asset, so the lease must be capitalised."},{"id":"cr-s18-level1-v1-q9","session":"18","level":1,"topic":"Genuine usage based aircraft rent","question":"An aircraft lease requires a fixed rent plus a genuine fee per flight hour, not linked to any index or rate, with no minimum amount. Which component stays out of the initial lease liability?","choices":["Both, because all payments depend on the aircraft keeping flying","Neither, the forecast flight hour fees are included at present value","The flight hour fee only, not the fixed rent","The fixed rent only, because usage fees track the asset's benefits"],"correct_index":2,"explanation":"Fixed commitments go into the liability. A genuine per hour fee with no floor does not, because no obligation exists until the hours are flown. Those fees still hit profit as they are incurred, so they matter commercially even though they never sit in the liability."},{"id":"cr-s18-level1-v1-q10","session":"18","level":1,"topic":"Survey statistics do not describe every airline","question":"A study reports a median debt increase of 40% across a sample of airlines after lease capitalisation. One airline's own careful measurement gives 20%. How should this be read?","choices":["Apply the 40% median to that airline as the sector standard adjustment","Apply 30%, splitting the difference between the estimate and the median","Use the airline's 20% but book the 20 point gap as an adoption expense","Use the airline's supported 20% figure instead of replacing it with the sample median"],"correct_index":3,"explanation":"A median describes a distribution of firms. It is not a mandated measurement for any one of them. Sitting below the median is not a contradiction. The airline's own lease portfolio determines its own increase."},{"id":"cr-s18-level2-v1-q1","session":"18","level":2,"topic":"Income and EPS bridge","question":"An airline's legacy profit before tax of 100 million euros is stated after rent of 50 million. Capitalisation removes that rent and adds depreciation of 42 million and interest of 12 million. With 20 million shares and no tax, what are the new profit and EPS?","choices":["Profit 108 million and EPS 5.4 euros","Profit 150 million and EPS 7.5 euros","Profit 96 million and EPS 5.0 euros","Profit 96 million and EPS 4.8 euros"],"correct_index":3,"explanation":"New profit is 100 + 50 - 42 - 12 = 96. EPS is 96/20 = 4.8 euros. A strong EBITDA bridge does not stop earnings per share from falling when the replacement charges exceed the old rent."},{"id":"cr-s18-level2-v1-q2","session":"18","level":2,"topic":"Operating CF bridge with operating interest","question":"An airline's old operating cash flow of 200 million euros is stated after lease rent of 48 million. Under the new rules the same 48 of cash splits into principal of 36 and interest of 12, and the company's permitted IAS 7 policy keeps interest in operating activities. What is the new operating cash flow? Apply IAS 7 before the IFRS 18 amendments, without early applying those amendments.","choices":["236 million euros","248 million euros","200 million euros","212 million euros"],"correct_index":0,"explanation":"Only the principal of 36 leaves operating activities for financing. The interest of 12 stays in operating under the stated policy. Operating cash flow is therefore 200 + 36 = 236, not the 248 it would be if the whole payment had left."},{"id":"cr-s18-level2-v1-q3","session":"18","level":2,"topic":"Debt EBITDA both rise","question":"Before adoption an airline has debt of 300 million euros and EBITDA of 100 million. Adoption adds lease debt of 120 million and raises EBITDA by 40 million, with no other changes. What happens to the gross debt to EBITDA multiple?","choices":["It rises to 4.2, adding the lease debt to the old figures","It stays at 3.0, the same as before adoption","It falls to about 2.14, updating only EBITDA","It rises to 4.0, adding the EBITDA increase to the old multiple"],"correct_index":1,"explanation":"Debt becomes 420 and EBITDA becomes 140, and 420/140 = 3.0, exactly the old 300/100. Both numerator and denominator can grow while the multiple stays put, so a stable ratio here does not mean nothing changed."},{"id":"cr-s18-level2-v1-q4","session":"18","level":2,"topic":"Asset turnover and fleet unchanged","question":"An airline's revenue of 1,200 million euros is unchanged, but closing total assets rise from 800 to 1,000 million because of lease capitalisation. Using closing assets, what are the old and new asset turnover ratios?","choices":["1.2 before and 1.5 after","1.5 before and 1.5 after, because the fleet is unchanged","1.5 before and 1.2 after","0.6667 before and 0.8333 after, because the ratio is assets over revenue"],"correct_index":2,"explanation":"Asset turnover is revenue over assets: 1,200/800 = 1.5 before and 1,200/1,000 = 1.2 after. The airline flies exactly the same routes. The ratio fell only because the balance sheet grew."},{"id":"cr-s18-level2-v1-q5","session":"18","level":2,"topic":"Net debt and equity changes","question":"An airline reports debt of 400 million euros, cash of 100 million and equity of 300 million before adoption. Lease recognition adds debt of 150 million and reduces equity by 10 million, with cash unchanged. Defining gearing as net debt over equity, what is the new gearing to three decimals?","choices":["1.500","1.897","1.000","1.552"],"correct_index":3,"explanation":"Net debt is 400 + 150 - 100 = 450 and equity is 300 - 10 = 290. Gearing is 450/290 = 1.552. Keeping the old equity of 300 would understate the ratio at 1.500 and miss the adoption adjustment."},{"id":"cr-s18-level2-v1-q6","session":"18","level":2,"topic":"Current and noncurrent debt reconciled","question":"On adoption an airline recognises right of use assets of 240 million euros and lease liabilities of 50 million current plus 200 million non current. Ignoring tax and everything else, what are the total liability and equity adjustments?","choices":["Liabilities rise 250 million and equity falls 10 million","Liabilities rise 200 million and equity rises 40 million","Liabilities rise 50 million and equity rises 190 million","Liabilities rise 250 million and equity rises 240 million"],"correct_index":0,"explanation":"Total new liabilities are 50 + 200 = 250. The equity bridge is assets of 240 minus liabilities of 250, a fall of 10. The current portion is part of the 250, not an extra layer on top of the non current 200."},{"id":"cr-s18-level2-v1-q7","session":"18","level":2,"topic":"EBITDAR definition avoids inconsistent addback","question":"An airline reports IFRS 16 EBITDA of 180 million euros, which already contains no rent for its capitalised leases. A data feed still lists the old equivalent rent of 40 million, and an analyst adds that 40 back on top to build a comparable EBITDA. What is the result?","choices":["No misstatement, the old adjustment always applies","EBITDA overstated by 40 million, adding back rent that is no longer deducted","EBITDA understated by 40 million, because the addback works as a deduction","EBITDA overstated by 80 million, counting both effects twice"],"correct_index":1,"explanation":"Under IFRS 16 the rent is already gone from EBITDA, replaced by depreciation and interest that sit below it. Adding the old 40 back again double counts the same adjustment and overstates the metric by 40."},{"id":"cr-s18-level2-v1-q8","session":"18","level":2,"topic":"Airline ROU impairment earnings","question":"An airline's right of use aircraft assets are carried at 300 million euros and a supported test gives a recoverable amount of 270 million. The lease liabilities stand at 320 million, with no modification or remeasurement event. What expense and liability reduction follow?","choices":["Expense 30 million and liability reduction 30 million","Expense 50 million and liability reduction 50 million","Expense 30 million and no automatic liability reduction","No expense, because the airline does not own the aircraft"],"correct_index":2,"explanation":"The impairment reduces the right of use asset by 300 − 270 = 30 million. The contractual liability stays at 320 million because no remeasurement event occurs. Asset recoverability and the obligation to pay rentals are separate assessments. This accounting difference does not itself establish who bears every economic risk under the contract."},{"id":"cr-s18-level2-v1-q9","session":"18","level":2,"topic":"Year specific profit effect","question":"An airline replaces annual rent of 30 million euros with right of use depreciation of 24 million. Lease interest is 9 million in year one and 4 million in year three. Everything else is unchanged. What is the effect on profit before tax in each year?","choices":["Both years fall by 3 million","Both years rise by 6 million","Year one rises 9 million and year three rises 4 million","Year one falls 3 million and year three rises 2 million"],"correct_index":3,"explanation":"Year one: 30 - 24 - 9 = -3. Year three: 30 - 24 - 4 = +2. Interest declines as the liability is repaid, so the same lease is a drag on profit early and a boost later. One adoption year cannot prove a permanent direction."},{"id":"cr-s18-level2-v1-q10","session":"18","level":2,"topic":"EPS percentage versus absolute change","question":"An airline's EPS falls from 2.50 euros under the old rules to 2.40 after capitalisation. What are the absolute and relative changes?","choices":["A decrease of 0.10 euros and 4%","A decrease of 0.10 euros and 0.10%","A decrease of 2.40 euros and 96%","An increase of 0.10 euros and 4%"],"correct_index":0,"explanation":"The absolute change is 2.40 - 2.50 = -0.10 euros. The relative decline is 0.10/2.50 = 4%. The fact that the new EPS equals 96% of the old one is the remaining level, not the size of the fall."},{"id":"cr-s18-level3-v1-q1","session":"18","level":3,"topic":"Integrated airline balance income cash case","question":"On adoption an airline recognises right of use assets of 190 million euros and lease liabilities of 200 million, with no tax or other balance sheet effect. During the year, rent of 50 million is replaced by depreciation of 43 million and interest of 12 million, and the same 50 of cash splits into principal of 38 and interest of 12 kept in operating activities. What are the changes in equity, profit before tax and operating cash flow?","choices":["Equity falls 10, profit falls 5, operating cash flow rises 38","Equity unchanged, profit rises 50, operating cash flow rises 50","Equity falls 10, profit rises 7, operating cash flow rises 38","Equity rises 190, profit falls 5, total cash rises 38"],"correct_index":0,"explanation":"The balance sheet bridge is 190 - 200 = -10 in equity. Profit changes by 50 - 43 - 12 = -5. Only the principal of 38 moves from operating to financing, while the interest of 12 stays in operating. Each statement tells a different part of the story and none of them offsets another."},{"id":"cr-s18-level3-v1-q2","session":"18","level":3,"topic":"Debt ratio and EBITDA growth together","question":"An airline has debt of 500 million euros and EBITDA of 125 million. Adoption adds lease debt of 200 million and removes rent of 50 million from EBITDA. What are the old and new debt to EBITDA multiples and the relative increase in debt?","choices":["Old 4.0, new 5.6, debt up 40%","Both multiples 4.0, debt up 40%","Old 4.0, new 2.857, debt up 20%","Both multiples 4.0, so no real liability was added"],"correct_index":1,"explanation":"Old multiple 500/125 = 4.0. New debt is 700 and new EBITDA is 175, giving 700/175 = 4.0 again. Debt still rose by 200/500 = 40% and EBITDA happened to grow by the same 40%. A stable multiple does not mean the balance sheet is unchanged or the risk identical."},{"id":"cr-s18-level3-v1-q3","session":"18","level":3,"topic":"Remeasurement versus reporting only judgement","question":"An airline carries a right of use asset at 90 million euros and the related lease liability at 100 million. An IAS 36 test writes the asset down by 20 million. Rentals, term and discount rate are all unchanged and no remeasurement event occurs. What are the carrying amounts after the test?","choices":["Asset 70 million and liability 80 million","Asset 70 million and liability 70 million","Asset 70 million and liability 100 million","Asset 90 million and liability 100 million"],"correct_index":2,"explanation":"The impairment cuts the asset from 90 to 70. The liability still measures the present value of the same unchanged contractual payments, so it stays at 100. Asset recoverability and liability measurement follow different rules and do not move together."},{"id":"cr-s18-level3-v1-q4","session":"18","level":3,"topic":"Covenant frozen versus floating definitions","question":"An airline has equity of 200 million euros, and reported debt rises from 180 to 260 million on adoption, with equity unchanged. Covenant A tests current reported debt against a 1.2 debt to equity maximum. Covenant B freezes the pre adoption definitions and tests the same maximum. What is the outcome?","choices":["Both ratios are 1.3 and both covenants are breached","Neither is breached, because adoption debt is non cash and excluded","Covenant A shows 0.9 and passes, covenant B shows 1.3 and breaches","Covenant A shows 1.3 and breaches, covenant B shows 0.9 and passes"],"correct_index":3,"explanation":"Covenant A uses reported debt: 260/200 = 1.3, above its 1.2 cap. Covenant B uses the frozen definitions: 180/200 = 0.9, comfortably inside. The same published statements produce opposite outcomes because the two contracts define debt differently."},{"id":"cr-s18-level3-v1-q5","session":"18","level":3,"topic":"Fixed versus variable commercial response","question":"An airline compares two leases with the same capacity and term. Lease A has fixed rentals and an initial liability of 120 million euros. Lease B has only genuine usage based rentals with no minimum, and higher expected total cash payments. Which comparison is right?","choices":["B shows lower initial recognised debt, but its higher expected cash cost means the debt figure says nothing about economic cost","B shows lower initial recognised debt and lower expected cash cost, because excluded payments leave the lease economics","B shows higher initial recognised debt and higher cash cost, because expected usage rentals enter debt at forecast value","B shows the same initial debt as A, because equal capacity and term create equal obligations"],"correct_index":0,"explanation":"B's usage rentals stay out of the initial liability, so its recognised debt is lower than A's 120. But the airline still expects to pay more cash under B. Recognised debt measures a contractual obligation, not the full expected cost of the arrangement."},{"id":"cr-s18-level3-v1-q6","session":"18","level":3,"topic":"Fleet mix weighted versus simple average","question":"Two airlines operate fleets of 100 and 300 aircraft. Their former operating leased fleets are 50 and 60 aircraft. Counting each aircraft equally, what share of the combined fleet was operating leased?","choices":["35%","27.5%","36.67%","20%"],"correct_index":1,"explanation":"Combined leased aircraft are 50 + 60 = 110 out of a combined fleet of 400, giving 27.5%. Averaging the two company percentages, (50% + 20%)/2 = 35%, ignores that the second fleet is three times larger."},{"id":"cr-s18-level3-v1-q7","session":"18","level":3,"topic":"Comparable historical margin reconstruction","question":"An airline reports IFRS 16 EBITDA of 210 million euros on revenue of 1,000 million. To rebuild an old style comparable figure, an analyst subtracts the 60 million of equivalent rent that no longer sits in the metric. What are the reported and reconstructed EBITDA margins?","choices":["21% and 27%","15% and 21%","21% and 15%","21% and 21%, because revenue did not change"],"correct_index":2,"explanation":"The reported margin is 210/1,000 = 21%. The reconstructed old basis margin is (210 - 60)/1,000 = 15%. Moving from a capitalised metric back to a rent expense basis means subtracting, not adding, the rent."},{"id":"cr-s18-level3-v1-q8","session":"18","level":3,"topic":"Leverage increase with equity loss","question":"An airline's old debt of 300 million euros and equity of 250 million give a debt to equity ratio of 1.2. Adoption adds 120 million of debt and reduces equity by 10 million. What are the new ratio and its relative increase?","choices":["1.68 and 40%","1.75 and 55%","1.20 and 45.83%","1.75 and 45.83%"],"correct_index":3,"explanation":"New debt is 420 and new equity is 240, so the ratio is 1.75. The relative increase is (1.75 - 1.2)/1.2 = 45.83%. Debt alone rose 40%, and the equity loss pushes the ratio up by more than that."},{"id":"cr-s18-level3-v1-q9","session":"18","level":3,"topic":"Complete cash flow reconciliation two policies","question":"An airline's old operating cash flow of 100 million euros and financing outflow of 40 million include rent of 36 million inside operating. On capitalisation that 36 splits into principal of 28 and interest of 8, and the IAS 7 rules before the IFRS 18 amendments permit either classification of interest paid. Compare policy O, interest in operating, with policy F, interest in financing. What operating cash flows and combined operating plus financing totals result?","choices":["Operating 128 under O and 136 under F, combined 60 under both","Operating 136 under both, combined 96 under both","Operating 128 under O and 136 under F, combined 60 under O and 68 under F","Operating 100 under O and 128 under F, combined 60 under O and 32 under F"],"correct_index":0,"explanation":"Under O only the principal of 28 leaves operating: 100 + 28 = 128, with financing at -40 - 28 = -68. Under F the whole 36 leaves: 100 + 36 = 136, with financing at -76. The combined total is 60 either way, because the real cash paid never depended on the policy. The policy choice here is the historical IAS 7 treatment, not the amended IFRS 18 classification requirements."},{"id":"cr-s18-level3-v1-q10","session":"18","level":3,"topic":"Profit decline attribution versus cash myth","question":"An airline's profit before tax falls from 100 to 60 million euros year on year. A controlled comparison shows the lease accounting change alone accounts for 5 million of that fall, the effects are additive and there is no tax. What share of the decline comes from the accounting change, and what must not be concluded?","choices":["100%, because adoption in the same year proves it caused the whole decline","12.5%, and no additional cash payment follows from the accounting alone","5%, and the 5 million effect creates an equal extra cash payment","12.5%, and the other 35 million must come from factors that improved profit"],"correct_index":1,"explanation":"The accounting component is 5 out of an observed 40 decline, which is 12.5%. The remaining 35 comes from other operating factors in this simplified bridge. A same year coincidence is not causation on its own, and an accounting measurement is not a cash payment."}],"19":[{"id":"cr-s19-level1-v1-q1","session":"19","level":1,"topic":"Permanent adjustment signs","question":"Accounting profit before tax is 200,000 euros, after deducting a non deductible fine of 10,000 and including tax exempt interest of 5,000. There are no temporary differences and the tax rate is 25%. What are taxable profit and current tax?","choices":["Taxable profit 185,000 and current tax 46,250","Taxable profit 215,000 and current tax 53,750","Taxable profit 205,000 and current tax 51,250","Taxable profit 200,000 and current tax 50,000"],"correct_index":2,"explanation":"Add the fine back and remove the exempt interest: 200,000 + 10,000 - 5,000 = 205,000. Current tax is 25% of that, 51,250. The two permanent adjustments work in opposite directions, and both signs matter."},{"id":"cr-s19-level1-v1-q2","session":"19","level":1,"topic":"Permanent difference is not future deduction","question":"A business incurs a fine of 20,000 euros that tax law states is never deductible. Management expects plenty of future taxable profit. At a 30% tax rate, what deferred tax asset does the fine create?","choices":["6,000, treating the fine as deductible when paid","20,000, using the expense itself instead of its tax effect","6,000, because available future profit supports the deduction","Zero, because no future tax deduction exists for this item"],"correct_index":3,"explanation":"Future profitability cannot create a deduction the law never grants. A permanent difference never reverses, so no deferred tax asset exists at any tax rate. The 30% rate and the expected profits are distractors."},{"id":"cr-s19-level1-v1-q3","session":"19","level":1,"topic":"Asset carrying versus tax base","question":"A machine's carrying amount is 90,000 euros and its tax base is 60,000. Recovering the asset will produce taxable benefits, no recognition exception applies and the tax rate is 20%. What deferred tax follows?","choices":["A deferred tax liability of 6,000","A deferred tax asset of 6,000","A deferred tax liability of 30,000","None, because the asset has not been sold"],"correct_index":0,"explanation":"The carrying amount exceeds the tax base by 30,000, a taxable temporary difference: accounting has deducted less than tax so far, so more tax comes later. At 20% the deferred tax liability is 6,000. Recognition does not wait for the sale. The future tax consequence is booked now."},{"id":"cr-s19-level1-v1-q4","session":"19","level":1,"topic":"Warranty liability deductible later","question":"A warranty provision is carried at 40,000 euros and will be fully deductible for tax only when paid, so its tax base is zero. Future taxable profit is probable and the rate is 25%. What deferred tax follows?","choices":["A deferred tax liability of 10,000","A deferred tax asset of 10,000","A deferred tax asset of 40,000","Zero, because a zero tax base means no difference"],"correct_index":1,"explanation":"Settling the 40,000 liability will generate a future tax deduction of the same amount, a deductible temporary difference of 40,000. At 25% the deferred tax asset is 10,000, recognised because recovery is probable."},{"id":"cr-s19-level1-v1-q5","session":"19","level":1,"topic":"Receivable already taxed","question":"Trade receivables are carried at 75,000 euros. The related revenue has already been taxed in full, the tax base is 75,000, and there is no doubtful debt allowance. The tax rate is 30%. What deferred tax arises on these receivables?","choices":["A deferred tax liability of 22,500, because collection is a second taxable event","A deferred tax asset of 22,500, because the future receipt is a deduction","Zero, because the carrying amount equals the tax base","A current tax receivable of 22,500"],"correct_index":2,"explanation":"Carrying amount and tax base are both 75,000, so the temporary difference is zero. The revenue was taxed already, and collecting the cash will not be taxed again. No deferred tax arises."},{"id":"cr-s19-level1-v1-q6","session":"19","level":1,"topic":"Cash taxed before book revenue","question":"A company receives 30,000 euros that tax law taxes immediately, while accounting holds it as a contract liability until the service is performed next year. The liability's tax base is zero because the future revenue will not be taxed again. Recognition conditions are met and the rate is 20%. What deferred tax follows?","choices":["A deferred tax liability of 6,000","A deferred tax asset of 30,000","Zero, because the tax has already been paid","A deferred tax asset of 6,000"],"correct_index":3,"explanation":"The liability of 30,000 will unwind into accounting revenue that is never taxed again, giving a future deduction effect: a deductible temporary difference of 30,000 and a deferred tax asset of 20% of 30,000 = 6,000. Having paid current tax does not cancel the future benefit."},{"id":"cr-s19-level1-v1-q7","session":"19","level":1,"topic":"Future taxable profit recognition limit","question":"A deductible temporary difference of 50,000 euros could generate a tax benefit at 20%. Only 30,000 of qualifying future taxable profit is probable within the usable period, and no other recovery source exists. What deferred tax asset is recognised?","choices":["6,000, limited to the deduction backed by probable future taxable profit","10,000, recognising the whole potential deduction anyway","30,000, treating the probable taxable profit itself as the asset","Zero, because partial recovery is not allowed"],"correct_index":0,"explanation":"A deferred tax asset is recognised only to the extent that future taxable profit will probably absorb it. The usable deduction is 30,000, so the asset is 30,000 × 20% = 6,000. Partial support means partial recognition, not all or nothing."},{"id":"cr-s19-level1-v1-q8","session":"19","level":1,"topic":"No discounting even long dated","question":"A taxable temporary difference of 100,000 euros will reverse in ten years. The enacted rate for that period is 25% and all recognition criteria are met. What deferred tax liability does IAS 12 require?","choices":["The present value of 25,000 discounted over ten years","25,000 euros, undiscounted","100,000 euros, matching the difference itself","Zero until the tenth year"],"correct_index":1,"explanation":"IAS 12 measures deferred tax at the nominal amount using the enacted reversal rate: 100,000 × 25% = 25,000, with no discounting however distant the reversal. An analyst's economic present value is a different concept."},{"id":"cr-s19-level1-v1-q9","session":"19","level":1,"topic":"Tax expense versus current payable","question":"Current tax expense is 45,000 euros. A deferred tax liability linked to profit grows by 8,000 during the year, with no other tax movements. What is the total tax expense?","choices":["37,000, treating the liability increase as a benefit","45,000, because deferred movements stay out of the total","53,000, adding the deferred increase to current tax","8,000, recognising only the deferred movement"],"correct_index":2,"explanation":"Total tax expense is 45,000 + 8,000 = 53,000. An increase in a deferred tax liability is an expense of the period even though the extra tax is not payable yet. That is the whole point of deferred tax: the charge follows accounting profit, not the cash calendar."},{"id":"cr-s19-level1-v1-q10","session":"19","level":1,"topic":"Expense and cash timing","question":"Current tax expense for the year is 60,000 euros. Tax instalments of 50,000 were paid during the year and the opening current tax payable was zero. What is the closing current tax payable?","choices":["60,000 euros","50,000 euros","110,000 euros","10,000 euros"],"correct_index":3,"explanation":"The year's charge is 60,000 and 50,000 of it has been paid, leaving 10,000 unpaid at year end. Expense, cash paid and closing liability are three different measures that reconcile but rarely coincide."},{"id":"cr-s19-level2-v1-q1","session":"19","level":2,"topic":"Current and deferred with accelerated tax depreciation","question":"Accounting profit is 100,000 euros after book depreciation of 10,000. Tax depreciation is 25,000, there are no permanent differences, the rate is 30% and opening deferred tax is zero. What are taxable profit, current tax and deferred tax expense?","choices":["Taxable 115,000, current 34,500, deferred benefit 4,500","Taxable 85,000, current 25,500, deferred benefit 4,500","Taxable 100,000, current 30,000, no deferred tax","Taxable 85,000, current 25,500, deferred expense 4,500"],"correct_index":3,"explanation":"Add back book depreciation and deduct the tax figure: 100,000 + 10,000 - 25,000 = 85,000 of taxable profit, so current tax is 25,500. The 15,000 of excess tax depreciation is a taxable temporary difference creating a deferred tax liability of 4,500. Total tax expense is 30,000, exactly 30% of accounting profit, as expected with no permanent differences."},{"id":"cr-s19-level2-v1-q2","session":"19","level":2,"topic":"Unpaid expense current tax bridge","question":"Accounting profit of 80,000 euros includes a warranty expense of 20,000 that is deductible for tax only when paid. Nothing is paid this year, there is no opening provision or deferred tax, the rate is 25% and recoverability is probable. What are current tax, deferred tax and total tax expense?","choices":["Current 25,000, deferred benefit 5,000, total expense 20,000","Current 20,000, deferred expense 5,000, total 25,000","Current 25,000, deferred expense 5,000, total 30,000","Current 15,000, deferred benefit 5,000, total 10,000"],"correct_index":0,"explanation":"The warranty is not yet deductible, so taxable profit is 80,000 + 20,000 = 100,000 and current tax is 25,000. The future deduction creates a deferred tax asset of 20,000 × 25% = 5,000, a benefit. Total tax expense is 25,000 - 5,000 = 20,000, matching 25% of accounting profit."},{"id":"cr-s19-level2-v1-q3","session":"19","level":2,"topic":"Gross assets and liabilities cannot be conflated","question":"A machine is carried at 140,000 euros with a tax base of 100,000. A warranty liability is carried at 30,000 with a tax base of zero, deductible when settled. The rate is 20% and full recognition applies. Before any permitted offset, what are the gross deferred tax balances?","choices":["A liability of 2,000 and no asset, because gross means net","A liability of 8,000 and an asset of 6,000","An asset of 8,000 and a liability of 6,000","A liability of 34,000 and an asset of 6,000"],"correct_index":1,"explanation":"The machine's carrying amount exceeds its tax base by 40,000, a taxable difference giving a liability of 8,000. The warranty liability gives a deductible difference of 30,000 and an asset of 6,000. Gross presentation keeps both. Offsetting is a separate question with its own conditions."},{"id":"cr-s19-level2-v1-q4","session":"19","level":2,"topic":"Tax base of unpaid accrued expense","question":"An accrued expense liability is carried at 18,000 euros and the full 18,000 will be deductible when paid. The rate is 30% and future taxable profit is probable. What are the tax base and the deferred tax?","choices":["Tax base 18,000 and no deferred tax","Tax base zero and a deferred tax liability of 5,400","Tax base zero and a deferred tax asset of 5,400","Tax base 36,000 and a deferred tax asset of 10,800"],"correct_index":2,"explanation":"The tax base of a liability is its carrying amount minus future deductions: 18,000 - 18,000 = zero. The deductible temporary difference of 18,000 gives a deferred tax asset of 18,000 × 30% = 5,400."},{"id":"cr-s19-level2-v1-q5","session":"19","level":2,"topic":"Book revenue before tax","question":"A company recognises 12,000 euros of interest revenue in this year's accounting profit, but tax law taxes it only when received next year. The receivable is carried at 12,000 with a tax base of zero and the rate is 25%. What tax effect arises now?","choices":["A deferred tax asset of 3,000, because collection comes later","Current tax of 3,000 now, despite the cash basis rule","No tax effect until the cash arrives","A deferred tax liability of 3,000, because the revenue will be taxed later"],"correct_index":3,"explanation":"The revenue is in accounting profit now but will enter taxable profit only on receipt, so future taxable profit will exceed accounting profit. The carrying amount of 12,000 over a zero tax base is a taxable temporary difference, giving a deferred tax liability of 3,000."},{"id":"cr-s19-level2-v1-q6","session":"19","level":2,"topic":"Current versus total tax with permanent and temporary items","question":"Accounting profit of 150,000 euros includes permanently non deductible costs of 10,000 and book depreciation of 15,000. Tax depreciation is 35,000 and the rate is 25%. What are current tax and total tax expense?","choices":["Current 35,000 and total 40,000","Current 40,000 and total 35,000","Both 37,500","Current 35,000 and total 30,000"],"correct_index":0,"explanation":"Remove the permanent costs first: 150,000 + 10,000 = 160,000 of adjusted profit. Taxable profit is 160,000 + 15,000 - 35,000 = 140,000, so current tax is 35,000. The 20,000 excess of tax over book depreciation is a taxable temporary difference, adding deferred expense of 5,000. Total is 40,000, which is 25% of the 160,000 adjusted profit: the permanent item moves the effective rate, not deferred tax."},{"id":"cr-s19-level2-v1-q7","session":"19","level":2,"topic":"Deferred balance versus period movement","question":"A deferred tax liability linked to profit items opens at 9,000 euros and must close at 14,000. There is no acquisition, rate change or other movement, and current tax expense is 30,000. What are the deferred and total tax expense?","choices":["Deferred 14,000 and total 44,000","Deferred 5,000 and total 35,000","Deferred benefit 5,000 and total 25,000","Deferred 9,000 and total 39,000"],"correct_index":1,"explanation":"The period's deferred expense is the movement in the balance: 14,000 - 9,000 = 5,000, not the whole closing liability. Total tax expense is 30,000 + 5,000 = 35,000."},{"id":"cr-s19-level2-v1-q8","session":"19","level":2,"topic":"DTA reversal does not mean new liability","question":"An opening deferred tax asset of 4,000 euros came from an expense deductible only when paid. That expense is paid this year, the temporary difference fully reverses and no new difference arises. What is the deferred tax effect?","choices":["Create a deferred tax liability of 4,000 alongside the old asset","Increase the asset by 4,000 and book another benefit","Reduce the asset to zero and recognise a deferred tax expense of 4,000","Reduce the asset against cash, with no expense"],"correct_index":2,"explanation":"The future deduction has now been used, so the asset goes back to zero: credit the deferred tax asset and debit deferred tax expense for 4,000. A reversal consumes the asset. It does not create a new liability and it never touches cash directly."},{"id":"cr-s19-level2-v1-q9","session":"19","level":2,"topic":"Effective rate from permanent difference","question":"Accounting profit before tax is 200,000 euros, including exempt income of 20,000 and no other tax adjustment. The statutory rate is 30%. What are the tax expense and the effective tax rate?","choices":["60,000 and 30%","66,000 and 33%","54,000 and 30%","54,000 and 27%"],"correct_index":3,"explanation":"Taxable profit is 200,000 - 20,000 = 180,000, giving tax of 54,000. The effective rate divides by accounting profit: 54,000/200,000 = 27%. The permanent exemption is exactly what pulls the effective rate below the statutory 30%."},{"id":"cr-s19-level2-v1-q10","session":"19","level":2,"topic":"Enacted reversal rate","question":"A taxable temporary difference of 80,000 euros will reverse in a period for which a 25% rate is already enacted, instead of the current 30%. No recognition exception applies. What deferred tax liability is recognised?","choices":["20,000 euros","24,000 euros","4,000 euros","80,000 euros"],"correct_index":0,"explanation":"Deferred tax uses the rate expected to apply on reversal, enacted or substantively enacted at the reporting date: 80,000 × 25% = 20,000. Today's 30% rate is not automatically the right one when a different future rate is already law."},{"id":"cr-s19-level3-v1-q1","session":"19","level":3,"topic":"Integrated tax reconciliation","question":"Accounting profit of 300,000 euros includes exempt income of 20,000, a non deductible fine of 5,000, book depreciation of 30,000 and a warranty expense of 15,000 that is deductible only when paid. Tax depreciation is 50,000 and nothing was paid on the warranty. The rate is 25%, opening deferred tax is zero and all effects run through profit. What are current tax, net deferred tax and total tax expense?","choices":["Current 70,000, net deferred expense 1,250, total 71,250","Current 71,250, no deferred tax, total 71,250","Current 70,000, net deferred benefit 1,250, total 68,750","Current 75,000, net deferred expense 1,250, total 76,250"],"correct_index":0,"explanation":"Adjust for permanent items first: 300,000 - 20,000 + 5,000 = 285,000. Taxable profit is 285,000 + 30,000 - 50,000 + 15,000 = 280,000, so current tax is 70,000. The excess tax depreciation builds a liability of 20,000 × 25% = 5,000 and the warranty an asset of 15,000 × 25% = 3,750, a net deferred expense of 1,250. Total is 71,250, which equals 25% of the 285,000 permanent adjusted profit."},{"id":"cr-s19-level3-v1-q2","session":"19","level":3,"topic":"Multiple assets tax bases and gross recognition","question":"At year end a machine is carried at 200,000 euros with a tax base of 140,000, a development asset of 50,000 has a tax base of zero because the costs were deducted for tax when incurred, and receivables are carried at 70,000 with a tax base of 90,000 because the impairment is deductible only later. The rate is 20% and full recognition applies. Before any offset, what are the gross deferred tax liability, gross deferred tax asset and the arithmetic net?","choices":["Liability 12,000, asset 14,000, net asset 2,000","Liability 22,000, asset 4,000, net liability 18,000","Liability 26,000, no asset, net liability 26,000","Liability 22,000, asset 20,000, net liability 2,000"],"correct_index":1,"explanation":"Taxable differences are 60,000 on the machine and 50,000 on the development asset, totalling 110,000, so the liability is 22,000. The receivables carry a deductible difference of 20,000, giving an asset of 4,000. The arithmetic net is an 18,000 liability, but offsetting on the balance sheet has its own conditions."},{"id":"cr-s19-level3-v1-q3","session":"19","level":3,"topic":"Two year temporary difference reversal","question":"Year one accounting profit of 100,000 euros includes a warranty expense of 10,000 deductible only when paid. In year two the warranty is paid and deducted, accounting profit is 120,000 with no new warranty expense. The rate is 30% and there are no other differences. What are the current taxes and deferred tax effects for the two years?","choices":["Current 30,000 and 36,000, with no deferred tax either year","Current 33,000 and 39,000, with deferred expense of 3,000 each year","Current 33,000 and 33,000, with a deferred benefit of 3,000 then a deferred expense of 3,000","Current 27,000 and 39,000, with a deferred benefit of 3,000 each year"],"correct_index":2,"explanation":"Year one: taxable profit is 110,000, current tax 33,000, and the future deduction builds a deferred tax asset of 3,000, a benefit that brings total expense to 30,000. Year two: taxable profit is 120,000 - 10,000 = 110,000, current tax 33,000 again, and the asset reverses into a 3,000 deferred expense, giving a total of 36,000. Over both years the cash tax is the same. Deferred tax only re-times the charge."},{"id":"cr-s19-level3-v1-q4","session":"19","level":3,"topic":"Cash payable and total expense integrated","question":"An opening current tax payable of 12,000 euros is fully paid this year. The current year tax charge before deferred tax is 40,000, and instalments of 30,000 are paid towards it. The deferred tax liability rises by 6,000 and the deferred tax asset by 2,000, all through profit. What are cash taxes paid, closing current payable and total tax expense?","choices":["Cash 30,000, payable 22,000, expense 48,000","Cash 42,000, payable 10,000, expense 48,000","Cash 52,000, payable zero, expense 40,000","Cash 42,000, payable 10,000, expense 44,000"],"correct_index":3,"explanation":"Cash taxes are 12,000 for the old liability plus 30,000 of instalments, totalling 42,000. The unpaid part of this year's charge is 40,000 - 30,000 = 10,000. Net deferred expense is 6,000 - 2,000 = 4,000, so total tax expense is 44,000. Cash, payable and expense each run on their own timeline."},{"id":"cr-s19-level3-v1-q5","session":"19","level":3,"topic":"Profit and OCI tax location","question":"A company has current tax on profit of 30,000 euros, a profit related deferred tax liability increase of 4,000, and a land revaluation gain of 40,000 recognised in other comprehensive income that creates a taxable temporary difference at 25%. There is no opening revaluation liability. What are the total tax expense in profit and the net gain in OCI?","choices":["Expense 34,000 and net OCI gain 30,000","Expense 44,000 and net OCI gain 40,000","Expense 30,000 and net OCI gain 26,000","Expense 34,000 and net OCI gain 40,000"],"correct_index":0,"explanation":"Tax expense in profit is 30,000 + 4,000 = 34,000. The deferred tax on the revaluation, 40,000 × 25% = 10,000, follows the gain into OCI, leaving a net OCI gain of 30,000. Deferred tax is recognised in the same place as the item that creates it."},{"id":"cr-s19-level3-v1-q6","session":"19","level":3,"topic":"Rate remeasurement plus new temporary difference","question":"A profit related deferred tax liability opens at 12,000 euros, built on a taxable temporary difference of 40,000 at 30%. By year end the difference has grown to 60,000 and a 25% reversal rate is enacted. No other tax effect exists. What are the closing liability and the net deferred tax expense?","choices":["Closing 18,000 and expense 6,000","Closing 15,000 and net expense 3,000","Closing 15,000 and benefit 2,000","Closing 10,000 and benefit 2,000"],"correct_index":1,"explanation":"The closing liability is 60,000 × 25% = 15,000, so the movement from 12,000 is a 3,000 expense. Decomposed: remeasuring the old 40,000 from 30% to 25% releases 2,000, while the new 20,000 of difference at 25% adds 5,000. Both the rate change and the new difference flow through the same expense line."},{"id":"cr-s19-level3-v1-q7","session":"19","level":3,"topic":"DTA support and tax expense movement","question":"A deductible temporary difference grows from 100,000 to 120,000 euros at a 25% rate. The opening deferred tax asset of 25,000 was fully supported, but at closing only 80,000 of qualifying future taxable profit is probable. All changes run through profit. What are the closing deferred tax asset and the period's deferred tax effect?","choices":["Closing 30,000 and benefit 5,000","Closing 20,000 and expense 10,000","Closing 20,000 and expense 5,000","Closing zero and expense 25,000"],"correct_index":2,"explanation":"The gross potential asset would be 120,000 × 25% = 30,000, but recognition is capped by probable future profit: 80,000 × 25% = 20,000. Against the recognised opening 25,000, that is a 5,000 expense for the period. A bigger deductible difference does not help if the profits to absorb it are not there."},{"id":"cr-s19-level3-v1-q8","session":"19","level":3,"topic":"Temporary difference decline and reversal rate","question":"An asset's taxable temporary difference falls from 80,000 to 50,000 euros during the year. The opening deferred tax liability of 24,000 reflects a 30% rate, and the enacted reversal rate at closing is 20%. All effects run through profit. What is the deferred tax movement?","choices":["A benefit of 9,000, leaving a liability of 15,000","An expense of 14,000, leaving a liability of 38,000","A benefit of 6,000, leaving a liability of 18,000","A benefit of 14,000, leaving a liability of 10,000"],"correct_index":3,"explanation":"The closing liability is 50,000 × 20% = 10,000. Moving from 24,000 to 10,000 releases 14,000, a benefit. Looking only at the 30,000 fall in the difference at the old rate would give 9,000 and miss the effect of the newly enacted lower rate."},{"id":"cr-s19-level3-v1-q9","session":"19","level":3,"topic":"Current taxable profit not inferred from DTL balance","question":"A closing deferred tax liability of 18,000 euros reflects cumulative taxable temporary differences at 30%. The opening liability was 12,000, all movements run through profit, and this year's accounting profit of 200,000 has no permanent differences. There is no deferred tax asset. What is the current tax expense?","choices":["54,000 euros","42,000 euros","60,000 euros","78,000 euros"],"correct_index":0,"explanation":"With no permanent differences, total tax expense is 30% of accounting profit: 60,000. The deferred part is the movement 18,000 - 12,000 = 6,000, so current tax is 60,000 - 6,000 = 54,000. Subtracting the whole closing liability of 18,000 would mix a cumulative balance with a one year expense."},{"id":"cr-s19-level3-v1-q10","session":"19","level":3,"topic":"Integrated loss and recognition limit","question":"A company reports an accounting loss before tax of 20,000 euros, which includes a permanently non deductible fine of 5,000. The only difference is the resulting tax loss, which can be carried forward, but only 10,000 of suitable future taxable profit is probable. The rate is 30% and opening deferred tax is zero. What deferred tax asset and after tax loss are reported?","choices":["Asset 4,500 and after tax loss 15,500","Asset 3,000 and after tax loss 17,000","Asset 6,000 and after tax loss 14,000","No asset and after tax loss 20,000"],"correct_index":1,"explanation":"Adding back the non deductible fine gives a tax loss of 15,000. The carry forward is a deductible difference, but recognition is capped by probable future profit: 10,000 × 30% = 3,000. That tax benefit reduces the accounting loss of 20,000 to an after tax loss of 17,000. The fine adds no future deduction, because permanent differences never reverse."}],"20":[{"id":"cr-s20-level1-v1-q1","session":"20","level":1,"topic":"Bad debt allowance timing","question":"Receivables before impairment are 100,000 euros. A book allowance of 10,000 is deductible for tax only on actual write off, so the net carrying amount is 90,000 and the tax base is 100,000. The rate is 30% and recovery is probable. What deferred tax follows?","choices":["A deferred tax liability of 3,000","A deferred tax asset of 30,000","A deferred tax asset of 3,000","None, because an allowance is non cash"],"correct_index":2,"explanation":"The carrying amount of 90,000 sits below the tax base of 100,000, so 10,000 of future deduction awaits: a deductible temporary difference. At 30% the deferred tax asset is 3,000, recognised because the recovery condition is satisfied."},{"id":"cr-s20-level1-v1-q2","session":"20","level":1,"topic":"DTA reduction when forecast deteriorates","question":"A recognised deferred tax asset stands at 24,000 euros. A year end review supports only 15,000 of recoverable benefit, all related to profit items, with no new difference or rate change. What are the expense and the closing asset?","choices":["A benefit of 9,000 and a closing asset of 33,000","An expense of 15,000 and a closing asset of 9,000","No expense and a closing asset of 24,000","An expense of 9,000 and a closing asset of 15,000"],"correct_index":3,"explanation":"The asset is cut from 24,000 to the 15,000 now supported, and the 9,000 reduction runs through profit as a tax expense. A benefit recognised in an earlier year is never guaranteed. it follows the current evidence."},{"id":"cr-s20-level1-v1-q3","session":"20","level":1,"topic":"Forecast improvement restoration","question":"A deductible difference could support a deferred tax asset of 20,000 euros, but only 8,000 was recognised in the past. New evidence now supports 14,000, with no other movement, all through profit. What is the current year tax benefit?","choices":["6,000 euros","14,000 euros","12,000 euros","20,000 euros"],"correct_index":0,"explanation":"The recognised asset rises from 8,000 to 14,000, so the benefit is 6,000. The benefit is the movement in the recognised balance, not the whole supported amount, and the still unsupported 6,000 of potential stays unrecognised."},{"id":"cr-s20-level1-v1-q4","session":"20","level":1,"topic":"Development asset already deducted","question":"A development asset is carried at 60,000 euros. Its expenditure was fully deducted for tax when incurred, leaving a tax base of zero. No recognition exception applies and the rate is 25%. What deferred tax follows?","choices":["A deferred tax asset of 15,000","A deferred tax liability of 15,000","A deferred tax liability of 60,000","Zero, because the tax deduction is already used"],"correct_index":1,"explanation":"Recovering the 60,000 carrying amount will produce taxable benefits with no future deduction left, a taxable temporary difference of 60,000. At 25% the deferred tax liability is 15,000. The earlier deduction does not create an asset. it creates the future tax cost."},{"id":"cr-s20-level1-v1-q5","session":"20","level":1,"topic":"Tax benefit maximum versus support","question":"A company has 200,000 euros of tax losses carried forward. Before expiry, only 120,000 euros of qualifying future taxable profit is probable, with no other recovery source. The applicable rate is 20%. What deferred tax asset is recognised?","choices":["40,000 euros, using all losses","120,000 euros, the supported future profit","24,000 euros, tax benefit on the supported usable losses","80,000 euros, the unsupported loss balance"],"correct_index":2,"explanation":"Only 120,000 of the 200,000 losses is supported for utilisation. Apply 20% to that usable amount: the recognised asset is 24,000. The potential 40,000 is capped by recoverability, and the remaining 80,000 of losses is a deduction amount, not a tax asset."},{"id":"cr-s20-level1-v1-q6","session":"20","level":1,"topic":"Current cash not same as deferred benefit","question":"At the start of year three, a company has a deferred tax liability of 8,000 euros. Of that balance, 6,000 relates to differences that do not change this year. A machinery taxable temporary difference of 10,000 reverses, while an equally sized new difference arises. The tax rate is 20% and no other movement occurs. What closing liability and net deferred tax expense follow?","choices":["A closing liability of 8,000 and an expense of 4,000","A closing liability of 10,000 and an expense of 2,000","A closing liability of zero and a benefit of 8,000","A closing liability of 8,000 and no net deferred tax expense"],"correct_index":3,"explanation":"The reversal removes 2,000 of liability and the new difference adds 2,000, leaving the balance at 8,000 with no net expense. A stable balance can hide two opposite movements, which is why a rolling deferred tax liability must be read item by item."},{"id":"cr-s20-level1-v1-q7","session":"20","level":1,"topic":"Book tax gap not automatic fraud","question":"A warranty liability of 20,000 euros is deductible only when paid. Future taxable profits are probable and the rate is 25%. What deferred tax follows?","choices":["A deferred tax asset of 5,000","A deferred tax asset of 20,000","No deferred tax, because the warranty is a liability","A deferred tax liability of 5,000"],"correct_index":0,"explanation":"The liability's carrying amount is 20,000 and its tax base is zero, because the deduction still lies ahead. Settling the liability will cut future taxable profit, a deductible temporary difference, so the deferred tax asset is 20,000 × 25% = 5,000."},{"id":"cr-s20-level1-v1-q8","session":"20","level":1,"topic":"Opening versus closing DTA","question":"A company reports a deferred tax liability of 40,000 euros after four years of growth. Management forecasts no fall in qualifying capital spending. What is the best reading of that liability?","choices":["It is an accounting error, because a liability cannot grow every year","It may persist as new differences replace reversals, so cash timing needs analysis","The entire balance ceases to be a recognised liability while investment continues","It can be ignored, because deferred taxes never affect cash"],"correct_index":1,"explanation":"With continuing investment, new taxable differences can replace reversing ones, so the liability persists and grows rather than becoming a cash payment. The analyst should ask when a reversal is actually likely instead of assuming either next year or never."},{"id":"cr-s20-level1-v1-q9","session":"20","level":1,"topic":"Permanent income and deferred tax","question":"A company recognises a deferred tax liability of 40,000 euros in year one and reverses it in year two. What is the combined effect on cash taxes over the two years, ignoring time value and any other change?","choices":["The liability recognition itself triggers an immediate cash payment of 40,000","No cash effect in either year","No permanent cash-tax saving, only a shift in payment timing","80,000 of cash tax paid overall"],"correct_index":2,"explanation":"The liability signals cash tax deferred in year one, and its reversal signals the catch up payment in year two. Over the two years the cash is the same. only the timing moved, which is exactly what a temporary difference is."},{"id":"cr-s20-level1-v1-q10","session":"20","level":1,"topic":"Deferred tax after actual bad debt write off","question":"A deferred tax asset of 3,000 euros exists for a 10,000 bad debt allowance that is deductible only on write off. The full debt is now written off and deducted, the rate stays 30% and no replacement allowance arises. What is the closing deferred tax asset?","choices":["6,000, because the same deduction is recognised again","3,000 indefinitely, because the original estimate was correct","A new deferred tax liability of 3,000 on top of the old asset","Zero, reversed through a deferred tax expense of 3,000"],"correct_index":3,"explanation":"The future deduction the asset represented has now been used in the current tax computation, so the asset falls to zero through a 3,000 deferred tax expense. The benefit has been collected. it cannot stay on the balance sheet as well."},{"id":"cr-s20-level2-v1-q1","session":"20","level":2,"topic":"Gross potential and recognised tax benefit","question":"A deductible difference of 150,000 euros at 30% implies a potential deferred tax asset of 45,000, but the evidence supports only 100,000 of qualifying future taxable profit before expiry, with no other recovery source. The opening recognised asset was 36,000. All items run through profit. What are the closing asset and the period effect?","choices":["A closing asset of 45,000 and a benefit of 9,000","A closing asset of 30,000 and an expense of 15,000","A closing asset of zero and an expense of 36,000","A closing asset of 30,000 and an expense of 6,000"],"correct_index":3,"explanation":"Recognition is capped by the supported deduction: 100,000 × 30% = 30,000. The recognised balance falls from 36,000 to 30,000, a 6,000 expense. The remaining 15,000 of the potential benefit is unrecognised. it is not part of the period expense."},{"id":"cr-s20-level2-v1-q2","session":"20","level":2,"topic":"Changing allowance need not mean cash tax","question":"In an explicitly specified US GAAP presentation, gross deferred tax assets of 50,000 euros less a valuation allowance of 20,000 give a net 30,000. The gross balance is unchanged but the allowance rises to 32,000, entirely through income tax expense. What net asset and profit effect follow?","choices":["A net asset of 18,000 and a tax expense of 12,000","A net asset of 82,000 and a tax benefit of 12,000","A net asset of 32,000 and a tax expense of 2,000","A net asset of 50,000 and no tax expense"],"correct_index":0,"explanation":"The contra allowance of 32,000 reduces gross 50,000 to a net asset of 18,000. The 12,000 increase in the allowance cuts the net balance from 30,000 and runs through tax expense. The prompt specifies US GAAP rather than claiming this presentation is mandatory IFRS terminology."},{"id":"cr-s20-level2-v1-q3","session":"20","level":2,"topic":"Multiple temporary differences gross balance","question":"Receivables carry 80,000 euros with a tax base of 100,000, vehicles carry 160,000 with a tax base of 120,000, and a warranty liability of 30,000 has a tax base of zero. The rate is 20%, deferred tax assets are fully supportable and no exception applies. What are the gross balances before any offset?","choices":["A deferred tax asset of 4,000 and a liability of 14,000, treating the warranty as taxable","A deferred tax asset of 10,000 and a liability of 8,000","A deferred tax asset of 8,000 and a liability of 10,000, reversing the signs","A net deferred tax asset of 2,000 only, offsetting the balances requested"],"correct_index":1,"explanation":"The receivable gap of 20,000 plus the warranty gap of 30,000 are deductible differences: 50,000 × 20% gives an asset of 10,000. The vehicle gap of 40,000 is taxable: 8,000 of liability. The question asks for the gross analysis, so netting them into 2,000 is not the answer."},{"id":"cr-s20-level2-v1-q4","session":"20","level":2,"topic":"Current tax and DTA recognition limit","question":"Accounting profit of 100,000 euros includes 20,000 of unpaid warranty expense that is deductible only when paid. The rate is 25%, only 12,000 of the resulting deductible difference has probable future utilisation, no other differences exist and the opening deferred tax asset is zero. What current tax and total tax expense follow?","choices":["Current 30,000 and total 25,000","Current 25,000 and total 22,000","Current 30,000 and total 27,000","Current 30,000 and total 33,000"],"correct_index":2,"explanation":"Taxable profit is 100,000 + 20,000 = 120,000, so current tax is 30,000. Recognition is capped at the supported part: 12,000 × 25% = 3,000 of benefit, not the full potential 5,000. Total expense is 27,000, showing how a recognition limit pushes the expense above 25% of accounting profit."},{"id":"cr-s20-level2-v1-q5","session":"20","level":2,"topic":"Recoverability using one profit pool only","question":"Two deductible differences of 40,000 and 60,000 euros expire at the same time and must both draw on the same future taxable profit pool of only 70,000, with no other recovery source. The rate is 30%. What combined deferred tax asset is supported at most?","choices":["30,000, because both differences are used in full","12,000, because only the smaller difference is supported","18,000, because only the larger difference is supported","21,000, because deductions are supported only up to the 70,000 pool"],"correct_index":3,"explanation":"The combined deductible amount of 100,000 competes for one pool of 70,000 of probable taxable profit. The supported benefit is at most 70,000 × 30% = 21,000. The same profits cannot be spent twice, however the categories are split."},{"id":"cr-s20-level2-v1-q6","session":"20","level":2,"topic":"Asset tax base reversal","question":"A development asset opens at 60,000 euros with a tax base of zero and a deferred tax liability of 15,000 at 25%. This year book amortisation of 20,000 occurs, no further tax deduction exists, the rate is unchanged and nothing else moves. What closing liability and deferred tax effect follow?","choices":["A closing liability of 10,000 and a tax benefit of 5,000","A closing liability of 15,000 and no movement","A closing liability of 20,000 and an expense of 5,000","A closing liability of 5,000 and a benefit of 10,000"],"correct_index":0,"explanation":"The closing carrying amount is 40,000 against a tax base of zero, so the liability is 10,000. The fall from 15,000 to 10,000 is a 5,000 benefit, the reversal of part of the taxable difference as amortisation catches up with the tax deduction already taken."},{"id":"cr-s20-level2-v1-q7","session":"20","level":2,"topic":"Taxable profit bridge allowance plus fine","question":"Accounting profit of 120,000 euros includes a bad debt expense of 15,000 deductible only on actual write off later, and a permanently nondeductible fine of 5,000. No write off or other difference occurs. The rate is 20%, deferred tax assets are fully supportable and opening deferred tax is zero. What current tax and total tax expense follow?","choices":["Current 24,000 and total 28,000","Current 28,000 and total 25,000","Current 28,000 and total 24,000","Current 25,000 and total 28,000"],"correct_index":1,"explanation":"Taxable profit is 120,000 + 15,000 + 5,000 = 140,000, so current tax is 28,000. The bad debt difference creates a deferred tax asset of 3,000, bringing total expense to 25,000, exactly 20% of the permanently adjusted profit of 125,000. The fine is permanent and creates no deferred tax."},{"id":"cr-s20-level2-v1-q8","session":"20","level":2,"topic":"DTA restoration capped at potential","question":"A potential deferred tax asset of 18,000 euros exists on deductible differences, but only 6,000 was recognised last year. New evidence now supports the full potential, with no new difference or rate change and all effects through profit. What is the maximum benefit from restoration?","choices":["18,000 euros","24,000 euros","12,000 euros","6,000 euros"],"correct_index":2,"explanation":"The recognised balance rises from 6,000 to the maximum potential of 18,000, so the benefit is 12,000. Better evidence can restore an asset up to its potential, but never above the tax benefit the underlying differences can actually deliver."},{"id":"cr-s20-level2-v1-q9","session":"20","level":2,"topic":"No universal country ranking","question":"Firm A has taxable temporary differences of 200,000 euros taxed at 20%. Firm B has taxable differences of 100,000 taxed at 30%, with no exceptions or recoverability complications. What deferred tax liabilities follow, and why must each be measured on its own facts?","choices":["A is 20,000 and B is 30,000, halving A's difference","A is 40,000 and B is 60,000, doubling B's difference","A is 60,000 and B is 20,000, swapping the two rates","A is 40,000 and B is 30,000, each firm's own difference times its own rate"],"correct_index":3,"explanation":"Firm A owes 200,000 × 20% = 40,000 and Firm B owes 100,000 × 30% = 30,000. General observations about national book tax conformity never determine one company's differences or its rate. the measurement uses the firm's own reversal rate."},{"id":"cr-s20-level2-v1-q10","session":"20","level":2,"topic":"Persistent DTL balance not perpetual tax exemption","question":"A deferred tax liability stays at 100,000 euros while old differences reverse and equally sized new taxable differences arise. What does the stable closing balance establish?","choices":["Reversals do occur even when new differences leave the net balance unchanged","No underlying difference has reversed while the total is stable","The liability can be derecognised because no net expense arose","The balance is a permanent exemption rather than deferred tax"],"correct_index":0,"explanation":"Equal origination and reversal can hold a balance constant while specific items still have real cash consequences. The analyst must look at cohorts and replacements rather than inferring either permanence or imminent payment from the net stock."},{"id":"cr-s20-level3-v1-q1","session":"20","level":3,"topic":"Gross DTA movement versus reduced support","question":"A deductible difference opens at 100,000 euros and closes at 160,000. The rate is 25%, the opening recognised deferred tax asset is 20,000, and closing qualifying future taxable profit supports only 120,000 of deductions, with no other recovery source and all effects through profit. What closing recognised asset and deferred benefit follow?","choices":["An asset of 30,000 and a benefit of 10,000","An asset of 40,000 and a benefit of 20,000","An asset of 30,000 and a benefit of 15,000","An asset of 10,000 and an expense of 10,000"],"correct_index":0,"explanation":"Closing potential is 160,000 × 25% = 40,000, but support caps the asset at 120,000 × 25% = 30,000. The benefit is measured from the recognised opening balance of 20,000, not the gross opening potential of 25,000, so the benefit is 10,000. Both the initial and the final support tests matter."},{"id":"cr-s20-level3-v1-q2","session":"20","level":3,"topic":"Allowance release versus operating improvement","question":"An explicitly US GAAP example reports pretax profit of 80 million euros, gross current tax expense of 24 million and no deferred movement other than a valuation allowance release of 10 million through income tax. No cash refund arises and there are 20 million shares. What net profit and EPS follow, and what caveat matters?","choices":["Profit 56 million and EPS 2.8, excluding the release from tax expense","Net profit 66 million and EPS 3.3, with the release being neither operating profit nor a cash inflow","Profit 90 million and EPS 4.5, treating the release as pretax income","Profit 66 million and EPS 3.3, establishing recurring cash tax savings from the release"],"correct_index":1,"explanation":"Tax expense is 24 - 10 = 14, so net profit is 80 - 14 = 66 and EPS is 66 / 20 = 3.3. The release lifts current after tax earnings through the tax line only. it improves neither pretax operating performance nor immediate cash."},{"id":"cr-s20-level3-v1-q3","session":"20","level":3,"topic":"Three year bad debt timing","question":"In year 1 a 10,000 euro doubtful debt expense is not deductible. In year 2 no write off occurs but recoverability evidence disappears and the deferred tax asset is cut to zero. In year 3 the debt is written off and tax law allows a full current deduction against sufficient taxable profit. The rate is 30% throughout. What happens to deferred tax in years 1 and 2, and what current tax saving does the write off bring in year 3? Recovery of the year 1 deferred tax asset was probable when first recognised, and all effects run through profit or loss.","choices":["A benefit of 3,000 in years 1 and 2, and a current saving of 3,000 in year 3","An expense of 3,000 in year 1, a benefit of 3,000 in year 2, and no year 3 saving","A year 1 benefit of 3,000, a year 2 expense of 3,000 and a year 3 current tax saving of 3,000","Zero in year 1, zero in year 2, and a saving of 3,000 in year 3"],"correct_index":2,"explanation":"Year 1: the supported future deduction creates an asset of 3,000, a benefit. Year 2: the failed recoverability test reverses it through an expense of 3,000. Year 3: the actual deduction saves 3,000 of current tax, and with the asset already at zero there is nothing left to reverse."},{"id":"cr-s20-level3-v1-q4","session":"20","level":3,"topic":"Profit taxes and support deterioration combined","question":"Current tax expense is 50,000 euros. The deferred tax liability rises from 12,000 to 18,000. The gross deferred tax asset potential rises from 20,000 to 28,000, but the recognised asset falls from 16,000 to 10,000 after a support review. All movements hit profit and no other tax item exists. What is the total tax expense?","choices":["48,000 euros","52,000 euros","64,000 euros","62,000 euros"],"correct_index":3,"explanation":"The liability increase of 6,000 is a deferred expense, and the recognised asset decrease of 6,000 is another, so total expense is 50,000 + 6,000 + 6,000 = 62,000. The rise in gross potential is not a benefit when the support test caps the recognised asset."},{"id":"cr-s20-level3-v1-q5","session":"20","level":3,"topic":"Shared profit cannot support tax losses twice","question":"A firm holds deductible temporary differences of 80,000 euros and tax loss carryforwards of 100,000. Both must draw on the same taxable profits and expire at the same time, total qualifying probable taxable profit is 120,000, there is no other recovery route and the rate is 25%. What maximum total deferred tax asset can be recognised before any allocation between the two categories?","choices":["30,000, using the common probable profit pool once across all deductible items","45,000, supporting both categories in full despite the common limit","50,000, assigning the same profit pool separately to each category","20,000, recognising only the temporary differences and ignoring the losses"],"correct_index":0,"explanation":"The combined potential deductions of 180,000 exceed the single pool of 120,000 of probable profit, so the maximum benefit is 120,000 × 25% = 30,000. Splitting the asset between losses and differences does not expand the total support."},{"id":"cr-s20-level3-v1-q6","session":"20","level":3,"topic":"Book tax gap includes permanent items","question":"Accounting profit of 500,000 euros includes exempt income of 50,000 and nondeductible costs of 10,000. Net temporary differences reduce this year's taxable profit by 40,000. The rate is 20%, no recoverability restriction applies and all tax runs through profit. What taxable profit, current tax and effective tax rate follow?","choices":["Taxable 460,000, current 92,000 and an effective rate of 18.4%","Taxable 420,000, current 84,000 and an effective rate of 18.4%","Taxable 420,000, current 84,000 and an effective rate of 16.8%","Taxable 500,000, current 100,000 and an effective rate of 20%"],"correct_index":1,"explanation":"Permanent items adjust book profit to 500,000 - 50,000 + 10,000 = 460,000. the temporary reduction of 40,000 gives taxable profit of 420,000 and current tax of 84,000. Deferred expense of 8,000 lifts total tax to 92,000, which over book profit of 500,000 is 18.4%. The 16.8% figure is only the current tax rate on book income."},{"id":"cr-s20-level3-v1-q7","session":"20","level":3,"topic":"DTA recognition after rate reduction","question":"A deductible difference of 200,000 euros is unchanged. The opening deferred tax asset of 40,000 reflected 20% and full support. A 15% reversal rate is now enacted, and only 160,000 of future taxable profit is probable within the usage period, with no other recovery route and all tax through profit. What closing asset and expense follow?","choices":["A closing asset of 30,000 and an expense of 10,000","A closing asset of 32,000 and an expense of 8,000","A closing asset of 24,000 and a tax expense of 16,000","A closing asset of 24,000 and an expense of 6,000"],"correct_index":2,"explanation":"The rate cut alone drops the potential to 200,000 × 15% = 30,000, and the support test caps recognition at 160,000 × 15% = 24,000. Against the opening 40,000 that is a 16,000 expense, combining both effects rather than only one."},{"id":"cr-s20-level3-v1-q8","session":"20","level":3,"topic":"Year 2 depreciation and current deferred split","question":"A machine costs 100,000 euros, depreciated 20,000 a year in the books while tax allows 40,000 in year 1 and 20,000 in year 2. The rate is 25% and year 2 accounting profit of 200,000 is after book depreciation, with no permanent or other differences. What year 2 current tax, deferred tax expense and closing deferred tax liability follow?","choices":["Current 45,000, deferred expense 5,000 and a closing liability of 10,000","Current 50,000, deferred expense 5,000 and a closing liability of 5,000","Current 55,000, a deferred benefit of 5,000 and a closing liability of zero","Current 50,000, deferred expense zero and a closing liability of 5,000"],"correct_index":3,"explanation":"End of year 1: carrying 80,000 versus tax base 60,000, a liability of 5,000. End of year 2: carrying 60,000 versus tax base 40,000, the same 20,000 gap and the same 5,000 liability. Year 2 book and tax depreciation are equal, so taxable profit equals book profit, current tax is 50,000 and no deferred movement occurs despite the standing balance."},{"id":"cr-s20-level3-v1-q9","session":"20","level":3,"topic":"IFRS recoverability not elective smoothing","question":"An IFRS entity has a potential deferred tax asset of 50,000 euros and evidence supports recovery of 35,000. Management asks to recognise only 20,000 this year and release the rest later to smooth earnings, with no contrary recovery evidence. What amount is appropriate on these facts?","choices":["35,000 euros","20,000 euros","50,000 euros","Zero"],"correct_index":0,"explanation":"IAS 12 requires recognition to the extent that utilisation is probable. Deliberately recognising less than the evidence supports, or more, to steer reported profit is not permitted. on the stated facts the asset is 35,000."},{"id":"cr-s20-level3-v1-q10","session":"20","level":3,"topic":"Tax cash forecast cannot use total expense blindly","question":"A simplified firm forecasts total income tax expense of 90,000 euros, including deferred expense of 20,000. There is no opening tax payable balance, no instalments and no other current tax adjustment, and all current tax is paid within the forecast year. What forecast cash tax follows?","choices":["90,000 euros","70,000 euros","110,000 euros","20,000 euros"],"correct_index":1,"explanation":"Current tax is 90,000 - 20,000 = 70,000, and under the stated cash assumptions that is also the cash outflow. In other settings payable balances and instalment timing would need their own bridge, so this is not a general rule that total expense equals cash."}],"21":[{"id":"cr-s21-level1-v1-q1","session":"21","level":1,"topic":"Sale and leaseback retained right","question":"A qualifying sale and leaseback transfers an asset with a carrying amount of 400,000 euros and a fair value of 500,000, sold at fair value with market rents. The present value of the leaseback payments is 100,000, so the retained right proportion is 20%. What initial right of use asset does the seller recognise?","choices":["100,000 euros","400,000 euros","80,000 euros","20,000 euros"],"correct_index":2,"explanation":"The right of use asset is the retained 20% of the previous carrying amount of 400,000, which is 80,000. In a qualifying sale and leaseback it is not measured at the full lease liability of 100,000 or at fair value."},{"id":"cr-s21-level1-v1-q2","session":"21","level":1,"topic":"Gain only transferred rights","question":"A qualifying sale and leaseback involves an asset carried at 300,000 euros with a fair value of 500,000, sold at fair value with market rents. Retained rights are 40% and transferred rights 60%. What initial disposal gain is recognised?","choices":["200,000 euros","80,000 euros","300,000 euros","120,000 euros"],"correct_index":3,"explanation":"The total economic gain is 500,000 - 300,000 = 200,000, but only the transferred 60% is recognised: 120,000. The retained 80,000 of gain relates to rights the seller keeps using and is not recognised immediately."},{"id":"cr-s21-level1-v1-q3","session":"21","level":1,"topic":"Failed sale financing","question":"A seller transfers legal title to an asset carried at 450,000 euros and receives 600,000, then leases the asset back. The transfer fails the IFRS 15 sale test because control has not transferred. What initial treatment follows for the seller?","choices":["Keep the 450,000 asset and recognise a 600,000 financing liability","Derecognise the asset and recognise a 150,000 gain","Recognise a 600,000 right of use asset and no liability","Write the asset down to zero with no replacement liability"],"correct_index":0,"explanation":"A failed sale is financing, not a disposal. The asset stays recognised at 450,000 and the proceeds received become a financial liability of 600,000. No gain arises because nothing was truly sold."},{"id":"cr-s21-level1-v1-q4","session":"21","level":1,"topic":"Buyer in failed sale","question":"A transfer of 700,000 euros fails the IFRS 15 sale test, so the seller accounts for it as financing. What initial treatment follows for the buyer on the same facts?","choices":["A 700,000 underlying asset, treating legal title as sufficient despite the failed sale","A 700,000 financial asset, reflecting financing rather than an asset purchase","A 700,000 prepaid lease asset, allocated over the leaseback term","A 700,000 right of use asset, applying the seller-lessee's leaseback treatment"],"correct_index":1,"explanation":"The financing substance shows on both sides. The buyer records the funds advanced as a financial asset under IFRS 9, not an acquisition of the underlying asset, because control never passed."},{"id":"cr-s21-level1-v1-q5","session":"21","level":1,"topic":"DTA rate increase","question":"A supported deductible temporary difference of 100,000 euros is unchanged, and the applicable enacted reversal rate rises from 20% to 25%. All items relate to profit. What change to the deferred tax asset follows?","choices":["A decrease of 5,000, creating an expense","An increase of 25,000, all recognised as this year's benefit","An increase of 5,000, creating a 5,000 tax benefit","No change until cash tax is paid"],"correct_index":2,"explanation":"The asset rises from 100,000 × 20% = 20,000 to 25,000. The 5,000 increase is a benefit through profit. The 25,000 is the closing balance, not the movement."},{"id":"cr-s21-level1-v1-q6","session":"21","level":1,"topic":"DTL rate decrease","question":"A taxable temporary difference of 200,000 euros is unchanged, and the applicable enacted reversal rate falls from 30% to 25%. All items relate to profit. What movement in the deferred tax liability follows?","choices":["An increase of 10,000, creating an expense","A decrease of 50,000, removing the whole closing balance","No change, because the temporary difference itself did not change","A decrease of 10,000, creating a 10,000 tax benefit"],"correct_index":3,"explanation":"The liability falls from 200,000 × 30% = 60,000 to 50,000. The same difference now costs less future tax, so the 10,000 reduction is a benefit through profit. A rate change alone is enough to trigger remeasurement."},{"id":"cr-s21-level1-v1-q7","session":"21","level":1,"topic":"Cash release not entire gain","question":"A qualifying sale and leaseback brings in 500,000 euros cash. The old asset carried 400,000, its fair value is 500,000, retained rights are 20%, rents are market and no other adjustment applies. What recognised gain and cash proceeds follow?","choices":["A gain of 80,000 and cash of 500,000","A gain of 500,000 and cash of 80,000","A gain of 100,000 and cash of 500,000","A gain of 400,000 and cash of 100,000"],"correct_index":0,"explanation":"The total gain of 100,000 times the 80% of rights transferred gives a recognised gain of 80,000. The cash proceeds stay at the full 500,000. Cash raised and profit recognised are two different questions."},{"id":"cr-s21-level1-v1-q8","session":"21","level":1,"topic":"Proposed rate not enacted","question":"A profit related deferred tax liability rests on a taxable difference of 100,000 euros and an applicable enacted rate of 30%. A minister proposes a 20% rate, but the proposal is neither enacted nor substantively enacted at the reporting date. What is the closing liability?","choices":["20,000","30,000","25,000","10,000"],"correct_index":1,"explanation":"Measurement uses the rate enacted or substantively enacted at the reporting date, which here remains 30%, so the liability stays at 30,000. A political proposal alone does not change the measurement rate."},{"id":"cr-s21-level1-v1-q9","session":"21","level":1,"topic":"Retained versus transferred share","question":"A qualifying sale and leaseback is priced at a fair value of 600,000 euros, and the leaseback payments have a present value of 150,000. With no off market or other adjustment, what are the retained and transferred proportions?","choices":["75% retained and 25% transferred","20% retained and 80% transferred","25% retained and 75% transferred","100% retained, because the seller keeps physically using the asset"],"correct_index":2,"explanation":"The retained share is 150,000 / 600,000 = 25%, so 75% of the rights are transferred. Continuing to use the asset does not mean the seller retains every right in it."},{"id":"cr-s21-level1-v1-q10","session":"21","level":1,"topic":"Tax effects follow underlying OCI","question":"An asset revaluation is recognised in other comprehensive income and creates an associated deferred tax liability of 10,000 euros, with no exception. Where is the deferred tax charge recognised?","choices":["In income tax expense in profit or loss","Directly in retained earnings as an owner transaction","Deferred until the asset is sold and the difference reverses","In other comprehensive income, following the underlying revaluation"],"correct_index":3,"explanation":"IAS 12 makes the tax follow the underlying transaction. Because the revaluation sits in OCI, its 10,000 tax charge reduces OCI rather than hitting current profit."},{"id":"cr-s21-level2-v1-q1","session":"21","level":2,"topic":"Sale leaseback balanced entry","question":"A qualifying sale and leaseback is priced at a fair value of 500,000 euros. The old carrying amount is 400,000, the market leaseback liability has a present value of 150,000 and the retained proportion is 30%. What right of use asset and recognised gain follow for the seller?","choices":["Right of use asset 150,000 and gain 100,000","Right of use asset 120,000 and gain 30,000","Right of use asset 280,000 and gain 70,000","Right of use asset 120,000 and gain 70,000"],"correct_index":3,"explanation":"The right of use asset is 30% × 400,000 = 120,000. The total gain of 100,000 times the 70% of rights transferred gives a recognised gain of 70,000. The entry balances: cash 500,000 plus right of use 120,000 equals the asset removed 400,000 plus liability 150,000 plus gain 70,000."},{"id":"cr-s21-level2-v1-q2","session":"21","level":2,"topic":"Retained right with different book discount","question":"An asset carried at 240,000 euros is sold at its fair value of 400,000 in a qualifying sale and leaseback. The market leaseback liability has a present value of 100,000 and the retained proportion is 25%. What right of use asset and gain follow?","choices":["Right of use asset 60,000 and gain 120,000","Right of use asset 100,000 and gain 160,000","Right of use asset 60,000 and gain 40,000","Right of use asset 180,000 and gain 120,000"],"correct_index":0,"explanation":"The right of use asset is 25% × 240,000 = 60,000. The total gain of 160,000 times the 75% of rights transferred gives 120,000. Keeping a quarter of the use rights defers a quarter of the total gain."},{"id":"cr-s21-level2-v1-q3","session":"21","level":2,"topic":"Net equity effect of qualifying transaction","question":"A qualifying sale and leaseback brings in 800,000 euros equal to fair value, removes an old asset carried at 600,000, and creates a lease liability of 200,000 plus a right of use asset of 150,000, with no tax or other adjustment. What is the immediate increase in equity?","choices":["200,000 euros","150,000 euros","800,000 euros","350,000 euros"],"correct_index":1,"explanation":"The net asset effect is cash 800,000 + right of use 150,000 - asset removed 600,000 - liability 200,000 = 150,000, which equals the recognised gain: the total gain of 200,000 times the 75% of rights transferred implied by these figures."},{"id":"cr-s21-level2-v1-q4","session":"21","level":2,"topic":"DTA support still applies after rate rise","question":"A deductible difference of 100,000 euros is unchanged. The applicable enacted rate rises from 20% to 30%, but only 60,000 of qualifying future taxable profit is probable, with no other recovery source. The opening recognised deferred tax asset of 12,000 already reflected that same 60,000 support at 20%. What closing asset and benefit follow?","choices":["A closing asset of 30,000 and a benefit of 18,000","A closing asset of 18,000 and a benefit of 10,000","A closing asset of 18,000 and a benefit of 6,000","A closing asset of 12,000 and no benefit, because support is unchanged"],"correct_index":2,"explanation":"The supported benefit is 60,000 × 30% = 18,000, so the asset rises from 12,000 to 18,000 for a benefit of 6,000. The rate rise does not lift the utilisation cap or create recognition for the unsupported 40,000 of deductions."},{"id":"cr-s21-level2-v1-q5","session":"21","level":2,"topic":"Opposite rate effects net profit","question":"A profit related deferred tax asset of 40,000 euros represents deductible differences of 200,000 at 20%, and a deferred tax liability of 60,000 represents taxable differences of 300,000 at 20%. Both differences are unchanged, the applicable enacted rate becomes 25% and the asset remains fully supported. What net tax expense does the remeasurement produce?","choices":["25,000 euros","A benefit of 5,000","A benefit of 10,000","5,000 euros"],"correct_index":3,"explanation":"The asset grows to 50,000, a benefit of 10,000, while the liability grows to 75,000, an expense of 15,000. The net effect is an expense of 5,000. One rate change can push an asset and a liability in opposite directions for profit."},{"id":"cr-s21-level2-v1-q6","session":"21","level":2,"topic":"Sale test precedes ratio calculation","question":"A transfer brings in 1,000,000 euros but fails the IFRS 15 sale test, so the old asset of 700,000 stays recognised and a financial liability of 1,000,000 is recorded. Cash was initially 200,000 and debt initially 400,000. Defining net debt as debt minus cash, what is net debt immediately after the receipt?","choices":["200,000 euros, unchanged","Minus 800,000, because the financing liability is ignored","1,200,000, because cash is not counted","500,000, because an assumed 300,000 gain reduces debt"],"correct_index":0,"explanation":"Debt becomes 400,000 + 1,000,000 = 1,400,000 and cash becomes 200,000 + 1,000,000 = 1,200,000, leaving net debt at 200,000. Raising cash through a failed sale adds a matching obligation, so it does not deleverage the firm."},{"id":"cr-s21-level2-v1-q7","session":"21","level":2,"topic":"Net tax balance rate decline","question":"At 30% a firm holds a deferred tax asset of 24,000 euros and a deferred tax liability of 45,000, both fully supported profit related balances with unchanged underlying differences. The applicable enacted rate falls to 20%. What closing net deferred tax liability and profit benefit follow?","choices":["A net liability of 21,000 and no benefit","A net liability of 14,000 and a benefit of 7,000","A net liability of 10,000 and a benefit of 11,000","A net liability of 14,000 and an expense of 7,000"],"correct_index":1,"explanation":"The deductible difference is 24,000 / 30% = 80,000, giving a new asset of 16,000, and the taxable difference is 45,000 / 30% = 150,000, giving a new liability of 30,000. The net liability falls from 21,000 to 14,000, a benefit of 7,000. This arithmetic comparison does not by itself establish permission to offset on the balance sheet."},{"id":"cr-s21-level2-v1-q8","session":"21","level":2,"topic":"Rate change recognition timing","question":"A taxable difference of 100,000 euros will reverse next year. A 25% rate for that reversal is substantively enacted at the current reporting date, replacing 30%, and IAS 12 permits substantive enactment in this jurisdiction. What is the current closing deferred tax liability?","choices":["30,000, retaining the old rate until the new one is legally effective","5,000, recognising the rate reduction itself as the liability","25,000 now, applying the substantively enacted rate expected to govern reversal","27,500, averaging the old and new rates over the period before reversal"],"correct_index":2,"explanation":"The liability is measured at the rate expected to apply on reversal, which here is the substantively enacted 25%, so it becomes 25,000 immediately. There is no waiting for payment and no averaging."},{"id":"cr-s21-level2-v1-q9","session":"21","level":2,"topic":"Failed sale buyer and seller symmetry","question":"A buyer pays 900,000 euros in a transfer that fails the sale test. Ignoring transaction costs and later interest, what balances arise initially across the two parties?","choices":["A buyer right of use asset of 900,000 and a seller gain of 900,000","A buyer financial liability of 900,000 and a seller financial asset of 900,000","Both parties recognise the same underlying asset as a completed purchase and sale","A buyer financial asset of 900,000 and a seller financial liability of 900,000"],"correct_index":3,"explanation":"In financing accounting the funds advanced are the buyer's receivable and the seller's borrowing. Legal title paperwork does not override the expressly failed control transfer test."},{"id":"cr-s21-level2-v1-q10","session":"21","level":2,"topic":"Sale leaseback gain not full fair uplift","question":"An old asset carried at 500,000 euros has a fair value of 800,000 and is sold for 800,000 with a market leaseback whose payments have a present value of 320,000, giving a retained proportion of 40%. The sale qualifies. How much of the total gain is left unrecognised initially because it relates to retained rights?","choices":["120,000 euros","180,000 euros","300,000 euros","320,000 euros"],"correct_index":0,"explanation":"The total economic gain is 800,000 - 500,000 = 300,000, and the retained 40% means 120,000 is not recognised immediately. The recognised 180,000 on the transferred 60% is a different figure from the one asked for."},{"id":"cr-s21-level3-v1-q1","session":"21","level":3,"topic":"Integrated fair value sale leaseback","question":"A qualifying sale and leaseback transfers an asset carried at 600,000 euros for its fair value of 1,000,000. Rents are at market, the leaseback payments have a present value of 250,000 and the retained proportion is 25%, with no tax or other adjustment. What initial right of use asset, recognised gain and net increase in assets less liabilities follow?","choices":["Right of use 150,000, gain 300,000 and a net increase of 300,000","Right of use 250,000, gain 400,000 and a net increase of 400,000","Right of use 150,000, gain 100,000 and a net increase of 100,000","Right of use 450,000, gain 300,000 and a net increase of 600,000"],"correct_index":0,"explanation":"The right of use asset is 600,000 × 25% = 150,000, and the recognised gain is (1,000,000 - 600,000) × 75% = 300,000. Net assets change by cash 1,000,000 + right of use 150,000 - asset removed 600,000 - liability 250,000 = 300,000, consistent with the profit."},{"id":"cr-s21-level3-v1-q2","session":"21","level":3,"topic":"Sale leaseback and subsequent year expense","question":"A qualifying sale and leaseback at a fair value of 800,000 euros removes an asset carried at 600,000. The market leaseback liability is 200,000 and the retained right is 25%, giving an initial right of use asset of 150,000 and a recognised gain of 150,000. The leaseback runs 5 years with no title transfer or purchase option, zero residual and straight line depreciation, the useful life of the underlying well exceeds the lease term, year 1 interest is 10,000 and nothing else changes. What is the net year 1 profit effect of the gain, the right of use depreciation and the interest together?","choices":["A net gain of 150,000","A net gain of 110,000","A net gain of 100,000","A net loss of 40,000"],"correct_index":1,"explanation":"Depreciation is 150,000 / 5 = 30,000 and interest is 10,000, so current charges total 40,000 against the initial gain of 150,000: a net gain of 110,000. The 800,000 of cash proceeds is not profit, and the day one gain does not cancel later lease costs."},{"id":"cr-s21-level3-v1-q3","session":"21","level":3,"topic":"Mixed profit and OCI rate changes","question":"A profit related taxable difference of 200,000 euros and an OCI revaluation taxable difference of 100,000 are unchanged, and both opening deferred tax liabilities use 30%. The applicable enacted reversal rate becomes 20%, with no other item. What profit tax benefit and OCI tax benefit follow?","choices":["A profit benefit of 30,000 and zero in OCI","A profit expense of 20,000 and an OCI expense of 10,000","A profit benefit of 20,000 and an OCI benefit of 10,000","A profit benefit of 10,000 and an OCI benefit of 20,000"],"correct_index":2,"explanation":"The 10 point rate cut saves 20,000 on the profit related difference, recognised in profit, and 10,000 on the OCI related difference, recognised in OCI. A rate change does not push every remeasurement effect through current profit."},{"id":"cr-s21-level3-v1-q4","session":"21","level":3,"topic":"DTA rate and recoverability move opposite","question":"An opening deferred tax asset of 60,000 euros reflects a deductible difference of 200,000 at 30% with full support. The difference stays at 200,000, but the applicable enacted rate rises to 35% while only 150,000 of qualifying future taxable profit is now probable, with no other recovery source and all effects in profit. What closing asset and expense follow?","choices":["A closing asset of 70,000 and a benefit of 10,000","A closing asset of 52,500 and a benefit of 7,500","A closing asset of 45,000 and an expense of 15,000","A closing asset of 52,500 and a tax expense of 7,500"],"correct_index":3,"explanation":"The rate rise lifts the potential to 200,000 × 35% = 70,000, but support caps recognition at 150,000 × 35% = 52,500. Against the opening 60,000 that is a 7,500 expense. A higher rate alone does not guarantee a recognised benefit when recoverability tightens."},{"id":"cr-s21-level3-v1-q5","session":"21","level":3,"topic":"Underlying differences and rate net together","question":"An opening profit related deferred tax liability of 45,000 euros reflects a taxable difference of 150,000 at 30%. At closing the taxable difference rises to 200,000 while the applicable enacted reversal rate falls to 20%, with no other effect. What closing liability and period deferred tax effect follow?","choices":["A closing liability of 40,000 and a tax benefit of 5,000","A closing liability of 60,000 and an expense of 15,000","A closing liability of 30,000 and a benefit of 15,000","A closing liability of 40,000 and an expense of 10,000"],"correct_index":0,"explanation":"The closing liability is 200,000 × 20% = 40,000, below the opening 45,000 even though the difference grew, so the period effect is a 5,000 benefit. It combines a 15,000 rate benefit on the old 150,000 and a 10,000 expense on the new 50,000 at 20%."},{"id":"cr-s21-level3-v1-q6","session":"21","level":3,"topic":"Retained right error quantified","question":"A qualifying sale and leaseback transfers an asset carried at 300,000 euros at its fair value of 600,000 with market rents. The leaseback present value is 240,000 and the retained proportion is 40%. An erroneous entry measures the right of use asset at 240,000 instead of the required retained carrying amount and recognises the full 300,000 gain. What asset and profit overstatements result?","choices":["No asset overstatement and a profit overstatement of 120,000","Both 120,000 euros","Both 180,000 euros","An asset overstatement of 120,000 and a profit overstatement of 300,000"],"correct_index":1,"explanation":"The correct right of use asset is 300,000 × 40% = 120,000, so 240,000 overstates it by 120,000. The correct gain is 300,000 × 60% = 180,000, so recognising the full 300,000 overstates profit by 120,000. Both mistakes book gain on rights the seller kept."},{"id":"cr-s21-level3-v1-q7","session":"21","level":3,"topic":"No sale not a gain choice","question":"A transfer fails the sale test: the 500,000 euros received and the old asset carried at 350,000 are in substance a borrowing. Management instead books a 150,000 gain, removes the asset and records no financial liability. Relative to the correct initial accounting, how are profit and liabilities misstated?","choices":["Profit is correct and liabilities are understated by 150,000","Profit is understated by 150,000 and liabilities overstated by 500,000","Profit is overstated by 150,000 and liabilities understated by 500,000","Profit is overstated by 500,000 and liabilities are correct"],"correct_index":2,"explanation":"Correct financing accounting keeps the 350,000 asset, adds a 500,000 liability and books no gain. The erroneous disposal invents 150,000 of profit and omits the entire 500,000 borrowing, not just the difference from carrying value."},{"id":"cr-s21-level3-v1-q8","session":"21","level":3,"topic":"Rate change after sale leaseback not all cash","question":"A qualifying sale and leaseback produces a recognised pretax gain of 120,000 euros. Current tax on that recognised gain is 30,000, and a separate profit related deferred tax liability falls by 8,000 purely because of an enacted rate cut. No other tax item exists and the sale cash received is 400,000. What after tax gain contribution and total cash receipt follow?","choices":["An after tax gain of 90,000 and sale cash of 408,000","An after tax gain of 128,000 and sale cash of 400,000","An after tax gain of 98,000 and sale cash of 98,000","An after tax gain of 98,000 and sale cash of 400,000"],"correct_index":3,"explanation":"Tax expense is 30,000 - 8,000 = 22,000, so the after tax gain is 120,000 - 22,000 = 98,000. Remeasuring a deferred tax balance is not an 8,000 cash receipt to add to the 400,000 of sale proceeds."},{"id":"cr-s21-level3-v1-q9","session":"21","level":3,"topic":"DTA and DTL simultaneous rate and balances","question":"An opening deferred tax asset of 30,000 euros and liability of 60,000 are measured at 30%, corresponding to deductible differences of 100,000 and taxable differences of 200,000. At closing the differences are deductible 120,000 and taxable 180,000, the applicable enacted rate is 25%, the asset is fully supported and all effects run through profit. What closing gross balances and net deferred tax effect follow?","choices":["Asset 30,000, liability 45,000 and a net benefit of 15,000","Asset 36,000, liability 54,000 and a net benefit of 12,000","Asset 30,000, liability 45,000 and a net expense of 15,000","Asset 25,000, liability 50,000 and a net benefit of 5,000"],"correct_index":0,"explanation":"The new asset is 120,000 × 25% = 30,000, unchanged, and the new liability is 180,000 × 25% = 45,000, down 15,000, so the net effect is a 15,000 benefit. Recompute the closing measurements from the differences rather than just applying the rate change to the opening balances."},{"id":"cr-s21-level3-v1-q10","session":"21","level":3,"topic":"Two transactions same cash different earnings","question":"Two independent transfers each bring in 1,000,000 euros cash and involve an old asset carried at 700,000. Transfer A qualifies as a sale and leaseback at a fair value of 1,000,000 with a market leaseback present value of 200,000 and a retained share of 20%. Transfer B fails the sale test and creates a 1,000,000 financing liability. No tax or other adjustment applies. What initial gains follow for A and B?","choices":["A gains 300,000 and B gains 300,000","A gains 240,000 and B gains zero","A gains 200,000 and B gains zero","A gains 240,000 and B gains 300,000"],"correct_index":1,"explanation":"For A the total gain of 300,000 times the 80% of rights transferred gives 240,000. B is financing with no disposal gain and the asset stays recognised. Equal cash proceeds do not imply equal profit, because the control test splits the two deals."}],"22":[{"id":"cr-s22-level1-v1-q1","session":"22","level":1,"topic":"Advance does not establish transfer","question":"A customer pays 24,000 euros on 1 January for services supplied evenly over the following 12 months. No service is transferred before that date, all IFRS 15 contract criteria are met and no separate upfront service exists. What initial revenue and liability follow on receipt?","choices":["Revenue 24,000 and no liability, treating the cash receipt as satisfaction","Revenue 12,000 and a liability of 12,000, recognising half at inception","Revenue zero and a contract liability of 24,000 euros","Revenue zero and a trade payable of 24,000, classifying the advance as a supplier balance"],"correct_index":2,"explanation":"Cash arrives before any service is transferred, so the entry is cash 24,000 against a contract liability of 24,000. Revenue follows performance, not payment."},{"id":"cr-s22-level1-v1-q2","session":"22","level":1,"topic":"Relative allocation basic bundle","question":"A contract sells two distinct goods, A and B, for 900 euros. Their stand alone prices are 600 and 400, and no exception to proportional allocation applies. What allocation follows?","choices":["A gets 600 and B gets 300","A gets 450 and B gets 450","A gets 500 and B gets 400","A gets 540 and B gets 360"],"correct_index":3,"explanation":"A receives 900 × 600/1,000 = 540 and B receives 900 × 400/1,000 = 360. The 100 discount is shared by relative stand alone prices, not split equally or dumped on one item."},{"id":"cr-s22-level1-v1-q3","session":"22","level":1,"topic":"Performance versus invoicing","question":"Control of a machine transfers to the customer on 30 June, with an unconditional right to 10,000 euros due on 30 July. All contract criteria are met and no remaining obligations or financing issues exist. What 30 June revenue and balance follow?","choices":["Revenue of 10,000 and a receivable of 10,000","Revenue of zero until the cash arrives on 30 July","Revenue of 10,000 and a contract liability of 10,000","Revenue of zero and a 10,000 contract fulfilment asset"],"correct_index":0,"explanation":"The obligation is satisfied and only the passage of time stands between the company and payment, so it recognises revenue of 10,000 and a receivable of 10,000 on 30 June. Waiting for cash would miss the transfer of control."},{"id":"cr-s22-level1-v1-q4","session":"22","level":1,"topic":"Distinctness both tests","question":"A supplier promises software plus substantial integration that significantly customises it into one combined output. The customer could benefit from generic software on its own, but in this contract the promises are not separately identifiable. What follows?","choices":["Separate obligations, because the customer can benefit from generic software alone","The promises are combined into one performance obligation in this contract","Software revenue on delivery, with the integration treated as an expense rather than a promise","A separate software obligation plus a combined obligation that includes the same software again"],"correct_index":1,"explanation":"Distinctness needs both tests: capable of separate benefit and separately identifiable within the contract. Significant integration fails the second test here, so the combined output is the unit of account."},{"id":"cr-s22-level1-v1-q5","session":"22","level":1,"topic":"Conditional right versus receivable","question":"A seller has earned revenue for transferred services, but its right to payment still depends on completing a further milestone rather than only on the passage of time. Which asset describes that earned conditional right?","choices":["A contract liability","A trade receivable","A contract asset","A capitalised contract acquisition cost"],"correct_index":2,"explanation":"A right to consideration that is conditional on something other than time is a contract asset. A transferred service can produce revenue before an unconditional right to payment exists. invoice timing alone is not the test."},{"id":"cr-s22-level1-v1-q6","session":"22","level":1,"topic":"Service revenue elapsed period","question":"A 12 month stand ready service has a total allocated price of 36,000 euros, with uniform performance and no other obligation. Service begins on 1 January and the year end is 31 March, after 3 months. What revenue follows?","choices":["36,000 euros","3,000 euros","27,000 euros","9,000 euros"],"correct_index":3,"explanation":"Uniform performance over 3 of 12 months earns 36,000 × 3/12 = 9,000. The unperformed nine months do not become revenue merely because the annual price is fixed."},{"id":"cr-s22-level1-v1-q7","session":"22","level":1,"topic":"Borrowing is not customer revenue","question":"During the period a firm obtains 100,000 euros of bank financing and collects 50,000 for a fully completed ordinary customer sale. These are its only receipts. How much qualifies as revenue?","choices":["50,000 euros","150,000 euros","100,000 euros","Zero, because both receipts are financing"],"correct_index":0,"explanation":"Only the satisfied customer sale is revenue. Loan proceeds create cash and a repayment obligation, not income from transferring goods or services in ordinary activities."},{"id":"cr-s22-level1-v1-q8","session":"22","level":1,"topic":"Contract collectibility gap","question":"An agreement fails the required probable collection criterion, so no IFRS 15 contract exists yet, and a customer deposit of 5,000 euros is received before any performance. What initial treatment follows?","choices":["Revenue of 5,000, using the deposit as evidence of collectibility","Cash and a liability of 5,000, with no revenue from the receipt alone","Cash of 5,000 with an equity credit, since no qualifying contract exists","Cash of 5,000 with a receivable credit, as if the deposit settled an existing claim"],"correct_index":1,"explanation":"Failing the contract criteria does not make received cash disappear or turn it into earned revenue. On these facts the funds are recorded as a liability until the criteria are met."},{"id":"cr-s22-level1-v1-q9","session":"22","level":1,"topic":"Cost to obtain distinct from receivable","question":"A supplier pays 6,000 euros of incremental sales commission that would not have arisen without winning a recoverable 3 year service contract. The recognition conditions for a contract cost asset are met and the benefit is consumed evenly over the 3 years. What annual amortisation follows?","choices":["6,000 euros of annual revenue","Zero, because a contract cost asset is an unpaid customer receivable","2,000 euros","18,000 euros"],"correct_index":2,"explanation":"The capitalised cost to obtain of 6,000 is amortised over the 3 year contract: 2,000 a year. This asset is not the IFRS 15 contract asset, which is a conditional right to customer consideration."},{"id":"cr-s22-level1-v1-q10","session":"22","level":1,"topic":"Simultaneous distinct goods remain distinct","question":"Two goods both meet the distinctness tests and no rule combines them, but they happen to be delivered at the same moment. What follows for identifying performance obligations?","choices":["One obligation, because identical delivery timing merges the promises","One obligation, because a single contract price sets the accounting unit","Two obligations only if the customer could buy each under a separate contract","Simultaneous delivery alone does not merge the two distinct promises"],"correct_index":3,"explanation":"The unit of account turns on distinctness, not delivery timing. Two distinct promises can be satisfied at the same moment and still carry their own allocations."},{"id":"cr-s22-level2-v1-q1","session":"22","level":2,"topic":"Expected variable consideration with constraint","question":"A contract has a fixed price of 500,000 euros with a penalty of 20,000 for each week of delay. Supported probabilities are 70% on time, 20% one week late and 10% two weeks late. Expected value is the best prediction and the resulting estimate passes the IFRS 15 variable consideration constraint. What transaction price follows?","choices":["500,000 euros","480,000 euros","488,000 euros","492,000 euros"],"correct_index":3,"explanation":"The expected penalty is 20% × 20,000 + 10% × 40,000 = 8,000, giving a price of 492,000. The constraint condition must be satisfied before an estimate of variable consideration is included in revenue."},{"id":"cr-s22-level2-v1-q2","session":"22","level":2,"topic":"Binary bonus method supplied","question":"A fixed contract price of 1,000,000 euros carries a possible extra 100,000 bonus if work is completed by a specified date. The most likely amount method best predicts this binary outcome, completion is strongly supported and including the full bonus passes the reversal constraint. What transaction price follows?","choices":["1,100,000 euros","1,095,000 euros","1,000,000 euros","1,050,000 euros"],"correct_index":0,"explanation":"The most likely amount is the full 100,000 bonus on top of the fixed 1,000,000, giving 1,100,000. The method that best predicts the consideration is used rather than defaulting to expected value by habit."},{"id":"cr-s22-level2-v1-q3","session":"22","level":2,"topic":"Bundle allocation and timing","question":"A distinct device and a 12 month service are sold together for 1,200 euros. Stand alone prices are 900 for the device and 600 for the service, with no allocation exception. Device control transfers immediately and the service is uniform. After 3 months of service, what cumulative revenue has been recognised?","choices":["1,050 euros","840 euros","1,200 euros","720 euros"],"correct_index":1,"explanation":"The device is allocated 1,200 × 900/1,500 = 720, recognised on transfer. The service is allocated 480, of which 3/12 = 120 is earned. Total cumulative revenue is 840. Neither the invoice label nor the stand alone price alone replaces relative allocation."},{"id":"cr-s22-level2-v1-q4","session":"22","level":2,"topic":"Cumulative output revenue","question":"A single over time obligation has a transaction price of 600,000 euros. A faithful output measure shows 40% completion, and cumulative revenue of 150,000 was already recognised in prior periods, with no estimate change or other obligation. What current period revenue follows?","choices":["240,000 euros","450,000 euros","90,000 euros","150,000 euros"],"correct_index":2,"explanation":"Required cumulative revenue is 600,000 × 40% = 240,000. Subtracting the 150,000 already recognised gives 90,000 for the current period. Cumulative progress is not automatically the current period's revenue."},{"id":"cr-s22-level2-v1-q5","session":"22","level":2,"topic":"Input method no inefficiency","question":"A single obligation qualifies for over time recognition. The transaction price is 900,000 euros, costs incurred are 240,000 and estimated total cost is 600,000. All costs faithfully depict progress, no wasted input or uninstalled material adjustment applies and no prior revenue exists. What revenue and gross profit follow?","choices":["Revenue 240,000 and zero gross profit","Revenue 900,000 and profit 660,000","Revenue 600,000 and profit 360,000","Revenue 360,000 and gross profit 120,000"],"correct_index":3,"explanation":"Progress is 240,000 / 600,000 = 40%, so revenue is 900,000 × 40% = 360,000, and deducting the 240,000 of costs gives a gross profit of 120,000. The stated assumptions make the cost based input measure appropriate rather than automatic."},{"id":"cr-s22-level2-v1-q6","session":"22","level":2,"topic":"Discount allocation exception explicit","question":"Distinct products A and B have stand alone prices of 100 and 200 euros and are regularly sold together for 240, while distinct product C regularly sells for 300 with no discount. All evidence meets the IFRS 15 condition to allocate the entire 60 bundle discount only to A and B. The contract price is 540. What allocation follows, treating A and B jointly?","choices":["A and B jointly 240 and C 300","A and B 270 and C 270, spreading the discount across all goods","A and B 300 and C 240, moving the discount to C","A and B 180 and C 360, applying the discount a second time"],"correct_index":0,"explanation":"The stated evidence supports the specific discount exception, so the discounted pair A and B keeps its observed 240 and C keeps 300, rather than defaulting to a proportional split of 540 over the 600 total. This says nothing about A and B being one performance obligation."},{"id":"cr-s22-level2-v1-q7","session":"22","level":2,"topic":"Contract liability rollforward","question":"An opening contract liability of 20,000 euros relates to an existing contract. New cash advances of 30,000 arrive, and 25,000 of revenue is recognised from obligations financed by those balances. No refunds, receivables or other movements exist. What is the closing contract liability?","choices":["75,000 euros","25,000 euros","5,000 euros","30,000 euros"],"correct_index":1,"explanation":"The rollforward is opening 20,000 + advances 30,000 - revenue released 25,000 = 25,000. Earning the revenue consumes part of the advance obligation. it does not add to it."},{"id":"cr-s22-level2-v1-q8","session":"22","level":2,"topic":"Contract cost asset closing","question":"A company pays an incremental 12,000 euro sales commission to win a 4 year customer service contract and expects to recover it, with even expected benefit and no renewal, impairment or other cost. One full year has elapsed. What amortisation expense and closing contract cost asset follow?","choices":["Expense 12,000 and asset zero","Expense 3,000 and a contract receivable of 12,000","Expense 3,000 and an asset of 9,000","Expense 4,000 and an asset of 8,000"],"correct_index":2,"explanation":"The 12,000 is spread over 4 years, giving an annual expense of 3,000 and a remaining asset of 9,000 after one year. A cost to obtain asset is not an unconditional right to customer payment."},{"id":"cr-s22-level2-v1-q9","session":"22","level":2,"topic":"Constraint overrides attractive estimate","question":"A contract has fixed consideration of 200,000 euros and a possible bonus of 50,000. Expected value predicts a 30,000 bonus, but the facts explicitly fail the condition that a significant revenue reversal be highly improbable, so the entire bonus must be excluded at this date. What transaction price follows?","choices":["230,000 euros","250,000 euros","180,000 euros","200,000 euros"],"correct_index":3,"explanation":"Estimating the variable amount and constraining it are separate steps. The failed constraint excludes the whole bonus despite the 30,000 estimate, leaving the price at the fixed 200,000. Arithmetic alone cannot justify recognising unsupported variable consideration."},{"id":"cr-s22-level2-v1-q10","session":"22","level":2,"topic":"Unconditional right after milestone","question":"An opening contract asset of 15,000 euros becomes unconditional when a contractual milestone is achieved, with no new performance or revenue at that moment and no cash received. What reclassification follows?","choices":["The contract asset falls 15,000, the receivable rises 15,000 and no new revenue arises","The contract asset stays 15,000, the receivable rises 15,000 and revenue rises 15,000","The contract asset falls 15,000, no receivable arises and revenue falls 15,000","The contract asset falls 15,000, a liability rises 15,000 and no new revenue arises"],"correct_index":0,"explanation":"A previously earned conditional right becoming unconditional is reclassified to a receivable. The revenue was already recognised when the performance transferred, so nothing new is earned at this point."},{"id":"cr-s22-level3-v1-q1","session":"22","level":3,"topic":"Bundle with staged satisfaction","question":"A contract priced at 240,000 euros covers three distinct obligations with stand alone prices of 120,000 for goods, 120,000 for annual support and 60,000 for training, with no allocation exception. The goods are delivered now, uniform support is 3 of 12 months complete and training has not started. What cumulative revenue and remaining allocated consideration follow?","choices":["Revenue 120,000 and remaining 120,000","Revenue 150,000 and remaining 90,000","Revenue 240,000 and remaining zero","Revenue 96,000 and remaining 144,000"],"correct_index":0,"explanation":"Allocation over the 300,000 stand alone total gives goods 96,000, support 96,000 and training 48,000. Earned so far: goods 96,000 plus 3/12 of support, 24,000, totals 120,000. Remaining: support 72,000 plus training 48,000, also 120,000. Unperformed training cannot be recognised just because cash was paid."},{"id":"cr-s22-level3-v1-q2","session":"22","level":3,"topic":"Cost estimate change cumulative catchup","question":"An over time obligation has a price of 1,000,000 euros. Prior costs of 200,000 against an estimated total of 500,000 generated cumulative revenue of 400,000. This period another 100,000 of cost is incurred and the total estimate rises to 750,000. All costs faithfully measure progress and no other adjustment applies. What current revenue and current gross profit follow?","choices":["Revenue 200,000 and profit 100,000","Revenue zero and a gross loss of 100,000","Revenue 400,000 and profit 300,000","Revenue 100,000 and zero gross profit"],"correct_index":1,"explanation":"The new cumulative progress is 300,000 / 750,000 = 40%, so required cumulative revenue is still 400,000, matching what was already recognised: no current revenue. The 100,000 of current costs therefore produces a 100,000 gross loss for the period, even though the contract as a whole remains profitable."},{"id":"cr-s22-level3-v1-q3","session":"22","level":3,"topic":"Variable price change after partial performance","question":"A single over time obligation is 50% complete at both the earlier and the current measurement dates, with no new performance in between. The prior transaction price of 400,000 euros gave cumulative revenue of 200,000. A newly includable bonus now raises the transaction price to 460,000 and passes the constraint. What current revenue adjustment follows?","choices":["An increase of 60,000","An increase of 230,000","An increase of 30,000","Zero, because no new physical performance occurred"],"correct_index":2,"explanation":"The revised cumulative revenue is 460,000 × 50% = 230,000, against 200,000 already recognised: a 30,000 catch up. A change in the constrained transaction price adjusts earned revenue even without new performance at that moment."},{"id":"cr-s22-level3-v1-q4","session":"22","level":3,"topic":"Input inefficiency excluded explicit","question":"A valid over time contract priced at 600,000 euros uses a cost based input measure. Costs incurred so far total 210,000, of which 30,000 is material wasted in an unexpected production error that created no usable work; the remaining costs faithfully depict the performance delivered. The total estimated contract cost, excluding the waste, is 450,000. No prior revenue or other adjustment exists. What revenue and current profit follow?","choices":["Revenue 280,000 and profit 70,000","Revenue 240,000 and profit 60,000","Revenue 600,000 and profit 390,000","Revenue 240,000 and profit 30,000"],"correct_index":3,"explanation":"Progress excludes the wasted material because it does not depict performance: (210,000 - 30,000) / 450,000 = 40%, so revenue is 240,000. All 210,000 of costs incurred are expensed, including the waste, leaving a profit of 30,000. Counting the waste in the progress measure would improperly accelerate revenue."},{"id":"cr-s22-level3-v1-q5","session":"22","level":3,"topic":"Three dates cash revenue receivable","question":"A seller receives a 40,000 euro advance, then satisfies a single obligation with an allocated price of 100,000, earning an unconditional right to the unpaid 60,000, still uncollected at the reporting date. No other transactions, taxes or costs exist. What cumulative cash, revenue, receivable and closing contract liability follow?","choices":["Cash 40,000, revenue 100,000, receivable 60,000 and liability zero","Cash 100,000, revenue 40,000, receivable 60,000 and liability 40,000","Cash 40,000, revenue 60,000, receivable 100,000 and liability 40,000","Cash 40,000, revenue 100,000, receivable 100,000 and liability 40,000"],"correct_index":0,"explanation":"The satisfied obligation releases the 40,000 advance into revenue and creates a receivable for the unconditional 60,000, so revenue is 100,000, cash stays at the 40,000 actually collected and no contract liability remains. The advance is neither kept as a liability nor billed twice."},{"id":"cr-s22-level3-v1-q6","session":"22","level":3,"topic":"Discount and material right allocate","question":"A contract sells a distinct current product and a distinct future service for 180 euros. Their stand alone prices are 150 and 50, with no specific discount exception. The product transfers immediately and no service has been performed. What initial revenue and deferred service allocation follow?","choices":["Revenue 150 and remaining 30","Revenue 135 and remaining 45","Revenue 180 and remaining zero","Revenue 90 and remaining 90"],"correct_index":1,"explanation":"Relative allocation gives the product 180 × 150/200 = 135 and the future service 45. Calling the service free does not erase its allocated price or allow recognising it before transfer."},{"id":"cr-s22-level3-v1-q7","session":"22","level":3,"topic":"Misclassification cost asset versus contract right","question":"A supplier has capitalised 8,000 euros of recoverable incremental commission, and separately has earned 20,000 of revenue for transferred services whose right to payment depends on completing another milestone. Neither amount is unconditional and no impairment applies. How should the balances be distinguished?","choices":["A receivable of 28,000, combining both as unconditional claims","A contract asset of 28,000, combining the commission cost and the conditional earned consideration","A contract cost asset of 8,000 and a contract asset of 20,000","A contract cost asset of 20,000 and a contract asset of 8,000, reversing the two"],"correct_index":2,"explanation":"The commission is a cost to obtain asset, while the earned conditional right to consideration is a contract asset. They differ in origin, measurement and subsequent path to expense or billing, despite similar sounding labels."},{"id":"cr-s22-level3-v1-q8","session":"22","level":3,"topic":"Output versus cash and cost","question":"An obligation qualifies for over time recognition and a faithful output assessment shows 30% completion of a 900,000 euro contract. Cash collected is 400,000 and costs of 350,000, all expensed, have been incurred. No other performance, prior period, loss provision or adjustment applies. What revenue, gross result and net advance position follow?","choices":["Revenue 400,000, profit 50,000 and no advance","Revenue 350,000, profit zero and a liability of 50,000","Revenue 270,000, profit 80,000 and a contract asset of 130,000","Revenue 270,000, gross loss 80,000 and a contract liability of 130,000"],"correct_index":3,"explanation":"Output progress of 30% × 900,000 gives revenue of 270,000, and costs of 350,000 produce a gross loss of 80,000. Cash of 400,000 exceeds earned revenue by 130,000, a contract liability. The specified faithful output measure is not replaced by cash collected or costs incurred."},{"id":"cr-s22-level3-v1-q9","session":"22","level":3,"topic":"Revenue and consideration reversal","question":"A product obligation previously satisfied has recognised revenue of 100,000 euros. New supported information reduces the expected entitled price to 92,000, and the updated variable estimate passes the constraint. No return asset or further performance exists. What current revenue effect follows?","choices":["A revenue reduction of 8,000, updating the cumulative amount on the satisfied obligation","A revenue increase of 92,000, treating the revised total as new performance","No adjustment, treating the estimate change as a future period event","An operating expense of 8,000, leaving the original revenue intact"],"correct_index":0,"explanation":"The updated entitled consideration cuts cumulative revenue from 100,000 to 92,000, so 8,000 of negative revenue is recorded. It is not a new sale, and on these facts it is not automatically a credit loss expense."},{"id":"cr-s22-level3-v1-q10","session":"22","level":3,"topic":"Allocation and contract cost combined","question":"A 120,000 euro contract has distinct goods with a stand alone price of 80,000 and a distinct service at 70,000, with relative allocation and no exception. The goods transfer now and the service is unperformed. An incremental recoverable commission of 6,000 is capitalised, and its amortisation is explicitly set to follow this contract's transfer pattern using the same allocation ratio. What initial revenue, commission expense and remaining commission asset follow?","choices":["Revenue 80,000, commission expense 6,000 and nothing remaining","Revenue 64,000, commission expense 3,200 and a remaining asset of 2,800","Revenue 64,000, commission expense 2,800 and a remaining asset of 3,200","Revenue 120,000, commission expense 6,000 and nothing remaining"],"correct_index":1,"explanation":"The goods allocation is 120,000 × 80/150 = 64,000. The specified matching amortises 6,000 × 80/150 = 3,200 of commission now, leaving 2,800 for the future service. The prompt supplies the amortisation pattern rather than assuming a universal ratio for every cost asset."}],"23":[{"id":"cr-s23-level1-v1-q1","session":"23","level":1,"topic":"Loyalty option is a promise","question":"A retailer sells goods together with a customer option that provides a material right to future goods. Both are distinct and the allocation rules apply. The goods transfer now and the option remains unexercised and unexpired. Which treatment is correct?","choices":["Recognise the full cash now, treating the option as a promotional selling expense","Defer the full cash until exercise or expiry, because one promise remains open","Allocate consideration to the material right and defer that part until transfer or expiry","Recognise the option allocation as a receivable, released when the customer exercises"],"correct_index":2,"explanation":"A material right is a separate performance obligation, so its allocated share of the price waits as a contract liability until the promise is satisfied or expires. The label option does not remove the unfulfilled promise."},{"id":"cr-s23-level1-v1-q2","session":"23","level":1,"topic":"Simple loyalty allocation","question":"A shop receives 110 euros for delivered goods plus a material right to future goods. Their stand alone values are 100 and 10. What initial revenue on the goods and liability for the option follow?","choices":["Revenue 110 and liability zero","Revenue 90 and liability 20","Revenue 55 and liability 55","Revenue 100 and liability 10"],"correct_index":3,"explanation":"Relative allocation gives the delivered goods 110 × 100/110 = 100 and the outstanding material right 10. Receiving cash for both promises does not satisfy both."},{"id":"cr-s23-level1-v1-q3","session":"23","level":1,"topic":"Returns reduce entitled consideration","question":"An entity sells 100 products at 120 euros each and expects 5 returns under a valid return right. The estimate is supported and passes the IFRS 15 constraint, with no financing or tax. What initial revenue follows?","choices":["11,400 euros","12,000 euros","600 euros","11,000 euros"],"correct_index":0,"explanation":"The expected retained 95 products earn 95 × 120 = 11,400. The 600 expected refund is a refund liability. customers paying 12,000 up front does not make it all revenue."},{"id":"cr-s23-level1-v1-q4","session":"23","level":1,"topic":"Refund liability basic","question":"A seller receives 9,000 euros for 90 products at 100 each and expects 4 products to be returned for a full refund, supported by predictive experience with the constraint met. What refund liability follows?","choices":["8,600 euros","400 euros","9,000 euros","Zero until actual returns occur"],"correct_index":1,"explanation":"The refund liability is 4 expected returns × 100 selling price = 400. Measuring it at cost, or waiting for actual refunds, would misstate the obligation at the date of sale."},{"id":"cr-s23-level1-v1-q5","session":"23","level":1,"topic":"Recovery asset basic","question":"Goods costing 60 euros each are sold with a return right, and 4 units are expected to be returned. Recovery costs are zero and the returned goods are expected to be fully recoverable at their previous cost. What initial right to recover returned goods asset follows?","choices":["400, using the customer selling price","60, the unit cost without multiplying by expected returns","240, the cost of the expected recoverable units","160, the four units' margin rather than their cost"],"correct_index":2,"explanation":"The recovery asset is measured at the former carrying amount of the goods expected back: 4 × 60 = 240, not at selling price. It is presented separately from the refund liability."},{"id":"cr-s23-level1-v1-q6","session":"23","level":1,"topic":"Joining activity not necessarily service","question":"A club collects a non-refundable registration fee for administrative set up. The set up transfers no separate service to the customer and access services begin later. What is recognised from the fee at collection?","choices":["Current revenue for the administrative set up activity","Deferred recognition of both cash and fee until access begins","A refund payable to be repaid when membership ends","A contract liability pending provision of the related services"],"correct_index":3,"explanation":"Revenue depends on transferring promised goods or services. Internal administration transfers nothing on these facts, so the fee is a contract liability until the related access services are provided. Cash is still recorded on receipt."},{"id":"cr-s23-level1-v1-q7","session":"23","level":1,"topic":"Annual fee included with service","question":"A 12 month uniform access contract starts on 1 January. Total consideration is 1,200 euros, including an upfront administrative fee that is not distinct. There is no renewal benefit or further obligation. What revenue is recognised after 3 months?","choices":["300 euros","1,200 euros","100 euros","900 euros"],"correct_index":0,"explanation":"On the stated facts the whole 1,200 attaches to the 12 month service, so 3 months earns 300. Accelerating the administrative fee at signing would treat an internal activity as a transferred service."},{"id":"cr-s23-level1-v1-q8","session":"23","level":1,"topic":"Cash above earned services","question":"A valid over time service contract has earned revenue of 80,000 euros by the reporting date, cash advances collected are 100,000 and no other rights or transactions exist. What net customer contract balance follows?","choices":["A contract asset of 20,000","A contract liability of 20,000","A receivable of 100,000","Revenue of 100,000, because cash determines progress"],"correct_index":1,"explanation":"Cash exceeds transferred performance by 20,000, so the firm owes future service: a contract liability of 20,000. The excess is not a right to collect more consideration."},{"id":"cr-s23-level1-v1-q9","session":"23","level":1,"topic":"Output measured correctly","question":"A single obligation qualifies for over time recognition, with a price of 450,000 euros. A faithful independent output measure shows one third completion and no prior revenue exists. What cumulative revenue follows?","choices":["450,000 euros","300,000 euros","150,000 euros","225,000 euros"],"correct_index":2,"explanation":"Revenue is 450,000 × 1/3 = 150,000. The facts supply both the over time qualification and a faithful progress measure, avoiding the invalid shortcut that every long contract automatically qualifies."},{"id":"cr-s23-level1-v1-q10","session":"23","level":1,"topic":"Refund and recovery not offset","question":"A return arrangement generates a refund liability of 1,000 euros and a separate recovery asset of 600 euros, with no other amounts. How should these balances be presented?","choices":["A net liability of 400, offsetting the recovery asset against refunds","A recovery asset of 1,000 and a liability of 600, reversing the bases","A liability of 1,600, combining both without a separate recovery asset","Separately, as a liability of 1,000 and a recovery asset of 600"],"correct_index":3,"explanation":"The refund obligation and the right to recover goods are separate balances on different measurement bases. They are not collapsed into a single net 400 in this arrangement."},{"id":"cr-s23-level2-v1-q1","session":"23","level":2,"topic":"Loyalty allocation and partial redemption","question":"A sale for 220 euros includes current goods with a stand alone value of 200 and an award obligation with a stand alone value of 50, with no discount exception. The goods transfer now. Later, half of the allocated award obligation is satisfied through redemption, with no breakage or estimate change. What cumulative revenue follows?","choices":["220 euros","200 euros","176 euros","198 euros"],"correct_index":3,"explanation":"The goods are allocated 220 × 200/250 = 176 and the award 44, of which half, 22, is earned on redemption. Cumulative revenue is 176 + 22 = 198, leaving 22 of obligation. The full stand alone award value is never added to consideration."},{"id":"cr-s23-level2-v1-q2","session":"23","level":2,"topic":"Returns profit bridge","question":"An entity sells 200 units at 50 euros each, costing 30 per unit. Supported expected returns are 10 units, with no recovery cost or impairment and the constraint met. What revenue, cost of sales and gross profit follow at the date of sale?","choices":["Revenue 9,500, cost 5,700 and gross profit 3,800","Revenue 10,000, cost 6,000 and profit 4,000","Revenue 9,500, cost 6,000 and profit 3,500","Revenue 10,000, cost 5,700 and profit 4,300"],"correct_index":0,"explanation":"The retained 190 units generate revenue of 9,500. The expected recovery asset of 10 × 30 = 300 reduces the 6,000 of inventory cost released to cost of sales of 5,700, giving a gross profit of 3,800. The refund liability of 500 is recorded separately."},{"id":"cr-s23-level2-v1-q3","session":"23","level":2,"topic":"Returns recovery costs","question":"A seller expects 6 products to be returned. Each cost 80 euros and the expected recovery cost is 5 per item, with no other impairment. What recovery asset follows?","choices":["480 euros","450 euros","510 euros","30 euros"],"correct_index":1,"explanation":"The asset is 6 × (80 - 5) = 450. Expected recovery costs reduce the recoverable carrying amount, and the selling price is irrelevant to measuring this asset."},{"id":"cr-s23-level2-v1-q4","session":"23","level":2,"topic":"Expected returns revision","question":"Initially 100 items at 100 euros each were sold with 5 expected returns. Before any return occurs, supported constraint compliant estimates cut expected returns to 2. What current revenue increase and closing refund liability follow?","choices":["A revenue increase of 200 and a liability of 300","A revenue increase of 500 and a liability of zero","A revenue increase of 300 and a liability of 200","No revenue change until refunds are paid"],"correct_index":2,"explanation":"The refund liability falls from 500 to 200, and the 300 reduction increases the consideration the entity expects to keep, so revenue rises by 300. This is neither a new cash sale nor an automatic expense reversal."},{"id":"cr-s23-level2-v1-q5","session":"23","level":2,"topic":"Return rate revision recovery counterpart","question":"Inventory of 100 units at 40 euros each is sold with 5 expected returns initially, no recovery costs or loss in value. Before any returns occur, expected returns fall to 2. What change in the recovery asset and cost of sales follows?","choices":["The recovery asset rises 120 and cost of sales falls 120","The recovery asset falls 300 and cost of sales rises 300, using the sales price","The recovery asset stays at 200 and cost of sales is unchanged until physical returns","The recovery asset falls 120 and cost of sales rises 120"],"correct_index":3,"explanation":"Expected recovery falls from 5 × 40 = 200 to 2 × 40 = 80, so the asset decreases by 120 and cost of sales rises by 120. A return estimate revision updates both the revenue/refund side and the inventory/recovery side together."},{"id":"cr-s23-level2-v1-q6","session":"23","level":2,"topic":"Joining fee revenue with explicit benefit horizon","question":"A club collects a non-distinct joining fee of 240 euros plus 960 for initial access. All consideration pays for a uniform 12 month service, with no renewal right or benefit beyond the 12 months. What revenue follows for the first 6 months?","choices":["600 euros","720 euros","1,200 euros","480 euros"],"correct_index":0,"explanation":"The total of 1,200 attaches to one year of uniform service, so 6 months earns 600. Recognising 240 at signing plus 480 of service would wrongly treat internal registration as a distinct transfer."},{"id":"cr-s23-level2-v1-q7","session":"23","level":2,"topic":"Eligible setup cost amortisation","question":"A provider incurs 9,000 euros of recoverable contract fulfilment costs that meet the asset recognition conditions and benefit 3 years of uniform service. One full year is complete and there is no impairment. What expense and closing asset follow?","choices":["Expense 9,000 and asset zero","Expense 3,000 and asset 6,000","Revenue 3,000 and receivable 6,000","Expense zero and a permanent asset of 9,000"],"correct_index":1,"explanation":"The eligible cost asset is amortised as the related services transfer: 3,000 a year, leaving 6,000 after one year. It is separate from any conditional right to customer payment and never creates revenue itself."},{"id":"cr-s23-level2-v1-q8","session":"23","level":2,"topic":"Output costs do not select input measure","question":"A contract qualifies for over time recognition, priced at 720,000 euros. A faithful output measure shows 25% completion. Actual costs of 210,000 are expensed and remaining costs are reliably estimated at 350,000, with no loss provision or other adjustment. What revenue and gross result follow?","choices":["Revenue 270,000 and profit 60,000","Revenue 210,000 and zero profit","Revenue 180,000 and a gross loss of 30,000","Revenue 360,000 and profit 150,000"],"correct_index":2,"explanation":"The specified output measure gives 25% × 720,000 = 180,000 of revenue, against 210,000 of costs: a gross loss of 30,000. The cost fraction of 210/560 = 37.5% is not used because the facts designate the output method as the faithful one."},{"id":"cr-s23-level2-v1-q9","session":"23","level":2,"topic":"Loyalty balance without breakage","question":"An award obligation has an opening balance of 18,000 euros, increased by 6,000 of new allocations. Satisfied redemptions release 9,000, and no breakage or estimate change applies. What closing obligation and award revenue follow?","choices":["Closing 24,000 and revenue zero","Closing 3,000 and revenue 21,000","Closing 15,000 and revenue 15,000","Closing 15,000 and award revenue 9,000"],"correct_index":3,"explanation":"The rollforward is 18,000 + 6,000 - 9,000 = 15,000 of liability. New allocations do not themselves earn award revenue. only actual satisfaction releases the 9,000."},{"id":"cr-s23-level2-v1-q10","session":"23","level":2,"topic":"Actual expected returns settlement","question":"At the date of sale, a refund liability of 600 euros and a recovery asset of 360 were recognised for 6 expected returns. Exactly those 6 units are now returned and refunded, with no estimate change or recovery cost. What settlement effect follows?","choices":["Cash falls 600, the liability falls 600, the recovery asset falls 360 and inventory rises 360","Cash falls 600, revenue falls 600, the recovery asset falls 360 and cost of sales rises 360","Cash falls 360, the liability falls 600, inventory rises 360 and profit rises 240","Cash falls 600, the liability falls 600, the recovery asset stays at 360 and inventory rises 360"],"correct_index":0,"explanation":"Settlement uses the balances already recognised: the refund debits the liability and credits cash for 600, and the returned units move the recovery asset of 360 back into inventory. Reversing revenue again would double count the original estimate."},{"id":"cr-s23-level3-v1-q1","session":"23","level":3,"topic":"Loyalty revised expected exercise","question":"A material right receives allocated consideration of 12,000 euros for 1,000 issued points. Expected total redemptions were initially 800. At the reporting date 300 points have been redeemed and expected total redemptions are revised to 600. Recognition is proportional to actual redemptions over expected total, the breakage criteria are met and nothing else changes. What cumulative award revenue and liability follow?","choices":["Revenue 6,000 and liability 6,000","Revenue 3,600 and liability 8,400","Revenue 4,500 and liability 7,500","Revenue 12,000 and liability zero"],"correct_index":0,"explanation":"The revised satisfaction fraction is 300/600 = 50%, so cumulative revenue is 50% × 12,000 = 6,000 and the remaining liability is 6,000. The denominator is the supported expected total redemptions, not the 1,000 points issued or the stale 800 estimate."},{"id":"cr-s23-level3-v1-q2","session":"23","level":3,"topic":"Loyalty cumulative catchup","question":"A material right carries an allocation of 20,000 euros. In a prior period 200 points were redeemed out of 800 expected total, generating 5,000 of revenue. At the current date 400 points are cumulatively redeemed and expected total redemptions are revised to 1,000, with qualifying breakage assumptions and no other change. What current period award revenue follows?","choices":["8,000 euros","3,000 euros","5,000 euros","10,000 euros"],"correct_index":1,"explanation":"The new cumulative revenue is 20,000 × 400/1,000 = 8,000, less the 5,000 already recognised: 3,000 this period. Raising expected total redemptions enlarges the denominator and slows recognition per redeemed point."},{"id":"cr-s23-level3-v1-q3","session":"23","level":3,"topic":"Returns integrated revision","question":"A seller sold 100 units at 150 euros each, costing 90 each, with 8 returns expected at sale, no recovery costs and the constraint met. Before any returns, the supported expectation falls to 3. What current revenue change, cost of sales change and profit change follow?","choices":["Revenue up 750, cost down 450 and profit up 1,200","Revenue up 450, cost up 750 and profit down 300","Revenue up 750, cost up 450 and profit up 300","No change until the return window expires"],"correct_index":2,"explanation":"Five fewer expected returns release 5 × 150 = 750 of refund liability into revenue, but the recovery asset falls by 5 × 90 = 450 into cost of sales. The net profit benefit is 300, and both sides must be updated consistently."},{"id":"cr-s23-level3-v1-q4","session":"23","level":3,"topic":"Returns with impairment and recovery costs","question":"A sale transfers 500 units at 80 euros each, originally costing 50. Supported expected returns are 20 units, each requiring 3 euros of recovery cost and with recovered value reduced by a further 7 euros from original cost. Both reductions apply to the recovery asset, the constraint is met and no other adjustment exists. What revenue, recovery asset, cost of sales and gross profit follow?","choices":["Revenue 38,400, recovery asset 1,000, cost 24,000 and profit 14,400","Revenue 40,000, recovery asset 800, cost 24,200 and profit 15,800","Revenue 38,400, recovery asset 940, cost 24,060 and profit 14,340","Revenue 38,400, recovery asset 800, cost 24,200 and profit 14,200"],"correct_index":3,"explanation":"Revenue is the retained 480 × 80 = 38,400. The recovery asset is 20 × (50 - 3 - 7) = 800, so cost of sales is 25,000 - 800 = 24,200 and gross profit is 14,200. The refund liability of 20 × 80 = 1,600 is recorded separately."},{"id":"cr-s23-level3-v1-q5","session":"23","level":3,"topic":"Return obligation after partial settlement","question":"Initially 10 returns were expected at a selling price of 100 euros and cost of 60, with no recovery costs or loss in value. Four units have actually been returned and refunded, and a supported estimate now expects 3 more returns, with the constraint met. What closing refund liability, recovery asset and incremental revenue change from the estimate revision follow?","choices":["Liability 300, recovery asset 180 and a revenue increase of 300","Liability 600, recovery asset 360 and no revenue change","Liability 700, recovery asset 420 and a revenue decrease of 300","Liability 300, recovery asset 180 and a revenue increase of 700"],"correct_index":0,"explanation":"The initial liability of 1,000 and recovery asset of 600 settle 400 and 240 for the 4 actual returns, leaving 600 and 360. The 3 further expected returns need only 300 and 180, so another 300 of liability is released to revenue. The settled 4 units are not counted again as future returns."},{"id":"cr-s23-level3-v1-q6","session":"23","level":3,"topic":"Upfront fee renewal benefit explicit","question":"A club charges a non-distinct joining fee of 300 euros plus annual access of 600. Evidence establishes a 3 year expected relationship and a renewal option conveying a material right, and the established allocation assigns the 300 joining consideration to that 3 year right and the 600 to year 1 access. The right is satisfied uniformly over 3 years, and all year 1 services are complete. What year 1 revenue and closing liability follow?","choices":["Revenue 900 and liability zero","Revenue 700 and liability 200","Revenue 300 and liability 600","Revenue 600 and liability 300 held forever"],"correct_index":1,"explanation":"Year 1 earns the 600 of completed access plus one third of the 300 right allocation, 100, giving 700. The remaining 200 is unearned. Actual renewal benefits and their allocation drive the answer, not an assumption that every joining fee follows the initial access term."},{"id":"cr-s23-level3-v1-q7","session":"23","level":3,"topic":"Output catchup with prior revenue","question":"A qualifying over time service has a price of 900,000 euros. A faithful output method previously showed 20% completion with 180,000 of revenue recognised. Cumulative output is now 35%, and cumulative costs are 360,000, of which 200,000 arose this period, with no other adjustment. What current revenue and current gross result follow?","choices":["Revenue 315,000 and profit 115,000","Revenue 180,000 and a loss of 20,000","Revenue 135,000 and a gross loss of 65,000","Revenue 360,000 and profit 160,000"],"correct_index":2,"explanation":"New cumulative revenue is 900,000 × 35% = 315,000, less the 180,000 already recognised: 135,000 this period. Current costs of 200,000 turn that into a 65,000 current loss. Comparing cumulative revenue with only current costs would misstate both."},{"id":"cr-s23-level3-v1-q8","session":"23","level":3,"topic":"Bad output progress adjustment","question":"A qualifying over time contract priced at 1,000,000 euros has independently verified faithful output progress of 40%. A manager instead uses costs paid of 500,000 over an estimate of 600,000 to record 833,333 of revenue, even though the costs do not faithfully depict progress. No prior revenue exists. What correction to the rounded revenue figure follows?","choices":["Increase revenue by 166,667 to 1,000,000","Keep 833,333, because any cost percentage is valid","Reduce revenue by 333,333 to the cash cost of 500,000","Reduce revenue by 433,333 to 400,000"],"correct_index":3,"explanation":"The faithful output measure requires 1,000,000 × 40% = 400,000, so the recorded 833,333 is cut by 433,333. Paying inputs is not the same as transferring output when the costs do not depict progress."},{"id":"cr-s23-level3-v1-q9","session":"23","level":3,"topic":"Multiple balances not all receivables","question":"At the reporting date an entity holds a contract liability of 12,000 euros for unperformed access, a recovery asset of 4,000 and a refund liability of 7,000 on separate return sales, plus 3,000 of capitalised commission. Assume no netting rights or other balances. What gross assets and liabilities arise?","choices":["Assets 7,000 and liabilities 19,000","Assets 19,000 and liabilities 7,000, reversing the classifications","A net liability of 12,000 only, offsetting the independent balances","Assets 4,000 and liabilities 19,000, expensing the commission"],"correct_index":0,"explanation":"Assets are the recovery asset of 4,000 plus the cost asset of 3,000, totalling 7,000. Liabilities are the unperformed access of 12,000 plus expected refunds of 7,000, totalling 19,000. None of these is automatically an unconditional customer receivable."},{"id":"cr-s23-level3-v1-q10","session":"23","level":3,"topic":"Revenue cost asset and cash combined","question":"A valid 12 month uniform service contract receives a 120,000 euro advance and no further payment. A recoverable commission of 12,000 is capitalised and consumed uniformly over the same 12 months. After 3 months, ordinary service costs of 18,000 have also been expensed, with no other items. What revenue, total expense, profit and closing contract liability follow?","choices":["Revenue 120,000, expense 30,000, profit 90,000 and liability zero","Revenue 30,000, expense 21,000, profit 9,000 and liability 90,000","Revenue 30,000, expense 18,000, profit 12,000 and liability 90,000","Revenue 30,000, expense 21,000, profit 9,000 and liability 120,000"],"correct_index":1,"explanation":"Three months earn 120,000 × 3/12 = 30,000, leaving an advance liability of 90,000. Expenses are commission amortisation of 12,000 × 3/12 = 3,000 plus service costs of 18,000, totalling 21,000 and giving a profit of 9,000. The remaining 9,000 commission asset is a separate balance."}],"24":[{"id":"cr-s24-level1-v1-q1","session":"24","level":1,"topic":"Modified retrospective comparison","question":"A modified retrospective adopter reports current revenue on the new basis and keeps the prior comparative on the old basis. Which comparison measures growth on one consistent old basis?","choices":["Current reported revenue against the original prior revenue","Current reported revenue plus the opening equity adjustment, against prior revenue","Current revenue without adoption, against the original prior revenue","Current reported revenue against the opening retained earnings balance"],"correct_index":2,"explanation":"Modified transition places old basis comparatives next to new basis current figures. The supplied counterfactual current revenue without adoption is the figure to compare with the old basis prior year before treating reported growth as economic."},{"id":"cr-s24-level1-v1-q2","session":"24","level":1,"topic":"Full retrospective comparison","question":"An illustrative company applies full retrospective transition and restates every comparative period it presents under the new revenue policy. What follows?","choices":["Comparatives keep the old basis, with the new policy applied only prospectively","Comparatives keep the old basis, with earlier effects only in current opening equity","Comparatives use the new basis, so their restated growth measures a change in cash sales","Presented restated periods sit on the new revenue basis under this approach"],"correct_index":3,"explanation":"Restating the presented comparatives puts every period on one consistent new policy basis. A restatement alone does not establish real economic growth or remove all judgement."},{"id":"cr-s24-level1-v1-q3","session":"24","level":1,"topic":"Opening equity is not current sales","question":"At adoption, a modified retrospective change increases opening retained earnings by 40 million euros, aggregating cumulative net effects from earlier periods. What can be concluded about current year revenue from this amount alone?","choices":["Nothing, because the amount aggregates earlier periods and effects beyond revenue","Revenue rises by 40 million, because the adjustment is a revenue correction","Revenue falls by 40 million, because earlier revenue is reversed","Revenue rises by the after tax share of 40 million, once tax is deducted"],"correct_index":0,"explanation":"An opening retained earnings adjustment aggregates cumulative net effects, potentially including costs and tax. It identifies neither current revenue nor cash, so a current period bridge is needed."},{"id":"cr-s24-level1-v1-q4","session":"24","level":1,"topic":"Positive adjustment no universal superiority","question":"Two companies adopt the same revenue standard with the same transition approach. One shows a positive and the other a negative opening equity effect. Which explanation is consistent with the different signs?","choices":["The company with the positive adjustment necessarily has higher earnings quality","Different contracts and earlier recognition patterns can produce opposite cumulative effects","The company with the negative adjustment necessarily committed a prior accounting error","The two companies must have used different standards despite their stated common adoption"],"correct_index":1,"explanation":"The same standard lands on different contracts and different old policy timing, so cumulative effects can have opposite signs. A sign alone establishes nothing about quality, misstatement or motive."},{"id":"cr-s24-level1-v1-q5","session":"24","level":1,"topic":"Backlog not completed performance","question":"An illustrative contractor discloses 500 million euros of remaining performance obligations at year end, none of which has yet been satisfied. Which statement is correct?","choices":["It is 500 million of current revenue, because signed contracts create enforceable rights","It is 500 million of cash collected, because obligations remain after customers pay","It is future allocated consideration, not current revenue before performance","It is 500 million of receivables, because the amounts are unconditional claims"],"correct_index":2,"explanation":"Remaining performance obligations concern future performance. The disclosure helps readers see the timing of future revenue, but it neither satisfies the transfer requirement nor establishes unconditional payment rights."},{"id":"cr-s24-level1-v1-q6","session":"24","level":1,"topic":"Adoption no automatic cash change","question":"In a simplified noncash adoption entry, 20 million euros of deferred revenue is removed and credited to opening retained earnings. There is no tax, cost or other entry. How much cash does this entry create?","choices":["Cash increases by 20 million","Cash decreases by 20 million","Cash doubles, whatever the opening balance","Zero"],"correct_index":3,"explanation":"The entry moves an existing liability into equity with no cash leg. Recognition timing and cash timing are separate questions."},{"id":"cr-s24-level1-v1-q7","session":"24","level":1,"topic":"Control evidence delivery assumption","question":"An aircraft sale meets no qualifying over time criterion in this illustrative contract, the customer obtains control only on final accepted delivery, which has not occurred, and a 10 million euro advance has been received. What follows before delivery?","choices":["Cash and a contract liability of 10 million, with no aircraft sale revenue yet","Revenue of 10 million, recognising the amount collected","Revenue by production progress, treating manufacturing activity alone as over time qualification","A receivable of 10 million with no liability, treating the advance as earned"],"correct_index":0,"explanation":"The facts make this a point in time sale with no transfer yet. Advances do not satisfy the remaining aircraft promise, and industry labels do not override the actual contract rights."},{"id":"cr-s24-level1-v1-q8","session":"24","level":1,"topic":"New revenue bridge signs","question":"Reported new basis revenue is 250 million euros, and a transition note says revenue would have been 240 million under the old basis. What is the accounting policy effect on current revenue?","choices":["A decrease of 10 million","An increase of 10 million","An increase of 250 million","An increase of 240 million"],"correct_index":1,"explanation":"The policy effect is reported new 250 less counterfactual old 240 = +10. Keep that accounting bridge separate from any underlying volume comparison."},{"id":"cr-s24-level1-v1-q9","session":"24","level":1,"topic":"Separate standards adoption","question":"Opening retained earnings increase for two reasons: 18 million euros from the revenue standard and 42 million from a separate share payment standard. Which part belongs in the revenue adoption bridge?","choices":["60 million euros","42 million euros","18 million euros","24 million euros"],"correct_index":2,"explanation":"Disaggregate by source. The 60 million total is not all revenue transition effect, and the unrelated 42 cannot be relabelled as revenue."},{"id":"cr-s24-level1-v1-q10","session":"24","level":1,"topic":"Transition disclosure purpose","question":"A modified retrospective adopter leaves prior figures on the old basis but also gives current figures as if adoption had not occurred. What comparison does that extra current year information make possible?","choices":["It makes the old basis mandatory for future periods too","It reconciles revenue to cash by removing the adoption adjustment","It substitutes old basis current figures for the required new basis statements","It supports same basis comparison and separates policy effects from operating changes"],"correct_index":3,"explanation":"The counterfactual old basis current figures let users compare against the unchanged old basis prior year. The disclosure supplements the new basis statements rather than replacing them."},{"id":"cr-s24-level2-v1-q1","session":"24","level":2,"topic":"Underlying growth bridge","question":"A fictional company reports prior old basis revenue of 1,000 million euros and current new basis revenue of 1,120 million. The adoption note gives current old basis revenue of 1,050 million. What reported growth and same old basis growth follow?","choices":["Reported 5% and same basis 12%, with the numerators swapped","Both 12%, comparing new current revenue with old prior revenue","Reported 7% and same basis 5%, confusing the policy effect with growth","Reported 12% and same basis 5%, separating published growth from the policy effect"],"correct_index":3,"explanation":"Reported growth is 1,120/1,000 - 1 = 12%. Comparable old basis growth is 1,050/1,000 - 1 = 5%. The 7 point difference is the accounting contribution in this bridge, not necessarily extra economic growth."},{"id":"cr-s24-level2-v1-q2","session":"24","level":2,"topic":"Opening net equity with tax","question":"A simplified transition removes a contract liability of 100 million euros and removes a related cost asset of 60 million. The resulting 40 million pretax gain creates a deferred tax liability of 10 million, with no other entry. What opening retained earnings increase follows?","choices":["30 million euros","40 million euros","90 million euros","170 million euros"],"correct_index":0,"explanation":"The pretax gain is 100 - 60 = 40, and the tax liability of 10 leaves an equity increase of 30. The 100 of released liability alone is not the net equity effect."},{"id":"cr-s24-level2-v1-q3","session":"24","level":2,"topic":"Negative equity transition with tax","question":"A transition defers previously earned consideration by adding a contract liability of 80 million euros and restores a related cost asset of 50 million. Tax creates a fully recognised deferred tax asset of 9 million. What opening retained earnings change follows?","choices":["A decrease of 30 million","A decrease of 21 million euros","An increase of 21 million","A decrease of 89 million"],"correct_index":1,"explanation":"Assets rise by 50 + 9 = 59 against a new liability of 80, so equity falls by 21. Equivalently, the pretax deferral loss of 80 - 50 = 30 is offset by the 9 tax benefit. Revenue, cost and tax effects stay separate."},{"id":"cr-s24-level2-v1-q4","session":"24","level":2,"topic":"New versus old margin","question":"Current new basis revenue is 600 million euros with cost of sales of 420 million, compared with current without adoption revenue of 580 million and cost of 400 million, and no other operating items. What is the policy effect on gross profit?","choices":["An increase of 20 million, reflecting the revenue bridge alone","A decrease of 20 million, reflecting the cost bridge alone","Zero: gross profit is 180 million on both bases","An increase of 40 million, adding the revenue and cost increases"],"correct_index":2,"explanation":"New gross profit is 600 - 420 = 180 and old is 580 - 400 = 180. The equal 20 million revenue and cost uplifts change the margin percentages but not absolute gross profit."},{"id":"cr-s24-level2-v1-q5","session":"24","level":2,"topic":"Retained earnings opening to closing","question":"The opening transition effect leaves retained earnings 30 million euros higher under the new policy. During the adoption year the policy reduces net income by 4 million relative to the old policy, with identical dividends and no other differential equity effect. What closing difference in retained earnings follows?","choices":["34 million higher","4 million lower","30 million higher regardless of current earnings","26 million euros higher"],"correct_index":3,"explanation":"The closing difference is the opening 30 plus the current earnings difference of minus 4: 26 million higher. The current year policy effect does not erase the cumulative opening effect."},{"id":"cr-s24-level2-v1-q6","session":"24","level":2,"topic":"Contract liability receipts reconstruction","question":"An illustrative service provider starts with a contract liability of 70 million euros and ends with 85 million, having recognised 40 million of revenue from that pool, with no other movements. What new cash advances were received?","choices":["55 million euros","15 million euros","125 million euros","40 million euros"],"correct_index":0,"explanation":"Closing 85 = opening 70 + advances - 40, so advances are 55. The 15 increase in the liability is a net movement, not the gross customer receipts."},{"id":"cr-s24-level2-v1-q7","session":"24","level":2,"topic":"Cumulative estimate adjustment","question":"A qualifying over time contract priced at 1,200 million euros was previously 30% complete with 360 million of revenue recognised. At the current date costs of 200 million against an estimated total of 500 million faithfully measure progress, with no other adjustment. What current revenue follows?","choices":["480 million euros","120 million euros","840 million euros","240 million euros"],"correct_index":1,"explanation":"Current cumulative progress is 200/500 = 40%, so cumulative revenue is 480, less the 360 already recognised: 120 currently. The cumulative catch up approach never books the full 480 again as current revenue."},{"id":"cr-s24-level2-v1-q8","session":"24","level":2,"topic":"Backlog rollforward simple","question":"Remaining performance obligations open at 900 million euros. New contracted allocations add 400 million, satisfied obligations release 350 million into revenue and a cancellation removes 50 million, with no other movements. What closing balance follows?","choices":["950 million euros","1,250 million euros","900 million euros","850 million euros"],"correct_index":2,"explanation":"The rollforward is 900 + 400 - 350 - 50 = 900. The backlog can close unchanged despite substantial new contracts and earned revenue, so a flat balance does not imply no activity."},{"id":"cr-s24-level2-v1-q9","session":"24","level":2,"topic":"Contract right billing reclassification","question":"A company holds a contract asset of 60 million euros for previously earned revenue. A milestone makes 35 million of it unconditional and billed, with no new performance and no cash. What closing contract asset and new receivable follow?","choices":["Contract asset 60 million and new revenue of 35 million","Contract liability 35 million and no receivable","Contract asset 95 million and receivable 35 million","Contract asset 25 million euros and receivable 35 million euros"],"correct_index":3,"explanation":"The 35 million reclassifies from conditional contract asset to unconditional receivable. The previously earned 60 does not become new revenue again at billing."},{"id":"cr-s24-level2-v1-q10","session":"24","level":2,"topic":"Gross revenue reclassification","question":"A new policy increases reported revenue by 25 million euros and reduces other operating income by the same 25 million, with no cost or tax effects. What change in total operating income follows?","choices":["Zero","An increase of 25 million","A decrease of 25 million","An increase of 50 million"],"correct_index":0,"explanation":"This is a pure reclassification between revenue and other operating income: the top line changes while total operating income does not. Revenue growth alone can mislead about added profit."},{"id":"cr-s24-level3-v1-q1","session":"24","level":3,"topic":"Full same basis comparison both years","question":"A company reports current new basis revenue of 1,260 million euros and a restated prior new basis of 1,200 million. The originally reported prior old basis was 1,100 million. What comparable new basis growth follows, and what misleading mixed basis growth would result?","choices":["Comparable 5% and mixed basis about 14.55%","Comparable 14.55% and mixed 5%, reversing the bases","Both 5%, treating the old prior total as already restated","Comparable 9.09% and mixed 14.55%, treating the prior restatement as current growth"],"correct_index":0,"explanation":"Comparable growth uses the restated denominator: 1,260/1,200 - 1 = 5%. Mixing 1,260 with the originally reported 1,100 gives about 14.55%. The 100 of prior restatement drives the denominator choice, not current cash."},{"id":"cr-s24-level3-v1-q2","session":"24","level":3,"topic":"Balance sheet and cash bridge","question":"A transition increases receivables by 12 million euros, decreases inventory by 8 million, decreases contract liabilities by 30 million and increases the deferred tax liability by 8.5 million, with no other adjustment. What retained earnings and cash changes follow?","choices":["Retained earnings up 34 million and cash up 34 million","Retained earnings up 25.5 million euros and cash unchanged","Retained earnings down 34 million and cash unchanged","Retained earnings up 42 million and cash up 12 million"],"correct_index":1,"explanation":"Net assets change by 12 - 8 = 4 and net liabilities change by -30 + 8.5 = -21.5, so equity rises by 4 - (-21.5) = 25.5. No listed entry touches cash. These are illustrative amounts, not an actual company bridge."},{"id":"cr-s24-level3-v1-q3","session":"24","level":3,"topic":"Revenue cost tax cumulative bridge","question":"A policy adds current revenue of 90 million euros, adds cost of sales of 55 million, reduces other income by 20 million and increases tax expense by 3 million. The opening retained earnings policy difference was negative 40 million, with identical dividends and other equity changes. What current net income effect and closing retained earnings difference follow?","choices":["Net income up 35 million and closing retained earnings 5 million lower","Net income up 32 million and closing retained earnings 8 million lower","Net income up 12 million euros and closing retained earnings 28 million lower","Net income up 168 million and closing retained earnings 128 million higher"],"correct_index":2,"explanation":"The current pretax effect is 90 - 55 - 20 = 15, less tax of 3 = 12. The closing difference is opening minus 40 plus 12 = minus 28. The 90 revenue uplift is neither the net profit effect nor the closing cumulative equity effect."},{"id":"cr-s24-level3-v1-q4","session":"24","level":3,"topic":"Contract liabilities not invoice only","question":"An opening contract liability of 120 million euros covers all advance funded unperformed services. During the year cash advances of 160 million arrive, 155 million of revenue is released from those obligations, refunds of 10 million settle part of the balance and acquired contracts add 25 million of liability without cash. What closing liability and advance cash inflow follow?","choices":["Closing 115 million and cash 185 million","Closing 140 million and cash 185 million","Closing 295 million and cash 160 million","Closing 140 million euros and advance cash inflow of 160 million euros"],"correct_index":3,"explanation":"The liability rollforward is 120 + 160 - 155 - 10 + 25 = 140. The acquisition adds a noncash balance, so cash advances stay at 160. Revenue released and cash received remain distinct."},{"id":"cr-s24-level3-v1-q5","session":"24","level":3,"topic":"Estimate change versus new economic work","question":"A qualifying contract priced at 2,000 million euros had incurred costs of 300 million against an estimated total of 1,000 million, with cumulative revenue of 600 million recognised. Before any new work, the total cost estimate rises to 1,200 million, with incurred costs unchanged. What immediate revenue catch up follows?","choices":["A revenue reduction of 100 million","A revenue increase of 100 million","A revenue increase of 500 million","Zero"],"correct_index":0,"explanation":"Revised progress is 300/1,200 = 25%, requiring cumulative revenue of 500 instead of the 600 booked: a negative catch up of 100. It reflects the estimate change, not a negative customer payment or automatically improper accounting."},{"id":"cr-s24-level3-v1-q6","session":"24","level":3,"topic":"Two policies reconcile growth and profit","question":"Prior old basis revenue is 800 million euros. Current new basis revenue is 920 million with operating profit of 92 million, and current without adoption revenue is 880 million with profit of 88 million. What same old basis revenue growth and adoption effect on operating margin follow?","choices":["Growth 15% and margin up 4 percentage points","Same basis growth 10% and no margin change, with both current margins at 10%","Growth 10% and margin up 0.5 percentage points","Growth 5% and margin down 10 percentage points"],"correct_index":1,"explanation":"Comparable growth is 880/800 - 1 = 10%. Both margins are 10%: 92/920 and 88/880. The policy adds 40 of revenue and 4 of profit while leaving the margin unchanged, and dividing the 4 by a mismatched denominator would invent a margin effect."},{"id":"cr-s24-level3-v1-q7","session":"24","level":3,"topic":"Mixed opening adjustments separated","question":"An opening reconciliation shows a total retained earnings increase of 120 million euros, including 150 million from a separate standard and an unknown revenue adoption effect. The revenue effect carries a pretax loss of 40 million and a recognised tax benefit of 10 million. Which reconciliation is consistent?","choices":["Revenue adoption adds 120 million and the separate standard has no opening effect","Revenue adoption reduces equity by 40 million and the tax benefit stays out of opening equity","Revenue adoption reduces equity by 30 million and the other standard adds 150 million","Revenue adoption adds 30 million and the separate standard adds the remaining 90 million"],"correct_index":2,"explanation":"The revenue net effect is -40 + 10 = -30, and the unrelated +150 brings the total to +120. A positive total equity adjustment does not prove a positive revenue policy effect."},{"id":"cr-s24-level3-v1-q8","session":"24","level":3,"topic":"Remaining obligations timing analysis","question":"Remaining performance obligations total 1,500 million euros, and disclosure estimates that 40% will be recognised next year, 35% in year 2 and 25% thereafter. These are prospective estimates, not current satisfied performance. Assuming the forecast occurs with no new contracts or cancellations, what expected next year revenue from this pool and remaining pool follow?","choices":["Current revenue of 1,500 million and next year zero","Expected next year 525 million and remaining 975 million","Expected next year 900 million and remaining 600 million","Expected next year 600 million euros and remaining 900 million euros"],"correct_index":3,"explanation":"Next year's expected slice is 40% × 1,500 = 600, leaving 900. These estimates are neither current revenue nor guaranteed future cash, and the stated no new movement assumption isolates the pool."},{"id":"cr-s24-level3-v1-q9","session":"24","level":3,"topic":"Control change hypothetical not industry rule","question":"Two hypothetical contracts for identical machines carry different enforceable rights. Contract A meets a valid over time criterion with faithful progress of 50% on an allocated price of 4 million euros. Contract B meets none, and control transfers only on final delivery, not yet made, on the same allocated price of 4 million. Both received a 2 million advance, with no other movements. What cumulative revenue and net balances follow?","choices":["A: revenue 2 and net balance zero. B: revenue zero and a liability of 2 million","A: revenue 2 and net balance zero. B: revenue 2 and net balance zero","A: revenue 4 and a receivable of 2. B: revenue 4 and a receivable of 2","A: revenue zero and a liability of 2. B: revenue 2 and net balance zero"],"correct_index":0,"explanation":"A earns 4 × 50% = 2, exactly offsetting its advance. B has transferred nothing, so its 2 million advance stays a contract liability. Identical products and identical cash do not produce identical accounting when the contract rights differ."},{"id":"cr-s24-level3-v1-q10","session":"24","level":3,"topic":"Analyst bridge conclusion bounded","question":"A modified retrospective adopter reports current revenue of 1,080 million euros against a prior 1,000 on the old basis. Current without adoption revenue is 1,020 million and current net income is unchanged by adoption. Which conclusion is supported by only these facts?","choices":["Growth of 8%, entirely organic, because adoption leaves net income unchanged","Reported growth 8%, old basis growth 2%, with adoption adding 60 of revenue and no net income effect","Old basis growth 2%, with the other 6% proving manipulation rather than a policy effect","Revenue and net income each increase by 60 million from adoption"],"correct_index":1,"explanation":"The reported increase of 80 splits into 20 of same basis change plus 60 of policy effect, and net income is unaffected. Neither this arithmetic nor the zero profit effect proves volume, organic growth, cash generation or motive."}],"25":[{"id":"cr-s25-level1-v1-q1","session":"25","level":1,"topic":"Employee grant service allocation","question":"An equity settled employee grant has 10,000 options with a grant date fair value of 6 euros each. All employees are expected to complete the required 3 years of service, with no other conditions or modifications. What year 1 expense follows?","choices":["60,000 euros","6,000 euros","20,000 euros","Zero until exercise"],"correct_index":2,"explanation":"The total grant date value of 10,000 × 6 = 60,000 is recognised over 3 years: 20,000 a year while expected vesting is unchanged. Exercise timing does not postpone the earned service cost."},{"id":"cr-s25-level1-v1-q2","session":"25","level":1,"topic":"Grant value not share price","question":"An equity settled employee option grant covers 20,000 options at a grant date fair value of 4 euros, with a 2 year service period and all expected to vest. At year end the option's fair value has risen to 7. What first year expense follows?","choices":["70,000 euros","80,000 euros","140,000 euros","40,000 euros"],"correct_index":3,"explanation":"The expense is 20,000 × 4 × 1/2 = 40,000, using the grant date fair value. The later market value of the option is never substituted into ordinary equity settled measurement."},{"id":"cr-s25-level1-v1-q3","session":"25","level":1,"topic":"Immediately vested past service","question":"A firm grants 1,000 equity settled shares with a grant date fair value of 30 euros each, as an unconditional reward for past service, with no future service or other condition. What recognition follows?","choices":["An immediate expense of 30,000 and an increase in equity of 30,000","Expense only when employees dispose of their awarded shares","The 30,000 expense spread over the first year after grant","A 30,000 liability, treating the award as cash settled"],"correct_index":0,"explanation":"The right vests immediately because the service is complete, so the full 1,000 × 30 = 30,000 is expensed now against equity. No future service period may be invented."},{"id":"cr-s25-level1-v1-q4","session":"25","level":1,"topic":"Exercise delay not service condition","question":"An unconditional equity settled award rewards past service. The employee cannot exercise for one year, but keeps the award even if employment ends immediately. When is the service expense recognised?","choices":["Over the one year until exercise becomes possible","Immediately, because no further service is required to retain the award","When the employee exercises and the company issues shares","When employment ends, confirming no more service will be provided"],"correct_index":1,"explanation":"The employee is already entitled without any future service. The date exercise becomes possible is not a service requirement, so the expense is immediate."},{"id":"cr-s25-level1-v1-q5","session":"25","level":1,"topic":"Goods received for equity","question":"A supplier provides inventory reliably valued at 24,000 euros in exchange for equity instruments. The inventory remains unsold at the reporting date, with no other consideration or entry. What initial treatment follows?","choices":["Immediate staff expense of 24,000 and a liability of 24,000","Revenue of 24,000, because shares were issued","Inventory of 24,000 and equity of 24,000","No entry until the inventory is sold"],"correct_index":2,"explanation":"For reliably measurable goods from a supplier, the received inventory is recognised at its fair value with a corresponding increase in equity. Expense follows consumption or sale. A share payment is not automatically a staff expense."},{"id":"cr-s25-level1-v1-q6","session":"25","level":1,"topic":"Service forfeiture at vesting","question":"An equity settled grant requires 2 years of service, and 10,000 euros of expense was recognised in year 1. At the final vesting date all employees have left before completing service, so no options vest. There are no market conditions or modifications. What year 2 effect follows?","choices":["Retain the 10,000 expense, treating the service condition like a market condition","Add another 10,000 to complete the originally forecast cost","Reverse 10,000 against a liability rather than the grant's equity reserve","Reverse the 10,000 expense, so cumulative recognised expense becomes zero"],"correct_index":3,"explanation":"Failure of the service vesting condition means the ultimately vested quantity is zero, so cumulative expense is zero and the prior 10,000 is reversed against the equity counterpart. No cash is invented."},{"id":"cr-s25-level1-v1-q7","session":"25","level":1,"topic":"Market failure service completed","question":"An equity settled employee grant has a market price target built into its grant date fair value and a 3 year service requirement. All required service is completed but the market target fails, with no other condition or modification. What follows?","choices":["Do not reverse the service expense solely for the market target failure","Reverse the expense, because the final share price condition failed","Remeasure the grant date fair value to zero after the target failure","Keep the reserve but reverse the expense directly through retained earnings"],"correct_index":0,"explanation":"Market conditions are priced into the grant date valuation. With every other vesting requirement met, the service expense stands even though the market target was missed."},{"id":"cr-s25-level1-v1-q8","session":"25","level":1,"topic":"Nonmarket performance final failure","question":"An equity settled award requires 3 years of service and an earnings growth target that is a non-market vesting condition. At the final date service is complete but the earnings target fails, so no awards vest. What cumulative expense follows?","choices":["The full original grant cost, treating the earnings condition like a market condition","Zero, reversing any prior expense for the failed non-market vesting condition","The final market price times the original awards, remeasured at vesting","The cost of completed service only, ignoring that no awards vest"],"correct_index":1,"explanation":"Unlike a market condition, a non-market performance vesting condition adjusts the expected and ultimately vested quantity. Final failure means no awards vest and cumulative cost is zero."},{"id":"cr-s25-level1-v1-q9","session":"25","level":1,"topic":"Vested lapse later","question":"A properly vested equity settled option award recognised 40,000 euros of service expense in earlier years. All service and non-market conditions were satisfied, and the vested options then expire unexercised. What profit effect follows solely from the expiry?","choices":["A gain of 40,000 reversing the cost","A cash inflow of 40,000","No reversal of the 40,000 service expense","A new expense of 40,000 regardless of the terms"],"correct_index":2,"explanation":"Once vested, later non-exercise does not undo the service received. A transfer within equity may be made, but expiry alone reverses no expense and creates no cash."},{"id":"cr-s25-level1-v1-q10","session":"25","level":1,"topic":"Exercise proceeds","question":"Employees exercise 5,000 vested options at an exercise price of 3 euros each. What cash increase follows, ignoring transaction costs and tax?","choices":["5,000 euros","3,000 euros","Zero, because the options were already expensed","15,000 euros"],"correct_index":3,"explanation":"Cash proceeds are 5,000 × 3 = 15,000. Recognising the employee service expense earlier does not cancel the contractual exercise price."},{"id":"cr-s25-level2-v1-q1","session":"25","level":2,"topic":"Revised expected leavers catchup","question":"A grant covers 100 employees with 100 options each at a grant date fair value of 6 euros, over a 3 year service period. Year 1 expects 90 employees to vest and recognises 18,000. At the end of year 2 the estimate falls to 80 expected vesting, with no other change. What year 2 expense follows?","choices":["16,000 euros","32,000 euros","18,000 euros","14,000 euros"],"correct_index":3,"explanation":"Required cumulative expense at year 2 is 80 × 100 × 6 × 2/3 = 32,000, less the 18,000 already booked: 14,000. The quantity estimate is revised. the grant date fair value is not."},{"id":"cr-s25-level2-v1-q2","session":"25","level":2,"topic":"Final actual vesting","question":"A 3 year equity settled grant pays 200 options per employee at a grant date value of 5 euros. Cumulative expense recognised through year 2 is 60,000 euros. At the final date 75 employees actually complete service and all other conditions are met. What year 3 expense follows?","choices":["15,000 euros","25,000 euros","75,000 euros","Zero, because expense stops before vesting"],"correct_index":0,"explanation":"Final cumulative expense is 75 × 200 × 5 = 75,000, less the 60,000 already charged: 15,000 currently. The final quantity is the actual vesting, not an earlier forecast."},{"id":"cr-s25-level2-v1-q3","session":"25","level":2,"topic":"Cash settled goods remeasurement","question":"Inventory acquired for a share price linked cash payment has an initial fair value of 18,000 euros and remains unsold. The liability, initially 18,000, rises to 22,000 at the reporting date purely from the share price change, with no other adjustment. What inventory and remeasurement expense follow?","choices":["Inventory 22,000 and no expense","Inventory 18,000, expense 4,000 and a liability of 22,000","Inventory 18,000 and equity 22,000","Revenue 4,000 and liability 18,000"],"correct_index":1,"explanation":"The goods asset stays at 18,000 while the cash settled liability remeasures to 22,000. The 4,000 change runs through profit or loss. it neither revalues the inventory nor turns a liability award into equity."},{"id":"cr-s25-level2-v1-q4","session":"25","level":2,"topic":"Exercise equity split","question":"Employees exercise 10,000 vested options at 2 euros each. The existing option reserve of 30,000 euros is transferred within equity, and the issued shares have a nominal value of 0.50 euros each, with no tax or costs. What cash, share capital and share premium entries follow?","choices":["Cash 20,000, share capital 5,000 and premium 15,000","Cash 30,000, capital 20,000 and premium 10,000","Cash 20,000, share capital 5,000 and share premium 45,000","Expense 30,000, capital 5,000 and premium 25,000"],"correct_index":2,"explanation":"Debits are cash of 20,000 and the option reserve of 30,000, totalling 50,000. Credits are share capital of 10,000 × 0.50 = 5,000 and a balancing premium of 45,000. The reserve transfer is neither new profit nor new cash."},{"id":"cr-s25-level2-v1-q5","session":"25","level":2,"topic":"Revised service failure reversal magnitude","question":"A 2 year grant has an initial total grant date fair value of 100,000 euros for all employees. Year 1 estimates that 80% will complete service and charges 40,000. At the end of year 2 only 60% actually complete, with no other conditions or modifications. What year 2 expense follows?","choices":["30,000 euros","60,000 euros","Negative 20,000 euros","20,000 euros"],"correct_index":3,"explanation":"Final cumulative expense is 100,000 × 60% = 60,000, less the 40,000 already recognised: 20,000. A lower quantity estimate does not necessarily make the current period expense negative."},{"id":"cr-s25-level2-v1-q6","session":"25","level":2,"topic":"Expected vesting period revision","question":"An equity settled employee grant with a non-market performance condition has a total expected vested grant date value of 90,000 euros. At the end of year 1 vesting was expected after 2 years, generating 45,000 of expense. At the end of year 2 the expected quantity is unchanged but the expected vesting period becomes 3 years, with no modification and all recognition assumptions holding. What year 2 expense follows?","choices":["15,000 euros","45,000 euros","60,000 euros","Negative 15,000 euros"],"correct_index":0,"explanation":"The new cumulative expense is 90,000 × 2/3 = 60,000, less the 45,000 prior: 15,000. A non-market performance based expected vesting period is revised as facts change, unlike a market condition valuation assumption."},{"id":"cr-s25-level2-v1-q7","session":"25","level":2,"topic":"Equity compensation no immediate cash","question":"An employer records 50,000 euros of employee service expense with an equal credit to equity for a valid equity settled grant, with no tax or other entry. What are the immediate effects on profit, total equity and cash?","choices":["Profit up 50,000, total equity up 50,000, cash down 50,000","Profit down 50,000, total equity unchanged, cash unchanged","Profit unchanged, total equity up 50,000, cash up 50,000","Profit down 50,000, total equity down 100,000, cash unchanged"],"correct_index":1,"explanation":"The expense cuts retained earnings by 50,000 while the award reserve rises by 50,000, so total equity is unchanged and no cash moves. This does not mean the compensation has no economic cost."},{"id":"cr-s25-level2-v1-q8","session":"25","level":2,"topic":"Goods later sold","question":"Inventory received in exchange for equity was recognised at 30,000 euros and is not impaired. It is later sold for 42,000 cash. What revenue, cost of sales and gross profit follow from that sale?","choices":["Revenue 12,000 and no cost","Revenue 42,000 and zero cost, because the shares were noncash","Revenue 42,000, cost 30,000 and profit 12,000","Revenue 30,000 and cost 42,000"],"correct_index":2,"explanation":"The noncash purchase still created an inventory cost of 30,000. On sale, revenue is 42,000 and cost of sales 30,000, giving 12,000 of profit. The form of the original payment does not make the inventory free."},{"id":"cr-s25-level2-v1-q9","session":"25","level":2,"topic":"Recognised quantity and grant fair value","question":"A 3 year employee award grants 50 options each to 200 employees at a grant date fair value of 8 euros, all initially expected to complete. After 1 year the share price has doubled but expected vesting employees have fallen to 180. What cumulative expense follows?","choices":["48,000 euros","26,666.67 euros","72,000 euros","24,000 euros"],"correct_index":3,"explanation":"The cumulative expense is 180 × 50 × 8 × 1/3 = 24,000: the expected service quantity is updated to 180, while the grant date fair value of 8 stays fixed despite the share price movement."},{"id":"cr-s25-level2-v1-q10","session":"25","level":2,"topic":"Market versus nonmarket identical amounts","question":"Two independent equity settled employee awards each have a grant date total cost of 30,000 euros, with all service complete. Award A fails only a market vesting target that was priced into fair value. Award B fails a non-market earnings vesting target, so none of it vests. What combined final cumulative expense follows?","choices":["30,000 euros","Zero","60,000 euros","15,000 euros"],"correct_index":0,"explanation":"Award A keeps its 30,000 because the service was received and the market condition was already priced in. Award B ends at zero because the failed non-market vesting condition leaves no qualifying awards. Equal amounts behave differently because the condition types differ."},{"id":"cr-s25-level3-v1-q1","session":"25","level":3,"topic":"Negative current expense without market repricing","question":"An equity settled 3 year grant covers 100 employees with 100 options each at a grant date option value of 9 euros. At the end of year 1, 90 employees were expected to vest and the expense was 27,000. At the end of year 2 only 30 are expected to vest, with the period unchanged and no modification. What year 2 expense follows?","choices":["Negative 9,000 euros, an expense reversal","Positive 18,000 euros","Positive 9,000 euros","Negative 27,000 euros, taking the final cumulative to zero"],"correct_index":0,"explanation":"Revised cumulative expense is 30 × 100 × 9 × 2/3 = 18,000, against 27,000 already booked: a negative 9,000. The reversal is driven by the service quantity estimate, not by later market fair value changes."},{"id":"cr-s25-level3-v1-q2","session":"25","level":3,"topic":"Three year changing forecast","question":"A 3 year equity settled grant gives 100 options per employee at a grant date value of 5 euros. Expected vesting employees are 96 after year 1 and 84 after year 2, with an actual 90 at year 3 and no other changes. What annual expenses follow?","choices":["16,000, 14,000 and 15,000, treating each cumulative forecast as a standalone yearly total","16,000, 12,000 and 17,000, taking each year's change in the required cumulative expense","48,000, 42,000 and 45,000, recognising the full expected cost at each year end","15,000 each year, applying the final actual vesting from year one without updates"],"correct_index":1,"explanation":"Cumulative costs are 96 × 100 × 5/3 = 16,000, then 84 × 100 × 5 × 2/3 = 28,000, then 90 × 100 × 5 = 45,000. Period charges are the differences: 16,000, 12,000 and 17,000, with the final 45,000 matching actual vesting."},{"id":"cr-s25-level3-v1-q3","session":"25","level":3,"topic":"Variable period and quantity combined","question":"An equity settled grant of 100 shares per employee at a grant date value of 12 euros carries a non-market performance condition. Year 1 expects 80 employees vesting after 2 years and records 48,000. Year 2 expects 75 employees vesting after 3 years, with all estimation assumptions holding and no modification. What year 2 expense follows?","choices":["30,000 euros","60,000 euros","12,000 euros","Negative 3,000 euros"],"correct_index":2,"explanation":"Revised cumulative expense is 75 × 100 × 12 × 2/3 = 60,000, less the 48,000 prior: 12,000. Both the quantity and the expected vesting period moved, but the grant date fair value stays at 12."},{"id":"cr-s25-level3-v1-q4","session":"25","level":3,"topic":"Grant versus exercise total equity","question":"An equity settled option reserve of 60,000 euros arose from earlier expense. Employees exercise 20,000 options at 4 euros each, the nominal share value is 1 euro and the entire reserve is transferred to capital and premium, with no tax or costs. What increase in total equity at exercise and what share premium credit follow?","choices":["Total equity up 140,000 and premium 120,000","Total equity up 80,000 and premium 60,000","Total equity unchanged and premium 140,000","Total equity up 80,000 and premium 120,000"],"correct_index":3,"explanation":"New external cash of 20,000 × 4 = 80,000 increases total equity, while reclassifying the existing 60,000 reserve adds none. Share capital is 20,000 and the premium is 80,000 + 60,000 - 20,000 = 120,000."},{"id":"cr-s25-level3-v1-q5","session":"25","level":3,"topic":"Equity award versus liability award cumulative","question":"Two 3 year employee grants each cover 10,000 rights with all service expected to be completed. The equity settled award has a grant date value of 6 euros per right, while the cash settled liability award has a current fair value of 9 euros per right. At the end of year 2, with no modifications, what cumulative expense balances follow?","choices":["Equity award 40,000 and cash settled award 60,000","Both 40,000, keeping grant date value for the cash settled award too","Both 60,000, remeasuring the equity award like the liability","Equity 60,000 and cash 90,000, recognising full value before service ends"],"correct_index":0,"explanation":"The equity grant gives 10,000 × 6 × 2/3 = 40,000 and the cash liability gives 10,000 × 9 × 2/3 = 60,000. The same service fraction does not erase the different measurement rules."},{"id":"cr-s25-level3-v1-q6","session":"25","level":3,"topic":"Service and market condition combined","question":"An equity settled grant of 100 options each to 50 employees, at a grant date fair value of 4 euros that already incorporates a market target, requires 2 years of service. Year 1 expects 45 employees vesting and charges 9,000 euros. At the final date 40 complete service and the market target fails, with no other conditions. What final cumulative expense and year 2 expense follow?","choices":["Cumulative zero and a year 2 reversal of 9,000","Cumulative 16,000 and year 2 expense of 7,000","Cumulative 20,000 and year 2 expense of 11,000","Cumulative 18,000 and year 2 expense of 9,000"],"correct_index":1,"explanation":"The 40 actual service completers give 40 × 100 × 4 = 16,000 despite the market target failure, and deducting the prior 9,000 leaves 7,000 currently. Service forfeitures still adjust the quantity even when a market target is priced in."},{"id":"cr-s25-level3-v1-q7","session":"25","level":3,"topic":"Final earnings target changes the cost","question":"An equity settled 3 year award to 80 employees of 200 options each, at a grant date value of 3 euros, requires service and a non-market earnings target. Prior cumulative cost of 32,000 euros was recognised. All 80 complete the service, but the final earnings target fails and no options vest. What current expense and equity reserve effect follow?","choices":["Add expense of 16,000 to reach the initial grant value of 48,000","No entry, retaining 32,000 because the service was completed","Reverse the 32,000 expense and reduce the reserve by 32,000","Reverse the 32,000 reserve straight to retained earnings without touching expense"],"correct_index":2,"explanation":"Both the service and the non-market performance conditions determine the ultimate quantity. The target failure brings it to zero, reversing the prior 32,000 expense and its equity credit. A non-market failure is not treated like a market target failure."},{"id":"cr-s25-level3-v1-q8","session":"25","level":3,"topic":"Immediately vested portion distinct grants","question":"A firm grants two independent equity settled awards on the same date. Award A unconditionally rewards past service with a total fair value of 18,000 euros. Award B, with a total grant date value of 72,000, requires 3 years of future service, all expected to be completed. One year has elapsed. What cumulative expense follows?","choices":["30,000 euros","90,000 euros","24,000 euros","42,000 euros"],"correct_index":3,"explanation":"Award A is fully expensed at grant, 18,000, because no future condition exists. Award B recognises 72,000/3 = 24,000 in year 1. Combined: 42,000. Separate awards follow their own vesting terms rather than an averaged period."},{"id":"cr-s25-level3-v1-q9","session":"25","level":3,"topic":"Cash liability gains before settlement","question":"A cash settled share based payment for inventory originally creates an asset of 25,000 euros and a liability of 25,000. While the inventory remains unsold, the liability is remeasured to 28,000, a 3,000 loss. It is then settled for 26,000 before the inventory is sold, with no other adjustments. What settlement period profit effect and inventory cost follow?","choices":["A gain of 2,000 and inventory cost of 25,000","A loss of 1,000 and inventory cost of 26,000","A gain of 3,000 and inventory cost of 28,000","No gain and inventory cost of 25,000"],"correct_index":0,"explanation":"The liability remeasures from 28,000 down to the 26,000 paid, a 2,000 gain in the settlement period, while the inventory stays at its original 25,000. Across all periods the net remeasurement loss is 1,000, which is different from this period's 2,000 gain."},{"id":"cr-s25-level3-v1-q10","session":"25","level":3,"topic":"Expense not share count exercise gain","question":"A fully vested equity settled grant comprises 8,000 options with a grant date fair value of 5 euros and an exercise price of 10 euros. Employees exercise when the share price is 30 euros, and the 40,000 service cost was fully recognised earlier. No tax or costs apply. What new employee service expense and cash proceeds follow at exercise?","choices":["Expense 160,000 and cash 80,000","New expense zero and cash 80,000","Expense 40,000 and cash 240,000","Expense 200,000 and cash zero"],"correct_index":1,"explanation":"The service was measured at 40,000 at grant and fully recognised, so exercise adds no expense. Cash proceeds are 8,000 × 10 = 80,000. The employees' intrinsic gain of 8,000 × (30 - 10) = 160,000 is not a new employer expense for an unchanged equity settled grant."}],"26":[{"id":"cr-s26-level1-v1-q1","session":"26","level":1,"topic":"Historical framework explicit","question":"A fictional company historically used the APB 25 intrinsic value method for a fixed employee option award. At grant the share price and the exercise price were both 20 dollars, grant was the measurement date and no special feature altered the treatment. What initial intrinsic value per option follows?","choices":["20 dollars","40 dollars","Zero dollars","Negative 20 dollars"],"correct_index":2,"explanation":"Under the specified historical fixed award illustration, intrinsic value is max(20 - 20, 0) = zero. That does not mean the option's fair value or economic compensation cost is zero."},{"id":"cr-s26-level1-v1-q2","session":"26","level":1,"topic":"Time value remains","question":"An option grants the right to buy a share for 30 dollars when the current share price is 30, and a reliable grant date option model values it at 8 dollars. What distinction is correct?","choices":["Both values are zero, because the strike equals the stock price","Intrinsic value is 30 and fair value is 8","The 8 dollars is cash already received by the employee","Intrinsic value is zero, but the option's fair value is 8 dollars"],"correct_index":3,"explanation":"At the money means zero immediate exercise gain, but the remaining option life can carry time value. Use the supplied model value of 8 rather than assuming an at the money option is worthless."},{"id":"cr-s26-level1-v1-q3","session":"26","level":1,"topic":"Fair value service cost simple","question":"In a historical fair value pro forma illustration, a grant includes 10,000 employee options with a grant date value of 5 dollars and a required 2 year service period, all expected to vest, with no tax or other differences. What annual expense follows?","choices":["25,000 dollars","50,000 dollars","Zero, because the option may be at the money","5,000 dollars"],"correct_index":0,"explanation":"Total fair value is 10,000 × 5 = 50,000, recognised over 2 years: 25,000 a year. Fair value measurement and service recognition apply even when intrinsic value is zero."},{"id":"cr-s26-level1-v1-q4","session":"26","level":1,"topic":"Pro forma bridge basic","question":"An illustrative historical company reports net income of 40 million dollars. Fair value based option accounting would add expense of 55 million, with no tax or other difference. What pro forma net income follows?","choices":["A profit of 95 million","A loss of 15 million dollars","A profit of 15 million","A loss of 55 million"],"correct_index":1,"explanation":"Reported 40 less the additional 55 gives negative 15. A disclosed alternative basis can turn a reported profit into a pro forma loss without any 55 million cash payment this period."},{"id":"cr-s26-level1-v1-q5","session":"26","level":1,"topic":"Expense versus cash exercise","question":"Employees exercise 2,000 vested options at 10 dollars each. Ignoring tax and costs, what cash does the employer receive?","choices":["Zero, because share based compensation carries an expense","The employee's gain rather than the contractual strike","20,000 dollars","2,000 dollars regardless of the strike"],"correct_index":2,"explanation":"Exercise proceeds are 2,000 × 10 = 20,000. The employer's cash from the strike is a different number from both the service cost and the employee's intrinsic gain."},{"id":"cr-s26-level1-v1-q6","session":"26","level":1,"topic":"Historical not current IFRS","question":"An analyst compares a historical profit measured at intrinsic value with fair value amounts that were only disclosed in the notes. For a current equity settled employee award under IFRS 2, which lesson carries over and which historical treatment cannot?","choices":["Use APB 25 for an at the money award and IFRS 2 for supplementary disclosure","Use the historical pro forma amount as the current IFRS grant date measurement","Choose the historical rule for options and IFRS 2 only for ordinary share awards","Separate the history: apply IFRS 2 grant date value and service conditions"],"correct_index":3,"explanation":"Historical US recognition and disclosure choices are not a current IFRS 2 exemption. The framework and the period must be explicit before a profit number means anything."},{"id":"cr-s26-level1-v1-q7","session":"26","level":1,"topic":"Outstanding options rollforward","question":"A company begins with 1 million outstanding options, grants 300,000, employees exercise 200,000 and 100,000 are cancelled, with no other movements. What closing outstanding quantity follows?","choices":["1 million options","1.3 million options","1.6 million options","700,000 options"],"correct_index":0,"explanation":"The rollforward is 1,000,000 + 300,000 - 200,000 - 100,000 = 1,000,000. Grants do not all stay outstanding. exercises and cancellations drain the pool."},{"id":"cr-s26-level1-v1-q8","session":"26","level":1,"topic":"Income gap no motive proof","question":"Applying an alternative option fair value expense turns a historical reported profit into a pro forma loss. With no cash flow bridge supplied, what does that difference establish?","choices":["The reported accounts necessarily contain a deliberate misstatement","The measurement basis materially affects reported profitability, without determining operating cash generation","The options have no economic cost, because no cash payment is in the reported expense","The option adjustment equals the cash compensation paid during the period"],"correct_index":1,"explanation":"Different recognition bases can swing reported earnings sharply. Cash, motive and solvency need separate evidence and cannot be inferred from a pro forma bridge."},{"id":"cr-s26-level1-v1-q9","session":"26","level":1,"topic":"Per share basic bridge","question":"A fictional pro forma loss is 12 million dollars and the weighted average basic share count is 60 million, with no other adjustment. What basic loss per share follows?","choices":["5 dollars loss","0.02 dollars loss","0.20 dollars loss","0.20 dollars profit"],"correct_index":2,"explanation":"Negative 12 million divided by 60 million gives a loss of 0.20 per share. Consistent units and the negative sign matter when a profit flips to a loss."},{"id":"cr-s26-level1-v1-q10","session":"26","level":1,"topic":"Grant fair value total","question":"An illustrative company grants 50,000 options, each reliably valued at 12 dollars at grant. What total grant date fair value follows before any vesting allocation?","choices":["50,012 dollars","12 dollars in total","600,000 dollars, necessarily all current expense regardless of service","600,000 dollars"],"correct_index":3,"explanation":"The total is 50,000 × 12 = 600,000. Total grant value is distinct from the portion recognised in any one service period."},{"id":"cr-s26-level2-v1-q1","session":"26","level":2,"topic":"Intrinsic versus fair value annual cost","question":"In a simplified historical fixed award, 10,000 options have a share price of 25 dollars, a strike of 20 and a grant fair value of 9. Both compared methods recognise the resulting cost evenly over 2 years, all vest and there is no tax. What annual intrinsic based and fair value based expenses follow?","choices":["50,000 dollars and 90,000 dollars","Zero and 45,000 dollars","45,000 dollars and 25,000 dollars","25,000 dollars and 45,000 dollars"],"correct_index":3,"explanation":"Intrinsic value per option is 25 - 20 = 5, totalling 50,000, or 25,000 a year. Fair value is 9 × 10,000 = 90,000, or 45,000 a year. The comparison is explicitly historical and simplified, not an IFRS 2 policy choice."},{"id":"cr-s26-level2-v1-q2","session":"26","level":2,"topic":"Pro forma remove old expense first","question":"Historical reported income of 30 million dollars already deducts intrinsic based option expense of 4 million. The alternative fair value expense is 18 million, with no tax or other change. What fair value pro forma income follows?","choices":["16 million dollars","12 million dollars","48 million dollars","52 million dollars"],"correct_index":0,"explanation":"Replace the old expense, do not double count: 30 + 4 - 18 = 16. Subtracting 18 without adding back the 4 would charge both methods at once."},{"id":"cr-s26-level2-v1-q3","session":"26","level":2,"topic":"Tax adjusted income bridge","question":"Reported net income of 50 million dollars includes all existing costs. The incremental fair value option expense versus the reported basis is 80 million pretax, with a fully recognised tax benefit at 25% and no other difference. What pro forma net income follows?","choices":["A loss of 30 million","A loss of 10 million dollars","A profit of 30 million","A profit of 110 million"],"correct_index":1,"explanation":"The after tax incremental expense is 80 × 75% = 60, so pro forma income is 50 - 60 = negative 10. Apply the stated recognised tax benefit rather than treating every disclosed cost bridge as fully pretax."},{"id":"cr-s26-level2-v1-q4","session":"26","level":2,"topic":"Option count versus dilution not same","question":"A company has 20 million outstanding employee options and 100 million existing ordinary shares, with no exercise or buyback. What simple option overhang ratio follows, defined here as outstanding options divided by existing shares?","choices":["16.67%","120%","20%","80%"],"correct_index":2,"explanation":"The supplied ratio is 20/100 = 20%. The fully exercised ownership fraction of 20/120 = 16.67% uses a different denominator. This simple overhang measure is not the diluted EPS incremental share calculation."},{"id":"cr-s26-level2-v1-q5","session":"26","level":2,"topic":"Annual vesting pool","question":"A historical fair value pro forma schedule shows three independent grants with current period expenses of 12, 8 and 5 million dollars. Reported current net income of 20 million excludes these expenses, with no tax. What pro forma net income follows?","choices":["A profit of 45 million","A profit of 8 million","A loss of 25 million","A loss of 5 million dollars"],"correct_index":3,"explanation":"The grant expenses sum to 25, so pro forma income is 20 - 25 = negative 5. A schedule of several vesting cohorts is not one grant, and only counting the newest cohort understates the cost."},{"id":"cr-s26-level2-v1-q6","session":"26","level":2,"topic":"Weighted average grant fair value","question":"A company grants 40,000 options at a model fair value of 6 dollars and 60,000 at 10 dollars. What weighted average grant date fair value follows?","choices":["8.40 dollars per option","8 dollars per option","16 dollars per option","4 dollars per option"],"correct_index":0,"explanation":"Total value is 40,000 × 6 + 60,000 × 10 = 840,000, over 100,000 options: 8.40. An unweighted mean of 8 ignores the different grant quantities."},{"id":"cr-s26-level2-v1-q7","session":"26","level":2,"topic":"Historical EPS consistent basis","question":"Reported income of 24 million dollars and alternative fair value income of 6 million use the same 120 million weighted average basic shares, with no other adjustments. What reported and alternative basic EPS follow?","choices":["0.05 dollars and 0.20 dollars","0.20 dollars and 0.05 dollars","0.20 dollars and 0.15 dollars","5 dollars and 20 dollars"],"correct_index":1,"explanation":"Reported EPS is 24/120 = 0.20 and the alternative is 6/120 = 0.05. The 0.15 difference is not itself the alternative EPS. Comparing frameworks needs a consistent share denominator."},{"id":"cr-s26-level2-v1-q8","session":"26","level":2,"topic":"Compensation not financing gain","question":"A company recognises 10 million dollars of noncash employee option expense with an equity reserve credit. Later, employees pay 15 million of exercise proceeds, with no taxes, costs or reserve changes beyond reclassification. What profit effect do the exercise proceeds have?","choices":["Profit rises 15 million, recognising the employee payment as income","Profit rises 5 million, offsetting the prior compensation expense","Zero: exercise proceeds increase cash and equity, not income","Profit falls 15 million, treating the proceeds as further compensation"],"correct_index":2,"explanation":"Paying the strike is a capital transaction, not an earnings credit that offsets the earlier service cost. The 10 million expense stands unless a relevant vesting rule independently changes it."},{"id":"cr-s26-level2-v1-q9","session":"26","level":2,"topic":"Counterfactual margin","question":"A fictional company reports revenue of 400 million dollars and operating profit of 60 million, excluding an incremental fair value employee option expense of 20 million, with no tax or other operating changes. What fair value adjusted operating margin follows?","choices":["15%","5%","20%","10%"],"correct_index":3,"explanation":"Adjusted operating profit is 60 - 20 = 40, over revenue of 400: 10%. The reported 15% margin excludes the incremental compensation charge."},{"id":"cr-s26-level2-v1-q10","session":"26","level":2,"topic":"Cancellation and exercise pool","question":"Opening options are 5 million, grants add 2 million, cancellations remove 0.5 million and 1.5 million are exercised at a weighted exercise price of 8 dollars each, with no other movements. What closing options and exercise cash follow?","choices":["5 million options and 12 million dollars of cash","7 million options and 40 million dollars","5 million options and 16 million dollars","3 million options and 12 million dollars"],"correct_index":0,"explanation":"The pool is 5 + 2 - 0.5 - 1.5 = 5 million, and cash is 1.5 million × 8 = 12 million. The closing outstanding quantity does not set the quantity actually exercised."},{"id":"cr-s26-level3-v1-q1","session":"26","level":3,"topic":"After tax replacement with old expense","question":"Historical reported net income of 45 million dollars already includes 12 million of pretax intrinsic compensation. The alternative fair value cost is 72 million, with a 25% tax benefit on both bases fully recognised and no other difference. What pro forma net income follows?","choices":["Zero","A loss of 9 million","Profit of zero before tax but 11.25 million after tax","A loss of 15 million"],"correct_index":0,"explanation":"The incremental pretax cost is 72 - 12 = 60, or 45 after tax, so pro forma income is 45 - 45 = zero. Equivalently, add back the existing net 9 and deduct the new net 54. Subtracting all 72, or the pretax 60, from after tax income would both be wrong."},{"id":"cr-s26-level3-v1-q2","session":"26","level":3,"topic":"Current cohort not full grant value","question":"An illustration has an old grant with a total fair value of 120 million dollars over 4 years, completing year 3 this year, and a new independent grant of 60 million over 3 years starting exactly halfway through the year. Assume straight line service, full vesting, no tax and no other expense differences. Reported income of 50 million excludes both costs. What current fair value cost and pro forma income follow?","choices":["Cost 180 million and a loss of 130 million","Cost 40 million and pro forma income of 10 million","Cost 50 million and pro forma income of zero","Cost 30 million and pro forma income of 20 million"],"correct_index":1,"explanation":"The old cohort costs 120/4 = 30 this year and the new one costs 60/3 × 1/2 = 10, totalling 40. Pro forma income is 50 - 40 = 10. Count current service, not the full multi year grant values."},{"id":"cr-s26-level3-v1-q3","session":"26","level":3,"topic":"Intrinsic economic employee gain distinct","question":"An equity settled employee grant of 10,000 options has a strike of 15 dollars and a grant option fair value of 4. All service is complete with cumulative expense of 40,000, and the options are exercised at a share price of 25. What employee intrinsic gain, employer cash and new compensation expense follow under the unchanged equity settled award?","choices":["Gain 150,000, employer cash 100,000 and expense 40,000","Gain 250,000, employer cash 150,000 and expense 100,000","Gain 100,000, employer cash 150,000 and new compensation expense zero","Gain 100,000, employer cash 250,000 and expense 100,000"],"correct_index":2,"explanation":"The employee gain is 10,000 × (25 - 15) = 100,000 and employer cash is 10,000 × 15 = 150,000. The earlier grant date service cost of 40,000 is never remeasured to the exercise gain on an unchanged equity settled award."},{"id":"cr-s26-level3-v1-q4","session":"26","level":3,"topic":"Pro forma loss and anti dilution supplied","question":"A firm has a pro forma net loss of 30 million dollars and 100 million weighted average ordinary shares. Options would add 5 million incremental shares in a profitable period, but they are antidilutive in this loss period and must be excluded under the supplied rule. What diluted loss per share follows?","choices":["A loss of 0.286","A loss of 0.3158","A loss of 6.00","A loss of 0.30"],"correct_index":3,"explanation":"Excluding the antidilutive options leaves -30/100 = -0.30. Adding 5 million shares would shrink the loss per share, which is exactly what the antidilution rule forbids."},{"id":"cr-s26-level3-v1-q5","session":"26","level":3,"topic":"Multiple income adjustments no cash inference","question":"Historical reported profit of 80 million dollars excludes 70 million of incremental fair value compensation and includes a 20 million nonrecurring gain. An analyst wants profit after both adjustments, with no tax or other changes. What result and cash inference follow?","choices":["A loss of 10 million, with no exact cash change inferable from this bridge alone","A profit of 30 million, with an exact cash outflow of 50 million from the bridge","A profit of 10 million, excluding the compensation but keeping the gain","A loss of 90 million, deducting the compensation twice"],"correct_index":0,"explanation":"The bridge is 80 - 70 - 20 = negative 10. The compensation may be noncash and the gain has its own cash history, so this profit bridge alone says nothing exact about total cash movement."},{"id":"cr-s26-level3-v1-q6","session":"26","level":3,"topic":"Share price fair value sensitivity specified","question":"Two otherwise identical at the money employee grants each contain 100,000 options and a 4 year service period, all vesting. The supplied option model value is 8 dollars per option for grant A and 12 for grant B, reflecting different supported valuation inputs. What annual fair value expenses and intrinsic values at grant follow?","choices":["Zero expense for both, using intrinsic value rather than model fair value","A: 200,000 and B: 300,000 of annual expense, with both initial intrinsic values zero","A: 800,000 and B: 1.2 million of annual expense, ignoring the service period","Both 200,000 of annual expense, treating equal strikes as equal option values"],"correct_index":1,"explanation":"Annual expense is 100,000 × 8/4 = 200,000 for A and 100,000 × 12/4 = 300,000 for B. Being at the money fixes the current intrinsic value at zero for both, but not the time value, which differs with the valuation inputs."},{"id":"cr-s26-level3-v1-q7","session":"26","level":3,"topic":"Weighted strikes exercised and share capital","question":"Employees exercise 100,000 options at 2 dollars and 50,000 at 8 dollars. An existing option reserve of 300,000 dollars is transferred, and the nominal share value is 1 dollar, with no tax or costs. What cash, share capital and share premium follow?","choices":["Cash 600,000, capital 150,000 and premium 450,000","Cash 750,000, capital 150,000 and premium 900,000","Cash 600,000, capital 150,000 and premium 750,000","Cash 900,000, capital 300,000 and premium 600,000"],"correct_index":2,"explanation":"Cash is 100,000 × 2 + 50,000 × 8 = 600,000 and new capital is 150,000 × 1 = 150,000. Premium is the balance: 600,000 + 300,000 reserve - 150,000 = 750,000. The reserve is not new cash."},{"id":"cr-s26-level3-v1-q8","session":"26","level":3,"topic":"Historical income gap versus total grant","question":"An illustrative firm reports income of 35 million dollars and a pro forma fair value loss of 25 million. The only difference is additional current compensation expense net of tax, while new current grants have a total fair value of 200 million to be earned over several years. What current net income effect follows?","choices":["200 million of additional expense, using total new grants rather than the income bridge","25 million of additional expense, using the loss magnitude rather than the bridge","10 million of additional expense, subtracting the loss from reported income","60 million of additional expense, not the full 200 million of new grant value"],"correct_index":3,"explanation":"The bridge gives the answer: 35 - cost = -25, so the cost is 60. The 200 million of total grant value is not automatically the current service charge, and other grant cohorts may also feed the expense."},{"id":"cr-s26-level3-v1-q9","session":"26","level":3,"topic":"Actual fair value cost with service update","question":"An IFRS 2 equity settled illustration grants 100 options each to 1,000 employees at a grant date option value of 10 dollars over a 2 year service period. Year 1 expects 90% vesting and recognises 450,000 of expense. At the final date 850 employees vest, with no other conditions, modifications or tax. What final year expense and cumulative cost follow?","choices":["Expense 400,000 and cumulative 850,000","Expense 425,000 and cumulative 875,000","Expense 450,000 and cumulative 900,000","Expense 850,000 and cumulative 1.3 million"],"correct_index":0,"explanation":"Actual vesting gives 850 × 100 × 10 = 850,000 of cumulative cost, less the 450,000 already recognised: 400,000 in the final year. This IFRS 2 illustration uses grant date fair value and actual service vesting, not the historical intrinsic value exemption."},{"id":"cr-s26-level3-v1-q10","session":"26","level":3,"topic":"Trend adjusted on consistent basis","question":"A fictional company reports profit of 20 million dollars in year 1 and 30 million in year 2, both excluding incremental option cost. Fair value current period compensation adjustments are 8 million and 25 million respectively, with no tax or other changes. What fair value adjusted profit trend follows?","choices":["Adjusted profit rises from 12 to 55 million, adding the year 2 cost instead of deducting it","Profit falls from 12 million to 5 million, despite reported profit rising","Adjusted profit falls from 28 to 5 million, adding the year 1 cost instead of deducting it","Adjusted profit rises from 20 to 30 million, treating the compensation as outside the adjustment"],"correct_index":1,"explanation":"Adjusted year 1 is 20 - 8 = 12 and year 2 is 30 - 25 = 5: the apparent growth reverses on a consistent measurement basis. The bridge itself explains neither the cause of the grant growth nor any cash change."}],"27":[{"id":"cr-s27-level1-v1-q1","session":"27","level":1,"topic":"Defined contribution unpaid","question":"A true defined contribution plan requires 100,000 euros of current service contributions. The employer pays 85,000 by year end, has no further legal or constructive obligation beyond the fixed contribution and all amounts are due shortly. What expense and closing liability follow?","choices":["Expense 85,000 and liability zero","Expense 15,000 and liability 100,000","Expense 100,000 and a liability of 15,000 euros","Expense zero, because the fund holds investment assets"],"correct_index":2,"explanation":"The expense is the contribution due for the service, 100,000, not the 85,000 actually paid. The unpaid 15,000 is a liability. Having no obligation to fund shortfalls is what makes the plan defined contribution."},{"id":"cr-s27-level1-v1-q2","session":"27","level":1,"topic":"Defined benefit deficit","question":"A defined benefit obligation has a present value of 900,000 euros and plan assets have a fair value of 700,000. No asset ceiling or other adjustment applies. What net balance is recognised?","choices":["A gross liability of 900,000, with plan assets presented outside the pension balance","A net asset of 200,000, reversing the direction of the deficit","A net liability of 1.6 million, adding plan assets to the obligation","A net defined benefit liability of 200,000, offsetting the plan assets against the obligation"],"correct_index":3,"explanation":"The net position is 900,000 - 700,000 = 200,000 of liability. The balance sheet amount is neither the sum of the two sides nor automatically a current expense."},{"id":"cr-s27-level1-v1-q3","session":"27","level":1,"topic":"Net interest simple","question":"The opening defined benefit obligation is 1,000,000 euros and plan assets are 800,000, with an annual discount rate of 5% and no interim cash or plan changes affecting interest. What net interest expense follows?","choices":["10,000 euros","50,000 euros","40,000 euros","90,000 euros"],"correct_index":0,"explanation":"The net deficit of 200,000 at 5% gives net interest of 10,000: obligation interest of 50,000 less asset interest of 40,000. The actual asset return is a separate comparison used for remeasurement."},{"id":"cr-s27-level1-v1-q4","session":"27","level":1,"topic":"Actual return excess","question":"Opening plan assets of 500,000 euros at a 4% discount rate produce recognised asset interest of 20,000. The actual total return is 35,000, with no other return component. What asset remeasurement follows, and where?","choices":["35,000 of additional gain in profit or loss","A gain of 15,000 in OCI","A loss of 20,000 in OCI","15,000 of service cost"],"correct_index":1,"explanation":"The actual return of 35,000 less the recognised interest of 20,000 leaves a 15,000 remeasurement gain in OCI. The full actual return is not recognised again as interest income."},{"id":"cr-s27-level1-v1-q5","session":"27","level":1,"topic":"Employer contribution effect","question":"Cash of 60,000 euros is transferred by an employer into the defined benefit plan's assets. No benefit terms or other balances change. What immediate balance sheet movement results?","choices":["Plan assets rise 60,000, cash falls 60,000 and service expense rises 60,000","The obligation rises 60,000, cash falls 60,000 and the net liability rises 60,000","Plan assets rise 60,000, cash falls 60,000 and the net liability falls 60,000","Plan assets rise 60,000, cash falls 60,000 and profit rises 60,000"],"correct_index":2,"explanation":"Funding adds to the segregated assets while reducing the employer's cash, so the net liability falls by 60,000. The contribution itself is not service cost and does not enlarge the accrued obligation."},{"id":"cr-s27-level1-v1-q6","session":"27","level":1,"topic":"Benefits paid from plan assets","question":"A defined benefit fund pays retirees 40,000 euros from plan assets, settling the same 40,000 of obligation, with no settlement gain or loss, other movement or tax. What change in the net deficit follows solely from the payment?","choices":["The deficit falls by 40,000, because the obligation is settled","The deficit rises by 40,000, because assets leave the plan","Profit falls by 80,000, because assets and obligation are both charged","No change, because the obligation and the plan assets both fall by 40,000"],"correct_index":3,"explanation":"Benefits paid from the fund reduce both gross sides equally, leaving their difference unchanged. Ordinary benefit payments are not another employer service expense."},{"id":"cr-s27-level1-v1-q7","session":"27","level":1,"topic":"Actuarial obligation loss","question":"A change in actuarial assumptions increases a defined benefit obligation by 25,000 euros, with no other change. How is this remeasurement recognised?","choices":["A loss of 25,000 in OCI, never recycled to profit or loss","A current service cost of 25,000 in profit or loss","A gain of 25,000 in OCI","No recognition until retirees receive cash"],"correct_index":0,"explanation":"An assumption change is an actuarial remeasurement loss. IAS 19 sends defined benefit remeasurements to OCI, with no later recycling into profit or loss."},{"id":"cr-s27-level1-v1-q8","session":"27","level":1,"topic":"Past service cost location","question":"A defined benefit plan amendment immediately increases the obligation by 30,000 euros for prior employee service, the recognition date is reached and nothing else changes. What treatment follows?","choices":["An OCI remeasurement loss of 30,000, treating the amendment as an actuarial change","Past service cost of 30,000 in profit or loss, not an actuarial OCI loss","A deferred service expense of 30,000, spread over remaining service lives","No expense until the benefits are paid, despite the amendment date"],"correct_index":1,"explanation":"A plan amendment changing prior benefit rights creates past service cost, recognised in profit or loss at the trigger date. It is distinct from a change in actuarial assumptions, which goes to OCI."},{"id":"cr-s27-level1-v1-q9","session":"27","level":1,"topic":"Discount rate source","question":"An IAS 19 obligation is denominated in euros with a twelve year duration, and a deep market in high quality euro corporate bonds exists. Which reporting date discount rate basis applies?","choices":["The employer's own euro borrowing yield with matching duration","The expected euro return on the plan assets with matching duration","High quality euro corporate bond yields with matching duration","Euro government bond yields with matching duration, despite the corporate market"],"correct_index":2,"explanation":"IAS 19 uses high quality corporate bond yields at the reporting date when that currency has a deep market. Government bond yields are the specified fallback only where such a market does not exist."},{"id":"cr-s27-level1-v1-q10","session":"27","level":1,"topic":"Risk classification grounded","question":"An employer promises specified retirement benefits and must make additional payments if the funded plan cannot meet them. Which classification follows?","choices":["Defined contribution, because the plan holds assets in an external fund","Defined contribution, because the employer makes regular annual contributions","Defined benefit only after an actual funding deficit is identified","Defined benefit, because the employer retains the obligation for the specified benefits"],"correct_index":3,"explanation":"Classification turns on the substance of the benefit promise and any further obligation, not on whether a separate fund exists. The stated shortfall obligation rules out a true fixed contribution classification."},{"id":"cr-s27-level2-v1-q1","session":"27","level":2,"topic":"Obligation rollforward","question":"The opening defined benefit obligation is 600,000 euros. The current service cost is 70,000, the discount rate is 5% on the opening balance, an actuarial loss is 20,000 and benefits of 50,000 are paid at year end, with no other movement. What closing obligation follows?","choices":["640,000 euros","720,000 euros","570,000 euros","670,000 euros"],"correct_index":3,"explanation":"The rollforward is 600,000 + 30,000 interest + 70,000 service + 20,000 actuarial loss - 50,000 benefits = 670,000. Contributions to plan assets would not directly reduce the obligation itself."},{"id":"cr-s27-level2-v1-q2","session":"27","level":2,"topic":"Plan assets rollforward","question":"Opening plan assets are 400,000 euros. The actual total investment return is 28,000, employer contributions are 90,000 and benefits paid are 40,000 at year end, with no other movements. What closing plan assets follow?","choices":["478,000 euros","498,000, after adding another 20,000 of interest","450,000, ignoring the return","568,000, adding contributions twice"],"correct_index":0,"explanation":"Use the actual total return once: 400,000 + 28,000 + 90,000 - 40,000 = 478,000. The interest allocation is a split of the actual return, not an extra return to add on top."},{"id":"cr-s27-level2-v1-q3","session":"27","level":2,"topic":"Pension profit and OCI bridge","question":"The opening obligation is 800,000 euros and plan assets are 600,000, with a 5% discount rate, a current service cost of 90,000 and a past service cost of 10,000. The actuarial obligation loss is 40,000, the actual asset return is 45,000 and all cash moves at year end. What profit or loss expense and OCI loss follow?","choices":["Expense 100,000 and OCI loss 40,000","Expense 110,000 and OCI loss 25,000","Expense 95,000 and OCI loss 40,000","Expense 150,000 and OCI gain 15,000"],"correct_index":1,"explanation":"Net interest is (800,000 - 600,000) × 5% = 10,000, so the profit or loss expense is 90,000 + 10,000 + 10,000 = 110,000. The asset remeasurement is 45,000 - 30,000 = 15,000 of gain, offsetting the 40,000 obligation loss for a net OCI loss of 25,000."},{"id":"cr-s27-level2-v1-q4","session":"27","level":2,"topic":"Net liability rollforward","question":"The opening pension net liability is 150,000 euros. The profit or loss pension expense is 60,000, the OCI remeasurement loss is 20,000 and employer contributions are 50,000, with no other movement. What closing net liability follows?","choices":["280,000 euros","140,000 euros","180,000 euros","110,000 euros"],"correct_index":2,"explanation":"The rollforward is 150,000 + 60,000 expense + 20,000 OCI loss - 50,000 funding = 180,000. Pension expense and funding are not interchangeable: one is a cost, the other a cash movement into the fund."},{"id":"cr-s27-level2-v1-q5","session":"27","level":2,"topic":"Projected unit credit simple","question":"A plan promises 2% of expected final salary for each service year. Expected final salary is 100,000 euros and accrued service is 3 years. The benefits attributable to those 3 years are all payable exactly 5 years from the measurement date, the discount rate is 10% and no mortality or other adjustment applies. What accrued obligation follows, rounded to the nearest euro?","choices":["6,000 euros","1,242 euros","9,663 euros","3,726 euros"],"correct_index":3,"explanation":"The undiscounted accrued benefit is 2% × 100,000 × 3 = 6,000, and its present value is 6,000 / 1.10^5 = 3,725.53, rounding to 3,726. Only service years already accrued enter the obligation."},{"id":"cr-s27-level2-v1-q6","session":"27","level":2,"topic":"Surplus ceiling supplied","question":"A defined benefit obligation of 500,000 euros and plan assets of 650,000 create a surplus. The present value of available economic benefits through refunds or contribution reductions is 100,000, with no further adjustment. What recognised net asset follows?","choices":["100,000, capping the recognised net pension asset at the asset ceiling","150,000, recognising the full surplus before the ceiling","650,000, recognising plan assets without deducting the obligation","Zero, excluding the surplus until a cash refund arrives"],"correct_index":0,"explanation":"The raw surplus of 150,000 is limited to the stated 100,000 asset ceiling. A surplus is not always fully recognisable, but its existence does not prohibit all asset recognition either."},{"id":"cr-s27-level2-v1-q7","session":"27","level":2,"topic":"Other long term benefit remeasurement","question":"An employee benefit is classified as an other long term benefit rather than a post employment benefit, and a current remeasurement loss of 12,000 euros arises. Under IAS 19, where is it recognised?","choices":["In OCI, recycled when the benefits are paid","In current profit or loss","In OCI, with no later recycling","Deferred in the liability and expensed when employment ends"],"correct_index":1,"explanation":"Remeasurements of other long term benefits are recognised in profit or loss. The OCI rule for post employment defined benefit plans must not be applied to every IAS 19 category."},{"id":"cr-s27-level2-v1-q8","session":"27","level":2,"topic":"Short term accrual","question":"Employees earn short term bonuses of 48,000 euros payable six months after year end. The obligation criteria are met, nothing is paid yet and settlement falls wholly within 12 months after the service year. What expense and measurement follow?","choices":["Zero expense, recognising the bonus only when paid","A present value below 48,000, discounting the six month obligation","Expense and liability of 48,000 euros, undiscounted","52,800, adding a ten percent financing return to the bonus"],"correct_index":2,"explanation":"Short term employee benefits accrue as the service is received and are measured undiscounted at the expected payment. Pension style discounting and cash basis recognition both miss the rule."},{"id":"cr-s27-level2-v1-q9","session":"27","level":2,"topic":"Asset return shortfall","question":"Opening plan assets are 1,000,000 euros, the discount rate is 6% and the actual total return is 20,000, with no interim movements affecting the interest calculation. What asset interest income and asset remeasurement follow?","choices":["Interest 20,000 and an OCI gain of 40,000","Interest 60,000 and an OCI gain of 20,000","Interest 80,000 and no OCI","Interest 60,000 and an OCI loss of 40,000"],"correct_index":3,"explanation":"Recognised interest is 1,000,000 × 6% = 60,000, so the actual return of 20,000 falls 40,000 short, an OCI loss. Weak actual returns do not retroactively replace the discount rate based interest allocation."},{"id":"cr-s27-level2-v1-q10","session":"27","level":2,"topic":"Benefit payment no duplicate cost","question":"The opening obligation is 300,000 euros and plan assets are 250,000. At the reporting date the fund pays 30,000 of retirement benefits, settling 30,000 of obligation, with no other changes. What closing obligation, assets and net liability follow?","choices":["Obligation 270,000, assets 220,000 and net liability 50,000","Obligation 300,000, assets 220,000 and liability 80,000","Obligation 270,000, assets 250,000 and liability 20,000","Obligation 270,000, assets 220,000 and expense 30,000"],"correct_index":0,"explanation":"Both gross sides fall by 30,000, so the deficit stays at 50,000. Settling already accrued benefits is not automatically a current service cost."},{"id":"cr-s27-level3-v1-q1","session":"27","level":3,"topic":"Comprehensive pension reconciliation","question":"The opening obligation is 1,000,000 euros and plan assets are 800,000, with a 5% annual discount rate. Current service is 120,000, past service is 20,000, the actuarial obligation loss is 50,000, the actual total asset return is 70,000, and an employer contribution of 100,000 and benefits of 60,000 both occur at year end, with no other movements or tax. What closing net liability, profit or loss expense and OCI loss follow?","choices":["Net liability 270,000, expense 150,000 and OCI loss 20,000","Net liability 270,000, expense 120,000 and OCI loss 50,000","Net liability 200,000, expense 150,000 and OCI loss 20,000","Net liability 330,000, expense 150,000 and OCI gain 30,000"],"correct_index":0,"explanation":"Obligation: 1,000,000 + 50,000 interest + 120,000 service + 20,000 past service + 50,000 actuarial loss - 60,000 benefits = 1,180,000. Assets: 800,000 + 70,000 actual return + 100,000 contribution - 60,000 benefits = 910,000. Net: 270,000. Profit or loss: 120,000 + 20,000 + 10,000 net interest = 150,000. The asset gain of 70,000 - 40,000 = 30,000 offsets the obligation loss of 50,000 for an OCI loss of 20,000."},{"id":"cr-s27-level3-v1-q2","session":"27","level":3,"topic":"Infer funding from deficit change","question":"The opening net pension liability is 200,000 euros and the closing is 230,000. The profit or loss expense is 90,000 and the net OCI gain is 20,000, with no benefit payment asymmetry, acquisition, exchange or other movement. What employer contributions follow?","choices":["80,000 euros","40,000 euros","60,000 euros","10,000 euros"],"correct_index":1,"explanation":"Solving 230,000 = 200,000 + 90,000 - 20,000 - contributions gives 40,000. An OCI gain reduces the liability in the rollforward, it does not add to it."},{"id":"cr-s27-level3-v1-q3","session":"27","level":3,"topic":"Two year interest uses updated opening","question":"Year 1 closes with an obligation of 900,000 euros and plan assets of 700,000. In year 2 the discount rate is 4%, the current service cost is 80,000 and the past service cost is 10,000, with no interim changes affecting interest and no remeasurements requested. What year 2 net interest and profit or loss expense follow?","choices":["Net interest 36,000 and expense 126,000","Net interest 28,000 and expense 118,000","Net interest 8,000 and total expense 98,000","Net interest zero and expense 90,000, because assets exist"],"correct_index":2,"explanation":"The year 2 opening deficit is 200,000, giving net interest of 200,000 × 4% = 8,000. Adding current service of 80,000 and past service of 10,000 gives a total expense of 98,000. Each year's interest uses that year's opening balances."},{"id":"cr-s27-level3-v1-q4","session":"27","level":3,"topic":"Obligation loss versus asset gain net","question":"A defined benefit plan has an actuarial obligation gain of 45,000 euros and an actual total asset return of 30,000 against recognised asset interest of 50,000, with no other remeasurement component. What net OCI effect follows?","choices":["A gain of 65,000","A loss of 25,000","A loss of 95,000","A gain of 25,000"],"correct_index":3,"explanation":"The obligation gain of 45,000 improves the net position, while the asset return shortfall of 30,000 - 50,000 = -20,000 is a loss. Net OCI gain: 25,000. The actual total return of 30,000 is not itself the whole asset remeasurement."},{"id":"cr-s27-level3-v1-q5","session":"27","level":3,"topic":"Plan amendment not actuarial netting","question":"Current service cost is 70,000 euros and net interest is 6,000. A plan amendment produces past service cost of 25,000, while a separate actuarial assumption change gives an obligation gain of 30,000, with no other items. What profit or loss expense and OCI effect follow?","choices":["Expense 101,000 and OCI gain 30,000","Expense 71,000 and OCI zero, offsetting the actuarial gain","Expense 76,000 and OCI gain 5,000","Expense 46,000 and OCI gain 25,000"],"correct_index":0,"explanation":"Profit or loss takes 70,000 + 6,000 + 25,000 = 101,000. The actuarial gain of 30,000 belongs in OCI and cannot be used to shrink the current service cost. Both items arise in the obligation but follow different recognition routes."},{"id":"cr-s27-level3-v1-q6","session":"27","level":3,"topic":"Discounting accrued service not total career","question":"An employee is expected to retire after 10 service years with a final salary of 150,000 euros, and the benefit equals 1% of final salary per service year. At the measurement date 4 years of service are complete and the retirement payment is due in 6 years. Using a 5% discount rate and ignoring turnover and mortality, what accrued obligation follows, rounded to the nearest euro?","choices":["11,193","4,477","6,000","15,000"],"correct_index":1,"explanation":"The accrued benefit is 4 × 1% × 150,000 = 6,000, discounted over 6 years: 6,000 / 1.05^6 = 4,477.29, rounding to 4,477. The future 6 years of service are not already accrued merely because they are expected."},{"id":"cr-s27-level3-v1-q7","session":"27","level":3,"topic":"Direct benefit payment by employer","question":"The opening obligation is 500,000 euros and plan assets are 400,000. The employer pays retirees 20,000 directly from its own cash, settling an equal amount of obligation without using plan assets, with no other movement or gain. What closing obligation, plan assets and net liability follow?","choices":["Obligation 480,000, assets 380,000 and net liability 100,000","Obligation 500,000, assets 420,000 and liability 80,000","Obligation 480,000, assets 400,000 and net liability 80,000","Obligation 500,000, assets 400,000 and liability 100,000"],"correct_index":2,"explanation":"A direct employer payment reduces its cash and the obligation, leaving the segregated plan assets untouched, so the net deficit falls by 20,000. This differs from benefits paid out of plan assets, which shrink both gross sides."},{"id":"cr-s27-level3-v1-q8","session":"27","level":3,"topic":"Interest surplus and ceiling excluded","question":"The opening defined benefit obligation is 700,000 euros, plan assets are 900,000 and the discount rate is 5%. The full surplus is recoverable with no asset ceiling restriction and there are no interim changes. What net interest follows?","choices":["An expense of 10,000","An expense of 35,000, without asset interest","Income of 45,000, without obligation interest","Income of 10,000"],"correct_index":3,"explanation":"Obligation interest is 35,000 and asset interest is 45,000, so the net is 10,000 of income. The stated full recoverability avoids any unstated asset ceiling adjustment."},{"id":"cr-s27-level3-v1-q9","session":"27","level":3,"topic":"Reconcile comprehensive cost versus cash","question":"The opening net pension liability is 90,000 euros and the closing is 140,000. An employer contribution of 35,000 and a direct benefit payment of 15,000 each reduce the net liability, and the only other movements are profit or loss expense of 70,000 and an unknown remeasurement. What OCI remeasurement follows?","choices":["A loss of 30,000","A gain of 30,000","Zero","A loss of 100,000"],"correct_index":0,"explanation":"Solving 140,000 = 90,000 + 70,000 + OCI - 35,000 - 15,000 gives an OCI loss of 30,000. Both stated employer cash routes reduce the net liability, while ordinary fund paid benefits would leave it unchanged."},{"id":"cr-s27-level3-v1-q10","session":"27","level":3,"topic":"Cash service cost category distinction","question":"A company has a true defined contribution expense of 40,000 euros of which 30,000 was paid, short term earned wages of 20,000 unpaid, and defined benefit current service of 50,000 with net interest of 5,000 and an OCI loss of 8,000. No other profit or loss items or tax apply. What total profit or loss expense and combined liabilities from unpaid contributions and wages follow?","choices":["Expense 123,000 and liabilities 20,000","Expense 115,000 and liabilities of 30,000 from the unpaid contributions and wages","Expense 105,000 and liabilities 30,000","Expense 115,000 and liabilities 38,000, putting OCI into the wage payable"],"correct_index":1,"explanation":"Profit or loss is 40,000 + 20,000 + 50,000 + 5,000 = 115,000. The unpaid contribution of 10,000 plus wages of 20,000 make 30,000 of separate current liabilities. The defined benefit OCI loss of 8,000 is neither profit or loss expense nor wage payable."}],"28":[{"id":"cr-s28-level1-v1-q1","session":"28","level":1,"topic":"Full consolidation despite minority","question":"A parent controls a subsidiary with 70% ownership. The subsidiary has identifiable assets of 1,000,000 euros and liabilities of 600,000, with no fair value, tax or other adjustment. What subsidiary assets and liabilities enter line by line consolidation before the investment elimination?","choices":["70% of each: assets 700,000 and liabilities 420,000","Only the net investment, applying the equity method despite control","100%: assets of 1,000,000 and liabilities of 600,000, with NCI shown separately","Assets 1,000,000 and liabilities 420,000, consolidating assets fully but liabilities proportionately"],"correct_index":2,"explanation":"A controlled subsidiary is consolidated in full, line by line. The 70% ownership affects the allocation to the non-controlling interest, not the proportion of each asset and liability included."},{"id":"cr-s28-level1-v1-q2","session":"28","level":1,"topic":"Control includes power link","question":"An investor owns 45% and receives variable dividends. An independent manager holds all substantive rights to direct the relevant activities, and the investor cannot replace or override the manager. Which control components does the investor have?","choices":["Power and variable returns, but no link between them","Power and the ability to use it, but no variable returns","Variable returns and joint direction rights, but no unilateral power","Variable returns, but neither power nor an ability to use power to affect them"],"correct_index":3,"explanation":"IFRS 10 requires power, exposure to variable returns and the ability to use power to affect those returns. On the stated facts the investor has only the exposure. That is necessary but not sufficient."},{"id":"cr-s28-level1-v1-q3","session":"28","level":1,"topic":"Protective lender rights","question":"A lender can block exceptional asset disposals that threaten repayment, but cannot direct the ordinary activities affecting returns, and those veto rights are protective on the supplied facts. What follows for lender control?","choices":["The veto rights alone do not supply power over the relevant activities","The veto rights establish sole control whenever a disposal exceeds the loan balance","The veto rights establish joint control, since shareholders cannot dispose without consent","The veto rights establish control only from the moment the lender first uses them"],"correct_index":0,"explanation":"Protective rights safeguard an interest without directing the relevant activities. A veto label is not enough to infer substantive power over the normal business."},{"id":"cr-s28-level1-v1-q4","session":"28","level":1,"topic":"Substantive ability matters","question":"A contract grants an investor decision rights, but a legal barrier prevents their exercise when relevant decisions must be made, and the investor has no other power. Which feature is missing from the right's contribution to current power?","choices":["Its written description in an enforceable contract","Its substantive exercisability when the relevant decisions are needed","Its potential to affect the value of the investor's return","Its association with a contract rather than a shareholding"],"correct_index":1,"explanation":"Power requires existing substantive rights and the practical ability to direct the relevant activities. The specific barrier defeats that here, though contractual rights are not automatically irrelevant."},{"id":"cr-s28-level1-v1-q5","session":"28","level":1,"topic":"Partial goodwill basic","question":"A parent buys 80% of a business for 900,000 euros. The fair value of identifiable net assets is 1,000,000, there is no previous interest and the NCI uses the proportionate share of net assets. What goodwill follows?","choices":["Negative 100,000 euros","300,000 euros","100,000 euros","900,000 euros"],"correct_index":2,"explanation":"The parent's share is 80% × 1,000,000 = 800,000, so partial goodwill is 900,000 - 800,000 = 100,000. Deducting 100% of net assets from a price paid for 80% would be wrong."},{"id":"cr-s28-level1-v1-q6","session":"28","level":1,"topic":"Full goodwill basic","question":"A parent buys 80% for 900,000 euros, the independently measured NCI fair value is 250,000 and the fair value of identifiable net assets is 1,000,000, with no previous interest. What full goodwill follows?","choices":["100,000 euros","250,000 euros","1,150,000 euros","150,000 euros"],"correct_index":3,"explanation":"Full goodwill is 900,000 + 250,000 - 1,000,000 = 150,000. The supplied NCI fair value exceeds its proportionate 200,000 share, which is what creates the extra 50,000 of recognised goodwill."},{"id":"cr-s28-level1-v1-q7","session":"28","level":1,"topic":"Investment elimination not asset aggregation","question":"A parent's investment in its controlled subsidiary stands at 800,000 euros in its separate accounts. Full consolidation replaces that investment with the underlying subsidiary balances and appropriate goodwill and NCI. What happens to the 800,000 investment line in the group accounts?","choices":["It is eliminated, because the subsidiary's underlying net assets replace it","It is retained, while only the subsidiary's share capital is eliminated","Only the ownership percentage is eliminated and the rest becomes goodwill","It is offset against subsidiary debt instead of acquisition equity"],"correct_index":0,"explanation":"Keeping both the investment line and the underlying controlled balances would double count the same economic interest. The elimination is distinct from an impairment or a sale of the investment."},{"id":"cr-s28-level1-v1-q8","session":"28","level":1,"topic":"Acquisition net asset uplift tax supplied","question":"At acquisition an asset fair value uplift of 100,000 euros has an unchanged tax base, the applicable tax rate is 25% and the DTL recognition conditions are met. What net increase in identifiable net assets follows?","choices":["100,000 euros","75,000 euros","125,000 euros","25,000 euros"],"correct_index":1,"explanation":"The uplift creates a taxable temporary difference of 100,000 and a DTL of 25,000, so identifiable net assets rise by 100,000 - 25,000 = 75,000. The unchanged tax base is supplied as a fact, not assumed universally."},{"id":"cr-s28-level1-v1-q9","session":"28","level":1,"topic":"Goodwill subsequent treatment","question":"Goodwill from an IFRS business combination is recognised and no disposal occurs. Which ordinary subsequent approach applies?","choices":["Amortise over ten years and test only after an adverse indicator","Remeasure the business annually, taking goodwill increases to OCI","Test annually and on indicators, without routine amortisation","Keep at cost until disposal, testing only if management intentions change"],"correct_index":2,"explanation":"IFRS goodwill is not routinely amortised. Annual impairment testing, plus indicator driven tests, governs its carrying amount, rather than automatic annual expense or upward revaluation."},{"id":"cr-s28-level1-v1-q10","session":"28","level":1,"topic":"Consolidation start control date","question":"A parent signs an acquisition agreement on 1 March, obtains control on 10 March and pays the consideration on 20 March. The dates are stipulated and no earlier control exists. When does consolidation begin?","choices":["1 March, the date the agreement is signed","20 March, the date the consideration is paid","31 March, the month end used for consolidation","10 March, the date control is obtained"],"correct_index":3,"explanation":"Consolidation starts when control is obtained. Signing and payment dates can differ from the moment the power and returns relationship actually transfers."},{"id":"cr-s28-level2-v1-q1","session":"28","level":2,"topic":"Net assets partial goodwill tax","question":"A parent buys 75% for 1.2 million euros. The acquiree's book net assets are 1 million, recognisable asset uplifts of 400,000 with unchanged tax base create a deferred tax liability at 25%, and there are no other adjustments. The NCI is measured at its proportionate share. What net assets, NCI and goodwill follow?","choices":["Net assets 1.4 million, NCI 350,000 and goodwill 150,000","Net assets 1.1 million, NCI 275,000 and goodwill 375,000","Net assets 1.3 million, NCI 325,000 and goodwill negative 100,000","Net assets 1.3 million euros, NCI 325,000 and goodwill 225,000 euros"],"correct_index":3,"explanation":"The uplift of 400,000 less the 100,000 DTL adds 300,000 net, giving net assets of 1.3 million. NCI is 25% × 1.3 million = 325,000, and goodwill is 1.2 million - 75% × 1.3 million = 225,000."},{"id":"cr-s28-level2-v1-q2","session":"28","level":2,"topic":"Full versus partial difference","question":"Consideration for 80% is 2 million euros, identifiable net assets are 2 million, and the NCI fair value is 550,000 against a proportionate share of 400,000. There are no other items. What partial and full goodwill follow?","choices":["Partial 400,000 euros and full 550,000 euros","Partial 550,000 euros and full 400,000","Both zero, because the price equals 100% of net assets","Partial 2 million euros and full 2.55 million"],"correct_index":0,"explanation":"Partial goodwill is 2 million - 80% × 2 million = 400,000. Full goodwill is 2 million + 550,000 - 2 million = 550,000. The 150,000 difference is the NCI fair value premium above its proportionate share."},{"id":"cr-s28-level2-v1-q3","session":"28","level":2,"topic":"Post acquisition reserves share","question":"A parent owns 80% throughout the period after acquisition. The subsidiary's retained earnings rise by 300,000 euros after acquisition, with no dividends and no consolidation adjustments. What increases arise in parent group retained earnings and NCI?","choices":["Parent 300,000 euros and NCI zero","Parent 240,000 euros and NCI 60,000 euros","Parent 60,000 euros and NCI 240,000","Both 300,000 euros"],"correct_index":1,"explanation":"The post acquisition increase of 300,000 is shared 80/20: 240,000 to the parent and 60,000 to the NCI. Pre acquisition reserves belong to purchase accounting, not to the parent's post acquisition retained earnings."},{"id":"cr-s28-level2-v1-q4","session":"28","level":2,"topic":"Post acquisition fair value depreciation","question":"At acquisition a subsidiary PPE uplift of 200,000 euros has a 5 year remaining life and an unchanged tax base, and the tax rate is 25%. One full year elapses on a straight line basis with no other change. What extra depreciation and deferred tax effect follow?","choices":["Depreciation 50,000 and deferred tax benefit 12,500","Depreciation 40,000 and additional deferred tax expense 10,000","Extra depreciation 40,000 euros and deferred tax benefit 10,000 euros","Depreciation zero and deferred tax unchanged, keeping pre acquisition depreciation in group profit"],"correct_index":2,"explanation":"The extra depreciation is 200,000 / 5 = 40,000. The related DTL reverses by 40,000 × 25% = 10,000, a deferred tax benefit, leaving a 30,000 after tax reduction in group profit."},{"id":"cr-s28-level2-v1-q5","session":"28","level":2,"topic":"NCI adjusted post acquisition profit","question":"A subsidiary earns 500,000 euros after acquisition. Extra fair value depreciation of 80,000 and a related DTL reversal of 20,000 apply. The NCI owns 25% and there are no other adjustments. What is the NCI share of adjusted profit?","choices":["125,000 euros","105,000 euros","15,000 euros","110,000 euros"],"correct_index":3,"explanation":"Adjusted profit is 500,000 - 80,000 + 20,000 = 440,000, and the NCI share is 25% × 440,000 = 110,000. The ownership percentage is applied after the consolidation adjustments to subsidiary profit."},{"id":"cr-s28-level2-v1-q6","session":"28","level":2,"topic":"Bargain purchase reassessment supplied","question":"A 100% business acquisition has consideration of 700,000 euros and a fair value of identifiable net assets of 800,000, with no previous interest and no NCI. All required reassessment is complete and the amounts are confirmed. What result follows?","choices":["A 100,000 euros bargain purchase gain in profit or loss","Negative goodwill of 100,000 carried as a deferred liability and released over time","Goodwill of 100,000 as an asset, reversing the sign of the acquisition difference","A 100,000 reduction of the acquired assets until net assets equal the consideration"],"correct_index":0,"explanation":"After the required reassessment, confirmed net assets exceed the consideration by 100,000. That excess is a bargain purchase gain recognised in profit or loss, not a liability or an asset write down."},{"id":"cr-s28-level2-v1-q7","session":"28","level":2,"topic":"Group assets investment elimination","question":"Parent total assets of 5 million euros include an investment of 1 million in a wholly owned subsidiary. The subsidiary has assets of 2 million and liabilities of 1.2 million, all fair values equal book values, the consideration was 1 million and there are no other adjustments. What are consolidated total assets?","choices":["7 million euros","6.2 million euros","6 million euros","5.8 million euros"],"correct_index":1,"explanation":"Subsidiary net assets are 800,000 against a price of 1 million, so goodwill is 200,000. Consolidated assets are 5 million + 2 million - 1 million investment eliminated + 200,000 goodwill = 6.2 million. Both the elimination and the goodwill matter."},{"id":"cr-s28-level2-v1-q8","session":"28","level":2,"topic":"Separate account dividend versus group","question":"A parent owns 80% of a subsidiary and carries the investment at cost in its separate accounts. The subsidiary declares and pays dividends of 100,000 euros, of which 80,000 goes to the parent and 20,000 to the NCI. There are no tax or other effects. What dividend income remains in group profit and what external cash distribution follows?","choices":["Dividend income 80,000 and distribution 100,000","Dividend income 100,000 and no distribution","No dividend income, and an external distribution of 20,000","Dividend income 20,000 and distribution 80,000"],"correct_index":2,"explanation":"The parent's receipt of 80,000 is intragroup and is eliminated on consolidation. Only the 20,000 paid to the external NCI leaves the group, as an equity distribution rather than a group expense."},{"id":"cr-s28-level2-v1-q9","session":"28","level":2,"topic":"Exemption conditions conjunctive","question":"An intermediate parent has unlisted shares but publicly traded bonds. It meets every other ordinary consolidation exemption condition and is not an investment entity. Does the bond listing prevent the IFRS 10 exemption?","choices":["Yes, because only public equity trading prevents the exemption","Yes, because publicly traded debt does not confer voting rights","Yes, because a public ultimate parent report overrides the debt condition","No, because publicly traded debt fails one required condition"],"correct_index":3,"explanation":"The exemption conditions are cumulative and cover publicly traded debt or equity alike. Satisfying the other conditions does not cure the stated public debt failure."},{"id":"cr-s28-level2-v1-q10","session":"28","level":2,"topic":"Own majority versus another power holder","question":"A holds 60% of the votes, but B has substantive contractual rights to direct all the relevant activities. A cannot override B and has no other power. Does the voting percentage establish A's control?","choices":["No, because the supplied contractual direction rights prevent A from having the required power","Yes, because a majority vote takes precedence over a contractual decision arrangement","Yes, because the investor's dividend exposure provides power even without direction rights","No, because a voting interest above half requires joint control rather than sole control"],"correct_index":0,"explanation":"Control depends on substantive power over the relevant activities, returns and the link between them. A voting majority is a common indicator, not an unconditional substitute for the actual governance assessment."},{"id":"cr-s28-level3-v1-q1","session":"28","level":3,"topic":"Integrated acquisition and first year reserves","question":"A parent buys 80% for 1.6 million euros on the first day of the year. Book net assets are 1.5 million, a PPE uplift of 500,000 has an unchanged tax base, the tax rate is 20% and the remaining life is 5 years. The NCI is proportionate. The subsidiary's after tax book profit is 300,000, with no dividends, impairment or other adjustments. What acquisition goodwill, parent post acquisition profit share and closing NCI follow?","choices":["Goodwill 80,000, parent share 176,000 and NCI 424,000","Goodwill zero, parent share 240,000 and NCI 440,000","Goodwill 80,000, parent share 240,000 and NCI 440,000","Goodwill 400,000, parent share 176,000 and NCI 424,000"],"correct_index":0,"explanation":"Acquisition net assets are 1.5 million + 500,000 - 100,000 DTL = 1.9 million, so goodwill is 1.6 million - 80% × 1.9 million = 80,000. Adjusted profit is 300,000 - 100,000 extra depreciation + 20,000 tax = 220,000, of which the parent takes 176,000. The NCI opens at 20% × 1.9 million = 380,000 and adds 44,000 of profit to close at 424,000."},{"id":"cr-s28-level3-v1-q2","session":"28","level":3,"topic":"Full goodwill impairment allocation supplied","question":"An 80% owned subsidiary carries full goodwill of 500,000 euros, and a full goodwill impairment of 100,000 arises this year. Assume the impairment is allocated 80% to the parent and 20% to the NCI, with no tax or other changes. What carrying goodwill and impairment attribution follow?","choices":["Goodwill 400,000, parent loss 100,000 and NCI loss zero","Goodwill 400,000 euros, parent loss 80,000 and NCI loss 20,000 euros","Goodwill 500,000, parent loss 80,000 and NCI loss 20,000 only through equity","Goodwill 420,000, parent loss 80,000 and NCI loss zero, excluding the NCI from full goodwill"],"correct_index":1,"explanation":"The recognised 500,000 is written down by 100,000 to 400,000. Under the supplied full goodwill allocation, 80,000 falls on the parent and 20,000 on the NCI. Partial goodwill would need a different treatment, not this assumed full basis."},{"id":"cr-s28-level3-v1-q3","session":"28","level":3,"topic":"Net assets liability fair value direction","question":"An acquiree's book net assets are 2 million euros. An identifiable asset uplift of 300,000 and a recognisable liability increase of 100,000 together carry an explicit net deferred tax effect of 50,000 additional liability. There are no other adjustments. The parent buys 75% for 1.8 million and the NCI is proportionate. What net assets and goodwill follow?","choices":["Net assets 2.45 million and goodwill negative 37,500","Net assets 2.25 million and goodwill 112,500","Net assets 2.15 million euros and goodwill 187,500 euros","Net assets 2.15 million and goodwill negative 350,000"],"correct_index":2,"explanation":"Net assets are 2 million + 300,000 - 100,000 - 50,000 = 2.15 million. The parent's 75% share is 1,612,500, so goodwill is 1.8 million - 1,612,500 = 187,500. The liability uplift reduces net assets rather than increasing them."},{"id":"cr-s28-level3-v1-q4","session":"28","level":3,"topic":"Equity transaction without control loss","question":"A parent reduces its ownership from 80% to 70% but retains control. It receives 300,000 euros and the required increase in the NCI carrying amount is 240,000. There is no tax, no costs and no other change. What consolidated treatment follows?","choices":["Profit of 300,000 and no change to NCI","Profit of 60,000 and goodwill remeasured","Loss of 240,000 and the cash ignored","Parent equity up 60,000 and no gain in profit or loss"],"correct_index":3,"explanation":"With control retained, the sale is an equity transaction. Cash of 300,000 less the 240,000 NCI increase gives a 60,000 credit to parent equity, not a profit. Goodwill is not remeasured for a mere ownership change within control."},{"id":"cr-s28-level3-v1-q5","session":"28","level":3,"topic":"Further purchase while retaining control","question":"A parent already controls 80% and buys a further 10% for 250,000 euros, retaining control. The required reduction in the NCI carrying amount is 180,000. There is no tax and no other change. What parent equity and goodwill effects follow?","choices":["Parent equity decreases 70,000 euros and goodwill is unchanged","Goodwill increases 70,000 euros and parent equity is unchanged","Profit increases 70,000 euros","Parent equity decreases 250,000 and goodwill increases 180,000"],"correct_index":0,"explanation":"The payment of 250,000 exceeds the 180,000 reduction in NCI by 70,000, which is charged to parent equity. Buying non-controlling interests after control is obtained is an equity transaction that creates no new business combination and no new goodwill."},{"id":"cr-s28-level3-v1-q6","session":"28","level":3,"topic":"Partial method post acquisition losses","question":"A parent owns 75%. At acquisition the fair value of net assets was 1 million euros and partial goodwill was 200,000. The subsidiary's adjusted post acquisition losses are 400,000, with no dividends, impairment or other changes. What closing NCI and parent share of the post acquisition loss follow?","choices":["NCI 250,000 euros and parent loss 400,000","NCI 150,000 euros and parent loss 300,000 euros","NCI zero and parent loss 400,000","NCI 450,000 euros and parent loss 100,000"],"correct_index":1,"explanation":"The NCI opens at 25% × 1 million = 250,000 and absorbs 25% × 400,000 = 100,000 of the losses, closing at 150,000. The parent's share of the loss is 75% × 400,000 = 300,000. The unimpaired partial goodwill does not change this allocation."},{"id":"cr-s28-level3-v1-q7","session":"28","level":3,"topic":"Deferred tax reduction goodwill sensitivity","question":"A parent buys 80% for 2 million euros. Identifiable net assets before a PPE uplift are 2 million, and the uplift of 500,000 has an unchanged tax base with a tax rate of 30%. The NCI is proportionate. What goodwill follows, and by how much would ignoring the uplift's deferred tax liability understate goodwill?","choices":["Goodwill zero, understated by 150,000","Goodwill 150,000, understated by 150,000","Goodwill 120,000, understated by 120,000","Goodwill 400,000, understated by 400,000"],"correct_index":2,"explanation":"Net assets are 2 million + 500,000 - 150,000 DTL = 2.35 million, the parent's 80% share is 1.88 million and goodwill is 120,000. Ignoring the DTL gives net assets of 2.5 million, a parent share of 2 million and goodwill of zero, understating goodwill by the full 120,000."},{"id":"cr-s28-level3-v1-q8","session":"28","level":3,"topic":"Group retained earnings eliminate pre acquisition","question":"Parent retained earnings are 3 million euros. Subsidiary retained earnings were 400,000 at acquisition and are 900,000 at the reporting date. The parent owns 80%, with no fair value profit adjustments, goodwill impairment or other consolidation differences. What group retained earnings attributable to the parent follow?","choices":["3.9 million euros","3.72 million euros","3.32 million euros","3.4 million euros"],"correct_index":3,"explanation":"Only the post acquisition increase of 900,000 - 400,000 = 500,000 counts, and the parent's 80% share is 400,000. Group retained earnings attributable to the parent are 3 million + 400,000 = 3.4 million. The subsidiary's full closing reserves are not all post acquisition parent earnings."},{"id":"cr-s28-level3-v1-q9","session":"28","level":3,"topic":"Full NCI choice difference no acquisition profit","question":"An 80% business acquisition has consideration of 1.5 million euros and identifiable net assets of 1.4 million. The NCI can be measured at its proportionate share of 280,000 or at an independent fair value of 350,000. There are no other differences. What changes when the full method is chosen instead of the partial method?","choices":["Goodwill and NCI each rise 70,000, with no acquisition profit","Goodwill falls 70,000 and profit rises 70,000, with unchanged NCI","NCI rises 70,000 and goodwill stays at 380,000, with unchanged profit","Goodwill stays at 380,000 and NCI stays at 280,000 under both methods"],"correct_index":0,"explanation":"Partial goodwill is 1.5 million + 280,000 - 1.4 million = 380,000. Full goodwill is 1.5 million + 350,000 - 1.4 million = 450,000. The 70,000 difference raises both the asset and the NCI equity. It is not new revenue or profit."},{"id":"cr-s28-level3-v1-q10","session":"28","level":3,"topic":"Existing control rights reassessment","question":"A parent currently controls 60% of a subsidiary. A new enforceable governance agreement gives another party substantive decision rights over all relevant activities and removes the parent's power, while the parent remains exposed to variable returns. On the stated facts the parent no longer has power or the power and returns link. What follows?","choices":["Continue consolidation, because retained majority votes determine power after the amendment","Reassess control and stop consolidation, because retaining 60% does not preserve power","Continue consolidation, because the return exposure remains despite the lost decision rights","Stop consolidation only on a share disposal rather than a contractual power change"],"correct_index":1,"explanation":"Control is reassessed when facts and circumstances change. Retained majority ownership does not restore power removed by a substantive agreement. The consequences of losing control require their own measurement, not an automatic goodwill update."}],"29":[{"id":"cr-s29-level1-v1-q1","session":"29","level":1,"topic":"Inventory margin versus markup","question":"A parent sells goods to its controlled subsidiary for 150,000 euros. The original cost was 120,000. Half the goods remain unsold outside the group at year end. Ignore tax. What unrealised profit must be eliminated?","choices":["18,750 euros","75,000 euros","15,000 euros","30,000 euros"],"correct_index":2,"explanation":"The entire internal margin is 30,000, and half remains in closing inventory, so 15,000 is unrealised. The selling price is not the profit base."},{"id":"cr-s29-level1-v1-q2","session":"29","level":1,"topic":"Full elimination with NCI","question":"A parent owns 70% of a subsidiary. An internal inventory transfer generated 40,000 euros of profit, all still in group inventory. Ignore tax. What profit elimination is required before attributing income to owners?","choices":["28,000 euros","12,000 euros","Zero, because the buyer is not wholly owned","40,000 euros"],"correct_index":3,"explanation":"Consolidation eliminates 100% of internal profit. The 70% ownership affects attribution of the results, not the amount removed from group inventory."},{"id":"cr-s29-level1-v1-q3","session":"29","level":1,"topic":"Internal sale and external revenue","question":"The parent reports revenue of 900,000 euros and its subsidiary reports 500,000. Included in the parent amount is 160,000 billed to that subsidiary, the only intragroup sale. What group revenue remains after elimination?","choices":["1,240,000 euros","1,400,000 euros","1,288,000 euros if ownership is 70%","1,060,000 euros"],"correct_index":0,"explanation":"Both entities are added in full and internal sales are eliminated in full: 900,000 + 500,000 - 160,000 = 1,240,000."},{"id":"cr-s29-level1-v1-q4","session":"29","level":1,"topic":"Downstream attribution","question":"A parent owns 80% of a subsidiary. The parent sold inventory downstream and recorded 25,000 euros of profit which is wholly unrealised at year end. Subsidiary profit before consolidation adjustments is 200,000. There is no tax and no other adjustment. What profit is attributed to the NCI?","choices":["45,000 euros","40,000 euros","35,000 euros","20,000 euros"],"correct_index":1,"explanation":"The unrealised profit sits in the parent's earnings and does not reduce the subsidiary's profit in this downstream case. The NCI is 20% × 200,000 = 40,000."},{"id":"cr-s29-level1-v1-q5","session":"29","level":1,"topic":"Upstream attribution","question":"A subsidiary owned 80% sells goods upstream to its parent. Subsidiary profit is 200,000 euros and includes 25,000 of unrealised profit sitting in closing group inventory. There is no tax and no other adjustment. What profit is attributed to the NCI?","choices":["5,000 euros","20,000 euros","35,000 euros","40,000 euros"],"correct_index":2,"explanation":"The seller is the subsidiary, so its adjusted profit is 200,000 - 25,000 = 175,000, and the NCI takes 20% × 175,000 = 35,000."},{"id":"cr-s29-level1-v1-q6","session":"29","level":1,"topic":"Loan and interest cancellation","question":"A parent lends its subsidiary 400,000 euros. Both record 16,000 of interest consistently. All the principal remains due at year end. What survives in the consolidated statements from these internal balances alone?","choices":["The 400,000 loan survives, with only the subsidiary's liability eliminated","The 16,000 interest expense survives, with only the parent's income eliminated","Loan and interest are eliminated only in proportion to ownership","Neither the loan nor the interest survives, both eliminate in full"],"correct_index":3,"explanation":"The group cannot lend to itself. Matching internal principal and interest are both eliminated in full."},{"id":"cr-s29-level1-v1-q7","session":"29","level":1,"topic":"External minority dividend","question":"A subsidiary owned 75% pays dividends of 120,000 euros. The parent records its 90,000 receipt as income in its separate accounts. Ignore tax. What group dividend income and external cash distribution arise?","choices":["No dividend income, and a 30,000 external distribution","90,000 income and a 120,000 external distribution","30,000 income and a 90,000 external distribution","No income and no external distribution"],"correct_index":0,"explanation":"The parent's receipt is internal and eliminated. The NCI receipt of 30,000 is external: it reduces group cash and NCI equity."},{"id":"cr-s29-level1-v1-q8","session":"29","level":1,"topic":"Inventory carrying amount","question":"A parent sells goods costing 72,000 euros to a subsidiary for 90,000. All remain unsold, no impairment exists and tax is ignored. What inventory carrying amount does the group report for these goods?","choices":["The parent's ownership percentage times 90,000","72,000 euros","90,000 euros","18,000 euros"],"correct_index":1,"explanation":"The group retains its original cost of 72,000. The internal profit of 18,000 does not create a higher group asset."},{"id":"cr-s29-level1-v1-q9","session":"29","level":1,"topic":"Internal PPE sale","question":"A parent sells machinery carried at 240,000 euros to a subsidiary for 300,000 at the reporting date, before any further depreciation. There is no impairment and no tax. What gain and machinery carrying amount does the group report?","choices":["Zero gain and machinery 300,000 euros","60,000 gain and machinery 240,000 euros","Zero gain and machinery 240,000 euros","60,000 gain and machinery 300,000 euros"],"correct_index":2,"explanation":"An internal sale does not generate a group disposal gain. The 60,000 is eliminated from both profit and the asset, which stays at 240,000."},{"id":"cr-s29-level1-v1-q10","session":"29","level":1,"topic":"Loss reflecting real impairment","question":"Inventory cost to the group is 100,000 euros. It is sold internally for 82,000. At year end its net realisable value is 82,000 and all remains in inventory. There are no further changes and no tax. What group carrying amount follows?","choices":["100,000, reversing the internal loss without considering the group's net realisable value","91,000, recognising half the internal decline as an external impairment","18,000, treating the internal loss amount as the closing inventory balance","82,000 euros, because the decline is genuine"],"correct_index":3,"explanation":"Eliminating internal transactions cannot remove a genuine impairment. The group measures the goods at the lower of its original cost of 100,000 and net realisable value of 82,000."},{"id":"cr-s29-level2-v1-q1","session":"29","level":2,"topic":"Markup and unsold fraction","question":"Internal sales from subsidiary to parent amount to 250,000 euros, priced at original cost plus 25%. Forty percent of the goods have not left the group at year end. Ignoring tax, how much profit must be removed from inventory?","choices":["25,000 euros","50,000 euros","100,000 euros","20,000 euros"],"correct_index":3,"explanation":"The original cost is 250,000 / 1.25 = 200,000, so total internal profit is 50,000. The unsold 40% contains 40% × 50,000 = 20,000 of unrealised profit."},{"id":"cr-s29-level2-v1-q2","session":"29","level":2,"topic":"Margin and deferred tax","question":"A parent sells inventory internally for 300,000 euros with a 20% margin on the selling price. One third remains unsold. The buyer's tax base equals the transfer price and the applicable tax rate is 25%. The DTA recognition criteria are met. What inventory reduction and deferred tax asset follow?","choices":["20,000 reduction and 5,000 DTA","25,000 reduction and 6,250 DTA","60,000 reduction and 15,000 DTA","20,000 reduction and 5,000 DTL"],"correct_index":0,"explanation":"The margin on the full transfer is 20% × 300,000 = 60,000, and one third of it, 20,000, is unrealised. The tax base then exceeds the consolidated carrying amount by 20,000, giving a DTA of 25% × 20,000 = 5,000."},{"id":"cr-s29-level2-v1-q3","session":"29","level":2,"topic":"Upstream tax and NCI","question":"A subsidiary owned 80% has book profit after tax of 400,000 euros. Its upstream sale contains 60,000 of unrealised profit, and the consolidation adjustment gives a 15,000 deferred tax benefit. There is no other adjustment. What NCI profit follows?","choices":["89,000 euros","71,000 euros","80,000 euros","68,000 euros"],"correct_index":1,"explanation":"Adjusted subsidiary profit is 400,000 - 60,000 + 15,000 = 355,000, and the NCI receives 20% × 355,000 = 71,000."},{"id":"cr-s29-level2-v1-q4","session":"29","level":2,"topic":"Inventory write down already recorded","question":"Group cost is 80,000 euros. A parent sells the goods to a subsidiary for 110,000. The buyer has already written the inventory down to its net realisable value of 95,000 at year end, and all goods remain unsold. Ignore tax. What further inventory reduction is needed on consolidation?","choices":["Zero","25,000 euros","15,000 euros","30,000 euros"],"correct_index":2,"explanation":"The internal margin was 30,000, and the buyer's write down of 15,000 has already absorbed half of it. Group inventory should be 80,000, so only a further 15,000 reduction from 95,000 is needed."},{"id":"cr-s29-level2-v1-q5","session":"29","level":2,"topic":"Inventory genuine decline below group cost","question":"Group cost is 80,000 euros and the internal transfer price is 110,000. The buyer has written the unsold goods down to a net realisable value of 70,000. Ignore tax. What additional inventory adjustment is required on consolidation?","choices":["Reduce by a further 30,000","Increase by 10,000, back to group cost","Increase by 40,000, back to the transfer price","Zero, since the 70,000 carrying amount is already correct"],"correct_index":3,"explanation":"The buyer's write down of 40,000 has already removed the full internal profit of 30,000 and more. Group inventory stays at the lower of original cost of 80,000 and net realisable value of 70,000, so nothing further is adjusted."},{"id":"cr-s29-level2-v1-q6","session":"29","level":2,"topic":"PPE excess depreciation","question":"On the first day of the year a parent transfers machinery carried at 300,000 euros to a subsidiary for 420,000. The remaining life is six years, straight line, with no residual value. Ignore tax. What closing PPE reduction and current profit reduction are needed?","choices":["100,000 euros each","120,000 euros each","20,000 euros each","100,000 PPE reduction and 120,000 profit reduction"],"correct_index":0,"explanation":"Remove the 120,000 gain and reverse the excess depreciation of 120,000 / 6 = 20,000. The remaining unrealised gain in PPE and the net profit reduction are both 120,000 - 20,000 = 100,000."},{"id":"cr-s29-level2-v1-q7","session":"29","level":2,"topic":"Opening profit realised externally","question":"Opening inventory contains 24,000 euros of internal profit eliminated last year. All that inventory is sold to external customers this year. No new internal inventory exists and tax is ignored. What current year consolidation effect follows?","choices":["No profit effect, because last year's elimination is permanent","Increase current profit by 24,000 euros through cost of sales","Reduce current profit by 24,000 euros again","Increase current revenue by 24,000 euros"],"correct_index":1,"explanation":"The prior profit is now realised externally. Releasing the opening inventory elimination reduces this year's consolidated cost of sales by 24,000, increasing current profit."},{"id":"cr-s29-level2-v1-q8","session":"29","level":2,"topic":"Combined revenue and cost of sales","question":"Parent and subsidiary total revenue before elimination is 2 million euros and total cost of sales is 1.3 million. Internal sales are 300,000 and closing unrealised profit is 50,000. There is no opening unrealised profit, no tax and no other adjustment. What consolidated revenue and cost of sales follow?","choices":["Revenue 2 million and cost of sales 1.35 million","Revenue 1.75 million and cost of sales 1.05 million","Revenue 1.7 million and cost of sales 1.05 million euros","Revenue 1.7 million and cost of sales 1 million"],"correct_index":2,"explanation":"Eliminate the 300,000 of internal sales from both revenue and cost of sales, then add the 50,000 closing unrealised profit back to cost of sales: revenue 1.7 million and cost of sales 1.3 million - 300,000 + 50,000 = 1.05 million."},{"id":"cr-s29-level2-v1-q9","session":"29","level":2,"topic":"Cash in transit reconciliation","question":"The parent records a 90,000 euro receivable from its subsidiary. The subsidiary records a 70,000 payable because it sent 20,000 in cash near year end, which the parent has not yet received or recorded. What adjustment precedes elimination?","choices":["Expense 20,000, treating the unmatched balance as a group loss","Increase the subsidiary payable by 20,000 without recognising cash in transit","Eliminate 70,000 and retain 20,000 as an external receivable pending arrival","Recognise 20,000 cash in transit and reduce the parent receivable to 70,000"],"correct_index":3,"explanation":"First reconcile the timing difference by recognising the missing receipt as cash in transit: the parent records 20,000 of cash and its receivable falls to 70,000. The matching 70,000 internal receivable and payable can then be eliminated."},{"id":"cr-s29-level2-v1-q10","session":"29","level":2,"topic":"NCI closing roll forward","question":"Opening NCI is 300,000 euros. The subsidiary's adjusted current profit is 160,000 and total dividends are 80,000. The NCI owns 25% throughout, with no OCI and no ownership changes. What closing NCI follows?","choices":["320,000 euros","340,000 euros","280,000 euros","380,000 euros"],"correct_index":0,"explanation":"Add the NCI share of profit, 25% × 160,000 = 40,000, and subtract the NCI share of dividends, 25% × 80,000 = 20,000: 300,000 + 40,000 - 20,000 = 320,000."},{"id":"cr-s29-level3-v1-q1","session":"29","level":3,"topic":"Upstream inventory two year release","question":"An 80% owned subsidiary has after tax book profit of 500,000 euros. Opening inventory contains upstream profit of 40,000 eliminated last year, all now sold externally. Closing inventory contains new upstream profit of 70,000. Both adjustments carry tax at 25%, with all DTA criteria met. What adjusted subsidiary profit and NCI profit follow?","choices":["477,500 euros and 95,500 euros","470,000 euros and 94,000 euros","447,500 euros and 89,500 euros","522,500 euros and 104,500 euros"],"correct_index":0,"explanation":"Release the opening profit net of tax, 40,000 × 75% = 30,000, and remove the closing profit net of tax, 70,000 × 75% = 52,500. Adjusted profit is 500,000 + 30,000 - 52,500 = 477,500, and the NCI takes 20% = 95,500."},{"id":"cr-s29-level3-v1-q2","session":"29","level":3,"topic":"PPE second year current versus cumulative","question":"A parent transferred machinery to its subsidiary at the start of last year. The internal gain was 150,000 euros and the remaining life five years, straight line, with no residual value. There is no disposal or impairment and tax is ignored. At the end of the second year, what PPE reduction and current year profit adjustment follow?","choices":["PPE reduction 150,000 and current profit increase 60,000","PPE reduction 90,000 and current profit increase 30,000 euros","PPE reduction 120,000 and current profit reduction 120,000","PPE reduction 90,000 and current profit reduction 90,000"],"correct_index":1,"explanation":"Excess annual depreciation is 150,000 / 5 = 30,000. Two years have realised 60,000 of the internal gain, leaving 90,000 to remove from PPE. This year's adjustment reverses only this year's excess depreciation, increasing current profit by 30,000."},{"id":"cr-s29-level3-v1-q3","session":"29","level":3,"topic":"Upstream PPE and NCI","question":"An 80% owned subsidiary sells machinery to its parent on the first day of the year. The internal gain is 100,000 euros and the remaining life four years, straight line. Subsidiary after tax book profit is 300,000. The tax effect of the net unrealised gain is 25% and is attributed with that gain to the subsidiary. What NCI profit follows? Residual value is zero.","choices":["60,000 euros","41,250 euros","48,750 euros","45,000 euros"],"correct_index":2,"explanation":"Reverse the gain of 100,000 and the excess depreciation of 25,000, a net reduction of 75,000 before tax, or 56,250 after 25% tax. Adjusted subsidiary profit is 300,000 - 56,250 = 243,750, and the NCI takes 20% = 48,750."},{"id":"cr-s29-level3-v1-q4","session":"29","level":3,"topic":"Downstream inventory plus upstream profit","question":"A parent owns 75% of a subsidiary. Subsidiary after tax profit is 600,000 euros. Upstream unrealised inventory profit is 80,000 and downstream unrealised profit is 120,000, each with a 25% tax benefit on elimination. There is no other adjustment. What NCI profit follows?","choices":["112,500 euros","150,000 euros","100,000 euros","135,000 euros"],"correct_index":3,"explanation":"Only the upstream adjustment reduces this subsidiary's profit for the NCI. Adjusted profit is 600,000 - 80,000 × 75% = 540,000, and the NCI takes 25% = 135,000. The downstream charge falls wholly on the group."},{"id":"cr-s29-level3-v1-q5","session":"29","level":3,"topic":"Acquisition uplift and upstream margin","question":"A parent owns 80%. Subsidiary after tax book profit is 450,000 euros. The acquisition PPE uplift adds 50,000 of depreciation and reverses 10,000 of deferred tax liability. The upstream closing profit elimination is 30,000 with a 6,000 deferred tax benefit. There are no other changes. What NCI profit follows?","choices":["77,200 euros","74,000 euros","90,000 euros","82,000 euros"],"correct_index":0,"explanation":"Adjusted subsidiary profit is 450,000 - 50,000 + 10,000 - 30,000 + 6,000 = 386,000, and the NCI takes 20% = 77,200."},{"id":"cr-s29-level3-v1-q6","session":"29","level":3,"topic":"Unrealised loss partly genuine","question":"Group inventory cost is 200,000 euros. The parent transfers all of it to the subsidiary for 150,000. All is unsold and year end net realisable value is 180,000. The buyer still carries 150,000 and tax is ignored. What consolidation adjustment and final group value follow?","choices":["Reduce by 20,000, to 130,000","Increase by 30,000, to 180,000","Increase by 50,000, to 200,000","No adjustment, leaving 150,000"],"correct_index":1,"explanation":"Only the artificial part of the internal loss is reversed. The group's correct measurement is the lower of original cost of 200,000 and net realisable value of 180,000. The buyer's 150,000 is increased by 30,000, retaining a genuine 20,000 loss."},{"id":"cr-s29-level3-v1-q7","session":"29","level":3,"topic":"Different tax rate and explicit base","question":"Internal inventory profit of 50,000 euros remains unsold. The seller paid current tax at 30%. The buyer's tax base is 200,000, the consolidated carrying amount after elimination is 150,000 and the buyer's applicable future rate is 20%. The DTA criteria are met. What deferred tax asset is recognised from the inventory difference?","choices":["25,000 euros","Zero, because the seller has already paid tax","10,000 euros","15,000 euros"],"correct_index":2,"explanation":"The DTA is measured using the tax consequences of the buyer recovering the inventory: a deductible difference of 50,000 at the buyer's 20% rate gives 10,000. The seller's 30% rate is not the measurement basis."},{"id":"cr-s29-level3-v1-q8","session":"29","level":3,"topic":"Current profit bridge","question":"Combined after tax book profits are 1 million euros and include 60,000 of parent dividend income from the subsidiary. Opening internal inventory profit of 20,000 is realised externally this year and closing internal profit is 50,000. Tax on both inventory adjustments is 20%. There are no other adjustments. What consolidated current profit follows?","choices":["940,000 euros","910,000 euros","964,000 euros","916,000 euros"],"correct_index":3,"explanation":"Eliminate the internal dividend income of 60,000, add the opening profit net of tax, 20,000 × 80% = 16,000, and remove the closing profit net of tax, 50,000 × 80% = 40,000: 1,000,000 - 60,000 + 16,000 - 40,000 = 916,000."},{"id":"cr-s29-level3-v1-q9","session":"29","level":3,"topic":"PPE tax base and closing DTA","question":"At the start of the year machinery carried at 400,000 euros is transferred internally for 600,000. The remaining life is five years, straight line. The buyer's tax base follows its transfer price and depreciation. The applicable tax rate is 25% and the DTA criteria are met. What closing group carrying amount and DTA follow? Residual value is zero.","choices":["320,000 euros and 40,000 euros","480,000 euros and 50,000 euros","320,000 euros and 50,000 euros","400,000 euros and 20,000 euros"],"correct_index":0,"explanation":"Group depreciation is 400,000 / 5 = 80,000, leaving a carrying amount of 320,000. The buyer's tax base is 600,000 - 120,000 = 480,000. The deductible difference of 160,000 gives a DTA of 25% × 160,000 = 40,000."},{"id":"cr-s29-level3-v1-q10","session":"29","level":3,"topic":"NCI with opening elimination and distributions","question":"Opening reported NCI of 220,000 euros already reflects last year's upstream profit elimination. Subsidiary book profit is 200,000. Prior unrealised profit of 40,000 is fully realised this year, new closing unrealised profit is 60,000, and both carry tax at 25%. The NCI is 20% and total dividends are 50,000. There are no other changes. What closing NCI follows?","choices":["250,000 euros","247,000 euros","257,000 euros","240,000 euros"],"correct_index":1,"explanation":"Adjusted current profit is 200,000 + 40,000 × 75% - 60,000 × 75% = 185,000, so the NCI profit share is 37,000. From the opening 220,000, add 37,000 and subtract the NCI dividend of 20% × 50,000 = 10,000: 247,000."}],"30":[{"id":"cr-s30-level1-v1-q1","session":"30","level":1,"topic":"Business before outputs","question":"A purchased research set includes specialised inputs and a skilled organised workforce whose substantive processes can develop outputs, but it has not begun selling. Does zero current revenue by itself mean the set is not a business?","choices":["It excludes a business unless the workforce is separately recognised as an intangible","It establishes a business whenever the assets are acquired through a legal company","It does not by itself exclude a business when the required inputs and substantive processes exist","It excludes a business until the research operation earns its first customer revenue"],"correct_index":2,"explanation":"A business can exist before outputs begin. Inputs and a substantive process are what matter. Legal form and revenue alone are not decisive."},{"id":"cr-s30-level1-v1-q2","session":"30","level":1,"topic":"Concentration test direction","question":"An acquirer elects the IFRS 3 concentration test. Substantially all the fair value of the gross assets is concentrated in one identifiable asset under that test. What conclusion follows?","choices":["The set qualifies as a business because one dominant asset determines its activity","The set qualifies as a business if the asset is held in a separate legal company","The set requires the full business definition assessment because passing the test is inconclusive","The set is not a business under the elected test"],"correct_index":3,"explanation":"Passing the concentration test establishes that the set is not a business. Failing it would require further assessment, not automatically establish a business."},{"id":"cr-s30-level1-v1-q3","session":"30","level":1,"topic":"Control date versus settlement","question":"A business purchase is signed on 2 May. Control transfers on 15 May under enforceable terms. Cash settles on 30 May and no earlier power exists. Which date measures the consideration and the identifiable acquisition balances?","choices":["15 May","2 May","30 May","The next reporting date"],"correct_index":0,"explanation":"The acquisition date is the date control is obtained, here 15 May. Signing and cash settlement need not coincide with it."},{"id":"cr-s30-level1-v1-q4","session":"30","level":1,"topic":"Share consideration measurement","question":"To buy a business an acquirer issues 100,000 shares valued at 12 euros each on the control date. Advice costs are 20,000 and share issuance costs 30,000. How much of the price is share consideration?","choices":["1,220,000 euros","1,200,000 euros","1,250,000 euros","1,170,000 euros"],"correct_index":1,"explanation":"Consideration is the acquisition date fair value of the shares issued: 100,000 × 12 = 1,200,000. Share issue costs and advisory fees have their own accounting and are never added to consideration."},{"id":"cr-s30-level1-v1-q5","session":"30","level":1,"topic":"Acquisition related advice","question":"A business buyer pays external advisers 90,000 euros for due diligence services received in the current period. The fee is not a debt or equity issuance cost and not consideration to the seller. How is it normally treated?","choices":["Deduct 90,000 from the acquiree's identifiable assets","Recognise 90,000 as an indefinite life intangible","Expense 90,000 in the period the services are received","Add 90,000 to goodwill as consideration"],"correct_index":2,"explanation":"Acquisition related services are expensed under IFRS 3. Only costs of issuing debt or equity follow their own standards, and advice is neither."},{"id":"cr-s30-level1-v1-q6","session":"30","level":1,"topic":"Identifiable acquired intangible","question":"An acquiree has an unrecognised customer contract asset which meets the contractual legal identifiability criterion. Its reliable acquisition date fair value is 180,000 euros and the IFRS 3 recognition requirements are met. What treatment follows?","choices":["Include it in goodwill because it was not recognised in the acquiree's accounts","Recognise only externally purchased portions, carrying forward the internal origin restrictions","Expense 180,000, applying internal development restrictions to the acquisition recognition","Recognise the identifiable intangible separately from goodwill"],"correct_index":3,"explanation":"Acquisition accounting can recognise identifiable assets that were absent from the acquiree's own books. The contractual legal criterion supports separate recognition here."},{"id":"cr-s30-level1-v1-q7","session":"30","level":1,"topic":"Contingent liability threshold","question":"An acquiree faces a lawsuit. A present obligation exists from a past event and the acquisition date fair value is reliably measurable at 70,000 euros. An outflow is not probable. What does IFRS 3 require at acquisition for this contingent liability?","choices":["Recognise 70,000 despite the absence of a probable outflow","No recognition, applying the IAS 37 probable outflow threshold at acquisition","Recognise the maximum claim rather than its reliably measurable acquisition fair value","Recognise 70,000 as a reduction of goodwill rather than a liability increasing it"],"correct_index":0,"explanation":"The IFRS 3 rule requires recognition of a present obligation with a reliably measurable fair value even when an outflow is not probable, which overrides the IAS 37 threshold at acquisition."},{"id":"cr-s30-level1-v1-q8","session":"30","level":1,"topic":"Partial goodwill numerical","question":"An acquirer pays 1 million euros for 75% of a business. Identifiable net assets at acquisition are 1.1 million. The NCI is measured at its proportionate share and no previous interest exists. What goodwill follows?","choices":["275,000 euros","175,000 euros","100,000 euros bargain gain","450,000 euros"],"correct_index":1,"explanation":"The acquirer's share of net assets is 75% × 1.1 million = 825,000, so partial goodwill is 1 million - 825,000 = 175,000."},{"id":"cr-s30-level1-v1-q9","session":"30","level":1,"topic":"Bargain gain after reassessment","question":"For a 100% business purchase, consideration is 900,000 euros and identifiable net assets are 1 million. The required reassessment confirms all recognition and measurement. What is recognised?","choices":["100,000 euros goodwill asset","A 100,000 direct credit to share capital","100,000 euros gain in profit or loss","100,000 euros negative goodwill liability"],"correct_index":2,"explanation":"A confirmed bargain purchase gain of 1 million - 900,000 = 100,000 is recognised in profit or loss after reassessment, not carried as negative goodwill."},{"id":"cr-s30-level1-v1-q10","session":"30","level":1,"topic":"Liability versus equity earnout","question":"An acquisition earnout is classified as equity at acquisition with a fair value of 120,000 euros. A later performance forecast implies a value of 170,000. No measurement period adjustment applies. What subsequent entry follows for that equity classified consideration?","choices":["Expense 50,000 and increase a liability by 50,000","Increase goodwill and the equity reserve by 50,000","Recognise a 50,000 OCI gain and increase the equity reserve","No subsequent remeasurement entry for the equity classified consideration"],"correct_index":3,"explanation":"Equity classified contingent consideration is not remeasured after acquisition. Later settlement stays within equity. Liability classification would produce a different subsequent result."},{"id":"cr-s30-level2-v1-q1","session":"30","level":2,"topic":"Deferred cash and unwind","question":"For a business acquisition, cash of 800,000 euros is paid immediately and another 242,000 is due after two years. Discounting is material and the annual rate is 10%. What acquisition consideration and first year unwind expense arise?","choices":["1,042,000 consideration and zero financing expense","1 million consideration and 42,000 first year financing expense","800,000 consideration and 242,000 first year financing expense","1 million euros consideration and 20,000 euros financing expense"],"correct_index":3,"explanation":"The present value of the deferred cash is 242,000 / 1.1² = 200,000, so total consideration is 1 million. The first year unwind is 10% × 200,000 = 20,000."},{"id":"cr-s30-level2-v1-q2","session":"30","level":2,"topic":"Net assets intangible tax effect","question":"Book net assets are 2 million euros. A newly recognised customer contract is valued at 400,000 with a tax base of zero, and the tax rate is 25%. All DTL conditions are met and no other adjustment exists. What identifiable net assets enter the goodwill calculation?","choices":["2.3 million euros","2.4 million euros","2.1 million euros","1.7 million euros"],"correct_index":0,"explanation":"Add the 400,000 asset and deduct the DTL of 25% × 400,000 = 100,000. The net increase is 300,000, giving 2.3 million."},{"id":"cr-s30-level2-v1-q3","session":"30","level":2,"topic":"Mixed consideration and costs","question":"A buyer pays cash of 1.5 million euros, issues shares worth 600,000, and recognises a liability earnout at a fair value of 200,000. It also incurs 80,000 of advisory expense and 30,000 of equity issuance costs. What consideration enters the acquisition accounting?","choices":["2.27 million euros","2.3 million euros","2.41 million euros","2.38 million euros"],"correct_index":1,"explanation":"Cash, shares and the acquisition date earnout total 1.5 million + 600,000 + 200,000 = 2.3 million. Advisory costs and share issuance costs do not change the consideration transferred."},{"id":"cr-s30-level2-v1-q4","session":"30","level":2,"topic":"Liability earnout later change","question":"A cash earnout recorded at 150,000 euros on acquisition is valued at 210,000 six months later because the new business traded better after acquisition. No acquisition date fact has changed. Where does the 60,000 increase go?","choices":["60,000 credit directly to parent equity","No entry until cash payment","60,000 expense in profit or loss, not an automatic goodwill increase","60,000 increase in goodwill because the change is within one year"],"correct_index":2,"explanation":"Liability classified contingent consideration is remeasured through profit or loss. The measurement period is not a blanket permission to put all first year changes into goodwill."},{"id":"cr-s30-level2-v1-q5","session":"30","level":2,"topic":"Measurement period fact","question":"A buyer provisionally measures acquired land at 500,000 euros. Within the permitted measurement period, new evidence about conditions existing at acquisition establishes a fair value of 560,000. There is no tax or other effect and ownership is 100%. What adjustment follows?","choices":["Increase land 60,000 with a current profit gain of 60,000","Leave the provisional acquisition amounts unchanged and disclose the revised fair value","Increase land and goodwill 60,000 each, reversing the residual allocation effect","Increase land 60,000 and reduce goodwill 60,000 retrospectively"],"correct_index":3,"explanation":"A qualifying measurement period adjustment revises the provisional acquisition accounting for acquisition date facts. More net assets mean less goodwill, absent other effects."},{"id":"cr-s30-level2-v1-q6","session":"30","level":2,"topic":"Step acquisition gain","question":"A previously held associate interest has a carrying amount of 300,000 euros and a fair value of 450,000 when control of the business is obtained. There is no OCI balance and no other adjustment. What remeasurement result arises?","choices":["A 150,000 gain in profit or loss","150,000 of new goodwill and no gain","A 450,000 gain in profit or loss","No remeasurement, as the investor already held shares"],"correct_index":0,"explanation":"On obtaining control, the prior interest is remeasured to its acquisition date fair value. The gain is 450,000 - 300,000 = 150,000 in profit or loss."},{"id":"cr-s30-level2-v1-q7","session":"30","level":2,"topic":"Full goodwill with prior interest","question":"A buyer pays 1.2 million euros for an additional stake that gives it control. Its previous interest has a fair value of 400,000, the NCI fair value is 300,000 and identifiable net assets are 1.5 million. What full goodwill follows?","choices":["700,000 euros","400,000 euros","Zero","100,000 euros"],"correct_index":1,"explanation":"Goodwill is the new consideration of 1.2 million plus the previous interest of 400,000 plus the NCI of 300,000, less identifiable net assets of 1.5 million: 400,000."},{"id":"cr-s30-level2-v1-q8","session":"30","level":2,"topic":"Common control boundary","question":"The same ultimate parent controls each of two businesses continuously before and after their transfer, with no transitory control arrangement. Is IFRS 3 acquisition accounting within scope for this common control combination?","choices":["It remains within IFRS 3 because the receiving entity obtains a business for cash","It remains within IFRS 3 because legal ownership changes despite unchanged ultimate control","The combination is outside the scope of IFRS 3 as a common control combination","It is outside IFRS 3 only if no consideration is paid between the group entities"],"correct_index":2,"explanation":"Business combinations under common control are outside IFRS 3. Being outside that standard does not mean the entity records nothing. It means another basis applies."},{"id":"cr-s30-level2-v1-q9","session":"30","level":2,"topic":"NCI measurement choice scope","question":"At acquisition an ordinary outside ownership interest entitles its holder to a proportionate liquidation share of net assets. What IFRS 3 choice exists for measuring this NCI?","choices":["Fair value for every combination, with no alternative","Proportionate identifiable net assets for every combination, with no alternative","Either fair value or proportionate net assets under one permanent group policy","Either fair value or proportionate net assets, selected for each combination"],"correct_index":3,"explanation":"For a present ownership interest of this kind, IFRS 3 allows fair value or the proportionate share, chosen combination by combination. It is not an unrestricted policy for all possible instruments."},{"id":"cr-s30-level2-v1-q10","session":"30","level":2,"topic":"Control retained additional stake","question":"A parent controls 80% and buys another 5% for 140,000 euros. The NCI carrying amount decreases by 110,000. There is no tax and no costs. What consolidated effect follows?","choices":["Parent equity decreases 30,000 and goodwill stays unchanged","Goodwill increases 30,000, parent equity unchanged","An acquisition expense of 30,000 enters profit, goodwill unchanged","Subsidiary assets are remeasured for the additional 5%, treating it as a new control acquisition"],"correct_index":0,"explanation":"Acquiring NCI while retaining control is an equity transaction. The 30,000 excess of the price over the NCI reduction is charged to parent equity, not to new goodwill."},{"id":"cr-s30-level3-v1-q1","session":"30","level":3,"topic":"Integrated deferred and contingent price","question":"A parent acquires 80% of a business. Cash paid now is 1.1 million euros, a payment due in two years has a present value of 200,000, and a liability earnout has a fair value of 150,000. Net assets before an intangible adjustment are 1.4 million. A recognised intangible of 300,000 has a zero tax base and the tax rate is 25%. The NCI is proportionate. What acquisition consideration and goodwill follow?","choices":["1.45 million euros and 150,000 euros","1.45 million euros and 90,000 euros","1.3 million euros and zero goodwill","1.45 million euros and 225,000 euros"],"correct_index":0,"explanation":"Consideration is 1.1 million + 200,000 + 150,000 = 1.45 million. Net assets are 1.4 million + 300,000 - 75,000 DTL = 1.625 million, the parent's 80% share is 1.3 million and goodwill is 1.45 million - 1.3 million = 150,000."},{"id":"cr-s30-level3-v1-q2","session":"30","level":3,"topic":"Step acquisition full bridge","question":"An investor previously holds 30% with a carrying amount of 360,000 euros and a fair value of 500,000. It pays 900,000 for another 50% and obtains control of a business. The remaining 20% NCI has a fair value of 330,000 and identifiable net assets are 1.5 million. There is no OCI and no other effect. What remeasurement gain and goodwill follow?","choices":["Gain 500,000 and goodwill 400,000 euros","Gain 140,000 and goodwill 230,000 euros","Gain 140,000 and goodwill 90,000 euros","Gain zero and goodwill 230,000 euros"],"correct_index":1,"explanation":"The prior interest gain is 500,000 - 360,000 = 140,000. Goodwill is 900,000 + 500,000 + 330,000 - 1.5 million = 230,000."},{"id":"cr-s30-level3-v1-q3","session":"30","level":3,"topic":"Provisional depreciable uplift correction","question":"A 100% acquisition occurs at the start of the year. The provisional acquired PPE fair value is 100,000 euros too low, identified after six months using new evidence about acquisition date facts within the measurement period. The remaining life at acquisition is five years, straight line, with zero tax. What correction after six months follows?","choices":["PPE and goodwill unchanged, profit up 100,000 with no depreciation","PPE up 100,000, goodwill unchanged, no catch up depreciation","PPE up 100,000, goodwill down 100,000, catch up depreciation 10,000","PPE up 100,000, goodwill up 100,000, no catch up depreciation"],"correct_index":2,"explanation":"The acquisition PPE and goodwill are corrected retrospectively by 100,000. Six months of additional depreciation is 100,000 / 5 × 1/2 = 10,000, so net PPE rises by 90,000."},{"id":"cr-s30-level3-v1-q4","session":"30","level":3,"topic":"Measurement period versus later events","question":"A cash earnout liability initially recognised at 100,000 euros is revised upward by 40,000. Of this, 15,000 comes from new information about facts and circumstances that existed at the acquisition date, identified within the measurement period, and 25,000 from unexpected post acquisition sales. There is no tax and ownership is 100%. What goodwill and profit effects follow?","choices":["Goodwill up 40,000 and profit unchanged","Goodwill unchanged and profit down 40,000","Goodwill down 15,000 and profit up 25,000","Goodwill up 15,000 and profit down 25,000"],"correct_index":3,"explanation":"Only the acquisition date evidence revises the acquisition consideration and goodwill, up 15,000. The post acquisition performance remeasures the liability through profit or loss, a 25,000 expense."},{"id":"cr-s30-level3-v1-q5","session":"30","level":3,"topic":"Contingent liability effect on goodwill","question":"A buyer acquires 75% for 1.2 million euros. Identifiable net assets before an acquisition related contingent liability are 1.4 million. The contingent liability is a present obligation whose fair value is reliably measurable at 100,000, with no tax effect. The NCI is proportionate. What goodwill follows, and what increase does recognising that liability cause?","choices":["225,000 goodwill and a 75,000 increase","150,000 goodwill and zero increase","250,000 goodwill and a 100,000 increase","225,000 goodwill and a 100,000 increase"],"correct_index":0,"explanation":"The liability reduces net assets to 1.3 million, the parent's 75% share is 975,000 and goodwill is 1.2 million - 975,000 = 225,000. Without the liability goodwill would be 150,000, so the increase is the parent's 75% × 100,000 = 75,000."},{"id":"cr-s30-level3-v1-q6","session":"30","level":3,"topic":"Separate transactions employee remuneration","question":"A business buyer pays the former owners 2 million euros at acquisition. It also promises 300,000 only if they remain employees for two years. The arrangement is stipulated to be remuneration for future services, not acquisition consideration. Identifiable net assets are 1.7 million and ownership is 100%. What goodwill follows?","choices":["1.7 million, treating identifiable net assets as the residual goodwill","300,000 euros, excluding the service remuneration","600,000, adding the future service remuneration to the acquisition consideration","Zero, treating payments to owners who become employees as entirely remuneration"],"correct_index":1,"explanation":"Only the 2 million of acquisition consideration enters goodwill: 2 million - 1.7 million = 300,000. The separately assessed service remuneration is accounted for over the service period under the applicable requirements."},{"id":"cr-s30-level3-v1-q7","session":"30","level":3,"topic":"Deferred price final year liability","question":"Deferred fixed acquisition consideration is initially recognised at 300,000 euros. The annual effective rate is 10%, cash settlement is at the end of year two and no other changes occur. What liability immediately before payment and cumulative financing expense follow?","choices":["330,000 liability and 30,000 expense","300,000 liability and zero expense","363,000 liability and 63,000 expense","360,000 liability and 60,000 expense"],"correct_index":2,"explanation":"The unwind compounds: end of year one is 300,000 × 1.1 = 330,000, and year two adds 33,000. The liability reaches 363,000 and cumulative financing expense is 63,000, with no remeasurement of goodwill for the unwind."},{"id":"cr-s30-level3-v1-q8","session":"30","level":3,"topic":"Acquisition gain and fees separated","question":"A 100% business acquisition has cash consideration of 850,000 euros and confirmed identifiable net assets of 1 million after the required reassessment. Advisory fees of 40,000 are current expenses. There is no tax and no other effect. What bargain gain and net current profit effect of these two items follow?","choices":["Bargain gain 110,000 and net profit increase 110,000","Goodwill 40,000 and net profit increase 150,000","Bargain gain 150,000 and net profit increase 190,000","Bargain gain 150,000 and net profit increase 110,000"],"correct_index":3,"explanation":"The bargain gain is measured from consideration and net assets: 1 million - 850,000 = 150,000. The advisory fees are a separate 40,000 expense, leaving a net profit increase of 110,000."},{"id":"cr-s30-level3-v1-q9","session":"30","level":3,"topic":"Full versus partial with tax uplift","question":"A parent pays 1.8 million euros for 80%. Book net assets are 1.6 million and the acquisition asset uplift is 500,000 with a zero tax base, tax 20%. The NCI fair value is 460,000 and there is no prior interest. What partial and full goodwill follow?","choices":["Partial 200,000 and full 260,000 euros","Partial 120,000 and full 160,000 euros","Partial 200,000 and full 360,000 euros","Partial 260,000 and full 200,000 euros"],"correct_index":0,"explanation":"Adjusted net assets are 1.6 million + 500,000 - 100,000 DTL = 2 million. Partial goodwill is 1.8 million - 80% × 2 million = 200,000. Full goodwill is 1.8 million + 460,000 - 2 million = 260,000."},{"id":"cr-s30-level3-v1-q10","session":"30","level":3,"topic":"Legal form and accounting acquirer","question":"Legal entity A issues shares to acquire B. Former B owners obtain 72% of the voting rights in the combined group, B's management directs the relevant activities and no other party has overriding rights. The transaction meets the supplied reverse acquisition criteria. Which statement is correct?","choices":["A is the acquirer, because issuing the consideration shares determines the accounting acquirer","B is the accounting acquirer even though A is the legal acquirer","A is the acquirer, because the legal parent controls the consolidated reporting name after the exchange","B is the acquirer only after legally merging into A, not when the reverse acquisition criteria are first met"],"correct_index":1,"explanation":"Accounting follows which entity obtains control in substance. A reverse acquisition can have a legal subsidiary as the accounting acquirer. Share issuance alone does not settle that question."}],"31":[{"id":"cr-s31-level1-v1-q1","session":"31","level":1,"topic":"Relevant activities in a lender case","question":"A owns 58% of a manufacturer, appoints the majority deciding production, prices and sales, and can use that power to affect its variable returns. A lender can block only liquidation and breaches of protective covenants. Does that lender protection prevent A from controlling?","choices":["Joint control with the lender, because liquidation and covenant vetoes require consent","Proportionate consolidation of 58%, retaining the outside holders' portion outside the group","A controls the manufacturer despite those protective lender rights","Lender control, treating protective vetoes as power over production and pricing"],"correct_index":2,"explanation":"A has power over the relevant activities, returns and the link between them. The stipulated protective lender rights do not remove that power. Consolidation is in full once control exists."},{"id":"cr-s31-level1-v1-q2","session":"31","level":1,"topic":"Contractual power with minority votes","question":"Investor A owns 35% of the ordinary votes. An enforceable agreement gives A the sole substantive right to direct the activities that most significantly affect returns. No other party can override that right. A has variable returns and can use its power to affect them. What conclusion follows?","choices":["A has significant influence only, because holding under half the votes decides the outcome","A has joint control with the other holders, because minority ownership implies shared consent","A has no control until it uses its right in an actual decision","A controls, because the substantive right outweighs owning less than half the votes"],"correct_index":3,"explanation":"IFRS 10 control can arise through substantive contractual rights. The facts explicitly supply power, returns and the ability to affect returns."},{"id":"cr-s31-level1-v1-q3","session":"31","level":1,"topic":"Returns without decision power","question":"A fund owns 45% and receives dividends and value changes. An independent party controls the relevant decisions and the fund cannot direct or override them. Which assessment follows?","choices":["The fund has variable returns but lacks the power needed for control","The fund controls because its returns depend on the investee's performance","The fund shares joint control because it participates in the returns","The fund lacks variable returns because another party makes the operating decisions"],"correct_index":0,"explanation":"Economic exposure is only one element of control. Without power and the ability to use it, the fund does not control on the stated facts."},{"id":"cr-s31-level1-v1-q4","session":"31","level":1,"topic":"Separate legal existence","question":"A controlled operating business remains a distinct legal entity with its own name, employees and bank accounts. The parent owns 90%, with no investment entity exception or reporting exemption. How should the group include it?","choices":["Dividend income only, because the subsidiary keeps its separate legal identity","Full consolidation, because control matters rather than legal separateness","Consolidation only after a legal merger combines bank accounts and staff","90% of assets and liabilities, in proportion to the ownership interest"],"correct_index":1,"explanation":"Consolidation presents the controlled group as one economic entity. Legal separation does not prevent it, and the NCI is presented separately."},{"id":"cr-s31-level1-v1-q5","session":"31","level":1,"topic":"Control and acquisition date","question":"A buyer contracts for 70% on 4 September and pays a refundable deposit on 6 September. It obtains substantive direction rights and variable returns on 18 September. Which event starts its acquisition accounting?","choices":["6 September","The first annual reporting date after September","18 September","4 September"],"correct_index":2,"explanation":"Control triggers acquisition accounting and consolidation, here on 18 September. Neither signing nor paying a refundable deposit alone establishes the acquisition date."},{"id":"cr-s31-level1-v1-q6","session":"31","level":1,"topic":"Fair value asset omitted from books","question":"An acquirer pays 2.4 million euros for 100% of a business. Book net assets are 1.8 million. An unrecorded patent has a reliably measurable fair value of 300,000, with no tax effects or other adjustments. What goodwill follows?","choices":["600,000, using book net assets without the patent","900,000, subtracting the patent from book net assets","Zero, assigning all the excess to the patent","300,000, consideration less net assets including the patent"],"correct_index":3,"explanation":"Identifiable net assets rise to 1.8 million + 300,000 = 2.1 million. Goodwill is 2.4 million - 2.1 million = 300,000."},{"id":"cr-s31-level1-v1-q7","session":"31","level":1,"topic":"Ordinary NCI versus debt","question":"A parent acquires 80% of a business. The ordinary NCI holds proportionate residual rights with no redemption obligation. How is that NCI presented on consolidation?","choices":["Within equity, separately from equity attributable to the parent's owners","Within financial liabilities, because outside holders may receive distributions","As a deduction from investment cost, leaving only parent owned net assets","As a separate asset, representing the outside shareholders' funding contribution"],"correct_index":0,"explanation":"Ordinary residual ownership NCI is equity, not a liability or an expense. It is presented within equity, separate from the parent owners' share."},{"id":"cr-s31-level1-v1-q8","session":"31","level":1,"topic":"Acquirer identification beyond payment","question":"B is the accounting acquirer in a reverse acquisition because its former owners control the combined group, although A legally acquired B by issuing shares. Which listed fact can still be true without contradicting that conclusion?","choices":["A holds overriding substantive rights to direct the combined relevant activities","A remains the legal issuer of the acquisition shares","A retains unilateral direction of all relevant activities despite B's voting rights","B's former owners lack substantive voting or governance rights in the combined business"],"correct_index":1,"explanation":"The legal issuer need not be the accounting acquirer in a reverse acquisition. Accounting follows control rather than the share issuance form alone."},{"id":"cr-s31-level1-v1-q9","session":"31","level":1,"topic":"Acquisition costs versus price","question":"A buyer acquires a business for 1.6 million euros and incurs separate due diligence expense of 60,000. Net identifiable assets are 1.3 million and ownership is 100%. There is no tax and no other item. What goodwill and current advice expense follow?","choices":["Goodwill 240,000 and expense 60,000","Goodwill 300,000 and expense zero","Goodwill 300,000 and expense 60,000 euros","Goodwill 360,000 and expense zero"],"correct_index":2,"explanation":"Goodwill is 1.6 million - 1.3 million = 300,000. The separate advisory service is expensed. It increases neither the consideration transferred nor goodwill."},{"id":"cr-s31-level1-v1-q10","session":"31","level":1,"topic":"Control reassessment","question":"A parent's contractual direction rights are removed by an enforceable amendment. Another party now directs all the relevant activities. The parent retains returns exposure but no power and no power returns link. What reporting consequence follows?","choices":["Continue consolidation until the parent disposes of its retained economic interest","Continue consolidation because control at acquisition determines the ongoing boundary","Continue consolidation because variable returns are sufficient without current power","Cease full consolidation from the date control is lost and account for that loss"],"correct_index":3,"explanation":"IFRS 10 requires reassessment when facts change. Retaining economic exposure is insufficient when the supplied amendment removes power and its link to returns."},{"id":"cr-s31-level2-v1-q1","session":"31","level":2,"topic":"Quorum as real shared decision right","question":"A appoints three of five directors, but a binding agreement requires both A and B to approve every decision about the relevant activities. Both rights are substantive. Which conclusion follows?","choices":["A has sole control because it appoints a board majority","B has sole control because its consent can block the board majority","Neither can share control because their board appointments are unequal","A and B share joint control because neither can direct the relevant activities alone"],"correct_index":3,"explanation":"A board majority does not override a substantive contractual requirement for both parties to consent to the relevant decisions. The specified unanimous sharing supports joint control."},{"id":"cr-s31-level2-v1-q2","session":"31","level":2,"topic":"Quorum bypass and current ability","question":"A appoints four of seven directors. B's presence is needed at a first meeting, but if B is absent a binding reconvened meeting occurs within two days where A's directors can decide all relevant activities alone. No other barriers exist. What does that quorum structure imply?","choices":["B's temporary attendance requirement does not prevent A's substantive direction power","B shares joint control because its attendance is required at the first meeting","A obtains power only after B chooses to attend an actual meeting","B has sole power because its first absence triggers the reconvened meeting"],"correct_index":0,"explanation":"The substantive effect of quorum arrangements is what matters. The supplied prompt reconvening mechanism lets A decide the relevant activities without B, unlike an unavoidable mutual consent rule."},{"id":"cr-s31-level2-v1-q3","session":"31","level":2,"topic":"Financing veto relevant in context","question":"A owns 60% of a project company and appoints a board majority. A and B must both approve the monthly selection of projects and their funding, and those recurring decisions most affect returns. Decisions on routine staff and procurement remain with A. Both consent rights are substantive. Which governance feature determines control?","choices":["B controls because its funding consent can prevent the company from undertaking new projects","A and B share joint control because the decisions most affecting returns require both to consent","A controls because staffing and procurement are recurring operating decisions directed by its board majority","A controls because B approves funding only alongside project selection, rather than directing the project company independently"],"correct_index":1,"explanation":"The relevant activities on these facts are the recurring project selection and funding, not the routine operating decisions retained by A. The agreement requires both parties to consent to those relevant activities, so neither directs them unilaterally. B does not gain sole control merely because it can block."},{"id":"cr-s31-level2-v1-q4","session":"31","level":2,"topic":"Integrated PPA tax","question":"A buys 80% for 3 million euros. Book net assets are 2.5 million, a recognised technology uplift of 800,000 has a tax base of zero and the tax rate is 25%, and a reliably measurable present obligation of 100,000 has no tax effect. The NCI is proportionate. What net assets and goodwill follow?","choices":["Net assets 3 million and goodwill zero","Net assets 3.4 million and goodwill 280,000","Net assets 3 million and goodwill 600,000 euros","Net assets 3.2 million and goodwill 440,000"],"correct_index":2,"explanation":"The technology adds 800,000, the DTL subtracts 200,000 and the liability subtracts 100,000, giving net assets of 3 million. The parent's 80% share is 2.4 million, so goodwill is 3 million - 2.4 million = 600,000."},{"id":"cr-s31-level2-v1-q5","session":"31","level":2,"topic":"NCI full versus partial original case","question":"A pays 2.7 million euros for 75% of a business. Identifiable net assets are 3 million and the NCI fair value is 900,000. What goodwill arises using proportionate NCI versus fair value NCI?","choices":["600,000 partial and 450,000 full","Zero partial and 600,000 full","450,000 partial and 900,000 full","450,000 partial and 600,000 full"],"correct_index":3,"explanation":"Proportionate NCI is 25% × 3 million = 750,000, so partial goodwill is 2.7 million + 750,000 - 3 million = 450,000. Substituting the NCI fair value of 900,000 gives full goodwill of 2.7 million + 900,000 - 3 million = 600,000."},{"id":"cr-s31-level2-v1-q6","session":"31","level":2,"topic":"Post acquisition earnings with uplift","question":"A acquires 80% at the start of the year. Subsidiary after tax book profit is 500,000 euros. An acquisition technology uplift of 600,000 has a six year remaining life, straight line, with DTL reversal at 25%. There are no other changes. What parent and NCI shares of adjusted profit follow?","choices":["Parent 340,000 and NCI 85,000 euros","Parent 400,000 and NCI 100,000","Parent 320,000 and NCI 80,000","Parent 360,000 and NCI 90,000"],"correct_index":0,"explanation":"Additional amortisation is 600,000 / 6 = 100,000 and the tax benefit is 25,000, so adjusted profit is 500,000 - 100,000 + 25,000 = 425,000. The parent takes 80% = 340,000 and the NCI 20% = 85,000."},{"id":"cr-s31-level2-v1-q7","session":"31","level":2,"topic":"Earnout liability after acquisition","question":"A cash earnout is initially 250,000 euros. It rises to 340,000 because the acquiree wins new contracts after acquisition. No acquisition date evidence or measurement period adjustment exists, and there is no tax. What accounting follows?","choices":["No entry, until the maximum payout becomes certain","An expense of 90,000, with the liability up and goodwill unchanged","A goodwill increase of 90,000 and no expense","An equity decrease of 90,000 and the liability unchanged"],"correct_index":1,"explanation":"This is a subsequent remeasurement of liability classified consideration due to later performance, recognised in profit or loss. The facts exclude acquisition date corrections, so goodwill does not move."},{"id":"cr-s31-level2-v1-q8","session":"31","level":2,"topic":"Step acquisition original case","question":"A previously held 25% interest has a carrying amount of 400,000 euros and a fair value of 550,000 when control is obtained. A pays 1.65 million for another 50%. The remaining 25% NCI is measured at its proportionate share of net assets of 2.4 million. There is no OCI. What prior gain and goodwill follow?","choices":["Zero gain and 400,000 goodwill","550,000 gain and 600,000 goodwill","150,000 gain and 400,000 goodwill","150,000 gain and 250,000 goodwill"],"correct_index":2,"explanation":"The NCI is 25% × 2.4 million = 600,000. Goodwill is 1.65 million + 550,000 + 600,000 - 2.4 million = 400,000. The prior interest gain is 550,000 - 400,000 = 150,000."},{"id":"cr-s31-level2-v1-q9","session":"31","level":2,"topic":"Retained control disposal original case","question":"A parent reduces its ownership from 85% to 75% but retains control. Cash received is 500,000 euros and the required NCI carrying increase is 420,000. There is no tax and no costs. What consolidated result follows?","choices":["Recognise profit of 80,000 and remeasure goodwill","Recognise revenue of 500,000 and ignore the NCI","Recognise a loss of 420,000 and goodwill of 80,000","Parent equity up 80,000, with no profit or goodwill effect"],"correct_index":3,"explanation":"An ownership change without loss of control is an equity transaction. The cash exceeds the NCI increase by 80,000, which is credited to parent equity."},{"id":"cr-s31-level2-v1-q10","session":"31","level":2,"topic":"Acquisition obligation recognition","question":"A target lawsuit has two possible descriptions. Case A is a present obligation with a reliable fair value but an outflow that is not probable. Case B is only a possible obligation and no present obligation exists. Under the supplied IFRS 3 contingent liability facts, what is the correct distinction?","choices":["A may qualify at acquisition, B lacks the required present obligation","Neither qualifies, applying probable outflow as an acquisition recognition threshold","Both qualify, treating possible and present obligations as equivalent at acquisition","B qualifies because litigation exists, while A fails because outflow is not probable"],"correct_index":0,"explanation":"The IFRS 3 acquisition exception removes the probability threshold for a qualifying present obligation with a reliably measurable fair value. It does not turn a merely possible obligation into a present one."},{"id":"cr-s31-level3-v1-q1","session":"31","level":3,"topic":"Control before computing goodwill","question":"A buys 62% of a legal company for 4 million euros. A appoints a board majority, but the contract text omits whether another investor's mandatory presence can permanently block relevant decisions. The returns exposure is clear. Which conclusion is justified before computing consolidated goodwill?","choices":["Resolve whether the quorum right substantively prevents unilateral power","Conclude control from 62%, treating quorum terms as protective regardless of substance","Conclude joint control from the attendance clause, without assessing its blocking effect","Compute goodwill from the consideration first, assessing the governance rights afterward"],"correct_index":0,"explanation":"The missing substantive effect of the quorum rule is decisive. Neither majority ownership nor the mere existence of attendance language proves who can direct the relevant activities. Acquisition method calculations require a grounded control conclusion first."},{"id":"cr-s31-level3-v1-q2","session":"31","level":3,"topic":"Full PPA and first year NCI","question":"A obtains 80% control on the first day of the year for 4 million euros. Book net assets are 3.5 million. The technology uplift is 1 million with a zero tax base, the tax rate is 20% and the life is five years. An additional reliably measurable present obligation is 100,000 with no tax effect. The NCI is proportionate. Subsidiary after tax book profit is 600,000, with no other changes. What goodwill and closing NCI follow?","choices":["640,000 goodwill and 840,000 closing NCI","640,000 goodwill and 928,000 closing NCI","640,000 goodwill and 960,000 closing NCI","480,000 goodwill and 928,000 closing NCI"],"correct_index":1,"explanation":"Net assets are 3.5 million + 1 million - 200,000 DTL - 100,000 = 4.2 million, so goodwill is 4 million - 80% × 4.2 million = 640,000. Adjusted profit is 600,000 - 200,000 amortisation + 40,000 tax = 440,000. The NCI opens at 20% × 4.2 million = 840,000 and adds 88,000 of profit to close at 928,000."},{"id":"cr-s31-level3-v1-q3","session":"31","level":3,"topic":"Consideration and post purchase expense split","question":"For a 100% business acquisition, the cash price is 2 million euros, the deferred price present value is 300,000 and the liability earnout fair value is 200,000. Identifiable net assets are 2.2 million. During the first year, deferred interest is 30,000, the earnout increases 50,000 from later performance, and separate advisory expense is 40,000. There is no tax and no measurement period change. What goodwill and combined listed current expenses follow?","choices":["Goodwill 350,000 and expenses 70,000","Goodwill 300,000 and expenses 90,000","Goodwill 300,000 and expenses 120,000","Goodwill 420,000 and expenses zero"],"correct_index":2,"explanation":"Initial consideration is 2 million + 300,000 + 200,000 = 2.5 million, giving goodwill of 300,000. The subsequent financing of 30,000, earnout remeasurement of 50,000 and advice of 40,000 are separate expenses totalling 120,000."},{"id":"cr-s31-level3-v1-q4","session":"31","level":3,"topic":"Step acquisition and first year attribution","question":"A's prior interest has a carrying amount of 500,000 euros and a fair value of 650,000. A pays 1.95 million to obtain 80% control at the start of the year. Net assets are 3 million and the fair value NCI is 700,000. Subsidiary adjusted profit after acquisition is 400,000. There is no OCI, tax or impairment. What acquisition goodwill, prior remeasurement gain and NCI current profit follow?","choices":["150,000 goodwill, 150,000 gain and 80,000 NCI profit","300,000 goodwill, 650,000 gain and 80,000 NCI profit","300,000 goodwill, 150,000 gain and 110,000 NCI profit","300,000 goodwill, 150,000 gain and 80,000 NCI profit"],"correct_index":3,"explanation":"Goodwill is 1.95 million + 650,000 + 700,000 - 3 million = 300,000. The prior remeasurement gain is 650,000 - 500,000 = 150,000. The NCI current profit is 20% × 400,000 = 80,000."},{"id":"cr-s31-level3-v1-q5","session":"31","level":3,"topic":"Acquisition and upstream adjustment integrated","question":"A owns 75% throughout. Opening NCI is 500,000 euros. Subsidiary after tax book profit of 400,000 includes upstream unrealised profit of 60,000. An acquisition uplift causes additional depreciation of 40,000. Both consolidation adjustments carry a tax benefit at 25%. Total subsidiary dividends are 80,000. There is no other change. What closing NCI follows?","choices":["561,250 euros","580,000 euros","555,000 euros","581,250 euros"],"correct_index":0,"explanation":"Adjusted profit is 400,000 - 45,000 after tax upstream profit - 30,000 after tax depreciation = 325,000. The NCI share is 25% × 325,000 = 81,250 and its dividend share is 20,000. Closing NCI is 500,000 + 81,250 - 20,000 = 561,250."},{"id":"cr-s31-level3-v1-q6","session":"31","level":3,"topic":"Full goodwill impairment plus post profit","question":"A owns 80% and acquired using full goodwill. Opening NCI is 700,000 euros and goodwill is 500,000. Current subsidiary adjusted profit before goodwill impairment is 300,000. The goodwill impairment is 100,000, stipulated to allocate 80% to the parent and 20% to the NCI. Total dividends are 50,000. There is no tax and no other change. What closing NCI and goodwill follow?","choices":["NCI 650,000 and goodwill 400,000","NCI 730,000 and goodwill 400,000","NCI 750,000 and goodwill 400,000","NCI 730,000 and goodwill 500,000"],"correct_index":1,"explanation":"The NCI takes 60,000 of profit, less its 20,000 share of the impairment and 10,000 of dividends: 700,000 + 60,000 - 20,000 - 10,000 = 730,000. Goodwill falls by the full 100,000 to 400,000."},{"id":"cr-s31-level3-v1-q7","session":"31","level":3,"topic":"Ownership transaction after profit allocation","question":"A owns 80% of a subsidiary and opening NCI is 300,000 euros. Adjusted annual profit is 200,000 and no dividends are paid. At year end A buys half the outstanding NCI for 210,000, retaining control. The required NCI reduction equals half its carrying amount immediately before the purchase. There is no tax. What closing NCI and parent equity transaction effect follow?","choices":["NCI 170,000 and goodwill increase 40,000","NCI 340,000 and parent equity decrease 210,000","NCI 170,000 and parent equity decrease 40,000","NCI 150,000 and parent equity decrease 60,000"],"correct_index":2,"explanation":"The NCI before the purchase is 300,000 + 20% × 200,000 = 340,000, and half of it is 170,000. Paying 210,000 for that carrying amount reduces parent equity by 40,000, with no new goodwill."},{"id":"cr-s31-level3-v1-q8","session":"31","level":3,"topic":"Bargain purchase with partial NCI","question":"A pays 1.3 million euros for 80% control. Confirmed identifiable net assets after all required reassessment are 1.8 million. The ordinary NCI is measured at its proportionate share and no previous interest exists. Separate current advisory costs are 30,000, with no tax. What bargain gain and net profit effect including advice follow?","choices":["Gain 500,000 and net profit increase 470,000","Gain 110,000 and net profit increase 110,000","Goodwill 140,000 and profit decrease 30,000","Gain 140,000 and net profit increase 110,000"],"correct_index":3,"explanation":"The NCI is 20% × 1.8 million = 360,000. Net assets of 1.8 million exceed consideration plus NCI, 1.3 million + 360,000, by 140,000, a bargain gain. The advice is a separate 30,000 expense, leaving a net profit increase of 110,000."},{"id":"cr-s31-level3-v1-q9","session":"31","level":3,"topic":"Measurement period NCI and amortisation","question":"A acquired 80% on the first day of the year with proportionate NCI. Six months later, new information about facts and circumstances existing at the acquisition date identifies an omitted customer asset of 200,000 euros, with a zero tax base, tax at 25% and a five year life. There is no other change. What acquisition goodwill reduction and current six month after tax amortisation follow?","choices":["Goodwill reduction 120,000 and after tax amortisation 15,000","Goodwill reduction 150,000 and after tax amortisation 20,000","Goodwill reduction 200,000 and after tax amortisation 15,000","Goodwill reduction 120,000 and after tax amortisation 20,000"],"correct_index":0,"explanation":"Net assets rise by 200,000 - 50,000 DTL = 150,000. The proportionate NCI rises by 30,000, so goodwill falls by the parent's 120,000 share. Six month amortisation is 200,000 / 5 × 1/2 = 20,000 with a 5,000 tax benefit, or 15,000 after tax."},{"id":"cr-s31-level3-v1-q10","session":"31","level":3,"topic":"Changing rights and retained majority","question":"A owns 70% of a business and previously directed its relevant activities through a board majority. A new enforceable agreement requires A and B to agree both the product programme and annual funding, which together most affect returns. A still appoints most directors and retains 70% of residual returns, but cannot bypass B on those decisions. Which reporting consequence follows from the new rights?","choices":["Continue full consolidation and treat the new agreement as an equity transaction with the NCI because A still has a majority economic interest","Account for loss of unilateral control from the agreement date, since the relevant decisions now require both parties to consent","Continue full consolidation because the retained board majority directs routine execution of the jointly approved programme","Treat B as the sole controller because B can block the product programme and funding despite its smaller economic interest"],"correct_index":1,"explanation":"The change concerns substantive direction of the relevant activities, not the size of A's ownership. A and B must now agree the decisions most affecting returns, so A no longer has unilateral control. Retaining a board majority for execution and most residual returns does not preserve that control."}]}},"MOYENNES":{"courses":[{"id":"cr","name":"Corporate Reporting","scale":30,"kind":"weighted","info":"Voie partiels : chaque partiel exige au moins 18/30. Autre voie possible : examen global 80 % + devoir 20 %.","evals":[{"id":"cr-dev","name":"Devoir (cases)","coef":20,"max":30},{"id":"cr-p1","name":"Partiel 1","coef":35,"max":30},{"id":"cr-p2","name":"Partiel 2","coef":45,"max":30}]},{"id":"fm","name":"Financial Management and Financial Markets","scale":30,"kind":"points","info":"Voie en deux temps : partiel 15 points + seconde moitié 15 points, les deux s'additionnent. S'inscrire à la seconde moitié consomme la note du partiel. Autre voie : examen complet, 8 QCM (6 points) + 4 questions ouvertes (24 points).","evals":[{"id":"fm-p1","name":"Partiel (1re moitié)","pts":15},{"id":"fm-p2","name":"Examen 2e moitié","pts":15}]},{"id":"cg","name":"Corporate Governance","scale":31,"kind":"points","info":"Note sur 31 : 31 vaut 30 e lode. Les trois composantes s'additionnent.","evals":[{"id":"cg-dev","name":"Devoir individuel","pts":4},{"id":"cg-fp","name":"Field project (groupe)","pts":12},{"id":"cg-ex","name":"Examen final","pts":15}]},{"id":"da","name":"Data Analysis for Business Decision","scale":31,"kind":"da","info":"Note V = max(S + M + T, 22/18 x S + M). Le score T des 3 tests en classe (0 à 4 selon les bonnes réponses sur 24) ne compte que pour la session de décembre 2026. Examen écrit de 2 h : statistiques sur 18, maths sur 9.","evals":[{"id":"da-s","name":"Examen, partie statistiques","pts":18},{"id":"da-m","name":"Examen, partie maths","pts":9},{"id":"da-t","name":"Tests en classe (score T)","pts":4}]}]}};
